#!/system/bin/sh
if [ "$(whoami)" != root ]; then
	echo "你是憨批？不給Root用你媽 爬"
	exit 1
fi
# 正規化 TMPDIR 提前到最開頭: 呼叫端終端 (如 MT 管理器內建終端) 可能繼承自己的 $TMPDIR
# (例如 app 私有目錄), 若晚於憑證檔/暫存檔建立才重設, 那些檔案會建在錯誤/不可靠的路徑。
TMPDIR="/data/local/tmp"
# 早期不再把 set -x 寫到 /data/cache；如需命令追蹤，請設 _dex_debug=1，會寫入 speed_debug/xtrace.log。
shell_language="zh-TW"
MODDIR_NAME="${MODDIR##*/}"
tools_path="$MODDIR/tools"
script="${0##*/}"
backup_version="202608312000"
# 固定用 GitHub release tag 作為線上更新比較基準；不要用每日 rebuild 日期，避免本地開發版被誤判舊版。
speedbackup_release_tag="202607232022"
speedbackup_patch_build="v24.20.14-7.66-924-canary-daemon-supervisor-keep-r501-202607232022"
# r222: 延續 r217/r219/r220 外科手術線；一次收斂 audit 剩餘低/中風險項目。
# r222: WebDAV/SMB 只抽 UI/progress/fixed-items/filelist facade，不合併協議核心；JSON 只抽底層 helper，不改 app_details schema。
# r222: Dex 不接管 JSON / app_details / 備份恢復規劃；C 只吃批量檔案事實操作；cgfreezerd 不動。
SPEEDBACKUP_CGROUP_FREEZER_REQUIRED_CAPS="cgroup-v2-uid-root-fallback freeze-package-single-request-v1 kill-package-live-rescan-v1 pidfd-signal-optional-v1 cgroup-kill-fastpath-v1 thaw-uid-emergency-v1 daemon-parent-control-v1 daemon-stats-v1 batch-pid-list-v1 cgroup-wchan-confirm-v1 backend-select-cache-v1"
# mksh/管線/command substitution 情境下，$$ 不一定是目前實際 shell process。
# WebDAV daemon owner watch 必須綁真正執行 tools.sh 的 process，否則 owner 誤判死亡會讓 daemon 每次 request 後退出。
_SPEEDBACKUP_SELF_PID=""
IFS=' ' read -r _SPEEDBACKUP_SELF_PID _ < /proc/self/stat 2>/dev/null || _SPEEDBACKUP_SELF_PID=""
case "$_SPEEDBACKUP_SELF_PID" in ''|*[!0-9]*) _SPEEDBACKUP_SELF_PID="$$" ;; esac
SPEEDBACKUP_MAIN_PID="$_SPEEDBACKUP_SELF_PID"
unset _SPEEDBACKUP_SELF_PID
# 私有 LAN 遠端操作期間臨時啟動 native netwatch。
# ============================================================
# SpeedBackup 內部策略
# ============================================================
# diagnostic_mode 已從公開 conf 移除；speed_debug 常態保留，深度診斷請用隱藏環境變數。
SPEED_DEBUG_BASE="/data/speed_debug"
SPEED_DEBUG_ERR_LOG="/dev/null"
SPEED_DEBUG_TS="$(date +%Y%m%d-%H%M%S 2>/dev/null)"
[[ -z "$SPEED_DEBUG_TS" ]] && SPEED_DEBUG_TS="unknown-$$"
SPEED_DEBUG_RUN_DIR="$SPEED_DEBUG_BASE/run_$SPEED_DEBUG_TS-$$"
SPEED_DEBUG_MAIN_LOG="$SPEED_DEBUG_RUN_DIR/main.log"
SPEED_DEBUG_PENDING_ERR_LOG="$SPEED_DEBUG_RUN_DIR/stderr.log"
SPEED_DEBUG_CMD_LOG="$SPEED_DEBUG_RUN_DIR/command.log"
SPEED_DEBUG_INFO_LOG="$SPEED_DEBUG_RUN_DIR/info.log"
SPEED_DEBUG_DEX_HUMAN_LOG="$SPEED_DEBUG_RUN_DIR/dex_human.log"
SPEED_DEBUG_ARCHIVE=""
SPEED_DEBUG_PACKED=0
SPEED_DEBUG_SNAPSHOT_DONE=0
SPEED_DEBUG_FIRST_BOOT=0
# r403/r487: 所有本輪暫存/狀態/socket/pid bucket 集中到專用 run tmpdir，避免 /data/local/tmp 根層殘留。
# 只允許 /data/local/tmp/.speedbackup_run_* 這個命名空間；正常結束後整個目錄刪除。
SPEEDBACKUP_TMP_BASE="${SPEEDBACKUP_TMP_BASE:-/data/local/tmp}"
SPEEDBACKUP_RUN_TMPDIR="${SPEEDBACKUP_RUN_TMPDIR:-$SPEEDBACKUP_TMP_BASE/.speedbackup_run_${SPEED_DEBUG_TS}_${SPEEDBACKUP_MAIN_PID}}"
SPEEDBACKUP_RUN_TMPDIR_OWN=0
SPEEDBACKUP_RUN_TMPDIR_STALE_REMOVED=0
SPEEDBACKUP_LEGACY_TMP_REMOVED=0

_speedbackup_run_tmpdir_export_scope() {
	local _run="${SPEEDBACKUP_RUN_TMPDIR:-}" _base="${SPEEDBACKUP_TMP_BASE:-/data/local/tmp}"
	case "$_run" in "$_base"/.speedbackup_run_*) ;; *) return 1 ;; esac
	SPEEDBACKUP_CGROUP_FREEZER_SOCKET="$_run/speedbackup_cgfreezerd.sock"
	SPEEDBACKUP_PROCESS_OBSERVER_BATCH_STATE_DIR="$_run/.speedbackup_process_observer_batch_state"
	SPEEDBACKUP_WAKEBLOCK_STATE_DIR="$_run/.speedbackup_wakeblock_state"
	SPEEDBACKUP_UID_NETBLOCK_STATE_DIR="$_run/.speedbackup_uid_netblock_state"
	SPEEDBACKUP_CGROUP_FREEZER_STATE_FILE="$_run/.speedbackup_cgroup_freezer_state"
	SPEEDBACKUP_NOTIFY_STATE_DIR="$_run/.speedbackup_notify_state"
	SMBCLIENT_PIDS_DIR="$_run/.smbclient_pids_${SPEEDBACKUP_MAIN_PID:-$$}"
	export SPEEDBACKUP_CGROUP_FREEZER_SOCKET \
		SPEEDBACKUP_PROCESS_OBSERVER_BATCH_STATE_DIR \
		SPEEDBACKUP_WAKEBLOCK_STATE_DIR \
		SPEEDBACKUP_UID_NETBLOCK_STATE_DIR \
		SPEEDBACKUP_CGROUP_FREEZER_STATE_FILE \
		SPEEDBACKUP_NOTIFY_STATE_DIR \
		SMBCLIENT_PIDS_DIR
	return 0
}

_speedbackup_legacy_tmpdir_prune_base() {
	local _base="${SPEEDBACKUP_TMP_BASE:-/data/local/tmp}" _f _removed=0
	case "$_base" in /data/local/tmp) ;; *) SPEEDBACKUP_LEGACY_TMP_REMOVED=0; return 0 ;; esac
	[[ -d $_base ]] || { SPEEDBACKUP_LEGACY_TMP_REMOVED=0; return 0; }
	# r417: 只清理已遷移到 SPEEDBACKUP_RUN_TMPDIR 後仍可能散落在 /data/local/tmp 根層的舊版空 marker。
	# 不恢復 r406 以前的大清單，不刪 root/appstate/remote 進行中狀態檔，避免誤殺流程內狀態。
	for _f in \
		"$_base/.restore_install_issues" \
		"$_base/.restore_install_vendor_warnings" \
		"$_base/.restore_media_space_skips"
	do
		case "$_f" in
		"$_base/.restore_install_issues"|"$_base/.restore_install_vendor_warnings"|"$_base/.restore_media_space_skips") ;;
		*) continue ;;
		esac
		if [[ -e $_f || -L $_f ]]; then
			rm -f "$_f" 2>/dev/null && _removed=$((_removed + 1))
		fi
	done
	SPEEDBACKUP_LEGACY_TMP_REMOVED="$_removed"
	[[ $_removed -gt 0 ]] && _speedbackup_run_tmpdir_log "TMPDIR_LEGACY_MARKER_CLEANUP_OK removed=$_removed mode=r417"
	return 0
}


_speedbackup_root_tmp_state_cleanup() {
	local _reason="${1:-root-tmp-state-cleanup}" _out _rc _flat _base="${SPEEDBACKUP_TMP_BASE:-/data/local/tmp}"
	case "$_base" in /data/local/tmp) ;; *) return 0 ;; esac
	# r487: Dex safety state is scoped under this run tmpdir via SPEEDBACKUP_*_STATE_* env.
	# On a controlled finish/exit, restore TTL=0 states before deleting the run tmpdir.
	command -v dex_hiddenapi_raw >/dev/null 2>&1 || return 0
	for _cmd in \
		"processObserverBatchCleanupStale" \
		"appWakeBlockCleanupStale" \
		"uidNetBlockCleanupStale" \
		"cgroupFreezeCleanupStale"
	do
		_out="$(_speedbackup_run_tmp_path "${_cmd}_${$}_${RANDOM:-0}.out")" || continue
		dex_hiddenapi_raw "$_cmd" "$_reason" 0 > "$_out" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
		_rc=$?
		_flat="$(tr '\n' '|' < "$_out" 2>/dev/null | cut -c1-900)"
		_speed_debug_log "TMPDIR_ROOT_STATE_CLEANUP_CMD cmd=$_cmd reason=$_reason rc=$_rc out=$_flat" 2>/dev/null || true
		rm -f "$_out" 2>/dev/null
	done
	_speedbackup_root_tmp_prune_namespaces "$_reason"
	return 0
}

_speedbackup_root_tmp_prune_namespaces() {
	local _reason="${1:-root-tmp-prune}" _base="${SPEEDBACKUP_TMP_BASE:-/data/local/tmp}" _d _pid _removed=0 _retained=0
	case "$_base" in /data/local/tmp) ;; *) return 0 ;; esac
	[[ -d $_base ]] || return 0
	# r487: root-level buckets are legacy only. Current SMB pid buckets live under SPEEDBACKUP_RUN_TMPDIR.
	for _d in "$_base"/.smbclient_pids_*; do
		[[ -d $_d ]] || continue
		_pid="${_d##*_}"
		case $_pid in ''|*[!0-9]*) _pid="" ;; esac
		if [[ -n $_pid ]] && kill -0 "$_pid" 2>/dev/null; then
			_retained=$((_retained + 1))
			continue
		fi
		rm -rf "$_d" 2>/dev/null && _removed=$((_removed + 1)) || _retained=$((_retained + 1))
	done
	# r487: prune legacy root-level SpeedBackup-owned namespaces only; current state is inside run tmpdir.
	for _d in \
		"$_base/.speedbackup_process_observer_batch_state" \
		"$_base/.speedbackup_uid_netblock_state" \
		"$_base/.speedbackup_wakeblock_state" \
		"$_base/.speedbackup_notify_state"
	do
		[[ -d $_d ]] || continue
		if rmdir "$_d" 2>/dev/null; then
			_removed=$((_removed + 1))
		else
			_retained=$((_retained + 1))
		fi
	done
	_speed_debug_log "TMPDIR_ROOT_NAMESPACE_PRUNE reason=$_reason removed=$_removed retained=$_retained mode=r487 legacyOnly=1" 2>/dev/null || true
	return 0
}

_speedbackup_run_tmpdir_owner_alive() {
	local _pid="$1" _cmd=""
	case "$_pid" in ''|*[!0-9]*) return 1 ;; esac
	kill -0 "$_pid" 2>/dev/null || return 1
	_cmd="$(tr '\0' ' ' < "/proc/$_pid/cmdline" 2>/dev/null)"
	case "$_cmd" in
	*tools.sh*|*start.sh*|*SpeedBackup*) return 0 ;;
	*) return 1 ;;
	esac
}

_speedbackup_run_tmpdir_prune_stale() {
	local _base="${SPEEDBACKUP_TMP_BASE:-/data/local/tmp}" _d _pid _removed=0
	case "$_base" in /data/local/tmp) ;; *) return 0 ;; esac
	[[ -d $_base ]] || return 0
	for _d in "$_base"/.speedbackup_run_*; do
		[[ -d $_d ]] || continue
		[[ -n ${SPEEDBACKUP_RUN_TMPDIR:-} && $_d = "$SPEEDBACKUP_RUN_TMPDIR" ]] && continue
		case "$_d" in "$_base"/.speedbackup_run_*) ;; *) continue ;; esac
		_pid="$(cat "$_d/owner.pid" 2>/dev/null)"
		if _speedbackup_run_tmpdir_owner_alive "$_pid"; then
			continue
		fi
		rm -rf "$_d" 2>/dev/null && _removed=$((_removed + 1))
	done
	SPEEDBACKUP_RUN_TMPDIR_STALE_REMOVED="$_removed"
	return 0
}

_speedbackup_run_tmpdir_init() {
	local _base="${SPEEDBACKUP_TMP_BASE:-/data/local/tmp}" _run="${SPEEDBACKUP_RUN_TMPDIR:-}"
	case "$_base" in /data/local/tmp) ;; *) TMPDIR="/data/local/tmp"; return 1 ;; esac
	mkdir -p "$_base" 2>/dev/null || { TMPDIR="/data/local/tmp"; return 1; }
	chmod 771 "$_base" 2>/dev/null || true
	chown 2000:2000 "$_base" 2>/dev/null || true
	case "$_run" in "$_base"/.speedbackup_run_*) ;; *) _run="$_base/.speedbackup_run_${SPEED_DEBUG_TS:-unknown}_${SPEEDBACKUP_MAIN_PID:-$$}" ;; esac
	SPEEDBACKUP_RUN_TMPDIR="$_run"
	_speedbackup_run_tmpdir_prune_stale
	_speedbackup_legacy_tmpdir_prune_base
	mkdir -p "$_run" 2>/dev/null || { TMPDIR="$_base"; return 1; }
	chmod 700 "$_run" 2>/dev/null || true
	printf '%s\n' "${SPEEDBACKUP_MAIN_PID:-$$}" > "$_run/owner.pid" 2>/dev/null || true
	TMPDIR="$_run"
	export TMPDIR SPEEDBACKUP_TMP_BASE SPEEDBACKUP_RUN_TMPDIR
	_speedbackup_run_tmpdir_export_scope || true
	SPEEDBACKUP_RUN_TMPDIR_OWN=1
	return 0
}

_speedbackup_run_tmpdir_owner_match() {
	local _run="$1" _owner="" _self="${SPEEDBACKUP_MAIN_PID:-$$}"
	_owner="$(cat "$_run/owner.pid" 2>/dev/null)"
	case "$_owner" in ''|*[!0-9]*) _owner="" ;; esac
	[[ "${SPEEDBACKUP_RUN_TMPDIR_OWN:-0}" = 1 ]] && return 0
	[[ -n $_owner && -n $_self && $_owner = $_self ]] && return 0
	case "$_run" in */*"_${_self}") return 0 ;; esac
	return 1
}

_speedbackup_run_tmpdir_log() {
	if command -v _speed_debug_log >/dev/null 2>&1; then
		_speed_debug_log "$1" 2>/dev/null || true
	fi
}

_speedbackup_run_tmpdir_stop_daemons_for_cleanup() {
	local _reason="${1:-final_tmpdir_cleanup}"
	# r416: 正常完成路徑也要先停掉使用 TMPDIR socket/pid 的 daemon/prewarm，避免目錄被刪後又被背景預熱程序重建。
	command -v _speedbackup_call_if_exists >/dev/null 2>&1 || return 0
	_speedbackup_call_if_exists _root_daemon_prewarm_stop "$_reason"
	_speedbackup_call_if_exists _install_daemon_stop "$_reason"
	_speedbackup_call_if_exists _root_daemon_stop "$_reason"
	_speedbackup_call_if_exists _webdav_daemon_stop "$_reason"
	return 0
}

_speedbackup_run_tmpdir_final_cleanup() {
	local _run="${SPEEDBACKUP_RUN_TMPDIR:-}" _base="${SPEEDBACKUP_TMP_BASE:-/data/local/tmp}" _rc=0 _owner=""
	case "$_base" in /data/local/tmp) ;; *) return 0 ;; esac
	case "$_run" in "$_base"/.speedbackup_run_*) ;; *) return 0 ;; esac
	[[ -n $_run && -d $_run ]] || { TMPDIR="$_base"; export TMPDIR; return 0; }
	_speedbackup_run_tmpdir_owner_match "$_run" || { _speedbackup_run_tmpdir_log "TMPDIR_RUN_FINAL_CLEANUP_SKIP path=$_run reason=owner_mismatch mode=r417"; return 0; }
	_speedbackup_run_tmpdir_stop_daemons_for_cleanup final_tmpdir_cleanup
	# r474: collect native run tmpdir facts before cleanup; facts-only, no process sweep.
	if [[ -n ${SPEEDSCAN_BIN:-} && -x ${SPEEDSCAN_BIN:-} && -d ${SPEED_DEBUG_RUN_DIR:-} ]]; then
		_runfacts="$SPEED_DEBUG_RUN_DIR/native_run_tmpdir_facts.tsv"
		if "$SPEEDSCAN_BIN" run-tmpdir-facts "$_base" "$_runfacts" .speedbackup_run_ >/dev/null 2>/dev/null; then
			_speedbackup_run_tmpdir_log "TMPDIR_RUN_FACTS_NATIVE_OK base=$_base out=${_runfacts##*/} backend=speedscan-run-tmpdir-facts mode=r474"
		else
			_speedbackup_run_tmpdir_log "TMPDIR_RUN_FACTS_NATIVE_FAIL base=$_base backend=speedscan-run-tmpdir-facts mode=r474 optional=1"
		fi
	fi
	# r470: prefer native bounded cleanup-owned after owner verification; fallback to legacy rm -rf if it skips/fails.
	_owner="$(cat "$_run/owner.pid" 2>/dev/null)"
	case $_owner in ''|*[!0-9]*) _owner="${SPEEDBACKUP_MAIN_PID:-$$}" ;; esac
	if command -v _eventwait_call >/dev/null 2>&1 && _eventwait_call cleanup-owned "$_owner" "$_run" >/dev/null 2>&1 && [[ ! -d $_run ]]; then
		_speedbackup_run_tmpdir_log "TMPDIR_RUN_FINAL_CLEANUP_NATIVE_OK path=$_run owner=$_owner backend=eventwait-cleanup-owned mode=r470"
	else
		rm -rf "$_run" 2>/dev/null || _rc=$?
		if [[ -d $_run ]]; then
			chmod -R u+rwX "$_run" 2>/dev/null || true
			rm -rf "$_run" 2>/dev/null || _rc=$?
		fi
	fi
	TMPDIR="$_base"
	export TMPDIR
	_speedbackup_legacy_tmpdir_prune_base
	_speedbackup_root_tmp_prune_namespaces final_run_tmpdir_cleanup
	if [[ -d $_run ]]; then
		_speedbackup_run_tmpdir_log "TMPDIR_RUN_FINAL_CLEANUP_FAIL path=$_run rc=${_rc:-1} mode=r417"
	else
		_speedbackup_run_tmpdir_log "TMPDIR_RUN_FINAL_CLEANUP_OK path=$_run mode=r417"
	fi
	return 0
}

_speedbackup_tmpdir_is_safe() {
	# r487: accept only the per-run namespace; root /data/local/tmp is not a valid runtime TMPDIR.
	# Some hot paths still need per-stage cleanup during the run, but must stay under .speedbackup_run_*.
	local _tmp="$1" _base="${SPEEDBACKUP_TMP_BASE:-/data/local/tmp}"
	case "$_base" in /data/local/tmp) ;; *) return 1 ;; esac
	case "$_tmp" in
	"$_base"/.speedbackup_run_*) return 0 ;;
	*) return 1 ;;
	esac
}

_speedbackup_path_is_under_tmpdir() {
	local _path="$1" _tmp="${TMPDIR:-}"
	_speedbackup_tmpdir_is_safe "$_tmp" || return 1
	case "$_path" in "$_tmp"|"$_tmp"/*) return 0 ;; *) return 1 ;; esac
}

_speedbackup_run_tmp_path() {
	# r488: do not fallback to bare /data/local/tmp for runtime temp files.
	# Caller must have initialized SPEEDBACKUP_RUN_TMPDIR.
	local _name="${1:-tmp}" _run="${SPEEDBACKUP_RUN_TMPDIR:-}" _base="${SPEEDBACKUP_TMP_BASE:-/data/local/tmp}"
	case "$_base" in /data/local/tmp) ;; *) return 1 ;; esac
	case "$_run" in "$_base"/.speedbackup_run_*) ;; *) return 1 ;; esac
	mkdir -p "$_run" 2>/dev/null || return 1
	printf '%s/.%s_%s_%s\n' "$_run" "$_name" "${SPEEDBACKUP_MAIN_PID:-$$}" "${RANDOM:-0}"
}

_speedbackup_run_tmpdir_init || true

_speedbackup_bool_on() {
	case "$1" in 1|true|True|TRUE|yes|YES|on|ON) return 0 ;; *) return 1 ;; esac
}

_speedbackup_apply_internal_policy() {
	SPEED_DEBUG_ENABLE=1
	SPEED_DEBUG_KEEP_TARS=10
	SPEED_DEBUG_SNAPSHOT_ON_NORMAL=0
	SPEED_DEBUG_SNAPSHOT_ON_EXIT=0
	SPEED_DEBUG_DEX_FIRST_TEST=1
	SPEED_DEBUG_DEX_TRANSLATE=1
	SPEED_DEBUG_DEX_TRANSLATE_TERMINAL=0
	RESTORE_APPSTATE_BATCH_CHUNK_SIZE=80
	VERIFY_APPSTATE_BATCH_CHUNK_SIZE=80
	backup_wifi_enable=1
	WIFI_BACKUP_TIMEOUT=20
	_restore_defaults="restore_pm_install_with_installer=1 restore_play_install_keep_workdir=0 restore_play_install_verify_source=1 restore_play_install_bypass_low_target=auto restore_play_install_allow_test=1 restore_play_install_allow_downgrade=0 restore_play_install_grant_runtime_permissions=0 restore_play_install_dont_kill=0 restore_play_install_require_user_action=not_required restore_play_install_package_source=store restore_play_install_reason=user restore_play_install_location=auto restore_play_install_extra_flags= restore_play_install_human_log=0 restore_play_install_log_mode=summary"
	for _kv in $_restore_defaults; do eval "$_kv"; done
	# r492: diagnostic_mode 舊 conf key 會在模板同步時移除；深度診斷改用隱藏環境變數。
	_dex_debug="${SPEEDBACKUP_DEBUG_XTRACE:-${_dex_debug:-0}}"
	_INCREMENTAL_DEBUG="${SPEEDBACKUP_INCREMENTAL_DEBUG:-${_INCREMENTAL_DEBUG:-0}}"
	SPEED_DEBUG_DEEP_SELF_TEST="${SPEED_DEBUG_DEEP_SELF_TEST:-0}"
}
_speedbackup_apply_internal_policy

_speed_debug_prune_archives() {
	local _keep="${SPEED_DEBUG_KEEP_TARS:-10}" _base="${SPEED_DEBUG_BASE:-}" _f
	case "$_keep" in ''|*[!0-9]*) _keep=10 ;; esac
	[[ -n $_base && -d $_base ]] || return 0
	case "$_base" in /data/speed_debug|*/speed_debug) ;; *) return 0 ;; esac
	# 只保留最新 N 份 speed_debug_*.tar；ls -t 依修改時間由新到舊排序。
	ls -1t "$_base"/speed_debug_*.tar 2>/dev/null | awk -v keep="$_keep" 'NR > keep {print}' | while IFS= read -r _f; do
		[[ -n $_f ]] || continue
		case "$_f" in "$_base"/speed_debug_*.tar) ;; *) continue ;; esac
		case "${_f##*/}" in speed_debug_*.tar) ;; *) continue ;; esac
		rm -f "$_f" 2>/dev/null && _speed_debug_pack_log "[speed_debug] 已刪除舊除錯壓縮包: $_f"
	done
}
_speed_debug_init() {
	[[ "$SPEED_DEBUG_ENABLE" = 1 ]] || { SPEED_DEBUG_ERR_LOG="/dev/null"; return 0; }
	# /data/speed_debug 是持久化目錄；只有此目錄不存在時，才視為第一次啟動腳本。
	# 後續清理只刪除目錄內舊 log/壓縮包，不刪除 /data/speed_debug 本身，避免重複觸發首次 dex 完整度測試。
	if [[ ! -d "$SPEED_DEBUG_BASE" ]]; then
		SPEED_DEBUG_FIRST_BOOT=1
	else
		SPEED_DEBUG_FIRST_BOOT=0
	fi
	mkdir -p "$SPEED_DEBUG_BASE" 2>/dev/null || { SPEED_DEBUG_ENABLE=0; SPEED_DEBUG_ERR_LOG="/dev/null"; return 0; }
	# 不再以 2MB 容量門檻清空 speed_debug；歷史資料改由打包後保留最新 10 份 tar 控制。
	# run dir 必須先存在；stderr.log 也要先 touch，之後才切換 SPEED_DEBUG_ERR_LOG
	mkdir -p "$SPEED_DEBUG_RUN_DIR" 2>/dev/null || { SPEED_DEBUG_ENABLE=0; SPEED_DEBUG_ERR_LOG="/dev/null"; return 0; }
	: > "$SPEED_DEBUG_PENDING_ERR_LOG" 2>/dev/null || { SPEED_DEBUG_ENABLE=0; SPEED_DEBUG_ERR_LOG="/dev/null"; return 0; }
	SPEED_DEBUG_ERR_LOG="$SPEED_DEBUG_PENDING_ERR_LOG"
	: > "$SPEED_DEBUG_MAIN_LOG" 2>>"$SPEED_DEBUG_ERR_LOG"
	SPEED_DEBUG_RUN_READY=1
	: > "$SPEED_DEBUG_CMD_LOG" 2>>"$SPEED_DEBUG_ERR_LOG"
	: > "$SPEED_DEBUG_INFO_LOG" 2>>"$SPEED_DEBUG_ERR_LOG"
	: > "$SPEED_DEBUG_DEX_HUMAN_LOG" 2>>"$SPEED_DEBUG_ERR_LOG"
	{
		echo "time=$(date '+%Y-%m-%d %H:%M:%S' 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null})"
		echo "pid=$SPEEDBACKUP_MAIN_PID shell_dollar_pid=$$"
		echo "script=$0"
		echo "entry_script=${SPEEDBACKUP_ENTRY_SCRIPT:-}"
		echo "entry_mode=${SPEEDBACKUP_ENTRY_MODE:-}"
		echo "tools_path=${tools_path:-}"
		echo "version=$backup_version"
		echo "shell=$SHELL"
		echo "user=$(id 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null})"
		echo "android=$(getprop ro.build.version.release 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}) sdk=$(getprop ro.build.version.sdk 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null})"
		echo "device=$(getprop ro.product.manufacturer 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}) $(getprop ro.product.model 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null})"
	} >> "$SPEED_DEBUG_INFO_LOG" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	printf '[speed_debug] 本次除錯目錄: %s\n' "$SPEED_DEBUG_RUN_DIR" >> "$SPEED_DEBUG_MAIN_LOG" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
}
_speed_debug_disarm_if_run_gone() {
	# 正常流程/子流程已 final 打包並刪除 run_xxx 後，父 shell 的 EXIT trap 可能仍持有舊 stderr.log 路徑。
	# 只要偵測到 run 目錄不存在，就立即把所有 debug 重定向切到 /dev/null，避免 mksh 在開檔階段刷 can't create。
	local _dir="${SPEED_DEBUG_RUN_DIR:-}" _base="${SPEED_DEBUG_BASE:-}"
	[[ -n $_dir && -n $_base ]] || return 0
	case "$_dir" in "$_base"/run_*) ;; *) return 0 ;; esac
	[[ -d "$_dir" ]] && return 0
	SPEED_DEBUG_RUN_DIR_REMOVED=1
	SPEED_DEBUG_ERR_LOG="/dev/null"
	SPEED_DEBUG_PENDING_ERR_LOG="/dev/null"
	SPEED_DEBUG_MAIN_LOG="/dev/null"
	SPEED_DEBUG_CMD_LOG="/dev/null"
	SPEED_DEBUG_INFO_LOG="/dev/null"
	SPEED_DEBUG_DEX_HUMAN_LOG="/dev/null"
	SPEED_DEBUG_RUN_READY=0
	return 0
}
_speed_debug_stderr_target() {
	_speed_debug_disarm_if_run_gone
	local _err="${SPEED_DEBUG_ERR_LOG:-/dev/null}"
	[[ -n $_err ]] || _err="/dev/null"
	if [[ $_err != "/dev/null" && -n ${SPEED_DEBUG_RUN_DIR:-} && ! -d "$SPEED_DEBUG_RUN_DIR" ]]; then
		_err="/dev/null"
		SPEED_DEBUG_ERR_LOG="/dev/null"
	fi
	printf '%s\n' "$_err"
}
_speed_debug_ensure_run_dir() {
	# 單獨入口、遠端預檢、或父 shell 殘留環境時，run_xxx 可能不存在；
	# 所有 debug 檔寫入前都先安全確認，避免 can't create /data/speed_debug/run_xxx/*.log 刷到終端。
	[[ "${SPEED_DEBUG_ENABLE:-1}" = 1 ]] || return 1
	_speed_debug_disarm_if_run_gone
	# final 已完成後不允許任何晚到的 log 寫入重建 run_xxx；這類訊息只留 pack.log 或直接丟棄。
	if [[ "${SPEED_DEBUG_PACKED:-0}" = 1 || "${SPEED_DEBUG_RUN_DIR_REMOVED:-0}" = 1 ]]; then
		SPEED_DEBUG_ERR_LOG="/dev/null"
		return 1
	fi
	[[ -n ${SPEED_DEBUG_RUN_DIR:-} ]] || return 1
	mkdir -p "$SPEED_DEBUG_RUN_DIR" 2>/dev/null || return 1
	[[ -d "$SPEED_DEBUG_RUN_DIR" ]] || return 1
	[[ -n ${SPEED_DEBUG_PENDING_ERR_LOG:-} ]] || SPEED_DEBUG_PENDING_ERR_LOG="$SPEED_DEBUG_RUN_DIR/stderr.log"
	: >> "$SPEED_DEBUG_PENDING_ERR_LOG" 2>/dev/null && SPEED_DEBUG_ERR_LOG="$SPEED_DEBUG_PENDING_ERR_LOG"
	[[ -n ${SPEED_DEBUG_MAIN_LOG:-} ]] || SPEED_DEBUG_MAIN_LOG="$SPEED_DEBUG_RUN_DIR/main.log"
	: >> "$SPEED_DEBUG_MAIN_LOG" 2>/dev/null || return 1
	SPEED_DEBUG_RUN_READY=1
	return 0
}
_speed_debug_log_path() {
	local _name="$1"
	[[ -n $_name ]] || { echo /dev/null; return 1; }
	if _speed_debug_ensure_run_dir; then
		echo "$SPEED_DEBUG_RUN_DIR/$_name"
		return 0
	fi
	echo /dev/null
	return 1
}

_speed_debug_append_file() {
	# Android / mksh 對「重定向目標不存在」的錯誤有時不會被同一條命令的 2>/dev/null 完全吞掉；
	# 所有可選 debug 檔寫入統一包進 subshell，確保 run_xxx 不存在時也不刷終端。
	local _file="$1"
	shift
	[[ -n $_file ]] || _file=/dev/null
	if [[ $_file != /dev/null ]]; then
		mkdir -p "${_file%/*}" 2>/dev/null || _file=/dev/null
	fi
	(
		for _line in "$@"; do
			printf '%s\n' "$_line"
		done >> "$_file"
	) 2>/dev/null || true
}

_speed_debug_append_cat() {
	local _file="$1" _src="$2" _prefix="$3"
	[[ -s $_src ]] || return 0
	[[ -n $_file ]] || _file=/dev/null
	if [[ $_file != /dev/null ]]; then
		mkdir -p "${_file%/*}" 2>/dev/null || _file=/dev/null
	fi
	(
		[[ -n $_prefix ]] && printf '%s\n' "$_prefix"
		sed -E 's#://[^/@[:space:]]+:[^/@[:space:]]+@#://[REDACTED]@#g; s/(password[[:space:]]*=[[:space:]]*).*/\1[REDACTED]/I' "$_src"
	) >> "$_file" 2>/dev/null || true
}

_speed_debug_safe() {
	# r363: small log sanitizer used before full debug helper section is loaded.
	# Keep it mksh/busybox-safe; do not depend on grep -P or bash-only features.
	printf '%s' "$*" | tr '\015\012\011' '___' | sed 's/[[:space:]][[:space:]]*/_/g' | cut -c1-500 2>/dev/null
}
_speed_debug_kv() {
	# Safe single-token value for marker details.
	printf '%s' "$*" | tr '\015\012\011 ' '____' | sed 's/=/％3D/g' | cut -c1-700 2>/dev/null
}

_speed_debug_timeline_append() {
	[[ "${SPEED_DEBUG_ENABLE:-0}" = 1 ]] || return 0
	[[ -n ${SPEED_DEBUG_RUN_DIR:-} && -d ${SPEED_DEBUG_RUN_DIR:-} ]] || return 0
	# r325: appList 前台逐行輸出會產生 100+ 條 MSG。舊版高速路徑沒有
	# debug_timeline.tsv；r321~r324 每條 MSG 又額外 date+寫 timeline，直接把 appList
	# 從約 1 秒拖到約 2 秒。預設跳過純使用者訊息的 timeline，只保留 main.log；
	# 需要完整 MSG timeline 時可設 SPEEDBACKUP_DEBUG_TIMELINE_MSG=1。
	case "$*" in
		MSG:*) [[ "${SPEEDBACKUP_DEBUG_TIMELINE_MSG:-0}" = 1 ]] || return 0 ;;
	esac
	local _msg="$*" _file _ts _event _pkg _rc _lat _detail _phase
	_file="$SPEED_DEBUG_RUN_DIR/debug_timeline.tsv"
	_ts="$(date '+%s' 2>/dev/null)"
	[[ -n $_ts ]] || _ts=0
	_event="${_msg%% *}"
	_phase="$_event"
	_pkg="-"; _rc="-"; _lat="-"; _detail="-"
	case " $_msg " in *" pkg="*) _pkg="$(printf '%s' "$_msg" | sed -n 's/.* pkg=\([^ ]*\).*/\1/p' | head -n 1)" ;; esac
	case " $_msg " in *" package="*) [[ $_pkg = - || -z $_pkg ]] && _pkg="$(printf '%s' "$_msg" | sed -n 's/.* package=\([^ ]*\).*/\1/p' | head -n 1)" ;; esac
	case " $_msg " in *" app="*) [[ $_pkg = - || -z $_pkg ]] && _pkg="$(printf '%s' "$_msg" | sed -n 's/.* app=\([^ ]*\).*/\1/p' | head -n 1)" ;; esac
	case " $_msg " in *" rc="*) _rc="$(printf '%s' "$_msg" | sed -n 's/.* rc=\([^ ]*\).*/\1/p' | head -n 1)" ;; esac
	case " $_msg " in *" elapsedMs="*) _lat="$(printf '%s' "$_msg" | sed -n 's/.* elapsedMs=\([^ ]*\).*/\1/p' | head -n 1)" ;; esac
	case " $_msg " in *" out="*) _detail="$(printf '%s' "$_msg" | sed -n 's/.* out=\([^ ]*\).*/\1/p' | head -n 1)" ;; esac
	case " $_msg " in *" detailFile="*) _detail="$(printf '%s' "$_msg" | sed -n 's/.* detailFile=\([^ ]*\).*/\1/p' | head -n 1)" ;; esac
	[[ -f $_file ]] || printf 'time\tphase\tpkg\tevent\trc\tlatencyMs\tdetailFile\n' >> "$_file" 2>/dev/null
	printf '%s\t%s\t%s\t%s\t%s\t%s\t%s\n' "$_ts" "$_phase" "${_pkg:- -}" "$_event" "$_rc" "$_lat" "$_detail" >> "$_file" 2>/dev/null || true
}

_speed_debug_log() {
	[[ "$SPEED_DEBUG_ENABLE" = 1 ]] || return 0
	if [[ "${SPEED_DEBUG_RUN_READY:-0}" = 1 && "${SPEED_DEBUG_PACKED:-0}" != 1 && "${SPEED_DEBUG_RUN_DIR_REMOVED:-0}" != 1 && -n ${SPEED_DEBUG_MAIN_LOG:-} ]]; then
		printf '[%s] %s\n' "$(date '+%H:%M:%S' 2>/dev/null)" "$*" >> "$SPEED_DEBUG_MAIN_LOG" 2>/dev/null && { _speed_debug_timeline_append "$*"; return 0; }
		SPEED_DEBUG_RUN_READY=0
	fi
	_speed_debug_ensure_run_dir || return 0
	printf '[%s] %s\n' "$(date '+%H:%M:%S' 2>/dev/null)" "$*" >> "$SPEED_DEBUG_MAIN_LOG" 2>/dev/null
	_speed_debug_timeline_append "$*"
}
_speed_debug_pack_log() {
	local _msg="$*" _ts
	_ts="$(date '+%H:%M:%S' 2>/dev/null)"
	[[ -z $_ts ]] && _ts="unknown"
	# 打包階段可能即將刪除 run 目錄；因此同時寫 root pack.log，避免為了記錄成功訊息又重建 run 目錄。
	mkdir -p "$SPEED_DEBUG_BASE" 2>/dev/null
	printf '[%s] %s\n' "$_ts" "$_msg" >> "$SPEED_DEBUG_BASE/pack.log" 2>/dev/null
	if [[ -n ${SPEED_DEBUG_MAIN_LOG:-} && -f "$SPEED_DEBUG_MAIN_LOG" ]]; then
		printf '[%s] %s\n' "$_ts" "$_msg" >> "$SPEED_DEBUG_MAIN_LOG" 2>/dev/null
	fi
}
_speed_debug_safe_remove_run_dir() {
	local _dir="${1:-}" _base="${SPEED_DEBUG_BASE:-}"
	# 只允許刪除本腳本建立的 /data/speed_debug/run_* 目錄，避免任何 rm -rf /* 類事故。
	[[ -n $_dir && -n $_base ]] || { _speed_debug_pack_log "[speed_debug] 刪除run目錄跳過: path/base為空 dir=$_dir base=$_base"; return 1; }
	[[ $_base != "/" && $_base != "/*" ]] || { _speed_debug_pack_log "[speed_debug] 刪除run目錄拒絕: base危險 $_base"; return 1; }
	[[ $_dir != "/" && $_dir != "/*" ]] || { _speed_debug_pack_log "[speed_debug] 刪除run目錄拒絕: path危險 $_dir"; return 1; }
	[[ $_dir = "$_base"/run_* ]] || { _speed_debug_pack_log "[speed_debug] 刪除run目錄拒絕: 不在speed_debug run範圍 dir=$_dir base=$_base"; return 1; }
	case "${_dir##*/}" in run_*) ;; *) _speed_debug_pack_log "[speed_debug] 刪除run目錄拒絕: basename不是run_* dir=$_dir"; return 1 ;; esac
	case "$_dir" in *".."*|*"//"*|*"*"*) _speed_debug_pack_log "[speed_debug] 刪除run目錄拒絕: path含危險字元 dir=$_dir"; return 1 ;; esac
	[[ -d $_dir ]] || { _speed_debug_pack_log "[speed_debug] 刪除run目錄跳過: 目錄不存在 $_dir"; return 0; }
	rm -rf "$_dir" 2>/dev/null || { _speed_debug_pack_log "[speed_debug] 刪除run目錄失敗: $_dir"; return 1; }
	SPEED_DEBUG_RUN_DIR_REMOVED=1
	SPEED_DEBUG_RUN_READY=0
	# final 打包成功後 run_xxx 已不存在，後續任何晚到的 debug redirection 都只能丟棄，不能再指向已刪除的 run 內 log。
	SPEED_DEBUG_ERR_LOG="/dev/null"
	SPEED_DEBUG_MAIN_LOG="/dev/null"
	_speed_debug_pack_log "[speed_debug] 已刪除原run目錄: $_dir"
	return 0
}


_speed_debug_sync_legacy_log() {
	# r36: 入口腳本為避免 tee/subshell 問題不再即時管線寫 legacy log，
	# 但不能留下 log_yyyy-mm-dd_hh-mm.txt 0KB 空檔；final/snapshot 打包前鏡像 main.log 摘要。
	local _mode="$1" _ec="${2:-0}" _legacy="${logfile:-}" _archive="${SPEED_DEBUG_ARCHIVE:-}"
	[[ -n $_legacy && $_legacy != "/dev/null" ]] || return 0
	case "$_legacy" in
	*/log/log_20[0-9][0-9]-[0-9][0-9]-[0-9][0-9]_[0-9][0-9]-[0-9][0-9].txt|/data/local/tmp/log_20[0-9][0-9]-[0-9][0-9]-[0-9][0-9]_[0-9][0-9]-[0-9][0-9].txt) ;;
	*) return 0 ;;
	esac
	mkdir -p "${_legacy%/*}" 2>/dev/null || return 0
	{
		echo "===== SpeedBackup legacy log mirror ====="
		echo "time=$(date '+%Y-%m-%d %H:%M:%S' 2>/dev/null)"
		echo "mode=$_mode"
		echo "exit_code=$_ec"
		echo "script=${SPEEDBACKUP_ENTRY_SCRIPT:-$0}"
		echo "patch=${speedbackup_patch_build:-}"
		[[ -n $_archive ]] && echo "speed_debug_archive=$_archive"
		[[ -n ${SPEED_DEBUG_RUN_DIR:-} ]] && echo "speed_debug_run=${SPEED_DEBUG_RUN_DIR:-}"
		echo "note=完整結構化日誌以 speed_debug tar 為準；此檔為 main.log 鏡像，避免 legacy log 空白。"
		echo ""
		echo "===== main.log ====="
		if [[ -s ${SPEED_DEBUG_MAIN_LOG:-/dev/null} ]]; then
			sed -E 's/\x1B\[[0-9;]*[A-Za-z]//g' "$SPEED_DEBUG_MAIN_LOG" 2>/dev/null
		else
			echo "main.log unavailable or empty"
		fi
	} > "$_legacy" 2>/dev/null || true
	# 避免入口收尾 sed -i 處理空檔；若 main.log 為空，至少留下摘要。
	[[ -s $_legacy ]] || printf 'SpeedBackup legacy log mirror: no content\n' > "$_legacy" 2>/dev/null || true
	_speed_debug_pack_log "[speed_debug] legacy log 已同步: $_legacy"
	return 0
}

# r440: final pack 收尾拆成兩段：
# 1) final tar 前只恢復 display-on 與停止音量監聽，保留使用者可見提示；
# 2) final debug tar 與 EXIT cleanup 都嘗試完成後，才在 EXIT trap 最後一步還原 screen_off_timeout，避免關屏後後續收尾被系統延後調度。
# r436 的 final pack 前額外 wake poke（dex_hiddenapi_raw setDisplayPowerMode 2 / input keyevent 224）維持撤回。
_SPEEDBACKUP_DISPLAY_RESTORE_DEFERRED="${_SPEEDBACKUP_DISPLAY_RESTORE_DEFERRED:-0}"
_SPEEDBACKUP_DISPLAY_RESTORE_DEFER_REASON="${_SPEEDBACKUP_DISPLAY_RESTORE_DEFER_REASON:-}"
_SPEEDBACKUP_DISPLAY_RESTORE_POST_PACK_PHASE="${_SPEEDBACKUP_DISPLAY_RESTORE_POST_PACK_PHASE:-0}"
_SPEEDBACKUP_DISPLAY_POWER_RESTORED_FOR_FINAL_PACK="${_SPEEDBACKUP_DISPLAY_POWER_RESTORED_FOR_FINAL_PACK:-0}"
_SPEEDBACKUP_DISPLAY_TIMEOUT_CACHE_ORIG="${_SPEEDBACKUP_DISPLAY_TIMEOUT_CACHE_ORIG:-}"
_SPEEDBACKUP_DISPLAY_TIMEOUT_CACHE_REQUESTED="${_SPEEDBACKUP_DISPLAY_TIMEOUT_CACHE_REQUESTED:-}"
_SPEEDBACKUP_DISPLAY_TIMEOUT_CACHE_APPLIED="${_SPEEDBACKUP_DISPLAY_TIMEOUT_CACHE_APPLIED:-}"
_SPEEDBACKUP_DISPLAY_TIMEOUT_CACHE_READY="${_SPEEDBACKUP_DISPLAY_TIMEOUT_CACHE_READY:-0}"
# r489/r492: normal finish already writes final speed_debug package and synchronously deletes run tmpdir.
# EXIT trap is only a shell lifecycle callback; do not repeat heavy cleanup synchronously.
_SPEEDBACKUP_NORMAL_FINISH_EXIT_FAST="${_SPEEDBACKUP_NORMAL_FINISH_EXIT_FAST:-0}"

_speedbackup_display_timeout_cache_capture() {
	local _scr_save _req_save _applied_save _orig="" _requested="" _applied=""
	command -v _display_timeout_save_file >/dev/null 2>&1 || return 1
	_scr_save="$(_display_timeout_save_file)"
	_req_save="${TMPDIR:-/data/local/tmp}/.screen_timeout_requested"
	_applied_save="${TMPDIR:-/data/local/tmp}/.screen_timeout_applied"
	[[ -s $_scr_save ]] || return 1
	_orig="$(cat "$_scr_save" 2>/dev/null)"
	case $_orig in ''|*[!0-9]*) return 1 ;; esac
	_requested="$_DISPLAY_TIMEOUT_REQUESTED_MS"
	if [[ -s $_req_save ]]; then
		_requested="$(cat "$_req_save" 2>/dev/null)"
		case $_requested in ''|*[!0-9]*) _requested="$_DISPLAY_TIMEOUT_REQUESTED_MS" ;; esac
	fi
	_applied="$_requested"
	if [[ -s $_applied_save ]]; then
		_applied="$(cat "$_applied_save" 2>/dev/null)"
		case $_applied in ''|*[!0-9]*) _applied="$_requested" ;; esac
	fi
	_SPEEDBACKUP_DISPLAY_TIMEOUT_CACHE_ORIG="$_orig"
	_SPEEDBACKUP_DISPLAY_TIMEOUT_CACHE_REQUESTED="$_requested"
	_SPEEDBACKUP_DISPLAY_TIMEOUT_CACHE_APPLIED="$_applied"
	_SPEEDBACKUP_DISPLAY_TIMEOUT_CACHE_READY=1
	_speed_debug_log "DISPLAY_TIMEOUT_RESTORE_CACHE_CAPTURE original=$_orig requested=$_requested applied=$_applied mode=r440"
	return 0
}

_speedbackup_display_settings_trace() {
	# r463: display timeout restore happens after final debug tar; main.log may already be packed/removed.
	# Write bounded settings markers to pack.log in that phase, otherwise use normal main.log.
	if [[ "${SPEED_DEBUG_PACKED:-0}" = 1 || "${SPEED_DEBUG_RUN_DIR_REMOVED:-0}" = 1 ]]; then
		_speed_debug_pack_log "[speed_debug] $*"
	else
		_speed_debug_log "$*"
	fi
}

_speedbackup_display_settings_kill_no_wait() {
	local _pid="$1" _tag="${2:-display_settings_timeout}"
	case $_pid in ''|*[!0-9]*) return 0 ;; esac
	if kill -0 "$_pid" 2>/dev/null; then
		kill -TERM "$_pid" 2>/dev/null || true
		sleep 0.1
		kill -0 "$_pid" 2>/dev/null && kill -KILL "$_pid" 2>/dev/null || true
	fi
	# Do not call plain wait here: on some Android builds `settings` can stay in a
	# slow binder/system_server path after TERM/KILL, and wait would recreate the
	# 30s+ terminal stall that this bounded path is supposed to prevent.
	_speedbackup_display_settings_trace "DISPLAY_SETTINGS_KILL_NO_WAIT pid=$_pid tag=$_tag mode=r463"
	return 0
}

_speedbackup_display_settings_wait_pid_ms() {
	local _pid="$1" _timeout_ms="${2:-5000}" _tag="${3:-display_settings}" _rc=125 _i=0 _limit
	case $_pid in ''|*[!0-9]*) return 125 ;; esac
	case $_timeout_ms in ''|*[!0-9]*) _timeout_ms=5000 ;; esac
	if command -v _eventwait_pid_exit_ms >/dev/null 2>&1; then
		_eventwait_pid_exit_ms "$_pid" "$_timeout_ms" "${_tag}_bounded" >/dev/null 2>&1
		_rc=$?
		if [[ $_rc = 0 ]]; then
			wait "$_pid" 2>/dev/null
			return $?
		fi
		if [[ $_rc = 124 ]]; then
			_speedbackup_display_settings_kill_no_wait "$_pid" "${_tag}_eventwait_timeout"
			return 124
		fi
	fi
	# fallback: 100ms * N，避免 eventwait 缺失時又退回長時間卡住。
	_limit=$(((_timeout_ms + 99) / 100))
	while kill -0 "$_pid" 2>/dev/null; do
		if [[ $_i -ge $_limit ]]; then
			_speedbackup_display_settings_kill_no_wait "$_pid" "${_tag}_fallback_timeout"
			return 124
		fi
		sleep 0.1
		_i=$((_i + 1))
	done
	wait "$_pid" 2>/dev/null
	return $?
}

_speedbackup_settings_get_system_bounded() {
	local _key="$1" _timeout_ms="${2:-2000}" _tag="${3:-settings_get}" _tmp _pid _rc
	[[ -n $_key ]] || return 2
	case $_timeout_ms in ''|*[!0-9]*) _timeout_ms=2000 ;; esac
	_tmp="${TMPDIR:-/data/local/tmp}/.speedbackup_settings_get_${$}_$(_rand 6 2>/dev/null)"
	( settings get system "$_key" > "$_tmp" 2>/dev/null ) &
	_pid=$!
	_speedbackup_display_settings_wait_pid_ms "$_pid" "$_timeout_ms" "$_tag"
	_rc=$?
	if [[ $_rc = 0 ]]; then
		cat "$_tmp" 2>/dev/null
		rm -f "$_tmp" 2>/dev/null
		_speedbackup_display_settings_trace "DISPLAY_SETTINGS_GET_BOUNDED key=$_key timeoutMs=$_timeout_ms rc=0 tag=$_tag backend=shell mode=r473"
		return 0
	fi
	rm -f "$_tmp" 2>/dev/null
	_speedbackup_display_settings_trace "DISPLAY_SETTINGS_GET_BOUNDED key=$_key timeoutMs=$_timeout_ms rc=$_rc tag=$_tag backend=shell mode=r473"
	return $_rc
}

_speedbackup_settings_put_system_bounded() {
	local _key="$1" _value="$2" _timeout_ms="${3:-5000}" _tag="${4:-settings_put}" _pid _rc
	[[ -n $_key ]] || return 2
	case $_timeout_ms in ''|*[!0-9]*) _timeout_ms=5000 ;; esac
	( settings put system "$_key" "$_value" >/dev/null 2>&1 ) &
	_pid=$!
	_speedbackup_display_settings_wait_pid_ms "$_pid" "$_timeout_ms" "$_tag"
	_rc=$?
	_speedbackup_display_settings_trace "DISPLAY_SETTINGS_PUT_BOUNDED key=$_key value=$_value timeoutMs=$_timeout_ms rc=$_rc tag=$_tag backend=shell mode=r473"
	return $_rc
}

_speedbackup_display_timeout_restore_from_cache() {
	local _reason="${1:-cached-final-restore}" _orig="${_SPEEDBACKUP_DISPLAY_TIMEOUT_CACHE_ORIG:-}" _requested="${_SPEEDBACKUP_DISPLAY_TIMEOUT_CACHE_REQUESTED:-}" _applied="${_SPEEDBACKUP_DISPLAY_TIMEOUT_CACHE_APPLIED:-}" _current="" _readback="" _get_rc=0 _put_rc=0 _rb_rc=0 _get_timeout _put_timeout
	[[ "${_SPEEDBACKUP_DISPLAY_TIMEOUT_CACHE_READY:-0}" = 1 ]] || return 1
	case $_orig in ''|*[!0-9]*) return 1 ;; esac
	case $_requested in ''|*[!0-9]*) _requested="${_DISPLAY_TIMEOUT_REQUESTED_MS:-2147483647}" ;; esac
	case $_applied in ''|*[!0-9]*) _applied="$_requested" ;; esac
	_get_timeout="${SPEEDBACKUP_DISPLAY_SETTINGS_GET_TIMEOUT_MS:-2000}"
	_put_timeout="${SPEEDBACKUP_DISPLAY_SETTINGS_PUT_TIMEOUT_MS:-5000}"
	# r473: Dex display-timeout direct path removed; use bounded shell get/put only.
	_current="$(_speedbackup_settings_get_system_bounded screen_off_timeout "$_get_timeout" display_timeout_restore_current)"
	_get_rc=$?
	if [[ $_get_rc = 0 && $_current = "$_orig" ]]; then
		rm -f "$(_display_timeout_save_file 2>/dev/null)" "${TMPDIR:-/data/local/tmp}/.screen_timeout_requested" "${TMPDIR:-/data/local/tmp}/.screen_timeout_applied" "${TMPDIR:-/data/local/tmp}/.screen_timeout_session_id" "${TMPDIR:-/data/local/tmp}/.screen_timeout_backend" 2>/dev/null
		_SPEEDBACKUP_DISPLAY_TIMEOUT_CACHE_READY=0
		_DISPLAY_TIMEOUT_ACTIVE=0
		Get_dark_screen_seconds=""
		_speedbackup_display_settings_trace "DISPLAY_TIMEOUT_SHELL_END_CACHE original=$_orig requested=$_requested applied=$_applied readback=$_current restored=already reason=$_reason backend=shell-timeout-stale-guard getRc=$_get_rc mode=r462"
		return 0
	fi
	if [[ $_get_rc = 0 && $_current != "$_applied" ]]; then
		_speedbackup_display_settings_trace "DISPLAY_TIMEOUT_SHELL_END_CACHE externalChange=true current=$_current original=$_orig requested=$_requested applied=$_applied restored=false reason=$_reason backend=shell-timeout-stale-guard getRc=$_get_rc mode=r462"
		_SPEEDBACKUP_DISPLAY_TIMEOUT_CACHE_READY=0
		_DISPLAY_TIMEOUT_ACTIVE=0
		Get_dark_screen_seconds=""
		return 0
	fi
	if [[ $_get_rc != 0 ]]; then
		_speedbackup_display_settings_trace "DISPLAY_TIMEOUT_SHELL_END_CACHE_CURRENT_UNAVAILABLE getRc=$_get_rc original=$_orig requested=$_requested applied=$_applied policy=restore-original-anyway reason=$_reason mode=r462"
	fi
	_speedbackup_settings_put_system_bounded screen_off_timeout "$_orig" "$_put_timeout" display_timeout_restore_put
	_put_rc=$?
	[[ $_put_rc = 0 ]] || return 1
	_readback="$(_speedbackup_settings_get_system_bounded screen_off_timeout "$_get_timeout" display_timeout_restore_readback)"
	_rb_rc=$?
	if [[ $_rb_rc = 0 && $_readback != "$_orig" ]]; then
		_speedbackup_display_settings_trace "DISPLAY_TIMEOUT_SHELL_END_CACHE_READBACK_MISMATCH original=$_orig requested=$_requested applied=$_applied readback=$_readback reason=$_reason backend=shell-timeout-stale-guard getRc=$_get_rc putRc=$_put_rc rbRc=$_rb_rc mode=r462"
		return 1
	fi
	rm -f "$(_display_timeout_save_file 2>/dev/null)" "${TMPDIR:-/data/local/tmp}/.screen_timeout_requested" "${TMPDIR:-/data/local/tmp}/.screen_timeout_applied" "${TMPDIR:-/data/local/tmp}/.screen_timeout_session_id" "${TMPDIR:-/data/local/tmp}/.screen_timeout_backend" 2>/dev/null
	_SPEEDBACKUP_DISPLAY_TIMEOUT_CACHE_READY=0
	_DISPLAY_TIMEOUT_ACTIVE=0
	Get_dark_screen_seconds=""
	if [[ $_rb_rc = 0 ]]; then
		_speedbackup_display_settings_trace "DISPLAY_TIMEOUT_SHELL_END_CACHE original=$_orig requested=$_requested applied=$_applied readback=$_readback restored=true reason=$_reason backend=shell-timeout-stale-guard getRc=$_get_rc putRc=$_put_rc rbRc=$_rb_rc mode=r462"
	else
		_speedbackup_display_settings_trace "DISPLAY_TIMEOUT_SHELL_END_CACHE original=$_orig requested=$_requested applied=$_applied readback=unavailable restored=put-ok reason=$_reason backend=shell-timeout-stale-guard getRc=$_get_rc putRc=$_put_rc rbRc=$_rb_rc mode=r462"
	fi
	return 0
}

_speedbackup_display_restore_should_defer_for_pack() {
	[[ "${SPEEDBACKUP_DISPLAY_RESTORE_AFTER_DEBUG_PACK:-1}" = 1 ]] || return 1
	[[ "${_SPEEDBACKUP_DISPLAY_RESTORE_POST_PACK_PHASE:-0}" = 1 ]] && return 1
	[[ "${SPEED_DEBUG_PACKED:-0}" = 1 ]] && return 1
	[[ -n ${SPEED_DEBUG_RUN_DIR:-} && -d "$SPEED_DEBUG_RUN_DIR" ]] || return 1
	command -v _display_timeout_session_active >/dev/null 2>&1 || return 1
	_display_timeout_session_active || return 1
	return 0
}

_speedbackup_display_power_restore_for_final_pack() {
	local _reason="${1:-before-final-debug-pack}" _display_rc=0
	[[ ${setDisplayPowerMode:-} = true ]] || return 0
	[[ "${_SPEEDBACKUP_DISPLAY_POWER_RESTORED_FOR_FINAL_PACK:-0}" = 1 ]] && return 0
	_speed_debug_log "DISPLAY_POWER_RESTORE_BEFORE_FINAL_PACK_BEGIN reason=$_reason mode=r440"
	# 只用既有 setDisplay 2 恢復顯示狀態；不再額外呼叫 dex_hiddenapi_raw 或 input keyevent 224。
	if setDisplay 2 >/dev/null 2>&1; then
		_display_rc=0
	else
		_display_rc=$?
	fi
	_speed_debug_log "DISPLAY_POWER_RESTORE_BEFORE_FINAL_PACK_SET mode=2 rc=$_display_rc inputKeyevent224=0 rawFallback=0 mode=r440"
	_display_power_volume_watcher_stop || true
	rm -f "$(_display_power_volume_hint_file)" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	_DISPLAY_POWER_VOLUME_HINT_SHOWN=0
	_SPEEDBACKUP_DISPLAY_POWER_RESTORED_FOR_FINAL_PACK=1
	echo_log "設置螢幕狀態display-on(mode=2)" "" 0
	return 0
}

_speedbackup_display_timeout_restore_after_debug_pack() {
	local _reason="${1:-final-debug-pack-done}" _rc=0
	if [[ ${_DISPLAY_RESTORE_DONE:-0} = 1 ]]; then
		_speed_debug_pack_log "[speed_debug] EXIT最後螢幕/鎖屏設定還原跳過: already_done=1 reason=$_reason mode=r440"
		return 0
	fi
	if ! command -v _display_timeout_session_active >/dev/null 2>&1 || ! _display_timeout_session_active; then
		if [[ "${_SPEEDBACKUP_DISPLAY_TIMEOUT_CACHE_READY:-0}" != 1 ]]; then
			_speed_debug_pack_log "[speed_debug] EXIT最後螢幕/鎖屏設定還原跳過: no-active-display-session reason=$_reason mode=r440"
			return 0
		fi
	fi
	_speed_debug_pack_log "[speed_debug] EXIT最後還原螢幕/鎖屏設定: reason=$_reason deferred=${_SPEEDBACKUP_DISPLAY_RESTORE_DEFERRED:-0} deferReason=${_SPEEDBACKUP_DISPLAY_RESTORE_DEFER_REASON:-none} displayPowerPreRestored=${_SPEEDBACKUP_DISPLAY_POWER_RESTORED_FOR_FINAL_PACK:-0} cacheReady=${_SPEEDBACKUP_DISPLAY_TIMEOUT_CACHE_READY:-0}"
	echoRgb "正在還原螢幕/鎖屏設定" "3"
	# r440: EXIT 最後一步可能已清掉 run tmpdir/TMPDIR marker；優先使用 r439 捕獲的記憶體 cache 還原 timeout。
	# 這可避免 _DISPLAY_TIMEOUT_ACTIVE=1 但 .screen_timeout_orig 已被 tmpdir cleanup 刪除時，_display_timeout_shell_end 誤判成功卻沒有真正寫回原值。
	if [[ "${_SPEEDBACKUP_DISPLAY_TIMEOUT_CACHE_READY:-0}" = 1 ]]; then
		_speed_debug_pack_log "[speed_debug] EXIT最後螢幕/鎖屏設定還原路徑: path=memory-cache reason=$_reason mode=r463"
		if _speedbackup_display_timeout_restore_from_cache "$_reason"; then
			echo_log "由shell還原無操作息屏時間" "" 0
			_DISPLAY_RESTORE_DONE=1
			_rc=0
		else
			echoRgb "還原無操作息屏時間失敗；shell暫存保留供下次啟動修復。" "0"
			_rc=1
		fi
	elif command -v _display_timeout_session_active >/dev/null 2>&1 && _display_timeout_session_active; then
		_speed_debug_pack_log "[speed_debug] EXIT最後螢幕/鎖屏設定還原路徑: path=session-marker reason=$_reason mode=r463"
		if _display_timeout_shell_end; then
			echo_log "由shell還原無操作息屏時間" "" 0
			_DISPLAY_RESTORE_DONE=1
			_rc=0
		else
			echoRgb "還原無操作息屏時間失敗；shell暫存保留供下次啟動修復。" "0"
			_rc=1
		fi
	else
		echoRgb "還原無操作息屏時間失敗；shell暫存保留供下次啟動修復。" "0"
		_rc=1
	fi
	_speed_debug_pack_log "[speed_debug] EXIT最後螢幕/鎖屏設定還原完成: rc=$_rc reason=$_reason mode=r463"
	return $_rc
}

_speedbackup_display_restore_defer_for_debug_pack() {
	local _reason="${1:-before-final-debug-pack}"
	_SPEEDBACKUP_DISPLAY_RESTORE_DEFERRED=1
	_SPEEDBACKUP_DISPLAY_RESTORE_DEFER_REASON="$_reason"
	_speedbackup_display_timeout_cache_capture || true
	_speed_debug_log "DISPLAY_RESTORE_DEFER reason=$_reason action=display-before-pack-timeout-at-final-exit active=${_DISPLAY_TIMEOUT_ACTIVE:-0} setDisplayPowerMode=${setDisplayPowerMode:-} cacheReady=${_SPEEDBACKUP_DISPLAY_TIMEOUT_CACHE_READY:-0} mode=r440"
	_speedbackup_display_power_restore_for_final_pack "$_reason" || true
	return 0
}

_speedbackup_display_restore_after_debug_pack() {
	local _reason="${1:-final-debug-pack-done}" _rc=0
	if [[ "${_SPEEDBACKUP_DISPLAY_RESTORE_DEFERRED:-0}" != 1 ]]; then
		if ! command -v _display_timeout_session_active >/dev/null 2>&1 || ! _display_timeout_session_active; then
			return 0
		fi
	fi
	_SPEEDBACKUP_DISPLAY_RESTORE_POST_PACK_PHASE=1
	_speedbackup_display_timeout_restore_after_debug_pack "$_reason"
	_rc=$?
	_SPEEDBACKUP_DISPLAY_RESTORE_POST_PACK_PHASE=0
	_SPEEDBACKUP_DISPLAY_RESTORE_DEFERRED=0
	_SPEEDBACKUP_DISPLAY_RESTORE_DEFER_REASON=""
	return $_rc
}

_speed_debug_pack_common() {
	local _mode="$1" _ec="${2:-0}" _delete="${3:-0}" _pack_start_ms="" _pack_elapsed_ms="unknown" _archive_size="unknown"
	# 打包以 run 目錄存在為準，不再只看 SPEED_DEBUG_ENABLE；
	# 因為 debug 已建立後，conf 或環境若改動 SPEED_DEBUG_ENABLE，也不應讓打包靜默跳過。
	if [[ -z ${SPEED_DEBUG_RUN_DIR:-} ]]; then
		_speed_debug_pack_log "[speed_debug] ${_mode}打包跳過: SPEED_DEBUG_RUN_DIR為空"
		return 0
	fi
	if [[ ! -d "$SPEED_DEBUG_RUN_DIR" ]]; then
		_speed_debug_pack_log "[speed_debug] ${_mode}打包跳過: run目錄不存在: $SPEED_DEBUG_RUN_DIR"
		return 0
	fi
	mkdir -p "$SPEED_DEBUG_BASE" 2>/dev/null || {
		_speed_debug_pack_log "[speed_debug] ${_mode}打包失敗: 無法建立 $SPEED_DEBUG_BASE"
		return 1
	}
	# v24.20.14-7.66-194：tools_version 是除錯資料，不再阻塞進入可操作選單；打包前才補寫。
	if [[ ! -s "$SPEED_DEBUG_RUN_DIR/tools_version.log" ]]; then
		SPEED_DEBUG_TOOLS_VERSION_SILENT=1 print_tools_version 2>/dev/null
		SPEED_DEBUG_TOOLS_VERSION_SILENT=0
	fi
	{
		echo "${_mode}_time=$(date '+%Y-%m-%d %H:%M:%S' 2>/dev/null)"
		echo "${_mode}_exit_code=$_ec"
	} >> "$SPEED_DEBUG_INFO_LOG" 2>/dev/null
	SPEED_DEBUG_ARCHIVE="$SPEED_DEBUG_BASE/speed_debug_$SPEED_DEBUG_TS.tar"
	_speed_debug_sync_legacy_log "$_mode" "$_ec"
	local _pack_err="$SPEED_DEBUG_BASE/.speed_debug_pack_$SPEED_DEBUG_TS.err"
	local _tar_bin
	_tar_bin="$(command -v tar 2>/dev/null)"
	[[ -z $_tar_bin && -x /data/backup_tools/tar ]] && _tar_bin="/data/backup_tools/tar"
	[[ -z $_tar_bin ]] && _tar_bin="tar"
	_pack_start_ms="$(_speed_now_ms 2>/dev/null)"
	_speed_debug_pack_log "[speed_debug] ${_mode}打包: run=$SPEED_DEBUG_RUN_DIR out=$SPEED_DEBUG_ARCHIVE tar=$_tar_bin"
	rm -f "$SPEED_DEBUG_ARCHIVE" "$_pack_err" 2>/dev/null
	(
		cd "$SPEED_DEBUG_BASE" || exit 70
		# debug 打包必須繞過 tar() OOM wrapper；wrapper 會寫 main.log，導致 tar 讀取 main.log 時 file changed as we read it。
		command "$_tar_bin" -cf "$(basename "$SPEED_DEBUG_ARCHIVE")" "$(basename "$SPEED_DEBUG_RUN_DIR")"
	) 2>"$_pack_err"
	local _tar_rc=$?
	if [[ $_tar_rc = 0 && -s "$SPEED_DEBUG_ARCHIVE" ]]; then
		case $_pack_start_ms in ''|*[!0-9]*) _pack_elapsed_ms="unknown" ;; *) _pack_elapsed_ms="$(( $(_speed_now_ms 2>/dev/null) - _pack_start_ms ))" ;; esac
		_archive_size="$(wc -c < "$SPEED_DEBUG_ARCHIVE" 2>/dev/null)"; case $_archive_size in ''|*[!0-9]*) _archive_size="unknown" ;; esac
		# r453: final/snapshot tar 完成後用 native eventwait 確認輸出大小穩定；失敗只記錄，不改成功語義。
		_eventwait_file_size_stable_ms "$SPEED_DEBUG_ARCHIVE" "${SPEEDBACKUP_DEBUG_PACK_STABLE_MS:-250}" "${SPEEDBACKUP_DEBUG_PACK_STABLE_TIMEOUT_MS:-3000}" "speed_debug_${_mode}_archive_stable" >/dev/null 2>&1 || true
		_speed_debug_pack_log "[speed_debug] ${_mode}打包完成: rc=0 elapsedMs=$_pack_elapsed_ms bytes=$_archive_size mode=r459"
		rm -f "$_pack_err" 2>/dev/null
		if [[ $_delete = 1 ]]; then
			_speed_debug_safe_remove_run_dir "$SPEED_DEBUG_RUN_DIR"
			_speed_debug_pack_log "[speed_debug] 除錯日誌已打包: $SPEED_DEBUG_ARCHIVE"
		else
			_speed_debug_pack_log "[speed_debug] 除錯日誌快照已打包: $SPEED_DEBUG_ARCHIVE"
		fi
		_speed_debug_prune_archives
		return 0
	fi
	_speed_debug_pack_log "[speed_debug] ${_mode}打包失敗 rc=$_tar_rc，保留目錄: $SPEED_DEBUG_RUN_DIR"; echo "[speed_debug] ${_mode}打包失敗 rc=$_tar_rc，保留目錄: $SPEED_DEBUG_RUN_DIR"
	[[ -s "$_pack_err" ]] && sed 's/^/[speed_debug][tar] /' "$_pack_err" 2>/dev/null
	return 1
}
_speed_debug_snapshot_pack() {
	_speed_debug_pack_common "snapshot" "${1:-0}" 0
	local _rc=$?
	[[ $_rc = 0 ]] && SPEED_DEBUG_SNAPSHOT_DONE=1
	return $_rc
}
_speed_debug_pack() {
	_speed_debug_disarm_if_run_gone
	if [[ "${SPEED_DEBUG_PACKED:-0}" = 1 ]]; then
		SPEED_DEBUG_ERR_LOG="/dev/null"
		_speed_debug_pack_log "[speed_debug] 最終打包跳過: 已打包過"
		return 0
	fi
	SPEED_DEBUG_PACKED=1
	_speed_debug_pack_common "final" "${1:-0}" 1
	local _pack_rc=$?
	# r440: 不在 _speed_debug_pack 內還原 screen_off_timeout；
	# 還原放到 EXIT trap 最後一步，避免 tar 完成後又因恢復鎖屏/息屏而讓後續 EXIT 收尾被螢幕關閉延後。
	return $_pack_rc
}

_speed_debug_consolidate_detail_pattern() {
	# r249: 將大量 per-app / per-stage detail txt 合併成 aggregate log，避免 speed_debug tar 被上百個小檔案刷屏。
	# 只在 final/snapshot 打包前整理 debug 目錄；主流程仍保留 main.log / debug_timeline.tsv 的快速定位資訊。
	[[ -n ${SPEED_DEBUG_RUN_DIR:-} && -d "$SPEED_DEBUG_RUN_DIR" ]] || return 0
	local _outname="$1" _pattern="$2" _title="$3" _out _f _count=0 _size
	[[ -n $_outname && -n $_pattern ]] || return 0
	_out="$SPEED_DEBUG_RUN_DIR/$_outname"
	for _f in $SPEED_DEBUG_RUN_DIR/$_pattern; do
		[[ -f $_f ]] || continue
		# 避免把 aggregate 自己再次吃進去。
		[[ ${_f##*/} = "$_outname" ]] && continue
		if [[ $_count -eq 0 ]]; then
			{
				echo "# SpeedBackup consolidated debug detail"
				echo "# title=${_title:-$_pattern}"
				echo "# pattern=$_pattern"
				echo "# generated=$(date '+%Y-%m-%d %H:%M:%S' 2>/dev/null)"
			} > "$_out" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} || return 0
		fi
		_size="$(wc -c < "$_f" 2>/dev/null)"
		{
			echo
			echo "===== ${_f##*/} BEGIN size=${_size:-0} ====="
			cat "$_f" 2>/dev/null
			echo "===== ${_f##*/} END ====="
		} >> "$_out" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} || true
		rm -f "$_f" 2>/dev/null && _count=$((_count + 1))
	done
	[[ $_count -gt 0 ]] && _speed_debug_pack_log "[speed_debug] 已合併 ${_title:-$_pattern}: $_count 個 -> $_outname"
	return 0
}

_speed_debug_consolidate_foreground_hot_logs() {
	# r436: 正常完成路徑也要把 ProcessObserver foreground 高量 per-app txt 收斂成少量單檔。
	# 保持其它重型 detail consolidation 預設跳過，避免回到 r424 前 snapshot/final 雙重打包開銷。
	[[ -n ${SPEED_DEBUG_RUN_DIR:-} && -d "$SPEED_DEBUG_RUN_DIR" ]] || return 0
	_speed_debug_consolidate_detail_pattern "process_observer_foreground_foreground_state_pkg_active_details.log" "process_observer_foreground_foreground_state_pkg_active_*.txt" "process observer foreground active detail"
	_speed_debug_consolidate_detail_pattern "process_observer_foreground_pkg_process_pids_details.log" "process_observer_foreground_pkg_process_pids_*.txt" "process observer foreground process-pids detail"
	_speed_debug_consolidate_detail_pattern "process_observer_foreground_cgroup_freezer_start_details.log" "process_observer_foreground_cgroup_freezer_start_*.txt" "process observer foreground cgroup-freezer detail"
	return 0
}

_speed_debug_consolidate_detail_logs() {
	[[ -n ${SPEED_DEBUG_RUN_DIR:-} && -d "$SPEED_DEBUG_RUN_DIR" ]] || return 0
	_speed_debug_consolidate_detail_pattern "process_observer_foreground_details.log" "process_observer_foreground_*.txt" "process observer foreground per-app detail"
	_speed_debug_consolidate_detail_pattern "process_observer_top_details.log" "process_observer_top_*.txt" "process observer top detail"
	_speed_debug_consolidate_detail_pattern "package_live_state_details.log" "package_live_state_*.txt" "package live state per-app detail"
	_speed_debug_consolidate_detail_pattern "package_install_snapshot_details.log" "package_install_snapshot_*.txt" "package install snapshot per-app detail"
	_speed_debug_consolidate_detail_pattern "package_restriction_snapshot_details.log" "package_restriction_snapshot_*.txt" "package restriction snapshot per-app detail"
	_speed_debug_consolidate_detail_pattern "uid_live_state_details.log" "uid_live_state_*.txt" "uid live state per-app detail"
	_speed_debug_consolidate_detail_pattern "uid_observer_probe_details.log" "uid_observer_probe_*.txt" "uid observer probe detail"
	_speed_debug_consolidate_detail_pattern "cgroup_proc_snapshot_details.log" "cgroup_proc_snapshot_*.txt" "cgroup proc snapshot per-app detail"
	_speed_debug_consolidate_detail_pattern "cgroup_kill_pid_list_details.log" "cgroup_kill_pid_list_*.txt" "cgroup kill pid list detail"
	_speed_debug_consolidate_detail_pattern "cgroup_native_kill_details.log" "cgroup_native_kill_*.txt" "cgroup native kill detail"
	_speed_debug_consolidate_detail_pattern "speedscan_tree_chown_details.log" "speedscan_tree_chown_*.txt" "speedscan tree-chown per-app detail"
	return 0
}

_speed_debug_merge_numbered_logs() {
	# v24.20.14-7.66-191：若舊流程或中途殘留 *_001.log / *_002.log，收尾前合併回 base.log 後移除。
	# 目標是批量備份/恢復時 speed_debug 包只保留少量 aggregate log，不再產生大量分片檔。
	[[ -n ${SPEED_DEBUG_RUN_DIR:-} && -d "$SPEED_DEBUG_RUN_DIR" ]] || return 0
	local _base _dup _merged=0 _basefile
	for _base in \
		compress extract checksum \
		app_state_stdinput \
		verify_app_state_stdinput; do
		_basefile="$SPEED_DEBUG_RUN_DIR/${_base}.log"
		for _dup in "$SPEED_DEBUG_RUN_DIR/${_base}_"[0-9][0-9][0-9].log; do
			[[ -f $_dup ]] || continue
			if [[ -f $_basefile ]] && cmp -s "$_basefile" "$_dup" 2>/dev/null; then
				rm -f "$_dup" 2>/dev/null && _merged=$((_merged + 1))
				continue
			fi
			{
				echo
				echo "===== MERGED ${_dup##*/} BEGIN ====="
				cat "$_dup" 2>/dev/null
				echo "===== MERGED ${_dup##*/} END ====="
			} >> "$_basefile" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
			rm -f "$_dup" 2>/dev/null && _merged=$((_merged + 1))
		done
	done
	[[ $_merged -gt 0 ]] && _speed_debug_pack_log "[speed_debug] 已合併分片debug log: $_merged 個"
	return 0
}

_speed_debug_dedupe_logs() {
	[[ -n ${SPEED_DEBUG_RUN_DIR:-} && -d "$SPEED_DEBUG_RUN_DIR" ]] || return 0
	local _removed=0
	_speed_debug_merge_numbered_logs
	_speed_debug_consolidate_detail_logs
	# command.log 若完全為空，沒有診斷價值；stderr.log 即使 0 bytes 仍保留作為清潔度證明。
	[[ -f "$SPEED_DEBUG_RUN_DIR/command.log" && ! -s "$SPEED_DEBUG_RUN_DIR/command.log" ]] && rm -f "$SPEED_DEBUG_RUN_DIR/command.log" 2>/dev/null && _removed=$((_removed + 1))
	[[ $_removed -gt 0 ]] && _speed_debug_pack_log "[speed_debug] 已清理空debug log: $_removed 個"
	return 0
}

# r492: removed obsolete detached normal-finish async cleanup; final run tmpdir deletion is synchronous.

_speed_debug_normal_finish_pack() {
	# 正常流程主動建立 final 包並刪除 run_xxx，避免單獨入口 / pipeline subshell 的 EXIT trap 沒有執行時留下 run 目錄。
	# r424: 正常成功路徑預設不再做昂貴的 detail consolidation 與 snapshot+final 雙打包；完整分片仍留在 speed_debug tar 內。
	if [[ "${SPEED_DEBUG_CONSOLIDATE_ON_NORMAL:-0}" = 1 ]]; then
		_speed_debug_dedupe_logs
	else
		_speed_debug_consolidate_foreground_hot_logs
		_speed_debug_pack_log "[speed_debug] normal finish 重型 detail 合併跳過: mode=r440 keep_per_app_details=1 foregroundHotMerged=1"
	fi
	if [[ "${SPEED_DEBUG_SNAPSHOT_ON_NORMAL:-0}" = 1 && "${SPEED_DEBUG_SNAPSHOT_DONE:-0}" != 1 ]]; then
		_speed_debug_snapshot_pack "${1:-0}"
	fi
	_speedbackup_run_tmpdir_stop_daemons_for_cleanup normal_finish
	_speed_debug_pack "${1:-0}"
	# r455: 保留 r454 timeout/stale 修復；進度條輸出回退 r453 inline_existing。
# r456: 只修進度列行狀態：保留 r453 label/格式，新增 clear-to-EOL 與普通輸出前清除 active progress，避免進度條與下一條訊息黏在同一行。
	_speedbackup_display_restore_after_debug_pack "normal-finish-after-final-debug-pack" || true
	_speedbackup_root_tmp_state_cleanup normal_finish || true
	# r489: normal success must synchronously delete the run-scoped runtime tmpdir.
	# The previous detached async cleanup could be killed with the parent shell on some Android/terminal
	# environments, leaving /data/local/tmp/.speedbackup_run_* after a successful final pack.
	_speedbackup_run_tmpdir_final_cleanup
