# 根據當前 conf_path 判斷類型,觸發對應模板重新寫入
# 用於腳本版本升級時自動補齊新增的設定欄位
_update_conf() {
	case $conf_path in
	*backup_settings.conf)  update_backup_settings_conf>"$conf_path" ;;
	*restore_settings.conf) update_Restore_settings_conf>"$conf_path" ;;
	*) echo "$conf_path配置遺失" && exit 1 ;;
	esac
