_conf_patch_log() {
	[[ -n ${SPEED_DEBUG_RUN_DIR:-} && -d ${SPEED_DEBUG_RUN_DIR:-} ]] || return 0
	printf '%s\n' "$*" >> "$SPEED_DEBUG_RUN_DIR/conf_patch.log" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
}
_conf_has_key() {
	grep -Eq "^[[:space:]]*$1=" "$conf_path" 2>/dev/null
}
_conf_insert_after_key() {
	local _anchor="$1" _key="$2" _line="$3" _tmp
	[[ -n $_key && -n $_line ]] || return 0
	_conf_has_key "$_key" && return 0
	_tmp="${conf_path}.tmp.$$"
	awk -v a="$_anchor" -v l="$_line" '
		BEGIN { done=0 }
		{ print }
		!done && $0 ~ "^[[:space:]]*" a "=" { print l; done=1 }
		END { if (!done) { print ""; print l } }
	' "$conf_path" > "$_tmp" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} && {
		cat "$_tmp" > "$conf_path"
		_conf_patch_log "INSERT key=$_key after=$_anchor line=$_line"
	}
	rm -f "$_tmp" 2>/dev/null
}
_conf_remove_exact_conf_lines() {
	local _tmp
	_tmp="${conf_path}.tmp.$$"
	awk '
		/^[[:space:]]*hybrid_urls="\$\{hybrid_urls:-\}"[[:space:]]*$/ {changed=1; next}
		/^[[:space:]]*hybrid_get_mode="\$\{hybrid_get_mode:-assist\}"[[:space:]]*$/ {changed=1; next}
		/^[[:space:]]*hybrid_get_lead_chunks="\$\{hybrid_get_lead_chunks:-32\}"[[:space:]]*$/ {changed=1; next}
		/^[[:space:]]*hybrid_get_assist_stride="\$\{hybrid_get_assist_stride:-5\}"[[:space:]]*$/ {changed=1; next}
		{ print }
		END { if (changed) exit 0; exit 1 }
	' "$conf_path" > "$_tmp" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} && {
		cat "$_tmp" > "$conf_path"
		_conf_patch_log "REMOVE abandoned_hxfer_conf_fallback_lines"
	}
	rm -f "$_tmp" 2>/dev/null
}
_conf_remove_key() {
	local _key="$1" _tmp
	[[ -n $_key ]] || return 0
	_conf_has_key "$_key" || return 0
	_tmp="${conf_path}.tmp.$$"
	awk -v k="$_key" '
		$0 ~ "^[[:space:]]*" k "=" { changed=1; next }
		{ print }
		END { if (changed) exit 0; exit 1 }
	' "$conf_path" > "$_tmp" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} && {
		cat "$_tmp" > "$conf_path"
		_conf_patch_log "REMOVE obsolete_key=$_key"
	}
	rm -f "$_tmp" 2>/dev/null
}
_conf_sanitize_legacy_comment_noise() {
	# 多次繁中轉換會把「算法」詞庫展開成「演演...算法」；只修註解，不碰使用者設定值。
	local _file="${1:-$conf_path}" _tmp
	[[ -n $_file && -f $_file ]] || return 0
	grep -q '演演.*算法' "$_file" 2>/dev/null || return 0
	_tmp="${_file}.tmp.sanitize.$$"
	awk '
		/^#/ {
			while (gsub(/演演算法/, "演算法")) {}
		}
		{ print }
	' "$_file" > "$_tmp" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} && {
		cat "$_tmp" > "$_file"
		_conf_patch_log "SANITIZE legacy_conf_comment=repeated_algorithm"
	}
	rm -f "$_tmp" 2>/dev/null
}
_conf_remove_internal_remote_function() {
	# 7.66-158 曾誤把內部 _remote_is_enabled() 函數寫進 backup_settings.conf；這裡只精準移除該污染區塊，不重排使用者 conf。
	grep -q '^_remote_is_enabled()[[:space:]]*{' "$conf_path" 2>/dev/null || return 0
	local _tmp="${conf_path}.tmp.$$"
	awk '
		/^_remote_is_enabled\(\)[[:space:]]*\{/ {skip=1; changed=1; next}
		skip && /^}/ {skip=0; next}
		!skip {print}
		END { if (changed) exit 0; exit 1 }
	' "$conf_path" > "$_tmp" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} && {
		if [[ -s "$_tmp" ]]; then
			cat "$_tmp" > "$conf_path"
			_conf_patch_log "REMOVE internal_function=_remote_is_enabled"
		else
			_conf_patch_log "SKIP remove: stripped result empty, conf left untouched"
		fi
	}
	rm -f "$_tmp" 2>/dev/null
}
_conf_template_sync_current() {
	# r492: 每次啟動都把 conf 更新成目前模板：保留使用者設定值，刷新註解/排序，移除已廢棄公開配置。
	# 注意：這不是重置設定。update_*_settings_conf 會使用剛 source 進來的變數值輸出模板。
	local _tmp _type _changed=0
	[[ -n ${conf_path:-} && -f $conf_path ]] || return 0
	_tmp="${conf_path}.template.$$"
	case $conf_path in
	*backup_settings.conf)
		_type="backup"
		update_backup_settings_conf > "$_tmp" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} || { rm -f "$_tmp" 2>/dev/null; return 0; }
		;;
	*restore_settings.conf)
		_type="restore"
		update_Restore_settings_conf > "$_tmp" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} || { rm -f "$_tmp" 2>/dev/null; return 0; }
		;;
	*)
		rm -f "$_tmp" 2>/dev/null
		return 0
		;;
	esac
	if [[ -s $_tmp ]] && ! cmp -s "$_tmp" "$conf_path" 2>/dev/null; then
		cat "$_tmp" > "$conf_path" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} && _changed=1
	fi
	rm -f "$_tmp" 2>/dev/null
	if [[ $_changed = 1 ]]; then
		_conf_patch_log "CONF_TEMPLATE_SYNC_OK type=$_type mode=r492 keep_user_values=1 removed_obsolete_public_keys=1"
	else
		_conf_patch_log "CONF_TEMPLATE_SYNC_SKIP type=$_type reason=already_current mode=r492"
	fi
	return 0
}

_conf_remove_obsolete_public_keys() {
	# r492: 舊 conf 先精準移除已廢棄公開配置；隨後模板同步會更新註解/排序。
	case $conf_path in
	*backup_settings.conf)
		_conf_remove_key diagnostic_mode
		_conf_remove_key stream_background_boost
		_conf_remove_key stream_background_boost_mode
		_conf_remove_key stream_background_boost_target
		_conf_remove_key stream_background_boost_interval_sec
		_conf_remove_key stream_background_boost_burst_interval_sec
		_conf_remove_key stream_background_boost_burst_sec
		_conf_remove_key stream_background_boost_idle_ms
		_conf_remove_key stream_background_boost_verbose
		;;
	esac
	return 0
}

_patch_conf_missing_fields() {
	# 先補/清舊 conf，再交給模板同步重寫註解與配置項；使用者值由 source 進來的變數保留。
	case $conf_path in
	*backup_settings.conf)
		# 清除已移交獨立模組/已放棄支線造成的舊污染；不重寫或重排其他使用者設定。
		local _obsolete_module_key="sm""bd_share_path"
		_conf_remove_key "$_obsolete_module_key"
		_conf_remove_internal_remote_function
		_conf_remove_obsolete_public_keys
		_conf_remove_exact_conf_lines
		_conf_sanitize_legacy_comment_noise "$conf_path"
		# 只補缺失項，補固定值，不再把 ${var:-default} fallback 寫入使用者 conf。
		_conf_insert_after_key background_execution notification_enable 'notification_enable=1'
		_conf_insert_after_key Compression_method rgb_a 'rgb_a=220'
		_conf_insert_after_key rgb_a rgb_b 'rgb_b=51'
		_conf_insert_after_key rgb_b rgb_c 'rgb_c=213'
		_conf_insert_after_key rgb_c remote_type 'remote_type='
		_conf_insert_after_key remote_type smb_url 'smb_url='
		_conf_insert_after_key smb_url smb_remote_user 'smb_remote_user='
		_conf_insert_after_key smb_remote_user smb_remote_pass 'smb_remote_pass=""'
		_conf_insert_after_key smb_remote_pass webdav_url 'webdav_url='
		_conf_insert_after_key webdav_url webdav_remote_user 'webdav_remote_user='
		_conf_insert_after_key webdav_remote_user webdav_remote_pass 'webdav_remote_pass=""'
		_conf_insert_after_key webdav_remote_pass remote_stream 'remote_stream=0'
		_conf_insert_after_key remote_stream webdav_stream_heartbeat_sec 'webdav_stream_heartbeat_sec=30'
		_conf_insert_after_key webdav_stream_heartbeat_sec webdav_stream_progress_step_mb 'webdav_stream_progress_step_mb=256'
		_conf_insert_after_key webdav_stream_progress_step_mb webdav_stream_idle_warn_sec 'webdav_stream_idle_warn_sec=60'
		_conf_insert_after_key webdav_stream_idle_warn_sec webdav_stream_verbose 'webdav_stream_verbose=0'
		_conf_insert_after_key webdav_stream_verbose remote_keep_local 'remote_keep_local=0'
		_conf_insert_after_key remote_keep_local remote_upload_per_app 'remote_upload_per_app=0'
		_conf_insert_after_key remote_upload_per_app log_max_size_mb 'log_max_size_mb=1'
		;;
	*restore_settings.conf)
		_conf_remove_exact_conf_lines
		_conf_sanitize_legacy_comment_noise "$conf_path"
		_conf_insert_after_key background_execution notification_enable 'notification_enable=1'
		_conf_insert_after_key notification_enable log_max_size_mb 'log_max_size_mb=1'
		_conf_insert_after_key Compression_method rgb_a 'rgb_a=220'
		_conf_insert_after_key rgb_a rgb_b 'rgb_b=51'
		_conf_insert_after_key rgb_b rgb_c 'rgb_c=213'
		;;
	esac
}
if [[ ! -f $conf_path ]]; then
	_update_conf
	echo "因腳本找不到\n$conf_path\n故重新生成默認列表\n請重新配置後重新執行腳本" && exit 0
fi
. "$conf_path" &>/dev/null
# 保存使用者 conf 原值；後續遠端預檢可能會暫時清空/關閉 runtime 變量，不能反寫污染 backup_settings.conf。
_CONF_SRC_remote_type="$remote_type"
_CONF_SRC_smb_url="$smb_url"
_CONF_SRC_smb_remote_user="$smb_remote_user"
_CONF_SRC_smb_remote_pass="$smb_remote_pass"
_CONF_SRC_webdav_url="$webdav_url"
_CONF_SRC_webdav_remote_user="$webdav_remote_user"
_CONF_SRC_webdav_remote_pass="$webdav_remote_pass"
_CONF_SRC_remote_stream="$remote_stream"
_CONF_SRC_remote_keep_local="$remote_keep_local"
_CONF_SRC_remote_upload_per_app="$remote_upload_per_app"
# r492: 先清舊 key / 污染，再依目前模板重寫 conf 註解與配置項；保留使用者設定值。
_patch_conf_missing_fields
_conf_template_sync_current
# 模板同步後重新載入一次，讓後續流程使用最新配置檔內容。
. "$conf_path" &>/dev/null
# 公開 conf 不再提供診斷細項；內部除錯策略由工具統一派生，不寫回 conf。
_speedbackup_apply_internal_policy
_remote_type_orig="${remote_type:-}"
# 依 remote_type 取對應遠端位址/帳密 (smb_*/webdav_* 由 conf 設定)
case $remote_type in
smb) remote_url="$smb_url"; remote_user="$smb_remote_user"; remote_pass="$smb_remote_pass" ;;
webdav) remote_url="$webdav_url"; remote_user="$webdav_remote_user"; remote_pass="$webdav_remote_pass" ;;
*) remote_url=""; remote_user=""; remote_pass="" ;;
esac

# SMB 憑證改走檔案傳遞；WebDAV 已改由 dex WebDavUtil 傳參，不再生成外部 HTTP 工具專用參數。
_SMB_AUTHFILE=""
# trim 前後空白: 設定檔裡的欄位若殘留空格/CR, "-n" 判斷會誤判為已填帳號,
# 導致產生只含空白的憑證檔路徑, 舊外部 HTTP 工具收到錯誤參數直接報錯。
_remote_user_trimmed="${remote_user# }"; _remote_user_trimmed="${_remote_user_trimmed% }"
if [[ $remote_type = smb && -n $_remote_user_trimmed ]]; then
	_SMB_AUTHFILE="${TMPDIR:-/data/local/tmp}/.smb_authfile_$$"
	{
		printf 'username = %s\n' "$remote_user"
		printf 'password = %s\n' "$remote_pass"
	} > "$_SMB_AUTHFILE" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	chmod 0600 "$_SMB_AUTHFILE" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
fi
unset _remote_user_trimmed

# ===== WebDAV daemon（優先 AF_UNIX，TCP loopback 相容回退）=====
# Dex daemon 的六行控制協定保持不變；native unixsock v2 只負責二進位安全的
# stdin/stdout relay、stdin EOF half-close，以及把兩行回應 header 寫入小型 sidecar。
# getstdoutrel 的 body 直接串到 stdout，不建立 archive-sized response 暫存檔。
_WEBDAV_DAEMON_PORT="${_WEBDAV_DAEMON_PORT:-8971}"
_WEBDAV_DAEMON_SOCKET="${_WEBDAV_DAEMON_SOCKET:-$TMPDIR/.webdav_daemon.sock}"
_WEBDAV_DAEMON_PID_FILE=""
_WEBDAV_DAEMON_STATE_FILE=""
_WEBDAV_DAEMON_START_LOCK="${_WEBDAV_DAEMON_START_LOCK:-$TMPDIR/.webdav_daemon.start.lock}"
_WEBDAV_DAEMON_READY=0
_WEBDAV_DAEMON_MODE=""
_WEBDAV_DAEMON_TARGET=""
_WEBDAV_UNIXSOCK_READY_CACHE=""
# command substitution 會在子 shell 執行；_WEBDAV_HTTP_CODE 這類變數不會回到父 shell。
# 因此 daemon 解析到的 HTTP 狀態同時寫入 sidecar，供 OPTIONS/list/stat 等捕獲 stdout 的路徑讀回。
_WEBDAV_LAST_STATUS_FILE="${_WEBDAV_LAST_STATUS_FILE:-$TMPDIR/.webdav_last_status_${SPEEDBACKUP_MAIN_PID:-$$}}"

_webdav_status_sidecar_reset() {
	[[ -n ${_WEBDAV_LAST_STATUS_FILE:-} ]] && rm -f "$_WEBDAV_LAST_STATUS_FILE" 2>/dev/null
}

_webdav_status_sidecar_store() {
	[[ -n ${_WEBDAV_LAST_STATUS_FILE:-} ]] || return 0
	{
		printf '%s\n' "${_WEBDAV_HTTP_CODE:-0}"
		printf '%s\n' "${_WEBDAV_BODY_LENGTH:-0}"
	} > "$_WEBDAV_LAST_STATUS_FILE" 2>/dev/null || true
}

_webdav_status_sidecar_load() {
	local _code _len
	[[ -s ${_WEBDAV_LAST_STATUS_FILE:-} ]] || return 1
	_code="$(sed -n '1p' "$_WEBDAV_LAST_STATUS_FILE" 2>/dev/null)"
	_len="$(sed -n '2p' "$_WEBDAV_LAST_STATUS_FILE" 2>/dev/null)"
	case $_code in ''|*[!0-9]*) return 1 ;; esac
	case $_len in -1|-2|*[!0-9]*|'') _len=0 ;; esac
	_WEBDAV_HTTP_CODE="$_code"
	_WEBDAV_BODY_LENGTH="$_len"
	rm -f "$_WEBDAV_LAST_STATUS_FILE" 2>/dev/null
	return 0
}

_webdav_tmp_path() {
	local _prefix="${1:-webdav_tmp}" _f
	_f="$(mktemp "$TMPDIR/.${_prefix}_XXXXXX" 2>/dev/null)" && { echo "$_f"; return 0; }
	printf '%s/.%s_%s_%s_%s\n' "$TMPDIR" "$_prefix" "$$" "$RANDOM" "$(date +%s 2>/dev/null)"
}

_webdav_unixsock_relay_ready() {
	local _ver
	_speedbackup_tool_verify_once unixsock 1 || { _WEBDAV_UNIXSOCK_READY_CACHE=0; return 1; }
	case ${_WEBDAV_UNIXSOCK_READY_CACHE:-} in
	1) return 0 ;;
	0) return 1 ;;
	esac
	[[ -x ${EVENT_UNIXSOCK_BIN:-} ]] || { _WEBDAV_UNIXSOCK_READY_CACHE=0; return 1; }
	# 外層 subshell 一併吞掉「Segmentation fault」等 shell 診斷；結果只快取一次，
	# 避免損壞的 unixsock 在同一輪被重複執行。
	_ver="$( ( _event_unixsock_call --version ) 2>/dev/null | head -n 1)"
	case "$_ver" in
	*stream-relay*|*stream-framed*|*plain-lines-single-eof*|unixsock\ 2.[3-9]*)
		_WEBDAV_UNIXSOCK_READY_CACHE=1
		_speed_debug_log "WEBDAV_UNIXSOCK_RELAY_READY version=${_ver}"
		return 0
		;;
	*)
		_WEBDAV_UNIXSOCK_READY_CACHE=0
		_speed_debug_log "WEBDAV_UNIXSOCK_RELAY_REJECT version=${_ver:-empty}"
		return 1
		;;
	esac
}

_webdav_proc_cmdline() {
	local _pid="$1"
	[[ -r /proc/$_pid/cmdline ]] || return 1
	tr '\000' ' ' < "/proc/$_pid/cmdline" 2>/dev/null
}

_webdav_proc_starttime() {
	local _pid="$1"
	[[ -r /proc/$_pid/stat ]] || return 1
	sed 's/^[^)]*) //' "/proc/$_pid/stat" 2>/dev/null | awk '{print $20; exit}'
}

_webdav_daemon_write_state() {
	local _pid="$1" _mode="$2" _target="$3" _start _tmp
	_start="$(_webdav_proc_starttime "$_pid")"
	case $_pid in ''|*[!0-9]*) return 1 ;; esac
	case $_start in ''|*[!0-9]*) return 1 ;; esac
	_tmp="${_WEBDAV_DAEMON_STATE_FILE}.tmp.$$.$RANDOM"
	printf '%s|%s|%s|%s|%s\n' "$_mode" "$_target" "$SPEEDBACKUP_MAIN_PID" "$_pid" "$_start" > "$_tmp" 2>/dev/null || return 1
	chmod 0600 "$_tmp" 2>/dev/null
	mv -f "$_tmp" "$_WEBDAV_DAEMON_STATE_FILE" 2>/dev/null || { rm -f "$_tmp" 2>/dev/null; return 1; }
	_dex_daemon_write_pid "$_WEBDAV_DAEMON_PID_FILE" "$_pid"
}

_webdav_daemon_load_state() {
	local _line _mode _target _owner _pid _start _current
	[[ -s $_WEBDAV_DAEMON_STATE_FILE && -s $_WEBDAV_DAEMON_PID_FILE ]] || return 1
	_line="$(sed -n '1p' "$_WEBDAV_DAEMON_STATE_FILE" 2>/dev/null)"
	_mode="${_line%%|*}"; _line="${_line#*|}"
	_target="${_line%%|*}"; _line="${_line#*|}"
	_owner="${_line%%|*}"; _line="${_line#*|}"
	_pid="${_line%%|*}"; _start="${_line#*|}"
	case $_pid in ''|*[!0-9]*) return 1 ;; esac
	case $_start in ''|*[!0-9]*) return 1 ;; esac
	[[ $_owner = "$SPEEDBACKUP_MAIN_PID" ]] || return 1
	[[ "$(cat "$_WEBDAV_DAEMON_PID_FILE" 2>/dev/null)" = "$_pid" ]] || return 1
	kill -0 "$_pid" 2>/dev/null || return 1
	_current="$(_webdav_proc_starttime "$_pid")"
	[[ $_current = "$_start" ]] || return 1
	# 不在 daemon fork 後立即用 /proc/<pid>/cmdline 驗證 Java 參數：
	# child 在 exec app_process 前存在極短競態窗口，會暫時仍顯示父 shell/nohup cmdline，
	# 導致正常 daemon 被誤判並立刻 TERM。PID + /proc starttime + owner + target 已足以防 PID reuse。
	case $_mode in
	unix) [[ $_target = "$_WEBDAV_DAEMON_SOCKET" ]] || return 1 ;;
	tcp) [[ $_target = "$_WEBDAV_DAEMON_PORT" ]] || return 1 ;;
	*) return 1 ;;
	esac
	_WEBDAV_DAEMON_MODE="$_mode"
	_WEBDAV_DAEMON_TARGET="$_target"
	return 0
}

_webdav_daemon_fast_ready_cache_file() {
	printf '%s\n' "${TMPDIR:-/data/local/tmp}/.webdav_daemon.ready_fast"
}

_webdav_daemon_fast_ready_mark() {
	local _now _pid _start _file _tmp
	[[ ${SPEEDBACKUP_WEBDAV_DAEMON_READY_FAST_CACHE:-1} = 1 ]] || return 0
	[[ -n ${_WEBDAV_DAEMON_MODE:-} && -n ${_WEBDAV_DAEMON_TARGET:-} ]] || return 0
	[[ -n ${_WEBDAV_DAEMON_PID_FILE:-} ]] || _WEBDAV_DAEMON_PID_FILE="${TMPDIR:-/data/local/tmp}/.webdav_daemon.pid"
	[[ -n ${_WEBDAV_DAEMON_STATE_FILE:-} ]] || _WEBDAV_DAEMON_STATE_FILE="${TMPDIR:-/data/local/tmp}/.webdav_daemon.state"
	_pid="$(cat "$_WEBDAV_DAEMON_PID_FILE" 2>/dev/null)"
	case $_pid in ''|*[!0-9]*) return 0 ;; esac
	_start="$(_webdav_proc_starttime "$_pid")"
	case $_start in ''|*[!0-9]*) return 0 ;; esac
	_now="$(_speed_now_ms 2>/dev/null)"
	case $_now in ''|*[!0-9]*) return 0 ;; esac
	_file="$(_webdav_daemon_fast_ready_cache_file)"
	_tmp="$_file.tmp.$$.$RANDOM"
	printf '%s|%s|%s|%s|%s\n' "$_now" "$_WEBDAV_DAEMON_MODE" "$_WEBDAV_DAEMON_TARGET" "$_pid" "$_start" > "$_tmp" 2>/dev/null || return 0
	chmod 0600 "$_tmp" 2>/dev/null
	mv -f "$_tmp" "$_file" 2>/dev/null || rm -f "$_tmp" 2>/dev/null
}

_webdav_daemon_fast_ready_ok() {
	local _file _line _ts _mode _target _pid _start _now _age _ttl _current
	[[ ${SPEEDBACKUP_WEBDAV_DAEMON_READY_FAST_CACHE:-1} = 1 ]] || return 1
	[[ -n ${_WEBDAV_DAEMON_PID_FILE:-} ]] || _WEBDAV_DAEMON_PID_FILE="${TMPDIR:-/data/local/tmp}/.webdav_daemon.pid"
	[[ -n ${_WEBDAV_DAEMON_STATE_FILE:-} ]] || _WEBDAV_DAEMON_STATE_FILE="${TMPDIR:-/data/local/tmp}/.webdav_daemon.state"
	_file="$(_webdav_daemon_fast_ready_cache_file)"
	[[ -s $_file ]] || return 1
	_line="$(sed -n '1p' "$_file" 2>/dev/null)"
	_ts="${_line%%|*}"; _line="${_line#*|}"
	_mode="${_line%%|*}"; _line="${_line#*|}"
	_target="${_line%%|*}"; _line="${_line#*|}"
	_pid="${_line%%|*}"; _start="${_line#*|}"
	case $_ts in ''|*[!0-9]*) return 1 ;; esac
	case $_pid in ''|*[!0-9]*) return 1 ;; esac
	case $_start in ''|*[!0-9]*) return 1 ;; esac
	_ttl="${SPEEDBACKUP_WEBDAV_DAEMON_READY_FAST_TTL_MS:-10000}"
	case $_ttl in ''|*[!0-9]*|0) _ttl=10000 ;; esac
	_now="$(_speed_now_ms 2>/dev/null)"
	case $_now in ''|*[!0-9]*) return 1 ;; esac
	_age=$((_now - _ts))
	[[ $_age -ge 0 && $_age -le $_ttl ]] || return 1
	[[ "$(cat "$_WEBDAV_DAEMON_PID_FILE" 2>/dev/null)" = "$_pid" ]] || return 1
	kill -0 "$_pid" 2>/dev/null || return 1
	_current="$(_webdav_proc_starttime "$_pid")"
	[[ $_current = "$_start" ]] || return 1
	case $_mode in
	unix) [[ $_target = "$_WEBDAV_DAEMON_SOCKET" && -S $_target ]] || return 1 ;;
	tcp) [[ $_target = "$_WEBDAV_DAEMON_PORT" ]] || return 1 ;;
	*) return 1 ;;
	esac
	_WEBDAV_DAEMON_MODE="$_mode"
	_WEBDAV_DAEMON_TARGET="$_target"
	_WEBDAV_DAEMON_READY=1
	_WEBDAV_DAEMON_FAST_READY_AGE_MS="$_age"
	_WEBDAV_DAEMON_FAST_READY_TTL_MS="$_ttl"
	return 0
}

_webdav_daemon_state_fast_ready_ok() {
	# r286: r284 的 file TTL cache 在部分 mksh/subshell 熱路徑沒有命中；
	# 在真正 transport probe 前先用嚴格 state 驗證：owner + pidfile + /proc starttime + socket。
	# 成功時可安全視為 daemon ready，避免每個 PUT 前都打 encodepath probe。
	[[ ${SPEEDBACKUP_WEBDAV_DAEMON_READY_FAST_CACHE:-1} = 1 ]] || return 1
	[[ ${remote_type:-} = webdav ]] || return 1
	if [[ ${remote_type:-} = webdav ]] && { _remote_stream_fatal_active || _remote_netwatch_changed_active; }; then
		return 1
	fi
	_webdav_daemon_load_state || return 1
	case $_WEBDAV_DAEMON_MODE in
	unix) [[ -S $_WEBDAV_DAEMON_SOCKET ]] || return 1 ;;
	tcp) ;;
	*) return 1 ;;
	esac
	_WEBDAV_DAEMON_READY=1
	_webdav_daemon_fast_ready_mark
	return 0
}

_webdav_daemon_cmdline_fast_ready_ok() {
	# r286: r285 strict-state 在部分熱路徑仍未命中時，使用 pidfile + cmdline + socket/port
	# 做零 relay 的 daemon ready 判定。它不觸碰 PUT 資料流，只避免每個 WebDAV command 前
	# 再送 encodepath probe。cmdline 必須明確包含本次 main pid，避免誤用上一輪孤兒 daemon。
	local _pid _cmdline
	[[ ${SPEEDBACKUP_WEBDAV_DAEMON_READY_FAST_CACHE:-1} = 1 ]] || return 1
	[[ ${remote_type:-} = webdav ]] || return 1
	if [[ ${remote_type:-} = webdav ]] && { _remote_stream_fatal_active || _remote_netwatch_changed_active; }; then
		return 1
	fi
	[[ -n ${_WEBDAV_DAEMON_PID_FILE:-} ]] || _WEBDAV_DAEMON_PID_FILE="${TMPDIR:-/data/local/tmp}/.webdav_daemon.pid"
	[[ -n ${_WEBDAV_DAEMON_STATE_FILE:-} ]] || _WEBDAV_DAEMON_STATE_FILE="${TMPDIR:-/data/local/tmp}/.webdav_daemon.state"
	_pid="$(cat "$_WEBDAV_DAEMON_PID_FILE" 2>/dev/null)"
	case $_pid in ''|*[!0-9]*) return 1 ;; esac
	kill -0 "$_pid" 2>/dev/null || return 1
	_cmdline="$(_webdav_proc_cmdline "$_pid")"
	case "$_cmdline" in
	*"com.xayah.dex.WebDavUtil daemonunix $_WEBDAV_DAEMON_SOCKET 1800 $SPEEDBACKUP_MAIN_PID"*)
		[[ -S $_WEBDAV_DAEMON_SOCKET ]] || return 1
		_WEBDAV_DAEMON_MODE=unix
		_WEBDAV_DAEMON_TARGET="$_WEBDAV_DAEMON_SOCKET"
		_WEBDAV_DAEMON_READY=1
		_webdav_daemon_fast_ready_mark
		return 0
		;;
	*"com.xayah.dex.WebDavUtil daemon $_WEBDAV_DAEMON_PORT 1800 $SPEEDBACKUP_MAIN_PID"*)
		_WEBDAV_DAEMON_MODE=tcp
		_WEBDAV_DAEMON_TARGET="$_WEBDAV_DAEMON_PORT"
		_WEBDAV_DAEMON_READY=1
		_webdav_daemon_fast_ready_mark
		return 0
		;;
	esac
	return 1
}

_webdav_daemon_transport_probe() {
	# 不只看 pid/state；直接對現存 transport 發一個純本地 encodepath request。
	# 這能跨 mksh command substitution/subshell 驗證真正可用的 daemon endpoint，
	# 避免 shell identity 或 state validator 假陰性造成每次 WebDAV 操作都重啟 JVM。
	local _status _rc _code_line
	_webdav_unixsock_relay_ready || return 1
	_status="$(_webdav_tmp_path webdav_daemon_probe_status)"
	rm -f "$_status" 2>/dev/null
	case $_WEBDAV_DAEMON_MODE in
	unix)
		[[ -S $_WEBDAV_DAEMON_SOCKET ]] || { rm -f "$_status" 2>/dev/null; return 1; }
		printf 'encodepath\n\n\nprobe\n\n0\n' | _event_unixsock_call relay-unix "$_WEBDAV_DAEMON_SOCKET" --header-file "$_status" >/dev/null 2>/dev/null
		_rc=$?
		;;
	tcp)
		printf 'encodepath\n\n\nprobe\n\n0\n' | _event_unixsock_call relay-tcp 127.0.0.1 "$_WEBDAV_DAEMON_PORT" --header-file "$_status" >/dev/null 2>/dev/null
		_rc=$?
		;;
	*)
		rm -f "$_status" 2>/dev/null
		return 1
		;;
	esac
	_code_line="$(sed -n '1p' "$_status" 2>/dev/null)"
	rm -f "$_status" 2>/dev/null
	[[ $_rc = 0 && $_code_line = "HTTP 200" ]]
}

_webdav_daemon_transport_alive() {
	# Reuse 以「實際 endpoint 可連線」為最終依據，而不是只依賴 shell state/PID。
	# state/PID 仍保留給 stop 的安全身分驗證與 TCP mode 還原。
	local _pid _line _mode _target
	[[ -n $_WEBDAV_DAEMON_PID_FILE ]] || _WEBDAV_DAEMON_PID_FILE="$TMPDIR/.webdav_daemon.pid"
	[[ -n $_WEBDAV_DAEMON_STATE_FILE ]] || _WEBDAV_DAEMON_STATE_FILE="$TMPDIR/.webdav_daemon.state"

	# AF_UNIX endpoint 存在時優先直接 probe；即使 state owner/starttime 因 shell identity
	# 驗證失敗，只要 socket 真能完成 daemon protocol，就視為可 reuse。
	if [[ -S $_WEBDAV_DAEMON_SOCKET ]]; then
		_WEBDAV_DAEMON_MODE=unix
		_WEBDAV_DAEMON_TARGET="$_WEBDAV_DAEMON_SOCKET"
		_webdav_daemon_transport_probe && return 0
	fi

	# 沒有可用 Unix endpoint 時，從 state 還原 TCP mode 再做實際 probe。
	if [[ -s $_WEBDAV_DAEMON_STATE_FILE ]]; then
		_line="$(sed -n '1p' "$_WEBDAV_DAEMON_STATE_FILE" 2>/dev/null)"
		_mode="${_line%%|*}"
		_line="${_line#*|}"
		_target="${_line%%|*}"
		case $_mode in
		tcp)
			[[ $_target = "$_WEBDAV_DAEMON_PORT" ]] || return 1
			_WEBDAV_DAEMON_MODE=tcp
			_WEBDAV_DAEMON_TARGET="$_target"
			_webdav_daemon_transport_probe && return 0
			;;
		esac
	fi

	# probe 不可用/失敗時只作保守失敗，不把未知 PID 當成可重用 daemon。
	return 1
}

_webdav_daemon_ready_line_ok() {
	local _out="$1"
	case $_WEBDAV_DAEMON_MODE in
	unix) grep -Fqx "DAEMON_READY_UNIX $_WEBDAV_DAEMON_SOCKET" "$_out" 2>/dev/null && [[ -S $_WEBDAV_DAEMON_SOCKET ]] ;;
	tcp) grep -Fqx "DAEMON_READY $_WEBDAV_DAEMON_PORT" "$_out" 2>/dev/null ;;
	*) return 1 ;;
	esac
}

# WebDAV daemon readiness：優先 filewatch 阻塞等待；事件遺失或 ROM inotify
# 行為異常時，才回退 0.1 秒有限輪詢。
_webdav_daemon_wait_ready() {
	local _out="$1" _diag="$2" _pid="$3" _fw_rc=0 _ew_rc=125 _i=0 _ready_pat=""
	case $_pid in ''|*[!0-9]*) return 1 ;; esac
	# 啟動等待只檢查這次剛 fork 出來的明確 PID。
	# r452: 主等待改走 native eventwait file-contains；filewatch/0.1s poll 只作 fallback。
	_webdav_daemon_ready_line_ok "$_out" && kill -0 "$_pid" 2>/dev/null && return 0
	kill -0 "$_pid" 2>/dev/null || return 1
	case $_WEBDAV_DAEMON_MODE in
	unix) _ready_pat="DAEMON_READY_UNIX $_WEBDAV_DAEMON_SOCKET" ;;
	tcp) _ready_pat="DAEMON_READY $_WEBDAV_DAEMON_PORT" ;;
	*) _ready_pat="DAEMON_READY" ;;
	esac
	_eventwait_file_contains "$_out" "$_ready_pat" 5 webdav_ready "$_diag"
	_ew_rc=$?
	_webdav_daemon_ready_line_ok "$_out" && kill -0 "$_pid" 2>/dev/null && {
		echo "$(date '+%H:%M:%S') ready_wait=eventwait rc=$_ew_rc mode=$_WEBDAV_DAEMON_MODE pid=$_pid" >> "$_diag" 2>/dev/null
		return 0
	}
	kill -0 "$_pid" 2>/dev/null || return 1
	if [[ $_ew_rc = 125 ]]; then
		_event_filewatch_once "$_out" 5 webdav_ready "$_diag"
		_fw_rc=$?
		_webdav_daemon_ready_line_ok "$_out" && kill -0 "$_pid" 2>/dev/null && {
			echo "$(date '+%H:%M:%S') ready_wait=filewatch rc=$_fw_rc mode=$_WEBDAV_DAEMON_MODE pid=$_pid" >> "$_diag" 2>/dev/null
			return 0
		}
		kill -0 "$_pid" 2>/dev/null || return 1
		[[ $_fw_rc != 125 ]] && echo "$(date '+%H:%M:%S') filewatch no ready line rc=$_fw_rc mode=$_WEBDAV_DAEMON_MODE pid=$_pid, fallback bounded poll" >> "$_diag" 2>/dev/null
	else
		echo "$(date '+%H:%M:%S') eventwait no ready line rc=$_ew_rc mode=$_WEBDAV_DAEMON_MODE pid=$_pid, fallback bounded poll" >> "$_diag" 2>/dev/null
	fi
	_i=0
	while [[ $_i -lt 30 ]]; do
		_webdav_daemon_ready_line_ok "$_out" && kill -0 "$_pid" 2>/dev/null && {
			echo "$(date '+%H:%M:%S') ready_wait=fallback_poll iterations=$_i mode=$_WEBDAV_DAEMON_MODE pid=$_pid" >> "$_diag" 2>/dev/null
			return 0
		}
		kill -0 "$_pid" 2>/dev/null || return 1
		sleep 0.1
		_i=$((_i + 1))
	done
	return 1
}

_webdav_daemon_stop() {
	_dex_watchdog_stop webdav
	local _pid="" _i=0 _can_kill=0 _cmdline=""
	[[ -n $_WEBDAV_DAEMON_PID_FILE ]] || _WEBDAV_DAEMON_PID_FILE="$TMPDIR/.webdav_daemon.pid"
	[[ -n $_WEBDAV_DAEMON_STATE_FILE ]] || _WEBDAV_DAEMON_STATE_FILE="$TMPDIR/.webdav_daemon.state"

	# 優先使用嚴格 state 驗證，避免 stale pid file 遇到 PID reuse 時誤殺其他程序。
	if _webdav_daemon_load_state; then
		_pid="$(cat "$_WEBDAV_DAEMON_PID_FILE" 2>/dev/null)"
		_can_kill=1
	else
		# 若 state 因 shell identity/owner 驗證失敗，但 pid 指向的 cmdline 明確仍是本工具的
		# WebDavUtil daemon，也允許安全收尾，避免留下只能等 idle timeout 的孤兒 JVM。
		_pid="$(cat "$_WEBDAV_DAEMON_PID_FILE" 2>/dev/null)"
		case $_pid in ''|*[!0-9]*) _pid="" ;; esac
		if [[ -n $_pid ]] && kill -0 "$_pid" 2>/dev/null; then
			_cmdline="$(_webdav_proc_cmdline "$_pid")"
			case "$_cmdline" in
			*"com.xayah.dex.WebDavUtil daemonunix $_WEBDAV_DAEMON_SOCKET"*|*"com.xayah.dex.WebDavUtil daemon $_WEBDAV_DAEMON_PORT"*) _can_kill=1 ;;
			esac
		fi
	fi

	if [[ $_can_kill = 1 && -n $_pid ]] && kill -0 "$_pid" 2>/dev/null; then
		_event_terminate_pid "$_pid" webdav_daemon_stop
	fi
	rm -f "$_WEBDAV_DAEMON_PID_FILE" "$_WEBDAV_DAEMON_STATE_FILE" "$(_webdav_daemon_fast_ready_cache_file)" "$TMPDIR/.webdav_daemon_out" "$_WEBDAV_DAEMON_SOCKET" 2>/dev/null
	# start lock 是 mkdir 建立的空目錄；正常/異常 stop 都保底移除，避免下輪等待 stale starter。
	rmdir "$_WEBDAV_DAEMON_START_LOCK" 2>/dev/null || true
	_WEBDAV_DAEMON_READY=0
	_WEBDAV_DAEMON_MODE=""
	_WEBDAV_DAEMON_TARGET=""
}

_webdav_daemon_start_mode() {
	local _mode="$1" _diag="$2" _out="$TMPDIR/.webdav_daemon_out" _pid _daemon_err _daemon_info
	_daemon_err="$(_speed_debug_log_path webdav_daemon_stderr.log)"
	_daemon_info="$(_speed_debug_log_path webdav_daemon_info.log)"
	_WEBDAV_DAEMON_MODE="$_mode"
	case $_mode in
	unix)
		_WEBDAV_DAEMON_TARGET="$_WEBDAV_DAEMON_SOCKET"
		rm -f "$_WEBDAV_DAEMON_SOCKET" 2>/dev/null
		;;
	tcp) _WEBDAV_DAEMON_TARGET="$_WEBDAV_DAEMON_PORT" ;;
	*) return 1 ;;
	esac
	: > "$_out" 2>/dev/null || return 1
	_dex_export_classpath
	case $_mode in
	unix)
		WEBDAV_DAEMON_INFO_LOG="$_daemon_info" \
		WEBDAV_STREAM_HEARTBEAT_SEC="${webdav_stream_heartbeat_sec:-30}" \
		WEBDAV_STREAM_PROGRESS_STEP_MB="${webdav_stream_progress_step_mb:-256}" \
		WEBDAV_STREAM_IDLE_WARN_SEC="${webdav_stream_idle_warn_sec:-60}" \
		WEBDAV_STREAM_VERBOSE="${webdav_stream_verbose:-0}" \
		nohup "$DEX_APP_PROCESS_BIN" "$DEX_APP_PROCESS_BASE" com.xayah.dex.WebDavUtil \
			daemonunix "$_WEBDAV_DAEMON_SOCKET" 1800 "$SPEEDBACKUP_MAIN_PID" > "$_out" 2>>"$_daemon_err" &
		;;
	tcp)
		WEBDAV_DAEMON_INFO_LOG="$_daemon_info" \
		WEBDAV_STREAM_HEARTBEAT_SEC="${webdav_stream_heartbeat_sec:-30}" \
		WEBDAV_STREAM_PROGRESS_STEP_MB="${webdav_stream_progress_step_mb:-256}" \
		WEBDAV_STREAM_IDLE_WARN_SEC="${webdav_stream_idle_warn_sec:-60}" \
		WEBDAV_STREAM_VERBOSE="${webdav_stream_verbose:-0}" \
		nohup "$DEX_APP_PROCESS_BIN" "$DEX_APP_PROCESS_BASE" com.xayah.dex.WebDavUtil \
			daemon "$_WEBDAV_DAEMON_PORT" 1800 "$SPEEDBACKUP_MAIN_PID" > "$_out" 2>>"$_daemon_err" &
		;;
	esac
	_pid=$!
	disown "$_pid" 2>/dev/null
	_speedbackup_protect_pid "$_pid" webdav_daemon
	if ! _webdav_daemon_write_state "$_pid" "$_mode" "$_WEBDAV_DAEMON_TARGET"; then
		kill "$_pid" 2>/dev/null
		return 1
	fi
	if _webdav_daemon_wait_ready "$_out" "$_diag" "$_pid"; then
		_WEBDAV_DAEMON_READY=1
		echo "$(date '+%H:%M:%S') OK started pid=$_pid owner=$SPEEDBACKUP_MAIN_PID mode=$_mode target=$_WEBDAV_DAEMON_TARGET" >> "$_diag" 2>/dev/null
		case $_mode in
		unix) _dex_watchdog_start webdav "$_WEBDAV_DAEMON_PID_FILE" "$_WEBDAV_DAEMON_SOCKET" com.xayah.dex.WebDavUtil daemonunix "$_WEBDAV_DAEMON_SOCKET" 1800 "$SPEEDBACKUP_MAIN_PID" ;;
		tcp) _dex_watchdog_start webdav "$_WEBDAV_DAEMON_PID_FILE" - com.xayah.dex.WebDavUtil daemon "$_WEBDAV_DAEMON_PORT" 1800 "$SPEEDBACKUP_MAIN_PID" ;;
		esac
		return 0
	fi
	{
		echo "$(date '+%H:%M:%S') FAIL daemon did not become ready mode=$_mode target=$_WEBDAV_DAEMON_TARGET out=$_out"
		echo "state=$(cat "$_WEBDAV_DAEMON_STATE_FILE" 2>/dev/null)"
		echo "pid=$_pid alive=$(kill -0 "$_pid" 2>/dev/null && echo 1 || echo 0) starttime=$(_webdav_proc_starttime "$_pid") shell_pid=$$"
		if _webdav_daemon_load_state; then echo "state_valid=1 mode=$_WEBDAV_DAEMON_MODE target=$_WEBDAV_DAEMON_TARGET"; else echo "state_valid=0"; fi
		echo "cmdline=$(_webdav_proc_cmdline "$_pid")"
		echo "----- daemon stdout -----"
		cat "$_out" 2>/dev/null
	} >> "$_diag" 2>/dev/null
	_webdav_daemon_stop
	return 1
}

_webdav_daemon_ensure() {
	_WEBDAV_DAEMON_PID_FILE="$TMPDIR/.webdav_daemon.pid"
	_WEBDAV_DAEMON_STATE_FILE="$TMPDIR/.webdav_daemon.state"
	_WEBDAV_DAEMON_START_LOCK="${_WEBDAV_DAEMON_START_LOCK:-$TMPDIR/.webdav_daemon.start.lock}"
	if [[ ${remote_type:-} = webdav ]] && { _remote_stream_fatal_active || _remote_netwatch_changed_active; }; then
		_WEBDAV_DAEMON_READY=0
		rm -f "$(_webdav_daemon_fast_ready_cache_file)" 2>/dev/null
		_speed_debug_log "WEBDAV_DAEMON_ENSURE_SKIP reason=remote_fatal"
		return 1
	fi
	local _diag="${SPEED_DEBUG_RUN_DIR:-/data/speed_debug}/webdav_daemon_ensure.log" _have_lock=0
	if _webdav_daemon_fast_ready_ok; then
		_speed_debug_log "WEBDAV_DAEMON_FAST_READY_HIT ageMs=${_WEBDAV_DAEMON_FAST_READY_AGE_MS:-0} ttlMs=${_WEBDAV_DAEMON_FAST_READY_TTL_MS:-0} mode=$_WEBDAV_DAEMON_MODE target=$_WEBDAV_DAEMON_TARGET source=pid-starttime-cache-r286"
		return 0
	fi
	if _webdav_daemon_state_fast_ready_ok; then
		_speed_debug_log "WEBDAV_DAEMON_FAST_READY_HIT ageMs=state ttlMs=${SPEEDBACKUP_WEBDAV_DAEMON_READY_FAST_TTL_MS:-10000} mode=$_WEBDAV_DAEMON_MODE target=$_WEBDAV_DAEMON_TARGET source=strict-state-pid-starttime-r286"
		return 0
	fi
	if _webdav_daemon_cmdline_fast_ready_ok; then
		_speed_debug_log "WEBDAV_DAEMON_FAST_READY_HIT ageMs=cmdline ttlMs=${SPEEDBACKUP_WEBDAV_DAEMON_READY_FAST_TTL_MS:-10000} mode=$_WEBDAV_DAEMON_MODE target=$_WEBDAV_DAEMON_TARGET source=cmdline-pid-socket-r286"
		return 0
	fi
	_WEBDAV_DAEMON_READY=0

	if _webdav_daemon_transport_alive; then
		_WEBDAV_DAEMON_READY=1
		_webdav_daemon_fast_ready_mark
		echo "$(date '+%H:%M:%S') reuse pid=$(cat "$_WEBDAV_DAEMON_PID_FILE" 2>/dev/null) owner=$SPEEDBACKUP_MAIN_PID mode=$_WEBDAV_DAEMON_MODE target=$_WEBDAV_DAEMON_TARGET" >> "$_diag" 2>/dev/null
		return 0
	fi

	# 多個 command substitution / 並行遠端預掃可能同時第一次呼叫 _webdav_dex。
	# 467/r18: start-lock 競態處理改走共用 helper；WebDAV 自己的 transport/state/probe 仍保留。
	if _dex_daemon_acquire_start_lock "$_WEBDAV_DAEMON_START_LOCK" _webdav_daemon_transport_alive webdav 80; then
		if [[ $_DEX_DAEMON_LOCK_ACQUIRED != 1 ]]; then
			_WEBDAV_DAEMON_READY=1
			_webdav_daemon_fast_ready_mark
			echo "$(date '+%H:%M:%S') reuse_after_wait pid=$(cat "$_WEBDAV_DAEMON_PID_FILE" 2>/dev/null) mode=$_WEBDAV_DAEMON_MODE target=$_WEBDAV_DAEMON_TARGET" >> "$_diag" 2>/dev/null
			return 0
		fi
	else
		echo "$(date '+%H:%M:%S') FAIL cannot acquire daemon start lock" >> "$_diag" 2>/dev/null
		return 1
	fi

	# 拿到鎖後再次確認，避免上一個 starter 已經在鎖交接前完成。
	if _webdav_daemon_transport_alive; then
		_WEBDAV_DAEMON_READY=1
		_webdav_daemon_fast_ready_mark
		rmdir "$_WEBDAV_DAEMON_START_LOCK" 2>/dev/null
		echo "$(date '+%H:%M:%S') reuse_after_lock pid=$(cat "$_WEBDAV_DAEMON_PID_FILE" 2>/dev/null) mode=$_WEBDAV_DAEMON_MODE target=$_WEBDAV_DAEMON_TARGET" >> "$_diag" 2>/dev/null
		return 0
	fi

	_webdav_daemon_stop

	# 只有 unixsock v2 stream relay 可用時才嘗試 AF_UNIX；舊單行 unixsock 不相容。
	if _webdav_unixsock_relay_ready; then
		if _webdav_daemon_start_mode unix "$_diag"; then
			_webdav_daemon_fast_ready_mark
			rmdir "$_WEBDAV_DAEMON_START_LOCK" 2>/dev/null
			return 0
		fi
		echo "$(date '+%H:%M:%S') WARN unix daemon unavailable, fallback tcp" >> "$_diag" 2>/dev/null
	fi

	if _webdav_unixsock_relay_ready; then
		if _webdav_daemon_start_mode tcp "$_diag"; then
			_webdav_daemon_fast_ready_mark
			rmdir "$_WEBDAV_DAEMON_START_LOCK" 2>/dev/null
			return 0
		fi
	fi
	rmdir "$_WEBDAV_DAEMON_START_LOCK" 2>/dev/null
	echo "$(date '+%H:%M:%S') FAIL no usable unixsock v2 stream relay" >> "$_diag" 2>/dev/null
	return 1
}

_webdav_parse_daemon_status() {
	local _status="$1" _code_line _len_line
	[[ -s $_status ]] || return 1
	_code_line="$(sed -n '1p' "$_status" 2>/dev/null)"
	_len_line="$(sed -n '2p' "$_status" 2>/dev/null)"
	_WEBDAV_HTTP_CODE="${_code_line#HTTP }"
	case $_WEBDAV_HTTP_CODE in *[!0-9]*|'') _WEBDAV_HTTP_CODE=0 ;; esac
	case $_len_line in
	-1|-2) _WEBDAV_BODY_LENGTH="$_len_line" ;;
	*[!0-9]*|'') _WEBDAV_BODY_LENGTH=0 ;;
	*) _WEBDAV_BODY_LENGTH="$_len_line" ;;
	esac
	[[ $_code_line = "HTTP $_WEBDAV_HTTP_CODE" ]] || return 1
	_webdav_status_sidecar_store
}

_webdav_transport_relay() {
	local _status="$1"
	_webdav_unixsock_relay_ready || return 125
	case $_WEBDAV_DAEMON_MODE in
	unix) _event_unixsock_call relay-unix "$_WEBDAV_DAEMON_SOCKET" --header-file "$_status" ;;
	tcp) _event_unixsock_call relay-tcp 127.0.0.1 "$_WEBDAV_DAEMON_PORT" --header-file "$_status" ;;
	*) return 125 ;;
	esac
}

# $1=command $2=user $3=pass $4=url $5=extra(可省)；stdin 為 PUT body。
# unixsock v2 路徑的 response body 全程直通 stdout，只暫存兩行 response header。
_webdav_daemon_call() {
	local _cmd="$1" _user="$2" _pass="$3" _url="$4" _extra=""
	shift 4 2>/dev/null || true
	if [[ $# -gt 0 ]]; then _extra="$1"; shift; fi
	while [[ $# -gt 0 ]]; do _extra="${_extra}	$1"; shift; done

	# WEB-R4/334: 只允許 unixsock v2 framed relay；不再回退 nc-only 舊 framing。
	if ! _webdav_unixsock_relay_ready; then
		_WEBDAV_HTTP_CODE=0
		_WEBDAV_ERROR_ZH="WebDAV daemon relay 不可用：需要 unixsock v2 framed relay；不再回退 nc-only 舊 framing"
		return 125
	fi

	case $_cmd in
	putstdinmanagedrel|putmanagedrel|managedbatchputrelwithparents|managedlistclassifyrel|managedproberel|compatProbeRel|ensurebaserel|ensuredirrel|ensuredirsbatchrel|preparedirsplanrel|optionspreflightrel|putstdinchunkedrel|putbatchrel|getstdoutrel|mkdirsrel|moverel|copyrel|statrel|listrel|classifylistrel|deleterel|putrel|getrel|mkdirrel|propfindrel|optionsrel) ;;
	*)
		_WEBDAV_HTTP_CODE=0
		_WEBDAV_ERROR_ZH="WebDAV rel-only 模式拒絕舊命令：$_cmd"
		return 125
		;;
	esac

	local _body_len=0 _status _relay_err _relay_rc _try=0 _max_try=2 _diag
	_webdav_status_sidecar_reset
	case $_cmd in putstdinmanagedrel|putstdinchunkedrel|putbatchrel|managedbatchputrelwithparents|ensuredirsbatchrel|preparedirsplanrel) _body_len=-1 ;; esac
	case $_cmd in putstdinmanagedrel|putstdinchunkedrel|putbatchrel|managedbatchputrelwithparents|ensuredirsbatchrel|preparedirsplanrel|getstdoutrel) _max_try=1 ;; esac
	_diag="${SPEED_DEBUG_RUN_DIR:-/data/speed_debug}/webdav_daemon_call.log"
	while [[ $_try -lt $_max_try ]]; do
		_status="$(_webdav_tmp_path webdav_daemon_status)"
		_relay_err="$(_webdav_tmp_path webdav_relay_err)"
		rm -f "$_status" "$_relay_err" 2>/dev/null
		{
			printf '%s\n%s\n%s\n%s\n%s\n%s\n' "$_cmd" "$_user" "$_pass" "$_url" "$_extra" "$_body_len"
			if [[ $_body_len = -1 ]]; then cat; fi
		} | _webdav_transport_relay "$_status" 2>"$_relay_err"
		_relay_rc=$?
		if [[ $_relay_rc = 0 ]] && _webdav_parse_daemon_status "$_status"; then
			_webdav_set_error_zh "$_WEBDAV_HTTP_CODE" ""
			case $_WEBDAV_HTTP_CODE in 2[0-9][0-9]) _webdav_daemon_fast_ready_mark ;; esac
			echo "$(date '+%H:%M:%S') cmd=$_cmd mode=$_WEBDAV_DAEMON_MODE relay_rc=$_relay_rc http=$_WEBDAV_HTTP_CODE body_len=${_WEBDAV_BODY_LENGTH:-0} try=$_try" >> "$_diag" 2>/dev/null
			rm -f "$_status" "$_relay_err" 2>/dev/null
			case $_WEBDAV_HTTP_CODE in 2[0-9][0-9]) return 0 ;; *) return 1 ;; esac
		fi
		echo "$(date '+%H:%M:%S') FAIL cmd=$_cmd mode=$_WEBDAV_DAEMON_MODE relay_rc=$_relay_rc status_size=$(_local_file_size_debug "$_status") try=$_try" >> "$_diag" 2>/dev/null
		if [[ -s $_relay_err ]]; then
			case $_cmd in
			putstdinmanagedrel|putstdinchunkedrel|putbatchrel|managedbatchputrelwithparents|ensuredirsbatchrel|preparedirsplanrel|getstdoutrel)
				# r165: stream relay 的低層 stderr（例如 unixsock: request copy failed）只是 WebDAV daemon/remote 已斷線的表層症狀。
				# 失敗由 REMOTE_STREAM_FATAL / WEBDAV_ERROR_ZH 結構化呈現；不要污染全域 stderr.log。
				remote_raw_cat "webdav_daemon_call_detail.log" "$_relay_err" "===== WEBDAV_RELAY_STREAM_ABORT cmd=$_cmd relay_rc=$_relay_rc try=$_try ====="
				;;
			*)
				if [[ ${remote_type:-} = webdav ]] && { _remote_netwatch_changed_active || _remote_stream_fatal_active; }; then
					remote_raw_cat "webdav_daemon_call_detail.log" "$_relay_err" "===== WEBDAV_RELAY_EXPECTED_ABORT cmd=$_cmd relay_rc=$_relay_rc try=$_try ====="
				else
					cat "$_relay_err" >> ${SPEED_DEBUG_ERR_LOG:-/dev/null} 2>/dev/null
				fi
				;;
			esac
		fi
		rm -f "$_status" "$_relay_err" "$(_webdav_daemon_fast_ready_cache_file)" 2>/dev/null
		_WEBDAV_DAEMON_READY=0
		if [[ ${remote_type:-} = webdav ]] && _remote_netwatch_changed_active; then
			_remote_netwatch_mark_remote_fatal "webdav_daemon_call_relay_fail" "$_cmd" >/dev/null 2>&1 || true
			break
		fi
		if [[ ${remote_type:-} = webdav ]] && _remote_stream_fatal_active; then
			break
		fi
		_webdav_daemon_stop
		_try=$((_try + 1))
		[[ $_try -lt $_max_try ]] && _webdav_daemon_ensure || break
	done
	_WEBDAV_HTTP_CODE=0
	_WEBDAV_ERROR_ZH="WebDAV daemon 沒有有效回應：AF_UNIX/TCP framed relay 中斷、daemon 已退出或本次傳輸被下游提前關閉"
	return 1
}
# 統一透過 dex WebDavUtil daemon 呼叫。daemon/relay 不可用時直接失敗，不再回退單次 app_process。
# 大型 getstdoutrel 只走 daemon stream relay，不使用 command substitution。
_webdav_dex() {
	_WEBDAV_HTTP_CODE=0
	_WEBDAV_BODY_LENGTH=0
	_WEBDAV_ERROR_ZH=""
	if [[ ${remote_type:-} = webdav ]] && _remote_netwatch_changed_active; then
		_remote_netwatch_mark_remote_fatal "webdav_dex_enter" "${1:-webdav}" >/dev/null 2>&1 || true
		_WEBDAV_HTTP_CODE=0
		_WEBDAV_ERROR_ZH="WebDAV 已因 LAN 路由／位址變更中止；本版不再等待或重試，請確認連線後重新執行"
		return 126
	fi
	if [[ ${remote_type:-} = webdav ]] && _remote_stream_fatal_active; then
		_WEBDAV_HTTP_CODE=0
		_WEBDAV_ERROR_ZH="WebDAV 已因遠端 fatal 中止"
		return 126
	fi
	if ! _webdav_daemon_ensure; then
		_WEBDAV_HTTP_CODE=0
		_WEBDAV_ERROR_ZH="WebDAV daemon 不可用：daemon 啟動失敗、unixsock v2 framed relay 不可用或 endpoint 無回應；熱路徑不再回退單次 app_process"
		_speed_debug_log "WEBDAV_DAEMON_REQUIRED_NO_SPAWN command=$1"
		return 1
	fi
	_webdav_daemon_call "$@"
	local _daemon_rc=$?
	if [[ $_daemon_rc = 125 ]]; then
		_WEBDAV_HTTP_CODE=0
		_WEBDAV_ERROR_ZH="WebDAV daemon relay 不可用：本功能需要 daemon stream relay；不再回退單次 app_process"
		_speed_debug_log "WEBDAV_DAEMON_RELAY_REQUIRED_NO_SPAWN command=$1 mode=$_WEBDAV_DAEMON_MODE"
		return 1
	fi
	return "$_daemon_rc"
}

# 本輪 WebDAV 目錄建立快取：避免同一輪反覆對同一路徑 MKCOL/EXISTS。
# 311: cache 必須是本輪私有；舊版固定 $TMPDIR/.webdav_mkcol_cache 會跨 run 殘留，
# 遠端被清空後仍誤判 MKCOL_CACHE_HIT，導致新備份目錄未建立。
_WEBDAV_MKCOL_CACHE_FILE="${_WEBDAV_MKCOL_CACHE_FILE:-$TMPDIR/.webdav_mkcol_cache_$$}"
_webdav_mkcol_cache_prune_stale() {
	local _f
	# 312: 清掉舊版固定 cache 與前次異常中斷留下的 per-run cache；本輪 cache 只做優化，刪舊檔不影響正確性。
	for _f in "$TMPDIR/.webdav_mkcol_cache" "$TMPDIR"/.webdav_mkcol_cache_[0-9]*; do
		[[ -e $_f ]] || continue
		[[ $_f = "$_WEBDAV_MKCOL_CACHE_FILE" ]] && continue
		rm -f "$_f" 2>/dev/null
	done
}
_webdav_mkcol_cache_prune_stale
_webdav_mkcol_cache_clear_current() {
	# 320: 本輪 MKCOL cache 只用於同一輪去重，正常/異常退出後都不應殘留在 TMPDIR。
	[[ -n ${_WEBDAV_MKCOL_CACHE_FILE:-} ]] && rm -f "$_WEBDAV_MKCOL_CACHE_FILE" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
}
_webdav_mkcol_cache_has() {
	local _key="$1	$2"
	[[ -s $_WEBDAV_MKCOL_CACHE_FILE ]] && grep -Fqx "$_key" "$_WEBDAV_MKCOL_CACHE_FILE" 2>/dev/null
}
_webdav_mkcol_cache_add() {
	local _key="$1	$2"
	mkdir -p "${_WEBDAV_MKCOL_CACHE_FILE%/*}" 2>/dev/null || true
	printf '%s\n' "$_key" >> "$_WEBDAV_MKCOL_CACHE_FILE" 2>/dev/null
}

_webdav_mkdirrel_cached() {
	local _user="$1" _pass="$2" _base="$3" _rel="$4" _err="$5"
	local _out _rc _http _state
	[[ -n $_base && -n $_rel ]] || return 1
	if _webdav_mkcol_cache_has "$_base" "$_rel"; then
		_WEBDAV_HTTP_CODE=200
		_speed_debug_log "WEBDAV_ENSUREDIR_CACHE_HIT rel=$_rel"
		return 0
	fi
	[[ -n $_err ]] || _err="$TMPDIR/.webdav_ensuredir_err_$$"
	_webdav_status_sidecar_reset
	_out="$(_webdav_dex ensuredirrel "$_user" "$_pass" "$_base" "$_rel" 2>"$_err")"
	_rc=$?
	_webdav_status_sidecar_load || true
	_http="${_WEBDAV_HTTP_CODE:-0}"
	_state="$(printf '%s\n' "$_out" | awk -F= '$1=="state"{print substr($0,index($0,"=")+1); exit}')"
	remote_raw_log "remote_webdav_preflight.log" "ENSURE_DIR_DEX rel=$_rel rc=$_rc http=$_http state=$_state base=$_base"
	[[ -n $_out ]] && printf '%s\n' "$_out" >> "${SPEED_DEBUG_RUN_DIR:-/data/speed_debug}/remote_webdav_preflight.log" 2>/dev/null
	case $_http in
	2*)
		_webdav_mkcol_cache_add "$_base" "$_rel"
		return 0
		;;
	esac
	return "$_rc"
}

# r344: WebDAV 目錄批量預建立後由 tools 將 parent mode 傳給 Dex；Dex WebDavUtil 決定 skip/ensure parent mkdir。
_webdav_prepare_dirs_planrel() {
	local _base="$1" _root_rel="$2" _manifest="$3" _out="$4" _err="$5" _progress="$6"
	[[ -n $_base && -n $_root_rel && -s $_manifest ]] || return 1
	[[ -n $_out ]] || _out="$TMPDIR/.webdav_prepare_dirs_plan_out_$$"
	[[ -n $_err ]] || _err="$TMPDIR/.webdav_prepare_dirs_plan_err_$$"
	[[ -n $_progress ]] || _progress=""
	_webdav_status_sidecar_reset
	_webdav_dex preparedirsplanrel "$remote_user" "$remote_pass" "$_base" "$_root_rel" "create" "$_progress" < "$_manifest" > "$_out" 2>"$_err"
	local _rc=$?
	_webdav_status_sidecar_load || true
	remote_raw_log "remote_webdav_preflight.log" "PREPARE_DIRS_PLAN_DEX rc=$_rc http=${_WEBDAV_HTTP_CODE:-0} root=$_root_rel manifest=$_manifest base=$_base progress=$_progress"
	remote_raw_cat "remote_webdav_preflight.log" "$_out" "===== WEBDAV_PREPARE_DIRS_PLAN stdout rc=$_rc http=${_WEBDAV_HTTP_CODE:-0} ====="
	remote_raw_cat "remote_webdav_preflight.log" "$_err" "===== WEBDAV_PREPARE_DIRS_PLAN stderr rc=$_rc http=${_WEBDAV_HTTP_CODE:-0} ====="
	return "$_rc"
}

_webdav_stream_prepare_app_dirs_from_txt() {
	[[ ${remote_type:-} = webdav && ${remote_stream:-0} = 1 ]] || return 0
	[[ -n ${txt:-} ]] || return 0
	# r363: App directory exists/create plan is Dex-side; progress uses the same single-line inline bar as other prescan stages.
	# tools only supplies desired app-dir rels and seeds mkdir cache from Dex TSV facts.
	local _manifest="$TMPDIR/.webdav_stream_app_dirs_$$_$RANDOM.lst" _line _name _pkg _subdir _rel _base _out _err _rc _status _rel_out _existing=0 _created=0 _ok=0 _failed=0 _summary _total=0
	local _progress _done _pid _last_done=-1 _done_n _total_n _existing_n _created_n _failed_n _pstatus _prel _http _wait_rc
	_subdir="${_BACKUP_DIRNAME_CACHED:-$(get_backup_dirname)}"
	_base="${remote_url%/}"
	: > "$_manifest"
	while IFS= read -r _line; do
		case $_line in ''|\#*|＃*) continue ;; esac
		_name="${_line%% *}"
		_pkg="${_line#* }"; _pkg="${_pkg%% *}"
		[[ -z $_name || -z $_pkg || $_pkg = "$_line" ]] && continue
		case $_name in
		\!*) _name="${_name#!}" ;;
		！*) _name="${_name#！}" ;;
		esac
		_name="$(_backup_path_safe_name "$_name" "$_pkg")"
		[[ -n $_name ]] || continue
		_rel="$_subdir/$_name"
		printf '%s\n' "$_rel" >> "$_manifest"
	done <<EOF_WEBDAV_STREAM_APP_DIRS
$txt
EOF_WEBDAV_STREAM_APP_DIRS
	_total="$(awk 'NF{n++} END{print n+0}' "$_manifest" 2>/dev/null)"
	case $_total in ''|*[!0-9]*) _total=0 ;; esac
	[[ $_total -gt 0 ]] || { _speed_debug_log "WEBDAV_STREAM_APP_DIR_PRECREATE_SKIP reason=empty mode=r370"; rm -f "$_manifest" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}; return 0; }
	_out="$TMPDIR/.webdav_prepare_app_dirs_out_$$_$RANDOM.tsv"
	_err="$TMPDIR/.webdav_prepare_app_dirs_err_$$_$RANDOM.log"
	_progress="$TMPDIR/.webdav_prepare_app_dirs_progress_$$_$RANDOM.tsv"
	_done="$TMPDIR/.webdav_prepare_app_dirs_done_$$_$RANDOM.tsv"
	rm -f "$_out" "$_err" "$_progress" "$_done" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	echoRgb "WebDAV 預建立本輪 App 遠端目錄 $_total 個" "3"
	_speedbackup_progress_step 0 "$_total" "WebDAV 預建 App 遠端目錄" "webdav_prepare_app_dirs" "107"
	_speed_debug_log "WEBDAV_STREAM_APP_DIR_PRECREATE_BEGIN policy=dex-prepare-dirs-plan-inline total=$_total root=$_subdir mode=r370"
	(
		_webdav_prepare_dirs_planrel "$_base" "$_subdir" "$_manifest" "$_out" "$_err" "$_progress"
		_rc=$?
		printf '%s\t%s\n' "$_rc" "${_WEBDAV_HTTP_CODE:-0}" > "$_done" 2>/dev/null
		exit "$_rc"
	) &
	_pid=$!
	while [[ ! -s $_done ]]; do
		if [[ -s $_progress ]]; then
			IFS=$'\t' read -r _done_n _total_n _existing_n _created_n _failed_n _pstatus _prel < "$_progress" 2>/dev/null || true
			case $_done_n in ''|*[!0-9]*) _done_n=0 ;; esac
			case $_total_n in ''|*[!0-9]*|0) _total_n="$_total" ;; esac
			if [[ $_done_n -ne $_last_done ]]; then
				_last_done="$_done_n"
				case $_pstatus in BEGIN|EMPTY) _prel="" ;; esac
				_speedbackup_progress_step "$_done_n" "$_total_n" "WebDAV 預建 App 遠端目錄" "webdav_prepare_app_dirs" "107"
				_speed_debug_log "WEBDAV_STREAM_APP_DIR_PRECREATE_PROGRESS current=$_done_n total=$_total_n existing=${_existing_n:-0} created=${_created_n:-0} failed=${_failed_n:-0} status=${_pstatus:-} rel=$(_speed_debug_kv "$(_speed_debug_safe "$_prel")") mode=r370"
			fi
		fi
		kill -0 "$_pid" 2>/dev/null || break
		sleep 1
	done
	wait "$_pid" 2>/dev/null
	_wait_rc=$?
	if [[ -s $_done ]]; then
		IFS=$'\t' read -r _rc _http < "$_done" 2>/dev/null || true
	else
		_rc="$_wait_rc"; _http="${_WEBDAV_HTTP_CODE:-0}"
	fi
	case $_rc in ''|*[!0-9]*) _rc=1 ;; esac
	case $_http in ''|*[!0-9]*) _http=0 ;; esac
	_WEBDAV_HTTP_CODE="$_http"
	if [[ -s $_progress ]]; then
		IFS=$'\t' read -r _done_n _total_n _existing_n _created_n _failed_n _pstatus _prel < "$_progress" 2>/dev/null || true
		case $_done_n in ''|*[!0-9]*) _done_n=0 ;; esac
		case $_total_n in ''|*[!0-9]*|0) _total_n="$_total" ;; esac
		if [[ $_done_n -gt $_last_done ]]; then
			_speedbackup_progress_step "$_done_n" "$_total_n" "WebDAV 預建 App 遠端目錄" "webdav_prepare_app_dirs" "107"
			_last_done="$_done_n"
		fi
	fi
	if [[ $_rc = 0 ]]; then
		while IFS= read -r _line; do
			case $_line in
			EXISTING$'\t'*|CREATED$'\t'*|OK$'\t'*)
				_status="${_line%%$'\t'*}"
				_rel_out="$(printf '%s\n' "$_line" | awk -F '\t' '{print $2; exit}')"
				[[ -n $_rel_out ]] && _webdav_mkcol_cache_add "$_base" "$_rel_out"
				_ok=$((_ok + 1))
				case $_status in EXISTING) _existing=$((_existing + 1)) ;; CREATED|OK) _created=$((_created + 1)) ;; esac
				;;
			FAIL$'\t'*|MISSING$'\t'*) _failed=$((_failed + 1)) ;;
			SUMMARY$'\t'*) _summary="$_line" ;;
			esac
		done < "$_out"
		case $_last_done in ''|*[!0-9]*|-) _last_done=0 ;; esac
		if [[ $_last_done -lt $_total ]]; then
			_speedbackup_progress_step "$_total" "$_total" "WebDAV 預建 App 遠端目錄" "webdav_prepare_app_dirs" "107"
		fi
		_speed_debug_log "WEBDAV_STREAM_APP_DIR_PRECREATE_OK policy=dex-prepare-dirs-plan-inline total=$_total existing=$_existing created=$_created ok=$_ok failed=$_failed http=${_WEBDAV_HTTP_CODE:-0} summary=$(_speed_debug_kv "$(_speed_debug_safe "$_summary")") mode=r370"
		# r370: Do not add the r368 visible barrier to the normal path. If the WebDAV server reports all dirs as EXISTING
		# right after the user deleted them outside WebDAV, this is a server/VFS directory-cache view, not a tools TMPDIR cache.
		if [[ $_existing -gt 0 && $_created = 0 ]]; then
			_speed_debug_log "WEBDAV_SERVER_DIR_CACHE_NOTE root=$_subdir total=$_total existing=$_existing created=$_created source=dex-propfind hint=rclone_serve_webdav_dir_cache_if_deleted_outside_webdav recommended=server_dir_cache_time_or_vfs_forget mode=r370"
		fi
		rm -f "$_manifest" "$_out" "$_err" "$_progress" "$_done" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
		[[ $_failed = 0 ]]
		return $?
	fi
	_speed_debug_log "WEBDAV_STREAM_APP_DIR_PRECREATE_FAIL policy=dex-prepare-dirs-plan-inline rc=$_rc http=${_WEBDAV_HTTP_CODE:-0} total=$_total action=fatal-no-shell-dir-plan-fallback mode=r370"
	rm -f "$_manifest" "$_out" "$_err" "$_progress" "$_done" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	return "$_rc"
}

_webdav_base_path_preflight_autocreate() {
	# 460: URL split, STAT, parent-chain MKCOL and final verification live in WebDavUtil ensurebaserel.
	local _base="$1" _mode="${2:-control}" _err _out _rc _http _state _rel
	[[ -n $_base ]] || return 1
	_err="$TMPDIR/.webdav_base_path_err_$$"
	_webdav_status_sidecar_reset
	_out="$(_webdav_dex ensurebaserel "$remote_user" "$remote_pass" "$_base" 2>"$_err")"
	_rc=$?
	_webdav_status_sidecar_load || true
	_http="${_WEBDAV_HTTP_CODE:-0}"
	_state="$(printf '%s\n' "$_out" | awk -F= '$1=="state"{print substr($0,index($0,"=")+1); exit}')"
	_rel="$(printf '%s\n' "$_out" | awk -F= '$1=="rel"{print substr($0,index($0,"=")+1); exit}')"
	remote_raw_log "remote_webdav_preflight.log" "BASE_PATH_DEX mode=$_mode rc=$_rc http=$_http state=$_state rel=$_rel configured=$_base"
	[[ -n $_out ]] && printf '%s\n' "$_out" >> "${SPEED_DEBUG_RUN_DIR:-/data/speed_debug}/remote_webdav_preflight.log" 2>/dev/null
	remote_raw_cat "remote_webdav_preflight.log" "$_err" "[WEBDAV_BASE_PATH_DEX stderr mode=$_mode rel=$_rel]"
	rm -f "$_err" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	case $_http in
	2*)
		case $_state in created) echoRgb "WebDAV 遠端資料夾已建立: /$_rel" "1" ;; esac
		return 0
		;;
	esac
	_webdav_set_error_zh "$_http" ""
	_WEBDAV_ERROR_ZH="WebDAV URL 指向的遠端資料夾不可用：$_base；${_WEBDAV_ERROR_ZH:-HTTP $_http}"
	return 1
}


_webdav_options_preflight() {
	local _base="$1" _rel="${2:-}" _mode="${3:-control}" _err _out _rc _http _state _missing
	[[ -n $_base ]] || return 1
	_err="$TMPDIR/.webdav_options_err_$$"
	_webdav_status_sidecar_reset
	_out="$(_webdav_dex optionspreflightrel "$remote_user" "$remote_pass" "$_base" "${_rel:-.}" "$_mode" 2>"$_err")"
	_rc=$?
	_webdav_status_sidecar_load || true
	_http="${_WEBDAV_HTTP_CODE:-0}"
	_state="$(printf '%s\n' "$_out" | awk -F= '$1=="state"{print substr($0,index($0,"=")+1); exit}')"
	_missing="$(printf '%s\n' "$_out" | awk -F= '$1=="missing"{print substr($0,index($0,"=")+1); exit}')"
	remote_raw_log "remote_webdav_preflight.log" "OPTIONS_DEX mode=$_mode rc=$_rc http=$_http state=$_state missing=$_missing base=$_base rel=$_rel"
	[[ -n $_out ]] && printf '%s\n' "$_out" >> "${SPEED_DEBUG_RUN_DIR:-/data/speed_debug}/remote_webdav_preflight.log" 2>/dev/null
	remote_raw_cat "remote_webdav_preflight.log" "$_err" "[WEBDAV_OPTIONS_DEX stderr mode=$_mode rel=$_rel]"
	rm -f "$_err" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	case $_http in 2*) return 0 ;; *) return 1 ;; esac
}



_webdav_putrel_atomic_file() {
	local _base="$1" _rel="$2" _file="$3" _tag="${4:-webdav_put}" _out="$5"
	local _err _rc _http
	[[ -n $_base && -n $_rel && -f $_file ]] || return 1
	_err="$TMPDIR/.webdav_put_managed_${_tag}_$$"
	_webdav_dex putmanagedrel "$remote_user" "$remote_pass" "$_base" "$_rel" "$_file" auto > "$_err" 2>&1
	_rc=$?
	_http="${_WEBDAV_HTTP_CODE:-0}"
	remote_raw_log "remote_webdav_upload_raw.log" "PUT_MANAGED tag=$_tag rc=$_rc http=$_http rel=$_rel file=$_file"
	remote_raw_cat "remote_webdav_upload_${_tag}.log" "$_err" "===== WEBDAV_PUT_MANAGED $_tag rel=$_rel rc=$_rc http=$_http ====="
	[[ -n $_out ]] && cat "$_err" > "$_out" 2>/dev/null
	rm -f "$_err" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	return "$_rc"
}

_webdav_atomic_capability_probe() {
	local _base="$1" _relbase="${2:-}" _err _out _rc _http
	[[ -n $_base ]] || return 1
	_err="$TMPDIR/.webdav_managed_probe_err_$$"
	_out="$TMPDIR/.webdav_managed_probe_out_$$"
	# 442: managed probe must mirror the real stream upload location.  Recent
	# WebDAV managed refactor probed by PUT-ing a test file directly under
	# remote_url; some Android/NAS servers return 404 there even though the real
	# backup path under Backup_zstd_X works after MKCOL.  The caller now creates
	# the backup subdir first and passes it here as relBase.
	_webdav_dex managedproberel "$remote_user" "$remote_pass" "$_base" "$_relbase" >"$_out" 2>"$_err"
	_rc=$?
	_http="${_WEBDAV_HTTP_CODE:-0}"
	remote_raw_log "remote_webdav_stream_probe_raw.log" "MANAGED_PROBE rc=$_rc http=$_http base=$_base relbase=$_relbase"
	remote_raw_cat "remote_webdav_stream_probe_raw.log" "$_out" "[managed probe detail http=$_http]"
	remote_raw_cat "remote_webdav_stream_probe_raw.log" "$_err" "[managed probe stderr http=$_http]"
	rm -f "$_err" "$_out" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	return "$_rc"
}

# WebDAV 小檔 batch PUT：manifest 每行 rel<TAB>localFile，由 Dex daemon 同一 request 順序 PUT。
_webdav_putbatchrel() {
	local _base="$1" _base_rel="$2" _manifest="$3" _out="$4"
	[[ -s $_manifest ]] || return 1
	_webdav_dex putbatchrel "$remote_user" "$remote_pass" "$_base" "$_base_rel" < "$_manifest" > "$_out"
}
# ===== 遠端、本地共用與壓縮 =====
remote_type_valid() {
	case "${remote_type:-}" in webdav|smb) return 0 ;; *) return 1 ;; esac
}
remote_enabled() {
	remote_type_valid && [[ -n ${remote_url:-} ]]
}
stream_enabled() {
	remote_enabled && [[ ${remote_stream:-0} = 1 ]]
}
remote_ui_allowed() {
	remote_enabled
}
case $Shell_LANG in
1) SCRIPT_LANG="CN" ;;
0) SCRIPT_LANG="TW" ;;
*)
	_l="$(settings get system system_locales 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} | head -1)"
	[[ -z $_l || $_l = null ]] && _l="$(getprop persist.sys.locale)"
	case $_l in
	zh-Hant*|zh_Hant*|zh-TW*|zh-HK*|zh-MO*) SCRIPT_LANG="TW" ;;
	zh-Hans*|zh_Hans*|zh-CN*|zh-SG*|zh*)    SCRIPT_LANG="CN" ;;
	esac
	;;
esac
# ======================================================
# 基礎工具函數
# ======================================================
# r458: 單行進度列狀態。r454 的 label compact 已回退；r456 的黏行修正保留，但不再把 redraw 寫入 stderr.log。
_SPEEDBACKUP_PROGRESS_LINE_ACTIVE=0
_speedbackup_progress_term_printf() {
	# 優先寫控制終端，避免腳本 stderr 被 speed_debug 收集時污染 stderr.log。
	# 無互動終端時不輸出 ANSI redraw，只保留 main.log marker。
	[[ -c /dev/tty ]] || return 1
	printf "$@" 2>/dev/null > /dev/tty
}
_speedbackup_progress_line_clear_before_output() {
	case "${_SPEEDBACKUP_PROGRESS_LINE_ACTIVE:-0}" in
		1)
			# 只清掉尚未完成的 transient progress line，避免下一條普通訊息接在同一列後面；不得寫入 stderr.log。
			_speedbackup_progress_term_printf '\r\033[K' || true
			_SPEEDBACKUP_PROGRESS_LINE_ACTIVE=0
			;;
	esac
}

# 帶色彩輸出, 用法: echoRgb "訊息" [色碼]
# 色碼:
#   0 = 紅色 (197)    - 錯誤/警告
#   1 = 亮綠 (121)    - 成功
#   2 = rgb_c (213)   - 強調/變數值 (粉紅, 預設)
#   3 = rgb_b (51)    - 提示/進度 (亮青, 預設)
#   其他/省略 = rgb_a (220) - 一般資訊 (亮黃, 預設)
# rgb_a/b/c 可在 conf 自訂, 全部都是 256 色 ANSI 編號
echoRgb() {
	local color
	_speedbackup_progress_line_clear_before_output
	case $2 in
	0) color=197 ;;
	1) color=121 ;;
	2) color=$rgb_c ;;
	3) color=$rgb_b ;;
	*) color=$rgb_a ;;
	esac
	echo -e "\e[38;5;${color}m -$1\e[0m"
	_speed_debug_log "MSG: $1"
}

# r148: 對可能超過 1 秒的準備/後處理階段給使用者明確提示，避免誤認為卡住。
_speedbackup_progress_hint() {
	local _msg="$1" _tag="${2:-progress_hint}"
	[[ -n $_msg ]] || return 0
	echoRgb "$_msg" "3"
	_speed_debug_log "PROGRESS_HINT tag=$_tag msg=$_msg"
}

_restore_post_state_guard_enabled() {
	case "${SPEEDBACKUP_RESTORE_POST_STATE_GUARD:-1}" in
		0|false|FALSE|no|NO|off|OFF|disable|DISABLE|none) return 1 ;;
	esac
	return 0
}

_restore_post_state_guard_defer_pkg() {
	local _pkg="$1" _kind="${2:-guard}"
	[[ -n $_pkg ]] || return 1
	_restore_post_state_guard_enabled || return 1
	# r243: r240 後普通 App 預設走 instant_kill，不再延長守護到 AppState 批次後。
	# 只有固定 hard-freeze / 顯式 high-risk App 才保留 post-AppState guard。
	if command -v _process_observer_high_risk_pkg >/dev/null 2>&1 && _process_observer_high_risk_pkg "$_pkg"; then
		_speed_debug_log "RESTORE_POST_STATE_GUARD_DEFER pkg=$_pkg kind=$_kind reason=hard_freeze_or_high_risk"
		return 0
	fi
	# r328: restore guard follows the same cgroup fast-settle/freeze candidate list as backup.
	# This includes default HOME launcher and explicitly configured fast-settle packages; keep them guarded
	# until AppState/SSAID batch is done, instead of releasing an instant-kill style guard too early.
	if command -v _speedbackup_cgroup_fast_settle_pkg >/dev/null 2>&1 && _speedbackup_cgroup_fast_settle_pkg "$_pkg"; then
		_speed_debug_log "RESTORE_POST_STATE_GUARD_DEFER pkg=$_pkg kind=$_kind reason=restore_freeze_list_parity mode=r334"
		return 0
	fi
	_speed_debug_log "RESTORE_POST_STATE_GUARD_NO_DEFER pkg=$_pkg kind=$_kind reason=instant_kill_default"
	return 1
}
[[ $remote_type = webdav ]] && echoRgb "WebDAV: dex WebDavUtil 原生/atomic模式" "3"

# ======================================================
# SMB client 網路 helper
# ======================================================
_get_local_ipv4() {
	local ipaddr

	ipaddr="$(ip route get 1.1.1.1 2>/dev/null | awk '{
		for (i = 1; i <= NF; i++) {
			if ($i == "src") {
				print $(i + 1)
				exit
			}
		}
	}')"

	if [[ -n "$ipaddr" ]]; then
		echo "$ipaddr"
		return 0
	fi

	ip -4 addr show wlan0 2>/dev/null | awk '/inet /{
		sub(/\/.*/, "", $2)
		print $2
		exit
	}'
}

# Android 上 smbclient 可能無法自行枚舉網卡；統一產生 client 端 smb.conf。
# client 端不綁死介面，避免遠端連線走錯網卡。
_smb_client_conf() {
	local run_dir conf_file ifaces ipaddr
	run_dir="/data/backup_tools/smbclient_runtime"
	conf_file="$run_dir/smb.conf"
	mkdir -p "$run_dir" 2>/dev/null || { echo /dev/null; return 1; }

	ifaces="$(ip -o -4 addr show scope global 2>/dev/null | awk '{print $4}' | tr '\n' ' ' | sed 's/[[:space:]]*$//')"
	if [[ -z "$ifaces" ]]; then
		ipaddr="$(_get_local_ipv4)"
		[[ -n "$ipaddr" ]] && ifaces="$ipaddr/24"
	fi
	if [[ -z "$ifaces" ]]; then
		ifaces="127.0.0.1/8"
	else
		ifaces="127.0.0.1/8 $ifaces"
	fi

	cat > "$conf_file" <<EOF
[global]
client min protocol = SMB2_02
client max protocol = SMB3
interfaces = $ifaces
bind interfaces only = no
disable netbios = yes
name resolve order = host
EOF
	chmod 600 "$conf_file" 2>/dev/null
	echo "$conf_file"
}

# 430: JSON domain helper，所有非 app_details 熱路徑 JSON 也從這裡進出。
# 原則：仍使用原生 jq；這裡只是集中 shell API，避免 jq 條件散落。
_json_parse_ok() {
	local _file="$1"
	[[ -s $_file ]] || return 1
	jq -e . "$_file" >/dev/null 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
}
_json_parse_quiet_ok() {
	local _file="$1"
	[[ -s $_file ]] || return 1
	jq -e . "$_file" >/dev/null 2>&1
}
_json_string_get() {
	local _json="$1" _filter="$2"
	[[ -n $_json && -n $_filter ]] || { printf '\n'; return 1; }
	# GitHub/API/CDN failures may return HTML/plain text; do not pollute stderr.log with jq parse errors.
	printf '%s\n' "$_json" | jq -r "$_filter" 2>/dev/null || { printf '\n'; return 1; }
}
_release_json_tag() {
	_json_string_get "$1" '.tag_name // ""'
}
_release_json_asset_urls() {
	_json_string_get "$1" '.assets[]?.browser_download_url // empty'
}
_release_json_body() {
	_json_string_get "$1" '.body // ""'
}
_speedbackup_update_local_tag() {
	# r40: online updater compares by the installed script build (backup_version) first.
	# speedbackup_release_tag is only a fallback for very old/source packages that do not carry backup_version.
	# This keeps same-tag releases quiet after publishing, while a manually lowered backup_version still becomes updateable.
	local _rel="${speedbackup_release_tag:-}" _bv="${backup_version:-}" _rel_d _bv_d
	_bv_d="$(_speedbackup_version_digits "$_bv")"
	_rel_d="$(_speedbackup_version_digits "$_rel")"
	if [[ -n $_bv_d ]]; then
		printf '%s\n' "$_bv"
	elif [[ -n $_rel_d ]]; then
		printf '%s\n' "$_rel"
	else
		printf '%s\n' "0"
	fi
}
_speedbackup_update_debug_log() {
	[[ -n ${SPEED_DEBUG_RUN_DIR:-} && -d ${SPEED_DEBUG_RUN_DIR:-} ]] || return 0
	printf '%s\n' "$*" >> "$SPEED_DEBUG_RUN_DIR/update_check.log" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} || true
	_speed_debug_log "UPDATE_CHECK $*"
}
_speedbackup_update_config_rescue() {
	# 如果 conf source 失敗或被污染導致 update/cdn 變數沒載入，直接從 conf 讀一次，避免誤跳音量鍵提示。
	local _u _c
	[[ -n ${conf_path:-} && -f $conf_path ]] || return 0
	if [[ -z ${update:-} ]]; then
		_u="$(awk -F= '/^[[:space:]]*update[[:space:]]*=/ {gsub(/^[[:space:]]+|[[:space:]]+$/, "", $2); gsub(/^"|"$/, "", $2); print $2; exit}' "$conf_path" 2>/dev/null)"
		if [[ -n $_u ]]; then
			update="$_u"
			_speedbackup_update_debug_log "CONFIG_RESCUE update=$_u source=$conf_path"
		fi
	fi
	if [[ -z ${cdn:-} ]]; then
		_c="$(awk -F= '/^[[:space:]]*cdn[[:space:]]*=/ {gsub(/^[[:space:]]+|[[:space:]]+$/, "", $2); gsub(/^"|"$/, "", $2); print $2; exit}' "$conf_path" 2>/dev/null)"
		[[ -n $_c ]] && cdn="$_c" && _speedbackup_update_debug_log "CONFIG_RESCUE cdn=$_c source=$conf_path"
	fi
}
_speedbackup_version_digits() {
	# Keep numeric build/date comparison stable for tags like 202607232022 or V15.5.5.
	# Avoid comparing against full download URLs; URLs contain punctuation and unrelated digits.
	printf '%s\n' "$1" | tr -cd '0-9' | cut -c1-18
}
_speedbackup_remote_tag_newer() {
	local _local _remote
	_local="$(_speedbackup_version_digits "$1")"
	_remote="$(_speedbackup_version_digits "$2")"
	[[ -n $_local && -n $_remote ]] || return 1
	# mksh arithmetic is enough for <=18 digits on Android arm64; all SpeedBackup tags are date-like.
	[[ $_remote -gt $_local ]]
}
_soc_json_read_info() {
	local _file="$1" _device="$2" _out="$3"
	[[ -s $_file && -n $_device && -n $_out ]] || return 1
	jq -r --arg device "$_device" '
		(.[$device] // null) as $d |
		if ($d|type)=="object" then
			"DEVICE\t處理器:\($d.VENDOR // "null") \($d.NAME // "null")",
			"RAM\tRAM:\($d.MEMORY // "null") \($d.CHANNELS // "null")"
		else
			"DEVICE\t處理器:null",
			"RAM\tRAM:null"
		end
	' "$_file" > "$_out" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
}

# JSON 覆寫 helper：用 cat 寫回而不是 mv/rename。
# 目的：避開部分 FUSE/sdcard/WebDAV/SMB 掛載層對 rename/chown/setfilecon 的限制。
# 僅用於 JSON 最終覆寫；壓縮檔搬移/檔名 rename 不走這裡。
_json_cat_replace() {
	local _src="$1" _dst="$2" _bak _had_old=0
	[[ -s $_src ]] || return 1
	_json_parse_ok "$_src" || return 1
	_bak="${TMPDIR:-/data/local/tmp}/.json_cat_replace_bak_${$}_$RANDOM"
	if [[ -f $_dst ]]; then
		_had_old=1
		cat "$_dst" > "$_bak" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} || rm -f "$_bak" 2>/dev/null
	fi
	if cat "$_src" > "$_dst" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} && _json_parse_ok "$_dst"; then
		rm -f "$_bak" 2>/dev/null
		return 0
	fi
	if [[ $_had_old = 1 && -f $_bak ]]; then
		cat "$_bak" > "$_dst" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	fi
	rm -f "$_bak" 2>/dev/null
	return 1
}

# JSON 原地更新 helper
# 用法: jq_inplace <檔案> <jq 表達式> [額外參數...]
# 例: jq_inplace "$app_details" --arg k "key" '.[$k] = "value"'
jq_inplace() {
	local file="$1"; shift
	local tmp="$TMPDIR/.jq_$$" rc
	# jq_inplace 目前只用於 app_details.json；輸出使用 pretty JSON，避免本地寫入後被重新壓成單行。
	if jq "$@" "$file" > "$tmp"; then
		_json_cat_replace "$tmp" "$file"
		rc=$?
		rm -f "$tmp" 2>/dev/null
		return $rc
	else
		rm -f "$tmp" 2>/dev/null
		return 1
	fi
}

# speedscan one-shot native bridge: 只吃檔案掃描/stat/chown 熱點；不可接管 JSON/planner。
_speedscan_path() {
	local _p
	_p="$(command -v speedscan 2>/dev/null)"
	[[ -n $_p && -x $_p ]] && { printf '%s\n' "$_p"; return 0; }
	[[ -n ${filepath:-} && -x $filepath/speedscan ]] && { printf '%s\n' "$filepath/speedscan"; return 0; }
	[[ -n ${tools_path:-} && -x $tools_path/speedscan ]] && { printf '%s\n' "$tools_path/speedscan"; return 0; }
	return 1
}
_speedscan_cmd() {
	local _bin
	_bin="$(_speedscan_path 2>/dev/null)" || return 127
	"$_bin" "$@"
}
_speedscan_available() {
	_speedscan_path >/dev/null 2>&1
}

_speedscan_storage_summary() {
	local _path="$1" _out=""
	[[ -n $_path ]] || return 2
	_out="$(_speedscan_cmd storage-summary "$_path" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null})" || return 1
	printf '%s\n' "$_out" | grep -Fqx '#schema	speedbackup.storage_summary.v1' 2>/dev/null || return 1
	printf '%s\n' "$_out"
	return 0
}
_speedscan_numeric() {
	case "$1" in ''|*[!0-9]*) return 1 ;; *) printf '%s\n' "$1"; return 0 ;; esac
}
_speedscan_dir_size() {
	local _out
	[[ -e $1 ]] || { echo 0; return 0; }
	_out="$(_speedscan_cmd dir-size "$1" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null})" || return 1
	_speedscan_numeric "$_out"
}
_speedscan_list_total_size() {
	local _out
	[[ -f $1 ]] || { echo 0; return 0; }
	_out="$(_speedscan_cmd list-total-size "$1" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null})" || return 1
	_speedscan_numeric "$_out"
}
_speedscan_has_files() {
	[[ -d $1 ]] || return 1
	_speedscan_cmd has-files "$1" >/dev/null 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
}
_speedscan_tree_chown() {
	local _ug="$1" _root="$2" _u _g _out _safe _summary _rc
	[[ -n $_ug && -d $_root ]] || return 1
	_u="${_ug%%:*}"; _g="${_ug#*:}"
	case $_u in ''|*[!0-9]*) return 1 ;; esac
	case $_g in ''|*[!0-9]*) return 1 ;; esac
	if [[ -n ${SPEED_DEBUG_RUN_DIR:-} && -d ${SPEED_DEBUG_RUN_DIR:-} ]]; then
		_safe="$(printf '%s' "${_root##*/}" | tr -cd 'A-Za-z0-9._-' 2>/dev/null)"
		[[ -n $_safe ]] || _safe="root"
		_out="$SPEED_DEBUG_RUN_DIR/speedscan_tree_chown_${_safe}_${$}_$RANDOM.txt"
	else
		_out="/dev/null"
	fi
	_speed_debug_log "SPEEDSCAN_TREE_CHOWN_BEGIN root=$_root uid=$_u gid=$_g mode=r348-silent"
	_speedscan_cmd tree-chown "$_u" "$_g" "$_root" > "$_out" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	_rc=$?
	if [[ $_out != "/dev/null" && -s $_out ]]; then
		_summary="$(tr '\012' '|' < "$_out" 2>/dev/null | cut -c1-500)"
		_speed_debug_log "SPEEDSCAN_TREE_CHOWN_SUMMARY root=$_root out=${_out##*/} summary=$_summary hash=0"
	fi
	return "$_rc"
}

_speedscan_tree_fixup() {
	local _ug="$1" _root="$2" _dir_mode="${3:--}" _file_mode="${4:--}" _u _g _out _safe _summary _rc _t0 _elapsed _sumfile _detailfile _keepfile
	[[ -n $_ug && -d $_root ]] || return 1
	_u="${_ug%%:*}"; _g="${_ug#*:}"
	case $_u in ''|*[!0-9]*) return 1 ;; esac
	case $_g in ''|*[!0-9]*) return 1 ;; esac
	case $_dir_mode in ''|none|NONE) _dir_mode="-" ;; esac
	case $_file_mode in ''|none|NONE) _file_mode="-" ;; esac
	_safe="$(printf '%s' "${_root##*/}" | tr -cd 'A-Za-z0-9._-' 2>/dev/null)"
	[[ -n $_safe ]] || _safe="root"
	if [[ -n ${TMPDIR:-} && -d ${TMPDIR:-} ]]; then
		_out="$TMPDIR/.speedscan_tree_fixup_${_safe}_${$}_$RANDOM.tmp"
	else
		_out="/dev/null"
	fi
	_t0="$(_speed_now_ms)"
	_speed_debug_log "SPEEDSCAN_TREE_FIXUP_BEGIN root=$_root uid=$_u gid=$_g dirMode=$_dir_mode fileMode=$_file_mode mode=r376-merged-log"
	_speedscan_cmd tree-fixup "$_u" "$_g" "$_root" "$_dir_mode" "$_file_mode" > "$_out" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	_rc=$?
	_elapsed="$(( $(_speed_now_ms) - _t0 ))"
	_summary=""
	if [[ $_out != "/dev/null" && -s $_out ]]; then
		_summary="$(tr '\012' '|' < "$_out" 2>/dev/null | cut -c1-500)"
	fi
	if [[ -n ${SPEED_DEBUG_RUN_DIR:-} && -d ${SPEED_DEBUG_RUN_DIR:-} ]]; then
		_sumfile="$SPEED_DEBUG_RUN_DIR/speedscan_tree_fixup_summary.tsv"
		_detailfile="$SPEED_DEBUG_RUN_DIR/speedscan_tree_fixup_detail.log"
		if [[ ! -f $_sumfile ]]; then
			printf 'tsMs	root	uid	gid	dirMode	fileMode	rc	elapsedMs	summary
' > "$_sumfile" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} || true
		fi
		printf '%s	%s	%s	%s	%s	%s	%s	%s	%s
' "$(_speed_now_ms)" "$_root" "$_u" "$_g" "$_dir_mode" "$_file_mode" "$_rc" "$_elapsed" "$_summary" >> "$_sumfile" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} || true
		{
			printf '===== SPEEDSCAN_TREE_FIXUP root=%s uid=%s gid=%s dirMode=%s fileMode=%s rc=%s elapsedMs=%s =====
' "$_root" "$_u" "$_g" "$_dir_mode" "$_file_mode" "$_rc" "$_elapsed"
			[[ $_out != "/dev/null" && -s $_out ]] && cat "$_out"
			printf '
'
		} >> "$_detailfile" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} || true
	fi
	_keepfile=""
	if [[ $_rc -ne 0 && -n ${SPEED_DEBUG_RUN_DIR:-} && -d ${SPEED_DEBUG_RUN_DIR:-} && $_out != "/dev/null" ]]; then
		_keepfile="$SPEED_DEBUG_RUN_DIR/speedscan_tree_fixup_${_safe}_${$}_$RANDOM.error.txt"
		cp "$_out" "$_keepfile" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} || true
	fi
	[[ $_out != "/dev/null" ]] && rm -f "$_out" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	_speed_debug_log "SPEEDSCAN_TREE_FIXUP_SUMMARY root=$_root out=speedscan_tree_fixup_summary.tsv detail=speedscan_tree_fixup_detail.log summary=$_summary rc=$_rc elapsedMs=$_elapsed keep=${_keepfile##*/} mode=r376-merged-log"
	_restore_perf_timing_done "tree_fixup" "$_t0" "path=$_root uid=$_u gid=$_g dirMode=$_dir_mode fileMode=$_file_mode rc=$_rc out=speedscan_tree_fixup_summary.tsv"
	return "$_rc"
}

_restore_chcon_tree_timed() {
	local _ctx="$1" _root="$2" _tag="${3:-chcon}" _t0 _rc
	[[ -n $_ctx && -n $_root && -e $_root ]] || return 1
	_t0="$(_speed_now_ms)"
	chcon -hR "$_ctx" "$_root" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	_rc=$?
	_restore_perf_timing_done "chcon" "$_t0" "tag=$_tag path=$_root ctx=$_ctx rc=$_rc"
	return $_rc
}

_restore_restorecon_timed() {
	local _root="$1" _tag="${2:-restorecon}" _t0 _rc
