	[[ -n ${SPEED_DEBUG_RUN_DIR:-} && -d ${SPEED_DEBUG_RUN_DIR:-} ]] || rm -f "$_facts" "$_summary" 2>/dev/null
	return 0
}

_speedscan_file_list_abs() {
	# r451: C native absolute file list + app_details/log prefix filtering. Fallback remains find for safety.
	local _root="$1" _out="$2" _skip_appdetails="${3:-0}" _tmp _stage _exclude_prefix="-" _summary
	[[ -d $_root && -n $_out ]] || return 1
	_stage="filelist_$(_process_observer_status_safe_name "${_root##*/}" 2>/dev/null || printf root)"
	case "$_root" in */log|*/log/) _exclude_prefix="-" ;; *) [[ $_root = "$Backup" && -d "$Backup/log" ]] && _exclude_prefix="$Backup/log" ;; esac
	_tmp="$TMPDIR/.speedscan_file_list_abs_filter_${$}_$RANDOM"
	_speedscan_cmd file-list-abs-filter "$_root" "$_tmp" "$_skip_appdetails" "$_exclude_prefix" > "$TMPDIR/.speedscan_file_list_abs_filter_summary_${$}_$RANDOM" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	if [[ $? = 0 && -f $_tmp ]]; then
		_speedscan_path_audit_list "$_root" "$_tmp" "${_stage}_audit" >/dev/null 2>&1 || _speed_debug_log "SPEEDSCAN_PATH_AUDIT_WARN stage=${_stage}_audit root=$_root action=continue_facts_only mode=r459"
		cat "$_tmp" >> "$_out" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
		_summary="$(wc -l < "$_tmp" 2>/dev/null | tr -d ' ')"; case $_summary in ''|*[!0-9]*) _summary=0 ;; esac
		_speed_debug_log "SPEEDSCAN_FILE_LIST_ABS_FILTER_OK root=$_root out=${_out##*/} rows=$_summary skipAppDetails=$_skip_appdetails excludePrefix=$(_speed_debug_kv "$_exclude_prefix") mode=r459"
		rm -f "$_tmp" "$TMPDIR"/.speedscan_file_list_abs_filter_summary_${$}_* 2>/dev/null
		return 0
	fi
	rm -f "$_tmp" "$TMPDIR"/.speedscan_file_list_abs_filter_summary_${$}_* 2>/dev/null
	_speed_debug_log "SPEEDSCAN_FILE_LIST_ABS_FILTER_FALLBACK root=$_root skipAppDetails=$_skip_appdetails mode=r459"
	if [[ $_skip_appdetails = 1 ]]; then
		find "$_root" -type f ! -name "app_details.json" >> "$_out" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	else
		find "$_root" -type f >> "$_out" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	fi
}
_speedscan_paths_all_exist() {
	local _list="$TMPDIR/.speedscan_exists_${$}_$RANDOM" _out="$TMPDIR/.speedscan_exists_out_${$}_$RANDOM" _rc=0 _p
	: > "$_list" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} || return 1
	for _p in "$@"; do [[ -n $_p ]] && printf '%s\n' "$_p" >> "$_list"; done
	[[ -s $_list ]] || { rm -f "$_list" "$_out" 2>/dev/null; return 1; }
	if _speedscan_batch_exists "$_list" "$_out"; then
		awk -F '	' '$2 != 1 { bad=1 } END { exit bad }' "$_out" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} || _rc=1
	else
		_rc=0
		while read -r _p; do [[ -e $_p ]] || { _rc=1; break; }; done < "$_list"
	fi
	rm -f "$_list" "$_out" 2>/dev/null
	return "$_rc"
}

_speedscan_appdetails_index() {
	# r450: C native app_details.json indexer. Facts-only; does not parse or rewrite JSON.
	local _root="$1" _out="$2" _max="${3:-2}" _min="${4:-0}"
	[[ -d $_root && -n $_out ]] || return 1
	_speedscan_cmd appdetails-index "$_root" "$_out" "$_max" "$_min" >/dev/null 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
}

_appdetails_index_paths() {
	# r450: centralized app_details.json path collection. Speedscan first; find remains only as safety fallback.
	local _root="$1" _out="$2" _max="${3:-2}" _min="${4:-0}" _sort="${5:-1}" _idx _rc _rows _source
	[[ -d $_root && -n $_out ]] || return 1
	_idx="${TMPDIR:-/data/local/tmp}/.appdetails_index_${$}_$RANDOM.tsv"
	rm -f "$_idx" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	if _speedscan_appdetails_index "$_root" "$_idx" "$_max" "$_min" && [[ -f $_idx ]]; then
		awk -F '\t' 'NF>=2 && $2 != "" {print $2}' "$_idx" > "$_out" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
		_rc=$?
		_source="speedscan-appdetails-index"
	else
		_source="find-fallback"
		if [[ $_min -gt 0 ]]; then
			find "$_root" -mindepth "$_min" -maxdepth "$_max" -name "app_details.json" -type f > "$_out" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
		else
			find "$_root" -maxdepth "$_max" -name "app_details.json" -type f > "$_out" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
		fi
		_rc=$?
	fi
	if [[ $_rc = 0 && $_sort = 1 && -s $_out ]]; then
		sort "$_out" > "$_out.sort.$$" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} && cat "$_out.sort.$$" > "$_out"
		rm -f "$_out.sort.$$" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	fi
	_rows="$(grep -vc '^[[:space:]]*$' "$_out" 2>/dev/null)"; case $_rows in ''|*[!0-9]*) _rows=0 ;; esac
	_speed_debug_log "APPDETAILS_INDEX_PATHS root=$_root out=${_out##*/} rows=$_rows maxdepth=$_max mindepth=$_min source=$_source mode=r459"
	rm -f "$_idx" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	return "$_rc"
}

_appdetails_index_count() {
	local _root="$1" _max="${2:-2}" _min="${3:-0}" _tmp _n
	_tmp="${TMPDIR:-/data/local/tmp}/.appdetails_index_count_${$}_$RANDOM.lst"
	_appdetails_index_paths "$_root" "$_tmp" "$_max" "$_min" 0 >/dev/null 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} || { rm -f "$_tmp" 2>/dev/null; echo 0; return 1; }
	_n="$(grep -vc '^[[:space:]]*$' "$_tmp" 2>/dev/null)"; case $_n in ''|*[!0-9]*) _n=0 ;; esac
	rm -f "$_tmp" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	printf '%s\n' "$_n"
}

_speedscan_backup_root_index() {
	# r451: backup tree/path facts index. C facts-only; shell only filters small TSV.
	local _root="$1" _out="$2" _max="${3:-3}"
	[[ -d $_root && -n $_out ]] || return 1
	_speedscan_cmd backup-root-index "$_root" "$_out" "$_max" >/dev/null 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
}

_speedscan_tar_payloads() {
	local _root="$1" _out="$2" _max="${3:-1}" _idx
	[[ -d $_root && -n $_out ]] || return 1
	_idx="$TMPDIR/.backup_root_index_${$}_$RANDOM.tsv"
	if _speedscan_backup_root_index "$_root" "$_idx" "$_max" && [[ -f $_idx ]]; then
		awk -F '\t' '$1=="tar_payload"{print $2}' "$_idx" | sort > "$_out" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
		rm -f "$_idx" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
		_speed_debug_log "SPEEDSCAN_TAR_PAYLOADS_READY root=$_root out=${_out##*/} rows=$(wc -l < "$_out" 2>/dev/null | tr -d ' ') maxdepth=$_max mode=r459"
		return 0
	fi
	rm -f "$_idx" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	find "$_root" -maxdepth "$_max" -name "*.tar*" -type f 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} | sort > "$_out"
}

_speedscan_backup_folder_has_tar_payload() {
	local _dir="$1" _tmp _n
	[[ -d $_dir ]] || return 1
	_tmp="$TMPDIR/.tar_payload_has_${$}_$RANDOM.lst"
	_speedscan_tar_payloads "$_dir" "$_tmp" 1 >/dev/null 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} || { rm -f "$_tmp" 2>/dev/null; return 1; }
	_n="$(wc -l < "$_tmp" 2>/dev/null | tr -d ' ')"; case $_n in ''|*[!0-9]*) _n=0 ;; esac
	rm -f "$_tmp" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	[[ $_n -gt 0 ]]
}

_speedscan_files_nonempty() {
	local _list="$TMPDIR/.speedscan_stat_${$}_$RANDOM" _out="$TMPDIR/.speedscan_stat_out_${$}_$RANDOM" _rc=0 _p
	: > "$_list" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} || return 1
	for _p in "$@"; do [[ -n $_p ]] && printf '%s\n' "$_p" >> "$_list"; done
	[[ -s $_list ]] || { rm -f "$_list" "$_out" 2>/dev/null; return 1; }
	if _speedscan_batch_stat "$_list" "$_out"; then
		awk -F '	' '($2 != 1 || $3 != "file" || $7 <= 0) { bad=1 } END { exit bad }' "$_out" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} || _rc=1
	else
		_rc=0
		while read -r _p; do [[ -s $_p ]] || { _rc=1; break; }; done < "$_list"
	fi
	rm -f "$_list" "$_out" 2>/dev/null
	return "$_rc"
}
_speedscan_chmod_list_or_fallback() {
	local _mode="$1" _list="$2" _p _rc=0
	[[ -n $_mode && -s $_list ]] || return 0
	_speedscan_batch_chmod "$_mode" "$_list" && return 0
	while read -r _p; do [[ -n $_p ]] && chmod "$_mode" "$_p" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} || _rc=1; done < "$_list"
	return "$_rc"
}

_speedscan_chmod_tree_or_fallback() {
	local _root="$1" _mode="$2" _list="$TMPDIR/.speedscan_chmod_tree_${$}_$RANDOM"
	[[ -d $_root && -n $_mode ]] || return 0
	find "$_root" -print > "$_list" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} || { rm -f "$_list" 2>/dev/null; chmod -R "$_mode" "$_root" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}; return $?; }
	_speedscan_chmod_list_or_fallback "$_mode" "$_list"
	local _rc=$?
	rm -f "$_list" 2>/dev/null
	return "$_rc"
}
_speedscan_backup_payload_manifest() {
	local _root="$1" _label="$2" _out _rows
	[[ -n ${SPEED_DEBUG_RUN_DIR:-} && -d ${SPEED_DEBUG_RUN_DIR:-} && -d $_root ]] || return 0
	_out="$SPEED_DEBUG_RUN_DIR/speedscan_manifest_${_label:-payload}.tsv"
	_out="$(printf '%s' "$_out" | tr ' /\:' '____')"
	_out="$SPEED_DEBUG_RUN_DIR/${_out##*/}"
	if _speedscan_manifest "$_root" "$_out"; then
		_rows="$(wc -l < "$_out" 2>/dev/null | tr -d ' ')"
		_speed_debug_log "SPEEDSCAN_MANIFEST_OK label=${_label:-payload} root=$_root rows=${_rows:-0} out=${_out##*/} policy=facts-only"
	fi
	return 0
}
_speedscan_restore_payload_precheck() {
	local _dir="$1" _label="$2" _list="$TMPDIR/.speedscan_restore_pre_${$}_$RANDOM" _out _p
	[[ -d $_dir ]] || return 0
	_out="${SPEED_DEBUG_RUN_DIR:-/data/speed_debug}/speedscan_restore_precheck_${_label:-app}.tsv"
	_out="$(printf '%s' "$_out" | tr ' /\:' '____')"
	_out="${SPEED_DEBUG_RUN_DIR:-/data/speed_debug}/${_out##*/}"
	: > "$_list" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} || return 0
	for _p in app_details.json app_details apk.tar apk.tar.zst user.tar user.tar.zst user_de.tar user_de.tar.zst data.tar data.tar.zst obb.tar obb.tar.zst; do
		printf '%s\n' "$_dir/$_p" >> "$_list"
	done
	_speedscan_batch_stat "$_list" "$_out" && _speed_debug_log "SPEEDSCAN_RESTORE_PRECHECK_OK label=${_label:-app} dir=$_dir out=${_out##*/} policy=facts-only"
	rm -f "$_list" 2>/dev/null
	return 0
}
_speedscan_upload_candidate_precheck() {
	local _list="$1" _label="$2" _out _rows
	[[ -s $_list && -n ${SPEED_DEBUG_RUN_DIR:-} && -d ${SPEED_DEBUG_RUN_DIR:-} ]] || return 0
	_out="$SPEED_DEBUG_RUN_DIR/speedscan_upload_candidates_${_label:-remote}.tsv"
	if _speedscan_batch_stat "$_list" "$_out"; then
		_rows="$(wc -l < "$_out" 2>/dev/null | tr -d ' ')"
		_speed_debug_log "SPEEDSCAN_UPLOAD_CANDIDATE_PRECHECK_OK label=${_label:-remote} rows=${_rows:-0} out=${_out##*/} policy=facts-only"
	else
		[[ -s $_out ]] && _speed_debug_log "SPEEDSCAN_UPLOAD_CANDIDATE_PRECHECK_PARTIAL label=${_label:-remote} out=${_out##*/} policy=facts-only"
	fi
	return 0
}

# 計算目錄總大小 (bytes), 純文件字節和 (對應電腦端「大小」)
# 用法: calc_dir_size <目錄路徑>
# 依功能類型顯示相關 conf 設定
# 遠端狀態片段 (供備份類附加顯示); 有啟用才顯示細節
remote_conf_line() {
	# 純本機模式不顯示任何遠端/流式字樣，避免一般用戶看到未啟用提示。
	remote_ui_allowed || return 0
	if stream_enabled; then
		echo "\n -遠端上傳:$remote_type ($remote_url)\n -流式上傳:開啟 (不佔本機)"
	else
		echo "\n -遠端上傳:$remote_type ($remote_url)\n -保留本地檔:$remote_keep_local"
	fi
}
show_conf() {
	case $1 in
	backup)
		echoRgb "配置詳細:\n -壓縮方式:$Compression_method\n -更新:$update\n -備份模式:$Backup_Mode\n -備份外部數據:$Backup_obb_data\n -備份user數據:$Backup_user_data\n -黑名單模式:$blacklist_mode\n -黑名單:$(printf "%s\n" "$blacklist" | awk '!/[#＃]/ && NF' | grep -c . 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null})個\n -白名單:$(printf "%s\n" "$whitelist" | awk '!/[#＃]/ && NF' | grep -c . 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null})個\n -自定義目錄備份:$backup_media\n -存在進程忽略備份:$Background_apps_ignore\n -關閉螢幕:$setDisplayPowerMode\n -通知欄:$notification_enable$(remote_conf_line)" ;;
	media)
		echoRgb "配置詳細:\n -壓縮方式:$Compression_method\n -自定義路徑:$Custom_path\n -關閉螢幕:$setDisplayPowerMode\n -通知欄:$notification_enable$(remote_conf_line)" ;;
	wifi)
		echoRgb "配置詳細:\n -關閉螢幕:$setDisplayPowerMode\n -通知欄:$notification_enable$(remote_conf_line)" ;;
	remote)
		echoRgb "配置詳細:\n -遠端類型:${remote_type:-未設定}\n -遠端位址:${remote_url:-未設定}\n -保留本地檔:$remote_keep_local" ;;
	restore)
		echoRgb "配置詳細:\n -壓縮方式:$Compression_method\n -關閉螢幕:$setDisplayPowerMode\n -通知欄:$notification_enable" ;;
	esac
}
calc_dir_size() {
    # speedscan 一次性 C 掃描優先；失敗時也使用 decimal string 加總，不再用 awk 大數 sum。
    local _n _scan_err="/dev/null"
    _n="$(_speedscan_dir_size "$1" 2>/dev/null)" && { echo "$_n"; return 0; }
    [[ -n ${SPEED_DEBUG_RUN_DIR:-} && -d ${SPEED_DEBUG_RUN_DIR:-} ]] && _scan_err="$SPEED_DEBUG_RUN_DIR/dir_size_scan.log"
    find "$1" -type f -printf '%s\n' 2>>"$_scan_err" | _decimal_sum_uint_stdin
}

# 查預掃的目錄大小表 (.dir_sizes, 由 prepare_dir_size_map 並行算好)
# 用法: _dir_size <pkg> <type> <目錄路徑>  — 表中有則秒回, 無則現算(兜底)
_dir_size() {
	local _p="$1" _t="$2" _path="$3" _vn
	_DIR_SIZE_RET=""
	# 零 fork 組變量名 (內建展開轉義)
	_vn="_sz_${_p//[!a-zA-Z0-9]/_}_${_t//[!a-zA-Z0-9]/_}"
	# 防呆: 變量名只含合法字元才 eval (避免殘留 . 等造成 bad substitution); 否則現算
	case $_vn in
		*[!a-zA-Z0-9_]*) ;;  # 含非法字元 → 跳過查表, 走 fallback
		*) eval "_DIR_SIZE_RET=\${$_vn:-}" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} ;;
	esac
	[[ -n $_DIR_SIZE_RET ]] && return
	_DIR_SIZE_RET="$(calc_dir_size "$_path")"
}
# 把 .dir_sizes 一次載入成動態變量 _sz_<pkg轉義>_<type>=size (取代每次 fork awk, 手機 fork 成本高)
load_dir_size_map() {
	[[ ! -f $TMPDIR/.dir_sizes ]] && return
	local _pk _ty _sz _vn
	while IFS=$'\t' read -r _pk _ty _sz; do
		[[ -z $_pk ]] && continue
		_vn="_sz_${_pk//[!a-zA-Z0-9]/_}_$_ty"
		eval "$_vn=\$_sz"
	done < "$TMPDIR/.dir_sizes"
}

# r446: 備份前容量總覽。只讀同輪 native speedscan 預掃與既有 fast-skip map，不改備份判斷語義；summary 階段不另掃大目錄。
_backup_prescan_size_map_get() {
	local _p="$1" _t="$2" _vn _v
	_vn="_sz_${_p//[!a-zA-Z0-9]/_}_${_t//[!a-zA-Z0-9]/_}"
	case $_vn in *[!a-zA-Z0-9_]*) echo 0; return 0 ;; esac
	eval "_v=\${$_vn:-0}" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	case $_v in ''|*[!0-9]*) _v=0 ;; esac
	printf '%s\n' "$_v"
}

# r450: obsolete r442-r445 per-app shell summary helpers removed. Summary now uses speedscan maps + single reducer; bounded media rescan removed from hot path.

_backup_prescan_custom_media_scan() {
	# r446: summary 階段不再另行 calc_dir_size。Custom_path / 媒體大小已在 prepare_dir_size_map 的
	# native speedscan dir-size-map 同輪 manifest 內完成；這裡只彙總 .dir_sizes，應該秒出。
	_BACKUP_PRESCAN_CUSTOM_MEDIA_TOTAL=0
	_BACKUP_PRESCAN_CUSTOM_CACHE_TOTAL=0
	_BACKUP_PRESCAN_CUSTOM_MEDIA_PARTIAL=0
	[[ ${backup_media:-false} = true && ! -f ${0%/*}/app_details.json ]] || return 0
	[[ -n ${Custom_path:-} ]] || return 0
	[[ ${SPEEDBACKUP_BACKUP_PRESCAN_CUSTOM_MEDIA_SCAN:-1} = 1 ]] || { _speed_debug_log "BACKUP_PRESCAN_CUSTOM_MEDIA_SCAN_SKIP reason=disabled mode=r459"; return 0; }
	local _pk _ty _sz _mapped=0 _cache_mapped=0 _start _now _elapsed
	_start="$(date +%s 2>/dev/null || echo 0)"
	_speed_debug_log "BACKUP_PRESCAN_CUSTOM_MEDIA_SCAN_BEGIN mode=r459 source=dir-size-map-only policy=no-extra-scan"
	if [[ -f $TMPDIR/.dir_sizes ]]; then
		while IFS=$'	' read -r _pk _ty _sz || [[ -n $_pk || -n $_ty || -n $_sz ]]; do
			[[ $_pk = __speedbackup_custom_media__ ]] || continue
			case $_sz in ''|*[!0-9]*) _sz=0 ;; esac
			case $_ty in
			media_*_exclude_cache)
				_BACKUP_PRESCAN_CUSTOM_CACHE_TOTAL="$(_decimal_add_uint "$_BACKUP_PRESCAN_CUSTOM_CACHE_TOTAL" "$_sz")"
				_cache_mapped=$((_cache_mapped + 1))
				;;
			media_*)
				_BACKUP_PRESCAN_CUSTOM_MEDIA_TOTAL="$(_decimal_add_uint "$_BACKUP_PRESCAN_CUSTOM_MEDIA_TOTAL" "$_sz")"
				_mapped=$((_mapped + 1))
				;;
			esac
		done < "$TMPDIR/.dir_sizes"
	fi
	if [[ $_mapped -eq 0 ]]; then
		# 不再 fallback shell 掃描，避免摘要阻塞；若需要完整媒體總量，讓 prepare_dir_size_map 的 C manifest 負責。
		_BACKUP_PRESCAN_CUSTOM_MEDIA_PARTIAL=1
		_speed_debug_log "BACKUP_PRESCAN_CUSTOM_MEDIA_SCAN_MAP_MISS reason=no-custom-media-rows action=count-zero-no-extra-scan mode=r459"
	fi
	_now="$(date +%s 2>/dev/null || echo 0)"; _elapsed=$((_now - _start))
	_speed_debug_log "BACKUP_PRESCAN_CUSTOM_MEDIA_SCAN_END mediaBytes=${_BACKUP_PRESCAN_CUSTOM_MEDIA_TOTAL:-0} cacheBytes=${_BACKUP_PRESCAN_CUSTOM_CACHE_TOTAL:-0} mapped=$_mapped cacheMapped=$_cache_mapped partial=${_BACKUP_PRESCAN_CUSTOM_MEDIA_PARTIAL:-0} elapsedSec=$_elapsed mode=r459 source=dir-size-map-only"
}

_backup_prescan_prepare_apk_size_map() {
	# r451: native speedscan apk-size-map; fallback stat-loop only for old speedscan.
	local _out="$TMPDIR/.backup_prescan_apk_size_map.tsv" _mpkg _p _rest _sz
	: > "$_out" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} || { printf '%s\n' "$_out"; return 0; }
	[[ -s $TMPDIR/.pkg_apk_paths ]] || { printf '%s\n' "$_out"; return 0; }
	if _speedscan_cmd apk-size-map "$TMPDIR/.pkg_apk_paths" "$_out" >/dev/null 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} && [[ -f $_out ]]; then
		_speed_debug_log "BACKUP_PRESCAN_APK_SIZE_MAP_READY rows=$(wc -l < "$_out" 2>/dev/null | tr -d ' ') source=speedscan-apk-size-map mode=r459"
		printf '%s\n' "$_out"
		return 0
	fi
	: > "$_out" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	while IFS=$'\t' read -r _mpkg _p _rest || [[ -n $_mpkg || -n $_p ]]; do
		[[ -n $_mpkg && -f $_p ]] || continue
		case $_p in *.apk) ;; *) continue ;; esac
		_sz="$(stat -c%s "$_p" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null})"
		case $_sz in ''|*[!0-9]*) _sz=0 ;; esac
		printf '%s\t%s\n' "$_mpkg" "$_sz" >> "$_out" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	done < "$TMPDIR/.pkg_apk_paths"
	_speed_debug_log "BACKUP_PRESCAN_APK_SIZE_MAP_READY rows=$(wc -l < "$_out" 2>/dev/null | tr -d ' ') source=stat-loop-fallback mode=r459"
	printf '%s\n' "$_out"
}

_backup_prescan_emit_selected_list() {
	# r451: selected-list reducer in C native. Fallback awk stays safety-only.
	local _out="$1" _list="$2" _in _blk _tmp
	: > "$_out" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} || return 1
	_in="$TMPDIR/.backup_prescan_selected_input_${$}_$RANDOM.txt"
	_blk="$TMPDIR/.backup_prescan_blacklist_${$}_$RANDOM.txt"
	_tmp="$TMPDIR/.backup_prescan_selected_${$}_$RANDOM.tsv"
	printf '%s\n' "$_list" > "$_in" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	printf '%s\n' "${blacklist:-}" | awk '!/^[[:space:]]*[#＃]/ && NF{print $1}' > "$_blk" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	if _speedscan_cmd selected-list "$_in" "$_blk" "$_tmp" "${blacklist_mode:-0}" >/dev/null 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} && [[ -f $_tmp ]]; then
		cat "$_tmp" > "$_out" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
		_speed_debug_log "BACKUP_PRESCAN_SELECTED_LIST_READY rows=$(wc -l < "$_out" 2>/dev/null | tr -d ' ') source=speedscan-selected-list mode=r459"
		rm -f "$_in" "$_blk" "$_tmp" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
		return 0
	fi
	awk -v bm="${blacklist_mode:-0}" '
		FNR==NR { if ($0 !~ /^[[:space:]]*[#＃]/ && NF) black[$1]=1; next }
		function safe_name(n,p,  x){ x=n; gsub(/[\\/:*?"<>|\t\r\n]/,"_",x); if(x=="") x=p; return x }
		/^[[:space:]]*$/ || /^[#＃]/ { next }
		{
			name=$1; pkg=$2; nodata=0;
			if(name ~ /^!/) { sub(/^!/,"",name); nodata=1; }
			if(substr(name,1,3)=="！") { name=substr(name,4); nodata=1; }
			bh=(pkg in black) ? 1 : 0;
			if (bh && (bm=="true" || bm=="1")) { print "EXCLUDED\t" name "\t" pkg; next; }
			if (bh) nodata=1;
			name=safe_name(name, pkg);
			print "APP\t" name "\t" pkg "\t" nodata;
		}
	' "$_blk" "$_in" > "$_tmp" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} && cat "$_tmp" > "$_out" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	_speed_debug_log "BACKUP_PRESCAN_SELECTED_LIST_READY rows=$(wc -l < "$_out" 2>/dev/null | tr -d ' ') source=awk-fallback mode=r459"
	rm -f "$_in" "$_blk" "$_tmp" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	return 0
}

_backup_prescan_compute_fast_totals() {
	# r451: C native prescan summary reducer. Fallback awk remains for old speedscan.
	local _sel="$1" _apkmap="$2" _out="$3" _rs="-" _ls="-" _combined="$TMPDIR/.backup_prescan_summary_combined.tsv"
	[[ -s $TMPDIR/.remote_fast_skip_ok ]] && _rs="$TMPDIR/.remote_fast_skip_ok"
	[[ -s $TMPDIR/.local_fast_skip_ok ]] && _ls="$TMPDIR/.local_fast_skip_ok"
	if _speedscan_cmd backup-prescan-summary "$_sel" "${TMPDIR:-/data/local/tmp}/.dir_sizes" "$_apkmap" "$_rs" "$_ls" "$_out" "${remote_stream:-0}" "${remote_type:--}" >/dev/null 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} && [[ -s $_out ]]; then
		_speed_debug_log "BACKUP_PRESCAN_SUMMARY_NATIVE_READY out=${_out##*/} mode=r459 source=speedscan-backup-prescan-summary"
		return 0
	fi
	: > "$_combined" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} || return 1
	[[ -s $_sel ]] && sed 's/^/SEL\t/' "$_sel" >> "$_combined" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	[[ -s $TMPDIR/.dir_sizes ]] && sed 's/^/DIR\t/' "$TMPDIR/.dir_sizes" >> "$_combined" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	[[ -s $_apkmap ]] && sed 's/^/APK\t/' "$_apkmap" >> "$_combined" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	[[ -s $TMPDIR/.remote_fast_skip_ok ]] && sed 's/^/RSKIP\t/' "$TMPDIR/.remote_fast_skip_ok" >> "$_combined" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	[[ -s $TMPDIR/.local_fast_skip_ok ]] && sed 's/^/LSKIP\t/' "$TMPDIR/.local_fast_skip_ok" >> "$_combined" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	awk -F '\t' -v remoteStream="${remote_stream:-0}" -v remoteType="${remote_type:-}" '
	function n(v){ return (v ~ /^[0-9]+$/) ? v + 0 : 0 }
	function out(k,v){ if (v < 0) v=0; printf "%s\t%.0f\n", k, v }
	$1=="SEL" && $2=="APP" { name=$3; pkg=$4; nd=$5; if (pkg!="" && !(pkg in selected)) { selected[pkg]=1; selName[pkg]=name; nodata[pkg]=nd; apps++ } next }
	$1=="SEL" && $2=="EXCLUDED" { excluded++; next }
	$1=="DIR" { pkg=$2; typ=$3; sz=n($4); if (pkg=="__speedbackup_custom_media__") { if (typ ~ /^media_[0-9]+_exclude_cache$/) { mediaCache += sz; cacheMapped++ } else if (typ ~ /^media_[0-9]+$/) { mediaTotal += sz; mediaMapped++ } next } if (typ=="user" || typ=="user_de") appdata[pkg]+=sz; else if (typ=="data" || typ=="obb" || typ=="media") external[pkg]+=sz; else if (typ=="user_exclude_cache" || typ=="user_exclude_code_cache" || typ=="user_de_exclude_cache" || typ=="user_de_exclude_code_cache" || typ=="data_exclude_cache" || typ=="obb_exclude_cache" || typ=="media_exclude_cache") cache[pkg]+=sz; next }
	$1=="APK" { apk[$2]+=n($3); next }
	$1=="RSKIP" { rskip[$2]=1; next }
	$1=="LSKIP" { lskip[$2]=1; next }
	END { for (p in selected) { ap=n(apk[p]); ad=n(appdata[p]); ex=n(external[p]); ca=n(cache[p]); if (nodata[p]=="1" || p=="bin.mt.plus") { ad=0; ex=0; ca=0 } raw=ap+ad+ex; eff=raw-ca; if(eff<0) eff=0; apkTotal+=ap; appdataTotal+=ad; externalTotal+=ex; cacheTotal+=ca; total+=eff; if(remoteStream=="1" && remoteType!="" && (selName[p] in rskip)) remoteSkip+=eff; else if(remoteType=="" && remoteStream!="1" && (selName[p] in lskip)) localSkip+=eff } total+=mediaTotal; cacheTotal+=mediaCache; total-=mediaCache; if(total<0) total=0; processSkip=remoteSkip+localSkip; expected=total-processSkip; if(expected<0) expected=0; partialMedia=(mediaMapped>0)?0:1; out("apps",apps); out("excludedApps",excluded); out("apk",apkTotal); out("appData",appdataTotal); out("external",externalTotal); out("mediaCustom",mediaTotal); out("excludedCache",cacheTotal); out("total",total); out("remoteSkip",remoteSkip); out("localSkip",localSkip); out("expected",expected); out("partialMedia",partialMedia); out("mediaMapped",mediaMapped); out("cacheMapped",cacheMapped); }
	' "$_combined" > "$_out" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	rm -f "$_combined" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	_speed_debug_log "BACKUP_PRESCAN_SUMMARY_NATIVE_FALLBACK out=${_out##*/} mode=r459 source=awk-fallback"
	[[ -s $_out ]]
}

_backup_prescan_result_get() {
	local _file="$1" _key="$2" _v
	_v="$(awk -F '\t' -v k="$_key" '$1==k{print $2; exit}' "$_file" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null})"
	case $_v in ''|*[!0-9]*) _v=0 ;; esac
	printf '%s\n' "$_v"
}

_backup_remote_prescan_progress_step() {
	# r448: restore a visible remote-prescan progress bar that explicitly includes the
	# remote-size stage. r447 only had coarse 0/4 phases, so the long remote_dir_size
	# request looked like the old size prescan progress disappeared.
	local _cur="$1" _msg="$2"
	[[ -n ${remote_type:-} || ${remote_stream:-0} = 1 ]] || return 0
	_speedbackup_progress_step "$_cur" 5 "$_msg" "prepare_remote_prescan_overall" "107"
}

_backup_remote_size_prescan_progress_begin() {
	local _path="$1"
	[[ -n ${remote_type:-} ]] || return 0
	echoRgb "正在預掃遠端備份大小: ${_path:-$(get_backup_dirname 2>/dev/null)}" "3"
	_speedbackup_progress_step 0 1 "正在計算遠端備份大小" "prepare_remote_size_before" "107"
	_speed_debug_log "REMOTE_SIZE_PRESCAN_PROGRESS_BEGIN path=$(_speed_debug_kv "${_path:-}") mode=r448"
}

_backup_remote_size_prescan_progress_done() {
	local _path="$1" _bytes="${2:-0}" _label
	[[ -n ${remote_type:-} ]] || return 0
	case $_bytes in ''|*[!0-9]*) _bytes=0 ;; esac
	_label="遠端備份大小預掃完成 $(size_with_bytes "$_bytes" 2>/dev/null)"
	_speedbackup_progress_step 1 1 "$_label" "prepare_remote_size_before" "107"
	_speed_debug_log "REMOTE_SIZE_PRESCAN_PROGRESS_DONE path=$(_speed_debug_kv "${_path:-}") bytes=$_bytes mode=r448"
}

_backup_prescan_skip_name_hit() {
	local _file="$1" _name="$2"
	[[ -s $_file && -n $_name ]] || return 1
	awk -v n="$_name" '$0==n{f=1;exit} END{exit f?0:1}' "$_file" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
}

_backup_prescan_show_summary() {
	[[ ${SPEEDBACKUP_BACKUP_PRESCAN_SIZE_SUMMARY:-1} = 1 ]] || return 0
	local _summary_start _summary_now _summary_elapsed _media_note=""
	_summary_start="$(date +%s 2>/dev/null || echo 0)"
	_speed_debug_log "BACKUP_PRESCAN_SIZE_SUMMARY_BEGIN mode=r459 source=native-speedscan-hotpaths"
	echoRgb "正在整理本輪備份容量總覽..." "3"
	local _list _name _pkg _sel _apkmap _res
	local _apps _excluded _apk_total _appdata_total _external_total _media_total _cache_total _total _remote_skip _local_skip _expected _partial_media _media_mapped _cache_mapped
	if [[ -f ${0%/*}/app_details.json ]]; then
		_name="$(_appdetails_get_first_entry_name "${0%/*}/app_details.json")"
		_pkg="$(_appdetails_get_first_pkg "${0%/*}/app_details.json")"
		_list="$_name $_pkg"
	else
		_list="$txt"
	fi
	_sel="$TMPDIR/.backup_prescan_selected.tsv"
	_res="$TMPDIR/.backup_prescan_size_summary.tsv"
	_speed_debug_log "BACKUP_PRESCAN_SIZE_SUMMARY_STAGE_BEGIN stage=selected-list mode=r459"
	_backup_prescan_emit_selected_list "$_sel" "$_list" || return 0
	_eventwait_output_file_stable_ms "$_sel" backup_prescan_selected_ready 50 1000 >/dev/null 2>&1 || true
	_speed_debug_log "BACKUP_PRESCAN_SIZE_SUMMARY_STAGE_END stage=selected-list mode=r459"
	_speed_debug_log "BACKUP_PRESCAN_SIZE_SUMMARY_STAGE_BEGIN stage=apk-size-map mode=r459"
	_apkmap="$(_backup_prescan_prepare_apk_size_map)"
	_eventwait_output_file_stable_ms "$_apkmap" backup_prescan_apkmap_ready 50 1000 >/dev/null 2>&1 || true
	_speed_debug_log "BACKUP_PRESCAN_SIZE_SUMMARY_STAGE_END stage=apk-size-map mode=r459"
	_speed_debug_log "BACKUP_PRESCAN_CUSTOM_MEDIA_SCAN_BEGIN mode=r459 source=dir-size-map-only policy=no-extra-scan"
	_speed_debug_log "BACKUP_PRESCAN_SIZE_SUMMARY_STAGE_BEGIN stage=compute-fast mode=r459"
	_backup_prescan_compute_fast_totals "$_sel" "$_apkmap" "$_res" || { _speed_debug_log "BACKUP_PRESCAN_SIZE_SUMMARY_FAIL stage=compute-fast mode=r459"; return 0; }
	_eventwait_output_file_stable_ms "$_res" backup_prescan_summary_ready 50 1000 >/dev/null 2>&1 || true
	_speed_debug_log "BACKUP_PRESCAN_SIZE_SUMMARY_STAGE_END stage=compute-fast mode=r459"
	_apps="$(_backup_prescan_result_get "$_res" apps)"
	_excluded="$(_backup_prescan_result_get "$_res" excludedApps)"
	_apk_total="$(_backup_prescan_result_get "$_res" apk)"
	_appdata_total="$(_backup_prescan_result_get "$_res" appData)"
	_external_total="$(_backup_prescan_result_get "$_res" external)"
	_media_total="$(_backup_prescan_result_get "$_res" mediaCustom)"
	_cache_total="$(_backup_prescan_result_get "$_res" excludedCache)"
	_total="$(_backup_prescan_result_get "$_res" total)"
	_remote_skip="$(_backup_prescan_result_get "$_res" remoteSkip)"
	_local_skip="$(_backup_prescan_result_get "$_res" localSkip)"
	_expected="$(_backup_prescan_result_get "$_res" expected)"
	_partial_media="$(_backup_prescan_result_get "$_res" partialMedia)"
	_media_mapped="$(_backup_prescan_result_get "$_res" mediaMapped)"
	_cache_mapped="$(_backup_prescan_result_get "$_res" cacheMapped)"
	[[ $_partial_media = 1 ]] && _media_note="（媒體/自訂路徑未進入本輪 C 預掃，已略過以避免摘要阻塞）"
	_summary_now="$(date +%s 2>/dev/null || echo 0)"; _summary_elapsed=$((_summary_now - _summary_start))
	_speed_debug_log "BACKUP_PRESCAN_CUSTOM_MEDIA_SCAN_END mediaBytes=$_media_total cacheBytes=0 mapped=$_media_mapped cacheMapped=$_cache_mapped partial=$_partial_media elapsedSec=$_summary_elapsed mode=r459 source=dir-size-map-only"
	_speed_debug_log "BACKUP_PRESCAN_SIZE_SUMMARY apps=$_apps excludedApps=$_excluded apk=$_apk_total appData=$_appdata_total external=$_external_total mediaCustom=$_media_total excludedCache=$_cache_total total=$_total remoteSkip=$_remote_skip localSkip=$_local_skip expected=$_expected partialMedia=$_partial_media elapsedSec=$_summary_elapsed mode=r459 source=native-speedscan-hotpaths"
	echoRgb "本輪備份預掃完成\n -App：$_apps 個\n -APK：$(size "$_apk_total")\n -App 資料：$(size "$_appdata_total")\n -外部資料 / OBB：$(size "$_external_total")\n -媒體 / 自訂資料夾：$(size "$_media_total")$_media_note\n -排除快取：$(size "$_cache_total")\n -壓縮前總量：$(size "$_total")\n -遠端可跳過：$(size "$_remote_skip")\n -預計實際處理：$(size "$_expected")" "3"
	[[ $_local_skip != 0 ]] && echoRgb " -本地無變化可跳過：$(size "$_local_skip")" "2"
}

# 將 $name1 寫入 .changed_apps (去重, 避免重複記錄)
_mark_changed() {
	awk -v n="$name1" 'BEGIN{f=0} $0==n{f=1;exit} END{if(!f)print n}' \
		"$TMPDIR/.changed_apps" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} >> "$TMPDIR/.changed_apps"
	# app_details metadata 變更也必須視為本輪有變更，否則遠端非流式增量會只上傳依賴文件，漏傳更新後的 app_details.json。
	backup_has_changes=1
}
# 通用: 把 pkg<TAB>value 表載入成動態變量 <prefix>_<pkg轉義>=value (零 fork 查詢)
# 用法: load_kv_map <檔案> <變量前綴>
load_kv_map() {
	[[ ! -f $1 ]] && return
	local _pk _val _vn _pfx="$2"
	while IFS=$'\t' read -r _pk _val; do
		[[ -z $_pk ]] && continue
		_vn="${_pfx}_${_pk//[!a-zA-Z0-9]/_}"
		eval "$_vn=\$_val"
	done < "$1"
}
# 通用查詢: _kv_get <變量前綴> <pkg>  → 印出值 (零 fork)
_kv_get() {
	local _vn="$1_${2//[!a-zA-Z0-9]/_}" _v
	eval "_v=\${$_vn}"
	echo "$_v"
}

# 通用查詢: pkg<TAB>value map 直接查詢；檔案不存在時保底建空檔，避免 awk No such file。
# 用法: _kv_file_get <map_file> <pkg>
_kv_file_get() {
	local _file="$1" _pkg="$2"
	[[ -z $_file || -z $_pkg ]] && return 0
	[[ -f $_file ]] || : > "$_file" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	awk -v pkg="$_pkg" -F'	' '$1 == pkg {print $2; exit}' "$_file" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
}
# 大值查詢: pkg<TAB>value map 直接輸出到檔案，避免把大型 JSON 放進 shell argv。
# 某些 Android shell/外部 printf 遇到幾十 KB AppState JSON 會報 Argument list too long。
_kv_file_get_to_file() {
	local _file="$1" _pkg="$2" _out="$3"
	[[ -z $_file || -z $_pkg || -z $_out ]] && return 1
	[[ -f $_file ]] || : > "$_file" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	awk -v pkg="$_pkg" -F'	' '$1 == pkg {print $2; found=1; exit} END{exit found?0:1}' "$_file" > "$_out" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
}

# 依本次實際壓縮方式 chmod 輸出檔
# 注意: 應用 data 通常走全域 Compression_method=zstd；Media/自訂資料夾會用 _comp_override=tar。
# 因此不能只看全域 Compression_method，必須看傳入的有效 _comp。
_chmod_compressed_output() {
	local _base="$1" _comp="$2"
	case $_comp in
	tar|Tar|TAR)
		[[ -f "$_base.tar" ]] && chmod 0600 "$_base.tar" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
		;;
	zstd|Zstd|ZSTD)
		[[ -f "$_base.tar.zst" ]] && chmod 0600 "$_base.tar.zst" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
		;;
	*)
		[[ -f "$_base.tar" ]] && chmod 0600 "$_base.tar" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
		[[ -f "$_base.tar.zst" ]] && chmod 0600 "$_base.tar.zst" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
		;;
	esac
}

# v24.20.14-7.8 stream stderr clean: 流式 SMB 噪音只進 raw log，不污染 stderr.log。
# v24.20.14-7 local archive raw debug: 本地備份/壓縮/校驗/解壓 raw/meta/stderr log。
# 注意：tar/zstd 資料流 stdout 不可落檔；只記 meta、stderr、rc、耗時、路徑與大小。
_local_raw_debug_next_log() {
	# v24.20.14-7.66-191：raw debug 不再為每次操作建立 extract_001/compress_001/checksum_001。
	# 同一 kind 全部 append 到單一檔案，批量恢復時 speed_debug 包不會爆出大量分片日誌。
	local _kind="$1"
	printf '%s/%s.log\n' "${SPEED_DEBUG_RUN_DIR:-/data/speed_debug}" "$_kind"
}
_local_raw_debug_summary() {
	local _kind="$1"; shift
	[[ -n ${SPEED_DEBUG_RUN_DIR:-} && -d ${SPEED_DEBUG_RUN_DIR:-} ]] || return 0
	printf '%s\n' "$*" >> "$SPEED_DEBUG_RUN_DIR/${_kind}_raw.log" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
}
_local_raw_debug_begin() {
	local _kind="$1"; shift
	[[ -n ${SPEED_DEBUG_RUN_DIR:-} && -d ${SPEED_DEBUG_RUN_DIR:-} ]] || { echo /dev/null; return 0; }
	local _log _now
	_log="$(_local_raw_debug_next_log "$_kind")"
	_now="$(date '+%Y-%m-%d %H:%M:%S' 2>/dev/null)"
	{
		echo "BEGIN kind=$_kind time=$_now"
		echo "$*"
	} >> "$_log" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	_local_raw_debug_summary "$_kind" "BEGIN log=${_log##*/} $*"
	echo "$_log"
}
_local_raw_debug_end() {
	local _kind="$1" _log="$2" _rc="$3" _start_ms="$4"; shift 4
	[[ -n $_log ]] || _log=/dev/null
	local _end_ms _elapsed _now
	_end_ms="$(date +%s%3N 2>/dev/null)"
	case $_end_ms in ''|*[!0-9]*) _end_ms="$(date +%s 2>/dev/null)000" ;; esac
	case $_start_ms in ''|*[!0-9]*) _elapsed=unknown ;; *) _elapsed=$((_end_ms - _start_ms)) ;; esac
	_now="$(date '+%Y-%m-%d %H:%M:%S' 2>/dev/null)"
	{
		echo "$*"
		echo "END kind=$_kind rc=$_rc elapsedMs=$_elapsed time=$_now"
	} >> "$_log" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	_local_raw_debug_summary "$_kind" "END log=${_log##*/} rc=$_rc elapsedMs=$_elapsed $*"
}
_local_file_size_debug() {
	local _f="$1" _s
	[ -f "$_f" ] || { echo 0; return; }
	# 不能用 `wc -c < file` 取壓縮檔大小；大檔會完整讀一遍，導致終端在「備份data數據成功」後長時間無輸出。
	# stat 只讀 metadata，8GB+ data.tar.zst 也能立即取得大小。
	_s="$(stat -c %s "$_f" 2>/dev/null)"
	case $_s in
	''|*[!0-9]*)
		# toybox/stat 不支援 -c 時退回 ls metadata；不要使用 wc -c，避免大檔完整讀取。
		_s="$(ls -ln "$_f" 2>/dev/null | awk '{print $5; exit}')"
		case $_s in ''|*[!0-9]*) _s=0 ;; esac
		;;
	esac
	echo "$_s"
}

_speed_now_ms() {
	local _ms
	_ms="$(date +%s%3N 2>/dev/null)"
	case $_ms in ''|*[!0-9]*) _ms="$(date +%s 2>/dev/null)000" ;; esac
	case $_ms in ''|*[!0-9]*) _ms=0 ;; esac
	printf '%s\n' "$_ms"
}

_restore_perf_timing_done() {
	local _tag="$1" _start="$2"; shift 2
	local _end _elapsed
	_end="$(_speed_now_ms)"
	case $_start in ''|*[!0-9]*) _elapsed=unknown ;; *) _elapsed=$((_end - _start)) ;; esac
	_speed_debug_log "RESTORE_PERF_TIMING tag=$_tag elapsedMs=$_elapsed $* mode=r370"
}

_webdav_speed_mib_s() {
	local _bytes="$1" _ms="$2"
	case $_bytes in ''|*[!0-9]*) _bytes=0 ;; esac
	case $_ms in ''|*[!0-9]*|0) _ms=1 ;; esac
	awk -v b="$_bytes" -v ms="$_ms" 'BEGIN{printf "%.2f", (b/1048576.0)/(ms/1000.0)}'
}
_webdav_size_mib_text() {
	local _bytes="$1"
	case $_bytes in ''|*[!0-9]*) _bytes=0 ;; esac
	awk -v b="$_bytes" 'BEGIN{printf "%.2fMiB", b/1048576.0}'
}

_restore_stream_perf_field() {
	printf '%s' "$1" | tr '\t\r\n' '   ' 2>/dev/null
}

_restore_stream_perf_record() {
	local _start="$1" _rc="$2" _app="$3" _pkg="$4" _payload="$5" _rel="$6" _bytes="$7" _dest="$8" _archive_ext="$9" _path_mode="${10:-original}"
	local _end _elapsed _avg _tsv
	_end="$(_speed_now_ms)"
	case $_start in ''|*[!0-9]*) _elapsed=unknown ;; *) _elapsed=$((_end - _start)) ;; esac
	case $_bytes in ''|*[!0-9]*) _bytes=0 ;; esac
	case $_elapsed in ''|*[!0-9]*|0|unknown) _avg=0.00 ;; *) _avg="$(_webdav_speed_mib_s "$_bytes" "$_elapsed")" ;; esac
	_speed_debug_log "RESTORE_STREAM_PERF_END app=$(_restore_stream_perf_field "$_app") package=$(_restore_stream_perf_field "$_pkg") payload=$(_restore_stream_perf_field "$_payload") rel=$(_restore_stream_perf_field "$_rel") bytes=$_bytes elapsedMs=$_elapsed avgMiBps=$_avg rc=$_rc dest=$(_restore_stream_perf_field "$_dest") archiveExt=$(_restore_stream_perf_field "$_archive_ext") pathMode=$(_restore_stream_perf_field "$_path_mode") trueStream=1 staged=0 scope=download_extract_pipe treeFixupSeparate=1 mode=r416"
	if [[ -n ${SPEED_DEBUG_RUN_DIR:-} && -d ${SPEED_DEBUG_RUN_DIR:-} ]]; then
		_tsv="$SPEED_DEBUG_RUN_DIR/restore_stream_perf.tsv"
		if [[ ! -f $_tsv ]]; then
			printf 'tsMs\tapp\tpackage\tpayload\trel\tbytes\telapsedMs\tavgMiBps\trc\tdest\tarchiveExt\tpathMode\ttrueStream\tstaged\tscope\tmode\n' > "$_tsv" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} || true
		fi
		printf '%s\t%s\t%s\t%s\t%s\t%s\t%s\t%s\t%s\t%s\t%s\t%s\t1\t0\tdownload_extract_pipe\tr413\n' \
			"$_end" "$(_restore_stream_perf_field "$_app")" "$(_restore_stream_perf_field "$_pkg")" "$(_restore_stream_perf_field "$_payload")" "$(_restore_stream_perf_field "$_rel")" \
			"$_bytes" "$_elapsed" "$_avg" "$_rc" "$(_restore_stream_perf_field "$_dest")" "$(_restore_stream_perf_field "$_archive_ext")" "$(_restore_stream_perf_field "$_path_mode")" \
			>> "$_tsv" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} || true
	fi
}


_restore_apk_timing_field() {
	printf '%s' "$1" | tr '\t\r\n' '   ' 2>/dev/null
}

_restore_elapsed_ms() {
	local _start="$1" _end
	_end="$(_speed_now_ms)"
	case $_start in ''|*[!0-9]*) printf '0\n' ;; *) printf '%s\n' "$((_end - _start))" ;; esac
}

_restore_apk_timing_record() {
	local _pkg="$1" _label="$2" _apk_bytes="$3" _installed_ver="$4" _backup_ver="$5" _action="$6" _extract_ms="$7" _install_ms="$8" _commit_ms="$9" _verify_ms="${10}" _total_ms="${11}" _reason="${12}" _tsv
	case $_apk_bytes in ''|*[!0-9]*) _apk_bytes=0 ;; esac
	case $_extract_ms in ''|*[!0-9]*) _extract_ms=0 ;; esac
	case $_install_ms in ''|*[!0-9]*) _install_ms=0 ;; esac
	case $_commit_ms in ''|*[!0-9]*) _commit_ms=0 ;; esac
	case $_verify_ms in ''|*[!0-9]*) _verify_ms=0 ;; esac
	case $_total_ms in ''|*[!0-9]*) _total_ms=0 ;; esac
	_speed_debug_log "RESTORE_APK_TIMING package=$(_restore_apk_timing_field "$_pkg") label=$(_restore_apk_timing_field "$_label") apkBytes=$_apk_bytes installedVersion=$(_restore_apk_timing_field "$_installed_ver") backupVersion=$(_restore_apk_timing_field "$_backup_ver") apkAction=$(_restore_apk_timing_field "$_action") extractMs=$_extract_ms installSessionMs=$_install_ms installCommitMs=$_commit_ms verifyMs=$_verify_ms totalMs=$_total_ms reason=$(_restore_apk_timing_field "$_reason") mode=r416"
	if [[ -n ${SPEED_DEBUG_RUN_DIR:-} && -d ${SPEED_DEBUG_RUN_DIR:-} ]]; then
		_tsv="$SPEED_DEBUG_RUN_DIR/restore_apk_timing.tsv"
		if [[ ! -f $_tsv ]]; then
			printf 'pkg\tlabel\tapkBytes\tinstalledVersion\tbackupVersion\tapkAction\textractMs\tinstallSessionMs\tinstallCommitMs\tverifyMs\ttotalMs\treason\tmode\n' > "$_tsv" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} || true
		fi
		printf '%s\t%s\t%s\t%s\t%s\t%s\t%s\t%s\t%s\t%s\t%s\t%s\tr413\n' \
			"$(_restore_apk_timing_field "$_pkg")" "$(_restore_apk_timing_field "$_label")" "$_apk_bytes" "$(_restore_apk_timing_field "$_installed_ver")" "$(_restore_apk_timing_field "$_backup_ver")" "$(_restore_apk_timing_field "$_action")" \
			"$_extract_ms" "$_install_ms" "$_commit_ms" "$_verify_ms" "$_total_ms" "$(_restore_apk_timing_field "$_reason")" >> "$_tsv" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} || true
	fi
}

_restore_phase_timing_field() {
	printf '%s' "$1" | tr '\t\r\n' '   ' 2>/dev/null
}

_restore_phase_timing_record() {
	local _stage="$1" _start="$2" _app="${3:-${name1:-}}" _pkg="${4:-${name2:-}}" _detail="${5:-}" _rc="${6:-0}" _end _elapsed _tsv
	_end="$(_speed_now_ms)"
	case $_start in ''|*[!0-9]*) _elapsed=0 ;; *) _elapsed=$((_end - _start)) ;; esac
	case $_rc in ''|*[!0-9-]*) _rc=0 ;; esac
	_speed_debug_log "RESTORE_APP_PHASE_TIMING app=$(_restore_phase_timing_field "$_app") package=$(_restore_phase_timing_field "$_pkg") stage=$(_restore_phase_timing_field "$_stage") elapsedMs=$_elapsed rc=$_rc detail=$(_restore_phase_timing_field "$_detail") mode=r416"
	if [[ -n ${SPEED_DEBUG_RUN_DIR:-} && -d ${SPEED_DEBUG_RUN_DIR:-} ]]; then
		_tsv="$SPEED_DEBUG_RUN_DIR/restore_app_phase_timing.tsv"
		if [[ ! -f $_tsv ]]; then
			printf 'tsMs\tapp\tpackage\tstage\telapsedMs\trc\tdetail\tmode\n' > "$_tsv" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} || true
		fi
		printf '%s\t%s\t%s\t%s\t%s\t%s\t%s\tr413\n' \
			"$_end" "$(_restore_phase_timing_field "$_app")" "$(_restore_phase_timing_field "$_pkg")" "$(_restore_phase_timing_field "$_stage")" "$_elapsed" "$_rc" "$(_restore_phase_timing_field "$_detail")" \
			>> "$_tsv" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} || true
	fi
}

_procwait_pkg_gone() {
	local _pkg="$1" _timeout_ms="${2:-700}" _stable_ms="${3:-120}" _tag="${4:-pkg_gone}" _user="${5:-${user:-${USER_ID:-0}}}" _out _rc _flat
	[[ -n $_pkg && -x ${EVENT_PROCWAIT_BIN:-} ]] || return 125
	_speedbackup_tool_verify_once procwait 0 >/dev/null 2>&1 || true
	_out="$TMPDIR/.procwait_pkg_gone_${$}_$RANDOM.out"
	"$EVENT_PROCWAIT_BIN" pkg-gone "$_user" "$_pkg" "$_timeout_ms" "$_stable_ms" > "$_out" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	_rc=$?
	_flat="$(tr '\n' '|' < "$_out" 2>/dev/null | cut -c1-500)"
	_speed_debug_log "PROCWAIT_PKG_GONE tag=$_tag pkg=$_pkg user=$_user timeoutMs=$_timeout_ms stableMs=$_stable_ms rc=$_rc out=$_flat mode=r416"
	rm -f "$_out" 2>/dev/null
	return $_rc
}

_procwait_pkg_stable() {
	local _pkg="$1" _timeout_ms="${2:-700}" _stable_ms="${3:-120}" _tag="${4:-pkg_stable}" _user="${5:-${user:-${USER_ID:-0}}}" _out _rc _flat
	[[ -n $_pkg && -x ${EVENT_PROCWAIT_BIN:-} ]] || return 125
	_speedbackup_tool_verify_once procwait 0 >/dev/null 2>&1 || true
	_out="$TMPDIR/.procwait_pkg_stable_${$}_$RANDOM.out"
	"$EVENT_PROCWAIT_BIN" pkg-stable "$_user" "$_pkg" "$_timeout_ms" "$_stable_ms" > "$_out" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	_rc=$?
	_flat="$(tr '\n' '|' < "$_out" 2>/dev/null | cut -c1-500)"
	_speed_debug_log "PROCWAIT_PKG_STABLE tag=$_tag pkg=$_pkg user=$_user timeoutMs=$_timeout_ms stableMs=$_stable_ms rc=$_rc out=$_flat mode=r416"
	rm -f "$_out" 2>/dev/null
	return $_rc
}

_procwait_uid_gone() {
	local _uid="$1" _timeout_ms="${2:-700}" _stable_ms="${3:-120}" _tag="${4:-uid_gone}" _out _rc _flat
	case $_uid in ''|*[!0-9]*) return 2 ;; esac
	[[ -x ${EVENT_PROCWAIT_BIN:-} ]] || return 125
	_speedbackup_tool_verify_once procwait 0 >/dev/null 2>&1 || true
	_out="$TMPDIR/.procwait_uid_gone_${$}_$RANDOM.out"
	"$EVENT_PROCWAIT_BIN" uid-gone "$_uid" "$_timeout_ms" "$_stable_ms" > "$_out" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	_rc=$?
	_flat="$(tr '\n' '|' < "$_out" 2>/dev/null | cut -c1-500)"
	_speed_debug_log "PROCWAIT_UID_GONE tag=$_tag uid=$_uid timeoutMs=$_timeout_ms stableMs=$_stable_ms rc=$_rc out=$_flat mode=r416"
	rm -f "$_out" 2>/dev/null
	return $_rc
}

_restore_procwait_pkg_gone() {
	_procwait_pkg_gone "$@"
}

_restore_speedscan_facts_phase() {
	local _root="$1" _label="$2" _stage="${3:-restore_facts}" _safe _out _summary _t0 _rc _flat
	[[ -n $_root && -d $_root ]] || return 1
	_speedscan_available || return 1
	_safe="$(_process_observer_status_safe_name "${_label:-app}")"
	[[ -n $_safe ]] || _safe=app
	if [[ -n ${SPEED_DEBUG_RUN_DIR:-} && -d ${SPEED_DEBUG_RUN_DIR:-} ]]; then
		_out="$SPEED_DEBUG_RUN_DIR/restore_tree_facts_${_safe}_${$}_$RANDOM.tsv"
		_summary="$SPEED_DEBUG_RUN_DIR/restore_tree_facts_${_safe}_${$}_$RANDOM.summary"
	else
		_out="$TMPDIR/.restore_tree_facts_${$}_$RANDOM.tsv"
		_summary="$TMPDIR/.restore_tree_facts_${$}_$RANDOM.summary"
	fi
	_t0="$(_speed_now_ms)"
	_speedscan_cmd facts "$_root" "$_out" > "$_summary" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	_rc=$?
	_flat="$(tr '\n' ' ' < "$_summary" 2>/dev/null | cut -c1-500)"
	_restore_phase_timing_record "speedscan_tree_facts" "$_t0" "${name1:-$_label}" "${name2:-}" "stage=$_stage root=$_root summary=$_flat out=${_out##*/}" "$_rc"
	[[ -n ${SPEED_DEBUG_RUN_DIR:-} && -d ${SPEED_DEBUG_RUN_DIR:-} ]] || rm -f "$_out" "$_summary" 2>/dev/null
	return $_rc
}

_archive_output_path() {
	local _base="$1" _comp="${2:-$Compression_method}"
	case $_comp in
	tar|Tar|TAR) printf '%s.tar\n' "$_base" ;;
	*) printf '%s.tar.zst\n' "$_base" ;;
	esac
}
_archive_print_ratio() {
	local _base="$1" _origin_size="$2" _comp="${3:-$Compression_method}" _out _out_size _rate
	case $_origin_size in ''|*[!0-9]*|0) return 0 ;; esac
	_out="$(_archive_output_path "$_base" "$_comp")"
	_out_size="$(_local_file_size_debug "$_out")"
	case $_out_size in ''|*[!0-9]*) _out_size=0 ;; esac
	_rate="$(awk -v s="$_out_size" -v f="$_origin_size" 'BEGIN{ if (f>0) printf "%.2f", (1-(s/f))*100; else printf "0.00" }')"
	echoRgb "壓縮率${_rate}% 大小$(size "$_out_size")"
}

# 單檔 stage helper 第一刀：集中 archive 檔名、清理、存在判斷、校驗與壓縮率輸出。
# 目標是先收斂 Backup_apk / Backup_data 裡重複的 .tar/.tar.zst 分支，不改檔名、不改恢復格式。
_archive_exists() {
	local _base="$1" _f
	for _f in "$_base".tar "$_base".tar.zst; do
		[[ -e $_f ]] && return 0
	done
	return 1
}
_archive_cleanup() {
	local _base="$1"
	rm -rf "$_base".tar "$_base".tar.zst "$_base".tar.* 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
}
_backup_mark_done_pkg() {
	[[ -n $TMPDIR && -n $name2 && -n $Backup_folder ]] || return 0
	if ! awk -v p="$name2" '$2==p{f=1} END{exit !f}' "$TMPDIR/.backup_done" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}; then
		echo "${Backup_folder##*/} $name2" >> "$TMPDIR/.backup_done"
	fi
}
_backup_stage_validate_and_ratio() {
	local _entry="$1" _base="$2" _origin_size="$3"
	if stream_enabled; then
		result=0
		echoRgb "${_entry}數據已流式上傳遠端 (大小 $(size "$_origin_size"))" "1"
		return 0
	fi
	Validation_file "$_base.tar"*
	case $result in ''|*[!0-9]*) result=1 ;; esac
	[[ $result = 0 ]] || return "$result"
	case $_origin_size in
	''|0|*[!0-9]*) ;;
	*) _archive_print_ratio "$_base" "$_origin_size" "${_comp_override:-$Compression_method}" ;;
	esac
	case $result in ''|*[!0-9]*) result=1 ;; esac
	return "$result"
}
_backup_data_archive_stage() {
	local _entry="$1" _data_path="$2" _out_base="$3" _dp_name _out_file
	_dp_name="${_data_path##*/}"
	_backup_hard_quiesce_stable_wait "${BACKUP_TAR_CONTEXT_PKG:-${name2:-}}" "${BACKUP_TAR_CONTEXT_LABEL:-${name1:-}}" "$_entry" "before_tar" || true
	case $_entry in
	hma)
		tar_compress_dir "$_out_base" "${_data_path%/*}" "$_dp_name"
		result=$?
		[[ $result = 0 ]] && echo_log "備份HMA-OSS配置" || { Set_back_1; echo_log "備份HMA-OSS配置"; }
		;;
	user|user_de)
		tar_compress_dir "$_out_base" "${_data_path%/*}" "$_dp_name" 			--exclude="$_dp_name/.ota" 			--exclude="$_dp_name/cache" 			--exclude="$_dp_name/lib" 			--exclude="$_dp_name/code_cache" 			--exclude="$_dp_name/no_backup" 			2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
		result=$?
		[[ $result = 0 ]] && echo_log "備份${_entry}數據" || { Set_back_1; echo_log "備份${_entry}數據"; }
		;;
	*)
		tar_compress_dir "$_out_base" "${_data_path%/*}" "$_dp_name" 			--exclude="Backup_*" 			--exclude="$_dp_name/cache" 			--exclude="$_dp_name/QQ" 			--exclude="$_dp_name/Telegram" 			--exclude="$_dp_name/.*"
		result=$?
		_out_file="$(_archive_output_path "$_out_base" "${_comp_override:-$Compression_method}")"
		# Media / Download / Custom_path 這類外部目錄常有檔案邊備份邊變動；tar rc=1 但已產生非 0 備份檔時降級為警告。
		# 164 起同時支援 .tar 與 .tar.zst 輸出判斷，避免 zstd 模式誤把可用輸出當失敗。
		if [[ $result = 1 && -s "$_out_file" ]]; then
			echoRgb "備份${_entry}數據完成，但部分檔案可能在備份期間變動，已降級為警告" "0"
			_speed_debug_log "WARN: 備份${_entry}數據 tar rc=1 but output exists: $_out_file"
			result=0
			Set_back_0
		else
			[[ $result = 0 ]] && echo_log "備份${_entry}數據" || { Set_back_1; echo_log "備份${_entry}數據"; }
		fi
		;;
	esac
	case $result in ''|*[!0-9]*) result=1 ;; esac
	return "$result"
}

# stage runner final：集中 app_details stage 寫入與成功標記。
# 不改 JSON 格式，只把 Backup_data / Backup_apk 內重複 jq 片段收斂到固定入口。
_app_details_update_data_stage() {
	local _entry="$1" _path_value="$2" _size_value="$3" _write_path=""
	[[ -n $zsize ]] && _write_path=1
	_appdetails_set_payload_success "$app_details" "$_entry" "$_path_value" "$_size_value" "$_write_path"
}
_backup_data_stage_record_success() {
	local _entry="$1" _src_path="$2" _size_value="$3"
	[[ ${Backup_folder##*/} = Media ]] && [[ $(sed -e '/^$/d' "$mediatxt" | grep -w "${REPLY##*/}.tar$" | head -1) = "" ]] && echo "$FILE_NAME" >> "$mediatxt"
	_app_details_update_data_stage "$_entry" "$_src_path" "$_size_value"
	backup_has_changes=1
	case $_entry in user|data|obb|user_de|media|thanox|hma) _mark_changed ;; esac
}
_app_details_update_apk_stage() {
	local _old_version="$1" _new_version="$2"
	if [[ -n $_old_version ]]; then
		echoRgb "覆蓋app_details"
	else
		echoRgb "新增app_details"
	fi
	_appdetails_set_apk_meta "$app_details" "$name1" "$name2" "$_new_version"
}
_backup_apk_archive_stage() {
	tar_compress_glob "$Backup_folder/apk" "$apk_path2" "*.apk"
	result=$?
	echo_log "備份$apk_number個Apk"
	if [[ $result = 0 && $remote_stream != 1 ]]; then
		Validation_file "$Backup_folder/apk.tar"*
	fi
	case $result in ''|*[!0-9]*) result=1 ;; esac
	return "$result"
}
_backup_apk_stage_record_success() {
	local _old_version="$1" _new_version="$2"
	_backup_mark_done_pkg
	_app_details_update_apk_stage "$_old_version" "$_new_version"
	backup_has_changes=1
	_mark_changed
	[[ $name2 = com.android.chrome ]] && cleanup_chrome_legacy
}

# tar/glob 共用收尾：維持原 result、debug、manifest 與失敗清單語義。
_tar_stream_finish() {
	local _rb="$1" _comp="$2" _raw_log="$3" _raw_start="$4" _mode="$5" _rc="$6" _final_rc
	case $_rc in ''|*[!0-9]*) _rc=1 ;; esac
	_final_rc="$_rc"
	if [[ $_rc != 0 ]] && _tar_changed_xlog_only "$_raw_log"; then
		_final_rc=0
		_speed_debug_log "TAR_CHANGED_XLOG_SOFT_OK mode=${_mode}-stream rb=$_rb comp=$_comp pkg=${BACKUP_TAR_CONTEXT_PKG:-} entry=${BACKUP_TAR_CONTEXT_ENTRY:-} original_rc=$_rc action=accept_archive"
	fi
	_local_raw_debug_end compress "$_raw_log" "$_final_rc" "$_raw_start" "mode=${_mode}-stream rb=$_rb comp=$_comp original_rc=$_rc"
	_media_backup_perf_done 1 "$_raw_start" "$_final_rc" "$_rb" "comp=$_comp originalRc=$_rc"
	if [[ $_final_rc != 0 ]]; then
		_backup_tar_error_record "$_rb" "$_comp" "$_raw_log" "${_mode}-stream" "$_final_rc"
		echoRgb "流式上傳失敗 ($_rb) 遠端可能未寫入完整, 建議重試" "0" >&2
		echo "${_rb%%/*}" >> "$TMPDIR/.stream_failed"
		echo "${_rb%%/*}: ${_rb#*/}" >> "$TMPDIR/.stream_failed_detail"
		_speed_debug_log "STREAM_PAYLOAD_FAILED app=${_rb%%/*} item=${_rb#*/} pipeline_rc=$_final_rc"
	else
		_manifest_add "$_rb"
	fi
	return "$_final_rc"
}
_tar_local_finish() {
	local _out_base="$1" _comp="$2" _raw_log="$3" _raw_start="$4" _rc="$5" _out_file _out_size _final_rc
	case $_rc in ''|*[!0-9]*) _rc=1 ;; esac
	_final_rc="$_rc"
	_chmod_compressed_output "$_out_base" "$_comp"
	case $_comp in tar|Tar|TAR) _out_file="$_out_base.tar" ;; *) _out_file="$_out_base.tar.zst" ;; esac
	_out_size="$(_local_file_size_debug "$_out_file")"
	if [[ $_rc != 0 ]] && [[ -s $_out_file ]] && _tar_changed_xlog_only "$_raw_log"; then
		_final_rc=0
		_speed_debug_log "TAR_CHANGED_XLOG_SOFT_OK mode=local rb=${_out_base#$Backup/} comp=$_comp pkg=${BACKUP_TAR_CONTEXT_PKG:-} entry=${BACKUP_TAR_CONTEXT_ENTRY:-} original_rc=$_rc out_size=$_out_size action=accept_archive"
	fi
	_local_raw_debug_end compress "$_raw_log" "$_final_rc" "$_raw_start" "out_file=$_out_file out_size=$_out_size original_rc=$_rc"
	_media_backup_perf_done 0 "$_raw_start" "$_final_rc" "${_out_base#$Backup/}" "comp=$_comp originalRc=$_rc outSize=$_out_size"
	[[ $_final_rc != 0 ]] && _backup_tar_error_record "${_out_base#$Backup/}" "$_comp" "$_raw_log" "local" "$_final_rc"
	[[ $_final_rc = 0 ]] && _manifest_add "${_out_base#$Backup/}"
	return "$_final_rc"
}

_backup_tar_safe_name() {
	printf '%s' "$1" | tr '/\\ :\t\r\n' '_______' | tr -cd 'A-Za-z0-9._+-' | cut -c1-96
}

# r309: App label / appList entry path segment sanitizer. Keep user-visible Unicode labels,
# but never allow a label to become path traversal or nested local/remote directories.
_backup_path_safe_name() {
	local _raw="$1" _fallback="$2" _safe
	_safe="$(printf '%s' "$_raw" | tr '/\\ :\t\r\n' '_______' | sed 's/\.\./__/g; s/^[.][.]*$/_/')"
	case "$_safe" in
	''|.|..) _safe="$(printf '%s' "${_fallback:-app}" | tr '/\\ :\t\r\n' '_______' | sed 's/\.\./__/g; s/^[.][.]*$/_/')" ;;
	esac
	case "$_safe" in ''|.|..) _safe="app" ;; esac
	printf '%s' "$_safe"
}

_backup_path_sanitize_current_name() {
	local _orig="${name1:-}" _pkg="${name2:-${PackageName:-}}" _safe
	_safe="$(_backup_path_safe_name "$_orig" "$_pkg")"
	if [[ $_safe != "$_orig" ]]; then
		_speed_debug_log "APP_LABEL_PATH_SANITIZE pkg=$_pkg from=$(_speed_debug_kv "$(_speed_debug_safe "$_orig")") to=$(_speed_debug_kv "$(_speed_debug_safe "$_safe")") mode=r309"
	fi
	name1="$_safe"
}

_backup_tar_error_record() {
	local _rb="$1" _comp="$2" _raw_log="$3" _mode="$4" _rc="$5"
	[[ $_rc = 0 ]] && return 0
	[[ -n ${SPEED_DEBUG_RUN_DIR:-} && -d ${SPEED_DEBUG_RUN_DIR:-} ]] || return 0
	local _pkg="${BACKUP_TAR_CONTEXT_PKG:-${name2:-}}" _label="${BACKUP_TAR_CONTEXT_LABEL:-${name1:-}}" _entry="${BACKUP_TAR_CONTEXT_ENTRY:-}"
	local _safe_pkg _safe_entry _seq _copy _summary _now _pids _pcnt _fg_rc _susp_rc
	[[ -z $_entry ]] && _entry="${_rb#*/}"
	_entry="${_entry%%.tar*}"
	_safe_pkg="$(_backup_tar_safe_name "${_pkg:-unknown}")"
	_safe_entry="$(_backup_tar_safe_name "${_entry:-unknown}")"
	_seq="$(_remote_debug_seq tar_error 2>/dev/null)"
	[[ -z $_seq ]] && _seq="$(date +%s 2>/dev/null)_$$"
	_copy="$SPEED_DEBUG_RUN_DIR/tar_error_${_seq}_${_safe_pkg}_${_safe_entry}.log"
	_summary="$SPEED_DEBUG_RUN_DIR/tar_error_records.log"
	_now="$(date '+%Y-%m-%d %H:%M:%S' 2>/dev/null)"
	{
		echo "===== TAR_ERROR tag=$_seq time=$_now rc=$_rc mode=$_mode comp=$_comp rb=$_rb app=$_label package=$_pkg entry=$_entry ====="
		echo "raw_log=$_raw_log"
		echo "stream=${remote_stream:-0} remote_type=${remote_type:-none} backup_folder=${Backup_folder:-} data_path=${data_path:-}"
	} >> "$_summary" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	if [[ -s $_raw_log ]]; then
		{
			echo "===== RAW_LOG_TAIL_BEGIN raw=$_raw_log ====="
			tail -n 200 "$_raw_log" 2>/dev/null
			echo "===== RAW_LOG_TAIL_END ====="
		} >> "$_copy" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
		{
			echo "raw_tail=$_copy"
			echo "raw_last_40_begin"
			tail -n 40 "$_raw_log" 2>/dev/null
			echo "raw_last_40_end"
		} >> "$_summary" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	else
		echo "raw_log_missing_or_empty=$_raw_log" >> "$_summary" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	fi
	if [[ -n $_pkg ]]; then
		_pids="$(_pkg_process_pids "$_pkg" 2>/dev/null)"
		_pcnt="$(printf '%s\n' "$_pids" | awk 'NF{n++} END{print n+0}' 2>/dev/null)"
		_foreground_state_pkg_active "$_pkg" >/dev/null 2>&1; _fg_rc=$?
		_pkg_suspend_state_daemon "$_pkg" "${user:-0}" >/dev/null 2>&1; _susp_rc=$?
		{
			echo "post_error_process_count=${_pcnt:-0} pids=$(printf '%s' "$_pids" | tr '\n' ',') foreground_rc=$_fg_rc suspend_rc=$_susp_rc"
			echo "process_snapshot_begin"
			Process_Information "$_pkg" 2>/dev/null || true
			echo "process_snapshot_end"
		} >> "$_summary" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	fi
	_speed_debug_log "TAR_ERROR_RECORD tag=$_seq app=$_label package=$_pkg entry=$_entry rc=$_rc mode=$_mode raw=${_raw_log##*/} saved=${_copy##*/}"
	return 0
}


# 壓縮 helper (取代散落各處的 tar/zstd case 分支)

_tar_changed_retry_enabled() {
	case "${SPEEDBACKUP_TAR_CHANGED_RETRY:-1}" in
	0|false|FALSE|no|NO|off|OFF|disable|DISABLE) return 1 ;;
	esac
	return 0
}

_tar_raw_last_op_changed_as_read_only() {
	local _raw_log="$1"
	[[ -s $_raw_log ]] || return 1
	awk '
		/^BEGIN kind=compress/ { hit=0; other=0; next }
		/^tar: .*file changed as we read it/ { hit=1; next }
		/^tar: / { other=1; next }
		END { exit (hit && !other) ? 0 : 1 }
	' "$_raw_log" 2>/dev/null
}

_tar_changed_xlog_soft_ok_enabled() {
	case "${SPEEDBACKUP_TAR_CHANGED_XLOG_SOFT_OK:-1}" in
	0|false|FALSE|no|NO|off|OFF|disable|DISABLE) return 1 ;;
	esac
	return 0
}

_tar_changed_xlog_only() {
	local _raw_log="$1" _pkg="${BACKUP_TAR_CONTEXT_PKG:-${name2:-}}" _entry="${BACKUP_TAR_CONTEXT_ENTRY:-}"
	_tar_changed_xlog_soft_ok_enabled || return 1
	[[ -s $_raw_log ]] || return 1
	case $_entry in user|user_de) ;; *) return 1 ;; esac
	case $_pkg in
	com.tencent.mm|com.tencent.mobileqq|com.tencent.tim|com.tencent.wework) ;;
	*) return 1 ;;
	esac
	awk '
		/^BEGIN kind=compress/ { hit=0; bad=0; next }
		/^tar: .*file changed as we read it/ {
			line=$0
			sub(/^tar: /, "", line)
			sub(/: file changed as we read it$/, "", line)
			if (line ~ /\/files\/xlog\/[^\/][^\/]*\.xlog$/) hit=1
			else bad=1
			next
		}
		/^tar: / { bad=1; next }
		END { exit (hit && !bad) ? 0 : 1 }
	' "$_raw_log" 2>/dev/null
}

_tar_changed_retry_quiesce() {
	local _pkg="${BACKUP_TAR_CONTEXT_PKG:-}" _entry="${BACKUP_TAR_CONTEXT_ENTRY:-}" _label="${BACKUP_TAR_CONTEXT_LABEL:-}" _sleep
	[[ -n $_pkg ]] || return 0
	_speed_debug_log "TAR_CHANGED_RETRY_QUIESCE pkg=$_pkg label=$_label entry=$_entry"
	if _speedbackup_hard_freeze_pkg "$_pkg" || _speedbackup_cgroup_fast_settle_default_home_pkg "$_pkg" || _speedbackup_cgroup_fast_settle_default_ime_pkg "$_pkg"; then
		_speed_debug_log "HIGH_RISK_BACKUP_GUARD_MISS package=$_pkg label=$_label entry=$_entry reason=tar_changed_as_read fallback=retry_after_guard mode=r370"
	fi
	_force_stop_pkg_best_effort "$_pkg" "tar_changed_retry_quiesce" >/dev/null 2>&1 || true
	_backup_hard_quiesce_stable_wait "$_pkg" "$_label" "$_entry" "tar_changed_retry" || true
	_sleep="${SPEEDBACKUP_TAR_CHANGED_RETRY_SLEEP:-1}"
	case $_sleep in
	''|*[!0-9]*) _sleep=1 ;;
	esac
	case $_sleep in
	0) : ;;
	*) sleep "$_sleep" 2>/dev/null || sleep 1 ;;
	esac
}

# 用法 1 (目錄打包): tar_compress_dir <輸出檔基礎名> <切到目錄> <要打包名> [tar 額外參數...]
#   例: tar_compress_dir "$folder/user" "${dp%/*}" "${dp##*/}" --exclude=cache
# 用法 2 (glob 打包): tar_compress_glob <輸出檔基礎名> <切到目錄> <glob 模式>
#   例: tar_compress_glob "$folder/apk" "$apk_path2" "*.apk"
# 自動依 $Compression_method 決定輸出 .tar 還是 .tar.zst
# 若呼叫前設了局部變數 _comp_override, 優先使用它 (取代暫時修改全域 Compression_method 再復原的舊做法)
tar_compress_dir() {
	local out_base="$1" cd_to="$2" pack_name="$3" result
	shift 3
	local _comp="${_comp_override:-$Compression_method}"
	# 流式模式 (remote_stream=1): 直接管道到遠端, 不寫本機 (省空間)
	# _STREAM_DEST 由呼叫端設為遠端目標目錄 (相對遠端根)
	if stream_enabled && [[ -n $_STREAM_DEST ]]; then
		{
			echoRgb "流式傳輸中 (邊壓邊傳, 不佔本機)..." "3" >/dev/tty 2>/dev/null ||
				_speed_debug_log "STREAM_TRANSFER_NOTICE out_base=$out_base comp=$_comp dest=$_STREAM_DEST"
		}
		local _rb="$_STREAM_DEST/${out_base##*/}" _stream_rel _stream_raw_log _stream_start _stream_rc _stream_pid
		case $_comp in tar|Tar|TAR) _stream_rel="$_rb.tar" ;; *) _stream_rel="$_rb.tar.zst" ;; esac
		_stream_start="$(date +%s%3N 2>/dev/null)"; case $_stream_start in ''|*[!0-9]*) _stream_start="$(date +%s 2>/dev/null)000" ;; esac
		_stream_raw_log="$(_local_raw_debug_begin compress "mode=dir-stream comp=$_comp out_base=$out_base cd_to=$cd_to pack=$pack_name extra=$*")"
		[[ ! -d ${out_base%/*} ]] && mkdir -p "${out_base%/*}" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
		_process_observer_start_payload "${BACKUP_TAR_CONTEXT_PKG:-}" "${BACKUP_TAR_CONTEXT_LABEL:-}" "${BACKUP_TAR_CONTEXT_ENTRY:-}" "backup-dir-stream" || true
		# 443: suppress GNU tar ignored-file warnings such as "socket ignored".
		# 445: stream tar/zstd stderr goes to compress_raw.log, not the main stderr.log.
		case $_comp in
		tar|Tar|TAR)
			( set -o pipefail 2>/dev/null; tar --checkpoint-action="ttyout=%T\r" --warning=no-file-ignored \
				"$@" -cpf - -C "$cd_to" "$pack_name" 2>>"$_stream_raw_log" | _stream_upload "$_stream_rel" ) & _stream_pid=$!
			;;
		zstd|Zstd|ZSTD)
			( set -o pipefail 2>/dev/null; tar --checkpoint-action="ttyout=%T\r" --warning=no-file-ignored \
				"$@" -cpf - -C "$cd_to" "$pack_name" 2>>"$_stream_raw_log" | \
				zstd --ultra -3 -T0 -q --priority=rt 2>>"$_stream_raw_log" | _stream_upload "$_stream_rel" ) & _stream_pid=$!
			;;
		esac
			_remote_stream_wait_pid_busy_abortable "$_stream_pid" "正在流式傳輸 ${_stream_rel##*/}" "backup_stream_${_stream_rel##*/}" "" 1 ""
			result=$?; _stream_rc="$result"
			case $_stream_rc in ''|*[!0-9]*) _stream_rc=1 ;; esac
		if [[ $_stream_rc != 0 ]] && _tar_changed_xlog_only "$_stream_raw_log"; then
			_speed_debug_log "TAR_CHANGED_RETRY_SKIP_XLOG_SOFT_OK mode=dir-stream rb=$_rb comp=$_comp pkg=${BACKUP_TAR_CONTEXT_PKG:-} entry=${BACKUP_TAR_CONTEXT_ENTRY:-} rc=$_stream_rc action=accept_first_upload"
		elif [[ $_stream_rc != 0 ]] && _tar_changed_retry_enabled && _tar_raw_last_op_changed_as_read_only "$_stream_raw_log"; then
			_local_raw_debug_end compress "$_stream_raw_log" "$_stream_rc" "$_stream_start" "mode=dir-stream rb=$_rb comp=$_comp attempt=1 retry=changed-as-read"
			_speed_debug_log "TAR_CHANGED_RETRY_BEGIN mode=dir-stream rb=$_rb comp=$_comp pkg=${BACKUP_TAR_CONTEXT_PKG:-} entry=${BACKUP_TAR_CONTEXT_ENTRY:-}"
			_tar_changed_retry_quiesce
			_stream_start="$(date +%s%3N 2>/dev/null)"; case $_stream_start in ''|*[!0-9]*) _stream_start="$(date +%s 2>/dev/null)000" ;; esac
			_stream_raw_log="$(_local_raw_debug_begin compress "mode=dir-stream-retry comp=$_comp out_base=$out_base cd_to=$cd_to pack=$pack_name extra=$*")"
			case $_comp in
			tar|Tar|TAR)
				( set -o pipefail 2>/dev/null; tar --checkpoint-action="ttyout=%T\r" --warning=no-file-ignored \
					"$@" -cpf - -C "$cd_to" "$pack_name" 2>>"$_stream_raw_log" | _stream_upload "$_rb.tar" ) & _stream_pid=$!
				;;
			zstd|Zstd|ZSTD)
				( set -o pipefail 2>/dev/null; tar --checkpoint-action="ttyout=%T\r" --warning=no-file-ignored \
					"$@" -cpf - -C "$cd_to" "$pack_name" 2>>"$_stream_raw_log" | \
					zstd --ultra -3 -T0 -q --priority=rt 2>>"$_stream_raw_log" | _stream_upload "$_rb.tar.zst" ) & _stream_pid=$!
				;;
			esac
				_remote_stream_wait_pid_busy_abortable "$_stream_pid" "正在流式重試傳輸 ${_rb##*/}" "backup_stream_retry_${_rb##*/}" "" 1 ""
				result=$?; _stream_rc="$result"
				case $_stream_rc in ''|*[!0-9]*) _stream_rc=1 ;; esac
			_speed_debug_log "TAR_CHANGED_RETRY_END mode=dir-stream rb=$_rb rc=$_stream_rc"
		fi
		_process_observer_stop_current "$_stream_rc" || true
		_tar_stream_finish "$_rb" "$_comp" "$_stream_raw_log" "$_stream_start" dir "$_stream_rc"
		return $?
	fi
	local _raw_log _raw_start _local_rc
	_raw_start="$(date +%s%3N 2>/dev/null)"; case $_raw_start in ''|*[!0-9]*) _raw_start="$(date +%s 2>/dev/null)000" ;; esac
	_raw_log="$(_local_raw_debug_begin compress "mode=dir comp=$_comp out_base=$out_base cd_to=$cd_to pack=$pack_name extra=$*")"
	_process_observer_start_payload "${BACKUP_TAR_CONTEXT_PKG:-}" "${BACKUP_TAR_CONTEXT_LABEL:-}" "${BACKUP_TAR_CONTEXT_ENTRY:-}" "backup-dir-local" || true
	case $_comp in
	tar|Tar|TAR)
		tar --checkpoint-action="ttyout=%T\r" --warning=no-file-ignored \
			"$@" -cpf "$out_base.tar" -C "$cd_to" "$pack_name" 2>>"$_raw_log"
		;;
	zstd|Zstd|ZSTD)
		( set -o pipefail 2>/dev/null; tar --checkpoint-action="ttyout=%T\r" --warning=no-file-ignored \
			"$@" -cpf - -C "$cd_to" "$pack_name" 2>>"$_raw_log" | \
			zstd --ultra -3 -T0 -q --priority=rt 2>>"$_raw_log" > "$out_base.tar.zst" )
		;;
	esac
	result=$?; _local_rc="$result"
	case $_local_rc in ''|*[!0-9]*) _local_rc=1 ;; esac
	if [[ $_local_rc != 0 ]] && [[ -s ${out_base}.tar || -s ${out_base}.tar.zst ]] && _tar_changed_xlog_only "$_raw_log"; then
		_speed_debug_log "TAR_CHANGED_RETRY_SKIP_XLOG_SOFT_OK mode=dir rb=${out_base#$Backup/} comp=$_comp pkg=${BACKUP_TAR_CONTEXT_PKG:-} entry=${BACKUP_TAR_CONTEXT_ENTRY:-} rc=$_local_rc action=accept_first_archive"
	elif [[ $_local_rc != 0 ]] && _tar_changed_retry_enabled && _tar_raw_last_op_changed_as_read_only "$_raw_log"; then
		_local_raw_debug_end compress "$_raw_log" "$_local_rc" "$_raw_start" "mode=dir rb=${out_base#$Backup/} comp=$_comp attempt=1 retry=changed-as-read"
		_speed_debug_log "TAR_CHANGED_RETRY_BEGIN mode=dir rb=${out_base#$Backup/} comp=$_comp pkg=${BACKUP_TAR_CONTEXT_PKG:-} entry=${BACKUP_TAR_CONTEXT_ENTRY:-}"
		_tar_changed_retry_quiesce
		_raw_start="$(date +%s%3N 2>/dev/null)"; case $_raw_start in ''|*[!0-9]*) _raw_start="$(date +%s 2>/dev/null)000" ;; esac
		_raw_log="$(_local_raw_debug_begin compress "mode=dir-retry comp=$_comp out_base=$out_base cd_to=$cd_to pack=$pack_name extra=$*")"
		case $_comp in
		tar|Tar|TAR)
			tar --checkpoint-action="ttyout=%T\r" --warning=no-file-ignored \
				"$@" -cpf "$out_base.tar" -C "$cd_to" "$pack_name" 2>>"$_raw_log"
			;;
		zstd|Zstd|ZSTD)
			( set -o pipefail 2>/dev/null; tar --checkpoint-action="ttyout=%T\r" --warning=no-file-ignored \
				"$@" -cpf - -C "$cd_to" "$pack_name" 2>>"$_raw_log" | \
				zstd --ultra -3 -T0 -q --priority=rt 2>>"$_raw_log" > "$out_base.tar.zst" )
			;;
		esac
		result=$?; _local_rc="$result"
		case $_local_rc in ''|*[!0-9]*) _local_rc=1 ;; esac
		_speed_debug_log "TAR_CHANGED_RETRY_END mode=dir rb=${out_base#$Backup/} rc=$_local_rc"
	fi
	_process_observer_stop_current "$_local_rc" || true
	_tar_local_finish "$out_base" "$_comp" "$_raw_log" "$_raw_start" "$_local_rc"
	return $?
}
# 記錄本次成功備份的檔案 (相對路徑不含副檔名, 例 1DM+/apk), 供結尾計數核驗
_manifest_add() {
	[[ -z $1 ]] && return
	# 第一次加入 manifest 時檔案可能尚未存在；不能直接 awk 讀不存在檔，否則 stderr.log 會出現
	# awk: /data/local/tmp/.backup_manifest: No such file or directory
	if [[ ! -f "$TMPDIR/.backup_manifest" ]]; then
		echo "$1" > "$TMPDIR/.backup_manifest"
		return 0
	fi
	if ! awk -v p="$1" '$0==p{f=1} END{exit !f}' "$TMPDIR/.backup_manifest" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}; then
		echo "$1" >> "$TMPDIR/.backup_manifest"
	fi
}

# app_details.json 健全度檢查。
# 新格式以每個 App entry 的 app_state（schemaVersion=2）為唯一 App 狀態來源。
# 舊備份僅記弱提示；恢復時由單一 legacy→schema2 轉換器讀入，不再走舊 Dex/token 協定。
_json_health_check() {
	local _file="$1" _name="$2" _pkg _ver _state_count _legacy_count _has_ssaid _issues="" _hints=""
	[[ ! -s $_file ]] && { echo "$_name: app_details.json 不存在或為空" >> "$TMPDIR/.json_health_issues"; return; }
	if ! _appdetails_json_parse_ok "$_file"; then
		echo "$_name: json 格式損壞 (無法解析)" >> "$TMPDIR/.json_health_issues"
		return
	fi
	_pkg="$(_appdetails_get_first_pkg "$_file")"
	_ver="$(_appdetails_get_first_apk_version "$_file")"
	_state_count="$(_appdetails_count_state "$_file")"
	_legacy_count="$(_appdetails_count_legacy_state "$_file")"
	_has_ssaid="$(_appdetails_count_appstate_ssaid "$_file")"
	case $_state_count in ''|*[!0-9]*) _state_count=0 ;; esac
	case $_legacy_count in ''|*[!0-9]*) _legacy_count=0 ;; esac
	case $_has_ssaid in ''|*[!0-9]*) _has_ssaid=0 ;; esac
	[[ -z $_pkg ]] && _issues="$_issues 缺PackageName"
	[[ -z $_ver ]] && _issues="$_issues 缺apk_version"
	if [[ $_state_count -gt 0 ]]; then
		if ! _appdetails_appstate_schema_ok "$_file"; then
			_issues="$_issues app_state schema/型態異常"
		fi
		if ! _appdetails_appstate_items_ok "$_file"; then
			_issues="$_issues app_state項目型態異常"
		fi
		if ! _appdetails_nullable_appstate_ok "$_file"; then
			_issues="$_issues app_state缺nullable標準欄位"
		fi
	else
		if [[ $_legacy_count -gt 0 ]]; then
			_hints="$_hints 舊版AppState格式（恢復時單次轉schema2）"
		else
			# 舊版/精簡 app_details 可能只有 APK/data 基本資訊，沒有權限狀態快照。
			# 只要 PackageName/apk_version 仍完整，就不視為損壞；恢復時只是不會有 AppState 可還原。
			if [[ -n $_issues ]]; then
				_issues="$_issues 缺app_state"
			else
				_hints="$_hints 精簡app_details未記錄AppState（非阻斷；重備後可補全權限狀態）"
			fi
		fi
	fi
	[[ -n $_issues ]] && echo "$_name:$_issues" >> "$TMPDIR/.json_health_issues"
	[[ $_state_count -gt 0 && $_has_ssaid -eq 0 ]] && _hints="$_hints SSAID無備份值"
	[[ -n $_hints ]] && echo "$_name:$_hints" >> "$TMPDIR/.json_health_hints"
}
# 彙整顯示流式備份失敗清單。
# 注意: 這裡的失敗不一定是 WebDAV PUT 失敗，也可能是 tar/zstd 在封包期間回傳非 0；
# 此時遠端可能已收到一個檔案，但 app_details 不會更新，下次會重備該 app，避免把不完整資料標記為有效。
_stream_failed_report() {
	[[ ! -s $TMPDIR/.stream_failed_detail ]] && return 0
	local _cnt
	_cnt="$(sort -u "$TMPDIR/.stream_failed_detail" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} | grep -vc '^$' 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null})"
	case $_cnt in ''|*[!0-9]*) _cnt=0 ;; esac
	[[ $_cnt -le 0 ]] && return 0
	echoRgb "⚠️ 本輪有 $_cnt 筆流式備份資料失敗，以下應用下次會重新備份:" "0"
	sort -u "$TMPDIR/.stream_failed_detail" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} | while read -r _line; do
		[[ -n $_line ]] && echoRgb "$_line" "0"
	done
	echoRgb "上述項目未更新遠端 app_details.json，避免不完整資料被視為有效備份" "2"
}

# 彙整顯示 json 健全度檢查結果 (呼叫端在所有 _json_health_check 跑完後呼叫一次)
_json_health_report() {
	local _has_hints=0 _invalid_count _missing_count _checked_count
	[[ -s $TMPDIR/.json_health_hints ]] && _has_hints=1
	_invalid_count="${JSON_HEALTH_INVALID_COUNT:-0}"
	_missing_count="${JSON_HEALTH_MISSING_COUNT:-0}"
	_checked_count="${JSON_HEALTH_CHECKED_COUNT:-}"
	case $_invalid_count in ''|*[!0-9]*) _invalid_count=0 ;; esac
	case $_missing_count in ''|*[!0-9]*) _missing_count=0 ;; esac
	if [[ -s $TMPDIR/.json_health_issues || $_has_hints = 1 || ${JSON_HEALTH_REPORT_ALWAYS:-0} = 1 || $_invalid_count -gt 0 || $_missing_count -gt 0 ]]; then
		echoRgb "—————— JSON健全度檢查 ——————" "3"
	fi
	if [[ ! -s $TMPDIR/.json_health_issues && $_has_hints != 1 ]]; then
		if [[ $_invalid_count -gt 0 || $_missing_count -gt 0 ]]; then
			echoRgb "⚠️ 遠端app_details無效/下載不完整 $((_invalid_count + _missing_count)) 個，已略過，不納入損壞回報" "2"
			if [[ -s $TMPDIR/.json_health_remote_drops ]]; then
				echoRgb "遠端app_details異常清單:" "2"
				sort -u "$TMPDIR/.json_health_remote_drops" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} | while read -r _drop; do
					[[ -n $_drop ]] && echoRgb "$_drop" "2"
				done
				rm -f "$TMPDIR/.json_health_remote_drops" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
			fi
		else
			if [[ ${JSON_HEALTH_REPORT_ALWAYS:-0} = 1 ]]; then
				if [[ -n $_checked_count ]]; then
					echoRgb "✅ JSON健全度檢查通過 $_checked_count/$_checked_count" "1"
				else
					echoRgb "✅ JSON健全度檢查通過" "1"
				fi
			fi
		fi
		unset JSON_HEALTH_REPORT_ALWAYS JSON_HEALTH_CHECKED_COUNT JSON_HEALTH_INVALID_COUNT JSON_HEALTH_MISSING_COUNT
		return
	fi
	if [[ -s $TMPDIR/.json_health_issues ]]; then
		local _cnt
		_cnt="$(grep -vc '^$' "$TMPDIR/.json_health_issues" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null})"
		echoRgb "⚠️ 發現 $_cnt 個app的app_details.json缺少必要欄位:" "0"
		while read -r _line; do
			[[ -n $_line ]] && echoRgb "$_line" "0"
		done < "$TMPDIR/.json_health_issues"
		echoRgb "上述app建議重新執行一次備份以補全資訊" "0"
		rm -f "$TMPDIR/.json_health_issues"
	fi
	if [[ $_has_hints = 1 ]]; then
		local _hcnt _limit=20
		_hcnt="$(grep -vc '^$' "$TMPDIR/.json_health_hints" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null})"
		case $_hcnt in ''|*[!0-9]*) _hcnt=0 ;; esac
		# 大量舊版備份會產生很多弱提示；完整清單留在 debug，終端只顯示摘要與前幾筆，避免誤會成失敗。
		if [[ -n ${SPEED_DEBUG_RUN_DIR:-} && -d ${SPEED_DEBUG_RUN_DIR:-} ]]; then
			cp -f "$TMPDIR/.json_health_hints" "$SPEED_DEBUG_RUN_DIR/json_health_hints.log" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} || true
		fi
		if [[ $_hcnt -gt $_limit ]]; then
			echoRgb "$_hcnt 個app為舊版/精簡 app_details 或缺少次要欄位（非阻斷；完整清單已寫入 debug）" "2"
			awk -v limit="$_limit" 'NF && NR<=limit {print}' "$TMPDIR/.json_health_hints" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} | while read -r _hline; do
				[[ -n $_hline ]] && echoRgb "$_hline" "2"
			done
			echoRgb "其餘 $((_hcnt - _limit)) 筆已省略，非阻斷" "2"
		else
			echoRgb "$_hcnt 個app有部分次要欄位未紀錄 (可能該app本來就沒有, 非異常):" "2"
			while read -r _hline; do
				[[ -n $_hline ]] && echoRgb "$_hline" "2"
			done < "$TMPDIR/.json_health_hints"
		fi
		rm -f "$TMPDIR/.json_health_hints"
	fi
	if [[ $_invalid_count -gt 0 || $_missing_count -gt 0 ]]; then
		echoRgb "⚠️ 遠端app_details無效/下載不完整 $((_invalid_count + _missing_count)) 個，已略過，不納入損壞回報" "2"
		if [[ -s $TMPDIR/.json_health_remote_drops ]]; then
			echoRgb "遠端app_details異常清單:" "2"
			sort -u "$TMPDIR/.json_health_remote_drops" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} | while read -r _drop; do
				[[ -n $_drop ]] && echoRgb "$_drop" "2"
			done
			rm -f "$TMPDIR/.json_health_remote_drops" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
		fi
	fi
	unset JSON_HEALTH_REPORT_ALWAYS JSON_HEALTH_CHECKED_COUNT JSON_HEALTH_INVALID_COUNT JSON_HEALTH_MISSING_COUNT
}

# 最終檔案計數核驗: 本次備份的檔案逐一確認存在 (本地 [[ -f ]] / 遠端流式下載驗證), 顯示數量

# 遠端 app_details JSON 完整性判斷。
# 用於 WebDAV/SMB 遠端健康檢查與快取防線：必須是完整 JSON object，且至少含 PackageName + apk_version。
_remote_appdetails_json_ok() {
	local _f="$1"
	[[ -s $_f ]] || return 1
	# r283: ad_required_meta_ok is executed by jq; parse errors already return non-zero.
	# Avoid a separate jq parse pass on every app_details.json.
	_appdetails_has_required_meta "$_f"
}

_remote_health_record_appdetails_drop() {
	# 466/r17: 遠端 JSON 缺失/損壞清單輸出集中，避免 restore/list/upload 三處格式漂移。
	local _app="$1" _key="$2" _kind="$3" _file="${4:-}"
	[[ -n $_key ]] || _key="$_app"
	case $_kind in
	invalid)
		_speed_debug_log "REMOTE_HEALTH_APPDETAILS_INVALID_DROP app=$_app key=$_key file=$_file"
		echo "$_app (遠端): app_details.json 無效/下載不完整 ($_key/app_details.json)" >> "$TMPDIR/.json_health_remote_drops"
		;;
	missing|*)
		_speed_debug_log "REMOTE_HEALTH_APPDETAILS_MISSING app=$_app key=$_key"
		echo "$_app (遠端): app_details.json 缺失或下載失敗 ($_key/app_details.json)" >> "$TMPDIR/.json_health_remote_drops"
		;;
	esac
}

verify_backup_manifest() {
	[[ ! -s $TMPDIR/.backup_manifest ]] && return
	local _mf="$TMPDIR/.backup_manifest" _ext _expect _found=0 _miss=""
	case $Compression_method in
	zstd|Zstd|ZSTD) _ext=".tar.zst" ;;
	*) _ext=".tar" ;;
	esac
	_expect="$(grep -vc '^$' "$_mf")"
	echoRgb "—————— 最終檔案計數核驗 ——————" "3"
	local _remote_chk=0
	if [[ $remote_stream = 1 ]]; then
		_remote_chk=1
	fi
	if [[ $_remote_chk = 1 ]]; then
		if _remote_netwatch_mark_stream_fatal "verify_manifest_enter" "verify_manifest" || _remote_stream_fatal_active; then
			echoRgb "遠端流式已中斷，跳過最終遠端檔案計數核驗" "0"
			_speed_debug_log "VERIFY_MANIFEST_REMOTE_SKIP reason=remote_stream_fatal $(_remote_stream_fatal_summary)"
			return 0
		fi
		local _rel _head _vlist _verify_by_notes=0
		case "${SPEEDBACKUP_STREAM_MANIFEST_STRICT_RELIST:-0}" in
		1|true|TRUE|yes|YES|on|ON) _verify_by_notes=0 ;;
		*) [[ -f $TMPDIR/.remote_files ]] && _verify_by_notes=1 ;;
		esac
		if [[ $_verify_by_notes = 1 ]]; then
			# r364: 本輪成功 PUT 筆記和遠端初始列表共用 .remote_files；
			# note fast path 只驗本輪筆記，不要求 .remote_filelist_ok，避免全新 WebDAV 目錄初始 classify 失敗/空列表後，
			# 已成功上傳的 payload 被誤報 0/全部缺失。
			echoRgb "核驗遠端檔案 (快速: 本輪上傳成功記錄)..." "3"
			_speed_debug_log "VERIFY_MANIFEST_REMOTE_NOTE_FAST_BEGIN expect=$_expect source=remote_files_notes strict_relist=0 mode=r370"
			while read -r _rel; do
				[[ -z $_rel ]] && continue
				if ! _remote_files_note_has_any_rel "$_rel$_ext" "$_rel.tar"; then
					_miss="$_miss$_rel$_ext\n"
				fi
			done <<EOF3
$(cat "$_mf")
EOF3
			_miss="$(echo -e "$_miss" | grep -v '^$')"
			_speed_debug_log "VERIFY_MANIFEST_REMOTE_NOTE_FAST_END expect=$_expect miss=$(echo "$_miss" | grep -vc '^$') mode=r370"
		else
			# 遠端核驗: 重抓一次遠端列表 (單連線), 逐項比對存在性
			echoRgb "核驗遠端檔案 (單次列表)..." "3"
			_vlist="$TMPDIR/.verify_files"
			remote_list_files "$(get_backup_dirname)" > "$_vlist" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
			while read -r _rel; do
				[[ -z $_rel ]] && continue
				if ! awk -v a="$_rel$_ext" -v b="$_rel.tar" '$0==a||$0==b{f=1;exit} END{exit !f}' "$_vlist" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}; then
					# 列表沒找到: 單檔下載開頭再確認一次 (smbclient 列表對中文名轉碼毀名, 避免誤報)
					_head="$(_stream_download "$(get_backup_dirname)/$_rel$_ext" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} | head -c 60)"
					case $_head in
					""|*NT_STATUS*) _miss="$_miss$_rel$_ext\n" ;;
					esac
				fi
			done <<EOF3
$(cat "$_mf")
EOF3
			_miss="$(echo -e "$_miss" | grep -v '^$')"
			rm -f "$_vlist"
		fi
	else
		# 本地核驗
		local _rel
		while read -r _rel; do
			[[ -z $_rel ]] && continue
			if [[ ! -f $Backup/$_rel.tar.zst && ! -f $Backup/$_rel.tar ]]; then
				_miss="$_miss$_rel$_ext\n"
			fi
		done <<EOF3
$(cat "$_mf")
EOF3
		_miss="$(echo -e "$_miss" | grep -v '^$')"
	fi
	local _misscnt
	_misscnt="$(echo "$_miss" | grep -vc '^$')"
	_found=$((_expect - _misscnt))
	if [[ $_misscnt -eq 0 ]]; then
		echoRgb "✅ 應有 $_expect 個檔案, 實際存在 $_expect 個" "1"
	else
		echoRgb "⚠️ 應有 $_expect 個檔案, 實際存在 $_found 個, 缺失 $_misscnt 個:" "0"
		echo "$_miss" | while read -r _m; do [[ -n $_m ]] && echoRgb "$_m" "0"; done
	fi
	rm -f "$_mf"
}

tar_compress_glob() {
	local out_base="$1" cd_to="$2" pattern="$3"
	# 第4參數可選: 覆寫本次使用的壓縮方式 (不傳則用全域 Compression_method)
	# 讓呼叫端可以針對單次打包指定方式, 不需要暫時修改全域變數再復原
	local _comp="${4:-$Compression_method}"
	# 流式模式
	if stream_enabled && [[ -n $_STREAM_DEST ]]; then
		{
			echoRgb "流式傳輸中 (邊壓邊傳, 不佔本機)..." "3" >/dev/tty 2>/dev/null ||
				_speed_debug_log "STREAM_TRANSFER_NOTICE out_base=$out_base comp=$_comp dest=$_STREAM_DEST"
		}
		local _rb="$_STREAM_DEST/${out_base##*/}" _stream_rel _stream_raw_log _stream_start _stream_rc _stream_pid
		case $_comp in tar|Tar|TAR) _stream_rel="$_rb.tar" ;; *) _stream_rel="$_rb.tar.zst" ;; esac
		_stream_start="$(date +%s%3N 2>/dev/null)"; case $_stream_start in ''|*[!0-9]*) _stream_start="$(date +%s 2>/dev/null)000" ;; esac
		_stream_raw_log="$(_local_raw_debug_begin compress "mode=glob-stream comp=$_comp out_base=$out_base cd_to=$cd_to pattern=$pattern")"
		[[ ! -d ${out_base%/*} ]] && mkdir -p "${out_base%/*}" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
		(
			cd "$cd_to" || exit 1
			# 443: suppress GNU tar ignored-file warnings such as "socket ignored".
			# 445: stream tar/zstd stderr goes to compress_raw.log, not the main stderr.log.
			case $_comp in
			tar|Tar|TAR)
				( set -o pipefail 2>/dev/null; tar --checkpoint-action="ttyout=%T\r" --warning=no-file-ignored -cf - $pattern 2>>"$_stream_raw_log" | _stream_upload "$_stream_rel" )
				;;
			zstd|Zstd|ZSTD)
				( set -o pipefail 2>/dev/null; tar --checkpoint-action="ttyout=%T\r" --warning=no-file-ignored -cf - $pattern 2>>"$_stream_raw_log" | \
					zstd --ultra -3 -T0 -q --priority=rt 2>>"$_stream_raw_log" | _stream_upload "$_stream_rel" )
				;;
			esac
		) & _stream_pid=$!
		_remote_stream_wait_pid_busy_abortable "$_stream_pid" "正在流式傳輸 ${_stream_rel##*/}" "backup_glob_stream_${_stream_rel##*/}" "" 1 ""
		result=$?; _stream_rc="$result"
		case $_stream_rc in ''|*[!0-9]*) _stream_rc=1 ;; esac
		_tar_stream_finish "$_rb" "$_comp" "$_stream_raw_log" "$_stream_start" glob "$_stream_rc"
		return $?
	fi
	local _raw_log _raw_start _local_rc
	_raw_start="$(date +%s%3N 2>/dev/null)"; case $_raw_start in ''|*[!0-9]*) _raw_start="$(date +%s 2>/dev/null)000" ;; esac
	_raw_log="$(_local_raw_debug_begin compress "mode=glob comp=$_comp out_base=$out_base cd_to=$cd_to pattern=$pattern")"
	(
		cd "$cd_to" || return 1
		case $_comp in
		tar|Tar|TAR)
			tar --checkpoint-action="ttyout=%T\r" --warning=no-file-ignored -cf "$out_base.tar" $pattern 2>>"$_raw_log"
			;;
		zstd|Zstd|ZSTD)
			( set -o pipefail 2>/dev/null; tar --checkpoint-action="ttyout=%T\r" --warning=no-file-ignored -cf - $pattern 2>>"$_raw_log" | \
				zstd --ultra -3 -T0 -q --priority=rt 2>>"$_raw_log" > "$out_base.tar.zst" )
			;;
		esac
	)
	result=$?
	_tar_local_finish "$out_base" "$_comp" "$_raw_log" "$_raw_start" "$result"
	return $?
}

rgb_a="${rgb_a:=220}"
abi="$(getprop ro.product.cpu.abi)"
sdk="$(getprop ro.build.version.sdk)"
release="$(getprop ro.build.version.release)"
case $abi in
arm64*)
	if [[ $sdk -lt 24 ]]; then
		echoRgb "設備Android ${release}版本過低 請升級至Android 8+" "0"
		exit 1
	else
		case $sdk in
		26|27|28)
			echoRgb "設備Android ${release}版本偏低，無法確定腳本能正確的使用" "0"
			;;
		esac
	fi
	;;
*)
	echoRgb "未知的架構: $abi" "0"
	exit 1
	;;
esac
get_mv="$(which mv)"
PATH="/system/bin:/system/xbin:/data/adb/ksu/bin:/sbin/.magisk/busybox:/sbin/.magisk:/sbin:/system_ext/bin:/vendor/bin:/vendor/xbin:/data/data/com.omarea.vtools/files/toolkit:/data/user/0/com.termux/files/usr/bin"
# 先查 magisk 二進制是否存在, 避免直接呼叫導致 libc 雜訊 (小米系統 vendor 屬性權限警告)
if command -v magisk >/dev/null 2>&1; then
	_magisk_path="$(magisk --path 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null})"
	if [[ -d $_magisk_path ]]; then
		PATH="$_magisk_path/.magisk/busybox:$PATH"
	fi
elif ! command -v ksud >/dev/null 2>&1; then
	echo "Magisk busybox Path does not exist"
fi
export PATH="$PATH"
filepath="/data/backup_tools"
busybox="$filepath/busybox"
busybox2="$tools_path/busybox"
#排除自身
exclude="
update
soc.json
classes.dex"
if [[ ! -d $filepath ]]; then
	mkdir -p "$filepath"
	[[ $? = 0 ]] && echoRgb "設置busybox環境中"
fi
#刪除無效軟連結
find -L "$filepath" -maxdepth 1 -type l -exec rm -rf {} \;
if [[ -f $busybox && -f $busybox2 ]]; then
	filesha256="$(sha256sum "$busybox" | cut -d" " -f1)"
	filesha256_1="$(sha256sum "$busybox2" | cut -d" " -f1)"
	if [[ $filesha256 != $filesha256_1 ]]; then
		echoRgb "busybox sha256不一致 重新創立環境中"
		rm -rf "$filepath"/*
	fi
fi
# r192: cleanup 子程序被預期 SIGTERM/對端先關閉時，Android shell/native helper 可能輸出可預期 stderr。
# 只過濾精確白名單；任何其他內容仍轉送正式 stderr，避免掩蓋真錯誤。
_speedbackup_filter_cleanup_stderr_file() {
	local _file="$1" _tag="$2" _line _trim _filtered=0 _forwarded=0
	[[ -s $_file ]] || { rm -f "$_file" 2>/dev/null || true; return 0; }
	while IFS= read -r _line; do
		_trim="$(printf '%s' "$_line" | tr -d '\r' | sed 's/^[[:space:]]*//;s/[[:space:]]*$//')"
		case "$_tag|$_trim" in
		cgfreezer_stale_stop\|unixsock:\ invalid\ or\ incomplete\ response\ header:\ Protocol\ error|cgfreezer_preflight_probe\|unixsock:\ invalid\ or\ incomplete\ response\ header:\ Protocol\ error|cgfreezer_parent_stop\|unixsock:\ invalid\ or\ incomplete\ response\ header:\ Protocol\ error|display_volume_watcher\|Terminated)
			_filtered=$((_filtered + 1))
			;;
		*)
			printf '%s\n' "$_line" >> "${SPEED_DEBUG_ERR_LOG:-/dev/null}" 2>/dev/null || true
			_forwarded=$((_forwarded + 1))
			;;
		esac
	done < "$_file"
	rm -f "$_file" 2>/dev/null || true
	_speed_debug_log "CLEANUP_STDERR_FILTER tag=$_tag filtered=$_filtered forwarded=$_forwarded"
	return 0
}

# r162: cgfreezer 仍由原本 generic SHA loop 負責 copy；但它是 persistent daemon binary，
# 因此只在要新增/替換 cgfreezer 前插入 stop，避免檔案已新但舊 process image 繼續服務。
_speedbackup_stop_cgfreezer_for_replace_startup() {
	local _socket _p _pid _cmd _stop_err
	_socket="$(_cgroup_freezer_daemon_socket_path 2>/dev/null)" || _socket=""
	if [[ -n $_socket && -S $_socket && -x $filepath/unixsock ]]; then
		_stop_err="$(_speedbackup_run_tmp_path "cgfreezer_stale_stop_stderr_${$}_${RANDOM:-0}")" || _stop_err=""
		if [[ -n $_stop_err ]]; then
			rm -f "$_stop_err" 2>/dev/null || true
			printf '%s\n' STOP | "$filepath/unixsock" relay-unix "$_socket" >/dev/null 2>"$_stop_err" || true
			_speedbackup_filter_cleanup_stderr_file "$_stop_err" cgfreezer_stale_stop
		else
			printf '%s\n' STOP | "$filepath/unixsock" relay-unix "$_socket" >/dev/null 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} || true
		fi
	fi
	[[ -n $_socket ]] && rm -f "$_socket" 2>/dev/null || true
	for _p in /proc/[0-9]*; do
		[[ -r $_p/cmdline ]] || continue
		_pid="${_p##*/}"
		_cmd="$({ tr '\000' ' ' < "$_p/cmdline"; } 2>/dev/null | cut -c1-240)"
		case "$_cmd" in
		*cgfreezer*daemon*)
			kill "$_pid" 2>/dev/null || true
			;;
		esac
	done
	return 0
}
_speedbackup_cgfreezer_caps_file_ok() {
	local _file="$1" _cap
	[[ -f $_file ]] || return 1
	for _cap in ${SPEEDBACKUP_CGROUP_FREEZER_REQUIRED_CAPS:-cgroup-v2-uid-root-fallback}; do
		grep -F "$_cap" "$_file" >/dev/null 2>&1 || return 1
	done
	return 0
}
_speedbackup_cgfreezer_required_caps_log() {
	printf '%s\n' "${SPEEDBACKUP_CGROUP_FREEZER_REQUIRED_CAPS:-cgroup-v2-uid-root-fallback}" | tr ' ' ','
}
_speedbackup_probe_stop_stale_cgfreezer_startup() {
	local _socket _need _probe _probe_rc _probe_flat
	_socket="$(_cgroup_freezer_daemon_socket_path 2>/dev/null)" || _socket=""
	_need="$(_speedbackup_cgfreezer_required_caps_log)"
	[[ -n $_socket && -S $_socket && -x $filepath/unixsock ]] || return 0
	_probe="$(_speedbackup_run_tmp_path "cgfreezer_install_probe_${$}_${RANDOM:-0}")" || return 0
	# r163: cgfreezerd 每次 socket 連線只 read/handle 一行；
	# r162 的 HELLO\nCAPS 同連線 probe 只會拿到 HELLO，導致新版 daemon 被誤判 stale。
	# 這裡只送 CAPS，避免進選單前每次錯誤 stop daemon 造成 5 秒卡頓。
	printf 'CAPS\n' | "$filepath/unixsock" relay-unix "$_socket" > "$_probe" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	_probe_rc=$?
	_probe_flat="$(tr '\n' '|' < "$_probe" 2>/dev/null | cut -c1-700)"
	if [[ $_probe_rc = 0 ]] && _speedbackup_cgfreezer_caps_file_ok "$_probe"; then
		_speed_debug_log "TOOLS_NATIVE_DAEMON_PROBE_KEEP name=cgfreezer requiredCap=$_need rc=$_probe_rc method=caps-single-line"
	else
		_speed_debug_log "TOOLS_NATIVE_DAEMON_STALE name=cgfreezer requiredCap=$_need rc=$_probe_rc method=caps-single-line action=stop out=$_probe_flat"
		_speedbackup_stop_cgfreezer_for_replace_startup || true
	fi
	rm -f "$_probe" 2>/dev/null || true
	return 0
}
find "$tools_path" -maxdepth 1 ! -path "$tools_path/tools.sh" -type f | grep -Ev "$(echo $exclude | sed 's/ /\|/g')" | while read -r; do
	File_name="${REPLY##*/}"
	# 發行目錄若殘留 tools.sh.bak / tools_v*.sh / *.orig / *.tmp，不應安裝到 /data/backup_tools，也不納入啟動工具環境。
	case "$File_name" in
	tools.sh.bak|tools.sh.bak_*|tools_v*.sh|*.bak|*.bak_*|*.orig|*.tmp|.*.tmp|SHA256SUMS*)
		_speed_debug_log "TOOLS_INSTALL_SKIP_RELEASE_ARTIFACT file=$File_name"
		continue
		;;
	esac
	if [[ ! -f $filepath/$File_name ]]; then
		if [[ $File_name = cgfreezer ]]; then
			_speed_debug_log "TOOLS_INSTALL_CGFREEZER_PRECOPY reason=missing dst=$filepath/$File_name src=$REPLY action=stop-daemon"
			_speedbackup_stop_cgfreezer_for_replace_startup || true
		fi
		cp -r "$REPLY" "$filepath"
		chmod 0755 "$filepath/$File_name"
		echoRgb "$File_name > $filepath/$File_name"
	else
		filesha256="$(sha256sum "$filepath/$File_name" | cut -d" " -f1)"
		filesha256_1="$(sha256sum "$tools_path/$File_name" | cut -d" " -f1)"
		if [[ $filesha256 != $filesha256_1 ]]; then
			if [[ $File_name = cgfreezer ]]; then
				_speed_debug_log "TOOLS_INSTALL_CGFREEZER_PRECOPY reason=sha-mismatch oldSha=$filesha256 newSha=$filesha256_1 dst=$filepath/$File_name src=$REPLY action=stop-daemon"
				_speedbackup_stop_cgfreezer_for_replace_startup || true
			fi
			echoRgb "$File_name sha256不一致 重新創建"
			cp -r "$REPLY" "$filepath"
			chmod 0755 "$filepath/$File_name"
			echoRgb "$File_name > $filepath/$File_name"
		fi
	fi
done

_speedbackup_cleanup_legacy_event_monitor_name() {
	# r176: 不再另寫 keycheck SHA 驗證；工具完整性由既有 _speedbackup_tool_sha_table()/安裝 SHA loop 負責。
	local _legacy="${filepath:-/data/backup_tools}/event_monitor" _native="${filepath:-/data/backup_tools}/keycheck"
	[[ -f $_legacy && -f $_native ]] || return 0
	rm -f "$_legacy" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} || true
	return 0
}
_speedbackup_cleanup_legacy_event_monitor_name || true

_speedbackup_probe_stop_stale_cgfreezer_startup || true

if [[ -f $busybox ]]; then
	"$busybox" --list | while read -r; do
		if [[ $REPLY != tar && $REPLY != bc && ! -f $filepath/$REPLY ]]; then
			ln -fs "$busybox" "$filepath/$REPLY"
		fi
	done
fi
[[ ! -f $filepath/zstd ]] && echoRgb "$filepath缺少zstd" && exit 2
export PATH="$filepath:$PATH"
export TZ=Asia/Taipei

# ===== Native event tools（內部自動偵測，不新增 conf 開關）=====
_event_resolve_bin() {
	local _name="$1" _cmd="" _fallback=""
	[[ -n $_name ]] || return 1
	_cmd="$(command -v "$_name" 2>/dev/null)"
	if [[ -n $_cmd && -x $_cmd ]]; then
		printf '%s\n' "$_cmd"
		return 0
	fi
	_fallback="$filepath/$_name"
	if [[ -x $_fallback ]]; then
		printf '%s\n' "$_fallback"
		return 0
	fi
	printf '%s\n' "$_name"
	return 1
}
EVENT_FILEWATCH_BIN="$(_event_resolve_bin filewatch)"
EVENT_PROCWAIT_BIN="$(_event_resolve_bin procwait)"
EVENT_EVENTWAIT_BIN="$(_event_resolve_bin eventwait)"
EVENT_UNIXSOCK_BIN="$(_event_resolve_bin unixsock)"
EVENT_NETWATCH_BIN="$(_event_resolve_bin netwatch)"

_event_filewatch_once() {
	_speedbackup_tool_verify_once filewatch 0 >/dev/null 2>&1 || true
	local _path="$1" _timeout="${2:-5}" _tag="${3:-filewatch}" _diag="${4:-}" _fw_pid="" _guard_pid="" _rc=125
	[[ -x ${EVENT_FILEWATCH_BIN:-} && -n $_path ]] || return 125
	case $_timeout in ''|*[!0-9]*) _timeout=5 ;; esac
	if command -v timeout >/dev/null 2>&1; then
		timeout "$_timeout" "$EVENT_FILEWATCH_BIN" --once "$_path" >/dev/null 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
		_rc=$?
	else
		"$EVENT_FILEWATCH_BIN" --once "$_path" >/dev/null 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} &
		_fw_pid=$!
		( trap - EXIT; sleep "$_timeout"; kill "$_fw_pid" 2>/dev/null ) &
		_guard_pid=$!
		wait "$_fw_pid" 2>/dev/null
		_rc=$?
		kill "$_guard_pid" 2>/dev/null
		wait "$_guard_pid" 2>/dev/null
	fi
	_speed_debug_log "FILEWATCH_ONCE tag=$_tag path=$_path timeout=$_timeout rc=$_rc"
	[[ -n $_diag ]] && echo "$(date '+%H:%M:%S') filewatch_once tag=$_tag path=$_path timeout=$_timeout rc=$_rc" >> "$_diag" 2>/dev/null
	return $_rc
}

_eventwait_ms_from_sec() {
	local _s="${1:-5}"
	case $_s in ''|*[!0-9]*) _s=5 ;; esac
	printf '%s\n' "$((_s * 1000))"
}

_eventwait_call() {
	local _op="$1" _tag _timeout_ms _out _rc
	shift
	_speedbackup_tool_verify_once eventwait 0 >/dev/null 2>&1 || true
	[[ -x ${EVENT_EVENTWAIT_BIN:-} ]] || return 125
	_out="$TMPDIR/.eventwait_${_op}_${$}_$RANDOM.out"
	"$EVENT_EVENTWAIT_BIN" "$_op" "$@" > "$_out" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	_rc=$?
	_EVENTWAIT_LAST_LINE="$(sed -n '1p' "$_out" 2>/dev/null)"
	rm -f "$_out" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	return $_rc
}

_eventwait_file_contains() {
	local _path="$1" _pattern="$2" _timeout_sec="${3:-5}" _tag="${4:-file_contains}" _diag="${5:-}" _rc _ms
	[[ -n $_path && -n $_pattern ]] || return 2
	_ms="$(_eventwait_ms_from_sec "$_timeout_sec")"
	_eventwait_call file-contains "$_path" "$_pattern" "$_ms" "$_tag"
	_rc=$?
	_speed_debug_log "EVENTWAIT_FILE_CONTAINS tag=$_tag path=$_path timeoutMs=$_ms rc=$_rc line=$(_speed_debug_kv "${_EVENTWAIT_LAST_LINE:-}") mode=r459"
	[[ -n $_diag ]] && echo "$(date '+%H:%M:%S') eventwait_file_contains tag=$_tag path=$_path timeoutMs=$_ms rc=$_rc line=${_EVENTWAIT_LAST_LINE:-}" >> "$_diag" 2>/dev/null
	return $_rc
}

_eventwait_file_nonempty() {
	local _path="$1" _timeout_sec="${2:-5}" _tag="${3:-file_nonempty}" _diag="${4:-}" _rc _ms
	[[ -n $_path ]] || return 2
	_ms="$(_eventwait_ms_from_sec "$_timeout_sec")"
	_eventwait_call file-nonempty "$_path" "$_ms" "$_tag"
	_rc=$?
	_speed_debug_log "EVENTWAIT_FILE_NONEMPTY tag=$_tag path=$_path timeoutMs=$_ms rc=$_rc line=$(_speed_debug_kv "${_EVENTWAIT_LAST_LINE:-}") mode=r459"
	[[ -n $_diag ]] && echo "$(date '+%H:%M:%S') eventwait_file_nonempty tag=$_tag path=$_path timeoutMs=$_ms rc=$_rc line=${_EVENTWAIT_LAST_LINE:-}" >> "$_diag" 2>/dev/null
	return $_rc
}

_eventwait_file_created_ms() {
	local _path="$1" _timeout_ms="${2:-3000}" _tag="${3:-file_created}" _diag="${4:-}" _rc
	[[ -n $_path ]] || return 2
	case $_timeout_ms in ''|*[!0-9]*) _timeout_ms=3000 ;; esac
	_eventwait_call file-created "$_path" "$_timeout_ms" "$_tag"
	_rc=$?
	_speed_debug_log "EVENTWAIT_FILE_CREATED tag=$_tag path=$_path timeoutMs=$_timeout_ms rc=$_rc line=$(_speed_debug_kv "${_EVENTWAIT_LAST_LINE:-}") mode=r459"
	[[ -n $_diag ]] && echo "$(date '+%H:%M:%S') eventwait_file_created tag=$_tag path=$_path timeoutMs=$_timeout_ms rc=$_rc line=${_EVENTWAIT_LAST_LINE:-}" >> "$_diag" 2>/dev/null
	return $_rc
}

_eventwait_socket_ready() {
	local _path="$1" _timeout_sec="${2:-5}" _tag="${3:-socket_ready}" _diag="${4:-}" _rc _ms
	[[ -n $_path ]] || return 2
	_ms="$(_eventwait_ms_from_sec "$_timeout_sec")"
	_eventwait_call socket-ready "$_path" "$_ms" "$_tag"
	_rc=$?
	_speed_debug_log "EVENTWAIT_SOCKET_READY tag=$_tag path=$_path timeoutMs=$_ms rc=$_rc line=$(_speed_debug_kv "${_EVENTWAIT_LAST_LINE:-}") mode=r459"
	[[ -n $_diag ]] && echo "$(date '+%H:%M:%S') eventwait_socket_ready tag=$_tag path=$_path timeoutMs=$_ms rc=$_rc line=${_EVENTWAIT_LAST_LINE:-}" >> "$_diag" 2>/dev/null
	return $_rc
}

_eventwait_pid_exit_ms() {
	local _pid="$1" _timeout_ms="${2:-3000}" _tag="${3:-pid_exit}" _diag="${4:-}" _rc
	case $_pid in ''|*[!0-9]*) return 2 ;; esac
	case $_timeout_ms in ''|*[!0-9]*) _timeout_ms=3000 ;; esac
	_eventwait_call pid-exit "$_pid" "$_timeout_ms" "$_tag"
	_rc=$?
	_speed_debug_log "EVENTWAIT_PID_EXIT tag=$_tag pid=$_pid timeoutMs=$_timeout_ms rc=$_rc line=$(_speed_debug_kv "${_EVENTWAIT_LAST_LINE:-}") mode=r459"
	[[ -n $_diag ]] && echo "$(date '+%H:%M:%S') eventwait_pid_exit tag=$_tag pid=$_pid timeoutMs=$_timeout_ms rc=$_rc line=${_EVENTWAIT_LAST_LINE:-}" >> "$_diag" 2>/dev/null
	return $_rc
}

_eventwait_pid_or_file_ms() {
	local _pid="$1" _fatal="$2" _timeout_ms="${3:-0}" _tag="${4:-pid_or_file}" _diag="${5:-}" _rc
	case $_pid in ''|*[!0-9]*) return 2 ;; esac
	[[ -n $_fatal ]] || _fatal="-"
	case $_timeout_ms in ''|*[!0-9]*) _timeout_ms=0 ;; esac
	_eventwait_call pid-or-file "$_pid" "$_fatal" "$_timeout_ms" "$_tag"
	_rc=$?
	_speed_debug_log "EVENTWAIT_PID_OR_FILE tag=$_tag pid=$_pid fatal=$_fatal timeoutMs=$_timeout_ms rc=$_rc line=$(_speed_debug_kv "${_EVENTWAIT_LAST_LINE:-}") mode=r459"
	[[ -n $_diag ]] && echo "$(date '+%H:%M:%S') eventwait_pid_or_file tag=$_tag pid=$_pid fatal=$_fatal timeoutMs=$_timeout_ms rc=$_rc line=${_EVENTWAIT_LAST_LINE:-}" >> "$_diag" 2>/dev/null
	return $_rc
}

_eventwait_pipeline_watch_ms() {
	local _pidfile="$1" _fatal="$2" _progress="$3" _idle_ms="${4:-0}" _timeout_ms="${5:-0}" _tag="${6:-pipeline_watch}" _diag="${7:-}" _rc
	[[ -n $_pidfile ]] || return 2
	[[ -n $_fatal ]] || _fatal="-"
	[[ -n $_progress ]] || _progress="-"
	case $_idle_ms in ''|*[!0-9]*) _idle_ms=0 ;; esac
	case $_timeout_ms in ''|*[!0-9]*) _timeout_ms=0 ;; esac
	local _min_bps="${SPEEDBACKUP_STREAM_PIPELINE_MIN_BPS:-0}" _rate_window="${SPEEDBACKUP_STREAM_PIPELINE_RATE_WINDOW_MS:-30000}" _backend="pipeline-watch"
	case $_min_bps in ''|*[!0-9]*) _min_bps=0 ;; esac
	case $_rate_window in ''|*[!0-9]*) _rate_window=30000 ;; esac
	if [[ $_min_bps -gt 0 && $_progress != "-" ]]; then
		_eventwait_call pipeline-rate-watch "$_pidfile" "$_fatal" "$_progress" "$_idle_ms" "$_timeout_ms" "$_min_bps" "$_rate_window" "$_tag"
		_backend="pipeline-rate-watch"
	else
		_eventwait_call pipeline-watch "$_pidfile" "$_fatal" "$_progress" "$_idle_ms" "$_timeout_ms" "$_tag"
	fi
	_rc=$?
	_speed_debug_log "EVENTWAIT_PIPELINE_WATCH tag=$_tag pidFile=$_pidfile fatal=$_fatal progress=$_progress idleMs=$_idle_ms timeoutMs=$_timeout_ms minBps=$_min_bps rateWindowMs=$_rate_window rc=$_rc line=$(_speed_debug_kv "${_EVENTWAIT_LAST_LINE:-}") backend=$_backend mode=r470"
	[[ -n $_diag ]] && echo "$(date '+%H:%M:%S') eventwait_pipeline_watch tag=$_tag pidFile=$_pidfile fatal=$_fatal progress=$_progress idleMs=$_idle_ms timeoutMs=$_timeout_ms rc=$_rc line=${_EVENTWAIT_LAST_LINE:-}" >> "$_diag" 2>/dev/null
	return $_rc
}

_eventwait_pipeline_watch_single_pid_ms() {
	local _pid="$1" _fatal="$2" _progress="$3" _idle_ms="${4:-0}" _timeout_ms="${5:-0}" _tag="${6:-pipeline_watch}" _pf _rc
	case $_pid in ''|*[!0-9]*) return 2 ;; esac
	local _safe_tag
	_safe_tag="$(printf '%s' "$_tag" | tr -c 'A-Za-z0-9_' '_' 2>/dev/null)"
	[[ -n $_safe_tag ]] || _safe_tag=pipeline_watch
	_pf="${TMPDIR:-/data/local/tmp}/.speedbackup_pipeline_pids_${_safe_tag}_$$_$RANDOM.tsv"
	printf 'root\t%s\n' "$_pid" > "$_pf" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} || return 2
	_eventwait_pipeline_watch_ms "$_pf" "$_fatal" "$_progress" "$_idle_ms" "$_timeout_ms" "$_tag"
	_rc=$?
	rm -f "$_pf" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	return $_rc
}

_speedbackup_stream_pipeline_progress_file() {
	local _p=""
	case ${remote_type:-} in
	webdav)
		_p="$(_speed_debug_log_path webdav_daemon_info.log 2>/dev/null)"
		[[ -n $_p && -e $_p ]] && { printf '%s\n' "$_p"; return 0; }
		;;
	esac
	printf '%s\n' "-"
}

_speedbackup_stream_pipeline_idle_ms() {
	local _progress="${1:-}" _idle="${SPEEDBACKUP_STREAM_PIPELINE_IDLE_MS:-auto}"
	case $_idle in
	''|auto|AUTO)
		case ${remote_type:-}:$_progress in
		webdav:/*) printf '%s\n' "${SPEEDBACKUP_STREAM_PIPELINE_WEBDAV_IDLE_MS:-180000}" ;;
		*) printf '0\n' ;;
		esac
		;;
	*[!0-9]*) printf '0\n' ;;
	*) printf '%s\n' "$_idle" ;;
	esac
}

_eventwait_file_size_stable_ms() {
	local _path="$1" _stable_ms="${2:-500}" _timeout_ms="${3:-3000}" _tag="${4:-file_size_stable}" _diag="${5:-}" _rc
	[[ -n $_path ]] || return 2
	case $_stable_ms in ''|*[!0-9]*) _stable_ms=500 ;; esac
	case $_timeout_ms in ''|*[!0-9]*) _timeout_ms=3000 ;; esac
	_eventwait_call file-size-stable "$_path" "$_stable_ms" "$_timeout_ms" "$_tag"
	_rc=$?
	_speed_debug_log "EVENTWAIT_FILE_SIZE_STABLE tag=$_tag path=$_path stableMs=$_stable_ms timeoutMs=$_timeout_ms rc=$_rc line=$(_speed_debug_kv "${_EVENTWAIT_LAST_LINE:-}") mode=r459"
	[[ -n $_diag ]] && echo "$(date '+%H:%M:%S') eventwait_file_size_stable tag=$_tag path=$_path stableMs=$_stable_ms timeoutMs=$_timeout_ms rc=$_rc line=${_EVENTWAIT_LAST_LINE:-}" >> "$_diag" 2>/dev/null
	return $_rc
}

# r458: 對本地輸出檔/TSV/map/bundle/manifest 做統一 eventwait 穩定確認。
# 不改業務判定，只避免 producer 剛退出後 reader 立刻讀到尚未 flush 完的中間檔。
_eventwait_output_file_stable_ms() {
	local _path="$1" _tag="${2:-output_file_stable}" _stable_ms="${3:-80}" _timeout_ms="${4:-1200}" _rc
	[[ -n $_path ]] || return 2
	case $_stable_ms in ''|*[!0-9]*) _stable_ms=80 ;; esac
	case $_timeout_ms in ''|*[!0-9]*) _timeout_ms=1200 ;; esac
	if [[ ! -e $_path ]]; then
		_eventwait_file_created_ms "$_path" "$_timeout_ms" "${_tag}_created" >/dev/null 2>&1 || true
	fi
	if [[ -e $_path ]]; then
		_eventwait_file_size_stable_ms "$_path" "$_stable_ms" "$_timeout_ms" "$_tag" >/dev/null 2>&1
		_rc=$?
	else
		_rc=2
	fi
	_speed_debug_log "EVENTWAIT_OUTPUT_FILE_STABLE tag=$_tag path=$_path stableMs=$_stable_ms timeoutMs=$_timeout_ms rc=$_rc mode=r459"
	return $_rc
}

_eventwait_output_files_stable_ms() {
	local _tag="${1:-output_files_stable}" _stable_ms="${2:-80}" _timeout_ms="${3:-1200}" _path _ok=0 _fail=0
	shift 3 2>/dev/null || return 2
	for _path in "$@"; do
		[[ -n $_path ]] || continue
		if _eventwait_output_file_stable_ms "$_path" "$_tag" "$_stable_ms" "$_timeout_ms" >/dev/null 2>&1; then
			_ok=$((_ok + 1))
		else
			_fail=$((_fail + 1))
		fi
	done
	_speed_debug_log "EVENTWAIT_OUTPUT_FILES_STABLE tag=$_tag ok=$_ok fail=$_fail stableMs=$_stable_ms timeoutMs=$_timeout_ms mode=r459"
	[[ $_fail -eq 0 ]]
}

# 等待指定 PID 清單，避免 wait 參數為空時退化成 bare wait、誤等長駐 daemon。
_event_wait_pid_list() {
	local _list="$1" _tag="${2:-pid_list}" _pid _rc=0 _one_rc=0 _count=0
	[[ -z $_list ]] && { _speed_debug_log "WAIT_PID_LIST_EMPTY tag=$_tag"; return 0; }
	for _pid in $_list; do
		[[ -z $_pid ]] && continue
		let _count++
		wait "$_pid" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
		_one_rc=$?
		[[ $_one_rc = 0 ]] || _rc=$_one_rc
	done
	_speed_debug_log "WAIT_PID_LIST_DONE tag=$_tag count=$_count rc=$_rc"
	return $_rc
}

_event_wait_pid_exit_procwait() {
	_speedbackup_tool_verify_once procwait 0 >/dev/null 2>&1 || true
	local _pid="$1" _timeout="${2:-1}" _tag="${3:-pid_exit}" _rc _state
	[[ -x ${EVENT_PROCWAIT_BIN:-} ]] || return 125
	command -v timeout >/dev/null 2>&1 || return 125
	case $_pid in ''|*[!0-9]*) return 125 ;; esac
	case $_timeout in ''|*[!0-9]*) _timeout=1 ;; esac
	timeout "$_timeout" "$EVENT_PROCWAIT_BIN" pid "$_pid" >/dev/null 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	_rc=$?
	case $_rc in
	0)
		_speed_debug_log "PROCWAIT_EXIT tag=$_tag pid=$_pid timeout=$_timeout rc=$_rc"
		return 0
		;;
	3)
		_speed_debug_log "PROCWAIT_FALLBACK tag=$_tag pid=$_pid rc=$_rc reason=pidfd_unsupported"
		return 125
		;;
	124|137|143)
		_speed_debug_log "PROCWAIT_EXIT_TIMEOUT tag=$_tag pid=$_pid timeout=$_timeout rc=$_rc"
		return 124
		;;
	*)
		_state="$(awk '/^State:/{print $2; exit}' /proc/"$_pid"/status 2>/dev/null)"
		if ! kill -0 "$_pid" 2>/dev/null || [[ $_state = Z ]]; then
			_speed_debug_log "PROCWAIT_EXIT tag=$_tag pid=$_pid rc=$_rc state=${_state:-gone}"
			return 0
		fi
		_speed_debug_log "PROCWAIT_FALLBACK tag=$_tag pid=$_pid rc=$_rc state=$_state"
		return 125
		;;
	esac
}

_event_terminate_pid() {
	local _pid="$1" _tag="${2:-terminate}" _i=0
	case $_pid in ''|*[!0-9]*) return 1 ;; esac
	kill -0 "$_pid" 2>/dev/null || return 0
	kill "$_pid" 2>/dev/null
	if _eventwait_pid_exit_ms "$_pid" 1000 "$_tag.term" >/dev/null 2>&1; then
		_speed_debug_log "EVENTWAIT_TERMINATE_EXIT tag=$_tag pid=$_pid phase=term mode=r459"
		return 0
	fi
	if _event_wait_pid_exit_procwait "$_pid" 1 "$_tag.term"; then
		return 0
	fi
	while [[ $_i -lt 10 ]] && kill -0 "$_pid" 2>/dev/null; do
		sleep 0.1
		_i=$((_i + 1))
	done
	if kill -0 "$_pid" 2>/dev/null; then
		kill -KILL "$_pid" 2>/dev/null
		_event_wait_pid_exit_procwait "$_pid" 1 "$_tag.kill" >/dev/null 2>&1 || true
	fi
	return 0
}

# 只在遠端目標為私有 IPv4 且路由走可信 LAN 介面時啟用。
# 監看器不輪詢、不持有 WakeLock；只在 NETLINK_ROUTE 事件發生時重新檢查到遠端的路由。
_remote_private_ipv4() {
	case "$1" in
	10.*|192.168.*) return 0 ;;
	172.*)
		local _o2="${1#172.}"; _o2="${_o2%%.*}"
		case $_o2 in ''|*[!0-9]*) return 1 ;; esac
		[[ $_o2 -ge 16 && $_o2 -le 31 ]]
		return
		;;
	esac
	return 1
}

_remote_lan_iface_ok() {
	local _if="$1"
	case "$_if" in
	''|lo|rmnet*|r_rmnet*|ccmni*|pdp*|wwan*|cell*|tun*|tap*|wg*|wireguard*|tailscale*|zt*|clat*|v4-*|dummy*|ifb*|ip6tnl*|sit*|gre*|gretap*|wifi-aware*|aware*|p2p*) return 1 ;;
	wlan*|wifi*|mlan*|eth*|en*|ap*|swlan*|softap*|rndis*|usb*|bnep*|bt-pan*|br*|bond*) return 0 ;;
	esac
	[[ -d /sys/class/net/"$_if"/wireless ]]
}

_remote_route_key() {
	local _host="$1"
	ip route get "$_host" 2>/dev/null | awk '{
		dev=""; src="";
		for (i=1; i<=NF; i++) {
			if ($i=="dev" && i<NF) dev=$(i+1)
			if ($i=="src" && i<NF) src=$(i+1)
		}
		if (dev!="" && src!="") { print dev "|" src; exit }
	}'
}

REMOTE_NETWATCH_BIN_PID=""
REMOTE_NETWATCH_READER_PID=""
REMOTE_NETWATCH_FIFO=""
REMOTE_NETWATCH_FLAG=""
REMOTE_NETWATCH_KEY=""
REMOTE_NETWATCH_HOST=""
REMOTE_NETWATCH_REPORTED=0
SMBCLIENT_PIDS_DIR="${SMBCLIENT_PIDS_DIR:-${TMPDIR:-/data/local/tmp}/.smbclient_pids_$$}"

_smbclient_pid_dir() {
	local _d="${SMBCLIENT_PIDS_DIR:-${TMPDIR:-/data/local/tmp}/.smbclient_pids_$$}"
	mkdir -p "$_d" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} || return 1
	printf '%s\n' "$_d"
}

_smbclient_note_pid() {
	local _pid="$1" _tag="${2:-smbclient_child}" _d
	case $_pid in ''|*[!0-9]*) return 0 ;; esac
	_d="$(_smbclient_pid_dir)" || return 0
	{
		printf 'pid=%s\n' "$_pid"
		printf 'tag=%s\n' "$_tag"
		printf 'time=%s\n' "$(date '+%Y-%m-%d %H:%M:%S' 2>/dev/null)"
	} > "$_d/$_pid" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} || true
}

_smbclient_forget_pid() {
	local _pid="$1" _d
	case $_pid in ''|*[!0-9]*) return 0 ;; esac
	_d="${SMBCLIENT_PIDS_DIR:-${TMPDIR:-/data/local/tmp}/.smbclient_pids_$$}"
	rm -f "$_d/$_pid" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
}

_remote_smbclient_stop_active() {
	local _reason="${1:-remote_changed}" _d _f _pid _tag
	_d="${SMBCLIENT_PIDS_DIR:-${TMPDIR:-/data/local/tmp}/.smbclient_pids_$$}"
	[[ -d $_d ]] || return 0
	for _f in "$_d"/*; do
		[[ -f $_f ]] || continue
		_pid="$(awk -F= '$1=="pid"{print $2; exit}' "$_f" 2>/dev/null)"
		_tag="$(awk -F= '$1=="tag"{print $2; exit}' "$_f" 2>/dev/null)"
		case $_pid in ''|*[!0-9]*) rm -f "$_f" 2>/dev/null; continue ;; esac
		_speed_debug_log "REMOTE_NETWATCH_STOP_SMBCLIENT reason=$_reason pid=$_pid tag=${_tag:-smbclient_child}"
		_event_terminate_pid "$_pid" "smbclient_${_tag:-child}" >/dev/null 2>&1 || true
		rm -f "$_f" 2>/dev/null
	done
	return 0
}

_remote_netwatch_start() {
	_remote_netwatch_stop
	REMOTE_NETWATCH_REPORTED=0
	[[ -x ${EVENT_NETWATCH_BIN:-} ]] || { _speed_debug_log "REMOTE_NETWATCH_SKIP reason=missing"; return 0; }
	[[ -n ${REMOTE_HOST:-} ]] || { _speed_debug_log "REMOTE_NETWATCH_SKIP reason=no_host"; return 0; }
	_remote_private_ipv4 "$REMOTE_HOST" || { _speed_debug_log "REMOTE_NETWATCH_SKIP reason=non_private_ipv4 host=$REMOTE_HOST"; return 0; }

	local _key _iface _fifo _flag _log
	_key="$(_remote_route_key "$REMOTE_HOST")"
	[[ -n $_key ]] || { _speed_debug_log "REMOTE_NETWATCH_SKIP reason=no_route host=$REMOTE_HOST"; return 0; }
	# mksh pattern expansion treats bare | unexpectedly on some builds; parse route key with awk instead of ${_key%%|*}.
	_iface="$(printf '%s\n' "$_key" | awk -F'|' '{print $1; exit}')"
	[[ -n $_iface ]] || { _speed_debug_log "REMOTE_NETWATCH_SKIP reason=empty_iface key=$_key"; return 0; }
	_remote_lan_iface_ok "$_iface" || { _speed_debug_log "REMOTE_NETWATCH_SKIP reason=untrusted_iface iface=$_iface key=$_key"; return 0; }

	_fifo="$TMPDIR/.remote_netwatch_fifo_$$"
	_flag="$TMPDIR/.remote_netwatch_event_$$"
	_log="$(_speed_debug_log_path remote_netwatch.log)"
	rm -f "$_fifo" "$_flag" "$_flag.reported" 2>/dev/null
	mkfifo "$_fifo" 2>/dev/null || { _speed_debug_log "REMOTE_NETWATCH_SKIP reason=mkfifo_failed fifo=$_fifo"; return 0; }

	# r335: keep FIFO open/redirection errors inside remote_netwatch.log.
	# mksh may print "can't create/open ... Interrupted system call" to the terminal
	# when stop kills the background FIFO opener while it is blocked in open(2).
	# Wrapping both workers lets shell redirection diagnostics inherit the log stderr.
	(
		trap - EXIT
		exec "$EVENT_NETWATCH_BIN" >"$_fifo"
	) 2>>"$_log" &
	REMOTE_NETWATCH_BIN_PID=$!
	_speedbackup_protect_pid "$REMOTE_NETWATCH_BIN_PID" netwatch_native
	(
		# 背景 reader 是內部 worker，不得執行主腳本 EXIT trap。
		trap - EXIT
		while IFS= read -r _event; do
			_event_if=""
			_new_key=""
			case "$_event" in
			LINK_NEW*|LINK_DEL*|ADDR_NEW*|ADDR_DEL*) ;;
			*) continue ;;
			esac
			_event_if="${_event#*ifname=}"
			_event_if="${_event_if%% *}"
			[[ $_event_if = "$_iface" ]] || continue
			_new_key="$(_remote_route_key "$REMOTE_HOST")"
			if [[ $_new_key != "$_key" ]]; then
				{
					echo "time=$(date '+%Y-%m-%d %H:%M:%S' 2>/dev/null)"
					echo "host=$REMOTE_HOST"
					echo "before=$_key"
					echo "after=$_new_key"
					echo "event=$_event"
				} > "$_flag" 2>/dev/null
				# r65: the reader is the first process that knows the route/address changed.
				# Persist the human/debug report here too; some restore abort paths return
				# before the foreground loop reaches another netwatch gate.
				_reported="${_flag}.reported"
				if [[ ! -e $_reported ]]; then
					: > "$_reported" 2>/dev/null || true
					echoRgb "遠端操作期間偵測到 LAN 路由／位址變更；本次傳輸結果請以協議返回值與校驗為準" "0"
					_speed_debug_append_cat "$_log" "$_flag" "===== REMOTE LAN CHANGE ====="
				fi
				# r61: LAN route/address changed must become fatal immediately, not only after the
				# foreground loop reaches the next gate. This prevents WebDAV getstdout/PUT relay
				# from being restarted after the daemon is killed, and gives SMB/download paths a
				# shared fatal flag even when the active command is killed from this reader.
				_remote_stream_mark_fatal "netwatch:${REMOTE_HOST:-unknown}" 126 0 "LAN route/address changed during remote operation" >/dev/null 2>&1 || true
				case "${remote_type:-}" in
				webdav)
					_speed_debug_log "REMOTE_NETWATCH_STOP_WEBDAV reason=route_changed key=$_key new_key=$_new_key"
					_webdav_daemon_stop >/dev/null 2>&1 || true
					;;
				smb)
					_speed_debug_log "REMOTE_NETWATCH_STOP_SMB reason=route_changed key=$_key new_key=$_new_key"
					_remote_smbclient_stop_active route_changed >/dev/null 2>&1 || true
					;;
				esac
				break
			fi
		done < "$_fifo"
	) 2>>"$_log" &
	REMOTE_NETWATCH_READER_PID=$!
	_speedbackup_protect_pid "$REMOTE_NETWATCH_READER_PID" netwatch_reader
	REMOTE_NETWATCH_FIFO="$_fifo"
	REMOTE_NETWATCH_FLAG="$_flag"
	REMOTE_NETWATCH_KEY="$_key"
	REMOTE_NETWATCH_HOST="$REMOTE_HOST"
	_speed_debug_log "REMOTE_NETWATCH_START host=$REMOTE_HOST key=$_key bin_pid=$REMOTE_NETWATCH_BIN_PID reader_pid=$REMOTE_NETWATCH_READER_PID mode=r335"
}

_remote_netwatch_report() {
	[[ -n ${REMOTE_NETWATCH_FLAG:-} && -s ${REMOTE_NETWATCH_FLAG:-} ]] || return 0
	local _reported
	_reported="${REMOTE_NETWATCH_FLAG}.reported"
	# r61: this function can be called from pipeline/subshell contexts; shell variables
	# are not a reliable once-only guard there. Use a file sentinel to avoid repeated
	# user messages and duplicate REMOTE LAN CHANGE blocks.
	if [[ ! -e $_reported ]]; then
		: > "$_reported" 2>/dev/null || true
		REMOTE_NETWATCH_REPORTED=1
		echoRgb "遠端操作期間偵測到 LAN 路由／位址變更；本次傳輸結果請以協議返回值與校驗為準" "0"
		_speed_debug_append_cat "$(_speed_debug_log_path remote_netwatch.log)" "$REMOTE_NETWATCH_FLAG" "===== REMOTE LAN CHANGE ====="
	fi
	return 0
}

_remote_netwatch_stop() {
	local _pid
	for _pid in "${REMOTE_NETWATCH_READER_PID:-}" "${REMOTE_NETWATCH_BIN_PID:-}"; do
		case "$_pid" in ''|*[!0-9]*) continue ;; esac
		kill "$_pid" 2>/dev/null
	done
	for _pid in "${REMOTE_NETWATCH_READER_PID:-}" "${REMOTE_NETWATCH_BIN_PID:-}"; do
		case "$_pid" in ''|*[!0-9]*) continue ;; esac
		wait "$_pid" 2>/dev/null
	done
	[[ -n ${REMOTE_NETWATCH_FIFO:-} ]] && rm -f "$REMOTE_NETWATCH_FIFO" 2>/dev/null
	REMOTE_NETWATCH_BIN_PID=""
	REMOTE_NETWATCH_READER_PID=""
	REMOTE_NETWATCH_FIFO=""
}

ln -fs "$tools_path/classes.dex" "$filepath/classes.dex"
export CLASSPATH="$filepath/classes.dex"
# ===== dex app_process 統一入口 =====
# 所有 Java/Dex 類呼叫統一經由這幾個 helper。
# 一般一次性呼叫用 _dex / _dex_raw；需要保留原始 stdout 或背景 daemon 時用 _dex_exec_unfiltered。
DEX_APP_PROCESS_BIN="${DEX_APP_PROCESS_BIN:-app_process}"
DEX_APP_PROCESS_BASE="${DEX_APP_PROCESS_BASE:-/system/bin}"

_dex_classes_path() {
	if [[ -f ${filepath:-}/classes.dex ]]; then
		printf '%s\n' "$filepath/classes.dex"
	elif [[ -f ${tools_path:-}/classes.dex ]]; then
		printf '%s\n' "$tools_path/classes.dex"
	elif [[ -n ${CLASSPATH:-} ]]; then
		printf '%s\n' "$CLASSPATH"
	else
		printf '%s\n' "/data/backup_tools/classes.dex"
	fi
}

_dex_export_classpath() {
	_speedbackup_tool_verify_once classes.dex 1 || return 1
	local _cp
	_cp="$(_dex_classes_path)"
	[[ -n $_cp ]] && export CLASSPATH="$_cp"
}

_dex_app_process_abs() {
	local _ap
	_ap="$(command -v "$DEX_APP_PROCESS_BIN" 2>/dev/null)"
	[[ -n $_ap ]] && { printf '%s\n' "$_ap"; return 0; }
	printf '%s\n' "/system/bin/app_process"
}

# 393: 低記憶體/ROM 背景清理下，daemon 或主 shell 可能被 LMK/SIGKILL。
# root 可寫時降低 oom_score_adj；失敗只記 log，不阻塞流程。
_speedbackup_protect_pid() {
	local _pid="$1" _tag="${2:-process}"
	case $_pid in ''|*[!0-9]*) return 1 ;; esac
	kill -0 "$_pid" 2>/dev/null || return 1
	if [[ -w "/proc/$_pid/oom_score_adj" ]]; then
		echo -900 > "/proc/$_pid/oom_score_adj" 2>/dev/null && _speed_debug_log "OOM_PROTECT tag=$_tag pid=$_pid score=-900"
	fi
	renice -n -5 -p "$_pid" >/dev/null 2>&1 || true
	return 0
}

# 509/r70: 短生命週期重型 child 也套 OOM/priority 保護。
# 保持 stdout/stderr/stdin 原樣穿透，rc 原樣回傳；stdin 以 fd9 轉交，避免 mksh 背景 job 把 fd0 換成 /dev/null。
_speedbackup_protected_command() {
	local _cmd="$1" _tag="$2" _pid _rc
	shift 2
	[[ -n $_cmd ]] || return 127
	[[ -n $_tag ]] || _tag="${_cmd}_child"
	{ command "$_cmd" "$@" <&9 & } 9<&0
	_pid=$!
	_speedbackup_protect_pid "$_pid" "$_tag"
	wait "$_pid"
	_rc=$?
	_speed_debug_log "OOM_PROTECTED_CHILD_END tag=$_tag cmd=$_cmd pid=$_pid rc=$_rc"
	return "$_rc"
}

# tar / zstd 是備份、流式上傳、遠端恢復與本地解壓的長耗時資料面 child。
tar() {
	_speedbackup_protected_command tar "${TAR_OOM_TAG:-tar_child}" "$@"
}

zstd() {
	_speedbackup_protected_command zstd "${ZSTD_OOM_TAG:-zstd_child}" "$@"
}

_event_unixsock_call() {
	local _pid _rc _tag="${UNIXSOCK_OOM_TAG:-unixsock_relay_child}"
	[[ -n ${EVENT_UNIXSOCK_BIN:-} ]] || return 127
	{ command "$EVENT_UNIXSOCK_BIN" "$@" <&9 & } 9<&0
	_pid=$!
	_speedbackup_protect_pid "$_pid" "$_tag"
	wait "$_pid"
	_rc=$?
	_speed_debug_log "UNIXSOCK_CHILD_END tag=$_tag pid=$_pid rc=$_rc args=$*"
	return "$_rc"
}

# 433: SMB 使用短生命週期 smbclient child；統一經由同名 wrapper 啟動，
# 讓 stdout/stderr/stdin 行為保持原樣，同時在 child 還活著時立刻套 oom_score_adj/renice。
# 因此一般 capture、stdin batch、流式 put -、get - stdout 都能受保護，不改 SMB 語義。
_smbclient_bin() {
	if [[ -n ${filepath:-} && -x "$filepath/smbclient" ]]; then
		printf '%s\n' "$filepath/smbclient"
	elif [[ -n ${tools_path:-} && -x "$tools_path/smbclient" ]]; then
		printf '%s\n' "$tools_path/smbclient"
	else
		command -v smbclient 2>/dev/null
	fi
}

smbclient() {
	_speedbackup_tool_verify_once smbclient 1 || return 126
	local _bin _pid _rc _tag
	_bin="$(_smbclient_bin)"
	[[ -n $_bin ]] || { echo "smbclient: not found" >&2; return 127; }
	_tag="${SMBCLIENT_OOM_TAG:-smbclient_child}"
	# mksh 對背景工作會把 stdin 重導到 /dev/null——即使呼叫端是 `smbclient < 批次檔`
	# 或 `printf | smbclient`，甚至在背景命令上寫 <&0 也救不回（mksh 先把 fd0 換成
	# /dev/null 才處理 <&0，等於 dup 到已經是 /dev/null 的 fd）。這會讓所有
	# `< "$batch"` / stdin 管道的呼叫點靜默執行 0 個指令卻回報成功。
	# 修法：先在群組層把 wrapper 真正的 stdin dup 到 fd9，背景 child 改讀 <&9。
	# (mksh/bash/dash 實測皆正確；rc 經 wait 正常傳遞)
	{ command "$_bin" "$@" <&9 & } 9<&0
	_pid=$!
	_smbclient_note_pid "$_pid" "$_tag"
	_speedbackup_protect_pid "$_pid" "$_tag"
	wait "$_pid"
	_rc=$?
	_smbclient_forget_pid "$_pid"
	_speed_debug_log "SMBCLIENT_CHILD_END tag=$_tag pid=$_pid rc=$_rc"
	return "$_rc"
}

_daemon_retry_sleep() {
	local _try="$1" _tag="${2:-daemon}" _sleep="0.3"
	case $_try in
	0) _sleep="0.3" ;;
	1) _sleep="0.8" ;;
	*) _sleep="1.5" ;;
	esac
	_speed_debug_log "DAEMON_RETRY_SLEEP tag=$_tag try=$_try sleep=$_sleep"
	sleep "$_sleep" 2>/dev/null || sleep 1
}


# 394: 可選 Dex 外部 watchdog。它不取代 tools 端 retry，只在 daemon 被 SIGKILL 後、owner tools.sh 仍活著時
# 嘗試重啟 root-side daemon，降低下一次 relay 遇到 stale socket 的概率。
_DEX_WATCHDOG_DIR="${_DEX_WATCHDOG_DIR:-$TMPDIR/.speedbackup_dex_watchdog}"
_dex_watchdog_stop() {
	local _tag="$1" _pidfile _pid
	[[ -n $_tag ]] || return 0
	_pidfile="$_DEX_WATCHDOG_DIR/${_tag}.pid"
	_pid="$(cat "$_pidfile" 2>/dev/null)"
	case $_pid in ''|*[!0-9]*) _pid="" ;; esac
	[[ -n $_pid ]] && kill "$_pid" 2>/dev/null || true
	rm -f "$_pidfile" 2>/dev/null
}

_dex_watchdog_start() {
	local _tag="$1" _pid_file="$2" _socket="$3" _class="$4" _cmd="$5" _arg1="$6" _idle="$7" _owner="$8"
	local _wd_pid_file _wd_pid _wd_out _wd_err _app_process
	[[ -n $_tag && -n $_pid_file && -n $_class && -n $_cmd ]] || return 0
	[[ ${SPEEDBACKUP_MAIN_PID:-} = *[!0-9]* || -z ${SPEEDBACKUP_MAIN_PID:-} ]] && return 0
	mkdir -p "$_DEX_WATCHDOG_DIR" 2>/dev/null || return 0
	_wd_pid_file="$_DEX_WATCHDOG_DIR/${_tag}.pid"
	_wd_pid="$(cat "$_wd_pid_file" 2>/dev/null)"
	case $_wd_pid in ''|*[!0-9]*) _wd_pid="" ;; esac
	if [[ -n $_wd_pid ]] && kill -0 "$_wd_pid" 2>/dev/null; then
		return 0
	fi
	_socket="${_socket:--}"
	_idle="${_idle:-1800}"
	_owner="${_owner:-$SPEEDBACKUP_MAIN_PID}"
	_wd_out="$_DEX_WATCHDOG_DIR/${_tag}.out"
	_wd_err="$_DEX_WATCHDOG_DIR/${_tag}.err"
	_app_process="$(_dex_app_process_abs)"
	_dex_export_classpath
	case $_cmd in
	daemonunix)
		nohup "$_app_process" "$DEX_APP_PROCESS_BASE" com.xayah.dex.DaemonSupervisorUtil supervise "$_tag" "$_pid_file" "$_socket" "$_owner" 1500 -- "$_app_process" "$DEX_APP_PROCESS_BASE" "$_class" daemonunix "$_arg1" "$_idle" "$_owner" > "$_wd_out" 2>>"$_wd_err" &
		;;
	daemon)
		nohup "$_app_process" "$DEX_APP_PROCESS_BASE" com.xayah.dex.DaemonSupervisorUtil supervise "$_tag" "$_pid_file" - "$_owner" 1500 -- "$_app_process" "$DEX_APP_PROCESS_BASE" "$_class" daemon "$_arg1" "$_idle" "$_owner" > "$_wd_out" 2>>"$_wd_err" &
		;;
	*) return 0 ;;
	esac
	_wd_pid=$!
	disown "$_wd_pid" 2>/dev/null
	printf '%s\n' "$_wd_pid" > "$_wd_pid_file" 2>/dev/null
	_speedbackup_protect_pid "$_wd_pid" "${_tag}_watchdog"
	_speed_debug_log "DEX_WATCHDOG_START tag=$_tag pid=$_wd_pid class=$_class cmd=$_cmd socket=$_socket"
	return 0
}

_speedbackup_protect_pid "$SPEEDBACKUP_MAIN_PID" main_shell

_dex_exec_unfiltered() {
	_dex_export_classpath || return 1
	if [[ "$1" = "/system/bin" || "$1" = "${DEX_APP_PROCESS_BASE:-/system/bin}" ]]; then
		shift
	fi
	local _pid _rc _tag _class
	_class="${1:-unknown}"
	_tag="${DEX_APP_PROCESS_OOM_TAG:-app_process_oneshot}"
	{ command "$DEX_APP_PROCESS_BIN" "$DEX_APP_PROCESS_BASE" "$@" <&9 & } 9<&0
	_pid=$!
	_speedbackup_protect_pid "$_pid" "$_tag"
	wait "$_pid"
	_rc=$?
	_speed_debug_log "DEX_ONESHOT_CHILD_END tag=$_tag class=$_class pid=$_pid rc=$_rc"
	return "$_rc"
}

dex_hiddenapi_raw() {
	case "$1" in
	getPackageUid|getInstallSourceInfo|forceStopPackageBatch|forceStopPackageVerify|uidLiveState|uidObserverState|uidObserverProbe|uidObserverWatch|packageLiveState|setDisplayPowerMode|processObserverStart|processObserverStop|processObserverBatchStart|processObserverBatchStop|processObserverRestoreSessionStart|processObserverStatus|processObserverTop|processObserverForeground|appWakeBlockStart|appWakeBlockStop|appWakeBlockStatus|appWakeBlockRestoreObserverToken|appWakeBlockRestorePackage|appWakeBlockRestoreAll|appWakeBlockCleanupStale|uidNetBlockStart|uidNetBlockStop|uidNetBlockStatus|uidNetBlockRestorePackage|uidNetBlockRestoreAll|uidNetBlockCleanupStale|uidNetBlockProbe|cgroupFreezeStart|cgroupFreezeStop|cgroupFreezeStatus|cgroupFreezeRestorePackage|cgroupFreezeRestoreAll|cgroupFreezeCleanupStale)
		# 465/r16: HiddenApi hot commands require unified root daemon; old HiddenApi daemon fallback removed.
		# r111: processObserverStart/Stop 必須走 RootDaemon；global observer/target/session 都存在於 RootDaemon JVM。
		_root_daemon_call_args_hot hiddenapi "$@"
		local _rc=$?
		if [[ $_rc = 125 ]]; then
			_speed_debug_log "ROOT_DAEMON_REQUIRED_NO_FALLBACK ns=hiddenapi command=$1"
		fi
		return $_rc
		;;
	esac
	_dex_raw com.xayah.dex.HiddenApiUtil "$@"
}

dex_hiddenapi() {
	case "$1" in
	getPackageUid|getInstallSourceInfo)
		local _dex_out _dex_rc _dex_ctx
		_dex_ctx="$(_dex_context_from_args com.xayah.dex.HiddenApiUtil "$@")"
		_dex_out="${TMPDIR:-/data/local/tmp}/.dex_stdout_${$}_$RANDOM"
		dex_hiddenapi_raw "$@" > "$_dex_out"
		_dex_rc=$?
		_dex_translate_file "$_dex_out" "$_dex_ctx"
		_dex_filter_human_stdout < "$_dex_out"
		rm -f "$_dex_out" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
		return $_dex_rc
		;;
	esac
	_dex com.xayah.dex.HiddenApiUtil "$@"
}


dex_smbscan_raw() {
	_dex_exec_unfiltered com.xayah.dex.SmbScanUtil "$@"
}


# 423/424: app_details shell/jq 統一入口。
# 原則：Dex 不讀寫 JSON、不處理 jq filter；所有 app_details 規則仍由原生 jq 處理，
# 但外層主流程應盡量走這些集中函式，避免 SSAID/payload/app_state/統計規則散落各處。
_appdetails_jq_inplace() {
	local _file="$1"
	shift
	[[ -n $_file ]] || return 1
	jq_inplace "$_file" "$@"
}

_appdetails_merge_old_new_jq() {
	local _old="$1" _new="$2" _out="$3"
	[[ -s $_old && -s $_new && -n $_out ]] || return 1
	# 遠端舊資料先讀，本地新資料後覆蓋；仍保留 jq 原生語義，不走 Dex。
	jq -s '.[0] * .[1]' "$_old" "$_new" > "$_out" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
}

_appdetails_put_app_state_file() {
	local _file="$1" _entry="$2" _state_file="$3"
	[[ -s $_file && -n $_entry && -s $_state_file ]] || return 1
	# 432: normal backup 寫入新 AppState 時，若當前快照的 SSAID/installer 是 null，
	# 不覆蓋舊 app_details 內已有的有效值；避免不同遠端或短暫讀取失敗時把可恢復資訊洗成 null。
	_appdetails_jq_inplace "$_file" --arg entry "$_entry" --slurpfile state "$_state_file" '
		def valid($v): ($v != null and ($v|tostring) != "" and ($v|tostring) != "null");
		(.[$entry] // {}) as $old |
		($old.app_state.ssaid // $old.Ssaid // null) as $old_ssaid |
		($old.app_state.installer // $old.installer // null) as $old_installer |
		($state[0]
			| if ((valid(.ssaid)|not) and valid($old_ssaid)) then .ssaid = $old_ssaid else . end
			| if ((valid(.installer)|not) and valid($old_installer)) then .installer = $old_installer else . end
		) as $merged |
		.[$entry].app_state = $merged |
		.[$entry] |= del(.permissions, .special_access, .battery_settings, .battery_opt,
			.installer, .install_diagnostics, .Ssaid, .permission_policy_v2)
	'
}

_appdetails_set_field() {
	local _file="$1" _entry="$2" _key="$3" _value="$4"
	[[ -n $_file && -n $_entry && -n $_key ]] || return 1
	_appdetails_jq_inplace "$_file" --arg entry "$_entry" --arg key "$_key" --arg value "$_value" '.[$entry][$key] = $value'
}
_appdetails_set_entry_string() {
	_appdetails_set_field "$@"
}

_appdetails_set_payload_success() {
	local _file="$1" _entry="$2" _path_value="$3" _size_value="$4" _write_path="${5:-}" _date_value
	[[ -s $_file && -n $_entry ]] || return 1
	_date_value="$(date "+%Y.%m.%d %H:%M:%S")"
	if [[ -n $_write_path ]]; then
		_appdetails_jq_inplace "$_file" --arg e "$_entry" --arg p "$_path_value" --arg s "$_size_value" --arg d "$_date_value" '.[$e].path = $p | .[$e].Size = $s | .["Backup time"].date = $d'
	else
		_appdetails_jq_inplace "$_file" --arg e "$_entry" --arg s "$_size_value" --arg d "$_date_value" '.[$e].Size = $s | .["Backup time"].date = $d'
	fi
}
_appdetails_set_apk_meta() {
	local _file="$1" _entry="$2" _pkg="$3" _apk_version="$4"
	[[ -s $_file && -n $_entry && -n $_pkg ]] || return 1
	_appdetails_jq_inplace "$_file" --arg software "$_entry" --arg pkg "$_pkg" --arg apk_version "$_apk_version" '.[$software].PackageName = $pkg | .[$software].apk_version = $apk_version'
}
_appdetails_set_keystore() {
	local _file="$1" _entry="$2" _value="$3"
	[[ -s $_file && -n $_entry ]] || return 1
	case $_value in true|false) ;; *) _value=false ;; esac
	_appdetails_set_entry_string "$_file" "$_entry" keystore "$_value"
}
_appdetails_ensure_package_name() {
	local _file="$1" _entry="$2" _pkg="$3"
	[[ -s $_file && -n $_entry && -n $_pkg ]] || return 1
	_appdetails_jq_inplace "$_file" --arg software "$_entry" --arg pkg "$_pkg" 'if .[$software] then .[$software].PackageName = $pkg else . end'
}
_appdetails_sync_package_name_all() {
	local _file="$1" _pkg="$2"
	[[ -s $_file && -n $_pkg ]] || return 1
	_appdetails_jq_inplace "$_file" --arg name2 "$_pkg" 'walk(if type == "object" and .PackageName then .PackageName = $name2 else . end)'
}
_appdetails_is_nonempty() {
	local _file="$1"
	[[ -f $_file ]] || return 1
	[[ "$(jq 'length' "$_file" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null})" != "0" ]]
}
_appdetails_remove_if_empty() {
	local _file="$1"
	[[ -f $_file ]] || return 0
	[[ "$(jq 'length' "$_file" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null})" = "0" ]] && rm -f "$_file"
}
_appdetails_normalize_final() {
	local _file="$1" _tag="${2:-APPDETAILS_FINAL}"
	[[ -f $_file ]] || return 1
	_appdetails_is_nonempty "$_file" || return 1
	if _app_details_normalize_restore_profile_file "$_file"; then
		_speed_debug_log "${_tag}_PRETTY_OK app=$name1 package=$name2 file=$_file"
		return 0
	fi
	_speed_debug_log "${_tag}_PRETTY_FAIL app=$name1 package=$name2 file=$_file"
	return 1
}

_appdetails_json_parse_ok() {
	_json_parse_quiet_ok "$1"
}

_appdetails_jq_common_defs() {
	# 466/r17: app_details / JSON 中階 jq 定義集中；payload、entry、package、legacy/app_state 統計共用。
	cat <<'JQ'
def ad_objects: [.[] | objects];
def ad_pkg_entries: [to_entries[] | select((.value|type)=="object" and (.value.PackageName? != null))];
def ad_payload_entry($o):
	(($o|type)=="object") and (
		($o|has("Size")) or ($o|has("size")) or ($o|has("path")) or ($o|has("keystore")) or
		($o|has("apk_size")) or ($o|has("data_size")) or ($o|has("obb_size")) or
		($o|has("media_size")) or ($o|has("origin_size"))
	);
def ad_first_pkg: try ((ad_pkg_entries[0].value.PackageName // "") | tostring) catch "";
def ad_first_entry_name:
	try (if (ad_pkg_entries|length)>0 then (ad_pkg_entries[0].key // "") else ((to_entries[0].key // "") | tostring) end) catch "";
def ad_first_apk_version: try (([.[] | objects | select(.apk_version != null).apk_version] | .[0]) // "") catch "";
def ad_state_count: try ([.[] | objects | select(.app_state != null)] | length) catch 0;
def ad_legacy_state_count: try ([.[] | objects | select(.permissions != null or .special_access != null or .battery_settings != null or .Ssaid != null)] | length) catch 0;
def ad_appstate_ssaid_count: try ([.[] | objects | select(.app_state.ssaid != null)] | length) catch 0;
def ad_any_ssaid_count: try ([.[] | objects | select((.app_state.ssaid // .Ssaid) != null)] | length) catch 0;
def ad_required_meta_ok: try (type=="object" and ([.[] | objects | select(.PackageName != null and .apk_version != null)] | length > 0)) catch false;
def ad_first_ssaid: try ([.[]|objects|((.app_state.ssaid // .Ssaid) // empty)]|.[0]) catch "";
JQ
}

_appdetails_jq_read() {
	local _file="$1" _expr="$2"
	[[ -s $_file && -n $_expr ]] || { printf '\n'; return 1; }
	jq -r "$(_appdetails_jq_common_defs) $_expr" "$_file" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
}

_appdetails_jq_test() {
	local _file="$1" _expr="$2"
	[[ -s $_file && -n $_expr ]] || return 1
	jq -e "$(_appdetails_jq_common_defs) $_expr" "$_file" >/dev/null 2>&1
}

_appdetails_get_first_pkg() {
	_appdetails_jq_read "$1" 'ad_first_pkg'
}

_appdetails_get_first_entry_name() {
	_appdetails_jq_read "$1" 'ad_first_entry_name' | head -n 1
}

_appdetails_get_first_apk_version() {
	_appdetails_jq_read "$1" 'ad_first_apk_version'
}

_appdetails_get_field() {
	local _file="$1" _entry="$2" _key="$3"
	[[ -s $_file && -n $_entry && -n $_key ]] || { printf '\n'; return 1; }
	jq -r --arg e "$_entry" --arg k "$_key" 'try (.[$e][$k] // "") catch ""' "$_file" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
}
_appdetails_get_entry_string() {
	_appdetails_get_field "$@"
}

_appdetails_get_entry_apk_version() {
	_appdetails_get_entry_string "$1" "$2" apk_version
}

_appdetails_get_entry_size() {
	_appdetails_get_entry_string "$1" "$2" Size
}


_appdetails_get_entry_app_state_file() {
	local _file="$1" _entry="$2" _out="$3"
	[[ -s $_file && -n $_entry && -n $_out ]] || return 1
	jq -c --arg entry "$_entry" 'try (.[$entry].app_state // null) catch null' "$_file" > "$_out" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
}


_appdetails_get_first_ssaid() {
	_appdetails_jq_read "$1" 'ad_first_ssaid'
}

_appdetails_count_state() {
	_appdetails_jq_read "$1" 'ad_state_count'
}

_appdetails_count_legacy_state() {
	_appdetails_jq_read "$1" 'ad_legacy_state_count'
}

_appdetails_count_appstate_ssaid() {
	_appdetails_jq_read "$1" 'ad_appstate_ssaid_count'
}

_appdetails_count_any_ssaid() {
	_appdetails_jq_read "$1" 'ad_any_ssaid_count'
}

_appdetails_has_required_meta() {
	_appdetails_jq_test "$1" 'ad_required_meta_ok'
}

_appdetails_appstate_schema_ok() {
	local _file="$1"
	[[ -s $_file ]] || return 1
	jq -e '
		try all(.[] | objects | select(.app_state != null);
			(.app_state | type) == "object" and
			(.app_state.schemaVersion == 2) and
			(.app_state.recordType == "snapshot") and
			((.app_state.packageName // "") | type) == "string" and
			(.app_state.permissions | type) == "array" and
			(.app_state.specialAccess | type) == "object" and
			(.app_state.otherAppOps | type) == "array" and
			(.app_state.batterySettings | type) == "object") catch false
	' "$_file" >/dev/null 2>&1
}

_appdetails_appstate_items_ok() {
	local _file="$1"
	[[ -s $_file ]] || return 1
	jq -e '
		try all(.[] | objects | select(.app_state != null);
			all(.app_state.permissions[]?;
				(.name|type)=="string" and (.granted|type)=="boolean" and
				(.flags|type)=="number") and
			all(.app_state.otherAppOps[]?;
				(.op|type)=="number" and (.mode|type)=="number")) catch false
	' "$_file" >/dev/null 2>&1
}

_appdetails_has_key() {
	local _file="$1" _entry="$2" _key="$3"
	[[ -s $_file && -n $_entry && -n $_key ]] || return 1
	jq -e --arg e "$_entry" --arg k "$_key" 'try (.[$e] | has($k) and .[$k] != null) catch false' "$_file" >/dev/null 2>&1
}

_appdetails_read_summary() {
	local _file="$1" _out="$2"
	[[ -s $_file && -n $_out ]] || return 1
	jq -r '
		(try (([.[] | objects | select(.apk_version != null).apk_version] | .[0]) // "") catch ""),
		(try (([.[] | objects | select(.PackageName != null).PackageName] | .[0]) // "") catch ""),
		(try (."Backup time".date // "") catch ""),
		(try (.user.Size // "") catch ""),
		(try (.data.Size // "") catch ""),
		(try (.obb.Size // "") catch ""),
		(try (.user_de.Size // "") catch ""),
		(try (.media.Size // "") catch "")
	' "$_file" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} > "$_out"
}

_appdetails_release_entry_read() {
	local _file="$1" _entry="$2" _out="$3"
	[[ -s $_file && -n $_entry && -n $_out ]] || return 1
	jq -r --arg e "$_entry" '
		(try (.[$e].Size // "") catch ""),
		(try (([.[] | objects | select(.keystore != null).keystore] | .[0]) // "") catch ""),
		(try (.[$e].path // "") catch "")
	' "$_file" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} > "$_out"
}

_appdetails_get_backup_installer_value() {
	local _file="$1" _v
	[[ -s $_file ]] || { printf '\n'; return 1; }
	_v="$(jq -r 'try (([.[] | objects | select(.app_state != null).app_state | (.installer // .package.installer // .installDiagnostics.installing // "")] | .[0]) // "") catch ""' "$_file" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null})"
	if [[ -z $_v || $_v = null ]]; then
		_v="$(jq -r 'try (([.[] | objects | select(.installer != null).installer] | .[0]) // "") catch ""' "$_file" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null})"
	fi
	if [[ -z $_v || $_v = null ]]; then
		_v="$(jq -r 'try (([.[] | objects | select(.install_diagnostics != null).install_diagnostics | (.installer // .installing // "")] | .[0]) // "") catch ""' "$_file" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null})"
	fi
	printf '%s\n' "$_v"
}

_appdetails_validate_schema() {
	local _file="$1"
	[[ -s $_file ]] || return 1
	_appdetails_json_parse_ok "$_file" || return 1
	_appdetails_has_required_meta "$_file" || return 1
	_appdetails_appstate_schema_ok "$_file" || return 1
	_appdetails_appstate_items_ok "$_file" || return 1
	return 0
}

_appdetails_nullable_appstate_ok() {
	local _file="$1"
	[[ -s $_file ]] || return 1
	jq -e '
		try all(.[] | objects | select(.app_state != null);
			(.app_state|has("installer")) and (.app_state|has("ssaid"))
		) catch false
	' "$_file" >/dev/null 2>&1
}

_appdetails_refresh_build_current_json() {
	local _old_file="$1" _entry="$2" _pkg="$3" _state_file="$4" _out="$5"
	[[ -s $_old_file && -s $_state_file && -n $_entry && -n $_pkg && -n $_out ]] || return 1
	jq --arg e "$_entry" --arg p "$_pkg" --slurpfile state "$_state_file" '
		. as $old |
		($old[$e] // {}) as $oe |
		def pick_entry($o):
			reduce ["Size","size","apk_size","data_size","obb_size","media_size","origin_size","path","keystore","apk_version","versionCode"][] as $k
			({}; if (($o|type)=="object" and ($o|has($k))) then .[$k]=$o[$k] else . end);
		def is_payload_entry($o):
			(($o|type)=="object") and (
				($o|has("Size")) or ($o|has("size")) or ($o|has("path")) or ($o|has("keystore")) or
				($o|has("apk_size")) or ($o|has("data_size")) or ($o|has("obb_size")) or
				($o|has("media_size")) or ($o|has("origin_size"))
			);
		def old_ssaid($o): ($o.app_state.ssaid // $o.Ssaid // null);
		def preserve_ssaid($state; $old_entry):
			if (old_ssaid($old_entry) != null and (old_ssaid($old_entry)|tostring) != "" and (old_ssaid($old_entry)|tostring) != "null")
			then ($state | .ssaid = old_ssaid($old_entry))
			elif (($state|type)=="object" and ($state|has("ssaid"))) then $state
			else ($state | .ssaid = null) end;
		({} + (if ($old|has("Backup time")) then {"Backup time": $old["Backup time"]} else {} end)) |
		reduce ($old|to_entries[]) as $it (.;
			if ($it.key == "Backup time" or $it.key == $e) then .
			elif is_payload_entry($it.value) then .[$it.key] = pick_entry($it.value)
			else . end) |
		.[$e] = (
			pick_entry($oe) +
			{
				PackageName: ($oe.PackageName // $p),
				app_state: preserve_ssaid($state[0]; $oe)
			}
		)
	' "$_old_file" > "$_out" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
}

# 463: 啟動只驗證核心工具；高成本/情境工具改為首次使用時驗證一次。
# r55/494: 工具 SHA 收斂成單一 table；startup check 與 lazy verify 共用同一來源，避免雙清單不同步。
SPEEDBACKUP_TOOL_SHA_VERIFIED=""
_speedbackup_tool_sha_table() {
	cat <<'SB_TOOL_SHA_TABLE'
busybox 4d60ab3f5a59ebb2ca863f2f514e6924401b581e9b64f602665c008177626651
cgfreezer 696468f10697dcf9385af307f0f84a68fcf15a52ec433496aa10879c1f2b35b3
classes.dex 7a844a4445ff81fd012acaa0b3bbb504de39ef4c1befb622d6a4355c4d3483c1
cmd 08da8ac23b6e99788fd3ce6c19c7b5a083b2ad48be35963a48d01d6ee7f3bb6d
dex_check.sh 857633531cb62d9f9bfaf7df25f24adaa4823ef4f263c1a8e8e11494038cd938
eventwait 259059d2b274eb8c29814ee9900d6ec0f44d70a2cd71ac577a9f05c3a6b1b0c5
filewatch 5d68e29180c8c791f4e531f8e6a39ef6689dfa2ea1e0c17e837770375588c4e5
find 7fa812e58aafa29679cf8b50fc617ecf9fec2cfb2e06ea491e0a2d6bf79b903b
jq 6bc62f25981328edd3cfcfe6fe51b073f2d7e7710d7ef7fcdac28d4e384fc3d4
keycheck 50645ee0e0d2a7d64fb4a1286446df7a4445f3d11aefd49eeeb88515b314c363
netwatch f3d14295853e17a8a8e7f4ae19cdd53609334223db27b6271d4b0290524398b6
procwait 12606ecee8aea17b7b5572807b07409d267806e50bd7957f767cfd0eb13f2463
smbclient 1866c6199998dbccfa7e7a3727e51f274cafaa8cd18752d345c62e38f28031e8
speedscan e0e7ff4e5d7ec75c62a2624a3b4629372a2b5d52d3a42fb24d7ab9534c121bdb
tar 882639ac310a7eb4052c68c21cea02633307700f9cc8c7c469c2dd18d734a112
uidexec 2db1792a42e2d7672f08236e1f122be752c3f09d89a0d53c47d843798f2b956d
unixsock 9ae68885818809f285cc2b630f7e58767ceb81ab77f052e5387b25dcc1d7cf74
zstd 9ef4b54148699c9874cfd45aaf38e5cc950e5d168afdcf2edf58a2463f5561ed
SB_TOOL_SHA_TABLE
}
_speedbackup_tool_expected_sha() {
	local _want="$1" _file="" _sha=""
	[[ -n $_want ]] || return 1
	while read -r _file _sha; do
		[[ $_file = "$_want" ]] && { printf '%s\n' "$_sha"; return 0; }
	done <<SB_TOOL_SHA_LOOKUP
$(_speedbackup_tool_sha_table)
SB_TOOL_SHA_LOOKUP
	return 1
}
_speedbackup_tool_is_startup_core() {
	case "$1" in
	busybox|cmd|dex_check.sh|find|jq|tar|zstd) return 0 ;;
	*) return 1 ;;
	esac
}
_speedbackup_tool_mark_verified() {
	case " $SPEEDBACKUP_TOOL_SHA_VERIFIED " in *" $1 "*) ;; *) SPEEDBACKUP_TOOL_SHA_VERIFIED="$SPEEDBACKUP_TOOL_SHA_VERIFIED $1" ;; esac
}
_speedbackup_classes_dex_sha_warn() {
	local _path="$1" _hash="$2" _expected="$3"
	_speed_debug_log "WARN_CLASSES_DEX_SHA_MISMATCH allowed=1 path=$_path actual=$_hash expected=$_expected"
	# This helper is also called inside command substitutions and stdout redirects.
	# Only print to the terminal when stdout is really interactive; otherwise log only,
	# so the warning cannot contaminate appList.txt, backup_settings.conf, jq input, etc.
	if [ -t 1 ]; then
		echoRgb "⚠️ classes.dex SHA-256 與內建值不同，允許繼續；本版以核心 capability smoke 作為有效性驗證" "3"
	fi
}
_speedbackup_tool_verify_once() {
	local _file="$1" _required="${2:-1}" _hash="" _expected="" _path=""
	[[ -n $_file ]] || return 1
	case " $SPEEDBACKUP_TOOL_SHA_VERIFIED " in *" $_file "*) return 0 ;; esac
	_expected="$(_speedbackup_tool_expected_sha "$_file" 2>/dev/null)" || return 1
	_path="$tools_path/$_file"
	if [[ ! -f $_path ]]; then
		[[ $_required = 1 ]] && echoRgb "⚠️ 檔案 $_path 不存在" "0"
		return 1
	fi
	if [[ $_expected = VERSION_ONLY ]]; then
		# r19: classes.dex is user-local compiled from Dex source; SHA changes with build
		# environment/R8 output. The hard gate is runtime capability smoke, while
		# full release SHA256SUMS_PACKAGE still records the exact binary hash.
		_speedbackup_tool_mark_verified "$_file"
		_speed_debug_log "TOOL_SHA_VERIFY_ONCE file=$_file rc=0 mode=version_only"
		return 0
	fi
	_hash="$(sha256sum "$_path" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} | awk '{print $1; exit}')"
	if [[ $_hash != "$_expected" ]]; then
		case $_file in
		classes.dex) _speedbackup_classes_dex_sha_warn "$_path" "$_hash" "$_expected"; _speedbackup_tool_mark_verified "$_file"; return 0 ;;
		*) [[ $_required = 1 ]] && echoRgb "❌ $_path: SHA-256 不一致\n -\"$_hash\"" "0"; return 1 ;;
		esac
	fi
	_speedbackup_tool_mark_verified "$_file"
	_speed_debug_log "TOOL_SHA_VERIFY_ONCE file=$_file rc=0"
	return 0
}

quit=0
while read -r file expected_hash; do
	_speedbackup_tool_is_startup_core "$file" || { _speed_debug_log "STARTUP_SHA_DEFER file=$file"; continue; }
	if [[ -f $tools_path/$file ]]; then
		if [[ $expected_hash = VERSION_ONLY ]]; then
			_speed_debug_log "STARTUP_SHA_VERSION_ONLY file=$file reason=local-build-capability-gated"
			_speedbackup_tool_mark_verified "$file"
			continue
		fi
		computed_hash="$(sha256sum "$tools_path/$file" | awk '{print $1}')"
		if [[ $computed_hash = $expected_hash ]]; then
			echoRgb "✅ $file: 驗證通過"
		else
			# 遠端可選工具在純本機模式不刷提示；只有對應遠端啟用時才顯示。
			case $file in
			smbclient)
				if [[ $remote_type = smb ]]; then
					echoRgb "⚠️ $tools_path/$file: SHA-256 不一致，僅影響 SMB 遠端備份
 -\"$computed_hash\"" "0"
				else
					_speed_debug_log "OPTIONAL_REMOTE_TOOL_HASH_MISMATCH file=$file remote_type=${remote_type:-none}"
				fi
				;;
			classes.dex)
				_speedbackup_classes_dex_sha_warn "$tools_path/$file" "$computed_hash" "$expected_hash"
				;;
			*)
				echoRgb "❌ $tools_path/$file: SHA-256 不一致
 -\"$computed_hash\""
				quit=2; break ;;
			esac
		fi
	else
		# smbclient 是遠端可選工具；純本機模式不顯示遠端相關提示。
		case $file in
		smbclient)
			if [[ $remote_type = smb ]]; then
				echoRgb "⚠️ 檔案 $tools_path/$file 不存在 (僅影響 SMB 遠端備份)" "0"
			else
				_speed_debug_log "OPTIONAL_REMOTE_TOOL_MISSING file=$file remote_type=${remote_type:-none}"
			fi
			;;
		*)
			echoRgb "⚠️ 檔案 $tools_path/$file 不存在"
			quit=1
			break
			;;
		esac
	fi
done <<SB_TOOL_SHA_STARTUP
$(_speedbackup_tool_sha_table)
SB_TOOL_SHA_STARTUP

# v24.20.14-7.66-199：工具 SHA 驗證資訊允許短暫顯示；全部完成後只清屏一次。
# 後續設備資訊、使用者狀態、後台應用提示與主選單照常顯示，不再被主選單前清掉。
clear 2>/dev/null

# dex 啟動期能力驗證延後：選單前不再啟動 app_process/JVM，只保留 classes.dex 存在性檢查。
# 完整 HiddenApiUtil --version 仍會在實際功能使用 / speed_debug final tools_version.log 階段取得。
if [[ ! -f $tools_path/classes.dex ]]; then
	echoRgb "⚠️ 檔案 $tools_path/classes.dex 不存在" "0"
	quit=1
else
	_speed_debug_log "DEX_PRECHECK_DEFERRED stage=startup reason=no_startup_jvm"
fi

# log 目錄超過上限就清空 (避免長期累積佔空間)
# 上限由 conf 的 log_max_size_mb 控制 (預設 2MB, 0=關閉)
# 清理範圍:
#   - ${logfile%/*}/                                 (主腳本一般 log_yyyy-mm-dd_hh-mm.txt)
#   - $MODDIR/Backup_*/log/                        (備份模式一般 log)
#   - $MODDIR/Backup_*/*/log/                      (子目錄一般 log)
#   - ${logfile%/*}/ (恢復模式一般 log)
# 除錯類 log 已集中到 /data/speed_debug/run_xxx，不再寫入腳本 log 目錄。
cleanup_log_if_oversize() {
	# conf 沒設置 (空值) 也不清, 只有明確設正整數才啟用
	local max="$log_max_size_mb"
	[[ -z $max || $max = 0 ]] && return 0
	case $max in
	*[!0-9]*) return 0 ;;  # 非純數字直接跳過
	esac
	local max_kb=$((max * 1024))
	local d size_kb
	for d in "$MODDIR/log" "$MODDIR"/Backup_*/log "$MODDIR"/Backup_*/*/log; do
		[[ ! -d $d ]] && continue
		[[ -z $(ls -A "$d" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}) ]] && continue
		size_kb=$(du -sk "$d" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} | awk '{print $1}')
		if [[ ${size_kb:-0} -ge $max_kb ]]; then
			rm -rf "$d"/*
			echoRgb "log 目錄 $d 超過 ${max}MB, 已清空" "3"
		fi
	done
}

# 打印 tools 目錄內所有二進制版本到 speed_debug/tools_version.log
# 啟動時跑一次, 方便除錯時知道用戶用什麼版本工具；不寫入腳本 log 目錄。
print_tools_version() {
	local _ver_log="${SPEED_DEBUG_RUN_DIR:-/data/speed_debug}/tools_version.log" _dex_ver_line="" _evt
	# print_tools_version 只記錄已知資訊，不啟動 app_process/JVM 讀 dex --version。
	# 若本輪已有顯式查過版本，使用快取；否則只記 sha256，避免 speed_debug final 打包階段拖慢/喚醒 dex。
	_dex_ver_line="${SPEED_DEBUG_LAST_DEX_VERSION:-未查詢（print_tools_version 不啟動 dex）}"
	mkdir -p "${_ver_log%/*}" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	{
		echo "===== Tools version on $(date '+%Y-%m-%d %H:%M:%S') ====="
		echo "abi=$abi sdk=$sdk release=$release"
		echo ""
		# script / selftest metadata
		echo "[tools.sh]"
		echo "path: ${tools_path}/tools.sh"
		echo "backup_version=$backup_version"
		echo "speedbackup_patch_build=${speedbackup_patch_build:-}"
		[[ -f ${tools_path}/tools.sh ]] && echo "sha256: $(sha256sum "${tools_path}/tools.sh" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} | awk '{print $1}')"
		echo ""
		[[ -f ${tools_path}/dex_check.sh ]] && {
			echo "[dex_check.sh]"
			echo "path: ${tools_path}/dex_check.sh"
			echo "sha256: $(sha256sum "${tools_path}/dex_check.sh" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} | awk '{print $1}')"
			echo ""
		}
		# zstd
		which zstd >/dev/null 2>&1 && {
			echo "[zstd]"
			zstd --version 2>&1 | head -2
			echo ""
		}
		# tar
		which tar >/dev/null 2>&1 && {
			echo "[tar]"
			tar --version 2>&1 | head -2
			echo ""
		}
		# busybox
		which busybox >/dev/null 2>&1 && {
			echo "[busybox]"
			busybox 2>&1 | head -1
			echo ""
		}
		# jq
		which jq >/dev/null 2>&1 && {
			echo "[jq]"
			jq --version 2>&1
			echo ""
		}
		# find
		which find >/dev/null 2>&1 && {
			echo "[find]"
			find --version 2>&1 | head -1
			echo ""
		}
		# smbclient
		which smbclient >/dev/null 2>&1 && {
			echo "[smbclient]"
			smbclient --version 2>&1 | head -1
			echo ""
		}
		# Native event tools：優先記錄 PATH 解析到的工具，若未進 PATH 則 fallback 到 tools 目錄。
		for _evt in filewatch procwait eventwait unixsock netwatch uidexec speedscan; do
			_evt_bin="$(command -v "$_evt" 2>/dev/null)"
			[[ -z $_evt_bin && -x $filepath/$_evt ]] && _evt_bin="$filepath/$_evt"
			if [[ -n $_evt_bin && -x $_evt_bin ]]; then
				echo "[$_evt]"
				"$_evt_bin" --version 2>&1 | head -1
				echo "path: $_evt_bin"
				echo "sha256: $(sha256sum "$_evt_bin" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} | awk '{print $1}')"
				echo ""
			fi
		done
		unset _evt_bin
		_cg_bin="$(command -v cgfreezer 2>/dev/null)"
		[[ -z $_cg_bin && -x $filepath/cgfreezer ]] && _cg_bin="$filepath/cgfreezer"
		if [[ -n $_cg_bin && -x $_cg_bin ]]; then
			echo "[cgfreezer]"
			echo "path: $_cg_bin"
			echo "sha256: $(sha256sum "$_cg_bin" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} | awk '{print $1}')"
			"$_cg_bin" backend-probe 2>&1 | head -2
			echo ""
		fi
		unset _cg_bin
		# keycheck (沒 --version, 記 sha256)
		which keycheck >/dev/null 2>&1 && {
			echo "[keycheck]"
			echo "sha256: $(sha256sum "$(which keycheck)" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} | awk '{print $1}')"
			echo ""
		}
		# classes.dex
		[[ -f $tools_path/classes.dex ]] && {
			echo "[classes.dex]"
			echo "sha256: $(sha256sum "$tools_path/classes.dex" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} | awk '{print $1}')"
			echo ""
			echo "[HiddenApiUtil]"
			echo "${_dex_ver_line:-無法取得}"
			echo ""
		}
		# script 自己版本
		echo "[backup_script]"
		echo "backup_version=$backup_version"
		echo "speedbackup_patch_build=${speedbackup_patch_build:-}"
	} > "$_ver_log" 2>&1
	[[ ${SPEED_DEBUG_TOOLS_VERSION_SILENT:-0} = 1 ]] || echoRgb "工具版本已寫入 speed_debug 包內: tools_version.log" "2"
}

get_dex_version_line() {
	# 只在使用者/流程明確需要顯示 dex 版本時呼叫；print_tools_version 不會再透過此函式啟動 JVM。
	# 結果寫入 SPEED_DEBUG_LAST_DEX_VERSION 供 show_dex_version / 後續 debug 使用。
	if [[ -n ${SPEED_DEBUG_LAST_DEX_VERSION:-} ]]; then
		echo "$SPEED_DEBUG_LAST_DEX_VERSION"
		return 0
	fi
	[[ ! -f $tools_path/classes.dex ]] && { SPEED_DEBUG_LAST_DEX_VERSION="未找到classes.dex"; echo "$SPEED_DEBUG_LAST_DEX_VERSION"; return 0; }
	local _dex_raw _dex_line
	_dex_raw="$(_dex_exec_unfiltered com.xayah.dex.HiddenApiUtil --version 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null})"
	# 新版 dex 直接輸出: v13.1 build=20260621
	# 單次 awk 解析 v / build 並組好輸出行 (原 2 次 awk + shell if/elif → 1 次)
	_dex_line="$(echo "$_dex_raw" | awk '{
		v=""; b="";
		for(i=1;i<=NF;i++){
			if(v=="" && $i ~ /^v[0-9]/) v=$i;
			if(b=="" && $i ~ /^build=/){ b=$i; sub(/^build=/,"",b) }
		}
		if(v!="" && b!="") print v" build="b;
		else if(v!="") print v;
		else print "無法取得";
	}')"
	SPEED_DEBUG_LAST_DEX_VERSION="$_dex_line"
	echo "$SPEED_DEBUG_LAST_DEX_VERSION"
}

show_dex_version() {
	[[ ! -f $tools_path/classes.dex ]] && return 0
	local _dex_ver
	_dex_ver="${SPEED_DEBUG_LAST_DEX_VERSION:-}"
	[[ -z $_dex_ver ]] && _dex_ver="$(get_dex_version_line)"
	if [[ -n $_dex_ver && $_dex_ver != "無法取得" ]]; then
		echoRgb "dex版本: $_dex_ver" "3"
	else
		echoRgb "dex版本: 無法取得，可能 classes.dex 尚未包含 --version" "0"
	fi
}

# 通知欄獨立開關：1=開啟, 0=關閉
# v24.20.14-7.66-190：verify-noise-fix；宣告型 FGS 權限不做 runtime 硬錯，AppOps 驗證補用 scope detail。
# v24.20.14-7.66-191：debug-log-merge；speed_debug 不再產生 *_001/*_002 分片日誌，改寫入單一 aggregate log。
# v24.20.14-7.66-192：debug-semantic-decl-skip；FOREGROUND_SERVICE* 宣告型權限在 semantic debug 內標記略過 runtime 判定。
# v24.20.14-7.66-194：json-compact-fast-menu；permission_policy_v2 改成 compact/derived，tools_version 延後到打包前，縮短進入選單時間。
# v24.20.14-7.66-197：no-logo-no-startup-dex-version；以 7.66-194 為基底，只移除啟動第一屏與選單前 dex 版本/JVM 啟動。
# 主通知固定 TAG/ID，避免不同階段堆出多張 SpeedBackup 進度通知。
notification_enable="${notification_enable:-1}"
SPEEDBACKUP_NOTIFY_THROTTLE_MS="${SPEEDBACKUP_NOTIFY_THROTTLE_MS:-500}"
SPEEDBACKUP_NOTIFY_MAIN_TAG="${SPEEDBACKUP_NOTIFY_MAIN_TAG:-speedbackup_main}"
SPEEDBACKUP_NOTIFY_MAIN_ID="${SPEEDBACKUP_NOTIFY_MAIN_ID:-2020}"
SPEEDBACKUP_NOTIFY_ERROR_TAG="${SPEEDBACKUP_NOTIFY_ERROR_TAG:-speedbackup_error}"
SPEEDBACKUP_NOTIFY_ERROR_ID="${SPEEDBACKUP_NOTIFY_ERROR_ID:-2021}"
if [[ $notification_enable = 1 ]]; then
	_notification_notify_batch_send() {
		local _event="$1" _channel="$2" _tag="$3" _max="$4" _progress="$5" _indeterminate="$6" _ongoing="$7" _auto_cancel="$8" _only_alert_once="$9"
		shift 9
		local _text="$*" _tmp _pkg _android_tag _android_id _event_up _channel_lc
		[[ -z $_tag ]] && _tag="speedbackup"
		[[ -z $_event ]] && _event="INFO"
		[[ -z $_channel ]] && _channel="result"
		[[ -z $_max ]] && _max=0
		[[ -z $_progress ]] && _progress=0
		[[ -z $_indeterminate ]] && _indeterminate=0
		[[ -z $_ongoing ]] && _ongoing=0
		[[ -z $_auto_cancel ]] && _auto_cancel=1
		[[ -z $_only_alert_once ]] && _only_alert_once=1
		# r293: 通知文字硬保底，避免空 title/text 或 ROM service auto-template key 被原樣顯示。
		case $_text in
			''|*service_notification_apply_auto_template_title*|*service_notification_apply_auto_template_message*)
				_text="SpeedBackup 執行中"
				_speed_debug_log "NOTIFY_TEXT_SANITIZE tag=$_tag event=$_event mode=no-template-r293"
				;;
		esac
		_event_up="$(echo "$_event" | tr '[:lower:]' '[:upper:]')"
		_channel_lc="$(echo "$_channel" | tr '[:upper:]' '[:lower:]')"
		if [[ $_event_up == *ERROR* || $_event_up == *WARN* || $_event_up == *FAIL* || $_channel_lc = error ]]; then
			_android_tag="$SPEEDBACKUP_NOTIFY_ERROR_TAG"
			_android_id="$SPEEDBACKUP_NOTIFY_ERROR_ID"
		else
			_android_tag="$SPEEDBACKUP_NOTIFY_MAIN_TAG"
			_android_id="$SPEEDBACKUP_NOTIFY_MAIN_ID"
		fi
		_pkg="${SPEEDBACKUP_NOTIFY_PACKAGE:-}"
		_tmp="${TMPDIR:-/data/local/tmp}/.speedbackup_notify_batch_$$"
		{
			printf 'EVENT|%s\n' "$_event"
			printf 'TAG|%s\n' "$_android_tag"
			printf 'ID|%s\n' "$_android_id"
			printf 'CHANNEL|%s\n' "$_channel"
			printf 'TITLE|SpeedBackup\n'
			printf 'TEXT|%s\n' "$_text"
			printf 'BIGTEXT|%s\n' "$_text"
			[[ -n $_pkg ]] && printf 'PACKAGE|%s\n' "$_pkg"
			[[ -n ${SPEED_DEBUG_MAIN_LOG:-} ]] && printf 'LOG_PATH|%s\n' "$SPEED_DEBUG_MAIN_LOG"
			[[ -n ${SPEED_DEBUG_RUN_DIR:-} ]] && printf 'DIR_PATH|%s\n' "$SPEED_DEBUG_RUN_DIR"
			printf 'INBOX|1\n'
			printf 'ERROR_AGGREGATE|1\n'
			printf 'NO_ACTIONS|1\n'
			printf 'SINGLE_MAIN|1\n'
			printf 'THROTTLE_MS|%s\n' "$SPEEDBACKUP_NOTIFY_THROTTLE_MS"
			if [[ $_max -gt 0 || $_indeterminate = 1 ]]; then
				printf 'PROGRESS|%s|%s|%s\n' "$_max" "$_progress" "$_indeterminate"
				[[ $_max -gt 0 ]] && printf 'ITEMS|%s|%s\n' "$_progress" "$_max"
			fi
			printf 'ONGOING|%s\n' "$_ongoing"
			printf 'AUTO_CANCEL|%s\n' "$_auto_cancel"
			printf 'ONLY_ALERT_ONCE|%s\n' "$_only_alert_once"
			printf 'END\n'
		} > "$_tmp" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
		local _nout _rc
		_nout="$(_webdav_tmp_path root_notify_out)"
		_root_notify_call_file notifyBatch "$_tmp" "$_nout" >/dev/null 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
		_rc=$?
		if [[ $_rc = 125 ]]; then
			# 通知是非核心功能；unified root daemon 不可用時跳過通知，避免每次通知退回 app_process。
			_speed_debug_log "ROOT_NOTIFY_REQUIRED_SKIP_NO_SPAWN tag=$_android_tag id=$_android_id event=$_event"
			_rc=0
		fi
		rm -f "$_tmp" "$_nout" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
		return $_rc
	}
	notification() {
		local _tag="$1"
		shift
		_notification_notify_batch_send INFO result "$_tag" 0 0 0 0 1 1 "$@"
	}
	# 主流程固定使用同一個 TAG/ID 更新主通知；dex 端負責 500ms 節流、ETA、Inbox。
	# 用法: notification_progress <tag> <max> <progress> <content>
	notification_progress() {
		local _tag="$1" _max="$2" _progress="$3" _ongoing=1 _auto_cancel=0
		shift 3
		[[ -z $_max || $_max -le 0 ]] && _max=100
		[[ -z $_progress || $_progress -lt 0 ]] && _progress=0
		[[ $_progress -gt $_max ]] && _progress="$_max"
		if [[ $_max -gt 0 && $_progress -ge $_max ]]; then
			_ongoing=0
			_auto_cancel=1
		fi
		_notification_notify_batch_send PROGRESS progress "$_tag" "$_max" "$_progress" 0 "$_ongoing" "$_auto_cancel" 1 "$@"
	}
	# 不確定總進度時使用跑馬條
	# 用法: notification_indeterminate <tag> <content>
	notification_indeterminate() {
		local _tag="$1"
		shift
		_notification_notify_batch_send PROGRESS progress "$_tag" 0 0 1 1 0 1 "$@"
	}
else
	notification() { :; }
	notification_progress() { :; }
	notification_indeterminate() { :; }
fi
if [[ $quit -ne 0 ]]; then
exit "$quit"
fi
# r366: 全新目錄第一次啟動時先建立 legacy log 目錄，避免外層入口/後續 mirror 寫 log 失敗。
if [[ -n ${MODDIR:-} ]]; then
	mkdir -p "$MODDIR/log" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} || _speed_debug_log "LEGACY_LOG_DIR_CREATE_FAIL path=$MODDIR/log mode=r370"
fi
cleanup_log_if_oversize
# tools_version.log 改為延後到 speed_debug 打包前產生，避免啟動進選單變慢。
# 啟動第一屏已移除：不再顯示 Logo / RESTORE // SYNC / sleep / clear，直接進入後續流程。
# r403: TMPDIR 已在早期切到本輪專用 /data/local/tmp/.speedbackup_run_*；不要再重設回裸 /data/local/tmp。
# TMPDIR cleanup compatibility entry；r407 起不再逐檔清理，僅保留舊呼叫點相容。
cleanup_tmpdir_contents() {
	# r407: compatibility no-op only.
	# 本輪暫存已全部集中到 SPEEDBACKUP_RUN_TMPDIR；不在此函式維護任何檔名/前綴 rm 清單。
	_speed_debug_log "TMPDIR_INCREMENTAL_CLEANUP_SKIP reason=final_run_tmpdir_cleanup_only mode=r417" 2>/dev/null || true
	return 0
}
_speedbackup_run_tmpdir_init || exit 1
cleanup_tmpdir_contents || exit 1

# WebDAV 已全面改由 dex WebDavUtil；不再覆蓋/包裝外部 HTTP 工具，也不再依賴外部 DNS fallback。
if [[ $(which busybox) = "" ]]; then
	echoRgb "環境變量中沒有找到busybox 請在tools內添加一個\narm64可用的busybox\n或是安裝搞機助手 scene或是Magisk busybox模塊...." "0"
	exit 1
fi
if [[ $(which toybox | grep -Eo "system") != system ]]; then
	echoRgb "系統變量中沒有找到toybox" "0"
	exit 1
fi
#下列為自定義函數
# 原始資料輸出型 dex 指令不可走 _dex 翻譯包裝層。
# down 可能下載 JSON / zip 等 payload；ts 也輸出原始文字，因此走 _dex_raw，避免 grep/翻譯層污染或卡住。
down() {
	_dex_raw com.xayah.dex.HttpUtil get "$@"
}
ts() {
	case $SCRIPT_LANG in
	*CN* | *cn*) _dex_raw com.xayah.dex.CCUtil t2s "$@" ;;
	*) _dex_raw com.xayah.dex.CCUtil s2t "$@" ;;
	esac
}
alias LS="toybox ls -Zd"
alias mv="$get_mv"
# 給 trap / 流程控制用的 return 函數
# Set_back_0 永遠回 0 (成功), Set_back_1 永遠回 1 (失敗)
Set_back_0() {
	return 0
}
Set_back_1() {
	return 1
}
# 計算並輸出某段流程的耗時
# 用法: endtime <計時編號> <名稱>
# 計時編號: 1=讀 starttime1, 2=讀 starttime2 (需先在外面 set 變數)
# 輸出格式: " -<名稱>用時:X天X時X分X秒"
endtime() {
	case $1 in
	1) starttime="$starttime1" ;;
	2) starttime="$starttime2" ;;
	esac
	endtime="$(date -u "+%s")"
	duration="$(echo $((endtime - starttime)) | awk '{t=split("60 秒 60 分 24 時 999 天",a);for(n=1;n<t;n+=2){if($1==0)break;s=$1%a[n]a[n+1]s;$1=int($1/a[n])}print s}')"
	[[ $duration != "" ]] && echo " -$2用時:$duration" || echo " -$2用時:0秒"
}
# 安全百分比，避免 total=0 時除以 0
# 用法: safe_percent <current> <total>
safe_percent() {
	local cur="$1" total="$2"
	case $cur in ""|*[!0-9]*) cur=0 ;; esac
	case $total in ""|*[!0-9]*) total=0 ;; esac
	[[ $total -le 0 ]] && { echo 0; return 0; }
	[[ $cur -lt 0 ]] && cur=0
	[[ $cur -gt $total ]] && cur="$total"
	echo $((cur * 100 / total))
}

_keycheck_resolve_executable() {
	local _p="$1" _cmd
	[[ -n $_p ]] || return 1
	if [[ -x $_p ]]; then
		printf '%s\n' "$_p"
		return 0
	fi
	_cmd="$(command -v "$_p" 2>/dev/null)" || return 1
	[[ -x $_cmd ]] || return 1
	printf '%s\n' "$_cmd"
	return 0
}

_keycheck_path() {
	# r176: 不再另寫 keycheck SHA 判斷；只解析執行檔，完整性沿用既有工具 SHA 表與安裝校驗。
	local _p _path
	for _p in "${filepath:-/data/backup_tools}/keycheck" "${tools_path:-}/keycheck" keycheck; do
		_path="$(_keycheck_resolve_executable "$_p" 2>/dev/null)" || continue
		printf '%s\n' "$_path"
		return 0
	done
	return 1
}

_keycheck_output_code() {
	# r191: 只接受音量上/下輸出；其他 keycheck stdout 一律不轉成選單或顯示控制事件。
	local _token
	_token="$(printf '%s\n' "$1" | head -n 1 | tr -d '\r' | tr '[:upper:]' '[:lower:]' | sed 's/^[[:space:]]*//; s/[[:space:]]*$//')"
	case "$_token" in
	long_vol+|long_volume_up|long-volume-up|long_vol_up|long-vol-up|vol+|volume+|volume_up|volume-up|volumeup|vol_up|vol-up|volup|key_volumeup|key_volume_up|keycode_volume_up|115|24|*volume*up*|*vol*up*) echo 42 ;;
	long_vol-|long_volume_down|long-volume-down|long_vol_down|long-vol-down|vol-|volume-|volume_down|volume-down|volumedown|vol_down|vol-down|voldown|key_volumedown|key_volume_down|keycode_volume_down|114|25|*volume*down*|*vol*down*) echo 41 ;;
	none|timeout|"") echo 0 ;;
	*) return 1 ;;
	esac
}

_keycheck_read_code() {
	# r191 volume-only contract：輸出只允許音量上/下；無輸出時相容 42/41 與 46/47/56/57 音量退出碼。
	# 完整性仍由既有 _speedbackup_tool_sha_table()/安裝 SHA loop 負責，不在這裡自寫 hash 判斷。
	local _bin _rc _out _code _raw_log
	_bin="$(_keycheck_path 2>/dev/null)" || return 1
	# r197: keycheck 在 watcher stop 時會收到 SIGTERM。裸 assignment 回143在 set -e/mksh下會直接終止 watcher，
	# 必須放入條件式才能取得 rc 並走既有 143→none 正規化。
	if _out="$("$_bin" 2>/dev/null)"; then
		_rc=0
	else
		_rc=$?
	fi
	if [[ -n "$_out" ]]; then
		_code="$(_keycheck_output_code "$_out" 2>/dev/null)" && { printf '%s\n' "$_code"; return 0; }
		_raw_log="$(printf '%s\n' "$_out" | head -n 1 | tr -d '\r' | cut -c 1-96)"
		_speed_debug_log "KEYCHECK_OUTPUT_IGNORED raw=$_raw_log rc=$_rc allowed=volume_up_down"
		printf '%s\n' 0
		return 0
	fi
	case $_rc in
	42|46|56)
		[[ $_rc = 42 ]] || _speed_debug_log "KEYCHECK_VOLUME_RC_NORMALIZE source=exit rc=$_rc mapped=42 input=vol+"
		printf '%s\n' 42
		return 0
		;;
	41|47|57)
		[[ $_rc = 41 ]] || _speed_debug_log "KEYCHECK_VOLUME_RC_NORMALIZE source=exit rc=$_rc mapped=41 input=vol-"
		printf '%s\n' 41
		return 0
		;;
	0|124|143)
		# cleanup SIGTERM/timeout/none 都視為無輸入，避免 143 污染主退出碼。
		printf '%s\n' 0
		return 0
		;;
	*)
		_speed_debug_log "KEYCHECK_RC_IGNORED rc=$_rc allowed=42,41"
		printf '%s\n' 0
		return 0
		;;
	esac
}

_keycheck_code_name() {
	case "$1" in
	42) echo vol+ ;;
	41) echo vol- ;;
	0) echo none ;;
	*) echo "unknown_$1" ;;
	esac
}

_get_version_keycheck_native() {
	# r191: 選單只接受音量上=第一選項、音量下=第二選項。
	local _rc _name
	_keycheck_path >/dev/null 2>&1 || return 1
	while :; do
		_rc="$(_keycheck_read_code 2>/dev/null)"
		_name="$(_keycheck_code_name "$_rc")"
		case $_rc in
		42)
			[[ $Select_user = true ]] && branch="$1" || branch=true
			echoRgb "$1" "1"
			sleep 0.15
			return 0 ;;
		41)
			[[ $Select_user = true ]] && branch="$2" || branch=false
			echoRgb "$2" "0"
			sleep 0.15
			return 0 ;;
		0|"")
			echoRgb "等待輸入超時，請音量上=$1，音量下=$2" "2"
			continue ;;
		*)
			echoRgb "keycheck輸入無效: $_name($_rc)" "0"
			continue ;;
		esac
	done
}

nskg=1
# 從 GitHub Release API 取得腳本最新版本號
# 透過 CDN (ghfast / cloudflare worker) 加速避免被牆
get_version() {
	local _default_branch
	[[ $Select_user = true ]] && _default_branch="" || _default_branch=false
	# keyboard_input=1 時改用鍵盤輸入 (輸入1=$1, 0=$2), 否則維持音量鍵
	if [[ $keyboard_input = 1 ]]; then
		echoRgb "請輸入選項: 1=$1  0=$2" "2"
		unset _kv_option
		while true; do
			if [[ -n $_kv_option ]]; then
				case $_kv_option in
				1)
					[[ $Select_user = true ]] && branch="$1" || branch=true
					echoRgb "$1" "1"
					break ;;
				0)
					[[ $Select_user = true ]] && branch="$2" || branch=false
					echoRgb "$2" "0"
					break ;;
				*)
					echoRgb "$_kv_option參數錯誤 只能是0或1" "0"
					unset _kv_option ;;
				esac
			else
				if ! read _kv_option; then
					branch="$_default_branch"
					echoRgb "無互動 stdin，取消輸入" "0"
					return 1
				fi
			fi
		done
		return
	fi
	# r191: keycheck 只接受音量上/下；完整性仍由既有工具 SHA 安裝流程負責。
	if _get_version_keycheck_native "$1" "$2"; then
		return
	fi
	# r308: keycheck 不可用時不要在背景/無 tty 場景無限循環；安全地取消本次互動。
	branch="$_default_branch"
	echoRgb "keycheck錯誤，無法取得音量鍵輸入" "0"
	if [[ ${background_execution:-0} = 1 || ! -t 0 ]]; then
		echoRgb "背景或無互動 stdin，取消等待避免卡死" "0"
	fi
	return 1
}
# AppState / Permission / AppOps 顯示本地化已搬到 Dex。
# tools.sh 只保留薄 wrapper：raw 欄位仍用於恢復/驗證，cn 欄位只用於終端顯示。
_appstate_dex_localize() {
	local _type="$1" _key="$2" _in _out _val
	[[ -n $_type && -n $_key ]] || return 1
	_in="$TMPDIR/.appstate_localize_in_${$}_$RANDOM"
	_out="$TMPDIR/.appstate_localize_out_${$}_$RANDOM"
	# 425: AppState diff/localize 熱路徑不再呼叫外部 printf；避免大 AppState 存在時 Android shell 報 Argument list too long。
	{
		cat <<EOF_APPSTATE_LOCALIZE
$_type	$_key
EOF_APPSTATE_LOCALIZE
	} > "$_in" 2>/dev/null || return 1
	if _root_appstate_call localize "$_in" "$_out"; then
		_val="$(awk -F'	' 'NF>=3 {print $3; exit}' "$_out" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null})"
		rm -f "$_in" "$_out" 2>/dev/null
		[[ -n $_val ]] && { echo "$_val"; return 0; }
	else
		_speed_debug_log "APPSTATE_LOCALIZE_FAIL type=$_type key=$_key"
	fi
	rm -f "$_in" "$_out" 2>/dev/null
	return 1
}

# 權限全名 → 中文名稱對照：Dex 解析；查不到回 raw。
_perm_cn() {
	_appstate_dex_localize perm "$1" || echo "$1"
}

# canonical AppState 的 mode/特殊存取顯示：Dex 解析；查不到保留 raw。
_appstate_mode_cn() {
	_appstate_dex_localize mode "$1" || echo "模式$1"
}
_appstate_bool_cn() {
	case "$1" in
	true|1) echo "是" ;;
	false|0) echo "否" ;;
	null|'') echo "未設定" ;;
	missing) echo "已移除" ;;
	*) echo "$1" ;;
	esac
}
_appstate_special_cn() {
	_appstate_dex_localize special "$1" || _perm_cn "$1"
}
_battery_cn() {
	case "$1" in
	RUN_IN_BACKGROUND|BATTERY:RUN_IN_BACKGROUND) echo "背景執行" ;;
	RUN_ANY_IN_BACKGROUND|BATTERY:RUN_ANY_IN_BACKGROUND) echo "任意背景執行" ;;
	deviceidleWhitelist|BATTERY:deviceidle_whitelist) echo "Doze白名單" ;;
	*) echo "$1" ;;
	esac
}

# 顯示兩份 schema v2 canonical AppState 的實際差異。
# 只負責 UI 翻譯，不參與備份、恢復或驗證判斷。
_appstate_show_backup_diff_file() {
	local _old_file="$1" _new_file="$2" _diff="$TMPDIR/.appstate_diff_${$}_$RANDOM"
	local _kind _key _a _b _c _d _e _f _label _msg _count=0 _flags_a _flags_b _tab
	[[ -s $_old_file && -s $_new_file ]] || return 0
	jq -e 'type=="object" and .schemaVersion==2' "$_old_file" >/dev/null 2>&1 || return 0
	jq -e 'type=="object" and .schemaVersion==2' "$_new_file" >/dev/null 2>&1 || return 0
	# 424/425: old/new AppState 都用檔案傳給 jq；差異解析也不再呼叫外部 printf。
	jq -s -r '
		.[0] as $old | .[1] as $new |
		def idx($a;$k): reduce ($a[]? | select(type=="object")) as $x ({}; .[($x[$k]|tostring)]=$x);
		def sv($x): if $x == null then "null" else ($x|tostring) end;
		($old.permissions // [] | idx(. ;"name")) as $op |
		($new.permissions // [] | idx(. ;"name")) as $np |
		(
			($np|to_entries[] | .key as $k | .value as $n | ($op[$k] // null) as $o |
				if $o == null then empty
				elif (($o.granted//null)!=($n.granted//null) or (($o.appOpMode//null)!=($n.appOpMode//null)) or ($o.flags//0)!=($n.flags//0)) then
					["PERMISSION",$k,sv($o.granted),sv($n.granted),sv($o.appOpMode),sv($n.appOpMode),sv($o.flags//0),sv($n.flags//0)]|@tsv
				else empty end),
			($op|to_entries[] | select($np[.key] == null) |
				["PERMISSION",.key,sv(.value.granted),"missing",sv(.value.appOpMode),"missing",sv(.value.flags//0),"missing"]|@tsv)
		),
		($old.specialAccess // {}) as $os |
		($new.specialAccess // {}) as $ns |
		($ns|to_entries[] | .key as $k | .value as $n | ($os[$k] // null) as $o |
			if $o != null and (($o.mode//null)!=($n.mode//null))
			then ["SPECIAL",$k,sv($o.mode),sv($n.mode),"","","",""]|@tsv else empty end),
		($old.otherAppOps // [] | idx(. ;"publicName")) as $oo |
		($new.otherAppOps // [] | idx(. ;"publicName")) as $no |
		($no|to_entries[] | .key as $k | .value as $n | ($oo[$k]//null) as $o |
			if $o != null and (($o.mode//null)!=($n.mode//null))
			then ["APPOP",$k,sv($o.mode),sv($n.mode),"","","",""]|@tsv else empty end),
		(["RUN_IN_BACKGROUND","RUN_ANY_IN_BACKGROUND"][] as $k |
			(($old.batterySettings[$k]//null) as $o | ($new.batterySettings[$k]//null) as $n |
			if $o != null and $n != null and (($o.mode//null)!=($n.mode//null))
			then ["BATTERY",$k,sv($o.mode),sv($n.mode),"","","",""]|@tsv else empty end)),
		(if (($old.batterySettings.deviceidleWhitelist//null)!=($new.batterySettings.deviceidleWhitelist//null))
			then ["BATTERY","deviceidleWhitelist",sv($old.batterySettings.deviceidleWhitelist),sv($new.batterySettings.deviceidleWhitelist),"","","",""]|@tsv else empty end),
		(if (($old.ssaid//null)!=($new.ssaid//null)) then ["SSAID","value","changed","changed","","","",""]|@tsv else empty end)
	' "$_old_file" "$_new_file" > "$_diff" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} || { rm -f "$_diff" 2>/dev/null; return 0; }
	[[ -s $_diff ]] || { rm -f "$_diff" 2>/dev/null; return 0; }
	_count="$(awk 'NF{n++} END{print n+0}' "$_diff" 2>/dev/null)"
	echoRgb "AppState狀態變更 $_count 項" "2"
	_tab="	"
	while IFS="$_tab" read -r _kind _key _a _b _c _d _e _f; do
		case $_kind in
		PERMISSION)
			_label="$(_perm_cn "$_key")"; _msg=""
			[[ $_a != $_b ]] && _msg="授予:$(_appstate_bool_cn "$_a")→$(_appstate_bool_cn "$_b")"
			[[ $_c != $_d ]] && _msg="${_msg:+$_msg  }AppOps:$(_appstate_mode_cn "$_c")→$(_appstate_mode_cn "$_d")"
			if [[ $_e != $_f ]]; then
				_flags_a="$_e"; _flags_b="$_f"
				[[ $_flags_a = missing ]] && _flags_a="已移除"
				[[ $_flags_b = missing ]] && _flags_b="已移除"
				[[ $_flags_a = null ]] && _flags_a="未設定"
				[[ $_flags_b = null ]] && _flags_b="未設定"
				_msg="${_msg:+$_msg  }flags:${_flags_a}→${_flags_b}"
			fi
			echoRgb "$_label: $_msg"
			;;
		SPECIAL)
			_label="$(_appstate_special_cn "$_key")"
			echoRgb "$_label: AppOps $(_appstate_mode_cn "$_a")→$(_appstate_mode_cn "$_b")"
			;;
		APPOP)
			_label="$(_perm_cn "$_key")"
			echoRgb "$_label: $(_appstate_mode_cn "$_a")→$(_appstate_mode_cn "$_b")"
			;;
		BATTERY)
			_label="$(_battery_cn "$_key")"
			case $_key in
			deviceidleWhitelist) echoRgb "$_label: $(_appstate_bool_cn "$_a")→$(_appstate_bool_cn "$_b")" ;;
			*) echoRgb "$_label: $(_appstate_mode_cn "$_a")→$(_appstate_mode_cn "$_b")" ;;
			esac
			;;
		SSAID) echoRgb "SSAID已變更" "2" ;;
		esac
	done < "$_diff"
	[[ -n ${SPEED_DEBUG_DEX_HUMAN_LOG:-} ]] && cat "$_diff" >> "$SPEED_DEBUG_DEX_HUMAN_LOG" 2>/dev/null
	rm -f "$_diff" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
}


# 規範化布林值,將 1/true/yes 等變成 true,其他變成 false
# 用於 conf 讀進來的開關項統一格式
isBoolean() {
	nsx="$1"
	case $1 in
	1|true|True|TRUE)
		nsx=true ;;
	0|false|False|FALSE)
		nsx=false ;;
	*)
		echoRgb "$conf_path $2=$1填寫錯誤，正確值1or0" "0"
		exit 2 ;;
	esac
}
# 根據上一條命令的退出碼輸出成功/失敗訊息
# 用法: echo_log "操作名稱" [skip_success_msg]
# 第二個參數非空時, 成功不輸出訊息 (只設變數)
echo_log() {
	local _echo_last="$?" _echo_forced="${3:-}"
	[[ -n $_echo_forced ]] && _echo_last="$_echo_forced"
	if [[ $_echo_last = 0 ]]; then
		[[ $2 = "" ]] && echoRgb "$1成功" "1"
		_speed_debug_log "OK: $1"
		result=0
		Set_back_0
	else
		echoRgb "$1失敗，過世了" "0"
		_speed_debug_log "FAIL: $1"
		notification "$RANDOM" "$name1: $1失敗，過世"
		result=1
		Set_back_1
	fi
}
# r189: 舊備份程序被強制終止時，EXIT trap 可能來不及執行。
# 此 helper 定義在 kill_Serve 前，直接用已存在的 dex_hiddenapi bridge 還原亮屏與原始 timeout。
_speedbackup_display_emergency_restore_early() {
	local _reason="${1:-emergency}" _scr_save="${TMPDIR:-/data/local/tmp}/.screen_timeout_orig" _req_save="${TMPDIR:-/data/local/tmp}/.screen_timeout_requested" _applied_save="${TMPDIR:-/data/local/tmp}/.screen_timeout_applied" _orig="" _current="" _requested="${_DISPLAY_TIMEOUT_REQUESTED_MS:-2147483647}" _applied="" _had_state=0 _force_wake=0 _get_rc=0 _put_rc=0 _get_timeout _put_timeout
	_get_timeout="${SPEEDBACKUP_DISPLAY_SETTINGS_GET_TIMEOUT_MS:-2000}"
	_put_timeout="${SPEEDBACKUP_DISPLAY_SETTINGS_PUT_TIMEOUT_MS:-5000}"
	[[ -s $_scr_save || -s $_req_save || -s $_applied_save ]] && _had_state=1
	case $_reason in killed_old_process|stale_lock_dead) _force_wake=1 ;; esac
	if [[ -s $_scr_save ]]; then
		_orig="$(cat "$_scr_save" 2>/dev/null)"
		case $_orig in ''|*[!0-9]*) _orig="" ;; esac
		_current="$(_speedbackup_settings_get_system_bounded screen_off_timeout "$_get_timeout" display_timeout_emergency_current)"
		_get_rc=$?
		# r468: emergency compare-and-restore remains bounded; Dex direct first, shell fallback.
		if [[ -n $_orig ]]; then
			if [[ -s $_req_save ]]; then
				_requested="$(cat "$_req_save" 2>/dev/null)"
				case $_requested in ''|*[!0-9]*) _requested="${_DISPLAY_TIMEOUT_REQUESTED_MS:-2147483647}" ;; esac
			fi
			_applied="$_requested"
			if [[ -s $_applied_save ]]; then
				_applied="$(cat "$_applied_save" 2>/dev/null)"
				case $_applied in ''|*[!0-9]*) _applied="$_requested" ;; esac
			fi
			if [[ $_get_rc = 0 && $_current = "$_applied" ]]; then
				_speedbackup_settings_put_system_bounded screen_off_timeout "$_orig" "$_put_timeout" display_timeout_emergency_put >/dev/null 2>&1
				_put_rc=$?
			fi
		fi
	fi
	rm -f "$_scr_save" "${TMPDIR:-/data/local/tmp}/.screen_timeout_requested" "${TMPDIR:-/data/local/tmp}/.screen_timeout_applied" "${TMPDIR:-/data/local/tmp}/.screen_timeout_session_id" "${TMPDIR:-/data/local/tmp}/.screen_timeout_backend" 2>/dev/null
	if [[ $_had_state = 1 || $_force_wake = 1 ]]; then
		setDisplay 2 >/dev/null 2>&1 || _dex_raw com.xayah.dex.HiddenApiUtil setDisplayPowerMode 2 >/dev/null 2>&1 || true
		input keyevent 224 >/dev/null 2>&1 || true
		rm -f "${TMPDIR:-/data/local/tmp}"/.speedbackup_display_*_watcher* \
			"${TMPDIR:-/data/local/tmp}"/.speedbackup_display_*_hint_shown 2>/dev/null
		_speed_debug_log "DISPLAY_EMERGENCY_RESTORE reason=$_reason mode=2 timeout=${_orig:-none} hadState=$_had_state forceWake=$_force_wake getRc=$_get_rc putRc=$_put_rc backend=bounded-shell mode=r473"
	else
		_speed_debug_log "DISPLAY_EMERGENCY_RESTORE_SKIP reason=$_reason hadState=0 forceWake=0 backend=bounded-shell mode=r473"
	fi
	return 0
}
# lock 清理保底：不要依賴 kill_Serve() 內的 local LOCK_DIR，避免 EXIT trap 執行時 local 已失效導致 /data/.backup_lock 殘留。
SPEEDBACKUP_LOCK_DIR="${SPEEDBACKUP_LOCK_DIR:-/data/.backup_lock}"
SPEEDBACKUP_LOCK_OWNER_PID="${SPEEDBACKUP_LOCK_OWNER_PID:-$$}"
_speedbackup_lock_cleanup() {
	local _lock="${SPEEDBACKUP_LOCK_DIR:-/data/.backup_lock}" _pid="" _owner="${SPEEDBACKUP_LOCK_OWNER_PID:-$$}"
	[[ -n $_lock && $_lock = /data/.backup_lock ]] || { _speed_debug_log "LOCK_CLEAN_SKIP invalid_lock=$_lock"; return 0; }
	[[ -d $_lock ]] || return 0
	if [[ -f $_lock/pid ]]; then
		_pid="$(cat "$_lock/pid" 2>/dev/null)"
		# 只清自己本輪建立的 lock；如果 pid 不是本輪 shell，避免誤刪另一個正在跑的腳本 lock。
		if [[ $_pid = "$_owner" || $_pid = "$$" ]]; then
			rm -rf "$_lock" 2>/dev/null && _speed_debug_log "LOCK_CLEANED pid=$_pid lock=$_lock"
		else
			_speed_debug_log "LOCK_CLEAN_SKIP owner_mismatch lock_pid=$_pid owner=$_owner self=$$"
		fi
	else
		# 沒 pid 的 lock 只會來自建立中斷或舊版殘留；若目前不是另一輪已知 lock，安全清掉。
		rm -rf "$_lock" 2>/dev/null && _speed_debug_log "LOCK_CLEANED empty_pid lock=$_lock"
	fi
}
# 殺死先前殘留的腳本進程,並設置 lock 防止重複執行
# trap EXIT 會清 lock 並觸發 remote_cleanup (若有遠端設定)
kill_Serve() {
	SPEEDBACKUP_LOCK_DIR="/data/.backup_lock"
	SPEEDBACKUP_LOCK_OWNER_PID="$$"
	local LOCK_DIR="$SPEEDBACKUP_LOCK_DIR"
	local MY_PID="$SPEEDBACKUP_LOCK_OWNER_PID"
	# 使用 mkdir 作為原子鎖操作，避免 TOCTOU 競態條件
	if ! mkdir "$LOCK_DIR" 2>/dev/null; then
		if [[ -f $LOCK_DIR/pid ]]; then
			OLD_PID="$(cat "$LOCK_DIR/pid")"
			if kill -0 "$OLD_PID" 2>/dev/null; then
				echo "發現先前的備份程序 (PID=$OLD_PID)，將其終止"
				# 單次 ps 快照 + awk 一次算出待殺清單: 舊程序整棵子孫樹 + 殘留 start.sh/tools.sh (排除自己祖先鏈)
				local _kp _psbin="/system/bin/ps"
				[[ -x $_psbin ]] || _psbin="ps"
				# self 整條祖先鏈 + 自己的子孫樹 一律保護 (避免殺到自己 / 自己起的 ps 子進程)
				for _kp in $($_psbin -e -o pid=,ppid=,args= 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} | awk -v root="$OLD_PID" -v self="$$" -v me="$MY_PID" '
					{ ppid[$1]=$2; cmd[$1]=$0 }
					END {
						# 保護: self 與 MY_PID 的祖先鏈
						for (start_pid in ppid) {}
						split(self" "me, seeds, " ")
						for (k in seeds) { p=seeds[k]; while (p>1 && (p in ppid)) { safe[p]=1; p=ppid[p] } safe[seeds[k]]=1 }
						# 保護: self/me 的子孫樹
						sm[self]=1; sm[me]=1; ch=1
						while (ch) { ch=0; for (x in ppid) if (!(x in sm) && (ppid[x] in sm)) { sm[x]=1; ch=1 } }
						for (x in sm) safe[x]=1
						# 待殺: 舊程序子孫樹 + 殘留 start.sh/tools.sh, 扣除保護集
						mark[root]=1; ch=1
						while (ch) { ch=0; for (x in ppid) if (!(x in mark) && (ppid[x] in mark)) { mark[x]=1; ch=1 } }
						for (x in cmd) if (cmd[x] ~ /start\.sh|tools\.sh/) mark[x]=1
						for (x in mark) if (!(x in safe)) print x
					}'); do
					kill -0 "$_kp" 2>/dev/null && kill -KILL "$_kp" 2>/dev/null
				done
				# 舊程序已被終止，清掉舊 lock，避免下次啟動再看到 stale lock。
				rm -rf "$LOCK_DIR" 2>/dev/null
				_speedbackup_display_emergency_restore_early killed_old_process || true
				_speed_debug_log "LOCK_CLEANED killed_old_pid=$OLD_PID lock=$LOCK_DIR displayRestored=1"
				echo "結束自身，避免重複執行"
				exit 1
			else
				_speedbackup_display_emergency_restore_early stale_lock_dead || true
				_speed_debug_log "STALE_LOCK_CLEARED pid=$OLD_PID lock=$LOCK_DIR displayRestored=1"
				rm -rf "$LOCK_DIR"
				mkdir "$LOCK_DIR" 2>/dev/null || exit 1
			fi
		else
			rm -rf "$LOCK_DIR"
			mkdir "$LOCK_DIR" 2>/dev/null || exit 1
		fi
	fi
	echo "$MY_PID" > "$LOCK_DIR/pid"
	# r206: 若前一次異常退出但 lock 已不存在/已被清掉，仍先用 shell-only marker 嘗試還原 timeout，避免 cleanup_tmpdir_contents 刪掉唯一原始值。
	_speedbackup_display_emergency_restore_early startup_stale_timeout || true
	# r407: TMPDIR 暫存不在 kill_Serve/EXIT 內逐檔清理；只處理 runtime guard / daemon / lock 類收尾。
    _speedbackup_kill_dirsize_workers() {
    	local _pid
    	for _pid in ${SPEEDBACKUP_DIRSIZE_PIDS:-}; do
    		kill -0 "$_pid" 2>/dev/null && kill -TERM "$_pid" 2>/dev/null
    	done
    	for _pid in ${SPEEDBACKUP_DIRSIZE_PIDS:-}; do
    		kill -0 "$_pid" 2>/dev/null && kill -KILL "$_pid" 2>/dev/null
    	done
    	unset SPEEDBACKUP_DIRSIZE_PIDS
    }
    _speedbackup_call_if_exists() {
    	# 446: 入口 wrapper / source 失敗或舊腳本混用時，EXIT cleanup 不應因函數未定義污染 stderr。
    	local _fn="$1"
    	shift
    	command -v "$_fn" >/dev/null 2>&1 || return 0
    	"$_fn" "$@"
    }
    _cleanup_tmp_files() {
    	# EXIT 收尾必須做完整清理，不保留恢復主迴圈的 session maps / batch queue。
    	# r324: menu/getlist/update 等非備份/恢復流程不應觸發螢幕/無操作息屏還原文案或 display-on；
    	# 只有本輪真的開過 display timeout / watcher session，才做 restore。
    	if command -v _display_timeout_session_active >/dev/null 2>&1 && _display_timeout_session_active; then
    		if [[ "${_SPEEDBACKUP_DISPLAY_RESTORE_DEFERRED:-0}" = 1 ]]; then
    			# r440: 正常流程已要求把 timeout 還原延到 EXIT 最後一步；
    			# 這裡只記錄，不提前還原，避免螢幕關閉後卡住後續 final-pack-skip / tmpdir cleanup。
    			_speed_debug_log "EXIT_DISPLAY_RESTORE_DEFER requested=1 reason=pending-final-exit active=1 packed=${SPEED_DEBUG_PACKED:-0} mode=r440"
    		else
    			_speedbackup_call_if_exists Set_screen_pause_seconds off
    			_speed_debug_log "EXIT_DISPLAY_RESTORE requested=1 reason=active-display-session mode=r440"
    		fi
    	else
    		_speed_debug_log "EXIT_DISPLAY_RESTORE_SKIP requested=0 reason=no-active-display-session mode=r440"
    	fi
    	_RESTORE_KEEP_SESSION_MAPS=0
    	_RESTORE_PRESERVE_BATCH_QUEUE=0
    	_speedbackup_kill_dirsize_workers
    	_speedbackup_call_if_exists _process_observer_stop_all exit_cleanup
    	_speedbackup_call_if_exists _uid_netblock_stop_all exit_cleanup
    	_speedbackup_call_if_exists _cgroup_freezer_stop_all exit_cleanup
    	_speedbackup_call_if_exists _cgroup_freezer_cleanup_stale_now exit_cleanup 0
    	_speedbackup_call_if_exists _cgroup_freezer_daemon_final_stop_unlink exit_cleanup
    	_speedbackup_call_if_exists _live_app_resume_paused
    	_speedbackup_call_if_exists _remote_netwatch_report
		_speedbackup_call_if_exists _remote_smbclient_stop_active exit_cleanup
    	_speedbackup_call_if_exists _remote_netwatch_stop
    	_speedbackup_call_if_exists _webdav_daemon_stop
    	_speedbackup_call_if_exists _webdav_mkcol_cache_clear_current
    	_speedbackup_call_if_exists _root_daemon_stop
    	_speedbackup_call_if_exists _install_daemon_stop
    	_speedbackup_call_if_exists _speedbackup_root_tmp_state_cleanup exit_cleanup
    	# r407/r487: 本輪一般暫存、Dex state、socket、SMB pid bucket 均在 run tmpdir；成功/退出收尾後 TTL=0 清理並刪整個 run tmpdir。
    	_speed_debug_log "TMPDIR_RUN_FINAL_CLEANUP_READY path=${SPEEDBACKUP_RUN_TMPDIR:-} stateScope=run-tmpdir mode=r487"
    }
    _speedbackup_exit_code_normalize() {
    	# r198: watcher 正常 stop 必須由獨立 exec shell自行 exit 0；不再掩蓋任何 143。
    	# 若主腳本真的收到 SIGTERM，保留真實退出碼供 debug/外層判斷。
    	printf '%s\n' "$1"
    }
    _speedbackup_exit_trap() {
    	local _ec="$?" _trap_err
    	_ec="$(_speedbackup_exit_code_normalize "$_ec" 2>/dev/null)"
    	_speed_debug_disarm_if_run_gone
    	_trap_err="$(_speed_debug_stderr_target)"
    	if [[ "${SPEEDBACKUP_ENTRY_QUIET_TRAP:-0}" = 1 ]]; then _speed_debug_log "trap信號成功接受EXIT，退出腳本(exit=$_ec)"; else echoRgb "trap信號成功接受EXIT，退出腳本(exit=$_ec)" "3"; fi
	if [[ "${_SPEEDBACKUP_NORMAL_FINISH_EXIT_FAST:-0}" = 1 && "${SPEED_DEBUG_PACKED:-0}" = 1 ]]; then
		# r489: fast-skip only after giving run tmpdir deletion one last bounded/synchronous chance.
		if [[ -n ${SPEEDBACKUP_RUN_TMPDIR:-} && -d ${SPEEDBACKUP_RUN_TMPDIR:-} ]]; then
			_speedbackup_run_tmpdir_final_cleanup >/dev/null 2>&1 || true
		fi
		_speed_debug_pack_log "[speed_debug] EXIT快速跳過重複收尾: exit=$_ec reason=normal_finish_already_packed runTmpdir=${SPEEDBACKUP_RUN_TMPDIR:-} mode=r489"
		return "$_ec"
	fi
    	# 預設不在 EXIT 裡做 snapshot，避免同一次退出打包兩次。
    	# 只有 SPEED_DEBUG_SNAPSHOT_ON_EXIT=1 時才先留安全快照。
    	if [[ "${SPEED_DEBUG_SNAPSHOT_ON_EXIT:-0}" = 1 ]]; then
    		if [[ "${SPEED_DEBUG_SNAPSHOT_DONE:-0}" = 1 ]]; then
    			if [[ "${SPEEDBACKUP_ENTRY_QUIET_TRAP:-0}" = 1 ]]; then _speed_debug_log "trap略過speed_debug快照，先前已建立"; else echoRgb "trap略過speed_debug快照，先前已建立" "3"; fi
    		else
    			if [[ "${SPEEDBACKUP_ENTRY_QUIET_TRAP:-0}" = 1 ]]; then _speed_debug_log "trap開始建立speed_debug快照"; else echoRgb "trap開始建立speed_debug快照" "3"; fi
    			_speed_debug_snapshot_pack "$_ec"
    		fi
    	fi
    	# 收尾清理。這些步驟不應阻止最後打包。
    	_speed_debug_disarm_if_run_gone
    	_trap_err="$(_speed_debug_stderr_target)"
    	_speedbackup_lock_cleanup
    	remote_cleanup
    	_speed_debug_disarm_if_run_gone
    	_cleanup_tmp_files
    	# 最終打包成功後才刪 run_xxx 目錄；失敗則保留 run_xxx。
    	if [[ "${SPEEDBACKUP_ENTRY_QUIET_TRAP:-0}" = 1 ]]; then _speed_debug_log "trap開始建立speed_debug最終包"; else echoRgb "trap開始建立speed_debug最終包" "3"; fi
    	_speed_debug_pack "$_ec"
    	_speedbackup_run_tmpdir_final_cleanup
    	# r440: timeout/鎖屏還原是 EXIT trap 最後一個實際收尾動作；完成後才印 trap 收尾完成，避免使用者在 timeout 尚未寫回前離開。
    	_speedbackup_display_restore_after_debug_pack "exit-trap-last-step" || true
    	if [[ "${SPEEDBACKUP_ENTRY_QUIET_TRAP:-0}" = 1 ]]; then _speed_debug_log "trap收尾流程完成(exit=$_ec)"; else echoRgb "trap收尾流程完成(exit=$_ec)" "3"; fi
    	return "$_ec"
    }
    trap '_speedbackup_exit_trap' EXIT
}
kill_Serve
# ======================================================
# 遠端功能函數 (upload / download / smb / webdav)
# ======================================================
# TCP port 探測：Android/toybox nc 常沒有 -z，不能只依賴 nc -z。
# 成功 return 0；失敗 return 1。用途：remote_precheck / SMB 區網掃描 fallback。
_tcp_port_open() {
	local host="$1" port="$2" timeout_s="${3:-2}" dbg="$4"
	local _nc_help _nc_has_z
	[[ -z $host || -z $port ]] && return 1
	if command -v nc >/dev/null 2>&1; then
		# 遠端未開時，timeout 包住 nc 可能讓終端直接吐出 "Terminated"。
		# 先判斷 nc 是否支援 -z：支援就只跑 -z；不支援才用空輸入 no-z。
		# 不再在 nc 已存在時疊加 bash /dev/tcp fallback，避免離線遠端多等與終端噪音。
		_nc_has_z=0
		_nc_help="$(nc -h 2>&1 || true)"
		case "$_nc_help" in *-z*) _nc_has_z=1 ;; esac
		if [[ $_nc_has_z = 1 ]]; then
			nc -z -w "$timeout_s" "$host" "$port" >/dev/null 2>&1 && {
				[[ -n $dbg ]] && _speed_debug_append_file "$dbg" "[OK] nc -z passed host=$host port=$port"
				return 0
			}
			[[ -n $dbg ]] && _speed_debug_append_file "$dbg" "[FAIL] nc -z failed host=$host port=$port"
			return 1
		fi
		nc -w "$timeout_s" "$host" "$port" </dev/null >/dev/null 2>&1 && {
			[[ -n $dbg ]] && _speed_debug_append_file "$dbg" "[OK] nc no-z passed host=$host port=$port"
			return 0
		}
		[[ -n $dbg ]] && _speed_debug_append_file "$dbg" "[FAIL] nc no-z failed host=$host port=$port"
		return 1
	fi
	# 只有沒有 nc 時才退到 bash /dev/tcp；保留兼容，但避免正常 Android 路徑觸發 timeout TERM 噪音。
	if command -v bash >/dev/null 2>&1 && command -v timeout >/dev/null 2>&1; then
		timeout "$timeout_s" bash -c ':</dev/tcp/$1/$2' _ "$host" "$port" >/dev/null 2>&1 && {
			[[ -n $dbg ]] && _speed_debug_append_file "$dbg" "[OK] bash /dev/tcp passed host=$host port=$port"
			return 0
		}
		[[ -n $dbg ]] && _speed_debug_append_file "$dbg" "[FAIL] bash /dev/tcp failed host=$host port=$port"
	fi
	return 1
}

# Dex SMB 目標 TCP 探測：只探目前已知 host:port，不掃整個網段。
_smb_dex_target_tcp_probe() {
	local host="$1" port="$2" timeout_ms="${3:-900}" retry_ms="${4:-1500}" dbg="$5" _out _rc
	[[ -n $host && -n $port ]] || return 2
	_out="$TMPDIR/.smb_target_tcp_probe_${$}_$RANDOM.jsonl"
	dex_smbscan_raw probeTarget "$host" "$port" "$timeout_ms" "$retry_ms" >"$_out" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	_rc=$?
	if [[ -s $_out ]]; then
		_speed_debug_append_file "$dbg" "[DEX] smb target tcp probe rc=$_rc host=$host port=$port timeoutMs=$timeout_ms retryMs=$retry_ms"
		cat "$_out" >> "$dbg" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	else
		_speed_debug_append_file "$dbg" "[DEX] smb target tcp probe no-output rc=$_rc host=$host port=$port"
	fi
	rm -f "$_out" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	return "$_rc"
}

_smb_target_probe_timeout_profile() {
	# 輸出四欄：tcp1_ms tcp2_ms smbclient_timeout_s label
	# r67: 備份前硬性預檢只做一段短 TCP connect；不可連線時不再疊加第二段 timeout。
	# 手動測試仍保留第二段較長 timeout，避免 NAS/Windows 首次喚醒較慢時誤判。
	case "${1:-backup_precheck}" in
	manual|test|list|download|restore)
		printf '%s	%s	%s	%s
' 900 1600 3 manual ;;
	*)
		printf '%s	%s	%s	%s
' 700 0 2 backup_fast ;;
	esac
}
_smb_target_probe_classify_error() {
	local _out="$1"
	_SMB_TARGET_PROBE_ERROR_ZH="SMB 目標連線失敗"
	_SMB_TARGET_PROBE_HINT_ZH="請檢查 SMB 位址、帳號密碼、共享名稱與伺服器狀態"
	printf '%s\n' "$_out" | grep -qiE 'NT_STATUS_LOGON_FAILURE|LOGON_FAILURE|session setup failed|Authentication failed|password' && {
		_SMB_TARGET_PROBE_ERROR_ZH="已連上 445 port，但 SMB 認證失敗"
		_SMB_TARGET_PROBE_HINT_ZH="請檢查 smb_remote_user / smb_remote_pass；若要匿名，請清空帳密並確認伺服器允許 Guest/匿名存取"
		return 0
	}
	printf '%s\n' "$_out" | grep -qiE 'NT_STATUS_BAD_NETWORK_NAME|tree connect failed|BAD_NETWORK_NAME|OBJECT_NAME_NOT_FOUND|OBJECT_PATH_NOT_FOUND|ERRbadpath|cd .*failed|does not exist' && {
		_SMB_TARGET_PROBE_ERROR_ZH="SMB 認證可嘗試，但共享名稱或路徑不存在"
		_SMB_TARGET_PROBE_HINT_ZH="請檢查 smb_url 的 share 名稱與後續路徑，例如 smb://IP/共享名稱/路徑"
		return 0
	}
	printf '%s\n' "$_out" | grep -qiE 'NT_STATUS_ACCESS_DENIED|ACCESS_DENIED|denied' && {
		_SMB_TARGET_PROBE_ERROR_ZH="SMB 共享拒絕目前帳號存取"
		_SMB_TARGET_PROBE_HINT_ZH="請檢查共享權限與 Windows/NAS 檔案系統權限；能登入不代表能讀寫該 share"
		return 0
	}
	printf '%s\n' "$_out" | grep -qiE 'Connection refused|Unable to connect|No route to host|timed out|timeout|protocol negotiation failed' && {
		_SMB_TARGET_PROBE_ERROR_ZH="SMB 伺服器不可連線或協議協商失敗"
		_SMB_TARGET_PROBE_HINT_ZH="請確認伺服器已開啟 SMB2/SMB3、445 port 未被防火牆阻擋，且手機與伺服器在可互通網段"
		return 0
	}
	return 0
}

_smb_target_precheck_path_missing_only() {
	# return 0 only when smbclient reached the share but cd into configured rem_path failed because that child path is absent.
	# Auth/share failures must stay fatal; only backup target paths may be auto-created.
	local _out="$1"
	printf '%s\n' "$_out" | grep -qiE 'NT_STATUS_OBJECT_NAME_NOT_FOUND|NT_STATUS_OBJECT_PATH_NOT_FOUND|ERRbadpath|cd .*failed|does not exist' || return 1
	printf '%s\n' "$_out" | grep -qiE 'NT_STATUS_LOGON_FAILURE|LOGON_FAILURE|session setup failed|Authentication failed|password|NT_STATUS_ACCESS_DENIED|ACCESS_DENIED|denied|NT_STATUS_BAD_NETWORK_NAME|tree connect failed|BAD_NETWORK_NAME|Connection refused|Unable to connect|No route to host|timed out|timeout|protocol negotiation failed' && return 1
	return 0
}

_smb_target_precheck_mkdir_rem_path() {
	# Create SMB_REM_PATH during backup target precheck only.
	# Returns 0 when mkdirs and a following cd/pwd verification succeed.
	local _share="$1" _auth="$2" _opts="$3" _path="$4" _dbg="$5" _script _out _rc _probe_path
	_path="${_path#/}"; _path="${_path%/}"
	[[ -n $_path ]] || return 0
	if ! _smb_safe_component "$_path"; then
		_speed_debug_append_file "$_dbg" "[SMB_TARGET_MKDIR] reject unsafe rem_path=$_path"
		_SMB_TARGET_PROBE_ERROR_ZH="SMB 遠端路徑含不安全字元"
		_SMB_TARGET_PROBE_HINT_ZH="請移除 smb_url 路徑中的分號、驚嘆號或換行字元"
		return 1
	fi
	_script="$TMPDIR/.smb_target_precheck_mkdir_${$}_$RANDOM"
	: > "$_script" || return 1
	_smb_mkdirs_script_append "$_path" "$_script"
	_probe_path="${_path//\//\\}"
	printf 'cd "%s"\n' "$_probe_path" >> "$_script"
	printf 'pwd\nexit\n' >> "$_script"
	_out="$(smbclient "$_share" $_auth $_opts < "$_script" 2>&1)"
	_rc=$?
	_speed_debug_append_file "$_dbg" \
		"[SMB_TARGET_MKDIR] rc=$_rc share=$_share rem_path=/${_path}" \
		"$_out"
	rm -f "$_script" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	if [[ $_rc = 0 ]] && ! _smb_output_has_error "$_out"; then
		_speed_debug_append_file "$_dbg" "[OK] SMB target rem_path mkdir/verify passed rem_path=/${_path}"
		return 0
	fi
	_smb_target_probe_classify_error "$_out"
	return 1
}

# 已知 SMB 目標預檢：Dex 快速 TCP 探測 + smbclient 用目前帳密/匿名驗證指定 share。
# 這不是大範圍掃描，不列整個區網；只驗證 backup_settings.conf 裡的 smb_url。
_smb_target_precheck() {
	local host="$1" port="$2" mode="${3:-backup_precheck}" dbg="$4" _profile _tcp1 _tcp2 _smb_timeout _label _dex_rc _auth _opts _out _rc
	[[ -n $host && -n $port ]] || return 1
	_SMB_TARGET_PROBE_ERROR_ZH=""
	_SMB_TARGET_PROBE_HINT_ZH=""
	_profile="$(_smb_target_probe_timeout_profile "$mode")"
	_tcp1="$(printf '%s\n' "$_profile" | awk -F '	' '{print $1}')"
	_tcp2="$(printf '%s\n' "$_profile" | awk -F '	' '{print $2}')"
	_smb_timeout="$(printf '%s\n' "$_profile" | awk -F '	' '{print $3}')"
	_label="$(printf '%s\n' "$_profile" | awk -F '	' '{print $4}')"
	_speed_debug_append_file "$dbg" "[SMB_TARGET] begin mode=$mode profile=$_label host=$host port=$port"
	if _smb_dex_target_tcp_probe "$host" "$port" "$_tcp1" "$_tcp2" "$dbg"; then
		_speed_debug_append_file "$dbg" "[OK] SMB Dex TCP target probe passed host=$host port=$port"
	else
		_dex_rc=$?
		case $_dex_rc in
		2|125|126|127)
			_speed_debug_append_file "$dbg" "[WARN] SMB Dex TCP target probe unavailable rc=$_dex_rc; fallback nc timeout=2s"
			if ! _tcp_port_open "$host" "$port" 2 "$dbg"; then
				_SMB_TARGET_PROBE_ERROR_ZH="SMB 主機或 445 port 不可連線"
				_SMB_TARGET_PROBE_HINT_ZH="腳本已先用 Dex 快速探測，Dex 不可用時才回退 nc；請開啟 SMB 伺服器、確認 IP/port、防火牆與同網段"
				return 1
			fi
			;;
		*)
			_SMB_TARGET_PROBE_ERROR_ZH="SMB 主機或 445 port 不可連線"
			_SMB_TARGET_PROBE_HINT_ZH="腳本已用 Dex 直接探測目前 smb_url 的 host:port；請開啟 SMB 伺服器、確認 IP/port、防火牆、Wi-Fi AP 隔離與伺服器是否休眠"
			return 1
			;;
		esac
	fi

	remote_parse_smb_url
	_auth="$(_smb_auth_args_current)" || {
		_SMB_TARGET_PROBE_ERROR_ZH="SMB 認證檔建立失敗"
		_SMB_TARGET_PROBE_HINT_ZH="請檢查 /data/local/tmp 是否可寫，以及 smb_remote_user/smb_remote_pass 是否含異常字元"
		_speed_debug_append_file "$dbg" "[FAIL] SMB auth args unavailable"
		return 1
	}
	_opts="-t $_smb_timeout -s $(_smb_client_conf)${REMOTE_PORT:+ -p $REMOTE_PORT} -m SMB3"
	local _probe_path _probe_cmd
	_probe_path="${SMB_REM_PATH#/}"
	_probe_path="${_probe_path%/}"
	if [[ -n $_probe_path ]]; then
		_probe_path="${_probe_path//\//\\}"
		_probe_cmd="cd \"$_probe_path\"; pwd; exit"
	else
		_probe_cmd='pwd; exit'
	fi
	_out="$(smbclient "$SMB_SHARE" $_auth $_opts -c "$_probe_cmd" 2>&1)"
	_rc=$?
	_speed_debug_append_file "$dbg" \
		"[SMB_TARGET] auth/share probe rc=$_rc share=$SMB_SHARE rem_path=${SMB_REM_PATH:-/} timeout=${_smb_timeout}s user=${remote_user:+set}${remote_user:+ }${remote_user:-anonymous}" \
		"$_out"
	if [[ $_rc != 0 ]] || printf '%s\n' "$_out" | grep -qiE 'NT_STATUS|tree connect failed|session setup failed|LOGON_FAILURE|ACCESS_DENIED|BAD_NETWORK_NAME|OBJECT_NAME_NOT_FOUND|OBJECT_PATH_NOT_FOUND|ERRbadpath|cd .*failed|does not exist|Connection refused|Unable to connect|No route to host|timed out|timeout|protocol negotiation failed'; then
		# r117: backup target precheck may auto-create a missing child path when the share itself is reachable.
		# Do not do this for restore/source/list/manual checks: a missing source must remain a real failure.
		if [[ $mode = backup_precheck && -n $_probe_path ]] && _smb_target_precheck_path_missing_only "$_out"; then
			_speed_debug_append_file "$dbg" "[SMB_TARGET] rem_path missing during backup_precheck; attempting mkdirs rem_path=${SMB_REM_PATH:-/}"
			if _smb_target_precheck_mkdir_rem_path "$SMB_SHARE" "$_auth" "$_opts" "$SMB_REM_PATH" "$dbg"; then
				_speed_debug_append_file "$dbg" "[OK] SMB target auth/share probe passed after mkdir share=$SMB_SHARE rem_path=${SMB_REM_PATH:-/}"
				return 0
			fi
		fi
		_smb_target_probe_classify_error "$_out"
		return 1
	fi
	_speed_debug_append_file "$dbg" "[OK] SMB target auth/share probe passed share=$SMB_SHARE"
	return 0
}

# 預連線測試 (避免後續操作卡住)
# 用法: remote_precheck <host> <port> [mode]
# SMB: Dex 直接探目前 smb_url 的 host:port，再用目前帳密/匿名驗證指定 share；WebDAV: 保留 TCP fallback。
remote_precheck() {
	local host="$1" port="$2" mode="${3:-backup_precheck}"
	[[ -z $host ]] && { echoRgb "remote_precheck: host為空" "0"; return 1; }
	local dbg
	dbg="$(_speed_debug_log_path remote_precheck.log)"
	_speed_debug_append_file "$dbg" \
		"===== precheck $(date '+%Y-%m-%d %H:%M:%S') =====" \
		"host=$host port=$port mode=$mode type=${remote_type:-unknown}"
	if [[ ${remote_type:-} = smb ]]; then
		_smb_target_precheck "$host" "$port" "$mode" "$dbg"
		return $?
	fi
	if _tcp_port_open "$host" "$port" 3 "$dbg"; then
		return 0
	fi
	# 詳細失敗原因已寫入 speed_debug 包內 remote_precheck.log；此函數本身不刷終端，交由呼叫端顯示摘要。
	return 1
}

_remote_precheck_print_smb_issue() {
	if [[ ${remote_type:-} = smb && -n ${_SMB_TARGET_PROBE_ERROR_ZH:-} ]]; then
		echoRgb "SMB 預檢問題：$_SMB_TARGET_PROBE_ERROR_ZH" "0"
		[[ -n ${_SMB_TARGET_PROBE_HINT_ZH:-} ]] && echoRgb "腳本處理：$_SMB_TARGET_PROBE_HINT_ZH" "3"
	fi
}

# r222: remote common UI/fatal/fixed-items facade。只抽共用提示與落地驗證；不合併 WebDAV/SMB 協議核心。
_smb_auth_unavailable_msg() {
	local _tail="${1:-操作}"
	echoRgb "SMB 認證資訊不可用，已停止${_tail}" "0"
}
_remote_type_missing_msg() {
	local _color="${1:-0}"
	echoRgb "remote_type 未設定" "$_color"
}
_webdav_print_reason() {
	local _color="${1:-0}"
	[[ -n ${_WEBDAV_ERROR_ZH:-} ]] && echoRgb "原因: $_WEBDAV_ERROR_ZH" "$_color"
}
_remote_local_tools_notice() {
	local _scope="${1:-remote}"
	# r264: 這只是本輪提示去重，不能再落地成 /data/local/tmp/.speedbackup_remote_local_tools_notice_* 殘留檔。
	case "$_scope" in
	upload)
		[[ ${_REMOTE_LOCAL_TOOLS_NOTICE_UPLOAD_SHOWN:-0} = 1 ]] && return 0
		_REMOTE_LOCAL_TOOLS_NOTICE_UPLOAD_SHOWN=1 ;;
	download)
		[[ ${_REMOTE_LOCAL_TOOLS_NOTICE_DOWNLOAD_SHOWN:-0} = 1 ]] && return 0
		_REMOTE_LOCAL_TOOLS_NOTICE_DOWNLOAD_SHOWN=1 ;;
	*)
		[[ ${_REMOTE_LOCAL_TOOLS_NOTICE_REMOTE_SHOWN:-0} = 1 ]] && return 0
		_REMOTE_LOCAL_TOOLS_NOTICE_REMOTE_SHOWN=1 ;;
	esac
	echoRgb "遠端不再上傳 tools/，下載後將使用本機 tools/ 補齊" "2"
}
_remote_download_fixed_notice() {
	echoRgb "遠端不再保存 restore_settings.conf；下載後本地生成，tools/ 使用本機補齊，入口/清單本地重建" "3"
}
_remote_download_fixed_verify() {
	local _dest="$1" _detail_file="${2:-}" _fix_fail=0
	if [[ ! -s $_dest/restore_settings.conf ]]; then
		update_Restore_settings_conf > "$_dest/restore_settings.conf" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} || _fix_fail=1
		_speed_debug_log "REMOTE_DOWNLOAD_RESTORE_CONF_LOCAL_GENERATE dest=$_dest/restore_settings.conf rc=$_fix_fail source=local-template reason=remote-conf-removed"
	fi
	_speedscan_files_nonempty "$_dest/restore_settings.conf" || _fix_fail=1
	if [[ $_fix_fail = 0 ]]; then
		_speedbackup_download_local_tools_fill "$_dest" || _fix_fail=1
	fi
	if [[ $_fix_fail = 0 ]]; then
		_speedbackup_download_sidecars_rebuild "$_dest" || _fix_fail=1
	fi
	_speedscan_files_nonempty "$_dest/restore_settings.conf" "$_dest/start.sh" || _fix_fail=1
	dir_has_files "$_dest/tools" || _fix_fail=1
	if [[ $_fix_fail = 1 ]]; then
		echoRgb "固定項目本地補齊有錯誤" "0"
		[[ -n $_detail_file && -f $_detail_file ]] && grep -E 'NT_STATUS|ERROR|failed|FAIL|denied|refused|timeout' "$_detail_file" 2>/dev/null | head -5
		_speedscan_files_nonempty "$_dest/restore_settings.conf" || echoRgb "restore_settings.conf 本地生成失敗" "0"
		dir_has_files "$_dest/tools" || echoRgb "本機 tools/ 補齊失敗" "0"
		_speedscan_files_nonempty "$_dest/start.sh" || echoRgb "start.sh 本地補齊失敗" "0"
		return 1
	fi
	echoRgb "✓ 本地生成 restore_settings.conf + 本機 tools/ + 本地入口/清單" "1"
	[[ -d $_dest/tools ]] && _speedscan_chmod_tree_or_fallback "$_dest/tools" 0755
	return 0
}
_remote_filelist_absent() {
	local _rel="$1" _kind="${2:-generic}"
	case $_kind in
	appdetails|app_details) _remote_webdav_filelist_absent "$_rel" && return 0; _remote_smb_filelist_absent "$_rel" && return 0; return 1 ;;
	webdav) _remote_webdav_filelist_absent "$_rel" ;;
	smb) _remote_smb_filelist_absent "$_rel" ;;
	*) _remote_webdav_filelist_absent "$_rel" && return 0; _remote_smb_filelist_absent "$_rel" ;;
	esac
}

# 流式恢復來源硬預檢：TCP port open 只代表該主機有服務監聽，不代表 SMB share/WebDAV 路徑可用。
# 這裡實際驗證「協議認證 + 遠端根 + Backup_zstd_X 子目錄」；任一失敗都必須在 Restore() 前中止。
_remote_stream_source_precheck() {
	local _subdir="$1" _dbg
	[[ -n $_subdir ]] || return 1
	_dbg="$(_speed_debug_log_path remote_source_precheck.log)"
	_speed_debug_append_file "$_dbg" \
		"===== source precheck $(date '+%Y-%m-%d %H:%M:%S') =====" \
		"type=$remote_type subdir=$_subdir url=$remote_url"

	case $remote_type in
	smb)
		local _auth _opts _target _cmd_path _out _rc
		_auth="$(_smb_auth_args_current)" || {
			_speed_debug_append_file "$_dbg" "[FAIL] SMB auth unavailable"
			_smb_auth_unavailable_msg "流式恢復"
			return 1
		}
		_target="$SMB_REM_PATH/$_subdir"
		_target="${_target#/}"
		_cmd_path="${_target//\//\\}"
		_opts="-t 10 -s $(_smb_client_conf)${REMOTE_PORT:+ -p $REMOTE_PORT} -m SMB3"
		_out="$(smbclient "$SMB_SHARE" $_auth $_opts -c "cd \"$_cmd_path\"; pwd; exit" 2>&1)"
		_rc=$?
		_speed_debug_append_file "$_dbg" \
			"SMB share=$SMB_SHARE target=$_target rc=$_rc" \
			"$_out"
		if [[ $_rc != 0 ]] || printf '%s\n' "$_out" | grep -qiE \
			'NT_STATUS|tree connect failed|session setup failed|LOGON_FAILURE|ACCESS_DENIED|BAD_NETWORK_NAME|OBJECT_NAME_NOT_FOUND|OBJECT_PATH_NOT_FOUND|ERRbadpath|does not exist|cd .*failed|Connection refused|protocol negotiation failed|Unable to connect'; then
			echoRgb "SMB 遠端來源不可用，已中止流式恢復" "0"
			echoRgb "共享/路徑: $SMB_SHARE/${_target}" "0"
			echoRgb "請檢查共享名稱、帳密與遠端備份目錄是否存在" "3"
			return 1
		fi
		return 0
		;;
	webdav)
		local _base _err _rc _http
		_base="${remote_url%/}"
		_err="$TMPDIR/.webdav_source_precheck_$$"
		rm -f "$_err" 2>/dev/null
		_webdav_dex statrel "$remote_user" "$remote_pass" "$_base" "$_subdir" >/dev/null 2>"$_err"
		_rc=$?
		_http="${_WEBDAV_HTTP_CODE:-0}"
		_speed_debug_append_file "$_dbg" \
			"WEBDAV_STAT base=$_base target=$_subdir rc=$_rc http=$_http"
		[[ -s $_err ]] && _speed_debug_append_cat "$_dbg" "$_err" "[WEBDAV stderr]"
		rm -f "$_err" 2>/dev/null
		case "$_http" in
		2[0-9][0-9])
			[[ $_rc = 0 ]] && return 0
			;;
		esac
		echoRgb "WebDAV 遠端來源不可用，已中止流式恢復" "0"
		echoRgb "HTTP:${_http:-0} 路徑: $_subdir" "0"
		_webdav_print_reason 3
		return 1
		;;
	esac
	return 1
}

# 寫入遠端上傳 log (帶時間戳)
# 用法: remote_log "訊息"
remote_log() {
	[[ -z $MODDIR ]] && return
	local _up_log
	_up_log="$(_speed_debug_log_path remote_upload.log)"
	_speed_debug_append_file "$_up_log" "[$(date '+%Y-%m-%d %H:%M:%S')] $*"
}

# v24.20.14-6 remote raw debug：遠端/流式詳細除錯 log。
# 注意：流式下載 stdout 是真實資料流，不能落檔也不能插入文字；这里只記 meta/stderr/rc/HTTP code。
remote_raw_log() {
	local _file="$1"; shift
	local _log
	_log="$(_speed_debug_log_path "$_file")"
	_speed_debug_append_file "$_log" "[$(date '+%Y-%m-%d %H:%M:%S')] $*"
}

remote_raw_cat() {
	local _file="$1" _src="$2" _prefix="$3"
	[[ -s $_src ]] || return 0
	local _log
	_log="$(_speed_debug_log_path "$_file")"
	_speed_debug_append_cat "$_log" "$_src" "$_prefix"
}

_remote_debug_seq() {
	local _name="$1" _f _n
	_f="$TMPDIR/.remote_debug_seq_${_name}"
	_n=0
	[[ -f $_f ]] && _n="$(cat "$_f" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null})"
	case $_n in ''|*[!0-9]*) _n=0 ;; esac
	_n=$((_n + 1))
	echo "$_n" > "$_f" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	printf '%03d' "$_n"
}

# 上傳結束時統一輸出總結並決定是否刪本地
# 參數: $1=協議名 $2=成功清單檔 $3=失敗清單檔
upload_summary() {
	local proto="$1" ok_list="$2" fail_list="$3"
	local ok_count=0 fail_count=0
	[[ -f $ok_list ]] && ok_count="$(wc -l < "$ok_list" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null})"
	[[ -f $fail_list ]] && fail_count="$(wc -l < "$fail_list" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null})"
	ok_count=${ok_count:-0}
	fail_count=${fail_count:-0}
	# 計算總耗時
	local elapsed_str=""
	if [[ -n $UPLOAD_START_TS ]]; then
		local elapsed=$(( $(date +%s) - UPLOAD_START_TS ))
		elapsed_str=" 用時${elapsed}秒"
	fi
	echoRgb "_______________________________________" "2"
	echoRgb "$proto 上傳完成: 成功 $ok_count / 失敗 $fail_count${elapsed_str}" "3"
	remote_log "$proto 上傳結束: 成功 $ok_count / 失敗 $fail_count${elapsed_str}"
	if [[ $fail_count -gt 0 ]]; then
		echoRgb "失敗清單已寫入 speed_debug 包內: remote_upload.log" "0"
		local n=0
		while read -r line && [[ $n -lt 5 ]]; do
			echoRgb "$line" "0"
			let n++
		done < "$fail_list"
		[[ $fail_count -gt 5 ]] && echoRgb "...還有 $((fail_count - 5)) 個，請看 speed_debug 包內 remote_upload.log" "0"
	fi
	# 刪本地檔案的策略: remote_keep_local=true 或 1 永遠保留
	# 否則: 必須「全部成功」才刪除所有上傳過的檔案
	case $remote_keep_local in
	1|true|True|TRUE)
		echoRgb "remote_keep_local=$remote_keep_local 本地檔案保留" "3"
		;;
	*)
		if [[ $fail_count -eq 0 && $ok_count -gt 0 ]]; then
			echoRgb "全部上傳成功,清除本地已上傳檔案與空應用資料夾 (保留 tools/ 跟入口腳本)" "1"
			while read -r f; do
				[[ -z $f ]] && continue
				# 保留: tools/ 目錄下檔案 / 備份根目錄入口檔
				case $f in
				*/tools/*) continue ;;
				esac
				_f_dir=${f%/*}
				_f_base=${f##*/}
				if [[ $_f_dir = "$Backup" ]]; then
					case $_f_base in
					start.sh|restore_settings.conf) continue ;;
					esac
				fi
				rm -f "$f"
			done < "$ok_list"
			# 刪除上傳後留下的空 log/ 與 app 目錄；保留 Backup 根目錄本身
			find "$Backup" -mindepth 1 -type d -empty -delete 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
		elif [[ $fail_count -gt 0 ]]; then
			echoRgb "部分上傳失敗,本地檔案全部保留 (含已上傳的)" "0"
			remote_log "部分失敗,本地檔案全部保留"
		fi
		;;
	esac
	rm -f "$ok_list" "$fail_list" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	unset UPLOAD_START_TS
	[[ $fail_count -eq 0 ]]
}

# 計算速度顯示字串
# 用法: speed_calc <總bytes> <用時秒數>
# 輸出: "1.23 GB/s" 或 "8.5 MB/s" 或 "512 KB/s" 或 "" (時間=0時)
speed_calc() {
	local bytes="$1" secs="$2"
	[[ -z $bytes || -z $secs ]] && return
	[[ $secs -le 0 ]] && return
	# 依速率(bytes/secs)分級, awk 一次處理 (無 32-bit 溢位, 四捨五入)
	awk -v b="$bytes" -v s="$secs" 'BEGIN{
		r=b/s
		if(r>=1073741824) printf "%.2f GB/s", r/1073741824
		else if(r>=1048576) printf "%.2f MB/s", r/1048576
		else if(r>=1024) printf "%.1f KB/s", r/1024
		else if(r>0) printf "%d B/s", r
	}'
}

# 計算清單檔案總大小 (bytes)
list_total_size() {
    local list="$1" _n
    [[ ! -f $list ]] && { echo 0; return; }
    _n="$(_speedscan_list_total_size "$list" 2>/dev/null)" && { echo "$_n"; return; }
    # r308 fallback: 一次批量 stat 後用 decimal string 加總，避免 20GB+ 在 awk/shell 整數路徑溢位。
    tr '\n' '\0' < "$list" | xargs -0 -r stat -c%s 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} | _decimal_sum_uint_stdin
}

# r170: 遠端不再保存可由本機重建的入口/名單 sidecar。
# 流式恢復直接由主流程還原；非流式下載落地後用 touch_shell 與 app_details.json 本地補齊。
_speedbackup_sidecar_upload_skip_path() {
	local _p="$1" _rel="$1"
	[[ -n ${Backup:-} ]] && case "$_p" in "$Backup"/*) _rel="${_p#$Backup/}" ;; esac
	# r419: 功能7/手動當前備份上傳時，app_details 已先彙總成根層
	# app_details_bundle.tar.zst；不再逐 App 上傳 app_details.json 舊相容檔。
	if [[ ${REMOTE_UPLOAD_CURRENT_BUNDLE_ONLY:-0} = 1 ]]; then
		case "$_rel" in */app_details.json) return 0 ;; esac
	fi
	case "$_rel" in
		start.sh|appList.txt|mediaList.txt|*/recover.sh|*/backup.sh|*/upload.sh)
			return 0 ;;
	esac
	return 1
}
_remote_filter_sidecar_upload_list() {
	local _list="$1" _tmp _kept=0 _skip=0 _f
	[[ -s $_list ]] || return 0
	_tmp="$TMPDIR/.remote_sidecar_filter_$$"
	: > "$_tmp" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} || return 0
	while IFS= read -r _f; do
		[[ -n $_f ]] || continue
		if _speedbackup_sidecar_upload_skip_path "$_f"; then
			_skip=$((_skip + 1))
			continue
		fi
		printf '%s\n' "$_f" >> "$_tmp"
		_kept=$((_kept + 1))
	done < "$_list"
	cat "$_tmp" > "$_list" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	rm -f "$_tmp" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	[[ $_skip -gt 0 ]] && _speed_debug_log "REMOTE_LOCAL_REBUILD_SIDECAR_SUMMARY skipped=$_skip kept=$_kept mode=local-rebuild-on-download"
	return 0
}


_remote_filter_sidecar_pair_list() {
	local _list="$1" _tmp _rel _file _skip=0 _kept=0
	[[ -s $_list ]] || return 0
	_tmp="$TMPDIR/.remote_sidecar_pair_filter_$$"
	: > "$_tmp" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} || return 0
	while IFS='	' read -r _rel _file; do
		[[ -n $_rel && -n $_file ]] || continue
		case "$_rel" in
			start.sh|appList.txt|mediaList.txt|*/recover.sh|*/backup.sh|*/upload.sh)
				_skip=$((_skip + 1))
				continue ;;
		esac
		printf '%s\t%s\n' "$_rel" "$_file" >> "$_tmp"
		_kept=$((_kept + 1))
	done < "$_list"
	cat "$_tmp" > "$_list" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	rm -f "$_tmp" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	[[ $_skip -gt 0 ]] && _speed_debug_log "REMOTE_LOCAL_REBUILD_SIDECAR_PAIR_SUMMARY skipped=$_skip kept=$_kept mode=local-rebuild-on-download"
	return 0
}

# 收集本次需要上傳的清單 (而非整個Backup)
# 結果寫入 $1 指定的list_file
# 範圍由以下變數控制 (在各備份入口設定,只反映「本次執行」):
#   REMOTE_APPLIST    : 字串,本次備份的 app 清單 (跟 $txt 同格式)
#   REMOTE_UPLOAD_MEDIA=1 : 本次有跑 Media 備份, 要上傳 $Backup/Media
#   REMOTE_UPLOAD_WIFI=1  : 本次有跑 wifi 備份, 要上傳 $Backup/wifi
# app 上傳條件:
#   1. 該行未被 #/＃/! 註解
#   2. $Backup/$name1 目錄存在
#   3. 目錄內至少有一個有效檔案
remote_collect_targets() {
	local list_file="$1"
	local tmp_collect="$TMPDIR/.rcollect"
	_speedscan_backup_payload_manifest "$Backup" "remote_collect" || true
	: > "$list_file"
	# 全目錄模式: 上傳整個 Backup 下所有檔案 (排除 log/), 不依清單
	if [[ $REMOTE_FULL_DIR = 1 ]]; then
		[[ $REMOTE_QUIET != 1 ]] && echoRgb "全目錄模式: 收集整個備份目錄" "2"
		_speedscan_file_list_abs "$Backup" "$list_file" 0 || find "$Backup" -type f -not -path "$Backup/log/*" >> "$list_file" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
		# speedscan file-list 不知道 log 排除規則，輸出後仍用既有 sidecar/filter 收斂。
		awk -v logp="$Backup/log/" 'index($0, logp) != 1' "$list_file" > "$tmp_collect" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} && mv "$tmp_collect" "$list_file"
		_remote_filter_sidecar_upload_list "$list_file"
		_speedscan_upload_candidate_precheck "$list_file" "remote_full_dir" || true
		rm -f "$tmp_collect" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
		return 0
	fi
	# 如果設置了 REMOTE_SKIP_APPDATA，跳過應用數據上傳
	if [[ $REMOTE_SKIP_APPDATA != 1 && -n $REMOTE_APPLIST ]]; then
		[[ $REMOTE_QUIET != 1 ]] && echoRgb "讀取本次備份名單" "2"
		echo "$REMOTE_APPLIST" | grep -Ev '^[[:space:]]*[#＃!]|^[[:space:]]*$' | while read -r line; do
			local name1="${line%% *}" pkg="${line#* }"
			pkg="${pkg%% *}"
			name1="$(_backup_path_safe_name "$name1" "$pkg")"
			[[ -z $name1 ]] && continue
			local full="$Backup/$name1"
			[[ -d $full ]] || continue
			: > "$tmp_collect"
			if [[ $REMOTE_APPDETAILS_SKIP = 1 ]]; then
				_speedscan_file_list_abs "$full" "$tmp_collect" 1 || find "$full" -type f ! -name "app_details.json" > "$tmp_collect" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
			else
				_speedscan_file_list_abs "$full" "$tmp_collect" 0 || find "$full" -type f  > "$tmp_collect" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
			fi
			[[ -s $tmp_collect ]] && cat "$tmp_collect" >> "$list_file"
		done
	fi
	if [[ $REMOTE_UPLOAD_MEDIA = 1 && -d $Backup/Media ]]; then
		: > "$tmp_collect"
		_speedscan_file_list_abs "$Backup/Media" "$tmp_collect" 0 || find "$Backup/Media" -type f  > "$tmp_collect" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
		[[ -s $tmp_collect ]] && cat "$tmp_collect" >> "$list_file"
	fi
	if [[ $REMOTE_UPLOAD_WIFI = 1 && -d $Backup/wifi ]]; then
		: > "$tmp_collect"
		_speedscan_file_list_abs "$Backup/wifi" "$tmp_collect" 0 || find "$Backup/wifi" -type f  > "$tmp_collect" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
		[[ -s $tmp_collect ]] && cat "$tmp_collect" >> "$list_file"
	fi
	# r419: 功能7上傳當前備份時，metadata 只上傳根層 bundle，不再逐 App JSON。
	if [[ ${REMOTE_UPLOAD_CURRENT_BUNDLE_ONLY:-0} = 1 && -s "$Backup/$(_appdetails_bundle_rel)" ]]; then
		printf '%s\n' "$Backup/$(_appdetails_bundle_rel)" >> "$list_file"
	fi
	# 固定附加: tools/ 資料夾、MT管理器.apk；遠端不再上傳 restore_settings.conf，下載後本地生成。
	# r170: start.sh/appList.txt/mediaList.txt/per-app backup/recover/upload wrappers 不再上傳；下載後本地重建。
	# 只要 list_file 已經有內容(代表本次有東西要上傳)就一併帶上固定必要檔。
	# REMOTE_SKIP_FIXED=1 時跳過 (逐應用上傳模式，避免重複上傳)
	# REMOTE_SKIP_APPDATA=1 時也需要上傳依賴文件
	if [[ $REMOTE_SKIP_FIXED != 1 && $REMOTE_SKIP_APPDATA = 1 ]] || [[ $REMOTE_SKIP_FIXED != 1 && -s $list_file ]]; then
		[[ -d $Backup/tools ]] && { _speedscan_file_list_abs "$Backup/tools" "$list_file" 0 || find "$Backup/tools" -type f >> "$list_file" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}; }
		[[ -f "$Backup/MT管理器.apk" ]] && echo "$Backup/MT管理器.apk" >> "$list_file"
	fi
	_remote_filter_sidecar_upload_list "$list_file"
	_speedscan_upload_candidate_precheck "$list_file" "remote_collect" || true
	rm -f "$tmp_collect" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
}
# 掃描核心: 找出區網內所有開放 445 的主機, 寫入 $TMPDIR/.smb_scan_results (一行一 IP, 已排序)
# 成功(有結果) return 0; 無結果或無法掃描 return 1. 供 scan_smb / smb_autodetect_url 複用
_smb_scan_hosts() {
	local my_ip
	my_ip="$(ip route get 1 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} | awk '{print $7; exit}')"
	[[ -z $my_ip ]] && my_ip="$(ifconfig 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} | grep -m1 'inet addr:192' | awk '{print $2}' | cut -d: -f2)"
	[[ -n $my_ip ]] && SMB_SCAN_SUBNET="${my_ip%.*}" || SMB_SCAN_SUBNET="auto"
	local _scan_label
	[[ $SMB_SCAN_SUBNET = auto ]] && _scan_label="自動偵測網段" || _scan_label="$SMB_SCAN_SUBNET.0/24"
	echoRgb "本機 IP: ${my_ip:-自動偵測}" "2"
	echoRgb "掃描 $_scan_label 上的 SMB 主機 (445 port)..." "3"
	local results="$TMPDIR/.smb_scan_results"; : > "$results"

	# 優先用 dex 併發 socket 預掃，避免 shell/nc 對 254 個 IP 反覆 fork。
	# SMB 傳輸仍交給 smbclient；這裡只找 445 open 的候選主機。
	local _dex_scan_out="$TMPDIR/.smb_scan_dex_out_$$" _dex_scan_err="$TMPDIR/.smb_scan_dex_err_$$" _dex_scan_rc=1
	if [[ -f "$tools_path/classes.dex" ]] && command -v "$DEX_APP_PROCESS_BIN" >/dev/null 2>&1; then
		dex_smbscan_raw scanSmb "$SMB_SCAN_SUBNET" 800 192 0 445,139 >"$_dex_scan_out" 2>"$_dex_scan_err"
		_dex_scan_rc=$?
		[[ -n ${SPEED_DEBUG_RUN_DIR:-} ]] && {
			{
				echo "===== SMB_SCAN_DEX rc=$_dex_scan_rc subnet=$SMB_SCAN_SUBNET ====="
				cat "$_dex_scan_out" 2>/dev/null
				cat "$_dex_scan_err" 2>/dev/null
			} >> "${SPEED_DEBUG_RUN_DIR:-/data/speed_debug}/remote_smb_scan_raw.log" 2>/dev/null
		}
		if [[ $_dex_scan_rc = 0 && -s $_dex_scan_out ]]; then
			awk -F '\t' '$3=="open" && ($2==445 || $2==139) {print $1}' "$_dex_scan_out" | sort -t. -k4 -n -u > "$results"
			rm -f "$_dex_scan_out" "$_dex_scan_err" 2>/dev/null
			if [[ -s $results ]]; then
				printf '\r -掃描 254/254 %s\n' "$(progress_bar 100)" >&2
				return 0
			fi
		fi
	fi
	rm -f "$_dex_scan_out" "$_dex_scan_err" 2>/dev/null

	# dex 不可用或未找到主機時，回退 shell TCP 掃描。
	# Android/toybox nc 常沒有 -z，因此不能硬依賴 nc -z。
	if ! command -v nc >/dev/null 2>&1 && ! command -v bash >/dev/null 2>&1; then
		echoRgb "未找到 nc/bash，無法 fallback 掃描" "0"; return 1
	fi
	if [[ $SMB_SCAN_SUBNET = auto ]]; then
		echoRgb "無法取得本機 IP" "0"; return 1
	fi
	local i pids=""
	for i in $(seq 1 254); do
		( _tcp_port_open "$SMB_SCAN_SUBNET.$i" 445 1 "" && echo "$SMB_SCAN_SUBNET.$i" >> "$results" ) &
		pids="$pids $!"
		if [[ $((i % 20)) -eq 0 ]]; then
			_event_wait_pid_list "$pids" smb_scan_batch 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}; pids=""
			printf '\r -掃描 %d/254 %s' "$i" "$(progress_bar $((i * 100 / 254)))" >&2
		fi
	done
	_event_wait_pid_list "$pids" smb_scan_final 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	printf '\r -掃描 254/254 %s\n' "$(progress_bar 100)" >&2
	[[ ! -s $results ]] && return 1
	sort -t. -k4 -n "$results" -o "$results"
	return 0
}

# 自動偵測區網 SMB 並設定 remote_url (取第一台有可用共享的主機)
# 不論 remote_stream/remote_user/remote_pass 是否填寫都會探測
smb_autodetect_url() {
	_smb_scan_hosts || return 1
	local _auth
	_auth="$(_smb_auth_args_current)" || { _smb_auth_unavailable_msg "操作"; return 1; }
	local target share
	while read -r target; do
		echoRgb "發現 SMB: $target" "1"
		share="$(smbclient -g -L "//$target" $_auth -t 5 -s $(_smb_client_conf) -m SMB3 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} \
			| _smb_parse_share_grepable)"
		if [[ -n $share ]]; then
			remote_url="smb://$target/$share"
			rm -f "$TMPDIR/.smb_scan_results"
			return 0
		fi
		echoRgb "$target 無可用共享 (或需認證)" "2"
	done < "$TMPDIR/.smb_scan_results"
	rm -f "$TMPDIR/.smb_scan_results"
	return 1
}

# 掃描區網內所有開放 SMB (445 port) 的主機 (菜單功能: 顯示所有主機與共享)
scan_smb() {
	if ! _smb_scan_hosts; then
		echoRgb "未發現 SMB 主機" "0"
		rm -f "$TMPDIR/.smb_scan_results"
		return 1
	fi
	echoRgb "------- 掃描完成 -------" "3"
	local _auth
	_auth="$(_smb_auth_args_current)" || { _smb_auth_unavailable_msg "操作"; return 1; }
	while read -r target; do
		echoRgb "發現 SMB: $target" "1"
		# 查主機名 (有 nmblookup 才查)
		if command -v nmblookup >/dev/null 2>&1; then
			local hn
			hn="$(nmblookup -A "$target" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} | awk 'NR==2{print $1}' | tr -d '<>\t ')"
			[[ -n $hn ]] && echoRgb "主機名: $hn" "2"
		fi
		# 列 share — smbclient 的 CP850/charset 噪音只進 raw log，不污染 stderr.log。
		local _scan_raw
		_scan_raw="$(_speed_debug_log_path remote_smb_scan_raw.log)"
		smbclient -g -L "//$target" $_auth -t 3 -s $(_smb_client_conf) -m SMB3 2>>"$_scan_raw" \
			| awk -F'|' '
				function trim(s){gsub(/^[[:space:]]+|[[:space:]]+$/, "", s); return s}
				$1=="Disk" {n=trim($2); if (n!="" && n !~ /\$$/) print "  共享: " n}
			' \
			| while read -r line; do echoRgb "$line" "2"; done
	done < "$TMPDIR/.smb_scan_results"
	rm -f "$TMPDIR/.smb_scan_results"
}
# SMB 上傳實作 (使用 smbclient)
# 流程: 解析 URL → 預檢 → 收集檔案 → 按目錄分組 → 每組一次 smbclient 批次傳輸
# 跟 upload_remote 的差別: SMB 用獨立的 smbclient 二進制, 不走外部 HTTP 工具
upload_smb() {
	[[ -z $remote_url ]] && { echoRgb "remote_url未設置" "0"; return 1; }
	UPLOAD_START_TS=$(date +%s)
	[[ $REMOTE_QUIET != 1 ]] && echoRgb "使用: $filepath/smbclient" "2"
	# 解析 smb://server/share/remotepath
	remote_parse_smb_url
	local share="$SMB_SHARE"
	local rem_path="$SMB_REM_PATH"
	# 自動加上備份目錄前綴 (跟本地結構一致)
	local backup_subdir="${_BACKUP_DIRNAME_CACHED:-$(get_backup_dirname)}"
	rem_path="${rem_path}/${backup_subdir}"
	# 拆出 host 和 port (從 share 反推)
	local _hp="${share#//}"; _hp="${_hp%%/*}"
	local host="${_hp%%:*}"
	local port="${_hp#*:}"
	[[ $port = $_hp ]] && port=445
	echoRgb "SMB: $share (路徑: ${rem_path:-/})" "2"
	# 連線預檢
	if ! remote_precheck "$host" "$port"; then
		echoRgb "SMB伺服器無法連線: $host:$port (請檢查WiFi/位址/伺服器狀態)" "0"
		echoRgb "本地檔案已保留" "0"
		return 1
	fi
	if _remote_netwatch_mark_remote_fatal "upload_smb_after_precheck" "$backup_subdir"; then
		echoRgb "SMB 上傳已因 LAN 路由／位址變更中止" "0"
		return 1
	fi
	local list_file="$TMPDIR/.slist"
	local ok_list="$TMPDIR/.sok"
	local fail_list="$TMPDIR/.sfail"
	: > "$ok_list"; : > "$fail_list"
	remote_collect_targets "$list_file"
	_remote_filter_tools_targets_by_signature "$list_file" "$Backup/tools"
	if [[ ! -s $list_file ]]; then
		echoRgb "無檔案需上傳" "3"
		rm -f "$list_file" "$ok_list" "$fail_list" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
		return 0
	fi
	local total
	total="$(wc -l < "$list_file")"
	[[ $REMOTE_QUIET != 1 ]] && echoRgb "準備上傳 $total 個檔案" "3"
	if [[ $REMOTE_QUIET != 1 ]]; then
		local _up_bytes
		_up_bytes="$(list_total_size "$list_file")"
		echoRgb "本次上傳總大小: $(size_with_bytes "$_up_bytes")" "3"
	fi
	remote_log "SMB 開始: $share, 共 $total 檔"
	remote_raw_log "remote_smb_upload_raw.log" "BEGIN share=$share rem_path=$rem_path total=$total backup_subdir=$backup_subdir host=$host port=$port"
	# 466/r17: SMB context 收斂，auth/opts/share 由 _smb_session_prepare 統一產生。
	if ! _smb_session_prepare 10 1; then
		_smb_auth_unavailable_msg "上傳"
		echo "SMB auth unavailable: user=${remote_user:+set} authfile=${_SMB_AUTHFILE:-empty}" >> "$fail_list"
		rm -f "$list_file" "$ok_list" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
		return 1
	fi
	local SMB_OPTS="$SMB_CMD_OPTS"
	local _smb_auth_args="$SMB_AUTH_ARGS"
	# 收集所有需要建立的目錄
	local mkdir_script="$TMPDIR/.smb_mkdir"
	: > "$mkdir_script"
	{
		while read -r f; do
			local d="${f#$Backup/}"
			d="${d%/*}"
			[[ -n $d && $d != "${f#$Backup/}" ]] && echo "${rem_path:+$rem_path/}$d"
		done < "$list_file"
	} | sort -u | while read -r d; do
		# 對每層路徑都產生 mkdir 命令
		# 注意: smbclient 內部命令不認 shell 引號, 不能加 '' 或 ""
		local cur=""
		local OLDIFS="$IFS"
		IFS='/'
		set -- $d
		IFS="$OLDIFS"
		for seg; do
			[[ -z $seg ]] && continue
			cur="$cur/$seg"
			echo "mkdir $cur" >> "$mkdir_script"
		done
	done
	# 一次連線執行所有 mkdir (比每個目錄重新連快很多)
	if [[ -s $mkdir_script ]]; then
		if _remote_netwatch_mark_remote_fatal "upload_smb_before_mkdir" "$backup_subdir"; then
			echoRgb "SMB 上傳已因 LAN 路由／位址變更中止" "0"
			rm -f "$mkdir_script" "$list_file" "$ok_list" "$fail_list" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
			return 1
		fi
		echo "exit" >> "$mkdir_script"
		local _mkdir_out _mkdir_rc
		_mkdir_out="$(_smb_cmd_common_share "$share" < "$mkdir_script" 2>&1)"
		_mkdir_rc=$?
		if [[ $_mkdir_rc != 0 ]]; then
			_remote_netwatch_mark_remote_fatal "upload_smb_mkdir_fail" "$backup_subdir" >/dev/null 2>&1 || true
		fi
		remote_raw_log "remote_smb_upload_raw.log" "MKDIR rc=$_mkdir_rc script=$mkdir_script"
		printf '%s\n' "$_mkdir_out" >> "${SPEED_DEBUG_RUN_DIR:-/data/speed_debug}/remote_smb_upload_raw.log" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
		printf '%s\n' "$_mkdir_out" | grep -Ev '^Domain=|^OS=|NT_STATUS_OBJECT_NAME_COLLISION|^Try "help"|^dos charset|^Can.t load' >&2
		if [[ $_mkdir_rc != 0 ]] || _smb_output_has_error "$_mkdir_out"; then
			echoRgb "SMB 建立遠端目錄失敗，已停止上傳" "0"
			rm -f "$mkdir_script" "$list_file" "$ok_list" "$fail_list" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
			return 1
		fi
	fi
	rm -f "$mkdir_script" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	# 按目錄分組上傳 (同一目錄的所有檔案,一次連線傳完)
	# 先依遠端目錄分組
	local group_dir="$TMPDIR/.smb_groups"
	mkdir -p "$group_dir" && rm -f "$group_dir"/*
	while read -r f; do
		[[ -z $f ]] && continue
		local rel="${f#$Backup/}"
		local file_dir="$(dirname "$rel")"
		local rem_dir="$rem_path"
		[[ $file_dir != . ]] && rem_dir="${rem_dir:+$rem_dir/}$file_dir"
		[[ -z $rem_dir ]] && rem_dir="/"
		# 用 base64 或 hash 當分組 key,避免路徑裡的 / 影響檔名
		local key="$(echo "$rem_dir|$(dirname "$f")" | md5sum 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} | cut -c1-12)"
		[[ -z $key ]] && key="$(echo "$rem_dir|$(dirname "$f")" | cksum | cut -d' ' -f1)"
		local gf="$group_dir/$key"
		[[ ! -f $gf ]] && {
			echo "$rem_dir" > "$gf.meta"
			echo "$(dirname "$f")" >> "$gf.meta"
		}
		echo "$f" >> "$gf"
	done < "$list_file"
	# 對每個分組執行批次上傳
	local idx=0
	# 算總目錄數 (用於進度計算; 不含 wifi, wifi 不參與百分比)
	local total_dirs done_dirs=0
	for gf in "$group_dir"/*; do
		[[ -f $gf && $gf != *.meta ]] || continue
		local rem_dir_check
		rem_dir_check="$(sed -n 1p "$gf.meta")"
		# wifi 目錄不算進總數
		[[ $rem_dir_check = */wifi || $rem_dir_check = wifi || $rem_dir_check = */wifi/* ]] && continue
		let total_dirs++
	done
	for gf in "$group_dir"/*; do
		[[ -f $gf && $gf != *.meta ]] || continue
		local meta="$gf.meta"
		local rem_dir local_dir
		rem_dir="$(sed -n 1p "$meta")"
		local_dir="$(sed -n 2p "$meta")"
		local file_count
		file_count="$(wc -l < "$gf")"
		# 判斷是否為 wifi (不計入進度)
		local is_wifi=0
		[[ $rem_dir = */wifi || $rem_dir = wifi || $rem_dir = */wifi/* ]] && is_wifi=1
		echoRgb "上傳目錄 $rem_dir ($file_count 檔)" "3"
		local dir_start
		dir_start=$(date +%s)
		# 建立 smbclient batch script
		local batch="$TMPDIR/.smb_batch"
		echo "cd $rem_dir" > "$batch"
		echo "lcd $local_dir" >> "$batch"
		while read -r f; do
			local fname="$(basename "$f")"
			echo "put $fname" >> "$batch"
		done < "$gf"
		echo "exit" >> "$batch"
		# 跑 batch, 解析每個 put 的結果
		if _remote_netwatch_mark_remote_fatal "upload_smb_before_batch" "$rem_dir"; then
			echoRgb "SMB 上傳已因 LAN 路由／位址變更中止" "0"
			rm -f "$batch" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
			rm -rf "$group_dir" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
			rm -f "$list_file" "$ok_list" "$fail_list" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
			return 1
		fi
		local smb_out _smb_batch_rc _raw_tag
		_raw_tag="$(_remote_debug_seq smb_upload)"
		smb_out="$(_smb_cmd_common_share "$share" < "$batch" 2>&1)"
		_smb_batch_rc=$?
		if [[ $_smb_batch_rc != 0 ]]; then
			_remote_netwatch_mark_remote_fatal "upload_smb_batch_fail" "$rem_dir" >/dev/null 2>&1 || true
		fi
		remote_raw_log "remote_smb_upload_raw.log" "BATCH tag=$_raw_tag rc=$_smb_batch_rc rem_dir=$rem_dir local_dir=$local_dir file_count=$file_count batch=$batch"
		{
			printf '===== SMB_UPLOAD_BATCH %s rem_dir=%s rc=%s =====\n' "$_raw_tag" "$rem_dir" "$_smb_batch_rc"
			printf '%s\n' "$smb_out" | _smb_output_filter_noise
		} >> "${SPEED_DEBUG_RUN_DIR:-/data/speed_debug}/remote_smb_upload_${_raw_tag}.log" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
		printf '%s\n' "$smb_out" >> "${SPEED_DEBUG_RUN_DIR:-/data/speed_debug}/remote_smb_upload_raw.log" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
		# 對應每個檔案的成功/失敗
		# 優化: smb_out 對全部檔案是同一份, 迴圈前一次抽出含錯誤標記的行,
		# 迴圈內改用參數展開 + case 零 fork 比對 (原本每檔 basename+echo+2grep ~4 fork)
		local _smb_err_lines _smb_global_fail=0
		_smb_err_lines="$(printf '%s\n' "$smb_out" | grep -E 'NT_STATUS|does not exist|ERR|Unable to|Failed to|failed|denied|Connection refused|tree connect|session setup' 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null})"
		# smbclient 的 rc/錯誤有時不含檔名；這種全域錯誤必須整組判失敗，避免假成功後刪除本地檔案。
		if [[ $_smb_batch_rc != 0 ]] || printf '%s\n' "$smb_out" | grep -qiE 'Unable to open credentials file|Failed to set parse authentication file|session setup failed|tree connect failed|NT_STATUS_LOGON_FAILURE|NT_STATUS_ACCESS_DENIED|NT_STATUS_BAD_NETWORK_NAME|Connection refused|protocol negotiation failed'; then
			_smb_global_fail=1
		fi
		while read -r f; do
			let idx++
			local rel="${f#$Backup/}"
			local fname="${f##*/}"
			if [[ $_smb_global_fail = 1 ]]; then
				echo "$rel" >> "$fail_list"
				echoRgb "[$idx/$total] ✗ $rel" "0"
				remote_log "FAIL SMB $rel batch_rc=$_smb_batch_rc"
			else
				# 用檔名比對錯誤行時必須要求邊界字元，否則像 user.tar 會被
				# user.tar.zst 的錯誤行「假陽性」命中 (純子字串比對的舊 bug)，
				# 導致明明上傳成功的檔案被誤判失敗。
				case "$_smb_err_lines" in
					"$fname" | "$fname"[!A-Za-z0-9_.-]* | *[!A-Za-z0-9_.-]"$fname" | *[!A-Za-z0-9_.-]"$fname"[!A-Za-z0-9_.-]*)
						echo "$rel" >> "$fail_list"
						echoRgb "[$idx/$total] ✗ $rel" "0"
						remote_log "FAIL SMB $rel"
						;;
					*)
						echo "$f" >> "$ok_list"
						echoRgb "[$idx/$total] ✓ $rel" "1"
						;;
				esac
			fi
		done < "$gf"
		rm -f "$batch"
		# 此目錄完成,印整體進度 (wifi 不算)
		if [[ $is_wifi = 0 && $total_dirs -gt 0 ]]; then
			let done_dirs++
			local dir_speed=""
			local dir_bytes
			dir_bytes=$(list_total_size "$gf")
			local dir_elapsed=$(( $(date +%s) - dir_start ))
			local sp
			sp=$(speed_calc "$dir_bytes" "$dir_elapsed")
			[[ -n $sp ]] && dir_speed=" ($sp)"
			echoRgb "完成$((done_dirs * 100 / total_dirs))% $(progress_bar $((done_dirs * 100 / total_dirs)))${dir_speed}" "3"
		fi
	done
	# REMOTE_APPDETAILS_FILE: 主體上傳完成後，若無失敗則上傳 app_details.json
	if [[ -n $REMOTE_APPDETAILS_FILE && -f $REMOTE_APPDETAILS_FILE ]]; then
		# 非流式遠端最後上傳 app_details 前再收斂，避免本地後續 jq_inplace/merge 遺留格式漂移。
		_app_details_normalize_restore_profile_file "$REMOTE_APPDETAILS_FILE" || _speed_debug_log "APPDETAILS_REMOTE_FINAL_PRETTY_FAIL file=$REMOTE_APPDETAILS_FILE proto=SMB"
		if [[ ! -s $fail_list ]]; then
			let idx++
			local _ad_rel="${REMOTE_APPDETAILS_FILE#$Backup/}"
			local _ad_dir="$(dirname "$REMOTE_APPDETAILS_FILE")"
			local _ad_fname="$(basename "$REMOTE_APPDETAILS_FILE")"
			local _ad_smb_out _ad_smb_rc _ad_tag
			_ad_tag="$(_remote_debug_seq smb_upload)"
			if _remote_netwatch_mark_remote_fatal "upload_smb_before_appdetails" "$_ad_rel"; then
				echoRgb "SMB app_details 上傳已因 LAN 路由／位址變更中止" "0"
				echo "$_ad_rel" >> "$fail_list"
			else
			if ! _smb_safe_component "$_ad_dir" || ! _smb_safe_component "$_ad_fname"; then
				echoRgb "偵測到不安全的路徑字元, 拒絕上傳 app_details: $_ad_rel" "0" >&2
				return 1
			fi
			_ad_smb_out="$(_smb_cmd_common_share "$share" \
				-D "${rem_path:+$rem_path/}$(dirname "$_ad_rel")" \
				-c "lcd $_ad_dir; put $_ad_fname; exit" 2>&1)"
			_ad_smb_rc=$?
			if [[ $_ad_smb_rc != 0 ]]; then
				_remote_netwatch_mark_remote_fatal "upload_smb_appdetails_fail" "$_ad_rel" >/dev/null 2>&1 || true
			fi
			remote_raw_log "remote_smb_upload_raw.log" "APP_DETAILS tag=$_ad_tag rc=$_ad_smb_rc rel=$_ad_rel dir=$_ad_dir"
			{
				echo "===== SMB_UPLOAD_APP_DETAILS $_ad_tag rel=$_ad_rel rc=$_ad_smb_rc ====="
				printf '%s\n' "$_ad_smb_out"
			} >> "${SPEED_DEBUG_RUN_DIR:-/data/speed_debug}/remote_smb_upload_${_ad_tag}.log" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
			if [[ $_ad_smb_rc != 0 ]] || echo "$_ad_smb_out" | grep -qE 'NT_STATUS|does not exist|ERR|Unable to|Failed to|failed|denied|session setup|tree connect'; then
				echo "$_ad_rel" >> "$fail_list"
				echoRgb "[$idx/$idx] ✗ $_ad_rel" "0"
				remote_log "FAIL SMB $_ad_rel"
			else
				echo "$REMOTE_APPDETAILS_FILE" >> "$ok_list"
				echoRgb "[$idx/$idx] ✓ $_ad_rel" "1"
			fi
			fi
		else
			echoRgb "其他文件上傳失敗,跳過 app_details.json" "0"
		fi
	fi
	rm -rf "$group_dir" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	rm -f "$list_file" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	upload_summary "SMB" "$ok_list" "$fail_list"
}

# 遠端上傳分派器 + WebDAV 實作
# $1=協議名 (webdav/smb), smb 會轉派給 upload_smb
# WebDAV: 用 dex WebDavUtil 逐檔 PUT，預先 MKCOL 建好目錄結構
upload_remote() {
	local proto="$1"
	[[ $proto = smb ]] && { upload_smb; return $?; }
	[[ -z $remote_url ]] && { echoRgb "remote_url未設置" "0"; return 1; }
	echoRgb "WebDAV上傳: dex WebDavUtil 原生/atomic模式" "3"
	UPLOAD_START_TS=$(date +%s)
	local base_root base_url
	case $proto in
	webdav)
		base_root="${remote_url%/}"
		base_url="$base_root"
		[[ $base_url != http://* && $base_url != https://* ]] && { echoRgb "WebDAV地址格式錯誤: $remote_url" "0"; return 1; }
		;;
	*) echoRgb "未支援的協議: $proto" "0"; return 1 ;;
	esac
	# 自動加上備份目錄前綴 (跟本地結構一致)
	local backup_subdir="${_BACKUP_DIRNAME_CACHED:-$(get_backup_dirname)}"
	base_url="$base_root/$backup_subdir"
	# 連線預檢: 從 base_url 解出 host:port
	local _hp="${base_url#*://}"
	_hp="${_hp%%/*}"
	local _host="${_hp%%:*}"
	local _port="${_hp#*:}"
	if [[ $_port = $_hp ]]; then
		[[ $base_url = https://* ]] && _port=443 || _port=80
	fi
	if ! remote_precheck "$_host" "$_port"; then
		echoRgb "$proto伺服器無法連線: $_host:$_port (請檢查WiFi/位址/伺服器狀態)" "0"
		echoRgb "本地檔案已保留" "0"
		return 1
	fi
	if _remote_netwatch_mark_remote_fatal "upload_webdav_after_precheck" "$backup_subdir"; then
		echoRgb "WebDAV 上傳已因 LAN 路由／位址變更中止" "0"
		return 1
	fi
	[[ $REMOTE_QUIET != 1 ]] && echoRgb "使用: classes.dex WebDavUtil" "2"
	local list_file="$TMPDIR/.rlist"
	local ok_list="$TMPDIR/.rok"
	local fail_list="$TMPDIR/.rfail"
	: > "$ok_list"; : > "$fail_list"
	[[ -z $Backup ]] && { echoRgb "Backup路徑為空" "0"; return 1; }
	remote_collect_targets "$list_file"
	_remote_filter_tools_targets_by_signature "$list_file" "$Backup/tools"
	if [[ ! -s $list_file ]]; then
		echoRgb "無檔案需上傳" "3"
		rm -f "$list_file" "$ok_list" "$fail_list" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
		return 0
	fi
	local total
	total="$(wc -l < "$list_file")"
	[[ $REMOTE_QUIET != 1 ]] && echoRgb "準備上傳 $total 個檔案" "3"
	if [[ $REMOTE_QUIET != 1 ]]; then
		local _up_bytes
		_up_bytes="$(list_total_size "$list_file")"
		echoRgb "本次上傳總大小: $(size_with_bytes "$_up_bytes")" "3"
	fi
	remote_log "$proto 開始: $base_url, 共 $total 檔"
	remote_raw_log "remote_webdav_upload_raw.log" "BEGIN base_url=$base_url total=$total host=$_host port=$_port backup_subdir=$backup_subdir"
	# WEB-R3/444: 非流式 WebDAV 也先確認 configured base path；若 base path 不存在可自動建立。
	if _remote_netwatch_mark_remote_fatal "upload_webdav_before_base_preflight" "$backup_subdir"; then
		echoRgb "WebDAV 上傳已因 LAN 路由／位址變更中止" "0"
		rm -f "$list_file" "$ok_list" "$fail_list" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
		return 1
	fi
	if ! _webdav_base_path_preflight_autocreate "$base_root" upload; then
		echoRgb "WebDAV 遠端基礎資料夾預檢失敗：URL 指向的遠端資料夾不可用" "0"
		_webdav_print_reason 0
		return 1
	fi
	# WEB-R3: 非流式 WebDAV 也先走 OPTIONS 能力預檢；atomic 上傳需要 MOVE。
	if ! _webdav_options_preflight "$base_root" "$backup_subdir" upload; then
		echoRgb "WebDAV 能力預檢失敗：伺服器不支援必要方法或遠端路徑不可用" "0"
		_webdav_print_reason 0
		return 1
	fi
	# WebDAV: 先建初始目錄 (Backup_zstd_X 自己)
	if _remote_netwatch_mark_remote_fatal "upload_webdav_before_root_mkdir" "$backup_subdir"; then
		echoRgb "WebDAV 上傳已因 LAN 路由／位址變更中止" "0"
		rm -f "$list_file" "$ok_list" "$fail_list" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
		return 1
	fi
	local _mkcol_http _mkcol_rc _mkcol_err="$TMPDIR/.webdav_mkcol_err_$$"
	_webdav_mkdirrel_cached "$remote_user" "$remote_pass" "$base_root" "$backup_subdir" "$_mkcol_err"
	_mkcol_rc=$?
	if [[ $_mkcol_rc != 0 ]]; then
		_remote_netwatch_mark_remote_fatal "upload_webdav_root_mkdir_fail" "$backup_subdir" >/dev/null 2>&1 || true
	fi
	_mkcol_http="$_WEBDAV_HTTP_CODE"
	remote_raw_log "remote_webdav_upload_raw.log" "MKCOL root rc=$_mkcol_rc http=$_mkcol_http url=$base_url"
	remote_raw_cat "remote_webdav_upload_raw.log" "$_mkcol_err" "[MKCOL root stderr]"
	rm -f "$_mkcol_err" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	# WebDAV: 創建遠程子目錄。340 起正式流程停用 mkdirsrel，改用 statrel + mkdirrel 逐層建立。
	while read -r f; do
		local d="${f#$Backup/}"
		d="${d%/*}"
		[[ -n $d && $d != "${f#$Backup/}" ]] && echo "$backup_subdir/$d"
	done < "$list_file" | sort -u | while read -r cur_rel; do
		if _remote_netwatch_mark_remote_fatal "upload_webdav_before_dir_mkdir" "$cur_rel"; then
			_speed_debug_log "WEBDAV_UPLOAD_MKDIR_ABORT reason=remote_netwatch_changed rel=$cur_rel"
			return 1
		fi
		local _sub_mk_err="$TMPDIR/.webdav_mkdirs_err_$$" _sub_mk_http _sub_mk_rc
		_webdav_mkdirrel_cached "$remote_user" "$remote_pass" "$base_root" "$cur_rel" "$_sub_mk_err"
		_sub_mk_rc=$?
		if [[ $_sub_mk_rc != 0 ]]; then
			_remote_netwatch_mark_remote_fatal "upload_webdav_dir_mkdir_fail" "$cur_rel" >/dev/null 2>&1 || true
		fi
		_sub_mk_http="$_WEBDAV_HTTP_CODE"
		remote_raw_log "remote_webdav_upload_raw.log" "MKDIRS dir rc=$_sub_mk_rc http=$_sub_mk_http rel=$cur_rel"
		remote_raw_cat "remote_webdav_upload_raw.log" "$_sub_mk_err" "[MKDIRS dir stderr]"
		rm -f "$_sub_mk_err" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	done
	# 預掃總目錄數 (排除 wifi, 不計入百分比)
	local total_dirs done_dirs=0 last_dir="" cur_top_dir=""
	local dir_start=0 dir_bytes_accum=0
	while read -r f; do
		local top="${f#$Backup/}"
		top="${top%%/*}"
		[[ $top = wifi ]] && continue
		echo "$top"
	done < "$list_file" | sort -u | while read -r d; do echo "$d"; done > "$TMPDIR/.dirs_count"
	total_dirs="$(wc -l < "$TMPDIR/.dirs_count" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null})"
	rm -f "$TMPDIR/.dirs_count"
	# 上傳檔案
	local idx=0
	while read -r f; do
		[[ -z $f ]] && continue
		let idx++
		local rel="${f#$Backup/}"
		local cur_top="${rel%%/*}"
		# 判斷是「目錄內檔案」還是「根目錄檔案」
		# rel 含 / → 目錄內檔案, cur_top 是目錄名
		# rel 不含 / → 根目錄檔案, cur_top 是檔案名本身
		local is_root_file=0
		[[ $rel = "$cur_top" ]] && is_root_file=1
		# 目錄切換時印上一個目錄的進度
		if [[ -n $last_dir && $cur_top != "$last_dir" ]]; then
			if [[ $last_dir != wifi && $total_dirs -gt 0 ]]; then
				let done_dirs++
				local dir_speed=""
				local dir_elapsed=$(( $(date +%s) - dir_start ))
				local sp
				sp=$(speed_calc "$dir_bytes_accum" "$dir_elapsed")
				[[ -n $sp ]] && dir_speed=" ($sp)"
				echoRgb "完成$((done_dirs * 100 / total_dirs))% $(progress_bar $((done_dirs * 100 / total_dirs)))${dir_speed}" "3"
			fi
			if [[ $is_root_file = 1 ]]; then
				echoRgb "上傳檔案 $cur_top" "3"
			else
				echoRgb "上傳目錄 $cur_top" "3"
			fi
			dir_start=$(date +%s)
			dir_bytes_accum=0
		elif [[ -z $last_dir ]]; then
			if [[ $is_root_file = 1 ]]; then
				echoRgb "上傳檔案 $cur_top" "3"
			else
				echoRgb "上傳目錄 $cur_top" "3"
			fi
			dir_start=$(date +%s)
			dir_bytes_accum=0
		fi
		last_dir="$cur_top"
		# 累計這個目錄已上傳的 bytes；r308: cosmetic per-dir counter also uses decimal addition.
		local _sz
		_sz=$(stat -c%s "$f" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null})
		case $_sz in ''|*[!0-9]*) _sz=0 ;; esac
		dir_bytes_accum="$(_decimal_add_uint "$dir_bytes_accum" "${_sz:-0}")"
		local target_url
		if [[ $proto = webdav ]]; then
			target_url="$backup_subdir/$rel"
		else
			target_url="$base_url/$rel"
		fi
		local http_code webdav_exit
		local _sz_human
		_sz_human=$(awk "BEGIN{s=${_sz:-0};if(s>=1073741824)printf\"%.2fGB\",s/1073741824;else if(s>=1048576)printf\"%.1fMB\",s/1048576;else if(s>=1024)printf\"%.0fKB\",s/1024;else printf\"%dB\",s}")
		local _webdav_progress="$TMPDIR/.webdav_progress_$$" _webdav_tag
		_webdav_tag="$(_remote_debug_seq webdav_upload)"
		echoRgb "\r[$idx/$total] $rel ($_sz_human) 上傳中..." "3" > /dev/tty
		if _remote_netwatch_mark_remote_fatal "upload_webdav_before_put" "$rel"; then
			echoRgb "WebDAV 上傳已因 LAN 路由／位址變更中止" "0"
			echo "$rel" >> "$fail_list"
			break
		fi
		_webdav_putrel_atomic_file "$base_root" "$target_url" "$f" "$_webdav_tag" "$_webdav_progress"
		webdav_exit=$?
		if [[ $webdav_exit != 0 ]]; then
			_remote_netwatch_mark_remote_fatal "upload_webdav_put_fail" "$rel" >/dev/null 2>&1 || true
		fi
		http_code="$_WEBDAV_HTTP_CODE"
		remote_raw_log "remote_webdav_upload_raw.log" "PUT_ATOMIC tag=$_webdav_tag rc=$webdav_exit http=$http_code bytes=${_sz:-0} rel=$rel url=$target_url"
		remote_raw_cat "remote_webdav_upload_${_webdav_tag}.log" "$_webdav_progress" "===== WEBDAV_PUT $_webdav_tag rel=$rel rc=$webdav_exit http=$http_code ====="
		cat "$_webdav_progress" >> "${SPEED_DEBUG_RUN_DIR:-/data/speed_debug}/remote_webdav_upload_raw.log" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
		rm -f "$_webdav_progress" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
		printf "\r\033[K" > /dev/tty
		# http_code 2xx 視為成功
		case $http_code in
		2*)
			echo "$f" >> "$ok_list"
			echoRgb "[$idx/$total] ✓ $rel" "1"
			;;
		*)
			echo "$rel  (HTTP $http_code)" >> "$fail_list"
			echoRgb "[$idx/$total] ✗ $rel (HTTP $http_code)" "0"
			_webdav_print_reason 0
			remote_log "FAIL $proto $rel HTTP=$http_code webdav_exit=$webdav_exit"
			;;
		esac
	done < "$list_file"
	# 最後一個目錄(非wifi)的進度
	if [[ -n $last_dir && $last_dir != wifi && $total_dirs -gt 0 ]]; then
		let done_dirs++
		local dir_speed=""
		local dir_elapsed=$(( $(date +%s) - dir_start ))
		local sp
		sp=$(speed_calc "$dir_bytes_accum" "$dir_elapsed")
		[[ -n $sp ]] && dir_speed=" ($sp)"
		echoRgb "完成$((done_dirs * 100 / total_dirs))% $(progress_bar $((done_dirs * 100 / total_dirs)))${dir_speed}" "3"
	fi
	# REMOTE_APPDETAILS_FILE: 主體上傳完成後，若無失敗則上傳 app_details.json
	if [[ -n $REMOTE_APPDETAILS_FILE && -f $REMOTE_APPDETAILS_FILE ]]; then
		# 非流式遠端最後上傳 app_details 前再收斂，避免本地後續 jq_inplace/merge 遺留格式漂移。
		_app_details_normalize_restore_profile_file "$REMOTE_APPDETAILS_FILE" || _speed_debug_log "APPDETAILS_REMOTE_FINAL_PRETTY_FAIL file=$REMOTE_APPDETAILS_FILE proto=WebDAV"
		if [[ ! -s $fail_list ]]; then
			let idx++
			local _ad_rel="${REMOTE_APPDETAILS_FILE#$Backup/}"
			local _ad_url="$backup_subdir/$_ad_rel"
			local _ad_http _ad_webdav_rc _ad_webdav_err="$TMPDIR/.webdav_ad_err_$$" _ad_tag
			_ad_tag="$(_remote_debug_seq webdav_upload)"
			if _remote_netwatch_mark_remote_fatal "upload_webdav_before_appdetails" "$_ad_rel"; then
				echoRgb "WebDAV app_details 上傳已因 LAN 路由／位址變更中止" "0"
				echo "$_ad_rel" >> "$fail_list"
			else
			_webdav_putrel_atomic_file "$base_root" "$_ad_url" "$REMOTE_APPDETAILS_FILE" "$_ad_tag" "$_ad_webdav_err"
			_ad_webdav_rc=$?
			if [[ $_ad_webdav_rc != 0 ]]; then
				_remote_netwatch_mark_remote_fatal "upload_webdav_appdetails_fail" "$_ad_rel" >/dev/null 2>&1 || true
			fi
			_ad_http="$_WEBDAV_HTTP_CODE"
			remote_raw_log "remote_webdav_upload_raw.log" "APP_DETAILS_ATOMIC tag=$_ad_tag rc=$_ad_webdav_rc http=$_ad_http rel=$_ad_rel url=$_ad_url"
			remote_raw_cat "remote_webdav_upload_${_ad_tag}.log" "$_ad_webdav_err" "===== WEBDAV_APP_DETAILS $_ad_tag rel=$_ad_rel rc=$_ad_webdav_rc http=$_ad_http ====="
			rm -f "$_ad_webdav_err" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
			case $_ad_http in
			2*)
				echo "$REMOTE_APPDETAILS_FILE" >> "$ok_list"
				echoRgb "[$idx/$idx] ✓ $_ad_rel" "1"
				;;
			*)
				echo "$_ad_rel  (HTTP $_ad_http)" >> "$fail_list"
				echoRgb "[$idx/$idx] ✗ $_ad_rel (HTTP $_ad_http)" "0"
				remote_log "FAIL $proto $_ad_rel HTTP=$_ad_http"
				;;
			esac
			fi
		else
			echoRgb "其他文件上傳失敗,跳過 app_details.json" "0"
		fi
	fi
	rm -f "$list_file" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	upload_summary "$proto" "$ok_list" "$fail_list"
}

# 從 remote_url 解析出 host 和 port (依 remote_type)
# 結果寫到全域變數 REMOTE_HOST 和 REMOTE_PORT
remote_parse_endpoint() {
	REMOTE_HOST=""; REMOTE_PORT=""
	case $remote_type in
	smb)
		local u="${remote_url#smb://}"; u="${u%%/*}"
		REMOTE_HOST="${u%%:*}"; REMOTE_PORT="${u#*:}"; [[ $REMOTE_PORT = $u ]] && REMOTE_PORT=445
		;;
	webdav)
		local u="${remote_url#*://}"; u="${u%%/*}"
		REMOTE_HOST="${u%%:*}"; REMOTE_PORT="${u#*:}"
		if [[ $REMOTE_PORT = $u ]]; then [[ $remote_url = https://* ]] && REMOTE_PORT=443 || REMOTE_PORT=80; fi
		;;
	esac
}
# r356: WebDAV 遠端清單分類優先交給 Dex WebDavUtil。
# 輸出格式: kind<TAB>rel<TAB>size<TAB>mtime<TAB>name；tools 只消費 FILE 類 rel，不再在深度清單熱路徑解析 href/XML。
_webdav_classify_listrel() {
	local _rel="$1" _depth="${2:--1}" _out="$3" _err="$4" _base
	[[ ${remote_type:-} = webdav ]] || return 1
	[[ -n $_rel && -n $_out ]] || return 1
	_base="${remote_url%/}"
	[[ -n $_err ]] || _err="$TMPDIR/.wdav_classify_err_$$"
	_webdav_status_sidecar_reset
	_webdav_dex classifylistrel "$remote_user" "$remote_pass" "$_base" "$_rel" "$_depth" > "$_out" 2>"$_err"
	local _rc=$?
	_webdav_status_sidecar_load || true
	remote_raw_log "remote_webdav_propfind_raw.log" "CLASSIFY_LIST path=$_rel rc=$_rc http=${_WEBDAV_HTTP_CODE:-0} base=$_base depth=$_depth mode=r370"
	remote_raw_cat "remote_webdav_propfind_raw.log" "$_err" "[WEBDAV_CLASSIFY_LIST stderr path=$_rel]"
	[[ -s $_out ]] && remote_raw_cat "remote_webdav_propfind_raw.log" "$_out" "[WEBDAV_CLASSIFY_LIST stdout path=$_rel]"
	return "$_rc"
}

_webdav_classified_files_to_rel_list() {
	local _in="$1" _out="$2"
	[[ -n $_out ]] || return 1
	: > "$_out" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} || return 1
	# r366: classifylistrel rc=0 + HTTP 207 但 stdout 為空時代表空遠端目錄，不是清單失敗。
	# 不能因為輸入檔 0 byte 讓 prepare_remote_filelist 誤印 REMOTE_WEBDAV_CLASSIFY_LIST_FAIL。
	[[ -s $_in ]] || return 0
	awk -F'	' '$1 != "DIR" && $2 != "" {print $2}' "$_in" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} > "$_out" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	# r357: classifylistrel 已是 WebDAV 深度清單硬閘門；空目錄/缺檔時輸出空清單也視為成功，不能回退舊 listrel。
	return 0
}
# 計算遠端某路徑 (相對遠端根) 下所有檔案總大小 (bytes), 對齊本地 calc_dir_size 的純檔案字節統計
# 用法: remote_dir_size "Backup_zstd_0/iQIYI"  或  "Backup_zstd_0"
# 依 remote_type 分發 smbclient(recurse ls) / dex WebDavUtil(PROPFIND)
# 一次列出遠端 $1 (相對 share/url 的子目錄) 下所有檔案的相對路徑 (相對 $1), 一行一個
# SMB 用 recurse ls 單連線; WebDAV 用 PROPFIND Depth:infinity 解析 href
remote_list_files() {
	local _path="$1"
	if _remote_netwatch_mark_remote_fatal "remote_list_files_enter" "$_path"; then
		_speed_debug_log "REMOTE_LIST_FILES_SKIP reason=remote_netwatch_changed path=$_path"
		return 1
	fi
	case $remote_type in
	smb)
		# v24.20.14-7.66-6: 非流式 SMB 也必須先解析 share/path。
		# 先前只有流式在 remote_setup() 解析，導致 remote_list_files/remote_dir_size
		# 於非流式備份前快照/增量預掃時 SMB_SHARE 為空，smbclient 只印 Usage，
		# 進而讓增量列表為空並誤判需要全量上傳。
		remote_parse_smb_url
		local _auth
		_auth="$(_smb_auth_args_current)" || { _smb_auth_unavailable_msg "操作"; return 1; }
		local SMB_OPTS="-t 300 -s $(_smb_client_conf)${REMOTE_PORT:+ -p $REMOTE_PORT} -m SMB3"
		local _pref="$SMB_REM_PATH/$_path"; _pref="${_pref#/}"
		local _p="$_pref"; _p="${_p//\//\\}"
		# recurse ls: stderr 只進 raw log；CP850/橫幅噪音不寫入 stderr.log。
		local _smb_ls_out="$TMPDIR/.smb_ls_out_$$" _smb_ls_err="$TMPDIR/.smb_ls_err_$$" _smb_ls_rc
		smbclient -g "$SMB_SHARE" $_auth $SMB_OPTS \
			-c "recurse ON; prompt OFF; cd \"$_p\"; ls" >"$_smb_ls_out" 2>"$_smb_ls_err"
		_smb_ls_rc=$?
		if [[ $_smb_ls_rc != 0 ]]; then
			_remote_netwatch_mark_remote_fatal "remote_list_files_smb_fail" "$_path" >/dev/null 2>&1 || true
		fi
		remote_raw_cat "remote_smb_list_raw.log" "$_smb_ls_err" "[SMB_LIST stderr path=$_path]"
		# stderr 已完整寫入 remote_smb_list_raw.log；列表/大小探測屬於非致命診斷，不污染 stderr.log。
		# v24.20.14-7.10：cd 目標不存在時，smbclient 會停在 share 根目錄；若繼續解析 ls，會誤把根目錄內容當成目標目錄。
		# 這會讓冷流式備份的「備份前遠端大小」變成接近舊資料大小，造成「本次備份增加 1KB」之類錯誤顯示。
		if grep -qiE 'NT_STATUS_OBJECT_NAME_NOT_FOUND|NT_STATUS_OBJECT_PATH_NOT_FOUND|ERRbadpath|does not exist|cd .*failed|cd .*NT_STATUS' "$_smb_ls_out" "$_smb_ls_err" 2>/dev/null; then
			_speed_debug_log "REMOTE_SMB_LIST_MISSING path=$_path pref=$_pref"
			rm -f "$_smb_ls_out" "$_smb_ls_err" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
			return 0
		fi
		remote_raw_cat "remote_smb_list_raw.log" "$_smb_ls_out" "[SMB_LIST stdout-g path=$_path]"
		_smb_parse_ls_entries "$_pref" < "$_smb_ls_out" | awk -F'\t' 'index($1,"D")==0 {print $3}' 
		rm -f "$_smb_ls_out" "$_smb_ls_err" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
		;;
	webdav)
		local _wd_out="$TMPDIR/.wdav_propfind_list_out_$$" _wd_err="$TMPDIR/.wdav_propfind_list_err_$$" _wd_files="$TMPDIR/.wdav_classified_files_$$" _wd_rc _wd_http
		rm -f "$TMPDIR/.remote_webdav_last_list_ok" "$_wd_out" "$_wd_err" "$_wd_files" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
		# r357: tools 與 Dex 已配套，不再相容舊 Dex 的 listrel 深度解析 fallback。
		# WebDAV 深度清單唯一入口為 classifylistrel；tools 只消費 Dex classified facts 的 rel 欄位。
		_webdav_classify_listrel "$_path" -1 "$_wd_out" "$_wd_err"
		_wd_rc=$?
		_wd_http="${_WEBDAV_HTTP_CODE:-0}"
		if [[ $_wd_rc = 0 ]] && _webdav_classified_files_to_rel_list "$_wd_out" "$_wd_files"; then
			: > "$TMPDIR/.remote_webdav_last_list_ok"
			local _wd_rows
			_wd_rows="$(grep -vc '^$' "$_wd_files" 2>/dev/null)"
			case $_wd_rows in ''|*[!0-9]*) _wd_rows=0 ;; esac
			_speed_debug_log "REMOTE_WEBDAV_CLASSIFY_LIST_OK path=$_path rows=$_wd_rows rc=$_wd_rc http=$_wd_http mode=r370"
			cat "$_wd_files" 2>/dev/null
			rm -f "$_wd_out" "$_wd_err" "$_wd_files" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
			return 0
		fi
		if [[ $_wd_rc != 0 ]]; then
			_remote_netwatch_mark_remote_fatal "remote_list_files_webdav_classify_fail" "$_path" >/dev/null 2>&1 || true
		fi
		case $_wd_http in
		404|410)
			_speed_debug_log "REMOTE_WEBDAV_CLASSIFY_LIST_MISSING path=$_path http=$_wd_http mode=r370 action=empty-list"
			rm -f "$_wd_out" "$_wd_err" "$_wd_files" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
			return 0
			;;
		esac
		_speed_debug_log "REMOTE_WEBDAV_CLASSIFY_LIST_FAIL path=$_path rc=$_wd_rc http=$_wd_http mode=r370 action=fail-no-listrel-fallback"
		rm -f "$_wd_out" "$_wd_err" "$_wd_files" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
		return 1
		;;
	esac
}
remote_dir_size() {
    local _path="$1"
    if _remote_netwatch_mark_remote_fatal "remote_dir_size_enter" "$_path"; then
        _speed_debug_log "REMOTE_DIR_SIZE_SKIP reason=remote_netwatch_changed path=$_path"
        echo 0
        return 1
    fi
    case $remote_type in
    smb)
        # v24.20.14-7.66-6: 非流式 SMB 也必須先解析 share/path。
        # r308: recurse ls 只負責輸出 map，總和交給 decimal string helper，避免 SMB 35GB+ 顯示被 awk 大數路徑污染。
        remote_parse_smb_url
        local _auth
        _auth="$(_smb_auth_args_current)" || { _smb_auth_unavailable_msg "操作"; return 1; }
        local SMB_OPTS="-t 300 -s $(_smb_client_conf)${REMOTE_PORT:+ -p $REMOTE_PORT} -m SMB3"
        local _pref="$SMB_REM_PATH/$_path"; _pref="${_pref#/}"
        local _p="$_pref"; _p="${_p//\//\\}"
        local _smb_size_out="$TMPDIR/.smb_size_out_$$" _smb_size_err="$TMPDIR/.smb_size_err_$$" _smb_size_rc
        smbclient -g "$SMB_SHARE" $_auth $SMB_OPTS \
            -c "recurse ON; prompt OFF; cd \"$_p\"; ls" >"$_smb_size_out" 2>"$_smb_size_err"
        _smb_size_rc=$?
        if [[ $_smb_size_rc != 0 ]]; then
            _remote_netwatch_mark_remote_fatal "remote_dir_size_smb_fail" "$_path" >/dev/null 2>&1 || true
        fi
        remote_raw_cat "remote_smb_list_raw.log" "$_smb_size_err" "[SMB_SIZE stderr path=$_path]"
        if grep -qiE 'NT_STATUS_OBJECT_NAME_NOT_FOUND|NT_STATUS_OBJECT_PATH_NOT_FOUND|ERRbadpath|does not exist|cd .*failed|cd .*NT_STATUS' "$_smb_size_out" "$_smb_size_err" 2>/dev/null; then
            _speed_debug_log "REMOTE_SMB_SIZE_MISSING path=$_path pref=$_pref before=0"
            echo 0
            rm -f "$_smb_size_out" "$_smb_size_err" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
            return 0
        fi
        remote_raw_cat "remote_smb_list_raw.log" "$_smb_size_out" "[SMB_SIZE stdout-g path=$_path]"
        local _smb_size_map="$TMPDIR/.smb_size_map_$$" _smb_sum
        _smb_parse_ls_entries "$_pref" < "$_smb_size_out" | awk -F'\t' 'index($1,"D")==0 && $2 ~ /^[0-9]+$/ {print $3 "\t" $2}' > "$_smb_size_map" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
        if _remote_size_map_capture_enabled "$_path"; then
            cp -f "$_smb_size_map" "$(_remote_size_map_before_file)" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
            _speed_debug_log "REMOTE_SIZE_MAP_BEFORE_CAPTURE protocol=smb path=$_path rows=$(grep -vc '^$' "$(_remote_size_map_before_file)" 2>/dev/null) mode=r309-bigint-deep"
        fi
        _smb_sum="$(_remote_size_map_sum_file "$_smb_size_map" 2>/dev/null)"
        case $_smb_sum in ''|*[!0-9]*) _smb_sum=0 ;; esac
        _speed_debug_log "REMOTE_DIR_SIZE_SUM protocol=smb path=$_path rows=$(grep -vc '^$' "$_smb_size_map" 2>/dev/null) bytes=$_smb_sum mode=r309-bigint-deep"
        echo "$_smb_sum"
        rm -f "$_smb_size_out" "$_smb_size_err" "$_smb_size_map" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
        ;;
    webdav)
        local _wd_out="$TMPDIR/.wdav_propfind_size_out_$$" _wd_err="$TMPDIR/.wdav_propfind_size_err_$$" _wd_rc _wd_sum
        local _wurl="${remote_url%/}"
        rm -f "$_wd_out" "$_wd_err" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
        _webdav_status_sidecar_reset
        _webdav_dex listrel "$remote_user" "$remote_pass" "$_wurl" "$_path" -1 >"$_wd_out" 2>"$_wd_err"
        _wd_rc=$?
        if [[ $_wd_rc != 0 ]]; then
            _remote_netwatch_mark_remote_fatal "remote_dir_size_webdav_fail" "$_path" >/dev/null 2>&1 || true
        fi
        _webdav_status_sidecar_load || true
        remote_raw_log "remote_webdav_propfind_raw.log" "SIZE path=$_path rc=$_wd_rc base=$_wurl"
        remote_raw_cat "remote_webdav_propfind_raw.log" "$_wd_err" "[WEBDAV_SIZE stderr path=$_path]"
        [[ -s $_wd_out ]] && remote_raw_cat "remote_webdav_propfind_raw.log" "$_wd_out" "[WEBDAV_SIZE stdout path=$_path]"
        rm -f "$_wd_err" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
        if [[ $_wd_rc != 0 ]]; then
            _speed_debug_log "REMOTE_WEBDAV_SIZE_MISSING_OR_FAIL path=$_path rc=$_wd_rc before=0"
            echo 0
            rm -f "$_wd_out" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
            return 0
        fi
        # r308: listrel 只解析成 rel<TAB>size map；深度統計與 before map 均走 decimal string sum。
        local _wd_size_map="$TMPDIR/.wdav_size_map_$$"
        awk -v base="$_path" -F'\t' '
            function clean_rel(h,    rel,idx,b) {
                b=base; gsub(/\r/,"",b); gsub(/^\/+/,"",b); gsub(/\/+$/, "", b)
                rel=h; gsub(/\r/,"",rel); sub(/^https?:\/\/[^\/]*\/?/,"",rel); gsub(/^\/+/,"",rel)
                if (b != "") {
                    if (rel == b) return ""
                    if (index(rel,b"/")==1) rel=substr(rel,length(b)+2)
                    else { idx=index(rel,"/" b "/"); if (idx>0) rel=substr(rel,idx+length(b)+2) }
                }
                return rel
            }
            {
                if (($1=="D" || $1=="DIR")) next
                if (($1=="F" || $1=="FILE") && NF>=3) { sz=$2; h=$3 } else if (NF>=2) { h=$1; sz=$2 } else next
                if (sz !~ /^[0-9]+$/) next
                rel=clean_rel(h)
                if (rel=="" || rel ~ /\/$/) next
                print rel "\t" sz
            }' "$_wd_out" > "$_wd_size_map" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
        if _remote_size_map_capture_enabled "$_path"; then
            cp -f "$_wd_size_map" "$(_remote_size_map_before_file)" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
            _speed_debug_log "REMOTE_SIZE_MAP_BEFORE_CAPTURE protocol=webdav path=$_path rows=$(grep -vc '^$' "$(_remote_size_map_before_file)" 2>/dev/null) mode=r309-bigint-deep"
        fi
        _wd_sum="$(_remote_size_map_sum_file "$_wd_size_map" 2>/dev/null)"
        case $_wd_sum in ''|*[!0-9]*) _wd_sum=0 ;; esac
        _speed_debug_log "REMOTE_DIR_SIZE_SUM protocol=webdav path=$_path rows=$(grep -vc '^$' "$_wd_size_map" 2>/dev/null) bytes=$_wd_sum mode=r309-bigint-deep"
        rm -f "$_wd_out" "$_wd_size_map" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
        echo "${_wd_sum:-0}"
        ;;
    *)
        echo 0
        ;;
    esac
}

# 流式模式: 上傳遠端必要附加檔；restore_settings.conf 不再上傳，下載/本地恢復時生成
# 294: SMB 真流式流程中的「已落地小檔」批量上傳。
# 大型 tar/zstd 仍走 _stream_upload 的 stdin 真流式；r170 起 start.sh/appList/per-app wrappers 不再上傳，下載後本地 touch_shell 重建；這裡只處理 MT 這類遠端附加檔，
# 目標是把多個小檔從「每檔一次 smbclient」收斂為「每個目錄一個 smbclient batch」。
_stream_upload_smb_local_files_batch() {
	local _list="$1" _label="${2:-local_files}" _subdir _auth SMB_OPTS _base _mkdir_script _groups _line _rel _file
	[[ $remote_type = smb && -s $_list ]] || return 1
	if _remote_netwatch_mark_stream_fatal "smb_local_batch_enter" "$_label"; then
		remote_raw_log "stream_upload.log" "SMB_LOCAL_BATCH_SKIP label=$_label reason=remote_netwatch_changed"
		return 1
	fi
	if _remote_stream_fatal_active; then
		remote_raw_log "stream_upload.log" "SMB_LOCAL_BATCH_SKIP label=$_label reason=remote_stream_fatal $(_remote_stream_fatal_summary)"
		return 1
	fi
	_smb_session_prepare 300 1 || { _smb_auth_unavailable_msg "批量上傳"; return 1; }
	_auth="$SMB_AUTH_ARGS"
	SMB_OPTS="$SMB_CMD_OPTS"
	_subdir="${_BACKUP_DIRNAME_CACHED:-$(get_backup_dirname)}"
	_base="$SMB_SESSION_BASE"
	_mkdir_script="$TMPDIR/.smb_stream_batch_mkdir_$$"
	_groups="$TMPDIR/.smb_stream_batch_groups_$$"
	rm -rf "$_groups" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	mkdir -p "$_groups" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} || return 1
	: > "$_mkdir_script"
	while IFS='	' read -r _rel _file; do
		[[ -n $_rel && -f $_file ]] || continue
		case $_rel in /*|*../*|../*) _speed_debug_log "SMB_STREAM_BATCH_SKIP_UNSAFE rel=$_rel"; continue ;; esac
		if printf '%s\n' "$_rel" | grep -q '[;"$]' 2>/dev/null; then _speed_debug_log "SMB_STREAM_BATCH_SKIP_UNSAFE rel=$_rel"; continue; fi
		local _remote="${_base:+$_base/}$_rel" _rdir _cur="" _seg _OLDIFS
		_rdir="${_remote%/*}"
		[[ $_rdir = $_remote ]] && _rdir=""
		_OLDIFS="$IFS"; IFS='/'; set -- $_rdir; IFS="$_OLDIFS"
		for _seg; do
			[[ -z $_seg ]] && continue
			if [[ -z $_cur ]]; then _cur="$_seg"; else _cur="$_cur\\$_seg"; fi
			printf 'mkdir "%s"\n' "$_cur" >> "$_mkdir_script"
		done
		local _ldir="${_file%/*}" _fname="${_file##*/}" _rfname="${_rel##*/}" _rdir_bslash="${_rdir//\//\\}"
		[[ -z $_rdir_bslash ]] && _rdir_bslash="\\"
		local _key
		_key="$(printf '%s' "$_rdir_bslash|$_ldir" | md5sum 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} | awk '{print $1}' | cut -c1-12)"
		[[ -z $_key ]] && _key="$(printf '%s' "$_rdir_bslash|$_ldir" | cksum 2>/dev/null | awk '{print $1}')"
		[[ -n $_key ]] || _key="group"
		if [[ ! -f $_groups/$_key.meta ]]; then
			printf '%s\n%s\n' "$_rdir_bslash" "$_ldir" > "$_groups/$_key.meta"
		fi
		printf '%s\t%s\t%s\n' "$_fname" "$_rfname" "$_rel" >> "$_groups/$_key"
	done < "$_list"
	if [[ -s $_mkdir_script ]]; then
		printf 'exit\n' >> "$_mkdir_script"
		local _mk_out _mk_rc
		if _remote_netwatch_mark_stream_fatal "smb_local_batch_before_mkdir" "$_label"; then
			_speed_debug_log "SMB_LOCAL_BATCH_MKDIR_SKIP label=$_label reason=remote_netwatch_changed"
			rm -rf "$_groups" "$_mkdir_script" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
			return 1
		fi
		_mk_out="$(_smb_cmd_common < "$_mkdir_script" 2>&1)"
		_mk_rc=$?
		remote_raw_log "stream_upload.log" "SMB_LOCAL_BATCH_MKDIR label=$_label rc=$_mk_rc list=$_list"
		printf '%s\n' "$_mk_out" | _smb_output_filter_noise >> "${SPEED_DEBUG_RUN_DIR:-/data/speed_debug}/stream_upload_detail.log" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
		if [[ $_mk_rc != 0 ]] || _smb_output_has_error "$_mk_out"; then
			_remote_netwatch_mark_stream_fatal "smb_local_batch_mkdir_fail" "$_label" >/dev/null 2>&1 || true
			_speed_debug_log "SMB_LOCAL_BATCH_MKDIR_FAIL label=$_label rc=$_mk_rc"
			rm -rf "$_groups" "$_mkdir_script" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
			return 1
		fi
	fi
	local _gf _ok=0 _fail=0 _total=0
	for _gf in "$_groups"/*; do
		[[ -f $_gf && $_gf != *.meta ]] || continue
		local _meta="$_gf.meta" _rdir _ldir _batch _out _rc _tag
		_rdir="$(sed -n 1p "$_meta" 2>/dev/null)"
		_ldir="$(sed -n 2p "$_meta" 2>/dev/null)"
		_batch="$TMPDIR/.smb_stream_batch_$$"
		{
			printf 'cd "%s"\n' "$_rdir"
			printf 'lcd "%s"\n' "$_ldir"
			while IFS='	' read -r _fname _rfname _rel; do
				[[ -n $_fname && -n $_rfname ]] || continue
				printf 'put "%s" "%s"\n' "$_fname" "$_rfname"
			done < "$_gf"
			printf 'exit\n'
		} > "$_batch"
		_tag="$(_remote_debug_seq stream_smb_batch)"
		if _remote_netwatch_mark_stream_fatal "smb_local_batch_before_put" "$_label"; then
			local _skip_count
			_skip_count="$(wc -l < "$_gf" 2>/dev/null | tr -d ' ')"
			case $_skip_count in ''|*[!0-9]*) _skip_count=0 ;; esac
			remote_raw_log "stream_upload.log" "SMB_LOCAL_BATCH_SKIP tag=$_tag label=$_label reason=remote_netwatch_changed dir=$_rdir count=$_skip_count"
			rm -f "$_batch" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
			_fail=$((_fail + _skip_count))
			_total=$((_total + _skip_count))
			continue
		fi
		_out="$(_smb_cmd_common < "$_batch" 2>&1)"
		_rc=$?
		local _count
		_count="$(wc -l < "$_gf" 2>/dev/null | tr -d ' ')"
		case $_count in ''|*[!0-9]*) _count=0 ;; esac
		_total=$((_total + _count))
		remote_raw_log "stream_upload.log" "SMB_LOCAL_BATCH tag=$_tag label=$_label rc=$_rc dir=$_rdir local=$_ldir count=$_count"
		{
			printf '===== STREAM_UPLOAD_SMB_LOCAL_BATCH %s label=%s rc=%s dir=%s count=%s =====\n' "$_tag" "$_label" "$_rc" "$_rdir" "$_count"
			printf '%s\n' "$_out" | _smb_output_filter_noise
		} >> "${SPEED_DEBUG_RUN_DIR:-/data/speed_debug}/stream_upload_detail.log" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
		if [[ $_rc != 0 ]] || _smb_output_has_error "$_out"; then
			_remote_netwatch_mark_stream_fatal "smb_local_batch_put_fail" "$_label" >/dev/null 2>&1 || true
			_fail=$((_fail + _count))
		else
			_ok=$((_ok + _count))
		fi
		rm -f "$_batch" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	done
	rm -rf "$_groups" "$_mkdir_script" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	_speed_debug_log "SMB_LOCAL_BATCH_SUMMARY label=$_label total=$_total ok=$_ok fail=$_fail"
	[[ $_total -gt 0 && $_fail -eq 0 ]]
}


_remote_stream_fatal_file() {
	printf '%s\n' "$TMPDIR/.remote_stream_fatal"
}

_remote_stream_fatal_active() {
	[[ -s "$(_remote_stream_fatal_file)" ]]
}

_remote_stream_event_fifo_path() {
	local _tag="${1:-remote_stream_child}" _safe
	_safe="$(printf '%s' "$_tag" | tr -c 'A-Za-z0-9_' '_' 2>/dev/null)"
	printf '%s\n' "${TMPDIR:-/data/local/tmp}/.remote_stream_event_${_safe}_${$}_${RANDOM}.fifo"
}

_remote_stream_event_prepare() {
	local _tag="${1:-remote_stream_child}" _fifo
	command -v mkfifo >/dev/null 2>&1 || return 1
	_fifo="$(_remote_stream_event_fifo_path "$_tag")"
	rm -f "$_fifo" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	mkfifo "$_fifo" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} || { rm -f "$_fifo" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}; return 1; }
	printf '%s\n' "$_fifo"
}

_remote_stream_event_emit() {
	local _type="${1:-done}" _rc="${2:-0}" _tag="${3:-remote_stream_child}" _reason="${4:-}" _fifo="${SPEEDBACKUP_REMOTE_STREAM_EVENT_FIFO:-}"
	[[ -n $_fifo && -p $_fifo ]] || return 0
	printf '%s\t%s\t%s\t%s\n' "$_type" "$_rc" "$_tag" "$_reason" > "$_fifo" 2>/dev/null || true
	return 0
}

_remote_stream_fatal_reset() {
	local _why="${1:-manual}" _f
	_f="$(_remote_stream_fatal_file)"
	if [[ -e $_f || -e $TMPDIR/.remote_stream_fatal_notice ]]; then
		rm -f "$_f" "$TMPDIR/.remote_stream_fatal_notice" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
		_speed_debug_log "REMOTE_STREAM_FATAL_RESET reason=$_why"
	fi
}

_remote_stream_mark_fatal() {
	local _rel="${1:-unknown}" _rc="${2:-1}" _http="${3:-0}" _reason="${4:-}" _f
	_f="$(_remote_stream_fatal_file)"
	[[ -s $_f ]] && return 0
	{
		printf 'rel=%s\n' "$_rel"
		printf 'rc=%s\n' "$_rc"
		printf 'http=%s\n' "$_http"
		printf 'reason=%s\n' "$_reason"
		printf 'time=%s\n' "$(date '+%Y-%m-%d %H:%M:%S' 2>/dev/null)"
	} > "$_f" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	_speed_debug_log "REMOTE_STREAM_FATAL rel=$_rel rc=$_rc http=$_http reason=$_reason"
	_remote_stream_event_emit "fatal" "$_rc" "${SPEEDBACKUP_REMOTE_STREAM_EVENT_TAG:-remote_stream_child}" "$_reason" || true
	case "${remote_type:-}" in
	webdav) _webdav_daemon_stop >/dev/null 2>&1 || true ;;
	smb) _remote_smbclient_stop_active stream_fatal >/dev/null 2>&1 || true ;;
	esac
}

_remote_stream_fatal_summary() {
	local _f
	_f="$(_remote_stream_fatal_file)"
	[[ -s $_f ]] || return 1
	tr '\n' ' ' < "$_f" 2>/dev/null
	return 0
}

_remote_stream_fatal_exit_rc() {
	# 遠端流式 fast-fail 統一用 126 對外表示「遠端中斷／連線狀態變更」，避免內部 tar/zstd/relay rc=1/2/141 被誤當普通流程成功。
	_remote_stream_fatal_active || { printf '0\n'; return 1; }
	printf '126\n'
	return 0
}

_remote_netwatch_changed_active() {
	[[ -n ${REMOTE_NETWATCH_FLAG:-} && -s ${REMOTE_NETWATCH_FLAG:-} ]]
}

_remote_connectivity_fast_fail_notice() {
	local _msg="$1" _color="${2:-0}"
	[[ -n $_msg ]] || return 0
	# 遠端 fast-fail 可能發生在 stream pipeline subshell；先直寫 /dev/tty，避免提示被資料管線吞掉。
	if [[ -w /dev/tty ]]; then
		echoRgb "$_msg" "$_color" > /dev/tty 2>/dev/null || echoRgb "$_msg" "$_color"
	else
		echoRgb "$_msg" "$_color"
	fi
}

_remote_connectivity_fast_fail() {
	local _where="${1:-remote_operation}" _rel="${2:-unknown}" _reason="${3:-remote_transport}" _summary
	[[ -n ${remote_type:-} ]] || return 1
	_summary="遠端連線／LAN 路由／伺服器狀態已變更，為避免備份或恢復資料不完整，已立即中止本輪流程；請確認 Wi-Fi、IP 位址與遠端伺服器後重新執行。"
	_remote_connectivity_fast_fail_notice "$_summary" "0"
	_speed_debug_log "REMOTE_CONNECTIVITY_FAST_FAIL where=$_where rel=$_rel reason=$_reason type=${remote_type:-} mode=r370 policy=fast-fail-no-retry"
	return 1
}

_remote_extract_log_transport_failure() {
	local _log="$1"
	[[ -s $_log ]] || return 1
	grep -E 'unexpected end of file|This does not look like a tar archive|Unexpected EOF|short read|truncated|Connection reset|Broken pipe|No route to host|Connection refused|timed out|I/O error|Input/output error' "$_log" >/dev/null 2>&1
}

_remote_netwatch_mark_remote_fatal() {
	local _where="${1:-remote_operation}" _rel="${2:-netwatch}"
	[[ -n ${remote_type:-} ]] || return 1
	_remote_netwatch_changed_active || return 1
	_speed_debug_log "REMOTE_NETWATCH_CHANGE_DETECTED where=$_where rel=$_rel type=$remote_type mode=r370 policy=fast-fail"
	_remote_netwatch_report
	_remote_connectivity_fast_fail "$_where" "$_rel" "LAN route/address changed during remote operation" || true
	if _remote_stream_fatal_active; then
		local _already_key _already_file
		_already_key="$(printf '%s_%s_%s' "$_where" "$_rel" "${remote_type:-}" | tr '/: \|' '_____')"
		_already_file="$TMPDIR/.remote_netwatch_remote_fatal_already_${_already_key}"
		if [[ ! -e $_already_file ]]; then
			: > "$_already_file" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
			_speed_debug_log "REMOTE_NETWATCH_REMOTE_FATAL_ALREADY where=$_where rel=$_rel type=$remote_type mode=r370"
		fi
		return 0
	fi
	_speed_debug_log "REMOTE_NETWATCH_REMOTE_FATAL where=$_where rel=$_rel type=$remote_type mode=r370 policy=fast-fail"
	_remote_stream_mark_fatal "$_rel" 126 0 "LAN route/address changed during remote operation; fast-fail without retry"
	return 0
}

_remote_netwatch_mark_stream_fatal() {
	local _where="${1:-remote_operation}" _rel="${2:-netwatch}"
	[[ ${remote_stream:-0} = 1 && -n ${remote_type:-} ]] || return 1
	if _remote_netwatch_mark_remote_fatal "$_where" "$_rel"; then
		_speed_debug_log "REMOTE_NETWATCH_STREAM_FATAL where=$_where rel=$_rel"
		return 0
	fi
	return 1
}

_wait_pid_timeout_basic() {
	local _pid="$1" _timeout="${2:-30}" _tag="${3:-child}" _i=0 _rc _ew_rc _timeout_ms
	case $_pid in ''|*[!0-9]*) return 125 ;; esac
	case $_timeout in ''|*[!0-9]*) _timeout=30 ;; esac
	_timeout_ms=$((_timeout * 1000))
	if _eventwait_pid_exit_ms "$_pid" "$_timeout_ms" "${_tag}_basic" >/dev/null 2>&1; then
		wait "$_pid" 2>/dev/null
		_rc=$?
		_speed_debug_log "WAIT_PID_DONE_BASIC tag=$_tag pid=$_pid rc=$_rc waitMode=eventwait timeout=$_timeout mode=r459"
		return $_rc
	else
		_ew_rc=$?
		if [[ $_ew_rc = 124 ]]; then
			_event_terminate_pid "$_pid" "${_tag}_timeout_basic" >/dev/null 2>&1 || true
			wait "$_pid" 2>/dev/null
			_speed_debug_log "WAIT_PID_TIMEOUT_BASIC tag=$_tag pid=$_pid timeout=$_timeout waitMode=eventwait mode=r459"
			return 124
		fi
	fi
	while kill -0 "$_pid" 2>/dev/null; do
		if [[ $_i -ge $_timeout ]]; then
			_event_terminate_pid "$_pid" "${_tag}_timeout_basic_fallback" >/dev/null 2>&1 || true
			wait "$_pid" 2>/dev/null
			_speed_debug_log "WAIT_PID_TIMEOUT_BASIC tag=$_tag pid=$_pid timeout=$_timeout waitMode=shell-fallback mode=r459"
			return 124
		fi
		sleep 1
		_i=$((_i + 1))
	done
	wait "$_pid" 2>/dev/null
	_rc=$?
	_speed_debug_log "WAIT_PID_DONE_BASIC tag=$_tag pid=$_pid rc=$_rc elapsed=${_i}s waitMode=shell-fallback mode=r459"
	return $_rc
}

_wait_child_timeout_remote() {
	local _pid="$1" _timeout="${2:-30}" _tag="${3:-remote_child}" _rc
	_wait_child_timeout_procwait "$_pid" "$_timeout" "$_tag"
	_rc=$?
	[[ $_rc != 125 ]] && return $_rc
	_wait_pid_timeout_basic "$_pid" "$_timeout" "$_tag"
	return $?
}

_remote_filter_tools_targets_by_signature() {
	# r202: 非流式上傳清單若包含 Backup/tools/*，一律移除；下載落地後使用本機 tools/ 補齊。
	local _list_file="$1" _src_tools_dir="$2" _prefix _tmp _removed
	[[ -s $_list_file ]] || return 0
	_prefix="$Backup/tools/"
	_removed="$(awk -v p="$_prefix" 'index($0,p)==1 {n++} END{print n+0}' "$_list_file" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null})"
	case $_removed in ''|*[!0-9]*) _removed=0 ;; esac
	[[ $_removed -gt 0 ]] || return 0
	_tmp="${_list_file}.notools.$$"
	if awk -v p="$_prefix" 'index($0,p)!=1 {print}' "$_list_file" > "$_tmp" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}; then
		cat "$_tmp" > "$_list_file"
	fi
	rm -f "$_tmp" 2>/dev/null
	_remote_local_tools_notice "upload"
	_speed_debug_log "REMOTE_LOCAL_TOOLS_ON_DOWNLOAD_SUMMARY removed=$_removed src=$_src_tools_dir"
	return 0
}

_stream_upload_webdav_local_files_batch() {
	local _list="$1" _label="${2:-local_files}" _subdir _base _manifest _out _failed_manifest _rc _ok _fail _total _line _rel _file
	[[ $remote_type = webdav && -s $_list ]] || return 1
	_subdir="${_BACKUP_DIRNAME_CACHED:-$(get_backup_dirname)}"
	_base="${remote_url%/}"
	_manifest="$TMPDIR/.webdav_local_batch_manifest_$$"
	_out="$TMPDIR/.webdav_local_batch_out_$$"
	_failed_manifest="$TMPDIR/.webdav_local_batch_failed_${_label}_$$"
	rm -f "$_failed_manifest" 2>/dev/null
	: > "$_manifest" || return 1
	while IFS='	' read -r _rel _file; do
		[[ -n $_rel && -f $_file ]] || continue
		case $_rel in /*|*../*|../*) _speed_debug_log "WEBDAV_LOCAL_BATCH_SKIP_UNSAFE rel=$_rel"; continue ;; esac
		printf '%s	%s
' "$_rel" "$_file" >> "$_manifest"
	done < "$_list"
	[[ -s $_manifest ]] || { rm -f "$_manifest" "$_out" 2>/dev/null; return 1; }
	_webdav_daemon_ensure || { rm -f "$_manifest" "$_out" 2>/dev/null; return 1; }
	local _batch_pid _batch_timeout
	case $_label in
	wifi) _batch_timeout=20 ;;
	infra) _batch_timeout=90 ;;
	*) _batch_timeout=60 ;;
	esac
	(
		_webdav_putbatchrel "$_base" "$_subdir" "$_manifest" "$_out"
	) &
	_batch_pid=$!
	_wait_child_timeout_remote "$_batch_pid" "$_batch_timeout" "webdav_local_batch_${_label}"
	_rc=$?
	if [[ $_rc = 124 ]]; then
		remote_raw_log "stream_upload.log" "WEBDAV_LOCAL_BATCH_TIMEOUT label=$_label timeout=$_batch_timeout base=$_base subdir=$_subdir"
		_remote_stream_mark_fatal "local_batch/$_label" 124 0 "WebDAV local batch timeout ${_batch_timeout}s"
		_webdav_daemon_stop >/dev/null 2>&1 || true
	fi
	_total="$(awk 'BEGIN{n=0} $1!="SUMMARY"{n++} END{print n+0}' "$_out" 2>/dev/null)"
	_ok="$(awk -F'	' '$4=="OK"{n++} END{print n+0}' "$_out" 2>/dev/null)"
	_fail="$(awk -F'	' '$4!="OK" && $1!="SUMMARY"{n++} END{print n+0}' "$_out" 2>/dev/null)"
	remote_raw_log "stream_upload.log" "WEBDAV_LOCAL_BATCH_SUMMARY label=$_label rc=$_rc http=${_WEBDAV_HTTP_CODE:-0} total=${_total:-0} ok=${_ok:-0} fail=${_fail:-0} base=$_base subdir=$_subdir"
	remote_raw_cat "stream_upload_detail.log" "$_out" "===== STREAM_UPLOAD_WEBDAV_LOCAL_BATCH label=$_label rc=$_rc http=${_WEBDAV_HTTP_CODE:-0} ====="
	if [[ $_rc = 0 && ${_fail:-1} = 0 && ${_ok:-0} -gt 0 && -s $_out ]]; then
		awk -F'	' '$4=="OK"{print $1}' "$_out" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} | while read -r _line; do
			[[ -n $_line ]] && _remote_files_note_present "$_line"
		done
	else
		# 320: batch partial 時只把失敗項留給呼叫端 fallback；避免 tools/ 成功 20 個又被逐檔重傳一次，造成收尾一卡一卡與速度下降。
		if [[ -s $_out && -s $_manifest ]]; then
			awk -F'	' '$1!="SUMMARY" && $4!="OK"{print $1}' "$_out" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} | while read -r _line; do
				[[ -n $_line ]] || continue
				awk -F'	' -v r="$_line" '$1==r{print; exit}' "$_manifest" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} >> "$_failed_manifest"
			done
		fi
		_speed_debug_log "WEBDAV_LOCAL_BATCH_PARTIAL_NO_REMOTE_FILELIST_NOTE label=$_label rc=$_rc ok=${_ok:-0} fail=${_fail:-0} failed_manifest=$_failed_manifest"
	fi
	rm -f "$_manifest" "$_out" 2>/dev/null
	[[ $_rc = 0 && ${_fail:-1} = 0 && ${_ok:-0} -gt 0 ]]
}

_stream_upload_infra_smb_batch() {
	stream_enabled || return 1
	[[ $remote_type = smb ]] || return 1
	local _stage="$TMPDIR/.stream_stage/.infra" _list="$TMPDIR/.stream_infra_smb_files_$$"
	mkdir -p "$_stage" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} || return 1
	: > "$_list"
	# r202: tools/ 不再上傳遠端；下載後以本機 tools/ 補齊。
	_speed_debug_log "STREAM_RESTORE_CONF_UPLOAD_OMIT protocol=smb reason=local-generate-on-download"
	[[ -f $Backup/MT管理器.apk ]] && printf '%s\t%s\n' "MT管理器.apk" "$Backup/MT管理器.apk" >> "$_list"
	_remote_local_tools_notice "upload"
	_speed_debug_log "STREAM_INFRA_TOOLS_OMIT protocol=smb reason=local-tools-on-download"
	if [[ ! -s $_list ]]; then
		_speed_debug_log "SMB_STREAM_INFRA_SKIP reason=no-remote-infra-files restore_conf=omitted"
		rm -rf "$_stage" "$_list" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
		return 0
	fi
	_remote_filter_sidecar_pair_list "$_list"
	if _stream_upload_smb_local_files_batch "$_list" infra; then
		echoRgb "SMB 基礎恢復檔案已批量上傳" "1"
		rm -rf "$_stage" "$_list" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
		return 0
	fi
	_speed_debug_log "SMB_STREAM_INFRA_BATCH_FAIL fallback=per_file"
	rm -f "$_list" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	return 1
}

_stream_upload_webdav_infra_file_direct() {
	local _rel="$1" _file="$2" _subdir _base _full_rel _wdir _mk_err _mk_rc _mk_http
	local _put_err _put_rc _put_http _stat_err _stat_rc _stat_http
	[[ ${remote_type:-} = webdav && -n $_rel && -f $_file ]] || return 1
	case $_rel in /*|*../*|../*) _speed_debug_log "WEBDAV_INFRA_DIRECT_SKIP_UNSAFE rel=$_rel"; return 1 ;; esac
	_subdir="${_BACKUP_DIRNAME_CACHED:-$(get_backup_dirname)}"
	_base="${remote_url%/}"
	_full_rel="$_subdir/$_rel"

	_wdir="${_full_rel%/*}"
	if [[ $_wdir != $_full_rel ]]; then
		_mk_err="$TMPDIR/.webdav_infra_mkdir_$$_$RANDOM"
		_webdav_mkdirrel_cached "$remote_user" "$remote_pass" "$_base" "$_wdir" "$_mk_err"
		_mk_rc=$?
		_mk_http="${_WEBDAV_HTTP_CODE:-0}"
		remote_raw_log "stream_upload.log" "WEBDAV_INFRA_DIRECT_MKDIR rel=$_wdir rc=$_mk_rc http=$_mk_http"
		remote_raw_cat "stream_upload_detail.log" "$_mk_err" "===== WEBDAV_INFRA_DIRECT_MKDIR rel=$_wdir rc=$_mk_rc http=$_mk_http ====="
		rm -f "$_mk_err" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
		if [[ $_mk_rc != 0 ]]; then
			_speed_debug_log "WEBDAV_INFRA_DIRECT_MKDIR_FAIL rel=$_wdir rc=$_mk_rc http=$_mk_http reason=${_WEBDAV_ERROR_ZH:-}"
			return 1
		fi
	fi

	_put_err="$TMPDIR/.webdav_infra_put_$$_$RANDOM"
	_webdav_dex putrel "$remote_user" "$remote_pass" "$_base" "$_full_rel" "$_file" > "$_put_err" 2>&1
	_put_rc=$?
	_put_http="${_WEBDAV_HTTP_CODE:-0}"
	remote_raw_log "stream_upload.log" "WEBDAV_INFRA_DIRECT_PUT rel=$_full_rel rc=$_put_rc http=$_put_http file=$_file"
	remote_raw_cat "stream_upload_detail.log" "$_put_err" "===== WEBDAV_INFRA_DIRECT_PUT rel=$_full_rel rc=$_put_rc http=$_put_http ====="
	if [[ $_put_rc != 0 ]]; then
		_speed_debug_log "WEBDAV_INFRA_DIRECT_PUT_FAIL rel=$_full_rel rc=$_put_rc http=$_put_http reason=${_WEBDAV_ERROR_ZH:-}"
		rm -f "$_put_err" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
		return 1
	fi
	rm -f "$_put_err" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}

	_stat_err="$TMPDIR/.webdav_infra_stat_$$_$RANDOM"
	_webdav_dex statrel "$remote_user" "$remote_pass" "$_base" "$_full_rel" >/dev/null 2>"$_stat_err"
	_stat_rc=$?
	_stat_http="${_WEBDAV_HTTP_CODE:-0}"
	remote_raw_log "stream_upload.log" "WEBDAV_INFRA_DIRECT_STAT rel=$_full_rel rc=$_stat_rc http=$_stat_http"
	remote_raw_cat "stream_upload_detail.log" "$_stat_err" "===== WEBDAV_INFRA_DIRECT_STAT rel=$_full_rel rc=$_stat_rc http=$_stat_http ====="
	rm -f "$_stat_err" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	if [[ $_stat_rc = 0 ]]; then
		_remote_files_note_present "$_rel"
		return 0
	fi
	return 1
}

# 遠端收尾附加檔上傳：restore_settings.conf/tools/start/appList 不再上傳；下載後本地補齊/生成。
# 僅保留 MT管理器.apk 等真正需要遠端保存的附加檔。
stream_upload_infra() {
	stream_enabled || { _speed_debug_log "STREAM_INFRA_SKIP reason=remote_disabled"; return 0; }
	if [[ $remote_type = smb ]]; then
		_stream_upload_infra_smb_batch && return 0
	fi
	if [[ $remote_type = webdav ]]; then
		local _stage_b="$TMPDIR/.stream_stage/.infra" _list_b="$TMPDIR/.stream_infra_webdav_files_$$" _tf_b _rel_b
		mkdir -p "$_stage_b" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
		: > "$_list_b" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
		# r202: tools/ 不再上傳遠端；下載後以本機 tools/ 補齊。
		_speed_debug_log "STREAM_RESTORE_CONF_UPLOAD_OMIT protocol=webdav reason=local-generate-on-download"
		[[ -f $Backup/MT管理器.apk ]] && printf '%s\t%s\n' "MT管理器.apk" "$Backup/MT管理器.apk" >> "$_list_b"
		_remote_local_tools_notice "upload"
		_speed_debug_log "STREAM_INFRA_TOOLS_OMIT protocol=webdav reason=local-tools-on-download"
		# WebDAV infra 仍以 direct putrel 覆寫 MT，避免 atomic MOVE 噪音。
		_speed_debug_log "WEBDAV_STREAM_INFRA_BATCH_SKIP reason=avoid_large_putbatchrel_broken_pipe fallback=direct_putrel"
		_remote_filter_sidecar_pair_list "$_list_b"
		local _infra_total_b=0 _infra_ok_b=0 _infra_fail_b=0
		while IFS=$'\t' read -r _rel_b _tf_b; do
			[[ -n $_rel_b && -f $_tf_b ]] || continue
			_infra_total_b=$((_infra_total_b + 1))
			if _stream_upload_webdav_infra_file_direct "$_rel_b" "$_tf_b"; then
				_infra_ok_b=$((_infra_ok_b + 1))
				case $_rel_b in MT管理器.apk) echoRgb "$_rel_b 已上傳遠端" "1" ;; esac
			else
				_infra_fail_b=$((_infra_fail_b + 1))
				case $_rel_b in MT管理器.apk) echoRgb "$_rel_b 上傳失敗" "0" ;; esac
			fi
		done < "$_list_b"
		_speed_debug_log "WEBDAV_STREAM_INFRA_DIRECT_SUMMARY total=$_infra_total_b ok=$_infra_ok_b fail=$_infra_fail_b tools_total=0 tools_fail=0 mode=r460"
		rm -rf "$_stage_b" "$_list_b" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
		[[ $_infra_fail_b -eq 0 ]]
		return $?
	fi
	local _stage="$TMPDIR/.stream_stage/.infra"
	mkdir -p "$_stage" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	_speed_debug_log "STREAM_RESTORE_CONF_UPLOAD_OMIT protocol=generic reason=local-generate-on-download"
	if [[ -f $Backup/MT管理器.apk ]]; then
		_stream_upload "MT管理器.apk" < "$Backup/MT管理器.apk" && echoRgb "MT管理器.apk 已上傳遠端" "1" || echoRgb "MT管理器.apk 上傳失敗" "0"
	fi
	_remote_local_tools_notice "upload"
	_speed_debug_log "STREAM_INFRA_TOOLS_OMIT protocol=generic reason=local-tools-on-download"
	rm -rf "$_stage" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
}

_stream_upload_rel_is_metadata() {
	case "$1" in
	*/app_details.json|app_details_bundle.tar|app_details_bundle.tar.zst|*/recover.sh|*/backup.sh|*/upload.sh|start.sh|appList.txt|mediaList.txt|wifi/*) return 0 ;;
	*) return 1 ;;
	esac
}

_appdetails_bundle_rel() {
	# r367: canonical filename matches the actual payload: tar | zstd.
	printf '%s\n' "app_details_bundle.tar.zst"
}

_appdetails_bundle_legacy_rel() {
	# r367 compatibility: r358-r366 wrote zstd-compressed bytes to app_details_bundle.tar.
	printf '%s\n' "app_details_bundle.tar"
}

_appdetails_bundle_name_is_bundle() {
	case "$1" in
	app_details_bundle.tar.zst|app_details_bundle.tar) return 0 ;;
	*) return 1 ;;
	esac
}

_appdetails_bundle_stage_root() {
	printf '%s\n' "${TMPDIR:-/data/local/tmp}/.stream_appdetails_bundle"
}

_appdetails_bundle_remote_json_path() {
	local _name="$1"
	[[ -n $_name ]] || return 1
	if [[ ${remote_stream:-0} = 1 && -n ${remote_type:-} ]]; then
		printf '%s/%s/app_details.json\n' "$(_appdetails_bundle_stage_root)" "$_name"
	else
		printf '%s/.remote_json/%s.json\n' "${TMPDIR:-/data/local/tmp}" "$_name"
	fi
}

_appdetails_bundle_remote_json_missing_file() {
	printf '%s\n' "${TMPDIR:-/data/local/tmp}/.appdetails_bundle_remote_missing"
}

_appdetails_bundle_remote_json_ready() {
	if [[ ${remote_stream:-0} = 1 && -n ${remote_type:-} ]]; then
		local _root _first
		_root="$(_appdetails_bundle_stage_root)"
		[[ -d $_root ]] || return 1
		[[ -f "$(_appdetails_bundle_remote_json_missing_file)" ]] && return 1
		local _idx_list
		_idx_list="${TMPDIR:-/data/local/tmp}/.appdetails_ready_${$}_$RANDOM.lst"
		_appdetails_index_paths "$_root" "$_idx_list" 2 2 0 >/dev/null 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} || true
		_first="$(sed -n '1p' "$_idx_list" 2>/dev/null)"
		rm -f "$_idx_list" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
		[[ -n $_first ]]
		return $?
	fi
	[[ -f "${TMPDIR:-/data/local/tmp}/.remote_json/.done" ]]
}

_appdetails_bundle_dirty_file() {
	printf '%s\n' "${TMPDIR:-/data/local/tmp}/.appdetails_bundle_dirty"
}

_appdetails_bundle_preupload_ok_file() {
	printf '%s\n' "${TMPDIR:-/data/local/tmp}/.appdetails_bundle_preupload_json_ok"
}

_appdetails_bundle_mark_dirty() {
	printf '%s	%s	%s
' "${1:-}" "${2:-}" "${3:-}" >> "$(_appdetails_bundle_dirty_file)" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} || true
}

_appdetails_bundle_is_dirty() {
	[[ -s "$(_appdetails_bundle_dirty_file)" ]]
}

_appdetails_bundle_stage_one() {
	local _name="$1" _pkg="$2" _file="$3" _root _dst _target _sz
	[[ ${remote_stream:-0} = 1 && -n ${remote_type:-} ]] || return 0
	[[ -n $_name && -s $_file ]] || return 1
	_root="$(_appdetails_bundle_stage_root)"
	_dst="$_root/$_name"
	_target="$_dst/app_details.json"
	mkdir -p "$_dst" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} || return 1
	if [[ $_file = "$_target" ]]; then
		_sz="$(stat -c%s "$_target" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null})"
		_speed_debug_log "APPDETAILS_BUNDLE_STAGE_REUSE app=$_name package=$_pkg size=${_sz:-0} mode=single-stage-r286 action=same-file dirty=0"
		return 0
	fi
	if [[ -s $_target ]] && cmp -s "$_file" "$_target" 2>/dev/null; then
		_sz="$(stat -c%s "$_target" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null})"
		_speed_debug_log "APPDETAILS_BUNDLE_STAGE_REUSE app=$_name package=$_pkg size=${_sz:-0} mode=single-stage-r286 action=content-same dirty=0"
		return 0
	fi
	cp -f "$_file" "$_target" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} || return 1
	_sz="$(stat -c%s "$_target" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null})"
	_appdetails_bundle_mark_dirty "$_name" "$_pkg" "${_sz:-0}"
	_speed_debug_log "APPDETAILS_BUNDLE_STAGE app=$_name package=$_pkg size=${_sz:-0} mode=single-stage-r286 dirty=1"
	return 0
}
_appdetails_bundle_build_manifest() {
	# r283: manifest build and pre-upload JSON validation are one pass.
	# Previous flow parsed each JSON once to read PackageName, then parsed again for JSON health.
	# This keeps the same safety gate but cuts jq calls and progress/notify overhead.
	local _root="$1" _manifest _jf _app _pkg _sz _sha _count=0 _total=0 _bad=0 _idx=0 _meta _okflag
	[[ -d $_root ]] || return 1
	rm -f "$(_appdetails_bundle_preupload_ok_file)" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	_manifest="$_root/manifest.tsv"
	: > "$_manifest" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} || return 1
	for _jf in "$_root"/*/app_details.json; do
		[[ -s $_jf ]] || continue
		_total=$((_total + 1))
	done
	if [[ $_total -gt 0 ]]; then
		echoRgb "—————— app_details bundle JSON 預檢 ——————" "3"
		_speedbackup_progress_step 0 "$_total" "正在建立並預檢 app_details bundle" "appdetails_bundle_preupload_json" "107"
	fi
	for _jf in "$_root"/*/app_details.json; do
		[[ -s $_jf ]] || continue
		_idx=$((_idx + 1))
		_app="${_jf%/app_details.json}"; _app="${_app##*/}"
		_speedbackup_progress_step "$_idx" "$_total" "建立/檢查 bundle JSON $_app" "appdetails_bundle_preupload_json" "107"
		_meta="$(jq -r "$(_appdetails_jq_common_defs) [ad_first_pkg, (ad_required_meta_ok|tostring)] | @tsv" "$_jf" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null})"
		if [[ $? -ne 0 || -z $_meta ]]; then
			_bad=$((_bad + 1))
			_speed_debug_log "APPDETAILS_BUNDLE_PREUPLOAD_JSON_CHECK_BAD app=$_app file=$_jf reason=parse_or_empty mode=manifest-onepass-r286"
			continue
		fi
		_pkg="${_meta%%$'	'*}"
		_okflag="${_meta#*$'	'}"
		if [[ $_okflag != true || -z $_pkg ]]; then
			_bad=$((_bad + 1))
			_speed_debug_log "APPDETAILS_BUNDLE_PREUPLOAD_JSON_CHECK_BAD app=$_app file=$_jf package=${_pkg:-empty} required=$_okflag mode=manifest-onepass-r286"
			continue
		fi
		_sz="$(stat -c%s "$_jf" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null})"
		_sha="$(sha256sum "$_jf" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} | awk '{print $1}')"
		printf '%s	%s	%s	%s
' "$_app" "$_pkg" "${_sz:-0}" "$_sha" >> "$_manifest"
		_count=$((_count + 1))
	done
	if [[ $_total -gt 0 && $_bad -eq 0 && $_count -eq $_total ]]; then
		printf '%s\n' "$_count" > "$(_appdetails_bundle_preupload_ok_file)" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} || true
		_eventwait_output_files_stable_ms appdetails_bundle_manifest_ready 50 1200 "$_manifest" "$(_appdetails_bundle_preupload_ok_file)" >/dev/null 2>&1 || true
		_speed_debug_log "APPDETAILS_BUNDLE_PREUPLOAD_JSON_CHECK_OK count=$_count total=$_total mode=manifest-onepass-r286"
		_speed_debug_log "APPDETAILS_BUNDLE_MANIFEST_READY count=$_count file=$_manifest mode=manifest-onepass-r286"
		echoRgb "app_details bundle JSON 預檢通過 $_count/$_total" "1"
		return 0
	fi
	_speed_debug_log "APPDETAILS_BUNDLE_PREUPLOAD_JSON_CHECK_FAIL ok=$_count bad=$_bad total=$_total mode=manifest-onepass-r286"
	echoRgb "app_details bundle JSON 預檢失敗 $_bad/$_total；不上傳 bundle" "0"
	return 1
}

_appdetails_bundle_payload_consistency_check() {
	# r379: build app_details payload map and remote payload map once, then do one awk in-memory join.
	# This keeps r375/r376 safety but avoids per-entry jq/awk probes.
	[[ ${remote_stream:-0} = 1 && -n ${remote_type:-} ]] || return 0
	[[ -f $TMPDIR/.remote_files ]] || return 0
	local _root="$1" _jf _app _remote_map _entries _bad_log _stats _checked _bad _t0 _elapsed
	[[ -d $_root ]] || return 1
	_t0="$(_speed_now_ms)"
	_remote_map="$TMPDIR/.remote_payload_map_${$}_$RANDOM.tsv"
	_entries="$TMPDIR/.appdetails_payload_map_${$}_$RANDOM.tsv"
	_bad_log="$TMPDIR/.appdetails_payload_stale_${$}_$RANDOM.log"
	_stats="$TMPDIR/.appdetails_payload_consistency_${$}_$RANDOM.stats"
	awk 'NF{print}' "$TMPDIR/.remote_files" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} | sort -u > "$_remote_map" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} || : > "$_remote_map"
	: > "$_entries" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} || return 1
	for _jf in "$_root"/*/app_details.json; do
		[[ -s $_jf ]] || continue
		_app="${_jf%/app_details.json}"; _app="${_app##*/}"
		jq -r --arg app "$_app" "$(_appdetails_jq_common_defs) ad_first_pkg as \$pkg | [\"user\",\"data\",\"obb\",\"media\",\"user_de\",\"thanox\",\"hma\"][] as \$e | (try (.[\$e].Size // empty) catch empty) as \$s | select(\$s != null and (\$s|tostring)!=\"\") | [\$app, \$pkg, \$e, (\$s|tostring)] | @tsv" "$_jf" >> "$_entries" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} || true
	done
	awk -F '	' -v badlog="$_bad_log" -v stats="$_stats" '
		NR==FNR { remote[$0]=1; next }
		{
			app=$1; pkg=$2; entry=$3; sz=$4
			gsub(/[ \t\r\n]/, "", sz)
			if (app=="" || entry=="" || sz !~ /^[0-9]+$/) next
			if (length(sz) < 4) next
			checked++
			relz=app "/" entry ".tar.zst"
			relt=app "/" entry ".tar"
			if ((relz in remote) || (relt in remote)) next
			bad++
			printf "REMOTE_METADATA_PAYLOAD_STALE app=%s package=%s entry=%s size=%s rel=%s reason=payload_missing mode=r386\n", app, (pkg==""?"unknown":pkg), entry, sz, relz >> badlog
		}
		END { printf "%d	%d\n", checked, bad > stats }
	' "$_remote_map" "$_entries" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	if [[ -s $_stats ]]; then
		IFS="$(printf '	')" read -r _checked _bad < "$_stats" 2>/dev/null || { _checked=0; _bad=1; }
	else
		_checked=0; _bad=1
	fi
	case $_checked in ''|*[!0-9]*) _checked=0 ;; esac
	case $_bad in ''|*[!0-9]*) _bad=1 ;; esac
	if [[ -n ${SPEED_DEBUG_RUN_DIR:-} && -d ${SPEED_DEBUG_RUN_DIR:-} ]]; then
		cp -f "$_remote_map" "$SPEED_DEBUG_RUN_DIR/remote_payload_map.tsv" 2>/dev/null || true
		cp -f "$_entries" "$SPEED_DEBUG_RUN_DIR/app_details_payload_map.tsv" 2>/dev/null || true
	fi
	if [[ $_bad -gt 0 ]]; then
		while read -r _line; do [[ -n $_line ]] && _speed_debug_log "$_line"; done < "$_bad_log"
		_elapsed="$(( $(_speed_now_ms) - _t0 ))"
		_speed_debug_log "APPDETAILS_BUNDLE_PAYLOAD_CONSISTENCY_FAIL checked=$_checked bad=$_bad elapsedMs=$_elapsed mode=r386 map=awk-join"
		echoRgb "app_details bundle 與遠端 payload 不一致：缺 $_bad 個檔案；不上傳正式 bundle" "0"
		rm -f "$_remote_map" "$_entries" "$_bad_log" "$_stats" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
		return 1
	fi
	_elapsed="$(( $(_speed_now_ms) - _t0 ))"
	_speed_debug_log "APPDETAILS_BUNDLE_PAYLOAD_CONSISTENCY_OK checked=$_checked bad=0 elapsedMs=$_elapsed mode=r386 map=awk-join"
	rm -f "$_remote_map" "$_entries" "$_bad_log" "$_stats" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	return 0
}

_appdetails_bundle_upload_stream() {
	[[ ${remote_stream:-0} = 1 && -n ${remote_type:-} ]] || return 0
	local _root _rel _count
	_root="$(_appdetails_bundle_stage_root)"
	_rel="$(_appdetails_bundle_rel)"
	[[ -d $_root ]] || { _speed_debug_log "APPDETAILS_BUNDLE_UPLOAD_SKIP reason=no_stage rel=$_rel"; return 0; }
	_appdetails_bundle_build_manifest "$_root" || {
		echoRgb "app_details bundle 建立失敗；r286 不再回退逐檔 JSON，上傳中止" "0"
		_remote_stream_mark_fatal "$_rel" 1 0 "appdetails_bundle_manifest_failed"
		return 1
	}
	_appdetails_bundle_payload_consistency_check "$_root" || {
		_remote_stream_mark_fatal "$_rel" 1 0 "appdetails_bundle_payload_consistency_failed"
		return 1
	}
	if ! _appdetails_bundle_is_dirty; then
		_speed_debug_log "APPDETAILS_BUNDLE_UPLOAD_SKIP reason=no_json_change rel=$_rel mode=single-stage-r286"
		echoRgb "app_details bundle 無 JSON 變化，跳過上傳" "2"
		return 0
	fi
	_count="$(grep -vc '^$' "$_root/manifest.tsv" 2>/dev/null)"
	local _list
	_list="${TMPDIR:-/data/local/tmp}/.appdetails_bundle_tarlist_${$}_$RANDOM.lst"
	rm -f "$_list" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	if ! find "$_root" -mindepth 1 -maxdepth 1 -printf '%P\0' > "$_list" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}; then
		rm -f "$_list" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
		echoRgb "app_details bundle 檔案清單建立失敗；r286 不回退逐檔 JSON" "0"
		_speed_debug_log "APPDETAILS_BUNDLE_TARLIST_FAIL root=$_root mode=bundle-single-stage-flat-r286"
		_remote_stream_mark_fatal "$_rel" 1 0 "appdetails_bundle_tarlist_failed"
		return 1
	fi
	echoRgb "上傳 app_details bundle ($_count 個 JSON)" "3"
	_speed_debug_log "APPDETAILS_BUNDLE_UPLOAD_BEGIN rel=$_rel count=${_count:-0} mode=bundle-single-stage-flat-r286 layout=flat"
	# r283: archive root must be flat: manifest.tsv and <App>/app_details.json directly at tar root.
	# Do not pack the staging directory itself; no wrapper compatibility is kept for release builds.
	if ( set -o pipefail 2>/dev/null; tar --null --warning=no-file-ignored -cf - -C "$_root" -T "$_list" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} | zstd -3 -q 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} | _stream_upload "$_rel" ); then
		rm -f "$_list" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
		_speed_debug_log "APPDETAILS_BUNDLE_UPLOAD_OK rel=$_rel count=${_count:-0} mode=bundle-single-stage-flat-r286 layout=flat"
		echoRgb "app_details bundle 已上傳遠端" "1"
		return 0
	fi
	rm -f "$_list" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	echoRgb "app_details bundle 上傳失敗；r286 不再回退逐檔 JSON" "0"
	_speed_debug_log "APPDETAILS_BUNDLE_UPLOAD_FAIL rel=$_rel count=${_count:-0} mode=single-stage-r286"
	_remote_stream_mark_fatal "$_rel" 1 0 "appdetails_bundle_upload_failed"
	return 1
}

# r419: 功能7「單獨上傳當前備份」用本地備份根目錄內現有 app_details.json
# 重新彙總成根層 app_details_bundle.tar.zst。bundle 內容保持 flat layout：
# manifest.tsv 與 <目錄名>/app_details.json 直接在 tar 根層，下載後可在備份根目錄同級解包。
_appdetails_bundle_build_local_for_current_upload() {
	local _backup_root="${1:-$Backup}" _stage _list _bundle _count=0 _total=0 _jf _dir _name _ok=0
	[[ -n $_backup_root && -d $_backup_root ]] || return 1
	_stage="${TMPDIR:-/data/local/tmp}/.appdetails_current_upload_bundle_${$}_$RANDOM"
	_list="${TMPDIR:-/data/local/tmp}/.appdetails_current_upload_tarlist_${$}_$RANDOM.lst"
	_bundle="$_backup_root/$(_appdetails_bundle_rel)"
	rm -rf "$_stage" "$_list" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	mkdir -p "$_stage" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} || return 1
	for _jf in "$_backup_root"/*/app_details.json; do
		[[ -s $_jf ]] || continue
		_dir="${_jf%/app_details.json}"
		_name="${_dir##*/}"
		case "$_name" in ''|.|..|log|tools|wifi) continue ;; esac
		_total=$((_total + 1))
		mkdir -p "$_stage/$_name" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} || continue
		cp -f "$_jf" "$_stage/$_name/app_details.json" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} || continue
		_count=$((_count + 1))
	done
	if [[ $_count -le 0 ]]; then
		rm -rf "$_stage" "$_list" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
		_speed_debug_log "APPDETAILS_BUNDLE_CURRENT_UPLOAD_BUILD_FAIL reason=no_json root=$_backup_root mode=r419"
		echoRgb "找不到可彙總的 app_details.json，已中止上傳" "0"
		return 1
	fi
	if ! _appdetails_bundle_build_manifest "$_stage"; then
		rm -rf "$_stage" "$_list" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
		_speed_debug_log "APPDETAILS_BUNDLE_CURRENT_UPLOAD_BUILD_FAIL reason=manifest root=$_backup_root total=$_total copied=$_count mode=r419"
		echoRgb "app_details bundle 建立/預檢失敗，已中止上傳" "0"
		return 1
	fi
	if ! find "$_stage" -mindepth 1 -maxdepth 1 -printf '%P\0' > "$_list" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}; then
		rm -rf "$_stage" "$_list" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
		_speed_debug_log "APPDETAILS_BUNDLE_CURRENT_UPLOAD_BUILD_FAIL reason=tarlist root=$_backup_root mode=r419"
		return 1
	fi
	rm -f "$_bundle" "$_bundle.part" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	if ( set -o pipefail 2>/dev/null; tar --null --warning=no-file-ignored -cf - -C "$_stage" -T "$_list" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} | zstd -3 -q 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} > "$_bundle.part" ); then
		if [[ -s $_bundle.part ]]; then
			mv -f "$_bundle.part" "$_bundle" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} && _ok=1
		fi
	fi
	rm -rf "$_stage" "$_list" "$_bundle.part" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	if [[ $_ok = 1 ]]; then
		_eventwait_output_file_stable_ms "$_bundle" appdetails_current_upload_bundle_ready 150 3000 >/dev/null 2>&1 || true
		_speed_debug_log "APPDETAILS_BUNDLE_CURRENT_UPLOAD_BUILD_OK rel=$(_appdetails_bundle_rel) file=$_bundle count=$_count total=$_total mode=r419 layout=flat"
		echoRgb "app_details 已彙總為 $(_appdetails_bundle_rel) ($_count 個 JSON)" "1"
		return 0
	fi
	_speed_debug_log "APPDETAILS_BUNDLE_CURRENT_UPLOAD_BUILD_FAIL reason=pack root=$_backup_root count=$_count mode=r419"
	echoRgb "app_details bundle 壓縮失敗，已中止上傳" "0"
	return 1
}

_appdetails_bundle_extract_file() {
	local _bundle="$1" _dest="$2" _mode="${3:-extract}" _count
	[[ -s $_bundle && -n $_dest ]] || return 1
	rm -rf "$_dest" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	mkdir -p "$_dest" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} || return 1
	if ! zstd -dc "$_bundle" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} | tar -xf - -C "$_dest" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}; then
		_speed_debug_log "APPDETAILS_BUNDLE_EXTRACT_FAIL mode=$_mode file=$_bundle dest=$_dest"
		return 1
	fi
	# r283: official release uses flat bundle only. No wrapper compatibility path; older test wrapper is unsupported.
	[[ -f "$_dest/manifest.tsv" ]] && _eventwait_output_file_stable_ms "$_dest/manifest.tsv" appdetails_bundle_extract_manifest_ready 80 1500 >/dev/null 2>&1 || true
	_count="$(_appdetails_index_count "$_dest" 2 2)"
	_speed_debug_log "APPDETAILS_BUNDLE_EXTRACT_OK mode=$_mode count=${_count:-0} file=$_bundle dest=$_dest layout=flat-r286"
	[[ ${_count:-0} -gt 0 ]]
}

_appdetails_bundle_remote_rel_resolve() {
	local _subdir="$1" _files _found _canon _legacy
	_canon="$(_appdetails_bundle_rel)"
	_legacy="$(_appdetails_bundle_legacy_rel)"
	_files="${TMPDIR:-/data/local/tmp}/.appdetails_bundle_resolve_${$}_$RANDOM"
	rm -f "$_files" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	remote_list_files "$_subdir" > "$_files" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} || true
	_eventwait_output_file_stable_ms "$_files" appdetails_bundle_resolve_filelist_ready 80 1500 >/dev/null 2>&1 || true
	_found="$(awk -v b="$_canon" -v lb="$_legacy" '
		{ rel=$1; base=rel; sub(/^.*\//, "", base); if (base==b) {print b; exit} if (base==lb && old=="") old=lb }
		END { if (old != "") print old }
	' "$_files" 2>/dev/null | sed -n '1p')"
	rm -f "$_files" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	[[ -n $_found ]] && { printf '%s\n' "$_found"; return 0; }
	return 1
}

_appdetails_bundle_download_extract() {
	local _subdir="$1" _dest="$2" _mode="${3:-remote-json}" _rel _bundle _try_rel _resolved
	_bundle="${TMPDIR:-/data/local/tmp}/.app_details_bundle_${_mode}_$$.tar.zst"
	rm -f "$_bundle" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	_resolved="$(_appdetails_bundle_remote_rel_resolve "$_subdir" 2>/dev/null)"
	if [[ -z $_resolved ]]; then
		_speed_debug_log "APPDETAILS_BUNDLE_REMOTE_RESOLVE_MISSING subdir=$_subdir canonical=$(_appdetails_bundle_rel) legacy=$(_appdetails_bundle_legacy_rel) mode=$_mode"
		return 1
	fi
	_try_rel="$_resolved"
	_rel="${_subdir%/}/$_try_rel"
	_speed_debug_log "APPDETAILS_BUNDLE_DOWNLOAD_BEGIN rel=$_rel mode=$_mode canonical=$(_appdetails_bundle_rel) legacy=$(_appdetails_bundle_legacy_rel) resolved=$_try_rel r370=1"
	if ! _stream_download "$_rel" > "$_bundle" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}; then
		_speed_debug_log "APPDETAILS_BUNDLE_DOWNLOAD_FAIL rel=$_rel mode=$_mode resolved=$_try_rel"
		rm -f "$_bundle" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
		return 1
	fi
	_eventwait_output_file_stable_ms "$_bundle" appdetails_bundle_download_ready 150 3000 >/dev/null 2>&1 || true
	if [[ ! -s $_bundle ]]; then
		_speed_debug_log "APPDETAILS_BUNDLE_DOWNLOAD_EMPTY rel=$_rel mode=$_mode resolved=$_try_rel"
		rm -f "$_bundle" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
		return 1
	fi
	if _appdetails_bundle_extract_file "$_bundle" "$_dest" "$_mode"; then
		[[ $_try_rel != "$(_appdetails_bundle_rel)" ]] && _speed_debug_log "APPDETAILS_BUNDLE_LEGACY_COMPAT_USED rel=$_try_rel canonical=$(_appdetails_bundle_rel) mode=$_mode"
		rm -f "$_bundle" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
		return 0
	fi
	_speed_debug_log "APPDETAILS_BUNDLE_EXTRACT_ATTEMPT_FAIL rel=$_rel mode=$_mode resolved=$_try_rel"
	rm -f "$_bundle" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	return 1
}

_appdetails_bundle_seed_remote_json_cache() {
	local _subdir="$1" _stage="$2" _jf _app _ok=0 _bad=0
	[[ -n $_stage ]] || _stage="$(_appdetails_bundle_stage_root)"
	rm -f "$(_appdetails_bundle_remote_json_missing_file)" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	# r283: single-stage。舊 bundle 直接解壓到本輪 bundle staging；不建立 .remote_json，不 copy，也不 symlink。
	if ! _appdetails_bundle_download_extract "$_subdir" "$_stage" "remote-json-map-single-stage"; then
		echoRgb "遠端缺少 app_details_bundle.tar.zst（相容讀取 app_details_bundle.tar 也失敗）；r286 已不兼容舊版逐檔 JSON，將視為無遠端 JSON 紀錄" "0"
		_speed_debug_log "APPDETAILS_BUNDLE_REQUIRED_MISSING stage=prepare_remote_json_map subdir=$_subdir mode=no-fallback-r286 cache=single-stage"
		mkdir -p "$_stage" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} || true
		: > "$(_appdetails_bundle_remote_json_missing_file)" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} || true
		return 1
	fi
	for _jf in "$_stage"/*/app_details.json; do
		[[ -s $_jf ]] || continue
		_app="${_jf%/app_details.json}"; _app="${_app##*/}"
		if _remote_appdetails_json_ok "$_jf"; then
			_ok=$((_ok + 1))
		else
			_bad=$((_bad + 1))
			_speed_debug_log "APPDETAILS_BUNDLE_CACHE_DROP_INVALID app=$_app file=$_jf action=remove-from-single-stage"
			rm -f "$_jf" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
		fi
	done
	_speed_debug_log "APPDETAILS_BUNDLE_REMOTE_JSON_MAP_OK count=$_ok bad=$_bad subdir=$_subdir mode=single-stage-r286 cache=stage-root"
	if [[ $_ok -gt 0 ]]; then
		rm -f "$(_appdetails_bundle_remote_json_missing_file)" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} || true
		return 0
	fi
	: > "$(_appdetails_bundle_remote_json_missing_file)" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} || true
	return 1
}
_restore_stream_appdetails_bundle_prepare() {
	[[ ${_RESTORE_STREAM:-0} = 1 && -n ${remote_type:-} ]] || return 0
	local _dest="$TMPDIR/.restore_stage"
	if _appdetails_bundle_download_extract "$_RESTORE_SUBDIR" "$_dest" "stream-restore"; then
		_speed_debug_log "STREAM_RESTORE_APPDETAILS_BUNDLE_READY subdir=$_RESTORE_SUBDIR dest=$_dest mode=single-stage-r351"
		return 0
	fi
	# r351: 功能 11 / 流式恢復不可使用 payload-scan fallback，也不可只靠 tar.zst 猜 metadata。
	# 功能 8 可以容錯產生診斷清單；恢復必須有 app_details metadata bundle，否則拒絕，避免不安全恢復。
	_speed_debug_log "STREAM_RESTORE_APPDETAILS_BUNDLE_FAIL subdir=$_RESTORE_SUBDIR action=abort_no_metadata mode=r370"
	echoRgb "遠端缺少 app_details metadata bundle；此清單可能來自 payload 掃描，無法安全流式恢復，請重新完成備份後再恢復" "0"
	_remote_stream_mark_fatal "$_RESTORE_SUBDIR/$(_appdetails_bundle_rel)" 1 0 "appdetails_metadata_missing_for_restore"
	return 1
}

_webdav_stream_last_fail_summary() {
	# r167: Dex WebDavUtil writes structured low-noise stream diagnostics into webdav_daemon_info.log.
	# Return a compact one-line summary for REMOTE_STREAM_FATAL reason, without promoting detail logs into stderr.
	local _rel="$1" _info _line _kind _sent _elapsed _http _error
	_info="$(_speed_debug_log_path webdav_daemon_info.log 2>/dev/null)"
	[[ -n $_rel && -s $_info ]] || return 1
	_line="$(grep -F 'WEBDAV_STREAM_FAIL ' "$_info" 2>/dev/null | grep -F "rel=$_rel" 2>/dev/null | tail -n 1)"
	[[ -n $_line ]] || return 1
	_kind="$(printf '%s\n' "$_line" | sed -n 's/.* kind=\([^ ]*\).*/\1/p')"
	_sent="$(printf '%s\n' "$_line" | sed -n 's/.* sentBytes=\([0-9][0-9]*\).*/\1/p')"
	_elapsed="$(printf '%s\n' "$_line" | sed -n 's/.* elapsedMs=\([0-9][0-9]*\).*/\1/p')"
	_http="$(printf '%s\n' "$_line" | sed -n 's/.* http=\([0-9][0-9]*\).*/\1/p')"
	_error="$(printf '%s\n' "$_line" | sed -n 's/.* error=\([^ ]*\).*/\1/p')"
	[[ -n $_kind ]] || _kind=unknown
	printf 'kind=%s' "$_kind"
	[[ -n $_sent ]] && printf ' sentBytes=%s' "$_sent"
	[[ -n $_elapsed ]] && printf ' elapsedMs=%s' "$_elapsed"
	[[ -n $_http ]] && printf ' http=%s' "$_http"
	[[ -n $_error ]] && printf ' error=%s' "$_error"
	printf '\n'
}

# 通用流式上傳: 從 stdin 讀資料, 上傳到遠端 (相對遠端根的) 路徑
# 依 remote_type 分發到 smbclient / dex WebDavUtil(webdav)
# 用法: <資料來源> | _stream_upload "相對路徑/file.tar.zst"
# 回傳: 0=成功
_stream_upload() {
	local _rel="$1"
	remote_enabled || { remote_log "STREAM_UPLOAD_SKIP remote_disabled rel=$_rel"; return 1; }
	if _remote_netwatch_mark_stream_fatal "stream_upload_enter" "$_rel"; then
		remote_raw_log "stream_upload.log" "SKIP type=${remote_type:-unknown} rel=$_rel reason=remote_netwatch_changed"
		return 1
	fi
	if _remote_stream_fatal_active; then
		remote_raw_log "stream_upload.log" "SKIP type=${remote_type:-unknown} rel=$_rel reason=remote_stream_fatal $(_remote_stream_fatal_summary)"
		[[ -f $TMPDIR/.remote_stream_fatal_notice ]] || {
			echoRgb "本輪遠端流式已失敗，略過後續遠端上傳，避免網路中斷後卡住" "0" >&2
			: > "$TMPDIR/.remote_stream_fatal_notice" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
		}
		return 1
	fi
	# 加上備份子目錄前綴 (Backup_zstd_X), 與 remote_download_single_file 路徑一致, 確保增量比對找得到
	# 用快取值 (_BACKUP_DIRNAME_CACHED, 在 backup()/backup_media() 開頭固定一次) 而非即時呼叫,
	# 因為 Backup_data() 內部對非 user/data/obb/user_de/media 類型資料 (如自訂資料夾) 會暫時
	# 把全域 Compression_method 改成 tar 再復原, 若流式上傳剛好在這段窗口期觸發, 即時呼叫
	# get_backup_dirname() 會拿到被污染的值, 導致上傳到錯誤的子資料夾 (如 Backup_tar_0 而非 Backup_zstd_0)
	local _subdir="${_BACKUP_DIRNAME_CACHED:-$(get_backup_dirname)}"
	_rel="$_subdir/$_rel"
	local _stream_tag _stream_start
	_stream_tag="$(_remote_debug_seq stream_upload)"
	_stream_start=$(date +%s)
	remote_raw_log "stream_upload.log" "BEGIN tag=$_stream_tag type=$remote_type rel=$_rel"
	case $remote_type in
	smb)
		# SMB 流式: 用 cd 切目錄 (對齊既有成功的 upload_smb, -D 會吃掉路徑字元) + put - 從 stdin
		local _auth
		_auth="$(_smb_auth_args_current)" || { _smb_auth_unavailable_msg "操作"; return 1; }
		local SMB_OPTS="-t 300 -s $(_smb_client_conf)${REMOTE_PORT:+ -p $REMOTE_PORT} -m SMB3"
		local _smbpath="$SMB_REM_PATH/$_rel"; _smbpath="${_smbpath#/}"
		local _smbdir="${_smbpath%/*}" _file="${_smbpath##*/}"
		# 1. 建立目錄：r345 起優先吃 app loop 前的 SMB batch mkdir cache；cache miss 才 fallback 單 payload mkdir。
		if [[ $_smbdir != $_smbpath ]]; then
			if _smb_mkdir_cache_has "$SMB_SHARE" "$_smbdir"; then
				remote_raw_log "stream_upload.log" "SMB_MKDIR_SKIP_CACHE tag=$_stream_tag dir=$_smbdir rel=$_rel mode=r345"
			else
				local _mk_script="$TMPDIR/.smb_stream_mkdir_${_stream_tag}_$$" _mk_out _mk_rc
				: > "$_mk_script"
				_smb_mkdirs_script_append "$_smbdir" "$_mk_script"
				printf 'exit\n' >> "$_mk_script"
				if _remote_netwatch_mark_stream_fatal "stream_upload_smb_before_mkdir" "$_rel"; then
					remote_raw_log "stream_upload.log" "ABORT tag=$_stream_tag type=smb reason=remote_netwatch_changed stage=mkdir rel=$_rel"
					rm -f "$_mk_script" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
					return 1
				fi
				_mk_out="$(smbclient "$SMB_SHARE" $_auth $SMB_OPTS < "$_mk_script" 2>&1)"
				_mk_rc=$?
				remote_raw_log "stream_upload.log" "SMB_MKDIR_FALLBACK tag=$_stream_tag rc=$_mk_rc dir=$_smbdir rel=$_rel mode=r345"
				printf '%s\n' "$_mk_out" | _smb_output_filter_noise >> "${SPEED_DEBUG_RUN_DIR:-/data/speed_debug}/stream_upload_detail.log" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
				rm -f "$_mk_script" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
				if [[ $_mk_rc != 0 ]] || _smb_output_has_error "$_mk_out"; then
					_remote_netwatch_mark_stream_fatal "stream_upload_smb_mkdir_fail" "$_rel" >/dev/null 2>&1 || true
					_remote_stream_mark_fatal "$_rel" "${_mk_rc:-1}" 0 "SMB mkdir failed"
					local _elapsed_mk=$(( $(date +%s) - _stream_start ))
					remote_raw_log "stream_upload.log" "END tag=$_stream_tag type=smb rc=1 cmd_rc=$_mk_rc elapsed=${_elapsed_mk}s rel=$_rel dir=$_smbdir file=${_rel##*/} stage=mkdir"
					echoRgb "[SMB流式失敗] 建立遠端目錄失敗 dir=$_smbdir" "0" >&2
					printf '%s\n' "$_mk_out" | sed -E 's#://[^/@[:space:]]+:[^/@[:space:]]+@#://[REDACTED]@#g; s/(password[[:space:]]*=[[:space:]]*).*/\1[REDACTED]/I; s/^/  /' >&2
					return 1
				fi
				_smb_mkdir_cache_add "$SMB_SHARE" "$_smbdir"
			fi
		fi
		# 2. 流式 put -: 用 -c 傳命令 (不佔 stdin!), stdin 留給 put - 讀管道資料
		#    (之前用 printf|smbclient 喂命令會佔住 stdin, 導致 put - 讀不到資料寫出 0KB)
		local _cddir="${_smbdir//\//\\}"
		local _out _cmd_rc
		if ! _smb_safe_component "$_cddir" || ! _smb_safe_component "$_file"; then
			echoRgb "偵測到不安全的路徑字元, 拒絕流式上傳: $_file" "0" >&2
			return 1
		fi
		if _remote_netwatch_mark_stream_fatal "stream_upload_smb_before_put" "$_rel"; then
			remote_raw_log "stream_upload.log" "ABORT tag=$_stream_tag type=smb reason=remote_netwatch_changed stage=put rel=$_rel"
			return 1
		fi
		_out="$(smbclient "$SMB_SHARE" $_auth $SMB_OPTS \
			-c "cd \"$_cddir\"; put - \"$_file\"" 2>&1)"
		_cmd_rc=$?
			# smbclient 退出碼不可靠但不可忽略；SIGTERM/timeout 等非 0 必須視為失敗，
			# 再用輸出錯誤關鍵字補抓「退出 0 但實際失敗」的情況。
			local _rc=0
			[[ $_cmd_rc != 0 ]] && _rc=$_cmd_rc
			_smb_output_has_error "$_out" && [[ $_rc = 0 ]] && _rc=1
		local _elapsed=$(( $(date +%s) - _stream_start ))
		remote_raw_log "stream_upload.log" "END tag=$_stream_tag type=smb rc=$_rc cmd_rc=$_cmd_rc elapsed=${_elapsed}s rel=$_rel dir=$_cddir file=$_file"
		{
			printf '===== STREAM_UPLOAD_SMB %s rel=%s rc=%s cmd_rc=%s elapsed=%ss =====\n' "$_stream_tag" "$_rel" "$_rc" "$_cmd_rc" "$_elapsed"
			printf '%s\n' "$_out" | _smb_output_filter_noise
		} >> "${SPEED_DEBUG_RUN_DIR:-/data/speed_debug}/stream_upload_detail.log" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
		if [[ $_rc != 0 ]]; then
			if _remote_netwatch_mark_stream_fatal "stream_upload_smb_put_fail" "$_rel"; then
				: # netwatch 已轉成 fast-fail fatal
			elif ! _stream_upload_rel_is_metadata "${_rel#$_subdir/}"; then
				_remote_stream_mark_fatal "$_rel" "${_cmd_rc:-1}" 0 "SMB stream upload failed"
			fi
			echoRgb "[SMB流式失敗] dir=$_cddir file=$_file" "0" >&2
			echo "$_out" | sed -E 's#://[^/@[:space:]]+:[^/@[:space:]]+@#://[REDACTED]@#g; s/(password[[:space:]]*=[[:space:]]*).*/\1[REDACTED]/I; s/^/  /' >&2
		else
			# r288: SMB stream 成功後也必須同步本輪成功檔案筆記。
			# r260 的快速最終核驗依賴 .remote_files；WebDAV 分支早已 note，
			# SMB 分支漏記會造成剛上傳成功的 payload 在 VERIFY_MANIFEST_REMOTE_NOTE_FAST 被誤報 miss。
			_remote_files_note_present "${_rel#$_subdir/}"
			_speed_debug_log "SMB_STREAM_REMOTE_FILE_NOTE rel=${_rel#$_subdir/} tag=$_stream_tag mode=r289"
		fi
		return $_rc
		;;
	webdav)
		# WebDAV: tools 只傳 baseUrl + raw relPath；URL 編碼、managed direct/atomic 與 parent mkdir policy 由 Dex WebDavUtil 統一處理。
		local _wbase="${remote_url%/}"
		local _wdir="${_rel%/*}" _parent_mode="ensureParentMkdir"
		if [[ $_wdir != $_rel ]] && _webdav_mkcol_cache_has "$_wbase" "$_wdir"; then
			_parent_mode="skipParentMkdir"
			_speed_debug_log "WEBDAV_PUT_SKIP_PARENT_MKDIR tag=$_stream_tag rel=$_rel parent=$_wdir reason=precreated_or_cached_parent mode=r370"
		else
			_speed_debug_log "WEBDAV_PUT_DEX_PARENT_MKDIR tag=$_stream_tag rel=$_rel parent=$_wdir reason=not_in_cache mode=r370"
		fi
		local _httpcode _stream_err="$TMPDIR/.stream_err_${_stream_tag}_$$" _put_cmd _rc
		_put_cmd="${WEBDAV_STREAM_UPLOAD_CMD:-putstdinmanagedrel}"
		if [[ $_put_cmd != putstdinmanagedrel ]]; then
			echoRgb "WebDAV 流式拒絕非 Dex managed 真流式上傳命令: $_put_cmd" "0" >&2
			remote_raw_log "stream_upload.log" "ABORT tag=$_stream_tag type=webdav reason=non_managed_stream cmd=$_put_cmd rel=$_rel"
			return 1
		fi

		if _remote_netwatch_mark_stream_fatal "stream_upload_before_put" "$_rel"; then
			remote_raw_log "stream_upload.log" "ABORT tag=$_stream_tag type=webdav reason=remote_netwatch_changed rel=$_rel"
			rm -f "$_stream_err" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
			return 1
		fi

		# 379: WebDAV direct/atomic 決策搬進 Dex WebDavUtil。
		# shell 不再自行 mkdir/part/move；只把 stdin、rel 與 parent mkdir mode 交給 Dex putstdinmanagedrel。
		_webdav_dex putstdinmanagedrel "$remote_user" "$remote_pass" "$_wbase" "$_rel" auto "$_parent_mode" 2>"$_stream_err"
		_rc=$?
		_httpcode="$_WEBDAV_HTTP_CODE"
		local _elapsed=$(( $(date +%s) - _stream_start ))
		remote_raw_log "stream_upload.log" "END tag=$_stream_tag type=webdav cmd=$_put_cmd managed=1 rc=$_rc http=$_httpcode elapsed=${_elapsed}s rel=$_rel base=$_wbase"
		if [[ $_rc = 0 ]]; then
			_remote_files_note_present "${_rel#$_subdir/}"
			if [[ $_wdir != $_rel ]]; then
				_webdav_mkcol_cache_add "$_wbase" "$_wdir"
				_speed_debug_log "WEBDAV_PUT_PARENT_CACHE_ADD tag=$_stream_tag rel=$_rel parent=$_wdir mode=r370"
			fi
		fi
		remote_raw_cat "stream_upload_detail.log" "$_stream_err" "===== STREAM_UPLOAD_WEBDAV_MANAGED $_stream_tag rel=$_rel rc=$_rc http=$_httpcode elapsed=${_elapsed}s ====="
		if [[ $_rc != 0 ]]; then
			local _stream_fail_summary _stream_fail_reason
			_stream_fail_summary="$(_webdav_stream_last_fail_summary "$_rel" 2>/dev/null)"
			_stream_fail_reason="${_WEBDAV_ERROR_ZH:-WebDAV managed stream upload failed}"
			if [[ -n $_stream_fail_summary ]]; then
				_stream_fail_reason="WebDAV stream fail $_stream_fail_summary"
				remote_raw_log "stream_upload.log" "WEBDAV_STREAM_FAIL_CLASSIFY tag=$_stream_tag rel=$_rel $_stream_fail_summary"
			fi
			if _stream_upload_rel_is_metadata "${_rel#$_subdir/}"; then
				_speed_debug_log "REMOTE_STREAM_METADATA_FAIL_NONFATAL rel=$_rel rc=$_rc http=$_httpcode reason=$_stream_fail_reason"
			else
				_remote_netwatch_mark_stream_fatal "stream_upload_webdav_put_fail" "$_rel" >/dev/null 2>&1 || true
				_remote_stream_mark_fatal "$_rel" "$_rc" "$_httpcode" "$_stream_fail_reason"
			fi
			echoRgb "[WebDAV managed流式失敗 rc=$_rc http=$_httpcode] rel=$_rel" "0" >&2
			_webdav_print_reason 0 >&2
			sed -E 's#://[^/@[:space:]]+:[^/@[:space:]]+@#://[REDACTED]@#g; s/(password[[:space:]]*=[[:space:]]*).*/\1[REDACTED]/I; s/^/  /' "$_stream_err" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} >&2
		fi
		rm -f "$_stream_err"
		return $_rc
		;;
	*)
		return 1
		;;
	esac
}

# 通用流式下載: 把遠端 (相對遠端根的) 路徑檔案輸出到 stdout
# 依 remote_type 分發 smbclient(get -) / dex WebDavUtil. 配合管道解壓: _stream_download "路徑" | zstd -d | tar -x
_stream_download() {
	local _rel="$1"
	if _remote_stream_fatal_active; then
		_speed_debug_log "STREAM_DOWNLOAD_SKIP reason=remote_stream_fatal rel=$_rel"
		return 126
	fi
	if _remote_netwatch_mark_remote_fatal "stream_download_enter" "$_rel"; then
		_speed_debug_log "STREAM_DOWNLOAD_SKIP reason=remote_netwatch_changed rel=$_rel"
		return 126
	fi
	local _stream_tag _stream_start
	_stream_tag="$(_remote_debug_seq stream_download)"
	_stream_start=$(date +%s)
	remote_raw_log "stream_download.log" "BEGIN tag=$_stream_tag type=$remote_type rel=$_rel"
	case $remote_type in
	smb)
		local _auth
		_auth="$(_smb_auth_args_current)" || { _smb_auth_unavailable_msg "操作"; return 1; }
		local SMB_OPTS="-t 300 -s $(_smb_client_conf)${REMOTE_PORT:+ -p $REMOTE_PORT} -m SMB3"
		local _smbpath="$SMB_REM_PATH/$_rel"; _smbpath="${_smbpath#/}"
		local _smbdir="${_smbpath%/*}" _file="${_smbpath##*/}"
		local _cddir="${_smbdir//\//\\}"
		# get "檔" - : 輸出到 stdout；stderr 另存 raw log 後再轉回 stderr，避免污染資料流。
		local _sd_err="$TMPDIR/.stream_download_err_$$" _sd_rc _sd_elapsed
		if ! _smb_safe_component "$_cddir" || ! _smb_safe_component "$_file"; then
			echoRgb "偵測到不安全的路徑字元, 拒絕流式下載: $_file" "0" >&2
			return 1
		fi
		if _remote_netwatch_mark_remote_fatal "stream_download_smb_before_get" "$_rel"; then
			rm -f "$_sd_err" 2>/dev/null
			return 1
		fi
		smbclient "$SMB_SHARE" $_auth $SMB_OPTS \
			-c "cd \"$_cddir\"; get \"$_file\" -" 2>"$_sd_err"
		_sd_rc=$?
		if [[ $_sd_rc != 0 ]]; then
			_remote_netwatch_mark_remote_fatal "stream_download_smb_get_fail" "$_rel" >/dev/null 2>&1 || true
		fi
		_sd_elapsed=$(( $(date +%s) - _stream_start ))
		remote_raw_log "stream_download.log" "END tag=$_stream_tag type=smb rc=$_sd_rc elapsed=${_sd_elapsed}s rel=$_rel dir=$_cddir file=$_file"
		remote_raw_cat "stream_download_detail.log" "$_sd_err" "===== STREAM_DOWNLOAD_SMB $_stream_tag rel=$_rel rc=$_sd_rc elapsed=${_sd_elapsed}s ====="
		grep -Ev '^dos charset|^Can.t load|^Domain=|^OS=|^Try "help"|^getting file |^putting file |^$' "$_sd_err" >&2 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
		rm -f "$_sd_err" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
		return $_sd_rc
		;;
	webdav)
		local _wd_err="$TMPDIR/.stream_download_err_${_stream_tag}_$$" _wd_rc _wd_elapsed _wd_http _wd_base
		# AF_UNIX daemon + unixsock v2 會把兩行 protocol header 寫到 sidecar，body 直接串到 stdout；
		# 若 daemon/relay 不可用，_webdav_dex 會直接失敗，避免熱路徑回退單次 app_process。
		_wd_base="${remote_url%/}"
		if _remote_netwatch_mark_remote_fatal "stream_download_webdav_before_get" "$_rel"; then
			rm -f "$_wd_err" 2>/dev/null
			return 1
		fi
		_webdav_dex getstdoutrel "$remote_user" "$remote_pass" "$_wd_base" "$_rel" 2>"$_wd_err"
		_wd_rc=$?
		_wd_http="${_WEBDAV_HTTP_CODE:-0}"
		if [[ $_wd_rc != 0 && $_wd_http = 404 ]]; then
			_stream_download_remote_missing_note "$_rel"
		elif [[ $_wd_rc != 0 && ${_wd_rc:-1} != 126 ]] && _remote_netwatch_changed_active; then
			_remote_netwatch_mark_remote_fatal "stream_download_webdav_get_fail" "$_rel" >/dev/null 2>&1 || true
			_wd_rc=126
		fi
		if [[ $_wd_rc != 0 && $_wd_http != 404 ]]; then
			_remote_netwatch_mark_remote_fatal "stream_download_webdav_get_fail" "$_rel" >/dev/null 2>&1 || true
		fi
		if [[ $_wd_rc = 0 && ${_WEBDAV_BODY_LENGTH:-0} = 0 ]]; then
			case $_rel in
			*.tar|*.tar.zst|*/apk.tar|*/apk.tar.zst|*/data.tar|*/data.tar.zst|*/user.tar|*/user.tar.zst|*/user_de.tar|*/user_de.tar.zst|*/obb.tar|*/obb.tar.zst|*/app_details_bundle.tar|*/app_details_bundle.tar.zst)
				_wd_rc=98
				_WEBDAV_ERROR_ZH="WebDAV 回應成功但資料體為 0，判定為遠端 short-read/伺服器中斷"
				_speed_debug_log "WEBDAV_STREAM_DOWNLOAD_SHORT_BODY rel=$_rel http=${_wd_http:-0} body_len=${_WEBDAV_BODY_LENGTH:-0} mode=r370"
				;;
			esac
		fi
		_wd_elapsed=$(( $(date +%s) - _stream_start ))
		remote_raw_log "stream_download.log" "END tag=$_stream_tag type=webdav rc=$_wd_rc http=${_wd_http:-0} elapsed=${_wd_elapsed}s rel=$_rel base=$_wd_base"
		remote_raw_cat "stream_download_detail.log" "$_wd_err" "===== STREAM_DOWNLOAD_WEBDAV $_stream_tag rel=$_rel rc=$_wd_rc http=${_wd_http:-0} elapsed=${_wd_elapsed}s ====="
		# app_details / tools 探測 404、以及 head 提前關管線，都屬於預期非致命；只寫 raw log，不污染 stderr.log。
		if [[ $_wd_rc != 0 ]]; then
			case "$_wd_http:$_rel:$_wd_rc" in
			404:*app_details.json:*|404:*/tools/tools.sh:*|*:*/tools/tools.sh:18|*:*/tools/tools.sh:22|*:*/tools/tools.sh:23|*:*:18|*:*:22|*:*:23)
				_speed_debug_log "WEBDAV_STREAM_DOWNLOAD_EXPECTED_NONFATAL rel=$_rel rc=$_wd_rc http=${_wd_http:-0}"
				;;
			*)
				cat "$_wd_err" >&2 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
				;;
			esac
		fi
		rm -f "$_wd_err" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
		return $_wd_rc
		;;
	*)
		return 1
		;;
	esac
}

# 解析 SMB URL 並設定 SMB_SHARE / SMB_REM_PATH 全域變數
# SMB_SHARE     = //server/share_name (smbclient -L 用)
# SMB_REM_PATH  = /sub/path (空字串代表 share 根目錄, 不含結尾斜線)
# 重複的 SMB URL 解析邏輯抽出 (原本有 4 個地方各自解析)
remote_parse_smb_url() {
	local url="${remote_url#smb://}"; url="${url%/}"
	local server="${url%%/*}"
	local after_server="${url#$server/}"
	local share_name="${after_server%%/*}"
	# after_server 去掉 share_name 後可能是 "" 或 "/path/..."
	# 直接用結果, 不再前綴 "/", 否則 "/path" 會變 "//path"
	local rem_path="${after_server#$share_name}"
	rem_path="${rem_path%/}"
	[[ $rem_path = / ]] && rem_path=""
	SMB_SHARE="//$server/$share_name"
	SMB_REM_PATH="$rem_path"
}

SMB_CMD_OPTS=""
SMB_AUTH_ARGS=""
SMB_SESSION_SHARE=""
SMB_SESSION_REM_PATH=""
SMB_SESSION_BASE=""
SMB_SESSION_BASE_BSLASH=""
_smb_join_rel() {
	# $1=base slash path, $2=relative path；輸出已去頭尾多餘 / 的 SMB 相對路徑。
	local _base="${1:-}" _rel="${2:-}" _out
	_base="${_base#/}"; _base="${_base%/}"
	_rel="${_rel#/}"
	case $_rel in *../*|../*|/*) return 1 ;; esac
	if [[ -n $_base && -n $_rel ]]; then _out="$_base/$_rel"
	elif [[ -n $_base ]]; then _out="$_base"
	else _out="$_rel"; fi
	_out="${_out#/}"; _out="${_out%/}"
	printf '%s\n' "$_out"
}

_smb_session_prepare() {
	# 建立單次 SMB 操作 context：share、auth、共同 smbclient opts、備份根目錄。
	# $1=timeout seconds, $2=append backup dirname(0/1, default 0)
	local _timeout="${1:-300}" _with_backup="${2:-0}" _subdir _base
	remote_parse_smb_url
	SMB_AUTH_ARGS="$(_smb_auth_args_current)" || return 1
	case $_timeout in ''|*[!0-9]*) _timeout=300 ;; esac
	SMB_CMD_OPTS="-t $_timeout -s $(_smb_client_conf)${REMOTE_PORT:+ -p $REMOTE_PORT} -m SMB3"
	SMB_SESSION_SHARE="$SMB_SHARE"
	SMB_SESSION_REM_PATH="$SMB_REM_PATH"
	_base="$SMB_REM_PATH"
	if [[ $_with_backup = 1 ]]; then
		_subdir="${_BACKUP_DIRNAME_CACHED:-$(get_backup_dirname)}"
		_base="$(_smb_join_rel "$SMB_REM_PATH" "$_subdir")" || return 1
	else
		_base="${_base#/}"; _base="${_base%/}"
	fi
	SMB_SESSION_BASE="$_base"
	SMB_SESSION_BASE_BSLASH="${_base//\//\\}"
	[[ -z $SMB_SESSION_BASE_BSLASH ]] && SMB_SESSION_BASE_BSLASH="\\"
	_speed_debug_log "SMB_SESSION_PREPARE share=$SMB_SESSION_SHARE base=${SMB_SESSION_BASE:-/} timeout=$_timeout port=${REMOTE_PORT:-default}"
	return 0
}

_smb_cmd_common() {
	# 466/r17: 已收斂的 smbclient 呼叫走這裡，統一 auth/opts/share。
	# 用法：_smb_cmd_common [extra smbclient args...] < batchfile
	[[ -n ${SMB_SESSION_SHARE:-} && -n ${SMB_CMD_OPTS:-} && -n ${SMB_AUTH_ARGS:-} ]] || _smb_session_prepare 300 0 || return 1
	smbclient "$SMB_SESSION_SHARE" $SMB_AUTH_ARGS $SMB_CMD_OPTS "$@"
}

_smb_cmd_common_share() {
	local _share="$1"
	shift
	[[ -n $_share ]] || _share="${SMB_SESSION_SHARE:-$SMB_SHARE}"
	[[ -n ${SMB_CMD_OPTS:-} && -n ${SMB_AUTH_ARGS:-} ]] || _smb_session_prepare 300 0 || return 1
	smbclient "$_share" $SMB_AUTH_ARGS $SMB_CMD_OPTS "$@"
}

_smb_mkdirs_script_append() {
	# $1=slash path, $2=script file；逐層輸出 smbclient mkdir 命令。
	local _path="${1:-}" _script="$2" _cur="" _seg _OLDIFS
	[[ -n $_script ]] || return 1
	_path="${_path#/}"; _path="${_path%/}"
	_OLDIFS="$IFS"; IFS='/'; set -- $_path; IFS="$_OLDIFS"
	for _seg; do
		[[ -z $_seg ]] && continue
		if [[ -z $_cur ]]; then _cur="$_seg"; else _cur="${_cur}\\${_seg}"; fi
		printf 'mkdir "%s"\n' "$_cur" >> "$_script"
	done
}

# r345: SMB 真流式大 payload 也做本輪目錄 cache。
# WebDAV 已由 Dex skipParentMkdir；SMB 仍由 tools/smbclient 管理，因此在 app loop 前批量 mkdir，
# 後續 _stream_upload 命中 cache 時直接 put，不再每個 payload 都跑 mkdir。
_SMB_MKDIR_CACHE_FILE="${_SMB_MKDIR_CACHE_FILE:-${TMPDIR:-/data/local/tmp}/.smb_mkdir_cache_$$}"

_smb_mkdir_cache_prune_stale() {
	local _f
	for _f in "${TMPDIR:-/data/local/tmp}"/.smb_mkdir_cache "${TMPDIR:-/data/local/tmp}"/.smb_mkdir_cache_[0-9]*; do
		[[ -e $_f ]] || continue
		[[ $_f = "$_SMB_MKDIR_CACHE_FILE" ]] && continue
		rm -f "$_f" 2>/dev/null
	done
}
_smb_mkdir_cache_prune_stale

_smb_mkdir_cache_has() {
	local _key="$1	$2"
	[[ -s $_SMB_MKDIR_CACHE_FILE ]] && grep -Fqx "$_key" "$_SMB_MKDIR_CACHE_FILE" 2>/dev/null
}

_smb_mkdir_cache_add() {
	local _key="$1	$2"
	mkdir -p "${_SMB_MKDIR_CACHE_FILE%/*}" 2>/dev/null || true
	printf '%s\n' "$_key" >> "$_SMB_MKDIR_CACHE_FILE" 2>/dev/null
}

_smb_stream_prepare_dirs_batch() {
	local _manifest="$1" _mode="${2:-stream}" _tmp _uniq _script _out _total _ok _bad _rel _rc _out_text
	[[ ${remote_type:-} = smb && ${remote_stream:-0} = 1 ]] || return 0
	[[ -s $_manifest ]] || { _speed_debug_log "SMB_STREAM_DIR_BATCH_SKIP reason=empty mode=$_mode"; return 0; }
	_smb_session_prepare 300 1 || { _smb_auth_unavailable_msg "批量建立遠端目錄"; return 1; }
	_tmp="$TMPDIR/.smb_stream_dir_batch_${_mode}_$$_$RANDOM.lst"
	_uniq="$TMPDIR/.smb_stream_dir_batch_${_mode}_$$_$RANDOM.uniq"
	_script="$TMPDIR/.smb_stream_dir_batch_${_mode}_$$_$RANDOM.cmd"
	_out="$TMPDIR/.smb_stream_dir_batch_${_mode}_$$_$RANDOM.out"
	awk 'NF{gsub(/^\/+/,"",$0); gsub(/\/+$/,"",$0); if($0!="") print $0}' "$_manifest" 2>/dev/null | sort -u > "$_uniq" 2>/dev/null
	: > "$_tmp"
	while IFS= read -r _rel; do
		[[ -n $_rel ]] || continue
		case $_rel in /*|*../*|../*) _speed_debug_log "SMB_STREAM_DIR_BATCH_SKIP_UNSAFE rel=$_rel mode=$_mode"; continue ;; esac
		if ! _smb_safe_component "$_rel"; then
			_speed_debug_log "SMB_STREAM_DIR_BATCH_SKIP_UNSAFE rel=$_rel reason=smb_unsafe_component mode=$_mode"
			continue
		fi
		if _smb_mkdir_cache_has "$SMB_SESSION_SHARE" "$_rel"; then
			_speed_debug_log "SMB_STREAM_DIR_BATCH_CACHE_HIT rel=$_rel mode=$_mode"
		else
			printf '%s\n' "$_rel" >> "$_tmp"
		fi
	done < "$_uniq"
	_total="$(grep -vc '^$' "$_tmp" 2>/dev/null)"
	case $_total in ''|*[!0-9]*) _total=0 ;; esac
	[[ $_total -gt 0 ]] || { _speed_debug_log "SMB_STREAM_DIR_BATCH_SKIP reason=all_cached mode=$_mode"; rm -f "$_tmp" "$_uniq" "$_script" "$_out" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}; return 0; }
	echoRgb "SMB 批量預建立遠端目錄 $_total 個" "3"
	: > "$_script"
	while IFS= read -r _rel; do
		[[ -n $_rel ]] || continue
		_smb_mkdirs_script_append "$_rel" "$_script"
	done < "$_tmp"
	printf 'exit\n' >> "$_script"
	if _remote_netwatch_mark_stream_fatal "smb_stream_dir_batch_before_mkdir" "$_mode"; then
		_speed_debug_log "SMB_STREAM_DIR_BATCH_ABORT mode=$_mode reason=remote_netwatch_changed"
		rm -f "$_tmp" "$_uniq" "$_script" "$_out" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
		return 1
	fi
	_out_text="$(_smb_cmd_common < "$_script" 2>&1)"
	_rc=$?
	printf '%s\n' "$_out_text" > "$_out" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	remote_raw_log "stream_upload.log" "SMB_STREAM_DIR_BATCH_MKDIR mode=$_mode rc=$_rc total=$_total"
	printf '%s\n' "$_out_text" | _smb_output_filter_noise >> "${SPEED_DEBUG_RUN_DIR:-/data/speed_debug}/stream_upload_detail.log" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	if [[ $_rc != 0 ]] || _smb_output_has_error "$_out_text"; then
		_bad=$_total
		_speed_debug_log "SMB_STREAM_DIR_BATCH_PREPARE_FAIL mode=$_mode total=$_total rc=$_rc action=per-upload-fallback"
		rm -f "$_tmp" "$_uniq" "$_script" "$_out" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
		return 1
	fi
	_ok=0; _bad=0
	while IFS= read -r _rel; do
		[[ -n $_rel ]] || continue
		_smb_mkdir_cache_add "$SMB_SESSION_SHARE" "$_rel"
		_ok=$((_ok + 1))
	done < "$_tmp"
	_speed_debug_log "SMB_STREAM_DIR_BATCH_PREPARE_OK mode=$_mode total=$_total ok=$_ok bad=$_bad command=smbclient-batch-r345"
	rm -f "$_tmp" "$_uniq" "$_script" "$_out" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	return 0
}

_smb_stream_prepare_app_dirs_from_txt() {
	[[ ${remote_type:-} = smb && ${remote_stream:-0} = 1 ]] || return 0
	[[ -n ${txt:-} ]] || return 0
	local _manifest="$TMPDIR/.smb_stream_app_dirs_$$_$RANDOM.lst" _line _name _pkg _rel
	_smb_session_prepare 300 1 || return 1
	: > "$_manifest"
	while IFS= read -r _line; do
		case $_line in ''|\#*|＃*) continue ;; esac
		_name="${_line%% *}"
		_pkg="${_line#* }"; _pkg="${_pkg%% *}"
		[[ -z $_name || -z $_pkg || $_pkg = "$_line" ]] && continue
		case $_name in
		\!*) _name="${_name#!}" ;;
		！*) _name="${_name#！}" ;;
		esac
		_name="$(_backup_path_safe_name "$_name" "$_pkg")"
		[[ -n $_name ]] || continue
		_rel="$(_smb_join_rel "$SMB_SESSION_BASE" "$_name")" || continue
		printf '%s\n' "$_rel" >> "$_manifest"
	done <<EOF_SMB_STREAM_APP_DIRS
$txt
EOF_SMB_STREAM_APP_DIRS
	_smb_stream_prepare_dirs_batch "$_manifest" "app-stream-preput" || _speed_debug_log "SMB_STREAM_DIR_BATCH_PREPARE_WARN mode=app-stream-preput action=per-upload-fallback"
	rm -f "$_manifest" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
}

_smb_trim_value() {
	# mksh 相容：去掉常見設定檔殘留空白/CR/TAB，避免把空白誤判成帳號。
	printf '%s' "${1:-}" | tr -d '
' | sed 's/^[[:space:]]*//;s/[[:space:]]*$//'
}

_smb_ensure_authfile() {
	# SMB 有帳號時一律用臨時 credentials file，即使密碼為空字串也要建立。
	# 這避免 remote_user 已設定但 _SMB_AUTHFILE 因初始化時機/TMPDIR 清理而不存在時，誤報「認證檔不存在」。
	local _u _auth_dir
	_u="$(_smb_trim_value "${remote_user:-}")"
	[[ -n $_u ]] || return 1
	if [[ -n ${_SMB_AUTHFILE:-} && -f "$_SMB_AUTHFILE" ]]; then
		return 0
	fi
	_auth_dir="${TMPDIR:-/data/local/tmp}"
	mkdir -p "$_auth_dir" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	_SMB_AUTHFILE="$_auth_dir/.smb_authfile_$$"
	{
		printf 'username = %s\n' "$_u"
		printf 'password = %s\n' "${remote_pass:-}"
	} > "$_SMB_AUTHFILE" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} || return 1
	chmod 0600 "$_SMB_AUTHFILE" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	return 0
}

_smb_auth_args_current() {
	# 無帳號：匿名/Guest；有帳號：惰性建立 credentials file。
	# 不再把「密碼未設」等同於「不能測試」；空密碼帳號會寫入 password = 空字串。
	if [[ -n "$(_smb_trim_value "${remote_user:-}")" ]]; then
		if _smb_ensure_authfile; then
			printf '%s\n' "-A $_SMB_AUTHFILE"
			return 0
		fi
		return 1
	fi
	printf '%s\n' "-N"
	return 0
}

_smb_protocol_from_debug() {
	local _dbg="$1" _proto=""
	[[ -s $_dbg ]] || return 1
	_proto="$(grep -aioE 'selected protocol[^A-Za-z0-9_]*(SMB[0-9](_[0-9]{2})?|SMB[0-9]_[0-9]{2}|NT1)|negotiated dialect[^A-Za-z0-9_]*(SMB[0-9](_[0-9]{2})?|SMB[0-9]_[0-9]{2}|NT1)|protocol[^\n\r]*(SMB[0-9]_[0-9]{2}|SMB[0-9]|NT1)[^\n\r]*(selected|negotiated)' "$_dbg" 2>/dev/null | grep -aioE 'SMB[0-9]_[0-9]{2}|SMB[0-9]|NT1' | tail -1)"
	[[ -n $_proto ]] || _proto="$(grep -aioE 'SMB3_11|SMB3_02|SMB3_00|SMB2_10|SMB2_02|SMB3|SMB2|NT1' "$_dbg" 2>/dev/null | tail -1)"
	[[ -n $_proto ]] || return 1
	printf '%s\n' "$_proto"
	return 0
}

_smb_probe_one_dialect() {
	local _share="$1" _auth="$2" _dialect="$3" _rem_path="${4:-}" _dbg="$5" _out _rc _cmd
	_cmd="cd ${_rem_path:-/}; exit"
	_out="$(smbclient "$_share" $_auth -t 5 -s $(_smb_client_conf)${REMOTE_PORT:+ -p $REMOTE_PORT} \
		--option="client min protocol=$_dialect" --option="client max protocol=$_dialect" \
		-c "$_cmd" 2>&1)"
	_rc=$?
	{
		echo "===== SMB_FORCE_DIALECT $_dialect rc=$_rc ====="
		printf '%s\n' "$_out"
	} >> "$_dbg" 2>/dev/null
	[[ $_rc = 0 ]] || return 1
	printf '%s\n' "$_out" | grep -qiE 'protocol negotiation failed|NT_STATUS_INVALID_NETWORK_RESPONSE|NT_STATUS_NOT_SUPPORTED|NT_STATUS_CONNECTION_DISCONNECTED|NT_STATUS_LOGON_FAILURE|NT_STATUS_ACCESS_DENIED' && return 1
	return 0
}

_smb_detect_protocol_version() {
	local _share="$1" _auth="$2" _rem_path="${3:-}" _dbg
	_dbg="$(_speed_debug_log_path smb_protocol_debug.log)"
	: > "$_dbg" 2>/dev/null
	{
		echo "===== SMB_PROTOCOL_DETECT $(date '+%Y-%m-%d %H:%M:%S') ====="
		echo "share=$_share rem_path=${_rem_path:-/} port=${REMOTE_PORT:-default}"
		echo "method=debug-parse"
	} >> "$_dbg" 2>/dev/null
	smbclient "$_share" $_auth -t 5 -s $(_smb_client_conf)${REMOTE_PORT:+ -p $REMOTE_PORT} -m SMB3 -d 10 \
		-c 'exit' >>"$_dbg" 2>&1
	local _proto
	_proto="$(_smb_protocol_from_debug "$_dbg")"
	if [[ -n $_proto ]]; then
		echoRgb "協議版本: $_proto" "1"
		return 0
	fi
	{
		echo ""
		echo "method=forced-dialect-probe"
	} >> "$_dbg" 2>/dev/null
	local _d
	for _d in SMB3_11 SMB3_02 SMB3_00 SMB2_10 SMB2_02 NT1; do
		if _smb_probe_one_dialect "$_share" "$_auth" "$_d" "$_rem_path" "$_dbg"; then
			echoRgb "協議版本: $_d (最高可用)" "1"
			return 0
		fi
	done
	echoRgb "無法解析協議版本，debug 已寫入 speed_debug: smb_protocol_debug.log" "2"
	return 1
}

_webdav_http_reason() {
	case "${1:-0}" in
	0|000) echo "未收到 HTTP 回應：可能是 DNS/路由/防火牆、TLS 握手失敗、daemon 無回應或連線被中斷" ;;
	200|201|204|207) echo "請求成功" ;;
	301|302|303|307|308) echo "伺服器要求重定向：remote_url 可能不是 WebDAV 真實端點" ;;
	400) echo "請求格式錯誤：URL 或 WebDAV path 可能含不合法字元" ;;
	401) echo "認證失敗：帳號或密碼錯誤" ;;
	403) echo "權限不足：帳號可登入但沒有此路徑讀寫權限" ;;
	404) echo "路徑不存在：remote_url/base path 或備份目錄不存在" ;;
	405) echo "方法不允許：此 URL 可能不是 WebDAV 端點，或伺服器不允許 PROPFIND/PUT" ;;
	408) echo "請求逾時：伺服器忙碌或網路延遲過高" ;;
	409) echo "父目錄不存在：需要先建立上層 WebDAV 目錄" ;;
	413) echo "檔案過大：伺服器限制單檔大小或反向代理限制 body size" ;;
	415) echo "伺服器不接受目前上傳格式" ;;
	423) echo "資源被鎖定：可能有其他客戶端正在寫入" ;;
	429) echo "請求過於頻繁：觸發伺服器限流" ;;
	500) echo "伺服器內部錯誤" ;;
	501) echo "伺服器不支援此 WebDAV 方法" ;;
	502) echo "閘道錯誤：反向代理或上游服務異常" ;;
	503) echo "服務不可用：伺服器維護、過載或 WebDAV 服務未啟動" ;;
	504) echo "閘道逾時：反向代理等待上游逾時" ;;
	507) echo "遠端空間不足或配額已滿" ;;
	*) echo "WebDAV/HTTP 異常：HTTP $1" ;;
	esac
}

_webdav_stderr_reason() {
	local _err="$1"
	case "$_err" in
	*UnknownHostException*|*Could\ not\ resolve\ host*|*Couldn*resolve*host*) echo "DNS 解析失敗：域名不存在、DNS 不通或代理未生效" ;;
	*ConnectException*Connection\ refused*|*Connection\ refused*) echo "連線被拒：IP 可達但端口未開，或防火牆拒絕" ;;
	*NoRouteToHostException*|*Network\ is\ unreachable*|*Host\ is\ unreachable*) echo "網路不可達：不在同網段、路由錯誤或防火牆阻擋" ;;
	*SocketTimeoutException*|*timed\ out*|*timeout*) echo "連線或讀寫逾時：伺服器太慢或網路不穩" ;;
	*SSLHandshakeException*|*certificate*|*Hostname\ verification\ failed*) echo "TLS/憑證驗證失敗：自簽、過期、域名不匹配或 http/https 寫錯" ;;
	*WRONG_VERSION_NUMBER*|*wrong\ version\ number*) echo "協議與端口不匹配：可能把 https 寫到 http 端口，或反過來" ;;
	*EOFException*empty\ HTTP\ response*|*Empty\ reply*) echo "伺服器提前關閉連線，沒有回 HTTP 回應" ;;
	*unexpected\ EOF*) echo "傳輸中斷：下載/上傳途中連線被關閉" ;;
	*HttpCore\ client\ is\ closing*) echo "WebDAV daemon 正在關閉，請重試" ;;
	*) return 1 ;;
	esac
	return 0
}

_webdav_set_error_zh() {
	local _code="${1:-0}" _err="${2:-}"
	_WEBDAV_ERROR_ZH="$(_webdav_stderr_reason "$_err" 2>/dev/null || true)"
	[[ -n $_WEBDAV_ERROR_ZH ]] || _WEBDAV_ERROR_ZH="$(_webdav_http_reason "$_code")"
	return 0
}


_remote_files_note_present() {
	local _rel="$1"
	[[ -n $_rel ]] || return 0
	case $_rel in /*|*../*|../*) return 0 ;; esac
	[[ -f $TMPDIR/.remote_files ]] || return 0
	# r118: 上傳成功後只在缺少時 append；不再每次 cat+awk 重寫整個遠端列表，
	# 避免大量小檔/metadata 上傳時對 TMPDIR 反覆 O(n) 改寫。
	if ! awk -v r="$_rel" '$0==r{f=1;exit} END{exit f?0:1}' "$TMPDIR/.remote_files" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}; then
		printf '%s\n' "$_rel" >> "$TMPDIR/.remote_files" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	fi
	_speed_debug_log "REMOTE_FILELIST_NOTE_PRESENT rel=$_rel"
	return 0
}

_remote_size_map_before_file() {
	printf '%s\n' "${TMPDIR:-/data/local/tmp}/.remote_size_map_before"
}

_remote_size_map_capture_enabled() {
	local _path="$1" _root
	_root="${_BACKUP_DIRNAME_CACHED:-$(get_backup_dirname)}"
	[[ -n $_path && -n $_root && $_path = "$_root" ]] || return 1
	return 0
}

_remote_stream_uploaded_size_map_file() {
	printf '%s\n' "${TMPDIR:-/data/local/tmp}/.remote_size_map_uploaded"
}

_remote_stream_build_uploaded_size_map() {
	local _subdir="$1" _out="$2" _info _detail _tmp
	[[ -n $_out ]] || return 1
	: > "$_out" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} || return 1
	_tmp="$(_webdav_tmp_path remote_size_map_uploaded_raw_${$}_$RANDOM)"
	: > "$_tmp" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} || return 1
	_info="$(_speed_debug_log_path webdav_daemon_info.log 2>/dev/null)"
	_detail="$(_speed_debug_log_path stream_upload_detail.log 2>/dev/null)"
	# r299: Android/busybox awk 大數 print s+0 可能輸出科學記號，後續純數字 gate 會把 3.7e+10 當不可用。
	# 延續 r298 split-awk，但所有 fastmap 大數 sum/delta 改用 printf "%.0f" 輸出十進位整數。
	[[ -s $_info || -s $_detail ]] || { rm -f "$_tmp" 2>/dev/null; return 1; }
	if [[ -s $_info ]]; then
		awk -v root="$_subdir" '
			function kv(line, key,    n,a,i,p) {
				n=split(line,a," ");
				for (i=1;i<=n;i++) { p=index(a[i],"="); if (p>0 && substr(a[i],1,p-1)==key) return substr(a[i],p+1) }
				return ""
			}
			function norm(rel,    r) {
				r=rel
				gsub(/^\/+/, "", r)
				if (root != "" && index(r, root"/")==1) r=substr(r, length(root)+2)
				return r
			}
			/WEBDAV_STREAM_DONE/ && /kind=ok/ {
				rel=norm(kv($0,"rel")); bytes=kv($0,"sentBytes")
				if (rel=="" || rel ~ /\/$/ || bytes !~ /^[0-9]+$/) next
				print rel "\t" bytes
			}
		' "$_info" >> "$_tmp" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} || true
	fi
	if [[ -s $_detail ]]; then
		awk -v root="$_subdir" '
			function norm(rel,    r) {
				r=rel
				gsub(/^\/+/, "", r)
				if (root != "" && index(r, root"/")==1) r=substr(r, length(root)+2)
				return r
			}
			$0 !~ /^=/ && $0 !~ /^SUMMARY[	 ]/ && $0 !~ /^$/ {
				rel=norm($1); http=$2; bytes=$3; status=$4
				if (rel=="" || rel ~ /\/$/ || bytes !~ /^[0-9]+$/) next
				if (status!="OK" && http !~ /^20[0-9]$/) next
				print rel "\t" bytes
			}
		' "$_detail" >> "$_tmp" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} || true
	fi
	awk -F '\t' '$1!="" && $2 ~ /^[0-9]+$/ { size[$1]=$2 } END { for (r in size) print r "\t" size[r] }' "$_tmp" > "$_out" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	rm -f "$_tmp" 2>/dev/null
	[[ -s $_out ]] && {
		_speed_debug_log "REMOTE_TOTAL_FASTMAP_UPLOAD_MAP_READY rows=$(grep -vc '^$' "$_out" 2>/dev/null) mode=r309-split-awk-decimal-shell-gate"
		return 0
	}
	return 1
}

_decimal_add_uint() {
	local _a="${1:-0}" _b="${2:-0}" _carry=0 _res="" _ap _bp _da _db _sum _digit
	case $_a in ''|*[!0-9]*) _a=0 ;; esac
	case $_b in ''|*[!0-9]*) _b=0 ;; esac
	while [[ -n $_a || -n $_b || $_carry -ne 0 ]]; do
		_da=0
		_db=0
		if [[ -n $_a ]]; then
			_ap=${_a%?}
			_da=${_a#$_ap}
			_a=$_ap
		fi
		if [[ -n $_b ]]; then
			_bp=${_b%?}
			_db=${_b#$_bp}
			_b=$_bp
		fi
		_sum=$((_carry + _da + _db))
		_digit=$((_sum % 10))
		_carry=$((_sum / 10))
		_res="$_digit$_res"
	done
	[[ -n $_res ]] || _res=0
	while [[ $_res = 0[0-9]* ]]; do
		_res=${_res#0}
	done
	printf '%s\n' "$_res"
}

_decimal_sum_uint_stdin() {
    local _n _sum=0
    # r308: keep the final unterminated line, matching awk's behavior for stdin without trailing newline.
    while IFS= read -r _n || [[ -n $_n ]]; do
        case $_n in ''|*[!0-9]*) continue ;; esac
        _sum="$(_decimal_add_uint "$_sum" "$_n")"
    done
    printf '%s\n' "$_sum"
}

_decimal_commas_uint() {
    local _n _out="" _tail
    _n="$(_decimal_norm_uint "$1")"
    while [[ ${#_n} -gt 3 ]]; do
        _tail=${_n#${_n%???}}
        _n=${_n%???}
        _out=",$_tail$_out"
    done
    printf '%s%s\n' "$_n" "$_out"
}

_decimal_norm_uint() {
	local _n="${1:-0}"
	case $_n in ''|*[!0-9]*) _n=0 ;; esac
	while [[ $_n = 0[0-9]* ]]; do
		_n=${_n#0}
	done
	[[ -n $_n ]] || _n=0
	printf '%s\n' "$_n"
}

_decimal_is_positive() {
	local _n
	_n="$(_decimal_norm_uint "$1")"
	[[ $_n != 0 ]]
}

_decimal_cmp_uint() {
	local _a _b _la _lb
	_a="$(_decimal_norm_uint "$1")"
	_b="$(_decimal_norm_uint "$2")"
	[[ $_a = "$_b" ]] && { echo 0; return 0; }
	_la=${#_a}
	_lb=${#_b}
	if [[ $_la -gt $_lb ]]; then echo 1; return 0; fi
	if [[ $_la -lt $_lb ]]; then echo -1; return 0; fi
	if [[ $_a > $_b ]]; then echo 1; else echo -1; fi
}

_decimal_sub_uint_abs() {
	local _a _b _borrow=0 _res="" _ap _bp _da _db _d
	_a="$(_decimal_norm_uint "$1")"
	_b="$(_decimal_norm_uint "$2")"
	while [[ -n $_a || -n $_b ]]; do
		_da=0
		_db=0
		if [[ -n $_a ]]; then
			_ap=${_a%?}
			_da=${_a#$_ap}
			_a=$_ap
		fi
		if [[ -n $_b ]]; then
			_bp=${_b%?}
			_db=${_b#$_bp}
			_b=$_bp
		fi
		_d=$((_da - _borrow - _db))
		if [[ $_d -lt 0 ]]; then
			_d=$((_d + 10))
			_borrow=1
		else
			_borrow=0
		fi
		_res="$_d$_res"
	done
	while [[ $_res = 0[0-9]* ]]; do
		_res=${_res#0}
	done
	[[ -n $_res ]] || _res=0
	printf '%s\n' "$_res"
}

_decimal_diff_uint() {
	local _cmp
	_cmp="$(_decimal_cmp_uint "$1" "$2")"
	case $_cmp in
		0) echo 0 ;;
		1) _decimal_sub_uint_abs "$1" "$2" ;;
		*) printf -- '-%s
' "$(_decimal_sub_uint_abs "$2" "$1")" ;;
	esac
}

_remote_size_map_sum_file() {
	local _f="$1" _rel _bytes _rest _sum=0
	[[ -s $_f ]] || { echo 0; return 1; }
	# r308: sum and every fastmap gate stay decimal-string safe; keep final unterminated map row.
	while IFS='	' read -r _rel _bytes _rest || [[ -n $_rel || -n $_bytes || -n $_rest ]]; do
		case $_bytes in ''|*[!0-9]*) continue ;; esac
		_sum="$(_decimal_add_uint "$_sum" "$_bytes")"
	done < "$_f"
	printf '%s\n' "$_sum"
}

_remote_stream_fast_after_size_from_maps() {
	local _before="$1" _uploaded="$2" _tmp _rc
	if [[ -s $_before && -s $_uploaded ]]; then
		_tmp="$(_webdav_tmp_path remote_size_map_after_${$}_$RANDOM)"
		: > "$_tmp" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} || { echo 0; return 1; }
		# r308: let awk only merge per-relative-path rows; perform large integer sum with decimal shell addition and decimal gates.
		awk -F '\t' 'FNR==NR { if ($1!="" && $2 ~ /^[0-9]+$/) m[$1]=$2; next } { if ($1!="" && $2 ~ /^[0-9]+$/) m[$1]=$2 } END { for (k in m) print k "\t" m[k] }' "$_before" "$_uploaded" > "$_tmp" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
		_rc=$?
		if [[ $_rc -eq 0 && -s $_tmp ]]; then
			_remote_size_map_sum_file "$_tmp"
			_rc=$?
		else
			echo 0
			_rc=1
		fi
		rm -f "$_tmp" 2>/dev/null
		return $_rc
	elif [[ -s $_uploaded ]]; then
		_remote_size_map_sum_file "$_uploaded"
	else
		echo 0
		return 1
	fi
}

_remote_webdav_known_missing() {
	local _rel="$1"
	[[ $remote_type = webdav ]] || return 1
	[[ -f $TMPDIR/.remote_files && -f $TMPDIR/.remote_webdav_last_list_ok ]] || return 1
	awk -v r="$_rel" '$0==r{f=1;exit} END{exit f?0:1}' "$TMPDIR/.remote_files" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} && return 1
	return 0
}

# 從遠端下載單個文件 (用於備份前對比 app_details.json)
# 用法: remote_download_single_file <遠端相對路徑> <本地目標路徑>
# 回傳: 0=成功, 1=失敗
remote_download_single_file() {
	local remote_rel="$1" local_dest="$2"
	[[ -z $remote_type || -z $remote_url ]] && return 1
	if _remote_netwatch_mark_remote_fatal "single_download_enter" "$remote_rel"; then
		_speed_debug_log "REMOTE_DOWNLOAD_SINGLE_SKIP reason=remote_netwatch_changed rel=$remote_rel"
		rm -f "$local_dest" 2>/dev/null
		return 1
	fi
	local backup_subdir="${_BACKUP_DIRNAME_CACHED:-$(get_backup_dirname)}"
	case $remote_type in
	webdav)
		local base_url="${remote_url%/}"
		local target_rel="$backup_subdir/$remote_rel"
		if _remote_webdav_known_missing "$remote_rel"; then
			_speed_debug_log "WEBDAV_SINGLE_GET_SKIP_KNOWN_MISSING rel=$remote_rel source=remote_files"
			rm -f "$local_dest" 2>/dev/null
			return 1
		fi
		local _tmp="${local_dest}.part.$$.$RANDOM" _err="$TMPDIR/.wdav_get_err_$$_$RANDOM" _rc _bytes _get_start_ms _get_elapsed_ms _get_speed
		# v24.20.14-7.66-16: 暫存錯誤檔可能已被其他清理流程移除；不要讓 rm 噪音污染 stderr.log。
		rm -f "$local_dest" "$_tmp" "$_err" 2>/dev/null
		if _remote_netwatch_mark_remote_fatal "single_download_webdav_before_get" "$remote_rel"; then
			rm -f "$_tmp" "$_err" "$local_dest" 2>/dev/null
			return 1
		fi
		_get_start_ms="$(_speed_now_ms)"
		_webdav_dex getrel "$remote_user" "$remote_pass" "$base_url" "$target_rel" "$_tmp" 2>"$_err"
		_rc=$?
		if [[ $_rc != 0 && ${_WEBDAV_HTTP_CODE:-0} != 404 ]]; then
			_remote_netwatch_mark_remote_fatal "single_download_webdav_get_fail" "$remote_rel" >/dev/null 2>&1 || true
		elif [[ $_rc != 0 && ${_WEBDAV_HTTP_CODE:-0} = 404 ]]; then
			_speed_debug_log "WEBDAV_SINGLE_GET_REMOTE_MISSING rel=$remote_rel http=404 mode=r377"
		fi
		_get_elapsed_ms=$(( $(_speed_now_ms) - _get_start_ms ))
		[[ $_get_elapsed_ms -le 0 ]] && _get_elapsed_ms=1
		_bytes="$(_local_file_size_debug "$_tmp")"
		_get_speed="$(_webdav_speed_mib_s "$_bytes" "$_get_elapsed_ms")"
		remote_raw_log "remote_download_raw.log" "WEBDAV_SINGLE_GET rc=$_rc bytes=${_bytes:-0} elapsedMs=$_get_elapsed_ms speedMiBps=$_get_speed rel=$target_rel base=$base_url"
		remote_raw_cat "remote_download_raw.log" "$_err" "[WEBDAV_SINGLE_GET stderr rel=$remote_rel rc=$_rc]"
		if [[ $_rc = 0 && -s $_tmp ]]; then
			mv "$_tmp" "$local_dest" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
			rm -f "$_err" 2>/dev/null
			return 0
		fi
		_speed_debug_log "WEBDAV_SINGLE_GET_DROP rel=$remote_rel rc=$_rc bytes=${_bytes:-0}"
		rm -f "$_tmp" "$_err" "$local_dest" 2>/dev/null
		return 1
		;;
	smb)
		remote_parse_smb_url
		local share="$SMB_SHARE"
		local rem_path="$SMB_REM_PATH"
		local base="${rem_path:+$rem_path/}$backup_subdir"
		local dir_part="${remote_rel%/*}"
		local file_part="${remote_rel##*/}"
		local smb_dest="$(mktemp -d "$TMPDIR/.smb_dl_XXXXXX" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null})"
		[[ -z $smb_dest ]] && smb_dest="$TMPDIR/.smb_dl_$$_$RANDOM"
		mkdir -p "$smb_dest" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
		if ! _smb_safe_component "$file_part" || ! _smb_safe_component "$smb_dest"; then
			echoRgb "偵測到不安全的檔名字元, 拒絕執行 smbclient 下載: $file_part" "0" >&2
			return 1
		fi
		local _smb_auth_args _smb_single_rc
		_smb_auth_args="$(_smb_auth_args_current)" || return 1
		if _remote_netwatch_mark_remote_fatal "single_download_smb_before_get" "$remote_rel"; then
			rm -rf "$smb_dest" "$local_dest" 2>/dev/null
			return 1
		fi
		smbclient "$share" $_smb_auth_args -t 10 -s $(_smb_client_conf) \
			-D "$base/$dir_part" \
			-c "lcd $smb_dest; get $file_part; exit" >/dev/null 2>&1
		_smb_single_rc=$?
		if [[ $_smb_single_rc != 0 ]]; then
			_remote_netwatch_mark_remote_fatal "single_download_smb_get_fail" "$remote_rel" >/dev/null 2>&1 || true
		fi
		if [[ -f "$smb_dest/$file_part" ]]; then
			mv "$smb_dest/$file_part" "$local_dest"
			rm -rf "$smb_dest"
			return 0
		else
			rm -rf "$smb_dest"
			return 1
		fi
		;;
	*)
		return 1
		;;
	esac
}

# 過濾 smbclient 輸出的雜訊行 (Try help / dos charset / OS= 等橫幅文字)
# 用法: smb_filter_noise <輸入字串>
smb_filter_noise() {
	echo "$1" | grep -Ev '^Try "help"|^dos charset|^Can.t load|^Domain=|^OS=|^directory_create_or_exist:|^$'
}

# 解析 smbclient -g -L 輸出，回傳第一個可用 Disk share 名稱。
# 純 -g 模式：只接受 Samba grepable share 格式 Disk|share|comment；不再解析普通 -L 表格。
_smb_parse_share_grepable() {
	awk -F'|' '
		function trim(s){gsub(/^[[:space:]]+|[[:space:]]+$/, "", s); return s}
		$1=="Disk" {
			n=trim($2)
			if (n!="" && n !~ /\$$/) { print n; exit }
		}
	'
}

# 解析 smbclient -g ls，輸出：ATTR<TAB>SIZE<TAB>REL_PATH
# 純 -g 命令模式：所有呼叫端都必須使用 smbclient -g。
# 注意：Samba 4.24.4 的「-g ls」實測仍可能輸出表格行，而不是 pipe 行；
# 這裡只把它視為 -g ls 的實際格式，不再提供「不帶 -g 重跑 / 普通 -L」兼容路徑。
# 支援的 -g ls 實測格式：
#   name|ATTR|SIZE|...
#   ATTR|name|SIZE|...
#   name|SIZE|ATTR|...
#   name  ATTR  SIZE  Week Mon Day Time Year   （4.24.4 -g ls 實測表格）
_smb_parse_ls_entries() {
	local _pref="${1:-}"
	awk -v pref="$_pref" '
		function trim(s){gsub(/^[[:space:]]+|[[:space:]]+$/, "", s); return s}
		function norm(s){gsub(/\\/, "/", s); gsub(/\/+/, "/", s); sub(/^\/+/, "", s); sub(/\/+$/, "", s); return s}
		function is_attr(s){return (s ~ /^[A-Za-z]+$/ && s ~ /[ADNHSR]/)}
		function emit(name, attr, sz, full, rel){
			name=trim(name); attr=trim(attr); sz=trim(sz)
			if (name=="" || name=="." || name=="..") return
			if (attr=="" || sz !~ /^[0-9]+$/) sz=0
			name=norm(name)
			if (name=="" || name=="." || name=="..") return
			if (dir!="" && index(name, dir"/")!=1) full=dir"/"name; else full=name
			full=norm(full)
			if (p!="") {
				if (full==p) return
				if (index(full,p"/")==1) rel=substr(full,length(p)+2)
				else rel=full
			} else rel=full
			rel=norm(rel)
			if (rel=="" || rel=="." || rel=="..") return
			print attr "\t" sz "\t" rel
		}
		BEGIN{p=norm(pref); dir=""}
		/^Try "help"/ || /^dos charset/ || /^Can.t load/ || /^WARNING:/ || /^Domain=/ || /^OS=/ || /^directory_create_or_exist:/ || /^$/ { next }
		/^[[:space:]]*[0-9]+[[:space:]]+blocks[[:space:]]+of[[:space:]]+size[[:space:]]+[0-9]+/ { next }
		/^\\/ { dir=norm($0); next }
		index($0,"|")>0 {
			n=split($0,a,"|"); for(i=1;i<=n;i++) a[i]=trim(a[i])
			if (a[1]=="Disk" || a[1]=="IPC" || a[1]=="Printer") next
			if (n>=3 && is_attr(a[2]) && a[3] ~ /^[0-9]+$/) { emit(a[1],a[2],a[3]); next }
			if (n>=3 && is_attr(a[1]) && a[3] ~ /^[0-9]+$/) { emit(a[2],a[1],a[3]); next }
			if (n>=3 && is_attr(a[3]) && a[2] ~ /^[0-9]+$/) { emit(a[1],a[3],a[2]); next }
			next
		}
		{
			# Samba 4.24.4 smbclient -g ls 實測仍輸出表格：檔名 ATTR SIZE 日期...
			# 檔名可含空白，因此找第一個 attr 欄位，下一欄必須是 size。
			for (i=2; i<=NF; i++) {
				if (is_attr($i) && $(i+1) ~ /^[0-9]+$/) {
					name=$1
					for (j=2; j<i; j++) name=name" "$j
					emit(name,$i,$(i+1)); break
				}
			}
		}
	'
}

# 判斷目錄是否含任何檔案 (非空)
# 用法: dir_has_files <目錄路徑>
# 回傳: 0=有檔案, 1=空目錄或不存在
dir_has_files() {
	[[ -d $1 ]] || return 1
	_speedscan_has_files "$1" && return 0
	[[ -n $(find "$1" -type f -print -quit 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}) ]]
}

# 啟動時的遠端設定初始化
# 規範化 remote_keep_local 值, 驗證 remote_type, TCP 預檢
# 失敗時清空 remote_type 停用上傳但保留本地備份
remote_setup() {
	# 若之前連線失敗清空了 remote_type, 用原始值恢復以重新檢測 (支援中途開 WiFi 後重試)
	[[ -z $remote_type && -n $_remote_type_orig ]] && remote_type="$_remote_type_orig"
	# 純本機模式：只做 runtime 關閉，不反寫 conf；使用者原 remote_stream/remote_upload_per_app 保留。
	if [[ -z $remote_type ]]; then
		remote_stream=0
		remote_upload_per_app=0
		return 0
	fi
	# 規範化 remote_keep_local 成 true/false
	case $remote_keep_local in
	1|true|True|TRUE) remote_keep_local=true ;;
	*) remote_keep_local=false ;;
	esac
	echoRgb "遠程備份: $remote_type -> $remote_url" "3"
	case $remote_type in
	webdav|smb)
		;;
	*) echoRgb "未知遠程類型: $remote_type (可選: webdav/smb)" "0"; remote_type=""; return 1 ;;
	esac
	[[ -z $remote_url ]] && { echoRgb "遠端位址未設置 (請設 smb_url 或 webdav_url)，停用遠端上傳" "0"; remote_type=""; return 1; }
	# conf 防呆: 檢查 URL 格式跟協議匹配
	case $remote_type in
	webdav)
		case $remote_url in
		http://*|https://*) ;;
		smb://*)
			echoRgb "remote_type=webdav 但 remote_url 是 smb:// 開頭" "0"
			echoRgb "請改成 http:// 或 https:// 開頭, 或把 remote_type 改成 smb" "3"
			remote_type=""; return 1 ;;
		*)
			echoRgb "remote_url 必須以 http:// 或 https:// 開頭" "0"
			echoRgb "目前: $remote_url" "0"
			remote_type=""; return 1 ;;
		esac
		;;
	smb)
		case $remote_url in
		smb://*) ;;
		http://*|https://*)
			echoRgb "remote_type=smb 但 remote_url 是 http(s):// 開頭" "0"
			echoRgb "請改成 smb:// 開頭, 或把 remote_type 改成 webdav" "3"
			remote_type=""; return 1 ;;
		"")
			# 未填地址: 自動掃描區網 SMB 並填入第一台的第一個共享
			echoRgb "remote_url 未填, 自動掃描區網 SMB..." "3"
			if smb_autodetect_url; then
				echoRgb "自動填入: $remote_url" "1"
			else
				echoRgb "自動掃描未找到可用 SMB, 請手動填 remote_url" "0"
				remote_type=""; return 1
			fi
			;;
		*)
			echoRgb "remote_url 必須以 smb:// 開頭" "0"
			echoRgb "目前: $remote_url" "0"
			remote_type=""; return 1 ;;
		esac
		;;
	esac
	# 帳密為空提醒 (非致命, 可能是匿名認證)
	[[ -z $remote_user ]] && echoRgb "remote_user 未設定 (將以匿名嘗試連線)" "0"
	# 事前連線測試: 從各協議解出 host:port 做快速 TCP 探測
	remote_parse_endpoint
	# 流式模式需要 SMB_SHARE/SMB_REM_PATH (平時在 upload 函數才解析, 流式不走那裡, 故這裡先解析)
	[[ $remote_stream = 1 && $remote_type = smb ]] && remote_parse_smb_url
	# 端口跟協議不一致警告 (常見錯誤: https 配 80 或 http 配 443)
	if [[ $remote_type = webdav ]]; then
		case "$remote_url:$REMOTE_PORT" in
		https://*:80)
			echoRgb "警告: HTTPS 通常用 443, 你設 80 (可能應改用 http://)" "0" ;;
		http://*:443)
			echoRgb "警告: HTTP 通常用 80, 你設 443 (可能應改用 https://)" "0" ;;
		esac
	fi
	if remote_precheck "$REMOTE_HOST" "$REMOTE_PORT"; then
		echoRgb "遠端連線測試通過 ($REMOTE_HOST:$REMOTE_PORT)" "1"
		if [[ $remote_type = webdav ]]; then
			if ! _webdav_base_path_preflight_autocreate "${remote_url%/}" control; then
				echoRgb "WebDAV 遠端基礎資料夾預檢失敗，已停用遠端上傳" "0"
				_webdav_print_reason 0
				if [[ $remote_stream = 1 ]]; then
					_speed_debug_normal_finish_pack 1
					exit 1
				fi
				remote_type=""
				return 1
			fi
			if _webdav_options_preflight "${remote_url%/}" "" control; then
				echoRgb "WebDAV OPTIONS 能力預檢通過" "1"
			else
				echoRgb "WebDAV OPTIONS 能力預檢失敗，已停用遠端上傳" "0"
				_webdav_print_reason 0
				if [[ $remote_stream = 1 ]]; then
					_speed_debug_normal_finish_pack 1
					exit 1
				fi
				remote_type=""
				return 1
			fi
		fi
		_remote_netwatch_start
		if [[ $remote_stream = 1 ]]; then
			echoRgb "流式上傳模式 (邊壓邊傳, 不佔本機空間)" "3"
			# WebDAV 流式只允許 dex putstdinchunkedrel：stdin 直接轉 HTTP chunked PUT，不在本機落地整包暫存。
			# 若伺服器不支援 chunked PUT，直接退出；remote_stream=1 的語意就是「真流式」。
			if [[ $remote_type = webdav ]]; then
				WEBDAV_STREAM_UPLOAD_CMD=putstdinmanagedrel
				local _stream_probe_rel="${_BACKUP_DIRNAME_CACHED:-$(get_backup_dirname)}"
				local _stream_probe_mk_err="$TMPDIR/.webdav_stream_probe_mkdir_$$" _stream_probe_mk_rc _stream_probe_mk_http
				if _webdav_options_preflight "${remote_url%/}" "" stream; then
					_webdav_mkdirrel_cached "$remote_user" "$remote_pass" "${remote_url%/}" "$_stream_probe_rel" "$_stream_probe_mk_err"
					_stream_probe_mk_rc=$?
					_stream_probe_mk_http="${_WEBDAV_HTTP_CODE:-0}"
					remote_raw_log "remote_webdav_stream_probe_raw.log" "PROBE_MKDIR rel=$_stream_probe_rel rc=$_stream_probe_mk_rc http=$_stream_probe_mk_http base=${remote_url%/}"
					remote_raw_cat "remote_webdav_stream_probe_raw.log" "$_stream_probe_mk_err" "[probe mkdir stderr rel=$_stream_probe_rel]"
					rm -f "$_stream_probe_mk_err" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
				else
					_stream_probe_mk_rc=1
				fi
				if [[ ${_stream_probe_mk_rc:-1} = 0 ]] && _webdav_atomic_capability_probe "${remote_url%/}" "$_stream_probe_rel"; then
					echoRgb "WebDAV Dex managed 真流式可用 (direct/atomic 由 Dex 決策，不佔本機整包暫存)" "1"
				else
					_probe_http="${_WEBDAV_HTTP_CODE:-0}"
					if [[ ${_probe_http:-0} = 0 ]]; then
						echoRgb "WebDAV Dex/daemon 原子真流式探測失敗：未取得有效 HTTP 回應" "0"
						echoRgb "請先檢查 classes.dex、WebDavUtil daemon、unixsock relay 與 WebDAV 伺服器" "3"
					else
						echoRgb "WebDAV Dex managed 真流式探測失敗 (HTTP $_probe_http)，已停止；remote_stream=1 不允許回退到本機暫存上傳" "0"
						echoRgb "需要伺服器支援 MKCOL/PUT 與必要的 MOVE/STAT；可改用 SMB 流式或設 remote_stream=0" "3"
					fi
					_speed_debug_normal_finish_pack 1
					exit 1
				fi
			fi
		elif [[ $remote_keep_local = true ]]; then
			echoRgb "備份完成後將自動上傳到遠端 (保留本地檔案)" "3"
		else
			echoRgb "備份完成後將自動上傳到遠端 (上傳成功後刪除本地檔案)" "3"
		fi
	else
		if [[ $remote_stream = 1 ]]; then
			echoRgb "真流式上傳不可用：遠端不可連線 ($REMOTE_HOST:$REMOTE_PORT)，已終止" "0"
			_remote_precheck_print_smb_issue
			echoRgb "remote_stream=1 不允許回退成本地備份；請開啟遠端伺服器、修正網路，或設 remote_stream=0" "3"
			echoRgb "詳情已寫入 speed_debug 包內: remote_precheck.log" "3"
			_speed_debug_normal_finish_pack 1
			exit 1
		fi
		echoRgb "遠端不可連線，已停用遠端上傳並保留本地備份 ($REMOTE_HOST:$REMOTE_PORT)" "2"
			_remote_precheck_print_smb_issue
		echoRgb "詳情已寫入 speed_debug 包內: remote_precheck.log" "3"
		remote_type=""
	fi
}

# 獨立的測試遠端入口 (給選單用)
# 1. 顯示 conf 設定
# 2. TCP 預檢
# 3. 嘗試認證 + list 遠端目錄
# 不會實際上傳任何東西
# 單獨上傳某個 app 的備份 (給子目錄 upload.sh 用)
# 假設呼叫時 Backup 是備份根目錄 (Backup_zstd_X)
# $1 = app 名 (子目錄名)
single_upload() {
	local app_name="$1"
	[[ -z $app_name ]] && { echoRgb "single_upload: 缺少 app 名" "0"; return 1; }
	[[ -z $Backup ]] && Backup="$MODDIR"
	local target="$Backup/$app_name"
	[[ ! -d $target ]] && { echoRgb "找不到目錄: $target" "0"; return 1; }
	dir_has_files "$target" || { echoRgb "$app_name 目錄為空,沒有東西可上傳" "0"; return 1; }
	# 重置範圍 flag, 只標記這一個
	unset REMOTE_APPLIST REMOTE_UPLOAD_MEDIA REMOTE_UPLOAD_WIFI
	case $app_name in
	Media) REMOTE_UPLOAD_MEDIA=1 ;;
	wifi) REMOTE_UPLOAD_WIFI=1 ;;
	*) REMOTE_APPLIST="$app_name" ;;
	esac
	REMOTE_TRIGGER=1
	# 啟動時 remote_setup 已跑過, 這裡只檢查狀態
	[[ -z $remote_type ]] && { echoRgb "遠端未設定或預檢失敗,終止" "0"; unset REMOTE_UPLOAD_CURRENT_BUNDLE_ONLY; return 1; }
	echoRgb "—————— 單獨上傳: $app_name ——————" "3"
	case $remote_type in
	smb) upload_smb ;;
	webdav) upload_remote "webdav" ;;
	esac
	# 已主動上傳, 清旗標避免 trap EXIT 再跑一次
	unset REMOTE_TRIGGER REMOTE_UPLOAD_CURRENT_BUNDLE_ONLY
}

# 邊備份邊上傳：每備份完一個應用後立即上傳並刪除本機檔案
# $1 = 應用名 (目錄名)
# 依賴 global: remote_type, remote_keep_local, Backup
per_app_upload_and_cleanup() {
	local app_name="$1"
	[[ -z $app_name ]] && return 1
	[[ -z $Backup ]] && return 1
	local target="$Backup/$app_name"
	[[ ! -d $target ]] && return 0
	dir_has_files "$target" || return 0
	[[ -z $remote_type ]] && return 1
	# 合併遠端 app_details.json 到本地，避免丢失遠端已有的字段
	local local_app_details="$target/app_details.json"
	local remote_app_details="$TMPDIR/.remote_app_details_merge_$$"
	local remote_rel="${app_name}/app_details.json"
	if [[ -f $local_app_details ]] && remote_download_single_file "$remote_rel" "$remote_app_details" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}; then
		[[ -s $remote_app_details ]] && {
			# 合併遠端數據到本地（本地數據優先，但保留遠端已有的字段）
			local merged="$TMPDIR/.merged_app_details_$$"
			if _appdetails_merge_old_new_jq "$remote_app_details" "$local_app_details" "$merged" && [[ -s $merged ]]; then
				cat "$merged" > "$local_app_details"
			fi
			rm -f "$merged"
		}
	fi
	rm -f "$remote_app_details"
	# 設定上傳範圍：只上傳這一個 app, 跳過 tools/ 等固定項避免重複上傳
	# REMOTE_APPDETAILS_FILE: 主體上傳完成後，若無失敗則由上傳函數自動處理
	unset REMOTE_APPLIST REMOTE_UPLOAD_MEDIA REMOTE_UPLOAD_WIFI
	REMOTE_APPLIST="$app_name"
	REMOTE_SKIP_FIXED=1
	REMOTE_APPDETAILS_SKIP=1
	REMOTE_QUIET=1
	REMOTE_TRIGGER=1
	REMOTE_APPDETAILS_FILE="$Backup/$app_name/app_details.json"
	local _upload_rc=0
	case $remote_type in
	smb) upload_smb; _upload_rc=$? ;;
	webdav) upload_remote "webdav"; _upload_rc=$? ;;
	esac
	# 清除標記
	unset REMOTE_TRIGGER REMOTE_SKIP_FIXED REMOTE_APPLIST REMOTE_APPDETAILS_SKIP REMOTE_QUIET REMOTE_APPDETAILS_FILE
	return $_upload_rc
}

# 主選單觸發: 讀 appList.txt + Custom_path, 直接上傳對應目錄
# 不互動,等同於跑完整備份後的自動上傳,但不重新備份
upload_current_backup() {
	backup_path
	[[ ! -d $Backup ]] && { echoRgb "本地備份目錄不存在: $Backup" "0"; return 1; }
	echoRgb "本地備份: $Backup" "2"
	show_conf remote
	# remote_setup 連線失敗或未設定時會清空 remote_type → 直接終止, 不再詢問
	# 用 remote_url 區分: 有設 URL 但 type 被清空 = 連線失敗; 沒設 URL = 未設定
	if [[ -z $remote_type ]]; then
		if [[ -n $remote_url ]]; then
			echoRgb "遠端連線失敗 (請檢查 WiFi/伺服器), 無法上傳" "0"
		else
			echoRgb "未設定遠端, 無法上傳" "0"
		fi
		return 1
	fi
	# r419: 功能7上傳當前備份前，先把各目錄 app_details.json 彙總成根層 bundle。
	# 上傳清單隨後會過濾逐 App JSON，只保留 app_details_bundle.tar.zst。
	REMOTE_UPLOAD_CURRENT_BUNDLE_ONLY=1
	if ! _appdetails_bundle_build_local_for_current_upload "$Backup"; then
		unset REMOTE_UPLOAD_CURRENT_BUNDLE_ONLY
		return 1
	fi
	# 選擇上傳模式: 1=按清單(appList) 2=整個目錄
	unset REMOTE_FULL_DIR
	unset _up_mode
	if ! ask_yn "上傳模式" "按清單上傳" "上傳整個Backup目錄"; then
		REMOTE_FULL_DIR=1
	fi
	if [[ $REMOTE_FULL_DIR = 1 ]]; then
		echoRgb "已選擇: 上傳整個 Backup 目錄 (排除 log)" "2"
	else
		# 讀 appList.txt (跟備份用同一個解析邏輯)
		local applist=""
		if [[ -n $list_location ]]; then
			if [[ ${list_location:0:1} = / ]]; then
				[[ -f $list_location ]] && applist="$list_location"
			else
				[[ -f $MODDIR/$list_location ]] && applist="$MODDIR/$list_location"
			fi
		fi
		[[ -z $applist && -f $MODDIR/appList.txt ]] && applist="$MODDIR/appList.txt"
		# 組裝 REMOTE_APPLIST (跟 backup() 用同一個變數,讓 collect_targets 認得)
		unset REMOTE_APPLIST REMOTE_UPLOAD_MEDIA REMOTE_UPLOAD_WIFI
		if [[ -n $applist ]]; then
			REMOTE_APPLIST="$(cat "$applist")"
			local app_count
			app_count=$(echo "$REMOTE_APPLIST" | grep -cEv '^[[:space:]]*[#＃!]|^[[:space:]]*$')
			echoRgb "讀取 $applist (有效 $app_count 個 app)" "2"
		else
			echoRgb "找不到 appList.txt" "0"
		fi
		# 讀 Custom_path: 有設就帶上 Media
		if [[ -n $Custom_path ]]; then
			if dir_has_files "$Backup/Media"; then
				REMOTE_UPLOAD_MEDIA=1
				echoRgb "Custom_path 已設, 將上傳 Media" "2"
			fi
		fi
		# wifi 目錄存在就一併上傳
		if dir_has_files "$Backup/wifi"; then
			REMOTE_UPLOAD_WIFI=1
			echoRgb "wifi 目錄存在, 將上傳 wifi" "2"
		fi
		if [[ -z $REMOTE_APPLIST && $REMOTE_UPLOAD_MEDIA != 1 && $REMOTE_UPLOAD_WIFI != 1 ]]; then
			echoRgb "沒有可上傳項目 (appList 為空, Custom_path 未設, 無 wifi)" "0"
			unset REMOTE_UPLOAD_CURRENT_BUNDLE_ONLY
			return 1
		fi
	fi
	# 上傳前統計大小並確認
	local _pre_list="$TMPDIR/.precheck_list" _pre_bytes
	remote_collect_targets "$_pre_list"
	if [[ ! -s $_pre_list ]]; then
		echoRgb "沒有可上傳的檔案" "0"; rm -f "$_pre_list" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}; unset REMOTE_UPLOAD_CURRENT_BUNDLE_ONLY; return 1
	fi
	local _pre_count="$(wc -l < "$_pre_list")"
	if [[ $REMOTE_FULL_DIR = 1 ]]; then
		# 全目錄模式: 用 du 算整個目錄 (跟備份時 Calculate_size 同源), 減去 log
		local _all _log
		# 純文件字節, 排除根目錄 log (整體 - log, 兩者同算法相減精確)
		local _all _log
		_all="$(calc_dir_size "$Backup")"
		_log="$(calc_dir_size "$Backup/log" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null})"
		_pre_bytes=$(awk -v a="${_all:-0}" -v l="${_log:-0}" 'BEGIN{print a-l}')
	else
		_pre_bytes="$(list_total_size "$_pre_list")"
	fi
	echoRgb "本次上傳: $_pre_count 個檔案, 總大小 $(size_with_bytes "$_pre_bytes")" "3"
	rm -f "$_pre_list" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	if ! ask_yn "確認上傳?" "確認上傳" "取消"; then
		echoRgb "已取消上傳" "1"; unset REMOTE_UPLOAD_CURRENT_BUNDLE_ONLY; return 0
	fi
	REMOTE_TRIGGER=1
	# 啟動時 remote_setup 已跑過, 這裡只檢查狀態
	[[ -z $remote_type ]] && { echoRgb "遠端未設定或預檢失敗,終止" "0"; return 1; }
	case $remote_type in
	smb) upload_smb ;;
	webdav) upload_remote "webdav" ;;
	esac
	# 已主動上傳, 清旗標避免 trap EXIT 再跑一次
	unset REMOTE_TRIGGER REMOTE_UPLOAD_CURRENT_BUNDLE_ONLY
}

# 測試遠端連線完整性 (主選單第 6 項)
# 三層測試: TCP 預檢 → 認證 → 路徑訪問
# 每層失敗都有具體錯誤訊息 (帳密錯/路徑不存在/分享不存在等)
remote_test() {
	echoRgb "============== 遠端連線測試 ==============" "3"
	show_conf remote
	if [[ -z $remote_type ]]; then
		_remote_type_missing_msg
		echoRgb "請編輯 $conf_path 設定 remote_type/remote_url/remote_user/remote_pass" "3"
		return 1
	fi
	echoRgb "類型: $remote_type" "2"
	echoRgb "位址: $remote_url" "2"
	echoRgb "帳號: ${remote_user:-(未設)}" "2"
	[[ -n $remote_pass ]] && echoRgb "密碼: ********" "2" || echoRgb "密碼: (未設)" "2"
	echoRgb "保留本地: ${remote_keep_local:-0}" "2"
	case $remote_type in
	webdav|smb) ;;
	*) echoRgb "未知 remote_type: $remote_type (可選: webdav/smb)" "0"; return 1 ;;
	esac
	[[ -z $remote_url ]] && { echoRgb "remote_url 未設置" "0"; return 1; }
	# 協議與 URL 一致性檢查
	case $remote_type in
	webdav)
		case $remote_url in
		http://*|https://*) ;;
		smb://*)
			echoRgb "remote_type=webdav 但 remote_url 是 smb:// 開頭" "0"
			echoRgb "請改 remote_type=smb, 或把 remote_url 改成 http(s)://" "3"
			return 1 ;;
		*://*)
			echoRgb "remote_url 協議 (${remote_url%%://*}://) 不被 webdav 支援" "0"
			echoRgb "WebDAV 只支援 http:// 或 https://" "3"
			return 1 ;;
		*)
			echoRgb "remote_url 必須以 http:// 或 https:// 開頭" "0"
			echoRgb "目前: $remote_url" "0"
			return 1 ;;
		esac ;;
	smb)
		case $remote_url in
		smb://*) ;;
		http://*|https://*)
			echoRgb "remote_type=smb 但 remote_url 是 http(s):// 開頭" "0"
			echoRgb "請改 remote_type=webdav, 或把 remote_url 改成 smb://" "3"
			return 1 ;;
		*://*)
			echoRgb "remote_url 協議 (${remote_url%%://*}://) 不被 smb 支援" "0"
			echoRgb "SMB 只支援 smb://" "3"
			return 1 ;;
		*)
			echoRgb "remote_url 必須以 smb:// 開頭" "0"
			echoRgb "目前: $remote_url" "0"
			return 1 ;;
		esac ;;
	esac
	# 遠端連線測試只測目前設定的 remote_url，不做整個區網 SMB 掃描。
	# SMB 掃描保留在「掃描 SMB」功能與 remote_type=smb 且 remote_url 空白的自動偵測流程。
	# 避免 WebDAV 測試也被 445/139 掃描拖慢。
	# 第一關: TCP 預檢
	remote_parse_endpoint
	echoRgb "—————— TCP 連線測試 ——————" "3"
	echoRgb "目標: $REMOTE_HOST:$REMOTE_PORT" "2"
	if remote_precheck "$REMOTE_HOST" "$REMOTE_PORT" manual; then
		echoRgb "TCP/SMB 目標連線通過" "1"
	else
		echoRgb "TCP 連線失敗" "0"
			_remote_precheck_print_smb_issue
		echoRgb "可能原因:" "0"
		echoRgb "WiFi 未開啟或不在同網段" "0"
		echoRgb "伺服器 IP / port 寫錯" "0"
		echoRgb "伺服器未啟動 / 防火牆阻擋" "0"
		return 1
	fi
	# 第二關: 認證 + 列目錄
	echoRgb "—————— 認證與列目錄測試 ——————" "3"
	case $remote_type in
	smb)
		remote_parse_smb_url
		local share="$SMB_SHARE"
		local rem_path="$SMB_REM_PATH"
		local out _smb_auth_args
		_smb_auth_args="$(_smb_auth_args_current)" || { _smb_auth_unavailable_msg "測試"; return 1; }
		out="$(smbclient -g "$share" $_smb_auth_args -t 10 -s $(_smb_client_conf)${REMOTE_PORT:+ -p $REMOTE_PORT} -m SMB3 \
			-c "cd ${rem_path:-/}; ls; exit" 2>&1)"
		out="$(smb_filter_noise "$out")"
		if echo "$out" | grep -qE 'NT_STATUS_LOGON_FAILURE'; then
			echoRgb "認證失敗 (帳號或密碼錯誤)" "0"
			return 1
		elif echo "$out" | grep -qE 'NT_STATUS_ACCESS_DENIED'; then
			echoRgb "存取被拒 (帳號權限不足)" "0"
			return 1
		elif echo "$out" | grep -qE 'NT_STATUS_BAD_NETWORK_NAME'; then
			echoRgb "share 名稱錯誤: $share (請檢查伺服器是否有此分享)" "0"
			return 1
		elif echo "$out" | grep -qE 'NT_STATUS_OBJECT_(PATH|NAME)_NOT_FOUND'; then
			echoRgb "遠端路徑不存在: $rem_path (將在首次上傳時建立)" "3"
		elif echo "$out" | grep -qE 'NT_STATUS_(CONNECTION_REFUSED|IO_TIMEOUT|HOST_UNREACHABLE)'; then
			echoRgb "網路不通 (伺服器無回應)" "0"
			return 1
		elif echo "$out" | grep -qE 'NT_STATUS_UNSUCCESSFUL'; then
			echoRgb "SMB 連線失敗 (NT_STATUS_UNSUCCESSFUL)" "0"
			echoRgb "常見原因: 端口錯誤 / SMB 協議版本不相容 / 伺服器拒絕" "3"
			return 1
		elif echo "$out" | grep -qE 'NT_STATUS|ERRSRV'; then
			echoRgb "SMB 錯誤:" "0"
			echo "$out" | head -5
			return 1
		else
			echoRgb "認證通過, share 可存取" "1"
			echoRgb "遠端路徑 $remote_url 可存取" "1"
			# 抓 SMB 協議版本：先解析 smbclient debug；解析不到時以 min=max 逐一強制 dialect，找最高可用版本。
			_smb_detect_protocol_version "$share" "$_smb_auth_args" "$rem_path" || true
		fi
		;;
	webdav)
		local base_url="${remote_url%/}"
		local code webdav_err _test_out
		# WEB-R3: 測試入口改走 OPTIONS + statrel/listrel，對齊新 WebDavUtil 能力層。
		_webdav_options_preflight "$base_url" "" control >/dev/null 2>"$TMPDIR/.webdav_test_err"
		code="$_WEBDAV_HTTP_CODE"
		if [[ $code = 2* ]]; then
			_webdav_status_sidecar_reset
			_test_out="$(_webdav_dex listrel "$remote_user" "$remote_pass" "$base_url" "." 0 2>>"$TMPDIR/.webdav_test_err")"
			_webdav_status_sidecar_load || true
			code="$_WEBDAV_HTTP_CODE"
		fi
		webdav_err="$(cat "$TMPDIR/.webdav_test_err" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null})"
		rm -f "$TMPDIR/.webdav_test_err"
		case $code in
		2*|207) echoRgb "WebDAV 認證通過 (HTTP $code)" "1" ;;
		401) echoRgb "認證失敗 (HTTP 401, 帳號或密碼錯誤)" "0"; return 1 ;;
		403) echoRgb "權限不足 (HTTP 403)" "0"; return 1 ;;
		404) echoRgb "路徑不存在 (HTTP 404)" "0"; return 1 ;;
		405) echoRgb "方法不允許 (HTTP 405, 此 URL 可能不是 WebDAV 端點)" "0"; return 1 ;;
		408) echoRgb "請求逾時 (HTTP 408, 伺服器繁忙)" "0"; return 1 ;;
		423) echoRgb "資源被鎖定 (HTTP 423, 有其他客戶端正在寫入)" "0"; return 1 ;;
		429) echoRgb "請求過於頻繁 (HTTP 429, 觸發伺服器限流)" "0"; return 1 ;;
		500) echoRgb "伺服器內部錯誤 (HTTP 500)" "0"; return 1 ;;
		502) echoRgb "閘道錯誤 (HTTP 502, 反向代理 / 上游服務有問題)" "0"; return 1 ;;
		503) echoRgb "服務不可用 (HTTP 503, 伺服器維護或過載)" "0"; return 1 ;;
		504) echoRgb "閘道逾時 (HTTP 504)" "0"; return 1 ;;
		3*) echoRgb "未處理的重定向 (HTTP $code，可能跳到非 WebDAV 端點)" "0"; return 1 ;;
		000)
			echoRgb "dex WebDavUtil 無法完成請求" "0"
			_webdav_print_reason 0
			[[ -n $webdav_err ]] && echoRgb "詳細: $webdav_err" "0"
			return 1 ;;
		*)   echoRgb "WebDAV 異常 (HTTP $code)" "0"
			_webdav_print_reason 0
			[[ -n $webdav_err ]] && echoRgb "詳細: $webdav_err" "0"
			return 1 ;;
		esac
		;;
	esac
	echoRgb "========================================" "3"
	echoRgb "全部測試通過, 可以開始備份" "1"
	return 0
}

# 功能 6 入口：保留原本「測試目前遠端連線」，並把區網 SMB 併發掃描接回來。
# 掃描使用既有 scan_smb() / _smb_scan_hosts()：優先 dex 併發 socket，fallback nc 並發。
remote_test_menu() {
	local _old_remote_type="$remote_type" _old_remote_url="$remote_url" _old_remote_user="$remote_user" _old_remote_pass="$remote_pass"
	local _old_smb_url="${smb_url:-}" _choice
	while true; do
		echoRgb "============== 遠端連線 / SMB 掃描 ==============" "3"
		echo " -1) 測試目前遠端連線"
		echo " -2) 掃描區網全部 SMB 主機"
		echo " -3) 掃描 SMB 並臨時套用第一個可用共享後測試"
		echo " -0) 返回"
		echo -n " -請輸入選項編號: "
		if ! read _choice; then
			# 若主選單因 background_execution=1 用 subshell/背景執行，stdin 可能在子選單變成 EOF；
			# 這裡嘗試從實際終端讀取，避免直接跳回「測試目前遠端連線」。
			if [[ -r /dev/tty ]]; then
				IFS= read -r _choice < /dev/tty || _choice=""
			fi
			if [[ -z $_choice ]]; then
				echoRgb "無互動 stdin，改為測試目前遠端連線" "0"
				remote_test
				return $?
			fi
		fi
		case $_choice in
		1)
			remote_test
			return $?
			;;
		2)
			# 掃描 SMB 時使用 SMB 專用帳密；若未設帳密則走 guest/匿名。
			remote_user="${smb_remote_user:-}"
			remote_pass="${smb_remote_pass:-}"
			scan_smb
			_rc=$?
			remote_type="$_old_remote_type"; remote_url="$_old_remote_url"; remote_user="$_old_remote_user"; remote_pass="$_old_remote_pass"
			return $_rc
			;;
		3)
			remote_type="smb"
			remote_user="${smb_remote_user:-}"
			remote_pass="${smb_remote_pass:-}"
			remote_url="${smb_url:-}"
			if smb_autodetect_url; then
				smb_url="$remote_url"
				echoRgb "臨時套用 SMB 位址: $remote_url" "1"
				remote_test
				_rc=$?
			else
				echoRgb "未找到可用 SMB 共享" "0"
				_rc=1
			fi
			# 不自動寫入 backup_settings.conf；只是功能 6 診斷流程的臨時套用。
			remote_type="$_old_remote_type"; remote_url="$_old_remote_url"; remote_user="$_old_remote_user"; remote_pass="$_old_remote_pass"; smb_url="$_old_smb_url"
			return $_rc
			;;
		0)
			return 0
			;;
		*)
			echoRgb "輸入錯誤，請重新輸入有效的數字。" "0"
			;;
		esac
	done
}

_app_network_is_reserved_tar_payload() {
	# r349: appList_network.txt 只有 Media 自定義資料夾壓縮包可以裸列 *.tar/*.tar.zst。
	# app / metadata payload 若意外進入清單，不能被功能 8/10/11 當成 Media 項目讀取。
	local _n="$1"
	_n="${_n##*/}"
	case "$_n" in
	app_details_bundle.tar|app_details_bundle.tar.zst|app_details.tar|app_details.tar.zst|	apk.tar|apk.tar.zst|data.tar|data.tar.zst|user.tar|user.tar.zst|user_de.tar|user_de.tar.zst|	obb.tar|obb.tar.zst|hma.tar|hma.tar.zst|thanox.tar|thanox.tar.zst)
		return 0
		;;
	esac
	return 1
}

_app_network_is_media_payload() {
	local _n="$1"
	# Media 壓縮包在 appList_network.txt 只允許第一層檔名；帶 slash 的 app payload / 子路徑一律不是 Media。
	case "$_n" in */*) return 1 ;; esac
	_app_network_is_reserved_tar_payload "$_n" && return 1
	case "$_n" in
	*.tar|*.tar.zst) return 0 ;;
	esac
	return 1
}

_app_network_media_payload_list() {
	local _in="$1" _out="$2"
	[[ -n $_in && -n $_out ]] || return 1
	awk '
		function reserved(n) {
			return (n=="app_details_bundle.tar" || n=="app_details_bundle.tar.zst" || n=="app_details.tar" || n=="app_details.tar.zst" ||
				n=="apk.tar" || n=="apk.tar.zst" || n=="data.tar" || n=="data.tar.zst" ||
				n=="user.tar" || n=="user.tar.zst" || n=="user_de.tar" || n=="user_de.tar.zst" ||
				n=="obb.tar" || n=="obb.tar.zst" || n=="hma.tar" || n=="hma.tar.zst" ||
				n=="thanox.tar" || n=="thanox.tar.zst")
		}
		/^[[:space:]]*[#＃]/ || /^[[:space:]]*$/ { next }
		{
			line=$0
			sub(/^[[:space:]]+/, "", line)
			sub(/[[:space:]]+$/, "", line)
			base=line
			sub(/^.*\//, "", base)
			if (line !~ /\// && line ~ /\.tar(\.zst)?$/ && !reserved(base)) print line
		}
	' "$_in" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} | sort -u > "$_out" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	[[ -s $_out ]]
}


_remote_list_payload_has_app() {
	# r351: app_details_bundle 缺失時，功能 8 不能只因 metadata 未 finalize 就整個中止。
	# 但也不能把 r345+ 批量預建立留下的空 App 目錄列出；必須確認該 App 目錄內至少有一個真 payload。
	local _file="$1" _app="$2"
	[[ -s $_file && -n $_app ]] || return 1
	awk -v app="$_app" '
		BEGIN { prefix = app "/" }
		index($0, prefix) == 1 {
			rel = substr($0, length(prefix) + 1)
			if (rel ~ /^(apk|data|user|user_de|obb|hma|thanox)\.tar(\.zst)?$/) { found=1; exit }
		}
		END { exit found ? 0 : 1 }
	' "$_file" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
}


_app_network_has_media_all_marker() {
	local _in="$1"
	[[ -s $_in ]] || return 1
	awk '
		/^[[:space:]]*[#＃]/ || /^[[:space:]]*$/ { next }
		{
			line=$0
			sub(/^[[:space:]]+/, "", line)
			sub(/[[:space:]]+$/, "", line)
			if (line == "Media") { found=1; exit }
		}
		END { exit found ? 0 : 1 }
	' "$_in" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
}


_app_network_media_payload_stem() {
	local _n="$1"
	case "$_n" in
	*.tar.zst) _n="${_n%.tar.zst}" ;;
	*.tar) _n="${_n%.tar}" ;;
	esac
	printf '%s\n' "$_n"
}

_app_network_media_json_keys_extract() {
	local _json="$1" _out="$2"
	[[ -s $_json && -n $_out ]] || return 1
	jq -r '
		to_entries[]
		| select(.key != "Backup time")
		| select(.key != "PackageName")
		| select(.key != "app_state")
		| select(.value|type == "object")
		| .key
	' "$_json" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} | sort -u > "$_out" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	[[ -s $_out ]]
}

_app_network_media_json_has_key() {
	local _keys="$1" _key="$2"
	[[ -s $_keys && -n $_key ]] || return 1
	awk -v k="$_key" '$0==k{f=1;exit} END{exit f?0:1}' "$_keys" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
}

_remote_media_appdetails_download_for_list() {
	local _target_dir="$1" _dest="$2"
	[[ -n $_target_dir && -n $_dest ]] || return 1
	rm -f "$_dest" 2>/dev/null
	case $remote_type in
	webdav)
		local _base_url="${remote_url%/}" _tmp="$_dest.part.$$.$RANDOM" _err="$TMPDIR/.media_appdetails_wdav_err_$$" _rc
		_webdav_dex getrel "$remote_user" "$remote_pass" "$_base_url" "$_target_dir/Media/app_details.json" "$_tmp" 2>"$_err"
		_rc=$?
		remote_raw_log "remote_download_raw.log" "WEBDAV_MEDIA_APPDETAILS_LIST_GET rc=$_rc rel=$_target_dir/Media/app_details.json"
		remote_raw_cat "remote_download_raw.log" "$_err" "[WEBDAV_MEDIA_APPDETAILS_LIST_GET stderr rc=$_rc]"
		rm -f "$_err" 2>/dev/null
		if [[ $_rc = 0 && -s $_tmp ]]; then
			mv "$_tmp" "$_dest" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
			return 0
		fi
		rm -f "$_tmp" "$_dest" 2>/dev/null
		return 1
		;;
	smb)
		remote_parse_smb_url
		local _share="$SMB_SHARE" _base="${SMB_REM_PATH:+$SMB_REM_PATH/}$_target_dir" _dl _out _auth _rc
		_dl="$(mktemp -d "$TMPDIR/.media_appdetails_smb_XXXXXX" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null})"
		[[ -z $_dl ]] && _dl="$TMPDIR/.media_appdetails_smb_$$_$RANDOM"
		mkdir -p "$_dl" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
		_auth="$(_smb_auth_args_current)" || { rm -rf "$_dl" 2>/dev/null; return 1; }
		_out=$(smbclient "$_share" $_auth -t 10 -s $(_smb_client_conf)${REMOTE_PORT:+ -p $REMOTE_PORT} -m SMB3 \
			-D "$_base/Media" \
			-c "lcd $_dl; prompt off; get app_details.json; exit" 2>&1)
		_rc=$?
		_out="$(smb_filter_noise "$_out")"
		remote_raw_log "remote_download_raw.log" "SMB_MEDIA_APPDETAILS_LIST_GET rc=$_rc base=$_base/Media dest=$_dest"
		printf '%s\n' "$_out" >> "${SPEED_DEBUG_RUN_DIR:-/data/speed_debug}/remote_download_raw.log" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
		if [[ $_rc = 0 && -s $_dl/app_details.json ]]; then
			mv "$_dl/app_details.json" "$_dest" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
			rm -rf "$_dl" 2>/dev/null
			return 0
		fi
		rm -rf "$_dl" "$_dest" 2>/dev/null
		return 1
		;;
	esac
	return 1
}

# r316: Media/app_details.json 是遠端 Media 清單與流式恢復的 key guard。
# 只備份 DCIM 時不能用本輪新 JSON 覆蓋掉遠端既有 Download/Pictures key，
# 否則功能8/流式恢復會只看見本輪備份的資料夾。
# 這裡在 Media staging 第一次建立時先種入遠端既有 JSON，再由本輪備份覆寫有變更的 entry。
_media_appdetails_seed_remote_if_stream() {
	local _dest="$1" _target_dir _tmp
	[[ $remote_stream = 1 && -n $remote_type && -n $_dest ]] || return 1
	if [[ -s $_dest ]] && _appdetails_json_parse_ok "$_dest"; then
		return 0
	fi
	_target_dir="$(get_backup_dirname)"
	_tmp="$_dest.remote_seed.$$.$RANDOM"
	rm -f "$_tmp" 2>/dev/null
	if _remote_media_appdetails_download_for_list "$_target_dir" "$_tmp" \
		&& [[ -s $_tmp ]] \
		&& _appdetails_json_parse_ok "$_tmp"; then
		mkdir -p "${_dest%/*}" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
		mv "$_tmp" "$_dest" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
		_speed_debug_log "MEDIA_APPDETAILS_REMOTE_SEED_OK rel=$_target_dir/Media/app_details.json dest=$_dest mode=r316-preserve-unselected"
		return 0
	fi
	rm -f "$_tmp" 2>/dev/null
	_speed_debug_log "MEDIA_APPDETAILS_REMOTE_SEED_SKIP rel=$_target_dir/Media/app_details.json dest=$_dest mode=r316-preserve-unselected"
	return 1
}

# 列出遠端可用的備份目錄並產生 appList_network.txt
# 流程: 連遠端 → 列 Backup_*_* 目錄 → 讓使用者選 → 檢查必要檔案 → 掃 app 清單 → 輸出
remote_list_backups() {
	show_conf remote
	[[ -z $remote_type ]] && { _remote_type_missing_msg; return 1; }
	case $remote_type in
	smb|webdav) ;;
	*) echoRgb "下載功能僅支援 smb / webdav (目前 remote_type=$remote_type)" "0"; return 1 ;;
	esac
	# 規範化 remote_keep_local
	case $remote_keep_local in
	1|true|True|TRUE) remote_keep_local=true ;;
	*) remote_keep_local=false ;;
	esac
	# 目標目錄 = 跟本地備份一樣的命名規則
	local target_dir="$(get_backup_dirname)"
	echoRgb "目標遠端目錄: $target_dir" "3"
	# 連線預檢
	remote_parse_endpoint
	if ! remote_precheck "$REMOTE_HOST" "$REMOTE_PORT"; then
		echoRgb "遠端連線失敗: $REMOTE_HOST:$REMOTE_PORT" "0"
			_remote_precheck_print_smb_issue
		return 1
	fi
	echoRgb "連線到 $remote_type://$REMOTE_HOST:$REMOTE_PORT" "1"
	# 進入目標目錄, 列出檔案/子資料夾
	local sub_listing="$TMPDIR/.remote_sub_listing"
	: > "$sub_listing"
	if [[ $remote_type = smb ]]; then
		remote_parse_smb_url
		local share="$SMB_SHARE"
		local rem_path="$SMB_REM_PATH"
		local smb_out
		local _smb_auth_args
		_smb_auth_args="$(_smb_auth_args_current)" || { _smb_auth_unavailable_msg "列出遠端"; return 1; }
		smb_out=$(smbclient -g "$share" $_smb_auth_args -t 10 -s $(_smb_client_conf)${REMOTE_PORT:+ -p $REMOTE_PORT} -m SMB3 \
			-c "cd ${rem_path:-/}/$target_dir; ls; exit" 2>&1)
		if echo "$smb_out" | grep -qE 'NT_STATUS_OBJECT_(PATH|NAME)_NOT_FOUND'; then
			echoRgb "遠端目錄不存在: $target_dir" "0"
			echoRgb "請確認遠端有此備份,或備份過至少一次" "3"
			rm -f "$sub_listing"
			return 1
		fi
		if echo "$smb_out" | grep -qE 'NT_STATUS|ERRSRV'; then
			echoRgb "讀取遠端失敗:" "0"
			echo "$smb_out" | grep -E 'NT_STATUS|ERR' | head -3
			rm -f "$sub_listing"
			return 1
		fi
		# 格式: "D dirname" 或 "N filename"；輸入固定來自 smbclient -g ls 的實測格式。
		{
			echo "===== SMB_LIST_BACKUPS stdout-g target=$target_dir ====="
			printf '%s\n' "$smb_out"
		} >> "${SPEED_DEBUG_RUN_DIR:-/data/speed_debug}/remote_smb_list_raw.log" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
		printf '%s\n' "$smb_out" | _smb_parse_ls_entries "" | awk -F'\t' '
			{
				name=$3
				# remote menu 只需要 target_dir 直下一層；遞迴項不在這裡處理。
				if (name=="" || name ~ /\//) next
				if (index($1,"D")>0) print "D " name; else print "N " name
			}' > "$sub_listing"
	elif [[ $remote_type = webdav ]]; then
		local base_url="${remote_url%/}"
		local http_code _wdav_err
		_wdav_err="$TMPDIR/.wdav_err_$$"
		: > "$TMPDIR/.wdav_out" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
		_webdav_dex listrel "$remote_user" "$remote_pass" "$base_url" "$target_dir" 1 > "$TMPDIR/.wdav_out" 2>"$_wdav_err"
		http_code="$_WEBDAV_HTTP_CODE"
		# debug: 把 list 結果(href/length)與 dex stderr 寫到 log 供除錯；不可污染 stderr.log。
		local dbg_log
		dbg_log="$(_speed_debug_log_path webdav_debug.log)"
		{
			echo "===== WebDAV list $(date '+%Y-%m-%d %H:%M:%S') ====="
			echo "Base: $base_url"
			echo "Rel: $target_dir"
			echo "HTTP code: $http_code"
			if [[ -s "$_wdav_err" ]]; then
				echo "----- dex stderr -----"
				cat "$_wdav_err" 2>/dev/null
			fi
			echo "----- href/length -----"
			[[ -f "$TMPDIR/.wdav_out" ]] && cat "$TMPDIR/.wdav_out" 2>/dev/null
			echo ""
			echo "----- End -----"
		} | while IFS= read -r _dbg_line; do _speed_debug_append_file "$dbg_log" "$_dbg_line"; done
		case $http_code in
		2*) ;;
		404)
			echoRgb "遠端目錄不存在: $target_dir (HTTP 404)" "0"
			echoRgb "請確認遠端有此備份,或備份過至少一次" "3"
			# 列根目錄看實際有什麼, 幫用戶確認路徑名
			local root_code root_xml="$TMPDIR/.wdav_root"
			local _root_err="$TMPDIR/.wdav_root_err_$$"
			_webdav_dex listrel "$remote_user" "$remote_pass" "$base_url" "." 1 > "$root_xml" 2>"$_root_err"
			root_code="$_WEBDAV_HTTP_CODE"
			{
				echo ""
				echo "----- 根目錄探測 listrel $base_url . -----"
				echo "HTTP code: $root_code"
				if [[ -s "$_root_err" ]]; then
					echo "----- root dex stderr -----"
					cat "$_root_err" 2>/dev/null
				fi
				[[ -f "$root_xml" ]] && cat "$root_xml" 2>/dev/null
				echo ""
			} | while IFS= read -r _dbg_line; do _speed_debug_append_file "$dbg_log" "$_dbg_line"; done
			case $root_code in
			2*)
				# 抓 href 列表給用戶看
				local found
				found=$(cat "$root_xml" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} | tr '><' '\n' | awk '
					/^(D:)?response$/ { in_resp=1; href="" }
					/^\/(D:)?response$/ { if (in_resp && href != "") print href; in_resp=0 }
					/^(D:)?href$/ { getline href }
				' | grep -v '^/$' | grep -v "^${base_url#http*://*/}$")
				if [[ -n $found ]]; then
					echoRgb "遠端根目錄實際有以下項目:" "3"
					echo "$found" | head -20
				fi
				;;
			esac
			rm -f "$root_xml" "$_root_err"
			echoRgb "原始回應已寫入 speed_debug 包內: webdav_debug.log" "3"
			rm -f "$sub_listing" "$TMPDIR/.wdav_out" "$_wdav_err"; return 1 ;;
		*) echoRgb "讀取遠端失敗 (HTTP $http_code)" "0"
			echoRgb "原始回應已寫入 speed_debug 包內: webdav_debug.log" "3"
			rm -f "$sub_listing" "$TMPDIR/.wdav_out" "$_wdav_err"; return 1 ;;
		esac
		local propfind_out
		propfind_out=$(cat "$TMPDIR/.wdav_out" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null})
		rm -f "$TMPDIR/.wdav_out" "$_wdav_err"
		# WebDavUtil no-ktor/daemon list 已輸出解析後的 TSV，不再是原始 XML：
		#   href<TAB>length<TAB>D/F
		# 舊 XML parser 會把已解析 TSV 全部吃空，導致遠端明明有檔案卻顯示「目錄為空」。
		# 這裡直接從 href 取 target_dir 下的一層子項，產生 remote_list_backups 後續使用的：
		#   D 資料夾名
		#   N 檔案名
		: > "$sub_listing"
		printf '%s\n' "$propfind_out" | awk -v target="$target_dir" -F'\t' '
			function trim_slash(s) { sub(/\/*$/, "", s); return s }
			NF >= 2 {
				h = $1
				kind = $3
				gsub(/\r$/, "", h)
				gsub(/\r$/, "", kind)
				if (h == "" || h ~ /^HTTP /) next
				is_dir = (kind == "D" || h ~ /\/$/)
				path = h
				sub(/\?.*$/, "", path)
				base1 = "/" target "/"
				base2 = target "/"
				idx = index(path, base1)
				if (idx > 0) {
					rel = substr(path, idx + length(base1))
				} else {
					idx = index(path, base2)
					if (idx == 0) next
					rel = substr(path, idx + length(base2))
				}
				rel = trim_slash(rel)
				if (rel == "" || rel == target) next
				# remote menu 只需要 target_dir 直下一層；遞迴項交給後續下載流程處理。
				if (rel ~ /\//) next
				print (is_dir ? "D" : "N") " " rel
			}
		' > "$sub_listing"

		# 保留舊 WebDAV 伺服器/舊 dex 若回傳 percent-encoded href 的解碼能力。
		local decoded="$TMPDIR/.decoded_listing"
		: > "$decoded"
		while read -r typ name; do
			[[ -z $name ]] && continue
			local converted real
			converted=$(echo "$name" | sed 's/%\([0-9a-fA-F][0-9a-fA-F]\)/\\x\1/g')
			real=$(printf '%b' "$converted")
			echo "$typ $real" >> "$decoded"
		done < "$sub_listing"
		mv "$decoded" "$sub_listing"
	fi
	if [[ ! -s $sub_listing ]]; then
		echoRgb "遠端目錄為空或讀取失敗" "0"
		# 列出 raw XML 跟解析後的結果到 log 方便除錯
		if [[ $remote_type = webdav && -f ${SPEED_DEBUG_RUN_DIR:-/data/speed_debug}/webdav_debug.log ]]; then
			{
				echo ""
				echo "----- Parsed listing (sub_listing) -----"
				[[ -f $sub_listing ]] && cat "$sub_listing"
				echo "(empty)"
			} >> "${SPEED_DEBUG_RUN_DIR:-/data/speed_debug}/webdav_debug.log"
			echoRgb "詳細回應已寫入 speed_debug 包內: webdav_debug.log" "3"
		fi
		rm -f "$sub_listing"
		return 1
	fi
	# r251: 遠端不再要求 tools/ 或 restore_settings.conf 存在；下載後使用本機 tools/ 補齊，restore_settings.conf 本地生成。
	_speed_debug_log "REMOTE_RESTORE_CONF_REQUIRE_SKIP dir=$target_dir reason=remote-conf-removed local-generate-on-download"
	# r351: app_details metadata bundle 是完整 restore 的主路徑，但功能 8 不應只因最後 metadata bundle 缺失就完全壞掉。
	# 斷線/伺服器中斷時，r345+ 可能已批量預建 App 目錄，甚至已有部分 payload，但 app_details_bundle.tar.zst 尚未 final upload。
	# 因此功能 8 允許降級為 payload fallback：深度掃描真 payload，過濾掉空目錄後產生 appList_network。
	local _appdetails_bundle_present=1 _payload_fallback_file="$TMPDIR/.remote_list_payload_fallback_files"
	: > "$_payload_fallback_file" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	local _appdetails_bundle_found_rel=""
	_appdetails_bundle_found_rel="$(awk -v b="$(_appdetails_bundle_rel)" -v lb="$(_appdetails_bundle_legacy_rel)" '$1=="N" && ($2==b || $2==lb) {print $2; exit}' "$sub_listing" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null})"
	if [[ -z $_appdetails_bundle_found_rel ]]; then
		_appdetails_bundle_present=0
		echoRgb "遠端缺少 app_details metadata bundle；將改用 payload 深度掃描產生清單（可能是不完整備份）" "0"
		_speed_debug_log "APPDETAILS_BUNDLE_REQUIRED_MISSING stage=remote_list_backups dir=$target_dir action=payload-fallback mode=r370"
		remote_list_files "$target_dir" > "$_payload_fallback_file" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} || true
		_speed_debug_log "REMOTE_LIST_PAYLOAD_FALLBACK_SCAN dir=$target_dir rows=$(grep -vc '^$' "$_payload_fallback_file" 2>/dev/null) mode=r370"
	else
		_speed_debug_log "APPDETAILS_BUNDLE_REQUIRED_OK stage=remote_list_backups dir=$target_dir rel=${_appdetails_bundle_found_rel:-$(_appdetails_bundle_rel)} canonical=$(_appdetails_bundle_rel) mode=r370"
		echoRgb "遠端根目錄檢查通過 (metadata bundle 可用；restore_settings.conf 本地生成)" "1"
	fi
	# r214: Media 清單必須同時滿足：遠端 Media/ 實際存在壓縮包，且 Media/app_details.json 有對應 key。
	local media_payloads="$TMPDIR/.remote_media_payloads"
	local media_payloads_raw="$TMPDIR/.remote_media_payloads_raw"
	local media_payloads_candidates="$TMPDIR/.remote_media_payloads_candidates"
	local media_json="$TMPDIR/.remote_media_app_details.json"
	local media_json_keys="$TMPDIR/.remote_media_app_details.keys"
	: > "$media_payloads" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	: > "$media_payloads_raw" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	: > "$media_payloads_candidates" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	: > "$media_json_keys" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	if awk '$1=="D" && $2=="Media" {f=1; exit} END{exit f?0:1}' "$sub_listing" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}; then
		remote_list_files "$target_dir/Media" > "$media_payloads_raw" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} || true
		awk '
			function reserved(n) {
				return (n=="app_details_bundle.tar" || n=="app_details_bundle.tar.zst" || n=="app_details.tar" || n=="app_details.tar.zst" ||
					n=="apk.tar" || n=="apk.tar.zst" || n=="data.tar" || n=="data.tar.zst" ||
					n=="user.tar" || n=="user.tar.zst" || n=="user_de.tar" || n=="user_de.tar.zst" ||
					n=="obb.tar" || n=="obb.tar.zst" || n=="hma.tar" || n=="hma.tar.zst" ||
					n=="thanox.tar" || n=="thanox.tar.zst")
			}
			{
				name=$0
				gsub(/\r$/, "", name)
				if (name == "") next
				# appList_network 只列 Media 第一層壓縮包；json/metadata/app payload 不列給使用者選。
				if (name ~ /\//) next
				if (name ~ /(^|\.)json$/) next
				if (name ~ /\.tar(\.zst)?$/ && !reserved(name)) print name
			}
		' "$media_payloads_raw" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} | sort -u > "$media_payloads_candidates" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
		if _remote_media_appdetails_download_for_list "$target_dir" "$media_json" && _app_network_media_json_keys_extract "$media_json" "$media_json_keys"; then
			local _mp _stem _json_ok_cnt=0 _json_drop_cnt=0
			while IFS= read -r _mp; do
				[[ -z $_mp ]] && continue
				_stem="$(_app_network_media_payload_stem "$_mp")"
				if _app_network_media_json_has_key "$media_json_keys" "$_stem"; then
					printf '%s\n' "$_mp" >> "$media_payloads" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
					_json_ok_cnt=$((_json_ok_cnt + 1))
					_speed_debug_log "APP_LIST_NETWORK_MEDIA_PAYLOAD_KEEP payload=$_mp key=$_stem jsonMatch=1"
				else
					_json_drop_cnt=$((_json_drop_cnt + 1))
					_speed_debug_log "APP_LIST_NETWORK_MEDIA_PAYLOAD_DROP payload=$_mp key=$_stem reason=json_key_missing"
				fi
			done < "$media_payloads_candidates"
			sort -u "$media_payloads" -o "$media_payloads" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
			_speed_debug_log "APP_LIST_NETWORK_MEDIA_PAYLOADS rows=$(grep -vc '^$' "$media_payloads" 2>/dev/null) candidates=$(grep -vc '^$' "$media_payloads_candidates" 2>/dev/null) jsonKeys=$(grep -vc '^$' "$media_json_keys" 2>/dev/null) kept=$_json_ok_cnt dropped=$_json_drop_cnt rel=$target_dir/Media guard=json-key"
		else
			_speed_debug_log "APP_LIST_NETWORK_MEDIA_PAYLOADS rows=0 candidates=$(grep -vc '^$' "$media_payloads_candidates" 2>/dev/null) rel=$target_dir/Media guard=json-key reason=app_details_unavailable"
		fi
	fi
	# 產生 appList_network.txt
	# 規則:
	#   - 排除 tools, start.sh, restore_settings.conf (遠端不使用/本地補齊項)
	#   - 是目錄: wifi/Media → 特殊項; 其他 → app
	#   - 是檔案就忽略
	local out="$MODDIR/appList_network.txt"
	local out_dir="${out%/*}" out_tmp="$TMPDIR/.appList_network_out.$$" out_cache="$TMPDIR/.speedbackup_last_appList_network"
	if ! mkdir -p "$out_dir" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}; then
		echoRgb "無法建立清單輸出目錄: $out_dir" "0"
		_speed_debug_log "APP_LIST_NETWORK_WRITE_FAIL reason=mkdir_parent path=$out dir=$out_dir mode=r370"
		rm -f "$sub_listing" "$media_payloads" "$media_payloads_raw" "$media_payloads_candidates" "$media_json" "$media_json_keys" "$_payload_fallback_file" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
		return 1
	fi
	rm -f "$out_tmp" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	# 遠端 app 清單
	local apps="$TMPDIR/.apps_list"
	: > "$apps"
	while read -r type name; do
		[[ $type = D ]] || continue
		case "$name" in
		tools|wifi|Media) continue ;;
		esac
		if [[ ${_appdetails_bundle_present:-1} != 1 ]]; then
			if _remote_list_payload_has_app "$_payload_fallback_file" "$name"; then
				_speed_debug_log "REMOTE_LIST_PAYLOAD_FALLBACK_APP_KEEP app=$name reason=payload_present mode=r370"
			else
				_speed_debug_log "REMOTE_LIST_PAYLOAD_FALLBACK_APP_DROP app=$name reason=no_payload_or_empty_precreated_dir mode=r370"
				continue
			fi
		fi
		echo "$name" >> "$apps"
	done < "$sub_listing"
	sort "$apps" > "$TMPDIR/.apps_sorted"
	# 本地備份資料夾清單
	local local_apps="$TMPDIR/.local_apps"
	local _local_backup="$MODDIR/$(get_backup_dirname)"
	: > "$local_apps"
	for _d in "$_local_backup"/*/; do
		_d="${_d%/}"; _d="${_d##*/}"
		case "$_d" in tools|wifi|Media|log) continue ;; esac
		[[ -f "$_local_backup/$_d/app_details.json" ]] && echo "$_d" >> "$local_apps"
	done
	sort "$local_apps" > "$TMPDIR/.local_sorted"
	local only_remote only_local
	only_remote="$(comm -23 "$TMPDIR/.apps_sorted" "$TMPDIR/.local_sorted")"
	only_local="$(comm -13 "$TMPDIR/.apps_sorted" "$TMPDIR/.local_sorted")"
	{
		echo "# 遠端備份目錄: $target_dir"
		echo "# 連線: $remote_type://$REMOTE_HOST/"
		if [[ ${_appdetails_bundle_present:-1} != 1 ]]; then
			echo "#  遠端缺少 app_details metadata bundle；此清單由 payload 深度掃描回退產生"
			echo "#  若這是中斷中的新備份，流式恢復可能因缺少 app_details metadata 而無法安全執行"
		fi
		echo "# 用 # 註解掉不要下載的項目, 編輯完選 '從遠端下載備份' 即可"
		echo ""
		echo "# ---- 應用 (每行一個 app) ----"
		cat "$TMPDIR/.apps_sorted"
		echo ""
		echo "# ---- 特殊項目 (非 app, 有就會下載 / 流式恢復可逐項保留) ----"
		if [[ -s $media_payloads ]]; then
			echo "# Media 自定義資料夾壓縮包 (排除 json；必須同時存在實檔與 app_details key；註解掉即可不下載/不流式恢復)"
			cat "$media_payloads"
		elif awk '$1=="D" && $2=="Media" {f=1; exit} END{exit f?0:1}' "$sub_listing" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}; then
			echo "# Media 目錄存在，但沒有通過 app_details.json key 校驗的可選壓縮包"
		fi
		while read -r type name; do
			[[ $type = D ]] || continue
			case "$name" in
			wifi) echo "$name" ;;
			esac
		done < "$sub_listing"
		echo ""
		echo "# ---- 比對結果 ----"
		if [[ -n $only_remote ]]; then
			echo "# 遠端有、本地無 (可下載):"
			echo "$only_remote" | while read -r _n; do echo "#   $_n"; done
		fi
		if [[ -n $only_local ]]; then
			echo "# 本地有、遠端無 (未上傳):"
			echo "$only_local" | while read -r _n; do echo "#   $_n"; done
		fi
		[[ -z $only_remote && -z $only_local ]] && echo "# 本地與遠端完全一致"
	} > "$out_tmp"
	if ! cp -f "$out_tmp" "$out" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}; then
		echoRgb "appList_network.txt 寫入失敗: $out" "0"
		_speed_debug_log "APP_LIST_NETWORK_WRITE_FAIL reason=copy path=$out tmp=$out_tmp mode=r370"
		rm -f "$out_tmp" "$apps" "$TMPDIR/.apps_sorted" "$local_apps" "$TMPDIR/.local_sorted" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
		rm -f "$sub_listing" "$media_payloads" "$media_payloads_raw" "$media_payloads_candidates" "$media_json" "$media_json_keys" "$_payload_fallback_file" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
		return 1
	fi
	chmod 0644 "$out" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} || true
	if [[ ! -f $out ]]; then
		echoRgb "appList_network.txt 寫入後不存在: $out" "0"
		_speed_debug_log "APP_LIST_NETWORK_WRITE_FAIL reason=verify_missing path=$out tmp=$out_tmp mode=r370"
		rm -f "$out_tmp" "$apps" "$TMPDIR/.apps_sorted" "$local_apps" "$TMPDIR/.local_sorted" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
		rm -f "$sub_listing" "$media_payloads" "$media_payloads_raw" "$media_payloads_candidates" "$media_json" "$media_json_keys" "$_payload_fallback_file" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
		return 1
	fi
	cp -f "$out" "$out_cache" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} || true
	_speed_debug_log "APP_LIST_NETWORK_WRITE_OK path=$out cache=$out_cache bytes=$(wc -c < "$out" 2>/dev/null) mode=r370"
	cp "$TMPDIR/.apps_sorted" "$TMPDIR/.apps_sorted_keep" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	rm -f "$out_tmp" "$apps" "$TMPDIR/.apps_sorted" "$local_apps" "$TMPDIR/.local_sorted"
	rm -f "$sub_listing" "$media_payloads" "$media_payloads_raw" "$media_payloads_candidates" "$media_json" "$media_json_keys" "$_payload_fallback_file" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	echoRgb "已輸出清單: $out" "1"
	local _rc _lc
	[[ -n $only_remote ]] && _rc="$(echo "$only_remote" | grep -c .)"
	[[ -n $only_local ]]  && _lc="$(echo "$only_local"  | grep -c .)"
	[[ -n $only_remote ]] && echoRgb "遠端有、本地無: ${_rc}個" "3" && echo "$only_remote" | while read -r _n; do echoRgb "$_n" "3"; done
	[[ -n $only_local ]]  && echoRgb "本地有、遠端無: ${_lc}個" "0" && echo "$only_local"  | while read -r _n; do echoRgb "$_n" "0"; done
	[[ -z $only_remote && -z $only_local ]] && echoRgb "本地與遠端完全一致" "1"
	# 有差異時提供快速操作
	if [[ -n $only_local ]]; then
		if ask_yn "立即上傳本地多出的應用?" "上傳" "跳過"; then
			backup_path
			REMOTE_APPLIST="$only_local"
			REMOTE_TRIGGER=1
			case $remote_type in
			smb) upload_smb ;;
			webdav) upload_remote "webdav" ;;
			esac
			unset REMOTE_TRIGGER REMOTE_APPLIST
		fi
	fi
	if [[ -n $only_remote ]]; then
		if ask_yn "立即下載遠端多出的應用?" "下載" "跳過"; then
			local _dl_items="$TMPDIR/.dl_diff_items"
			echo "$only_remote" > "$_dl_items"
			local chosen="$(get_backup_dirname)"
			local dest="$MODDIR/$chosen"
			mkdir -p "$dest" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
			_remote_download_appdetails_bundle "$chosen" "$dest" || { rm -f "$_dl_items" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}; return 1; }
			remote_parse_endpoint
			if remote_precheck "$REMOTE_HOST" "$REMOTE_PORT"; then
				if [[ $remote_type = smb ]]; then
					_remote_download_smb "$chosen" "$dest" "$_dl_items"
				elif [[ $remote_type = webdav ]]; then
					_remote_download_webdav "$chosen" "$dest" "$_dl_items"
				fi
			else
				echoRgb "遠端連線失敗" "0"
					_remote_precheck_print_smb_issue
			fi
			rm -f "$_dl_items"
		fi
	fi
	if [[ ${_appdetails_bundle_present:-1} = 1 ]]; then
		ask_yn_indep "順手檢查遠端app_details.json健全度? (解析 metadata bundle 驗證)" "檢查" "跳過"
	else
		branch=false
		echoRgb "遠端 metadata bundle 缺失，已跳過 app_details 健全度檢查" "0"
		_speed_debug_log "REMOTE_LIST_BUNDLE_HEALTH_SKIP reason=bundle_missing mode=r370"
	fi
	if [[ $branch = true ]]; then
		local _ra _jchk_total _jchk_i=0 _jok=0 _jinvalid=0 _jmissing=0
		local _health_root="$TMPDIR/.health_check_appdetails_bundle" _bundle_ok=0
		_jchk_total="$(grep -vc '^$' "$TMPDIR/.apps_sorted_keep" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null})"
		rm -rf "$_health_root" "$TMPDIR/.health_check_dl" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
		mkdir -p "$_health_root" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
		echoRgb "解析遠端 app_details metadata bundle..." "3"
		_speed_debug_log "REMOTE_LIST_BUNDLE_HEALTH_DOWNLOAD_BEGIN subdir=$target_dir rel=$target_dir/$(_appdetails_bundle_rel) mode=bundle-only-r287"
		if _appdetails_bundle_download_extract "$target_dir" "$_health_root" "remote-list-health-r287"; then
			_bundle_ok=1
			_speed_debug_log "REMOTE_LIST_BUNDLE_HEALTH_BUNDLE_READY subdir=$target_dir root=$_health_root total=$_jchk_total mode=bundle-only-r287"
			echoRgb "遠端 app_details metadata bundle 解析完成，開始檢查 $_jchk_total 個 JSON" "1"
		else
			_bundle_ok=0
			_speed_debug_log "REMOTE_LIST_BUNDLE_HEALTH_BUNDLE_FAIL subdir=$target_dir total=$_jchk_total mode=no-per-app-fallback-r287"
			echoRgb "遠端 app_details metadata bundle 解析失敗；此版本不再逐檔下載 app_details.json" "0"
		fi
		while read -r _ra; do
			[[ -z $_ra ]] && continue
			let _jchk_i++
			local _rk="${_ra%% *}" _jf
			[[ -z $_rk ]] && _rk="$_ra"
			_jf="$_health_root/$_rk/app_details.json"
			_speedbackup_progress_step "$_jchk_i" "$_jchk_total" "檢查遠端 app_details $_ra" "remote_json_health_verify"
			if [[ $_bundle_ok = 1 && -s $_jf ]]; then
				if _remote_appdetails_json_ok "$_jf"; then
					let _jok++
					_json_health_check "$_jf" "$_ra (遠端bundle)"
				else
					let _jinvalid++
					_remote_health_record_appdetails_drop "$_ra" "$_rk" invalid "$_jf"
				fi
			else
				let _jmissing++
				_remote_health_record_appdetails_drop "$_ra" "$_rk" missing
			fi
		done < "$TMPDIR/.apps_sorted_keep"
		rm -rf "$_health_root" "$TMPDIR/.health_check_dl" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
		JSON_HEALTH_REPORT_ALWAYS=1
		JSON_HEALTH_CHECKED_COUNT="$_jchk_total"
		JSON_HEALTH_INVALID_COUNT="$_jinvalid"
		JSON_HEALTH_MISSING_COUNT="$_jmissing"
		_json_health_report
		echoRgb "檢查完成 $_jchk_i/$_jchk_total" "1"
	fi
	rm -f "$TMPDIR/.apps_sorted_keep" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	echoRgb "請編輯該檔案,留下你要下載的項目,然後選 '從遠端下載備份'" "3"
}

# r419: 功能10遠端下載備份時，metadata 只接受根層 app_details_bundle.tar.zst。
# 下載成功後立即在本地備份根目錄同級解包，恢復 <App>/app_details.json 結構。
# 不再保留舊版逐 App JSON 下載/相容路徑，也不再讀 app_details_bundle.tar 舊檔名。
_remote_download_appdetails_bundle() {
	local _chosen="$1" _dest="$2" _base_url _rel _dst _tmp _err _rc _tag
	[[ -n $_chosen && -n $_dest ]] || return 1
	mkdir -p "$_dest" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} || return 1
	_rel="$(_appdetails_bundle_rel)"
	_dst="$_dest/${_rel##*/}"
	_tmp="$_dst.part.$$.$RANDOM"
	_err="${TMPDIR:-/data/local/tmp}/.remote_download_bundle_err_${$}_$RANDOM"
	_tag="$(_remote_debug_seq remote_download_bundle)"
	rm -f "$_tmp" 2>/dev/null
	case ${remote_type:-} in
	webdav)
		_base_url="${remote_url%/}"
		_webdav_dex getrel "$remote_user" "$remote_pass" "$_base_url" "$_chosen/$_rel" "$_tmp" 2>"$_err"
		_rc=$?
		remote_raw_log "remote_download_raw.log" "WEBDAV_APPDETAILS_BUNDLE_GET tag=$_tag rc=$_rc rel=$_chosen/$_rel dest=$_dst mode=r419"
		remote_raw_cat "remote_download_webdav_bundle_${_tag}.log" "$_err" "===== WEBDAV_APPDETAILS_BUNDLE_GET $_tag rel=$_chosen/$_rel rc=$_rc ====="
		;;
	smb)
		remote_parse_smb_url
		local _share="$SMB_SHARE" _base="${SMB_REM_PATH:+$SMB_REM_PATH/}$_chosen" _auth _out
		_auth="$(_smb_auth_args_current)" || { rm -f "$_err" "$_tmp" 2>/dev/null; _speed_debug_log "REMOTE_DOWNLOAD_APPDETAILS_BUNDLE_FAIL reason=smb_auth_unavailable rel=$_rel mode=r419"; return 1; }
		_out=$(smbclient "$_share" $_auth -t 60 -s $(_smb_client_conf)${REMOTE_PORT:+ -p $REMOTE_PORT} -m SMB3 \
			-D "$_base" \
			-c "lcd $_dest; prompt off; get \"$_rel\" \"$_tmp\"; exit" 2>&1)
		_rc=$?
		_out="$(smb_filter_noise "$_out")"
		remote_raw_log "remote_download_raw.log" "SMB_APPDETAILS_BUNDLE_GET tag=$_tag rc=$_rc base=$_base rel=$_rel dest=$_dst mode=r419"
		{
			echo "===== SMB_APPDETAILS_BUNDLE_GET $_tag rel=$_rel rc=$_rc ====="
			printf '%s\n' "$_out"
		} >> "${SPEED_DEBUG_RUN_DIR:-/data/speed_debug}/remote_download_smb_bundle_${_tag}.log" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
		;;
	*)
		rm -f "$_err" "$_tmp" 2>/dev/null
		return 1
		;;
	esac
	rm -f "$_err" 2>/dev/null
	if [[ $_rc = 0 && -s $_tmp ]]; then
		mv -f "$_tmp" "$_dst" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} || { rm -f "$_tmp" 2>/dev/null; return 1; }
		if _appdetails_bundle_extract_file "$_dst" "$_dest" "remote-download-r419"; then
			_speed_debug_log "REMOTE_DOWNLOAD_APPDETAILS_BUNDLE_OK rel=$_rel dest=$_dst extractDest=$_dest mode=r419 layout=flat"
			echoRgb "✓ app_details metadata bundle 已下載並解包 ($_rel)" "1"
			return 0
		fi
		_speed_debug_log "REMOTE_DOWNLOAD_APPDETAILS_BUNDLE_EXTRACT_FAIL rel=$_rel dest=$_dst extractDest=$_dest mode=r419"
		echoRgb "app_details metadata bundle 解包失敗，已中止下載" "0"
		return 1
	fi
	rm -f "$_tmp" 2>/dev/null
	_speed_debug_log "REMOTE_DOWNLOAD_APPDETAILS_BUNDLE_REQUIRED_MISSING subdir=$_chosen rel=$_rel action=abort mode=r419"
	echoRgb "遠端缺少 app_details_bundle.tar.zst；功能10已移除逐 App JSON 相容，下載中止" "0"
	return 1
}

# 依 appList_network.txt 下載備份到 $MODDIR/Backup_*_$user
remote_download_backup() {
	show_conf remote
	[[ -z $remote_type ]] && { _remote_type_missing_msg; return 1; }
	case $remote_type in
	smb|webdav) ;;
	*) echoRgb "下載功能僅支援 smb / webdav (目前 remote_type=$remote_type)" "0"; return 1 ;;
	esac
	local list="$MODDIR/appList_network.txt"
	if [[ ! -f $list ]]; then
		echoRgb "找不到 $list" "0"
		echoRgb "請先執行 '列出遠端備份' 產生清單" "3"
		return 1
	fi
	local dl_start
	dl_start=$(date +%s)
	# 目標目錄 = 跟本地備份一樣的命名規則
	local chosen="$(get_backup_dirname)"
	echoRgb "目標遠端目錄: $chosen" "3"
	# 連線預檢
	remote_parse_endpoint
	if ! remote_precheck "$REMOTE_HOST" "$REMOTE_PORT"; then
		echoRgb "遠端連線失敗: $REMOTE_HOST:$REMOTE_PORT" "0"
			_remote_precheck_print_smb_issue
		return 1
	fi
	_remote_stream_fatal_reset "remote_download_start"
	_remote_netwatch_start
	if _remote_netwatch_mark_remote_fatal "remote_download_after_precheck" "$chosen"; then
		echoRgb "遠端下載已因 LAN 路由／位址變更中止" "0"
		_remote_netwatch_finish
		return 1
	fi
	# 解析清單 (去除註解/空行)
	local items_file="$TMPDIR/.dl_items"
	grep -Ev '^[[:space:]]*[#＃]|^[[:space:]]*$' "$list" > "$items_file"
	if [[ ! -s $items_file ]]; then
		echoRgb "清單為空,沒有東西需要下載" "0"
		rm -f "$items_file"
		_remote_netwatch_finish
		return 1
	fi
	local item_count
	item_count=$(wc -l < "$items_file")
	echoRgb "將下載 $item_count 個項目；restore_settings.conf 下載後本地生成，tools/ 使用本機補齊，app_details bundle 必須先下載並解包" "3"
	# 下載目標: $MODDIR/$chosen (例: $MODDIR/Backup_zstd_0)
	local dest="$MODDIR/$chosen"
	mkdir -p "$dest" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	echoRgb "下載到: $dest" "2"
	_remote_download_appdetails_bundle "$chosen" "$dest" || { rm -f "$items_file" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}; _remote_netwatch_finish; return 1; }
	# 依協議分派
	local fail=0
	if [[ $remote_type = smb ]]; then
		_remote_download_smb "$chosen" "$dest" "$items_file" || fail=1
	elif [[ $remote_type = webdav ]]; then
		_remote_download_webdav "$chosen" "$dest" "$items_file" || fail=1
	fi
	rm -f "$items_file"
	local dl_elapsed=$(( $(date +%s) - dl_start ))
	if [[ $fail -eq 0 ]]; then
		echoRgb "_______________________________________" "2"
		echoRgb "下載完成: $dest 用時${dl_elapsed}秒" "1"
		echoRgb "已本地補齊入口腳本，可直接執行 $dest/start.sh 進行恢復" "3"
		remote_log "下載完成: $dest 用時${dl_elapsed}秒"
		_remote_netwatch_finish
	else
		echoRgb "下載過程有失敗,請檢查上方訊息 (用時${dl_elapsed}秒)" "0"
		remote_log "下載失敗 用時${dl_elapsed}秒"
		_remote_netwatch_finish
		return 1
	fi
}

# SMB 下載實作
# 每個 item 一次 smbclient (用 -D 直接切目錄,避免 cd 路徑解析問題)
# $1=遠端 Backup_zstd_X 目錄名, $2=本地目標, $3=要下載的項目清單檔
_remote_download_smb() {
	local chosen="$1" dest="$2" items_file="$3"
	if _remote_netwatch_mark_remote_fatal "remote_download_smb_enter" "$chosen"; then
		_speed_debug_log "REMOTE_DOWNLOAD_SMB_SKIP reason=remote_netwatch_changed chosen=$chosen"
		return 1
	fi
	remote_parse_smb_url
	local share="$SMB_SHARE"
	local rem_path="$SMB_REM_PATH"
	local SMB_OPTS="-t 300 -s $(_smb_client_conf)${REMOTE_PORT:+ -p $REMOTE_PORT} -m SMB3"
	local base="${rem_path:+$rem_path/}$chosen"
	remote_raw_log "remote_download_raw.log" "SMB_BEGIN share=$share base=$base dest=$dest items_file=$items_file"
	local total_items
	total_items=$(wc -l < "$items_file")
	local idx=0 fail_total=0 _smb_item_rc _media_payload_selected=0
	# 下載每個項目 (用 -D 切到指定目錄, 再 mget *)
	while read -r item; do
		[[ -z $item ]] && continue
		if _remote_netwatch_mark_remote_fatal "remote_download_smb_item_enter" "$item"; then
			_speed_debug_log "REMOTE_DOWNLOAD_SMB_ABORT reason=remote_netwatch_changed item=$item"
			fail_total=$((fail_total + 1))
			break
		fi
		let idx++
		echoRgb "[$idx/$total_items] $(progress_bar $((idx * 100 / total_items))) 下載 $item" "3"
		local out
		if ! _smb_safe_component "$item" || ! _smb_safe_component "$dest"; then
			echoRgb "偵測到不安全的項目名稱字元, 拒絕執行 smbclient 下載: $item" "0" >&2
			continue
		fi
		local _smb_auth_args
		_smb_auth_args="$(_smb_auth_args_current)" || { _smb_auth_unavailable_msg "下載 $item"; fail_total=$((fail_total+1)); continue; }
		if _app_network_is_media_payload "$item"; then
			_media_payload_selected=1
			mkdir -p "$dest/Media" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
			out=$(smbclient "$share" $_smb_auth_args $SMB_OPTS \
				-D "$base/Media" \
				-c "lcd $dest/Media; prompt off; get \"$item\"; exit" 2>&1)
		else
			mkdir -p "$dest/$item" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
			out=$(smbclient "$share" $_smb_auth_args $SMB_OPTS \
				-D "$base/$item" \
				-c "lcd $dest/$item; prompt off; recurse on; mget *; exit" 2>&1)
		fi
		_smb_item_rc=$?
		if [[ $_smb_item_rc != 0 ]]; then
			_remote_netwatch_mark_remote_fatal "remote_download_smb_item_fail" "$item" >/dev/null 2>&1 || true
		fi
		out="$(smb_filter_noise "$out")"
		local _dl_tag
		_dl_tag="$(_remote_debug_seq remote_download_smb)"
		remote_raw_log "remote_download_raw.log" "SMB_ITEM tag=$_dl_tag idx=$idx total=$total_items item=$item dest=$dest/$item"
		{
			echo "===== SMB_DOWNLOAD_ITEM $_dl_tag item=$item ====="
			printf '%s\n' "$out"
		} >> "${SPEED_DEBUG_RUN_DIR:-/data/speed_debug}/remote_download_smb_${_dl_tag}.log" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
		printf '%s\n' "$out" >> "${SPEED_DEBUG_RUN_DIR:-/data/speed_debug}/remote_download_raw.log" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
		if echo "$out" | grep -qE 'NT_STATUS_[A-Z_]+' \
			|| { if _app_network_is_media_payload "$item"; then [[ ! -s "$dest/Media/$item" ]]; else [[ -z "$(ls -A "$dest/$item" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null})" ]]; fi; }; then
			if echo "$out" | grep -q 'NT_STATUS_OBJECT_NAME_NOT_FOUND'; then
				echoRgb "✗ $item（遠端不存在或已被刪除）" "0"
				if _app_network_is_media_payload "$item"; then rm -f "$dest/Media/$item" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}; else rm -rf "$dest/$item" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}; fi
			else
				echoRgb "✗ $item（下載失敗，詳見 speed_debug）" "0"
			fi
			let fail_total++
		else
			if ! _app_network_is_media_payload "$item"; then
				rm -f "$dest/$item/app_details.json" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} || true
				_speed_debug_log "REMOTE_DOWNLOAD_PER_APP_JSON_DROP item=$item mode=r419 reason=bundle-only"
			fi
			echoRgb "✓ $item" "1"
		fi
	done < "$items_file"
	# r419: metadata 已由根層 app_details_bundle.tar.zst 同級解包；不再逐項下載 Media/app_details.json。
	if false && [[ $_media_payload_selected = 1 ]]; then
		echoRgb "下載 Media metadata: app_details.json" "3"
		mkdir -p "$dest/Media" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
		local _smb_auth_args_meta _meta_out _meta_rc
		_smb_auth_args_meta="$(_smb_auth_args_current)" || { _smb_auth_unavailable_msg "下載 Media/app_details.json"; fail_total=$((fail_total+1)); _smb_auth_args_meta=""; }
		if [[ -n $_smb_auth_args_meta ]]; then
			_meta_out=$(smbclient "$share" $_smb_auth_args_meta $SMB_OPTS \
				-D "$base/Media" \
				-c "lcd $dest/Media; prompt off; get app_details.json; exit" 2>&1)
			_meta_rc=$?
			_meta_out="$(smb_filter_noise "$_meta_out")"
			remote_raw_log "remote_download_raw.log" "SMB_MEDIA_METADATA rc=$_meta_rc base=$base/Media dest=$dest/Media/app_details.json"
			printf '%s\n' "$_meta_out" >> "${SPEED_DEBUG_RUN_DIR:-/data/speed_debug}/remote_download_raw.log" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
			if [[ $_meta_rc != 0 || ! -s $dest/Media/app_details.json ]]; then
				echoRgb "✗ Media/app_details.json（下載失敗）" "0"
				fail_total=$((fail_total + 1))
			else
				echoRgb "✓ Media/app_details.json" "1"
			fi
		fi
	fi
	# 固定項: restore_settings.conf 不再從遠端下載；下載完成後本地生成，tools/ 與入口/清單本地補齊。
	_remote_download_fixed_notice
	_remote_download_fixed_verify "$dest" || fail_total=$((fail_total + 1))
	rm -f "$_fix_detail" 2>/dev/null
	[[ $fail_total -eq 0 ]]
}

_remote_download_webdav() {
	local chosen="$1" dest="$2" items_file="$3"
	if _remote_netwatch_mark_remote_fatal "remote_download_webdav_enter" "$chosen"; then
		_speed_debug_log "REMOTE_DOWNLOAD_WEBDAV_SKIP reason=remote_netwatch_changed chosen=$chosen"
		return 1
	fi
	local base_url="${remote_url%/}"
	local base_rel="$chosen"
	remote_raw_log "remote_download_raw.log" "WEBDAV_BEGIN base_url=$base_url base_rel=$base_rel dest=$dest items_file=$items_file"
	local total_items
	total_items=$(wc -l < "$items_file")
	case "$total_items" in ''|*[!0-9]*) total_items=0 ;; esac
	local fail_total=0
	# 遞迴掃描 WebDAV 路徑, 把所有檔案 (含子目錄內) 寫入清單檔
	# 清單格式: <遠端相對路徑>\t<本地完整路徑>
	# $1=遠端相對路徑, $2=本地目錄, $3=清單檔
	_webdav_scan_files() {
		local r_rel="$1" l_dir="$2" out_list="$3"
		if _remote_netwatch_mark_remote_fatal "remote_download_webdav_scan_enter" "$r_rel"; then
			_speed_debug_log "WEBDAV_SCAN_SKIP reason=remote_netwatch_changed rel=$r_rel"
			return 1
		fi
		mkdir -p "$l_dir" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
		local out _scan_err="$TMPDIR/.wdav_scan_err_$$" _scan_rc _scan_tag
		_scan_tag="$(_remote_debug_seq webdav_scan)"
		_webdav_status_sidecar_reset
		out="$(_webdav_dex listrel "$remote_user" "$remote_pass" "$base_url" "$r_rel" 1 2>"$_scan_err")"
		_scan_rc=$?
		if [[ $_scan_rc != 0 ]]; then
			_remote_netwatch_mark_remote_fatal "remote_download_webdav_scan_fail" "$r_rel" >/dev/null 2>&1 || true
		fi
		_webdav_status_sidecar_load || true
		remote_raw_log "remote_download_raw.log" "WEBDAV_SCAN tag=$_scan_tag rc=$_scan_rc rel=$r_rel local=$l_dir"
		remote_raw_cat "remote_download_webdav_scan_${_scan_tag}.log" "$_scan_err" "===== WEBDAV_SCAN $_scan_tag rel=$r_rel rc=$_scan_rc ====="
		rm -f "$_scan_err" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
		[[ $_scan_rc -ne 0 ]] && return 1
		# 用 mktemp 避免遞迴呼叫時不同層級共用同個檔案造成資料覆蓋
		local parsed
		parsed=$(mktemp "$TMPDIR/.wdav_scan_XXXXXX")
		# dex list 已輸出 "href	length	D|F"; 重排成 "typ	href" 供下游沿用。
		printf '%s\n' "$out" | awk -F'	' '{print $3"\t"$1}' > "$parsed"
		local r_url_basename
		r_url_basename="${r_rel%/}"
		r_url_basename="${r_url_basename##*/}"
		local rc=0
		while IFS=$'	' read -r typ href; do
			[[ -z $href ]] && continue
			local name
			name="$(echo "$href" | sed 's|/$||; s|.*/||')"
			[[ -z $name ]] && continue
			[[ $name = "$r_url_basename" ]] && continue
			if [[ $typ = D ]]; then
				_webdav_scan_files "$r_rel/$name" "$l_dir/$name" "$out_list" || rc=1
			else
				# r170: 遠端舊備份若仍有 per-app wrappers，下載階段也直接跳過；落地後由 touch_shell 重建。
				case "$name" in backup.sh|recover.sh|upload.sh) _speed_debug_log "WEBDAV_SCAN_SIDECAR_SKIP rel=$r_rel/$name reason=local-rebuild-on-download"; continue ;; esac
				# 寫入清單: 遠端相對路徑	本地路徑
				echo -e "$r_rel/$name	$l_dir/$name" >> "$out_list"
			fi
		done < "$parsed"
		rm -f "$parsed"
		return $rc
	}
	# 逐筆下載清單內的所有檔案 (改用 dex get, 不再 parallel; 正確性優先於並行速度)
	# 每行 "rel_path\tlocal_path"
	# 第二參數 quiet 時：不在終端逐檔換行，只保留 raw/debug log；UI 由 item 層級進度列負責。
	_webdav_parallel_get() {
		local list="$1" ui_mode="$2"
		[[ ! -s $list ]] && return 0
		local _get_err="$TMPDIR/.wdav_get_err_$$" _get_tag
		_get_tag="$(_remote_debug_seq webdav_get)"
		local rc=0 _file_rc=0 _get_total _get_idx=0 _pct _get_start_ms _get_elapsed_ms _get_bytes _get_speed _get_size _quiet=0
		[[ $ui_mode = quiet ]] && _quiet=1
		_get_total=$(wc -l < "$list" 2>/dev/null)
		case "$_get_total" in ''|*[!0-9]*) _get_total=0 ;; esac
		while IFS=$'	' read -r rel lpath; do
			[[ -z $rel ]] && continue
			if _remote_netwatch_mark_remote_fatal "remote_download_webdav_get_enter" "$rel"; then
				_speed_debug_log "WEBDAV_GET_ABORT reason=remote_netwatch_changed rel=$rel"
				rc=1
				break
			fi
			_get_idx=$((_get_idx + 1))
			if [[ $_quiet -ne 1 ]]; then
				if [[ $_get_total -gt 0 ]]; then
					_pct=$((_get_idx * 100 / _get_total))
					printf '\r -下載遠端檔案 %d/%d %s %s' "$_get_idx" "$_get_total" "$(progress_bar $_pct)" "$rel" >&2
				else
					printf '\r -下載遠端檔案 %d %s' "$_get_idx" "$rel" >&2
				fi
			fi
			_get_start_ms="$(_speed_now_ms)"
			_file_rc=0
			_webdav_dex getrel "$remote_user" "$remote_pass" "$base_url" "$rel" "$lpath" 2>>"$_get_err" || _file_rc=$?
			if [[ $_file_rc != 0 ]]; then
				_remote_netwatch_mark_remote_fatal "remote_download_webdav_get_fail" "$rel" >/dev/null 2>&1 || true
			fi
			if [[ $_file_rc != 0 ]]; then
				case "${rel##*/}" in
				backup.sh)
					mkdir -p "${lpath%/*}" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
					if touch_shell "1" "$lpath" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}; then
						chmod 0755 "$lpath" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
						remote_raw_log "remote_download_raw.log" "WEBDAV_GET_REGEN_APP_SCRIPT rel=$rel type=backup rc=$_file_rc"
						_file_rc=0
					fi
					;;
				recover.sh)
					mkdir -p "${lpath%/*}" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
					if touch_shell "3" "$lpath" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}; then
						chmod 0755 "$lpath" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
						remote_raw_log "remote_download_raw.log" "WEBDAV_GET_REGEN_APP_SCRIPT rel=$rel type=recover rc=$_file_rc"
						_file_rc=0
					fi
					;;
				upload.sh)
					mkdir -p "${lpath%/*}" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
					if touch_shell "5" "$lpath" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}; then
						chmod 0755 "$lpath" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
						remote_raw_log "remote_download_raw.log" "WEBDAV_GET_REGEN_APP_SCRIPT rel=$rel type=upload rc=$_file_rc"
						_file_rc=0
					fi
					;;
				esac
			fi
			if [[ $_file_rc != 0 ]]; then
				rc=1
			fi
			_get_elapsed_ms=$(( $(_speed_now_ms) - _get_start_ms ))
			[[ $_get_elapsed_ms -le 0 ]] && _get_elapsed_ms=1
			_get_bytes="$(_local_file_size_debug "$lpath")"
			_get_speed="$(_webdav_speed_mib_s "$_get_bytes" "$_get_elapsed_ms")"
			_get_size="$(_webdav_size_mib_text "$_get_bytes")"
			remote_raw_log "remote_download_raw.log" "WEBDAV_GET_FILE tag=$_get_tag idx=$_get_idx total=$_get_total rc=$_file_rc cumulativeRc=$rc bytes=${_get_bytes:-0} elapsedMs=$_get_elapsed_ms speedMiBps=$_get_speed rel=$rel"
			if [[ $_quiet -ne 1 ]]; then
				if [[ $_get_total -gt 0 ]]; then
					printf '\r -下載遠端檔案 %d/%d %s %s %sMiB/s %s\n' "$_get_idx" "$_get_total" "$(progress_bar $_pct)" "$_get_size" "$_get_speed" "$rel" >&2
				else
					printf '\r -下載遠端檔案 %d %sMiB/s %s %s\n' "$_get_idx" "$_get_speed" "$_get_size" "$rel" >&2
				fi
			fi
		done < "$list"
		remote_raw_log "remote_download_raw.log" "WEBDAV_GET tag=$_get_tag rc=$rc files=$_get_idx list=$list ui=$ui_mode"
		{
			echo "===== WEBDAV_GET $_get_tag rc=$rc list=$list ui=$ui_mode ====="
			echo "[list]"
			cat "$list"
			echo "[stderr]"
			cat "$_get_err" 2>/dev/null
		} >> "${SPEED_DEBUG_RUN_DIR:-/data/speed_debug}/remote_download_webdav_get_${_get_tag}.log" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
		# WebDAV GET 清理暫存檔時完全靜默，避免偶發 rm 噪音污染 stderr.log。
		rm -f "$_get_err" 2>/dev/null
		return $rc
	}
	# 逐 item 掃描 + 下載；終端顯示與 SMB 保持一致，只顯示 item 級進度與成功/失敗。
	local idx=0 item _pct item_list item_fail _media_payload_selected=0
	while read -r item; do
		[[ -z $item ]] && continue
		if _remote_netwatch_mark_remote_fatal "remote_download_webdav_item_enter" "$item"; then
			_speed_debug_log "REMOTE_DOWNLOAD_WEBDAV_ABORT reason=remote_netwatch_changed item=$item"
			fail_total=$((fail_total + 1))
			break
		fi
		idx=$((idx + 1))
		if [[ $total_items -gt 0 ]]; then
			_pct=$((idx * 100 / total_items))
		else
			_pct=0
		fi
		echoRgb "[$idx/$total_items] $(progress_bar $_pct) 下載 $item" "3"
		item_list="$TMPDIR/.wdav_item_files_${idx}_$$"
		: > "$item_list"
		item_fail=0
		if _app_network_is_media_payload "$item"; then
			_media_payload_selected=1
			mkdir -p "$dest/Media" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
			printf '%s	%s
' "$base_rel/Media/$item" "$dest/Media/$item" >> "$item_list"
			if ! _webdav_parallel_get "$item_list" quiet; then
				echoRgb "✗ $item（下載失敗，詳見 speed_debug）" "0"
				item_fail=1
			elif [[ ! -s "$dest/Media/$item" ]]; then
				echoRgb "✗ $item (本地為空)" "0"
				item_fail=1
			else
				echoRgb "✓ $item" "1"
			fi
		elif ! _webdav_scan_files "$base_rel/$item" "$dest/$item" "$item_list"; then
			echoRgb "✗ 掃描失敗: $item" "0"
			item_fail=1
		elif ! _webdav_parallel_get "$item_list" quiet; then
			echoRgb "✗ $item（下載失敗，詳見 speed_debug）" "0"
			item_fail=1
		elif [[ -z "$(ls -A "$dest/$item" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null})" ]]; then
			echoRgb "✗ $item (本地為空)" "0"
			item_fail=1
		else
			if ! _app_network_is_media_payload "$item"; then
				rm -f "$dest/$item/app_details.json" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} || true
				_speed_debug_log "REMOTE_DOWNLOAD_PER_APP_JSON_DROP item=$item mode=r419 reason=bundle-only"
			fi
			echoRgb "✓ $item" "1"
		fi
		[[ $item_fail = 1 ]] && fail_total=$((fail_total + 1))
		rm -f "$item_list" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	done < "$items_file"
	# r419: metadata 已由根層 app_details_bundle.tar.zst 同級解包；不再逐項下載 Media/app_details.json。
	if false && [[ $_media_payload_selected = 1 ]]; then
		echoRgb "下載 Media metadata: app_details.json" "3"
		mkdir -p "$dest/Media" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
		local _media_meta_list="$TMPDIR/.wdav_media_metadata_$$" _media_meta_fail=0
		: > "$_media_meta_list" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
		printf '%s	%s
' "$base_rel/Media/app_details.json" "$dest/Media/app_details.json" >> "$_media_meta_list"
		_webdav_parallel_get "$_media_meta_list" quiet || _media_meta_fail=1
		rm -f "$_media_meta_list" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
		if [[ $_media_meta_fail = 1 || ! -s $dest/Media/app_details.json ]]; then
			echoRgb "✗ Media/app_details.json（下載失敗）" "0"
			fail_total=$((fail_total + 1))
		else
			echoRgb "✓ Media/app_details.json" "1"
		fi
	fi
	# 固定項: restore_settings.conf 不再從遠端下載；下載完成後本地生成，tools/ 與入口/清單本地補齊。
	_remote_download_fixed_notice
	_remote_download_fixed_verify "$dest" || fail_total=$((fail_total + 1))
	[[ $fail_total -eq 0 ]]
}

_remote_netwatch_finish() {
	_remote_netwatch_report
	_remote_netwatch_stop
}

# trap EXIT 觸發的遠端上傳函數
# 只在 backup/backup_media/backup_update_apk 成功完成後才觸發上傳
# 其他選項 (測試/列出/下載/退出) 不觸發, 由 REMOTE_TRIGGER 旗標控制
remote_cleanup() {
	# 只有在 backup / backup_media / backup_update_apk 跑完後才上傳。
	# 未觸發上傳時仍要停止本輪臨時 netwatch，避免回到選單後殘留。
	if [[ $REMOTE_TRIGGER != 1 ]]; then
		_remote_netwatch_finish
		return 0
	fi
	# 純本機模式：完全不進入遠端收尾，避免「已上傳/只上傳依賴文件」等提示殘留。
	if ! remote_ui_allowed; then
		_remote_netwatch_finish
		return 0
	fi
	# 防雙重觸發 (backup 內直接呼叫 + trap EXIT 都可能呼叫)
	if [[ $REMOTE_DONE = 1 ]]; then
		_remote_netwatch_finish
		return 0
	fi
	REMOTE_DONE=1
	# 流式模式: 應用數據與 json 已在備份過程中逐個流式傳走, 此處只補傳結尾的 wifi (若有)
	if [[ $remote_stream = 1 && -n $remote_type ]]; then
		local _wifidir="$TMPDIR/.stream_stage/wifi"
		if _remote_stream_fatal_active; then
			echoRgb "本輪遠端流式已失敗，略過 wifi/tools/遠端統計收尾，避免網路中斷後卡住" "0"
			_speed_debug_log "REMOTE_CLEANUP_STREAM_FATAL_SKIP $(_remote_stream_fatal_summary)"
			_remote_netwatch_finish
			return 0
		fi
		if [[ $REMOTE_UPLOAD_WIFI = 1 && -d $_wifidir ]]; then
			local _wf
			if [[ $remote_type = webdav ]]; then
				local _wifi_list="$TMPDIR/.stream_wifi_webdav_files_$$"
				: > "$_wifi_list" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
				for _wf in "$_wifidir"/*; do
					[[ -f $_wf ]] && printf '%s	%s
' "wifi/${_wf##*/}" "$_wf" >> "$_wifi_list"
				done
				if _stream_upload_webdav_local_files_batch "$_wifi_list" wifi; then
					echoRgb "wifi 設定已上傳遠端" "1"
				else
					echoRgb "wifi 設定上傳失敗/逾時，已略過；下次會重試" "0"
				fi
				rm -f "$_wifi_list" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
			else
				for _wf in "$_wifidir"/*; do
					[[ -f $_wf ]] && _stream_upload "wifi/${_wf##*/}" < "$_wf"
				done
				echoRgb "wifi 設定已上傳遠端" "1"
			fi
		fi
		if _remote_stream_fatal_active; then
			echoRgb "WebDAV 收尾上傳中斷，略過 tools/ 與遠端統計，避免卡住" "0"
			_speed_debug_log "REMOTE_CLEANUP_AFTER_WIFI_FATAL_SKIP $(_remote_stream_fatal_summary)"
			_remote_netwatch_finish
			return 0
		fi
		echoRgb "流式上傳完成 (數據未佔用本機空間)" "1"
		# 遠端不再上傳 restore_settings.conf；只做必要附加檔/統計收尾，恢復端本地生成 conf。
		stream_upload_infra
		if _remote_stream_fatal_active; then
			echoRgb "WebDAV tools/ 上傳中斷，略過遠端統計，避免卡住" "0"
			_speed_debug_log "REMOTE_CLEANUP_AFTER_INFRA_FATAL_SKIP $(_remote_stream_fatal_summary)"
			_remote_netwatch_finish
			return 0
		fi
		# 統計遠端備份資料夾大小 (對齊本地備份的 Calculate_size 顯示)。
		# r262: 流式模式預設不在 100% 後再深度遍歷整個 WebDAV 目錄；改用備份前 size-map + 本輪 PUT sentBytes 計算顯示。
		# 如需強制遠端重掃精確核驗，設 SPEEDBACKUP_STREAM_REMOTE_TOTAL_DEEP_VERIFY=1。
		local _subdir="$(get_backup_dirname)"
		local _rtotal _rnew _skip_remote_total=0
		if [[ $remote_stream = 1 ]]; then
			# r289: SMB stream has no reliable sentBytes fastmap source; force the existing
			# remote_dir_size path instead of falling into the WebDAV-only fastmap path.
			if [[ $remote_type = smb ]]; then
				_skip_remote_total=0
			else
				case "${SPEEDBACKUP_STREAM_REMOTE_TOTAL_DEEP_VERIFY:-0}" in
				1|true|TRUE|yes|YES|on|ON) _skip_remote_total=0 ;;
				*) _skip_remote_total=1 ;;
				esac
			fi
		fi
		if [[ $_skip_remote_total = 1 ]]; then
			local _before_map _uploaded_map _uploaded_bytes _fast_total _fast_rows
			_before_map="$(_remote_size_map_before_file)"
			_uploaded_map="$(_remote_stream_uploaded_size_map_file)"
			_remote_stream_build_uploaded_size_map "$_subdir" "$_uploaded_map" >/dev/null 2>&1 || true
			_uploaded_bytes="$(_remote_size_map_sum_file "$_uploaded_map" 2>/dev/null)"
			_fast_total="$(_remote_stream_fast_after_size_from_maps "$_before_map" "$_uploaded_map" 2>/dev/null)"
			_fast_rows="$(grep -vc '^$' "$_uploaded_map" 2>/dev/null)"
			case $_fast_total in ''|*[!0-9]*) _fast_total=0 ;; esac
			case $_uploaded_bytes in ''|*[!0-9]*) _uploaded_bytes=0 ;; esac
			echoRgb "遠端備份資料夾↓↓↓\n -$remote_url ($_subdir)" "2"
			if _decimal_is_positive "$_fast_total" || _decimal_is_positive "$_uploaded_bytes"; then
				echoRgb "遠端備份總體大小$(size_with_bytes "$_fast_total")" "3"
				_decimal_is_positive "$_uploaded_bytes" && echoRgb "本次流式上傳總量$(size_with_bytes "$_uploaded_bytes")" "3"
				_rnew="$(_decimal_diff_uint "${_fast_total:-0}" "${_RTOTAL_BEFORE:-0}")"
				_speed_debug_log "REMOTE_TOTAL_AFTER_FASTMAP subdir=$_subdir before=${_RTOTAL_BEFORE:-0} after=$_fast_total delta=$_rnew uploaded=$_uploaded_bytes rows=${_fast_rows:-0} beforeMap=$([[ -s $_before_map ]] && echo 1 || echo 0) mode=stream-post100-fastmap-r309-bigint-safe"
				local _remote_delta_label="本次備份"
				if [[ -s $TMPDIR/.remote_orphan_cleanup_removed ]]; then
					_remote_delta_label="遠端孤兒備份清理後總大小"
				elif [[ -f $TMPDIR/.stream_all_apps_fast_skipped && ! -s $TMPDIR/.changed_apps ]]; then
					_remote_delta_label="遠端基礎檔案更新後總大小"
				fi
				case $_rnew in
				-*) echoRgb "${_remote_delta_label}減少 $(size "${_rnew#-}")" "3" ;;
				0)  echoRgb "文件大小未改變" "3" ;;
				*)  echoRgb "${_remote_delta_label}增加 $(size "$_rnew")" "3" ;;
				esac
			else
				echoRgb "遠端總大小快速統計不可用；未做深度遍歷" "2"
				_speed_debug_log "REMOTE_TOTAL_AFTER_FASTMAP_UNAVAILABLE subdir=$_subdir mode=stream-post100-fastmap-r309-bigint-safe env=SPEEDBACKUP_STREAM_REMOTE_TOTAL_DEEP_VERIFY"
			fi
		else
			# r289: SMB stream 無 WebDAV sentBytes 訊號，不能用 WebDAV fastmap 精確推總量。
			# 對 SMB 直接落回既有 remote_dir_size，避免顯示「快速統計不可用」且保留準確總大小。
			[[ $remote_type = smb ]] && _speed_debug_log "SMB_REMOTE_TOTAL_DEEP_FALLBACK reason=no_stream_sentbytes_fastmap mode=r309-bigint-deep subdir=$_subdir"
    		_rtotal="$(remote_dir_size "$_subdir")"
    		if _decimal_is_positive "$_rtotal"; then
    			echoRgb "遠端備份資料夾↓↓↓\n -$remote_url ($_subdir)" "2"
    			echoRgb "遠端備份總體大小$(size_with_bytes "$_rtotal")" "3"
    			# 本次差異: 整體資料夾大小差異 (備份前快照 vs 現在, 對齊本地 Calculate_size)
    			_rnew="$(_decimal_diff_uint "${_rtotal:-0}" "${_RTOTAL_BEFORE:-0}")"
    			_speed_debug_log "REMOTE_TOTAL_AFTER subdir=$_subdir before=${_RTOTAL_BEFORE:-0} after=${_rtotal:-0} delta=$_rnew mode=r309-bigint-safe"
    			local _remote_delta_label="本次備份"
    			# r53: 若本輪 remote_stream 全 fast-skip 但同時執行遠端孤兒備份刪除，
    			# 遠端總大小差異來自孤兒清理，不應標示為「基礎檔案更新」。
    			if [[ -s $TMPDIR/.remote_orphan_cleanup_removed ]]; then
    				_remote_delta_label="遠端孤兒備份清理後總大小"
    				_speed_debug_log "REMOTE_TOTAL_DELTA_LABEL mode=remote_orphan_cleanup removed=$(cat "$TMPDIR/.remote_orphan_cleanup_removed" 2>/dev/null) delta=$_rnew"
    			# r47: 若本輪所有應用都被 remote fast-skip 折疊，app payload/app_details 沒有實際重備份；
    			# 仍可能因 wifi/MT 等附加檔上傳而改變遠端總大小；restore_settings.conf 已改為本地生成不上傳。
    			# 此時不要顯示「本次備份增加/減少」，避免誤解為應用資料有重打包。
    			elif [[ -f $TMPDIR/.stream_all_apps_fast_skipped && ! -s $TMPDIR/.changed_apps ]]; then
    				_remote_delta_label="遠端基礎檔案更新後總大小"
    				_speed_debug_log "REMOTE_TOTAL_DELTA_LABEL mode=infra_only_all_apps_fast_skip delta=$_rnew"
    			fi
    			case $_rnew in
    			-*) echoRgb "${_remote_delta_label}減少 $(size "${_rnew#-}")" "3" ;;
    			0)  echoRgb "文件大小未改變" "3" ;;
    			*)  echoRgb "${_remote_delta_label}增加 $(size "$_rnew")" "3" ;;
    			esac
    		fi
		fi
		# r118: .stream_stage 先保留到 JSON 健全度檢查完成。
		# 流式模式每個 app 的 app_details.json 是本輪剛生成並已由 managed PUT 回 2xx；
		# 預設直接驗證本地 staged JSON，避免每 App 再遠端 GET 一次造成「一行一行」體感卡頓。
		# 方案A: 最後仍只清理 TMPDIR 暫存區 (絕不碰用戶既有的本地 $Backup 備份)。
		# 遠端json健全度檢查: 流式模式每個app上傳完就已即時上傳json, 此處對本次變更的app做收尾驗證
		if [[ -s "$(_appdetails_bundle_preupload_ok_file)" ]]; then
			local _pre_ok
			_pre_ok="$(cat "$(_appdetails_bundle_preupload_ok_file)" 2>/dev/null)"
			_speed_debug_log "STREAM_JSON_HEALTH_SKIP reason=appdetails-bundle-preupload-checked count=${_pre_ok:-0} mode=single-stage-r286"
			echoRgb "JSON健全度檢查已於 bundle 上傳前通過 ${_pre_ok:-0}/${_pre_ok:-0}" "1"
		elif [[ -s $TMPDIR/.changed_apps ]]; then
			echoRgb "—————— 備份後 JSON 結構驗證 ——————" "3"
			local _ra _rfile _jchk_total _jchk_i=1 _jchk_sorted="$TMPDIR/.stream_json_check_apps" _jinvalid=0 _jmissing=0 _jok=0 _jtrusted_batch=0
			sort -u "$TMPDIR/.changed_apps" > "$_jchk_sorted"
			_jchk_total="$(grep -vc '^$' "$_jchk_sorted")"
			# r263: trusted-fast 預設不再逐 App 做 stat/progress；本輪 app_details.json 已由 managed PUT 成功記錄確認。
			# 需要逐檔/遠端/深度驗證時，可設 SPEEDBACKUP_STREAM_HEALTH_TRUSTED_FAST=0、
			# SPEEDBACKUP_STREAM_HEALTH_REMOTE_VERIFY=1 或 SPEEDBACKUP_STREAM_HEALTH_DEEP_VERIFY=1。
			case "${SPEEDBACKUP_STREAM_HEALTH_REMOTE_VERIFY:-0}" in 1|true|TRUE|yes|YES|on|ON) _jtrusted_batch=0 ;; *)
				case "${SPEEDBACKUP_STREAM_HEALTH_TRUSTED_FAST:-1}" in 0|false|FALSE|no|NO|off|OFF|disable|DISABLE) _jtrusted_batch=0 ;; *)
					case "${SPEEDBACKUP_STREAM_HEALTH_DEEP_VERIFY:-0}" in 1|true|TRUE|yes|YES|on|ON) _jtrusted_batch=0 ;; *) _jtrusted_batch=1 ;; esac ;;
				esac ;;
			esac
			if [[ $_jtrusted_batch = 1 ]]; then
				_jok="$_jchk_total"
				_speed_debug_log "STREAM_JSON_HEALTH_TRUSTED_FAST_BATCH_OK total=$_jchk_total source=appdetails-bundle mode=no-parse-no-stat bundle=app_details_bundle.tar.zst"
				echoRgb "JSON健全度檢查快速通過 $_jchk_total/$_jchk_total" "1"
			else
    			while read -r _ra; do
    				[[ -z $_ra ]] && continue
    				if _remote_netwatch_mark_remote_fatal "remote_health_stream_enter" "$_ra"; then
    					_speed_debug_log "REMOTE_HEALTH_STREAM_ABORT reason=remote_netwatch_changed app=$_ra"
    					break
    				fi
    				local _rk="${_ra%% *}" _rfile_tmp=0
    				[[ -z $_rk ]] && _rk="$_ra"
    				_speedbackup_progress_step "$_jchk_i" "$_jchk_total" "檢查本輪 JSON $_ra" "stream_json_health_verify"
    				if [[ ${SPEEDBACKUP_STREAM_HEALTH_REMOTE_VERIFY:-0} != 1 && -s "$TMPDIR/.stream_stage/$_rk/app_details.json" ]]; then
    					_rfile="$TMPDIR/.stream_stage/$_rk/app_details.json"
    					_speed_debug_log "STREAM_JSON_HEALTH_LOCAL app=$_ra key=$_rk file=$_rfile reason=managed-put-trusted"
    					case "${SPEEDBACKUP_STREAM_HEALTH_TRUSTED_FAST:-1}" in
    					0|false|FALSE|no|NO|off|OFF|disable|DISABLE)
    						if _remote_appdetails_json_ok "$_rfile"; then
    							let _jok++
    						else
    							let _jinvalid++
    							_remote_health_record_appdetails_drop "$_ra" "$_rk" invalid "$_rfile"
    						fi ;;
    					*)
    						# r260: 本輪 app_details.json 由 tools 生成且 managed PUT 已回 2xx；預設信任 staged 檔存在，避免 100% 後每 App 再 jq/required-meta。
    						let _jok++
    						_speed_debug_log "STREAM_JSON_HEALTH_TRUSTED_FAST_OK app=$_ra key=$_rk reason=managed-put-trusted-local-json mode=no-parse" ;;
    					esac
    					case "${SPEEDBACKUP_STREAM_HEALTH_DEEP_VERIFY:-0}" in
    					1|true|TRUE|yes|YES|on|ON)
    						if _remote_appdetails_json_ok "$_rfile"; then
    							_json_health_check "$_rfile" "$_ra (本輪生成)"
    						else
    							_speed_debug_log "STREAM_JSON_HEALTH_DEEP_VERIFY_INVALID app=$_ra key=$_rk file=$_rfile"
    						fi ;;
    					*)
    						_speed_debug_log "STREAM_JSON_HEALTH_DEEP_SKIP app=$_ra key=$_rk reason=managed-put-trusted-local-json mode=trusted-fast" ;;
    					esac
    				else
    					_rfile="$TMPDIR/.remote_health_check_$$.json"
    					_rfile_tmp=1
    					_speed_debug_log "STREAM_JSON_HEALTH_REMOTE_GET app=$_ra key=$_rk strict=${SPEEDBACKUP_STREAM_HEALTH_REMOTE_VERIFY:-0}"
    					if remote_download_single_file "$_rk/app_details.json" "$_rfile" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} && [[ -s $_rfile ]]; then
    						if _remote_appdetails_json_ok "$_rfile"; then
    							let _jok++
    							_json_health_check "$_rfile" "$_ra (遠端)"
    						else
    							let _jinvalid++
    							_remote_health_record_appdetails_drop "$_ra" "$_rk" invalid "$_rfile"
    						fi
    					else
    						let _jmissing++
    						_remote_health_record_appdetails_drop "$_ra" "$_rk" missing
    					fi
    				fi
    				[[ $_rfile_tmp = 1 ]] && rm -f "$_rfile" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
    				let _jchk_i++
    			done < "$_jchk_sorted"
			fi
			rm -f "$_jchk_sorted"
			echoRgb "檢查完成 $((_jok+_jinvalid+_jmissing))/$_jchk_total" "1"
			JSON_HEALTH_REPORT_ALWAYS=1
			JSON_HEALTH_CHECKED_COUNT="$_jchk_total"
			JSON_HEALTH_INVALID_COUNT="$_jinvalid"
			JSON_HEALTH_MISSING_COUNT="$_jmissing"
			_json_health_report
		fi
		rm -rf "$TMPDIR/.stream_stage" "$TMPDIR/.stream_appdetails_bundle" "$TMPDIR/.appdetails_bundle_extract_remote_json" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
		_remote_netwatch_finish
		return 0
	fi
	if [[ $backup_has_changes = 0 ]]; then
		if [[ $remote_upload_per_app = 1 ]]; then
			echoRgb "逐應用上傳模式：無備份變更，只上傳依賴文件" "2"
		else
			echoRgb "無備份變更，只上傳依賴文件" "2"
		fi
		# 設置標記，跳過應用數據上傳
		REMOTE_SKIP_APPDATA=1
	elif [[ $remote_upload_per_app = 0 && -s "$TMPDIR/.changed_apps" ]]; then
		# 非逐應用上傳模式，但有變更的應用，只上傳變更的應用
		local changed_apps changed_count
		changed_apps="$(sort -u "$TMPDIR/.changed_apps" | tr '\n' ' ')"
		changed_count="$(sort -u "$TMPDIR/.changed_apps" | awk 'END{print NR}')"
		[[ -n $remote_type ]] && echoRgb "僅上傳變更的應用 (共 $changed_count 個): $changed_apps" "2"
		# 設置 REMOTE_APPLIST 為變更的應用列表
		REMOTE_APPLIST="$(_applist_home_last_text "$(sort -u "$TMPDIR/.changed_apps")" "remote_changed_apps")"
	fi
	case $remote_type in
	webdav) upload_remote "webdav" ;;
	smb) upload_remote "smb" ;;
	*)
		_remote_netwatch_finish
		return 0
		;;
	esac
	if _remote_stream_fatal_active || _remote_netwatch_mark_remote_fatal "remote_cleanup_after_upload" "post_upload"; then
		echoRgb "遠端操作已中斷，略過備份後 JSON 結構驗證" "0"
		_speed_debug_log "REMOTE_CLEANUP_NONSTREAM_FATAL_SKIP $(_remote_stream_fatal_summary 2>/dev/null)"
		REMOTE_SKIP_APPDATA=0
		unset REMOTE_APPLIST
		_remote_netwatch_finish
		return 0
	fi
	REMOTE_SKIP_APPDATA=0
	# 遠端json健全度檢查: 下載剛上傳的 app_details.json 逐一驗證 (確保傳輸/合併過程沒有損壞欄位)
	# 優先用 .changed_apps (本次實際變更上傳的app, 覆蓋面較廣); 無則 fallback REMOTE_APPLIST
	local _health_src
	if [[ -s $TMPDIR/.changed_apps ]]; then
		_health_src="$(sort -u "$TMPDIR/.changed_apps")"
	else
		_health_src="$REMOTE_APPLIST"
	fi
	if [[ -n $_health_src ]]; then
		local _ra _rfile _jchk_total _jchk_i=1
		_jchk_total="$(echo "$_health_src" | grep -vc '^$')"
		while read -r _ra; do
			[[ -z $_ra ]] && continue
			if _remote_netwatch_mark_remote_fatal "remote_health_nonstream_enter" "$_ra"; then
				_speed_debug_log "REMOTE_HEALTH_NONSTREAM_ABORT reason=remote_netwatch_changed app=$_ra"
				break
			fi
			local _rk="${_ra%% *}"
			[[ -z $_rk ]] && _rk="$_ra"
			_speedbackup_progress_step "$_jchk_i" "$_jchk_total" "檢查遠端 JSON $_ra" "nonstream_json_health_verify"
			_rfile="$TMPDIR/.remote_health_check_$$.json"
			if remote_download_single_file "$_rk/app_details.json" "$_rfile" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} && [[ -s $_rfile ]]; then
				if _remote_appdetails_json_ok "$_rfile"; then
					_json_health_check "$_rfile" "$_ra (遠端)"
				else
					_remote_health_record_appdetails_drop "$_ra" "$_rk" invalid "$_rfile"
				fi
			fi
			rm -f "$_rfile" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
			let _jchk_i++
		done <<EOF4
$_health_src
EOF4
		echoRgb "檢查完成 $((_jchk_i-1))/$_jchk_total" "1"
		_json_health_report
	fi
	unset REMOTE_APPLIST
	_remote_netwatch_finish
}
# 秒 -> Nx天 Ny小時 Nz分鐘 Ns秒 (省略前導 0 單位)
hms() {
	awk -v t="$1" 'BEGIN{
		t=int(t); d=int(t/86400); h=int((t%86400)/3600); m=int((t%3600)/60); s=t%60
		o=""
		if(d>0) o=o d"天 "
		if(o!="" || h>0) o=o h"小時 "
		if(o!="" || m>0) o=o m"分鐘 "
		o=o s"秒"
		printf "%s", o
	}'
}

_speedbackup_device_facts_json_field() {
	local _file="$1" _key="$2"
	[[ -s $_file ]] || return 1
	jq -r --arg k "$_key" '.[$k] // empty' "$_file" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} | head -1
}

_speedbackup_device_facts_collect() {
	local _out _rc _dbg
	_out="${TMPDIR:-/data/local/tmp}/.speedbackup_device_facts_${$}_$RANDOM.json"
	# r395: Show_boottime/啟動畫面會在後段 _dex_raw helper 定義前執行。
	# 這裡必須直接走較早已定義的 _dex_exec_unfiltered，避免 mksh 報
	# `_dex_raw: inaccessible or not found`，造成 deviceFacts 永遠 fallback。
	_dex_exec_unfiltered com.xayah.dex.HiddenApiUtil deviceFacts >"$_out" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	_rc=$?
	if [[ $_rc = 0 ]] && jq -e '.schema=="speedbackup.device_facts.v1"' "$_out" >/dev/null 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}; then
		if [[ -d ${SPEED_DEBUG_RUN_DIR:-} ]]; then
			cp -f "$_out" "$SPEED_DEBUG_RUN_DIR/device_facts.json" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} || true
		fi
		_dbg="marketZh=$(_speedbackup_device_facts_json_field "$_out" marketNameZh) rawModel=$(_speedbackup_device_facts_json_field "$_out" model) source=$(_speedbackup_device_facts_json_field "$_out" modelNameSource) confidence=$(_speedbackup_device_facts_json_field "$_out" modelNameConfidence) matchedField=$(_speedbackup_device_facts_json_field "$_out" matchedField) matchedKey=$(_speedbackup_device_facts_json_field "$_out" matchedKey) dbEntries=$(_speedbackup_device_facts_json_field "$_out" modelDbEntryCount) dbLines=$(_speedbackup_device_facts_json_field "$_out" modelDbSourceLines)"
		_speed_debug_log "DEVICE_FACTS_DEX_OK schema=speedbackup.device_facts.v1 $_dbg mode=r416"
		printf '%s\n' "$_out"
		return 0
	fi
	_speed_debug_log "DEVICE_FACTS_DEX_FAIL rc=$_rc fallback=getprop mode=r416"
	rm -f "$_out" 2>/dev/null || true
	return 1
}

# 運作時間 + 深度睡眠 (uptime vs CLOCK_MONOTONIC 差 = 深睡時長)
Show_boottime() {
	local BOOT MONO
	BOOT=$(awk '{print $1; exit}' /proc/uptime)
	MONO=$(awk '/now at/{print $3; exit}' /proc/timer_list 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null})
	if [[ -z $MONO ]]; then
		hms "$BOOT"
		return
	fi
	awk -v b="$BOOT" -v m="$MONO" 'BEGIN{
		mono=m/1e9; susp=b-mono; if(susp<0)susp=0
		printf "%.0f %.0f %.1f\n", b, susp, susp/b*100
	}' | while read -r rt sp pct; do
		printf "%s\n -深度睡眠:%s (%s%%)" "$(hms "$rt")" "$(hms "$sp")" "$pct"
	done
}
