_appstate_capability_diagnose_transport() {
	local _uout _uerr _utxt _urc _root_err _root_out _root_txt _ver
	_uout="$TMPDIR/.appstate_unixsock_diag_out_$$"
	_uerr="$TMPDIR/.appstate_unixsock_diag_err_$$"
	if [[ -z ${EVENT_UNIXSOCK_BIN:-} || ! -x ${EVENT_UNIXSOCK_BIN:-} ]]; then
		_appstate_capability_fail_set transport native_binary "unixsock=missing-or-not-executable path=${EVENT_UNIXSOCK_BIN:-unknown}" "配套二進制 unixsock 不存在或不可執行；請先檢查 /data/backup_tools/unixsock、SHA、ABI、chmod 與 SELinux"
		rm -f "$_uout" "$_uerr" 2>/dev/null
		return 0
	fi
	command "$EVENT_UNIXSOCK_BIN" --version > "$_uout" 2> "$_uerr"
	_urc=$?
	_utxt="$(cat "$_uout" "$_uerr" 2>/dev/null | _appstate_diag_oneline)"
	_ver="$(sed -n '1p' "$_uout" 2>/dev/null)"
	if [[ $_urc != 0 ]] || ! { case "$_ver" in *stream-relay*|*stream-framed*|*plain-lines-single-eof*|unixsock\ 2.[3-9]*) true ;; *) false ;; esac; }; then
		if _appstate_text_has_native_link_error "$_utxt"; then
			_appstate_capability_fail_set transport native_binary "unixsock_rc=$_urc unixsock_error=${_utxt:-empty}" "配套 native 二進制載入失敗；優先檢查 unixsock/procwait/filewatch/netwatch/uidexec 是否出現 GNU_RELRO/Out_of_memory/ABI/權限問題"
		else
			_appstate_capability_fail_set transport native_binary "unixsock_rc=$_urc unixsock_version=${_ver:-empty} unixsock_error=${_utxt:-empty}" "unixsock relay 不可用或版本不符；需要 stream-framed/stream-relay 或 2.3+ plain-lines-single-eof；請換正確 native helpers 後再跑 dex_check"
		fi
		rm -f "$_uout" "$_uerr" 2>/dev/null
		return 0
	fi
	rm -f "$_uout" "$_uerr" 2>/dev/null
	_root_err="$(_speed_debug_log_path root_daemon_stderr.log)"
	_root_out="$TMPDIR/.speedbackup_root_daemon_out"
	_root_txt="$(cat "$_root_err" "$_root_out" 2>/dev/null | tail -n 20 | _appstate_diag_oneline)"
	if _appstate_text_has_native_link_error "$_root_txt"; then
		_appstate_capability_fail_set transport native_binary "rootdaemon_native_error=${_root_txt:-empty}" "RootDaemon 啟動鏈碰到 native/linker 錯誤；請檢查 app_process/配套二進制與 debug/root_daemon_stderr.log"
	elif _appstate_text_has_dex_runtime_error "$_root_txt"; then
		_appstate_capability_fail_set transport dex_runtime "rootdaemon_dex_error=${_root_txt:-empty}" "Dex RootDaemon 啟動失敗；請檢查 classes.dex 是否混版、損壞或未重編"
	else
		_appstate_capability_fail_set transport dex_runtime "unixsock=ok rootdaemon=not-ready result=${_APPSTATE_RESULT_CODE:-unknown} name=${_APPSTATE_RESULT_NAME:-unknown} rc=125" "AF_UNIX relay 可用但 RootDaemon/AppState transport 不可用；請看 speed_debug/root_daemon_stderr.log 與 appstate_capabilities 相關檔案"
	fi
}

_root_appstate_call() {
	local _command="$1" _in="$2" _out="$3" _rc
	[[ -n $_command && -f $_in && -n $_out ]] || return 2
	_root_daemon_call_appstate "$_command" "$_in" "$_out"
	_rc=$?
	[[ $_rc = 125 ]] && _speed_debug_log "ROOT_APPSTATE_REQUIRED_NO_FALLBACK command=$_command"
	return $_rc
}

_dex_capabilities_contract_ok() {
	local _out="$1"
	[[ -s $_out ]] || return 1
	jq -e '
		. as $root |
		def cap($n): any($root.capabilities[]?; .name == $n and .enabled == true);
		($root.schemaVersion == 2) and
		((($root.daemonProtocolVersion // 0)) >= 1) and
		((($root.dexVersion // "")) | startswith("v2.6.")) and
		([
			"dex.capabilities.v1",
			"dex.machine_stdout.v1",
			"dex.root_unified_daemon.v1",
			"hiddenapi.daemon.af_unix.v1",
			"hiddenapi.force_stop_package_batch.daemon.v1",
			"dex.app_inventory.snapshot.v1",
			"dex.app_inventory.pkg_uid.single.v1",
			"dex.app_inventory.package_status.single.v1",
			"dex.app_inventory.getlist_onecall.v1",
			"dex.app_inventory.package_facts.batch.v1",
			"dex.pm.pre_restore_package_state.batch.v1",
			"dex.pm.installer_context_facts.v1",
			"dex.pm.post_install_facts_batch.v1",
			"dex.settings.exec_shim.v1",
			"dex.pm.visible_after_install.v1",
			"dex.framework_facts.batch.v1",
			"appstate.snapshot.batch.v2",
			"appstate.restore.batch.v4",
			"appstate.verify.batch.v4",
			"appstate.verify.vendor_classification.dex.v1",
			"appstate.daemon.af_unix.v1",
			"appstate.structured_result_codes.v2",
			"appstate.ssaid.integrated.v1",
			"appstate.special_access.integrated.v1",
			"appstate.scoped_appops_fields.v1",
			"appstate.default_home.v1",
			"appstate.foreground_state.batch.v1",
			"appstate.foreground_list.json.v1",
			"dex.process_observer.global_daemon.v1",
			"dex.process_observer.target_lifecycle.v1",
			"dex.process_observer.batch_watchset.v1",
			"dex.process_observer.batch_stop_safe.v1",
			"dex.process_observer.taskstack_package_guard.v1",
			"dex.app_wake_block.persistent_restore.v1",
			"dex.uid_net_block.persistent_restore.v1",
			"dex.cgroup_freezer.lifecycle.v1",
			"dex.cgroup_freezer.persistent_batch_session.v1",
			"dex.cgroup_freezer.native_package_atomic.v1",
			"dex.cgroup_freezer.native_package_kill_live_rescan.v1",
			"dex.cgroup_freezer.native_thaw_uid_emergency.v1",
			"dex.cgroup_freezer.daemon_parent_control.v1",
			"dex.display_power.root_daemon.v1",
			"webdav.rel_only.v1",
			"webdav.relpath.strict_gate.v1",
			"webdav.managed_put.v1",
			"webdav.managed_list_classify.v1",
			"webdav.managed_batch_put_with_parents.v1",
			"webdav.propfind.no_cache.v1",
			"webdav.stream_heartbeat_error_kind.dex.v1",
			"dex.smb.target_probe.v1",
			"notification.daemon.af_unix.v1",
			"notification.inline_small_icon.v1"
		] | all(.[]; cap(.)))
	' "$_out" >/dev/null 2>&1
}
_dex_capabilities_version() {
	local _out="$1"
	[[ -s $_out ]] || { printf 'unknown\n'; return 1; }
	jq -r '.dexVersion // "unknown"' "$_out" 2>/dev/null | head -n 1
}
_dex_capabilities_enabled_summary() {
	local _out="$1"
	[[ -s $_out ]] || { printf 'unknown\n'; return 1; }
	jq -r '[.capabilities[]? | select(.enabled==true) | .name] | join(",")' "$_out" 2>/dev/null | cut -c1-600
}

# 透過 unified root daemon / AppState namespace 驗證機器可讀核心能力。
# 不檢查精確 Dex version/build/patch，只看目前 tools 主流程必要 capabilities。
_appstate_capabilities_check() {
	case ${_APPSTATE_CAPABILITY_STATE:-0} in
	1) return 0 ;;
	-1) return 1 ;;
	esac
	local _in="$TMPDIR/.appstate_cap_in_$$" _out="$TMPDIR/.appstate_cap_out_$$"
	: > "$_in" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} || { _APPSTATE_CAPABILITY_STATE=-1; return 1; }
	local _cap_rc
	_root_appstate_call capabilities "$_in" "$_out"
	_cap_rc=$?
	if [[ $_cap_rc != 0 ]]; then
		_speed_debug_log "APPSTATE_CAPABILITIES_FAIL stage=transport result=${_APPSTATE_RESULT_CODE:-unknown} name=${_APPSTATE_RESULT_NAME:-unknown} rc=$_cap_rc"
		if [[ $_cap_rc = 125 ]]; then
			_appstate_capability_diagnose_transport
		else
			_appstate_capability_fail_set appstate dex_appstate "result=${_APPSTATE_RESULT_CODE:-unknown} name=${_APPSTATE_RESULT_NAME:-unknown} rc=$_cap_rc" "RootDaemon 已回應但 AppState capabilities 回傳非 OK；偏向 Dex/AppState runtime 或 classes.dex 混版"
		fi
		rm -f "$_in" "$_out" 2>/dev/null
		_APPSTATE_CAPABILITY_STATE=-1
		return 1
	fi
	if _dex_capabilities_contract_ok "$_out"; then
		_APPSTATE_CAPABILITY_STATE=1
		[[ -n ${SPEED_DEBUG_RUN_DIR:-} && -d ${SPEED_DEBUG_RUN_DIR:-} ]] && cp -f "$_out" "$SPEED_DEBUG_RUN_DIR/appstate_capabilities.json" 2>/dev/null
		_speed_debug_log "APPSTATE_CAPABILITIES_OK dex=core-capability-gated schema=2 protocol=1 no-exact-version-build"
		rm -f "$_in" "$_out" 2>/dev/null
		return 0
	fi
	[[ -n ${SPEED_DEBUG_RUN_DIR:-} && -d ${SPEED_DEBUG_RUN_DIR:-} ]] && cp -f "$_out" "$SPEED_DEBUG_RUN_DIR/appstate_capabilities_invalid.json" 2>/dev/null
	local _dexv _cap_summary _missing_caps
	_dexv="$(_dex_capabilities_version "$_out")"
	_cap_summary="$(_dex_capabilities_enabled_summary "$_out")"
	_missing_caps="$(_appstate_capabilities_missing_summary "$_out")"
	_speed_debug_log "APPSTATE_CAPABILITIES_FAIL stage=contract dex=${_dexv:-unknown} missing_caps=${_missing_caps:-unknown} enabled_caps=${_cap_summary:-unknown}"
	_appstate_capability_fail_set contract dex_contract "dex=${_dexv:-unknown} missing=${_missing_caps:-unknown}" "classes.dex 與 tools.sh capability 契約不匹配；請重編/替換正確 Dex，缺少 capability 見 appstate_capabilities_invalid.json"
	rm -f "$_in" "$_out" 2>/dev/null
	_APPSTATE_CAPABILITY_STATE=-1
	return 1
}

# 依賴 unified root daemon；只檢查實際需要的核心 capability，不再用 Dex 版本/build 判斷混版。
_appstate_snapshot_batch_raw() {
	local _pkg_file="$1" _out="$2" _rc
	[[ -s $_pkg_file && -n $_out ]] || return 1
	_appstate_capabilities_check || return 2
	if _root_appstate_call snapshotAppStateBatch "$_pkg_file" "$_out"; then
		return 0
	fi
	# capabilities 已通過後 daemon request 仍失敗，屬 transport/runtime 錯誤；不再改走另一顆 JVM 掩蓋問題。
	_rc=$?
	_speed_debug_log "APPSTATE_SNAPSHOT_FAIL result=${_APPSTATE_RESULT_CODE:-unknown} name=${_APPSTATE_RESULT_NAME:-unknown} rc=$_rc"
	return 1
}
# AppState NDJSON 解析集中入口：所有 restore/verify/foreground/snapshot 結果讀取都走這裡，避免 jq 條件散落。
_appstate_ndjson_has_summary() {
	local _file="$1" _cmd="$2"
	[[ -s $_file && -n $_cmd ]] || return 1
	jq -s -e --arg cmd "$_cmd" 'any(.[]; .recordType=="summary" and .command==$cmd)' "$_file" >/dev/null 2>&1
}

# r336: verifyAppStateBatch may intentionally return structured code 61 when the whole
# chunk contains only vendor/platform constrained rows.  That is a valid Dex
# classification, not a transport/protocol failure.  Accept it when the NDJSON
# summary is present, then let _appstate_ndjson_summarize() count vendor rows.
_appstate_verify_batch_accept() {
	local _out="$1" _rc="${2:-1}"
	[[ -s $_out ]] || return 1
	_appstate_ndjson_has_summary "$_out" verifyAppStateBatch || return 1
	[[ $_rc = 0 ]] && return 0
	if [[ ${_APPSTATE_RESULT_CODE:-} = 61 || ${_APPSTATE_RESULT_NAME:-} = VERIFY_VENDOR_CONSTRAINED ]]; then
		_speed_debug_log "APPSTATE_VERIFY_VENDOR_CONSTRAINED_ACCEPT rc=$_rc code=${_APPSTATE_RESULT_CODE:-unknown} name=${_APPSTATE_RESULT_NAME:-unknown} mode=r370"
		return 0
	fi
	if jq -s -e '
		any(.[]; .recordType=="summary" and .command=="verifyAppStateBatch" and .result.name=="VERIFY_VENDOR_CONSTRAINED") or
		any(.[]; .recordType=="verify" and .result.name=="VERIFY_VENDOR_CONSTRAINED")
	' "$_out" >/dev/null 2>&1; then
		_speed_debug_log "APPSTATE_VERIFY_VENDOR_CONSTRAINED_ACCEPT rc=$_rc code=${_APPSTATE_RESULT_CODE:-unknown} name=${_APPSTATE_RESULT_NAME:-unknown} source=ndjson mode=r370"
		return 0
	fi
	return 1
}

_appstate_ndjson_has_snapshot_ok_summary() {
	local _file="$1"
	[[ -s $_file ]] || return 1
	jq -s -e '
		any(.[];
			.recordType == "summary" and
			.command == "snapshotAppStateBatch" and
			.schemaVersion == 2 and
			(.result.name == "OK" or .result.name == "PARTIAL"))
	' "$_file" >/dev/null 2>&1
}

_appstate_ndjson_snapshot_to_map_files() {
	local _ndjson="$1" _states="$2" _errors="$3"
	[[ -s $_ndjson && -n $_states && -n $_errors ]] || return 1
	jq -r '
		select(.recordType=="snapshot" and (.result.name=="OK" or .result.name=="PARTIAL"))
		| select((.packageName // "") != "")
		| [.packageName, (.|tojson)] | @tsv
	' "$_ndjson" > "$_states" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} || return 1
	jq -r '
		select((.recordType=="snapshot" and .result.name != "OK") or .recordType=="error")
		| [(.packageName // "-"), (.result.name // "UNKNOWN"), (.result.message // ""), ((.errors // [])|tojson)] | @tsv
	' "$_ndjson" > "$_errors" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} || return 1
	return 0
}

_appstate_ndjson_summarize() {
	local _file="$1" _kind="$2" _issues="$3" _tmp _stats _tag _n
	_APPSTATE_NDJSON_OK=0
	_APPSTATE_NDJSON_WARN=0
	_APPSTATE_NDJSON_FAILED=0
	_APPSTATE_NDJSON_VENDOR=0
	[[ -s $_file ]] || return 1
	case $_kind in restore) _tag="RESTORE" ;; verify) _tag="VERIFY" ;; *) return 2 ;; esac
	_tmp="$(_webdav_tmp_path appstate_${_kind}_summary)"
	if ! jq -rs -r --arg kind "$_kind" --arg tag "$_tag" '
		def mode_is($v; $n): (($v // "__null__")|tostring) == ($n|tostring);
		def opnum($v): (($v // -1)|tonumber? // -1);
		def vendor_verify_mismatch($m):
			($m.path // "") as $p |
			($m.expected // null) as $e |
			($m.actual // null) as $a |
			($m.message // "") as $msg |
			(
				# MIUI/HyperOS: restricted settings AppOp is often controlled by vendor policy;
				# the framework keeps effective mode at default or prunes the explicit record.
				(($p == "otherAppOps.119.mode") and mode_is($e;0) and mode_is($a;3) and ($msg == "effective mode mismatch")) or
				(($p == "otherAppOps.119") and ($a == null) and (opnum($e.op) == 119) and (($e.publicName // "") == "android:access_restricted_settings") and ($msg == "missing AppOp record")) or
				# MIUI/HyperOS may omit legacy_storage as a persisted AppOp record after restore.
				(($p == "otherAppOps.87") and ($a == null) and (opnum($e.op) == 87) and (($e.publicName // "") == "android:legacy_storage") and ($msg == "missing AppOp record")) or
				# Broad file access special access is subject to vendor and platform effective-policy gates.
				(($p == "specialAccess.MANAGE_EXTERNAL_STORAGE.mode") and mode_is($e;0) and mode_is($a;3) and ($msg == "effective mode mismatch")) or
				# MIUI battery policy may reset RUN_IN_BACKGROUND effective mode after restore.
				(($p == "batterySettings.RUN_IN_BACKGROUND.mode") and mode_is($e;0) and mode_is($a;3) and ($msg == "effective mode mismatch")) or
				# Some ROMs prune legacy runtime/AppOp records that are not user-visible anymore.
				(($p == "permissions.android.permission.GET_ACCOUNTS") and ($a == null) and (($e.name // "") == "android.permission.GET_ACCOUNTS") and ($msg == "missing permission record")) or
				# Vendor audio/media effective mode can be foreground-derived rather than stored as requested.
				(($p == "otherAppOps.36.mode") and mode_is($e;1) and mode_is($a;4) and ($msg == "effective mode mismatch"))
			);
		def dex_vendor_row:
			((.result.name // "") == "VERIFY_VENDOR_CONSTRAINED");
		def vendor_only_row:
			dex_vendor_row or
			(((.result.name // "") == "VERIFY_MISMATCH") and
			(((.mismatches // []) | length) > 0) and
			(all((.mismatches // [])[]; vendor_verify_mismatch(.))));
		def vendor_issue_detail:
			[(.mismatches // [])[] | (.path // "unknown")] | unique | join(",");
		[.[] | select(.recordType==$kind)] as $rows |
		if $kind=="restore" then
			# r371: STATS field order is OK, VENDOR, WARN, FAILED for both restore/verify.
			# r370 emitted OK, WARN, FAILED, 0 here, so the shell reader stored partial
			# in _APPSTATE_NDJSON_VENDOR and printed 部分=0 even when Dex summary was PARTIAL.
			(["STATS", ($rows|map(select(.result.name=="OK"))|length), 0,
			  ($rows|map(select(.result.name=="PARTIAL" or .result.name=="VERIFY_MISMATCH"))|length),
			  ($rows|map(select(.result.name!="OK" and .result.name!="PARTIAL" and .result.name!="VERIFY_MISMATCH"))|length)] | @tsv),
			($rows[] | select(.result.name!="OK") |
			 "\($tag)\t\(.packageName)\t\(.result.name)\t\(.result.message // "")")
		else
			(["STATS", ($rows|map(select(.result.name=="OK"))|length),
			  ($rows|map(select(vendor_only_row))|length),
			  ($rows|map(select(.result.name=="VERIFY_MISMATCH" and (vendor_only_row|not)))|length),
			  ($rows|map(select(.result.name!="OK" and .result.name!="VERIFY_MISMATCH" and .result.name!="VERIFY_VENDOR_CONSTRAINED"))|length)] | @tsv),
			($rows[] | select(.result.name!="OK") |
			 if vendor_only_row then
				"VERIFY_VENDOR\t\(.packageName)\tVENDOR_CONSTRAINED\t\((.mismatches // [])|length)\t\((.vendorConstraintPaths // [] | join(",")) // vendor_issue_detail)"
			 else
				"\($tag)\t\(.packageName)\t\(.result.name)\t\((.mismatches // [])|length)"
			 end)
		end
	' "$_file" > "$_tmp" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}; then
		rm -f "$_tmp" 2>/dev/null
		return 1
	fi
	_stats="$(sed -n '1p' "$_tmp" 2>/dev/null)"
	IFS="$(printf '\t')" read -r _tag _APPSTATE_NDJSON_OK _APPSTATE_NDJSON_VENDOR _APPSTATE_NDJSON_WARN _APPSTATE_NDJSON_FAILED <<EOF
$_stats
EOF
	[[ $_tag = STATS ]] || { rm -f "$_tmp" 2>/dev/null; return 1; }
	for _n in "$_APPSTATE_NDJSON_OK" "$_APPSTATE_NDJSON_VENDOR" "$_APPSTATE_NDJSON_WARN" "$_APPSTATE_NDJSON_FAILED"; do
		case $_n in ''|*[!0-9]*) rm -f "$_tmp" 2>/dev/null; _APPSTATE_NDJSON_OK=0; _APPSTATE_NDJSON_VENDOR=0; _APPSTATE_NDJSON_WARN=0; _APPSTATE_NDJSON_FAILED=0; return 1 ;; esac
	done
	[[ -n $_issues ]] && sed -n '2,$p' "$_tmp" >> "$_issues" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	rm -f "$_tmp" 2>/dev/null
	return 0
}
_appstate_ndjson_get_foreground_active() {
	local _file="$1" _pkg="$2"
	[[ -s $_file && -n $_pkg ]] || { printf '\n'; return 1; }
	jq -r --arg p "$_pkg" 'select(.recordType=="foregroundState" and .packageName==$p) | .active' "$_file" 2>/dev/null | tail -n 1
}
_appstate_ndjson_foreground_active_packages() {
	local _file="$1"
	[[ -s $_file ]] || return 1
	jq -r 'select(.recordType=="foregroundState" and .active==true) | .packageName' "$_file" 2>/dev/null | awk 'NF && !seen[$0]++'
}

_appstate_snapshot_json_ok() {
	local _file="$1"
	[[ -s $_file ]] || return 1
	jq -e 'type=="object" and .schemaVersion==2 and .recordType=="snapshot"' "$_file" >/dev/null 2>&1
}
_appstate_snapshot_persistable_ok() {
	local _file="$1"
	[[ -s $_file ]] || return 1
	jq -e '
		type == "object" and .recordType == "snapshot" and .schemaVersion == 2 and
		.packageName != null and (.permissions|type)=="array" and
		(.specialAccess|type)=="object" and (.otherAppOps|type)=="array" and
		(.batterySettings|type)=="object"
	' "$_file" >/dev/null 2>&1
}
_appstate_ndjson_remove_package_file() {
	local _file="$1" _pkg="$2" _out="$3"
	[[ -s $_file && -n $_pkg && -n $_out ]] || return 1
	jq -c --arg pkg "$_pkg" 'select((.packageName // "") != $pkg)' "$_file" > "$_out" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
}
_appstate_snapshot_ssaid_only_file() {
	local _record="$1" _out="$2"
	[[ -s $_record && -n $_out ]] || return 1
	jq -c 'select(.ssaid != null and (.ssaid|tostring)!="" and (.ssaid|tostring)!="null")' "$_record" > "$_out" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
}


# structured snapshot NDJSON → 既有狀態 maps；只接受 snapshot record，summary/error 不會混入。
_appstate_snapshot_to_maps() {
	local _ndjson="$1" _base _states _errors
	[[ -s $_ndjson ]] || return 1
	_appstate_ndjson_has_snapshot_ok_summary "$_ndjson" || return 1

	_base="$TMPDIR/.appstate_maps_${$}_$RANDOM"
	_states="${_base}.states"
	_errors="${_base}.errors"
	rm -f "$_base"* 2>/dev/null

	# app_state 是唯一持久化資料模型；restore / verify 直接重用這份 canonical snapshot NDJSON。
	_appstate_ndjson_snapshot_to_map_files "$_ndjson" "$_states" "$_errors" || { rm -f "$_base"* 2>/dev/null; return 1; }

	mv -f "$_states" "$TMPDIR/.pkg_appstate" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} || { rm -f "$_base"* 2>/dev/null; return 1; }
	mv -f "$_errors" "$TMPDIR/.appstate_snapshot_errors" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} || { rm -f "$_base"* 2>/dev/null; return 1; }
	_eventwait_output_files_stable_ms appstate_snapshot_maps_ready 50 1200 "$TMPDIR/.pkg_appstate" "$TMPDIR/.appstate_snapshot_errors" >/dev/null 2>&1 || true
	return 0
}

# 設定 dex 取應用名稱用的 locale (export 給 HiddenApiUtil 的 applyLocale 讀)
# 優先序: Shell_LANG 明確指定 > dex getLocale 取系統實際語言 > 退出提示手動設定
case $Shell_LANG in
1) export APP_LABEL_LOCALE="zh-CN" ;;
0) export APP_LABEL_LOCALE="zh-TW" ;;
*)
	# 用 settings 取用戶實際設定的語言 (system_locales, 如 zh-Hant-TW / zh-Hans-CN), 命令列可靠取得
	_syslocale="$(settings get system system_locales 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} | head -1)"
	[[ -z $_syslocale || $_syslocale = null ]] && _syslocale="$(getprop persist.sys.locale)"
	case $_syslocale in
	zh-Hant*|zh_Hant*|zh-TW*|zh_TW*|zh-HK*|zh_HK*|zh-MO*) export APP_LABEL_LOCALE="zh-TW" ;;
	zh-Hans*|zh_Hans*|zh-CN*|zh_CN*|zh-SG*|zh*)            export APP_LABEL_LOCALE="zh-CN" ;;
	*)
		echoRgb "系統語言取得失敗或非中文 (取得: ${_syslocale:-空})" "0"
		echoRgb "dex 將取得英文應用名稱, 可能導致名稱比對/恢復異常" "0"
		echoRgb "請於 backup_settings.conf 設定 Shell_LANG=0 (繁中) 或 1 (簡中)" "3"
		exit 1 ;;
	esac
	;;
esac
# 482/r43: App inventory snapshot — 一次取得 label/pkg/uid/version/source/flag，RootDaemon 內同輪 cache。
_app_inventory_call() {
	local _format="${1:-jsonl}" _filter="${2:-all}" _refresh="${3:-}" _body _out _rc
	_body="$(_webdav_tmp_path root_inventory_args)"
	_out="$(_webdav_tmp_path root_inventory_out)"
	{
		printf '%s\n' "${USER_ID:-${user:-0}}"
		printf '%s\n' "$_format"
		printf '%s\n' "$_filter"
		[[ -n $_refresh ]] && printf '%s\n' "$_refresh"
	} > "$_body"
	_root_daemon_call_file_hot hiddenapi appInventorySnapshot "$_body" "$_out"
	_rc=$?
	if [[ $_rc = 125 ]]; then
		_speed_debug_log "APP_INVENTORY_ROOT_DAEMON_FALLBACK format=$_format filter=$_filter"
		_dex_raw com.xayah.dex.HiddenApiUtil appInventorySnapshot "${USER_ID:-${user:-0}}" "$_format" "$_filter" $_refresh > "$_out"
		_rc=$?
	fi
	cat "$_out" 2>/dev/null
	rm -f "$_body" "$_out" 2>/dev/null
	return $_rc
}

appinventory() { _app_inventory_call "$@"; }

_app_inventory_getlist_call() {
	local _targets="${1:-}" _refresh="${2:-}" _body _out _rc
	_body="$(_webdav_tmp_path root_inventory_getlist_args)"
	_out="$(_webdav_tmp_path root_inventory_getlist_out)"
	{
		printf '%s\n' "${USER_ID:-${user:-0}}"
		printf '%s\n' "$_targets"
		[[ -n $_refresh ]] && printf '%s\n' "$_refresh"
	} > "$_body"
	_root_daemon_call_file_hot hiddenapi appInventoryGetlist "$_body" "$_out"
	_rc=$?
	if [[ $_rc = 125 ]]; then
		_speed_debug_log "APP_INVENTORY_GETLIST_ROOT_DAEMON_FALLBACK targets=${_targets:-empty}"
		_dex_raw com.xayah.dex.HiddenApiUtil appInventoryGetlist "${USER_ID:-${user:-0}}" "$_targets" $_refresh > "$_out"
		_rc=$?
	fi
	cat "$_out" 2>/dev/null
	rm -f "$_body" "$_out" 2>/dev/null
	return $_rc
}

appinventory_getlist() { _app_inventory_getlist_call "$@"; }


# r497: Android Canary may return an empty AppInventory through hidden API / RootDaemon even
# though PackageManager CLI is still usable. This fallback keeps appList generation usable and
# avoids treating a clean Canary device or hidden-API visibility drift as a hard script failure.
_applist_inventory_has_rows() {
	awk '$1!="#META" && NF>=3 {found=1; exit} END{exit found?0:1}' 2>/dev/null
}

_pm_list_packages_for_user() {
	local _user_id="${1:-0}" _mode="${2:-all}" _cmd
	case $_mode in
	user|third|thirdparty)
		for _cmd in 			"cmd package list packages --user $_user_id -3" 			"cmd package list packages -3 --user $_user_id" 			"pm list packages --user $_user_id -3" 			"pm list packages -3 --user $_user_id"; do
			eval "$_cmd" 2>/dev/null | sed -n 's/^package://p' | awk '{print $1}' | sed '/^[[:space:]]*$/d' && return 0
		done
		;;
	*)
		for _cmd in 			"cmd package list packages --user $_user_id" 			"pm list packages --user $_user_id"; do
			eval "$_cmd" 2>/dev/null | sed -n 's/^package://p' | awk '{print $1}' | sed '/^[[:space:]]*$/d' && return 0
		done
		;;
	esac
	return 1
}

_applist_getlist_pm_fallback() {
	local _targets="$1" _user_id="${USER_ID:-${user:-0}}" _all _third _out _pkg _rows=0 _oldifs
	_all="$TMPDIR/.applist_pm_all_${$}_$RANDOM"
	_third="$TMPDIR/.applist_pm_third_${$}_$RANDOM"
	_out="$TMPDIR/.applist_pm_getlist_${$}_$RANDOM"
	_pm_list_packages_for_user "$_user_id" all | awk 'NF && $0 ~ /^[A-Za-z0-9_.-]+$/ {print}' | sort -u > "$_all" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	_pm_list_packages_for_user "$_user_id" user | awk 'NF && $0 ~ /^[A-Za-z0-9_.-]+$/ {print}' | sort -u > "$_third" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	{
		printf '#META	defaultHome			pm-fallback
'
		printf '#META	defaultIme			pm-fallback
'
		while read -r _pkg; do
			[[ -n $_pkg ]] || continue
			printf '%s %s user
' "$_pkg" "$_pkg"
			_rows=$((_rows + 1))
		done < "$_third"
		_oldifs=$IFS
		IFS=','
		for _pkg in $_targets; do
			IFS=$_oldifs
			_pkg="$(printf '%s' "$_pkg" | tr -d ' 	
')"
			case $_pkg in ''|*[!A-Za-z0-9_.-]*|.*|*..*) IFS=','; continue ;; esac
			if awk -v p="$_pkg" '$0==p{found=1; exit} END{exit found?0:1}' "$_all" 2>/dev/null; then
				printf '%s %s system
' "$_pkg" "$_pkg"
				_rows=$((_rows + 1))
			fi
			IFS=','
		done
		IFS=$_oldifs
	} > "$_out" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	_speed_debug_log "APP_INVENTORY_GETLIST_PM_FALLBACK user=$_user_id rows=$_rows targets=${_targets:-empty} mode=r497"
	cat "$_out" 2>/dev/null
	rm -f "$_all" "$_third" "$_out" 2>/dev/null
	return 0
}

# r90: 單包 UID 查詢。restore 中只要 install/reinstall touched，就不再相信批量預掃 UID，
# 直接向 RootDaemon/Dex AppInventory 讀 PackageManager 當下最新 UID。
_app_inventory_pkg_uid_single_call() {
	local _pkg="$1" _refresh="${2:-refresh}" _body _out _rc
	[[ -n $_pkg ]] || return 1
	_body="$(_webdav_tmp_path root_inventory_pkguid_args)"
	_out="$(_webdav_tmp_path root_inventory_pkguid_out)"
	{
		printf '%s\n' "${USER_ID:-${user:-0}}"
		printf '%s\n' "$_pkg"
		[[ -n $_refresh ]] && printf '%s\n' "$_refresh"
	} > "$_body"
	_root_daemon_call_file_hot hiddenapi appInventoryPkgUid "$_body" "$_out"
	_rc=$?
	if [[ $_rc = 125 ]]; then
		_speed_debug_log "APP_INVENTORY_PKG_UID_SINGLE_ROOT_DAEMON_FALLBACK package=$_pkg"
		_dex_raw com.xayah.dex.HiddenApiUtil appInventoryPkgUid "${USER_ID:-${user:-0}}" "$_pkg" $_refresh > "$_out"
		_rc=$?
	fi
	awk -v p="$_pkg" -F'\t' '$1 == p && $2 ~ /^[0-9]+$/ {print $2; found=1; exit} END{exit found?0:1}' "$_out" 2>/dev/null
	_rc=$?
	rm -f "$_body" "$_out" 2>/dev/null
	return $_rc
}

_pkg_uid_map_set_one() {
	local _pkg="$1" _uid="$2" _tmp
	[[ -n $_pkg ]] || return 1
	case $_uid in ''|*[!0-9]*) return 1 ;; esac
	[[ -f "$TMPDIR/.pkg_uid" ]] || : > "$TMPDIR/.pkg_uid" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	_tmp="$TMPDIR/.pkg_uid_set_${$}_$RANDOM"
	awk -v p="$_pkg" -F'\t' '$1 != p {print}' "$TMPDIR/.pkg_uid" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} > "$_tmp" || { rm -f "$_tmp" 2>/dev/null; return 1; }
	printf '%s\t%s\n' "$_pkg" "$_uid" >> "$_tmp" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} || { rm -f "$_tmp" 2>/dev/null; return 1; }
	cat "$_tmp" > "$TMPDIR/.pkg_uid" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} || { rm -f "$_tmp" 2>/dev/null; return 1; }
	rm -f "$_tmp" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	return 0
}

_app_inventory_package_status_call() {
	local _pkg="$1" _refresh="${2:-refresh}" _body _out _rc
	[[ -n $_pkg ]] || return 1
	_body="$(_webdav_tmp_path root_inventory_pkgstatus_args)"
	_out="$(_webdav_tmp_path root_inventory_pkgstatus_out)"
	{
		printf '%s\n' "${USER_ID:-${user:-0}}"
		printf '%s\n' "$_pkg"
		[[ -n $_refresh ]] && printf '%s\n' "$_refresh"
	} > "$_body"
	_root_daemon_call_file_hot hiddenapi appInventoryPackageStatus "$_body" "$_out"
	_rc=$?
	if [[ $_rc = 125 ]]; then
		_speed_debug_log "APP_INVENTORY_PACKAGE_STATUS_ROOT_DAEMON_FALLBACK package=$_pkg"
		_dex_raw com.xayah.dex.HiddenApiUtil appInventoryPackageStatus "${USER_ID:-${user:-0}}" "$_pkg" $_refresh > "$_out"
		_rc=$?
	fi
	if [[ $_rc = 0 ]] && jq -e 'type=="object" and .recordType=="packageStatus"' "$_out" >/dev/null 2>&1; then
		cat "$_out" 2>/dev/null
		rm -f "$_body" "$_out" 2>/dev/null
		return 0
	fi
	cat "$_out" 2>/dev/null
	rm -f "$_body" "$_out" 2>/dev/null
	return 1
}

_pkg_ver_map_set_one() {
	local _pkg="$1" _ver="$2" _tmp
	[[ -n $_pkg ]] || return 1
	case $_ver in ''|*[!0-9]*) return 1 ;; esac
	[[ -f "$TMPDIR/.pkg_ver" ]] || : > "$TMPDIR/.pkg_ver" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	_tmp="$TMPDIR/.pkg_ver_set_${$}_$RANDOM"
	awk -v p="$_pkg" -F'	' '$1 != p {print}' "$TMPDIR/.pkg_ver" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} > "$_tmp" || { rm -f "$_tmp" 2>/dev/null; return 1; }
	printf '%s	%s
' "$_pkg" "$_ver" >> "$_tmp" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} || { rm -f "$_tmp" 2>/dev/null; return 1; }
	cat "$_tmp" > "$TMPDIR/.pkg_ver" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} || { rm -f "$_tmp" 2>/dev/null; return 1; }
	rm -f "$_tmp" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	return 0
}

_installed_map_set_one() {
	local _pkg="$1"
	[[ -n $_pkg ]] || return 1
	[[ -f "$TMPDIR/.installed_pkgs" ]] || : > "$TMPDIR/.installed_pkgs" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	awk -v p="$_pkg" '$0==p{found=1; exit} END{exit found?0:1}' "$TMPDIR/.installed_pkgs" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} && return 0
	printf '%s\n' "$_pkg" >> "$TMPDIR/.installed_pkgs" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
}

appinfo() {
	local _filter="${1:-user|system}" _format="${2:-label|pkgName|flag}"
	case $_format in
		label\|pkgName\|flag) appinventory appinfo "$_filter" ;;
		pkgName) appinventory pkgName "$_filter" ;;
		*)
			_speed_debug_log "APPINFO_UNSUPPORTED_FORMAT filter=$_filter format=$_format"
			return 1
			;;
	esac
}
appinfo2() { dex_hiddenapi getPackageLabel "$USER_ID" "$@"; }
appinfo3() { dex_hiddenapi getPackageArchiveInfo "$@"; }
get_uid() { dex_hiddenapi getPackageUid "$USER_ID" "$@"; }
# AppOps package reset 已內聚於 restoreAppStateBatch；不再存在公開 reset 入口或 shell token 區段。
setDisplay() {
	# r201: normal path uses the persistent RootDaemon; one-shot is emergency-only.
	dex_hiddenapi_raw setDisplayPowerMode "$@"
	local _rc=$?
	if [[ $_rc = 125 ]]; then
		_speed_debug_log "DISPLAY_POWER_ROOT_DAEMON_FALLBACK mode=${1:-unknown} reason=transport"
		_dex_raw com.xayah.dex.HiddenApiUtil setDisplayPowerMode "$@"
		return $?
	fi
	return $_rc
}

_prepare_timed() {
	# 統一量測所有 prepare_* 預掃耗時。stdout/stderr 不改向，由原函式自己控制。
	local _name="$1" _start _end _elapsed
	shift
	_start="$(date +%s%3N 2>/dev/null)"
	case $_start in ''|*[!0-9]*) _start="$(date +%s 2>/dev/null)000" ;; esac
	_speed_debug_log "PREPARE_BEGIN name=$_name args=$*"
	"$_name" "$@"
	local _rc=$?
	_end="$(date +%s%3N 2>/dev/null)"
	case $_end in ''|*[!0-9]*) _end="$(date +%s 2>/dev/null)000" ;; esac
	_elapsed=$((_end - _start))
	_speed_debug_log "PREPARE_END name=$_name rc=$_rc elapsedMs=$_elapsed"
	if [[ -n ${SPEED_DEBUG_RUN_DIR:-} && -d ${SPEED_DEBUG_RUN_DIR:-} ]]; then
		printf '%s	%s	%s
' "$_name" "$_rc" "$_elapsed" >> "$SPEED_DEBUG_RUN_DIR/prepare_timing.tsv" 2>/dev/null
	fi
	return $_rc
}

_speed_debug_first_pid_pkg() {
	local _pkg
	_pkg="$(ps -A -o pid=,args= 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} | awk '
		$2 ~ /^[A-Za-z0-9_]+(\.[A-Za-z0-9_]+)+$/ && $2 !~ /^(com\.android\.shell|com\.android\.systemui)$/ {print $2; exit}
	')"
	[[ -z $_pkg ]] && _pkg="$(appinventory pkgName all 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} | awk 'NF{print; exit}')"
	[[ -z $_pkg ]] && _pkg="android"
	printf '%s\n' "$_pkg"
}

# Dex/uidexec/helper 自檢已從 tools.sh 分離。
# tools.sh 只負責決定何時呼叫；測試內容固定集中在 tools/dex_check.sh。
# 只接受 dex_check.sh 這個檔名，避免版本尾碼或舊 speedbackup_dex_selftest.sh 被誤用。
_speed_debug_dex_selftest_script_path() {
	# 啟動早期路徑搜尋保持最保守寫法：不用 for 續行、不用 [[ ]]，避免部分 Android sh/mksh 在解析階段誤炸。
	local _p
	_p="$tools_path/dex_check.sh"
	[ -f "$_p" ] && { printf '%s\n' "$_p"; return 0; }
	return 1
}
_speed_debug_dex_full_test() {
	[[ "${SPEED_DEBUG_ENABLE:-1}" = 1 ]] || return 0
	[[ "${SPEED_DEBUG_FIRST_BOOT:-0}" = 1 ]] || return 0
	[[ -d "$SPEED_DEBUG_RUN_DIR" ]] || return 0
	[[ -f "$tools_path/classes.dex" ]] || return 0
	local _target _script _tools_selftest_path _rc _level _ok _fail
	_target="$(_speed_debug_first_pid_pkg)"
	_script="$(_speed_debug_dex_selftest_script_path)"
	_tools_selftest_path="$tools_path/tools.sh"
	[[ -f "$_tools_selftest_path" ]] || _tools_selftest_path="$0"
	: > "$SPEED_DEBUG_RUN_DIR/dex_full_test.log" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	: > "$SPEED_DEBUG_RUN_DIR/dex_full_test.summary" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	: > "$SPEED_DEBUG_RUN_DIR/dex_full_test_human.log" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	{
		echo "time=$(date '+%Y-%m-%d %H:%M:%S' 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null})"
		echo "target=$_target"
		echo "user=$USER_ID"
		echo "script=$_script"
		echo "tools_path=$_tools_selftest_path"
		echo "mode=$([[ ${SPEED_DEBUG_DEEP_SELF_TEST:-0} = 1 ]] && echo diagnostic || echo quick)"
	} > "$SPEED_DEBUG_RUN_DIR/dex_full_test.info" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	if [[ -z $_script ]]; then
		echo "FAIL dex_selftest script_not_found" >> "$SPEED_DEBUG_RUN_DIR/dex_full_test.summary" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
		echoRgb "dex 自檢腳本不存在：請把 dex_check.sh 放到 tools/" "0"
		return 0
	fi
	_level="quick"
	[[ "${SPEED_DEBUG_DEEP_SELF_TEST:-0}" = 1 ]] && _level="diagnostic"
	echoRgb "首次建立 /data/speed_debug，調用獨立 dex 自檢腳本" "3"
	echoRgb "測試目標app: $_target" "3"
	CLASSPATH_PATH="$tools_path/classes.dex" \
	TOOLS_PATH="$_tools_selftest_path" \
	SPEEDBACKUP_PATCH_BUILD="${speedbackup_patch_build:-}" \
	TEST_LOG_DIR="$SPEED_DEBUG_RUN_DIR" \
	TEST_LOG_FILE="$SPEED_DEBUG_RUN_DIR/dex_check.log" \
	TEST_SUMMARY_FILE="$SPEED_DEBUG_RUN_DIR/dex_full_test.summary" \
	BACKUP_WIFI_ENABLE="${backup_wifi_enable:-1}" \
	REMOTE_TYPE="${remote_type:-}" \
	SB_SELFTEST_LEVEL="$_level" \
	CHANGELOG_URL="${SPEED_DEBUG_DEX_TEST_URL:-https://api.github.com/repos/XayahSuSuSu/Android-DataBackup/releases/latest}" \
	sh "$_script" "$_target" "${USER_ID:-0}"
	_rc=$?
	{
		echo "===== DEX SELFTEST script=$_script level=$_level rc=$_rc ====="
		cat "$SPEED_DEBUG_RUN_DIR/dex_check.log" 2>/dev/null
	} >> "$SPEED_DEBUG_RUN_DIR/dex_full_test.log" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	if [[ $_rc -eq 0 ]]; then
		echo "OK dex_selftest rc=0 script=$_script level=$_level" >> "$SPEED_DEBUG_RUN_DIR/dex_full_test.summary" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	else
		echo "FAIL dex_selftest rc=$_rc script=$_script level=$_level" >> "$SPEED_DEBUG_RUN_DIR/dex_full_test.summary" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	fi
	_ok="$(grep -c '^OK ' "$SPEED_DEBUG_RUN_DIR/dex_full_test.summary" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null})"
	_fail="$(grep -c '^FAIL ' "$SPEED_DEBUG_RUN_DIR/dex_full_test.summary" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null})"
	echoRgb "dex 自檢完成: ✅${_ok:-0} ❌${_fail:-0}，詳情會打包在 speed_debug tar 內: dex_full_test.log" "3"
	# dex_check rc=2 只代表核心 capability smoke 失敗；不再代表 exact version/build contract mismatch。
	if [[ $_rc = 2 ]]; then
		echoRgb "Dex 核心能力不可用，已中止腳本，避免產生不完整備份/恢復" "0"
		_speed_debug_normal_finish_pack 2
		exit 2
	fi
	return 0
}

_speed_debug_dex_full_test
find_tools_path="$(find "$path_hierarchy"/* -maxdepth 1 -name "tools" -type d ! -path "$path_hierarchy/tools" | grep -v "/Backup_[^/]*/tools$")"
# 等待指定子程序並提供 timeout：
# - 有 pidfd 時：procwait 阻塞 poll(pidfd)，另用一顆一次性 sleep 作 watchdog。
# - 核心不支援 pidfd / 工具缺失：回傳 125，呼叫端使用原有限輪詢保底。
# 返回：子程序 rc；124=逾時；125=請使用 fallback。
_wait_child_timeout_eventwait() {
	local _pid="$1" _timeout="$2" _tag="${3:-child}" _timeout_ms _ew_rc _child_rc
	case $_pid in ''|*[!0-9]*) return 125 ;; esac
	case $_timeout in ''|*[!0-9]*) return 125 ;; esac
	_timeout_ms=$((_timeout * 1000))
	_eventwait_pid_exit_ms "$_pid" "$_timeout_ms" "${_tag}_child_exit" >/dev/null 2>&1
	_ew_rc=$?
	case $_ew_rc in
	0)
		wait "$_pid" 2>/dev/null
		_child_rc=$?
		_speed_debug_log "EVENTWAIT_CHILD_DONE tag=$_tag pid=$_pid child_rc=$_child_rc timeout=$_timeout mode=r459"
		return "$_child_rc"
		;;
	124)
		_event_terminate_pid "$_pid" "${_tag}_eventwait_timeout" >/dev/null 2>&1 || true
		wait "$_pid" 2>/dev/null
		_speed_debug_log "EVENTWAIT_CHILD_TIMEOUT tag=$_tag pid=$_pid timeout=$_timeout mode=r459"
		return 124
		;;
	125|127|126)
		_speed_debug_log "EVENTWAIT_CHILD_FALLBACK tag=$_tag pid=$_pid rc=$_ew_rc reason=eventwait_unavailable mode=r459"
		return 125
		;;
	*)
		if ! kill -0 "$_pid" 2>/dev/null; then
			wait "$_pid" 2>/dev/null
			_child_rc=$?
			_speed_debug_log "EVENTWAIT_CHILD_DONE tag=$_tag pid=$_pid child_rc=$_child_rc rc=$_ew_rc reason=pid_gone_after_eventwait mode=r459"
			return "$_child_rc"
		fi
		_speed_debug_log "EVENTWAIT_CHILD_FALLBACK tag=$_tag pid=$_pid rc=$_ew_rc reason=eventwait_error mode=r459"
		return 125
		;;
	esac
}

_wait_child_timeout_procwait() {
	local _pid="$1" _timeout="$2" _tag="${3:-child}" _watch_rc _child_rc _state _i
	[[ -x ${EVENT_PROCWAIT_BIN:-} ]] || return 125
	command -v timeout >/dev/null 2>&1 || return 125
	case $_pid in ''|*[!0-9]*) return 125 ;; esac
	case $_timeout in ''|*[!0-9]*) return 125 ;; esac

	# r453: 全面接入 eventwait pid-exit 作為 child wait 主路徑；procwait/shell loop 只作相容 fallback。
	_wait_child_timeout_eventwait "$_pid" "$_timeout" "$_tag"
	_child_rc=$?
	[[ $_child_rc != 125 ]] && return "$_child_rc"

	# 不再建立會繼承主腳本 EXIT trap 的 background watchdog shell。
	# timeout 只限制 procwait 本身；逾時後由目前主 shell 精準 TERM/KILL 目標 child。
	timeout "$_timeout" "$EVENT_PROCWAIT_BIN" pid "$_pid" >/dev/null 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	_watch_rc=$?

	case $_watch_rc in
	0)
		wait "$_pid" 2>/dev/null
		_child_rc=$?
		_speed_debug_log "PROCWAIT_DONE tag=$_tag pid=$_pid child_rc=$_child_rc watcher_rc=$_watch_rc"
		return "$_child_rc"
		;;
	3)
		# procwait 定義：pidfd_open 不支援時返回 3，交回原有限輪詢。
		_speed_debug_log "PROCWAIT_FALLBACK tag=$_tag pid=$_pid watcher_rc=$_watch_rc reason=pidfd_unsupported"
		return 125
		;;
	124|137|143)
		if kill -0 "$_pid" 2>/dev/null; then
			kill -TERM "$_pid" 2>/dev/null
			_i=0
			while [[ $_i -lt 10 ]] && kill -0 "$_pid" 2>/dev/null; do
				sleep 0.1
				_i=$((_i + 1))
			done
			kill -0 "$_pid" 2>/dev/null && kill -KILL "$_pid" 2>/dev/null
		fi
		wait "$_pid" 2>/dev/null
		_speed_debug_log "PROCWAIT_TIMEOUT tag=$_tag pid=$_pid timeout=$_timeout watcher_rc=$_watch_rc"
		return 124
		;;
	*)
		_state="$(awk '/^State:/{print $2; exit}' /proc/"$_pid"/status 2>/dev/null)"
		case "$_state" in
		''|Z)
			wait "$_pid" 2>/dev/null
			_child_rc=$?
			_speed_debug_log "PROCWAIT_DONE tag=$_tag pid=$_pid child_rc=$_child_rc watcher_rc=$_watch_rc state=${_state:-gone}"
			return "$_child_rc"
			;;
		*)
			_speed_debug_log "PROCWAIT_FALLBACK tag=$_tag pid=$_pid watcher_rc=$_watch_rc state=$_state"
			return 125
			;;
		esac
		;;
	esac
}

# 備份 WiFi 密碼到指定目錄, 用 classes.dex 讀 system 內的 WifiConfigStore
# ===== 備份預掃與快取 =====
backup_wifi() {
	local wifi_dir="$1"
	[[ -z $wifi_dir ]] && echoRgb "backup_wifi: 目錄參數為空" "0" && return 1
	case ${backup_wifi_enable:-1} in
	0|false|False|FALSE)
		echoRgb "WiFi備份已關閉，略過" "3"
		return 0
		;;
	esac
	[[ ! -d $wifi_dir ]] && mkdir -p "$wifi_dir"
	if [[ -d $wifi_dir ]]; then
		echoRgb "備份wifi密碼"
		rm -rf "${wifi_dir:?}"/*
		local _wifi_tmp _wifi_err _wifi_rc _wifi_pid _wifi_wait _wifi_timeout
		_wifi_timeout="${WIFI_BACKUP_TIMEOUT:-20}"
		case $_wifi_timeout in ""|*[!0-9]*) _wifi_timeout=20 ;; esac
		_wifi_tmp="$TMPDIR/.speedbackup_wifi_save_${$}_$RANDOM.json"
		_wifi_err="$TMPDIR/.speedbackup_wifi_save_${$}_$RANDOM.err"
		rm -f "$_wifi_tmp" "$_wifi_err" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
		# saveNetworks 會輸出完整 JSON，必須直跑 app_process；不可走 _dex 翻譯/過濾包裝層。
		_dex_export_classpath
		command "$DEX_APP_PROCESS_BIN" "$DEX_APP_PROCESS_BASE" com.xayah.dex.NetworkUtil saveNetworks >"$_wifi_tmp" 2>"$_wifi_err" &
		_wifi_pid=$!
		_speedbackup_protect_pid "$_wifi_pid" app_process_oneshot_wifi
		_wait_child_timeout_procwait "$_wifi_pid" "$_wifi_timeout" wifi_backup
		_wifi_rc=$?
		if [[ $_wifi_rc = 125 ]]; then
			# 舊核心或特殊 ROM 的相容保底；只有 pidfd 不可用時才進入。
			_wifi_wait=0
			while kill -0 "$_wifi_pid" 2>/dev/null; do
				if [[ $_wifi_wait -ge $_wifi_timeout ]]; then
					kill -TERM "$_wifi_pid" 2>/dev/null
					sleep 1
					kill -KILL "$_wifi_pid" 2>/dev/null
					wait "$_wifi_pid" 2>/dev/null
					_wifi_rc=124
					break
				fi
				sleep 1
				_wifi_wait=$((_wifi_wait + 1))
			done
			if [[ $_wifi_rc = 125 ]]; then
				wait "$_wifi_pid" 2>/dev/null
				_wifi_rc=$?
			fi
		fi
		[[ -s $_wifi_err ]] && cat "$_wifi_err" >> "${SPEED_DEBUG_ERR_LOG:-/dev/null}" 2>/dev/null
		if [[ $_wifi_rc = 0 && -s $_wifi_tmp ]]; then
			cat "$_wifi_tmp" > "$wifi_dir/wifi.json"
			rm -f "$_wifi_tmp" "$_wifi_err" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
			echo_log "wifi備份"
		else
			rm -f "$wifi_dir/wifi.json" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
			case $_wifi_rc in
			124) echoRgb "wifi備份逾時 ${_wifi_timeout}s，已略過，不影響其他備份" "0" ;;
			*) echoRgb "wifi備份失敗 rc=$_wifi_rc，已略過，不影響其他備份" "0" ;;
			esac
			[[ -s $_wifi_err ]] && echoRgb "WiFi備份錯誤已寫入 speed_debug 包內: stderr.log" "3"
			rm -f "$_wifi_tmp" "$_wifi_err" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
			result=1
			Set_back_1
			return 1
		fi
	fi
}
# 從備份恢復 WiFi 密碼 (寫回 WifiConfigStore)
recover_wifi() {
	if [[ -d $1 ]]; then
		if [[ -f $1/wifi.json ]]; then
			echoRgb "恢復wifi密碼"
			_dex com.xayah.dex.NetworkUtil restoreNetworks "$1/wifi.json"
			echo_log "wifi恢復"
		else
			echoRgb "wifi.json遺失"
		fi
	else
		echoRgb "$1不存在 wifi無法恢復" "0"
	fi
}
# 在指定路徑生成入口腳本 (start.sh / backup.sh / recover.sh / upload.sh)
# $1=模式 (0/1/2/3/5), $2=目標檔案路徑
# 446: wrapper 一律先解析腳本實體目錄，不再用 ${0%/*/*} 直接推路徑，避免 ./recover.sh 被當成目錄。
# 446: tools.sh 必須在目前 shell source；不能放在 pipeline 左側，避免 start.sh source 後直接退出。
touch_shell() {
	unset conf_path MODDIR_Path MODDIR_Path1 _sb_root_rel _sb_moddir_rel _sb_conf_rel
	case $1 in
	0)
		_sb_root_rel='.'
		_sb_moddir_rel='.'
		_sb_conf_rel='backup_settings.conf' ;;
	1)
		# backup.sh: 依舊維持舊版相對深度，從腳本所在目錄往上兩層取備份根目錄。
		_sb_root_rel='../..'
		_sb_moddir_rel='../..'
		_sb_conf_rel='../../backup_settings.conf' ;;
	2)
		_sb_root_rel='.'
		_sb_moddir_rel='.'
		_sb_conf_rel='restore_settings.conf' ;;
	3)
		# recover.sh: 位於單一 app 備份目錄；tools/ 與 restore_settings.conf 在上一層備份根目錄。
		_sb_root_rel='..'
		_sb_moddir_rel='.'
		_sb_conf_rel='../restore_settings.conf' ;;
	5)
		# upload.sh: 放在 Backup_zstd_X/<app>/，MODDIR 是 Backup_zstd_X 自己，設定檔在再上一層。
		_sb_root_rel='../..'
		_sb_moddir_rel='..'
		_sb_conf_rel='../../backup_settings.conf' ;;
	*)
		return 1 ;;
	esac
	cat > "$2" <<'TOUCH_SHELL_EOF'
#!/system/bin/sh
# SpeedBackup entry wrapper generated by tools.sh.
# 446: resolve physical script directory first; relative invocations like ./recover.sh must not turn into ./recover.sh/tools/tools.sh.
_sb_entry_file="$0"
case "$_sb_entry_file" in
	*/*) ;;
	*)
		_sb_cmd="$(command -v "$_sb_entry_file" 2>/dev/null)"
		[ -n "$_sb_cmd" ] && _sb_entry_file="$_sb_cmd"
		;;
esac
_sb_entry_dir="${_sb_entry_file%/*}"
[ "$_sb_entry_dir" = "$_sb_entry_file" ] && _sb_entry_dir="."
_sb_entry_dir="$(cd "$_sb_entry_dir" 2>/dev/null && pwd -P)"
if [ -z "$_sb_entry_dir" ]; then
	echo "SpeedBackup 入口錯誤: 無法解析腳本目錄: $0"
	exit 127
fi
_sb_abs_dir() {
	(cd "$1" 2>/dev/null && pwd -P) || return 1
}
_sb_root="$(_sb_abs_dir "$_sb_entry_dir/ROOT_REL_PLACEHOLDER")" || _sb_root=""
_sb_moddir="$(_sb_abs_dir "$_sb_entry_dir/MODDIR_REL_PLACEHOLDER")" || _sb_moddir=""
conf_path="$_sb_entry_dir/CONF_REL_PLACEHOLDER"
case "$conf_path" in
	/*) ;;
	*) conf_path="$(_sb_abs_dir "${conf_path%/*}" 2>/dev/null)/${conf_path##*/}" ;;
esac
if [ -z "$_sb_root" ] || [ -z "$_sb_moddir" ]; then
	echo "SpeedBackup 入口錯誤: 無法解析根目錄 root=$_sb_root moddir=$_sb_moddir script=$0"
	exit 127
fi
if [ ! -f "$_sb_root/tools/tools.sh" ]; then
	echo "$_sb_root/tools/tools.sh遺失"
	exit 127
fi
MODDIR="$_sb_moddir"
# 入口腳本自己的 log 目錄必須自行建立；不能引用 tools.sh 上一次 run 的 speed_debug 路徑。
# r487: 入口 wrapper log 只寫入入口旁 log/；不可再 fallback 到 /data/local/tmp 根層。
_log_dir="$_sb_entry_dir/log"
if ! mkdir -p "$_log_dir" 2>/dev/null; then
	_log_dir=""
fi
if [ -n "$_log_dir" ]; then
	logfile="$_log_dir/log_$(date +%Y-%m-%d_%H-%M).txt"
	: > "$logfile" 2>/dev/null || logfile="/dev/null"
else
	logfile="/dev/null"
fi
# 由入口腳本啟動時，trap 收尾訊息只寫 speed_debug，不刷終端，避免單獨恢復開頭出現 trap 訊息。
export SPEEDBACKUP_ENTRY_QUIET_TRAP=1
export SPEEDBACKUP_ENTRY_MODE="ENTRY_MODE_PLACEHOLDER"
export SPEEDBACKUP_ENTRY_SCRIPT="$0"
# 防止舊入口腳本 / 父 shell 殘留上一輪 speed_debug run_xxx 變數，導致單獨腳本誤寫已被 final 刪除的 main.log/stderr.log。
unset SPEED_DEBUG_RUN_DIR SPEED_DEBUG_MAIN_LOG SPEED_DEBUG_PENDING_ERR_LOG SPEED_DEBUG_CMD_LOG SPEED_DEBUG_INFO_LOG SPEED_DEBUG_DEX_HUMAN_LOG SPEED_DEBUG_ARCHIVE SPEED_DEBUG_PACKED SPEED_DEBUG_SNAPSHOT_DONE SPEED_DEBUG_RUN_DIR_REMOVED SPEED_DEBUG_ERR_LOG
# 446: 不可使用 `. tools.sh | tee`。source 放在 pipeline 內會讓部分 shell/入口條件下主流程直接退出或在 subshell 中跑壞。
# r36: legacy logfile 由 _speed_debug_sync_legacy_log 在 final/snapshot 打包前寫入 main.log 鏡像；實際診斷仍以 /data/speed_debug 內 speed_debug 包為準。
. "$_sb_root/tools/tools.sh"
_entry_rc=$?
case "$_entry_rc" in
	''|*[!0-9]*) _entry_rc=1 ;;
esac
if [ "$logfile" != "/dev/null" ] && [ -f "$logfile" ]; then
	sed -i "$(printf 's/\033\[[0-9;]*m//g')" "$logfile" 2>/dev/null || true
fi
exit "$_entry_rc"
TOUCH_SHELL_EOF
	sed -i \
		-e "s#ROOT_REL_PLACEHOLDER#$_sb_root_rel#g" \
		-e "s#MODDIR_REL_PLACEHOLDER#$_sb_moddir_rel#g" \
		-e "s#CONF_REL_PLACEHOLDER#$_sb_conf_rel#g" \
		-e "s#ENTRY_MODE_PLACEHOLDER#$1#g" \
		"$2" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
}

# r171: 遠端下載落地後，本地補齊不再上傳到遠端的入口 sidecar；appList/mediaList 直接復用既有「重新生成應用列表」流程，避免重複造輪子。
_speedbackup_download_local_tools_fill() {
	local _dest="$1" _src _cnt
	[[ -n $_dest && -d $_dest ]] || return 1
	_src="$MODDIR/tools"
	if [[ ! -d $_src || ! -f $_src/tools.sh ]]; then
		_speed_debug_log "REMOTE_DOWNLOAD_LOCAL_TOOLS_FILL_FAIL reason=source_missing src=$_src dest=$_dest"
		return 1
	fi
	mkdir -p "$_dest/tools" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} || return 1
	cp -rf "$_src/." "$_dest/tools/" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} || return 1
	_speedscan_paths_all_exist "$_dest/tools/tools.sh" || return 1
	_speedscan_chmod_tree_or_fallback "$_dest/tools" 0755
	_cnt="$(find "$_dest/tools" -type f 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} | wc -l 2>/dev/null | tr -d ' ')"
	case $_cnt in ''|*[!0-9]*) _cnt=0 ;; esac
	_speed_debug_log "REMOTE_DOWNLOAD_LOCAL_TOOLS_FILL ok=1 src=$_src dest=$_dest/tools files=$_cnt reason=remote-tools-removed"
	echoRgb "已使用本機 tools/ 補齊下載備份" "1"
	return 0
}

_speedbackup_download_sidecars_rebuild() {
	local _dest="$1" _app _cnt=0 _appcnt=0 _user_hint
	[[ -n $_dest && -d $_dest ]] || return 1
	if ! touch_shell "2" "$_dest/start.sh" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}; then
		_speed_debug_log "SIDECAR_LOCAL_REBUILD_FAIL type=start dest=$_dest/start.sh"
		return 1
	fi
	chmod 0755 "$_dest/start.sh" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	_user_hint="${_dest##*/}"
	case $_user_hint in
		Backup_zstd_*) _user_hint="${_user_hint#Backup_zstd_}"; _user_hint="${_user_hint%%[^0-9]*}" ;;
		*) _user_hint="${user:-${USER_ID:-0}}" ;;
	esac
	case $_user_hint in ''|*[!0-9]*) _user_hint="${USER_ID:-0}" ;; esac
	# 復用恢復模式選單的 dumpname/get_name Apkname：它已負責 appList/mediaList、recover.sh/backup.sh、一致性檢查與舊備份 apk probe。
	(
		MODDIR="$_dest"
		user="$_user_hint"
		SPEEDBACKUP_REGEN_USER="$_user_hint"
		SPEEDBACKUP_REGEN_NO_EXIT=1
		SPEEDBACKUP_REGEN_SKIP_ORPHAN_CLEANUP=1
		get_name Apkname
	)
	if [[ $? -ne 0 ]]; then
		_speed_debug_log "SIDECAR_LOCAL_REBUILD_FAIL type=existing_applist_regen dest=$_dest"
		return 1
	fi
	# 既有重新生成應用列表功能只補 recover/backup；遠端下載落地後再補 upload 入口。
	find "$_dest" -mindepth 1 -maxdepth 1 -type d 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} | sort | while read -r _app; do
		case "${_app##*/}" in tools|wifi|Media|log) continue ;; esac
		[[ -f $_app/app_details.json || -f $_app/app_details || -f $_app/apk.tar || -f $_app/apk.tar.zst ]] || continue
		touch_shell "5" "$_app/upload.sh" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} && chmod 0755 "$_app/upload.sh" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	done
	_appcnt="$(grep -vc '^[[:space:]]*$' "$_dest/appList.txt" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null})"
	case $_appcnt in ''|*[!0-9]*) _appcnt=0 ;; esac
	find "$_dest" -mindepth 2 -maxdepth 2 \( -name recover.sh -o -name backup.sh -o -name upload.sh \) -type f 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} | while read -r _x; do echo 1; done > "$TMPDIR/.sidecar_rebuild_count.$$"
	_cnt="$(wc -l < "$TMPDIR/.sidecar_rebuild_count.$$" 2>/dev/null | tr -d ' ')"
	rm -f "$TMPDIR/.sidecar_rebuild_count.$$" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	case $_cnt in ''|*[!0-9]*) _cnt=0 ;; esac
	_speed_debug_log "SIDECAR_LOCAL_REBUILD dest=$_dest start=1 appList=$_appcnt wrappers=$_cnt source=existing_regenerate_app_list reason=remote-sidecar-not-uploaded"
	echoRgb "已本地補齊入口/清單: start.sh appList.txt/mediaList.txt app wrappers=${_cnt}" "1"
	return 0
}

# 447: 同步既有備份根目錄內嵌 tools/start/recover wrapper。
# 場景: 使用者把更新 zip 放在主目錄自動解壓後，主目錄 tools/ 已更新，
# 但既有 Backup_zstd_X/tools/ 仍停在舊版，導致單 app 目錄 ./recover.sh 還會使用舊 wrapper。
# 這裡只更新恢復基礎設施，不改 app payload/app_details/備份資料。
_speedbackup_sync_embedded_backup_tools() {
	local _root="${1:-$path_hierarchy}" _src _br _app _cnt_file _cnt
	[[ -z $_root || ! -d $_root ]] && return 0
	_src="$_root/tools"
	[[ ! -d $_src || ! -f $_src/tools.sh ]] && return 0
	_cnt_file="$TMPDIR/.embedded_tools_sync_count.$$"
	: > "$_cnt_file" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	find "$_root" -maxdepth 1 -type d -name 'Backup_*' 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} | while read -r _br; do
		[[ -z $_br || $_br = "$_root" ]] && continue
		# 只處理看起來像 SpeedBackup 備份根的目錄，避免誤更新普通資料夾。
		[[ -d $_br/tools || -f $_br/restore_settings.conf || -f $_br/app_details.json ]] || continue
		if [[ ! -f $_br/tools/tools.sh ]] || ! cmp -s "$_src/tools.sh" "$_br/tools/tools.sh" 2>/dev/null; then
			mkdir -p "$_br/tools" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} || continue
			cp -rf "$_src/." "$_br/tools/" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} || continue
			chmod -R 0755 "$_br/tools" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
			echo 1 >> "$_cnt_file"
		fi
		# 備份根入口：start.sh 重新指向本備份根 tools/。
		if [[ -f $_br/start.sh || -f $_br/restore_settings.conf ]]; then
			touch_shell "2" "$_br/start.sh"
			chmod 0755 "$_br/start.sh" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
		fi
		# 單 app 入口：recover.sh 必須重生，否則舊 wrapper 會繼續把 ./recover.sh 當目錄。
		find "$_br" -mindepth 1 -maxdepth 1 -type d 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} | while read -r _app; do
			[[ -f $_app/app_details.json || -f $_app/app_details ]] || continue
			touch_shell "3" "$_app/recover.sh"
			chmod 0755 "$_app/recover.sh" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
			[[ -f $_app/backup.sh ]] && { touch_shell "1" "$_app/backup.sh"; chmod 0755 "$_app/backup.sh" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}; }
			[[ -f $_app/upload.sh ]] && { touch_shell "5" "$_app/upload.sh"; chmod 0755 "$_app/upload.sh" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}; }
		done
	done
	_cnt="$(wc -l < "$_cnt_file" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} | tr -d ' ')"
	rm -f "$_cnt_file" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	if [[ ${_cnt:-0} -gt 0 ]]; then
		echoRgb "已同步既有備份目錄 tools/start/recover: ${_cnt} 個" "1"
	fi
	return 0
}
# 用 ts 翻譯檔案 (取代散落各處的 ts<X>temp && cp temp X && rm temp 模式)
# 用法: ts_inplace <檔案>
ts_inplace() {
	local f="$1" tmp="$TMPDIR/.ts_$$"
	if ts < "$f" > "$tmp"; then
		cp "$tmp" "$f"
		rm -f "$tmp"
	else
		rm -f "$tmp"
		return 1
	fi
}

_speedbackup_translate_file_once() {
	# $1=file, $2=done-list.  避免同一 conf 因 root/conf_path 重疊被重複轉換。
	local _file="$1" _done="$2" _abs
	[[ -n $_file && -f $_file ]] || return 0
	_abs="$(cd "${_file%/*}" 2>/dev/null && pwd -P)/${_file##*/}"
	[[ -n $_done && -f $_done ]] && grep -Fqx "$_abs" "$_done" 2>/dev/null && return 0
	if ts_inplace "$_file"; then
		case ${_file##*/} in backup_settings.conf|restore_settings.conf) _conf_sanitize_legacy_comment_noise "$_file" ;; esac
		[[ -n $_done ]] && printf '%s\n' "$_abs" >> "$_done" 2>/dev/null
		return 0
	fi
	return 1
}

_speedbackup_startup_language_sync() {
	# 456: 恢復 Shell_LANG 啟動語系同步，但不再逐一掃描/翻譯每一份 Backup_*/tools/tools.sh。
	# 做法：只翻譯 canonical root/tools/tools.sh 一份，通過語法檢查後整體覆蓋；
	# 再呼叫 embedded tools sync，把同一份 tools/ 複製到既有 Backup_* 並重生 wrapper。
	local _root="${1:-$path_hierarchy}" _main_tools _main_sh _lang _tmp_dir _tmp_sh _done _changed=0 _conf _br
	[[ -n $Script_target_language && -n $_root && -d $_root ]] || return 0
	_main_tools="$_root/tools"
	_main_sh="$_main_tools/tools.sh"
	[[ -f $_main_sh ]] || return 0
	_lang="$(awk -F= '/^shell_language=/ {gsub(/"/, "", $2); print $2; exit}' "$_main_sh" 2>/dev/null)"
	case $_lang in zh-TW|zh-CN) ;; *) return 0 ;; esac
	[[ $_lang = "$Script_target_language" ]] && return 0

	_tmp_dir="${TMPDIR:-/data/local/tmp}/.speedbackup_lang_sync.$$"
	_done="$_tmp_dir/done.list"
	rm -rf "$_tmp_dir" 2>/dev/null
	mkdir -p "$_tmp_dir" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} || return 1
	_tmp_sh="$_tmp_dir/tools.sh"
	echoRgb "腳本語言為$_lang，整體轉換為$Script_target_language；只更新主 tools.sh，再同步到既有備份目錄" "3"
	if ts < "$_main_sh" > "$_tmp_sh"; then
		sed -i "s/shell_language=\"$_lang\"/shell_language=\"$Script_target_language\"/g" "$_tmp_sh" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
		if sh -n "$_tmp_sh" >/dev/null 2>>"${SPEED_DEBUG_ERR_LOG:-/dev/null}"; then
			cat "$_tmp_sh" > "$_main_sh" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
			chmod 0755 "$_main_sh" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
			_changed=1
			echo_log "tools/tools.sh整體翻譯"
		else
			echoRgb "語系轉換後 tools.sh 語法檢查失敗，已保留原檔" "0"
			rm -rf "$_tmp_dir" 2>/dev/null
			return 1
		fi
	else
		echoRgb "tools.sh 語系轉換失敗，已保留原檔" "0"
		rm -rf "$_tmp_dir" 2>/dev/null
		return 1
	fi

	# 非腳本資源/設定檔可同步轉換；這些不是執行中的 tools.sh，不會造成半更新腳本狀態。
	for _conf in "$_root/backup_settings.conf" "$_root/restore_settings.conf" "${conf_path:-}"; do
		_speedbackup_translate_file_once "$_conf" "$_done" && _changed=1
	done
	for _br in "$_root"/Backup_*; do
		[[ -d $_br ]] || continue
		for _conf in "$_br/backup_settings.conf" "$_br/restore_settings.conf"; do
			_speedbackup_translate_file_once "$_conf" "$_done" && _changed=1
		done
	done

	if [[ $_changed = 1 ]]; then
		_speedbackup_sync_embedded_backup_tools "$_root"
		rm -rf "$_tmp_dir" 2>/dev/null
		echoRgb "語系同步完成，請重新執行腳本以使用 $Script_target_language" "1"
		exit 2
	fi
	rm -rf "$_tmp_dir" 2>/dev/null
	return 0
}

# 448: transactional updater helpers.
_sb_update_zip_has_core() {
	local _zip="$1"
	[[ -f $_zip ]] || return 1
	unzip -l "$_zip" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} | grep -q 'tools/tools\.sh$'
}

_sb_update_patch_build_of() {
	local _file="$1"
	awk -F= '/^speedbackup_patch_build=/ {gsub(/"/, "", $2); print $2; exit}' "$_file" 2>/dev/null
}

_sb_update_backup_version_of() {
	local _file="$1"
	awk -F= '/^backup_version=/ {gsub(/"/, "", $2); print $2; exit}' "$_file" 2>/dev/null
}

_sb_update_release_tag_of() {
	# r15: raw release tag for reports; fallback to backup_version for old packages.
	local _file="$1" _tag _bv
	_tag="$(awk -F= '/^speedbackup_release_tag=/ {gsub(/"/, "", $2); print $2; exit}' "$_file" 2>/dev/null)"
	if [[ -n $_tag ]]; then
		printf '%s\n' "$_tag"
	else
		_bv="$(_sb_update_backup_version_of "$_file")"
		printf '%s\n' "$_bv"
	fi
}

_sb_update_effective_version_of() {
	# r40: package/install effective version follows backup_version first; release_tag is fallback only.
	# A package whose backup_version was lowered is therefore still treated as older even if release_tag was left unchanged.
	local _file="$1" _tag _bv _tag_d _bv_d
	_tag="$(awk -F= '/^speedbackup_release_tag=/ {gsub(/"/, "", $2); print $2; exit}' "$_file" 2>/dev/null)"
	_bv="$(_sb_update_backup_version_of "$_file")"
	_bv_d="$(_speedbackup_version_digits "$_bv")"
	_tag_d="$(_speedbackup_version_digits "$_tag")"
	if [[ -n $_bv_d ]]; then
		printf '%s\n' "$_bv"
	elif [[ -n $_tag_d ]]; then
		printf '%s\n' "$_tag"
	else
		printf '%s\n' "0"
	fi
}

_sb_update_sanitize_path() {
	printf '%s\n' "$1" | sed 's#[/: 　]#_#g; s#[^A-Za-z0-9._+-]#_#g'
}

_sb_update_is_backup_root() {
	local _d="$1" _b
	[[ -d $_d ]] || return 1
	_b="${_d##*/}"
	case $_b in
	Backup_*) return 0 ;;
	esac
	[[ -f $_d/restore_settings.conf && -d $_d/tools ]] && return 0
	return 1
}


_sb_update_path_is_external_inbox() {
	# r484: Download/QQ file_recv are update-package inboxes only; never treat them as update targets.
	# pwd -P on Android may expose /storage, /mnt/*/emulated, /mnt/user/*/primary, or /data/media forms.
	local _d="$1"
	case "$_d" in
		/storage/emulated/[0-9]*/Download|/sdcard/Download|/storage/self/primary/Download|/mnt/sdcard/Download|/data/media/[0-9]*/Download)
			return 0 ;;
		/mnt/user/[0-9]*/primary/Download|/mnt/runtime/*/emulated/[0-9]*/Download|/mnt/pass_through/*/emulated/[0-9]*/Download|/mnt/installer/*/emulated/[0-9]*/Download)
			return 0 ;;
		/storage/emulated/[0-9]*/Android/data/com.tencent.mobileqq/Tencent/QQfile_recv|/sdcard/Android/data/com.tencent.mobileqq/Tencent/QQfile_recv|/storage/self/primary/Android/data/com.tencent.mobileqq/Tencent/QQfile_recv|/data/media/[0-9]*/Android/data/com.tencent.mobileqq/Tencent/QQfile_recv)
			return 0 ;;
		/mnt/user/[0-9]*/primary/Android/data/com.tencent.mobileqq/Tencent/QQfile_recv|/mnt/runtime/*/emulated/[0-9]*/Android/data/com.tencent.mobileqq/Tencent/QQfile_recv|/mnt/pass_through/*/emulated/[0-9]*/Android/data/com.tencent.mobileqq/Tencent/QQfile_recv|/mnt/installer/*/emulated/[0-9]*/Android/data/com.tencent.mobileqq/Tencent/QQfile_recv)
			return 0 ;;
	esac
	return 1
}

_sb_update_target_is_external_inbox() {
	_sb_update_path_is_external_inbox "$1"
}

_sb_update_report_line() {
	local _report="$1"; shift
	printf '%s\n' "$*" >> "$_report" 2>/dev/null
}

_sb_update_collect_targets() {
	# $1=zip_dir, $2=targets_file
	local _zip_dir="$1" _targets="$2" _main="" _backup="" _parent="" _br _external_inbox=0
	: > "$_targets" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} || return 1
	_sb_update_path_is_external_inbox "$_zip_dir" && _external_inbox=1
	# r484: Download/QQ file_recv may contain unrelated Tools/tools/start.sh; they are sources only, not roots.
	# Therefore app-dir / backup-root / direct-main detection from zip_dir is disabled for these inboxes.
	if [[ $_external_inbox != 1 ]]; then
		# 若更新包放在單 app 目錄，避免誤動；提示回到 Backup_zstd_X 或主根。
		if [[ -f $_zip_dir/app_details.json || -f $_zip_dir/app_details ]]; then
			_parent="${_zip_dir%/*}"
			printf '%s\t%s\n' "abort_app_dir" "$_parent" >> "$_targets"
			return 0
		fi
		if _sb_update_is_backup_root "$_zip_dir"; then
			_backup="$_zip_dir"
			printf '%s\t%s\n' "backup" "$_backup" >> "$_targets"
			_parent="${_backup%/*}"
			if [[ -d $_parent/tools || -f $_parent/start.sh ]]; then
				printf '%s\t%s\n' "main_parent" "$_parent" >> "$_targets"
			fi
			return 0
		fi
		if [[ -d $_zip_dir/tools || -f $_zip_dir/start.sh || -f $_zip_dir/backup_settings.conf ]]; then
			_main="$_zip_dir"
		fi
	fi
	# 更新包放在 Download/QQ 收件匣時，必須回到目前執行中的主根；不可用 zip_dir。
	if [[ -z $_main && -n $path_hierarchy && -d $path_hierarchy/tools ]]; then
		_main="$path_hierarchy"
	elif [[ -z $_main && -n $MODDIR && -d $MODDIR/tools ]]; then
		_main="$MODDIR"
	fi
	if [[ -n $_main ]] && _sb_update_target_is_external_inbox "$_main"; then
		_speed_debug_log "UPDATE_TARGET_REJECT_EXTERNAL_INBOX zipDir=$_zip_dir main=$_main reason=external_inbox_must_not_be_target mode=r484"
		return 1
	fi
	[[ -z $_main || ! -d $_main ]] && return 1
	printf '%s\t%s\n' "main" "$_main" >> "$_targets"
	find "$_main" -maxdepth 1 -type d -name 'Backup_*' 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} | while read -r _br; do
		[[ -z $_br || $_br = "$_main" ]] && continue
		[[ -d $_br/tools || -f $_br/restore_settings.conf || -f $_br/app_details.json ]] || continue
		if _sb_update_target_is_external_inbox "$_br"; then
			_speed_debug_log "UPDATE_EMBEDDED_TARGET_SKIP_EXTERNAL_INBOX target=$_br mode=r484"
			continue
		fi
		printf '%s\t%s\n' "embedded" "$_br" >> "$_targets"
	done
	return 0
}

_sb_update_backup_target_for_rollback() {
	local _target="$1" _rbroot="$2" _safe _rb _rel
	_safe="$(_sb_update_sanitize_path "$_target")"
	_rb="$_rbroot/$_safe"
	mkdir -p "$_rb" "$_rb/files" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} || return 1
	printf '%s\n' "$_target" > "$_rb/target.path"
	[[ -d $_target/tools ]] && cp -Rp "$_target/tools" "$_rb/tools" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	# 只備份入口腳本；不碰 app payload/json。
	( cd "$_target" 2>/dev/null && find . -maxdepth 2 -type f \( -name 'start.sh' -o -name 'recover.sh' -o -name 'backup.sh' -o -name 'upload.sh' \) 2>/dev/null ) |
	while read -r _rel; do
		[[ -z $_rel ]] && continue
		mkdir -p "$_rb/files/${_rel%/*}" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
		cp -p "$_target/$_rel" "$_rb/files/$_rel" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	done
	return 0
}

_sb_update_restore_one_target() {
	local _rb="$1" _target _rel
	[[ -f $_rb/target.path ]] || return 1
	_target="$(cat "$_rb/target.path" 2>/dev/null)"
	[[ -n $_target && -d $_target ]] || return 1
	if [[ -d $_rb/tools ]]; then
		mkdir -p "$_target/tools" 2>/dev/null
		cp -Rf "$_rb/tools/." "$_target/tools/" 2>/dev/null
	fi
	( cd "$_rb/files" 2>/dev/null && find . -type f 2>/dev/null ) |
	while read -r _rel; do
		[[ -z $_rel ]] && continue
		mkdir -p "$_target/${_rel%/*}" 2>/dev/null
		cp -p "$_rb/files/$_rel" "$_target/$_rel" 2>/dev/null
	done
	return 0
}

_sb_update_try_rollback() {
	local _rollback="$1" _rb
	[[ -d $_rollback ]] || return 1
	find "$_rollback" -mindepth 1 -maxdepth 1 -type d 2>/dev/null | while read -r _rb; do
		_sb_update_restore_one_target "$_rb" >/dev/null 2>&1 || true
	done
	return 0
}

_sb_update_copy_one_file_fuse_safe() {
	# $1=src, $2=dst. 464-r4: Android /storage FUSE/bind targets may reject cp -f/Rf overwrites.
	# Prefer cat > dst so the updater works on emulated/bind storage; fall back to remove+create.
	local _src="$1" _dst="$2" _d _mode
	[[ -f $_src && -n $_dst ]] || return 1
	_d="${_dst%/*}"
	mkdir -p "$_d" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} || return 1
	chmod u+w "$_dst" 2>/dev/null || true
	if cat "$_src" > "$_dst" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}; then
		: 
	else
		rm -f "$_dst" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} || true
		cat "$_src" > "$_dst" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} || return 1
	fi
	# Keep tools executable. 0644 files under tools are harmless as 0755; legacy updater used chmod -R 0755.
	chmod 0755 "$_dst" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} || true
	return 0
}

_sb_update_copy_tree_fuse_safe() {
	# $1=srcdir, $2=dstdir
	local _srcdir="$1" _dstdir="$2" _rel
	[[ -d $_srcdir ]] || return 1
	mkdir -p "$_dstdir" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} || return 1
	( cd "$_srcdir" 2>/dev/null && find . -type f 2>/dev/null ) | while read -r _rel; do
		[[ -n $_rel ]] || continue
		case $_rel in *../*|../*|/*) return 1 ;; esac
		_sb_update_copy_one_file_fuse_safe "$_srcdir/$_rel" "$_dstdir/$_rel" || return 1
	done
}


_sb_update_stage_is_full_release() {
	# r15: 自動更新只接受完整 release 包；避免 source/hotfix 包誤套用後缺二進位。
	# 完整 release 才允許後續把目標 tools/ 修剪成與更新包 tools/ 一致。
	local _stage="$1" _report="$2" _rel _missing=""
	[[ -d $_stage && -d $_stage/tools ]] || return 1
	for _rel in \
		start.sh \
		backup_settings.conf \
		tools/tools.sh \
		tools/dex_check.sh \
		tools/classes.dex \
		tools/jq \
		tools/tar \
		tools/zstd \
		tools/smbclient \
		tools/uidexec \
		tools/unixsock \
		tools/filewatch \
		tools/procwait \
		tools/eventwait \
		tools/keycheck
	do
		[[ -f $_stage/$_rel ]] || _missing="$_missing $_rel"
	done
	if [[ -n $_missing ]]; then
		_sb_update_report_line "$_report" "Full release validate: MISSING$_missing"
		return 1
	fi
	_sb_update_report_line "$_report" "Full release validate: OK"
	return 0
}

_sb_update_prune_tools_to_stage_manifest() {
	# r15: full release 更新時，以更新包 tools/ manifest 為準，刪除目標 tools/ 多出的舊檔。
	# 不碰 tools/ 以外的 app payload/json/wifi/media。
	local _stage_tools="$1" _target_tools="$2" _report="$3" _rel _src _dst _n=0 _fail=0
	[[ -d $_stage_tools && -d $_target_tools ]] || return 1
	( cd "$_target_tools" 2>/dev/null && find . -type f 2>/dev/null ) | while read -r _rel; do
		[[ -n $_rel ]] || continue
		case $_rel in *../*|../*|/*) continue ;; esac
		_src="$_stage_tools/$_rel"
		_dst="$_target_tools/$_rel"
		[[ -f $_src ]] && continue
		chmod u+w "$_dst" 2>/dev/null || true
		rm -f "$_dst" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} || true
		if [[ -f $_dst ]]; then
			printf 'FAIL\t%s\n' "$_rel" >> "${TMPDIR:-/data/local/tmp}/.sb_update_prune.$$"
		else
			printf 'OK\t%s\n' "$_rel" >> "${TMPDIR:-/data/local/tmp}/.sb_update_prune.$$"
		fi
	done
	if [[ -f ${TMPDIR:-/data/local/tmp}/.sb_update_prune.$$ ]]; then
		_n="$(grep -c '^OK' "${TMPDIR:-/data/local/tmp}/.sb_update_prune.$$" 2>/dev/null | tr -d ' ')"
		_fail="$(grep -c '^FAIL' "${TMPDIR:-/data/local/tmp}/.sb_update_prune.$$" 2>/dev/null | tr -d ' ')"
		_sb_update_report_line "$_report" "- tools prune: removed=${_n:-0} fail=${_fail:-0}"
		rm -f "${TMPDIR:-/data/local/tmp}/.sb_update_prune.$$" 2>/dev/null
	else
		_sb_update_report_line "$_report" "- tools prune: removed=0 fail=0"
	fi
	[[ ${_fail:-0} -eq 0 ]]
}

_sb_update_copy_tools_to_root() {
	local _stage_tools="$1" _target="$2" _report="$3"
	[[ -d $_stage_tools && -f $_stage_tools/tools.sh ]] || return 1
	mkdir -p "$_target/tools" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} || return 1
	if ! _sb_update_copy_tree_fuse_safe "$_stage_tools" "$_target/tools"; then
		_sb_update_report_line "$_report" "- tools: FAIL fuse-safe copy -> $_target/tools"
		return 1
	fi
	chmod -R 0755 "$_target/tools" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	if ! _sb_update_prune_tools_to_stage_manifest "$_stage_tools" "$_target/tools" "$_report"; then
		_sb_update_report_line "$_report" "- tools prune: FAIL -> $_target/tools"
		return 1
	fi
	chmod -R 0755 "$_target/tools" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	_sb_update_report_line "$_report" "- tools: OK full-sync -> $_target/tools"
	return 0
}

_sb_update_regen_root_start() {
	local _kind="$1" _root="$2" _report="$3" _mode
	case $_kind in
	backup|embedded) _mode=2 ;;
	*)
		if [[ -f $_root/backup_settings.conf || ! -f $_root/restore_settings.conf ]]; then
			_mode=0
		else
			_mode=2
		fi ;;
	esac
	touch_shell "$_mode" "$_root/start.sh" || return 1
	chmod 0755 "$_root/start.sh" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	_sb_update_report_line "$_report" "- start.sh: OK -> $_root/start.sh mode=$_mode"
	return 0
}

_sb_update_regen_app_wrappers() {
	local _root="$1" _report="$2" _app _cnt_file _cnt
	_cnt_file="$TMPDIR/.sb_update_wrappers.$$"
	: > "$_cnt_file" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	find "$_root" -mindepth 1 -maxdepth 1 -type d 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} | while read -r _app; do
		[[ -f $_app/app_details.json || -f $_app/app_details ]] || continue
		touch_shell "3" "$_app/recover.sh" || continue
		chmod 0755 "$_app/recover.sh" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
		echo 1 >> "$_cnt_file"
		if [[ -f $_app/backup.sh ]]; then
			touch_shell "1" "$_app/backup.sh" && chmod 0755 "$_app/backup.sh" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
		fi
		if [[ -f $_app/upload.sh ]]; then
			touch_shell "5" "$_app/upload.sh" && chmod 0755 "$_app/upload.sh" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
		fi
	done
	_cnt="$(wc -l < "$_cnt_file" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} | tr -d ' ')"
	rm -f "$_cnt_file" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	_sb_update_report_line "$_report" "- app wrappers: ${_cnt:-0} under $_root"
	return 0
}

_sb_update_apply_target() {
	local _kind="$1" _target="$2" _stage_tools="$3" _report="$4"
	[[ -d $_target ]] || return 1
	_sb_update_report_line "$_report" ""
	_sb_update_report_line "$_report" "Target: $_kind $_target"
	_sb_update_copy_tools_to_root "$_stage_tools" "$_target" "$_report" || return 1
	_sb_update_regen_root_start "$_kind" "$_target" "$_report" || return 1
	_sb_update_translate_target_confs "$_target" "$_report" || true
	case $_kind in
	backup|embedded) _sb_update_regen_app_wrappers "$_target" "$_report" || return 1 ;;
esac
	return 0
}

# 449: update_state.json 僅作自動更新/CLI/debug 狀態紀錄；不是 KSU Manager / WebUI 介面契約。
_sb_update_write_state() {
	local _state="$1" _result="$2" _from="$3" _to="$4" _targets="$5" _wrappers="$6" _rollback="$7"
	cat > "$_state" <<EOF
{"schema":1,"result":"$_result","from":"$_from","to":"$_to","targets":$_targets,"app_wrappers":$_wrappers,"rollback_available":$_rollback,"protected_data_modified":false}
EOF
}

# 451: updater workspace is transient only; do not create persistent .speedbackup_update in user directories.
# Staging/rollback/report/state live under TMPDIR and are removed after successful update.
# 452: consume successful update zip robustly and translate backup/restore settings during update.
_sb_update_delete_zip_file() {
	local _f="$1"
	[[ -n $_f && -f $_f ]] || return 0
	chmod 0600 "$_f" 2>/dev/null || true
	rm -f "$_f" 2>/dev/null || true
	[[ -f $_f ]] && command rm -f "$_f" 2>/dev/null || true
	[[ -f $_f ]] && busybox rm -f "$_f" 2>/dev/null || true
	[[ ! -f $_f ]]
}

_sb_update_zip_patch_build_from_zip() {
	local _zip="$1"
	[[ -f $_zip ]] || return 1
	unzip -p "$_zip" tools/tools.sh 2>/dev/null | awk -F= '/^speedbackup_patch_build=/ {gsub(/"/, "", $2); print $2; exit}'
}

_sb_update_zip_release_tag_from_zip() {
	# r15: return effective package version, not just release_tag.
	# Same-tag packages with a lower backup_version must be blocked as downgrade.
	local _zip="$1" _tmp _v
	[[ -f $_zip ]] || return 1
	_tmp="${TMPDIR:-/data/local/tmp}/.sb_zip_tools_$$.sh"
	unzip -p "$_zip" tools/tools.sh > "$_tmp" 2>/dev/null || { rm -f "$_tmp" 2>/dev/null; return 1; }
	_v="$(_sb_update_effective_version_of "$_tmp")"
	rm -f "$_tmp" 2>/dev/null
	printf '%s\n' "$_v"
}

_sb_update_translate_target_confs() {
	local _root="$1" _report="$2" _c _n=0
	[[ -n $Script_target_language && -d $_root ]] || return 0
	for _c in "$_root/backup_settings.conf" "$_root/restore_settings.conf"; do
		[[ -f $_c ]] || continue
		if ts_inplace "$_c"; then
			_conf_sanitize_legacy_comment_noise "$_c"
			_n=$((_n + 1))
		fi
	done
	[[ $_n -gt 0 ]] && _sb_update_report_line "$_report" "- translated conf files: $_n -> $_root"
	return 0
}

_sb_update_prune_success_artifacts() {
	local _update_dir="$1" _stage="$2" _rollback="$3" _zip_abs="$4" _report="$5" _sha
	[[ -n $_report ]] && _sb_update_report_line "$_report" ""
	if [[ -n $_zip_abs && -f $_zip_abs ]]; then
		_sha="$(sha256sum "$_zip_abs" 2>/dev/null | awk '{print $1}')"
		[[ -n $_sha && -n $_report ]] && _sb_update_report_line "$_report" "Applied zip sha256: $_sha"
		if _sb_update_delete_zip_file "$_zip_abs"; then
			[[ -n $_report ]] && _sb_update_report_line "$_report" "Source zip removed: $_zip_abs"
		else
			[[ -n $_report ]] && _sb_update_report_line "$_report" "WARNING: source zip remove failed: $_zip_abs"
		fi
	fi
	rm -rf "$_stage" "$_rollback" "$_update_dir"/staging "$_update_dir"/applied_*.zip 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	# If a previous 448/449 successful run left rollback copies, compact them on the next successful updater run.
	if [[ -f $_update_dir/update_state.json ]] && grep -q '"result":"ok"' "$_update_dir/update_state.json" 2>/dev/null; then
		rm -rf "$_update_dir"/rollback/* 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	fi
	[[ -n $_report ]] && _sb_update_report_line "$_report" "Workspace cleanup: transient updater workspace removed"
}

_sb_update_copy_artifacts_to_debug() {
	# r15: do not leave updater workspaces in TMPDIR just to preserve diagnostics.
	# Copy report/state into current speed_debug run before removing the transient workspace.
	local _report="$1" _state="$2" _dst
	[[ -n ${SPEED_DEBUG_RUN_DIR:-} && -d ${SPEED_DEBUG_RUN_DIR:-} ]] || return 0
	_dst="$SPEED_DEBUG_RUN_DIR"
	[[ -f $_report ]] && cp -f "$_report" "$_dst/update_report.log" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} || true
	[[ -f $_state ]] && cp -f "$_state" "$_dst/update_state.json" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} || true
}

_sb_update_cleanup_workspace() {
	local _update_dir="$1" _report="$2" _state="$3" _reason="$4"
	[[ -n $_report && -f $_report ]] && _sb_update_report_line "$_report" "Workspace cleanup: reason=${_reason:-unknown} transient updater workspace removed"
	_sb_update_copy_artifacts_to_debug "$_report" "$_state"
	[[ -n $_update_dir ]] && rm -rf "$_update_dir" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
}


# 從 zip 檔自動更新腳本：451 起 staging/validate/rollback/report 只使用 TMPDIR 暫存，不在使用者目錄產生 .speedbackup_update；452 成功後強制消耗更新包並同步翻譯 conf。
# 放在主根：更新主 tools/start.sh + 所有 Backup_zstd_*/tools/start/recover。
# 放在 Backup_zstd_X：更新此備份根 tools/start/recover，並往回同步上一層主 tools/start.sh（若存在）。
update_script() {
	[[ -n $1 ]] && zipFile="$1"
	[[ -z $zipFile ]] && zipFile="$(find "$MODDIR" -maxdepth 1 -name "*.zip" -type f 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null})"
	[[ -z $zipFile ]] && { unset NAME; return 0; }
	case $zipFile in
	*$'\n'*)
		echoRgb "錯誤 請刪除當前目錄多餘zip\n -保留一個最新的更新包.zip\n -下列為當前目錄zip\n$zipFile" "0"
		exit 1 ;;
	esac
	_sb_update_zip_has_core "$zipFile" || { unset NAME; return 0; }
	local _zip_abs _zip_dir _update_dir _stage _rollback _report _state _targets _stage_tools
	local _from _to _tag_from _tag_to _bv_to _target_count _wrapper_count _kind _target _abort_hint
	_zip_abs="$zipFile"
	case $_zip_abs in
	/*) ;;
	*) _zip_abs="$(pwd -P)/$_zip_abs" ;;
	esac
	_zip_dir="${_zip_abs%/*}"
	_zip_dir="$(cd "$_zip_dir" 2>/dev/null && pwd -P)"
	[[ -z $_zip_dir || ! -d $_zip_dir ]] && { echoRgb "更新失敗: 無法解析更新包目錄" "0"; return 1; }
	_update_dir="${TMPDIR:-/data/local/tmp}/speedbackup_update.$$"
	_stage="$_update_dir/staging"
	_rollback="$_update_dir/rollback/$(date +%Y%m%d-%H%M%S)"
	_report="$_update_dir/update_report.log"
	_state="$_update_dir/update_state.json"
	_targets="$_update_dir/targets.$$"
	mkdir -p "$_update_dir" "$_stage" "$_rollback" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} || { echoRgb "更新失敗: 無法建立 updater 暫存目錄" "0"; return 1; }
	printf '%s\n' "pid=$$ time=$(date '+%Y-%m-%d %H:%M:%S') zip=$_zip_abs" > "$_update_dir/lock"
	: > "$_report"
	_sb_update_report_line "$_report" "SpeedBackup Update Report"
	_sb_update_report_line "$_report" "========================="
	_sb_update_report_line "$_report" "Zip: $_zip_abs"
	_sb_update_report_line "$_report" "Zip dir: $_zip_dir"
	_sb_update_report_line "$_report" ""
	rm -rf "$_stage" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	mkdir -p "$_stage" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	if ! unzip -o "$_zip_abs" -d "$_stage" >> "$_report" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}; then
		_sb_update_report_line "$_report" "Result: FAIL staging unzip"
		_sb_update_write_state "$_state" "fail_unzip" "$speedbackup_patch_build" "unknown" 0 0 false
		_sb_update_cleanup_workspace "$_update_dir" "$_report" "$_state" "fail_unzip"
		echoRgb "更新失敗: 解壓 staging 失敗，暫存已清理，詳見 speed_debug/update_report.log" "0"
		return 1
	fi
	_stage_tools="$_stage/tools"
	if [[ ! -f $_stage_tools/tools.sh || ! -f $_stage_tools/dex_check.sh ]]; then
		_sb_update_report_line "$_report" "Result: FAIL staging validate"
		_sb_update_write_state "$_state" "fail_validate" "$speedbackup_patch_build" "unknown" 0 0 false
		_sb_update_cleanup_workspace "$_update_dir" "$_report" "$_state" "fail_validate"
		echoRgb "更新失敗: 更新包缺 tools/tools.sh 或 tools/dex_check.sh，暫存已清理，詳見 speed_debug/update_report.log" "0"
		return 1
	fi
	if ! _sb_update_stage_is_full_release "$_stage" "$_report"; then
		_sb_update_report_line "$_report" "Result: FAIL full release validate"
		_sb_update_write_state "$_state" "fail_full_release_validate" "$speedbackup_patch_build" "unknown" 0 0 false
		_sb_update_cleanup_workspace "$_update_dir" "$_report" "$_state" "fail_full_release_validate"
		echoRgb "更新失敗: 更新包不是完整 release，拒絕覆蓋/修剪 tools/，暫存已清理" "0"
		return 1
	fi
	_to="$(_sb_update_patch_build_of "$_stage_tools/tools.sh")"
	_bv_to="$(_sb_update_backup_version_of "$_stage_tools/tools.sh")"
	_raw_tag_to="$(_sb_update_release_tag_of "$_stage_tools/tools.sh")"
	_tag_to="$(_sb_update_effective_version_of "$_stage_tools/tools.sh")"
	_from="${speedbackup_patch_build:-unknown}"
	_tag_from="$(_speedbackup_update_local_tag)"
	[[ -z $_to ]] && _to="unknown"
	_sb_update_report_line "$_report" "From: $_from"
	_sb_update_report_line "$_report" "To:   $_to"
	_sb_update_report_line "$_report" "effective_version(from): $_tag_from"
	_sb_update_report_line "$_report" "effective_version(to): $_tag_to"
	_sb_update_report_line "$_report" "release_tag(to): $_raw_tag_to"
	_sb_update_report_line "$_report" "backup_version(to): $_bv_to"
	# r15: local full-release zip may overwrite at the same effective version, but downward updates are blocked.
	# Online latest with the same tag remains NO_NEWER to avoid repeated update prompts.
	if [[ -z $_tag_to || -z $_tag_from ]]; then
		_sb_update_report_line "$_report" "Result: BLOCK unknown update version"
		_sb_update_write_state "$_state" "block_unknown_version" "$_from" "$_to" 0 0 false
		_sb_update_cleanup_workspace "$_update_dir" "$_report" "$_state" "block_unknown_version"
		echoRgb "更新已拒絕: 更新包版本無法判定，避免誤覆蓋，暫存已清理" "0"
		return 1
	fi
	if _speedbackup_remote_tag_newer "$_tag_to" "$_tag_from"; then
		_sb_update_report_line "$_report" "Result: BLOCK downgrade"
		_sb_update_write_state "$_state" "block_downgrade" "$_from" "$_to" 0 0 false
		_sb_update_cleanup_workspace "$_update_dir" "$_report" "$_state" "block_downgrade"
		echoRgb "更新已拒絕: 不接受向下更新 local=$_tag_from package=$_tag_to，暫存已清理" "0"
		return 1
	fi
	if [[ $_tag_to = "$_tag_from" ]]; then
		_sb_update_report_line "$_report" "Policy: same release tag overwrite allowed"
	fi
	# 455: 只禁止「啟動時」掃描並改寫已安裝 tools.sh。
	# 更新流程翻譯新版 tools.sh / conf；r393 起 Device_List 純全量匯入 Dex；r395 修正早期 deviceFacts 呼叫不依賴後置 _dex_raw；r396 補齊 device model prop candidates；r397 改用 public product/odm model 優先，避免 vendor model 誤判地區版本；r398 修正 restore_stream_perf.tsv mode 欄位同步；r399 將 stream extract wait 改為 watchdog + wait，移除小 payload 1 秒輪詢尾延遲；r400 加入 APK timing / apkAction early decision，並將 stream wait 預設改為 FIFO event；r401 修正 FIFO event read 被 SIGCHLD/EINTR 打斷時的終端噪音與 fallback；r402 修正 restore_stream_perf.tsv / restore_apk_timing.tsv mode 欄位仍寫 r400。
	if [[ -n $Script_target_language ]]; then
		local _stage_lang
		_stage_lang="$(awk -F= '/^shell_language=/ {gsub(/"/, "", $2); print $2; exit}' "$_stage_tools/tools.sh" 2>/dev/null)"
		if [[ -n $_stage_lang && $_stage_lang != "$Script_target_language" ]]; then
			_sb_update_report_line "$_report" "Translate staging: $_stage_lang -> $Script_target_language"
			[[ -f $_stage/backup_settings.conf ]] && ts_inplace "$_stage/backup_settings.conf"
			[[ -f $_stage/restore_settings.conf ]] && ts_inplace "$_stage/restore_settings.conf"
			ts_inplace "$_stage_tools/tools.sh" && sed -i "s/shell_language=\"$_stage_lang\"/shell_language=\"$Script_target_language\"/g" "$_stage_tools/tools.sh" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
		fi
	fi
	_sb_update_collect_targets "$_zip_dir" "$_targets" || {
		_sb_update_report_line "$_report" "Result: FAIL target collect"
		_sb_update_write_state "$_state" "fail_targets" "$_from" "$_to" 0 0 false
		_sb_update_cleanup_workspace "$_update_dir" "$_report" "$_state" "fail_targets"
		echoRgb "更新失敗: 無法判定要更新的 SpeedBackup 根目錄，暫存已清理，詳見 speed_debug/update_report.log" "0"
		return 1
	}
	if grep -q '^abort_app_dir' "$_targets" 2>/dev/null; then
		_abort_hint="$(awk -F'\t' '/^abort_app_dir/{print $2; exit}' "$_targets")"
		_sb_update_report_line "$_report" "Result: ABORT app directory"
		_sb_update_write_state "$_state" "abort_app_dir" "$_from" "$_to" 0 0 false
		_sb_update_cleanup_workspace "$_update_dir" "$_report" "$_state" "abort_app_dir"
		echoRgb "偵測到更新包: ${_zip_abs##*/}" "2"
		echoRgb "⚠ 目前在單一應用備份目錄內，避免誤更新，請把更新包放到以下其中之一後再執行:\n -$_abort_hint\n -${_abort_hint%/*}" "0"
		return 0
	fi
	_target_count="$(wc -l < "$_targets" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} | tr -d ' ')"
	[[ ${_target_count:-0} -gt 0 ]] || {
		_sb_update_report_line "$_report" "Result: FAIL no targets"
		_sb_update_write_state "$_state" "fail_no_targets" "$_from" "$_to" 0 0 false
		_sb_update_cleanup_workspace "$_update_dir" "$_report" "$_state" "fail_no_targets"
		echoRgb "更新失敗: 找不到可更新目標，暫存已清理，詳見 speed_debug/update_report.log" "0"
		return 1
	}
	_sb_update_report_line "$_report" "Targets: $_target_count"
	while IFS='	' read -r _kind _target; do
		[[ -z $_kind || -z $_target ]] && continue
		if _sb_update_target_is_external_inbox "$_target"; then
			_sb_update_report_line "$_report" "Result: FAIL unsafe external inbox target=$_target"
			_sb_update_write_state "$_state" "fail_unsafe_external_inbox_target" "$_from" "$_to" "$_target_count" 0 true
			_sb_update_cleanup_workspace "$_update_dir" "$_report" "$_state" "fail_unsafe_external_inbox_target"
			echoRgb "更新失敗: 拒絕把 Download/QQ 收件目錄當更新目標，已保護外部 Tools 目錄" "0"
			return 1
		fi
	done < "$_targets"
	while IFS='	' read -r _kind _target; do
		[[ -z $_kind || -z $_target ]] && continue
		_sb_update_backup_target_for_rollback "$_target" "$_rollback" || true
	done < "$_targets"
	_wrapper_count=0
	while IFS='	' read -r _kind _target; do
		[[ -z $_kind || -z $_target ]] && continue
		if ! _sb_update_apply_target "$_kind" "$_target" "$_stage_tools" "$_report"; then
			_sb_update_report_line "$_report" "Result: FAIL apply target=$_target"
			_sb_update_try_rollback "$_rollback" >/dev/null 2>&1 || true
			_sb_update_write_state "$_state" "fail_apply_rollback_attempted" "$_from" "$_to" "$_target_count" "$_wrapper_count" true
			_sb_update_cleanup_workspace "$_update_dir" "$_report" "$_state" "fail_apply_rollback_attempted"
			echoRgb "更新失敗: 目標更新失敗，已嘗試 rollback，暫存已清理，詳見 speed_debug/update_report.log" "0"
			return 1
		fi
		case $_kind in
		backup|embedded)
			local _wc
			_wc="$(find "$_target" -mindepth 1 -maxdepth 1 -type d 2>/dev/null | while read -r _d; do [[ -f $_d/app_details.json || -f $_d/app_details ]] && echo 1; done | wc -l | tr -d ' ')"
			_wrapper_count=$((_wrapper_count + ${_wc:-0})) ;;
		esac
	done < "$_targets"
	_sb_update_report_line "$_report" ""
	_sb_update_report_line "$_report" "Protected: app archives/json untouched"
	_sb_update_report_line "$_report" "Result: OK"
	# 450/r15: rollback/report/state are copied to speed_debug on failure and TMP workspace is removed.
	_sb_update_write_state "$_state" "ok" "$_from" "$_to" "$_target_count" "$_wrapper_count" false
	_sb_update_prune_success_artifacts "$_update_dir" "$_stage" "$_rollback" "$_zip_abs" "$_report"
	rm -rf "$_update_dir" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	echoRgb "更新完成: $_to" "1"
	echoRgb "更新暫存已清理，不會保留 .speedbackup_update" "3"
	echoRgb "請重新執行腳本" "2"
	exit 0
}
update_script
# 掃 Download 和 QQ 收件匣，找到有效 zip 直接傳入 update_script
# 兩個來源都嘗試 (Download 有無關 zip 時不該擋住 QQ 的更新包)。
# 不用 ls <dir>/*.zip：目錄存在但沒有 zip 時，未匹配 glob 會把「No such file or directory」寫進 stderr.log。
_latest_zip_in_dir() {
	local _dir="$1"
	[[ -d $_dir ]] || return 0
	find "$_dir" -maxdepth 1 -type f -name '*.zip' -printf '%T@\t%p\n' 2>/dev/null |
		sort -nr 2>/dev/null | head -1 | cut -f2-
}
_dl_zip="$(_latest_zip_in_dir /storage/emulated/0/Download)"
_qq_zip="$(_latest_zip_in_dir /storage/emulated/0/Android/data/com.tencent.mobileqq/Tencent/QQfile_recv)"
for _try_zip in "$_dl_zip" "$_qq_zip"; do
	[[ -z $_try_zip ]] && continue
	# 448: 只要含 tools/tools.sh 即視為 SpeedBackup 更新包；不再要求 backup_settings.conf。
	if _sb_update_zip_has_core "$_try_zip"; then
		_try_to="$(_sb_update_zip_patch_build_from_zip "$_try_zip")"
		_try_tag="$(_sb_update_zip_release_tag_from_zip "$_try_zip")"
		_try_local_tag="$(_speedbackup_update_local_tag)"
		if [[ -z $_try_tag ]]; then
			echoRgb "拒絕更新包: ${_try_zip##*/} 版本無法判定" "0"
			continue
		fi
		if _speedbackup_remote_tag_newer "$_try_tag" "$_try_local_tag"; then
			echoRgb "拒絕向下更新包: ${_try_zip##*/} local=$_try_local_tag package=$_try_tag" "0"
			continue
		fi
		if [[ $_try_tag = "$_try_local_tag" ]]; then
			echoRgb "偵測到同版本覆蓋更新包: ${_try_zip##*/}" "2"
		else
			echoRgb "偵測到更新包: ${_try_zip##*/}" "2"
		fi
		update_script "$_try_zip"
	fi
done
unset _dl_zip _qq_zip _try_zip _try_to _try_tag _try_local_tag
unset -f _latest_zip_in_dir 2>/dev/null || true
# 456: Shell_LANG 啟動語系同步恢復，但不再逐一改每份 Backup_*/tools/tools.sh。
# 只翻譯主根 tools/tools.sh 一份，再整體同步到 Backup_* 內嵌 tools/ 並重生 wrapper。
_speedbackup_startup_language_sync "$path_hierarchy"
# 447: 啟動時補同步既有 Backup_* 內嵌 tools 與入口 wrapper，修正先前自動更新只更新主目錄 tools/ 的情境。
_speedbackup_sync_embedded_backup_tools "$path_hierarchy"
# APK 安裝統一走 installapk() 內部函數。
# Play 來源 app 可優先使用 Play UID daemon 建立/提交 session，APK bytes 仍由 root pm install-write 寫入；
# 傳統 pm fallback 仍保留 -i <installer> 偽裝來源，但 initiatingPackageName 仍會是 shell。
#settings get system system_locales
Language="https://api.github.com/repos/YAWAsau/backup_script/releases/latest"
# 自動更新流程仍會在 staging 內翻譯新版 tools.sh/conf；Device_List 不再外置。
# 479-r40: 線上更新比較 installed backup_version；release_tag 僅舊包 fallback，避免同版 release 反覆提示。所有提示/不提示都寫入 speed_debug/update_check.log。
_speedbackup_update_config_rescue
_update_local_tag="$(_speedbackup_update_local_tag)"
_speedbackup_update_debug_log "BEGIN local=$_update_local_tag backup_version=${backup_version:-} patch=${speedbackup_patch_build:-} update=${update:-<empty>} cdn=${cdn:-<empty>} url=$Language"
#校驗選填是否正確
ask_yn_indep "自動更新腳本?" "更新" "不更新" update
_speedbackup_update_debug_log "CONFIG update=$update cdn=${cdn:-<empty>}"
if [[ $update = true ]]; then
	json="$(down "$Language")"
	_speedbackup_update_debug_log "FETCH bytes=$(printf '%s' "$json" | wc -c | tr -d ' ')"
else
	_speedbackup_update_debug_log "DISABLED_BY_CONFIG local=$_update_local_tag"
	echoRgb "自動更新被關閉" "0"
fi
if [[ $json != "" ]]; then
	tag="$(_release_json_tag "$json")"
	if [[ $tag = "" ]]; then
		_json_sample="$(printf '%s' "$json" | tr '\n' ' ' | cut -c1-160)"
		_speedbackup_update_debug_log "JSON_INVALID bytes=$(printf '%s' "$json" | wc -c | tr -d ' ') sample=$_json_sample"
		[[ $update = true ]] && echoRgb "更新獲取失敗: GitHub release API 回傳不是有效 JSON 或缺少 tag_name" "0"
		unset _json_sample
	elif _speedbackup_remote_tag_newer "$tag" "$_update_local_tag"; then
		_speedbackup_update_debug_log "DOWNGRADE_BLOCKED local=$_update_local_tag remote=$tag patch=${speedbackup_patch_build:-}"
		[[ $update = true ]] && echoRgb "已忽略較舊線上版本:$tag，目前版本:$_update_local_tag" "3"
	elif _speedbackup_remote_tag_newer "$_update_local_tag" "$tag"; then
		_speedbackup_update_debug_log "NEWER local=$_update_local_tag remote=$tag patch=${speedbackup_patch_build:-}"
		_update_notice="發現新版本"
		download="$(_release_json_asset_urls "$json" | head -n 1)"
		if [[ -z $download ]]; then
			_speedbackup_update_debug_log "ASSET_MISSING tag=$tag"
			[[ $update = true ]] && echoRgb "發現新版本:$tag，但 release 沒有可下載 zip asset" "0"
		else
			case $cdn in
			0) zip_url="$download" ;;
			1) zip_url="https://ghfast.top/$download" ;;
			2) zip_url="https://shrill-pond-3e81.hunsh.workers.dev/$download" ;;
			*) echoRgb "$conf_path cdn=設置錯誤 範圍只能是0-2" && exit 2 ;;
			esac
			echoRgb "$_update_notice:$tag"
			# 在應用備份目錄內: 僅提示去正確目錄，不執行下載
			_skip_update_dl=0
			case $MODDIR in
			*Backup_*)
				if [[ -f $MODDIR/app_details.json ]]; then
					echoRgb "⚠ 目前在應用備份目錄內，無法在此下載更新" "0"
					echoRgb "請到以下目錄執行 start.sh 後即可自動更新:\n -${path_hierarchy:-${MODDIR%/*}}" "3"
					_skip_update_dl=1
				fi ;;
			esac
			if [[ $_skip_update_dl = 0 && $update = true ]]; then
				echoRgb "$(ts "更新日誌:\n$(_release_json_body "$json")")"
				if ask_yn "是否更新腳本?" "更新" "不更新" choose; then
					echoRgb "下載中.....耐心等待 如果下載失敗請掛飛機"
					starttime1="$(date -u "+%s")"
					_dl_dest="${path_hierarchy:-$MODDIR}"
					down "$zip_url" >"$_dl_dest/update.zip" &
					wait $!
					endtime 1
					[[ ! -f $_dl_dest/update.zip ]] && echoRgb "下載失敗" && exit 2
					zipFile="$_dl_dest/update.zip"
					unset _dl_dest
				fi
			elif [[ $_skip_update_dl = 0 ]]; then
				echoRgb "$conf_path內update選項為0忽略更新僅提示更新" "0"
			fi
			unset _skip_update_dl
		fi
	else
		_speedbackup_update_debug_log "NO_NEWER local=$_update_local_tag remote=$tag patch=${speedbackup_patch_build:-}"
	fi
else
	_speedbackup_update_debug_log "FETCH_EMPTY update=$update"
	[[ $update = true ]] && echoRgb "更新獲取失敗" "0"
fi
unset _update_local_tag _update_notice
update_script
# 給定路徑, 穿透 bind/FUSE 找出真實底層的「可餵給 df 的路徑」
# 用於 Android emulated storage (sdcardfs/FUSE) 上 bind 了其他分區的情況
# 例: /storage/emulated/0/虛擬分區 實際是 /mnt/YAWAsau/備份 的 bind, 應回傳 /mnt/YAWAsau
# 策略:
#   1) 先把已知的 sdcardfs/FUSE 視圖路徑顯式轉成內核真實路徑 /data/media/<N>/<X>
#      (不能用 realpath, /storage/emulated 通常是 symlink 到 /mnt/installer/.../emulated,
#       resolve 後反而會撞到 FUSE 掛載點, 拿不到底下的 bind)
#   2) 在 /proc/self/mountinfo 找 mp 是 target 祖先的最長匹配 → 取得 source
#   3) 找同 source 且 root="/" 的 canonical mountpoint, 回傳該路徑
#      (Android toybox df 不接受 block device, 必須回傳真實「路徑」)
#   4) 找不到 canonical 時, 若 source 是現存目錄就用 source, 否則原樣回傳
_resolve_real_mount() {
	local p="$1" rp target rest out
	[[ -z $p ]] && { echo "$p"; return; }
	# 先 readlink -f 一次, 解開常見入口 symlink (/sdcard, /storage/self/primary, /mnt/sdcard 等)
	# 注意: 之前嘗試過 realpath 會把 /storage/emulated/0 解成 /mnt/installer/.../emulated/0,
	# 撞到 FUSE 掛載點; 現在下方 case 已涵蓋 /mnt/installer/... 等視圖, 所以 readlink 後也能正確處理
	rp="$(readlink -f "$p" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null})"
	[[ -n $rp ]] && p="$rp"
	# 把已知 sdcardfs/FUSE 視圖路徑剝皮成 /data/media/<N>/<X>
	case "$p" in
		/storage/emulated/*)            rest="${p#/storage/emulated/}"; target="/data/media/$rest" ;;
		/mnt/installer/*/emulated/*)    rest="${p##*/emulated/}"; target="/data/media/$rest" ;;
		/mnt/runtime/*/emulated/*)      rest="${p##*/emulated/}"; target="/data/media/$rest" ;;
		/mnt/pass_through/*/emulated/*) rest="${p##*/emulated/}"; target="/data/media/$rest" ;;
		/mnt/user/*/emulated/*)         rest="${p##*/emulated/}"; target="/data/media/$rest" ;;
		*)                              target="$p" ;;
	esac
	out="$(awk -v target="$target" '
	function unesc(s) { gsub(/\\040/, " ", s); return s }
	{
		root=unesc($4); mp=unesc($5)
		i=6; while (i<=NF && $i!="-") i++
		src=unesc($(i+2))
		n++; mp_a[n]=mp; root_a[n]=root; src_a[n]=src
	}
	END {
		best_len=-1
		for (i=1; i<=n; i++) {
			m=mp_a[i]
			if (m==target || index(target, m"/")==1) {
				if (length(m) > best_len) { best_len=length(m); R_src=src_a[i] }
			}
		}
		if (best_len<0) exit
		# 找同 source 且 root="/" 的 canonical mountpoint
		for (i=1; i<=n; i++) {
			if (src_a[i]==R_src && root_a[i]=="/") { print mp_a[i]; exit }
		}
		# 沒 canonical 且 source 是路徑而非 /dev/*, 就用 source
		if (substr(R_src,1,1)=="/" && R_src !~ /^\/dev\//) print R_src
	}' /proc/self/mountinfo 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null})"
	if [[ -n $out ]] && [[ -d $out || -b $out ]]; then
		echo "$out"
	else
		echo "$p"
	fi
}
_backup_df_target() {
	local _p="$1" _fallback _resolved
	[[ -n $_p ]] || return 1
	_resolved="$(_backup_resolved_mounted_path "$_p")"
	if [[ -n $_resolved ]] && df -h "$_resolved" >/dev/null 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}; then
		echo "$_resolved"
		return 0
	fi
	if df -h "$_p" >/dev/null 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}; then
		echo "$_p"
		return 0
	fi
	_fallback="$(_resolve_real_mount "${_p%/*}")"
	[[ -n $_fallback ]] && echo "$_fallback" || echo "$_p"
}
_backup_mount_point() {
	local _p="$1" _mp
	_mp="$(df -h "$_p" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} | awk 'NR==2{print $NF; exit}')"
	printf '%s\n' "$_mp"
}
_backup_resolved_mounted_path() {
	# r421: 若備份目錄位於 /storage/emulated 視圖中的 bind/mount 子樹，
	# df 原路徑會先命中整個 /storage/emulated FUSE，顯示成內置儲存。
	# 這裡只在 resolve 出非 /data* 的真實掛載路徑時採用，避免一般內置儲存顯示被改成 /data。
	local _p="$1" _r
	[[ -n $_p ]] || return 1
	_r="$(_resolve_real_mount "$_p")"
	[[ -n $_r && $_r != "$_p" ]] || return 1
	case "$_r" in
		/data|/data/*) return 1 ;;
	esac
	[[ -e $_r || -d $_r ]] || return 1
	printf '%s\n' "$_r"
}
_backup_underlying_storage_path() {
	local _p="$1" _rest _candidate _resolved
	_resolved="$(_backup_resolved_mounted_path "$_p")"
	if [[ -n $_resolved && $_resolved != "$_p" ]]; then
		printf '%s\n' "$_resolved"
		return 0
	fi
	case "$_p" in
	/storage/emulated/0/*)
		_rest="${_p#/storage/emulated/0/}"
		_candidate="/data/media/0/$_rest"
		;;
	/storage/emulated/*)
		_rest="${_p#/storage/emulated/}"
		_candidate="/data/media/$_rest"
		;;
	/sdcard/*)
		_rest="${_p#/sdcard/}"
		_candidate="/data/media/0/$_rest"
		;;
	*) return 1 ;;
	esac
	[[ -e $_candidate ]] && printf '%s\n' "$_candidate"
}

# r374: Media/自訂資料夾在 root 讀寫時優先走 /data/media/<user> lower path，避開 /storage/emulated FUSE 熱路徑。
# 對外仍保留使用者設定的原始顯示路徑，app_details.json 不改寫成 lower path。
_media_storage_lower_path() {
	local _p="$1" _rest _uid _cand
	[[ -n $_p ]] || return 1
	case "$_p" in
	/storage/emulated/0/*)
		_rest="${_p#/storage/emulated/0/}"
		_cand="/data/media/0/$_rest"
		;;
	/storage/emulated/*/*)
		_rest="${_p#/storage/emulated/}"
		_uid="${_rest%%/*}"
		_rest="${_rest#*/}"
		case $_uid in ''|*[!0-9]*) return 1 ;; esac
		_cand="/data/media/$_uid/$_rest"
		;;
	/sdcard/*)
		_rest="${_p#/sdcard/}"
		_cand="/data/media/0/$_rest"
		;;
	/mnt/pass_through/0/emulated/0/*)
		_rest="${_p#/mnt/pass_through/0/emulated/0/}"
		_cand="/data/media/0/$_rest"
		;;
	*) return 1 ;;
	esac
	[[ -n $_cand ]] || return 1
	printf '%s\n' "$_cand"
}

_media_path_log_value() {
	_speed_debug_kv "$(_speed_debug_safe "$1")"
}

_media_backup_perf_done() {
	local _stream="$1" _start="$2" _rc="$3" _rel="$4" _extra="$5"
	local _end _elapsed _bytes _avg _entry _display _actual _path_mode
	[[ ${BACKUP_TAR_CONTEXT_KIND:-} = media_custom ]] || return 0
	_end="$(_speed_now_ms)"
	case $_start in ''|*[!0-9]*) _elapsed=unknown ;; *) _elapsed=$((_end - _start)) ;; esac
	_bytes="${BACKUP_TAR_CONTEXT_ORIGIN_SIZE:-0}"
	case $_bytes in ''|*[!0-9]*) _bytes=0 ;; esac
	case $_elapsed in ''|*[!0-9]*|0|unknown) _avg=unknown ;; *) _avg="$(_webdav_speed_mib_s "$_bytes" "$_elapsed")" ;; esac
	_entry="${BACKUP_TAR_CONTEXT_ENTRY:-}"
	_display="${BACKUP_TAR_CONTEXT_DISPLAY_PATH:-}"
	_actual="${BACKUP_TAR_CONTEXT_ACTUAL_PATH:-}"
	_path_mode="${BACKUP_TAR_CONTEXT_PATH_MODE:-original}"
	_speed_debug_log "MEDIA_BACKUP_PERF entry=$_entry bytes=$_bytes elapsedMs=$_elapsed avgMiBps=$_avg stream=$_stream transport=${remote_type:-local} archiveRel=$_rel rc=$_rc pathMode=$_path_mode displayPath=$(_media_path_log_value "$_display") actualPath=$(_media_path_log_value "$_actual") $_extra mode=r377"
}

_media_restore_perf_done() {
	local _stream="$1" _start="$2" _bytes="$3" _rc="$4" _payload="$5" _src="$6" _dest="$7" _display="$8" _actual="$9"
	shift 9
	local _path_mode="$1" _end _elapsed _avg
	case $_bytes in ''|*[!0-9]*) _bytes=0 ;; esac
	_end="$(_speed_now_ms)"
	case $_start in ''|*[!0-9]*) _elapsed=unknown ;; *) _elapsed=$((_end - _start)) ;; esac
	case $_elapsed in ''|*[!0-9]*|0|unknown) _avg=unknown ;; *) _avg="$(_webdav_speed_mib_s "$_bytes" "$_elapsed")" ;; esac
	_speed_debug_log "MEDIA_RESTORE_PERF payload=$_payload bytes=$_bytes elapsedMs=$_elapsed avgMiBps=$_avg stream=$_stream transport=${remote_type:-local} src=$(_media_path_log_value "$_src") dest=$(_media_path_log_value "$_dest") rc=$_rc pathMode=${_path_mode:-original} displayPath=$(_media_path_log_value "$_display") actualPath=$(_media_path_log_value "$_actual") mode=r377"
}

_backup_mount_display_suffix() {
	local _backup="$1" _df_target="$2" _mp _under _out="" _label="底層對應" _resolved
	_mp="$(_backup_mount_point "$_df_target")"
	[[ -n $_mp ]] && _out=" -└─ 掛載點: $_mp"
	_resolved="$(_backup_resolved_mounted_path "$_backup")"
	if [[ -n $_resolved ]]; then
		_under="$_resolved"
		_label="實際統計路徑"
	else
		_under="$(_backup_underlying_storage_path "$_backup")"
	fi
	if [[ -n $_under && $_under != "$_backup" ]]; then
		if [[ -n $_out ]]; then
			_out="$_out
 -└─ $_label: $_under"
		else
			_out=" -└─ $_label: $_under"
		fi
	fi
	printf '%s' "$_out"
}

_backup_df_summary_from_output() {
	# r465: Android/toybox df may wrap a long Filesystem column onto its own line.
	# Do not assume NR==2 or fixed columns.  Find the first row that contains
	# a real Size/Used/Avail/Use% tuple; this also handles the continuation row
	# after a wrapped filesystem/source line.
	awk '
		function header_token(v) {
			return (v == "Size" || v == "Used" || v == "Avail" || v == "Available" || v == "Use%" || v == "1K-blocks" || v == "1024-blocks")
		}
		function metric_token(v) {
			return (v ~ /^[0-9][0-9.]*([KMGTPE]i?|[KMGTPE])?$/)
		}
		{
			for (i = 1; i <= NF - 3; i++) {
				if ($(i + 3) ~ /^[0-9]+%$/ && !header_token($i) && metric_token($i) && metric_token($(i + 1)) && metric_token($(i + 2))) {
					print "總共:" $i "已用:" $(i + 1) "剩餘:" $(i + 2) "使用率:" $(i + 3)
					exit
				}
			}
		}
	'
}

_backup_partition_fs_type_from_mountinfo() {
	local _target="$1"
	[[ -n $_target && -r /proc/self/mountinfo ]] || return 1
	awk -v target="$_target" '
		function unesc(s) {
			gsub(/\\040/, " ", s)
			gsub(/\\011/, "\t", s)
			gsub(/\\012/, "\n", s)
			gsub(/\\134/, "\\", s)
			return s
		}
		function is_prefix(path, mp) {
			if (mp == "/") return 1
			return (path == mp || index(path, mp "/") == 1)
		}
		{
			sep = 0
			for (i = 1; i <= NF; i++) {
				if ($i == "-") { sep = i; break }
			}
			if (sep <= 0 || sep + 1 > NF) next
			mp = unesc($5)
			fs = $(sep + 1)
			if (is_prefix(target, mp) && length(mp) >= best_len) {
				best_len = length(mp)
				best = fs
			}
		}
		END { if (best != "") print best }
	' /proc/self/mountinfo 2>/dev/null
}

_backup_partition_fs_type_from_df() {
	local _target="$1"
	# df -T is not stable on every Android build, but when available we parse it
	# as a fallback without assuming that the filesystem/source column is short.
	df -T "$_target" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} | awk '
		function metric_token(v) { return (v ~ /^[0-9][0-9.]*([KMGTPE]i?|[KMGTPE])?$/) }
		{
			for (i = 2; i <= NF - 3; i++) {
				if ($(i + 3) ~ /^[0-9]+%$/ && metric_token($i) && metric_token($(i + 1)) && metric_token($(i + 2))) {
					print $(i - 1)
					exit
				}
			}
		}
	'
}

_backup_partition_summary() {
	local _target="$1" _summary="" _fs="" _df_out="" _ss_out="" _ss_line="" _ss_mount="" _ss_src=""
	if _ss_out="$(_speedscan_storage_summary "$_target" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null})"; then
		_ss_line="$(printf '%s\n' "$_ss_out" | awk -F '\t' '$1=="OK"{print; exit}')"
		if [[ -n $_ss_line ]]; then
			_summary="$(printf '%s\n' "$_ss_line" | awk -F '\t' '{printf "總共:%s已用:%s剩餘:%s使用率:%s%%", $11, $12, $13, $7}')"
			_fs="$(printf '%s\n' "$_ss_line" | awk -F '\t' '{print $8}')"
			_ss_mount="$(printf '%s\n' "$_ss_line" | awk -F '\t' '{print $9}')"
			_ss_src="$(printf '%s\n' "$_ss_line" | awk -F '\t' '{print $10}')"
			[[ -z $_fs || $_fs = unknown ]] && _fs="未知"
			_speed_debug_log "BACKUP_PARTITION_SUMMARY target=$(_speed_debug_kv "$_target") summary=$(_speed_debug_kv "$_summary") fs=$_fs mount=$(_speed_debug_kv "$_ss_mount") source=$(_speed_debug_kv "$_ss_src") backend=speedscan-storage-summary mode=r470"
			printf '%s檔案系統:%s\n' "$_summary" "$_fs"
			return 0
		fi
	fi
	_df_out="$(df -h "$_target" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null})"
	_summary="$(printf '%s\n' "$_df_out" | _backup_df_summary_from_output)"
	if [[ -z $_summary ]]; then
		_df_out="$(df "$_target" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null})"
		_summary="$(printf '%s\n' "$_df_out" | _backup_df_summary_from_output)"
	fi
	_fs="$(_backup_partition_fs_type_from_mountinfo "$_target")"
	[[ -z $_fs ]] && _fs="$(_backup_partition_fs_type_from_df "$_target")"
	[[ -z $_summary ]] && _summary="總共:未知已用:未知剩餘:未知使用率:未知"
	[[ -z $_fs ]] && _fs="未知"
	_speed_debug_log "BACKUP_PARTITION_SUMMARY target=$(_speed_debug_kv "$_target") summary=$(_speed_debug_kv "$_summary") fs=$_fs backend=df-fallback mode=r470"
	printf '%s檔案系統:%s\n' "$_summary" "$_fs"
}

# 計算本地備份目錄路徑
# 格式: $Output_path/Backup_${Compression_method}_${user}
# 並建立目錄, 設定 $Backup 全域變數供其他函數使用
# 返回帶後綴的備份目錄名 (Backup_${Compression_method}_${user}${suffix})
# 解析 Backup_suffix 中的日期時間變量: %yyyymmdd %hhmmss %yyyymmddhhmmss %yyyy %mm %dd
get_backup_dirname() {
	local base="Backup_${Compression_method}_${user:-0}"
	if [[ -n $Backup_suffix ]]; then
		local resolved="$Backup_suffix"
		local now="$(date '+%Y%m%d%H%M%S')"
		resolved="${resolved//%yyyymmddhhmmss/$now}"
		resolved="${resolved//%yyyymmdd/${now:0:8}}"
		resolved="${resolved//%hhmmss/${now:8}}"
		resolved="${resolved//%yyyy/${now:0:4}}"
		resolved="${resolved//%mm/${now:4:2}}"
		resolved="${resolved//%dd/${now:6:2}}"
		echo "${base}${resolved}"
	else
		echo "$base"
	fi
}

# ======================================================
# 備份路徑 / 預掃 / app_details 讀取
# ======================================================
backup_path() {
	if [[ $Output_path != "" ]]; then
		[[ ${Output_path: -1} = / ]] && Output_path="${Output_path%?}"
		if [[ ${Output_path:0:1} != / ]]; then
			Directory_type="相對路徑"
			Backup="$MODDIR/$Output_path/$(get_backup_dirname)"
		else
			Directory_type="絕對路徑"
			Backup="$Output_path/$(get_backup_dirname)"
		fi
		outshow="使用自定義目錄($Directory_type)"
	else
		Backup="$MODDIR/$(get_backup_dirname)"
		if [[ ! -f ${0%/*}/app_details.json ]]; then
			outshow="使用當前路徑作為備份目錄"
		else
			[[ -d $Backup ]] && outshow="使用上層路徑作為備份目錄" || echoRgb "$Backup目錄不存在" "0"
		fi
	fi
	PU="$(mount | awk '$3 ~ "/mnt/media_rw/[^/]+$" {print $3, $5}' | grep -Ev "$mount_point")"
	OTGPATH="$(echo "$PU" | cut -d' ' -f1)"
	OTGFormat="$(echo "$PU" | cut -d' ' -f2)"
	if [[ -d $OTGPATH ]]; then
		if [[ $(echo "$MODDIR" | grep -Eo "^${OTGPATH}") != "" ]]; then
			hx="true"
			Backup="$MODDIR/$(get_backup_dirname)"
		else
			ask_yn_indep "檢測到隨身碟 是否在隨身碟備份?" "選擇了隨身碟備份" "選擇了本地備份"
			[[ $branch = true ]] && hx="$branch"
			[[ $hx = true ]] && Backup="$OTGPATH/$(get_backup_dirname)"
		fi
		if [[ $hx = true ]]; then
			if [[ $OTGFormat = vfat ]]; then
				echoRgb "隨身碟檔案系統$OTGFormat不支持超過單檔4GB\n -請格式化為exfat" "0"
				exit
			fi
			outshow="於隨身碟備份" && hx=usb
		fi
	fi
	# 流式遠端備份不應建立本機 Backup_zstd_X 空殼；$Backup 只保留作為顯示/相對路徑基準。
	# 實際 app/json/wifi/media staging 全部走 $TMPDIR/.stream_stage，再直接 _stream_upload 到遠端。
	if stream_enabled; then
		_speed_debug_log "STREAM_LOCAL_BACKUP_ROOT_SKIP path=$Backup"
		# 舊版可能已留下空的 Backup_zstd_X；只刪空殼，不碰已有內容的舊本地備份。
		if [[ -d $Backup ]]; then
			if find "$Backup" -mindepth 1 -print -quit 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} | grep -q .; then
				_speed_debug_log "STREAM_LOCAL_BACKUP_ROOT_PRESERVE_NONEMPTY path=$Backup"
			else
				rmdir "$Backup" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} && _speed_debug_log "STREAM_LOCAL_BACKUP_ROOT_REMOVED_EMPTY path=$Backup"
			fi
		fi
	else
		[[ ! -d $Backup ]] && mkdir -p "$Backup"
	fi
	# 分區詳細：非流式用實際 Backup 路徑；流式不落地，df 只用 MODDIR 作顯示 fallback。
	if stream_enabled; then
		_df_target="$(_backup_df_target "$MODDIR")"
	else
		_df_target="$(_backup_df_target "$Backup")"
	fi
	_real_suffix="$(_backup_mount_display_suffix "$Backup" "$_df_target")"
	if [[ ${SPEEDBACKUP_DEFER_REMOTE_SETUP:-0} = 1 ]]; then
		SPEEDBACKUP_REMOTE_SETUP_DEFERRED=1
		_speed_debug_log "REMOTE_SETUP_DEFERRED phase=backup_path remote_type=${remote_type:-none}"
	else
		backup_path_remote_finalize
	fi
}

# 完成備份路徑階段被延後的遠端初始化。
# 目的：避免 WebDAV daemon / chunked probe / remote_dir_size 在本機 dirsize 預掃前先啟動，
# 用來驗證「只有遠端模式卡 prepare_dir_size_map」是否由 remote_setup 前置副作用造成。
backup_path_remote_finalize() {
	if [[ ${remote_stream:-0} = 1 ]]; then
		_remote_stream_fatal_reset "backup_path_remote_finalize"
	fi
	remote_setup
	# 一致性保護: remote_stream=1 但 remote_type 無效/空 → 直接終止。
	# 真流式沒有安全本地回退目標，不反寫 conf。
	if [[ $remote_stream = 1 && -z $remote_type ]]; then
		echoRgb "真流式上傳不可用：遠端初始化失敗，已終止" "0"
		echoRgb "remote_stream=1 不允許回退成本地備份；請修正遠端連線或設 remote_stream=0" "3"
		_speed_debug_normal_finish_pack 1
		exit 1
	fi
	if [[ $remote_stream = 1 && $remote_type = smb ]]; then
		if ! remote_smb_write_precheck; then
			echoRgb "真流式 SMB 寫入預檢未通過，已終止，避免產生半套遠端備份" "0"
			_speed_debug_normal_finish_pack 1
			exit 1
		fi
	fi
	# 分區統計放在 remote_setup/一致性保護之後：
	# 連線失敗自動轉純本機備份時，也能正確顯示本地資訊；流式不顯示本地分區統計。
	if [[ $remote_stream != 1 ]]; then
		echoRgb "${hx}備份資料夾所使用分區統計如下↓\n -$(_backup_partition_summary "$_df_target")\n -備份目錄輸出位置↓\n -$Backup${_real_suffix:+\n$_real_suffix}"
		echoRgb "$outshow" "2"
	fi
	# 快照備份前遠端大小 (結尾算差異，對齊本地備份的整體資料夾差異統計)。
	if [[ -n $remote_type ]]; then
		_remote_before_subdir="$(get_backup_dirname)"
		_backup_remote_size_prescan_progress_begin "$_remote_before_subdir"
		_RTOTAL_BEFORE="$(remote_dir_size "$_remote_before_subdir" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null})"
		[[ -z $_RTOTAL_BEFORE ]] && _RTOTAL_BEFORE=0
		_backup_remote_size_prescan_progress_done "$_remote_before_subdir" "$_RTOTAL_BEFORE"
		_speed_debug_log "REMOTE_TOTAL_BEFORE subdir=$_remote_before_subdir bytes=$_RTOTAL_BEFORE mode=r448"
		unset _remote_before_subdir
	fi
	SPEEDBACKUP_REMOTE_SETUP_DEFERRED=0
}

backup_finalize_remote_setup_if_deferred() {
	if [[ ${SPEEDBACKUP_REMOTE_SETUP_DEFERRED:-0} = 1 ]]; then
		_prepare_timed backup_path_remote_finalize
	fi
}


# 真流式模式的早期硬性連線檢查。
# 只做 URL/host/port/TCP 這類低成本檢查，不啟動 WebDAV daemon / chunked PUT probe，
# 避免恢復舊版「遠端前置干擾 dirsize 預掃」問題；但若遠端根本沒開，立即終止，不進入本地備份流程。
remote_stream_early_hard_precheck() {
	[[ ${remote_stream:-0} = 1 ]] || return 0
	[[ -n ${remote_type:-} ]] || return 0
	case $remote_type in
	webdav|smb) ;;
	*)
		echoRgb "真流式上傳已開啟，但 remote_type=$remote_type 不支援；已終止，避免回退成本地備份" "0"
		_speed_debug_normal_finish_pack 1
		exit 1
		;;
	esac
	[[ -n ${remote_url:-} ]] || {
		echoRgb "真流式上傳已開啟，但遠端位址未設定；已終止，避免回退成本地備份" "0"
		_speed_debug_normal_finish_pack 1
		exit 1
	}
	remote_parse_endpoint
	[[ $remote_type = smb ]] && remote_parse_smb_url
	if ! remote_precheck "$REMOTE_HOST" "$REMOTE_PORT" backup_precheck; then
		echoRgb "真流式上傳不可用：遠端不可連線 ($REMOTE_HOST:$REMOTE_PORT)，已終止" "0"
			_remote_precheck_print_smb_issue
		echoRgb "remote_stream=1 不允許回退成本地備份；請開啟遠端伺服器、修正網路，或設 remote_stream=0" "3"
		echoRgb "詳情已寫入 speed_debug 包內: remote_precheck.log" "3"
		_speed_debug_normal_finish_pack 1
		exit 1
	fi
	echoRgb "真流式早期連線檢查通過 ($REMOTE_HOST:$REMOTE_PORT)" "1"
	return 0
}
prepare_app_state_prescan_batch() {
	local _all_pkgs _rc
	if [[ -n $1 ]]; then
		_all_pkgs="$*"
	else
		_all_pkgs="$(echo "$txt" | awk '{print $2}' | grep -v '^$' | paste -sd' ' -)"
	fi
	[[ -z $_all_pkgs ]] && return 0
	local _snapshot_pkgs="$TMPDIR/.appstate_snapshot_pkgs_$$" _snapshot_out="$TMPDIR/.appstate_snapshot_out_$$"
	rm -f "$_snapshot_pkgs" "$_snapshot_out" 2>/dev/null
	echoRgb "預掃應用狀態中... (AppState daemon: 權限/特殊存取/安裝來源/電池/SSAID)" "2"
	printf '%s\n' $_all_pkgs | sed '/^$/d' | sort -u > "$_snapshot_pkgs"
	local _snapshot_total
	_snapshot_total="$(wc -l < "$_snapshot_pkgs" 2>/dev/null | tr -d ' ')"
	case $_snapshot_total in ''|*[!0-9]*) _snapshot_total=0 ;; esac
	[[ $_snapshot_total -gt 0 ]] && _speedbackup_progress_step 0 "$_snapshot_total" "正在預掃應用狀態" "prepare_appstate_prescan" "107"
	# 294: 同一輪若已經有完整 canonical AppState map，不重複打 daemon snapshot。
	if [[ -s $TMPDIR/.pkg_appstate ]]; then
		local _miss
		_miss="$(awk 'NR==FNR{need[$1]=1; next} {seen[$1]=1} END{for (k in need) if (!(k in seen)) {print k; exit}}' "$_snapshot_pkgs" "$TMPDIR/.pkg_appstate" 2>/dev/null)"
		if [[ -z $_miss ]]; then
			_speed_debug_log "APPSTATE_PRESCAN_CACHE_HIT packages=$(wc -l < "$_snapshot_pkgs" 2>/dev/null | tr -d ' ')"
			[[ $_snapshot_total -gt 0 ]] && _speedbackup_progress_step "$_snapshot_total" "$_snapshot_total" "應用狀態預掃完成（快取命中）" "prepare_appstate_prescan" "107"
			rm -f "$_snapshot_pkgs" "$_snapshot_out" 2>/dev/null
			return 0
		fi
		_speed_debug_log "APPSTATE_PRESCAN_CACHE_MISS firstMissing=$_miss"
	fi
	_appstate_snapshot_batch_raw "$_snapshot_pkgs" "$_snapshot_out"
	_rc=$?
	if [[ $_rc = 0 ]] && _appstate_snapshot_to_maps "$_snapshot_out"; then
		[[ -n ${SPEED_DEBUG_RUN_DIR:-} && -d ${SPEED_DEBUG_RUN_DIR:-} ]] && {
			cp -f "$_snapshot_out" "$SPEED_DEBUG_RUN_DIR/appstate_snapshot.ndjson" 2>/dev/null
			printf 'APPSTATE_SNAPSHOT_OK packages=%s result=%s name=%s
' 				"$(wc -l < "$_snapshot_pkgs" 2>/dev/null | tr -d ' ')" 				"${_APPSTATE_RESULT_CODE:-0}" "${_APPSTATE_RESULT_NAME:-OK}" 				>> "$SPEED_DEBUG_RUN_DIR/appstate_prescan_batch.log" 2>/dev/null
		}
		[[ $_snapshot_total -gt 0 ]] && _speedbackup_progress_step "$_snapshot_total" "$_snapshot_total" "應用狀態預掃完成" "prepare_appstate_prescan" "107"
		rm -f "$_snapshot_pkgs" "$_snapshot_out" 2>/dev/null
		return 0
	fi
	_speed_debug_log "APPSTATE_STRUCTURED_PRESCAN_FATAL rc=$_rc result=${_APPSTATE_RESULT_CODE:-unknown} name=${_APPSTATE_RESULT_NAME:-unknown}"
	[[ -n ${SPEED_DEBUG_RUN_DIR:-} && -d ${SPEED_DEBUG_RUN_DIR:-} && -s $_snapshot_out ]] && 		cp -f "$_snapshot_out" "$SPEED_DEBUG_RUN_DIR/appstate_snapshot_invalid.ndjson" 2>/dev/null
	rm -f "$_snapshot_pkgs" "$_snapshot_out" 2>/dev/null
	return 2
}

# 預掃 pkg → uid map (給備份主迴圈用, 避免每個 app 都 fork 一次 pm + awk)
# 寫到 $TMPDIR/.pkg_uid 格式: pkg<TAB>uid
# 用法: prepare_pkg_uid_map (backup / backup_update_apk 開頭呼叫)
prepare_pkg_uid_map() {
	: > "$TMPDIR/.pkg_uid" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	appinventory pkgUidMap all 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} >> "$TMPDIR/.pkg_uid"
	_eventwait_output_file_stable_ms "$TMPDIR/.pkg_uid" pkg_uid_map_ready 50 1200 >/dev/null 2>&1 || true
	if [[ -s "$TMPDIR/.pkg_uid" ]]; then
		_speed_debug_log "APP_INVENTORY_UID_MAP_OK rows=$(wc -l < "$TMPDIR/.pkg_uid" 2>/dev/null | tr -d ' ')"
		return 0
	fi
	_speed_debug_log "APP_INVENTORY_UID_MAP_FAIL strict=1 fallback=off"
	return 1
}

_restore_package_facts_map_file() {
	printf '%s\n' "${TMPDIR:-/data/local/tmp}/.restore_package_facts.tsv"
}

_restore_package_compare_map_file() {
	printf '%s\n' "${TMPDIR:-/data/local/tmp}/.restore_package_compare_map.tsv"
}

_restore_package_compare_summary_file() {
	printf '%s\n' "${TMPDIR:-/data/local/tmp}/.restore_package_compare_summary.txt"
}

_restore_package_compare_apk_plan_get() {
	local _pkg="$1" _map
	_map="$(_restore_package_compare_map_file)"
	[[ -n $_pkg && -s $_map ]] || return 1
	awk -F '\t' -v p="$_pkg" 'NR==1{next} $3==p{print $25 "\t" $26; exit}' "$_map" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
}

_restore_package_compare_build() {
	# r386: report-only join; normalize remote keys from .remote_files and debug raw APP_PAYLOAD rows.
	# This does not decide install/restore/AppState behavior; it only produces a stable debug map for pre-restore diagnosis.
	local _stage="${1:-${TMPDIR:-/data/local/tmp}/.restore_stage}" _selected="${2:-0}" _facts _out _summary _meta _remote _tmp _t0 _elapsed
	local _total _installed _missing _remote_newer _local_newer _same _payload_missing _system _default_home _default_ime
	local _jf _app _pkg _ver _row
	[[ -d $_stage ]] || return 1
	_facts="$(_restore_package_facts_map_file)"
	[[ -s $_facts ]] || return 1
	_out="$(_restore_package_compare_map_file)"
	_summary="$(_restore_package_compare_summary_file)"
	_meta="${TMPDIR:-/data/local/tmp}/.restore_package_compare_meta_${$}_$RANDOM.tsv"
	_remote="${TMPDIR:-/data/local/tmp}/.restore_package_compare_remote_${$}_$RANDOM.tsv"
	_tmp="${TMPDIR:-/data/local/tmp}/.restore_package_compare_${$}_$RANDOM.tsv"
	_t0="$(_speed_now_ms)"
	: > "$_meta" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} || return 1
	_json_list="${TMPDIR:-/data/local/tmp}/.restore_compare_appdetails_${$}_$RANDOM.lst"
	_appdetails_index_paths "$_stage" "$_json_list" 2 2 1 >/dev/null 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} || true
	while read -r _jf; do
		[[ -s $_jf ]] || continue
		_app="${_jf%/app_details.json}"; _app="${_app##*/}"
		_row="$(jq -r "$(_appdetails_jq_common_defs) [ad_first_pkg, ad_first_apk_version, (try (.user.Size // .user.size // null) catch null), (try (.user_de.Size // .user_de.size // null) catch null), (try (.data.Size // .data.size // null) catch null), (try (.obb.Size // .obb.size // null) catch null)] | @tsv" "$_jf" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null})"
		_pkg="$(printf '%s\n' "$_row" | awk -F '\t' '{print $1}' | tr -d ' \t\r\n')"
		_ver="$(printf '%s\n' "$_row" | awk -F '\t' '{print $2}' | tr -d ' \t\r\n')"
		case $_pkg in ''|null) continue ;; esac
		case $_ver in ''|null) _ver="" ;; esac
		# Keep labels single-line TSV-safe; app directory is the display label in restore stage.
		printf '%s	%s
' "$_app" "$_row" | tr '\r' ' ' >> "$_meta" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	done < "$_json_list"
	rm -f "$_json_list" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	[[ -s $_meta ]] || { rm -f "$_meta" "$_remote" "$_tmp" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}; return 1; }
	: > "$_remote" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} || return 1
	# r386: compare-map must see the same classified APP_PAYLOAD rows that restore uses.
	# .remote_files may be plain list, prefixed rel list, or unavailable in some stream restore paths;
	# remote_webdav_propfind_raw.log contains stable APP_PAYLOAD<TAB>rel rows in debug mode.
	if [[ -f ${TMPDIR:-/data/local/tmp}/.remote_files ]]; then
		awk 'NF{gsub(/\r/,"",$0); print}' "${TMPDIR:-/data/local/tmp}/.remote_files" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} >> "$_remote" || true
	fi
	if [[ -n ${SPEED_DEBUG_RUN_DIR:-} && -s ${SPEED_DEBUG_RUN_DIR}/remote_webdav_propfind_raw.log ]]; then
		awk -F '\t' '$1=="APP_PAYLOAD" && $2!=""{gsub(/\r/,"",$2); print $2}' "${SPEED_DEBUG_RUN_DIR}/remote_webdav_propfind_raw.log" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} >> "$_remote" || true
	fi
	if [[ -s $_remote ]]; then
		sort -u "$_remote" -o "$_remote" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} || true
	fi
	awk -F '\t' -v OFS='\t' -v remote="$_remote" '
		BEGIN {
			print "idx","label","package","remoteVersion","localInstalled","localVersion","localUid","localEnabled","localSystem","localUpdatedSystem","localSourceDir","localDataDir","localDeDataDir","remoteHasApk","remoteHasUser","remoteHasUserDe","remoteHasData","remoteHasObb","remoteExpectUser","remoteExpectUserDe","remoteExpectData","remoteExpectObb","roleHint","compareStatus","apkAction","apkReason"
			while ((getline rr < remote) > 0) {
				gsub(/\r/,"",rr)
				if (rr == "") continue
				split(rr, c, "\t")
				if (c[2] != "") rr=c[2]
				rf[rr]=1
				n=split(rr, rp, "/")
				if (n >= 2) rf[rp[n-1] "/" rp[n]]=1
			}
			close(remote)
		}
		FNR==NR {
			if ($1 ~ /^#/) next
			pkg=$2; if (pkg=="") next
			status[pkg]=$1; inst[pkg]=$3; uid[pkg]=$4; ver[pkg]=$5; enabled[pkg]=$7; sysFlag[pkg]=$8; upd[pkg]=$9; src[pkg]=$13; dataDirMap[pkg]=$17; deDirMap[pkg]=$18; reason[pkg]=$21
			next
		}
		{
			idx++
			label=$1; pkg=$2; rver=$3; expUser=$4; expUserDe=$5; expData=$6; expObb=$7
			gsub(/[\t\r\n]/," ",label)
			li=inst[pkg]; if (li=="") li="false"
			lv=ver[pkg]; if (lv=="") lv=""
			luid=uid[pkg]; if (luid=="") luid=""
			len=enabled[pkg]; if (len=="") len=""
			lsys=sysFlag[pkg]; if (lsys=="") lsys="false"
			lupd=upd[pkg]; if (lupd=="") lupd="false"
			lsrc=src[pkg]; ldata=dataDirMap[pkg]; lde=deDirMap[pkg]
			apk=((label "/apk.tar.zst") in rf || (label "/apk.tar") in rf) ? "true" : "false"
			user=((label "/user.tar.zst") in rf || (label "/user.tar") in rf) ? "true" : "false"
			userde=((label "/user_de.tar.zst") in rf || (label "/user_de.tar") in rf) ? "true" : "false"
			datahas=((label "/data.tar.zst") in rf || (label "/data.tar") in rf) ? "true" : "false"
			obb=((label "/obb.tar.zst") in rf || (label "/obb.tar") in rf) ? "true" : "false"
			expUser=(expUser ~ /^[0-9]+$/ && expUser+0 > 0) ? "true" : "false"
			expUserDe=(expUserDe ~ /^[0-9]+$/ && expUserDe+0 > 0) ? "true" : "false"
			expData=(expData ~ /^[0-9]+$/ && expData+0 > 0) ? "true" : "false"
			expObb=(expObb ~ /^[0-9]+$/ && expObb+0 > 0) ? "true" : "false"
			role="normal"
			if (pkg=="com.android.launcher3" || label ~ /Launcher|桌面/) role="default_home_or_launcher"
			else if (pkg=="com.google.android.inputmethod.latin" || label ~ /Gboard|鍵盤|输入法|輸入法/) role="default_ime_candidate"
			else if (pkg=="com.google.android.dialer" || label ~ /電話|拨号|Dialer/) role="default_dialer_candidate"
			if (li != "true") cmp="local_missing"
			else if (rver ~ /^[0-9]+$/ && lv ~ /^[0-9]+$/ && rver+0 > lv+0) cmp="remote_newer"
			else if (rver ~ /^[0-9]+$/ && lv ~ /^[0-9]+$/ && lv+0 > rver+0) cmp="local_newer"
			else cmp="same_or_unknown"
			if (apk=="false") cmp=cmp "+remote_apk_missing"
			apkAction="install"; apkReason="default_install"
			if (apk=="false") { apkAction="missing"; apkReason="remote_apk_missing" }
			else if (li != "true") { apkAction="install"; apkReason="not_installed" }
			else if (rver ~ /^[0-9]+$/ && lv ~ /^[0-9]+$/ && rver+0 > lv+0) { apkAction="install"; apkReason="remote_newer" }
			else if (rver ~ /^[0-9]+$/ && lv ~ /^[0-9]+$/ && lv+0 > rver+0) { apkAction="skip_newer_local"; apkReason="local_newer" }
			else if (rver ~ /^[0-9]+$/ && lv ~ /^[0-9]+$/) { apkAction="skip_same_version"; apkReason="installed_version_sufficient" }
			else { apkAction="skip_installed_uncomparable"; apkReason="installed_backup_version_uncomparable" }
			if (expUser=="true" && user=="false") cmp=cmp "+remote_user_missing"
			if (expUserDe=="true" && userde=="false") cmp=cmp "+remote_user_de_missing"
			if (expData=="true" && datahas=="false") cmp=cmp "+remote_data_missing"
			if (expObb=="true" && obb=="false") cmp=cmp "+remote_obb_missing"
			printf "%s\t%s\t%s\t%s\t%s\t%s\t%s\t%s\t%s\t%s\t%s\t%s\t%s\t%s\t%s\t%s\t%s\t%s\t%s\t%s\t%s\t%s\t%s\t%s\t%s\t%s\n", idx,label,pkg,rver,li,lv,luid,len,lsys,lupd,lsrc,ldata,lde,apk,user,userde,datahas,obb,expUser,expUserDe,expData,expObb,role,cmp,apkAction,apkReason
		}
	' "$_facts" "$_meta" > "$_tmp" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} || {
		rm -f "$_meta" "$_remote" "$_tmp" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
		return 1
	}
	cat "$_tmp" > "$_out" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} || { rm -f "$_meta" "$_remote" "$_tmp" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}; return 1; }
	{
		awk -F '\t' 'NR>1{total++; if($5=="true") installed++; else missing++; if($24 ~ /remote_newer/) remoteNewer++; if($24 ~ /local_newer/) localNewer++; if($24 ~ /same_or_unknown/) same++; if($24 ~ /remote_.*_missing/) payloadMissing++; if($9=="true" || $10=="true") sys++; if($23 ~ /launcher/) home++; if($23 ~ /ime/) ime++} END{printf "total=%d\ninstalled=%d\nmissing=%d\nremoteNewer=%d\nlocalNewer=%d\nsameOrUnknown=%d\npayloadMissing=%d\nsystemOrUpdated=%d\ndefaultHomeHints=%d\ndefaultImeHints=%d\n", total+0, installed+0, missing+0, remoteNewer+0, localNewer+0, same+0, payloadMissing+0, sys+0, home+0, ime+0}' "$_out"
	} > "$_summary" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} || true
	_total="$(awk -F= '$1=="total"{print $2}' "$_summary" 2>/dev/null)"; case $_total in ''|*[!0-9]*) _total=0 ;; esac
	_installed="$(awk -F= '$1=="installed"{print $2}' "$_summary" 2>/dev/null)"; case $_installed in ''|*[!0-9]*) _installed=0 ;; esac
	_missing="$(awk -F= '$1=="missing"{print $2}' "$_summary" 2>/dev/null)"; case $_missing in ''|*[!0-9]*) _missing=0 ;; esac
	_remote_newer="$(awk -F= '$1=="remoteNewer"{print $2}' "$_summary" 2>/dev/null)"; case $_remote_newer in ''|*[!0-9]*) _remote_newer=0 ;; esac
	_local_newer="$(awk -F= '$1=="localNewer"{print $2}' "$_summary" 2>/dev/null)"; case $_local_newer in ''|*[!0-9]*) _local_newer=0 ;; esac
	_payload_missing="$(awk -F= '$1=="payloadMissing"{print $2}' "$_summary" 2>/dev/null)"; case $_payload_missing in ''|*[!0-9]*) _payload_missing=0 ;; esac
	_system="$(awk -F= '$1=="systemOrUpdated"{print $2}' "$_summary" 2>/dev/null)"; case $_system in ''|*[!0-9]*) _system=0 ;; esac
	_default_home="$(awk -F= '$1=="defaultHomeHints"{print $2}' "$_summary" 2>/dev/null)"; case $_default_home in ''|*[!0-9]*) _default_home=0 ;; esac
	_default_ime="$(awk -F= '$1=="defaultImeHints"{print $2}' "$_summary" 2>/dev/null)"; case $_default_ime in ''|*[!0-9]*) _default_ime=0 ;; esac
	_elapsed="$(( $(_speed_now_ms) - _t0 ))"
	[[ -n ${SPEED_DEBUG_RUN_DIR:-} && -d ${SPEED_DEBUG_RUN_DIR:-} ]] && {
		cp -f "$_out" "$SPEED_DEBUG_RUN_DIR/restore_package_compare_map.tsv" 2>/dev/null || true
		cp -f "$_summary" "$SPEED_DEBUG_RUN_DIR/restore_package_compare_summary.txt" 2>/dev/null || true
		cp -f "$_remote" "$SPEED_DEBUG_RUN_DIR/restore_package_compare_remote_map.tsv" 2>/dev/null || true
	}
	_eventwait_output_files_stable_ms restore_package_compare_outputs_ready 50 1200 "$_out" "$_summary" >/dev/null 2>&1 || true
	_speed_debug_log "RESTORE_PACKAGE_COMPARE_MAP_OK total=$_total selected=${_selected:-0} localInstalled=$_installed localMissing=$_missing remoteNewer=$_remote_newer localNewer=$_local_newer payloadMissing=$_payload_missing systemOrUpdated=$_system defaultHomeHints=$_default_home defaultImeHints=$_default_ime elapsedMs=$_elapsed mode=r416 report_only=1"
	rm -f "$_meta" "$_remote" "$_tmp" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	return 0
}

