		[[ -d ${SPEED_DEBUG_RUN_DIR:-} ]] && cp -f "$_out" "$SPEED_DEBUG_RUN_DIR/storage_media_facts.tsv" 2>/dev/null || true
		_rows="$(awk -F '\t' '$1=="OK"{n++} END{print n+0}' "$_out" 2>/dev/null)"
