_restore_post_install_facts_refresh_one() {
	local _pkg="$1" _reason="${2:-post_install}" _list _facts _t0 _elapsed _ok _flat _row _status _installed _uid _ver _ud _de _why
	[[ -n $_pkg ]] || return 1
	_list="$TMPDIR/.restore_post_install_pkg_${$}_$RANDOM.txt"
	_facts="$TMPDIR/.restore_post_install_facts_${$}_$RANDOM.tsv"
	printf '%s\n' "$_pkg" > "$_list" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} || return 1
	_t0="$(_speed_now_ms)"
	if _restore_post_install_facts_batch_call "$_list" refresh > "$_facts" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}; then
		_ok="$(awk -F '\t' -v p="$_pkg" '$1=="OK" && $2==p && $3=="true"{print 1; exit}' "$_facts" 2>/dev/null)"
		awk -F '\t' '$1=="OK" && $3=="true" && $2!="" {print $2}' "$_facts" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} >> "$TMPDIR/.installed_pkgs" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} || true
		awk -F '\t' '$1=="OK" && $3=="true" && $2!="" && $4 ~ /^[0-9]+$/ {print $2 "\t" $4}' "$_facts" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} >> "$TMPDIR/.pkg_uid" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} || true
		awk -F '\t' '$1=="OK" && $3=="true" && $2!="" && $5 ~ /^[0-9]+$/ {print $2 "\t" $5}' "$_facts" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} >> "$TMPDIR/.pkg_ver" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} || true
		sort -u "$TMPDIR/.installed_pkgs" -o "$TMPDIR/.installed_pkgs" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} || true
		sort -u "$TMPDIR/.pkg_uid" -o "$TMPDIR/.pkg_uid" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} || true
		sort -u "$TMPDIR/.pkg_ver" -o "$TMPDIR/.pkg_ver" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} || true
		_elapsed="$(( $(_speed_now_ms) - _t0 ))"
		_row="$(awk -F '\t' -v p="$_pkg" '$2==p {print $1 "\t" $3 "\t" $4 "\t" $5 "\t" $19 "\t" $20 "\t" $21; exit}' "$_facts" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null})"
		if [[ -n $_row ]]; then
			IFS="$(printf '\t')" read -r _status _installed _uid _ver _ud _de _why <<EOF_POST_INSTALL_FACT
$_row
EOF_POST_INSTALL_FACT
			RESTORE_PKG_INSTALLED="$_installed"
			RESTORE_PKG_UID="$_uid"
			RESTORE_PKG_VER="$_ver"
			RESTORE_PKG_USER_DATA_EXISTS="$_ud"
			RESTORE_PKG_USER_DE_DATA_EXISTS="$_de"
			RESTORE_PKG_STATUS_REASON="$_why"
		fi
		_flat="$(awk -F '\t' -v p="$_pkg" '$2==p{print; exit}' "$_facts" 2>/dev/null | cut -c1-500)"
		[[ -n ${SPEED_DEBUG_RUN_DIR:-} && -d ${SPEED_DEBUG_RUN_DIR:-} ]] && cat "$_facts" >> "$SPEED_DEBUG_RUN_DIR/post_install_facts_batch.tsv" 2>/dev/null || true
		_speed_debug_log "POST_INSTALL_FACTS_BATCH_OK package=$_pkg reason=$_reason installed=${_ok:-0} uid=${RESTORE_PKG_UID:-unknown} ver=${RESTORE_PKG_VER:-unknown} elapsedMs=$_elapsed row=$_flat mode=r416"
		rm -f "$_list" "$_facts" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
		[[ ${_ok:-0} = 1 ]]
		return $?
	fi
	_elapsed="$(( $(_speed_now_ms) - _t0 ))"
	_speed_debug_log "POST_INSTALL_FACTS_BATCH_FAIL package=$_pkg reason=$_reason elapsedMs=$_elapsed fallback=package_status mode=r416"
	rm -f "$_list" "$_facts" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	return 1
}

_restore_package_facts_extract_from_stage() {
	# r381: stream restore appList may contain only labels/selection text. The authoritative package list is already
	# available after app_details_bundle.tar.zst is extracted into $TMPDIR/.restore_stage.
	# Build the facts prefetch package list from those JSON files instead of skipping the batch cache.
	local _out="$1" _stage="${2:-${TMPDIR:-/data/local/tmp}/.restore_stage}" _tmp _jf _pkg _count
	[[ -n $_out && -d $_stage ]] || return 1
	_tmp="${_out}.stage_${$}_$RANDOM"
	rm -f "$_tmp" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	: > "$_tmp" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} || return 1
	_json_list="${TMPDIR:-/data/local/tmp}/.restore_stage_appdetails_${$}_$RANDOM.lst"
	_appdetails_index_paths "$_stage" "$_json_list" 2 2 0 >/dev/null 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} || true
	while read -r _jf; do
		[[ -s $_jf ]] || continue
		_pkg="$(_appdetails_get_first_pkg "$_jf" 2>/dev/null | tr -d ' \t\r\n')"
		case $_pkg in ''|null) continue ;; esac
		printf '%s\n' "$_pkg"
	done < "$_json_list" | sort -u > "$_tmp" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	rm -f "$_json_list" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	_count="$(wc -l < "$_tmp" 2>/dev/null | tr -d ' ')"; case $_count in ''|*[!0-9]*) _count=0 ;; esac
	if [[ $_count -gt 0 ]]; then
		cat "$_tmp" > "$_out" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
		_eventwait_output_file_stable_ms "$_out" restore_package_facts_stage_pkgs_ready 50 1200 >/dev/null 2>&1 || true
		[[ -n ${SPEED_DEBUG_RUN_DIR:-} && -d ${SPEED_DEBUG_RUN_DIR:-} ]] && cp -f "$_out" "$SPEED_DEBUG_RUN_DIR/package_facts_prefetch_pkgs_stage.tsv" 2>/dev/null || true
		_speed_debug_log "RESTORE_PACKAGE_FACTS_EXTRACT_STAGE_OK count=$_count stage=$_stage mode=r386 source=app_details_bundle"
		rm -f "$_tmp" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
		return 0
	fi
	_speed_debug_log "RESTORE_PACKAGE_FACTS_EXTRACT_STAGE_EMPTY stage=$_stage mode=r386 source=app_details_bundle"
	rm -f "$_tmp" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	return 1
}

_restore_package_facts_extract_list() {
	local _src="$1" _out="$2" _stage_count
	: > "$_out" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} || return 1
	if [[ -f $_src ]]; then
		awk '
			/^[[:space:]]*[#＃]/ || /^[[:space:]]*$/ { next }
			{
				line=$0
				sub(/^[[:space:]]+/, "", line); sub(/[[:space:]]+$/, "", line)
				if (line ~ /^!play[[:space:]]+/) sub(/^!play[[:space:]]+/, "", line)
				else if (line ~ /^！play[[:space:]]+/) sub(/^！play[[:space:]]+/, "", line)
				else if (line ~ /^[!！]/) { sub(/^[!！]/, "", line); sub(/^[[:space:]]+/, "", line) }
				split(line, a, /[[:space:]]+/)
				if (a[2] != "") print a[2]
			}
		' "$_src" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} | sort -u > "$_out" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	else
		printf '%s\n' "$_src" | awk '
			/^[[:space:]]*[#＃]/ || /^[[:space:]]*$/ { next }
			{
				line=$0
				sub(/^[[:space:]]+/, "", line); sub(/[[:space:]]+$/, "", line)
				if (line ~ /^!play[[:space:]]+/) sub(/^!play[[:space:]]+/, "", line)
				else if (line ~ /^！play[[:space:]]+/) sub(/^！play[[:space:]]+/, "", line)
				else if (line ~ /^[!！]/) { sub(/^[!！]/, "", line); sub(/^[[:space:]]+/, "", line) }
				split(line, a, /[[:space:]]+/)
				if (a[2] != "") print a[2]
			}
		' 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} | sort -u > "$_out" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	fi
	if [[ -s $_out ]]; then
		_eventwait_output_file_stable_ms "$_out" restore_package_facts_list_pkgs_ready 50 1200 >/dev/null 2>&1 || true
		_stage_count="$(wc -l < "$_out" 2>/dev/null | tr -d ' ')"; case $_stage_count in ''|*[!0-9]*) _stage_count=0 ;; esac
		_speed_debug_log "RESTORE_PACKAGE_FACTS_EXTRACT_LIST_OK count=$_stage_count mode=r386 source=app_list"
		return 0
	fi
	# r381: network/stream restore lists can be label-only. Fall back to the already extracted metadata bundle.
	_restore_package_facts_extract_from_stage "$_out" "${TMPDIR:-/data/local/tmp}/.restore_stage"
}

_restore_package_facts_prefetch() {
	# r381: restore loop consumes one PackageManager facts map instead of per-App packageStatus calls; stream restore falls back to app_details stage package list.
	local _src="$1" _selected="${2:-0}" _pkglist _facts _t0 _elapsed _count _ok _missing _facts_total
	[[ -n $_src ]] || return 1
	_pkglist="$TMPDIR/.restore_package_facts_pkgs_${$}_$RANDOM.txt"
	_facts="$(_restore_package_facts_map_file)"
	_restore_package_facts_extract_list "$_src" "$_pkglist" || { rm -f "$_pkglist" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}; return 1; }
	_count="$(wc -l < "$_pkglist" 2>/dev/null | tr -d ' ')"; case $_count in ''|*[!0-9]*) _count=0 ;; esac
	[[ $_count -gt 0 ]] || { rm -f "$_pkglist" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}; return 1; }
	_t0="$(_speed_now_ms)"
	local _facts_source
	_facts_source="preRestorePackageStateBatch"
	if ! _app_inventory_pre_restore_package_state_batch_call "$_pkglist" refresh > "$_facts" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}; then
		_speed_debug_log "PRE_RESTORE_PACKAGE_STATE_BATCH_FAIL requested=$_count mode=r481 fallback=appInventoryPackageFactsBatch"
		_facts_source="appInventoryPackageFactsBatch"
		_app_inventory_package_facts_batch_call "$_pkglist" refresh > "$_facts" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	fi
	if [[ -s $_facts ]] && { grep -Fqx '#schema	speedbackup.pre_restore_package_state.v1' "$_facts" 2>/dev/null || grep -Fqx '#schema	speedbackup.pm_facts.v1' "$_facts" 2>/dev/null; }; then
		_ok="$(awk -F '\t' '$1=="OK" && $3=="true"{c++} END{print c+0}' "$_facts" 2>/dev/null)"
		_missing="$(awk -F '\t' '$1!="#schema" && $1!="#fields" && $1!="OK"{c++} END{print c+0}' "$_facts" 2>/dev/null)"
		_facts_total="$(awk -F '\t' '$1!="#schema" && $1!="#fields"{c++} END{print c+0}' "$_facts" 2>/dev/null)"
		awk -F '\t' '$1=="OK" && $3=="true" && $2!="" {print $2}' "$_facts" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} | sort -u > "$TMPDIR/.installed_pkgs" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} || true
		awk -F '\t' '$1=="OK" && $3=="true" && $2!="" && $4 ~ /^[0-9]+$/ {print $2 "\t" $4}' "$_facts" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} | sort -u > "$TMPDIR/.pkg_uid" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} || true
		awk -F '\t' '$1=="OK" && $3=="true" && $2!="" && $5 ~ /^[0-9]+$/ {print $2 "\t" $5}' "$_facts" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} | sort -u > "$TMPDIR/.pkg_ver" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} || true
		_eventwait_output_files_stable_ms restore_package_facts_maps_ready 50 1200 "$_facts" "$TMPDIR/.installed_pkgs" "$TMPDIR/.pkg_uid" "$TMPDIR/.pkg_ver" >/dev/null 2>&1 || true
		_elapsed="$(( $(_speed_now_ms) - _t0 ))"
		[[ -n ${SPEED_DEBUG_RUN_DIR:-} && -d ${SPEED_DEBUG_RUN_DIR:-} ]] && cp -f "$_facts" "$SPEED_DEBUG_RUN_DIR/package_facts_map.tsv" 2>/dev/null || true
		_speed_debug_log "RESTORE_PACKAGE_FACTS_PREFETCH_OK requested=$_count factsTotal=${_facts_total:-0} selected=${_selected:-0} installed=${_ok:-0} missing=${_missing:-0} elapsedMs=$_elapsed mode=r481 source=${_facts_source:-unknown}"
		_restore_package_compare_build "${TMPDIR:-/data/local/tmp}/.restore_stage" "$_selected" || _speed_debug_log "RESTORE_PACKAGE_COMPARE_MAP_SKIP reason=build_failed selected=${_selected:-0} mode=r386"
		rm -f "$_pkglist" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
		return 0
	fi
	_elapsed="$(( $(_speed_now_ms) - _t0 ))"
	_speed_debug_log "RESTORE_PACKAGE_FACTS_PREFETCH_FAIL requested=$_count selected=${_selected:-0} elapsedMs=$_elapsed mode=r386 fallback=single_package_status"
	rm -f "$_pkglist" "$_facts" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	return 1
}

_restore_package_status_from_facts_cache() {
	local _pkg="$1" _reason="${2:-restore_pre_app}" _facts _row _installed _uid _ver _ud _de _why _status
	_facts="$(_restore_package_facts_map_file)"
	[[ $_reason = restore_pre_app && -s $_facts && -n $_pkg ]] || return 1
	_row="$(awk -F '\t' -v p="$_pkg" '$2==p {print $1 "\t" $3 "\t" $4 "\t" $5 "\t" $19 "\t" $20 "\t" $21; exit}' "$_facts" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null})"
	[[ -n $_row ]] || return 1
	IFS="$(printf '\t')" read -r _status _installed _uid _ver _ud _de _why <<EOF
$_row
EOF
	RESTORE_PKG_INSTALLED="$_installed"
	RESTORE_PKG_PREINSTALLED="$_installed"
	RESTORE_PKG_UID="$_uid"
	RESTORE_PKG_VER="$_ver"
	RESTORE_PKG_USER_DATA_EXISTS="$_ud"
	RESTORE_PKG_USER_DE_DATA_EXISTS="$_de"
	RESTORE_PKG_STATUS_REASON="$_why"
	case $_installed in true|1)
		_installed_map_set_one "$_pkg" || true
		case $_uid in ''|*[!0-9]*) ;; *) _pkg_uid_map_set_one "$_pkg" "$_uid" || true ;; esac
		case $_ver in ''|*[!0-9]*) ;; *) _pkg_ver_map_set_one "$_pkg" "$_ver" || true ;; esac
		_speed_debug_log "RESTORE_PACKAGE_STATUS_OK package=$_pkg installed=true uid=${_uid:-NA} version=${_ver:-NA} userData=$_ud userDe=$_de reason=$_reason source=pre_restore_package_state_cache-r481 status=$_status"
		;;
	*)
		_restore_installed_map_drop_one "$_pkg"
		_speed_debug_log "RESTORE_PACKAGE_STATUS_MISSING package=$_pkg reason=$_reason statusReason=$_why action=install_if_apk source=pre_restore_package_state_cache-r481 status=$_status"
		;;
	esac
	return 0
}

# r101: restore-time package status facade。開頭預掃只當 cache；處理 App 時以單包 PackageManager 狀態校正 installed/version/uid。
_restore_installed_map_drop_one() {
	local _pkg="$1" _tmp _map
	[[ -n $_pkg ]] || return 1
	if [[ -f "$TMPDIR/.installed_pkgs" ]]; then
		_tmp="$TMPDIR/.installed_pkgs.drop_${$}_$RANDOM"
		awk -v p="$_pkg" '$0 != p {print}' "$TMPDIR/.installed_pkgs" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} > "$_tmp" &&
			cat "$_tmp" > "$TMPDIR/.installed_pkgs" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
		rm -f "$_tmp" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	fi
	for _map in "$TMPDIR/.pkg_ver" "$TMPDIR/.pkg_uid"; do
		[[ -f $_map ]] || continue
		_tmp="${_map}.drop_${$}_$RANDOM"
		awk -v p="$_pkg" -F'	' '$1 != p {print}' "$_map" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} > "$_tmp" &&
			cat "$_tmp" > "$_map" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
		rm -f "$_tmp" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	done
}

_restore_package_status_refresh() {
	local _pkg="$1" _reason="${2:-restore_pre_app}" _json _tmp _installed _uid _ver _ud _de _src _why
	RESTORE_PKG_INSTALLED=""
	RESTORE_PKG_PREINSTALLED=""
	RESTORE_PKG_UID=""
	RESTORE_PKG_VER=""
	RESTORE_PKG_USER_DATA_EXISTS=""
	RESTORE_PKG_USER_DE_DATA_EXISTS=""
	RESTORE_PKG_STATUS_REASON=""
	[[ -n $_pkg ]] || return 1
	if _restore_package_status_from_facts_cache "$_pkg" "$_reason"; then
		return 0
	fi
	_json="$(_app_inventory_package_status_call "$_pkg" refresh 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null})" || _json=""
	_tmp="$TMPDIR/.package_status_${$}_$RANDOM.json"
	printf '%s\n' "$_json" > "$_tmp" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	if ! jq -e 'type=="object" and .recordType=="packageStatus"' "$_tmp" >/dev/null 2>&1; then
		_speed_debug_log "RESTORE_PACKAGE_STATUS_FAIL package=$_pkg reason=$_reason source=appinventory_package_status"
		rm -f "$_tmp" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
		return 1
	fi
	[[ -n ${SPEED_DEBUG_RUN_DIR:-} && -d ${SPEED_DEBUG_RUN_DIR:-} ]] && cat "$_tmp" >> "$SPEED_DEBUG_RUN_DIR/package_status.ndjson" 2>/dev/null
	_installed="$(jq -r '.installed // false' "$_tmp" 2>/dev/null)"
	_uid="$(jq -r '.uid // empty' "$_tmp" 2>/dev/null | tr -d ' 	
')"
	_ver="$(jq -r '.versionCode // empty' "$_tmp" 2>/dev/null | tr -d ' 	
')"
	_ud="$(jq -r '.userDataExists // false' "$_tmp" 2>/dev/null)"
	_de="$(jq -r '.userDeDataExists // false' "$_tmp" 2>/dev/null)"
	_src="$(jq -r '.source // "packageManager"' "$_tmp" 2>/dev/null)"
	_why="$(jq -r '.reason // ""' "$_tmp" 2>/dev/null)"
	RESTORE_PKG_INSTALLED="$_installed"
	RESTORE_PKG_PREINSTALLED="$_installed"
	RESTORE_PKG_UID="$_uid"
	RESTORE_PKG_VER="$_ver"
	RESTORE_PKG_USER_DATA_EXISTS="$_ud"
	RESTORE_PKG_USER_DE_DATA_EXISTS="$_de"
	RESTORE_PKG_STATUS_REASON="$_why"
	case $_installed in true|1)
		_installed_map_set_one "$_pkg" || true
		case $_uid in ''|*[!0-9]*) ;; *) _pkg_uid_map_set_one "$_pkg" "$_uid" || true ;; esac
		case $_ver in ''|*[!0-9]*) ;; *) _pkg_ver_map_set_one "$_pkg" "$_ver" || true ;; esac
		_speed_debug_log "RESTORE_PACKAGE_STATUS_OK package=$_pkg installed=true uid=${_uid:-NA} version=${_ver:-NA} userData=$_ud userDe=$_de reason=$_reason source=$_src"
		;;
	*)
		_restore_installed_map_drop_one "$_pkg"
		_speed_debug_log "RESTORE_PACKAGE_STATUS_MISSING package=$_pkg reason=$_reason statusReason=$_why action=install_if_apk source=$_src"
		;;
	esac
	rm -f "$_tmp" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	return 0
}

_pm_visible_after_install_direct() {
	local _pkg="$1" _reason="${2:-after_install}" _body _out _rc _line _vis _uid _ver
	[[ -n $_pkg ]] || return 1
	_body="$(_webdav_tmp_path root_pm_visible_args)"
	_out="$(_webdav_tmp_path root_pm_visible_out)"
	{
		printf '%s\n' "${USER_ID:-${user:-0}}"
		printf '%s\n' "$_pkg"
		printf '%s\n' refresh
	} > "$_body" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} || return 1
	_root_daemon_call_file_hot hiddenapi packageVisibleAfterInstall "$_body" "$_out" >/dev/null 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	_rc=$?
	if [[ $_rc = 125 ]]; then
		_dex_raw com.xayah.dex.HiddenApiUtil packageVisibleAfterInstall "${USER_ID:-${user:-0}}" "$_pkg" refresh > "$_out" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
		_rc=$?
	fi
	if [[ $_rc = 0 ]] && grep -Fqx '#schema	speedbackup.pm_visible_after_install.v1' "$_out" 2>/dev/null; then
		_line="$(awk -F '\t' '$1=="OK"{print; exit}' "$_out" 2>/dev/null)"
		if [[ -n $_line ]]; then
			_vis="$(printf '%s\n' "$_line" | awk -F '\t' '{print $4}')"
			_uid="$(printf '%s\n' "$_line" | awk -F '\t' '{print $6}')"
			_ver="$(printf '%s\n' "$_line" | awk -F '\t' '{print $8}')"
			RESTORE_PKG_INSTALLED=true
			RESTORE_PKG_UID="$_uid"
			RESTORE_PKG_VER="$_ver"
			case $_uid in ''|*[!0-9]*) ;; *) _pkg_uid_map_set_one "$_pkg" "$_uid" || true ;; esac
			case $_ver in ''|*[!0-9]*) ;; *) _pkg_ver_map_set_one "$_pkg" "$_ver" || true ;; esac
			_installed_map_set_one "$_pkg" || true
			_speed_debug_log "RESTORE_PACKAGE_VISIBLE_DIRECT_OK package=$_pkg reason=$_reason uid=${_uid:-unknown} version=${_ver:-unknown} backend=dex-packageVisibleAfterInstall mode=r470"
			rm -f "$_body" "$_out" 2>/dev/null
			return 0
		fi
	fi
	_speed_debug_log "RESTORE_PACKAGE_VISIBLE_DIRECT_MISS package=$_pkg reason=$_reason rc=$_rc backend=dex-packageVisibleAfterInstall mode=r470 fallback=post_install_facts"
	rm -f "$_body" "$_out" 2>/dev/null
	return 1
}

_restore_package_visible_wait_after_install() {
	# r458: 不新增 Dex/ROM 事件來源；PM 安裝命令同步返回後，只做短 bounded visible 確認。
	local _pkg="$1" _reason="${2:-after_install}" _tries="${SPEEDBACKUP_RESTORE_PACKAGE_VISIBLE_TRIES:-5}" _sleep="${SPEEDBACKUP_RESTORE_PACKAGE_VISIBLE_SLEEP:-0.12}" _i=0
	[[ -n $_pkg ]] || return 1
	_pm_visible_after_install_direct "$_pkg" "$_reason" && { _speed_debug_log "RESTORE_PACKAGE_VISIBLE_WAIT_OK package=$_pkg reason=$_reason tries=1 mode=r470 source=dex-visible-direct"; return 0; }
	case $_tries in ''|*[!0-9]*) _tries=5 ;; esac
	while [[ $_i -lt $_tries ]]; do
		_restore_post_install_facts_refresh_one "$_pkg" "${_reason}_visible_wait" || _restore_package_status_refresh "$_pkg" "${_reason}_visible_wait" || true
		case ${RESTORE_PKG_INSTALLED:-} in true|1)
			_speed_debug_log "RESTORE_PACKAGE_VISIBLE_WAIT_OK package=$_pkg reason=$_reason tries=$((_i + 1)) mode=r459"
			return 0
			;;
		esac
		sleep "$_sleep"
		_i=$((_i + 1))
	done
	_speed_debug_log "RESTORE_PACKAGE_VISIBLE_WAIT_FAIL package=$_pkg reason=$_reason tries=$_tries mode=r459"
	return 1
}

_pkg_uid_map_refresh_after_install() {
	local _pkg="$1"
	RESTORE_PKG_VISIBLE_AFTER_INSTALL_OK=0
	[[ -n $_pkg ]] || return 1
	_restore_package_visible_wait_after_install "$_pkg" after_install || {
		_speed_debug_log "RESTORE_INSTALLED_UID_REFRESH_FAIL package=$_pkg reason=package_visible_wait_failed source=post_install_facts_or_package_status mode=r459"
		return 1
	}
	case $RESTORE_PKG_INSTALLED in true|1) ;; *)
		_speed_debug_log "RESTORE_INSTALLED_UID_REFRESH_FAIL package=$_pkg reason=package_not_installed source=post_install_facts_or_package_status"
		return 1
		;;
	esac
	case $RESTORE_PKG_UID in ''|*[!0-9]*)
		_speed_debug_log "RESTORE_INSTALLED_UID_REFRESH_FAIL package=$_pkg reason=uid_missing source=post_install_facts_or_package_status"
		return 1
		;;
	esac
	RESTORE_PKG_VISIBLE_AFTER_INSTALL_OK=1
	_speed_debug_log "RESTORE_INSTALLED_UID_REFRESH package=$_pkg uid=$RESTORE_PKG_UID mode=postInstallFactsBatch source=post_install_facts_or_package_status visibleAfterInstall=1"
	return 0
}

_restore_install_issue_file() { printf '%s\n' "$TMPDIR/.restore_install_issues"; }

_restore_install_vendor_warning_file() { printf '%s\n' "$TMPDIR/.restore_install_vendor_warnings"; }

_restore_install_issue_reset() {
	: > "$(_restore_install_issue_file)" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	: > "$(_restore_install_vendor_warning_file)" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
}

_restore_install_issue_is_vendor_constrained() {
	local _pkg="$1" _label="$2" _reason="$3" _detail="$4" _home=""
	case $_reason in
	install_success_but_package_missing|upgrade_success_but_package_missing) ;;
	*) return 1 ;;
	esac
	if command -v _default_home_pkg_ensure >/dev/null 2>&1; then
		_default_home_pkg_ensure >/dev/null 2>&1 || true
		_home="${_DEFAULT_HOME_PKG_CACHE:-}"
		[[ -n $_home && $_pkg = "$_home" ]] && return 0
	fi
	case $_pkg in
	com.android.launcher3|com.android.launcher|com.miui.home|com.oneplus.launcher|com.google.android.apps.nexuslauncher|com.sec.android.app.launcher) return 0 ;;
	esac
	case $_label in
	*Launcher*|*launcher*|*桌面*|*啟動器*|*启动器*) return 0 ;;
	esac
	return 1
}

_restore_install_vendor_warning_record() {
	local _pkg="$1" _label="$2" _reason="$3" _detail="$4" _file
	[[ -n $_pkg ]] || _pkg="unknown"
	[[ -n $_label ]] || _label="unknown"
	[[ -n $_reason ]] || _reason="unknown"
	_label="$(printf '%s' "$_label" | tr '\t\r\n' '   ')"
	_detail="$(printf '%s' "$_detail" | tr '\t\r\n' '   ')"
	_file="$(_restore_install_vendor_warning_file)"
	printf '%s\t%s\t%s\t%s\n' "$_pkg" "$_label" "$_reason" "$_detail" >> "$_file" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	_speed_debug_log "RESTORE_INSTALL_VENDOR_CONSTRAINED package=$_pkg label=$_label reason=$_reason detail=$_detail mode=r377"
}

_restore_install_issue_record() {
	local _pkg="$1" _label="$2" _reason="$3" _detail="$4" _file
	[[ -n $_pkg ]] || _pkg="unknown"
	[[ -n $_label ]] || _label="unknown"
	[[ -n $_reason ]] || _reason="unknown"
	if _restore_install_issue_is_vendor_constrained "$_pkg" "$_label" "$_reason" "$_detail"; then
		_restore_install_vendor_warning_record "$_pkg" "$_label" "$_reason" "$_detail"
		return 0
	fi
	_label="$(printf '%s' "$_label" | tr '\t\r\n' '   ')"
	_detail="$(printf '%s' "$_detail" | tr '\t\r\n' '   ')"
	_file="$(_restore_install_issue_file)"
	printf '%s\t%s\t%s\t%s\n' "$_pkg" "$_label" "$_reason" "$_detail" >> "$_file" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	_speed_debug_log "RESTORE_INSTALL_ISSUE package=$_pkg label=$_label reason=$_reason detail=$_detail mode=r377"
}

_restore_install_issue_emit() {
	local _file="$(_restore_install_issue_file)" _warn_file="$(_restore_install_vendor_warning_file)" _count _warn_count
	_count=0
	_warn_count=0
	if [[ -s $_file ]]; then
		_count="$(awk 'NF{n++} END{print n+0}' "$_file" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null})"
		case $_count in ''|*[!0-9]*) _count=0 ;; esac
	fi
	if [[ -s $_warn_file ]]; then
		_warn_count="$(awk 'NF{n++} END{print n+0}' "$_warn_file" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null})"
		case $_warn_count in ''|*[!0-9]*) _warn_count=0 ;; esac
	fi
	if [[ $_warn_count -gt 0 ]]; then
		_speed_debug_log "RESTORE_INSTALL_VENDOR_CONSTRAINED_SUMMARY count=$_warn_count file=restore_install_vendor_warnings.tsv mode=r377"
		echoRgb "APK安裝系統限制警告: $_warn_count 個（詳情見 speed_debug/restore_install_vendor_warnings.tsv）" "2"
		sed -n '1,12p' "$_warn_file" 2>/dev/null | while IFS="$(printf '\t')" read -r _pkg _label _reason _detail; do
			[[ -n $_pkg ]] && echoRgb " - ${_label:-$_pkg} $_pkg system/vendor constrained" "2"
		done
		[[ $_warn_count -gt 12 ]] && echoRgb "其餘 $((_warn_count-12)) 個見 speed_debug/restore_install_vendor_warnings.tsv" "2"
		[[ -n ${SPEED_DEBUG_RUN_DIR:-} && -d ${SPEED_DEBUG_RUN_DIR:-} ]] && cp -f "$_warn_file" "$SPEED_DEBUG_RUN_DIR/restore_install_vendor_warnings.tsv" 2>/dev/null
	fi
	[[ $_count -gt 0 ]] || return 0
	_speed_debug_log "RESTORE_INSTALL_ISSUE_SUMMARY count=$_count file=restore_install_issues.tsv mode=r377"
	echoRgb "APK安裝/驗證異常: $_count 個（詳情見 speed_debug/restore_install_issues.tsv）" "0"
	sed -n '1,12p' "$_file" 2>/dev/null | while IFS="$(printf '\t')" read -r _pkg _label _reason _detail; do
		[[ -n $_pkg ]] && echoRgb " - ${_label:-$_pkg} $_pkg $_reason" "0"
	done
	[[ $_count -gt 12 ]] && echoRgb "其餘 $((_count-12)) 個見 speed_debug/restore_install_issues.tsv" "0"
	[[ -n ${SPEED_DEBUG_RUN_DIR:-} && -d ${SPEED_DEBUG_RUN_DIR:-} ]] && cp -f "$_file" "$SPEED_DEBUG_RUN_DIR/restore_install_issues.tsv" 2>/dev/null
	return 0
}

# 預掃所有待備份 app 的數據目錄大小 (data/user/user_de/obb), 並行加速 (約快 3 倍)
# 寫到 $TMPDIR/.dir_sizes, 格式: pkg<TAB>type<TAB>size; 主迴圈 _dir_size 查此表免重複遍歷
prepare_dir_size_map() {
	local _map="$TMPDIR/.dir_sizes"
	: > "$_map"
	local _list
	if [[ -n $1 ]]; then
		_list="$1"
	else
		_list="$(echo "$txt" | awk '{print $2}' | grep -v '^$')"
	fi
	[[ -z $_list ]] && return
	local _ss_manifest="$TMPDIR/.dir_sizes_manifest" _ss_bin
	_ss_bin="$(_speedscan_path 2>/dev/null)" || _ss_bin=""
	if [[ -n $_ss_bin ]]; then
		: > "$_ss_manifest"
		local _pkg _typ _dp _rows=0
		while read -r _pkg; do
			[[ -z $_pkg ]] && continue
			for _typ in user user_de data obb media; do
				case $_typ in
				user|user_de) [[ ${Backup_Mode:-false} = true && ${Backup_user_data:-false} = true ]] || continue ;;
				data|obb|media) [[ ${Backup_Mode:-false} = true && ${Backup_obb_data:-false} = true ]] || continue ;;
				esac
				case $_typ in
				user)    _dp="$path2/$_pkg" ;;
				user_de) _dp="$path3/$_pkg" ;;
				data)    _dp="$path/data/$_pkg" ;;
				obb)     _dp="$path/obb/$_pkg" ;;
				media)   _dp="$path/media/$_pkg" ;;
				esac
				[[ -d $_dp ]] || continue
				printf '%s	%s	%s
' "$_pkg" "$_typ" "$_dp" >> "$_ss_manifest"
				_rows=$((_rows+1))
				# r442: 同一輪 native speedscan 預掃順便掃 cache/code_cache，供備份前容量總覽顯示「排除快取」。
				case $_typ in
				user|user_de)
					for _ex in cache code_cache; do
						_ex_path="$_dp/$_ex"
						[[ -d $_ex_path ]] || continue
						printf '%s	%s	%s
' "$_pkg" "${_typ}_exclude_${_ex//[!a-zA-Z0-9]/_}" "$_ex_path" >> "$_ss_manifest"
						_rows=$((_rows+1))
				done
					;;
				data|obb|media)
					_ex_path="$_dp/cache"
					if [[ -d $_ex_path ]]; then
						printf '%s	%s	%s
' "$_pkg" "${_typ}_exclude_cache" "$_ex_path" >> "$_ss_manifest"
						_rows=$((_rows+1))
					fi
					;;
				esac
			done
		done <<EOF
$_list
EOF
		# r446: Custom_path / Media 也納入同輪 C native speedscan dir-size-map。
		# summary 階段只讀 .dir_sizes，不再額外 calc_dir_size，因此預掃完成後容量總覽應秒出。
		if [[ ${backup_media:-false} = true && ! -f ${0%/*}/app_details.json && -n ${Custom_path:-} ]]; then
			local _custom_tmp="$TMPDIR/.dir_sizes_custom_media_$$" _custom_path _custom_actual _custom_idx=0
			printf '%s\n' "$Custom_path" | awk '!/[#＃]/ && NF' | sed 's:/*$::' > "$_custom_tmp" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
			while IFS= read -r _custom_path || [[ -n $_custom_path ]]; do
				[[ -n $_custom_path ]] || continue
				_custom_actual="$(_media_storage_lower_path "$_custom_path" 2>/dev/null)"
				[[ -n $_custom_actual && -d $_custom_actual ]] || _custom_actual="$_custom_path"
				if [[ ! -d $_custom_actual ]]; then
					_speed_debug_log "DIRSIZE_MAP_CUSTOM_MEDIA_SKIP path=$_custom_path actual=$_custom_actual reason=not-dir mode=r459"
					continue
				fi
				_custom_idx=$((_custom_idx + 1))
				printf '%s	%s	%s
' "__speedbackup_custom_media__" "media_${_custom_idx}" "$_custom_actual" >> "$_ss_manifest"
				_rows=$((_rows + 1))
				if [[ -d $_custom_actual/cache ]]; then
					printf '%s	%s	%s
' "__speedbackup_custom_media__" "media_${_custom_idx}_exclude_cache" "$_custom_actual/cache" >> "$_ss_manifest"
					_rows=$((_rows + 1))
				fi
			done < "$_custom_tmp"
			rm -f "$_custom_tmp" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
			_speed_debug_log "DIRSIZE_MAP_CUSTOM_MEDIA_MANIFEST rows=$_custom_idx mode=r446 source=native-speedscan"
		fi
		[[ $_rows -gt 0 ]] && _speedbackup_progress_step 0 "$_rows" "正在預掃數據大小" "prepare_dir_size_speedscan" "107"
		if [[ $_rows -gt 0 ]] && "$_ss_bin" dir-size-map "$_ss_manifest" > "$_map" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}; then
			_eventwait_output_file_stable_ms "$_map" dirsize_map_ready 80 1500 >/dev/null 2>&1 || true
			_speed_debug_log "DIRSIZE_MAP_SPEEDSCAN_OK rows=$(wc -l < "$_map" 2>/dev/null) manifestRows=$_rows bin=$_ss_bin"
			_speedbackup_progress_step "$_rows" "$_rows" "數據大小預掃完成" "prepare_dir_size_speedscan" "107"
			rm -f "$_ss_manifest" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
			return 0
		fi
		_speed_debug_log "DIRSIZE_MAP_SPEEDSCAN_FALLBACK rows=$_rows bin=${_ss_bin:-missing}"
		rm -f "$_ss_manifest" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	fi
	local _workdir="$TMPDIR/.dirsize_work"
	rm -rf "$_workdir"; mkdir -p "$_workdir"
	local _total _i=0 _running=0 _par=8 _dsz_pids=""
	_total="$(echo "$_list" | grep -vc '^$')"
	_speed_debug_log "DIRSIZE_MAP_START total=$_total par=$_par remote_type=${remote_type:-none} deferred_remote=${SPEEDBACKUP_REMOTE_SETUP_DEFERRED:-0}"
	# 用 here-string 餵 while, 避免管道把迴圈丟進子 shell (子 shell 內背景任務的變數作用域問題)
	local _pkg _typ _dp
	while read -r _pkg; do
		[[ -z $_pkg ]] && continue
		let _i++
		printf '\r -預掃數據大小 %d/%d %s' "$_i" "$_total" "$(progress_bar $((_i * 100 / _total)))" >&2
		for _typ in user user_de data obb media; do
			case $_typ in
				user|user_de)
					if [[ ${Backup_Mode:-false} != true || ${Backup_user_data:-false} != true ]]; then
						_speed_debug_log "DIRSIZE_SKIP pkg=$_pkg type=$_typ reason=user_data_disabled"
						continue
					fi
					;;
				data|obb|media)
					if [[ ${Backup_Mode:-false} != true || ${Backup_obb_data:-false} != true ]]; then
						_speed_debug_log "DIRSIZE_SKIP pkg=$_pkg type=$_typ reason=obb_data_disabled"
						continue
					fi
					;;
			esac
			case $_typ in
				user)    _dp="$path2/$_pkg" ;;
				user_de) _dp="$path3/$_pkg" ;;
				data)    _dp="$path/data/$_pkg" ;;
				obb)     _dp="$path/obb/$_pkg" ;;
				media)   _dp="$path/media/$_pkg" ;;
			esac
			[[ ! -d $_dp ]] && continue
			# 背景並行算大小, 各寫獨立檔 (無共享寫入, 安全); 背景內再確認 workdir 存在防競態
			{
				if [[ -d $_workdir ]]; then
					_ds_start="$(date -u +%s%3N 2>/dev/null)"; [[ -z $_ds_start ]] && _ds_start=$(( $(date -u +%s 2>/dev/null) * 1000 ))
					_speed_debug_log "DIRSIZE_BEGIN pkg=$_pkg type=$_typ path=$_dp"
					_ds_size="$(find "$_dp" -type f -printf '%s\n' 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} | _decimal_sum_uint_stdin)"
					printf '%s\t%s\t%s\n' "$_pkg" "$_typ" "$_ds_size" > "$_workdir/${_pkg}.${_typ}" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
					_ds_end="$(date -u +%s%3N 2>/dev/null)"; [[ -z $_ds_end ]] && _ds_end=$(( $(date -u +%s 2>/dev/null) * 1000 ))
					_ds_elapsed=$((_ds_end - _ds_start))
					_speed_debug_log "DIRSIZE_END pkg=$_pkg type=$_typ elapsedMs=$_ds_elapsed size=$_ds_size path=$_dp"
					[[ $_ds_elapsed -ge 5000 ]] && _speed_debug_log "DIRSIZE_SLOW pkg=$_pkg type=$_typ elapsedMs=$_ds_elapsed size=$_ds_size path=$_dp"
				fi
				# 上一條 [[ elapsed -ge 5000 ]] 在非慢目錄時會回 1；背景 size 任務本身已成功，避免 wait list 顯示 rc=1。
				true
			} &
			_dsz_pids="$_dsz_pids $!"
			SPEEDBACKUP_DIRSIZE_PIDS="${SPEEDBACKUP_DIRSIZE_PIDS:-} $!"
			_running=$((_running+1))
			[[ $_running -ge $_par ]] && { _event_wait_pid_list "$_dsz_pids" dirsize_batch; _dsz_pids=""; SPEEDBACKUP_DIRSIZE_PIDS=""; _running=0; }
		done
	done <<EOF
$_list
EOF
	_event_wait_pid_list "$_dsz_pids" dirsize_final
	SPEEDBACKUP_DIRSIZE_PIDS=""
	echo >&2
	cat "$_workdir"/* 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} > "$_map"
	_speed_debug_log "DIRSIZE_MAP_END rows=$(wc -l < "$_map" 2>/dev/null)"
	rm -rf "$_workdir"
}

# WebDAV 遠端總列表已成功取得時，若明確沒有某個檔案，視為已知不存在。
# 用途：避免對全新/剛刪除的 app_details.json 發 GET；部分輕量 WebDAV server
# 對不存在檔案會短暫回 2xx + Content-Length 但 body 提前 EOF，造成 fixed body EOF 噪音。
_remote_filelist_has_rel() {
	local _rel="$1"
	[[ $remote_stream = 1 ]] || return 1
	[[ -f $TMPDIR/.remote_files && -f $TMPDIR/.remote_filelist_ok ]] || return 1
	awk -v r="$_rel" '$0==r{f=1;exit} END{exit f?0:1}' "$TMPDIR/.remote_files" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
}

_remote_webdav_filelist_absent() {
	local _rel="$1"
	[[ $remote_type = webdav && $remote_stream = 1 ]] || return 1
	[[ -f $TMPDIR/.remote_files ]] || return 1
	# 7.66-277：清掉 275/276 測試殘留的 shell 變數 gate，統一只信任 marker file。
	# 避免函式重定向 / 子流程邊界造成變數可見性誤判。
	[[ -f $TMPDIR/.remote_filelist_ok ]] || return 1
	_remote_filelist_has_rel "$_rel" && return 1
	return 0
}

# SMB 遠端總列表已成功取得且路徑為純 ASCII 時，若明確沒有某個檔案，視為已知不存在。
# 中文/非 ASCII app 名稱保留原本 get fallback，避免 smbclient 代碼頁轉碼造成 false missing。
_remote_smb_filelist_absent() {
	local _rel="$1"
	[[ $remote_type = smb && $remote_stream = 1 ]] || return 1
	[[ -f $TMPDIR/.remote_files ]] || return 1
	grep -q . "$TMPDIR/.remote_files" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} || return 1
	printf '%s\n' "$_rel" | LC_ALL=C grep -Eq '^[ -~]+$' 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} || return 1
	awk -v r="$_rel" '$0==r{f=1;exit} END{exit !f}' "$TMPDIR/.remote_files" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} && return 1
	return 0
}

# 遠端模式: 並發預掃所有 app 的遠端 app_details.json 到本地快取
# 主迴圈 apk/data 增量比對直接讀快取, 免每 app 多次遠端往返
prepare_remote_json_map() {
	local _cache
	if [[ ${remote_stream:-0} = 1 && -n ${remote_type:-} ]]; then
		_cache="$(_appdetails_bundle_stage_root)"
		rm -rf "$_cache" "$TMPDIR/.remote_json" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
		mkdir -p "$_cache" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	else
		_cache="$TMPDIR/.remote_json"
		rm -rf "$_cache"; mkdir -p "$_cache"
	fi
	[[ -z $remote_type ]] && return
	local _list
	# appList/txt 格式是「備份顯示名 package version...」；主備份迴圈的遠端資料夾固定使用第 1 欄 name1。
	# 舊寫法只移除最後一欄，遇到三欄格式會變成「AdobeScan com.adobe.scan.android」，
	# 導致預掃去找 AdobeScan com.adobe.scan.android/app_details.json，
	# 實際遠端卻是 AdobeScan/app_details.json，第二輪仍被誤判為「遠端無此備份」。
	_list="$(echo "$txt" | awk '{n=$1; sub(/^[!！]+/,"",n); if(n!="") print n}' | grep -v '^$')"
	if [[ -z $_list ]]; then
		if [[ ${remote_stream:-0} != 1 || -z ${remote_type:-} ]]; then
			touch "$_cache/.done"
		fi
		return
	fi
	local _subdir
	_subdir="${_BACKUP_DIRNAME_CACHED:-$(get_backup_dirname)}"
	# WebDAV 根備份目錄 404 時代表遠端是全新備份或目錄不存在；
	# 此時不嘗試抓 metadata bundle，直接標記完成並走全量備份，避免新遠端被誤標 fatal。
	if [[ $remote_type = webdav && ${REMOTE_BACKUP_ROOT_MISSING:-0} = 1 ]]; then
		_speed_debug_log "REMOTE_JSON_SKIP reason=backup_root_404 total=$(printf '%s\n' "$_list" | grep -vc '^$' 2>/dev/null) subdir=$_subdir mode=single-stage-r286"
		echoRgb "遠端備份目錄不存在，跳過 app_details bundle 預抓，改走全量備份" "2"
		if [[ ${remote_stream:-0} != 1 || -z ${remote_type:-} ]]; then
			touch "$TMPDIR/.remote_json/.done"
		fi
		return 0
	fi
	# r277: app_details 遠端 metadata 改為 single-stage bundle-only，不再逐 App GET app_details.json。
	# bundle 不存在代表舊版備份；主線不做 fallback，直接視為無遠端 JSON 紀錄。
	if [[ ${remote_stream:-0} = 1 && -n ${remote_type:-} ]]; then
		_speedbackup_busy_step "預掃遠端 app_details bundle..." "prepare_remote_bundle_map" "107"
		_appdetails_bundle_seed_remote_json_cache "$_subdir" "$_cache" || true
		_speed_debug_log "PROGRESS_ONESHOT_COLLAPSE tag=prepare_remote_bundle_map mode=busy status=done reason=one_step_0_1_hidden_r286"
		echoRgb "遠端 app_details bundle 預掃完成" "2"
		local _bundle_got=0
		_bundle_got="$(_appdetails_index_count "$_cache" 2 2)"
		case $_bundle_got in ''|*[!0-9]*) _bundle_got=0 ;; esac
		echoRgb "遠端 bundle staging: $_bundle_got 個 app 有遠端紀錄" "2"
		return 0
	fi
	# 全部 app 直接批量抓 json (不靠遠端列表交集 — smbclient 列表對中文名會轉碼毀名導致誤配)
	# 不存在的檔 get 失敗即空, 內容驗證會濾掉; 批量模式連線數不增
	echo "$_list" > "$TMPDIR/.json_fetch"
	local _total _i=0
	_total="$(grep -vc '^$' "$TMPDIR/.json_fetch")"
	if [[ $_total -eq 0 ]]; then
		rm -f "$TMPDIR/.json_fetch"; touch "$_cache/.done"; echo >&2; return
	fi
	if [[ $remote_type = smb ]]; then
		# SMB: 單連線批量 get (每批 20 檔), 連線數 120→6
		local _auth SMB_OPTS _batchcmd="" _app _n=0 _smb_json_rc
		_auth="$(_smb_auth_args_current)" || { _smb_auth_unavailable_msg "操作"; return 1; }
		SMB_OPTS="-t 300 -s $(_smb_client_conf)${REMOTE_PORT:+ -p $REMOTE_PORT} -m SMB3"
		local _base="$SMB_REM_PATH/$_subdir"; _base="${_base#/}"; _base="${_base//\//\\}"
		while read -r _app; do
			[[ -z $_app ]] && continue
			if _remote_netwatch_mark_remote_fatal "remote_json_smb_prescan_app" "$_app"; then
				_speed_debug_log "REMOTE_JSON_SMB_PRESCAN_ABORT reason=remote_netwatch_changed app=$_app"
				break
			fi
			let _i++
			if _remote_smb_filelist_absent "$_app/app_details.json"; then
				_speed_debug_log "SMB_REMOTE_APPDETAILS_LIST_MISS app=$_app rel=$_app/app_details.json"
				continue
			fi
			let _n++
			_batchcmd="$_batchcmd get \"${_app//\//\\}\\app_details.json\" \"$_cache/$_app.json\";"
			if [[ $_n -ge 20 ]]; then
				printf '\r -預掃遠端清單 %d/%d' "$_i" "$_total" >&2
				if _remote_netwatch_mark_remote_fatal "remote_json_smb_before_batch" "$_app"; then
					_speed_debug_log "REMOTE_JSON_SMB_BATCH_SKIP reason=remote_netwatch_changed app=$_app"
					break
				fi
				smbclient "$SMB_SHARE" $_auth $SMB_OPTS -c "cd \"$_base\"; $_batchcmd" >/dev/null 2>&1
				_smb_json_rc=$?
				if [[ $_smb_json_rc != 0 ]]; then
					_remote_netwatch_mark_remote_fatal "remote_json_smb_batch_fail" "$_app" >/dev/null 2>&1 || true
				fi
				_batchcmd=""; _n=0
			fi
		done < "$TMPDIR/.json_fetch"
		if [[ -n $_batchcmd ]]; then
			if _remote_netwatch_mark_remote_fatal "remote_json_smb_before_final_batch" "final"; then
				_speed_debug_log "REMOTE_JSON_SMB_FINAL_BATCH_SKIP reason=remote_netwatch_changed"
			else
				smbclient "$SMB_SHARE" $_auth $SMB_OPTS -c "cd \"$_base\"; $_batchcmd" >/dev/null 2>&1
				_smb_json_rc=$?
				if [[ $_smb_json_rc != 0 ]]; then
					_remote_netwatch_mark_remote_fatal "remote_json_smb_final_batch_fail" "final" >/dev/null 2>&1 || true
				fi
			fi
		fi
		printf '\r -預掃遠端清單 %d/%d' "$_total" "$_total" >&2
	else
		# WebDAV: 預掃 app_details 改用單檔 GET。
		# v24.20.14-7.66-15：部分 WebDAV 服務在 _stream_download 預掃小 JSON 時會回下載 rc=18，
		# 但同一路徑用 remote_download_single_file/WEBDAV_SINGLE_GET 可成功。
		# 因此這裡直接走已驗證較穩的單檔 GET，避免遠端已有 app_details 卻 seed 失敗後不必要重備份。
		local _running=0 _app _json_pids=""
		while read -r _app; do
			[[ -z $_app ]] && continue
			if _remote_netwatch_mark_remote_fatal "remote_json_webdav_prescan_app" "$_app"; then
				_speed_debug_log "REMOTE_JSON_WEBDAV_PRESCAN_ABORT reason=remote_netwatch_changed app=$_app"
				break
			fi
			let _i++
			printf '\r -預掃遠端清單 %d/%d' "$_i" "$_total" >&2
			(
				local _tmp_json="$_cache/$_app.json.part" _final_json="$_cache/$_app.json" _ok=0 _try=1
				rm -f "$_tmp_json" "$_final_json" 2>/dev/null
				if _remote_filelist_absent "$_app/app_details.json" appdetails; then
					_speed_debug_log "WEBDAV_REMOTE_APPDETAILS_LIST_MISS app=$_app rel=$_app/app_details.json"
					exit 0
				fi
				# 只有 HTTP 0 / daemon 無回應 / 連線類錯誤才 retry。
				# HTTP 404 代表該 app 遠端本來就沒有 app_details，不重試，避免冷遠端 50 app 變 100 次 GET。
				while [[ $_try -le 2 ]]; do
					if remote_download_single_file "$_app/app_details.json" "$_tmp_json"; then
						_ok=1
						break
					fi
					case ${_WEBDAV_HTTP_CODE:-0} in
					0)
						_speed_debug_log "WEBDAV_REMOTE_APPDETAILS_RETRY app=$_app try=$_try http=${_WEBDAV_HTTP_CODE:-0}"
						rm -f "$_tmp_json" 2>/dev/null
						let _try++
						[[ $_try -le 2 ]] && sleep 1
						;;
					*)
						_speed_debug_log "WEBDAV_REMOTE_APPDETAILS_NO_RETRY app=$_app try=$_try http=${_WEBDAV_HTTP_CODE:-0}"
						break
						;;
					esac
				done
				if [[ $_ok = 1 ]]; then
					# 遠端 app_details 快取必須是完整 object，且至少含 PackageName/apk_version。
					if [[ -s $_tmp_json ]] && _remote_appdetails_json_ok "$_tmp_json"; then
						mv "$_tmp_json" "$_final_json" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
					else
						_speed_debug_log "WEBDAV_REMOTE_APPDETAILS_INVALID_DROP app=$_app file=$_tmp_json"
						rm -f "$_tmp_json" "$_final_json" 2>/dev/null
					fi
				else
					_speed_debug_log "WEBDAV_REMOTE_APPDETAILS_MISSING_OR_FAIL app=$_app method=single_get_retry"
					rm -f "$_tmp_json" "$_final_json" 2>/dev/null
				fi
			) &
			_json_pids="$_json_pids $!"
			let _running++
			if [[ $_running -ge 8 ]]; then _event_wait_pid_list "$_json_pids" webdav_json_fetch_batch; _json_pids=""; _running=0; fi
		done < "$TMPDIR/.json_fetch"
		_event_wait_pid_list "$_json_pids" webdav_json_fetch_final
	fi
	rm -f "$TMPDIR/.json_fetch"
	# 內容驗證: 必須是完整 JSON object；非 JSON / 半截 JSON 一律視為不存在。
	local _jf
	for _jf in "$_cache"/*.json; do
		[[ -f $_jf ]] || continue
		if ! _remote_appdetails_json_ok "$_jf"; then
			_speed_debug_log "REMOTE_APPDETAILS_CACHE_DROP_INVALID file=${_jf##*/}"
			rm -f "$_jf" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
		fi
	done
	echo >&2
	local _got=0
	for _jf in "$_cache"/*.json; do
		[[ -f $_jf ]] || continue
		_got=$((_got + 1))
	done
	echoRgb "遠端清單快取: $_got/$_total 個 app 有遠端紀錄" "2"
	touch "$_cache/.done"
}

# 取遠端 app_details: 預掃快取命中直接用。
# return: 0=取得成功, 1=下載/網路異常, 2=預掃已確認遠端不存在。
_get_remote_appdetails() {
	local _cache="$TMPDIR/.remote_json" _name="$1" _out="$2" _cache_file
	if [[ ${remote_stream:-0} = 1 && -n ${remote_type:-} && $_name != Media ]]; then
		_cache_file="$(_appdetails_bundle_remote_json_path "$_name")"
		if [[ -s "$_cache_file" ]]; then
			if _appdetails_has_required_meta "$_cache_file"; then
				cp "$_cache_file" "$_out" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
				_appdetails_has_required_meta "$_out" && return 0
			fi
			_speed_debug_log "REMOTE_APPDETAILS_BUNDLE_STAGE_INVALID_DROP name=$_name cache=$_cache_file"
			rm -f "$_out" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
			return 2
		fi
		return 2
	fi
	# Media 不在批量預掃範圍內 (prepare_remote_json_map 只抓 appList.txt 裡的 app 名稱),
	# 但流式模式已經有遠端總列表；若列表沒有 Media/app_details.json，視為「已知不存在」而不是錯誤。
	if [[ $_name = Media ]]; then
		if [[ $remote_stream = 1 && -f $TMPDIR/.remote_files ]]; then
			awk -v r="Media/app_details.json" '$0==r{f=1;exit} END{exit !f}' "$TMPDIR/.remote_files" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} || return 2
		fi
		remote_download_single_file "$_name/app_details.json" "$_out"
		return $?
	fi
	if [[ -f $_cache/.done ]]; then
		if [[ -s "$_cache/$_name.json" ]]; then
			# v24.20.14-7.15：讀快取前再驗一次，避免舊壞快取被健康檢查當成「遠端 json 損壞」。
			if _appdetails_has_required_meta "$_cache/$_name.json"; then
				cp "$_cache/$_name.json" "$_out" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
				if _appdetails_has_required_meta "$_out"; then
					return 0
				fi
			fi
			_speed_debug_log "REMOTE_APPDETAILS_CACHE_INVALID_DROP name=$_name cache=$_cache/$_name.json"
			rm -f "$_cache/$_name.json" "$_out" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
			return 2
		fi
		# 批量預掃已完成且沒有此 app 的 json：這是全新遠端備份/遠端缺檔，不是下載失敗。
		return 2
	fi
	remote_download_single_file "$_name/app_details.json" "$_out"
}

# 一次抓遠端檔案總列表 (供腳本檢查/核驗共用, 單連線取代逐檔往返)
prepare_remote_filelist() {
	: > "$TMPDIR/.remote_files"
	rm -f "$TMPDIR/.remote_filelist_ok" "$TMPDIR/.remote_webdav_last_list_ok" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	REMOTE_FILELIST_HTTP_CODE=0
	REMOTE_BACKUP_ROOT_MISSING=0
	[[ -z $remote_type ]] && return
	echoRgb "預掃遠端檔案列表 (單次連線)..." "3"
	remote_list_files "${_BACKUP_DIRNAME_CACHED:-$(get_backup_dirname)}" > "$TMPDIR/.remote_files" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	_eventwait_output_file_stable_ms "$TMPDIR/.remote_files" remote_filelist_ready 80 1500 >/dev/null 2>&1 || true
	if [[ $remote_type = webdav ]]; then
		if [[ -f $TMPDIR/.remote_webdav_last_list_ok ]]; then
			REMOTE_FILELIST_HTTP_CODE=207
			: > "$TMPDIR/.remote_filelist_ok"
			_speed_debug_log "WEBDAV_REMOTE_FILELIST_OK rows=$(grep -vc '^$' "$TMPDIR/.remote_files" 2>/dev/null)"
		else
			REMOTE_FILELIST_HTTP_CODE="${_WEBDAV_HTTP_CODE:-0}"
			case $REMOTE_FILELIST_HTTP_CODE in
			404)
				REMOTE_BACKUP_ROOT_MISSING=1
				_speed_debug_log "REMOTE_FILELIST_ROOT_MISSING http=404 subdir=${_BACKUP_DIRNAME_CACHED:-$(get_backup_dirname)}"
				;;
			esac
		fi
	else
		: > "$TMPDIR/.remote_filelist_ok"
	fi
	echoRgb "遠端列表取得 $(grep -vc '^$' "$TMPDIR/.remote_files" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}) 筆" "2"
}

_remote_filelist_has_prefix() {
	local _prefix="$1"
	[[ $remote_stream = 1 ]] || return 1
	[[ -n $_prefix ]] || return 1
	[[ -f $TMPDIR/.remote_files && -f $TMPDIR/.remote_filelist_ok ]] || return 1
	awk -v p="$_prefix" 'index($0,p)==1{f=1;exit} END{exit f?0:1}' "$TMPDIR/.remote_files" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
}

_remote_filelist_has_any_rel() {
	local _a="$1" _b="$2"
	[[ $remote_stream = 1 ]] || return 1
	[[ -f $TMPDIR/.remote_files && -f $TMPDIR/.remote_filelist_ok ]] || return 1
	awk -v a="$_a" -v b="$_b" '$0==a||$0==b{f=1;exit} END{exit f?0:1}' "$TMPDIR/.remote_files" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
}


# r491: 流式恢復開頭校正 appList_network 與遠端實檔/metadata 的交集。
# 規則：
# - 遠端仍有 App 資料夾，但 app_details_bundle / legacy app_details.json 都沒有 metadata：保留清單並警告。
# - 遠端資料夾與 metadata 都不存在：視為已刪孤兒，從本輪 stream list 與本地 appList_network.txt 移除。
# 只在遠端總列表成功時執行；列表不可用時不做破壞性修改。
_restore_stream_prune_missing_remote_apps() {
	local _src="$1" _work="$2" _stage="${3:-$TMPDIR/.restore_stage}" _tmp _rewrite _line _trim _body _name _json_rel _folder _json _kept=0 _dropped=0 _warn=0 _total=0
	[[ ${_RESTORE_STREAM:-0} = 1 ]] || return 0
	[[ -f $TMPDIR/.remote_files && -f $TMPDIR/.remote_filelist_ok ]] || { _speed_debug_log "STREAM_RESTORE_LIST_PRUNE_SKIP reason=no_remote_filelist source=$_src work=$_work mode=r491"; return 0; }
	[[ -f $_work ]] || return 0
	_tmp="${_work}.r491_pruned.$$"
	_rewrite="${_src}.r491_pruned.$$"
	: > "$_tmp" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} || return 1
	[[ -f $_src ]] && : > "$_rewrite" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} || _rewrite=""
	while IFS= read -r _line; do
		_trim="$(printf '%s\n' "$_line" | tr '\t' ' ' | sed 's/^[ ]*//;s/[ ]*$//')"
		case "$_trim" in
		''|\#*|＃*)
			printf '%s\n' "$_line" >> "$_tmp" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
			[[ -n $_rewrite ]] && printf '%s\n' "$_line" >> "$_rewrite" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
			continue
			;;
		esac
		_body="$_trim"
		case "$_body" in
		!play[[:space:]]*|！play[[:space:]]*)
			_body="${_body#*!play}"; _body="${_body#*！play}"; _body="$(printf '%s\n' "$_body" | sed 's/^[ ]*//')"
			;;
		![[:space:]]*|！[[:space:]]*|!*)
			_body="${_body#!}"; _body="${_body#！}"; _body="$(printf '%s\n' "$_body" | sed 's/^[ ]*//')"
			;;
		esac
		_name="${_body%% *}"
		case "$_name" in
		''|wifi|Media|*.tar|*.tar.zst)
			printf '%s\n' "$_line" >> "$_tmp" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
			[[ -n $_rewrite ]] && printf '%s\n' "$_line" >> "$_rewrite" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
			continue
			;;
		esac
		_total=$((_total + 1))
		_json_rel="$_name/app_details.json"
		_folder=0
		_json=0
		if _remote_filelist_has_prefix "$_name/"; then
			_folder=1
		fi
		if _remote_filelist_has_any_rel "$_json_rel" "$_json_rel" || [[ -s "$_stage/$_name/app_details.json" ]]; then
			_json=1
		fi
		if [[ $_folder = 0 && $_json = 0 ]]; then
			_dropped=$((_dropped + 1))
			_speed_debug_log "STREAM_RESTORE_LIST_PRUNE_MISSING_REMOTE_APP app=$_name reason=no_remote_folder_no_appdetails action=drop source=$_src mode=r491"
			continue
		fi
		if [[ $_folder = 1 && $_json = 0 ]]; then
			_warn=$((_warn + 1))
			_speed_debug_log "STREAM_RESTORE_LIST_WARN_FOLDER_WITHOUT_APPDETAILS app=$_name rel=$_json_rel action=keep mode=r491"
			echoRgb "警告: $_name 遠端資料夾存在但缺少 app_details.json，將保留清單並在恢復時依錯誤處理" "0"
		fi
		printf '%s\n' "$_line" >> "$_tmp" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
		[[ -n $_rewrite ]] && printf '%s\n' "$_line" >> "$_rewrite" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
		_kept=$((_kept + 1))
	done < "$_work"
	cat "$_tmp" > "$_work" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} || true
	if [[ -n $_rewrite && -f $_src && -s $_rewrite ]]; then
		cat "$_rewrite" > "$_src" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} && _speed_debug_log "STREAM_RESTORE_LIST_SOURCE_REWRITE_OK source=$_src dropped=$_dropped kept=$_kept mode=r491" || _speed_debug_log "STREAM_RESTORE_LIST_SOURCE_REWRITE_FAIL source=$_src dropped=$_dropped kept=$_kept mode=r491"
	elif [[ -n $_rewrite && -f $_src && $_dropped -gt 0 ]]; then
		: > "$_src" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} || true
		_speed_debug_log "STREAM_RESTORE_LIST_SOURCE_REWRITE_EMPTY source=$_src dropped=$_dropped kept=$_kept mode=r491"
	fi
	rm -f "$_tmp" "$_rewrite" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	_speed_debug_log "STREAM_RESTORE_LIST_PRUNE_DONE source=$_src work=$_work total=$_total kept=$_kept dropped=$_dropped folderWithoutJson=$_warn mode=r491"
	[[ $_dropped -gt 0 ]] && echoRgb "已從 appList_network.txt 移除 $_dropped 個遠端已不存在的項目" "2"
	return 0
}

_remote_payload_missing_map_file() {
	printf '%s\n' "${TMPDIR:-/data/local/tmp}/.remote_payload_missing_map"
}

_remote_payload_missing_note() {
	local _name="$1" _pkg="$2" _entry="$3" _rel="$4" _f
	[[ -n $_name && -n $_entry && -n $_rel ]] || return 0
	_f="$(_remote_payload_missing_map_file)"
	printf '%s	%s	%s	%s
' "$_name" "$_pkg" "$_entry" "$_rel" >> "$_f" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} || true
	_speed_debug_log "REMOTE_PAYLOAD_MISSING_NOTE app=$_name package=$_pkg entry=$_entry rel=$_rel mode=r377"
}

_remote_payload_missing_hit() {
	local _name="$1" _entry="$2" _f
	_f="$(_remote_payload_missing_map_file)"
	[[ -s $_f && -n $_name && -n $_entry ]] || return 1
	awk -F '	' -v n="$_name" -v e="$_entry" '$1==n && $3==e{f=1;exit} END{exit f?0:1}' "$_f" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
}

_stream_download_remote_missing_file() {
	printf '%s\n' "${TMPDIR:-/data/local/tmp}/.stream_download_remote_missing"
}

_stream_download_remote_missing_note() {
	local _rel="$1" _f
	[[ -n $_rel ]] || return 0
	_f="$(_stream_download_remote_missing_file)"
	printf '%s\n' "$_rel" >> "$_f" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} || true
	_speed_debug_log "STREAM_DOWNLOAD_REMOTE_MISSING rel=$_rel http=404 mode=r377"
}

_stream_download_remote_missing_hit() {
	local _rel="$1" _f
	_f="$(_stream_download_remote_missing_file)"
	[[ -s $_f && -n $_rel ]] || return 1
	awk -v r="$_rel" '$0==r{f=1;exit} END{exit f?0:1}' "$_f" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
}

_restore_stream_payload_known_missing() {
	local _src="$1" _rel _root
	[[ ${_RESTORE_STREAM:-0} = 1 && -n $_src && -f $TMPDIR/.remote_files && -f $TMPDIR/.remote_filelist_ok ]] || return 1
	_rel="$_src"
	_root="${_RESTORE_SUBDIR:-${_BACKUP_DIRNAME_CACHED:-$(get_backup_dirname)}}"
	case $_rel in
	$_root/*) _rel="${_rel#$_root/}" ;;
	esac
	_remote_files_note_has_any_rel "$_rel" "$_rel" && return 1
	return 0
}

_remote_files_note_has_any_rel() {
	# r364: final verification fast path uses this-run successful upload notes.
	# It must not require .remote_filelist_ok: WebDAV initial classify/list may be empty or fail
	# on a fresh remote, while successful PUT notes are still authoritative for this run.
	local _a="$1" _b="$2"
	[[ $remote_stream = 1 ]] || return 1
	[[ -f $TMPDIR/.remote_files ]] || return 1
	awk -v a="$_a" -v b="$_b" '$0==a||$0==b{f=1;exit} END{exit f?0:1}' "$TMPDIR/.remote_files" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
}

_remote_fast_skip_entry_ok() {
	local _name="$1" _pkg="$2" _entry="$3" _json="$4" _data_path _cur _remote
	case $_entry in
	user) _data_path="$path2/$_pkg" ;;
	user_de) _data_path="$path3/$_pkg" ;;
	data|obb|media) _data_path="$path/$_entry/$_pkg" ;;
	*) _speed_debug_log "REMOTE_FAST_SKIP_ENTRY_MISS app=$_name package=$_pkg entry=$_entry reason=unknown_entry"; return 1 ;;
	esac
	# 路徑不存在時既有 Backup_data 也不會產生備份，視為可快速跳過。
	[[ -d $_data_path ]] || { _speed_debug_log "REMOTE_FAST_SKIP_ENTRY_OK app=$_name package=$_pkg entry=$_entry reason=local_path_missing"; return 0; }
	_dir_size "$_pkg" "$_entry" "$_data_path"; _cur="$_DIR_SIZE_RET"
	case $_cur in ''|*[!0-9]*) _speed_debug_log "REMOTE_FAST_SKIP_ENTRY_MISS app=$_name package=$_pkg entry=$_entry reason=local_size_invalid local=$_cur path=$_data_path"; return 1 ;; esac
	# <1KB 依既有語義不備份且不寫入 payload entry。
	[[ ${#_cur} -lt 4 ]] && { _speed_debug_log "REMOTE_FAST_SKIP_ENTRY_OK app=$_name package=$_pkg entry=$_entry reason=small_local_size local=$_cur"; return 0; }
	_remote="$(_appdetails_get_entry_size "$_json" "$_entry")"
	if [[ -z $_remote || $_remote = null || $_remote != "$_cur" ]]; then
		_speed_debug_log "REMOTE_FAST_SKIP_ENTRY_MISS app=$_name package=$_pkg entry=$_entry reason=size_mismatch local=$_cur remote=${_remote:-empty}"
		return 1
	fi
	if ! _remote_filelist_has_any_rel "$_name/$_entry.tar.zst" "$_name/$_entry.tar"; then
		_speed_debug_log "REMOTE_FAST_SKIP_ENTRY_MISS app=$_name package=$_pkg entry=$_entry reason=payload_missing rel=$_name/$_entry.tar.zst mode=r377"
		_remote_payload_missing_note "$_name" "$_pkg" "$_entry" "$_name/$_entry.tar.zst"
		return 1
	fi
	_speed_debug_log "REMOTE_FAST_SKIP_ENTRY_OK app=$_name package=$_pkg entry=$_entry reason=size_payload_ok local=$_cur"
	return 0
}

prepare_remote_fast_skip_map() {
	local _map="$TMPDIR/.remote_fast_skip_ok"
	: > "$_map"
	: > "$(_remote_payload_missing_map_file)" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} || true
	[[ $remote_stream = 1 && -n $remote_type ]] || return 0
	[[ -f $TMPDIR/.remote_files && -f $TMPDIR/.remote_filelist_ok ]] || return 0
	if ! _appdetails_bundle_remote_json_ready; then
		_speed_debug_log "REMOTE_FAST_SKIP_PRESCAN_SKIP reason=remote_json_unavailable mode=single-stage-r286 rows=0"
		return 0
	fi
	local _line _name _pkg _json _cv _rv _nodata _ok _entry _total _i=0
	_total="$(printf '%s\n' "$txt" | awk 'NF && $1 !~ /^[#＃]/ {n++} END{print n+0}' 2>/dev/null)"
	case $_total in ''|*[!0-9]*) _total=0 ;; esac
	[[ $_total -gt 0 ]] && _speedbackup_progress_step 0 "$_total" "正在比對遠端是否變更" "prepare_remote_fast_skip_map" "107"
	while IFS= read -r _line; do
		case $_line in ''|\#*|＃*) continue ;; esac
		_i=$((_i + 1))
		[[ $_total -gt 0 ]] && _speedbackup_progress_step "$_i" "$_total" "比對遠端變更 ${_line%% *}" "prepare_remote_fast_skip_map" "107"
		_name="${_line%% *}"
		_pkg="${_line#* }"; _pkg="${_pkg%% *}"
		[[ -z $_name || -z $_pkg || $_pkg = "$_line" ]] && continue
		_nodata=0
		case $_name in
		\!*) _name="${_name#!}"; _nodata=1 ;;
		！*) _name="${_name#！}"; _nodata=1 ;;
		esac
		_name="$(_backup_path_safe_name "$_name" "$_pkg")"
		_json="$(_appdetails_bundle_remote_json_path "$_name")"
		if [[ ! -s $_json ]]; then
			_speed_debug_log "REMOTE_FAST_SKIP_APP_MISS app=$_name package=$_pkg reason=remote_json_missing"
			continue
		fi
		# r184: r170/r171 起遠端 per-app wrapper 已改成本地下載後重建，
		# 遠端 fast-skip 不能再依賴 recover/backup/upload.sh 是否存在。
		# 只要 app_details.json 與 payload 檔案都完整，仍可整體跳過。
		if [[ -s $TMPDIR/.listver_changed ]] && awk -v p="$_pkg" '$0==p{f=1;exit} END{exit f?0:1}' "$TMPDIR/.listver_changed" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}; then
			_speed_debug_log "REMOTE_FAST_SKIP_APP_MISS app=$_name package=$_pkg reason=version_changed_prescan"
			continue
		fi
		eval "_cv=\${_pv_${_pkg//[!a-zA-Z0-9]/_}}"
		if [[ -z $_cv ]]; then
			_speed_debug_log "REMOTE_FAST_SKIP_APP_MISS app=$_name package=$_pkg reason=current_version_missing"
			continue
		fi
		_rv="$(_appdetails_get_entry_apk_version "$_json" "$_name" | tr -d ' 	
')"
		if [[ -z $_rv || $_rv != "$_cv" ]]; then
			_speed_debug_log "REMOTE_FAST_SKIP_APP_MISS app=$_name package=$_pkg reason=apk_version_mismatch local=$_cv remote=${_rv:-empty}"
			continue
		fi
		if ! _remote_filelist_has_any_rel "$_name/apk.tar.zst" "$_name/apk.tar"; then
			_speed_debug_log "REMOTE_FAST_SKIP_APP_MISS app=$_name package=$_pkg reason=apk_payload_missing"
			continue
		fi
		_ok=1
		if [[ $Backup_Mode = true && $_nodata != 1 ]]; then
			if [[ $Backup_obb_data = true && $_pkg != bin.mt.plus ]]; then
				for _entry in data obb media; do
					_remote_fast_skip_entry_ok "$_name" "$_pkg" "$_entry" "$_json" || _ok=0
				done
			fi
			if [[ $Backup_user_data = true && $_pkg != bin.mt.plus ]]; then
				for _entry in user user_de; do
					_remote_fast_skip_entry_ok "$_name" "$_pkg" "$_entry" "$_json" || _ok=0
				done
			fi
		fi
		if [[ $_ok = 1 ]]; then
			_speed_debug_log "REMOTE_FAST_SKIP_APP_OK app=$_name package=$_pkg reason=all_entries_ok"
			echo "$_name" >> "$_map"
		else
			_speed_debug_log "REMOTE_FAST_SKIP_APP_MISS app=$_name package=$_pkg reason=entry_mismatch"
		fi
	done <<EOF_FAST_SKIP
$txt
EOF_FAST_SKIP
	_eventwait_output_files_stable_ms remote_fast_skip_map_ready 50 1200 "$_map" "$(_remote_payload_missing_map_file)" >/dev/null 2>&1 || true
	_speed_debug_log "REMOTE_FAST_SKIP_PRESCAN_OK rows=$(grep -vc '^$' "$_map" 2>/dev/null) mode=r459"
}

_remote_app_fast_skip_ok() {
	local _name="$1"
	[[ $remote_stream = 1 ]] || return 1
	[[ -f $TMPDIR/.remote_fast_skip_ok ]] || return 1
	awk -v n="$_name" '$0==n{f=1;exit} END{exit f?0:1}' "$TMPDIR/.remote_fast_skip_ok" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
}

_stream_fast_skip_collapse_applist() {
	# r31: r30 已能判定整個 app 無變化，但仍逐 app 進 UI/notify/progress，23 個全跳過也會累積數秒。
	# 這裡把 fast prescan 命中的 app 先從主迴圈折疊掉，只留真正需要檢查/備份的 app 進原流程。
	[[ $remote_stream = 1 && -n $remote_type ]] || return 0
	[[ -f ${0%/*}/app_details.json ]] && return 0
	[[ -s $TMPDIR/.remote_fast_skip_ok ]] || return 0
	[[ -n $txt ]] || return 0

	local _keep="$TMPDIR/.fast_skip_keep_$$"
	local _skip="$TMPDIR/.fast_skip_skip_$$"
	local _skip2="$TMPDIR/.fast_skip_skip2_$$"
	local _line _name _pkg _skip_count _keep_count _mark_count _old_r _bf

	: > "$_keep"
	: > "$_skip"
	while IFS= read -r _line; do
		case $_line in ''|\#*|＃*)
			[ -n "$_line" ] && echo "$_line" >> "$_keep"
			continue
			;;
		esac
		_name="${_line%% *}"
		_pkg="${_line#* }"; _pkg="${_pkg%% *}"
		case $_name in
		\!*) _name="${_name#!}" ;;
		！*) _name="${_name#！}" ;;
		esac
		_name="$(_backup_path_safe_name "$_name" "$_pkg")"
		if [[ -n $_name && -n $_pkg && $_pkg != "$_line" ]] && _remote_app_fast_skip_ok "$_name"; then
			echo "$_line" >> "$_skip"
		else
			echo "$_line" >> "$_keep"
		fi
	done <<EOF_STREAM_FAST_SKIP_COLLAPSE
$txt
EOF_STREAM_FAST_SKIP_COLLAPSE

	_skip_count="$(grep -vc '^$' "$_skip" 2>/dev/null)"
	_keep_count="$(grep -vc '^$' "$_keep" 2>/dev/null)"
	case $_skip_count in ''|*[!0-9]*) _skip_count=0 ;; esac
	case $_keep_count in ''|*[!0-9]*) _keep_count=0 ;; esac
	[[ $_skip_count -gt 0 ]] || { rm -f "$_keep" "$_skip" "$_skip2" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}; return 0; }

	# r34: 若全部都是 fast-skip，允許全數折疊；後續 wifi/summary/remote_cleanup 已可在 r=0 下完成。
	# 不再保留最後 1 個 app 進主迴圈，避免「全無變化」仍多一次 UI/notify/quiesce 成本。

	_mark_count=0
	while IFS= read -r _line; do
		[[ -z $_line ]] && continue
		_name="${_line%% *}"
		_pkg="${_line#* }"; _pkg="${_pkg%% *}"
		case $_name in
		\!*) _name="${_name#!}" ;;
		！*) _name="${_name#！}" ;;
		esac
		[[ -z $_name || -z $_pkg || $_pkg = "$_line" ]] && continue
		_bf="$Backup/$_name"
		[[ $remote_stream = 1 && -n $remote_type ]] && _bf="$TMPDIR/.stream_stage/$_name"
		if ! awk -v p="$_pkg" '$2==p{f=1} END{exit !f}' "$TMPDIR/.backup_done" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}; then
			echo "${_bf##*/} $_pkg" >> "$TMPDIR/.backup_done"
		fi
		osj="$((osj + 1))"
		_mark_count="$((_mark_count + 1))"
		_speed_debug_log "STREAM_APP_FAST_SKIP_UNCHANGED app=$_name package=$_pkg source=fast_prescan_batch"
	done < "$_skip"

	_old_r="$r"
	txt="$(cat "$_keep" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null})"
	r="$_keep_count"
	i=1
	_speed_debug_log "STREAM_APP_FAST_SKIP_BATCH_COLLAPSE skipped=$_mark_count remain=$r original=$_old_r"
	if [[ $r = 0 ]]; then
		: > "$TMPDIR/.stream_all_apps_fast_skipped" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
		_speed_debug_log "STREAM_APP_FAST_SKIP_ALL_APPS skipped=$_mark_count original=$_old_r"
	fi
	echoRgb "遠端無變化應用 $_mark_count 個，已批量快速跳過；剩餘 $r 個進一步檢查" "2"
	notification_progress "101" "$_old_r" "$_mark_count" "已快速跳過 $_mark_count/$_old_r 個無變化應用"
	rm -f "$_keep" "$_skip" "$_skip2" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
}

_local_fast_skip_appstate_ok() {
	local _name="$1" _pkg="$2" _json="$3"
	local _state_raw_file _state_file _old_file _old_cmp_file _rc
	[[ -s $_json && -s $TMPDIR/.pkg_appstate ]] || return 1
	_state_raw_file="$TMPDIR/.local_fast_appstate_raw_${$}_$RANDOM.json"
	_state_file="$TMPDIR/.local_fast_appstate_new_${$}_$RANDOM.json"
	_old_file="$TMPDIR/.local_fast_appstate_old_${$}_$RANDOM.json"
	_old_cmp_file="$TMPDIR/.local_fast_appstate_old_cmp_${$}_$RANDOM.json"
	rm -f "$_state_raw_file" "$_state_file" "$_old_file" "$_old_cmp_file" 2>/dev/null
	if ! _kv_file_get_to_file "$TMPDIR/.pkg_appstate" "$_pkg" "$_state_raw_file" || [[ ! -s $_state_raw_file ]]; then
		rm -f "$_state_raw_file" "$_state_file" "$_old_file" "$_old_cmp_file" 2>/dev/null
		return 1
	fi
	if ! _appstate_snapshot_persistable_ok "$_state_raw_file" || ! _appstate_persist_compact < "$_state_raw_file" > "$_state_file" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}; then
		rm -f "$_state_raw_file" "$_state_file" "$_old_file" "$_old_cmp_file" 2>/dev/null
		return 1
	fi
	if ! _appstate_snapshot_persistable_ok "$_state_file"; then
		rm -f "$_state_raw_file" "$_state_file" "$_old_file" "$_old_cmp_file" 2>/dev/null
		return 1
	fi
	app_details_has_key "$_json" "$_name" "app_state" || { rm -f "$_state_raw_file" "$_state_file" "$_old_file" "$_old_cmp_file" 2>/dev/null; return 1; }
	_appdetails_get_entry_app_state_file "$_json" "$_name" "$_old_file" || printf '%s\n' null > "$_old_file"
	if _appstate_snapshot_persistable_ok "$_old_file" && _appstate_persist_compact_file "$_old_file" "$_old_cmp_file"; then
		:
	else
		cat "$_old_file" > "$_old_cmp_file" 2>/dev/null || printf '%s\n' null > "$_old_cmp_file"
	fi
	cmp -s "$_old_cmp_file" "$_state_file" 2>/dev/null
	_rc=$?
	rm -f "$_state_raw_file" "$_state_file" "$_old_file" "$_old_cmp_file" 2>/dev/null
	return $_rc
}

_local_fast_skip_entry_ok() {
	local _name="$1" _pkg="$2" _entry="$3" _json="$4" _data_path _cur _old
	case $_entry in
	user) _data_path="$path2/$_pkg" ;;
	user_de) _data_path="$path3/$_pkg" ;;
	data|obb|media) _data_path="$path/$_entry/$_pkg" ;;
	*) return 1 ;;
	esac
	# 路徑不存在時既有 Backup_data 也不會產生 tar，視為可整體 fast-skip。
	[[ -d $_data_path ]] || return 0
	_dir_size "$_pkg" "$_entry" "$_data_path"; _cur="$_DIR_SIZE_RET"
	case $_cur in ''|*[!0-9]*) return 1 ;; esac
	# <1KB 依既有語義不記錄 payload、不產生 tar。
	[[ ${#_cur} -lt 4 ]] && return 0
	_old="$(_appdetails_get_entry_size "$_json" "$_entry")"
	[[ -n $_old && $_old != null && $_old = "$_cur" ]] || return 1
	_archive_exists "$Backup/$_name/$_entry" || return 1
	return 0
}

prepare_local_fast_skip_map() {
	local _map="$TMPDIR/.local_fast_skip_ok"
	: > "$_map"
	# 只針對純本地備份；遠端非流式/流式仍需考慮遠端缺檔與上傳語義。
	[[ -z $remote_type && $remote_stream != 1 ]] || return 0
	[[ -f ${0%/*}/app_details.json ]] && return 0
	[[ -n $txt && -n $Backup ]] || return 0
	local _line _name _raw_name _pkg _json _cv _lv _nodata _ok _entry _black_hit
	while IFS= read -r _line; do
		case $_line in ''|\#*|＃*) continue ;; esac
		_raw_name="${_line%% *}"
		_name="$_raw_name"
		_pkg="${_line#* }"; _pkg="${_pkg%% *}"
		[[ -z $_name || -z $_pkg || $_pkg = "$_line" ]] && continue
		_nodata=0
		case $_name in
		\!*) _name="${_name#!}"; _nodata=1 ;;
		！*) _name="${_name#！}"; _nodata=1 ;;
		esac
		_name="$(_backup_path_safe_name "$_name" "$_pkg")"
		# 黑名單整個不備份時交回原流程；黑名單只跳 data 時仍可 fast-skip APK。
		_black_hit=0
		if [[ -n $blacklist ]]; then
			printf '%s\n' "$blacklist" | awk -v p="$_pkg" '$0==p{f=1} END{exit !f}' 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} && _black_hit=1
		fi
		if [[ $_black_hit = 1 ]]; then
			[[ $blacklist_mode = true ]] && continue
			_nodata=1
		fi
		_json="$Backup/$_name/app_details.json"
		[[ -s $_json ]] || continue
		_archive_exists "$Backup/$_name/apk" || continue
		eval "_cv=\${_pv_${_pkg//[!a-zA-Z0-9]/_}}"
		[[ -n $_cv ]] || continue
		_lv="$(_appdetails_get_entry_apk_version "$_json" "$_name" | tr -d ' \t\r\n')"
		[[ -n $_lv && $_lv = "$_cv" ]] || continue
		# user 會同步 metadata/AppState；若 app_state 漂移，不能整體跳過。
		if [[ $Backup_Mode = true && $_nodata != 1 && $Backup_user_data = true && $_pkg != bin.mt.plus ]]; then
			_local_fast_skip_appstate_ok "$_name" "$_pkg" "$_json" || continue
		fi
		_ok=1
		if [[ $Backup_Mode = true && $_nodata != 1 ]]; then
			if [[ $Backup_obb_data = true && $_pkg != bin.mt.plus ]]; then
				for _entry in data obb media; do
					_local_fast_skip_entry_ok "$_name" "$_pkg" "$_entry" "$_json" || _ok=0
				done
			fi
			if [[ $Backup_user_data = true && $_pkg != bin.mt.plus ]]; then
				for _entry in user user_de; do
					_local_fast_skip_entry_ok "$_name" "$_pkg" "$_entry" "$_json" || _ok=0
				done
			fi
		fi
		[[ $_ok = 1 ]] && echo "$_name" >> "$_map"
	done <<EOF_LOCAL_FAST_SKIP
$txt
EOF_LOCAL_FAST_SKIP
	_eventwait_output_file_stable_ms "$_map" local_fast_skip_map_ready 50 1200 >/dev/null 2>&1 || true
	_speed_debug_log "LOCAL_FAST_SKIP_PRESCAN_OK rows=$(grep -vc '^$' "$_map" 2>/dev/null) mode=r459"
}

_local_app_fast_skip_ok() {
	local _name="$1"
	[[ -z $remote_type && $remote_stream != 1 ]] || return 1
	[[ -f $TMPDIR/.local_fast_skip_ok ]] || return 1
	awk -v n="$_name" '$0==n{f=1;exit} END{exit f?0:1}' "$TMPDIR/.local_fast_skip_ok" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
}

_local_fast_skip_collapse_applist() {
	# r33: 純本地無變化 App 也在主迴圈前折疊，避免逐 App UI/notify/progress 成本。
	[[ -z $remote_type && $remote_stream != 1 ]] || return 0
	[[ -f ${0%/*}/app_details.json ]] && return 0
	[[ -s $TMPDIR/.local_fast_skip_ok ]] || return 0
	[[ -n $txt ]] || return 0

	local _keep="$TMPDIR/.fast_skip_keep_$$"
	local _skip="$TMPDIR/.fast_skip_skip_$$"
	local _skip2="$TMPDIR/.fast_skip_skip2_$$"
	local _line _name _pkg _skip_count _keep_count _mark_count _old_r _bf
	: > "$_keep"
	: > "$_skip"
	while IFS= read -r _line; do
		case $_line in ''|\#*|＃*) [ -n "$_line" ] && echo "$_line" >> "$_keep"; continue ;; esac
		_name="${_line%% *}"
		_pkg="${_line#* }"; _pkg="${_pkg%% *}"
		case $_name in
		\!*) _name="${_name#!}" ;;
		！*) _name="${_name#！}" ;;
		esac
		_name="$(_backup_path_safe_name "$_name" "$_pkg")"
		if [[ -n $_name && -n $_pkg && $_pkg != "$_line" ]] && _local_app_fast_skip_ok "$_name"; then
			echo "$_line" >> "$_skip"
		else
			echo "$_line" >> "$_keep"
		fi
	done <<EOF_LOCAL_FAST_SKIP_COLLAPSE
$txt
EOF_LOCAL_FAST_SKIP_COLLAPSE
	_skip_count="$(grep -vc '^$' "$_skip" 2>/dev/null)"
	_keep_count="$(grep -vc '^$' "$_keep" 2>/dev/null)"
	case $_skip_count in ''|*[!0-9]*) _skip_count=0 ;; esac
	case $_keep_count in ''|*[!0-9]*) _keep_count=0 ;; esac
	[[ $_skip_count -gt 0 ]] || { rm -f "$_keep" "$_skip" "$_skip2" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}; return 0; }
	# r34: 若全部都是 local fast-skip，也允許全數折疊；不再保留最後 1 個 app 進主迴圈。
	_mark_count=0
	while IFS= read -r _line; do
		[[ -z $_line ]] && continue
		_name="${_line%% *}"
		_pkg="${_line#* }"; _pkg="${_pkg%% *}"
		case $_name in
		\!*) _name="${_name#!}" ;;
		！*) _name="${_name#！}" ;;
		esac
		[[ -z $_name || -z $_pkg || $_pkg = "$_line" ]] && continue
		_bf="$Backup/$_name"
		if ! awk -v p="$_pkg" '$2==p{f=1} END{exit !f}' "$TMPDIR/.backup_done" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}; then
			echo "${_bf##*/} $_pkg" >> "$TMPDIR/.backup_done"
		fi
		osj="$((osj + 1))"
		_mark_count="$((_mark_count + 1))"
		_speed_debug_log "LOCAL_APP_FAST_SKIP_UNCHANGED app=$_name package=$_pkg source=local_fast_prescan_batch"
	done < "$_skip"
	_old_r="$r"
	txt="$(cat "$_keep" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null})"
	r="$_keep_count"
	i=1
	_speed_debug_log "LOCAL_FAST_SKIP_BATCH_COLLAPSE skipped=$_mark_count remain=$r original=$_old_r"
	echoRgb "本地無變化應用 $_mark_count 個，已批量快速跳過；剩餘 $r 個進一步檢查" "2"
	notification_progress "101" "$_old_r" "$_mark_count" "已快速跳過 $_mark_count/$_old_r 個本地無變化應用"
	rm -f "$_keep" "$_skip" "$_skip2" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
}


# 480/r41: 已卸載 App 的本機孤兒備份清理。
# 原則：不新增 conf；只在批量本機/非流式備份完成後發現孤兒才詢問；不碰遠端。
# 判定來源：備份資料夾 app_details.json 的 PackageName / app_state.packageName 與目前 user 已安裝列表比對。
_backup_orphan_pkg_installed() {
	local _pkg="$1"
	[[ -n $_pkg ]] || return 1
	[[ -s $TMPDIR/.installed_pkgs ]] || prepare_installed_pkgs_map || return 2
	awk -v p="$_pkg" '$0==p{f=1} END{exit !f}' "$TMPDIR/.installed_pkgs" 2>/dev/null
}

# 481/r42: 共用已卸載 App 備份清理引擎。
# 呼叫者：1) 備份完成後清理 $Backup  2) 恢復資料夾「重新生成應用列表」清理 $MODDIR
# 第 5 參數可傳入 hint 檔，格式：name<TAB>pkg<TAB>dir，用於沒有 app_details.json 但已由 apk probe 解析出的舊備份。
_orphan_backup_cleanup_dir() {
	local _base="$1" _applist="$2" _context="${3:-local}" _skip_bg="${4:-1}" _hint="${5:-}"
	[[ -d $_base ]] || return 0
	if [[ $_skip_bg = 1 ]]; then
		case "${background_execution:-0}" in
			1|true|TRUE|True)
				_speed_debug_log "ORPHAN_BACKUP_CLEANUP_SKIP context=$_context reason=background_execution base=$_base"
				return 0
				;;
		esac
	fi
	if ! prepare_installed_pkgs_map; then
		_speed_debug_log "ORPHAN_BACKUP_CLEANUP_SKIP context=$_context reason=installed_map_unavailable base=$_base"
		return 0
	fi
	local _list="$TMPDIR/.orphan_backup_list_$$" _pkgs="$TMPDIR/.orphan_backup_pkgs_$$" _seen="$TMPDIR/.orphan_backup_seen_$$"
	local _report="${SPEED_DEBUG_RUN_DIR:-/data/speed_debug}/orphan_backup_cleanup.log"
	local _dir _name _json _pkg _cnt _tmp _removed _failed _key
	: > "$_list"
	: > "$_pkgs"
	: > "$_seen"
	find "$_base" -mindepth 1 -maxdepth 1 -type d 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} | sort | while read -r _dir; do
		_name="${_dir##*/}"
		case $_name in
			''|tools|wifi|Media|log|.trash_orphan_*|.*) continue ;;
		esac
		_json="$_dir/app_details.json"
		[[ -s $_json ]] || continue
		_pkg="$(_appdetails_get_first_pkg "$_json" | tr -d ' \t\r\n')"
		[[ -n $_pkg ]] || continue
		_backup_orphan_pkg_installed "$_pkg" && continue
		printf '%s\t%s\t%s\n' "$_name" "$_pkg" "$_dir" >> "$_list"
		printf '%s\n' "$_pkg" >> "$_pkgs"
		printf '%s\t%s\n' "$_pkg" "$_dir" >> "$_seen"
	done
	# 恢復資料夾重新生成 appList 時，舊備份可能缺 app_details.json；用 apk probe 得到的提示補進同一套清理流程。
	if [[ -n $_hint && -s $_hint ]]; then
		while IFS='	' read -r _name _pkg _dir; do
			[[ -n $_name && -n $_pkg && -n $_dir ]] || continue
			_backup_orphan_pkg_installed "$_pkg" && continue
			_key="$(printf '%s\t%s\n' "$_pkg" "$_dir")"
			grep -Fqx "$_key" "$_seen" 2>/dev/null && continue
			printf '%s\t%s\t%s\n' "$_name" "$_pkg" "$_dir" >> "$_list"
			printf '%s\n' "$_pkg" >> "$_pkgs"
			printf '%s\n' "$_key" >> "$_seen"
		done < "$_hint"
	fi
	_cnt="$(grep -vc '^$' "$_list" 2>/dev/null)"
	case $_cnt in ''|*[!0-9]*) _cnt=0 ;; esac
	[[ $_cnt -gt 0 ]] || { rm -f "$_list" "$_pkgs" "$_seen" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}; return 0; }
	{
		echo "===== ORPHAN_BACKUP_SCAN $(date '+%Y-%m-%d %H:%M:%S') ====="
		echo "context=$_context"
		echo "base=$_base"
		echo "count=$_cnt"
		while IFS='	' read -r _name _pkg _dir; do
			[[ -n $_name && -n $_pkg ]] || continue
			echo "orphan app=$_name package=$_pkg dir=$_dir"
		done < "$_list"
	} >> "$_report" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	_speed_debug_log "ORPHAN_BACKUP_SCAN context=$_context count=$_cnt base=$_base report=$_report"
	echoRgb "偵測到 $_cnt 個已卸載 App 的本機備份孤兒項:" "2"
	while IFS='	' read -r _name _pkg _dir; do
		[[ -n $_name && -n $_pkg ]] || continue
		echoRgb "$_name [$_pkg]" "2"
	done < "$_list"
	if ! ask_yn "是否清理這些已卸載 App 的本機備份?" "清理" "保留"; then
		_speed_debug_log "ORPHAN_BACKUP_CLEANUP_KEEP context=$_context count=$_cnt"
		rm -f "$_list" "$_pkgs" "$_seen" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
		return 0
	fi
	if ! ask_yn "二次確認：將刪除上述備份資料夾並從 appList.txt 移除" "確認刪除" "取消"; then
		_speed_debug_log "ORPHAN_BACKUP_CLEANUP_CANCEL context=$_context count=$_cnt"
		rm -f "$_list" "$_pkgs" "$_seen" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
		return 0
	fi
	_removed=0
	_failed=0
	while IFS='	' read -r _name _pkg _dir; do
		[[ -n $_name && -n $_pkg && -n $_dir ]] || continue
		case $_dir in
			"$_base"/*) ;;
			*) _speed_debug_log "ORPHAN_BACKUP_DELETE_SKIP_UNSAFE context=$_context app=$_name package=$_pkg dir=$_dir"; _failed=$((_failed+1)); continue ;;
		esac
		case $_dir in
			"$_base/tools"|"$_base/wifi"|"$_base/Media"|"$_base/log") _failed=$((_failed+1)); continue ;;
		esac
		if rm -rf "$_dir" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}; then
			_removed=$((_removed+1))
			echoRgb "已刪除孤兒備份: $_name [$_pkg]" "1"
			_speed_debug_log "ORPHAN_BACKUP_DELETE_OK context=$_context app=$_name package=$_pkg dir=$_dir"
		else
			_failed=$((_failed+1))
			echoRgb "刪除孤兒備份失敗: $_name [$_pkg]" "0"
			_speed_debug_log "ORPHAN_BACKUP_DELETE_FAIL context=$_context app=$_name package=$_pkg dir=$_dir"
		fi
	done < "$_list"
	# 同步移除 appList.txt 裡對應包名；保留其他註解與清單順序，使用 cat 覆蓋避免 mv 在部分 FUSE 場景失敗。
	if [[ -f $_applist && -s $_pkgs ]]; then
		_tmp="$TMPDIR/.orphan_backup_applist_$$"
		awk 'NR==FNR{drop[$1]=1; next} {p=$2; if (p in drop) next; print}' "$_pkgs" "$_applist" > "$_tmp" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} && cat "$_tmp" > "$_applist"
		rm -f "$_tmp" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	fi
	{
		echo "delete_removed=$_removed"
		echo "delete_failed=$_failed"
		echo "appList=$_applist"
	} >> "$_report" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	_speed_debug_log "ORPHAN_BACKUP_CLEANUP_DONE context=$_context removed=$_removed failed=$_failed appList=$_applist"
	echoRgb "孤兒備份清理完成: 已刪除 $_removed 個，失敗 $_failed 個" "1"
	rm -f "$_list" "$_pkgs" "$_seen" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
}

_backup_orphan_cleanup_local() {
	[[ -f ${0%/*}/app_details.json ]] && return 0
	[[ $remote_stream = 1 ]] && return 0
	[[ -d $Backup ]] || return 0
	_orphan_backup_cleanup_dir "$Backup" "$txt_path2" "backup_after_local" 1
}

_remote_orphan_rel_safe() {
	local _rel="$1"
	[[ -n $_rel ]] || return 1
	case $_rel in
		/*|*../*|../*|*'"'*|*';'*|*'!'*|*$'\n'*|*$'\r'*) return 1 ;;
	esac
	return 0
}

_remote_orphan_webdav_delete_dir() {
	local _app="$1" _subdir _base _rel _err _rc _http
	_remote_orphan_rel_safe "$_app" || return 1
	if _remote_netwatch_mark_remote_fatal "remote_orphan_webdav_delete_enter" "$_app"; then
		_speed_debug_log "REMOTE_ORPHAN_WEBDAV_DELETE_SKIP reason=remote_netwatch_changed app=$_app"
		return 1
	fi
	_subdir="${_BACKUP_DIRNAME_CACHED:-$(get_backup_dirname)}"
	_base="${remote_url%/}"
	_rel="$_subdir/$_app"
	_err="$TMPDIR/.remote_orphan_webdav_delete_${$}_$RANDOM.err"
	_webdav_daemon_ensure || { rm -f "$_err" 2>/dev/null; return 1; }
	_webdav_dex deleterel "$remote_user" "$remote_pass" "$_base" "$_rel" 2>"$_err"
	_rc=$?
	if [[ $_rc != 0 ]]; then
		_remote_netwatch_mark_remote_fatal "remote_orphan_webdav_delete_fail" "$_app" >/dev/null 2>&1 || true
	fi
	_http="${_WEBDAV_HTTP_CODE:-0}"
	remote_raw_log "remote_orphan_cleanup.log" "WEBDAV_DELETE_DIR app=$_app rel=$_rel rc=$_rc http=$_http"
	remote_raw_cat "remote_orphan_cleanup.log" "$_err" "[WEBDAV_DELETE_DIR stderr app=$_app rel=$_rel]"
	rm -f "$_err" 2>/dev/null
	case "$_rc:$_http" in
		0:2[0-9][0-9]|*:404) return 0 ;;
	esac
	return 1
}

_remote_orphan_smb_delete_dir() {
	local _app="$1" _subdir _base _files _dirs _cmd _out _rc _rel _dir _path _bs
	_remote_orphan_rel_safe "$_app" || return 1
	if _remote_netwatch_mark_remote_fatal "remote_orphan_smb_delete_enter" "$_app"; then
		_speed_debug_log "REMOTE_ORPHAN_SMB_DELETE_SKIP reason=remote_netwatch_changed app=$_app"
		return 1
	fi
	_smb_session_prepare 300 1 || return 1
	_files="$TMPDIR/.remote_orphan_files_${$}_$RANDOM"
	_dirs="$TMPDIR/.remote_orphan_dirs_${$}_$RANDOM"
	_cmd="$TMPDIR/.remote_orphan_cmd_${$}_$RANDOM"
	: > "$_files"; : > "$_dirs"; : > "$_cmd"
	_subdir="${_BACKUP_DIRNAME_CACHED:-$(get_backup_dirname)}"
	if _remote_netwatch_mark_remote_fatal "remote_orphan_smb_before_list" "$_app"; then
		rm -f "$_files" "$_dirs" "$_cmd" 2>/dev/null
		return 1
	fi
	remote_list_files "$_subdir/$_app" > "$_files" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	_base="$SMB_SESSION_BASE"
	while IFS= read -r _rel; do
		[[ -n $_rel ]] || continue
		_remote_orphan_rel_safe "$_rel" || { _speed_debug_log "REMOTE_ORPHAN_SMB_DELETE_SKIP_UNSAFE_FILE app=$_app rel=$_rel"; continue; }
		_path="$(_smb_join_rel "$SMB_SESSION_BASE" "$_app/$_rel")" || continue
		_bs="${_path//\//\\}"
		printf 'del "%s"\n' "$_bs" >> "$_cmd"
		_dir="$_app/${_rel%/*}"
		[[ $_dir = "$_app/$_rel" || $_dir = "$_app/." || $_dir = "$_app/" ]] && continue
		while [[ -n $_dir && $_dir != "." && $_dir != "/" ]]; do
			printf '%s\n' "$_dir" >> "$_dirs"
			case $_dir in */*) _dir="${_dir%/*}" ;; *) break ;; esac
		done
	done < "$_files"
	# rmdir must be deepest-first; include root app dir last.
	if [[ -s $_dirs ]]; then
		awk '!seen[$0]++ {print length($0) "\t" $0}' "$_dirs" | sort -rn | cut -f2- | while IFS= read -r _dir; do
			_remote_orphan_rel_safe "$_dir" || continue
			_path="$(_smb_join_rel "$SMB_SESSION_BASE" "$_dir")" || continue
			_bs="${_path//\//\\}"
			printf 'rmdir "%s"\n' "$_bs"
		done >> "$_cmd"
	fi
	_path="$(_smb_join_rel "$SMB_SESSION_BASE" "$_app")" || { rm -f "$_files" "$_dirs" "$_cmd" 2>/dev/null; return 1; }
	_bs="${_path//\//\\}"
	printf 'rmdir "%s"\nexit\n' "$_bs" >> "$_cmd"
	if _remote_netwatch_mark_remote_fatal "remote_orphan_smb_before_delete" "$_app"; then
		rm -f "$_files" "$_dirs" "$_cmd" 2>/dev/null
		return 1
	fi
	_out="$(_smb_cmd_common < "$_cmd" 2>&1)"
	_rc=$?
	if [[ $_rc != 0 ]]; then
		_remote_netwatch_mark_remote_fatal "remote_orphan_smb_delete_fail" "$_app" >/dev/null 2>&1 || true
	fi
	remote_raw_log "remote_orphan_cleanup.log" "SMB_DELETE_DIR app=$_app rc=$_rc base=${SMB_SESSION_BASE:-/}"
	printf '%s\n' "$_out" | _smb_output_filter_noise >> "${SPEED_DEBUG_RUN_DIR:-/data/speed_debug}/remote_orphan_cleanup.log" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	rm -f "$_files" "$_dirs" "$_cmd" 2>/dev/null
	[[ $_rc = 0 ]] && ! _smb_output_has_error "$_out"
}

_remote_orphan_delete_dir() {
	case "$remote_type" in
		webdav) _remote_orphan_webdav_delete_dir "$1" ;;
		smb) _remote_orphan_smb_delete_dir "$1" ;;
		*) return 1 ;;
	esac
}

_remote_orphan_cleanup_stream() {
	# r50: 遠端真流式備份完成後，清理已卸載 App 的遠端孤兒備份。
	# r242: 備份主流程不再呼叫；只允許由「刪除遠端已卸載應用」明確入口手動觸發。
	# 第 1 參數 manual/menu/maintenance 代表手動入口；其他值保留舊呼叫相容但不主動掛入備份流程。
	local _remote_orphan_trigger="${1:-auto}" _remote_orphan_manual=0
	case "$_remote_orphan_trigger" in manual|menu|maintenance) _remote_orphan_manual=1 ;; esac
	[[ -n $remote_type ]] || { echoRgb "未設定遠端類型，無法刪除遠端已卸載應用" "0"; return 0; }
	if [[ $_remote_orphan_manual != 1 ]]; then
		[[ $remote_stream = 1 ]] || return 0
		[[ -f ${0%/*}/app_details.json ]] && return 0
	fi
	case "$remote_type" in webdav|smb) ;; *) echoRgb "目前遠端類型 $remote_type 不支援刪除遠端已卸載應用" "0"; return 0 ;; esac
	case "${background_execution:-0}" in
		1|true|TRUE|True)
			_speed_debug_log "REMOTE_ORPHAN_CLEANUP_SKIP reason=background_execution"
			return 0
			;;
	esac
	if _remote_stream_fatal_active; then
		_speed_debug_log "REMOTE_ORPHAN_CLEANUP_SKIP reason=remote_stream_fatal $(_remote_stream_fatal_summary)"
		return 0
	fi
	if ! prepare_installed_pkgs_map; then
		_speed_debug_log "REMOTE_ORPHAN_CLEANUP_SKIP reason=installed_map_unavailable"
		return 0
	fi
	local _subdir _rfiles _list _pkgs _seen _report _rel _app _json _pkg _cnt _tmp _removed _failed _cache_hit=0 _stage_hit=0 _remote_get=0 _json_source _scan_total=0 _scan_i=0 _bundle_root _bundle_ready=0 _bundle_jsons _removed_apps
	_subdir="${_BACKUP_DIRNAME_CACHED:-$(get_backup_dirname)}"
	_rfiles="$TMPDIR/.remote_orphan_files_${$}_$RANDOM"
	_list="$TMPDIR/.remote_orphan_list_${$}_$RANDOM"
	_pkgs="$TMPDIR/.remote_orphan_pkgs_${$}_$RANDOM"
	_seen="$TMPDIR/.remote_orphan_seen_${$}_$RANDOM"
	_report="${SPEED_DEBUG_RUN_DIR:-/data/speed_debug}/remote_orphan_cleanup.log"
	_bundle_root="$(_appdetails_bundle_stage_root)"
	_bundle_jsons="$TMPDIR/.remote_orphan_bundle_jsons_${$}_$RANDOM"
	_removed_apps="$TMPDIR/.remote_orphan_removed_apps_${$}_$RANDOM"
	: > "$_rfiles"; : > "$_list"; : > "$_pkgs"; : > "$_seen"; : > "$_removed_apps"
	if _remote_netwatch_mark_remote_fatal "remote_orphan_before_scan" "$_subdir"; then
		_speed_debug_log "REMOTE_ORPHAN_CLEANUP_SKIP reason=remote_netwatch_changed stage=before_scan subdir=$_subdir"
		rm -f "$_rfiles" "$_list" "$_pkgs" "$_seen" "$_bundle_jsons" "$_removed_apps" 2>/dev/null
		return 0
	fi
	remote_list_files "$_subdir" > "$_rfiles" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	if [[ ! -s $_rfiles ]]; then
		_speed_debug_log "REMOTE_ORPHAN_CLEANUP_SKIP reason=remote_filelist_empty subdir=$_subdir"
		if [[ $_remote_orphan_manual = 1 ]]; then
			echoRgb "遠端備份清單為空或未取得任何項目，沒有可刪除的已卸載 App" "0"
		fi
		rm -f "$_rfiles" "$_list" "$_pkgs" "$_seen" "$_bundle_jsons" "$_removed_apps" 2>/dev/null
		return 0
	fi
	# r312: 遠端孤兒掃描只支援 app_details_bundle.tar.zst bundle-only（相容 r358-r366 app_details_bundle.tar）。
	# 舊版逐 App <App>/app_details.json fallback 已移除，避免混用過期模型造成誤判。
	if awk -v b="$(_appdetails_bundle_rel)" -v lb="$(_appdetails_bundle_legacy_rel)" '{rel=$1; base=rel; sub(/^.*\//, "", base); if(base==b || base==lb || rel==b || rel==lb){f=1; exit}} END{exit f?0:1}' "$_rfiles" 2>/dev/null; then
		if _appdetails_bundle_seed_remote_json_cache "$_subdir" "$_bundle_root" >/dev/null 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}; then
			_bundle_ready=1
			_speed_debug_log "REMOTE_ORPHAN_BUNDLE_CACHE_OK subdir=$_subdir root=$_bundle_root mode=r312-bundle-only-strict"
		else
			_speed_debug_log "REMOTE_ORPHAN_BUNDLE_CACHE_FAIL subdir=$_subdir rel=$(_appdetails_bundle_rel) mode=r312-bundle-only-strict"
		fi
	else
		_speed_debug_log "REMOTE_ORPHAN_BUNDLE_REQUIRED_MISSING subdir=$_subdir rel=$(_appdetails_bundle_rel) mode=r312-bundle-only-strict visible=$([[ $_remote_orphan_manual = 1 ]] && echo 1 || echo 0)"
	fi
	if [[ $_bundle_ready != 1 ]]; then
		if [[ $_remote_orphan_manual = 1 ]]; then
			echoRgb "遠端缺少 app_details_bundle.tar.zst，無法可靠判斷已卸載 App，已取消掃描" "0"
			echoRgb "請先用新版重新備份一次，產生 app_details bundle 後再執行清理" "2"
		fi
		rm -f "$_rfiles" "$_list" "$_pkgs" "$_seen" "$_bundle_jsons" "$_removed_apps" 2>/dev/null
		return 0
	fi
	_appdetails_index_paths "$_bundle_root" "$_bundle_jsons" 2 2 1 >/dev/null 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} || true
	_scan_total="$(grep -vc '^$' "$_bundle_jsons" 2>/dev/null)"
	case $_scan_total in ''|*[!0-9]*) _scan_total=0 ;; esac
	[[ $_scan_total -gt 0 ]] && _speedbackup_progress_step 0 "$_scan_total" "正在掃描遠端已卸載應用" "remote_uninstalled_scan" "107"
	while IFS= read -r _json || [[ -n $_json ]]; do
		[[ -s $_json ]] || continue
		_app="${_json%/app_details.json}"; _app="${_app##*/}"
		case $_app in ''|tools|wifi|Media|log|.*) continue ;; esac
		_remote_orphan_rel_safe "$_app" || { _speed_debug_log "REMOTE_ORPHAN_SKIP_UNSAFE_APP app=$_app source=bundle file=$_json"; continue; }
		grep -Fqx "$_app" "$_seen" 2>/dev/null && continue
		printf '%s\n' "$_app" >> "$_seen"
		_scan_i=$((_scan_i + 1))
		[[ $_scan_total -gt 0 ]] && _speedbackup_progress_step "$_scan_i" "$_scan_total" "掃描遠端備份 $_app" "remote_uninstalled_scan" "107"
		if _remote_netwatch_mark_remote_fatal "remote_orphan_scan_app" "$_app"; then
			_speed_debug_log "REMOTE_ORPHAN_SCAN_ABORT reason=remote_netwatch_changed app=$_app source=bundle"
			break
		fi
		_pkg="$(_appdetails_get_first_pkg "$_json" | tr -d ' \t\r\n')"
		[[ -n $_pkg ]] || { _speed_debug_log "REMOTE_ORPHAN_SKIP_NO_PKG app=$_app source=bundle"; continue; }
		_backup_orphan_pkg_installed "$_pkg" && continue
		printf '%s	%s\n' "$_app" "$_pkg" >> "$_list"
		printf '%s\n' "$_pkg" >> "$_pkgs"
	done < "$_bundle_jsons"
	_cnt="$(grep -vc '^$' "$_list" 2>/dev/null)"
	case $_cnt in ''|*[!0-9]*) _cnt=0 ;; esac
	if [[ $_cnt -le 0 ]]; then
		_speed_debug_log "REMOTE_ORPHAN_SCAN count=0 subdir=$_subdir bundle=$_bundle_ready cache_hit=$_cache_hit stage_hit=$_stage_hit remote_get=$_remote_get scanned=$_scan_i total=$_scan_total visible=$([[ $_remote_orphan_manual = 1 ]] && echo 1 || echo 0)"
		if [[ $_remote_orphan_manual = 1 ]]; then
			echoRgb "遠端已卸載 App 掃描完成：未發現可刪除的遠端孤兒備份" "1"
			echoRgb "已掃描 $_scan_i/$_scan_total 個遠端 App 目錄，無需清理" "2"
		fi
		rm -f "$_rfiles" "$_list" "$_pkgs" "$_seen" "$_bundle_jsons" "$_removed_apps" 2>/dev/null
		return 0
	fi
	{
		echo "===== REMOTE_ORPHAN_SCAN $(date '+%Y-%m-%d %H:%M:%S') ====="
		echo "type=$remote_type"
		echo "subdir=$_subdir"
		echo "count=$_cnt"
		while IFS='	' read -r _app _pkg; do
			[[ -n $_app && -n $_pkg ]] && echo "orphan app=$_app package=$_pkg"
		done < "$_list"
	} >> "$_report" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	_speed_debug_log "REMOTE_ORPHAN_SCAN type=$remote_type count=$_cnt subdir=$_subdir report=$_report bundle=$_bundle_ready cache_hit=$_cache_hit stage_hit=$_stage_hit remote_get=$_remote_get scanned=$_scan_i total=$_scan_total"
	echoRgb "偵測到 $_cnt 個已卸載 App 的遠端備份孤兒項:" "2"
	while IFS='	' read -r _app _pkg; do
		[[ -n $_app && -n $_pkg ]] && echoRgb "$_app [$_pkg]" "2"
	done < "$_list"
	if ! ask_yn "是否清理這些已卸載 App 的遠端備份?" "清理" "保留"; then
		_speed_debug_log "REMOTE_ORPHAN_CLEANUP_KEEP count=$_cnt"
		rm -f "$_rfiles" "$_list" "$_pkgs" "$_seen" "$_bundle_jsons" "$_removed_apps" 2>/dev/null
		return 0
	fi
	if ! ask_yn "二次確認：將刪除上述遠端備份資料夾並更新遠端 appList.txt" "確認刪除" "取消"; then
		_speed_debug_log "REMOTE_ORPHAN_CLEANUP_CANCEL count=$_cnt"
		rm -f "$_rfiles" "$_list" "$_pkgs" "$_seen" "$_bundle_jsons" "$_removed_apps" 2>/dev/null
		return 0
	fi
	_removed=0; _failed=0
	if _remote_netwatch_mark_remote_fatal "remote_orphan_before_delete_loop" "$_subdir"; then
		_speed_debug_log "REMOTE_ORPHAN_DELETE_SKIP reason=remote_netwatch_changed subdir=$_subdir"
		rm -f "$_rfiles" "$_list" "$_pkgs" "$_seen" "$_bundle_jsons" "$_removed_apps" 2>/dev/null
		return 0
	fi
	while IFS='	' read -r _app _pkg; do
		[[ -n $_app && -n $_pkg ]] || continue
		if _remote_netwatch_mark_remote_fatal "remote_orphan_delete_app" "$_app"; then
			_speed_debug_log "REMOTE_ORPHAN_DELETE_ABORT reason=remote_netwatch_changed app=$_app"
			_failed=$((_failed + 1))
			break
		fi
		if _remote_orphan_delete_dir "$_app"; then
			_removed=$((_removed + 1))
			printf '%s\n' "$_app" >> "$_removed_apps" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} || true
			echoRgb "已刪除遠端孤兒備份: $_app [$_pkg]" "1"
			_speed_debug_log "REMOTE_ORPHAN_DELETE_OK type=$remote_type app=$_app package=$_pkg"
		else
			_failed=$((_failed + 1))
			echoRgb "刪除遠端孤兒備份失敗: $_app [$_pkg]" "0"
			_speed_debug_log "REMOTE_ORPHAN_DELETE_FAIL type=$remote_type app=$_app package=$_pkg"
		fi
	done < "$_list"
	# r312: bundle-only 遠端刪除 App 目錄後，也要從 app_details_bundle.tar.zst 移除該 App 的 JSON，否則下次掃描會反覆命中同一孤兒。
	if [[ $_bundle_ready = 1 && $_removed -gt 0 && -s $_removed_apps ]]; then
		while IFS= read -r _app || [[ -n $_app ]]; do
			[[ -n $_app ]] || continue
			_remote_orphan_rel_safe "$_app" || continue
			rm -rf "$_bundle_root/$_app" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} || true
		done < "$_removed_apps"
		_appdetails_bundle_mark_dirty "remote-orphan-prune" "bundle" "$_removed"
		if _appdetails_bundle_upload_stream; then
			_speed_debug_log "REMOTE_ORPHAN_BUNDLE_PRUNE_UPLOAD_OK removed=$_removed root=$_bundle_root mode=r312-bundle-only-strict"
		else
			_failed=$((_failed + 1))
			echoRgb "遠端 app_details bundle 更新失敗；孤兒目錄已刪除但 bundle 可能保留舊紀錄" "0"
			_speed_debug_log "REMOTE_ORPHAN_BUNDLE_PRUNE_UPLOAD_FAIL removed=$_removed root=$_bundle_root mode=r312-bundle-only-strict"
		fi
	fi
	# 同步本輪待上傳的 appList；stream_upload_infra 隨後會把它覆寫到遠端。
	if [[ -n ${txt_path2:-} && -f $txt_path2 && -s $_pkgs && $_removed -gt 0 ]]; then
		_tmp="$TMPDIR/.remote_orphan_applist_${$}_$RANDOM"
		awk 'NR==FNR{drop[$1]=1; next} {p=$2; if (p in drop) next; print}' "$_pkgs" "$txt_path2" > "$_tmp" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} && cat "$_tmp" > "$txt_path2"
		rm -f "$_tmp" 2>/dev/null
		_speed_debug_log "REMOTE_ORPHAN_APPLIST_UPDATED path=$txt_path2 removed=$_removed"
	fi
	# r53: 若本輪 remote_stream 全 fast-skip 但同時刪除了遠端孤兒 App 備份，
	# 遠端總大小差異應標示為「孤兒清理」而不是「基礎檔案更新」。
	if [[ $_removed -gt 0 ]]; then
		echo "$_removed" > "$TMPDIR/.remote_orphan_cleanup_removed" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	fi
	{
		echo "delete_removed=$_removed"
		echo "delete_failed=$_failed"
		echo "appList=${txt_path2:-}"
	} >> "$_report" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	_speed_debug_log "REMOTE_ORPHAN_CLEANUP_DONE type=$remote_type removed=$_removed failed=$_failed appList=${txt_path2:-}"
	echoRgb "遠端孤兒備份清理完成: 已刪除 $_removed 個，失敗 $_failed 個" "1"
	rm -f "$_rfiles" "$_list" "$_pkgs" "$_seen" "$_bundle_jsons" "$_removed_apps" 2>/dev/null
}

# r242: 主選單明確入口；不在備份完成後自動掃整個遠端 app_details。
delete_remote_uninstalled_apps() {
	echoRgb "刪除遠端已卸載應用" "3"
	_speed_debug_log "REMOTE_UNINSTALLED_APPS_DELETE_MENU_START remote_type=${remote_type:-} remote_stream=${remote_stream:-}"
	case "${background_execution:-0}" in
		1|true|TRUE|True)
			echoRgb "後台執行不允許刪除遠端已卸載應用，請前台手動執行" "0"
			_speed_debug_log "REMOTE_UNINSTALLED_APPS_DELETE_MENU_SKIP reason=background_execution"
			return 0
			;;
	esac
	if [[ -z ${remote_type:-} ]]; then
		echoRgb "remote_type 未設定，請先配置 WebDAV/SMB 遠端後再執行" "0"
		_speed_debug_log "REMOTE_UNINSTALLED_APPS_DELETE_MENU_SKIP reason=remote_type_empty"
		return 0
	fi
	_remote_orphan_cleanup_stream manual
	_rc=$?
	_speed_debug_log "REMOTE_UNINSTALLED_APPS_DELETE_MENU_DONE rc=$_rc"
	return "$_rc"
}

# 預掃 pkg → version code map (取代 Backup_apk 內每個 app 都 fork pm 的開銷)
# 寫到 $TMPDIR/.pkg_ver 格式: pkg<TAB>versionCode
prepare_pkg_ver_map() {
	: > "$TMPDIR/.pkg_ver" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	appinventory pkgVerMap all 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} >> "$TMPDIR/.pkg_ver"
	if [[ -s "$TMPDIR/.pkg_ver" ]]; then
		_speed_debug_log "APP_INVENTORY_VER_MAP_OK rows=$(wc -l < "$TMPDIR/.pkg_ver" 2>/dev/null | tr -d ' ')"
		return 0
	fi
	_speed_debug_log "APP_INVENTORY_VER_MAP_FAIL strict=1 fallback=off"
	return 1
}

# 預掃 pkg → APK source/split path map (取代備份主迴圈 pm path)。
# 寫到 $TMPDIR/.pkg_apk_paths 格式: pkg<TAB>/data/app/.../base.apk；split APK 同 pkg 多行。
prepare_pkg_apk_path_map() {
	: > "$TMPDIR/.pkg_apk_paths" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	appinventory pkgApkPathMap all 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} >> "$TMPDIR/.pkg_apk_paths"
	if [[ -s "$TMPDIR/.pkg_apk_paths" ]]; then
		_speed_debug_log "APP_INVENTORY_APK_PATH_MAP_OK rows=$(wc -l < "$TMPDIR/.pkg_apk_paths" 2>/dev/null | tr -d ' ')"
		return 0
	fi
	_speed_debug_log "APP_INVENTORY_APK_PATH_MAP_FAIL strict=1 fallback=off"
	return 1
}

_pkg_apk_paths_from_map() {
	local _pkg="$1"
	[[ -n $_pkg && -f $TMPDIR/.pkg_apk_paths ]] || return 1
	awk -v p="$_pkg" -F'	' '$1 == p && $2 != "" {print $2}' "$TMPDIR/.pkg_apk_paths" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
}

get_current_apk_paths() {
	local _pkg="$1" _paths="" _tmp
	[[ -n $_pkg ]] || return 1
	_paths="$(_pkg_apk_paths_from_map "$_pkg")"
	if [[ -z $_paths ]]; then
		_tmp="$TMPDIR/.pkg_apk_paths_refresh_$$"
		: > "$_tmp" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
		appinventory pkgApkPathMap all refresh 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} >> "$_tmp"
		if [[ -s $_tmp ]]; then
			cat "$_tmp" > "$TMPDIR/.pkg_apk_paths" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
			_paths="$(_pkg_apk_paths_from_map "$_pkg")"
		fi
		rm -f "$_tmp" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	fi
	if [[ -z $_paths ]]; then
		_speed_debug_log "APP_APK_PATH_LOOKUP_FAIL pkg=$_pkg source=inventory_map,inventory_refresh fallback=off"
		return 1
	fi
	printf '%s\n' "$_paths"
}
app_details_read() {
	local file="$1" tmpf
	APK_VER=""; PKG_NAME=""; BACKUP_TIME=""
	SIZE_user=""; SIZE_data=""; SIZE_obb=""; SIZE_user_de=""; SIZE_media=""
	[[ ! -f $file ]] && return
	tmpf="$TMPDIR/.app_details_read_$$"
	_appdetails_read_summary "$file" "$tmpf"
	exec 3< "$tmpf"
	read -r APK_VER <&3
	read -r PKG_NAME <&3
	read -r BACKUP_TIME <&3
	read -r SIZE_user <&3
	read -r SIZE_data <&3
	read -r SIZE_obb <&3
	read -r SIZE_user_de <&3
	read -r SIZE_media <&3
	exec 3<&-
	rm -f "$tmpf"
}

# 判斷目前 app_details.json 的指定 entry 是否已存在指定欄位。
# 用途：app_details 被 APK/Size 流程重建後，即使舊值與當前值相同，也必須補寫缺失欄位。
# 回傳：0=欄位存在且不是 null，1=缺失/檔案不存在/JSON異常
app_details_has_key() {
	local _file="$1" _entry="$2" _key="$3"
	[[ -s $_file && -n $_entry && -n $_key ]] || return 1
	_appdetails_has_key "$_file" "$_entry" "$_key"
}

# Chrome 特例: trichromelibrary 會留多個舊版本, 只保留最新一個
# 在 Backup_apk 末尾 (name2=com.android.chrome 時) 呼叫
cleanup_chrome_legacy() {
	local files
	files=$(ls /data/app/*/com.google.android.trichromelibrary_*/base.apk 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null})
	[[ -z $files ]] && return
	local n
	n=$(printf "%s\n" "$files" | awk 'END{print NR}')
	# 多於 1 個 → 按時間刪掉舊的, 只留最新
	if [[ $n -gt 1 ]]; then
		echo "$files" \
			| while read -r f; do
				printf '%s %s\n' "$(stat -c '%Y' "$f" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null})" "$f"
			done \
			| sort -n \
			| head -n -1 \
			| while read -r _ts oldfile; do
				rm -rf "${oldfile%/*/*}" && echo "刪除文件:${oldfile%/*/*}"
			done
	fi
	# 拷貝最新一個到備份目錄
	local kept
	kept=$(ls /data/app/*/com.google.android.trichromelibrary_*/base.apk 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} | head -1)
	[[ -f $kept ]] && cp -r "$kept" "$Backup_folder/nmsl.apk"
}

# 查 app uid。優先使用 AppInventory 預掃 .pkg_uid；必要時只做 Dex 單點補查，不再回退 pm/dumpsys。
# 用法: uid=$(get_app_uid "$pkg")
get_app_uid() {
	local pkg="$1" uid
	[[ -n $pkg ]] || return 0
	if [[ -f $TMPDIR/.pkg_uid ]]; then
		uid=$(awk -v p="$pkg" -F'\t' '$1 == p {print $2; exit}' "$TMPDIR/.pkg_uid")
		[[ -n $uid ]] && { echo "$uid" | grep -Eo '[0-9]+' | head -n 1; return; }
	fi
	uid=$(get_uid "$pkg" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null})
	case $uid in
		''|*[!0-9]*) _speed_debug_log "APP_UID_LOOKUP_FAIL pkg=$pkg source=inventory_map,dex_single" ;;
	esac
	echo "$uid" | grep -Eo '[0-9]+' | head -n 1
}

# 恢復用: 一次抓 Release_data 需要的 Size / keystore / path
# 用法: release_details_read <app_details.json> <entry>
# 設定全域變數: REL_SIZE / REL_KEYSTORE / REL_PATH
release_details_read() {
	local file="$1" entry="$2"
	REL_SIZE=""; REL_KEYSTORE=""; REL_PATH=""
	[[ ! -f $file ]] && return
	local tmpf="$TMPDIR/.rel_jq_$$"
	_appdetails_release_entry_read "$file" "$entry" "$tmpf"
	exec 3< "$tmpf"
	read -r REL_SIZE <&3
	read -r REL_KEYSTORE <&3
	read -r REL_PATH <&3
	exec 3<&-
	rm -f "$tmpf"
}

# 預掃已安裝 package map；r44 起只使用 AppInventory，不再回退 pm list。
# 寫到 $TMPDIR/.installed_pkgs (一行一個 pkg name)
prepare_installed_pkgs_map() {
	: > "$TMPDIR/.installed_pkgs" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	appinventory pkgName all 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} >> "$TMPDIR/.installed_pkgs"
	if [[ -s "$TMPDIR/.installed_pkgs" ]]; then
		_speed_debug_log "APP_INVENTORY_INSTALLED_MAP_OK rows=$(wc -l < "$TMPDIR/.installed_pkgs" 2>/dev/null | tr -d ' ')"
		return 0
	fi
	_speed_debug_log "APP_INVENTORY_INSTALLED_MAP_FAIL strict=1 fallback=off"
	return 1
}

# 計算指定目錄的總大小並輸出可讀字串 (KB/MB/GB)
Calculate_size() {
    #計算出備份大小跟差異性；r308: delta 全程 decimal string safe，不再用 awk a-b。
    filesizee="$(calc_dir_size "$1")"
    local _diff _abs
    _diff="$(_decimal_diff_uint "${filesizee:-0}" "${filesize:-0}")"
    case $_diff in
    -*)
        _abs=${_diff#-}
        NJL="本次備份減少 $(size "$_abs")" ;;
    0)
        NJL="文件大小未改變" ;;
    *)
        NJL="本次備份增加 $(size "$_diff")" ;;
    esac
    _speed_debug_log "LOCAL_TOTAL_AFTER before=${filesize:-0} after=${filesizee:-0} delta=$_diff mode=r309-bigint-safe"
    echoRgb "備份資料夾路徑↓↓↓\n -$1"
    echoRgb "備份資料夾總體大小$(size_with_bytes "$filesizee")"
    echoRgb "$NJL"
}

# 將輸入解析為 bytes。參數可為純數字或檔案路徑。
_size_bytes_value() {
	local _in="$1" _b
	case $_in in
	'' ) _b=0 ;;
	*[!0-9]*) _b="$(stat -c%s "$_in" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null})" ;;
	*) _b="$_in" ;;
	esac
	case $_b in ''|*[!0-9]*) _b=0 ;; esac
	printf '%s\n' "$_b"
}

# 把 bytes 轉成人類可讀格式 (B/KB/MB/GB/TB)，顯示策略對齊 Windows「大小」欄位。
# r270: 單次 awk 完成單位判斷、小數截斷與千分位，避免收尾大小顯示啟動多個 awk。
# 用法: size <bytes 數值> 或 size <檔案路徑> (會 stat 取大小)
_size_format_awk='
function trunc2(v) { return int(v * 100) / 100 }
function human(n, u, v) {
	n += 0
	if (n == 0) return "0 bytes"
	if (n < 1024) return sprintf("%.0f bytes", n)
	if (n < 1048576) { u = 1024; v = trunc2(n / u); return sprintf("%.2f KB", v) }
	if (n < 1073741824) { u = 1048576; v = trunc2(n / u); return sprintf("%.2f MB", v) }
	if (n < 1099511627776) { u = 1073741824; v = trunc2(n / u); return sprintf("%.2f GB", v) }
	u = 1099511627776; v = trunc2(n / u); return sprintf("%.2f TB", v)
}
function commas(n, s, out) {
	s = sprintf("%.0f", n + 0); out = ""
	while (length(s) > 3) { out = "," substr(s, length(s) - 2, 3) out; s = substr(s, 1, length(s) - 3) }
	return s out
}
'

size() {
	local b_size
	b_size="$(_size_bytes_value "$1")"
	awk -v n="$b_size" "${_size_format_awk}BEGIN{print human(n)}"
}

size_with_bytes() {
    local _b _human _commas
    _b="$(_size_bytes_value "$1")"
    _human="$(awk -v n="$_b" "${_size_format_awk}BEGIN{print human(n)}")"
    _commas="$(_decimal_commas_uint "$_b")"
    printf '%s (%s 位元組)\n' "$_human" "$_commas"
}

#分區佔用信息
partition_info() {
	unset Skip
	Occupation_status="$(df -B1 "$(_resolve_real_mount "${1%/*}")" | sed -n 's|% /.*|%|p' | awk '{print $(NF-1)}')"
	Filesize2="$(size "$Filesize")"
	# 流式模式: 數據不落地本機, 本機剩餘空間跟這次備份無關, 不顯示 (避免誤導使用者以為是遠端容量)
	if [[ $remote_stream = 1 ]]; then
		echo " -$2大小:$Filesize2"
	else
		echo " -$2大小:$Filesize2 剩餘大小:$(size "$Occupation_status")"
	fi
	if [[ $remote_stream != 1 && -n $Filesize ]]; then
		if [[ $(_decimal_cmp_uint "$Filesize" "$Occupation_status") = 1 ]]; then
			echoRgb "$2備份大小將超出rom可用大小" "0"
			Skip=1
		fi
	fi
	Occupation_status="$(df -h "$(_resolve_real_mount "${Backup%/*}")" | sed -n 's|% /.*|%|p' | awk '{print $(NF-1),$(NF)}')"
}
_progress_local_storage_suffix() {
	# 若整輪都只是跳過備份，partition_info() 可能未被呼叫；此時仍要即時查一次本地剩餘空間，避免進度列顯示「本地剩餘:使用率:」。
	[[ $remote_stream = 1 ]] && return 0
	local _occ="${Occupation_status:-}" _target
	if [[ -z $_occ ]]; then
		_target="${Backup%/*}"
		[[ -z $_target || $_target = "$Backup" ]] && _target="$MODDIR"
		_occ="$(df -h "$(_resolve_real_mount "$_target")" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} | sed -n 's|% /.*|%|p' | awk '{print $(NF-1),$(NF); exit}')"
	fi
	printf '%s\n' "$_occ" | awk -v pfx="${hx:-本地}" '
		END {
			if ($1 == "" || $2 == "") print " " pfx "剩餘:未知使用率:未知";
			else print " " pfx "剩餘:" $1 "使用率:" $2;
		}'
}
# 取得指定 app 的後台運行 PID (Dex daemon 不可用時的 fallback)
Process_Information() {
	dumpsys activity processes 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} | awk -v key="$1" -v user="$user" '
	function getUserFromUid(uid){return int(uid/100000)}
	# 進程塊起點: ProcessRecord{hash PID:name/uid} → 抓 pid (兼容無獨立 pid= 行的新格式)
	/ProcessRecord\{/ {tmp=$0; sub(/^.*ProcessRecord\{[^ ]+ /,"",tmp); sub(/:.*/,"",tmp); pid=tmp; uid=""; pkg=""; next}
	/^ *user #[0-9]+ uid=/ {if($0 ~ /ISOLATED uid=[0-9]+/){uid="";next} tmp=$0; sub(/^.*uid=/,"",tmp); sub(/ .*/,"",tmp); uid=tmp}
	/packageList=\{/ {tmp=$0; sub(/^.*packageList=\{/,"",tmp); sub(/\}.*/,"",tmp); pkg=tmp; if(pkg!="" && uid!="" && pid!=""){if((key=="" || pkg==key) && (user=="" || getUserFromUid(uid)==user)) print pid}}
	'
}

# foreground 狀態查詢：r226 起優先走 ProcessObserver direct status，失敗才回 AppState daemon。
# 回傳: 0=active=true, 1=active=false, 2=查詢失敗。
_foreground_state_pkg_active() {
	local _pkg="$1" _in _out _active _direct_rc
	[[ -n $_pkg ]] || return 2
	_process_observer_foreground_status "$_pkg" "foreground_state_pkg_active"
	_direct_rc=$?
	case $_direct_rc in
	0) _speed_debug_log "FOREGROUND_STATE_DIRECT_HIT pkg=$_pkg active=true"; return 0 ;;
	1) _speed_debug_log "FOREGROUND_STATE_DIRECT_HIT pkg=$_pkg active=false"; return 1 ;;
	esac
	_in="$TMPDIR/.foreground_state_one_${$}_$RANDOM.in"
	_out="$TMPDIR/.foreground_state_one_${$}_$RANDOM.out"
	printf '%s\n' "$_pkg" > "$_in" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} || return 2
	if _root_appstate_call foregroundStateBatch "$_in" "$_out"; then
		_active="$(_appstate_ndjson_get_foreground_active "$_out" "$_pkg")"
		_speed_debug_log "FOREGROUND_STATE_BATCH_DAEMON pkg=$_pkg active=${_active:-unknown} result=${_APPSTATE_RESULT_CODE:-unknown}/${_APPSTATE_RESULT_NAME:-unknown} fallbackFrom=processObserverDirect"
		rm -f "$_in" "$_out" 2>/dev/null
		case $_active in
		true) return 0 ;;
		false) return 1 ;;
		esac
		return 2
	fi
	_speed_debug_log "FOREGROUND_STATE_BATCH_DAEMON_FAIL pkg=$_pkg result=${_APPSTATE_RESULT_CODE:-unknown}/${_APPSTATE_RESULT_NAME:-unknown} fallbackFrom=processObserverDirect"
	rm -f "$_in" "$_out" 2>/dev/null
	return 2
}

# 透過 unified root daemon / HiddenApi forceStopPackageBatch 單獨終止指定 app。
# 回傳: 0=daemon force-stop 成功, 1=daemon force-stop 失敗。
_force_stop_pkg_daemon() {
	local _pkg="$1" _out _rc
	[[ -n $_pkg ]] || return 1
	_out="$(_webdav_tmp_path hiddenapi_force_stop_${$}_$RANDOM)"
	dex_hiddenapi_raw forceStopPackageBatch "${USER_ID:-${user:-0}}" "$_pkg" > "$_out"
	_rc=$?
	if [[ $_rc = 0 ]] && grep -F "FORCE_STOP_OK package=$_pkg " "$_out" >/dev/null 2>&1; then
		_speed_debug_log "FORCE_STOP_PACKAGE_BATCH_DAEMON_OK pkg=$_pkg out=$(tr '\n' '|' < "$_out" | cut -c1-300)"
		rm -f "$_out" 2>/dev/null
		return 0
	fi
	_speed_debug_log "FORCE_STOP_PACKAGE_BATCH_DAEMON_FAIL pkg=$_pkg rc=$_rc out=$(tr '\n' '|' < "$_out" | cut -c1-300)"
	rm -f "$_out" 2>/dev/null
	return 1
}

_force_stop_pkg_best_effort() {
	local _pkg="$1" _label="${2:-best_effort}" _u="${user:-0}"
	[[ -n $_pkg ]] || return 1
	_process_observer_status_cache_invalidate_pkg "$_pkg" "before_force_stop_${_label}" >/dev/null 2>&1 || true
	if _force_stop_pkg_verify_daemon "$_pkg" "$_label"; then
		_process_observer_status_cache_invalidate_pkg "$_pkg" "after_force_stop_dex_verify_${_label}" >/dev/null 2>&1 || true
		_speed_debug_log "FORCE_STOP_BEST_EFFORT_OK method=dex_verify pkg=$_pkg label=$_label"
		return 0
	fi
	if _force_stop_pkg_daemon "$_pkg"; then
		_process_observer_status_cache_invalidate_pkg "$_pkg" "after_force_stop_daemon_${_label}" >/dev/null 2>&1 || true
		_speed_debug_log "FORCE_STOP_BEST_EFFORT_OK method=daemon pkg=$_pkg label=$_label"
		return 0
	fi
	if am force-stop --user "$_u" "$_pkg" >/dev/null 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}; then
		_process_observer_status_cache_invalidate_pkg "$_pkg" "after_force_stop_am_${_label}" >/dev/null 2>&1 || true
		_speed_debug_log "FORCE_STOP_BEST_EFFORT_OK method=am_force_stop_fallback pkg=$_pkg user=$_u label=$_label"
		return 0
	fi
	_process_observer_status_cache_invalidate_pkg "$_pkg" "after_force_stop_fail_${_label}" >/dev/null 2>&1 || true
	_speed_debug_log "FORCE_STOP_BEST_EFFORT_FAIL pkg=$_pkg user=$_u label=$_label"
	return 1
}


# 備份/恢復用 live-app quiesce：cgroup freezer / ProcessObserver 為主；舊 package-suspend 入口暫停已移除。
_live_app_pause_enabled() {
	case "${SPEEDBACKUP_LIVE_APP_PAUSE_MODE:-${SPEEDBACKUP_LIVE_APP_PAUSE:-0}}" in
	1|true|TRUE|yes|YES|auto|pause|PAUSE) return 0 ;;
	esac
	return 1
}


_live_app_suspended_state_file() {
	printf '%s\n' "${TMPDIR:-/data/local/tmp}/.speedbackup_live_app_suspended"
}


_live_app_unsuspend_all() {
	local _state
	_state="$(_live_app_suspended_state_file)"
	[[ -e $_state ]] && rm -f "$_state" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} || true
	LIVE_APP_SUSPENDED_PKG=""
	return 0
}

_pkg_is_quiesce_never_pause() {
	local _pkg="$1"
	[[ -n $_pkg ]] || return 0
	case $_pkg in
	android|system|com.android.systemui|com.android.phone|com.android.providers.*|com.android.server.telecom|com.android.nfc|com.android.bluetooth|com.android.shell|com.android.permissioncontroller|com.google.android.permissioncontroller|com.android.vending|com.google.android.gms|com.google.android.gsf|com.android.launcher*|com.google.android.apps.nexuslauncher|com.miui.home|com.sec.android.app.launcher|com.oppo.launcher|com.coloros.launcher|com.huawei.android.launcher|com.vivo.launcher)
		return 0 ;;
	esac
	return 1
}


# r121: 高風險 App per-UID 網路封鎖。優先 Dex direct netpolicy Binder，不走 shell iptables；netd 僅作手動 hard/probe。
_uid_netblock_enabled() {
	case "${SPEEDBACKUP_UID_NETBLOCK:-1}" in
	0|false|FALSE|no|NO|off|OFF|disable|DISABLE) return 1 ;;
	esac
	return 0
}

_uid_netblock_token_state_file() {
	printf '%s\n' "${TMPDIR:-/data/local/tmp}/.speedbackup_uid_netblock_tokens"
}

_uid_netblock_pkg_enabled() {
	local _pkg="$1" _policy="${SPEEDBACKUP_UID_NETBLOCK_POLICY:-smart}"
	[[ -n $_pkg ]] || return 1
	_uid_netblock_enabled || return 1
	case $_policy in
	all|full|on|enable|enabled) return 0 ;;
	none|off|disable|disabled) return 1 ;;
	smart|auto|*) _process_observer_high_risk_pkg "$_pkg" && return 0 ;;
	esac
	return 1
}

_uid_netblock_log_path() {
	local _pkg="$1" _stage="$2" _safe_pkg _base
	_safe_pkg="$(_backup_tar_safe_name "${_pkg:-unknown}")"
	if [[ -n ${SPEED_DEBUG_RUN_DIR:-} && -d ${SPEED_DEBUG_RUN_DIR:-} ]]; then
		_base="$SPEED_DEBUG_RUN_DIR"
	else
		_base="${TMPDIR:-/data/local/tmp}"
	fi
	printf '%s\n' "$_base/uid_netblock_${_safe_pkg}_${_stage}.log"
}

_uid_netblock_start_app() {
	local _pkg="$1" _label="$2" _stage="${3:-app-scope}" _mode _log _out _rc _token _state
	[[ -n $_pkg ]] || return 0
	_uid_netblock_pkg_enabled "$_pkg" || { _speed_debug_log "UID_NET_BLOCK_SKIP pkg=$_pkg label=$_label stage=$_stage policy=${SPEEDBACKUP_UID_NETBLOCK_POLICY:-smart}"; return 0; }
	case $_pkg in bin.mt.plus|bin.mt.plus.canary|com.termux) _speed_debug_log "UID_NET_BLOCK_SKIP_SELF pkg=$_pkg stage=$_stage"; return 0 ;; esac
	if [[ -n ${UID_NETBLOCK_APP_TOKEN:-} && ${UID_NETBLOCK_APP_PKG:-} = "$_pkg" ]]; then
		_speed_debug_log "UID_NET_BLOCK_APP_REUSE token=${UID_NETBLOCK_APP_TOKEN:-} pkg=$_pkg label=$_label stage=$_stage"
		return 0
	fi
	if [[ -n ${UID_NETBLOCK_APP_TOKEN:-} ]]; then
		_uid_netblock_stop_app "app-switch-${_stage}" || true
	fi
	_mode="${SPEEDBACKUP_UID_NETBLOCK_MODE:-netpolicy}"
	_log="$(_uid_netblock_log_path "$_pkg" "$_stage")"
	_speed_debug_log "UID_NET_BLOCK_POLICY pkg=$_pkg label=$_label stage=$_stage policy=${SPEEDBACKUP_UID_NETBLOCK_POLICY:-smart} mode=$_mode"
	_out="$(_webdav_tmp_path uid_netblock_start_${$}_$RANDOM)"
	dex_hiddenapi_raw uidNetBlockStart "${USER_ID:-${user:-0}}" "$_pkg" "$_mode" "$_log" > "$_out" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	_rc=$?
	if [[ $_rc = 0 ]] && grep -F "UID_NET_BLOCK_START_OK" "$_out" >/dev/null 2>&1; then
		_token="$(sed -n 's/.*token=\([0-9][0-9]*\).*/\1/p' "$_out" | head -n 1)"
		if [[ -n $_token ]]; then
			_state="$(_uid_netblock_token_state_file)"
			printf '%s\t%s\t%s\t%s\t%s\n' "$_token" "$_pkg" "$_label" "$_stage" "$_log" >> "$_state" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
			UID_NETBLOCK_APP_TOKEN="$_token"
			UID_NETBLOCK_APP_PKG="$_pkg"
			UID_NETBLOCK_APP_LABEL="$_label"
			UID_NETBLOCK_APP_STAGE="$_stage"
			UID_NETBLOCK_APP_LOG="$_log"
			_speed_debug_log "UID_NET_BLOCK_START_OK token=$_token pkg=$_pkg label=$_label stage=$_stage mode=$_mode log=$_log"
			rm -f "$_out" 2>/dev/null
			return 0
		fi
	fi
	_speed_debug_log "UID_NET_BLOCK_START_FAIL pkg=$_pkg label=$_label stage=$_stage mode=$_mode rc=$_rc out=$(tr '\n' '|' < "$_out" | cut -c1-500)"
	rm -f "$_out" 2>/dev/null
	return 1
}

_uid_netblock_remove_state_token() {
	local _token="$1" _state _tmp
	[[ -n $_token ]] || return 0
	_state="$(_uid_netblock_token_state_file)"
	[[ -f $_state ]] || return 0
	_tmp="$TMPDIR/.uid_netblock_tokens_${$}_$RANDOM"
	awk -F '	' -v t="$_token" '$1!=t {print $0}' "$_state" > "$_tmp" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} || cp -f "$_state" "$_tmp" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	cat "$_tmp" > "$_state" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} || true
	rm -f "$_tmp" 2>/dev/null
	[[ -s $_state ]] || rm -f "$_state" 2>/dev/null
}

_uid_netblock_stop_token() {
	local _token="$1" _reason="$2" _pkg="$3" _stage="$4" _log="$5" _out _rc _flat
	[[ -n $_token ]] || return 0
	_out="$(_webdav_tmp_path uid_netblock_stop_${$}_$RANDOM)"
	dex_hiddenapi_raw uidNetBlockStop "$_token" "${USER_ID:-${user:-0}}" "$_pkg" > "$_out" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	_rc=$?
	_flat="$(_cgroup_freezer_compact_out "$_out")"
	_speed_debug_log "UID_NET_BLOCK_STOP token=$_token reason=$_reason pkg=$_pkg stage=$_stage rc=$_rc out=$_flat"
	if [[ $_rc != 0 ]] || grep -E 'UID_NET_BLOCK_STOP_MISSING|UID_NET_BLOCK_STOP_FAILED|UID_NET_BLOCK_RESTORE_FAILED|UID_NET_BLOCK_PERSISTENT_RESTORE_MISSING|UID_NET_BLOCK_PERSISTENT_RESTORE_FAILED|UID_NET_BLOCK_PERSISTENT_RESTORE_REJECTED|stateRetained=true|stateDeleted=false' "$_out" >/dev/null 2>&1; then
		_dex_out="$(_webdav_tmp_path uid_netblock_restore_pkg_${$}_$RANDOM)"
		dex_hiddenapi_raw uidNetBlockRestorePackage "${USER_ID:-${user:-0}}" "$_pkg" > "$_dex_out" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
		_dex_rc=$?
		_speed_debug_log "UID_NET_BLOCK_RESTORE_PACKAGE token=$_token reason=$_reason pkg=$_pkg rc=$_dex_rc out=$(tr '\n' '|' < "$_dex_out" | cut -c1-700)"
		rm -f "$_dex_out" 2>/dev/null
	fi
	_uid_netblock_remove_state_token "$_token"
	rm -f "$_out" 2>/dev/null
	return 0
}

_uid_netblock_stop_app() {
	local _reason="${1:-app-scope-done}" _token="${UID_NETBLOCK_APP_TOKEN:-}" _pkg="${UID_NETBLOCK_APP_PKG:-}" _label="${UID_NETBLOCK_APP_LABEL:-}" _stage="${UID_NETBLOCK_APP_STAGE:-}" _log="${UID_NETBLOCK_APP_LOG:-}"
	UID_NETBLOCK_APP_TOKEN=""; UID_NETBLOCK_APP_PKG=""; UID_NETBLOCK_APP_LABEL=""; UID_NETBLOCK_APP_STAGE=""; UID_NETBLOCK_APP_LOG=""
	[[ -n $_token ]] || return 0
	if [[ $_reason = restore_app_scope_done && $_stage = restore_app_scope ]] && _restore_post_state_guard_defer_pkg "$_pkg" uid_netblock; then
		_speed_debug_log "UID_NET_BLOCK_APP_DEFER token=$_token reason=$_reason pkg=$_pkg label=$_label stage=$_stage until=restore_post_appstate"
		return 0
	fi
	_uid_netblock_stop_token "$_token" "$_reason" "$_pkg" "$_stage" "$_log"
	_speed_debug_log "UID_NET_BLOCK_APP_STOP token=$_token reason=$_reason pkg=$_pkg label=$_label stage=$_stage"
}

_uid_netblock_stop_all() {
	local _reason="${1:-cleanup}" _state _tmp _line _token _pkg _label _stage _log _total=0 _idx=0
	UID_NETBLOCK_APP_TOKEN=""; UID_NETBLOCK_APP_PKG=""; UID_NETBLOCK_APP_LABEL=""; UID_NETBLOCK_APP_STAGE=""; UID_NETBLOCK_APP_LOG=""
	_state="$(_uid_netblock_token_state_file)"
	[[ -f $_state ]] || return 0
	_tmp="$TMPDIR/.uid_netblock_tokens_cleanup_${$}_$RANDOM"
	cp -f "$_state" "$_tmp" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} || return 0
	_total="$(awk 'NF{n++} END{print n+0}' "$_tmp" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null})"
	case $_total in ''|*[!0-9]*) _total=0 ;; esac
	[[ $_total -gt 0 ]] && _speedbackup_progress_step 0 "$_total" "正在解除目標App網路阻斷" "uid_netblock_stop_all" "107"
	while IFS='	' read -r _token _pkg _label _stage _log; do
		[[ -n $_token ]] || continue
		_idx=$((_idx + 1))
		_speedbackup_progress_step "$_idx" "$_total" "解除網路阻斷 ${_label:-$_pkg}" "uid_netblock_stop_all" "107"
		_uid_netblock_stop_token "$_token" "$_reason" "$_pkg" "$_stage" "$_log" >/dev/null 2>&1 || true
	done < "$_tmp"
	rm -f "$_tmp" "$_state" 2>/dev/null
}


# r138: cgroup v2 freezer tar-scope lifecycle。備份/恢復 app-scope 前 freeze 目前所有 live pid；r148 起恢復會延長到 AppState/SSAID 後處理完成才 thaw。
# Dex 會優先使用可選 native cgfreezer helper 做 raw /proc + cgroup.freeze hot path；未安裝 helper 時自動走 Java fallback。
_cgroup_freezer_enabled() {
	case "${SPEEDBACKUP_CGROUP_FREEZER:-auto}" in
		0|false|FALSE|no|NO|off|OFF|disable|DISABLE|none) return 1 ;;
	esac
	return 0
}

_cgroup_freezer_token_state_file() {
	printf '%s\n' "${TMPDIR:-/data/local/tmp}/.speedbackup_cgroup_freezer_tokens"
}


_cgroup_freezer_cleanup_stale_once() {
	# r136: 意外退出/Termux 被殺/RootDaemon 重啟後，下一次 app scope 前先由 Dex persistent state 還原所有未 stop 的 freezer token。
	# TTL 預設 0 = 立即恢復舊 state；只跑一次，避免每個 App 額外 daemon call。
	[[ ${CGROUP_FREEZER_CLEANUP_STALE_DONE:-0} = 1 ]] && return 0
	CGROUP_FREEZER_CLEANUP_STALE_DONE=1
	_cgroup_freezer_enabled || return 0
	local _ttl="${SPEEDBACKUP_CGROUP_FREEZER_CLEANUP_TTL_MS:-0}" _out _rc
	case $_ttl in ''|*[!0-9]*) _ttl=0 ;; esac
	_out="$(_webdav_tmp_path cgroup_freezer_cleanup_stale_${$}_$RANDOM)"
	dex_hiddenapi_raw cgroupFreezeCleanupStale startup-recover "$_ttl" > "$_out" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	_rc=$?
	_speed_debug_log "CGROUP_FREEZER_CLEANUP_STALE_ONCE rc=$_rc ttlMs=$_ttl out=$(tr '\n' '|' < "$_out" | cut -c1-700)"
	rm -f "$_out" 2>/dev/null
	return 0
}

_cgroup_freezer_cleanup_stale_now() {
	local _reason="${1:-manual}" _ttl="${2:-0}" _out _rc
	_cgroup_freezer_enabled || return 0
	case $_ttl in ''|*[!0-9]*) _ttl=0 ;; esac
	_out="$(_webdav_tmp_path cgroup_freezer_cleanup_now_${$}_$RANDOM)"
	dex_hiddenapi_raw cgroupFreezeCleanupStale "$_reason" "$_ttl" > "$_out" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	_rc=$?
	_speed_debug_log "CGROUP_FREEZER_CLEANUP_STALE_NOW reason=$_reason rc=$_rc ttlMs=$_ttl out=$(tr '\n' '|' < "$_out" | cut -c1-700)"
	rm -f "$_out" 2>/dev/null
	return 0
}

_CGROUP_FREEZER_BATCH_SESSION_ACTIVE=0
_CGROUP_FREEZER_BATCH_SESSION_REASON=""
_CGROUP_FREEZER_REQUIRED_NATIVE_CAPS="${SPEEDBACKUP_CGROUP_FREEZER_REQUIRED_CAPS:-cgroup-v2-uid-root-fallback cgroup-wchan-confirm-v1}"
_cgroup_freezer_daemon_socket_path() {
	# r488: strict run-tmpdir socket path. Never fallback to /data/local/tmp root.
	local _socket="${SPEEDBACKUP_CGROUP_FREEZER_SOCKET:-}" _run="${SPEEDBACKUP_RUN_TMPDIR:-}" _base="${SPEEDBACKUP_TMP_BASE:-/data/local/tmp}"
	case "$_base" in /data/local/tmp) ;; *) return 1 ;; esac
	case "$_socket" in "$_base"/.speedbackup_run_*/speedbackup_cgfreezerd.sock) printf '%s\n' "$_socket"; return 0 ;; esac
	case "$_run" in "$_base"/.speedbackup_run_*) printf '%s/speedbackup_cgfreezerd.sock\n' "$_run"; return 0 ;; esac
	return 1
}

_cgroup_freezer_daemon_process_sweep() {
	# r420: cgfreezerd 是批量備份/恢復期間的 persistent helper，流程結束後不應留在系統進程表。
	# 先走 socket STOP；若 socket 已被 unlink、unixsock 不可用、或舊版 daemon 沒回 pid，最後用嚴格 cmdline 白名單掃描兜底。
	local _reason="${1:-final_cleanup}" _socket _p _pid _cmd _matched=0 _term=0 _kill=0 _alive _i
	_socket="$(_cgroup_freezer_daemon_socket_path)"
	for _p in /proc/[0-9]*; do
		_pid="${_p##*/}"
		case $_pid in ''|*[!0-9]*) continue ;; esac
		# 只匹配 cgfreezer daemon，不碰一次性 scan/freeze/kill 子命令，也不碰 tools.sh 自身。
		_cmd="$({ tr '\000' ' ' < "$_p/cmdline"; } 2>/dev/null)"
		[[ -n $_cmd ]] || continue
		case " $_cmd " in
			*"cgfreezer daemon "*) ;;
			*) continue ;;
		esac
		# 優先要求 socket path 或常見工具路徑；argv0 只有 cgfreezer 時仍視為本 helper daemon。
		case " $_cmd " in
			*" $_socket "*|*"/data/backup_tools/cgfreezer daemon "*|*"/data/local/tmp/"*"/cgfreezer daemon "*|*" cgfreezer daemon "*) ;;
			*) continue ;;
		esac
		_matched=$((_matched + 1))
		kill "$_pid" 2>/dev/null && _term=$((_term + 1))
	done
	if [[ $_matched -gt 0 ]]; then
		_i=0
		while [[ $_i -lt 10 ]]; do
			_alive=0
			for _p in /proc/[0-9]*; do
				_pid="${_p##*/}"
				case $_pid in ''|*[!0-9]*) continue ;; esac
				_cmd="$({ tr '\000' ' ' < "$_p/cmdline"; } 2>/dev/null)"
				case " $_cmd " in *"cgfreezer daemon "*) _alive=1; break ;; esac
			done
			[[ $_alive = 0 ]] && break
			sleep 0.05
			_i=$((_i + 1))
		done
		if [[ ${_alive:-0} != 0 ]]; then
			for _p in /proc/[0-9]*; do
				_pid="${_p##*/}"
				case $_pid in ''|*[!0-9]*) continue ;; esac
				_cmd="$({ tr '\000' ' ' < "$_p/cmdline"; } 2>/dev/null)"
				case " $_cmd " in *"cgfreezer daemon "*) kill -9 "$_pid" 2>/dev/null && _kill=$((_kill + 1)) ;; esac
			done
		fi
	fi
	_speed_debug_log "CGFREEZER_DAEMON_PROCESS_SWEEP reason=$_reason matched=$_matched term=$_term kill9=$_kill socket=$_socket mode=r420"
	return 0
}
_cgroup_freezer_daemon_sock_call() {
	local _cmd="$1" _out="$2" _socket _rc _err
	[[ -n $_cmd && -n $_out ]] || return 2
	_socket="$(_cgroup_freezer_daemon_socket_path)"
	[[ -S $_socket ]] || return 3
	_webdav_unixsock_relay_ready || return 127
	_err="${TMPDIR:-/data/local/tmp}/.cgfreezer_sock_stderr_${$}_$RANDOM"
	rm -f "$_err" 2>/dev/null || true
	# r253: cgfreezerd 全部 control/status 命令統一 plain-lines protocol。
	# 不再用 RootDaemon/WebDAV header-file 模式，避免 STATUS/STATS/LAST_ERROR 單行回覆被 unixsock 誤判 rc=5。
	printf '%s\n' "$_cmd" | _event_unixsock_call relay-unix "$_socket" > "$_out" 2>"$_err"
	_rc=$?
	_speedbackup_filter_cleanup_stderr_file "$_err" cgfreezer_parent_stop
	return "$_rc"
}

_cgroup_freezer_daemon_debug_status() {
	local _reason="${1:-status}" _cmd _out _rc _flat _safe
	[[ -S "$(_cgroup_freezer_daemon_socket_path)" ]] || return 0
	_safe="$(_process_observer_status_safe_name "$_reason" 2>/dev/null || printf '%s' "$_reason")"
	for _cmd in STATUS STATS STATS_DETAIL LAST_ERROR; do
		_out="$(_webdav_tmp_path cgroup_freezer_daemon_${_cmd}_${$}_$RANDOM)"
		_cgroup_freezer_daemon_sock_call "$_cmd" "$_out"
		_rc=$?
		_flat="$(tr '\n' '|' < "$_out" 2>/dev/null | cut -c1-900)"
		case $_cmd in
			STATUS) _speed_debug_log "CGROUP_FREEZER_DAEMON_STATUS reason=$_reason rc=$_rc out=$_flat" ;;
			STATS) _speed_debug_log "CGROUP_FREEZER_DAEMON_STATS reason=$_reason rc=$_rc out=$_flat" ;;
			STATS_DETAIL) _speed_debug_log "CGROUP_FREEZER_DAEMON_STATS_DETAIL reason=$_reason rc=$_rc out=$_flat" ;;
			LAST_ERROR) _speed_debug_log "CGROUP_FREEZER_DAEMON_LAST_ERROR reason=$_reason rc=$_rc out=$_flat" ;;
		esac
		if [[ -n ${SPEED_DEBUG_RUN_DIR:-} && -d ${SPEED_DEBUG_RUN_DIR:-} && -s $_out ]]; then
			cp -f "$_out" "$SPEED_DEBUG_RUN_DIR/cgroup_freezer_daemon_${_cmd}_${_safe}.txt" 2>/dev/null || true
		fi
		rm -f "$_out" 2>/dev/null
	done
	return 0
}
_cgroup_freezer_daemon_stop_socket() {
	local _reason="$1" _out _rc _flat _socket
	_socket="$(_cgroup_freezer_daemon_socket_path)"
	[[ -S $_socket ]] || return 0
	_out="$(_webdav_tmp_path cgroup_freezer_daemon_stop_${$}_$RANDOM)"
	_cgroup_freezer_daemon_sock_call STOP "$_out"
	_rc=$?
	_flat="$(tr '\n' '|' < "$_out" 2>/dev/null | cut -c1-700)"
	_speed_debug_log "CGROUP_FREEZER_DAEMON_PREFLIGHT_STOP reason=$_reason rc=$_rc socket=$_socket out=$_flat"
	rm -f "$_out" "$_socket" 2>/dev/null
	return 0
}

_cgroup_freezer_daemon_final_stop_unlink() {
	# r212: cgfreezerd is a persistent native daemon during a backup/restore run.
	# After ProcessObserver / netblock / cgroup freezer tokens are released, stop it explicitly
	# so /data/local/tmp/speedbackup_cgfreezerd.sock does not remain as stale state.
	# Use raw line-v4 relay; cgfreezerd replies plain text lines, not root-daemon header framing.
	local _reason="${1:-final_cleanup}" _socket _out _err _rc _flat _pid _i _alive
	_socket="$(_cgroup_freezer_daemon_socket_path)"
	if [[ ! -S $_socket ]]; then
		# r433: menu/update/list-only exit often has no cgfreezerd session at all.
		# The old no-socket fallback still scanned /proc, and on some Android 16 builds this
		# could block the EXIT trap before speed_debug final pack / tmpdir cleanup.
		# Only run the expensive process sweep when this run actually started a batch
		# cgfreezerd session, or when explicitly requested for diagnostics.
		if [[ ${_CGROUP_FREEZER_BATCH_SESSION_ACTIVE:-0} = 1 || -n ${_CGROUP_FREEZER_BATCH_SESSION_REASON:-} || ${SPEEDBACKUP_CGROUP_FREEZER_SWEEP_ON_NO_SOCKET:-0} = 1 ]]; then
			_speed_debug_log "CGROUP_FREEZER_DAEMON_FINAL_STOP_SKIP reason=$_reason state=no-socket socket=$_socket action=process-sweep active=${_CGROUP_FREEZER_BATCH_SESSION_ACTIVE:-0} activeReason=${_CGROUP_FREEZER_BATCH_SESSION_REASON:-} mode=r433"
			_cgroup_freezer_daemon_process_sweep "no-socket-${_reason}" || true
		else
			_speed_debug_log "CGROUP_FREEZER_DAEMON_FINAL_STOP_SKIP reason=$_reason state=no-socket socket=$_socket action=skip-no-session active=0 mode=r433"
		fi
		return 0
	fi
	if ! _webdav_unixsock_relay_ready; then
		rm -f "$_socket" 2>/dev/null
		_speed_debug_log "CGROUP_FREEZER_DAEMON_FINAL_STOP reason=$_reason rc=127 action=unlink-no-unixsock-process-sweep socket=$_socket"
		_cgroup_freezer_daemon_process_sweep "no-unixsock-${_reason}" || true
		return 0
	fi
	_cgroup_freezer_daemon_debug_status "before_final_stop_${_reason}" || true
	_out="$(_webdav_tmp_path cgroup_freezer_daemon_final_stop_${$}_$RANDOM)"
	_err="${_out}.stderr"
	rm -f "$_err" 2>/dev/null || true
	printf 'STOP\n' | _event_unixsock_call relay-unix "$_socket" > "$_out" 2>"$_err"
	_rc=$?
	_speedbackup_filter_cleanup_stderr_file "$_err" cgfreezer_final_stop
	_flat="$(tr '\n' '|' < "$_out" 2>/dev/null | cut -c1-700)"
	_pid="$(sed -n 's/.* pid=\([0-9][0-9]*\).*/\1/p' "$_out" 2>/dev/null | head -n 1)"
	_i=0
	_alive=0
	while [[ $_i -lt 20 ]]; do
		if [[ -n $_pid ]] && kill -0 "$_pid" 2>/dev/null; then
			_alive=1
		else
			_alive=0
		fi
		[[ ! -S $_socket && $_alive = 0 ]] && break
		sleep 0.1
		_i=$((_i + 1))
	done
	rm -f "$_socket" 2>/dev/null
	_cgroup_freezer_daemon_process_sweep "after-stop-${_reason}" || true
	_speed_debug_log "CGROUP_FREEZER_DAEMON_FINAL_STOP reason=$_reason rc=$_rc socket=$_socket pid=${_pid:-unknown} waitLoops=$_i aliveAfter=$_alive action=stop-unlink-process-sweep out=$_flat"
	rm -f "$_out" 2>/dev/null
	return 0
}

_cgroup_freezer_daemon_preflight_restart_if_stale() {
	local _reason="$1" _out _rc _flat _socket _need _err
	_socket="$(_cgroup_freezer_daemon_socket_path)"
	_need="$(_speedbackup_cgfreezer_required_caps_log)"
	[[ -S $_socket ]] || { _speed_debug_log "CGROUP_FREEZER_DAEMON_PREFLIGHT reason=$_reason stale=false socket=$_socket state=no-socket"; return 0; }
	_out="$(_webdav_tmp_path cgroup_freezer_daemon_preflight_${$}_$RANDOM)"
	_err="${_out}.stderr"
	rm -f "$_err" 2>/dev/null || true
	# r169/r199: cgfreezerd 每次連線只處理一行；首次 CAPS 探測若遇到 stale/尚未 ready socket，
	# unixsock 可能回精確 incomplete-header。只在這個 preflight 路徑捕獲並白名單過濾。
	printf 'CAPS\n' | _event_unixsock_call relay-unix "$_socket" --header-file "${_out}.status" > "$_out" 2>"$_err"
	_rc=$?
	_speedbackup_filter_cleanup_stderr_file "$_err" cgfreezer_preflight_probe
	_flat="$(tr '\n' '|' < "$_out" 2>/dev/null | cut -c1-700)"
	if [[ $_rc = 0 ]] && _speedbackup_cgfreezer_caps_file_ok "$_out"; then
		_speed_debug_log "CGROUP_FREEZER_DAEMON_PREFLIGHT method=caps-single-line reason=$_reason stale=false socket=$_socket requiredCap=$_need out=$_flat"
		rm -f "$_out" "${_out}.status" 2>/dev/null
		return 0
	fi
	_speed_debug_log "CGROUP_FREEZER_DAEMON_PREFLIGHT method=caps-single-line reason=$_reason stale=true socket=$_socket requiredCap=$_need rc=$_rc action=stop-restart out=$_flat"
	rm -f "$_out" "${_out}.status" 2>/dev/null
	_cgroup_freezer_daemon_stop_socket "stale-${_reason}"
	return 0
}
_cgroup_freezer_batch_session_begin() {
	local _reason="${1:-batch}" _out _rc _max_attempts
	_cgroup_freezer_enabled || { _speed_debug_log "CGROUP_FREEZER_BATCH_SESSION_SKIP reason=$_reason policy=${SPEEDBACKUP_CGROUP_FREEZER:-auto}"; return 0; }
	if [[ ${_CGROUP_FREEZER_BATCH_SESSION_ACTIVE:-0} = 1 ]]; then
		_speed_debug_log "CGROUP_FREEZER_BATCH_SESSION_REUSE reason=$_reason activeReason=${_CGROUP_FREEZER_BATCH_SESSION_REASON:-} persistent=true closeOnAppStop=false uidPidByC=true"
		return 0
	fi
	_cgroup_freezer_daemon_preflight_restart_if_stale "$_reason" || true
	local _attempt=1 _need_cap="$(_speedbackup_cgfreezer_required_caps_log)"
	_max_attempts="${SPEEDBACKUP_CGROUP_FREEZER_CAP_RETRY_MAX:-1}"
	case $_max_attempts in ''|*[!0-9]*) _max_attempts=1 ;; esac
	[[ $_max_attempts -lt 1 ]] && _max_attempts=1
	[[ $_max_attempts -gt 2 ]] && _max_attempts=2
	while [[ $_attempt -le $_max_attempts ]]; do
		_out="$(_webdav_tmp_path cgroup_freezer_batch_session_${$}_$RANDOM)"
		dex_hiddenapi_raw cgroupFreezeDaemonEnsure "$_reason" > "$_out" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
		_rc=$?
		if [[ $_rc = 0 ]] && grep -F "CGROUP_FREEZE_DAEMON_ENSURE ok=true" "$_out" >/dev/null 2>&1; then
			if _speedbackup_cgfreezer_caps_file_ok "$_out"; then
				_CGROUP_FREEZER_BATCH_SESSION_ACTIVE=1
				_CGROUP_FREEZER_BATCH_SESSION_REASON="$_reason"
				_cgroup_freezer_log_key_lines "$_out" || true
				_speed_debug_log "CGROUP_FREEZER_BATCH_SESSION_BEGIN reason=$_reason rc=$_rc attempt=$_attempt persistent=true closeOnAppStop=false perAppFastCommand=true uidPidByC=true daemonNoExit=true requiredCap=$_need_cap out=$(tr '\n' '|' < "$_out" | cut -c1-700)"
				_cgroup_freezer_daemon_debug_status "batch_begin_${_reason}" || true
				rm -f "$_out" 2>/dev/null
				return 0
			fi
			if [[ $_attempt -lt $_max_attempts ]]; then
				_speed_debug_log "CGROUP_FREEZER_BATCH_SESSION_STALE_CAP reason=$_reason rc=$_rc attempt=$_attempt requiredCap=$_need_cap action=stop-retry out=$(tr '\n' '|' < "$_out" | cut -c1-700)"
				rm -f "$_out" 2>/dev/null
				_cgroup_freezer_daemon_stop_socket "missing-required-cap-${_reason}-attempt-${_attempt}" || true
				_attempt=$((_attempt + 1))
				continue
			fi
			_speed_debug_log "CGROUP_FREEZER_BATCH_SESSION_STALE_CAP reason=$_reason rc=$_rc attempt=$_attempt requiredCap=$_need_cap action=stop-fallback out=$(tr '\n' '|' < "$_out" | cut -c1-700)"
			rm -f "$_out" 2>/dev/null
			_cgroup_freezer_daemon_stop_socket "missing-required-cap-${_reason}-attempt-${_attempt}" || true
			break
		fi
		_speed_debug_log "CGROUP_FREEZER_BATCH_SESSION_UNAVAILABLE reason=$_reason rc=$_rc attempt=$_attempt fallback=per-command out=$(tr '\n' '|' < "$_out" | cut -c1-700)"
		rm -f "$_out" 2>/dev/null
		return 1
	done
	_speed_debug_log "CGROUP_FREEZER_BATCH_SESSION_UNAVAILABLE reason=$_reason rc=$_rc attempts=$_max_attempts fallback=per-command requiredCap=$_need_cap reasonDetail=missing-required-cap"
	return 1
}
_cgroup_freezer_batch_daemon_ensure() {
	_cgroup_freezer_batch_session_begin "$1"
}
_cgroup_freezer_batch_session_note_app() {
	local _pkg="$1" _label="$2" _stage="$3"
	[[ ${_CGROUP_FREEZER_BATCH_SESSION_ACTIVE:-0} = 1 ]] || return 0
	_speed_debug_log "CGROUP_FREEZER_BATCH_SESSION_APP pkg=$_pkg label=$_label stage=$_stage action=per-app-scan-freeze uidPidByC=true daemonPersistent=true"
}

_cgroup_freezer_pkg_enabled() {
	local _pkg="$1" _stage="${2:-app-scope}" _policy="${SPEEDBACKUP_CGROUP_FREEZER:-auto}"
	[[ -n $_pkg ]] || return 1
	_cgroup_freezer_enabled || return 1
	case $_pkg in bin.mt.plus|bin.mt.plus.canary|com.termux) return 1 ;; esac
	case $_policy in
		all|full|on|enable|enabled|1|true|TRUE)
			if _pkg_is_quiesce_never_pause "$_pkg" && ! _speedbackup_cgroup_fast_settle_default_home_pkg "$_pkg" && ! _speedbackup_cgroup_fast_settle_default_ime_pkg "$_pkg"; then return 1; fi
			if _speedbackup_cgroup_fast_settle_default_ime_pkg "$_pkg"; then
				case $_stage in restore_app_scope) _speed_debug_log "RESTORE_POLICY_DEFAULT_IME package=$_pkg action=cgroup-first forceStop=false mode=r370" ;; backup_app_scope) _speed_debug_log "BACKUP_POLICY_DEFAULT_IME package=$_pkg action=cgroup-first mode=r370" ;; esac
			fi
			_speed_debug_log "QUIESCE_POLICY pkg=$_pkg mode=hard_freeze reason=policy_all stage=cgroup_freezer_enabled scope=$_stage"
			return 0 ;;
		none|off|disable|disabled|0|false|FALSE)
			_speed_debug_log "QUIESCE_POLICY pkg=$_pkg mode=instant_kill reason=policy_off stage=cgroup_freezer_disabled scope=$_stage"
			return 1 ;;
		smart|auto|*)
			if _pkg_is_quiesce_never_pause "$_pkg" && ! _speedbackup_cgroup_fast_settle_default_home_pkg "$_pkg" && ! _speedbackup_cgroup_fast_settle_default_ime_pkg "$_pkg"; then return 1; fi
			if _speedbackup_hard_freeze_pkg "$_pkg"; then
				_speed_debug_log "QUIESCE_POLICY pkg=$_pkg mode=hard_freeze reason=hardcoded_high_risk stage=cgroup_freezer_enabled scope=$_stage"
				return 0
			fi
			case $_stage in
				backup_app_scope|restore_app_scope)
					if _speedbackup_cgroup_fast_settle_pkg "$_pkg"; then
						if _speedbackup_cgroup_fast_settle_default_ime_pkg "$_pkg"; then
							case $_stage in restore_app_scope) _speed_debug_log "RESTORE_POLICY_DEFAULT_IME package=$_pkg action=cgroup-first forceStop=false mode=r370" ;; backup_app_scope) _speed_debug_log "BACKUP_POLICY_DEFAULT_IME package=$_pkg action=cgroup-first mode=r370" ;; esac
						fi
						_speed_debug_log "QUIESCE_POLICY pkg=$_pkg mode=hard_freeze reason=aggressive_fast_settle_restore_parity stage=cgroup_freezer_enabled scope=$_stage mode=r370"
						return 0
					fi
					;;
			esac
			_speed_debug_log "QUIESCE_POLICY pkg=$_pkg mode=instant_kill reason=default_non_hardcoded stage=cgroup_freezer_skip scope=$_stage"
			return 1
			;;
	esac
	return 1
}

# r154: 把 Dex cgroup 輸出的關鍵短摘要拆成 main.log 獨立行。
# 避免 CGROUP_FREEZER_TAR_SCOPE_START_OK/STOP 的 out=... 被 700 字元截斷後，
# 看不到 backend/pids/binder/elapsed 等真正判斷資訊。
# r156: Dex r153 的 native scan 行會在 batch session 內仍輸出 daemonPersistent=false；
# 該欄位代表單次 scan command 沒有自己持有 daemon，不代表批量 daemon 沒常駐。
# 這裡在 tools main.log 層正規化，避免交付測試時被誤判成 daemon 未復用。
_cgroup_freezer_normalize_log_line() {
	local _line="$1"
	case $_line in
		CGROUP_FREEZE_NATIVE_HELPER_SCAN*daemonPersistent=false*)
			if [[ ${_CGROUP_FREEZER_BATCH_SESSION_ACTIVE:-0} = 1 ]]; then
				_line="$(printf '%s\n' "$_line" | sed 's/ daemonPersistent=false/ daemonSessionPersistent=true daemonPersistentSource=batch-session/g')"
			fi
			;;
	esac
	printf '%s\n' "$_line"
}
_cgroup_freezer_compact_out() {
	local _file="$1" _text
	[[ -f $_file ]] || return 0
	_text="$(tr '\n' '|' < "$_file" | cut -c1-700)"
	case $_text in
		*CGROUP_FREEZE_NATIVE_HELPER_SCAN*daemonPersistent=false*)
			if [[ ${_CGROUP_FREEZER_BATCH_SESSION_ACTIVE:-0} = 1 ]]; then
				_text="$(printf '%s\n' "$_text" | sed 's/ daemonPersistent=false/ daemonSessionPersistent=true daemonPersistentSource=batch-session/g')"
			fi
			;;
	esac
	printf '%s\n' "$_text"
}
_cgroup_freezer_log_key_lines() {
	local _file="$1" _line
	[[ -f $_file ]] || return 0
	while IFS= read -r _line; do
		case $_line in
			CGROUP_FREEZER_SUMMARY*|CGROUP_FREEZE_START_OK*|CGROUP_FREEZE_STOP_OK*|CGROUP_FREEZE_NATIVE_HELPER_SCAN*|CGROUP_FREEZE_DAEMON_ENSURE*)
				_line="$(_cgroup_freezer_normalize_log_line "$_line")"
				_speed_debug_log "$_line"
				;;
		esac
	done < "$_file"
}

_cgroup_freezer_kv_from_line() {
	local _line="$1" _key="$2"
	[[ -n $_line && -n $_key ]] || return 0
	printf '%s\n' "$_line" | sed -n "s/.*[[:space:]]${_key}=\([^[:space:]]*\).*/\1/p" | tail -n 1
}

_cgroup_freezer_terminal_start_result() {
	local _file="$1" _pkg="$2" _label="$3" _stage="$4" _summary _checked _frozen _failed _backend
	[[ -f $_file ]] || return 0
	case $_stage in backup_app_scope|restore_app_scope) ;; *) return 0 ;; esac
	_summary="$(grep -F 'CGROUP_FREEZER_SUMMARY stage=start' "$_file" 2>/dev/null | tail -n 1)"
	[[ -n $_summary ]] || return 0
	_checked="$(_cgroup_freezer_kv_from_line "$_summary" checked)"
	_frozen="$(_cgroup_freezer_kv_from_line "$_summary" frozenCount)"
	_failed="$(_cgroup_freezer_kv_from_line "$_summary" failed)"
	_backend="$(_cgroup_freezer_kv_from_line "$_summary" backend)"
	case $_checked in ''|*[!0-9]*) _checked=0 ;; esac
	case $_frozen in ''|*[!0-9]*) _frozen=0 ;; esac
	case $_failed in ''|*[!0-9]*) _failed=0 ;; esac
	[[ $_checked -gt 0 ]] || return 0
	case $_backend in ''|v2) _backend="v2" ;; esac
	if [[ $_failed -eq 0 && $_frozen -gt 0 ]]; then
		echoRgb "事件cgroup $_backend成功" "1"
		_speed_debug_log "TERMINAL_EVENT_CGROUP_RESULT pkg=$_pkg label=$_label stage=$_stage result=success backend=$_backend checked=$_checked frozen=$_frozen failed=$_failed"
	else
		echoRgb "事件cgroup $_backend失敗" "0"
		_speed_debug_log "TERMINAL_EVENT_CGROUP_RESULT pkg=$_pkg label=$_label stage=$_stage result=fail backend=$_backend checked=$_checked frozen=$_frozen failed=$_failed"
	fi
}

# r216: LSPosed/NoANR companion property bridge removed.
# cgroup freezer now only performs scoped freeze/thaw/kill; no debug.* frozen UID props are written.
_cgroup_freezer_start_app() {
	local _pkg="$1" _label="$2" _stage="${3:-app-scope}" _out _rc _token _state _timeout _event_pid _wchan_rc
	[[ -n $_pkg ]] || return 0
	_cgroup_freezer_pkg_enabled "$_pkg" "$_stage" || { _speed_debug_log "CGROUP_FREEZER_SKIP pkg=$_pkg label=$_label stage=$_stage policy=${SPEEDBACKUP_CGROUP_FREEZER:-auto}"; return 0; }
	case $_pkg in bin.mt.plus|bin.mt.plus.canary|com.termux) _speed_debug_log "CGROUP_FREEZER_SKIP_SELF pkg=$_pkg stage=$_stage"; return 0 ;; esac
	_cgroup_freezer_cleanup_stale_once || true
	if [[ -n ${CGROUP_FREEZER_APP_TOKEN:-} && ${CGROUP_FREEZER_APP_PKG:-} = "$_pkg" ]]; then
		_speed_debug_log "CGROUP_FREEZER_APP_REUSE token=${CGROUP_FREEZER_APP_TOKEN:-} pkg=$_pkg label=$_label stage=$_stage"
		return 0
	fi
	if [[ -n ${CGROUP_FREEZER_APP_TOKEN:-} ]]; then
		_cgroup_freezer_stop_app "app-switch-${_stage}" || true
	fi
	_cgroup_freezer_batch_session_note_app "$_pkg" "$_label" "$_stage" || true
	_process_observer_foreground_barrier "$_pkg" "$_label" "cgroup_freezer_start_${_stage}" || true
	_event_pid="$(_process_observer_alive_first_pid "$_pkg" "cgroup_freezer_start_${_stage}" 2>/dev/null)"
	case $_event_pid in ''|*[!0-9]*) _event_pid=-1 ;; esac
	_timeout="${SPEEDBACKUP_CGROUP_FREEZER_TIMEOUT_MS:-1500}"
	case $_timeout in ''|*[!0-9]*) _timeout=1500 ;; esac
	_out="$(_webdav_tmp_path cgroup_freezer_start_${$}_$RANDOM)"
	dex_hiddenapi_raw cgroupFreezeStart "${USER_ID:-${user:-0}}" "$_pkg" "$_event_pid" "$_timeout" "$_stage" > "$_out" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	_rc=$?
	if [[ $_rc = 0 ]] && grep -F "CGROUP_FREEZE_START_OK" "$_out" >/dev/null 2>&1; then
		_token="$(sed -n 's/.*token=\([0-9][0-9]*\).*/\1/p' "$_out" | head -n 1)"
		if [[ -n $_token ]]; then
			_state="$(_cgroup_freezer_token_state_file)"
			printf '%s\t%s\t%s\t%s\n' "$_token" "$_pkg" "$_label" "$_stage" >> "$_state" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
			CGROUP_FREEZER_APP_TOKEN="$_token"
			CGROUP_FREEZER_APP_PKG="$_pkg"
			CGROUP_FREEZER_APP_LABEL="$_label"
			CGROUP_FREEZER_APP_STAGE="$_stage"
			_cgroup_freezer_log_key_lines "$_out" || true
			_cgroup_freezer_terminal_start_result "$_out" "$_pkg" "$_label" "$_stage" || true
			_cgroup_freezer_wchan_confirm_pkg "$_pkg" "$_label" "after_freeze_start_${_stage}" frozen "$_stage"
			_wchan_rc=$?
			if [[ $_wchan_rc = 1 ]]; then
				_cgroup_freezer_wchan_corrective_pkg "$_pkg" "$_label" "after_freeze_start_${_stage}" frozen "$_stage" || true
			fi
			_speed_debug_log "CGROUP_FREEZER_TAR_SCOPE_START_OK token=$_token pkg=$_pkg label=$_label stage=$_stage wchanConfirm=true out=$(_cgroup_freezer_compact_out "$_out")"
			rm -f "$_out" 2>/dev/null
			return 0
		fi
	fi
	_cgroup_freezer_log_key_lines "$_out" || true
	_cgroup_freezer_terminal_start_result "$_out" "$_pkg" "$_label" "$_stage" || true
	_speed_debug_log "CGROUP_FREEZER_TAR_SCOPE_START_UNAVAILABLE pkg=$_pkg label=$_label stage=$_stage rc=$_rc fallback=process-observer out=$(_cgroup_freezer_compact_out "$_out")"
	if _speedbackup_hard_freeze_pkg "$_pkg" || _speedbackup_cgroup_fast_settle_default_home_pkg "$_pkg" || _speedbackup_cgroup_fast_settle_default_ime_pkg "$_pkg"; then
		_speed_debug_log "HIGH_RISK_FREEZE_DEGRADED package=$_pkg label=$_label stage=$_stage reason=cgroup_freeze_unavailable fallback=observer_guard_stop mode=r370"
	fi
	rm -f "$_out" 2>/dev/null
	return 1
}

_cgroup_freezer_remove_state_token() {
	local _token="$1" _state _tmp
	[[ -n $_token ]] || return 0
	_state="$(_cgroup_freezer_token_state_file)"
	[[ -f $_state ]] || return 0
	_tmp="$TMPDIR/.cgroup_freezer_tokens_${$}_$RANDOM"
	awk -F '\t' -v t="$_token" '$1!=t {print $0}' "$_state" > "$_tmp" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} || cp -f "$_state" "$_tmp" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	cat "$_tmp" > "$_state" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} || true
	rm -f "$_tmp" 2>/dev/null
	[[ -s $_state ]] || rm -f "$_state" 2>/dev/null
}

_cgroup_freezer_stop_token() {
	local _token="$1" _reason="$2" _pkg="$3" _stage="$4" _out _rc _flat _dex_out _dex_rc _wchan_rc
	[[ -n $_token ]] || return 0
	_cgroup_freezer_wchan_confirm_pkg "$_pkg" "${CGROUP_FREEZER_APP_LABEL:-$_pkg}" "before_freeze_stop_${_reason}" frozen "$_stage"
	_wchan_rc=$?
	if [[ $_wchan_rc = 1 ]]; then
		_cgroup_freezer_wchan_corrective_pkg "$_pkg" "${CGROUP_FREEZER_APP_LABEL:-$_pkg}" "before_freeze_stop_${_reason}" frozen "$_stage" || true
	fi
	_out="$(_webdav_tmp_path cgroup_freezer_stop_${$}_$RANDOM)"
	dex_hiddenapi_raw cgroupFreezeStop "$_token" "${USER_ID:-${user:-0}}" "$_pkg" > "$_out" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	_rc=$?
	_cgroup_freezer_wchan_confirm_pkg "$_pkg" "${CGROUP_FREEZER_APP_LABEL:-$_pkg}" "after_freeze_stop_${_reason}" thawed "$_stage"
	_wchan_rc=$?
	if [[ $_wchan_rc = 1 ]]; then
		_cgroup_freezer_wchan_corrective_pkg "$_pkg" "${CGROUP_FREEZER_APP_LABEL:-$_pkg}" "after_freeze_stop_${_reason}" thawed "$_stage" || true
	fi
	_flat="$(_cgroup_freezer_compact_out "$_out")"
	_cgroup_freezer_log_key_lines "$_out" || true
	_speed_debug_log "CGROUP_FREEZER_STOP token=$_token reason=$_reason pkg=$_pkg stage=$_stage rc=$_rc out=$_flat"
	if [[ $_rc != 0 ]] || grep -E 'CGROUP_FREEZE_STOP_FAILED|CGROUP_FREEZE_STOP_REJECTED|stateDeleted=false' "$_out" >/dev/null 2>&1; then
		_dex_out="$(_webdav_tmp_path cgroup_freezer_restore_pkg_${$}_$RANDOM)"
		dex_hiddenapi_raw cgroupFreezeRestorePackage "${USER_ID:-${user:-0}}" "$_pkg" > "$_dex_out" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
		_dex_rc=$?
		_speed_debug_log "CGROUP_FREEZER_RESTORE_PACKAGE token=$_token reason=$_reason pkg=$_pkg rc=$_dex_rc out=$(_cgroup_freezer_compact_out "$_dex_out")"
		rm -f "$_dex_out" 2>/dev/null
	fi
	_cgroup_freezer_remove_state_token "$_token"
	rm -f "$_out" 2>/dev/null
	return 0
}

_cgroup_freezer_stop_app() {
	local _reason="${1:-app-scope-done}" _token="${CGROUP_FREEZER_APP_TOKEN:-}" _pkg="${CGROUP_FREEZER_APP_PKG:-}" _label="${CGROUP_FREEZER_APP_LABEL:-}" _stage="${CGROUP_FREEZER_APP_STAGE:-}"
	CGROUP_FREEZER_APP_TOKEN=""; CGROUP_FREEZER_APP_PKG=""; CGROUP_FREEZER_APP_LABEL=""; CGROUP_FREEZER_APP_STAGE=""
	[[ -n $_token ]] || return 0
	if [[ $_reason = restore_app_scope_done && $_stage = restore_app_scope ]] && _restore_post_state_guard_defer_pkg "$_pkg" cgroup_freezer; then
		_speed_debug_log "CGROUP_FREEZER_TAR_SCOPE_APP_DEFER token=$_token reason=$_reason pkg=$_pkg label=$_label stage=$_stage until=restore_post_appstate"
		return 0
	fi
	_cgroup_freezer_stop_token "$_token" "$_reason" "$_pkg" "$_stage"
	_speed_debug_log "CGROUP_FREEZER_TAR_SCOPE_APP_STOP token=$_token reason=$_reason pkg=$_pkg label=$_label stage=$_stage"
}

_cgroup_freezer_stop_all() {
	CGROUP_FREEZER_APP_TOKEN=""; CGROUP_FREEZER_APP_PKG=""; CGROUP_FREEZER_APP_LABEL=""; CGROUP_FREEZER_APP_STAGE=""
	local _reason="${1:-cleanup}" _state _tmp _token _pkg _label _stage _total=0 _idx=0
	_state="$(_cgroup_freezer_token_state_file)"
	[[ -s $_state ]] || return 0
	_tmp="$TMPDIR/.cgroup_freezer_tokens_cleanup_${$}_$RANDOM"
	cp -f "$_state" "$_tmp" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} || return 0
	_total="$(awk 'NF{n++} END{print n+0}' "$_tmp" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null})"
	case $_total in ''|*[!0-9]*) _total=0 ;; esac
	[[ $_total -gt 0 ]] && _speedbackup_progress_step 0 "$_total" "正在解除 cgroup freezer 守護" "cgroup_freezer_stop_all" "107"
	while IFS='	' read -r _token _pkg _label _stage; do
		[[ -n $_token ]] || continue
		_idx=$((_idx + 1))
		_speedbackup_progress_step "$_idx" "$_total" "解除 cgroup freezer ${_label:-$_pkg}" "cgroup_freezer_stop_all" "107"
		_cgroup_freezer_stop_token "$_token" "$_reason" "$_pkg" "$_stage" >/dev/null 2>&1 || true
	done < "$_tmp"
	rm -f "$_tmp" "$_state" 2>/dev/null
}

# r148: 恢復時把 app-scope guard 延長到 AppState/SSAID 批量恢復與驗證之後再釋放。
# r150: release 前先終止已恢復 App 的舊進程；restore 不能 thaw 舊 process，避免 tar 覆蓋後資料被舊記憶體狀態繼續寫回。
_restore_post_state_guard_collect_pkgs() {
	local _out="$1" _state
	[[ -n $_out ]] || return 1
	: > "$_out" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} || return 1
	_state="$(_cgroup_freezer_token_state_file)"
	if [[ -s $_state ]]; then
		awk -F '	' '$4=="restore_app_scope" && $2!="" {label=$3; if(label=="") label=$2; print $2 "	" label}' "$_state" >> "$_out" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} || true
	fi
	_state="$(_process_observer_token_state_file)"
	if [[ -s $_state ]]; then
		awk -F '	' '$5=="restore_app_scope" && $2!="" {label=$3; if(label=="") label=$2; print $2 "	" label}' "$_state" >> "$_out" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} || true
	fi
	_state="$(_uid_netblock_token_state_file)"
	if [[ -s $_state ]]; then
		awk -F '	' '$4=="restore_app_scope" && $2!="" {label=$3; if(label=="") label=$2; print $2 "	" label}' "$_state" >> "$_out" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} || true
	fi
	if [[ -s $_out ]]; then
		sort -u "$_out" -o "$_out" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} || true
		# r243: post-AppState kill list 只保留 hard_freeze/high-risk App；普通 instant_kill App 已在 app-scope 結束時釋放。
		local _filter _p _l
		_filter="$TMPDIR/.restore_post_state_kill_filter_${$}_$RANDOM"
		: > "$_filter" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} || true
		while IFS='	' read -r _p _l; do
			[[ -n $_p ]] || continue
			if _restore_post_state_guard_defer_pkg "$_p" collect; then
				printf '%s	%s
' "$_p" "${_l:-$_p}" >> "$_filter" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
			fi
		done < "$_out"
		cat "$_filter" > "$_out" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} || true
		rm -f "$_filter" 2>/dev/null
	fi
	return 0
}

_restore_live_guard_enabled() {
	case "${SPEEDBACKUP_RESTORE_LIVE_GUARD:-1}" in
	0|false|FALSE|no|NO|off|OFF|disable|DISABLE) return 1 ;;
	esac
	return 0
}

_restore_fastpath_enabled() {
	# r334: 保留 r331 restore 語義，但縮短空快照與 default HOME kill-before-thaw 的多餘探測。
	case "${SPEEDBACKUP_RESTORE_GUARD_FASTPATH:-1}" in
	0|false|FALSE|no|NO|off|OFF|disable|DISABLE) return 1 ;;
	esac
	return 0
}

_restore_fastpath_recheck_ms() {
	local _ms="${SPEEDBACKUP_RESTORE_GUARD_FASTPATH_RECHECK_MS:-80}"
	case $_ms in ''|*[!0-9]*) _ms=80 ;; esac
	[[ $_ms -lt 0 ]] && _ms=0
	[[ $_ms -gt 180 ]] && _ms=180
	printf '%s\n' "$_ms"
}

_restore_fastpath_sleep_ms() {
	local _ms="$1"
	case $_ms in ''|*[!0-9]*) return 0 ;; esac
	[[ $_ms -le 0 ]] && return 0
	sleep "0.$(printf '%03d' "$_ms" 2>/dev/null | tail -c 4)" 2>/dev/null || true
}

_restore_live_guard_pkg_critical() {
	local _pkg="$1"
	case $_pkg in
		bin.mt.plus|bin.mt.plus.canary|com.termux|android|system|com.android.systemui|com.android.phone|com.android.providers.*|com.android.server.telecom|com.android.nfc|com.android.bluetooth|com.android.shell|com.android.permissioncontroller|com.google.android.permissioncontroller|com.android.vending|com.google.android.gms|com.google.android.gsf) return 0 ;;
	esac
	return 1
}

_restore_live_guard_default_home_pkg() {
	local _pkg="$1"
	command -v _speedbackup_cgroup_fast_settle_default_home_pkg >/dev/null 2>&1 || return 1
	_speedbackup_cgroup_fast_settle_default_home_pkg "$_pkg"
}

_restore_live_guard_policy_for_pkg() {
	local _pkg="$1"
	if _restore_live_guard_default_home_pkg "$_pkg"; then
		printf '%s\n' default_home_process_kill
	elif _restore_post_state_guard_defer_pkg "$_pkg" live_guard_policy >/dev/null 2>&1; then
		printf '%s\n' freeze_list_kill_before_thaw
	else
		printf '%s\n' instant_kill_recheck
	fi
}

_restore_live_guard_scope_start() {
	local _pkg="$1" _label="${2:-$1}" _stage="${3:-restore_app_scope}" _policy _pids _cnt
	_restore_live_guard_enabled || return 0
	[[ $_stage = restore_app_scope && -n $_pkg ]] || return 0
	if _restore_live_guard_pkg_critical "$_pkg"; then
		_speed_debug_log "RESTORE_LIVE_GUARD_START_SKIP pkg=$_pkg label=$_label stage=$_stage reason=critical mode=r334"
		return 0
	fi
	_policy="$(_restore_live_guard_policy_for_pkg "$_pkg")"
	_pids="$(_pkg_process_pids "$_pkg" 2>/dev/null | tr '\n' ',' | sed 's/,$//')"
	_cnt=0
	[[ -n $_pids ]] && _cnt="$(printf '%s\n' "$_pids" | awk -F, '{print NF}')"
	_speed_debug_log "RESTORE_LIVE_GUARD_START pkg=$_pkg label=$_label stage=$_stage policy=$_policy alive=${_cnt:-0} pids=${_pids:-none} eventDriven=processObserver+cgroup finalSnapshotKill=true mode=r334"
	return 0
}

_restore_live_guard_kill_process_snapshot() {
	local _pkg="$1" _label="${2:-$1}" _reason="${3:-restore_live_guard}" _force_mode="${4:-auto}" _pass="${5:-1}" _pids _pid _event_pid _force_ok=1 _force_desc=false _native_ok=0 _sigkill_ok=0 _sigkill_fail=0 _after _cnt
	[[ -n $_pkg ]] || return 0
	_pids="$(_pkg_process_pids "$_pkg" 2>/dev/null | tr '\n' ',' | sed 's/,$//')"
	[[ -n $_pids ]] || { _speed_debug_log "RESTORE_LIVE_GUARD_SNAPSHOT_EMPTY pkg=$_pkg label=$_label reason=$_reason pass=$_pass mode=r334"; return 0; }
	_speed_debug_log "RESTORE_LIVE_GUARD_SNAPSHOT pkg=$_pkg label=$_label reason=$_reason pass=$_pass pids=$_pids forceMode=$_force_mode mode=r334"
	case $_force_mode in
		process_only|default_home_process_kill)
			_force_desc=skipped-process-kill-only
			;;
		*)
			_force_stop_pkg_best_effort "$_pkg" "restore_live_guard_${_reason}_pass${_pass}" >/dev/null 2>&1 && _force_ok=0 || _force_ok=1
			_force_desc=$([[ $_force_ok = 0 ]] && echo true || echo false)
			;;
	esac
	_after="$(_pkg_process_pids "$_pkg" 2>/dev/null)"
	if [[ -n $_after ]]; then
		_event_pid="$(printf '%s\n' "$_after" | awk 'NF && $1 ~ /^[0-9]+$/ {print $1; exit}')"
		if _cgroup_freezer_native_kill_pkg "$_pkg" "restore_live_guard_${_reason}_pass${_pass}" "${_event_pid:--1}" "${SPEEDBACKUP_RESTORE_LIVE_GUARD_KILL_TIMEOUT_MS:-700}"; then
			_native_ok=1
			_after="$(_pkg_process_pids "$_pkg" 2>/dev/null)"
		fi
	fi
	if [[ -n $_after ]]; then
		for _pid in $_after; do
			case $_pid in ''|*[!0-9]*) continue ;; esac
			if kill -KILL "$_pid" 2>/dev/null; then
				_sigkill_ok=$((_sigkill_ok + 1))
			else
				_sigkill_fail=$((_sigkill_fail + 1))
			fi
		done
	fi
	_wait_pkg_process_gone "$_pkg" >/dev/null 2>&1 || true
	_after="$(_pkg_process_pids "$_pkg" 2>/dev/null | tr '\n' ',' | sed 's/,$//')"
	_cnt=0
	[[ -n $_after ]] && _cnt="$(printf '%s\n' "$_after" | awk -F, '{print NF}')"
	_speed_debug_log "RESTORE_LIVE_GUARD_KILL_PASS pkg=$_pkg label=$_label reason=$_reason pass=$_pass forceStopOk=$_force_desc nativeKillOk=$_native_ok sigkillOk=$_sigkill_ok sigkillFail=$_sigkill_fail after=${_after:-none} alive=${_cnt:-0} mode=r334"
	return 0
}

_restore_live_guard_final_kill_recheck_pkg() {
	local _pkg="$1" _label="${2:-$1}" _reason="${3:-restore_app_scope_done}" _force_mode="${4:-auto}" _recheck_ms _after _cnt _initial _fast _procwait_rc
	_restore_live_guard_enabled || return 0
	[[ -n $_pkg ]] || return 0
	if _restore_live_guard_pkg_critical "$_pkg"; then
		_speed_debug_log "RESTORE_LIVE_GUARD_FINAL_SKIP pkg=$_pkg label=$_label reason=$_reason reasonDetail=critical mode=r334"
		return 0
	fi
	_fast=0
	_restore_fastpath_enabled && _fast=1
	_initial="$(_pkg_process_pids "$_pkg" 2>/dev/null | tr '
' ',' | sed 's/,$//')"
	_cnt=0
	[[ -n $_initial ]] && _cnt="$(printf '%s\n' "$_initial" | awk -F, '{print NF}')"
	if [[ $_fast = 1 && $_cnt -eq 0 ]]; then
		_speed_debug_log "RESTORE_LIVE_GUARD_FAST_EMPTY_SKIP pkg=$_pkg label=$_label reason=$_reason forceMode=$_force_mode action=skip-kill-recheck alive=0 mode=r334"
		_speed_debug_log "RESTORE_LIVE_GUARD_FINAL_DONE pkg=$_pkg label=$_label reason=$_reason alive=0 pids=none mode=r334"
		return 0
	fi
	_speed_debug_log "RESTORE_LIVE_GUARD_FINAL_BEGIN pkg=$_pkg label=$_label reason=$_reason forceMode=$_force_mode initial=${_initial:-none} fastPath=$_fast mode=r334"
	_restore_live_guard_kill_process_snapshot "$_pkg" "$_label" "$_reason" "$_force_mode" 1 || true
	if [[ $_fast = 1 ]]; then
		_recheck_ms="$(_restore_fastpath_recheck_ms)"
	else
		_recheck_ms="${SPEEDBACKUP_RESTORE_LIVE_GUARD_RECHECK_MS:-180}"
		case $_recheck_ms in ''|*[!0-9]*) _recheck_ms=180 ;; esac
	fi
	_procwait_pkg_gone "$_pkg" "${SPEEDBACKUP_RESTORE_LIVE_GUARD_PROCWAIT_TIMEOUT_MS:-700}" "$_recheck_ms" "restore_live_guard_final_recheck_${_reason}" "${user:-${USER_ID:-0}}"
	_procwait_rc=$?
	if [[ $_procwait_rc = 125 ]]; then
		_restore_fastpath_sleep_ms "$_recheck_ms"
		_speed_debug_log "RESTORE_LIVE_GUARD_RECHECK_WAIT_FALLBACK pkg=$_pkg label=$_label reason=$_reason recheckMs=$_recheck_ms engine=shell-sleep"
	else
		_speed_debug_log "RESTORE_LIVE_GUARD_RECHECK_WAIT pkg=$_pkg label=$_label reason=$_reason recheckMs=$_recheck_ms procwaitRc=$_procwait_rc engine=procwait"
	fi
	_after="$(_pkg_process_pids "$_pkg" 2>/dev/null | tr '
' ',' | sed 's/,$//')"
	_cnt=0
	[[ -n $_after ]] && _cnt="$(printf '%s\n' "$_after" | awk -F, '{print NF}')"
	_speed_debug_log "RESTORE_LIVE_GUARD_RECHECK pkg=$_pkg label=$_label reason=$_reason alive=$_cnt pids=${_after:-none} recheckMs=$_recheck_ms fastPath=$_fast mode=r334"
	if [[ $_cnt -gt 0 ]]; then
		_restore_live_guard_kill_process_snapshot "$_pkg" "$_label" "${_reason}_recheck" "$_force_mode" 2 || true
		_after="$(_pkg_process_pids "$_pkg" 2>/dev/null | tr '
' ',' | sed 's/,$//')"
		_cnt=0
		[[ -n $_after ]] && _cnt="$(printf '%s\n' "$_after" | awk -F, '{print NF}')"
	fi
	_speed_debug_log "RESTORE_LIVE_GUARD_FINAL_DONE pkg=$_pkg label=$_label reason=$_reason alive=$_cnt pids=${_after:-none} mode=r334"
	return 0
}

_restore_live_guard_scope_final_pkg() {
	local _pkg="$1" _label="${2:-$1}" _reason="${3:-restore_app_scope_done}" _policy
	_restore_live_guard_enabled || return 0
	[[ -n $_pkg ]] || return 0
	if _restore_post_state_guard_defer_pkg "$_pkg" live_guard_final >/dev/null 2>&1; then
		_policy="$(_restore_live_guard_policy_for_pkg "$_pkg")"
		_speed_debug_log "RESTORE_LIVE_GUARD_FINAL_DEFER pkg=$_pkg label=$_label reason=$_reason policy=$_policy until=restore_post_appstate_before_thaw mode=r334"
		return 0
	fi
	_restore_live_guard_final_kill_recheck_pkg "$_pkg" "$_label" "$_reason" auto
	return 0
}

_restore_lowrisk_guard_trim_enabled() {
	case "${SPEEDBACKUP_RESTORE_LOW_RISK_GUARD_TRIM:-1}" in
	0|false|FALSE|no|NO|off|OFF|disable|DISABLE) return 1 ;;
	esac
	return 0
}

_restore_lowrisk_guard_trim_high_risk_pkg() {
	local _pkg="$1"
	[[ -n $_pkg ]] || return 0
	_restore_live_guard_pkg_critical "$_pkg" && return 0
	command -v _speedbackup_hard_freeze_pkg >/dev/null 2>&1 && _speedbackup_hard_freeze_pkg "$_pkg" && return 0
	command -v _speedbackup_cgroup_fast_settle_default_home_pkg >/dev/null 2>&1 && _speedbackup_cgroup_fast_settle_default_home_pkg "$_pkg" && return 0
	command -v _speedbackup_cgroup_fast_settle_default_ime_pkg >/dev/null 2>&1 && _speedbackup_cgroup_fast_settle_default_ime_pkg "$_pkg" && return 0
	command -v _speedbackup_cgroup_fast_settle_pkg >/dev/null 2>&1 && _speedbackup_cgroup_fast_settle_pkg "$_pkg" && return 0
	command -v _process_observer_high_risk_pkg >/dev/null 2>&1 && _process_observer_high_risk_pkg "$_pkg" && return 0
	case $_pkg in
		com.tencent.mm|com.tencent.mobileqq|com.tencent.tim|com.tencent.wework|com.eg.android.AlipayGphone|com.taobao.taobao|com.ss.android.ugc.aweme|com.google.android.inputmethod.latin|com.baidu.input*|com.sohu.inputmethod.sogou*|com.android.launcher*|com.miui.home|net.oneplus.launcher|com.google.android.apps.nexuslauncher)
			return 0 ;;
	esac
	return 1
}

_restore_lowrisk_guard_trim_app() {
	local _pkg="$1" _label="${2:-$1}" _stage="${3:-restore_app_scope}" _installed="${4:-}" _preinstalled="${5:-}" _rc _pids _alive _active _top _count
	_restore_lowrisk_guard_trim_enabled || return 1
	[[ $_stage = restore_app_scope && -n $_pkg ]] || return 1
	# r480: trim 只允許「本輪恢復前未安裝、剛由本輪 APK 安裝成功」的 App。
	# 已安裝/覆蓋恢復的 App 可能有 provider、receiver、job、push 或 ROM 掃描喚醒風險，保留 r477/r478 完整 per-app guard。
	case $_preinstalled in
		1|true|TRUE|yes|YES)
			_speed_debug_log "RESTORE_LOW_RISK_GUARD_TRIM_SKIP pkg=$_pkg label=$_label stage=$_stage reason=preexisting_install_wake_risk preInstalled=$_preinstalled installed=${_installed:-0} pkgInstalled=${RESTORE_PKG_INSTALLED:-unknown} visibleAfterInstall=${RESTORE_PKG_VISIBLE_AFTER_INSTALL_OK:-0} mode=r481"
			return 1 ;;
	esac
	case $_installed:${RESTORE_PKG_INSTALLED:-}:${RESTORE_PKG_VISIBLE_AFTER_INSTALL_OK:-0} in
		1:true:1|1:1:1) ;;
		*) _speed_debug_log "RESTORE_LOW_RISK_GUARD_TRIM_SKIP pkg=$_pkg label=$_label stage=$_stage reason=new_install_visible_after_install_not_confirmed preInstalled=${_preinstalled:-0} installed=${_installed:-0} pkgInstalled=${RESTORE_PKG_INSTALLED:-unknown} visibleAfterInstall=${RESTORE_PKG_VISIBLE_AFTER_INSTALL_OK:-0} mode=r481"; return 1 ;;
	esac
	if [[ ${PROCESS_OBSERVER_BATCH_SCOPE:-} != restore_session ]] || ! _process_observer_batch_pkg_active "$_pkg"; then
		_speed_debug_log "RESTORE_LOW_RISK_GUARD_TRIM_SKIP pkg=$_pkg label=$_label stage=$_stage reason=batch_session_not_covering scope=${PROCESS_OBSERVER_BATCH_SCOPE:-none} mode=r481"
		return 1
	fi
	if _restore_lowrisk_guard_trim_high_risk_pkg "$_pkg"; then
		_speed_debug_log "RESTORE_LOW_RISK_GUARD_TRIM_SKIP pkg=$_pkg label=$_label stage=$_stage reason=high_risk_or_home_ime mode=r481"
		return 1
	fi
	_process_observer_foreground_status "$_pkg" "restore_lowrisk_guard_trim_probe" >/dev/null 2>&1
	_rc=$?
	_active="${PROCESS_OBSERVER_DIRECT_ACTIVE:-unknown}"
	_top="${PROCESS_OBSERVER_DIRECT_TOP:-unknown}"
	_alive="${PROCESS_OBSERVER_DIRECT_ALIVE:-unknown}"
	_pids="${PROCESS_OBSERVER_DIRECT_PIDS:-}"
	case $_rc in
		1) ;;
		0) _speed_debug_log "RESTORE_LOW_RISK_GUARD_TRIM_SKIP pkg=$_pkg label=$_label stage=$_stage reason=active active=$_active topTarget=$_top alive=$_alive alivePids=${_pids:-none} mode=r481"; return 1 ;;
		*) _speed_debug_log "RESTORE_LOW_RISK_GUARD_TRIM_SKIP pkg=$_pkg label=$_label stage=$_stage reason=foreground_status_unknown rc=$_rc active=$_active topTarget=$_top alive=$_alive alivePids=${_pids:-none} mode=r481"; return 1 ;;
	esac
	case $_top in true) _speed_debug_log "RESTORE_LOW_RISK_GUARD_TRIM_SKIP pkg=$_pkg label=$_label stage=$_stage reason=top_target active=$_active topTarget=$_top alive=$_alive alivePids=${_pids:-none} mode=r481"; return 1 ;; esac
	case $_alive in true) _speed_debug_log "RESTORE_LOW_RISK_GUARD_TRIM_SKIP pkg=$_pkg label=$_label stage=$_stage reason=alive_background active=$_active topTarget=$_top alive=$_alive alivePids=${_pids:-none} mode=r481"; return 1 ;; esac
	case $_pids in ''|none|-) ;;
		*) _count="$(echo "$_pids" | awk -F, '{print NF}' 2>/dev/null)"; _speed_debug_log "RESTORE_LOW_RISK_GUARD_TRIM_SKIP pkg=$_pkg label=$_label stage=$_stage reason=alive_pids active=$_active topTarget=$_top alive=$_alive alivePids=$_pids count=${_count:-0} mode=r481"; return 1 ;;
	esac
	RESTORE_LOW_RISK_GUARD_TRIM_COUNT=$((${RESTORE_LOW_RISK_GUARD_TRIM_COUNT:-0} + 1))
	_speed_debug_log "RESTORE_LOW_RISK_GUARD_TRIM_APPLY pkg=$_pkg label=$_label stage=$_stage reason=new_install_batch_session_covers_inactive_lowrisk active=$_active topTarget=$_top alive=$_alive alivePids=none finalSnapshotKill=true action=skip-per-app-cgroup-kill-netblock-liveguard-new-install-only mode=r481"
	return 0
}

_restore_post_state_kill_pkg_before_thaw() {
	local _pkg="$1" _label="${2:-$1}" _reason="${3:-restore_post_state_done}" _before _after _pid _sigkill_ok=0 _sigkill_fail=0 _force_ok=1 _force_desc=false _event_pid _native_ok=0 _default_home_kill=0 _default_ime_kill=0 _fast=0
	[[ -n $_pkg ]] || return 0
	_restore_fastpath_enabled && _fast=1
	if command -v _speedbackup_cgroup_fast_settle_default_home_pkg >/dev/null 2>&1 && _speedbackup_cgroup_fast_settle_default_home_pkg "$_pkg"; then
		_default_home_kill=1
	fi
	if command -v _speedbackup_cgroup_fast_settle_default_ime_pkg >/dev/null 2>&1 && _speedbackup_cgroup_fast_settle_default_ime_pkg "$_pkg"; then
		_default_ime_kill=1
	fi
	case $_pkg in
		bin.mt.plus|bin.mt.plus.canary|com.termux|android|system|com.android.systemui|com.android.phone|com.android.providers.*|com.android.server.telecom|com.android.nfc|com.android.bluetooth|com.android.shell|com.android.permissioncontroller|com.google.android.permissioncontroller|com.android.vending|com.google.android.gms|com.google.android.gsf)
			_speed_debug_log "RESTORE_POST_STATE_KILL_SKIP_CRITICAL pkg=$_pkg label=$_label reason=$_reason mode=r334"
			return 0 ;;
		com.android.launcher*|com.google.android.apps.nexuslauncher|com.miui.home|com.sec.android.app.launcher|com.oppo.launcher|com.coloros.launcher|com.huawei.android.launcher|com.vivo.launcher)
			if [[ $_default_home_kill = 1 ]]; then
				_speed_debug_log "RESTORE_POST_STATE_KILL_ALLOW_DEFAULT_HOME pkg=$_pkg label=$_label reason=$_reason action=kill_process_before_thaw forceStop=false mode=r334"
			else
				_speed_debug_log "RESTORE_POST_STATE_KILL_SKIP_CRITICAL pkg=$_pkg label=$_label reason=$_reason mode=r334"
				return 0
			fi ;;
	esac
	if [[ $_fast = 1 ]]; then
		_speed_debug_log "RESTORE_POST_STATE_FASTPATH_DIRECT_KILL pkg=$_pkg label=$_label reason=$_reason skip=foreground_barrier,live_state mode=r334"
	else
		_process_observer_foreground_barrier "$_pkg" "$_label" "restore_post_state_kill_${_reason}" || true
		_package_live_state_status "$_pkg" "restore_post_state_before_kill_${_reason}" >/dev/null 2>&1 || true
	fi
	_before="$(_pkg_process_pids "$_pkg" 2>/dev/null | tr '
' ',' | sed 's/,$//')"
	if [[ $_default_home_kill = 1 ]]; then
		_force_desc=skipped-default-home-process-kill
		_speed_debug_log "RESTORE_POST_STATE_FORCE_STOP_SKIP_DEFAULT_HOME pkg=$_pkg label=$_label reason=$_reason action=native_or_sigkill_only mode=r334"
	elif [[ $_default_ime_kill = 1 ]]; then
		_force_desc=skipped-default-ime-process-kill
		_speed_debug_log "RESTORE_POST_STATE_FORCE_STOP_SKIP_DEFAULT_IME pkg=$_pkg label=$_label reason=$_reason action=native_or_sigkill_only mode=r370"
	else
		_force_stop_pkg_best_effort "$_pkg" "restore_post_state_kill_before_thaw_${_reason}" >/dev/null 2>&1 && _force_ok=0 || _force_ok=1
		_force_desc=$([[ $_force_ok = 0 ]] && echo true || echo false)
	fi
	_after="$(_pkg_process_pids "$_pkg" 2>/dev/null)"
	if [[ -n $_after ]]; then
		_event_pid="$(printf '%s\n' "$_after" | awk 'NF && $1 ~ /^[0-9]+$/ {print $1; exit}')"
		if _cgroup_freezer_native_kill_pkg "$_pkg" "restore_post_state_${_reason}" "${_event_pid:--1}" "${SPEEDBACKUP_NATIVE_KILL_TIMEOUT_MS:-700}"; then
			_native_ok=1
			_after="$(_pkg_process_pids "$_pkg" 2>/dev/null)"
		fi
	fi
	if [[ -n $_after ]]; then
		for _pid in $_after; do
			case $_pid in ''|*[!0-9]*) continue ;; esac
			if kill -KILL "$_pid" 2>/dev/null; then
				_sigkill_ok=$((_sigkill_ok + 1))
			else
				_sigkill_fail=$((_sigkill_fail + 1))
			fi
		done
	fi
	local _recheck_ms _recheck_cnt _procwait_rc
	if [[ $_fast = 1 ]]; then
		_recheck_ms="$(_restore_fastpath_recheck_ms)"
	else
		_recheck_ms="${SPEEDBACKUP_RESTORE_LIVE_GUARD_RECHECK_MS:-180}"
		case $_recheck_ms in ''|*[!0-9]*) _recheck_ms=180 ;; esac
	fi
	_procwait_pkg_gone "$_pkg" "${SPEEDBACKUP_RESTORE_LIVE_GUARD_PROCWAIT_TIMEOUT_MS:-700}" "$_recheck_ms" "restore_post_state_kill_${_reason}" "${user:-${USER_ID:-0}}"
	_procwait_rc=$?
	if [[ $_procwait_rc = 125 ]]; then
		_wait_pkg_process_gone "$_pkg" >/dev/null 2>&1 || true
		[[ $_fast = 1 ]] && _restore_fastpath_sleep_ms "$_recheck_ms"
	fi
	_after="$(_pkg_process_pids "$_pkg" 2>/dev/null | tr '
' ',' | sed 's/,$//')"
	_recheck_cnt=0
	[[ -n $_after ]] && _recheck_cnt="$(printf '%s\n' "$_after" | awk -F, '{print NF}')"
	_speed_debug_log "RESTORE_POST_STATE_KILL_RECHECK pkg=$_pkg label=$_label reason=$_reason alive=$_recheck_cnt pids=${_after:-none} recheckMs=$_recheck_ms fastPath=$_fast mode=r334"
	if [[ $_recheck_cnt -gt 0 ]]; then
		if [[ $_fast = 1 && $_default_home_kill = 1 ]]; then
			# r334: default HOME 可能由系統立即重拉。恢復資料/AppState 後已殺掉舊 pid；
			# 新 pid 由 r331 ProcessObserver cgroup-freeze action 接手，避免在 thaw 前進入 kill→respawn 迴圈。
			_speed_debug_log "RESTORE_POST_STATE_DEFAULT_HOME_RESPAWN_ACCEPT pkg=$_pkg label=$_label reason=$_reason pids=${_after:-none} action=accept-post-restore-respawn observer=cgroup-freeze skipSecondKill=1 mode=r334"
		elif [[ $_fast = 1 && $_default_ime_kill = 1 ]]; then
			# r426: default IME 會被系統/目前輸入焦點立即重拉；AppState/SSAID 已完成後不再進第二輪 kill→respawn。
			_speed_debug_log "RESTORE_POST_STATE_DEFAULT_IME_RESPAWN_ACCEPT pkg=$_pkg label=$_label reason=$_reason pids=${_after:-none} action=accept-post-restore-respawn observer=cgroup-freeze skipSecondKill=1 mode=r427"
		else
			_restore_live_guard_kill_process_snapshot "$_pkg" "$_label" "post_state_${_reason}_recheck" "$([[ $_default_home_kill = 1 ]] && echo process_only || echo auto)" 2 || true
			_after="$(_pkg_process_pids "$_pkg" 2>/dev/null | tr '
' ',' | sed 's/,$//')"
		fi
	fi
	_speed_debug_log "RESTORE_POST_STATE_KILL_BEFORE_THAW pkg=$_pkg label=$_label reason=$_reason forceStopOk=$_force_desc nativeKillOk=$_native_ok sigkillOk=$_sigkill_ok sigkillFail=$_sigkill_fail before=${_before:-none} after=${_after:-none} fastPath=$_fast mode=r334"
	return 0
}

_restore_post_state_kill_all_before_thaw() {
	local _reason="${1:-restore_post_appstate_done}" _tmp _pkg _label _n=0 _total=0
	_restore_post_state_guard_enabled || return 0
	_tmp="$TMPDIR/.restore_post_state_kill_pkgs_${$}_$RANDOM"
	_restore_post_state_guard_collect_pkgs "$_tmp" || return 0
	if [[ ! -s $_tmp ]]; then
		rm -f "$_tmp" 2>/dev/null
		_speed_debug_log "RESTORE_POST_STATE_KILL_ALL_SKIP reason=$_reason packages=0"
		return 0
	fi
	_total="$(awk 'NF{n++} END{print n+0}' "$_tmp" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null})"
	case $_total in ''|*[!0-9]*) _total=0 ;; esac
	_speedbackup_progress_step 0 "$_total" "正在終止高風險 App 舊進程" "restore_post_kill_before_thaw" "107"
	_speed_debug_log "RESTORE_POST_STATE_KILL_ALL_BEGIN reason=$_reason total=$_total"
	while IFS='	' read -r _pkg _label; do
		[[ -n $_pkg ]] || continue
		_n=$((_n + 1))
		# r334: 不要在實際 kill/recheck 尚未完成前把高風險App守護顯示成 100%。
		# 先維持上一個完成數，完成後再推進，避免 1/1 看起來卡住。
		_speedbackup_progress_step "$((_n - 1))" "$_total" "正在終止高風險 App 舊進程 ${_label:-$_pkg}" "restore_post_kill_before_thaw" "107"
		_restore_post_state_kill_pkg_before_thaw "$_pkg" "$_label" "$_reason" || true
		_speedbackup_progress_step "$_n" "$_total" "高風險 App 舊進程處理完成 ${_label:-$_pkg}" "restore_post_kill_before_thaw" "107"
	done < "$_tmp"
	rm -f "$_tmp" 2>/dev/null
	_speed_debug_log "RESTORE_POST_STATE_KILL_ALL_DONE reason=$_reason packages=$_n"
	return 0
}

_restore_post_state_guard_has_pending() {
	local _state
	_state="$(_cgroup_freezer_token_state_file)"
	if [[ -s $_state ]] && awk -F '	' '$4=="restore_app_scope"{found=1} END{exit(found?0:1)}' "$_state" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}; then return 0; fi
	_state="$(_process_observer_token_state_file)"
	if [[ -s $_state ]] && awk -F '	' '$5=="restore_app_scope"{found=1} END{exit(found?0:1)}' "$_state" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}; then return 0; fi
	_state="$(_uid_netblock_token_state_file)"
	if [[ -s $_state ]] && awk -F '	' '$4=="restore_app_scope"{found=1} END{exit(found?0:1)}' "$_state" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}; then return 0; fi
	return 1
}

_restore_post_state_guard_stop_all() {
	local _reason="${1:-restore_post_appstate_done}"
	_restore_post_state_guard_enabled || return 0
	if ! _restore_post_state_guard_has_pending; then
		_speed_debug_log "RESTORE_POST_STATE_GUARD_STOP_ALL_SKIP reason=$_reason tokens=0"
		return 0
	fi
	_speedbackup_progress_hint "正在釋放恢復守護，AppState/SSAID 已處理完成" "restore_guard_release"
	_speed_debug_log "RESTORE_POST_STATE_GUARD_STOP_ALL_BEGIN reason=$_reason killBeforeThaw=true"
	_restore_post_state_kill_all_before_thaw "$_reason" || true
	_process_observer_stop_all "$_reason" || true
	_uid_netblock_stop_all "$_reason" || true
	_cgroup_freezer_stop_all "$_reason" || true
	_speed_debug_log "RESTORE_POST_STATE_GUARD_STOP_ALL_DONE reason=$_reason killBeforeThaw=true"
	return 0
}


_cgroup_freezer_app_active_for_pkg() {
	local _pkg="$1"
	[[ -n $_pkg && -n ${CGROUP_FREEZER_APP_TOKEN:-} && ${CGROUP_FREEZER_APP_PKG:-} = "$_pkg" ]]
}

# r113: Dex processObserver + wake-block 正式 app lifecycle helper。RootDaemon 內 global observer 常駐；tools 只 add/remove package target；token missing 時優先 Dex persistent snapshot restore，shell fallback 只作最後保險。
_process_observer_guard_enabled() {
	case "${SPEEDBACKUP_PROCESS_OBSERVER_GUARD:-1}" in
	0|false|FALSE|no|NO|off|OFF|disable|DISABLE) return 1 ;;
	esac
	return 0
}

_process_observer_token_state_file() {
	printf '%s\n' "${TMPDIR:-/data/local/tmp}/.speedbackup_process_observer_tokens"
}

# r267: batch watch-set：同一輪備份的 data App 一次加入 RootDaemon global ProcessObserver target。
# 定位：只減少 shell ↔ RootDaemon / unixsock round-trip；喚醒/復活守護仍由 Dex 事件驅動處理，不砍安全語意。
PROCESS_OBSERVER_BATCH_ACTIVE=0
PROCESS_OBSERVER_BATCH_STATE=""
PROCESS_OBSERVER_BATCH_PKGS=""
PROCESS_OBSERVER_BATCH_SCOPE=""
PROCESS_OBSERVER_BATCH_CAP_OK=""
_process_observer_batch_capability_ok() {
	case "${SPEEDBACKUP_PROCESS_OBSERVER_BATCH_CAP_GATE:-1}" in
	0|false|FALSE|no|NO|off|OFF|disable|DISABLE) return 0 ;;
	esac
	case "${PROCESS_OBSERVER_BATCH_CAP_OK:-}" in
	1) return 0 ;;
	0) return 1 ;;
	esac
	local _cap="" _in="" _out="" _rc=1
	if [[ -n ${SPEED_DEBUG_RUN_DIR:-} && -s ${SPEED_DEBUG_RUN_DIR:-}/appstate_capabilities.json ]]; then
		_cap="${SPEED_DEBUG_RUN_DIR}/appstate_capabilities.json"
	else
		_in="$(_webdav_tmp_path process_observer_batch_cap_in_${$}_$RANDOM)"
		_out="$(_webdav_tmp_path process_observer_batch_cap_out_${$}_$RANDOM)"
		printf '{}\n' > "$_in" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} || true
		if _root_appstate_call capabilities "$_in" "$_out" >/dev/null 2>&1 && [[ -s $_out ]]; then
			_cap="$_out"
		fi
	fi
	if [[ -s $_cap ]] && jq -e '
		. as $root |
		def cap($n): any($root.capabilities[]?; .name == $n and .enabled == true);
		cap("dex.process_observer.batch_watchset.v1") and cap("dex.process_observer.batch_stop_safe.v1") and cap("dex.process_observer.batch_persistent_safety.v1")
	' "$_cap" >/dev/null 2>&1; then
		PROCESS_OBSERVER_BATCH_CAP_OK=1
		_speed_debug_log "PROCESS_OBSERVER_BATCH_CAP_OK required=dex.process_observer.batch_watchset.v1,dex.process_observer.batch_stop_safe.v1,dex.process_observer.batch_persistent_safety.v1 mode=r296"
		_rc=0
	else
		PROCESS_OBSERVER_BATCH_CAP_OK=0
		_speed_debug_log "PROCESS_OBSERVER_BATCH_CAP_MISSING required=dex.process_observer.batch_watchset.v1,dex.process_observer.batch_stop_safe.v1,dex.process_observer.batch_persistent_safety.v1 action=disable_batch mode=r296"
		_rc=1
	fi
	case "$_out" in "$TMPDIR"/*) rm -f "$_out" 2>/dev/null ;; esac
	case "$_in" in "$TMPDIR"/*) rm -f "$_in" 2>/dev/null ;; esac
	return $_rc
}
_process_observer_batch_guard_enabled() {
	case "${SPEEDBACKUP_PROCESS_OBSERVER_BATCH_GUARD:-1}" in
	0|false|FALSE|no|NO|off|OFF|disable|DISABLE) return 1 ;;
	esac
	_process_observer_guard_enabled || return 1
	# r298: full-list batch watch-set 會讓尚未輪到備份的 App 也被 observer/wake guard 影響。
	# 預設改為 live-safe：不提前 watch 全清單，只在當前 App 備份時走既有 app-scope observer。
	# 若要壓測舊 r296/r297 全清單批次模式，可明確設 SPEEDBACKUP_PROCESS_OBSERVER_BATCH_FULL_LIST=1。
	case "${SPEEDBACKUP_PROCESS_OBSERVER_BATCH_FULL_LIST:-0}" in
	1|true|TRUE|yes|YES|on|ON|enable|ENABLE) ;;
	*) _speed_debug_log "PROCESS_OBSERVER_BATCH_GUARD_SKIP reason=live_safe_full_list_disabled mode=r298"; return 1 ;;
	esac
	_process_observer_batch_capability_ok || return 1
	return 0
}
_process_observer_batch_state_file() {
	printf '%s\n' "${TMPDIR:-/data/local/tmp}/.speedbackup_process_observer_batch_tokens"
}
_process_observer_batch_pkgs_file() {
	printf '%s\n' "${TMPDIR:-/data/local/tmp}/.speedbackup_process_observer_batch_pkgs"
}
_process_observer_batch_pkg_active() {
	local _pkg="$1" _pkgs="${PROCESS_OBSERVER_BATCH_PKGS:-}"
	[[ ${PROCESS_OBSERVER_BATCH_ACTIVE:-0} = 1 && -n $_pkg && -f $_pkgs ]] || return 1
	awk -F '\t' -v p="$_pkg" '$1==p{f=1;exit} END{exit f?0:1}' "$_pkgs" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
}
_process_observer_batch_blacklisted_pkg() {
	local _pkg="$1"
	[[ -n $_pkg && -n ${blacklist:-} ]] || return 1
	printf '%s\n' "$blacklist" | awk -v p="$_pkg" '$0==p{f=1} END{exit !f}' 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
}
_process_observer_batch_build_spec() {
	local _spec="$1" _pkgs="$2" _line _name _pkg _label _action _log _count=0
	: > "$_spec" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} || return 1
	: > "$_pkgs" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} || return 1
	_process_observer_batch_guard_enabled || { _speed_debug_log "PROCESS_OBSERVER_BATCH_GUARD_SKIP reason=disabled"; return 1; }
	[[ ${Backup_Mode:-} = true ]] || { _speed_debug_log "PROCESS_OBSERVER_BATCH_GUARD_SKIP reason=backup_mode_apk_only"; return 1; }
	[[ -n ${txt:-} ]] || { _speed_debug_log "PROCESS_OBSERVER_BATCH_GUARD_SKIP reason=empty_applist"; return 1; }
	while IFS= read -r _line; do
		case $_line in ''|\#*|＃*) continue ;; esac
		_name="${_line%% *}"
		_pkg="${_line#* }"; _pkg="${_pkg%% *}"
		[[ -n $_name && -n $_pkg && $_pkg != "$_line" ]] || continue
		case $_name in
		\!*|！*) _speed_debug_log "PROCESS_OBSERVER_BATCH_GUARD_CANDIDATE_SKIP pkg=$_pkg label=$_name reason=no_backupdata"; continue ;;
		esac
		if _process_observer_batch_blacklisted_pkg "$_pkg"; then
			_speed_debug_log "PROCESS_OBSERVER_BATCH_GUARD_CANDIDATE_SKIP pkg=$_pkg label=$_name reason=blacklist_or_no_backupdata"
			continue
		fi
		case $_pkg in bin.mt.plus|bin.mt.plus.canary|com.termux) _speed_debug_log "PROCESS_OBSERVER_BATCH_GUARD_CANDIDATE_SKIP pkg=$_pkg label=$_name reason=self"; continue ;; esac
		_label="$_name"
		_action="$(_process_observer_action_for_pkg "$_pkg" "backup_batch_scope")"
		case $_action in ''|none|off|disable) _speed_debug_log "PROCESS_OBSERVER_BATCH_GUARD_CANDIDATE_SKIP pkg=$_pkg label=$_label reason=action_off"; continue ;; esac
		_log="$(_process_observer_log_path "$_pkg" "$_label" "backup_batch_scope")"
		printf '%s\t%s\t%s\t%s\n' "$_pkg" "$_label" "$_action" "$_log" >> "$_spec" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
		printf '%s\t%s\n' "$_pkg" "$_label" >> "$_pkgs" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
		_count=$((_count + 1))
	done <<EOF_PROCESS_OBSERVER_BATCH_SPEC
$txt
EOF_PROCESS_OBSERVER_BATCH_SPEC
	[[ $_count -gt 0 ]] || { _speed_debug_log "PROCESS_OBSERVER_BATCH_GUARD_SKIP reason=no_data_candidates"; return 1; }
	_speed_debug_log "PROCESS_OBSERVER_BATCH_GUARD_SPEC_READY count=$_count spec=$_spec pkgs=$_pkgs"
	return 0
}
_process_observer_batch_state_prune_main() {
	local _batch="$1" _state _tmp
	[[ -s $_batch ]] || return 0
	_state="$(_process_observer_token_state_file)"
	[[ -s $_state ]] || return 0
	_tmp="$TMPDIR/.process_observer_tokens_prune_${$}_$RANDOM"
	awk -F '\t' 'NR==FNR{del[$1]=1; next} !($1 in del){print $0}' "$_batch" "$_state" > "$_tmp" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} || cp -f "$_state" "$_tmp" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	cat "$_tmp" > "$_state" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} || true
	rm -f "$_tmp" 2>/dev/null
	[[ -s $_state ]] || rm -f "$_state" 2>/dev/null
}
_process_observer_batch_start_backup() {
	local _spec _pkgs _state _out _norm _rc _flat _started _requested
	_process_observer_batch_guard_enabled || return 0
	[[ ${PROCESS_OBSERVER_BATCH_ACTIVE:-0} = 1 ]] && return 0
	_spec="${TMPDIR:-/data/local/tmp}/.speedbackup_process_observer_batch_spec_${$}"
	_pkgs="$(_process_observer_batch_pkgs_file)"
	_state="$(_process_observer_batch_state_file)"
	rm -f "$_spec" "$_pkgs" "$_state" 2>/dev/null
	_process_observer_batch_build_spec "$_spec" "$_pkgs" || { rm -f "$_spec" 2>/dev/null; return 0; }
	_out="$(_webdav_tmp_path process_observer_batch_start_${$}_$RANDOM)"
	_norm="$(_webdav_tmp_path process_observer_batch_start_norm_${$}_$RANDOM)"
	dex_hiddenapi_raw processObserverBatchStart "${USER_ID:-${user:-0}}" "$_spec" > "$_out" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	_rc=$?
	_flat="$(tr '\n' '|' < "$_out" 2>/dev/null | cut -c1-1200)"
	_speed_debug_log "PROCESS_OBSERVER_BATCH_START rc=$_rc out=$_flat"
	# r268: 某些 dex wrapper 會把多行 stdout 壓成單行 pipe-separated；先正規化再解析。
	# 同時避免 awk 變數名 log 撞到內建 log()，否則 Android awk 會噴 Unexpected token 並讓 started=0。
	tr '|' '\n' < "$_out" > "$_norm" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} || cp -f "$_out" "$_norm" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	awk '
		$1=="PROCESS_OBSERVER_BATCH_START_ITEM" {
			token=""; pkg=""; label=""; logp="";
			for (i=2;i<=NF;i++) {
				split($i,a,"=");
				if (a[1]=="token") token=a[2];
				else if (a[1]=="package") pkg=a[2];
				else if (a[1]=="label") label=a[2];
				else if (a[1]=="log") logp=a[2];
			}
			if (token != "" && pkg != "") print token "\t" pkg "\t" label "\tapp\tbackup_batch_scope\t" logp "\tbatch";
		}
	' "$_norm" > "$_state" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	_started="$(awk 'NF{n++} END{print n+0}' "$_state" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null})"
	case $_started in ''|*[!0-9]*) _started=0 ;; esac
	_requested="$(awk 'NF{n++} END{print n+0}' "$_pkgs" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null})"
	case $_requested in ''|*[!0-9]*) _requested=0 ;; esac
	_speed_debug_log "PROCESS_OBSERVER_BATCH_START_PARSE requested=$_requested parsed=$_started mode=pipe-normalized"
	if [[ $_rc = 0 && $_started -gt 0 ]]; then
		cat "$_state" >> "$(_process_observer_token_state_file)" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} || true
		PROCESS_OBSERVER_BATCH_ACTIVE=1
		PROCESS_OBSERVER_BATCH_STATE="$_state"
		PROCESS_OBSERVER_BATCH_PKGS="$_pkgs"
		PROCESS_OBSERVER_BATCH_SCOPE="backup_batch"
		_speed_debug_log "PROCESS_OBSERVER_BATCH_GUARD_READY started=$_started state=$_state pkgs=$_pkgs lifecycle=batch-watchset parser=r268"
	else
		_speed_debug_log "PROCESS_OBSERVER_BATCH_GUARD_FAIL rc=$_rc started=$_started requested=$_requested spec=$_spec parser=r268"
		rm -f "$_state" "$_pkgs" 2>/dev/null
	fi
	rm -f "$_spec" "$_out" "$_norm" 2>/dev/null
	return 0
}

_process_observer_restore_session_enabled() {
	case "${SPEEDBACKUP_RESTORE_GUARD_SESSION:-1}" in
	0|false|FALSE|no|NO|off|OFF|disable|DISABLE) return 1 ;;
	esac
	_process_observer_guard_enabled || return 1
	_process_observer_batch_capability_ok || return 1
	return 0
}
_process_observer_restore_session_action_fast() {
	local _pkg="$1" _home="$2" _ime="$3" _policy="${SPEEDBACKUP_PROCESS_OBSERVER_POLICY:-smart}" _action
	[[ -n $_pkg ]] || return 1
	# r425: restore session spec 是 100+ App 熱路徑；不能逐 App 呼叫
	# _process_observer_action_for_pkg，避免反覆 ensure default HOME/IME。
	case $_pkg in
		com.tencent.mm|com.tencent.mobileqq|com.tencent.tim|com.tencent.wework|com.eg.android.AlipayGphone|com.taobao.taobao|com.ss.android.ugc.aweme|com.baidu.input*)
			printf '%s\n' "cgroup-freeze"; return 0 ;;
	esac
	[[ -n $_home && $_pkg = "$_home" ]] && { printf '%s\n' "cgroup-freeze"; return 0; }
	[[ -n $_ime && $_pkg = "$_ime" ]] && { printf '%s\n' "cgroup-freeze"; return 0; }
	_process_observer_pkg_in_words "$_pkg" "${SPEEDBACKUP_CGROUP_FAST_SETTLE_PACKAGES:-}" && { printf '%s\n' "cgroup-freeze"; return 0; }
	if _pkg_is_quiesce_never_pause "$_pkg"; then
		printf '%s\n' "monitor"
		return 0
	fi
	case $_policy in
	all|full|restricted|guard-stop-restricted)
		_action="guard-stop-restricted" ;;
	basic|lite|force-stop|guard-stop)
		_action="guard-stop:nologd" ;;
	appops|guard-stop-appops)
		_action="guard-stop-appops" ;;
	monitor|log|none|off|disable)
		_action="$_policy" ;;
	smart|auto|*)
		if _process_observer_high_risk_pkg "$_pkg"; then
			_action="guard-stop-restricted"
		else
			_action="guard-stop:nologd"
		fi ;;
	esac
	[[ -n ${SPEEDBACKUP_PROCESS_OBSERVER_ACTION:-} ]] && _action="$SPEEDBACKUP_PROCESS_OBSERVER_ACTION"
	printf '%s\n' "$_action"
}

# r441: compare-map 可能是整個備份來源的全量表；單選/子集恢復時不能用全量 compare-map 建 restore session，
# 否則會出現「恢復 1 個 app，但批量守護 117 / 高風險守護 4」的過寬守護範圍。
_process_observer_restore_session_compare_map_scope_ok() {
	local _cmp="$1" _stage="${2:-unknown}" _cmp_rows _sel_rows
	case "${SPEEDBACKUP_RESTORE_GUARD_SESSION_ALLOW_WIDE_COMPARE:-0}" in
	1|true|TRUE|yes|YES|on|ON|enable|ENABLE)
		_speed_debug_log "RESTORE_GUARD_SESSION_COMPARE_SCOPE_WIDE_ALLOWED stage=$_stage reason=env-override mode=r441"
		return 0
		;;
	esac
	[[ -s $_cmp ]] || return 1
	_cmp_rows="$(awk -F '	' '
		NR==1 {next}
		/^#/ {next}
		NF >= 3 && $3 ~ /^[A-Za-z0-9_]+(\.[A-Za-z0-9_]+)+$/ {c++}
		END {print c+0}
	' "$_cmp" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null})"
	_sel_rows="$(printf '%s\n' "${txt:-}" | awk '
		NF != 0 {c++}
		END {print c+0}
	' 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null})"
	case $_cmp_rows in ''|*[!0-9]*) _cmp_rows=0 ;; esac
	case $_sel_rows in ''|*[!0-9]*) _sel_rows=0 ;; esac
	if [[ $_sel_rows -gt 0 && $_cmp_rows -gt $_sel_rows ]]; then
		_speed_debug_log "RESTORE_GUARD_SESSION_COMPARE_SCOPE_SKIP stage=$_stage reason=selected-subset cmpRows=$_cmp_rows selectedRows=$_sel_rows action=parse-effective-list mode=r441"
		return 1
	fi
	_speed_debug_log "RESTORE_GUARD_SESSION_COMPARE_SCOPE_OK stage=$_stage cmpRows=$_cmp_rows selectedRows=$_sel_rows mode=r441"
	return 0
}

_process_observer_restore_session_build_from_compare_map() {
	local _spec="$1" _pkgs="$2" _cmp _tmp _pkg _label _action _log _count=0 _t0 _elapsed _home _ime
	_t0="$(_speed_now_ms)"
	_cmp="${TMPDIR:-/data/local/tmp}/.restore_package_compare_map.tsv"
	[[ -s $_cmp ]] || _cmp="${SPEED_DEBUG_RUN_DIR:-}/restore_package_compare_map.tsv"
	[[ -s $_cmp ]] || return 1
	_process_observer_restore_session_compare_map_scope_ok "$_cmp" "tools-build-spec" || return 1
	_tmp="${TMPDIR:-/data/local/tmp}/.restore_guard_session_compare_${$}_$RANDOM"
	_home=""; _ime=""
	case "${SPEEDBACKUP_CGROUP_FAST_SETTLE_DEFAULT_HOME:-1}" in 0|false|FALSE|no|NO|off|OFF|disable|DISABLE) ;; *) _default_home_pkg_ensure >/dev/null 2>&1 || true; _home="${_DEFAULT_HOME_PKG_CACHE:-}" ;; esac
	case "${SPEEDBACKUP_CGROUP_FAST_SETTLE_DEFAULT_IME:-1}" in 0|false|FALSE|no|NO|off|OFF|disable|DISABLE) ;; *) _default_ime_pkg_ensure >/dev/null 2>&1 || true; _ime="${_DEFAULT_IME_PKG_CACHE:-}" ;; esac
	awk -F '	' '
		NR==1 {next}
		/^#/ {next}
		NF >= 3 {
			pkg=$3; label=$2;
			if (pkg ~ /^[A-Za-z0-9_]+(\.[A-Za-z0-9_]+)+$/ && !seen[pkg]++) print pkg "	" label;
		}
	' "$_cmp" > "$_tmp" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} || { rm -f "$_tmp" 2>/dev/null; return 1; }
	while IFS='	' read -r _pkg _label; do
		[[ -n $_pkg ]] || continue
		case $_pkg in bin.mt.plus|bin.mt.plus.canary|com.termux) _speed_debug_log "RESTORE_GUARD_SESSION_CANDIDATE_SKIP pkg=$_pkg label=$_label reason=self mode=r427"; continue ;; esac
		[[ -n $_label ]] || _label="$_pkg"
		_action="$(_process_observer_restore_session_action_fast "$_pkg" "$_home" "$_ime")"
		case $_action in ''|none|off|disable) _speed_debug_log "RESTORE_GUARD_SESSION_CANDIDATE_SKIP pkg=$_pkg label=$_label reason=action_off source=compare_map mode=r427"; continue ;; esac
		_log="$(_process_observer_log_path "$_pkg" "$_label" "restore_session")"
		printf '%s	%s	%s	%s
' "$_pkg" "$_label" "$_action" "$_log" >> "$_spec" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
		printf '%s	%s
' "$_pkg" "$_label" >> "$_pkgs" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
		_count=$((_count + 1))
	done < "$_tmp"
	rm -f "$_tmp" 2>/dev/null
	[[ $_count -gt 0 ]] || return 1
	_elapsed=$(( $(_speed_now_ms) - _t0 ))
	_speed_debug_log "RESTORE_GUARD_SESSION_SPEC_READY count=$_count spec=$_spec pkgs=$_pkgs policy=restore-session-auto parse=compare-map-fast source=${_cmp##*/} elapsedMs=$_elapsed home=${_home:-none} ime=${_ime:-none} mode=r427"
	return 0
}

_process_observer_restore_session_build_spec() {
	local _spec="$1" _pkgs="$2" _line _work _name _pkg _label _action _log _count=0 _appd _pkg_token
	: > "$_spec" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} || return 1
	: > "$_pkgs" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} || return 1
	_process_observer_restore_session_enabled || { _speed_debug_log "RESTORE_GUARD_SESSION_SKIP reason=disabled_or_missing_capability mode=r427"; return 1; }
	[[ -n ${txt:-} ]] || { _speed_debug_log "RESTORE_GUARD_SESSION_SKIP reason=empty_applist mode=r427"; return 1; }
	# r424: compare map 已在恢復前建立，直接用 label/package TSV 建 session，避免逐 App jq 讀 app_details 導致守護 session 啟動卡數十秒。
	if _process_observer_restore_session_build_from_compare_map "$_spec" "$_pkgs"; then
		return 0
	fi
	while IFS= read -r _line; do
		case $_line in ''|\#*|＃*) continue ;; esac
		_work="$(printf '%s\n' "$_line" | sed 's/^[ 	]*//;s/[ 	]*$//')"
		case "$_work" in
		!play[[:space:]]*|！play[[:space:]]*)
			_work="${_work#*!play}"; _work="${_work#*！play}"; _work="$(printf '%s\n' "$_work" | sed 's/^[ 	]*//;s/[ 	]*$//')" ;;
		![[:space:]]*|！[[:space:]]*|!*)
			_work="${_work#!}"; _work="${_work#！}"; _work="$(printf '%s\n' "$_work" | sed 's/^[ 	]*//;s/[ 	]*$//')" ;;
		esac
		_name=""; _pkg=""; _label=""
		# r423: 遠端流式恢復的 appList_network 可能只有資料夾/顯示名稱；包名必須從已解包的 app_details_bundle stage 取得。
		_appd="${TMPDIR:-/data/local/tmp}/.restore_stage/$_work/app_details.json"
		if [[ -s $_appd ]] && _appdetails_json_parse_ok "$_appd"; then
			_pkg="$(_appdetails_get_first_pkg "$_appd")"
			_label="$(_appdetails_get_first_entry_name "$_appd")"
			[[ -n $_label ]] || _label="$_work"
			_name="$_label"
		else
			# 一般本地 appList 允許空格或 tab 分隔；包名可被括號包住。
			_pkg_token="$(printf '%s\n' "$_work" | awk '{for(i=1;i<=NF;i++){t=$i; gsub(/^[!！(（]+/,"",t); gsub(/[)）,;]+$/,"",t); if(t ~ /^[A-Za-z0-9_]+(\.[A-Za-z0-9_]+)+$/){print t; exit}}}' 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null})"
			_pkg="$_pkg_token"
			if [[ -n $_pkg ]]; then
				_name="$(printf '%s\n' "$_work" | awk -v p="$_pkg" '{out=""; for(i=1;i<=NF;i++){t=$i; gsub(/^[!！(（]+/,"",t); gsub(/[)）,;]+$/,"",t); if(t==p) break; out=(out?out" ":"")$i} print out}' 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null})"
				[[ -n $_name ]] || _name="$_pkg"
				_label="$_name"
			fi
		fi
		[[ -n $_pkg ]] || { _speed_debug_log "RESTORE_GUARD_SESSION_CANDIDATE_SKIP line=$_work reason=no_pkg_or_stage_appdetails mode=r427"; continue; }
		case $_pkg in bin.mt.plus|bin.mt.plus.canary|com.termux) _speed_debug_log "RESTORE_GUARD_SESSION_CANDIDATE_SKIP pkg=$_pkg label=$_name reason=self mode=r427"; continue ;; esac
		[[ -n $_label ]] || _label="${_name:-$_pkg}"
		_action="$(_process_observer_action_for_pkg "$_pkg" "restore_app_scope")"
		case $_action in ''|none|off|disable) _speed_debug_log "RESTORE_GUARD_SESSION_CANDIDATE_SKIP pkg=$_pkg label=$_label reason=action_off mode=r427"; continue ;; esac
		_log="$(_process_observer_log_path "$_pkg" "$_label" "restore_session")"
		printf '%s	%s	%s	%s\n' "$_pkg" "$_label" "$_action" "$_log" >> "$_spec" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
		printf '%s	%s\n' "$_pkg" "$_label" >> "$_pkgs" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
		_count=$((_count + 1))
	done <<EOF_PROCESS_OBSERVER_RESTORE_SESSION_SPEC
$txt
EOF_PROCESS_OBSERVER_RESTORE_SESSION_SPEC
	[[ $_count -gt 0 ]] || { _speed_debug_log "RESTORE_GUARD_SESSION_SKIP reason=no_restore_candidates mode=r427"; return 1; }
	_speed_debug_log "RESTORE_GUARD_SESSION_SPEC_READY count=$_count spec=$_spec pkgs=$_pkgs policy=restore-session-auto parse=stage-or-whitespace mode=r427"
	return 0
}

_process_observer_restore_session_direct_capability_ok() {
	case "${SPEEDBACKUP_RESTORE_GUARD_SESSION_DIRECT_DEX:-1}" in
	0|false|FALSE|no|NO|off|OFF|disable|DISABLE) return 1 ;;
	esac
	local _cap="" _out="" _in=""
	if [[ -n ${SPEED_DEBUG_RUN_DIR:-} && -s ${SPEED_DEBUG_RUN_DIR:-}/appstate_capabilities.json ]]; then
		_cap="${SPEED_DEBUG_RUN_DIR}/appstate_capabilities.json"
	else
		_in="$(_webdav_tmp_path restore_session_direct_cap_in_${$}_$RANDOM)"
		_out="$(_webdav_tmp_path restore_session_direct_cap_out_${$}_$RANDOM)"
		printf '{}\n' > "$_in" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} || true
		if _root_appstate_call capabilities "$_in" "$_out" >/dev/null 2>&1 && [[ -s $_out ]]; then
			_cap="$_out"
		fi
	fi
	if [[ -s $_cap ]] && jq -e '
		. as $root |
		(any($root.capabilities[]?; .name == "dex.process_observer.restore_session_direct_start.v1" and .enabled == true)) and
		(any($root.capabilities[]?; .name == "dex.process_observer.restore_session_facts_cache.v1" and .enabled == true)) and
		(any($root.capabilities[]?; .name == "dex.process_observer.restore_action_policy_builder.v1" and .enabled == true)) and
		(any($root.capabilities[]?; .name == "dex.process_observer.batch_stop_summary_tsv.v1" and .enabled == true))
	' "$_cap" >/dev/null 2>&1; then
		case "$_out" in "$TMPDIR"/*) rm -f "$_out" 2>/dev/null ;; esac
		case "$_in" in "$TMPDIR"/*) rm -f "$_in" 2>/dev/null ;; esac
		return 0
	fi
	case "$_out" in "$TMPDIR"/*) rm -f "$_out" 2>/dev/null ;; esac
	case "$_in" in "$TMPDIR"/*) rm -f "$_in" 2>/dev/null ;; esac
	return 1
}

_process_observer_restore_session_direct_start() {
	local _pkgs="$1" _state="$2" _cmp _out _norm _rc _flat _started _requested _log _policy _base_policy _home_flag _ime_flag _hard_csv _facts _t0 _elapsed _facts_rows
	_process_observer_restore_session_direct_capability_ok || return 1
	_cmp="${TMPDIR:-/data/local/tmp}/.restore_package_compare_map.tsv"
	[[ -s $_cmp ]] || _cmp="${SPEED_DEBUG_RUN_DIR:-}/restore_package_compare_map.tsv"
	[[ -s $_cmp ]] || return 1
	_process_observer_restore_session_compare_map_scope_ok "$_cmp" "dex-direct-start" || return 1
	_t0="$(_speed_now_ms)"
	_home_flag=1; _ime_flag=1
	case "${SPEEDBACKUP_CGROUP_FAST_SETTLE_DEFAULT_HOME:-1}" in 0|false|FALSE|no|NO|off|OFF|disable|DISABLE) _home_flag=0 ;; esac
	case "${SPEEDBACKUP_CGROUP_FAST_SETTLE_DEFAULT_IME:-1}" in 0|false|FALSE|no|NO|off|OFF|disable|DISABLE) _ime_flag=0 ;; esac
	_hard_csv="$(printf '%s\n' "${SPEEDBACKUP_CGROUP_FAST_SETTLE_PACKAGES:-}" | tr ' ;' ',,' | sed 's/,,*/,/g;s/^,//;s/,$//' 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null})"
	_base_policy="${SPEEDBACKUP_PROCESS_OBSERVER_POLICY:-smart}"
	_policy="${_base_policy};home=${_home_flag};ime=${_ime_flag}"
	[[ -n $_hard_csv ]] && _policy="${_policy};hard=${_hard_csv}"
	if [[ -n ${SPEED_DEBUG_RUN_DIR:-} && -d ${SPEED_DEBUG_RUN_DIR:-} ]]; then
		_log="$SPEED_DEBUG_RUN_DIR/process_observer_restore_app_scope.log"
		_facts="$SPEED_DEBUG_RUN_DIR/restore_session_facts.tsv"
	else
		_log="${TMPDIR:-/data/local/tmp}/process_observer_restore_app_scope.log"
		_facts="${TMPDIR:-/data/local/tmp}/restore_session_facts.tsv"
	fi
	_out="$(_webdav_tmp_path restore_guard_session_direct_${$}_$RANDOM)"
	_norm="$(_webdav_tmp_path restore_guard_session_direct_norm_${$}_$RANDOM)"
	rm -f "$_pkgs" "$_state" "$_facts" 2>/dev/null
	_speed_debug_log "RESTORE_GUARD_SESSION_DIRECT_BEGIN user=${USER_ID:-${user:-0}} compare=${_cmp##*/} pkgs=$_pkgs facts=$_facts policy=$_policy policyBuilder=dex-r430 home=dex ime=dex mode=r433"
	dex_hiddenapi_raw processObserverRestoreSessionStart "${USER_ID:-${user:-0}}" "$_cmp" "$_pkgs" "$_policy" "$_log" "-" "-" "$_facts" > "$_out" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	_rc=$?
	if [[ $_rc = 0 ]]; then
		_eventwait_file_size_stable_ms "$_facts" 80 1200 restore_session_facts_ready >/dev/null 2>&1 || true
	fi
	_flat="$(tr '\n' '|' < "$_out" 2>/dev/null | cut -c1-1600)"
	_speed_debug_log "RESTORE_GUARD_SESSION_DIRECT_SENT rc=$_rc out=$_flat"
	tr '|' '\n' < "$_out" > "$_norm" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} || cp -f "$_out" "$_norm" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	awk '
		$1=="PROCESS_OBSERVER_BATCH_START_ITEM" {
			token=""; pkg=""; label=""; logp=""; action=""; actionReason="";
			for (i=2;i<=NF;i++) {
				split($i,a,"=");
				if (a[1]=="token") token=a[2];
				else if (a[1]=="package") pkg=a[2];
				else if (a[1]=="label") label=a[2];
				else if (a[1]=="log") logp=a[2];
				else if (a[1]=="action") action=a[2];
				else if (a[1]=="actionReason") actionReason=a[2];
			}
			if (token != "" && pkg != "") print token "\t" pkg "\t" label "\tapp\trestore_app_scope\t" logp "\trestore_session\t" action "\t" actionReason;
		}
	' "$_norm" > "$_state" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	_started="$(awk 'NF{n++} END{print n+0}' "$_state" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null})"
	_requested="$(awk 'NF{n++} END{print n+0}' "$_pkgs" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null})"
	if [[ -s $_facts ]]; then
		_facts_rows="$(awk 'BEGIN{n=0} /^[^#]/ && NF{n++} END{print n+0}' "$_facts" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null})"
	else
		_facts_rows=0
		_speed_debug_log "RESTORE_GUARD_SESSION_FACTS_MISSING path=$_facts rc=$_rc mode=r433"
	fi
	case $_started in ''|*[!0-9]*) _started=0 ;; esac
	case $_requested in ''|*[!0-9]*) _requested=0 ;; esac
	case $_facts_rows in ''|*[!0-9]*) _facts_rows=0 ;; esac
	_elapsed=$(( $(_speed_now_ms) - _t0 ))
	if [[ $_rc = 0 && $_started -gt 0 ]] && grep -F 'PROCESS_OBSERVER_RESTORE_SESSION_DIRECT_START_OK' "$_out" >/dev/null 2>&1; then
		cat "$_state" >> "$(_process_observer_token_state_file)" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} || true
		PROCESS_OBSERVER_BATCH_ACTIVE=1
		PROCESS_OBSERVER_BATCH_STATE="$_state"
		PROCESS_OBSERVER_BATCH_PKGS="$_pkgs"
		PROCESS_OBSERVER_BATCH_SCOPE="restore_session"
		_speed_debug_log "RESTORE_GUARD_SESSION_READY requested=$_requested started=$_started state=$_state pkgs=$_pkgs facts=$_facts factsRows=$_facts_rows lifecycle=batch-watchset policy=dex-direct-restore-session policyBuilder=dex-r430 release=bulk-post-appstate elapsedMs=$_elapsed mode=r433"
		rm -f "$_out" "$_norm" 2>/dev/null
		return 0
	fi
	_speed_debug_log "RESTORE_GUARD_SESSION_DIRECT_FALLBACK rc=$_rc requested=$_requested started=$_started factsRows=$_facts_rows elapsedMs=$_elapsed out=$_flat mode=r433"
	rm -f "$_out" "$_norm" "$_pkgs" "$_state" 2>/dev/null
	return 1
}

_process_observer_restore_session_start() {
	local _spec _pkgs _state _out _norm _rc _flat _started _requested
	_process_observer_restore_session_enabled || return 0
	[[ ${PROCESS_OBSERVER_BATCH_ACTIVE:-0} = 1 ]] && { _speed_debug_log "RESTORE_GUARD_SESSION_SKIP reason=batch_already_active scope=${PROCESS_OBSERVER_BATCH_SCOPE:-unknown} mode=r427"; return 0; }
	_spec="${TMPDIR:-/data/local/tmp}/.speedbackup_restore_guard_session_spec_${$}"
	_pkgs="$(_process_observer_batch_pkgs_file)"
	_state="$(_process_observer_batch_state_file)"
	rm -f "$_spec" "$_pkgs" "$_state" 2>/dev/null
	if _process_observer_restore_session_direct_start "$_pkgs" "$_state"; then
		rm -f "$_spec" 2>/dev/null
		return 0
	fi
	rm -f "$_pkgs" "$_state" 2>/dev/null
	_process_observer_restore_session_build_spec "$_spec" "$_pkgs" || { rm -f "$_spec" "$_pkgs" "$_state" 2>/dev/null; return 0; }
	_out="$(_webdav_tmp_path restore_guard_session_start_${$}_$RANDOM)"
	_norm="$(_webdav_tmp_path restore_guard_session_start_norm_${$}_$RANDOM)"
	_speed_debug_log "RESTORE_GUARD_SESSION_BEGIN user=${USER_ID:-${user:-0}} spec=$_spec state=$_state policy=tools-owner-dex-events-c-exec mode=r427"
	dex_hiddenapi_raw processObserverBatchStart "${USER_ID:-${user:-0}}" "$_spec" > "$_out" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	_rc=$?
	_flat="$(tr '\n' '|' < "$_out" 2>/dev/null | cut -c1-1400)"
	_speed_debug_log "RESTORE_GUARD_SESSION_POLICY_SENT rc=$_rc out=$_flat"
	tr '|' '\n' < "$_out" > "$_norm" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} || cp -f "$_out" "$_norm" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	awk '
		$1=="PROCESS_OBSERVER_BATCH_START_ITEM" {
			token=""; pkg=""; label=""; logp="";
			for (i=2;i<=NF;i++) {
				split($i,a,"=");
				if (a[1]=="token") token=a[2];
				else if (a[1]=="package") pkg=a[2];
				else if (a[1]=="label") label=a[2];
				else if (a[1]=="log") logp=a[2];
			}
			if (token != "" && pkg != "") print token "\t" pkg "\t" label "\tapp\trestore_app_scope\t" logp "\trestore_session";
		}
	' "$_norm" > "$_state" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	_started="$(awk 'NF{n++} END{print n+0}' "$_state" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null})"
	_requested="$(awk 'NF{n++} END{print n+0}' "$_pkgs" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null})"
	case $_started in ''|*[!0-9]*) _started=0 ;; esac
	case $_requested in ''|*[!0-9]*) _requested=0 ;; esac
	if [[ $_rc = 0 && $_started -gt 0 ]]; then
		cat "$_state" >> "$(_process_observer_token_state_file)" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} || true
		PROCESS_OBSERVER_BATCH_ACTIVE=1
		PROCESS_OBSERVER_BATCH_STATE="$_state"
		PROCESS_OBSERVER_BATCH_PKGS="$_pkgs"
		PROCESS_OBSERVER_BATCH_SCOPE="restore_session"
		_speed_debug_log "RESTORE_GUARD_SESSION_READY requested=$_requested started=$_started state=$_state pkgs=$_pkgs lifecycle=batch-watchset policy=dex-auto-c-exec release=bulk-post-appstate mode=r427"
	else
		_speed_debug_log "RESTORE_GUARD_SESSION_FAIL rc=$_rc requested=$_requested started=$_started spec=$_spec out=$_flat mode=r427"
		rm -f "$_state" "$_pkgs" 2>/dev/null
	fi
	rm -f "$_spec" "$_out" "$_norm" 2>/dev/null
	return 0
}

_process_observer_batch_stop() {
	local _reason="${1:-batch-stop}" _state="${PROCESS_OBSERVER_BATCH_STATE:-}" _pkgs="${PROCESS_OBSERVER_BATCH_PKGS:-}" _out _rc _flat _requested _stopped _recovered _missing _failed _sum _summary
	[[ -n $_state && -s $_state ]] || { PROCESS_OBSERVER_BATCH_ACTIVE=0; PROCESS_OBSERVER_BATCH_SCOPE=""; return 0; }
	_out="$(_webdav_tmp_path process_observer_batch_stop_${$}_$RANDOM)"
	if [[ -n ${SPEED_DEBUG_RUN_DIR:-} && -d ${SPEED_DEBUG_RUN_DIR:-} ]]; then
		_summary="$SPEED_DEBUG_RUN_DIR/process_observer_batch_stop_summary.tsv"
	else
		_summary="${TMPDIR:-/data/local/tmp}/process_observer_batch_stop_summary.tsv"
	fi
	rm -f "$_summary" 2>/dev/null
	_requested="$(awk 'NF{n++} END{print n+0}' "$_state" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null})"
	case $_requested in ''|*[!0-9]*) _requested=0 ;; esac
	[[ $_requested -gt 0 ]] && _speedbackup_progress_step 0 "$_requested" "正在解除批量喚醒守護" "process_observer_batch_stop" "107"
	_speed_debug_log "PROCESS_OBSERVER_BATCH_STOP_BEGIN reason=$_reason requested=$_requested state=$_state summary=$_summary mode=r433"
	dex_hiddenapi_raw processObserverBatchStop "$_state" "${USER_ID:-${user:-0}}" "$_summary" > "$_out" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	_rc=$?
	if [[ $_rc = 0 ]]; then
		_eventwait_file_size_stable_ms "$_summary" 80 1200 process_observer_batch_stop_summary_ready >/dev/null 2>&1 || true
	fi
	_flat="$(tr '\n' '|' < "$_out" 2>/dev/null | cut -c1-1400)"
	_requested="$(printf '%s\n' "$_flat" | sed -n 's/.*requested=\([0-9][0-9]*\).*/\1/p' | head -n 1)"
	_stopped="$(printf '%s\n' "$_flat" | sed -n 's/.*stopped=\([0-9][0-9]*\).*/\1/p' | head -n 1)"
	_recovered="$(printf '%s\n' "$_flat" | sed -n 's/.*recovered=\([0-9][0-9]*\).*/\1/p' | head -n 1)"
	_missing="$(printf '%s\n' "$_flat" | sed -n 's/.*missing=\([0-9][0-9]*\).*/\1/p' | head -n 1)"
	_failed="$(printf '%s\n' "$_flat" | sed -n 's/.*failed=\([0-9][0-9]*\).*/\1/p' | head -n 1)"
	case $_requested in ''|*[!0-9]*) _requested=0 ;; esac
	case $_stopped in ''|*[!0-9]*) _stopped=0 ;; esac
	case $_recovered in ''|*[!0-9]*) _recovered=0 ;; esac
	case $_missing in ''|*[!0-9]*) _missing=0 ;; esac
	case $_failed in ''|*[!0-9]*) _failed=0 ;; esac
	_speed_debug_log "PROCESS_OBSERVER_BATCH_STOP reason=$_reason rc=$_rc requested=$_requested stopped=$_stopped recovered=$_recovered missing=$_missing failed=$_failed summary=$_summary out=$_flat"
	_sum=$((_stopped + _recovered))
	if [[ $_rc = 0 && $_requested -gt 0 && $_requested = $_sum && $_missing = 0 && $_failed = 0 ]] && grep -F 'PROCESS_OBSERVER_BATCH_STOP_OK' "$_out" >/dev/null 2>&1 && grep -F 'restoreOk=true' "$_out" >/dev/null 2>&1 && grep -F 'stateDeleted=true' "$_out" >/dev/null 2>&1; then
		_process_observer_batch_state_prune_main "$_state" || true
		rm -f "$_state" "$_pkgs" "$_out" 2>/dev/null
		PROCESS_OBSERVER_BATCH_ACTIVE=0
		PROCESS_OBSERVER_BATCH_STATE=""
		PROCESS_OBSERVER_BATCH_PKGS=""
		PROCESS_OBSERVER_BATCH_SCOPE=""
		[[ $_requested -gt 0 ]] && _speedbackup_progress_step "$_requested" "$_requested" "批量喚醒守護已解除" "process_observer_batch_stop" "107"
		_speed_debug_log "PROCESS_OBSERVER_BATCH_STOP_CLEANUP_OK reason=$_reason requested=$_requested stopped=$_stopped recovered=$_recovered stateDeleted=true summary=$_summary mode=r433"
		return 0
	fi
	_speed_debug_log "PROCESS_OBSERVER_BATCH_STOP_RETAIN_STATE reason=$_reason rc=$_rc requested=$_requested stopped=$_stopped recovered=$_recovered missing=$_missing failed=$_failed state=$_state pkgs=$_pkgs stateRetained=true mode=r296"
	rm -f "$_out" 2>/dev/null
	PROCESS_OBSERVER_BATCH_ACTIVE=1
	PROCESS_OBSERVER_BATCH_STATE="$_state"
	PROCESS_OBSERVER_BATCH_PKGS="$_pkgs"
	return 1
}

# r297: batch observer 仍一次 start，改為每個 App 完成後釋放該 App 的 token。
# 目的：保留 r296 batch start 減少 round-trip，同時避免已備份完成的 App 一直被 watch-set
# 擋到整個 App phase / Media phase 結束才可正常使用。
_process_observer_batch_release_pkg() {
	local _pkg="$1" _label="$2" _reason="${3:-app-scope-done}" _state="${PROCESS_OBSERVER_BATCH_STATE:-}" _pkgs="${PROCESS_OBSERVER_BATCH_PKGS:-}"
	local _subset _remain _pkgtmp _out _rc _flat _requested _stopped _recovered _missing _failed _sum
	[[ -n $_pkg && ${PROCESS_OBSERVER_BATCH_ACTIVE:-0} = 1 && -s $_state ]] || return 0
	_subset="$(_webdav_tmp_path process_observer_batch_release_${$}_$RANDOM)"
	_remain="$(_webdav_tmp_path process_observer_batch_remain_${$}_$RANDOM)"
	_pkgtmp="$(_webdav_tmp_path process_observer_batch_pkgs_${$}_$RANDOM)"
	_out="$(_webdav_tmp_path process_observer_batch_release_out_${$}_$RANDOM)"
	awk -F '	' -v p="$_pkg" '$2==p{print $0}' "$_state" > "$_subset" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	_requested="$(awk 'NF{n++} END{print n+0}' "$_subset" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null})"
	case $_requested in ''|*[!0-9]*) _requested=0 ;; esac
	if [[ $_requested -le 0 ]]; then
		[[ -s $_pkgs ]] && awk -F '	' -v p="$_pkg" '$1!=p{print $0}' "$_pkgs" > "$_pkgtmp" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} && cat "$_pkgtmp" > "$_pkgs" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
		rm -f "$_subset" "$_remain" "$_pkgtmp" "$_out" 2>/dev/null
		_speed_debug_log "PROCESS_OBSERVER_BATCH_RELEASE_PKG_SKIP pkg=$_pkg label=$_label reason=$_reason state=no-token mode=r297"
		return 0
	fi
	dex_hiddenapi_raw processObserverBatchStop "$_subset" "${USER_ID:-${user:-0}}" > "$_out" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	_rc=$?
	_flat="$(tr '\n' '|' < "$_out" 2>/dev/null | cut -c1-1000)"
	_stopped="$(printf '%s\n' "$_flat" | sed -n 's/.*stopped=\([0-9][0-9]*\).*/\1/p' | head -n 1)"
	_recovered="$(printf '%s\n' "$_flat" | sed -n 's/.*recovered=\([0-9][0-9]*\).*/\1/p' | head -n 1)"
	_missing="$(printf '%s\n' "$_flat" | sed -n 's/.*missing=\([0-9][0-9]*\).*/\1/p' | head -n 1)"
	_failed="$(printf '%s\n' "$_flat" | sed -n 's/.*failed=\([0-9][0-9]*\).*/\1/p' | head -n 1)"
	case $_stopped in ''|*[!0-9]*) _stopped=0 ;; esac
	case $_recovered in ''|*[!0-9]*) _recovered=0 ;; esac
	case $_missing in ''|*[!0-9]*) _missing=0 ;; esac
	case $_failed in ''|*[!0-9]*) _failed=0 ;; esac
	_sum=$((_stopped + _recovered))
	_speed_debug_log "PROCESS_OBSERVER_BATCH_RELEASE_PKG reason=$_reason pkg=$_pkg label=$_label rc=$_rc requested=$_requested stopped=$_stopped recovered=$_recovered missing=$_missing failed=$_failed out=$_flat"
	if [[ $_rc = 0 && $_requested = $_sum && $_missing = 0 && $_failed = 0 ]] && grep -F 'PROCESS_OBSERVER_BATCH_STOP_OK' "$_out" >/dev/null 2>&1 && grep -F 'restoreOk=true' "$_out" >/dev/null 2>&1 && grep -F 'stateDeleted=true' "$_out" >/dev/null 2>&1; then
		_process_observer_batch_state_prune_main "$_subset" || true
		awk -F '	' -v p="$_pkg" '$2!=p{print $0}' "$_state" > "$_remain" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} || cp -f "$_state" "$_remain" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
		cat "$_remain" > "$_state" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} || true
		[[ -s $_pkgs ]] && awk -F '	' -v p="$_pkg" '$1!=p{print $0}' "$_pkgs" > "$_pkgtmp" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} && cat "$_pkgtmp" > "$_pkgs" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
		if [[ ! -s $_state ]]; then
			rm -f "$_state" "$_pkgs" 2>/dev/null
			PROCESS_OBSERVER_BATCH_ACTIVE=0
			PROCESS_OBSERVER_BATCH_STATE=""
			PROCESS_OBSERVER_BATCH_PKGS=""
			PROCESS_OBSERVER_BATCH_SCOPE=""
		fi
		rm -f "$_subset" "$_remain" "$_pkgtmp" "$_out" 2>/dev/null
		_speed_debug_log "PROCESS_OBSERVER_BATCH_RELEASE_PKG_OK reason=$_reason pkg=$_pkg label=$_label requested=$_requested stopped=$_stopped recovered=$_recovered stateDeleted=true mode=r297"
		return 0
	fi
	rm -f "$_subset" "$_remain" "$_pkgtmp" "$_out" 2>/dev/null
	_speed_debug_log "PROCESS_OBSERVER_BATCH_RELEASE_PKG_RETAIN_STATE reason=$_reason pkg=$_pkg label=$_label rc=$_rc requested=$_requested stopped=$_stopped recovered=$_recovered missing=$_missing failed=$_failed stateRetained=true mode=r297"
	return 1
}

_process_observer_pkg_in_words() {
	local _pkg="$1" _list="$2" _p
	[[ -n $_pkg && -n $_list ]] || return 1
	for _p in $_list; do
		[[ $_pkg = "$_p" ]] && return 0
	done
	return 1
}

_speedbackup_cgroup_fast_settle_default_home_pkg() {
	local _pkg="$1" _home
	[[ -n $_pkg ]] || return 1
	case "${SPEEDBACKUP_CGROUP_FAST_SETTLE_DEFAULT_HOME:-1}" in
	0|false|FALSE|no|NO|off|OFF|disable|DISABLE) return 1 ;;
	esac
	_default_home_pkg_ensure >/dev/null 2>&1 || true
	_home="${_DEFAULT_HOME_PKG_CACHE:-}"
	[[ -n $_home && $_pkg = "$_home" ]]
}

_speedbackup_cgroup_fast_settle_default_ime_pkg() {
	local _pkg="$1" _ime
	[[ -n $_pkg ]] || return 1
	case "${SPEEDBACKUP_CGROUP_FAST_SETTLE_DEFAULT_IME:-1}" in
	0|false|FALSE|no|NO|off|OFF|disable|DISABLE) return 1 ;;
	esac
	_default_ime_pkg_ensure >/dev/null 2>&1 || true
	_ime="${_DEFAULT_IME_PKG_CACHE:-}"
	[[ -n $_ime && $_pkg = "$_ime" ]]
}


_speedbackup_cgroup_fast_settle_pkg() {
	local _pkg="$1"
	[[ -n $_pkg ]] || return 1
	# r314: 百度网盘不是本輪 aggressive settle 目標；不內建命中。
	[[ $_pkg = com.baidu.netdisk ]] && return 1
	_speedbackup_hard_freeze_pkg "$_pkg" && return 0
	case $_pkg in
		com.baidu.input*) return 0 ;;
	esac
	_speedbackup_cgroup_fast_settle_default_home_pkg "$_pkg" && return 0
	_speedbackup_cgroup_fast_settle_default_ime_pkg "$_pkg" && return 0
	_process_observer_pkg_in_words "$_pkg" "${SPEEDBACKUP_CGROUP_FAST_SETTLE_PACKAGES:-}" && return 0
	return 1
}

_speedbackup_cgroup_fast_settle_barrier_ms() {
	local _ms="${SPEEDBACKUP_CGROUP_FAST_SETTLE_BARRIER_MS:-80}"
	case $_ms in ''|*[!0-9]*) _ms=80 ;; esac
	[[ $_ms -gt 300 ]] && _ms=300
	printf '%s\n' "$_ms"
}

_speedbackup_hard_freeze_pkg() {
	local _pkg="$1"
	[[ -n $_pkg ]] || return 1
	# r240: hard freeze 只直接寫死給少數高風險/多進程/強保活 App；不讀 /data/backup_tools/hard_freeze_apps.conf。
	# 其他 App 在 auto/smart policy 下走 instant kill / force-stop / native kill，不進 cgroup v2 tar-scope freeze。
	case $_pkg in
		com.tencent.mm|com.tencent.mobileqq|com.tencent.tim|com.tencent.wework|com.eg.android.AlipayGphone|com.taobao.taobao|com.ss.android.ugc.aweme)
			return 0 ;;
	esac
	return 1
}

_process_observer_high_risk_pkg() {
	local _pkg="$1"
	# r119/r240: restricted wake-block / netblock 預設跟 hard-freeze 固定名單一致；仍允許環境變數臨時追加觀察，不建立外部 conf。
	_speedbackup_hard_freeze_pkg "$_pkg" && return 0
	_process_observer_pkg_in_words "$_pkg" "${SPEEDBACKUP_PROCESS_OBSERVER_HIGH_RISK_PACKAGES:-}" && return 0
	return 1
}

_process_observer_action_for_pkg() {
	local _pkg="$1" _stage="${2:-}" _policy="${SPEEDBACKUP_PROCESS_OBSERVER_POLICY:-smart}" _action
	# r334: restore freeze-list/default HOME remains event-driven cgroup-freeze; fast-path only trims redundant probes.
	# Default HOME is normally never-pause, but during restore we have overwritten data;
	# any respawn before post-AppState kill must be frozen instead of left running.
	if [[ $_stage = restore_app_scope ]] && _speedbackup_cgroup_fast_settle_pkg "$_pkg"; then
		printf '%s\n' "cgroup-freeze"
		return 0
	fi
	if _pkg_is_quiesce_never_pause "$_pkg"; then
		printf '%s\n' "monitor"
		return 0
	fi
	case $_policy in
		all|full|restricted|guard-stop-restricted)
			_action="guard-stop-restricted" ;;
		basic|lite|force-stop|guard-stop)
			_action="guard-stop" ;;
		appops|guard-stop-appops)
			_action="guard-stop-appops" ;;
		monitor|log|none|off|disable)
			_action="$_policy" ;;
		smart|auto|*)
			if _process_observer_high_risk_pkg "$_pkg"; then
				_action="guard-stop-restricted"
			else
				_action="guard-stop"
			fi ;;
	esac
	# 顯式 SPEEDBACKUP_PROCESS_OBSERVER_ACTION 仍可覆蓋 smart policy，方便回到舊全量 restricted。
	[[ -n ${SPEEDBACKUP_PROCESS_OBSERVER_ACTION:-} ]] && _action="$SPEEDBACKUP_PROCESS_OBSERVER_ACTION"
	printf '%s\n' "$_action"
}


# r226: processObserverTop / processObserverForeground shell 端全面接入。
# 定位：只做 direct status probe / debug / guard 輔助，不接管 JSON、app_details 或備份/恢復規劃。
_process_observer_direct_status_enabled() {
	case "${SPEEDBACKUP_PROCESS_OBSERVER_DIRECT_STATUS:-1}" in
	0|false|FALSE|no|NO|off|OFF|disable|DISABLE) return 1 ;;
	esac
	return 0
}

_process_observer_status_safe_name() {
	printf '%s' "${1:-unknown}" | tr -cd 'A-Za-z0-9._-一-龥' | cut -c1-80
}

_process_observer_status_kv() {
	local _line="$1" _key="$2"
	[[ -n $_line && -n $_key ]] || return 0
	printf '%s\n' "$_line" | sed -n "s/.*[[:space:]]${_key}=\([^[:space:]]*\).*/\1/p" | tail -n 1
}

# r259: ProcessObserver direct status 短 TTL cache。
# 目的：同一 App 在 kill_app / foregroundState / pkg_process_pids / guard barrier 之間常連續查詢同一份
# processObserverForeground，r258 實測 123 App 全量備份會累積大量 RootDaemon/unixsock round-trip。
# 這裡只快取「狀態查詢結果」，不接管 policy；任何 force-stop / stop-app / native kill 後立即失效。
_PROCESS_OBSERVER_FG_CACHE_PKG=""
_PROCESS_OBSERVER_FG_CACHE_TS_MS=0
_PROCESS_OBSERVER_FG_CACHE_RC=2
_PROCESS_OBSERVER_FG_CACHE_ACTIVE=""
_PROCESS_OBSERVER_FG_CACHE_TOP=""
_PROCESS_OBSERVER_FG_CACHE_ALIVE=""
_PROCESS_OBSERVER_FG_CACHE_PIDS=""
_PROCESS_OBSERVER_FG_CACHE_LINE=""
_PROCESS_OBSERVER_TOP_CACHE_TS_MS=0
_PROCESS_OBSERVER_TOP_CACHE_RC=2
_PROCESS_OBSERVER_TOP_CACHE_FLAT=""

_process_observer_status_cache_enabled() {
	case "${SPEEDBACKUP_PROCESS_OBSERVER_STATUS_CACHE:-1}" in
	0|false|FALSE|no|NO|off|OFF|disable|DISABLE) return 1 ;;
	esac
	return 0
}
_process_observer_status_cache_ttl_ms() {
	local _ttl="${SPEEDBACKUP_PROCESS_OBSERVER_STATUS_CACHE_TTL_MS:-450}"
	case $_ttl in ''|*[!0-9]*) _ttl=450 ;; esac
	[[ $_ttl -lt 0 ]] && _ttl=0
	[[ $_ttl -gt 2000 ]] && _ttl=2000
	printf '%s\n' "$_ttl"
}
_process_observer_status_cache_stage_fresh_required() {
	local _stage="$1"
	case $_stage in
	*after_stop*|*after_force*|*after_native_kill*|*after_wait*|*respawn*|*verify*|*fallback*|*cleanup*|*restore_post*)
		return 0 ;;
	esac
	return 1
}
_process_observer_status_cache_invalidate_pkg() {
	local _pkg="$1" _reason="${2:-unknown}"
	if [[ -z $_pkg || $_pkg = "${_PROCESS_OBSERVER_FG_CACHE_PKG:-}" ]]; then
		_PROCESS_OBSERVER_FG_CACHE_PKG=""
		_PROCESS_OBSERVER_FG_CACHE_TS_MS=0
		_PROCESS_OBSERVER_FG_CACHE_RC=2
		_PROCESS_OBSERVER_FG_CACHE_ACTIVE=""
		_PROCESS_OBSERVER_FG_CACHE_TOP=""
		_PROCESS_OBSERVER_FG_CACHE_ALIVE=""
		_PROCESS_OBSERVER_FG_CACHE_PIDS=""
		_PROCESS_OBSERVER_FG_CACHE_LINE=""
	fi
	_PROCESS_OBSERVER_TOP_CACHE_TS_MS=0
	_PROCESS_OBSERVER_TOP_CACHE_RC=2
	_PROCESS_OBSERVER_TOP_CACHE_FLAT=""
	_speed_debug_log "PROCESS_OBSERVER_STATUS_CACHE_INVALIDATE pkg=${_pkg:-all} reason=$_reason"
	return 0
}
_process_observer_foreground_cache_store() {
	local _pkg="$1" _rc="$2" _active="$3" _top="$4" _alive="$5" _pids="$6" _line="$7"
	_process_observer_status_cache_enabled || return 0
	_PROCESS_OBSERVER_FG_CACHE_PKG="$_pkg"
	_PROCESS_OBSERVER_FG_CACHE_TS_MS="$(_speed_now_ms)"
	_PROCESS_OBSERVER_FG_CACHE_RC="$_rc"
	_PROCESS_OBSERVER_FG_CACHE_ACTIVE="$_active"
	_PROCESS_OBSERVER_FG_CACHE_TOP="$_top"
	_PROCESS_OBSERVER_FG_CACHE_ALIVE="$_alive"
	_PROCESS_OBSERVER_FG_CACHE_PIDS="$_pids"
	_PROCESS_OBSERVER_FG_CACHE_LINE="$_line"
	return 0
}
_process_observer_foreground_cache_load() {
	local _pkg="$1" _stage="$2" _now _age _ttl
	PROCESS_OBSERVER_DIRECT_ACTIVE=""
	PROCESS_OBSERVER_DIRECT_TOP=""
	PROCESS_OBSERVER_DIRECT_ALIVE=""
	PROCESS_OBSERVER_DIRECT_PIDS=""
	PROCESS_OBSERVER_DIRECT_LINE=""
	_process_observer_status_cache_enabled || return 1
	[[ -n $_pkg && $_pkg = "${_PROCESS_OBSERVER_FG_CACHE_PKG:-}" ]] || return 1
	_process_observer_status_cache_stage_fresh_required "$_stage" && return 1
	_ttl="$(_process_observer_status_cache_ttl_ms)"
	[[ $_ttl -gt 0 ]] || return 1
	_now="$(_speed_now_ms)"
	_age=$((_now - ${_PROCESS_OBSERVER_FG_CACHE_TS_MS:-0}))
	[[ $_age -ge 0 && $_age -le $_ttl ]] || return 1
	PROCESS_OBSERVER_DIRECT_ACTIVE="${_PROCESS_OBSERVER_FG_CACHE_ACTIVE:-}"
	PROCESS_OBSERVER_DIRECT_TOP="${_PROCESS_OBSERVER_FG_CACHE_TOP:-}"
	PROCESS_OBSERVER_DIRECT_ALIVE="${_PROCESS_OBSERVER_FG_CACHE_ALIVE:-}"
	PROCESS_OBSERVER_DIRECT_PIDS="${_PROCESS_OBSERVER_FG_CACHE_PIDS:-}"
	PROCESS_OBSERVER_DIRECT_LINE="${_PROCESS_OBSERVER_FG_CACHE_LINE:-}"
	_speed_debug_log "PROCESS_OBSERVER_FOREGROUND_STATUS_CACHE_HIT stage=$_stage pkg=$_pkg ageMs=$_age ttlMs=$_ttl rc=${_PROCESS_OBSERVER_FG_CACHE_RC:-2} active=${PROCESS_OBSERVER_DIRECT_ACTIVE:-unknown} topTarget=${PROCESS_OBSERVER_DIRECT_TOP:-unknown} alive=${PROCESS_OBSERVER_DIRECT_ALIVE:-unknown} alivePids=${PROCESS_OBSERVER_DIRECT_PIDS:-}"
	return "${_PROCESS_OBSERVER_FG_CACHE_RC:-2}"
}
_process_observer_top_cache_store() {
	local _rc="$1" _flat="$2"
	_process_observer_status_cache_enabled || return 0
	_PROCESS_OBSERVER_TOP_CACHE_TS_MS="$(_speed_now_ms)"
	_PROCESS_OBSERVER_TOP_CACHE_RC="$_rc"
	_PROCESS_OBSERVER_TOP_CACHE_FLAT="$_flat"
	return 0
}
_process_observer_top_cache_load() {
	local _stage="$1" _now _age _ttl
	_process_observer_status_cache_enabled || return 1
	_process_observer_status_cache_stage_fresh_required "$_stage" && return 1
	_ttl="$(_process_observer_status_cache_ttl_ms)"
	[[ $_ttl -gt 0 && ${_PROCESS_OBSERVER_TOP_CACHE_TS_MS:-0} -gt 0 ]] || return 1
	_now="$(_speed_now_ms)"
	_age=$((_now - ${_PROCESS_OBSERVER_TOP_CACHE_TS_MS:-0}))
	[[ $_age -ge 0 && $_age -le $_ttl ]] || return 1
	_speed_debug_log "PROCESS_OBSERVER_TOP_STATUS_CACHE_HIT stage=$_stage ageMs=$_age ttlMs=$_ttl rc=${_PROCESS_OBSERVER_TOP_CACHE_RC:-2} out=${_PROCESS_OBSERVER_TOP_CACHE_FLAT:-}"
	return "${_PROCESS_OBSERVER_TOP_CACHE_RC:-2}"
}

_process_observer_top_status() {
	local _stage="${1:-probe}" _out _rc _flat _safe_stage
	_process_observer_direct_status_enabled || return 1
	if _process_observer_top_cache_load "$_stage"; then
		return $?
	fi
	_out="$(_webdav_tmp_path process_observer_top_${$}_$RANDOM)"
	dex_hiddenapi_raw processObserverTop "${USER_ID:-${user:-0}}" > "$_out" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	_rc=$?
	_flat="$(tr '\n' '|' < "$_out" 2>/dev/null | cut -c1-700)"
	_speed_debug_log "PROCESS_OBSERVER_TOP_STATUS stage=$_stage rc=$_rc out=$_flat"
	_process_observer_top_cache_store "$_rc" "$_flat"
	if [[ -n ${SPEED_DEBUG_RUN_DIR:-} && -d ${SPEED_DEBUG_RUN_DIR:-} && -s $_out ]]; then
		_safe_stage="$(_process_observer_status_safe_name "$_stage")"
		cp -f "$_out" "$SPEED_DEBUG_RUN_DIR/process_observer_top_${_safe_stage}.txt" 2>/dev/null || true
	fi
	rm -f "$_out" 2>/dev/null
	return $_rc
}

_process_observer_foreground_status() {
	local _pkg="$1" _stage="${2:-probe}" _out _rc _line _active _top _alive _pids _flat _safe_stage _safe_pkg
	PROCESS_OBSERVER_DIRECT_ACTIVE=""
	PROCESS_OBSERVER_DIRECT_TOP=""
	PROCESS_OBSERVER_DIRECT_ALIVE=""
	PROCESS_OBSERVER_DIRECT_PIDS=""
	PROCESS_OBSERVER_DIRECT_LINE=""
	_process_observer_direct_status_enabled || return 1
	[[ -n $_pkg ]] || return 2
	if _process_observer_foreground_cache_load "$_pkg" "$_stage"; then
		return $?
	fi
	_out="$(_webdav_tmp_path process_observer_foreground_${$}_$RANDOM)"
	dex_hiddenapi_raw processObserverForeground "${USER_ID:-${user:-0}}" "$_pkg" > "$_out" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	_rc=$?
	_line="$(grep -F 'PROCESS_OBSERVER_FOREGROUND ' "$_out" 2>/dev/null | grep -F "package=$_pkg" | tail -n 1)"
	_active="$(_process_observer_status_kv "$_line" active)"
	_top="$(_process_observer_status_kv "$_line" topTarget)"
	_alive="$(_process_observer_status_kv "$_line" alive)"
	_pids="$(_process_observer_status_kv "$_line" alivePids)"
	PROCESS_OBSERVER_DIRECT_ACTIVE="$_active"
	PROCESS_OBSERVER_DIRECT_TOP="$_top"
	PROCESS_OBSERVER_DIRECT_ALIVE="$_alive"
	PROCESS_OBSERVER_DIRECT_PIDS="$_pids"
	PROCESS_OBSERVER_DIRECT_LINE="$_line"
	_flat="$(tr '\n' '|' < "$_out" 2>/dev/null | cut -c1-900)"
	_speed_debug_log "PROCESS_OBSERVER_FOREGROUND_STATUS stage=$_stage pkg=$_pkg rc=$_rc active=${_active:-unknown} topTarget=${_top:-unknown} alive=${_alive:-unknown} alivePids=${_pids:-} source=direct out=$_flat"
	case $_rc:$_active in
	0:true) _process_observer_foreground_cache_store "$_pkg" 0 "$_active" "$_top" "$_alive" "$_pids" "$_line" ;;
	0:false) _process_observer_foreground_cache_store "$_pkg" 1 "$_active" "$_top" "$_alive" "$_pids" "$_line" ;;
	*) _process_observer_foreground_cache_store "$_pkg" 2 "$_active" "$_top" "$_alive" "$_pids" "$_line" ;;
	esac
	if [[ -n ${SPEED_DEBUG_RUN_DIR:-} && -d ${SPEED_DEBUG_RUN_DIR:-} && -s $_out ]]; then
		_safe_stage="$(_process_observer_status_safe_name "$_stage")"
		_safe_pkg="$(_process_observer_status_safe_name "$_pkg")"
		cp -f "$_out" "$SPEED_DEBUG_RUN_DIR/process_observer_foreground_${_safe_stage}_${_safe_pkg}.txt" 2>/dev/null || true
	fi
	case $_rc:$_active in
	0:true) rm -f "$_out" 2>/dev/null; return 0 ;;
	0:false) rm -f "$_out" 2>/dev/null; return 1 ;;
	esac
	rm -f "$_out" 2>/dev/null
	return 2
}

_process_observer_pkg_alive_pids() {
	local _pkg="$1" _stage="${2:-alive_pids}" _pids _p
	[[ -n $_pkg ]] || return 1
	_process_observer_foreground_status "$_pkg" "$_stage" >/dev/null 2>&1
	case $? in 0|1) ;; *) return 1 ;; esac
	case ${PROCESS_OBSERVER_DIRECT_ALIVE:-}:${PROCESS_OBSERVER_DIRECT_PIDS:-} in
	true:*)
		_pids="${PROCESS_OBSERVER_DIRECT_PIDS:-}"
		[[ -n $_pids && $_pids != none && $_pids != - ]] || return 0
		printf '%s\n' "$_pids" | tr ',' '\n' | while read -r _p; do
			case $_p in ''|*[!0-9]*) continue ;; esac
			printf '%s\n' "$_p"
		done
		return 0 ;;
	false:*) return 0 ;;
	esac
	return 1
}

_process_observer_alive_first_pid() {
	local _pkg="$1" _stage="${2:-first_pid}" _p
	_process_observer_pkg_alive_pids "$_pkg" "$_stage" | while read -r _p; do
		case $_p in ''|*[!0-9]*) continue ;; esac
		printf '%s\n' "$_p"
		break
	done
}

_process_observer_foreground_barrier() {
	local _pkg="$1" _label="$2" _stage="${3:-barrier}" _delay _first_top _second_top _first_pids _second_pids
	[[ -n $_pkg ]] || return 0
	_process_observer_direct_status_enabled || return 0
	_process_observer_foreground_status "$_pkg" "${_stage}_before" >/dev/null 2>&1 || return 0
	_uid_live_state_status "$_pkg" "${_stage}_uid_before" >/dev/null 2>&1 || true
	_package_install_snapshot_status "$_pkg" "${_stage}_install_before" >/dev/null 2>&1 || true
	_package_restriction_snapshot_status "$_pkg" "${_stage}_restriction_before" >/dev/null 2>&1 || true
	_first_top="${PROCESS_OBSERVER_DIRECT_TOP:-unknown}"
	_first_pids="${PROCESS_OBSERVER_DIRECT_PIDS:-}"
	case $_first_top in true)
		_delay="${SPEEDBACKUP_PROCESS_OBSERVER_TOP_BARRIER_MS:-300}"
		case $_delay in ''|*[!0-9]*) _delay=300 ;; esac
		if _speedbackup_cgroup_fast_settle_pkg "$_pkg"; then
			_delay="$(_speedbackup_cgroup_fast_settle_barrier_ms)"
			_speed_debug_log "PROCESS_OBSERVER_FOREGROUND_BARRIER_FAST_SETTLE stage=$_stage pkg=$_pkg label=$_label waitMs=$_delay reason=cgroup-fast-settle-r330"
		fi
		[[ $_delay -gt 0 ]] && sleep $(awk -v ms="$_delay" 'BEGIN{printf "%.3f", ms/1000}')
		_process_observer_foreground_status "$_pkg" "${_stage}_after_wait" >/dev/null 2>&1 || true
		_second_top="${PROCESS_OBSERVER_DIRECT_TOP:-unknown}"
		_second_pids="${PROCESS_OBSERVER_DIRECT_PIDS:-}"
		_speed_debug_log "PROCESS_OBSERVER_FOREGROUND_BARRIER stage=$_stage pkg=$_pkg label=$_label firstTop=$_first_top secondTop=$_second_top firstPids=${_first_pids:-none} secondPids=${_second_pids:-none} waitMs=$_delay fastSettle=$(_speedbackup_cgroup_fast_settle_pkg "$_pkg" && echo 1 || echo 0) action=observe-then-existing-policy"
		;;
	*)
		_speed_debug_log "PROCESS_OBSERVER_FOREGROUND_BARRIER stage=$_stage pkg=$_pkg label=$_label firstTop=$_first_top pids=${_first_pids:-none} fastSettle=$(_speedbackup_cgroup_fast_settle_pkg "$_pkg" && echo 1 || echo 0) action=no-wait"
		;;
	esac
	return 0
}

