_cgroup_freezer_wchan_corrective_pkg() {
	local _pkg="$1" _label="${2:-$1}" _phase="${3:-corrective}" _expect="${4:-any}" _stage="${5:-}" _max _i=0 _timeout _after_phase _rc
	_cgroup_freezer_wchan_corrective_enabled || { _speed_debug_log "CGROUP_WCHAN_CORRECTIVE_SKIP phase=$_phase pkg=$_pkg label=$_label stage=$_stage expected=$_expect reason=disabled mode=r483"; return 0; }
	[[ -n $_pkg ]] || return 0
	case $_expect in frozen|thawed|not-frozen) ;; *) _speed_debug_log "CGROUP_WCHAN_CORRECTIVE_SKIP phase=$_phase pkg=$_pkg label=$_label stage=$_stage expected=$_expect reason=expect_any mode=r483"; return 0 ;; esac
	case $_phase in before_freeze_stop_*)
		_speed_debug_log "CGROUP_WCHAN_CORRECTIVE_SKIP phase=$_phase pkg=$_pkg label=$_label stage=$_stage expected=$_expect reason=before_stop_external_thaw_observe_only mode=r483"
		return 0 ;;
	esac
	_max="$(_cgroup_freezer_wchan_corrective_max)"
	[[ $_max -gt 0 ]] || { _speed_debug_log "CGROUP_WCHAN_CORRECTIVE_SKIP phase=$_phase pkg=$_pkg label=$_label stage=$_stage expected=$_expect reason=max_zero mode=r483"; return 0; }
	case $_expect in
	frozen)
		_timeout="${SPEEDBACKUP_CGROUP_FREEZER_WCHAN_REFREEZE_TIMEOUT_MS:-700}"
		case $_timeout in ''|*[!0-9]*) _timeout=700 ;; esac
		while [[ $_i -lt $_max ]]; do
			_i=$((_i + 1))
			_speed_debug_log "CGROUP_WCHAN_CORRECTIVE_BEGIN phase=$_phase pkg=$_pkg label=$_label stage=$_stage expected=$_expect attempt=$_i action=freeze_pkg_retry mode=r483"
			_cgroup_freezer_native_freeze_retry_pkg "$_pkg" "${_phase}_attempt${_i}" "$_timeout" || true
			_after_phase="after_corrective_${_phase}_attempt${_i}"
			_cgroup_freezer_wchan_confirm_pkg "$_pkg" "$_label" "$_after_phase" frozen "$_stage"
			_rc=$?
			if [[ $_rc = 0 ]]; then
				_speed_debug_log "CGROUP_WCHAN_CORRECTIVE_DONE phase=$_phase pkg=$_pkg label=$_label stage=$_stage expected=$_expect attempt=$_i result=fixed mode=r483"
				return 0
			fi
		done
		_speed_debug_log "CGROUP_WCHAN_CORRECTIVE_DONE phase=$_phase pkg=$_pkg label=$_label stage=$_stage expected=$_expect attempts=$_max result=still_mismatch mode=r483"
		return 1 ;;
	thawed|not-frozen)
		_timeout="${SPEEDBACKUP_CGROUP_FREEZER_WCHAN_THAW_TIMEOUT_MS:-700}"
		case $_timeout in ''|*[!0-9]*) _timeout=700 ;; esac
		while [[ $_i -lt $_max ]]; do
			_i=$((_i + 1))
			_speed_debug_log "CGROUP_WCHAN_CORRECTIVE_BEGIN phase=$_phase pkg=$_pkg label=$_label stage=$_stage expected=$_expect attempt=$_i action=thaw_uid_restore_package mode=r483"
			_cgroup_freezer_native_thaw_uid_pkg "$_pkg" "${_phase}_attempt${_i}" "$_timeout" || true
			_cgroup_freezer_restore_package_direct "$_pkg" "${_phase}_attempt${_i}" || true
			_after_phase="after_corrective_${_phase}_attempt${_i}"
			_cgroup_freezer_wchan_confirm_pkg "$_pkg" "$_label" "$_after_phase" "$_expect" "$_stage"
			_rc=$?
			if [[ $_rc = 0 ]]; then
				_speed_debug_log "CGROUP_WCHAN_CORRECTIVE_DONE phase=$_phase pkg=$_pkg label=$_label stage=$_stage expected=$_expect attempt=$_i result=fixed mode=r483"
				return 0
			fi
		done
		_speed_debug_log "CGROUP_WCHAN_CORRECTIVE_DONE phase=$_phase pkg=$_pkg label=$_label stage=$_stage expected=$_expect attempts=$_max result=still_mismatch mode=r483"
		return 1 ;;
	esac
	return 0
}

_cgroup_freezer_native_kill_pkg() {
	local _pkg="$1" _stage="${2:-native_kill}" _event_pid="${3:--1}" _timeout="${4:-700}" _out _rc _flat _remain _wchan_rc
	[[ -n $_pkg ]] || return 1
	case $_event_pid in ''|*[!0-9]*) _event_pid=-1 ;; esac
	case $_timeout in ''|*[!0-9]*) _timeout=700 ;; esac
	_cgroup_freezer_proc_snapshot "$_pkg" "before_native_kill_${_stage}" >/dev/null 2>&1 || true
	_cgroup_freezer_wchan_confirm_pkg "$_pkg" "$_pkg" "before_native_kill_${_stage}" any "native_kill" || true
	_uid_live_state_status "$_pkg" "before_native_kill_${_stage}" >/dev/null 2>&1 || true
	_process_observer_status_cache_invalidate_pkg "$_pkg" "before_native_kill_${_stage}" >/dev/null 2>&1 || true
	_out="$(_webdav_tmp_path cgroup_freezer_native_kill_${$}_$RANDOM)"
	_cgroup_freezer_daemon_sock_call "KILL_PKG $_pkg ${USER_ID:-${user:-0}} $_event_pid $_timeout" "$_out"
	_rc=$?
	_process_observer_status_cache_invalidate_pkg "$_pkg" "after_native_kill_${_stage}" >/dev/null 2>&1 || true
	_flat="$(tr '\n' '|' < "$_out" 2>/dev/null | cut -c1-1000)"
	_remain="$(sed -n 's/.*CGFREEZER_KILL_PKG_DONE .*remain=\([0-9][0-9]*\).*/\1/p' "$_out" 2>/dev/null | tail -n 1)"
	_speed_debug_log "CGROUP_NATIVE_KILL_DIRECT stage=$_stage pkg=$_pkg eventPid=$_event_pid timeoutMs=$_timeout rc=$_rc remain=${_remain:-unknown} out=$_flat"
	if [[ ${_remain:-0} != 0 ]]; then
		_process_observer_foreground_status "$_pkg" "after_native_kill_${_stage}" >/dev/null 2>&1 || true
		[[ -n ${PROCESS_OBSERVER_DIRECT_PIDS:-} && ${PROCESS_OBSERVER_DIRECT_PIDS:-} != none ]] && _cgroup_freezer_kill_pid_list "$_pkg" "${PROCESS_OBSERVER_DIRECT_PIDS:-}" "after_native_kill_${_stage}" 9 >/dev/null 2>&1 || true
	fi
	_cgroup_freezer_proc_snapshot "$_pkg" "after_native_kill_${_stage}" >/dev/null 2>&1 || true
	_cgroup_freezer_wchan_confirm_pkg "$_pkg" "$_pkg" "after_native_kill_${_stage}" thawed "native_kill"
	_wchan_rc=$?
	if [[ $_wchan_rc = 1 ]]; then
		_cgroup_freezer_wchan_corrective_pkg "$_pkg" "$_pkg" "after_native_kill_${_stage}" thawed "native_kill" || true
	fi
	if [[ -n ${SPEED_DEBUG_RUN_DIR:-} && -d ${SPEED_DEBUG_RUN_DIR:-} && -s $_out ]]; then
		cp -f "$_out" "$SPEED_DEBUG_RUN_DIR/cgroup_native_kill_${_stage}_$(_process_observer_status_safe_name "$_pkg").txt" 2>/dev/null || true
	fi
	rm -f "$_out" 2>/dev/null
	[[ $_rc = 0 && ${_remain:-1} = 0 ]]
}


_uid_live_state_status() {
	local _pkg="$1" _stage="${2:-uid_live_state}" _out _rc _flat _safe_stage _safe_pkg
	_process_observer_direct_status_enabled || return 1
	[[ -n $_pkg ]] || return 2
	_out="$(_webdav_tmp_path uid_live_state_${$}_$RANDOM)"
	dex_hiddenapi_raw uidLiveState "${USER_ID:-${user:-0}}" "$_pkg" > "$_out" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	_rc=$?
	_flat="$(tr '\n' '|' < "$_out" 2>/dev/null | cut -c1-900)"
	_speed_debug_log "UID_LIVE_STATE_STATUS stage=$_stage pkg=$_pkg rc=$_rc out=$_flat hash=0"
	if [[ -n ${SPEED_DEBUG_RUN_DIR:-} && -d ${SPEED_DEBUG_RUN_DIR:-} && -s $_out ]]; then
		_safe_stage="$(_process_observer_status_safe_name "$_stage")"
		_safe_pkg="$(_process_observer_status_safe_name "$_pkg")"
		cp -f "$_out" "$SPEED_DEBUG_RUN_DIR/uid_live_state_${_safe_stage}_${_safe_pkg}.txt" 2>/dev/null || true
	fi
	rm -f "$_out" 2>/dev/null
	return $_rc
}

_cgroup_freezer_proc_snapshot() {
	local _pkg="$1" _stage="${2:-proc_snapshot}" _out _rc _flat _safe_stage _safe_pkg
	[[ -n $_pkg ]] || return 1
	# r334: current cgfreezerd builds used by the mainline do not expose PROC_SNAPSHOT.
	# Do not keep emitting unknown_command detail files; native KILL_PKG already returns
	# before/after remain counts and tools has Dex/package live-state snapshots for diagnostics.
	if [[ ${CGROUP_FREEZER_PROC_SNAPSHOT_SUPPORTED:-unknown} = 0 ]]; then
		_speed_debug_log "CGROUP_PROC_SNAPSHOT_SKIP stage=$_stage pkg=$_pkg reason=daemon_unsupported cached=1 mode=r334"
		return 0
	fi
	_out="$(_webdav_tmp_path cgroup_proc_snapshot_${$}_$RANDOM)"
	_cgroup_freezer_daemon_sock_call "PROC_SNAPSHOT $_pkg ${USER_ID:-${user:-0}}" "$_out"
	_rc=$?
	if grep -F 'reason=unknown_command command=PROC_SNAPSHOT' "$_out" >/dev/null 2>&1; then
		CGROUP_FREEZER_PROC_SNAPSHOT_SUPPORTED=0
		_speed_debug_log "CGROUP_PROC_SNAPSHOT_SKIP stage=$_stage pkg=$_pkg rc=$_rc reason=daemon_unsupported first_probe=1 mode=r334"
		rm -f "$_out" 2>/dev/null
		return 0
	fi
	CGROUP_FREEZER_PROC_SNAPSHOT_SUPPORTED=1
	_flat="$(grep -F 'CGFREEZER_PROC_SNAPSHOT_DONE ' "$_out" 2>/dev/null | tail -n 1 | cut -c1-700)"
	_speed_debug_log "CGROUP_PROC_SNAPSHOT stage=$_stage pkg=$_pkg rc=$_rc summary=$_flat mode=r334"
	if [[ -n ${SPEED_DEBUG_RUN_DIR:-} && -d ${SPEED_DEBUG_RUN_DIR:-} && -s $_out ]]; then
		_safe_stage="$(_process_observer_status_safe_name "$_stage")"
		_safe_pkg="$(_process_observer_status_safe_name "$_pkg")"
		cp -f "$_out" "$SPEED_DEBUG_RUN_DIR/cgroup_proc_snapshot_${_safe_stage}_${_safe_pkg}.txt" 2>/dev/null || true
	fi
	rm -f "$_out" 2>/dev/null
	return $_rc
}

_cgroup_freezer_wchan_enabled() {
	case "${SPEEDBACKUP_CGROUP_FREEZER_WCHAN_CONFIRM:-1}" in
	0|false|FALSE|no|NO|off|OFF|disable|DISABLE) return 1 ;;
	esac
	return 0
}

_cgroup_freezer_wchan_confirm_pkg() {
	local _pkg="$1" _label="${2:-$1}" _phase="${3:-confirm}" _expect="${4:-any}" _stage="${5:-}" _pids _out _rc _flat _summary _safe_phase _safe_pkg _ok _checked _frozen _sigstop _mismatch
	_cgroup_freezer_wchan_enabled || return 0
	[[ -n $_pkg ]] || return 0
	case $_expect in frozen|thawed|not-frozen|any) ;; *) _expect=any ;; esac
	_pids="$(_pkg_process_pids "$_pkg" 2>/dev/null | tr '\n' ',' | sed 's/,$//')"
	if [[ -z $_pids ]]; then
		case $_expect in
		frozen) _speed_debug_log "CGROUP_WCHAN_CONFIRM_SKIP pkg=$_pkg label=$_label phase=$_phase stage=$_stage expected=$_expect reason=no_pids ok=false mode=r483"; return 2 ;;
		*) _speed_debug_log "CGROUP_WCHAN_CONFIRM_SKIP pkg=$_pkg label=$_label phase=$_phase stage=$_stage expected=$_expect reason=no_pids ok=true mode=r483"; return 0 ;;
		esac
	fi
	_out="$(_webdav_tmp_path cgroup_wchan_${$}_$RANDOM)"
	_cgroup_freezer_daemon_sock_call "WCHAN_PID_LIST ${USER_ID:-${user:-0}} $_pids $_expect" "$_out"
	_rc=$?
	_summary="$(grep -E 'CGFREEZER_WCHAN(_UID)?_DONE ' "$_out" 2>/dev/null | tail -n 1 | cut -c1-900)"
	_flat="$(tr '\n' '|' < "$_out" 2>/dev/null | cut -c1-1400)"
	_ok="$(_cgroup_freezer_kv_from_line "$_summary" ok)"
	_checked="$(_cgroup_freezer_kv_from_line "$_summary" checked)"
	_frozen="$(_cgroup_freezer_kv_from_line "$_summary" frozen)"
	_sigstop="$(_cgroup_freezer_kv_from_line "$_summary" sigstop)"
	_mismatch="$(_cgroup_freezer_kv_from_line "$_summary" mismatch)"
	_speed_debug_log "CGROUP_WCHAN_CONFIRM phase=$_phase pkg=$_pkg label=$_label stage=$_stage expected=$_expect pids=$_pids rc=$_rc ok=${_ok:-unknown} checked=${_checked:-unknown} frozen=${_frozen:-unknown} sigstop=${_sigstop:-unknown} mismatch=${_mismatch:-unknown} summary=${_summary:-none} mode=r483"
	if [[ -n ${SPEED_DEBUG_RUN_DIR:-} && -d ${SPEED_DEBUG_RUN_DIR:-} && -s $_out ]]; then
		_safe_phase="$(_process_observer_status_safe_name "$_phase" 2>/dev/null || printf '%s' "$_phase")"
		_safe_pkg="$(_process_observer_status_safe_name "$_pkg" 2>/dev/null || printf '%s' "$_pkg")"
		cp -f "$_out" "$SPEED_DEBUG_RUN_DIR/cgroup_wchan_${_safe_phase}_${_safe_pkg}.txt" 2>/dev/null || true
	fi
	case $_expect:${_ok:-false} in
	frozen:false|thawed:false|not-frozen:false)
		_speed_debug_log "CGROUP_WCHAN_CONFIRM_WARN phase=$_phase pkg=$_pkg label=$_label stage=$_stage expected=$_expect rc=$_rc out=$_flat mode=r483"
		rm -f "$_out" 2>/dev/null
		return 1 ;;
	esac
	rm -f "$_out" 2>/dev/null
	return 0
}

_cgroup_freezer_kill_pid_list() {
	local _pkg="$1" _pids="$2" _stage="${3:-kill_pid_list}" _sig="${4:-9}" _out _rc _flat
	[[ -n $_pids && $_pids != none && $_pids != - ]] || return 1
	case $_sig in ''|*[!0-9]*) _sig=9 ;; esac
	_out="$(_webdav_tmp_path cgroup_kill_pid_list_${$}_$RANDOM)"
	_cgroup_freezer_daemon_sock_call "KILL_PID_LIST ${USER_ID:-${user:-0}} $_pids $_sig" "$_out"
	_rc=$?
	_flat="$(tr '\n' '|' < "$_out" 2>/dev/null | cut -c1-1200)"
	_speed_debug_log "CGROUP_KILL_PID_LIST_DIRECT stage=$_stage pkg=$_pkg pids=$_pids signal=$_sig rc=$_rc out=$_flat"
	[[ -n ${SPEED_DEBUG_RUN_DIR:-} && -d ${SPEED_DEBUG_RUN_DIR:-} && -s $_out ]] && cp -f "$_out" "$SPEED_DEBUG_RUN_DIR/cgroup_kill_pid_list_${_stage}_$(_process_observer_status_safe_name "$_pkg").txt" 2>/dev/null || true
	rm -f "$_out" 2>/dev/null
	return $_rc
}


_process_observer_log_path() {
	local _pkg="$1" _entry="$2" _stage="$3" _safe_pkg _safe_entry _safe_stage _base _kind _mode
	_safe_pkg="$(_backup_tar_safe_name "${_pkg:-unknown}")"
	_safe_entry="$(_backup_tar_safe_name "${_entry:-unknown}")"
	_safe_stage="$(_backup_tar_safe_name "${_stage:-unknown}")"
	if [[ -n ${SPEED_DEBUG_RUN_DIR:-} && -d ${SPEED_DEBUG_RUN_DIR:-} ]]; then
		_base="$SPEED_DEBUG_RUN_DIR"
	else
		_base="${TMPDIR:-/data/local/tmp}"
	fi
	# r123: 預設改為操作級聚合 log，避免一個 App 一個 process_observer_*.log 導致 debug 包刷屏。
	# 每行 Dex log 本身已有 package/token/user/action/stage，可用 grep package=... 定位；必要時可用 legacy/per-app 回舊模式。
	_mode="${SPEEDBACKUP_PROCESS_OBSERVER_LOG_MODE:-operation}"
	case $_mode in
		legacy|per-app|package)
			printf '%s\n' "$_base/process_observer_${_safe_pkg}_${_safe_entry}_${_safe_stage}.log"
			return 0 ;;
	esac
	case "$_stage" in
		*restore*) _kind="restore" ;;
		*backup*) _kind="backup" ;;
		*)
			case "$_entry" in
				*restore*) _kind="restore" ;;
				*backup*) _kind="backup" ;;
				*) _kind="other" ;;
			esac ;;
	esac
	printf '%s\n' "$_base/process_observer_${_kind}_app_scope.log"
}

_process_observer_start_payload() {
	local _pkg="$1" _label="$2" _entry="$3" _stage="$4"
	PROCESS_OBSERVER_TOKEN=""
	PROCESS_OBSERVER_LOG=""
	PROCESS_OBSERVER_PKG=""
	PROCESS_OBSERVER_ENTRY=""
	# r111: 正式備份/恢復已提升為 app-scope target。payload helper 保留為 fallback；
	# 若同 pkg app target 已啟動，這裡只記 reuse，不再重複 add/remove target。
	if [[ -n ${PROCESS_OBSERVER_APP_TOKEN:-} && ${PROCESS_OBSERVER_APP_PKG:-} = "$_pkg" ]]; then
		_speed_debug_log "PROCESS_OBSERVER_PAYLOAD_REUSE_APP token=${PROCESS_OBSERVER_APP_TOKEN:-} pkg=$_pkg label=$_label entry=$_entry stage=$_stage"
		return 0
	fi
	# r269: r267/r268 batch watch-set 已在 App phase 一次加入 data App observer target。
	# payload 階段不要再為 data/user/user_de 每個檔案重複 processObserverStart/Stop；
	# 喚醒/復活守護仍由 batch global target 覆蓋整個 App phase。
	if _process_observer_batch_pkg_active "$_pkg"; then
		_speed_debug_log "PROCESS_OBSERVER_PAYLOAD_BATCH_REUSE pkg=$_pkg label=$_label entry=$_entry stage=$_stage lifecycle=batch-watchset action=skip-payload-start"
		return 0
	fi
	_process_observer_start_token "$_pkg" "$_label" "$_entry" "$_stage" payload
}

_process_observer_guard_hint_once() {
	local _stage="${1:-}"
	_process_observer_guard_enabled || return 0
	[[ ${PROCESS_OBSERVER_GUARD_HINT_SHOWN:-0} = 1 ]] && return 0
	PROCESS_OBSERVER_GUARD_HINT_SHOWN=1
	echoRgb "事件驅動守護已啟用（cgroup優先，失敗才瞬殺）" "2"
	_speed_debug_log "PROCESS_OBSERVER_GUARD_HINT shown=1 stage=$_stage once=1"
}

_process_observer_start_token() {
	local _pkg="$1" _label="$2" _entry="$3" _stage="$4" _scope="$5" _action _log _out _rc _token _state
	_process_observer_guard_enabled || return 0
	[[ -n $_pkg ]] || return 0
	case $_pkg in bin.mt.plus|bin.mt.plus.canary|com.termux) _speed_debug_log "PROCESS_OBSERVER_SKIP_SELF pkg=$_pkg entry=$_entry stage=$_stage scope=$_scope"; return 0 ;; esac
	_action="$(_process_observer_action_for_pkg "$_pkg" "$_stage")"
	case $_action in ''|none|off|disable) return 0 ;; esac
	_log="$(_process_observer_log_path "$_pkg" "$_entry" "$_stage")"
	_speed_debug_log "PROCESS_OBSERVER_POLICY pkg=$_pkg entry=$_entry stage=$_stage scope=$_scope policy=${SPEEDBACKUP_PROCESS_OBSERVER_POLICY:-smart} action=$_action"
	case $_action in cgroup-freeze)
		if _speedbackup_cgroup_fast_settle_default_ime_pkg "$_pkg"; then
			_speed_debug_log "PROCESS_OBSERVER_RESTORE_CGROUP_FREEZE_ACTION pkg=$_pkg label=$_label stage=$_stage scope=$_scope reason=default_ime mode=r370"
		else
			_speed_debug_log "PROCESS_OBSERVER_RESTORE_CGROUP_FREEZE_ACTION pkg=$_pkg label=$_label stage=$_stage scope=$_scope reason=restore_freeze_list_event_driven mode=r370"
		fi ;;
	esac
	# r261: start 前 top/foreground 只是觀測，不參與 policy；預設跳過，避免每 App 固定多兩次 RootDaemon round-trip。
	case "${SPEEDBACKUP_PROCESS_OBSERVER_START_STATUS_VERIFY:-0}" in
	1|true|TRUE|yes|YES|on|ON|enable|ENABLE)
		_process_observer_top_status "${_stage}_${_scope}_before_start" >/dev/null 2>&1 || true
		_process_observer_foreground_status "$_pkg" "${_stage}_${_scope}_before_start" >/dev/null 2>&1 || true
		;;
	*)
		_speed_debug_log "PROCESS_OBSERVER_START_STATUS_SKIP pkg=$_pkg entry=$_entry stage=$_stage scope=$_scope mode=r261-appscope-fast"
		;;
	esac
	_out="$(_webdav_tmp_path process_observer_start_${$}_$RANDOM)"
	dex_hiddenapi_raw processObserverStart "${USER_ID:-${user:-0}}" "$_pkg" "$_action" "$_log" > "$_out" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	_rc=$?
	if [[ $_rc = 0 ]] && grep -F "PROCESS_OBSERVER_START_OK" "$_out" >/dev/null 2>&1; then
		_token="$(sed -n 's/.*token=\([0-9][0-9]*\).*/\1/p' "$_out" | head -n 1)"
		if [[ -n $_token ]]; then
			_state="$(_process_observer_token_state_file)"
			printf '%s\t%s\t%s\t%s\t%s\t%s\t%s\n' "$_token" "$_pkg" "$_label" "$_entry" "$_stage" "$_log" "$_scope" >> "$_state" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
			_speed_debug_log "PROCESS_OBSERVER_START_OK token=$_token pkg=$_pkg label=$_label entry=$_entry stage=$_stage scope=$_scope action=$_action log=$_log"
			if [[ $_scope = app ]]; then
				PROCESS_OBSERVER_APP_TOKEN="$_token"
				PROCESS_OBSERVER_APP_PKG="$_pkg"
				PROCESS_OBSERVER_APP_LABEL="$_label"
				PROCESS_OBSERVER_APP_STAGE="$_stage"
				PROCESS_OBSERVER_APP_LOG="$_log"
			else
				PROCESS_OBSERVER_TOKEN="$_token"
				PROCESS_OBSERVER_LOG="$_log"
				PROCESS_OBSERVER_PKG="$_pkg"
				PROCESS_OBSERVER_ENTRY="$_entry"
			fi
			_process_observer_guard_hint_once "$_stage" || true
			rm -f "$_out" 2>/dev/null
			return 0
		fi
	fi
	_speed_debug_log "PROCESS_OBSERVER_START_FAIL pkg=$_pkg label=$_label entry=$_entry stage=$_stage scope=$_scope action=$_action rc=$_rc out=$(tr '\n' '|' < "$_out" | cut -c1-400)"
	rm -f "$_out" 2>/dev/null
	return 1
}

_process_observer_start_app() {
	local _pkg="$1" _label="$2" _stage="${3:-app-scope}"
	[[ -n $_pkg ]] || return 0
	if [[ -n ${_BACKUP_APP_QUIESCE_CACHE_PKG:-} && ${_BACKUP_APP_QUIESCE_CACHE_PKG:-} != "$_pkg" ]]; then
		_backup_app_quiesce_scope_cache_clear "${_BACKUP_APP_QUIESCE_CACHE_PKG:-}" "app-switch-${_stage}" || true
	fi
	if _process_observer_batch_pkg_active "$_pkg"; then
		PROCESS_OBSERVER_APP_TOKEN=""
		PROCESS_OBSERVER_APP_PKG="$_pkg"
		PROCESS_OBSERVER_APP_LABEL="$_label"
		PROCESS_OBSERVER_APP_STAGE="$_stage"
		PROCESS_OBSERVER_APP_LOG=""
		_speed_debug_log "PROCESS_OBSERVER_APP_BATCH_REUSE pkg=$_pkg label=$_label stage=$_stage lifecycle=batch-watchset action=skip-per-app-start release=${PROCESS_OBSERVER_BATCH_SCOPE:-batch}-r422"
		return 0
	fi
	if [[ -n ${PROCESS_OBSERVER_APP_TOKEN:-} && ${PROCESS_OBSERVER_APP_PKG:-} = "$_pkg" ]]; then
		_speed_debug_log "PROCESS_OBSERVER_APP_REUSE token=${PROCESS_OBSERVER_APP_TOKEN:-} pkg=$_pkg label=$_label stage=$_stage"
		return 0
	fi
	# 防止上一個 App 異常未 stop，先恢復。
	if [[ -n ${PROCESS_OBSERVER_APP_TOKEN:-} ]]; then
		_process_observer_stop_app "app-switch-${_stage}" || true
	fi
	_process_observer_start_token "$_pkg" "$_label" app "$_stage" app
}

_process_observer_remove_state_token() {
	local _token="$1" _state _tmp
	[[ -n $_token ]] || return 0
	_state="$(_process_observer_token_state_file)"
	[[ -f $_state ]] || return 0
	_tmp="$TMPDIR/.process_observer_tokens_${$}_$RANDOM"
	awk -F '	' -v t="$_token" '$1!=t {print $0}' "$_state" > "$_tmp" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} || cp -f "$_state" "$_tmp" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	cat "$_tmp" > "$_state" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} || true
	rm -f "$_tmp" 2>/dev/null
	[[ -s $_state ]] || rm -f "$_state" 2>/dev/null
}

_process_observer_log_kv() {
	local _line="$1" _key="$2"
	[[ -n $_line && -n $_key ]] || return 0
	printf '%s\n' "$_line" | sed -n "s/.*[[:space:]]${_key}=\([^[:space:]]*\).*/\1/p" | tail -n 1
}

_process_observer_appop_mode_valid() {
	case "$1" in allow|deny|ignore|default|foreground) return 0 ;; esac
	return 1
}

_process_observer_bucket_valid() {
	case "$1" in exempted|active|working_set|frequent|rare|restricted|never) return 0 ;; esac
	return 1
}

_process_observer_pkg_safe_for_shell() {
	case "$1" in ''|*[!A-Za-z0-9._-]*) return 1 ;; esac
	return 0
}

_process_observer_log_last_for_pkg() {
	local _log="$1" _tag="$2" _pkg="$3"
	[[ -n $_log && -f $_log && -n $_tag && -n $_pkg ]] || return 0
	awk -v tag="$_tag" -v p="package=$_pkg" '
		index($0, tag)>0 {
			ok=0
			for (i=1; i<=NF; i++) if ($i == p) ok=1
			if (ok) line=$0
		}
		END { if (line != "") print line }
	' "$_log" 2>/dev/null
}

_process_observer_fallback_restore_from_log() {
	local _token="$1" _pkg="$2" _log="$3" _reason="$4"
	local _snap _apply _restored _user _run_bg _run_any _bucket _run_bg_touched _run_any_touched _bucket_touched _rc _did=0
	_process_observer_pkg_safe_for_shell "$_pkg" || { _speed_debug_log "PROCESS_OBSERVER_FALLBACK_RESTORE_SKIP token=$_token pkg=$_pkg reason=unsafe-pkg"; return 0; }
	[[ -n $_log && -f $_log ]] || { _speed_debug_log "PROCESS_OBSERVER_FALLBACK_RESTORE_SKIP token=$_token pkg=$_pkg reason=no-log log=$_log"; return 0; }
	_apply="$(_process_observer_log_last_for_pkg "$_log" 'APP_WAKE_BLOCK_APPLY_DONE ' "$_pkg")"
	[[ -n $_apply ]] || { _speed_debug_log "PROCESS_OBSERVER_FALLBACK_RESTORE_SKIP token=$_token pkg=$_pkg reason=no-apply-done log=$_log"; return 0; }
	_snap="$(_process_observer_log_last_for_pkg "$_log" 'APP_WAKE_BLOCK_SNAPSHOT user=' "$_pkg")"
	[[ -n $_snap ]] || { _speed_debug_log "PROCESS_OBSERVER_FALLBACK_RESTORE_SKIP token=$_token pkg=$_pkg reason=no-snapshot log=$_log"; return 0; }
	_restored="$(_process_observer_log_last_for_pkg "$_log" 'APP_WAKE_BLOCK_RESTORE_DONE ' "$_pkg")"
	if [[ -n $_restored ]]; then
		_speed_debug_log "PROCESS_OBSERVER_FALLBACK_RESTORE_SKIP token=$_token pkg=$_pkg reason=already-restored log=$_log"
		return 0
	fi
	_user="$(_process_observer_log_kv "$_snap" user)"
	case $_user in ''|*[!0-9]*) _user="${USER_ID:-${user:-0}}" ;; esac
	_run_bg="$(_process_observer_log_kv "$_snap" runBg)"
	_run_any="$(_process_observer_log_kv "$_snap" runAny)"
	_bucket="$(_process_observer_log_kv "$_snap" standbyBucket)"
	_run_bg_touched="$(_process_observer_log_kv "$_apply" runBgTouched)"
	_run_any_touched="$(_process_observer_log_kv "$_apply" runAnyTouched)"
	_bucket_touched="$(_process_observer_log_kv "$_apply" standbyTouched)"
	_speed_debug_log "PROCESS_OBSERVER_FALLBACK_RESTORE_BEGIN token=$_token pkg=$_pkg user=$_user reason=$_reason log=$_log runBg=$_run_bg runAny=$_run_any standby=$_bucket touched=${_run_bg_touched}/${_run_any_touched}/${_bucket_touched}"
	if [[ $_bucket_touched = true ]] && _process_observer_bucket_valid "$_bucket"; then
		if [[ $_bucket = exempted ]]; then
			cmd deviceidle whitelist +"$_pkg" >/dev/null 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}; _rc=$?
			[[ $_rc = 0 ]] || { dumpsys deviceidle whitelist +"$_pkg" >/dev/null 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}; _rc=$?; }
			_speed_debug_log "PROCESS_OBSERVER_FALLBACK_RESTORE stage=deviceidle-whitelist token=$_token pkg=$_pkg target=true originalBucket=exempted rc=$_rc"
		else
			am set-standby-bucket --user "$_user" "$_pkg" "$_bucket" >/dev/null 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}; _rc=$?
			_speed_debug_log "PROCESS_OBSERVER_FALLBACK_RESTORE stage=standby token=$_token pkg=$_pkg target=$_bucket rc=$_rc"
		fi
		_did=1
	else
		_speed_debug_log "PROCESS_OBSERVER_FALLBACK_RESTORE stage=standby skipped=true token=$_token pkg=$_pkg touched=$_bucket_touched target=$_bucket"
	fi
	if [[ $_run_any_touched = true ]] && _process_observer_appop_mode_valid "$_run_any"; then
		cmd appops set --user "$_user" "$_pkg" RUN_ANY_IN_BACKGROUND "$_run_any" >/dev/null 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}; _rc=$?
		_speed_debug_log "PROCESS_OBSERVER_FALLBACK_RESTORE stage=appops op=RUN_ANY_IN_BACKGROUND token=$_token pkg=$_pkg target=$_run_any rc=$_rc"
		_did=1
	else
		_speed_debug_log "PROCESS_OBSERVER_FALLBACK_RESTORE stage=appops op=RUN_ANY_IN_BACKGROUND skipped=true token=$_token pkg=$_pkg touched=$_run_any_touched target=$_run_any"
	fi
	if [[ $_run_bg_touched = true ]] && _process_observer_appop_mode_valid "$_run_bg"; then
		cmd appops set --user "$_user" "$_pkg" RUN_IN_BACKGROUND "$_run_bg" >/dev/null 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}; _rc=$?
		_speed_debug_log "PROCESS_OBSERVER_FALLBACK_RESTORE stage=appops op=RUN_IN_BACKGROUND token=$_token pkg=$_pkg target=$_run_bg rc=$_rc"
		_did=1
	else
		_speed_debug_log "PROCESS_OBSERVER_FALLBACK_RESTORE stage=appops op=RUN_IN_BACKGROUND skipped=true token=$_token pkg=$_pkg touched=$_run_bg_touched target=$_run_bg"
	fi
	_speed_debug_log "PROCESS_OBSERVER_FALLBACK_RESTORE_DONE token=$_token pkg=$_pkg did=$_did reason=$_reason"
	return 0
}

_process_observer_dex_cleanup_retained_state() {
	local _token="$1" _pkg="$2" _reason="$3" _out _rc _flat _user
	_process_observer_pkg_safe_for_shell "$_pkg" || { _speed_debug_log "PROCESS_OBSERVER_DEX_RETAINED_CLEANUP_SKIP token=$_token pkg=$_pkg reason=unsafe-pkg"; return 0; }
	_user="${USER_ID:-${user:-0}}"
	case $_user in ''|*[!0-9]*) _user=0 ;; esac
	_out="$(_webdav_tmp_path process_observer_retained_cleanup_${$}_$RANDOM)"
	dex_hiddenapi_raw appWakeBlockRestorePackage "$_user" "$_pkg" > "$_out" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	_rc=$?
	_flat="$(tr '\n' '|' < "$_out" | cut -c1-500)"
	_speed_debug_log "PROCESS_OBSERVER_DEX_RETAINED_CLEANUP token=$_token pkg=$_pkg user=$_user reason=$_reason rc=$_rc out=$_flat"
	if [[ $_rc != 0 ]] || ! grep -F 'APP_WAKE_BLOCK_PERSISTENT_RESTORE_DONE' "$_out" >/dev/null 2>&1 || ! grep -F 'stateDeleted=true' "$_out" >/dev/null 2>&1; then
		if [[ ${_PROCESS_OBSERVER_CLEANUP_STALE_DONE:-0} != 1 ]]; then
			_PROCESS_OBSERVER_CLEANUP_STALE_DONE=1
			: > "$_out"
			dex_hiddenapi_raw appWakeBlockCleanupStale "post-restore-retained-${_reason:-unknown}" 0 > "$_out" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
			_rc=$?
			_flat="$(tr '
' '|' < "$_out" | cut -c1-500)"
			_speed_debug_log "PROCESS_OBSERVER_DEX_FORCE_CLEANUP token=$_token pkg=$_pkg reason=$_reason rc=$_rc out=$_flat"
		else
			_speed_debug_log "PROCESS_OBSERVER_DEX_FORCE_CLEANUP_SKIP token=$_token pkg=$_pkg reason=$_reason already_done=1"
		fi
	fi
	rm -f "$_out" 2>/dev/null
	return 0
}

_process_observer_stop_token() {
	local _token="$1" _reason="$2" _pkg="$3" _entry="$4" _log="$5" _out _rc _flat _skip_status=0
	[[ -n $_token ]] || return 0
	case $_reason in
	exit_cleanup|restore_post_appstate_done|restore_post_appstate_final) _skip_status=1 ;;
	backup_app_scope_done|payload-rc-*)
		# r260: backup payload/scope stop 後的 top/foreground 查詢只作觀測，r259 實測 123 App 全量備份會多燒大量 RootDaemon/unixsock round-trip。
		# 預設跳過；需要逐 entry stop 後觀測時可設 SPEEDBACKUP_PROCESS_OBSERVER_STOP_STATUS_VERIFY=1。
		case "${SPEEDBACKUP_PROCESS_OBSERVER_STOP_STATUS_VERIFY:-0}" in
		1|true|TRUE|yes|YES|on|ON) _skip_status=0 ;;
		*) _skip_status=1 ;;
		esac ;;
	esac
	_out="$(_webdav_tmp_path process_observer_stop_${$}_$RANDOM)"
	dex_hiddenapi_raw processObserverStop "$_token" "${USER_ID:-${user:-0}}" "$_pkg" > "$_out" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	_rc=$?
	_flat="$(tr '\n' '|' < "$_out" | cut -c1-500)"
	_speed_debug_log "PROCESS_OBSERVER_STOP token=$_token reason=$_reason pkg=$_pkg entry=$_entry rc=$_rc out=$_flat"
	if [[ $_skip_status != 1 ]]; then
		_process_observer_top_status "${_reason}_${_entry}_after_stop" >/dev/null 2>&1 || true
		[[ -n $_pkg ]] && _process_observer_foreground_status "$_pkg" "${_reason}_${_entry}_after_stop" >/dev/null 2>&1 || true
	else
		_speed_debug_log "PROCESS_OBSERVER_STOP_STATUS_SKIP token=$_token reason=$_reason pkg=$_pkg entry=$_entry mode=r260-backup-fast"
	fi
	if grep -F 'APP_WAKE_BLOCK_PERSISTENT_RESTORE_DONE' "$_out" >/dev/null 2>&1 && grep -F 'stateDeleted=true' "$_out" >/dev/null 2>&1; then
		_speed_debug_log "PROCESS_OBSERVER_DEX_PERSISTENT_RESTORE_OK token=$_token reason=$_reason pkg=$_pkg stateDeleted=true"
	elif grep -F 'APP_WAKE_BLOCK_STOP_OK' "$_out" >/dev/null 2>&1 && grep -F 'stateDeleted=true' "$_out" >/dev/null 2>&1; then
		_speed_debug_log "PROCESS_OBSERVER_DEX_RESTORE_OK token=$_token reason=$_reason pkg=$_pkg stateDeleted=true"
	elif [[ $_rc != 0 ]] || grep -E 'PROCESS_OBSERVER_STOP_MISSING|APP_WAKE_BLOCK_STOP_MISSING|APP_WAKE_BLOCK_STOP_FAILED|APP_WAKE_BLOCK_RESTORE_FAILED|APP_WAKE_BLOCK_PERSISTENT_RESTORE_MISSING|APP_WAKE_BLOCK_PERSISTENT_RESTORE_FAILED|APP_WAKE_BLOCK_PERSISTENT_RESTORE_REJECTED|stateRetained=true|stateDeleted=false' "$_out" >/dev/null 2>&1; then
		_process_observer_fallback_restore_from_log "$_token" "$_pkg" "$_log" "$_reason" || true
		_process_observer_dex_cleanup_retained_state "$_token" "$_pkg" "$_reason" || true
	fi
	_process_observer_remove_state_token "$_token"
	rm -f "$_out" 2>/dev/null
	return $_rc
}

_process_observer_stop_current() {
	local _rc="$1" _token="${PROCESS_OBSERVER_TOKEN:-}" _pkg="${PROCESS_OBSERVER_PKG:-}" _entry="${PROCESS_OBSERVER_ENTRY:-}" _log="${PROCESS_OBSERVER_LOG:-}"
	PROCESS_OBSERVER_TOKEN=""
	PROCESS_OBSERVER_PKG=""
	PROCESS_OBSERVER_ENTRY=""
	PROCESS_OBSERVER_LOG=""
	[[ -n $_token ]] || return 0
	_process_observer_stop_token "$_token" "payload-rc-${_rc:-unknown}" "$_pkg" "$_entry" "$_log"
}

_process_observer_stop_app() {
	local _reason="${1:-app-scope-done}" _token="${PROCESS_OBSERVER_APP_TOKEN:-}" _pkg="${PROCESS_OBSERVER_APP_PKG:-}" _label="${PROCESS_OBSERVER_APP_LABEL:-}" _stage="${PROCESS_OBSERVER_APP_STAGE:-}" _log="${PROCESS_OBSERVER_APP_LOG:-}"
	PROCESS_OBSERVER_APP_TOKEN=""
	PROCESS_OBSERVER_APP_PKG=""
	PROCESS_OBSERVER_APP_LABEL=""
	PROCESS_OBSERVER_APP_STAGE=""
	PROCESS_OBSERVER_APP_LOG=""
	if [[ -z $_token ]]; then
		if [[ -n $_pkg ]] && _process_observer_batch_pkg_active "$_pkg"; then
			if [[ ${PROCESS_OBSERVER_BATCH_SCOPE:-} = restore_session ]]; then
				case $_reason in
				restore_app_scope_done|restore_stream_fatal|app-switch-restore_app_scope)
					_speed_debug_log "RESTORE_GUARD_SESSION_KEEP pkg=$_pkg label=$_label reason=$_reason scope=restore_session release=bulk-post-appstate mode=r427"
					return 0 ;;
				esac
			fi
			_process_observer_batch_release_pkg "$_pkg" "$_label" "$_reason" || true
			_backup_app_quiesce_scope_cache_clear "$_pkg" "process-observer-batch-release-${_reason}" || true
		fi
		return 0
	fi
	if [[ $_reason = restore_app_scope_done && $_stage = restore_app_scope ]] && _restore_post_state_guard_defer_pkg "$_pkg" process_observer; then
		_speed_debug_log "PROCESS_OBSERVER_APP_DEFER token=$_token reason=$_reason pkg=$_pkg label=$_label stage=$_stage until=restore_post_appstate"
		return 0
	fi
	_process_observer_stop_token "$_token" "$_reason" "$_pkg" "app" "$_log"
	_speed_debug_log "PROCESS_OBSERVER_APP_STOP token=$_token reason=$_reason pkg=$_pkg label=$_label stage=$_stage"
	_backup_app_quiesce_scope_cache_clear "$_pkg" "process-observer-app-stop-${_reason}" || true
}

_process_observer_stop_all() {
	_process_observer_batch_stop "${1:-cleanup}" || true
	_backup_app_quiesce_scope_cache_clear "" "process-observer-stop-all" || true
	PROCESS_OBSERVER_APP_TOKEN=""; PROCESS_OBSERVER_APP_PKG=""; PROCESS_OBSERVER_APP_LABEL=""; PROCESS_OBSERVER_APP_STAGE=""; PROCESS_OBSERVER_APP_LOG=""
	local _reason="${1:-cleanup}" _state _tmp _token _pkg _label _entry _stage _log _scope _total=0 _idx=0
	_state="$(_process_observer_token_state_file)"
	[[ -s $_state ]] || return 0
	_tmp="$TMPDIR/.process_observer_tokens_cleanup_${$}_$RANDOM"
	cp -f "$_state" "$_tmp" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} || return 0
	_total="$(awk 'NF{n++} END{print n+0}' "$_tmp" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null})"
	case $_total in ''|*[!0-9]*) _total=0 ;; esac
	[[ $_total -gt 0 ]] && _speedbackup_progress_step 0 "$_total" "正在解除 ProcessObserver 守護" "process_observer_stop_all" "107"
	while IFS='	' read -r _token _pkg _label _entry _stage _log _scope; do
		[[ -n $_token ]] || continue
		_idx=$((_idx + 1))
		_speedbackup_progress_step "$_idx" "$_total" "解除 ProcessObserver ${_label:-$_pkg}" "process_observer_stop_all" "107"
		_process_observer_stop_token "$_token" "$_reason" "$_pkg" "$_entry" "$_log" >/dev/null 2>&1 || true
	done < "$_tmp"
	rm -f "$_tmp" "$_state" 2>/dev/null
	return 0
}

_pkg_process_pids() {
	local _pkg="$1"
	[[ -n $_pkg ]] || return 0
	if _process_observer_pkg_alive_pids "$_pkg" "pkg_process_pids"; then
		return 0
	fi
	Process_Information "$_pkg" | awk 'NF && $1 ~ /^[0-9]+$/ {print $1}' | sort -n | uniq
}

_pkg_process_count() {
	_pkg_process_pids "$1" | awk 'NF{n++} END{print n+0}'
}

_wait_pkg_process_gone() {
	local _pkg="$1" _i _cnt
	[[ -n $_pkg ]] || return 0
	for _i in 1 2 3 4 5; do
		_cnt="$(_pkg_process_count "$_pkg")"
		case $_cnt in ''|*[!0-9]*) _cnt=0 ;; esac
		[[ $_cnt -eq 0 ]] && return 0
		sleep 0.1
	done
	return 1
}

_backup_hard_quiesce_stable_cache_file() {
	printf '%s\n' "${TMPDIR:-/data/local/tmp}/.speedbackup_hard_quiesce_stable_cache"
}
_backup_hard_quiesce_stable_cache_ttl_ms() {
	local _ttl="${SPEEDBACKUP_HARD_QUIESCE_STABLE_CACHE_TTL_MS:-600000}"
	case $_ttl in ''|*[!0-9]*) _ttl=600000 ;; esac
	[[ $_ttl -lt 0 ]] && _ttl=0
	printf '%s\n' "$_ttl"
}
_backup_hard_quiesce_stable_cache_mark() {
	local _pkg="$1" _label="$2" _entry="$3" _phase="$4" _state _now
	[[ -n $_pkg ]] || return 0
	_state="$(_backup_hard_quiesce_stable_cache_file)"
	_now="$(_speed_now_ms)"
	mkdir -p "${_state%/*}" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} || true
	awk -F '\t' -v p="$_pkg" '$1!=p{print}' "$_state" 2>/dev/null > "${_state}.tmp" || : > "${_state}.tmp"
	printf '%s\t%s\t%s\t%s\t%s\t%s\n' "$_pkg" "${USER_ID:-${user:-0}}" "$_now" "$_entry" "$_phase" "$_label" >> "${_state}.tmp"
	mv -f "${_state}.tmp" "$_state" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} || rm -f "${_state}.tmp" 2>/dev/null
	_speed_debug_log "HARD_QUIESCE_STABLE_WAIT_CACHE_MARK pkg=$_pkg label=$_label entry=$_entry phase=$_phase tsMs=$_now"
	return 0
}
_backup_hard_quiesce_stable_cache_clear_pkg() {
	local _pkg="$1" _reason="${2:-unknown}" _state
	[[ -n $_pkg ]] || return 0
	_state="$(_backup_hard_quiesce_stable_cache_file)"
	[[ -s $_state ]] || return 0
	awk -F '\t' -v p="$_pkg" '$1!=p{print}' "$_state" 2>/dev/null > "${_state}.tmp" || : > "${_state}.tmp"
	mv -f "${_state}.tmp" "$_state" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} || rm -f "${_state}.tmp" 2>/dev/null
	_speed_debug_log "HARD_QUIESCE_STABLE_WAIT_CACHE_CLEAR pkg=$_pkg reason=$_reason"
	return 0
}
_backup_hard_quiesce_stable_cache_hit() {
	local _pkg="$1" _label="$2" _entry="$3" _phase="$4" _state _line _ts _now _age _ttl _cnt
	[[ -n $_pkg ]] || return 1
	case $_entry in user|user_de|data) ;; *) return 1 ;; esac
	_state="$(_backup_hard_quiesce_stable_cache_file)"
	[[ -s $_state ]] || return 1
	_line="$(awk -F '\t' -v p="$_pkg" '$1==p{line=$0} END{print line}' "$_state" 2>/dev/null)"
	[[ -n $_line ]] || return 1
	_ts="$(printf '%s\n' "$_line" | awk -F '\t' '{print $3}')"
	case $_ts in ''|*[!0-9]*) return 1 ;; esac
	_ttl="$(_backup_hard_quiesce_stable_cache_ttl_ms)"
	[[ $_ttl -gt 0 ]] || return 1
	_now="$(_speed_now_ms)"
	_age=$((_now - _ts))
	[[ $_age -ge 0 && $_age -le $_ttl ]] || return 1
	_cnt="$(_pkg_process_count "$_pkg" 2>/dev/null)"
	case $_cnt in ''|*[!0-9]*) _cnt=0 ;; esac
	if [[ $_cnt -eq 0 ]]; then
		_speed_debug_log "HARD_QUIESCE_STABLE_WAIT_CACHE_HIT pkg=$_pkg label=$_label entry=$_entry phase=$_phase ageMs=$_age ttlMs=$_ttl verifyAlive=0 action=skip-full-stable-wait"
		return 0
	fi
	_speed_debug_log "HARD_QUIESCE_STABLE_WAIT_CACHE_STALE pkg=$_pkg label=$_label entry=$_entry phase=$_phase ageMs=$_age ttlMs=$_ttl verifyAlive=$_cnt action=full-stable-wait"
	_backup_hard_quiesce_stable_cache_clear_pkg "$_pkg" "respawn-before-${_phase}-${_entry}" >/dev/null 2>&1 || true
	return 1
}

_backup_hard_quiesce_stable_wait_enabled() {
	case "${SPEEDBACKUP_HARD_QUIESCE_STABLE_WAIT:-1}" in
	0|false|FALSE|no|NO|off|OFF|disable|DISABLE) return 1 ;;
	esac
	return 0
}

_backup_hard_quiesce_stable_wait() {
	local _pkg="$1" _label="$2" _entry="$3" _phase="$4" _ms _need _max _i _stable _cnt _last_cnt _procwait_rc
	[[ -n $_pkg ]] || return 0
	_backup_hard_quiesce_stable_wait_enabled || return 0
	_process_observer_high_risk_pkg "$_pkg" || return 0
	case $_entry in data|user|user_de) ;; *) return 0 ;; esac
	if _backup_hard_quiesce_stable_cache_hit "$_pkg" "$_label" "$_entry" "$_phase"; then
		return 0
	fi
	if _cgroup_freezer_app_active_for_pkg "$_pkg"; then
		if _speedbackup_cgroup_fast_settle_pkg "$_pkg"; then
			_speed_debug_log "HARD_QUIESCE_STABLE_WAIT_SKIP_CGROUP_ACTIVE pkg=$_pkg label=$_label entry=$_entry phase=$_phase token=${CGROUP_FREEZER_APP_TOKEN:-} reason=cgroup-fast-settle-r330"
		else
			_speed_debug_log "HARD_QUIESCE_STABLE_WAIT_SKIP_CGROUP_ACTIVE pkg=$_pkg label=$_label entry=$_entry phase=$_phase token=${CGROUP_FREEZER_APP_TOKEN:-} reason=cgroup-freezer-primary"
		fi
		return 0
	fi
	_ms="${SPEEDBACKUP_HARD_QUIESCE_STABLE_MS:-2500}"
	case $_ms in ''|*[!0-9]*) _ms=2500 ;; esac
	[[ $_ms -le 0 ]] && return 0
	_need=$(((_ms + 99) / 100))
	[[ $_need -lt 1 ]] && _need=1
	[[ $_need -gt 50 ]] && _need=50
	_max="${SPEEDBACKUP_HARD_QUIESCE_STABLE_MAX_LOOPS:-80}"
	case $_max in ''|*[!0-9]*) _max=80 ;; esac
	[[ $_max -lt $_need ]] && _max=$_need
	_speed_debug_log "HARD_QUIESCE_STABLE_WAIT_BEGIN pkg=$_pkg label=$_label entry=$_entry phase=$_phase needLoops=$_need maxLoops=$_max ms=$_ms engine=procwait-first"
	_force_stop_pkg_best_effort "$_pkg" "hard_quiesce_stable_${_phase}_${_entry}" >/dev/null 2>&1 || true
	_procwait_pkg_gone "$_pkg" "$((_ms + 1200))" "$_ms" "backup_hard_quiesce_${_phase}_${_entry}" "${user:-${USER_ID:-0}}"
	_procwait_rc=$?
	if [[ $_procwait_rc = 0 ]]; then
		_speed_debug_log "HARD_QUIESCE_STABLE_WAIT_OK pkg=$_pkg label=$_label entry=$_entry phase=$_phase engine=procwait stableMs=$_ms"
		_backup_hard_quiesce_stable_cache_mark "$_pkg" "$_label" "$_entry" "$_phase" || true
		return 0
	fi
	if [[ $_procwait_rc != 125 ]]; then
		_cnt="$(_pkg_process_count "$_pkg" 2>/dev/null)"
		case $_cnt in ''|*[!0-9]*) _cnt=0 ;; esac
		if [[ $_cnt -gt 0 ]]; then
			_force_stop_pkg_best_effort "$_pkg" "hard_quiesce_stable_respawn_${_phase}_${_entry}" >/dev/null 2>&1 || true
			_procwait_pkg_gone "$_pkg" "$((_ms + 800))" "$_ms" "backup_hard_quiesce_retry_${_phase}_${_entry}" "${user:-${USER_ID:-0}}" && {
				_speed_debug_log "HARD_QUIESCE_STABLE_WAIT_OK pkg=$_pkg label=$_label entry=$_entry phase=$_phase engine=procwait-retry stableMs=$_ms"
				_backup_hard_quiesce_stable_cache_mark "$_pkg" "$_label" "$_entry" "$_phase" || true
				return 0
			}
		fi
		_speed_debug_log "HARD_QUIESCE_STABLE_WAIT_TIMEOUT pkg=$_pkg label=$_label entry=$_entry phase=$_phase engine=procwait rc=$_procwait_rc lastAlive=${_cnt:-unknown}"
		_backup_hard_quiesce_stable_cache_clear_pkg "$_pkg" "timeout-procwait-${_phase}-${_entry}" >/dev/null 2>&1 || true
		return 1
	fi
	_speed_debug_log "HARD_QUIESCE_STABLE_WAIT_FALLBACK pkg=$_pkg label=$_label entry=$_entry phase=$_phase reason=procwait_unavailable"
	_i=0
	_stable=0
	_last_cnt=unknown
	while [[ $_i -lt $_max ]]; do
		_cnt="$(_pkg_process_count "$_pkg" 2>/dev/null)"
		case $_cnt in ''|*[!0-9]*) _cnt=0 ;; esac
		_last_cnt="$_cnt"
		if [[ $_cnt -eq 0 ]]; then
			_stable=$((_stable + 1))
			if [[ $_stable -ge $_need ]]; then
				_speed_debug_log "HARD_QUIESCE_STABLE_WAIT_OK pkg=$_pkg label=$_label entry=$_entry phase=$_phase loops=$((_i + 1)) stableLoops=$_stable engine=shell-fallback"
				_backup_hard_quiesce_stable_cache_mark "$_pkg" "$_label" "$_entry" "$_phase" || true
				return 0
			fi
		else
			[[ $_stable -gt 0 ]] && _speed_debug_log "HARD_QUIESCE_STABLE_WAIT_RESET pkg=$_pkg entry=$_entry phase=$_phase alive=$_cnt stableLoops=$_stable"
			_stable=0
			_force_stop_pkg_best_effort "$_pkg" "hard_quiesce_stable_respawn_${_phase}_${_entry}" >/dev/null 2>&1 || true
		fi
		sleep 0.1
		_i=$((_i + 1))
	done
	_speed_debug_log "HARD_QUIESCE_STABLE_WAIT_TIMEOUT pkg=$_pkg label=$_label entry=$_entry phase=$_phase loops=$_i stableLoops=$_stable lastAlive=$_last_cnt engine=shell-fallback"
	_backup_hard_quiesce_stable_cache_clear_pkg "$_pkg" "timeout-${_phase}-${_entry}" >/dev/null 2>&1 || true
	return 1
}

_stop_app_pkg_cmd() {
	local _pkg="$1" _u="${user:-0}"
	[[ -n $_pkg ]] || return 1
	_process_observer_status_cache_invalidate_pkg "$_pkg" "before_stop_app_cmd" >/dev/null 2>&1 || true
	if cmd activity stop-app --user "$_u" "$_pkg" >/dev/null 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}; then
		_process_observer_status_cache_invalidate_pkg "$_pkg" "after_stop_app_cmd_user" >/dev/null 2>&1 || true
		return 0
	fi
	if cmd activity stop-app "$_pkg" >/dev/null 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}; then
		_process_observer_status_cache_invalidate_pkg "$_pkg" "after_stop_app_cmd" >/dev/null 2>&1 || true
		return 0
	fi
	_process_observer_status_cache_invalidate_pkg "$_pkg" "after_stop_app_cmd_fail" >/dev/null 2>&1 || true
	return 1
}

_stop_pkg_for_backup() {
	local _pkg="$1" _label="$2" _cnt
	[[ -n $_pkg ]] || return 1
	# r127: foreground/live-app quiesce also uses daemon forceStopPackage first.
	# cmd activity stop-app is kept only as a compatibility fallback, avoiding shell on the normal path.
	if _force_stop_pkg_best_effort "$_pkg" "$_label"; then
		if _wait_pkg_process_gone "$_pkg"; then
			_speed_debug_log "QUIESCE_STOP_OK method=force_stop_best_effort pkg=$_pkg label=$_label"
			return 0
		fi
		_cnt="$(_pkg_process_count "$_pkg")"
		_speed_debug_log "QUIESCE_STOP_RESPAWN method=force_stop_best_effort pkg=$_pkg remaining_pids=${_cnt:-unknown}"
	fi
	if _stop_app_pkg_cmd "$_pkg"; then
		if _wait_pkg_process_gone "$_pkg"; then
			_speed_debug_log "QUIESCE_STOP_OK method=cmd_activity_stop_app_fallback pkg=$_pkg label=$_label"
			return 0
		fi
		_cnt="$(_pkg_process_count "$_pkg")"
		_speed_debug_log "QUIESCE_STOP_RESPAWN method=cmd_activity_stop_app_fallback pkg=$_pkg remaining_pids=${_cnt:-unknown}"
	fi
	return 1
}

_live_app_resume_paused() {
	local _pid _pkg="${LIVE_APP_PAUSED_PKG:-}" _pids="${LIVE_APP_PAUSED_PIDS:-}" _pids_csv
	if [[ -n $_pids ]]; then
		for _pid in $_pids; do
			case $_pid in ''|*[!0-9]*) continue ;; esac
			kill -CONT "$_pid" 2>/dev/null
		done
		_pids_csv="$(printf '%s' "$_pids" | tr '\n' ',')"
		_speed_debug_log "QUIESCE_RESUME pids=$_pids_csv pkg=$_pkg"
		LIVE_APP_PAUSED_PIDS=""
		LIVE_APP_PAUSED_PKG=""
	fi
	# r55 保險：正常流程每個 app/資料項結束會解凍；EXIT trap 也會走這裡，避免異常退出留下入口暫停。
	_live_app_unsuspend_all
	return 0
}

_live_app_recover_stale_suspended_on_start() {
	local _state
	_state="$(_live_app_suspended_state_file)"
	[[ -e $_state ]] && rm -f "$_state" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} || true
	return 0
}

# r56: 若前一次被 kill -9、Termux 被系統回收、手機重啟前未跑到 EXIT trap，
# .speedbackup_live_app_suspended 會殘留；本次啟動時先解凍，避免 App 長時間入口暫停。
_live_app_recover_stale_suspended_on_start

_live_app_pause_pids() {
	local _pkg="$1" _label="$2" _force="${3:-0}" _pids _after _pid _new=0
	[[ -n $_pkg ]] || return 1
	[[ $_force = 1 ]] || _live_app_pause_enabled || return 1
	if [[ $_force != 1 ]] && _pkg_is_quiesce_never_pause "$_pkg"; then
		_speed_debug_log "QUIESCE_PAUSE_DENY_CRITICAL pkg=$_pkg label=$_label"
		return 1
	fi
	_pids="$(_pkg_process_pids "$_pkg")"
	[[ -n $_pids ]] || return 1
	for _pid in $_pids; do
		case $_pid in ''|*[!0-9]*) continue ;; esac
		kill -STOP "$_pid" 2>/dev/null || _new=1
	done
	if [[ $_new = 1 ]]; then
		for _pid in $_pids; do case $_pid in ''|*[!0-9]*) continue ;; esac; kill -CONT "$_pid" 2>/dev/null; done
		_speed_debug_log "QUIESCE_PAUSE_FAIL_SIGNAL pkg=$_pkg label=$_label"
		return 1
	fi
	sleep 0.1
	_after="$(_pkg_process_pids "$_pkg")"
	_new=0
	while read -r _pid; do
		[[ -n $_pid ]] || continue
		printf '%s\n' "$_pids" | grep -qx "$_pid" || _new=1
	done <<EOFQAFTER
$_after
EOFQAFTER
	if [[ $_new = 1 ]]; then
		for _pid in $_pids; do case $_pid in ''|*[!0-9]*) continue ;; esac; kill -CONT "$_pid" 2>/dev/null; done
		_speed_debug_log "QUIESCE_PAUSE_FAIL_NEW_PID pkg=$_pkg label=$_label before=$(printf '%s' "$_pids" | tr '\n' ',') after=$(printf '%s' "$_after" | tr '\n' ',')"
		return 1
	fi
	LIVE_APP_PAUSED_PKG="$_pkg"
	LIVE_APP_PAUSED_PIDS="$_pids"
	_speed_debug_log "QUIESCE_PAUSE_OK pkg=$_pkg label=$_label pids=$(printf '%s' "$_pids" | tr '\n' ',')"
	return 0
}

# r261: app-scope quiesce cache. 先把「同一 App 已靜止/無進程/已由 cgroup 接管」升級成 app 級狀態，
# 避免 data/user/user_de 每個 entry 都重新跑 top/foreground/force-stop/pid poll。
_BACKUP_APP_QUIESCE_CACHE_PKG=""
_BACKUP_APP_QUIESCE_CACHE_LABEL=""
_BACKUP_APP_QUIESCE_CACHE_STATE=""
_BACKUP_APP_QUIESCE_CACHE_TS_MS=0
_BACKUP_APP_QUIESCE_CACHE_ENTRY=""
_backup_app_quiesce_scope_cache_enabled() {
	case "${SPEEDBACKUP_APP_QUIESCE_SCOPE_CACHE:-1}" in
	0|false|FALSE|no|NO|off|OFF|disable|DISABLE) return 1 ;;
	esac
	return 0
}
_backup_app_quiesce_scope_cache_clear() {
	local _pkg="$1" _reason="${2:-clear}"
	if [[ -z $_pkg || $_pkg = "${_BACKUP_APP_QUIESCE_CACHE_PKG:-}" ]]; then
		_speed_debug_log "APP_SCOPE_QUIESCE_CACHE_CLEAR pkg=${_pkg:-${_BACKUP_APP_QUIESCE_CACHE_PKG:-all}} reason=$_reason state=${_BACKUP_APP_QUIESCE_CACHE_STATE:-none}"
		_BACKUP_APP_QUIESCE_CACHE_PKG=""
		_BACKUP_APP_QUIESCE_CACHE_LABEL=""
		_BACKUP_APP_QUIESCE_CACHE_STATE=""
		_BACKUP_APP_QUIESCE_CACHE_TS_MS=0
		_BACKUP_APP_QUIESCE_CACHE_ENTRY=""
	fi
	return 0
}
_backup_app_quiesce_scope_cache_mark() {
	local _pkg="$1" _label="$2" _state="$3" _entry="${4:-unknown}" _now
	_backup_app_quiesce_scope_cache_enabled || return 0
	[[ -n $_pkg && -n $_state ]] || return 0
	_now="$(_speed_now_ms)"
	_BACKUP_APP_QUIESCE_CACHE_PKG="$_pkg"
	_BACKUP_APP_QUIESCE_CACHE_LABEL="$_label"
	_BACKUP_APP_QUIESCE_CACHE_STATE="$_state"
	_BACKUP_APP_QUIESCE_CACHE_TS_MS="$_now"
	_BACKUP_APP_QUIESCE_CACHE_ENTRY="$_entry"
	_speed_debug_log "APP_SCOPE_QUIESCE_CACHE_MARK pkg=$_pkg label=$_label state=$_state entry=$_entry tsMs=$_now"
	return 0
}
_backup_app_quiesce_scope_cache_hit() {
	local _pkg="$1" _label="$2" _entry="$3" _now _age _ttl _state
	_backup_app_quiesce_scope_cache_enabled || return 1
	case $_entry in user|data|obb|user_de) ;; *) return 1 ;; esac
	[[ -n $_pkg && $_pkg = "${_BACKUP_APP_QUIESCE_CACHE_PKG:-}" ]] || return 1
	_state="${_BACKUP_APP_QUIESCE_CACHE_STATE:-}"
	case $_state in inactive|no_process|stopped_active|stopped_running|paused_active|paused_running|cgroup_active) ;; *) return 1 ;; esac
	_ttl="${SPEEDBACKUP_APP_QUIESCE_SCOPE_CACHE_TTL_MS:-900000}"
	case $_ttl in ''|*[!0-9]*) _ttl=900000 ;; esac
	_now="$(_speed_now_ms)"
	_age=$((_now - ${_BACKUP_APP_QUIESCE_CACHE_TS_MS:-0}))
	[[ $_age -ge 0 && $_age -le $_ttl ]] || { _speed_debug_log "APP_SCOPE_QUIESCE_CACHE_STALE pkg=$_pkg label=$_label entry=$_entry state=$_state ageMs=$_age ttlMs=$_ttl action=full-kill-app"; return 1; }
	_speed_debug_log "APP_SCOPE_QUIESCE_CACHE_HIT pkg=$_pkg label=$_label entry=$_entry state=$_state firstEntry=${_BACKUP_APP_QUIESCE_CACHE_ENTRY:-unknown} ageMs=$_age ttlMs=$_ttl action=skip-kill-app"
	return 0
}

_backup_unsafe_live_skip_file() {
	printf '%s\n' "${TMPDIR:-/data/local/tmp}/.speedbackup_unsafe_live_app_scope_skip"
}
_backup_pkg_unsafe_live_skip_should_persist() {
	local _pkg="$1" _home
	[[ -n $_pkg ]] || return 1
	if _pkg_is_quiesce_never_pause "$_pkg"; then
		return 0
	fi
	_default_home_pkg_ensure >/dev/null 2>&1 || true
	_home="${_DEFAULT_HOME_PKG_CACHE:-}"
	[[ -n $_home && $_pkg = "$_home" ]] && return 0
	return 1
}
_backup_pkg_mark_unsafe_live_skip() {
	local _pkg="$1" _label="$2" _reason="$3" _state _now
	_backup_pkg_unsafe_live_skip_should_persist "$_pkg" || return 0
	_state="$(_backup_unsafe_live_skip_file)"
	_now="$(_speed_now_ms)"
	mkdir -p "${_state%/*}" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} || true
	awk -F '\t' -v p="$_pkg" '$1!=p{print}' "$_state" 2>/dev/null > "${_state}.tmp" || : > "${_state}.tmp"
	printf '%s\t%s\t%s\t%s\t%s\n' "$_pkg" "${USER_ID:-${user:-0}}" "$_now" "$_reason" "$_label" >> "${_state}.tmp"
	mv -f "${_state}.tmp" "$_state" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} || rm -f "${_state}.tmp" 2>/dev/null
	_speed_debug_log "BACKUP_UNSAFE_LIVE_APP_SCOPE_MARK pkg=$_pkg label=$_label reason=$_reason action=skip-remaining-data-entries"
	return 0
}
_backup_pkg_unsafe_live_skip_hit() {
	local _pkg="$1" _entry="$2" _state _line _reason
	[[ -n $_pkg ]] || return 1
	case $_entry in user|data|obb|user_de) ;; *) return 1 ;; esac
	_state="$(_backup_unsafe_live_skip_file)"
	[[ -s $_state ]] || return 1
	_line="$(awk -F '\t' -v p="$_pkg" '$1==p{line=$0} END{print line}' "$_state" 2>/dev/null)"
	[[ -n $_line ]] || return 1
	_reason="$(printf '%s\n' "$_line" | awk -F '\t' '{print $4}')"
	_speed_debug_log "BACKUP_UNSAFE_LIVE_APP_SCOPE_SKIP pkg=$_pkg entry=$_entry reason=${_reason:-marked_respawn} action=skip-without-retry"
	return 0
}

# 強制終止/靜止指定 app (foregroundStateBatch daemon + stop-app/force-stop + bounded pid poll + optional STOP/CONT pause)
# 回傳: 0=可繼續備份/恢復, 125=不安全/常駐綁定/force-stop 後立即復活，呼叫端應跳過該 data entry。
kill_app() {
	local _active_rc _remaining _speedbackup_data_scope_word
	case ${_RESTORE_STREAM:-0}:${restore_mode:-}:${Action:-} in
		1:*:*|*:restore:*|*:*restore*) _speedbackup_data_scope_word="恢復" ;;
		*) _speedbackup_data_scope_word="備份" ;;
	esac
	KILL_APP_UNSAFE_SKIP=0
	[[ -n $name2 ]] || return 0
	case $name2 in
	bin.mt.plus|com.termux|bin.mt.plus.canary)
		_speed_debug_log "KILL_APP_SKIP_SELF pkg=$name2"
		return 0
		;;
	esac
	# r261: kill_app_before 的 top 是純觀測，foreground 會在 _foreground_state_pkg_active 內查一次；不要重複做。
	case "${SPEEDBACKUP_KILL_APP_TOP_STATUS_VERIFY:-0}" in
	1|true|TRUE|yes|YES|on|ON|enable|ENABLE) _process_observer_top_status "kill_app_before" >/dev/null 2>&1 || true ;;
	*) _speed_debug_log "KILL_APP_TOP_STATUS_SKIP pkg=$name2 label=$name1 mode=r261-appscope-fast" ;;
	esac
	if _cgroup_freezer_app_active_for_pkg "$name2"; then
		_speed_debug_log "KILL_APP_SKIP_CGROUP_ACTIVE pkg=$name2 label=$name1 token=${CGROUP_FREEZER_APP_TOKEN:-} reason=cgroup-freezer-primary"
		_backup_app_quiesce_scope_cache_mark "$name2" "$name1" "cgroup_active" "kill_app" || true
		return 0
	fi
	_foreground_state_pkg_active "$name2"
	_active_rc=$?
	case $_active_rc in
	0)
		if _stop_pkg_for_backup "$name2" "$name1"; then
			echoRgb "事件瞬殺成功" "1"
			_speed_debug_log "TERMINAL_EVENT_KILL_RESULT pkg=$name2 label=$name1 result=success method=quiesce_stop active=true"
			_speed_debug_log "QUIESCE_ENTRY_CGROUP_ONLY pkg=$name2 label=$name1 reason=backup_restore_after_stop_active iconGrey=false"
			_speed_debug_log "KILL_APP_DONE method=quiesce_stop pkg=$name2 active=true remaining_pids=0"
			_backup_app_quiesce_scope_cache_mark "$name2" "$name1" "stopped_active" "kill_app" || true
			return 0
		fi
		if _live_app_pause_pids "$name2" "$name1"; then
			echoRgb "事件瞬殺失敗，已改用暫停進程" "2"
			_speed_debug_log "TERMINAL_EVENT_KILL_RESULT pkg=$name2 label=$name1 result=paused method=stop_cont active=true"
			_speed_debug_log "QUIESCE_ENTRY_CGROUP_ONLY pkg=$name2 label=$name1 reason=backup_restore_after_pid_pause_active iconGrey=false"
			_speed_debug_log "KILL_APP_PAUSED method=stop_cont pkg=$name2 active=true"
			_backup_app_quiesce_scope_cache_mark "$name2" "$name1" "paused_active" "kill_app" || true
			return 0
		fi
		_remaining="$(_pkg_process_count "$name2")"
		KILL_APP_UNSAFE_SKIP=1
		echoRgb "事件瞬殺失敗" "0"
		echoRgb "${name1} 停止後仍立即復活，為避免腳本被系統殺死，跳過此資料項${_speedbackup_data_scope_word:-備份}" "0"
		_speed_debug_log "KILL_APP_UNSAFE_SKIP_RESPAWN method=quiesce_stop pkg=$name2 remaining_pids=${_remaining:-unknown}"
		_backup_pkg_mark_unsafe_live_skip "$name2" "$name1" "quiesce_stop_respawn" || true
		return 125
		;;
	1)
		_speed_debug_log "KILL_APP_SKIP_INACTIVE method=foregroundStateBatch_daemon pkg=$name2 active=false"
		_backup_app_quiesce_scope_cache_mark "$name2" "$name1" "inactive" "kill_app" || true
		;;
	*)
		process_Information="$(Process_Information "$name2")"
		if [[ $process_Information != "" ]]; then
			if _stop_pkg_for_backup "$name2" "$name1"; then
				echoRgb "事件瞬殺成功" "1"
				_speed_debug_log "TERMINAL_EVENT_KILL_RESULT pkg=$name2 label=$name1 result=success method=dumpsys_quiesce_stop active=unknown"
				_speed_debug_log "QUIESCE_ENTRY_CGROUP_ONLY pkg=$name2 label=$name1 reason=backup_restore_after_stop_running iconGrey=false"
				_speed_debug_log "KILL_APP_DONE method=dumpsys_quiesce_stop pkg=$name2 pids=$(printf '%s\n' "$process_Information" | awk 'NF{n++} END{print n+0}') remaining_pids=0"
				_backup_app_quiesce_scope_cache_mark "$name2" "$name1" "stopped_running" "kill_app" || true
				return 0
			fi
			if _live_app_pause_pids "$name2" "$name1"; then
				echoRgb "事件瞬殺失敗，已改用暫停進程" "2"
				_speed_debug_log "TERMINAL_EVENT_KILL_RESULT pkg=$name2 label=$name1 result=paused method=dumpsys_stop_cont active=unknown"
				_speed_debug_log "QUIESCE_ENTRY_CGROUP_ONLY pkg=$name2 label=$name1 reason=backup_restore_after_pid_pause_running iconGrey=false"
				_speed_debug_log "KILL_APP_PAUSED method=dumpsys_stop_cont pkg=$name2"
				_backup_app_quiesce_scope_cache_mark "$name2" "$name1" "paused_running" "kill_app" || true
				return 0
			fi
			_remaining="$(_pkg_process_count "$name2")"
			KILL_APP_UNSAFE_SKIP=1
			echoRgb "事件瞬殺失敗" "0"
			echoRgb "${name1} 停止後仍立即復活，為避免腳本被系統殺死，跳過此資料項${_speedbackup_data_scope_word:-備份}" "0"
			_speed_debug_log "KILL_APP_UNSAFE_SKIP_RESPAWN method=dumpsys_quiesce_stop pkg=$name2 remaining_pids=${_remaining:-unknown}"
			_backup_pkg_mark_unsafe_live_skip "$name2" "$name1" "dumpsys_quiesce_stop_respawn" || true
			return 125
		else
			_speed_debug_log "KILL_APP_SKIP_NO_PROCESS method=dumpsys_fallback pkg=$name2"
			_backup_app_quiesce_scope_cache_mark "$name2" "$name1" "no_process" "kill_app" || true
		fi
		;;
	esac
	return 0
}
# ======================================================

# 取得當前 apk versionCode。優先使用預掃 .pkg_ver，失敗才 fallback。
# 避免單獨備份/部分 ROM 下 .pkg_ver 未命中時，把 app_details.apk_version 覆蓋成空值。
get_current_apk_version_code() {
	local _pkg="$1" _v="" _tmp
	[[ -z $_pkg ]] && { echo ""; return 0; }
	if [[ -f $TMPDIR/.pkg_ver ]]; then
		_v="$(_kv_file_get "$TMPDIR/.pkg_ver" "$_pkg" | tr -d ' \t\r\n')"
	fi
	if [[ -z $_v ]]; then
		_tmp="$TMPDIR/.pkg_ver_refresh_$$"
		: > "$_tmp" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
		appinventory pkgVerMap all refresh 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} >> "$_tmp"
		if [[ -s $_tmp ]]; then
			cat "$_tmp" > "$TMPDIR/.pkg_ver" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
			_v="$(_kv_file_get "$TMPDIR/.pkg_ver" "$_pkg" | tr -d ' \t\r\n')"
		fi
		rm -f "$_tmp" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	fi
	if [[ -z $_v ]]; then
		_speed_debug_log "APP_VERSION_LOOKUP_FAIL pkg=$_pkg source=inventory_map,inventory_refresh fallback=off"
	fi
	echo "$_v"
}

# 備份核心函數 (Backup_apk / Backup_data / unified AppState)
# ======================================================
# 備份 app 的 apk 檔 (含 split apk, 用 tar/zstd 打包)
Backup_apk() {
	# 契約 guard：nobackup 只可能是 "true"/"false"，兩個既有呼叫點 (12610/12612)
	# 呼叫前都已經 [[ $nobackup != true ]] 過濾，所以這裡進來時 nobackup 必為 "false"。
	# 明確寫成 guard，不再依賴函式內部一個「其實恆真」的 if 分支。
	[[ $nobackup = false ]] || return 0
	#檢測apk狀態進行備份
	#創建APP備份文件夾
	[[ ! -d $Backup_folder ]] && mkdir -p "$Backup_folder"
	[[ ! -f $app_details ]] && echo "{\n}">"$app_details"
	# 從預掃 map 查當前版本 (取代 fork pm + cut + head)；未命中時 fallback，避免單獨備份把版本寫成空值
	eval "apk_version2=\${_pv_${name2//[!a-zA-Z0-9]/_}}"
	[[ -z $apk_version2 ]] && apk_version2="$(get_current_apk_version_code "$name2")"
	if [[ -z $apk_version2 ]]; then
		# 最後防線：保留舊版本值，避免 app_details.apk_version 被覆蓋成空字串而觸發 JSON 健全度缺 apk_version
		apk_version2="$APK_VER"
		[[ -z $apk_version2 ]] && apk_version2="unknown"
		echoRgb "當前apk版本號獲取失敗，保留/寫入保底版本:$apk_version2" "0"
	fi
	# 如果啟用遠程備份，從遠端獲取 app_details.json 進行對比
	local _remote_checked=0
	if [[ -n $remote_type ]]; then
		local remote_app_details="$TMPDIR/.remote_app_details_$$"
		local remote_rel="${name1}/app_details.json"
		if _get_remote_appdetails "$name1" "$remote_app_details" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}; then
			[[ -s $remote_app_details ]] && {
				_remote_checked=1
				# 從遠端 app_details 讀取版本號
				local remote_apk_ver
				remote_apk_ver="$(_appdetails_get_entry_apk_version "$remote_app_details" "$name1")"
				# 如果遠端版本與當前版本一致，且本地或遠端已有 apk 備份，才跳過備份。
				# v24.20.14-7.13：非流式 remote_keep_local=0 會在上傳成功後刪本地 tar，
				# 下一輪應以遠端檔案存在作為 skip 依據，避免本地缺檔而重壓/重傳。
				local _local_apk_exists=0
				if [[ -f "$Backup_folder/apk.tar.zst" ]] || [[ -f "$Backup_folder/apk.tar" ]]; then
					_local_apk_exists=1
				fi
				if [[ $remote_stream != 1 && -n $remote_type && -f $TMPDIR/.remote_files ]]; then
					if awk -v a="$name1/apk.tar.zst" -v b="$name1/apk.tar" '$0==a||$0==b{f=1;exit} END{exit !f}' "$TMPDIR/.remote_files" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}; then
						_local_apk_exists=1
						_speed_debug_log "REMOTE_APK_EXISTS package=$name2 app=$name1 source=remote_files"
					fi
				fi
				# 流式模式: 遠端有且版本一致即可跳過 (不需本機 tar, 因流式本就不留本地)
				[[ $remote_stream = 1 ]] && _local_apk_exists=1
				if [[ -s "$TMPDIR/.listver_changed" ]] && awk -v p="$name2" '$0==p{f=1} END{exit !f}' "$TMPDIR/.listver_changed" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}; then
					# 啟動檢查偵測到實機版本已變: 遠端 json 版本號不可信 (可能被失敗輪汙染), 強制重備
					echoRgb "清單偵測到版本已更新, 重新備份apk" "3"
				elif [[ -n $remote_apk_ver && $remote_apk_ver = "$apk_version2" && $_local_apk_exists = 1 ]]; then
					# 版本相符再核對遠端 apk 檔實際存在 (json 可能被舊版/失敗輪汙染而 apk 缺檔)
					_rapk_ok=0
					if [[ $remote_stream = 1 ]]; then
						if awk -v a="$name1/apk.tar.zst" -v b="$name1/apk.tar" '$0==a||$0==b{f=1;exit} END{exit !f}' "$TMPDIR/.remote_files" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}; then
							_rapk_ok=1
						else
							# 列表沒找到 (可能中文名轉碼) → 單檔下載開頭確認
							case "$(_stream_download "${_BACKUP_DIRNAME_CACHED:-$(get_backup_dirname)}/$name1/apk.tar.zst" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} | head -c 60)" in
							""|*NT_STATUS*) _rapk_ok=0 ;;
							*) _rapk_ok=1 ;;
							esac
						fi
					else
						_rapk_ok=1
					fi
					if [[ $_rapk_ok = 1 ]]; then
						_backup_mark_done_pkg
						# 遠端非流式且 APK 無變化時，要先用遠端 app_details.json 作為本輪本地種子。
						# 否則本地 app_details 只是新建的 {}，後續 Backup_metadata_once 會誤判 permissions/installer/battery 全部缺失，
						# 造成第二次增量仍重新備份/上傳 JSON。
						if [[ $remote_stream != 1 && -n $remote_type && -s $remote_app_details ]]; then
							cp "$remote_app_details" "$app_details" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
							app_details_read "$app_details"
							_speed_debug_log "REMOTE_APPDETAILS_SEED app=$name1 package=$name2 source=remote_apk_skip"
						fi
						unset xb
						let osj++
						result=0
						echoRgb "Apk版本無更新(遠端備份無變化) 跳過備份" "2"
						rm -f "$remote_app_details"
						return 0
					fi
					echoRgb "版本相符但遠端缺apk檔, 補備份一次" "0"
				fi
			}
		fi
		rm -f "$remote_app_details"
		# 遠端啟用但查無此備份: 即使本地版本未變, 仍會備份並上傳一次
		[[ $_remote_checked = 0 ]] && echoRgb "遠端無此備份 將備份一次並上傳" "2"
	fi
	# APK_VER 已經由 app_details_read 載入 (在主迴圈呼叫過)
	apk_version="$APK_VER"
	# 遠端已啟用但無備份時，不應依據本地 app_details 跳過，應上傳到遠端
	_local_apk_exists=0
	if [[ -f "$Backup_folder/apk.tar.zst" ]] || [[ -f "$Backup_folder/apk.tar" ]]; then
		_local_apk_exists=1
	fi
	# 流式模式: 不依賴本機 tar (本機可能有舊備份殘留), 強制當作無本機檔, 走重新壓縮流式
	[[ $remote_stream = 1 ]] && _local_apk_exists=0
	if [[ $apk_version = $apk_version2 ]] && [[ $_local_apk_exists = 1 ]]; then
		# 版本一致且本地已有備份: 不重新打包
		_backup_mark_done_pkg
		unset xb
		let osj++
		result=0
		# 遠端啟用但查無此備份: 不重壓, 直接把現有本地檔標記為待上傳 (流式無本地檔, 不走此路)
		if [[ $remote_stream != 1 && -n $remote_type && $_remote_checked = 0 ]]; then
			backup_has_changes=1
			_mark_changed
			echoRgb "Apk版本無更新 遠端缺檔: 直接上傳本地備份(免重壓)" "2"
		else
			echoRgb "Apk版本無更新 跳過備份" "2"
		fi
	else
		# nobackup=false 已由函式開頭 guard 保證，這裡不再重複判斷。
		# 版本一致且本地已有 apk 備份: 不重壓 (避免重複備份)
		if [[ $apk_version != "" && $apk_version = "$apk_version2" && $_local_apk_exists = 1 ]]; then
			let osj++
			echoRgb "版本:$apk_version 無更新 跳過備份" "2"
			_backup_mark_done_pkg
			result=0
			return 0
		fi
		if [[ $apk_version != "" ]]; then
			if [[ $apk_version = "$apk_version2" ]]; then
				let osj++
				if [[ $remote_stream = 1 || -n $remote_type ]]; then
					echoRgb "版本:$apk_version (遠端無此版本, 補備份一次)"
				else
					echoRgb "版本:$apk_version (本機無備份檔, 補備份一次)"
				fi
			else
				let osn++
				# 用暫存檔取代字串拼接
				echo "$name1 \"$name2\"" >> "$TMPDIR/.update_apks"
				echoRgb "版本:$apk_version>$apk_version2"
			fi
		else
			let osk++
			echo "$name1 \"$name2\"" >> "$TMPDIR/.add_apks"
			echoRgb "版本:$apk_version2"
		fi
		unset Filesize
		Filesize="$(calc_dir_size "$apk_path2")"
		_archive_cleanup "$Backup_folder/apk"
		partition_info "$Backup" "$name1 apk"
		if [[ $Skip != 1 ]]; then
			#備份apk
			echoRgb "$1"
			echo "$apk_path" | sed -e '/^$/d' | while read -r; do
				echoRgb "${REPLY##*/} $(size "$REPLY")"
			done
			BACKUP_TAR_CONTEXT_PKG="$name2"
			BACKUP_TAR_CONTEXT_LABEL="$name1"
			BACKUP_TAR_CONTEXT_ENTRY="apk"
			_backup_apk_archive_stage
			BACKUP_TAR_CONTEXT_PKG=""; BACKUP_TAR_CONTEXT_LABEL=""; BACKUP_TAR_CONTEXT_ENTRY=""
			if [[ $result = 0 ]]; then
				_backup_apk_stage_record_success "$apk_version" "$apk_version2"
			else
				rm -rf "$Backup_folder"
			fi
		fi
	fi
	[[ $name2 = bin.mt.plus && ! -f $Backup/$name1.apk ]] && cp -r "$apk_path" "$Backup/$name1.apk"
}
# 壓縮持久化 AppState：Dex 可輸出完整診斷快照，但 app_details.json 只保存恢復必要欄位 + 快速查看 cn 欄位。
# 目的：移除 engineVersion/dexVersion/package uid/installDiagnostics/result/json_refresh 等 debug/診斷資料。
# 注意：raw 欄位仍完整保留；nameCn/modeCn/keyCn 等 cn 欄位保留作快速查看，不參與恢復判斷。
_appstate_compact_jq_defs() {
	cat <<'JQ'
def addif($o; $k): if (($o|type) == "object" and ($o|has($k))) then {($k): $o[$k]} else {} end;
def notnull: with_entries(select(.value != null));
def perm($p): (
	{} + addif($p;"name") + addif($p;"nameCn") + addif($p;"granted") + addif($p;"flags") +
	addif($p;"runtime") + addif($p;"development") + addif($p;"appOp") +
	addif($p;"appOpName") + addif($p;"appOpNameCn") + addif($p;"packageMode") + addif($p;"uidMode") +
	addif($p;"scope") + addif($p;"appOpMode") + addif($p;"appOpModeName") + addif($p;"appOpModeCn")
) | notnull;
def special($s): (
	{} + addif($s;"keyCn") + addif($s;"publicName") + addif($s;"publicNameCn") + addif($s;"manifestPermission") +
	addif($s;"manifestPermissionCn") + addif($s;"requested") + addif($s;"supported") + addif($s;"op") +
	addif($s;"packageMode") + addif($s;"uidMode") + addif($s;"scope") +
	addif($s;"mode") + addif($s;"modeName") + addif($s;"modeCn")
) | notnull;
def opobj($o): (
	{} + addif($o;"op") + addif($o;"publicName") + addif($o;"publicNameCn") + addif($o;"supported") +
	addif($o;"packageMode") + addif($o;"uidMode") + addif($o;"scope") +
	addif($o;"mode") + addif($o;"modeName") + addif($o;"modeCn")
) | notnull;
def compact_state($s): {
	schemaVersion: ($s.schemaVersion // 2),
	recordType: ($s.recordType // "snapshot"),
	userId: ($s.userId // 0),
	packageName: ($s.packageName // null),
	installer: ($s.installer // $s.package.installer // $s.installDiagnostics.installer // $s.installDiagnostics.installing // null),
	permissions: [($s.permissions // [])[] | perm(.)],
	specialAccess: (($s.specialAccess // {}) | with_entries(.value = special(.value))),
	batterySettings: (($s.batterySettings // {}) | with_entries(if (.value|type)=="object" then .value = opobj(.value) else . end)),
	otherAppOps: [($s.otherAppOps // [])[] | opobj(.)],
	ssaid: ($s.ssaid // null)
};
JQ
}
_appstate_persist_compact() {
	jq -c "$(_appstate_compact_jq_defs)
compact_state(.)" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
}

_appstate_persist_compact_file() {
	local _in="$1" _out="$2"
	[[ -s $_in && -n $_out ]] || return 1
	_appstate_persist_compact < "$_in" > "$_out" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
}

# 將 app_details.json 收斂成唯一 canonical restore profile；保留快速查看 cn 欄位。
# 正常備份與「重生現有備份JSON」都必須走同一個出口，避免兩邊 app_state/app entry/root metadata 結構不一致。
# 輸出固定使用 jq pretty JSON；所有正常備份/JSON重生出口都應保持同一格式。
_app_details_normalize_restore_profile_file() {
	local _file="$1" _tmp _jq _rc
	[[ -s $_file ]] || return 1
	_tmp="${_file}.canon_${$}_$RANDOM"
	_jq="${_tmp}.jq"
	_appstate_compact_jq_defs > "$_jq" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} || { rm -f "$_tmp" "$_jq" 2>/dev/null; return 1; }
	cat >> "$_jq" <<'JQ'
def pick_entry($e):
	reduce ["keystore","path","Size","size","apk_size","data_size","obb_size","media_size","origin_size","apk_version","versionCode","PackageName"][] as $k
	({}; if (($e|type)=="object" and ($e|has($k))) then .[$k]=$e[$k] else . end);
def is_payload_entry($e):
	(($e|type)=="object") and (
		($e|has("Size")) or ($e|has("size")) or ($e|has("path")) or ($e|has("keystore")) or
		($e|has("apk_size")) or ($e|has("data_size")) or ($e|has("obb_size")) or
		($e|has("media_size")) or ($e|has("origin_size"))
	);
def entry($e): (
	pick_entry($e) +
	{PackageName: ($e.PackageName // $e.app_state.packageName // null)} +
	(if (($e.app_state // null)|type) == "object" then {app_state: compact_state($e.app_state)} else {} end)
) | notnull;
def payload_entry($e): (pick_entry($e)) | notnull;
. as $root |
({}
 + (if ($root|has("Backup time")) then {"Backup time": $root["Backup time"]} else {} end)
) as $base |
reduce ($root|to_entries[]) as $it ($base;
	if ($it.key == "Backup time") then .
	elif (($it.value|type)=="object" and ($it.value.PackageName != null or $it.value.app_state.packageName != null)) then .[$it.key] = entry($it.value)
	elif is_payload_entry($it.value) then .[$it.key] = payload_entry($it.value)
	else . end)
JQ
	jq -f "$_jq" "$_file" > "$_tmp" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} || { rm -f "$_tmp" "$_jq" 2>/dev/null; return 1; }
	_json_cat_replace "$_tmp" "$_file"
	_rc=$?
	if [[ $_rc = 0 ]]; then
		# 438: canonical profile 仍由既有 shell/jq API 產生；Dex 只負責 AppState snapshot/restore/verify，不接管 app_details JSON。
		rm -f "$_file.pre360.bak" "$_file".pre*.bak 2>/dev/null
	fi
	rm -f "$_tmp" "$_jq" 2>/dev/null
	return $_rc
}

# 寫入每個 App 的唯一 canonical AppState 快照。
# 權限、AppOps、特殊存取、電池與 SSAID 均已包含在同一份 schema v2 JSON。
Backup_AppState() {
	local _state_raw_file _state_file _old_file _old_cmp_file _missing=0 _state_ok=0
	_state_raw_file="$TMPDIR/.appstate_raw_${$}_$RANDOM.json"
	_state_file="$TMPDIR/.appstate_compact_${$}_$RANDOM.json"
	_old_file="$TMPDIR/.appstate_old_${$}_$RANDOM.json"
	_old_cmp_file="$TMPDIR/.appstate_old_cmp_${$}_$RANDOM.json"
	rm -f "$_state_raw_file" "$_state_file" "$_old_file" "$_old_cmp_file" 2>/dev/null
	if ! _kv_file_get_to_file "$TMPDIR/.pkg_appstate" "$name2" "$_state_raw_file" || [[ ! -s $_state_raw_file ]]; then
		echoRgb "AppState快照缺失或格式錯誤: $name2" "0"
		_speed_debug_log "APPSTATE_BACKUP_SKIP package=$name2 reason=missing_or_invalid_canonical_snapshot_file"
		rm -f "$_state_raw_file" "$_state_file" "$_old_file" "$_old_cmp_file" 2>/dev/null
		return 1
	fi
	if ! _appstate_snapshot_persistable_ok "$_state_raw_file"; then
		echoRgb "AppState快照缺失或格式錯誤: $name2" "0"
		_speed_debug_log "APPSTATE_BACKUP_SKIP package=$name2 reason=missing_or_invalid_canonical_snapshot"
		rm -f "$_state_raw_file" "$_state_file" "$_old_file" "$_old_cmp_file" 2>/dev/null
		return 1
	fi
	if ! _appstate_persist_compact < "$_state_raw_file" > "$_state_file" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}; then
		echoRgb "AppState持久化裁剪失敗: $name2" "0"
		_speed_debug_log "APPSTATE_BACKUP_SKIP package=$name2 reason=persist_compact_failed"
		rm -f "$_state_raw_file" "$_state_file" "$_old_file" "$_old_cmp_file" 2>/dev/null
		return 1
	fi
	if ! _appstate_snapshot_persistable_ok "$_state_file"; then
		echoRgb "AppState持久化裁剪失敗: $name2" "0"
		_speed_debug_log "APPSTATE_BACKUP_SKIP package=$name2 reason=persist_compact_failed"
		rm -f "$_state_raw_file" "$_state_file" "$_old_file" "$_old_cmp_file" 2>/dev/null
		return 1
	fi
	app_details_has_key "$app_details" "$name1" "app_state" || _missing=1
	_appdetails_get_entry_app_state_file "$app_details" "$name1" "$_old_file" || printf '%s\n' null > "$_old_file"
	# 432: 比對前先把舊 app_state 也壓成同一個 persist/canonical profile，
	# 避免舊 SMB 備份中的 allowed/診斷欄位/顯示欄位造成「允許→允許」假變更。
	if [[ $_missing = 0 ]] && _appstate_snapshot_persistable_ok "$_old_file" && _appstate_persist_compact_file "$_old_file" "$_old_cmp_file"; then
		:
	else
		cat "$_old_file" > "$_old_cmp_file" 2>/dev/null || printf '%s\n' null > "$_old_cmp_file"
	fi
	if [[ $_missing = 1 ]] || ! cmp -s "$_old_cmp_file" "$_state_file" 2>/dev/null; then
		[[ $_missing = 0 ]] && _appstate_show_backup_diff_file "$_old_cmp_file" "$_state_file"
		if _appdetails_put_app_state_file "$app_details" "$name1" "$_state_file"; then
			if _app_details_normalize_restore_profile_file "$app_details"; then
				_speed_debug_log "APPDETAILS_CANONICAL_PROFILE_OK source=normal_backup app=$name1 package=$name2"
			else
				_speed_debug_log "APPDETAILS_CANONICAL_PROFILE_FAIL source=normal_backup app=$name1 package=$name2"
			fi
			# echo_log 依賴上一條命令退出碼；不能放在 [[ $_missing = 1 ]] && echoRgb 後面，
			# 否則 app_state 已成功寫入但 _missing=0 時會被誤報失敗。
			echo_log "備份統一AppState快照"
			[[ $_missing = 1 ]] && echoRgb "寫入統一AppState快照" "2"
			_mark_changed
			rm -f "$_state_raw_file" "$_state_file" "$_old_file" "$_old_cmp_file" 2>/dev/null
			return 0
		fi
		result=1
		_speed_debug_log "APPSTATE_BACKUP_JQ_UPDATE_FAILED package=$name2 app_details=$app_details"
		rm -f "$_state_raw_file" "$_state_file" "$_old_file" "$_old_cmp_file" 2>/dev/null
		return 1
	fi
	rm -f "$_state_raw_file" "$_state_file" "$_old_file" "$_old_cmp_file" 2>/dev/null
	return 0
}
# 每個 app metadata 只寫一次 canonical app_state；不再拆成 permissions/AppOps/特殊存取/電池/SSAID 多份欄位。
Backup_metadata_once() {
	local _md_vn="_md_${name2//[!a-zA-Z0-9]/_}" _md_done
	eval "_md_done=\${$_md_vn:-0}"
	[[ $_md_done = 1 ]] && return 0
	[[ -f $app_details ]] || return 0
	Backup_AppState || return 1
	eval "$_md_vn=1"
}

#檢測數據位置進行備份
# ===== 備份資料與恢復資料 =====
_backup_remote_stream_fatal_payloads_active() {
	local _app="$1" _pkg="$2" _where="$3"
	if [[ ${remote_stream:-0} = 1 && -n ${remote_type:-} ]] && _remote_stream_fatal_active; then
		echoRgb "遠端流式已中斷，停止 ${_app:-unknown} 後續 payload 備份" "0"
		_speed_debug_log "REMOTE_STREAM_FATAL_ABORT_APP_PAYLOADS app=$_app package=$_pkg where=$_where $(_remote_stream_fatal_summary) mode=r377"
		return 0
	fi
	return 1
}

Backup_data() {
	data_path="$path/$1/$name2"
	MODDIR_NAME="${data_path%/*}"
	MODDIR_NAME="${MODDIR_NAME##*/}"
	# 取舊 Size:
	# - 應用備份 ($1 = user/data/obb/user_de): 直接讀 app_details_read 預讀的變數
	# - 媒體備份 ($1 = 動態資料夾名 Download/DCIM/...): 預讀變數沒有, fallback 用 jq 即時查
	# - 其他 (thanox 等): 同 fallback
	Size=""
	case $1 in
	user|data|obb|user_de|media)
		eval "Size=\"\$SIZE_$1\""
		;;
	*)
		[[ -f $app_details ]] && Size="$(_appdetails_get_entry_size "$app_details" "$1")"
		;;
	esac
	[[ -z $Size ]] && Size=""
	case $1 in
	user) data_path="$path2/$name2" ;;
	user_de) data_path="$path3/$name2" ;;
	data|obb|media) ;;
	*)
		data_path="$2"
		# 自訂資料夾固定用 tar 打包 (不透過暫改全域 Compression_method 再復原這種做法,
		# 改用 local override 變數, 避免備份結尾等其他環節讀到中途被污染的全域值)
		[[ $1 != thanox && $1 != hma ]] && local _comp_override=tar
		if [[ $1 != thanox && $1 != hma ]]; then
			local _media_display_path _media_lower_path
			_media_display_path="$data_path"
			_media_lower_path="$(_media_storage_lower_path "$data_path" 2>/dev/null)"
			if [[ -n $_media_lower_path && -d $_media_lower_path ]]; then
				data_path="$_media_lower_path"
				_speed_debug_log "MEDIA_BACKUP_LOWER_PATH entry=$1 displayPath=$(_media_path_log_value "$_media_display_path") actualPath=$(_media_path_log_value "$data_path") action=use_data_media_lower mode=r374"
			else
				_speed_debug_log "MEDIA_BACKUP_LOWER_PATH_SKIP entry=$1 displayPath=$(_media_path_log_value "$_media_display_path") candidate=$(_media_path_log_value "$_media_lower_path") reason=missing_or_not_dir mode=r374"
			fi
		fi
		zsize=1
		zmediapath=1
		;;
	esac
	# 如果啟用遠程備份，從遠端獲取 app_details.json 進行對比
	local _remote_data_checked=0
	if [[ -n $remote_type ]]; then
		local remote_app_details="$TMPDIR/.remote_app_details_$$"
		local _remote_lookup_name
		case $1 in
		user|data|obb|user_de|media|thanox|hma) _remote_lookup_name="$name1" ;;
		# 自訂資料夾 (如 Download/DCIM): 所有資料夾共用同一份 Media/app_details.json,
		# 不是各自獨立的 "$1/app_details.json" — 查詢路徑必須固定用 "Media"
		*) _remote_lookup_name="Media" ;;
		esac
		local remote_rel="${_remote_lookup_name}/app_details.json"
		local _remote_appdetails_rc=0
		_get_remote_appdetails "$_remote_lookup_name" "$remote_app_details" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
		_remote_appdetails_rc=$?
		if [[ $_remote_appdetails_rc != 0 && $_remote_appdetails_rc != 2 ]]; then
			# 重試一次, 避免單次網路抖動導致整段增量比對失效。
			# rc=2 代表預掃已確認遠端不存在，不能當錯誤重試/刷診斷。
			sleep 1
			_get_remote_appdetails "$_remote_lookup_name" "$remote_app_details" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
			_remote_appdetails_rc=$?
		fi
		if [[ -s $remote_app_details ]]; then
			{
				# 從遠端 app_details 讀取 Size
				local remote_size
				remote_size="$(_appdetails_get_entry_size "$remote_app_details" "$1")"
				[[ $_INCREMENTAL_DEBUG = 1 ]] && _speed_debug_log "REMOTE_APPDETAILS_SIZE query=$_remote_lookup_name entry=$1 json_bytes=$(wc -c < "$remote_app_details" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}) remote_size=$remote_size"
				# 如果遠端 Size 與當前一致，跳過備份
				if [[ -n $remote_size && $remote_size != "null" ]]; then
					_remote_data_checked=1
					local current_size
					_dir_size "$name2" "$1" "$data_path"; current_size="$_DIR_SIZE_RET"
					# 本地或遠端必須已有該 tar 才可跳過，否則全新備份會漏掉。
					# r375: 流式遠端也不能無條件視為 payload 存在；必須查遠端列表/本輪成功上傳 note。
					# 否則 app_details Size 一致但 DuckDetector/user_de.tar.zst 這類實體缺檔會被誤判「無變化」。
					local _local_data_exists=0 _remote_data_rel_a _remote_data_rel_b _payload_missing_known=0
					ls "$Backup_folder/$1.tar"* >/dev/null 2>&1 && _local_data_exists=1
					case $1 in
					user|data|obb|user_de|media|thanox|hma)
						_remote_data_rel_a="$name1/$1.tar.zst"; _remote_data_rel_b="$name1/$1.tar" ;;
					*)
						_remote_data_rel_a="Media/$1.tar.zst"; _remote_data_rel_b="Media/$1.tar" ;;
					esac
					if [[ -n $remote_type && -f $TMPDIR/.remote_files ]]; then
						if _remote_files_note_has_any_rel "$_remote_data_rel_a" "$_remote_data_rel_b"; then
							_local_data_exists=1
							_speed_debug_log "REMOTE_DATA_EXISTS app=$name1 entry=$1 rel=$_remote_data_rel_a source=remote_files_or_upload_note mode=r377"
						fi
					fi
					if [[ $remote_stream = 1 ]] && _remote_payload_missing_hit "$name1" "$1"; then
						_payload_missing_known=1
						_local_data_exists=0
						_speed_debug_log "REMOTE_PAYLOAD_MISSING_FORCE_BACKUP app=$name1 package=$name2 entry=$1 rel=$_remote_data_rel_a remoteSize=$remote_size currentSize=$current_size mode=r377"
					fi
					if [[ "$remote_size" = "$current_size" && $_local_data_exists = 1 && $_payload_missing_known != 1 ]]; then
						echoRgb "$1數據無變化(遠端備份無變化) 跳過備份" "2"
						rm -f "$remote_app_details"
						return 0
					fi
				fi
			}
		else
			if [[ $_INCREMENTAL_DEBUG = 1 ]]; then
				if [[ $_remote_appdetails_rc = 2 ]]; then
					_speed_debug_log "REMOTE_APPDETAILS_MISSING query=$_remote_lookup_name rel=$remote_rel known_missing=1"
				else
					echoRgb "[診斷] 查詢=$_remote_lookup_name _get_remote_appdetails失敗(重試後仍下載失敗 rc=$_remote_appdetails_rc)" "0" >&2
				fi
			fi
		fi
		rm -f "$remote_app_details"
	fi
	if [[ -d $data_path ]]; then
		unset Filesize ssaid Get_Permissions result Permissions
		_dir_size "$name2" "$1" "$data_path"; Filesize="$_DIR_SIZE_RET"
		# ssaid/permissions 只要是 user 類型就無條件執行 (不依賴 size 變化)
		case $1 in
		user)
			Backup_metadata_once
			;;
		esac
		# 太小不備份是使用者設定語義：不能把 0 bytes / <1KB 寫成正常 payload Size，
		# 否則 app_details 會看起來像「已有 user_de/data 備份」，但遠端實際沒有 tar。
		# 這裡只做早期 skip，避免遠端缺 Size 時每輪進入備份、kill_app、partition_info，
		# 但不更新 payload entry、不標 changed_apps、不觸發上傳 app_details。
		if [[ -n $Filesize && ${#Filesize} -lt 4 ]]; then
			local _small_size_text
			_small_size_text="$(size "${Filesize:-0}")"
			echoRgb "$1數據 $_small_size_text太小，依設定不備份" "2"
			_speed_debug_log "DATA_SMALL_SKIP_NO_RECORD app=$name1 package=$name2 entry=$1 size=${Filesize:-0}"
			result=0
			return 0
		fi
		[[ $Filesize != "" ]] && {
		# 遠端缺檔但本地 Size 無變化且本地 tar 已存在: 不重壓, 直接標記上傳現有本地檔
		local _local_data_exists2=0
		_archive_exists "$Backup_folder/$1" && _local_data_exists2=1
		# 流式模式: 忽略本機殘留 tar, 強制重新壓縮流式上傳
		stream_enabled && _local_data_exists2=0
		if ! stream_enabled && remote_enabled && [[ $_remote_data_checked = 0 && $Size = $Filesize && $_local_data_exists2 = 1 ]]; then
			backup_has_changes=1
			case $1 in user|data|obb|user_de|media) _mark_changed ;; esac
			echoRgb "$1數據無變化 遠端缺檔: 直接上傳本地備份(免重壓)" "2"
			return 0
		fi
		# 遠端已啟用但無備份時，即使本地 Size 無變化也應上傳到遠端
		local _force_data_backup=0
		# 遠端已啟用時，匹配的情況已在上面 return 0，走到這裡代表遠端要嘛沒有 Size 要嘛不匹配，都應備份
		remote_enabled && _force_data_backup=1
		# v24.20.14-7.66-14：本地模式不能只依賴殘留 app_details.json 的 Size 判斷跳過。
		# remote_keep_local=0 上傳成功後可能刪除 data/user tar，但舊 JSON 仍殘留；
		# 若 Size 一致但本機 tar 已不存在，必須補備份一次，避免本地備份目錄只有 JSON 沒有資料包。
		if ! remote_enabled && [[ $Size = $Filesize && $_local_data_exists2 != 1 ]]; then
			_force_data_backup=1
			echoRgb "$1數據無變化但本機無備份檔, 補備份一次" "2"
		fi
		if [[ $Size != $Filesize ]] || [[ $_force_data_backup = 1 ]]; then
			case $1 in
			user)
				# 從預掃的 pkg→uid map 查 uid (省去 fork pm + awk)
				local _uid
				eval "_uid=\${_pu_${name2//[!a-zA-Z0-9]/_}}"
				if [[ -n $_uid ]] && [[ $(su "$_uid" -c keystore_cli_v2 list 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} | wc -l) -ge 2 ]]; then
					echoRgb "$name1包含keystore 恢復可能閃退" "0"
					_appdetails_set_keystore "$app_details" "$name1" true
				else
					_appdetails_set_keystore "$app_details" "$name1" false
				fi ;;
			esac
			#停止應用；輸入法也不再特例放過，與普通 App 同走 stop-app/force-stop/pid poll；仍不使用廣域 kill -9/pkill。
			case $1 in
			user|data|obb|user_de)
				if _backup_pkg_unsafe_live_skip_hit "$name2" "$1"; then
					echoRgb "$name1 $1資料因前一資料項已判定存活/系統綁定，直接跳過備份" "0"
					_speed_debug_log "DATA_SKIP_UNSAFE_LIVE_APP_CACHED app=$name1 package=$name2 entry=$1"
					result=0
					return 0
				fi
				KILL_APP_UNSAFE_SKIP=0
				if _backup_app_quiesce_scope_cache_hit "$name2" "$name1" "$1"; then
					_kill_rc=0
				else
					kill_app
					_kill_rc=$?
				fi
				if [[ $_kill_rc = 125 || $KILL_APP_UNSAFE_SKIP = 1 ]]; then
					echoRgb "$name1 $1資料因存活/系統綁定狀態跳過備份" "0"
					_speed_debug_log "DATA_SKIP_UNSAFE_LIVE_APP app=$name1 package=$name2 entry=$1 kill_rc=$_kill_rc"
					result=0
					return 0
				fi
				;;
			esac
			_archive_cleanup "$Backup_folder/$1"
			partition_info "$Backup" "$1"
			if [[ $Skip != 1 ]]; then
				echoRgb "備份$1數據"
				# 判斷是否超過 1KB (太小的數據不值得備份, 可能是空目錄)
				# 注意: Android mksh 在 32-bit 環境下 [[ $a -gt N ]] 對超過 ~2GB 的數值會溢位
				# 改用字串長度判斷: bytes 數值字串長度 >= 4 就是 >= 1000 bytes (約 1KB)
				if [[ ${#Filesize} -ge 4 ]]; then
					Start_backup="true"
				else
					Start_backup="false"
				fi
				if [[ $Start_backup = true ]]; then
					BACKUP_TAR_CONTEXT_PKG="$name2"
					BACKUP_TAR_CONTEXT_LABEL="$name1"
					BACKUP_TAR_CONTEXT_ENTRY="$1"
					BACKUP_TAR_CONTEXT_ORIGIN_SIZE="$Filesize"
					BACKUP_TAR_CONTEXT_SOURCE_PATH="$data_path"
					BACKUP_TAR_CONTEXT_KIND=""
					BACKUP_TAR_CONTEXT_DISPLAY_PATH=""
					BACKUP_TAR_CONTEXT_ACTUAL_PATH=""
					BACKUP_TAR_CONTEXT_PATH_MODE=""
					case $1 in
					user|data|obb|user_de|media|thanox|hma) ;;
					*)
						BACKUP_TAR_CONTEXT_KIND="media_custom"
						BACKUP_TAR_CONTEXT_DISPLAY_PATH="$2"
						BACKUP_TAR_CONTEXT_ACTUAL_PATH="$data_path"
						if [[ $data_path != "$2" ]]; then BACKUP_TAR_CONTEXT_PATH_MODE="data-media-lower"; else BACKUP_TAR_CONTEXT_PATH_MODE="original"; fi
						;;
					esac
					_backup_data_archive_stage "$1" "$data_path" "$Backup_folder/$1"
					BACKUP_TAR_CONTEXT_PKG=""; BACKUP_TAR_CONTEXT_LABEL=""; BACKUP_TAR_CONTEXT_ENTRY=""; BACKUP_TAR_CONTEXT_ORIGIN_SIZE=""; BACKUP_TAR_CONTEXT_SOURCE_PATH=""; BACKUP_TAR_CONTEXT_KIND=""; BACKUP_TAR_CONTEXT_DISPLAY_PATH=""; BACKUP_TAR_CONTEXT_ACTUAL_PATH=""; BACKUP_TAR_CONTEXT_PATH_MODE=""
				else
					echoRgb "$1數據 $Filesize2太小" "0" && result=1
				fi
				if [[ $result = 0 ]]; then
					_backup_stage_validate_and_ratio "$1" "$Backup_folder/$1" "$Filesize"
					if [[ $result = 0 ]]; then
								_backup_data_stage_record_success "$1" "$2" "$Filesize"
					else
						rm -rf "$Backup_folder/$1".tar.*
					fi
				fi
				# r67: 不在每個 data/user/user_de 資料項後解凍；改由每 App 結束後統一解凍，確保備份期間入口全程灰色。
			fi
		else
			[[ $Size != "" ]] && echoRgb "$1數據無發生變化 跳過備份" "2"
		fi
		}
	else
		[[ -f $data_path ]] && echoRgb "$1是一個文件 不支持備份" "0"
	fi
}
# 恢復 app 的 data 資料 (解壓 tar.zst 到 /data/data/<pkg>/)
# 處理 selinux context、uid 綁定
_restore_mount_fstype() {
	local _path="$1"
	[[ -n $_path && -r /proc/mounts ]] || return 1
	awk -v p="$_path" '
		BEGIN { best_len = -1; best_type = "" }
		{
			m = $2; t = $3
			if (p == m || index(p, m "/") == 1) {
				l = length(m)
				if (l > best_len) { best_len = l; best_type = t }
			}
		}
		END { if (best_type != "") print best_type }
	' /proc/mounts 2>/dev/null
}

_restore_path_available_bytes_one() {
	local _path="$1" _df _kb
	[[ -z $_path ]] && { echo 0; return 1; }
	[[ -d $_path ]] || _path="${_path%/*}"
	[[ -d $_path ]] || { echo 0; return 1; }
	_df="$(df -k "$_path" 2>/dev/null | tail -n 1)"
	_kb="$(printf '%s\n' "$_df" | awk '{print $4; exit}' 2>/dev/null)"
	case $_kb in ''|*[!0-9]*) echo 0; return 1 ;; esac
	echo $((_kb * 1024))
	return 0
}

_restore_media_target_candidates() {
	local _target="$1" _rel
	[[ -n $_target ]] || return 0
	echo "$_target"
	case "$_target" in
	/storage/emulated/0/*)
		_rel="${_target#/storage/emulated/0/}"
		echo "/data/media/0/$_rel"
		echo "/mnt/pass_through/0/emulated/0/$_rel"
		;;
	/sdcard/*)
		_rel="${_target#/sdcard/}"
		echo "/data/media/0/$_rel"
		echo "/mnt/pass_through/0/emulated/0/$_rel"
		;;
	/data/media/0/*)
		_rel="${_target#/data/media/0/}"
		echo "/storage/emulated/0/$_rel"
		echo "/mnt/pass_through/0/emulated/0/$_rel"
		;;
	/mnt/pass_through/0/emulated/0/*)
		_rel="${_target#/mnt/pass_through/0/emulated/0/}"
		echo "/data/media/0/$_rel"
		echo "/storage/emulated/0/$_rel"
		;;
	esac
}

_restore_media_space_skip_state_init() {
	[[ -n ${TMPDIR:-} ]] || return 0
	: > "$TMPDIR/.restore_media_space_skips" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
}

_restore_media_space_skip_record() {
	local _file="$1" _payload="$2" _dest="$3" _need="$4" _src="$5"
	[[ -n ${TMPDIR:-} ]] || return 0
	printf '%s	%s	%s	%s	%s
' "$_file" "$_payload" "$_dest" "$_need" "$_src" >> "$TMPDIR/.restore_media_space_skips" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	_speed_debug_log "MEDIA_RESTORE_SPACE_SKIP_RECORD file=$_file payload=$_payload dest=$(_media_path_log_value "$_dest") need=${_need:-0} src=${_src:-} mode=r378"
	return 0
}

_restore_media_space_skip_count() {
	local _f="${TMPDIR:-}/.restore_media_space_skips"
	[[ -s $_f ]] || { echo 0; return 0; }
	awk 'NF{n++} END{print n+0}' "$_f" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
}

_restore_media_space_skip_names() {
	local _f="${TMPDIR:-}/.restore_media_space_skips"
	[[ -s $_f ]] || return 0
	awk -F '\t' 'NF{if(seen[$1]++==0){if(out!="") out=out","; out=out $1}} END{print out}' "$_f" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
}

_restore_media_final_notify_msg() {
	local _base="$1" _skip_count _skip_names
	_skip_count="$(_restore_media_space_skip_count)"
	case $_skip_count in ''|*[!0-9]*) _skip_count=0 ;; esac
	if [[ $_skip_count -gt 0 ]]; then
		_skip_names="$(_restore_media_space_skip_names)"
		echo "${_base}，但有 ${_skip_count} 個 Media 項目因空間不足跳過${_skip_names:+：$_skip_names}"
	else
		echo "$_base"
	fi
}

_restore_media_space_precheck() {
	local _target="$1" _need="$2" _avail _margin _need_with_margin _cand _c_avail _c_type _picked _tmpfs_seen=0
	case $_need in ''|*[!0-9]*|0) return 0 ;; esac
	[[ -n $_target ]] || return 0

	_avail=0
	while read -r _cand; do
		[[ -n $_cand ]] || continue
		[[ -d $_cand ]] || _cand="${_cand%/*}"
		[[ -d $_cand ]] || continue
		_c_avail="$(_restore_path_available_bytes_one "$_cand")"
		case $_c_avail in ''|*[!0-9]*|0) continue ;; esac
		_c_type="$(_restore_mount_fstype "$_cand")"
		{
			echo "MEDIA_SPACE_CANDIDATE file=$FILE_NAME path=$_cand fstype=$_c_type avail=$_c_avail need=$_need stream=${_RESTORE_STREAM:-0} src=${_STREAM_SRC:-$tar_path}"
		} >> "${SPEED_DEBUG_RUN_DIR:-/data/speed_debug}/media_space_precheck.log" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
		# Android 可能把 /data/media/0/DCIM 或 Pictures 額外 tmpfs 掛載；df /storage/emulated/0 會看到 300GB，
		# 但 tar 實際寫入會打到 tmpfs，必須優先以 tmpfs 的可用空間判斷。
		if [[ $_c_type = tmpfs ]]; then
			_tmpfs_seen=1
			if [[ $_avail -eq 0 || $_c_avail -lt $_avail ]]; then
				_avail="$_c_avail"
				_picked="$_cand"
			fi
		elif [[ $_tmpfs_seen != 1 ]]; then
			if [[ $_avail -eq 0 || $_c_avail -lt $_avail ]]; then
				_avail="$_c_avail"
				_picked="$_cand"
			fi
		fi
	done <<EOFMSPC
$(_restore_media_target_candidates "$_target")
EOFMSPC

	case $_avail in ''|*[!0-9]*|0) return 0 ;; esac
	# Media 解壓需要額外 metadata/目錄項/相簿索引餘量；至少保留 64MiB。
	_margin=$((64 * 1024 * 1024))
	_need_with_margin=$((_need + _margin))
	if [[ $_tmpfs_seen = 1 ]]; then
		echoRgb "偵測到 Media 目標路徑被 tmpfs 掛載，實際可用空間以 $_picked 為準" "2"
	fi
	if [[ $_avail -lt $_need_with_margin ]]; then
		echoRgb "Media恢復空間不足，跳過 $FILE_NAME" "0"
		echoRgb "目標路徑：$_target" "0"
		echoRgb "實際檢查：${_picked:-$_target}" "0"
		echoRgb "需要約 $(size "$_need")，可用 $(size "$_avail")，至少需額外保留 64MiB" "0"
		{
			echo "MEDIA_SPACE_SKIP file=$FILE_NAME target=$_target picked=$_picked tmpfs=$_tmpfs_seen need=$_need avail=$_avail margin=$_margin stream=${_RESTORE_STREAM:-0} src=${_STREAM_SRC:-$tar_path}"
		} >> "${SPEED_DEBUG_RUN_DIR:-/data/speed_debug}/media_space_precheck.log" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
		return 1
	fi
	return 0
}

_restore_stream_payload_size_from_raw_list() {
	local _src="$1" _raw="${_RESTORE_STREAM_MEDIA_REMOTE_RAW:-}" _size
	[[ -n $_src && -s $_raw ]] || return 1
	_size="$(awk -F'	' -v rel="$_src" '
		function clean_path(x) {
			gsub(/\r/, "", x)
			sub(/^https?:\/\/[^\/]*\/?/, "", x)
			gsub(/^\/+/, "", x)
			return x
		}
		function is_suffix_path(p, r) {
			if (p == r) return 1
			if (length(p) > length(r) && substr(p, length(p)-length(r)+1) == r && substr(p, length(p)-length(r), 1) == "/") return 1
			return 0
		}
		BEGIN { r=clean_path(rel) }
		{
			for (i=1; i<=NF; i++) gsub(/\r/, "", $i)
			p=""; sz=""; typ=""
			if (($1 == "F" || $1 == "FILE") && NF >= 3) { typ=$1; sz=$2; p=$3 }
			else if (($1 == "D" || $1 == "DIR") && NF >= 3) { next }
			else if (NF >= 2) { p=$1; sz=$2; typ=$3 }
			else next
			if (typ == "D" || typ == "DIR") next
			if (sz !~ /^[0-9]+$/) next
			p=clean_path(p)
			if (is_suffix_path(p, r)) { print sz; found=1; exit }
		}
		END { if (!found) exit 1 }
	' "$_raw" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null})" || return 1
	case $_size in ''|*[!0-9]*) return 1 ;; esac
	printf '%s\n' "$_size"
	return 0
}

_restore_release_data_cleanup() {
	# r407: Release_data 高頻路徑不再逐檔 rm TMPDIR 內容。
	# 依賴本輪專用 SPEEDBACKUP_RUN_TMPDIR 在 EXIT final cleanup 時整目錄刪除。
	cleanup_tmpdir_contents
}

Release_data() {
	tar_path="$1"
	X="$path2/$name2"
	MODDIR_NAME="${tar_path%/*}"
	MODDIR_NAME="${MODDIR_NAME##*/}"
	FILE_NAME="${tar_path##*/}"
	case "$FILE_NAME" in
	speed_debug_*.tar|speed_debug_*.tar.zst)
		_speed_debug_log "SKIP debug archive in app restore dir: $tar_path"
		return 0 ;;
	esac
	# 只去 .tar / .tar.zst 後綴 (不可用 %%.* , 否則 service.d.tar 會被砍成 service)
	FILE_NAME2="${FILE_NAME%.zst}"
	FILE_NAME2="${FILE_NAME2%.tar}"
	local _media_restore_display_path="" _media_restore_actual_path="" _media_restore_path_mode="original"
	case ${FILE_NAME##*.} in
	zst | tar)
		unset FILE_PATH Size Selinux_state
		# 一次 jq 抓 Size / keystore / path (取代 3 個獨立 jq fork)
		release_details_read "$app_details" "$FILE_NAME2"
		Size="$REL_SIZE"
		if [[ ${_RESTORE_STREAM:-0} = 1 && ${MODDIR_NAME##*/} = Media && -n ${_STREAM_SRC:-} ]]; then
			local _remote_payload_size
			_remote_payload_size="$(_restore_stream_payload_size_from_raw_list "$_STREAM_SRC")"
			case $_remote_payload_size in
			''|*[!0-9]*) ;;
			*)
				case $Size in ''|*[!0-9]*) Size="$_remote_payload_size" ;;
				*) [[ $_remote_payload_size -gt $Size ]] && Size="$_remote_payload_size" ;;
				esac
				_speed_debug_log "STREAM_RESTORE_MEDIA_SIZE_OVERRIDE file=$FILE_NAME jsonSize=${REL_SIZE:-empty} remoteSize=$_remote_payload_size effectiveSize=$Size src=$_STREAM_SRC raw=${_RESTORE_STREAM_MEDIA_REMOTE_RAW:-none}"
				;;
			esac
		fi
		case $FILE_NAME2 in
		user)
			if [[ -d $X ]]; then
				[[ $REL_KEYSTORE = true ]] && echoRgb "$name1存在keystore 恢復可能閃退" "0"
				FILE_PATH="$path2"
				# 合併 LS|awk|sed → 1 個 awk (省 2 fork)
				Selinux_state="$(LS "$X" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} | awk 'NF>1 {gsub(/system_data_file/, "app_data_file"); print $1; exit}')"
			else
				# r371: 已安裝 App 的 CE data dir 可能被系統/安裝流程延後建立。
				# 遠端有 user.tar(.zst) 時不能把「目錄暫不存在」誤判成「App不存在」並跳過。
				# tar 內容以 package 目錄為 root，所以只需允許解到 /data/user/<user>；解壓後再 chown/restorecon。
				if [[ -d $path2 ]] && [[ -n $(get_app_uid "$name2") ]]; then
					FILE_PATH="$path2"
					Selinux_state=""
					echoRgb "$X暫不存在，將由備份資料重建user數據" "3"
					_speed_debug_log "RESTORE_USER_PAYLOAD_TARGET_MISSING_ALLOW package=$name2 label=$name1 path=$X parent=$path2 action=extract_recreate mode=r371"
				else
					echoRgb "$X不存在 無法恢復$FILE_NAME2數據" "0"
					_speed_debug_log "RESTORE_USER_PAYLOAD_TARGET_MISSING_FAIL package=$name2 label=$name1 path=$X parent=$path2 reason=no_parent_or_uid mode=r371"
				fi
			fi ;;
		user_de)
			X="$path3/$name2"
			if [[ -d $X ]]; then
				FILE_PATH="$path3"
				Selinux_state="$(LS "$X" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} | awk 'NF>1 {gsub(/system_data_file/, "app_data_file"); print $1; exit}')"
			else
				if [[ -d $path3 ]] && [[ -n $(get_app_uid "$name2") ]]; then
					FILE_PATH="$path3"
					Selinux_state=""
					echoRgb "$X暫不存在，將由備份資料重建user_de數據" "3"
					_speed_debug_log "RESTORE_USER_DE_PAYLOAD_TARGET_MISSING_ALLOW package=$name2 label=$name1 path=$X parent=$path3 action=extract_recreate mode=r371"
				else
					echoRgb "$X不存在 無法恢復$FILE_NAME2數據" "0"
					_speed_debug_log "RESTORE_USER_DE_PAYLOAD_TARGET_MISSING_FAIL package=$name2 label=$name1 path=$X parent=$path3 reason=no_parent_or_uid mode=r371"
				fi
			fi ;;
		data)
			FILE_PATH="$path/data"
			Selinux_state="$(LS "$FILE_PATH" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} | awk 'NF>1 {gsub(/system_data_file/, "app_data_file"); print $1; exit}')"
			;;
		obb)
			FILE_PATH="$path/obb"
			Selinux_state="$(LS "$FILE_PATH" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} | awk 'NF>1 {gsub(/system_data_file/, "app_data_file"); print $1; exit}')"
			;;
		media)
			FILE_PATH="$path/media"
			;;
		thanox)
			FILE_PATH="/data/system"
			find "/data/system" -maxdepth 1 -type d -name "thanos*" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} | while read -r _td; do
				case $_td in
					/data/system/thanos*) [[ -n $_td ]] && rm -rf "$_td" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} ;;
				esac
			done
			;;
		hma)
			FILE_PATH="/data/misc"
			find "/data/misc" -maxdepth 1 -mindepth 1 -type d -name "hide_my_applist_*" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} | while read -r _hd; do
				case $_hd in
					/data/misc/hide_my_applist_*) [[ -n $_hd ]] && rm -rf "$_hd" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} ;;
				esac
			done
			;;
		*)
			if [[ $A != "" ]]; then
				if [[ ${MODDIR_NAME##*/} = Media ]]; then
					FILE_PATH="$REL_PATH"
					_media_restore_display_path="$FILE_PATH"
					_media_restore_actual_path="$FILE_PATH"
					_media_restore_path_mode="original"
					if [[ $FILE_PATH = "" ]]; then
						echoRgb "路徑獲取失敗" "0"
					else
						local _media_lower_restore_path _media_lower_restore_parent
						_media_lower_restore_path="$(_media_storage_lower_path "$FILE_PATH" 2>/dev/null)"
						_media_lower_restore_parent="${_media_lower_restore_path%/*}"
						if [[ -n $_media_lower_restore_path && -d $_media_lower_restore_parent ]]; then
							_media_restore_actual_path="$_media_lower_restore_path"
							_media_restore_path_mode="data-media-lower"
							_speed_debug_log "MEDIA_RESTORE_LOWER_PATH file=$FILE_NAME displayPath=$(_media_path_log_value "$_media_restore_display_path") actualPath=$(_media_path_log_value "$_media_restore_actual_path") action=use_data_media_lower mode=r374"
						else
							_speed_debug_log "MEDIA_RESTORE_LOWER_PATH_SKIP file=$FILE_NAME displayPath=$(_media_path_log_value "$_media_restore_display_path") candidate=$(_media_path_log_value "$_media_lower_restore_path") reason=missing_parent mode=r374"
						fi
						local _media_restore_display_suffix
						_media_restore_display_suffix=""
						[[ $_media_restore_path_mode != original ]] && _media_restore_display_suffix=" ($_media_restore_path_mode)"
						echoRgb "解壓路徑↓\n -$_media_restore_display_path$_media_restore_display_suffix" "2"
						FILE_PATH="${_media_restore_actual_path%/*}"
						[[ ! -d $FILE_PATH ]] && mkdir -p "$FILE_PATH"
					fi
				fi
			else
				echoRgb "$tar_path名稱似乎有誤" "0"
			fi ;;
		esac
		echoRgb "恢復$FILE_NAME2數據 釋放$(size "$Size")" "3"
		if [[ $_RESTORE_STREAM = 1 && -n $_STREAM_SRC ]] && _restore_stream_payload_known_missing "$_STREAM_SRC"; then
			_speed_debug_log "RESTORE_PAYLOAD_REMOTE_MISSING app=${name1:-} package=${name2:-} entry=$FILE_NAME2 rel=$_STREAM_SRC action=skip_before_extract_delete mode=r377"
			echoRgb "$name1 缺少遠端檔案 $FILE_NAME，已略過此 payload 並繼續恢復" "0"
			result=0
			return 0
		fi
		if [[ $FILE_PATH != "" ]]; then
			if [[ ${MODDIR_NAME##*/} = Media ]]; then
				if ! _restore_media_space_precheck "$FILE_PATH" "$Size"; then
					result=1
					_restore_media_space_skip_record "$FILE_NAME" "$FILE_NAME2" "$FILE_PATH" "$Size" "${_STREAM_SRC:-$tar_path}"
					_speed_debug_log "MEDIA_RESTORE_SPACE_SKIP_RESULT file=$FILE_NAME payload=$FILE_NAME2 dest=$FILE_PATH result=skip_no_extract mode=r378"
					echo_log "解壓縮$FILE_NAME" "" 1
					return 1
				fi
			fi
			case $FILE_NAME2 in
			user|data|obb|user_de)
				_process_observer_start_payload "${name2:-}" "${name1:-}" "$FILE_NAME2" "restore-extract" || true
				;;
			esac
			[[ ${MODDIR_NAME##*/} != Media ]] && rm -rf "$FILE_PATH/$name2"
			# 流式恢復: 從遠端拉 → 管道解壓 (不落地本機); _STREAM_SRC 為遠端相對路徑
			if [[ $_RESTORE_STREAM = 1 && -n $_STREAM_SRC ]]; then
				local _stream_extract_raw_log _stream_extract_raw_start _stream_perf_bytes _stream_perf_ext _stream_perf_path_mode
				_stream_extract_raw_start="$(_speed_now_ms)"; local _stream_profile_start="$_stream_extract_raw_start"; case $_stream_extract_raw_start in ''|*[!0-9]*) _stream_extract_raw_start="$(date +%s 2>/dev/null)000" ;; esac
				_stream_perf_bytes="${Size:-0}"
				case $_stream_perf_bytes in ''|*[!0-9]*) _stream_perf_bytes=0 ;; esac
				_stream_perf_ext="${FILE_NAME##*.}"
				_stream_perf_path_mode="${_media_restore_path_mode:-original}"
				_speed_debug_log "RESTORE_STREAM_PERF_BEGIN app=$(_restore_stream_perf_field "${name1:-}") package=$(_restore_stream_perf_field "${name2:-}") payload=$(_restore_stream_perf_field "$FILE_NAME2") rel=$(_restore_stream_perf_field "$_STREAM_SRC") bytes=$_stream_perf_bytes dest=$(_restore_stream_perf_field "$FILE_PATH") archiveExt=$(_restore_stream_perf_field "$_stream_perf_ext") pathMode=$(_restore_stream_perf_field "$_stream_perf_path_mode") trueStream=1 staged=0 scope=download_extract_pipe mode=r416"
				_stream_extract_raw_log="$(_local_raw_debug_begin extract "kind=data-stream src=$_STREAM_SRC name=$FILE_NAME dest=$FILE_PATH ext=${FILE_NAME##*.}")"
				local _stream_extract_pid _stream_extract_msg _stream_extract_tag _stream_notify _stream_event_fifo
				_stream_extract_msg="正在流式解壓 ${FILE_NAME} → ${FILE_PATH}"
				_stream_extract_tag="stream_extract_${FILE_NAME2}"
				_stream_notify=""
				[[ ${MODDIR_NAME##*/} = Media ]] && _stream_notify="106"
				_stream_event_fifo="$(_remote_stream_event_prepare "$_stream_extract_tag" 2>/dev/null || true)"
				case ${FILE_NAME##*.} in
				zst) ( export SPEEDBACKUP_REMOTE_STREAM_EVENT_FIFO="$_stream_event_fifo" SPEEDBACKUP_REMOTE_STREAM_EVENT_TAG="$_stream_extract_tag"; set -o pipefail 2>/dev/null; _stream_download "$_STREAM_SRC" | zstd -d 2>>"$_stream_extract_raw_log" | tar --checkpoint-action="ttyout=%T\r" -xmpf - -C "$FILE_PATH" 2>>"$_stream_extract_raw_log"; _ev_rc=$?; _remote_stream_event_emit done "$_ev_rc" "$_stream_extract_tag" complete; exit "$_ev_rc" ) & _stream_extract_pid=$! ;;
				tar) if [[ ${MODDIR_NAME##*/} = Media ]]; then ( export SPEEDBACKUP_REMOTE_STREAM_EVENT_FIFO="$_stream_event_fifo" SPEEDBACKUP_REMOTE_STREAM_EVENT_TAG="$_stream_extract_tag"; set -o pipefail 2>/dev/null; _stream_download "$_STREAM_SRC" | tar --checkpoint-action="ttyout=%T\r" -axf - -C "$FILE_PATH" 2>>"$_stream_extract_raw_log"; _ev_rc=$?; _remote_stream_event_emit done "$_ev_rc" "$_stream_extract_tag" complete; exit "$_ev_rc" ) & _stream_extract_pid=$!; else ( export SPEEDBACKUP_REMOTE_STREAM_EVENT_FIFO="$_stream_event_fifo" SPEEDBACKUP_REMOTE_STREAM_EVENT_TAG="$_stream_extract_tag"; set -o pipefail 2>/dev/null; _stream_download "$_STREAM_SRC" | tar --checkpoint-action="ttyout=%T\r" -amxf - -C "$FILE_PATH" 2>>"$_stream_extract_raw_log"; _ev_rc=$?; _remote_stream_event_emit done "$_ev_rc" "$_stream_extract_tag" complete; exit "$_ev_rc" ) & _stream_extract_pid=$!; fi ;;
				esac
				_remote_stream_wait_pid_busy_abortable "$_stream_extract_pid" "$_stream_extract_msg" "$_stream_extract_tag" "$_stream_notify" 1 "$_stream_event_fifo"
				result=$?
				if [[ $_RESTORE_STREAM = 1 ]] && _remote_stream_fatal_active; then
					_speed_debug_log "STREAM_RESTORE_EXTRACT_REMOTE_FATAL app=${name1:-} file=$FILE_NAME src=${_STREAM_SRC:-} result=$result mode=r370"
					result=126
				elif [[ $result != 0 ]] && _stream_download_remote_missing_hit "${_STREAM_SRC:-}"; then
					_speed_debug_log "RESTORE_PAYLOAD_REMOTE_MISSING app=${name1:-} package=${name2:-} entry=$FILE_NAME2 rel=${_STREAM_SRC:-} action=download_404_no_fastfail rc=$result mode=r377"
					echoRgb "$name1 缺少遠端檔案 $FILE_NAME，已略過此 payload 並繼續恢復" "0"
					result=0
				elif [[ $result != 0 ]] && _remote_extract_log_transport_failure "$_stream_extract_raw_log"; then
					_remote_connectivity_fast_fail "stream_restore_extract" "${_STREAM_SRC:-}" "extract_short_read_or_transport" || true
					_remote_stream_mark_fatal "${_STREAM_SRC:-}" 126 0 "restore stream extract transport failure; fast-fail without retry"
					_speed_debug_log "STREAM_RESTORE_EXTRACT_TRANSPORT_FATAL app=${name1:-} package=${name2:-} file=$FILE_NAME src=${_STREAM_SRC:-} rc=$result mode=r370"
					result=126
				fi
				_local_raw_debug_end extract "$_stream_extract_raw_log" "$result" "$_stream_extract_raw_start" "kind=data-stream dest=$FILE_PATH"
				_restore_stream_perf_record "$_stream_profile_start" "$result" "${name1:-}" "${name2:-}" "$FILE_NAME2" "${_STREAM_SRC:-}" "$_stream_perf_bytes" "$FILE_PATH" "$_stream_perf_ext" "$_stream_perf_path_mode"
				_restore_perf_timing_done "payload_extract" "$_stream_profile_start" "app=${name1:-} package=${name2:-} payload=$FILE_NAME2 stream=1 src=${_STREAM_SRC:-} size=${Size:-0} rc=$result dest=$FILE_PATH trueStream=1 staged=0 mode2=r408"
				[[ ${MODDIR_NAME##*/} = Media ]] && _media_restore_perf_done 1 "$_stream_profile_start" "${Size:-0}" "$result" "$FILE_NAME2" "${_STREAM_SRC:-}" "$FILE_PATH" "$_media_restore_display_path" "$_media_restore_actual_path" "$_media_restore_path_mode"
			else
				local _extract_raw_log _extract_raw_start _extract_size
				_extract_size="$(_local_file_size_debug "$tar_path")"
				_extract_raw_start="$(_speed_now_ms)"; local _extract_profile_start="$_extract_raw_start"; case $_extract_raw_start in ''|*[!0-9]*) _extract_raw_start="$(date +%s 2>/dev/null)000" ;; esac
				_extract_raw_log="$(_local_raw_debug_begin extract "kind=data file=$tar_path name=$FILE_NAME dest=$FILE_PATH ext=${FILE_NAME##*.} size=$_extract_size")"
				case ${FILE_NAME##*.} in
				zst) ( set -o pipefail 2>/dev/null; zstd -d < "$tar_path" 2>>"$_extract_raw_log" | tar --checkpoint-action="ttyout=%T\r" -xmpf - -C "$FILE_PATH" 2>>"$_extract_raw_log" ) ;;
				tar) [[ ${MODDIR_NAME##*/} = Media ]] && tar --checkpoint-action="ttyout=%T\r" -axf "$tar_path" -C "$FILE_PATH" 2>>"$_extract_raw_log" || tar --checkpoint-action="ttyout=%T\r" -amxf "$tar_path" -C "$FILE_PATH" 2>>"$_extract_raw_log" ;;
				esac
				result=$?
				_local_raw_debug_end extract "$_extract_raw_log" "$result" "$_extract_raw_start" "kind=data dest=$FILE_PATH"
				_restore_perf_timing_done "payload_extract" "$_extract_profile_start" "app=${name1:-} package=${name2:-} payload=$FILE_NAME2 stream=0 file=$tar_path size=${_extract_size:-0} rc=$result dest=$FILE_PATH"
				[[ ${MODDIR_NAME##*/} = Media ]] && _media_restore_perf_done 0 "$_extract_profile_start" "${_extract_size:-0}" "$result" "$FILE_NAME2" "$tar_path" "$FILE_PATH" "$_media_restore_display_path" "$_media_restore_actual_path" "$_media_restore_path_mode"
			fi
		else
			Set_back_1
		fi
		_process_observer_stop_current "$result" || true
		echo_log "解壓縮$FILE_NAME" "" "$result"
		if [[ $_RESTORE_STREAM = 1 ]] && _remote_stream_fatal_active; then
			_speed_debug_log "STREAM_RESTORE_RELEASE_DATA_FATAL app=${name1:-} file=$FILE_NAME src=${_STREAM_SRC:-} result=$result"
			return 126
		fi
		if [[ $result = 0 ]]; then
			case $FILE_NAME2 in
			user|data|obb|user_de)
				# 用 helper 查 uid (取代 3 層 fallback 散落)
				G="$(get_app_uid "$name2")"
				if [[ $G != "" ]]; then
					if [[ -d $X ]]; then
						case ${#G} in
						5)
							if [[ $user = 0 ]]; then
								uid="$G:$G"
							else
								uid="$user$G:$user$G"
							fi ;;
						6|7|8|9|10)
							uid="$G:$G" ;;
						esac
						case $FILE_NAME2 in
						user|user_de)
							case $FILE_NAME2 in
							user) [[ $X = $path2/$name2 ]] && Validation_settings="true" || Validation_settings="false" ;;
							user_de) [[ $X = $path3/$name2 ]] && Validation_settings="true" || Validation_settings="false" ;;
							esac
							if [[ $Validation_settings = true ]]; then
								_speedscan_tree_fixup "$uid" "$X" - - || _speedscan_tree_chown "$uid" "$X" || chown -hR "$uid" "$X/"
								echo_log "設置用戶組$uid"
								_restore_chcon_tree_timed "$Selinux_state" "$X/" "${FILE_NAME2}_${name2}" || _restore_restorecon_timed "$X/" "${FILE_NAME2}_${name2}_restorecon_r371"
								echo_log "selinux上下文設置"
							else
								echoRgb "路徑:$X出現錯誤"
							fi ;;
						data|obb)
							_speedscan_tree_fixup "$uid" "$FILE_PATH/$name2" - - || _speedscan_tree_chown "$uid" "$FILE_PATH/$name2" || chown -hR "$uid" "$FILE_PATH/$name2/"
							echo_log "設置用戶組$uid"
							_restore_chcon_tree_timed "$Selinux_state" "$FILE_PATH/$name2/" "${FILE_NAME2}_${name2}"
							echo_log "selinux上下文設置" ;;
						esac
					else
						echoRgb "$FILE_NAME2路徑$X不存在" "0"
					fi
				else
					echoRgb "uid獲取失敗" "0"
				fi
				;;
			thanox)
				for _td in $(find "/data/system" -maxdepth 1 -type d -name "thanos*" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}); do _restore_restorecon_timed "$_td" "thanox"; done
				echo_log "selinux上下文設置" && echoRgb "警告 thanox配置恢復後務必重啟\n -否則不生效" "0"
				;;
			hma)
				find "/data/misc" -maxdepth 1 -mindepth 1 -type d -name "hide_my_applist_*" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} | while read -r _hd; do
					case $_hd in
					/data/misc/hide_my_applist_*) _restore_restorecon_timed "$_hd" "hma" ;;
					esac
				done
				echo_log "selinux上下文設置" && echoRgb "警告 HMA-OSS配置恢復後建議重啟\n -否則 Hide My Applist 設定可能不立即生效" "0"
				;;
			esac
		fi
		;;
	*)
		echoRgb "$FILE_NAME 壓縮包不支持解壓縮" "0"
		Set_back_1
		;;
	esac
	_restore_release_data_cleanup || exit 1
}
# 取得備份記錄的 installer；若 .installer 缺失，從 install_diagnostics.installer/installing fallback
_restore_backup_installer_value() {
	_appdetails_get_backup_installer_value "$1"
}

# 安裝來源上下文解析：只使用備份記錄且目前系統真的存在的 installer。
# 流程：讀備份 installer → 檢查目前 user 是否存在 → 取得 UID → 取得可用 data dir → 安裝時才套用 -i/UID context。
# 目的：避免無腦使用 com.android.vending 或其他已不存在的來源，造成 pm -i 無效、install-create 失敗或來源欄位污染。
_restore_pkg_exists_for_user() {
	local _pkg="$1"
	[[ -n $_pkg ]] || return 1
	_appinventory_pkg_exists_for_user "$_pkg" "${user:-${USER_ID:-0}}"
}

_restore_pkg_uid_for_user() {
	local _pkg="$1" _uid=""
	[[ -n $_pkg ]] || return 1
	_uid="$(_appinventory_pkg_uid_for_user "$_pkg" "${user:-${USER_ID:-0}}")" || _uid=""
	if [[ -z $_uid ]]; then
		_uid="$(dex_hiddenapi_raw getPackageUid "$USER_ID" "$_pkg" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} | awk '/^[0-9]+$/ {print; exit}')"
	fi
	case $_uid in ''|*[!0-9]*) return 1 ;; esac
	echo "$_uid"
}

_restore_pkg_data_dir_for_user() {
	local _pkg="$1" _dir
	for _dir in "/data/user/${USER_ID}/$_pkg" "/data/user_de/${USER_ID}/$_pkg"; do
		[[ -d $_dir ]] && { echo "$_dir"; return 0; }
	done
	return 1
}

_restore_installer_context_facts_call() {
	local _target_pkg="$1" _installer="$2" _body _out _rc
	[[ -n $_target_pkg && -n $_installer ]] || return 1
	_body="$(_webdav_tmp_path root_installer_context_args)"
	_out="$(_webdav_tmp_path root_installer_context_out)"
	{
		printf '%s\n' "${USER_ID:-${user:-0}}"
		printf '%s\n' "$_target_pkg"
		printf '%s\n' "$_installer"
		printf '%s\n' refresh
	} > "$_body"
	_root_daemon_call_file_hot hiddenapi installerContextFacts "$_body" "$_out" >/dev/null 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	_rc=$?
	if [[ $_rc = 125 ]]; then
		_dex_raw com.xayah.dex.HiddenApiUtil installerContextFacts "${USER_ID:-${user:-0}}" "$_target_pkg" "$_installer" refresh > "$_out" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
		_rc=$?
	fi
	if [[ $_rc = 0 ]] && grep -Fqx '#schema	speedbackup.installer_context_facts.v1' "$_out" 2>/dev/null; then
		cat "$_out" 2>/dev/null
		rm -f "$_body" "$_out" 2>/dev/null
		return 0
	fi
	[[ -n ${SPEED_DEBUG_RUN_DIR:-} && -d ${SPEED_DEBUG_RUN_DIR:-} ]] && cp -f "$_out" "$SPEED_DEBUG_RUN_DIR/installer_context_facts_failed.tsv" 2>/dev/null || true
	rm -f "$_body" "$_out" 2>/dev/null
	return 1
}

_restore_select_installer_context() {
	local _target_pkg="$1" _installer="$2" _uid _data_dir
	RESTORE_INSTALLER_PKG=""
	RESTORE_INSTALLER_UID=""
	RESTORE_INSTALLER_DATA_DIR=""
	case $_installer in ''|null|NULL|clear|CLEAR|none|NONE)
		_restore_log_install_method "$_target_pkg" "installer_context_skip" "reason=empty backupInstaller=${_installer:-null}"
		return 1
		;;
	esac
	# 只有備份記錄的原始安裝來源是 Google Play 商店本身才做安裝來源偽裝 (installer/initiating/UID hybrid)。
	# 非 Play 來源 (其他應用商店/側載) 偽裝成該商店會有假安裝失敗風險, 直接跳過偽裝、走原生 pm 正常安裝。
	if [[ $_installer != com.android.vending ]]; then
		echoRgb "備份安裝來源 $_installer 非 Google Play, 不偽裝安裝來源, 使用原生 pm 安裝" "2"
		_restore_log_install_method "$_target_pkg" "installer_context_skip" "reason=non_play_installer installer=$_installer"
		return 1
	fi
	local _ctx _status _target _inst _uid _data_dir _de_dir _installed _enabled _usable_pm _usable_hybrid _reason
	_ctx="$(_restore_installer_context_facts_call "$_target_pkg" "$_installer" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null})" || _ctx=""
	if printf '%s\n' "$_ctx" | grep -Fqx '#schema	speedbackup.installer_context_facts.v1' 2>/dev/null; then
		[[ -n ${SPEED_DEBUG_RUN_DIR:-} && -d ${SPEED_DEBUG_RUN_DIR:-} ]] && printf '%s\n' "$_ctx" >> "$SPEED_DEBUG_RUN_DIR/installer_context_facts.tsv" 2>/dev/null || true
		IFS="$(printf '	')" read -r _status _target _inst _user_id _target_installed _target_installer _installed _enabled _uid _data_dir _de_dir _ver _is_play _usable_pm _usable_hybrid _reason <<EOF_INSTALLER_CONTEXT
$(printf '%s\n' "$_ctx" | awk -F '	' '$1=="OK" || $1=="MISSING"{print; exit}' 2>/dev/null)
EOF_INSTALLER_CONTEXT
		if [[ $_status = OK && $_installed = true && $_enabled = true ]]; then
			case $_uid in ''|*[!0-9]*)
				echoRgb "備份安裝來源 $_installer 無法取得 UID，跳過安裝來源偽裝" "2"
				_restore_log_install_method "$_target_pkg" "installer_context_skip" "reason=uid_missing installer=$_installer source=installerContextFacts-r481"
				return 1
				;;
			esac
			case $_usable_hybrid:$_data_dir in true:/*)
				_restore_log_install_method "$_target_pkg" "installer_context_ok" "installer=$_installer uid=$_uid dataDir=$_data_dir reason=${_reason:-OK} source=installerContextFacts-r481"
				;;
			*)
				_data_dir=""
				_restore_log_install_method "$_target_pkg" "installer_context_pm_only" "installer=$_installer uid=$_uid reason=${_reason:-data_dir_missing} source=installerContextFacts-r481"
				;;
			esac
			RESTORE_INSTALLER_PKG="$_installer"
			RESTORE_INSTALLER_UID="$_uid"
			RESTORE_INSTALLER_DATA_DIR="$_data_dir"
			return 0
		fi
		case $_installed:$_enabled in
		false:*) echoRgb "備份安裝來源 $_installer 目前不存在，跳過安裝來源偽裝" "2"; _restore_log_install_method "$_target_pkg" "installer_context_skip" "reason=package_missing installer=$_installer source=installerContextFacts-r481 factsReason=${_reason:-unknown}"; return 1 ;;
		true:false) echoRgb "備份安裝來源 $_installer 目前停用，跳過安裝來源偽裝" "2"; _restore_log_install_method "$_target_pkg" "installer_context_skip" "reason=package_disabled installer=$_installer source=installerContextFacts-r481 factsReason=${_reason:-unknown}"; return 1 ;;
		esac
	fi
	_speed_debug_log "INSTALLER_CONTEXT_FACTS_FALLBACK target=$_target_pkg installer=$_installer mode=r481 reason=dex_facts_unavailable"
	if ! _restore_pkg_exists_for_user "$_installer"; then
		echoRgb "備份安裝來源 $_installer 目前不存在，跳過安裝來源偽裝" "2"
		_restore_log_install_method "$_target_pkg" "installer_context_skip" "reason=package_missing installer=$_installer fallback=appinventory"
		return 1
	fi
	_uid="$(_restore_pkg_uid_for_user "$_installer")"
	case $_uid in ''|*[!0-9]*)
		echoRgb "備份安裝來源 $_installer 無法取得 UID，跳過安裝來源偽裝" "2"
		_restore_log_install_method "$_target_pkg" "installer_context_skip" "reason=uid_missing installer=$_installer fallback=appinventory"
		return 1
		;;
	esac
	_data_dir="$(_restore_pkg_data_dir_for_user "$_installer")"
	if [[ -z $_data_dir ]]; then
		_restore_log_install_method "$_target_pkg" "installer_context_pm_only" "installer=$_installer uid=$_uid reason=data_dir_missing fallback=appinventory"
	else
		_restore_log_install_method "$_target_pkg" "installer_context_ok" "installer=$_installer uid=$_uid dataDir=$_data_dir fallback=appinventory"
	fi
	RESTORE_INSTALLER_PKG="$_installer"
	RESTORE_INSTALLER_UID="$_uid"
	RESTORE_INSTALLER_DATA_DIR="$_data_dir"
	return 0
}

_restore_bool_enabled() {
	case "$1" in 1|true|True|TRUE|yes|YES|on|ON) return 0 ;; *) return 1 ;; esac
}

_restore_play_uid() {
	local _uid=""
	_uid="$(_appinventory_pkg_uid_for_user com.android.vending "${user:-${USER_ID:-0}}")" || _uid=""
	if [[ -z $_uid ]]; then
		_uid="$(dex_hiddenapi_raw getPackageUid "$USER_ID" com.android.vending 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} | awk '/^[0-9]+$/ {print; exit}')"
	fi
	echo "$_uid"
}

_restore_has_play_store() {
	local _uid="" _path_ok=0 _disabled=0 _enabled_rc
	_restore_pkg_exists_for_user com.android.vending && _path_ok=1
	_appinventory_pkg_enabled_for_user com.android.vending "${user:-${USER_ID:-0}}"
	_enabled_rc=$?
	[[ $_enabled_rc = 2 ]] && _disabled=1
	_uid="$(_restore_play_uid)"
	case $_uid in ''|*[!0-9]*)
		_speed_debug_log "PLAY_STORE_CHECK result=fail reason=uid_missing path_ok=$_path_ok disabled=$_disabled source=appinventory"
		return 1
		;;
	esac
	if [[ $_path_ok != 1 ]]; then
		_speed_debug_log "PLAY_STORE_CHECK result=fail reason=package_missing uid=$_uid disabled=$_disabled source=appinventory"
		return 1
	fi
	if [[ $_disabled = 1 ]]; then
		_speed_debug_log "PLAY_STORE_CHECK result=fail reason=package_disabled uid=$_uid source=appinventory"
		return 1
	fi
	_speed_debug_log "PLAY_STORE_CHECK result=ok uid=$_uid path_ok=$_path_ok disabled=$_disabled source=appinventory"
	return 0
}

_restore_line_requests_play_session() {
	local _line="$1"
	_line="$(printf '%s\n' "$_line" | sed 's/^[ 	]*//')"
	case "$_line" in
	\#*|＃*|'') return 1 ;;
	!play[[:space:]]*|！play[[:space:]]*|![[:space:]]*|！[[:space:]]*|!*) return 0 ;;
	esac
	return 1
}

_restore_list_has_play_markers() {
	local _list="$1" _line=""
	[[ -s $_list ]] || return 1
	while IFS= read -r _line; do
		_restore_line_requests_play_session "$_line" && return 0
	done < "$_list"
	return 1
}

_restore_play_work_root() {
	# 使用備份目錄下的專用子目錄，避免寫入或污染 Google Play 私有資料目錄。
	# 279 起 APK bytes 由 root pm install-write 寫入；此處只給 Play UID daemon 載入 classes.dex。
	echo "$filepath/.speedbackup_play_session/u$user"
}

_restore_prepare_play_dex() {
	local _play_uid="$1" _root _art_dir _dex_dst
	[[ -n $_play_uid && -f $tools_path/classes.dex ]] || return 1
	_root="$(_restore_play_work_root)"
	_art_dir="$_root/art"
	_dex_dst="$_art_dir/classes.dex"
	mkdir -p "$_art_dir/tmp" "$_art_dir/dalvik-cache" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} || return 1
	chown "$_play_uid:$_play_uid" "$_root" "$_art_dir" "$_art_dir/tmp" "$_art_dir/dalvik-cache" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	chmod 700 "$_root" "$_art_dir" "$_art_dir/tmp" "$_art_dir/dalvik-cache" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	local _src_sha _dst_sha _copy_reason="missing"
	if [[ -f $_dex_dst ]]; then
		if command -v cmp >/dev/null 2>&1 && cmp -s "$tools_path/classes.dex" "$_dex_dst" 2>/dev/null; then
			_speed_debug_log "PLAY_DEX_REUSE method=cmp dst=$_dex_dst"
		else
			_src_sha="$(sha256sum "$tools_path/classes.dex" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} | awk '{print $1}')"
			_dst_sha="$(sha256sum "$_dex_dst" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} | awk '{print $1}')"
			if [[ -n $_src_sha && $_src_sha = $_dst_sha ]]; then
				_speed_debug_log "PLAY_DEX_REUSE method=sha256 dst=$_dex_dst sha=$_src_sha"
			else
				_copy_reason="changed"
				cp -f "$tools_path/classes.dex" "$_dex_dst" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} || return 1
				_speed_debug_log "PLAY_DEX_COPY reason=$_copy_reason dst=$_dex_dst src_sha=${_src_sha:-unknown} dst_sha=${_dst_sha:-missing}"
			fi
		fi
	else
		cp -f "$tools_path/classes.dex" "$_dex_dst" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} || return 1
		_speed_debug_log "PLAY_DEX_COPY reason=$_copy_reason dst=$_dex_dst"
	fi
	chown "$_play_uid:$_play_uid" "$_dex_dst" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	# Android 14+/16 ART 禁止載入對呼叫 UID 可寫的 dex；必須只讀
	chmod 400 "$_dex_dst" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} || return 1
	restorecon -R "$_root" 2>>${SPEED_DEBUG_CMD_LOG:-/dev/null}
	echo "$_dex_dst"
}

_restore_apk_stage_root() {
	echo "$TMPDIR/.speedbackup_apk_stage"
}

_restore_apk_stage_dir() {
	local _pkg="$1"
	[[ -n $_pkg ]] || _pkg="unknown"
	printf '%s/%s\n' "$(_restore_apk_stage_root)" "${_pkg//[!a-zA-Z0-9_.-]/_}"
}

_restore_prepare_apk_stage_dir() {
	local _pkg="$1" _root _work
	if ! _speedbackup_tmpdir_is_safe "$TMPDIR"; then
		echoRgb "TMPDIR異常，拒絕建立 APK stage: $TMPDIR" "0"
		return 1
	fi
	_root="$(_restore_apk_stage_root)"
	_work="$(_restore_apk_stage_dir "$_pkg")"
	rm -rf "$_work" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	mkdir -p "$_work" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} || return 1
	chmod 711 "$_root" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	chmod 700 "$_work" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	restorecon -R "$_root" 2>>${SPEED_DEBUG_CMD_LOG:-/dev/null}
	echo "$_work"
}

_restore_apk_work_root() {
	echo "$TMPDIR/.speedbackup_apk_work"
}

_restore_clear_apk_work_dir() {
	local _work="$(_restore_apk_work_root)"
	case "$_work" in
	"$TMPDIR"/.speedbackup_apk_work) ;;
	*) echoRgb "APK work 路徑異常，拒絕清理: $_work" "0"; return 1 ;;
	esac
	_speedbackup_path_is_under_tmpdir "$_work" || { echoRgb "APK work 路徑異常，拒絕清理: $_work" "0"; return 1; }
	[[ -d $_work ]] || return 0
	find "$_work" -mindepth 1 -maxdepth 1 -exec rm -rf -- {} + 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
}

_restore_prepare_apk_work_dir() {
	local _pkg="$1" _work
	if ! _speedbackup_tmpdir_is_safe "$TMPDIR"; then
		echoRgb "TMPDIR異常，拒絕建立 APK work: $TMPDIR" "0"
		return 1
	fi
	_work="$(_restore_apk_work_root)"
	mkdir -p "$_work" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} || return 1
	chmod 700 "$_work" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	_restore_clear_apk_work_dir || return 1
	echo "$_work"
}

_restore_cleanup_play_session() {
	local _pkg="$1" _root _art_dir _install_root _work
	[[ ${restore_play_install_keep_workdir:-0} = 1 ]] && return 0
	if [[ ${_RESTORE_DEFER_PLAY_CLEANUP:-0} = 1 ]]; then
		[[ -n $_pkg ]] && _restore_log_install_stage "$_pkg" "CLEANUP_SKIP" "reason=deferred_for_fallback"
		return 0
	fi
	[[ -z $_pkg ]] && return 0
	_root="$(_restore_play_work_root)"
	_art_dir="$_root/art"
	_install_root="$_root/install"
	_work="$_install_root/$_pkg"
	# 只清本腳本建立的集中二進制目錄專用工作區，絕不清 Play 商店私有資料。
	# 294: 若 Install daemon 仍可 probe，保留 art/classes.dex 與 root，讓批量 !AppName 共用同一顆
	# Play UID app_process；只清每個 App 的 APK stage / install work，避免佔空間。
	if _install_daemon_probe; then
		rm -rf "$_work" "$(_restore_apk_stage_dir "$_pkg")" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
		_restore_log_install_stage "$_pkg" "CLEANUP_KEEP_DAEMON" "apk_stage=removed art=kept socket=$_INSTALL_DAEMON_SOCKET"
		[ -d "$_install_root" ] && rmdir "$_install_root" 2>/dev/null || true
		return 0
	fi
	rm -rf "$_art_dir" "$_work" "$(_restore_apk_stage_dir "$_pkg")" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	_restore_log_install_stage "$_pkg" "CLEANUP_OK" "workdir=removed"
	[ -d "$_install_root" ] && rmdir "$_install_root" 2>/dev/null || true
	[ -d "$_root" ] && rmdir "$_root" 2>/dev/null || true
	[ -d "$filepath/.speedbackup_play_session" ] && rmdir "$filepath/.speedbackup_play_session" 2>/dev/null || true
}

_restore_now_ms() {
	local _ms
	_ms="$(date +%s%3N 2>/dev/null)"
	case $_ms in ''|*[!0-9]*) _ms="$(date +%s 2>/dev/null)000" ;; esac
	case $_ms in ''|*[!0-9]*) _ms=0 ;; esac
	printf '%s' "$_ms"
}

_restore_log_install_stage() {
	local _pkg="$1" _stage="$2" _detail="$3"
	[[ -z $_pkg ]] && _pkg="unknown"
	[[ -z $_stage ]] && _stage="unknown"
	_restore_log_install_method "$_pkg" "INSTALL_STAGE_${_stage}" "$_detail"
}

_restore_log_install_timing() {
	local _pkg="$1" _name="$2" _start="$3" _end _elapsed
	[[ -z $_pkg ]] && _pkg="unknown"
	[[ -z $_name ]] && _name="unknown"
	_end="$(_restore_now_ms)"
	case $_start in ''|*[!0-9]*) _elapsed="unknown" ;; *) _elapsed=$((_end-_start)) ;; esac
	_restore_log_install_method "$_pkg" "INSTALL_TIMING" "${_name}Ms=$_elapsed"
}

_restore_count_stage_apks() {
	local _dir="$1" _n=0 _a
	for _a in "$_dir"/*.apk; do [[ -f $_a ]] && _n=$((_n+1)); done
	echo "$_n"
}

_restore_sum_stage_apk_bytes() {
	local _dir="$1" _sum=0 _a _sz
	for _a in "$_dir"/*.apk; do
		[[ -f $_a ]] || continue
		_sz=$(stat -c '%s' "$_a" 2>/dev/null || echo 0)
		case $_sz in *[!0-9]*|'') _sz=0 ;; esac
		_sum=$((_sum+_sz))
	done
	echo "$_sum"
}

_restore_log_install_method() {
	local _pkg="$1" _method="$2" _detail="$3" _line _log
	[[ -z $_pkg ]] && _pkg="unknown"
	[[ -z $_method ]] && _method="unknown"
	_line="INSTALL_METHOD $_pkg $_method"
	[[ -n $_detail ]] && _line="$_line $_detail"
	# INSTALL_METHOD 是機器判讀/除錯用資料，不直接顯示到終端，避免一般用戶看到 uid/uidexec/flags 等技術細節。
	echo "$_line" >> "$TMPDIR/.install_method_log" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	_log="${SPEED_DEBUG_RUN_DIR:-/data/speed_debug}/install_method.log"
	mkdir -p "${_log%/*}" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	echo "[$(date '+%Y-%m-%d %H:%M:%S')] $_line" >> "$_log" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	# v24.20.14-7.46 installer source strategy report：抽出使用者可讀的策略摘要，完整原始資料仍留 install_method.log。
# v24.20.14-7.47 mksh here-string cleanup：移除 <<< / done<<<，避免 Android sh 解析 unexpected redirection。
	case "$_method" in
		installer_context_ok|installer_context_pm_only|installer_context_skip|hybrid_installer_pm|hybrid_installer_pm_success|hybrid_installer_pm_failed|hybrid_installer_pm_source_mismatch|dex_play_session|dex_play_session_success|dex_play_session_failed|pm_install|pm_install_create|pm_fallback_after_*|play_session_requested_by_appList)
			local _slog="${SPEED_DEBUG_RUN_DIR:-/data/speed_debug}/install_strategy.log"
			mkdir -p "${_slog%/*}" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
			echo "[$(date '+%Y-%m-%d %H:%M:%S')] $_pkg $_method ${_detail:-}" >> "$_slog" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
			;;
	esac
}

_restore_save_play_session_raw_log() {
	local _pkg="$1" _file="$2" _log
	[[ -s $_file ]] || return 0
	_log="${SPEED_DEBUG_RUN_DIR:-/data/speed_debug}/install_session.log"
	mkdir -p "${_log%/*}" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	{
		echo "===== [$(date '+%Y-%m-%d %H:%M:%S')] $_pkg ====="
		cat "$_file"
		echo
	} >> "$_log" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
}

_restore_save_play_session_raw_log_from_line() {
	local _pkg="$1" _file="$2" _start="${3:-0}" _tmp
	[[ -s $_file ]] || return 0
	case $_start in ''|*[!0-9]*) _start=0 ;; esac
	_tmp="$(_webdav_tmp_path play_session_log_delta)"
	awk -v s="$_start" 'NR>s {print}' "$_file" > "$_tmp" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	_restore_save_play_session_raw_log "$_pkg" "$_tmp"
	rm -f "$_tmp" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
}

_restore_print_play_session_output() {
	local _file="$1" _mode="${restore_play_install_log_mode:-summary}"
	[[ -s $_file ]] || return 0
	case $_mode in
		raw|RAW|full|FULL)
			cat "$_file" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} | while read -r _l; do [[ -n $_l ]] && echoRgb "$_l" "2"; done
			;;
		quiet|QUIET|0|off|OFF)
			return 0
			;;
		*)
			cat "$_file" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} | grep -E 'INSTALL_SESSION (failed|failureCode|failureHint|packageNotFoundAfterWait|sourceVerifyFailed)' | while read -r _l; do
				[[ -n $_l ]] && echoRgb "$_l" "2"
			done
			;;
	esac
}

_restore_get_install_diag_value() {
	local _file="$1" _pkg="$2" _key="$3"
	awk -v p="$_pkg" -v k="$_key" '$1==p && $2=="INSTALL_DIAG" && $3==k {print $4; exit}' "$_file" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
}

_restore_verify_play_install_source_from_file() {
	local _pkg="$1" _diag="$2" _installer _installing _initiating _source
	[[ ${restore_play_install_verify_source:-1} = 1 ]] || return 0
	[[ -n $_pkg && -s $_diag ]] || return 1
	_installer="$(_restore_get_install_diag_value "$_diag" "$_pkg" installer)"
	_installing="$(_restore_get_install_diag_value "$_diag" "$_pkg" installing)"
	_initiating="$(_restore_get_install_diag_value "$_diag" "$_pkg" initiating)"
	_source="$(_restore_get_install_diag_value "$_diag" "$_pkg" packageSourceName)"
	if [[ $_installer = com.android.vending && $_installing = com.android.vending && $_initiating = com.android.vending ]]; then
		echoRgb "Play 來源驗證通過" "1"
		return 0
	fi
	# PackageInstaller session 失敗或未回完整 INSTALL_DIAG 時，交回 getInstallSourceInfo 路徑。
	[[ -z $_installer && -z $_installing && -z $_initiating ]] && return 1
	echoRgb "⚠️ Play來源驗證未完全通過: installer=${_installer:-null} installing=${_installing:-null} initiating=${_initiating:-null} source=${_source:-null}" "0"
	return 0
}

_restore_verify_play_install_source() {
	local _pkg="$1" _diag _installer _installing _initiating _source
	[[ ${restore_play_install_verify_source:-1} = 1 ]] || return 0
	[[ -n $_pkg ]] || return 1
	_diag="$TMPDIR/.play_install_source_${_pkg//[!a-zA-Z0-9]/_}"
	local _diag_err
	_diag_err="${TMPDIR:-/data/local/tmp}/.play_install_source_stderr_${_pkg//[!a-zA-Z0-9]/_}_$$"
	dex_hiddenapi_raw getInstallSourceInfo "$USER_ID" "$_pkg" 2>"$_diag_err" | _dex_filter_human_stdout > "$_diag"
	_dex_append_nonhuman_stderr "$_diag_err"
	rm -f "$_diag_err" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	_dex_translate_file "$_diag" "HiddenApiUtil:getInstallSourceInfo"
	# 詳細 INSTALL_DIAG 已寫入 speed_debug/install_session.log；終端只顯示通過/異常結論。
	_installer="$(_restore_get_install_diag_value "$_diag" "$_pkg" installer)"
	_installing="$(_restore_get_install_diag_value "$_diag" "$_pkg" installing)"
	_initiating="$(_restore_get_install_diag_value "$_diag" "$_pkg" initiating)"
	_source="$(_restore_get_install_diag_value "$_diag" "$_pkg" packageSourceName)"
	if [[ $_installer = com.android.vending && $_installing = com.android.vending && $_initiating = com.android.vending ]]; then
		echoRgb "Play 來源驗證通過" "1"
		rm -f "$_diag" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
		return 0
	fi
	echoRgb "⚠️ Play來源驗證未完全通過: installer=${_installer:-null} installing=${_installing:-null} initiating=${_initiating:-null} source=${_source:-null}" "0"
	[[ ${restore_play_install_keep_workdir:-0} = 1 ]] || rm -f "$_diag" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	# 安裝本身已成功，不在這裡回退 pm；pm 反而會導致 initiating=shell。
	return 0
}

_restore_play_install_options() {
	local _flags="INSTALL_REPLACE_EXISTING" _bypass="${restore_play_install_bypass_low_target:-auto}"
	_restore_bool_enabled "${restore_play_install_allow_test:-1}" && _flags="$_flags,INSTALL_ALLOW_TEST"
	_restore_bool_enabled "${restore_play_install_allow_downgrade:-0}" && _flags="$_flags,INSTALL_ALLOW_DOWNGRADE,INSTALL_REQUEST_DOWNGRADE"
	_restore_bool_enabled "${restore_play_install_grant_runtime_permissions:-0}" && _flags="$_flags,INSTALL_GRANT_RUNTIME_PERMISSIONS"
	case $_bypass in
		1|true|TRUE|yes|YES|on|ON) _flags="$_flags,INSTALL_BYPASS_LOW_TARGET_SDK_BLOCK" ;;
		auto|AUTO) [[ ${sdk:-0} -gt 33 ]] && _flags="$_flags,INSTALL_BYPASS_LOW_TARGET_SDK_BLOCK" ;;
	esac
	[[ -n ${restore_play_install_extra_flags:-} ]] && _flags="$_flags,${restore_play_install_extra_flags}"
	# 這些值預期為無空白 token；extra_flags 請用逗號分隔，不要加入空白。
	printf '%s' "--installer=com.android.vending --package-source=${restore_play_install_package_source:-store} --install-reason=${restore_play_install_reason:-user} --require-user-action=${restore_play_install_require_user_action:-not_required} --install-location=${restore_play_install_location:-auto} --install-flags=$_flags --dont-kill=${restore_play_install_dont_kill:-0} --human-log=${restore_play_install_human_log:-0}"
}

# 舊批量/預檢安裝路線已於 7.66-284 清除；!play 只保留 create=Play/write=root/commit=Play。

_restore_play_session_id_from_file() {
	local _pkg="$1" _file="$2"
	awk -v p="$_pkg" '$1==p && $2=="INSTALL_SESSION_CREATE" && $3=="sessionId" {print $4; exit}' "$_file" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
}

_restore_run_play_session_create_once() {
	local _pkg="$1" _play_uid="$2" _art_dir="$3" _dex_dst="$4" _apk_work="$5" _session_opts="$6" _out="$7" _sess_err _raw _rc _t0 _total
	_sess_err="${TMPDIR:-/data/local/tmp}/.play_install_create_stderr_${_pkg//[!a-zA-Z0-9]/_}_$$"
	_raw="$(_webdav_tmp_path play_session_create_raw)"
	rm -f "$_out" "$_sess_err" "$_raw" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	_total="$(_restore_sum_stage_apk_bytes "$_apk_work")"
	case $_total in ''|*[!0-9]*) _total=0 ;; esac
	_t0="$(_restore_now_ms)"
	# !play/STORE 路線改為 hybrid：Play UID daemon 建 session，APK bytes 仍由 root pm install-write 寫入。
	# 不能用 pipeline 承接 daemon call，否則 mksh 會在子 shell 內更新 _INSTALL_DAEMON_READY，commit 階段又重啟 daemon。
	# shellcheck disable=SC2086
	_install_daemon_call_args "$_play_uid" "$_art_dir" "$_dex_dst" installSessionCreate "$USER_ID" "$_pkg" "$_total" $_session_opts > "$_raw" 2>"$_sess_err"
	_rc=$?
	_dex_filter_human_stdout < "$_raw" > "$_out"
	rm -f "$_raw" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	if [[ $_rc = 125 ]]; then
		_speed_debug_log "INSTALL_DAEMON_REQUIRED_NO_SPAWN command=installSessionCreate pkg=$_pkg play_uid=$_play_uid"
	fi
	_restore_log_install_timing "$_pkg" "session_create" "$_t0"
	_dex_append_nonhuman_stderr "$_sess_err"
	rm -f "$_sess_err" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	_dex_translate_file "$_out" "HiddenApiUtil:installSessionCreate"
	_restore_save_play_session_raw_log "$_pkg" "$_out"
	_restore_print_play_session_output "$_out"
	return $_rc
}

_restore_play_session_write_root() {
	local _pkg="$1" _session_id="$2" _apk_work="$3" _out="$4" _err="$5" _a _name _rc _write_failed=0 _t0 _start_line
	[[ -n $_pkg && -n $_session_id && -d $_apk_work ]] || return 1
	_t0="$(_restore_now_ms)"
	_start_line="$(wc -l < "$_out" 2>/dev/null || echo 0)"
	case $_start_line in ''|*[!0-9]*) _start_line=0 ;; esac
	_restore_log_install_method "$_pkg" "dex_play_session_write_root" "session=$_session_id apkDir=$_apk_work writer=root"
	for _a in "$_apk_work"/*.apk; do
		[[ -f $_a ]] || continue
		_name="${_a##*/}"
		_name="${_name%.apk}"
		_restore_log_install_method "$_pkg" "dex_play_session_write_root_file" "session=$_session_id file=${_a##*/} splitName=$_name"
		pm install-write "$_session_id" "$_name" "$_a" >>"$_out" 2>>"$_err"
		_rc=$?
		echo "PLAY_SESSION_WRITE_ROOT file=${_a##*/} name=$_name rc=$_rc" >>"$_out"
		if [[ $_rc != 0 ]]; then _write_failed=1; break; fi
		echo_log "${_a##*/}寫入session"
	done
	_restore_log_install_timing "$_pkg" "session_write_root" "$_t0"
	_restore_save_play_session_raw_log_from_line "$_pkg" "$_out" "$_start_line"
	[[ $_write_failed = 0 ]]
}

_restore_run_play_session_commit_once() {
	local _pkg="$1" _play_uid="$2" _art_dir="$3" _dex_dst="$4" _session_id="$5" _session_opts="$6" _out="$7" _sess_err _raw _rc _t0 _start_line
	_sess_err="${TMPDIR:-/data/local/tmp}/.play_install_commit_stderr_${_pkg//[!a-zA-Z0-9]/_}_$$"
	_raw="$(_webdav_tmp_path play_session_commit_raw)"
	rm -f "$_sess_err" "$_raw" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	_t0="$(_restore_now_ms)"
	_start_line="$(wc -l < "$_out" 2>/dev/null || echo 0)"
	case $_start_line in ''|*[!0-9]*) _start_line=0 ;; esac
	# 不能用 pipeline 承接 daemon call，避免 create 成功後的 daemon ready 狀態丟在子 shell。
	# shellcheck disable=SC2086
	_install_daemon_call_args "$_play_uid" "$_art_dir" "$_dex_dst" installSessionCommit "$USER_ID" "$_pkg" "$_session_id" $_session_opts > "$_raw" 2>"$_sess_err"
	_rc=$?
	_dex_filter_human_stdout < "$_raw" >> "$_out"
	rm -f "$_raw" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	if [[ $_rc = 125 ]]; then
		_speed_debug_log "INSTALL_DAEMON_REQUIRED_NO_SPAWN command=installSessionCommit pkg=$_pkg play_uid=$_play_uid"
	fi
	_restore_log_install_timing "$_pkg" "session_commit" "$_t0"
	RESTORE_APK_TIMING_COMMIT_MS="$(_restore_elapsed_ms "$_t0")"
	_dex_append_nonhuman_stderr "$_sess_err"
	rm -f "$_sess_err" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	_dex_translate_file "$_out" "HiddenApiUtil:installSessionCommit"
	_restore_save_play_session_raw_log_from_line "$_pkg" "$_out" "$_start_line"
	_restore_print_play_session_output "$_out"
	return $_rc
}

_restore_hybrid_installer_source_ok() {
	local _pkg="$1" _installer="$2"
	[[ -n $_pkg && -n $_installer ]] || return 1
	# hybrid 成功後不再逐 app 額外啟動 dex 查來源；來源/完整性集中到最後 verifyAppStateBatch。
	# 這可省下每個 app 一次 app_process 啟動與 getInstallSourceInfo 診斷時間。
	_restore_log_install_method "$_pkg" "hybrid_installer_pm_source_deferred" "verify=verifyAppStateBatch installerExpected=$_installer installingExpected=$_installer initiatingExpected=$_installer packageSourceExpected=OTHER"
	return 0
}

_restore_uidexec_bin() {
	_speedbackup_tool_verify_once uidexec 1 || return 1
	local _u="${tools_path:-/data/backup_tools}/uidexec"
	if [[ -x $_u ]]; then
		printf '%s' "$_u"
		return 0
	fi
	_u="$(command -v uidexec 2>/dev/null || true)"
	if [[ -n $_u && -x $_u ]]; then
		printf '%s' "$_u"
		return 0
	fi
	return 1
}

_restore_install_with_hybrid_installer_pm() {
	local _pkg="$1" _apk_src="$2" _inst_pkg="$3" _inst_uid="$4" _inst_data_dir="$5"
	local _apk_work _rc _t_prepare _t_install _iarg _bypass="" _out _err _apk_count=0 _a _uidexec_bin
	local _session_id="" _session_raw="" _write_failed=0 _commit_rc=1 _nmsl="" _main_count=0 _legacy="" _name="" _commit_raw=""
	[[ -n $_pkg && -n $_inst_pkg ]] || return 1
	case $_inst_uid in ""|*[!0-9]*) echoRgb "安裝來源 $_inst_pkg UID 無效，跳過混合來源安裝流程" "0"; return 1 ;; esac
	[[ -d $_inst_data_dir ]] || { echoRgb "安裝來源 $_inst_pkg 缺少 data dir，跳過混合來源安裝流程" "2"; return 1; }
	_uidexec_bin="$(_restore_uidexec_bin)" || { echoRgb "找不到 uidexec，跳過混合來源安裝流程" "0"; return 1; }
	echoRgb "使用混合安裝來源安裝: $_inst_pkg" "3"
	# uidexec 會把 TMPDIR 指向 installer app data；pm install-create 可能需要此 tmp 目錄存在且 installer UID 可寫。
	mkdir -p "$_inst_data_dir/tmp" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	chown "$_inst_uid:$_inst_uid" "$_inst_data_dir/tmp" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	chmod 700 "$_inst_data_dir/tmp" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	_t_prepare="$(_restore_now_ms)"
	[[ -n $_apk_src && -d $_apk_src ]] || { echoRgb "APK 目錄不存在，跳過混合來源安裝流程" "0"; return 1; }
	if ! ls "$_apk_src"/*.apk >/dev/null 2>&1; then
		echoRgb "APK 目錄沒有 apk，跳過混合來源安裝流程" "0"
		return 1
	fi
	_apk_work="$_apk_src"
	_restore_log_install_stage "$_pkg" "READY" "mode=direct_root_write dir=$_apk_work apkCount=$(_restore_count_stage_apks "$_apk_work") bytes=skipped"
	_restore_log_install_timing "$_pkg" "prepare_hybrid_installer_pm" "$_t_prepare"
	_restore_log_install_method "$_pkg" "hybrid_installer_pm" "installer=$_inst_pkg uid=$_inst_uid uidexec=$_uidexec_bin dataDir=$_inst_data_dir apkDir=$_apk_work sourceNote=packageSource_OTHER_expected stage=direct_root_write"
	_iarg="$(_pm_installer_arg "$_inst_pkg")"
	[[ $sdk -gt 33 ]] && _bypass="--bypass-low-target-sdk-block"
	[[ $sdk -lt 30 ]] && _legacy="-l"
	_out="$TMPDIR/.hybrid_installer_pm_${_pkg//[!a-zA-Z0-9]/_}"
	_err="$TMPDIR/.hybrid_installer_pm_stderr_${_pkg//[!a-zA-Z0-9]/_}_$$"
	rm -f "$_out" "$_err" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	for _a in "$_apk_work"/*.apk; do
		[[ -f $_a ]] || continue
		_apk_count=$((_apk_count+1))
		[[ ${_a##*/} = nmsl.apk ]] && _nmsl="$_a" || _main_count=$((_main_count+1))
	done
	if [[ $_apk_count -lt 1 || $_main_count -lt 1 ]]; then
		_restore_log_install_method "$_pkg" "hybrid_installer_pm_failed" "rc=1 reason=no_apk apkCount=$_apk_count mainCount=$_main_count installer=$_inst_pkg"
		_restore_log_install_stage "$_pkg" "CLEANUP_SKIP" "reason=hybrid_installer_pm_failed_keep_for_fallback"
		return 1
	fi
	if [[ $_main_count -gt 1 ]]; then
		echoRgb "恢復split apk（混合安裝來源）" "2"
	else
		echoRgb "恢復普通apk（混合安裝來源）" "2"
	fi
	_t_install="$(_restore_now_ms)"
	{
		echo "HYBRID_INSTALLER_PM_BEGIN pkg=$_pkg installer=$_inst_pkg uid=$_inst_uid apkCount=$_apk_count mainCount=$_main_count sdk=$sdk"
		echo "HYBRID_INSTALLER_PM_ROUTE create=InstallerUID write=root commit=InstallerUID packageSource=OTHER_expected"
	} >>"$_out"

	# nmsl.apk 若存在，沿用舊版特殊處理：先獨立安裝，其他 APK 仍走混合 session。
	if [[ -n $_nmsl && -f $_nmsl ]]; then
		_restore_log_install_method "$_pkg" "hybrid_installer_pm_nmsl" "cmd=/system/bin/pm subcmd=install user=$user apk=nmsl.apk bypass=${_bypass:-none} installerArg=${_iarg:-none} writer=root installer=$_inst_pkg"
		# shellcheck disable=SC2086
		pm install -r $_bypass --user "$user" -t $_legacy $_iarg "$_nmsl" >>"$_out" 2>>"$_err"
		_rc=$?
		if [[ $_rc != 0 ]]; then
			_restore_log_install_method "$_pkg" "hybrid_installer_pm_failed" "rc=$_rc stage=nmsl_install installer=$_inst_pkg"
			_restore_log_install_timing "$_pkg" "hybrid_installer_pm_install" "$_t_install"
			cat "$_out" "$_err" 2>/dev/null >> "${SPEED_DEBUG_RUN_DIR:-/data/speed_debug}/install_session.log"
			rm -f "$_err" 2>/dev/null
			_restore_log_install_stage "$_pkg" "CLEANUP_SKIP" "reason=hybrid_installer_pm_failed_keep_for_fallback"
			[[ ${restore_play_install_keep_workdir:-0} = 1 ]] || rm -f "$_out" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
			return 1
		fi
		echo "HYBRID_INSTALLER_PM_NMSL_OK pkg=$_pkg installer=$_inst_pkg" >>"$_out"
		echo_log "nmsl.apk安裝"
	fi

	_restore_log_install_method "$_pkg" "hybrid_installer_pm_route" "create=InstallerUID write=root commit=InstallerUID user=$user apkCount=$_main_count packageSource=OTHER installer=$_inst_pkg"
	# Session ownership/initiating 在 install-create 當下決定：這一步必須由備份 installer UID 建立。
	# shellcheck disable=SC2086
	_session_raw="$("$_uidexec_bin" "$_inst_uid" "$_inst_uid" "$_inst_data_dir" "${tools_path}/classes.dex" \
		/system/bin/pm install-create -r $_bypass --user "$user" -t $_legacy $_iarg 2>>"$_err")"
	_rc=$?
	echo "HYBRID_INSTALLER_PM_CREATE rc=$_rc raw=$_session_raw" >>"$_out"
	_session_id="$(printf '%s\n' "$_session_raw" | sed -n 's/.*\[\([0-9][0-9]*\)\].*/\1/p' | head -n1)"
	if [[ $_rc = 0 && -n $_session_id ]]; then
		for _a in "$_apk_work"/*.apk; do
			[[ -f $_a && ${_a##*/} != nmsl.apk ]] || continue
			_name="${_a##*/}"
			_name="${_name%.apk}"
			_restore_log_install_method "$_pkg" "hybrid_installer_pm_write_root" "session=$_session_id file=${_a##*/} splitName=$_name installer=$_inst_pkg"
			# APK bytes 寫入由 root/shell 執行，使用原生 pm reverse-path，避開 installer UID reverse-mode 限制並保持速度。
			pm install-write "$_session_id" "$_name" "$_a" >>"$_out" 2>>"$_err"
			_rc=$?
			echo "HYBRID_INSTALLER_PM_WRITE_ROOT file=${_a##*/} name=$_name rc=$_rc" >>"$_out"
			if [[ $_rc != 0 ]]; then
				_write_failed=1
				break
			fi
			echo_log "${_a##*/}寫入session"
		done
		if [[ $_write_failed = 0 ]]; then
			# commit 優先由 installer UID 執行；若 ROM 對 ownership/權限有差異，再 root commit fallback。
			local _hybrid_commit_start
			_hybrid_commit_start="$(_speed_now_ms)"
			_commit_raw="$("$_uidexec_bin" "$_inst_uid" "$_inst_uid" "$_inst_data_dir" "${tools_path}/classes.dex" \
				/system/bin/pm install-commit "$_session_id" 2>>"$_err")"
			_commit_rc=$?
			echo "HYBRID_INSTALLER_PM_COMMIT_INSTALLER session=$_session_id rc=$_commit_rc raw=$_commit_raw" >>"$_out"
			if [[ $_commit_rc != 0 ]]; then
				_commit_raw="$(pm install-commit "$_session_id" 2>>"$_err")"
				_commit_rc=$?
				echo "HYBRID_INSTALLER_PM_COMMIT_ROOT session=$_session_id rc=$_commit_rc raw=$_commit_raw" >>"$_out"
			fi
			RESTORE_APK_TIMING_COMMIT_MS="$(_restore_elapsed_ms "$_hybrid_commit_start")"
			_rc=$_commit_rc
		else
			"$_uidexec_bin" "$_inst_uid" "$_inst_uid" "$_inst_data_dir" "${tools_path}/classes.dex" \
				/system/bin/pm install-abandon "$_session_id" >>"$_out" 2>>"$_err" || true
			pm install-abandon "$_session_id" >>"$_out" 2>>"$_err" || true
			_rc=1
		fi
	else
		_restore_log_install_method "$_pkg" "hybrid_installer_pm_failed" "rc=$_rc stage=install-create raw=${_session_raw:-empty} installer=$_inst_pkg"
		_rc=1
	fi
	_restore_log_install_timing "$_pkg" "hybrid_installer_pm_install" "$_t_install"
	cat "$_out" "$_err" 2>/dev/null >> "${SPEED_DEBUG_RUN_DIR:-/data/speed_debug}/install_session.log"
	rm -f "$_err" 2>/dev/null
	if [[ $_rc = 0 ]]; then
		if [[ $_main_count -gt 1 ]]; then
			echoRgb "split Apk提交成功，等待PackageManager驗證" "1"
		else
			echoRgb "Apk提交成功，等待PackageManager驗證" "1"
		fi
		_speed_debug_log "OK: Apk提交 stage=commit_wait_package_verify mode=r370"
		result=0
		Set_back_0
		_restore_log_install_method "$_pkg" "hybrid_installer_pm_success" "rc=0 apkCount=$_apk_count mainCount=$_main_count mode=create_installer_write_root_commit_installer installer=$_inst_pkg sourceExpected=installer_installing_initiating_${_inst_pkg}_packageSource_OTHER"
		echoRgb "混合安裝來源commit成功: $_inst_pkg" "1"
		if _restore_hybrid_installer_source_ok "$_pkg" "$_inst_pkg"; then
			rm -f "$_out" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
			return 0
		fi
		_restore_log_install_method "$_pkg" "hybrid_installer_pm_source_mismatch" "fallback=pm installer=$_inst_pkg"
	else
		_restore_log_install_method "$_pkg" "hybrid_installer_pm_failed" "rc=$_rc apkCount=$_apk_count mainCount=$_main_count mode=create_installer_write_root_commit_installer installer=$_inst_pkg"
		echoRgb "混合安裝來源commit失敗: $_inst_pkg" "0"
	fi
	# 失敗或來源不完整時不能清理 APK 目錄；後續 pm fallback 或 !play 慢速模式仍要共用同一批 APK。
	_restore_log_install_stage "$_pkg" "CLEANUP_SKIP" "reason=hybrid_installer_pm_failed_keep_for_fallback"
	[[ ${restore_play_install_keep_workdir:-0} = 1 ]] || rm -f "$_out" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	return 1
}
_restore_install_with_play_session() {
	local _pkg="$1" _apk_src="$2" _play_uid _dex_dst _apk_work _out _err _rc _art_dir _session_opts _session_id _t_prepare
	[[ -n $_pkg ]] || return 1
	_restore_has_play_store || { echoRgb "未找到 Google Play 商店，跳過 Play UID 安裝流程" "2"; return 1; }
	_play_uid="$(_restore_play_uid)"
	case $_play_uid in ""|*[!0-9]*) echoRgb "無法取得 Google Play UID，跳過 Play UID 安裝流程" "0"; return 1 ;; esac
	[[ -n $_apk_src && -d $_apk_src ]] || return 1
	_apk_work="$_apk_src"
	_t_prepare="$(_restore_now_ms)"
	_dex_dst="$(_restore_prepare_play_dex "$_play_uid")" || { echoRgb "準備 Play 私有 dex 失敗，跳過 Play UID 安裝流程" "0"; _restore_cleanup_play_session "$_pkg"; return 1; }
	_restore_log_install_timing "$_pkg" "prepare" "$_t_prepare"
	_art_dir="$(_restore_play_work_root)/art"
	_out="$TMPDIR/.play_install_session_${_pkg//[!a-zA-Z0-9]/_}"
	_err="$TMPDIR/.play_install_session_write_stderr_${_pkg//[!a-zA-Z0-9]/_}_$$"
	rm -f "$_out" "$_err" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	_restore_log_install_method "$_pkg" "dex_play_session" "installer=com.android.vending uid=$_play_uid uidexec=uidexec mode=create_play_write_root_commit_play apkDir=$_apk_work"
	echoRgb "使用 Google Play UID hybrid session 安裝 APK..." "3"
	_session_opts="$(_restore_play_install_options)"
	_restore_log_install_method "$_pkg" "dex_play_session_options" "flags=${restore_play_install_extra_flags:-default} downgrade=${restore_play_install_allow_downgrade:-0} test=${restore_play_install_allow_test:-1} source=${restore_play_install_package_source:-store} logMode=${restore_play_install_log_mode:-summary} humanLog=${restore_play_install_human_log:-0} route=createPlay_writeRoot_commitPlay"
	if ! _restore_run_play_session_create_once "$_pkg" "$_play_uid" "$_art_dir" "$_dex_dst" "$_apk_work" "$_session_opts" "$_out"; then
		echoRgb "Play UID 建立安裝 session 失敗" "0"
		_restore_log_install_method "$_pkg" "dex_play_session_failed" "stage=create installer=com.android.vending"
		_RESTORE_DEFER_PLAY_CLEANUP=1 _restore_cleanup_play_session "$_pkg"
		[[ ${restore_play_install_keep_workdir:-0} = 1 ]] || rm -f "$_out" "$_err" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
		return 1
	fi
	_session_id="$(_restore_play_session_id_from_file "$_pkg" "$_out")"
	case $_session_id in ''|*[!0-9]*)
		echoRgb "Play UID 建立 session 後無 sessionId" "0"
		_restore_log_install_method "$_pkg" "dex_play_session_failed" "stage=parse_session_id raw=empty"
		_RESTORE_DEFER_PLAY_CLEANUP=1 _restore_cleanup_play_session "$_pkg"
		[[ ${restore_play_install_keep_workdir:-0} = 1 ]] || rm -f "$_out" "$_err" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
		return 1
		;;
	esac
	if ! _restore_play_session_write_root "$_pkg" "$_session_id" "$_apk_work" "$_out" "$_err"; then
		echoRgb "root 寫入 Play session 失敗" "0"
		_restore_log_install_method "$_pkg" "dex_play_session_failed" "stage=write_root session=$_session_id installer=com.android.vending"
		pm install-abandon "$_session_id" >>"$_out" 2>>"$_err" || true
		cat "$_out" "$_err" 2>/dev/null >> "${SPEED_DEBUG_RUN_DIR:-/data/speed_debug}/install_session.log"
		rm -f "$_err" 2>/dev/null
		_RESTORE_DEFER_PLAY_CLEANUP=1 _restore_cleanup_play_session "$_pkg"
		[[ ${restore_play_install_keep_workdir:-0} = 1 ]] || rm -f "$_out" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
		return 1
	fi
	cat "$_err" 2>/dev/null >> "${SPEED_DEBUG_RUN_DIR:-/data/speed_debug}/install_session.log"
	rm -f "$_err" 2>/dev/null
	_restore_run_play_session_commit_once "$_pkg" "$_play_uid" "$_art_dir" "$_dex_dst" "$_session_id" "$_session_opts" "$_out"
	_rc=$?
	if [[ $_rc = 0 ]] && grep -q "$_pkg INSTALL_SESSION packageFound" "$_out" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}; then
		echoRgb "Play UID hybrid session 安裝成功" "1"
		_restore_log_install_method "$_pkg" "dex_play_session_success" "installer=com.android.vending mode=create_play_write_root_commit_play session=$_session_id"
		_restore_verify_play_install_source_from_file "$_pkg" "$_out" || _restore_verify_play_install_source "$_pkg"
		_restore_cleanup_play_session "$_pkg"
		rm -f "$_out" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
		return 0
	fi
	echoRgb "Play UID hybrid session 安裝失敗" "0"
	_restore_log_install_method "$_pkg" "dex_play_session_failed" "stage=commit session=$_session_id installer=com.android.vending"
	_RESTORE_DEFER_PLAY_CLEANUP=1 _restore_cleanup_play_session "$_pkg"
	[[ ${restore_play_install_keep_workdir:-0} = 1 ]] || rm -f "$_out" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	return 1
}

_pm_installer_arg() {
	local _installer="$1"
	_restore_bool_enabled "${restore_pm_install_with_installer:-1}" || return 0
	# 呼叫端必須先經過 _restore_select_installer_context 驗證；這裡只負責組 pm 參數。
	case $_installer in ""|null|NULL|clear|CLEAR|none|NONE) return 0 ;; esac
	printf '%s\n' "-i $_installer"
}

_pm_install_single() {
	local _apk="$1" _installer="$2" _pkg="${3:-}" _iarg _bypass="" _legacy="" _err _rc
	[[ -f $_apk ]] || return 1
	_iarg="$(_pm_installer_arg "$_installer")"
	[[ $sdk -gt 33 ]] && _bypass="--bypass-low-target-sdk-block"
	# 與 _pm_install_create_session / _restore_install_with_hybrid_installer_pm 一致：
	# sdk<30 (Android 9/10) 需要 -l，這裡原本漏掉，單一 apk (最常見路徑) 在舊機上會跟其他安裝路線不一致。
	[[ $sdk -lt 30 ]] && _legacy="-l"
	_err="${SPEED_DEBUG_RUN_DIR:-/data/speed_debug}/pm_install_stderr.log"
	mkdir -p "${_err%/*}" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	# shellcheck disable=SC2086
	pm install -r $_bypass --user "$user" -t $_legacy $_iarg "$_apk" >/dev/null 2>>"$_err"
	_rc=$?
	if [[ $_rc != 0 ]]; then
		_restore_log_install_method "${_pkg:-unknown}" "pm_install_failed" "rc=$_rc user=$user apk=${_apk##*/} stderr=pm_install_stderr.log"
	fi
	return "$_rc"
}

_pm_install_create_session() {
	local _installer="$1" _iarg _bypass="" _legacy=""
	_iarg="$(_pm_installer_arg "$_installer")"
	[[ $sdk -gt 33 ]] && _bypass="--bypass-low-target-sdk-block"
	[[ $sdk -lt 30 ]] && _legacy="-l"
	# shellcheck disable=SC2086
	pm install-create $_bypass --user "$user" -t $_legacy $_iarg
}

_restore_pm_install_existing_for_user() {
	# r435: install-existing 僅預設用於非 owner user。
	# user=0 全量恢復直接走 APK install，避免每個 missing App 先做 install-existing 造成額外開銷；
	# 需要時可用 SPEEDBACKUP_RESTORE_INSTALL_EXISTING_FOR_OWNER=1 手動打開 owner user install-existing。
	# 非 owner user 可能只差「此 user 未啟用 package」，所以保留 r434 的 install-existing 優先路徑。
	local _pkg="$1" _label="$2" _backup_ver="$3" _out _err _rc _t0 _elapsed _raw _cmd _ok=0
	[[ -n $_pkg && -n ${user:-} ]] || return 1
	_out="$TMPDIR/.pm_install_existing_${_pkg//[!a-zA-Z0-9_.-]/_}_${$}_$RANDOM.out"
	_err="$TMPDIR/.pm_install_existing_${_pkg//[!a-zA-Z0-9_.-]/_}_${$}_$RANDOM.err"
	_t0="$(_speed_now_ms)"
	_restore_log_install_method "$_pkg" "pm_install_existing_try" "user=$user backupVersion=${_backup_ver:-unknown} label=$(_restore_apk_timing_field "$_label")"
	for _cmd in pm cmd; do
		: > "$_out" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
		: > "$_err" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
		case $_cmd in
			pm) pm install-existing --user "$user" "$_pkg" >"$_out" 2>"$_err" ;;
			cmd) cmd package install-existing --user "$user" "$_pkg" >"$_out" 2>"$_err" ;;
		esac
		_rc=$?
		_elapsed="$(_restore_elapsed_ms "$_t0")"
		_raw="$(cat "$_out" "$_err" 2>/dev/null | tr '\t\r\n' '   ' | sed 's/[ ][ ]*/_/g' | cut -c1-360)"
		_restore_log_install_method "$_pkg" "pm_install_existing_result" "cmd=$_cmd rc=$_rc elapsedMs=$_elapsed raw=${_raw:-empty}"
		if [[ $_rc = 0 ]]; then
			_ok=1
			break
		fi
	done
	rm -f "$_out" "$_err" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	[[ $_ok = 1 ]] || return 1
	if _pkg_uid_map_refresh_after_install "$_pkg"; then
		_speed_debug_log "RESTORE_INSTALL_EXISTING_OK package=$_pkg label=$(_restore_apk_timing_field "$_label") user=$user version=${RESTORE_PKG_VER:-unknown} backupVersion=${_backup_ver:-unknown} mode=r440"
		echoRgb "已為用戶$user啟用既有安裝：$_label" "1"
		return 0
	fi
	_speed_debug_log "RESTORE_INSTALL_EXISTING_VERIFY_FAIL package=$_pkg label=$(_restore_apk_timing_field "$_label") user=$user backupVersion=${_backup_ver:-unknown} mode=r440"
	return 1
}

# 安裝 apk (含 split apk 處理), 自動繞過安裝驗證
installapk() {
	local _apk_stage _apk_total_start _apk_extract_start _apk_install_start _apk_extract_ms=0 _apk_install_ms=0 _apk_commit_ms=0 _apk_bytes=0
	_apk_total_start="$(_speed_now_ms)"
	RESTORE_APK_TIMING_EXTRACT_MS=0
	RESTORE_APK_TIMING_INSTALL_MS=0
	RESTORE_APK_TIMING_COMMIT_MS=0
	RESTORE_APK_TIMING_VERIFY_MS=0
	RESTORE_APK_TIMING_TOTAL_MS=0
	RESTORE_APK_TIMING_BYTES=0
	RESTORE_APK_TIMING_ACTION="${RESTORE_APK_ACTION_CONTEXT:-install}"
	RESTORE_APK_TIMING_REASON="pending"
	if [[ ${_restore_force_play_session:-0} = 1 ]]; then
		_apk_stage="$(_restore_prepare_apk_stage_dir "$name2")" || { result=1; Set_back_1; return 1; }
	else
		_apk_stage="$(_restore_prepare_apk_work_dir "$name2")" || { result=1; Set_back_1; return 1; }
	fi
	# 流式恢復: 從遠端拉 apk.tar.zst → 解壓到本次 APK work 目錄 (apk 安裝需檔案, pm install 不能用 stdin)
	if [[ $_RESTORE_STREAM = 1 && -n $_STREAM_APK_SRC ]]; then
		local _apk_stream_extract_raw_log _apk_stream_extract_raw_start
		_apk_stream_extract_raw_start="$(_speed_now_ms)"; local _apk_stream_profile_start="$_apk_stream_extract_raw_start"; case $_apk_stream_extract_raw_start in ''|*[!0-9]*) _apk_stream_extract_raw_start="$(date +%s 2>/dev/null)000" ;; esac
		_apk_stream_extract_raw_log="$(_local_raw_debug_begin extract "kind=apk-stream src=$_STREAM_APK_SRC dest=$_apk_stage ext=${_STREAM_APK_SRC##*.}")"
			local _apk_stream_extract_pid _apk_stream_extract_msg _apk_stream_event_fifo
			_apk_stream_extract_msg="正在流式解壓 apk.tar.zst → $_apk_stage"
			_apk_stream_event_fifo="$(_remote_stream_event_prepare stream_extract_apk 2>/dev/null || true)"
			case ${_STREAM_APK_SRC##*.} in
			zst) ( export SPEEDBACKUP_REMOTE_STREAM_EVENT_FIFO="$_apk_stream_event_fifo" SPEEDBACKUP_REMOTE_STREAM_EVENT_TAG="stream_extract_apk"; set -o pipefail 2>/dev/null; _stream_download "$_STREAM_APK_SRC" | zstd -d 2>>"$_apk_stream_extract_raw_log" | tar --checkpoint-action="ttyout=%T\r" -xmpf - -C "$_apk_stage" 2>>"$_apk_stream_extract_raw_log"; _ev_rc=$?; _remote_stream_event_emit done "$_ev_rc" stream_extract_apk complete; exit "$_ev_rc" ) & _apk_stream_extract_pid=$! ;;
			tar) ( export SPEEDBACKUP_REMOTE_STREAM_EVENT_FIFO="$_apk_stream_event_fifo" SPEEDBACKUP_REMOTE_STREAM_EVENT_TAG="stream_extract_apk"; set -o pipefail 2>/dev/null; _stream_download "$_STREAM_APK_SRC" | tar --checkpoint-action="ttyout=%T\r" -xmpf - -C "$_apk_stage" 2>>"$_apk_stream_extract_raw_log"; _ev_rc=$?; _remote_stream_event_emit done "$_ev_rc" stream_extract_apk complete; exit "$_ev_rc" ) & _apk_stream_extract_pid=$! ;;
			esac
			_remote_stream_wait_pid_busy_abortable "$_apk_stream_extract_pid" "$_apk_stream_extract_msg" "stream_extract_apk" "" 1 "$_apk_stream_event_fifo"
			result=$?
			if [[ $_RESTORE_STREAM = 1 ]] && _remote_stream_fatal_active; then
				_speed_debug_log "STREAM_RESTORE_APK_EXTRACT_REMOTE_FATAL app=${name1:-} src=${_STREAM_APK_SRC:-} result=$result mode=r370"
				result=126
			elif [[ $result != 0 ]] && _remote_extract_log_transport_failure "$_apk_stream_extract_raw_log"; then
				_remote_connectivity_fast_fail "stream_restore_apk_extract" "${_STREAM_APK_SRC:-}" "apk_extract_short_read_or_transport" || true
				_remote_stream_mark_fatal "${_STREAM_APK_SRC:-}" 126 0 "restore apk stream transport failure; fast-fail without retry"
				_speed_debug_log "STREAM_RESTORE_APK_EXTRACT_TRANSPORT_FATAL app=${name1:-} package=${name2:-} src=${_STREAM_APK_SRC:-} rc=$result mode=r370"
				result=126
			fi
		_local_raw_debug_end extract "$_apk_stream_extract_raw_log" "$result" "$_apk_stream_extract_raw_start" "kind=apk-stream dest=$_apk_stage"
		_restore_perf_timing_done "apk_extract" "$_apk_stream_profile_start" "app=${name1:-} package=${name2:-} stream=1 src=${_STREAM_APK_SRC:-} rc=$result dest=$_apk_stage"
		RESTORE_APK_TIMING_EXTRACT_MS="$(_restore_elapsed_ms "$_apk_stream_profile_start")"
		echo_log "apk流式解壓" "" "$result"
		if [[ $result != 0 ]]; then
			[[ ${_restore_force_play_session:-0} != 1 ]] && _restore_clear_apk_work_dir
			[[ $_RESTORE_STREAM = 1 ]] && _remote_stream_fatal_active && return 126
			return 1
		fi
	else
		apkfile="$(find "$Backup_folder" -maxdepth 1 -name "apk.*" -type f 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null})"
		if [[ $apkfile != "" ]]; then
			local _apk_extract_raw_log _apk_extract_raw_start _apk_size
			_apk_size="$(_local_file_size_debug "$apkfile")"
			_apk_extract_raw_start="$(_speed_now_ms)"; local _apk_profile_start="$_apk_extract_raw_start"; case $_apk_extract_raw_start in ''|*[!0-9]*) _apk_extract_raw_start="$(date +%s 2>/dev/null)000" ;; esac
			_apk_extract_raw_log="$(_local_raw_debug_begin extract "kind=apk file=$apkfile dest=$_apk_stage ext=${apkfile##*.} size=$_apk_size")"
			case ${apkfile##*.} in
			zst) ( set -o pipefail 2>/dev/null; zstd -d < "$apkfile" 2>>"$_apk_extract_raw_log" | tar --checkpoint-action="ttyout=%T\r" -xmpf - -C "$_apk_stage" 2>>"$_apk_extract_raw_log" ) ;;
			tar) tar --checkpoint-action="ttyout=%T\r" -xmpf "$apkfile" -C "$_apk_stage" 2>>"$_apk_extract_raw_log" ;;
			*)
				echoRgb "${apkfile##*/} 壓縮包不支持解壓縮" "0"
				Set_back_1
				;;
			esac
			result=$?
			_local_raw_debug_end extract "$_apk_extract_raw_log" "$result" "$_apk_extract_raw_start" "kind=apk dest=$_apk_stage"
			_restore_perf_timing_done "apk_extract" "$_apk_profile_start" "app=${name1:-} package=${name2:-} stream=0 file=$apkfile size=${_apk_size:-0} rc=$result dest=$_apk_stage"
			RESTORE_APK_TIMING_EXTRACT_MS="$(_restore_elapsed_ms "$_apk_profile_start")"
			echo_log "${apkfile##*/}解壓縮" "" "$result" && [[ -f $Backup_folder/nmsl.apk ]] && cp -r "$Backup_folder/nmsl.apk" "$_apk_stage"
			if [[ $result != 0 ]]; then
				[[ ${_restore_force_play_session:-0} != 1 ]] && _restore_clear_apk_work_dir
				return 1
			fi
		else
			echoRgb "你的Apk壓縮包離家出走了，可能備份後移動過程遺失了\n -解決辦法手動安裝Apk後再執行恢復腳本" "0"
			result=1
			Set_back_1
		fi
	fi
	if [[ $result = 0 ]]; then
		# 用 glob + 計數取代 find | wc (省 2 fork)
		local _apks _apk_count=0 _installer _installer_raw _used_play_session=0 _fallback_pm=0 _apk_install_profile_start
		_apk_install_profile_start="$(_speed_now_ms)"
		for _apks in "$_apk_stage"/*.apk; do
			[[ -f $_apks ]] && let _apk_count++
		done
		_installer_raw="$(_restore_backup_installer_value "$app_details")"
		_installer=""
		# 備份 installer 只作為候選；必須在目前 user 真的存在且能取得 UID，才允許用於 -i / UID hybrid。
		if [[ $_apk_count -gt 0 ]]; then
			if _restore_select_installer_context "$name2" "$_installer_raw"; then
				_installer="$RESTORE_INSTALLER_PKG"
			else
				_installer=""
			fi
		fi
		# !play 是使用者明確指定的慢速 STORE 來源路線，仍維持 Play Java session；失敗固定回退原生 pm。
		if [[ $_apk_count -gt 0 && ${_restore_force_play_session:-0} = 1 ]]; then
			echoRgb "${_restore_force_play_marker:-!play} 標記：使用 Play UID hybrid session 安裝（create/commit=Play，write=root）" "3"
			_restore_log_install_method "$name2" "play_session_requested_by_appList" "marker=${_restore_force_play_marker:-!play} mode=play_daemon_create_root_write_play_commit installerBackup=${_installer_raw:-null} validatedInstaller=${_installer:-null} fallback=pm packageSource=STORE"
			if _restore_install_with_play_session "$name2" "$_apk_stage"; then
				_used_play_session=1
				result=0
				Set_back_0
			else
				echoRgb "Play UID hybrid session 安裝失敗，回退原生 pm" "3"
				_restore_log_install_method "$name2" "pm_fallback_after_play_session_failed" "installer=${_installer:-null} rawInstaller=${_installer_raw:-null}"
				_fallback_pm=1
			fi
		elif [[ $_apk_count -gt 0 && -n $_installer && -n ${RESTORE_INSTALLER_UID:-} && -n ${RESTORE_INSTALLER_DATA_DIR:-} ]]; then
			if [[ ${_restore_hybrid_installer_pm_disabled:-0} = 1 ]]; then
				echoRgb "本輪已停用混合安裝來源，直接使用原生 pm" "3"
				_restore_log_install_method "$name2" "hybrid_installer_pm_skip_disabled" "fallback=pm installer=${_installer:-null} rawInstaller=${_installer_raw:-null}"
				_fallback_pm=1
			elif _restore_install_with_hybrid_installer_pm "$name2" "$_apk_stage" "$RESTORE_INSTALLER_PKG" "$RESTORE_INSTALLER_UID" "$RESTORE_INSTALLER_DATA_DIR"; then
				_used_play_session=1
				result=0
				Set_back_0
				if [[ ${_restore_hybrid_installer_pm_consecutive_fail:-0} != 0 ]]; then
					_restore_log_install_method "$name2" "hybrid_installer_pm_consecutive_fail_reset" "reason=next_app_hybrid_success previousFailures=${_restore_hybrid_installer_pm_consecutive_fail:-0} installer=${_installer:-null} rawInstaller=${_installer_raw:-null}"
				fi
			_restore_hybrid_installer_pm_consecutive_fail=0
			else
				# r245: 不能同一個 App 連續跑兩次混合安裝。
				# 第一次 hybrid 失敗只讓「本 App」回退原生 pm，下一個符合條件的 App 再測一次 hybrid；
				# 只有連續兩個不同 App 都 hybrid 失敗，才停用本輪後續 hybrid。
				if [[ ${_restore_hybrid_installer_pm_consecutive_fail:-0} -ge 1 ]]; then
					echoRgb "混合安裝來源連續兩個應用失敗，本輪後續全部回退原生 pm" "3"
					_restore_hybrid_installer_pm_disabled=1
					_restore_log_install_method "$name2" "hybrid_installer_pm_disable_for_batch" "fallback=pm policy=next_app_probe consecutiveApps=2 installer=${_installer:-null} rawInstaller=${_installer_raw:-null}"
				else
					echoRgb "混合安裝來源commit失敗，本 App 回退原生 pm；下一個符合條件的 App 再測一次混合安裝" "3"
					_restore_hybrid_installer_pm_consecutive_fail=1
					_restore_log_install_method "$name2" "hybrid_installer_pm_first_fail_defer_batch_disable" "fallback=pm policy=next_app_probe consecutiveApps=1 installer=${_installer:-null} rawInstaller=${_installer_raw:-null}"
				fi
				_fallback_pm=1
			fi
		fi
		if [[ $_used_play_session != 1 ]]; then
			case $_apk_count in
			1)
				echoRgb "恢復普通apk" "2"
				_restore_log_install_method "$name2" "pm_install" "apk=single installer=${_installer:-null}"
				_pm_install_single "$_apk_stage"/*.apk "$_installer" "$name2"
				echo_log "Apk安裝"
				;;
			0)
				echoRgb "$_apk_stage 中沒有apk" "0"
				Set_back_1
				;;
			*)
				echoRgb "恢復split apk" "2"
				_restore_log_install_method "$name2" "pm_install_create" "apk=split count=$_apk_count installer=${_installer:-null}"
				b="$(_pm_install_create_session "$_installer" | grep -Eo '[0-9]+')"
				if [[ -z $b ]]; then
					echoRgb "pm install-create 失敗" "0"
					Set_back_1
					[[ -n ${_apk_install_profile_start:-} ]] && _restore_perf_timing_done "apk_install" "$_apk_install_profile_start" "app=${name1:-} package=${name2:-} apkCount=${_apk_count:-0} rc=1 stage=install_create_failed"
					[[ ${_restore_force_play_session:-0} != 1 ]] && _restore_clear_apk_work_dir
					return 1
				fi
				if [[ -f $_apk_stage/nmsl.apk ]]; then
					_pm_install_single "$_apk_stage/nmsl.apk" "$_installer" "$name2"
					echo_log "nmsl.apk安裝"
				fi
				# 用 glob 取代 find | grep -v (省 fork)
				for _apks in "$_apk_stage"/*.apk; do
					[[ -f $_apks && ${_apks##*/} != nmsl.apk ]] || continue
					pm install-write "$b" "${_apks##*/}" "$_apks" </dev/null >/dev/null
					echo_log "${_apks##*/}寫入session"
				done
				local _pm_commit_start
				_pm_commit_start="$(_speed_now_ms)"
				pm install-commit "$b" >/dev/null
				RESTORE_APK_TIMING_COMMIT_MS="$(_restore_elapsed_ms "$_pm_commit_start")"
				echo_log "split Apk安裝"
				;;
			esac
		fi
	fi
	if [[ -n ${_apk_install_profile_start:-} ]]; then
		RESTORE_APK_TIMING_INSTALL_MS="$(_restore_elapsed_ms "$_apk_install_profile_start")"
		_restore_perf_timing_done "apk_install" "$_apk_install_profile_start" "app=${name1:-} package=${name2:-} apkCount=${_apk_count:-0} rc=${result:-1} usedPlaySession=${_used_play_session:-0} fallbackPm=${_fallback_pm:-0}"
	fi
	RESTORE_APK_TIMING_BYTES="$(_restore_sum_stage_apk_bytes "$_apk_stage" 2>/dev/null || echo 0)"
	case ${RESTORE_APK_TIMING_BYTES:-} in ''|*[!0-9]*) RESTORE_APK_TIMING_BYTES=0 ;; esac
	RESTORE_APK_TIMING_TOTAL_MS="$(_restore_elapsed_ms "$_apk_total_start")"
	case ${result:-1} in 0) RESTORE_APK_TIMING_REASON="${RESTORE_APK_TIMING_REASON:-install_ok}" ;; *) RESTORE_APK_TIMING_REASON="install_failed" ;; esac
	[[ ${_restore_force_play_session:-0} != 1 ]] && _restore_clear_apk_work_dir
	case ${result:-1} in ''|*[!0-9]*) return 1 ;; *) return "$result" ;; esac
}
# 關閉 apk 安裝驗證 (verifier_verify_adb_installs)
# 避免 Play Protect / 系統驗證攔截批次安裝
disable_verify() {
	#禁用apk驗證
	settings put global verifier_verify_adb_installs 0 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	#禁用安裝包驗證
	settings put global package_verifier_enable 0 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	#未知來源
	settings put secure install_non_market_apps 1 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	#關閉play安全校驗
	if [[ $(settings get global package_verifier_user_consent 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}) != -1 ]]; then
		settings put global package_verifier_user_consent -1 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
		settings put global upload_apk_enable 0 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
		echoRgb "PLAY安全驗證為開啟狀態已被腳本關閉防止apk安裝失敗" "3"
	fi
	# 額外安全性攔截
	settings put global harmful_app_warning_on 0 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	# 關閉應用的受限模式 (針對 Android 13/14 側載應用)
	settings put secure enhanced_confirmation_states 0 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	# 設定檔案路徑
	FILE="/data/data/com.android.vending/shared_prefs/finsky.xml"
	if [[ -f $FILE ]]; then
		# 提取當前的 auto_update_enabled 值
		CURRENT_VALUE="$(sed -n '/<boolean name="auto_update_enabled" /s/.*value="\([^"]*\)".*/\1/p' "$FILE")"
		if [[ $CURRENT_VALUE = true ]]; then
			sed -i '/<boolean name="auto_update_enabled" /s/value="true"/value="false"/' "$FILE"
			[[ $(sed -n '/<boolean name="auto_update_enabled" /s/.*value="\([^"]*\)".*/\1/p' "$FILE") = false ]] && echoRgb "play自動更新已關閉" "3"
			echoRgb "殺死 Google Play 商店..."
			_force_stop_pkg_best_effort com.android.vending "play_store_auto_update" >/dev/null 2>&1 || true
		else
			if [[ $CURRENT_VALUE = "" ]]; then
				sed -i '/<\/map>/i \    <boolean name="auto_update_enabled" value="false" />' "$FILE"
				[[ $(sed -n '/<boolean name="auto_update_enabled" /s/.*value="\([^"]*\)".*/\1/p' "$FILE") = false ]] && echoRgb "auto_update_enabled已插入false,play自動更新已關閉" "3"
				echoRgb "殺死 Google Play 商店..."
				_force_stop_pkg_best_effort com.android.vending "play_store_auto_update" >/dev/null 2>&1 || true
			else
				[[ $CURRENT_VALUE != false ]] && echoRgb "無法識別play auto_update_enabled當前$CURRENT_VALUE值" "0"
			fi
		fi
	fi
}
# 取得目前使用者已安裝包名；r44 起只信任 AppInventory，失敗時回空讓呼叫端跳過破壞性清理。
_installed_app_packages() {
	local _user="${1:-${user:-0}}" _packages _old_user="${USER_ID:-}"
	USER_ID="$_user"
	_packages="$(appinventory pkgName all 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null})"
	USER_ID="$_old_user"
	if [[ -z "$_packages" ]]; then
		_speed_debug_log "APP_INVENTORY_INSTALLED_PACKAGES_FAIL user=$_user fallback=off"
		return 1
	fi
	printf '%s\n' "$_packages" | grep -Ev 'ice.message|com.topjohnwu.magisk' | sort -u
}

_appinventory_pkg_exists_for_user() {
	local _pkg="$1" _target_user="${2:-${user:-${USER_ID:-0}}}" _old_user="${USER_ID:-}" _ok=1
	[[ -n $_pkg ]] || return 1
	if [[ -f "$TMPDIR/.installed_pkgs" ]] && awk -v p="$_pkg" '$0==p{found=1; exit} END{exit found?0:1}' "$TMPDIR/.installed_pkgs" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}; then
		return 0
	fi
	USER_ID="$_target_user"
	appinventory pkgName all 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} | awk -v p="$_pkg" '$0==p{found=1; exit} END{exit found?0:1}'
	_ok=$?
	USER_ID="$_old_user"
	return $_ok
}

_appinventory_pkg_uid_for_user() {
	local _pkg="$1" _target_user="${2:-${user:-${USER_ID:-0}}}" _old_user="${USER_ID:-}" _uid=""
	[[ -n $_pkg ]] || return 1
	if [[ -f "$TMPDIR/.pkg_uid" ]]; then
		_uid="$(_kv_file_get "$TMPDIR/.pkg_uid" "$_pkg" | tr -d ' \t\r\n')"
	fi
	if [[ -z $_uid ]]; then
		USER_ID="$_target_user"
		_uid="$(_app_inventory_pkg_uid_single_call "$_pkg" refresh 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null})" || _uid=""
		USER_ID="$_old_user"
		case $_uid in ''|*[!0-9]*) ;; *) _pkg_uid_map_set_one "$_pkg" "$_uid" || true ;; esac
	fi
	case $_uid in ''|*[!0-9]*) return 1 ;; esac
	printf '%s\n' "$_uid"
}
_appinventory_pkg_enabled_for_user() {
	local _pkg="$1" _target_user="${2:-${user:-${USER_ID:-0}}}" _old_user="${USER_ID:-}" _enabled="" _tmp
	[[ -n $_pkg ]] || return 1
	_tmp="$TMPDIR/.pkg_enabled_$$"
	USER_ID="$_target_user"
	appinventory pkgEnabledMap all 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} > "$_tmp"
	_enabled="$(_kv_file_get "$_tmp" "$_pkg" | tr -d ' \t\r\n')"
	USER_ID="$_old_user"
	rm -f "$_tmp" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	case $_enabled in true|1) return 0 ;; false|0) return 2 ;; *) return 1 ;; esac
}

# 從 app 安裝資訊取得 app 名稱 / apk 路徑 / 版本等資料
# 用 classes.dex 透過 hidden API 拿到完整 PackageInfo
get_name(){
	txt="$MODDIR/appList.txt"
	txt2="$MODDIR/mediaList.txt"
	if [[ $1 = Apkname ]]; then
		rm -rf "$txt" "$txt2"
		echoRgb "列出全部資料夾內應用名與自定義目錄壓縮包名稱" "3"
	fi
	rgb_a=118
	user="${SPEEDBACKUP_REGEN_USER:-$(echo "${0%}" | sed 's/.*\/Backup_zstd_\([0-9]*\).*/\1/')}"
	Apk_info="$(_installed_app_packages "$user")"
	[[ $Apk_info = "" ]] && echoRgb "Apk_info變量為空" "0" && exit
	starttime1="$(date -u "+%s")"
	i=1
	_apk_scan_list="$TMPDIR/.apk_scan_list"
	find "$MODDIR" -maxdepth 2 -name "apk.*" -type f 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} | sort > "$_apk_scan_list"
	while read -r; do
		Folder="${REPLY%/*}"
		[[ $rgb_a -ge 229 ]] && rgb_a=118
		unset PackageName NAME DUMPAPK ChineseName apk_version Ssaid dataSize userSize obbSize
		if [[ -f $Folder/app_details.json ]]; then
			ChineseName="$(_appdetails_get_first_entry_name "$Folder/app_details.json")"
			PackageName="$(_appdetails_get_first_pkg "$Folder/app_details.json")"
		fi
		if [[ $PackageName = "" || $ChineseName = "" ]]; then
			echoRgb "${Folder##*/}包名獲取失敗，解壓縮獲取包名中..." "0"
			cleanup_tmpdir_contents || exit 1
			local _probe_extract_raw_log _probe_extract_raw_start _probe_size
			_probe_size="$(_local_file_size_debug "$REPLY")"
			_probe_extract_raw_start="$(date +%s%3N 2>/dev/null)"; case $_probe_extract_raw_start in ''|*[!0-9]*) _probe_extract_raw_start="$(date +%s 2>/dev/null)000" ;; esac
			_probe_extract_raw_log="$(_local_raw_debug_begin extract "kind=apk_probe file=$REPLY dest=$TMPDIR ext=${REPLY##*.} size=$_probe_size")"
			case ${REPLY##*.} in
			zst) ( set -o pipefail 2>/dev/null; zstd -d < "$REPLY" 2>>"$_probe_extract_raw_log" | tar -xmpf - -C "$TMPDIR" --wildcards --no-anchored 'base.apk' 2>>"$_probe_extract_raw_log" ) ;;
			tar) tar -xmpf "$REPLY" -C "$TMPDIR" --wildcards --no-anchored 'base.apk' 2>>"$_probe_extract_raw_log" ;;
			*)
				echoRgb "${REPLY##*/} 壓縮包不支持解壓縮" "0"
				Set_back_1
				;;
			esac
			result=$?
			_local_raw_debug_end extract "$_probe_extract_raw_log" "$result" "$_probe_extract_raw_start" "kind=apk_probe dest=$TMPDIR"
			echo_log "${REPLY##*/}解壓縮"
			if [[ $result = 0 ]]; then
				if [[ -f $TMPDIR/base.apk ]]; then
					DUMPAPK="$(appinfo3 "$TMPDIR/base.apk")"
					if [[ $DUMPAPK != "" ]]; then
						# getPackageArchiveInfo 固定輸出「無空白標籤 套件名」；直接拆欄位，避免 shell array。
						ChineseName="${DUMPAPK%% *}"
						PackageName="${DUMPAPK#* }"
						PackageName="${PackageName%% *}"
						cleanup_tmpdir_contents || exit 1
					else
						echoRgb "appinfo輸出失敗" "0"
					fi
				fi
			fi
		fi
		if [[ $PackageName != "" && $ChineseName != "" ]]; then
			if [[ $(echo "$Apk_info" | awk -v pkg="$PackageName" '$1 == pkg {print $1}') = "" ]]; then
				echoRgb "$ChineseName已經不存在$user使用者中"
				if [[ $delete_app = "" ]]; then
					delete_app="$ChineseName $PackageName"
				else
					delete_app="$delete_app\n$ChineseName $PackageName"
				fi
			fi
			case $1 in
			Apkname)
				[[ -f $Folder/${PackageName}.sh ]] && rm -rf "$Folder/${PackageName}.sh"
				[[ ! -f $Folder/recover.sh ]] && touch_shell "3" "$Folder/recover.sh"
				[[ ! -f $Folder/backup.sh ]] && touch_shell "1" "$Folder/backup.sh"
				echoRgb "$i:$ChineseName $PackageName"
				if [[ $TMPTXT = "" ]]; then
					TMPTXT="#不需要恢復還原的應用請在開頭使用#注釋 比如：#酷安 com.coolapk.market\n$ChineseName $PackageName"
				else
					TMPTXT="$TMPTXT\n$ChineseName $PackageName"
				fi
				let i++ ;;
			convert)
				if [[ ${Folder##*/} = $PackageName ]]; then
					DIR_NAME="${Folder%/*}/$ChineseName"
					echoRgb "${Folder##*/} > $ChineseName"
				else
					DIR_NAME="${Folder%/*}/$PackageName"
					echoRgb "${Folder##*/} > $PackageName"
				fi
				if [[ -d $DIR_NAME ]]; then
					i=1
					NEW_DIR_NAME="${DIR_NAME}_${i}"
					while [[ -d $NEW_DIR_NAME ]]; do
						i=$((i + 1))
						NEW_DIR_NAME="${DIR_NAME}_${i}"
					done
					DIR_NAME="$NEW_DIR_NAME"
				fi
				mv "$Folder" "$DIR_NAME" ;;
			esac
		fi
		let rgb_a++
	done < "$_apk_scan_list"
	rm -f "$_apk_scan_list" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	[[ $TMPTXT != "" ]] && echo "$TMPTXT">"$txt"
	# 重新生成後一致性檢查: 比對資料夾與 appList.txt
	if [[ -f $txt ]]; then
		local _chk_folders="$TMPDIR/.chk_folders" _chk_listed="$TMPDIR/.chk_listed"
		for d in "$MODDIR"/*/; do
			d="${d%/}"; d="${d##*/}"
			case "$d" in wifi|Media|tools|log) continue ;; esac
			echo "$d"
		done | sort > "$_chk_folders"
		awk '!/^#|^＃/ && NF {print $1}' "$txt" | sort > "$_chk_listed"
		local _only_folder _only_list
		_only_folder="$(comm -23 "$_chk_folders" "$_chk_listed")"
		_only_list="$(comm -13 "$_chk_folders" "$_chk_listed")"
		if [[ -n $_only_folder || -n $_only_list ]]; then
			echoRgb "_______________________________________" "2"
			echoRgb "一致性檢查發現異常:" "0"
			[[ -n $_only_folder ]] && { echoRgb "有資料夾但不在清單:" "0"; echo "$_only_folder"; }
			[[ -n $_only_list ]] && { echoRgb "在清單但無資料夾:" "0"; echo "$_only_list"; }
		else
			echoRgb "一致性檢查通過: 資料夾與清單完全對應" "1"
		fi
		rm -f "$_chk_folders" "$_chk_listed" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	fi
	if [[ -d $MODDIR/Media ]]; then
		echoRgb "存在媒體資料夾" "2"
		[[ ! -f $txt2 ]] && echo "#不需要恢復的資料夾請在開頭使用#注釋 比如：#Download" > "$txt2"
		find "$MODDIR/Media" -maxdepth 1 -name "*.tar*" -type f 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} | while read -r; do
			echoRgb "${REPLY##*/}" && echo "${REPLY##*/}" >> "$txt2"
		done
		echoRgb "$txt2重新生成" "1"
	fi
	if [[ $delete_app != "" && ${SPEEDBACKUP_REGEN_SKIP_ORPHAN_CLEANUP:-0} != 1 ]]; then
		# r42: 恢復資料夾「重新生成應用列表」原本已有未安裝 App 清理。
		# 現在改接共用 orphan cleanup engine，避免與備份後清理維護兩套刪除/改 appList 邏輯。
		local _restore_orphan_hint="$TMPDIR/.orphan_restore_hint_$$" _or_name _or_pkg _or_i _or_n
		: > "$_restore_orphan_hint"
		_or_i=1
		_or_n="$(echo "$delete_app" | awk 'NF != 0 { count++ } END { print count }')"
		while [[ $_or_i -le $_or_n ]]; do
			_or_name="$(echo "$delete_app" | awk -v n=$_or_i 'NF{c++} c==n{print $1; exit}')"
			_or_pkg="$(echo "$delete_app" | awk -v n=$_or_i 'NF{c++} c==n{print $2; exit}')"
			[[ -n $_or_name && -n $_or_pkg ]] && printf '%s\t%s\t%s\n' "$_or_name" "$_or_pkg" "$MODDIR/$_or_name" >> "$_restore_orphan_hint"
			_or_i=$((_or_i+1))
		done
		_orphan_backup_cleanup_dir "$MODDIR" "$txt" "restore_list_regen" 1 "$_restore_orphan_hint"
		rm -f "$_restore_orphan_hint" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	fi
	if [[ $delete_app != "" && ${SPEEDBACKUP_REGEN_SKIP_ORPHAN_CLEANUP:-0} = 1 ]]; then
		_speed_debug_log "APPLIST_REGENERATE_ORPHAN_CLEANUP_SKIP context=download_local_rebuild entries=$(echo "$delete_app" | awk 'NF != 0 { count++ } END { print count+0 }')"
	fi
	chown "$(stat -c '%u:%g' '/data/media/0/Download')" "$txt"
	endtime 1
	[[ ${SPEEDBACKUP_REGEN_NO_EXIT:-0} = 1 ]] && return 0
	exit 0
}
# 低電量檢測 (依 low_battery_mode conf 設定決定行為; 留空則跳音量鍵詢問)
# ===== AppState 驗證與恢復 =====
self_test() {
	local _level _charging
	_charging="$(dumpsys deviceidle get charging)"
	_level="$(dumpsys battery | awk '/level/{print $2}' | grep -Eo '[0-9]+')"
	[[ $_charging = true || -z $_level || $_level -gt 15 ]] && return
	case $low_battery_mode in
	1)
		echoRgb "電量${_level}%太低且未充電\n -為防止備份檔案或是恢復因低電量強制關機導致檔案損毀\n -請連接充電器後備份" "0" && exit 2
		;;
	2)
		echoRgb "電量${_level}%太低且未充電 (low_battery_mode=2, 已忽略繼續執行)" "0"
		;;
	*)
		echoRgb "電量${_level}%太低且未充電\n -音量上: 無視風險繼續操作 / 音量下: 退出" "0"
		get_version "繼續" "退出"
		[[ $branch != true ]] && exit 2
		;;
	esac
}
# 驗證單一檔案的 sha256 校驗碼 (對照 tools 目錄內預存的雜湊)
Validation_file() {
	MODDIR_NAME="${1%/*}"
	MODDIR_NAME="${MODDIR_NAME##*/}"
	FILE_NAME="${1##*/}"
	local _raw_log _raw_start _fsize _rc
	_fsize="$(_local_file_size_debug "$1")"
	_raw_start="$(date +%s%3N 2>/dev/null)"; case $_raw_start in ''|*[!0-9]*) _raw_start="$(date +%s 2>/dev/null)000" ;; esac
	_raw_log="$(_local_raw_debug_begin checksum "file=$1 name=$FILE_NAME ext=${FILE_NAME##*.} size=$_fsize")"
	echoRgb "校驗$FILE_NAME"
	case ${FILE_NAME##*.} in
	zst)
		# r470: collect native zst file facts before authoritative zstd -t validation.
		if [[ -n ${SPEEDSCAN_BIN:-} && -x ${SPEEDSCAN_BIN:-} ]]; then
			_zstfacts="${TMPDIR:-/data/local/tmp}/.speedbackup_zst_file_facts_${$}_$RANDOM.tsv"
			if "$SPEEDSCAN_BIN" zst-file-facts "$1" > "$_zstfacts" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}; then
				[[ -d ${SPEED_DEBUG_RUN_DIR:-} ]] && cat "$_zstfacts" >> "$SPEED_DEBUG_RUN_DIR/native_zst_file_facts.tsv" 2>/dev/null || true
				_speed_debug_log "CHECK_ARCHIVE_NATIVE_ZST_FILE_FACTS_OK file=$(_speed_debug_kv "$1") backend=speedscan-zst-file-facts mode=r470"
			else
				_speed_debug_log "CHECK_ARCHIVE_NATIVE_ZST_FILE_FACTS_FAIL file=$(_speed_debug_kv "$1") backend=speedscan-zst-file-facts mode=r470 fallback=zstd_t"
			fi
			rm -f "$_zstfacts" 2>/dev/null
		fi
		# zstd -t 成功時會把「file.tar.zst: N bytes」寫到 stderr，這是正常資訊，不進全域 stderr.log，但會保存到 checksum raw。
		zstd -t "$1" 2>>"$_raw_log"
		_rc=$?
		[[ $_rc = 0 ]]
		;;
	tar) tar -tf "$1" > /dev/null 2>>"$_raw_log"; _rc=$?; [[ $_rc = 0 ]] ;;
	esac
	result=$?
	_local_raw_debug_end checksum "$_raw_log" "${_rc:-$result}" "$_raw_start" "result=$result"
	echo_log "${FILE_NAME##*.}校驗"
}
# 檢查壓縮檔完整性 (zstd -t / tar -t)
# 主選單「壓縮檔完整性檢查」呼叫
Check_archive() {
	starttime1="$(date -u "+%s")"
	error_log="$TMPDIR/error_log"
	rm -rf "$error_log"
	FIND_PATH_TMP="$TMPDIR/.check_archive_all_tar_${$}_$RANDOM.lst"
	_speedscan_tar_payloads "$1" "$FIND_PATH_TMP" 3 >/dev/null 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	FIND_PATH="$(cat "$FIND_PATH_TMP" 2>/dev/null)"
	rm -f "$FIND_PATH_TMP" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	i=1
	local _app_jsons
	_app_jsons="${TMPDIR:-/data/local/tmp}/.check_archive_appdetails_${$}_$RANDOM.lst"
	_appdetails_index_paths "$MODDIR" "$_app_jsons" 2 0 1 >/dev/null 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} || true
	r="$(grep -vc '^[[:space:]]*$' "$_app_jsons" 2>/dev/null)"; case $r in ''|*[!0-9]*) r=0 ;; esac
	while read -r REPLY; do
		[[ -n $REPLY ]] || continue
		REPLY="${REPLY%/*}"
		echoRgb "校驗第$i/$r個資料夾 剩下$((r - i))個" "3"
		echoRgb "校驗:${REPLY##*/}"
		_check_tar_payloads="$TMPDIR/.check_archive_tar_payloads_${$}_$RANDOM.lst"
		_speedscan_tar_payloads "$REPLY" "$_check_tar_payloads" 1 >/dev/null 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
		while read -r REPLY; do
			[[ -n $REPLY ]] || continue
			Validation_file "$REPLY"
			[[ $result != 0 ]] && echo "$REPLY">>"$error_log"
		done < "$_check_tar_payloads"
		rm -f "$_check_tar_payloads" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
		echoRgb "$(safe_percent "$i" "$r")% $(progress_bar $(safe_percent "$i" "$r"))"
		let i++ nskg++
	done < "$_app_jsons"
	rm -f "$_app_jsons" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	if [[ -n ${SPEEDSCAN_BIN:-} && -x ${SPEEDSCAN_BIN:-} && -d $MODDIR ]]; then
		_cksum_out="${TMPDIR:-/data/local/tmp}/.speedbackup_checksum_list_${$}_$RANDOM.tsv"
		if "$SPEEDSCAN_BIN" checksum-list "$MODDIR" "$_cksum_out" >/dev/null 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}; then
			[[ -d ${SPEED_DEBUG_RUN_DIR:-} ]] && cp -f "$_cksum_out" "$SPEED_DEBUG_RUN_DIR/native_checksum_list.tsv" 2>/dev/null || true
			_speed_debug_log "CHECK_ARCHIVE_NATIVE_CHECKSUM_LIST_OK root=$(_speed_debug_kv "$MODDIR") out=$_cksum_out backend=speedscan-checksum-list mode=r470"
		else
			_speed_debug_log "CHECK_ARCHIVE_NATIVE_CHECKSUM_LIST_FAIL root=$(_speed_debug_kv "$MODDIR") backend=speedscan-checksum-list mode=r470 fallback=zstd_tar"
		fi
		rm -f "$_cksum_out" 2>/dev/null
		_manifest_out="${TMPDIR:-/data/local/tmp}/.speedbackup_manifest_verify_manifest_${$}_$RANDOM.tsv"
		_verify_out="${TMPDIR:-/data/local/tmp}/.speedbackup_manifest_verify_${$}_$RANDOM.tsv"
		if _speedscan_manifest "$MODDIR" "$_manifest_out" && "$SPEEDSCAN_BIN" manifest-verify "$MODDIR" "$_manifest_out" > "$_verify_out" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}; then
			[[ -d ${SPEED_DEBUG_RUN_DIR:-} ]] && cp -f "$_verify_out" "$SPEED_DEBUG_RUN_DIR/native_manifest_verify.tsv" 2>/dev/null || true
			_speed_debug_log "CHECK_ARCHIVE_NATIVE_MANIFEST_VERIFY_OK root=$(_speed_debug_kv "$MODDIR") backend=speedscan-manifest-verify mode=r474"
		else
			_speed_debug_log "CHECK_ARCHIVE_NATIVE_MANIFEST_VERIFY_FAIL root=$(_speed_debug_kv "$MODDIR") backend=speedscan-manifest-verify mode=r474 optional=1"
		fi
		rm -f "$_manifest_out" "$_manifest_out.summary" "$_verify_out" 2>/dev/null
	fi
	endtime 1
	[[ -f $error_log ]] && echoRgb "以下為失敗的檔案\n $(cat "$error_log")" || echoRgb "恭喜~~全數校驗通過"
	rm -rf "$error_log"
}
# 產生 ASCII 進度條, 用法: progress_bar 42 → [████████░░░░░░░░░░░░]
progress_bar() {
	local pct="${1:-0}" width=20 filled i=0 bar=""
	[[ $pct -lt 0 ]] && pct=0
	[[ $pct -gt 100 ]] && pct=100
	filled=$((pct * width / 100))
	while [[ $i -lt $width ]]; do
		[[ $i -lt $filled ]] && bar="$bar█" || bar="$bar░"
		let i++
	done
	echo "[$bar]"
}

# r244: 對長耗時但原本只有一句「正在...」的階段輸出可見進度條，避免使用者以為卡住。
# r252: 改回腳本既有「批量預掃」型單行進度條，不再用 echoRgb 每次刷出新行。
# r253: AppState 批量恢復不再先輸出 begin 0/N，避免 chunk 0/N 造成雙進度列。
# r256: AppState 批量完成不再額外輸出第二條 100% 進度列；最後一個 chunk_done 已經是終端 100%。
# r258: 遠端已卸載掃描與 JSON 健全度檢查也走既有單行進度列，避免長時間無回饋或逐行刷屏。
# r290: 恢復完成後不再用 indeterminate 通知覆蓋 100% 完成狀態；AppState 結尾通知改無進度，避免通知欄殘留半截進度條。
_speedbackup_progress_label() {
	case "${1:-}" in
		appstate_batch_*) echo "AppState批量恢復" ;;
		remote_uninstalled_scan) echo "掃描遠端已卸載應用" ;;
		remote_json_health_download) echo "下載遠端JSON" ;;
		prepare_appstate_prescan) echo "預掃應用狀態" ;;
		prepare_dir_size_speedscan|prepare_dir_size_fallback) echo "預掃數據大小" ;;
		prepare_remote_bundle_map) echo "預掃遠端JSON bundle" ;;
		prepare_remote_fast_skip_map) echo "比對遠端變更" ;;
		webdav_prepare_app_dirs) echo "WebDAV預建App遠端目錄" ;;
		appdetails_bundle_preupload_json|remote_json_health_verify|stream_json_health_verify|nonstream_json_health_verify|post_json_health_verify|json_structure_check) echo "JSON健全度檢查" ;;
		process_observer_batch_stop) echo "批量喚醒守護" ;;
		restore_post_kill_before_thaw) echo "高風險App守護" ;;
		process_observer_stop_all) echo "解除程序守護" ;;
		uid_netblock_stop_all) echo "解除網路阻斷" ;;
		cgroup_freezer_stop_all) echo "解除cgroup守護" ;;
		*) echo "${2:-進度}" ;;
	esac
}

_speedbackup_progress_notify_should_send() {
	local _tag="$1" _cur="$2" _total="$3" _pct="$4" _file _last _min _safe _small
	case $_tag in
	prepare_appstate_prescan|prepare_dir_size_speedscan|prepare_dir_size_fallback|prepare_remote_fast_skip_map|webdav_prepare_app_dirs|appdetails_bundle_preupload_json|remote_json_health_verify|stream_json_health_verify|nonstream_json_health_verify|post_json_health_verify|json_structure_check) ;;
	*) return 0 ;;
	esac
	[[ $_cur -le 0 || $_cur -ge $_total ]] && return 0
	# r283: 預掃/JSON 小批量通常很快，終端仍單行刷新，但通知只發起點與終點，避免 RootDaemon notifyBatch 變成瓶頸。
	_small="${SPEEDBACKUP_PROGRESS_NOTIFY_SMALL_TOTAL:-20}"
	case $_small in ''|*[!0-9]*) _small=20 ;; esac
	if [[ $_total -le $_small ]]; then
		return 1
	fi
	_min="${SPEEDBACKUP_PROGRESS_NOTIFY_MIN_PCT:-10}"
	case $_min in ''|*[!0-9]*) _min=10 ;; esac
	_safe="$(printf '%s\n' "$_tag" | tr -c 'A-Za-z0-9_' '_')"
	_file="${TMPDIR:-/data/local/tmp}/.progress_notify_pct_${_safe}"
	_last="$(cat "$_file" 2>/dev/null)"
	case $_last in ''|*[!0-9]*) _last=0 ;; esac
	if [[ $((_pct - _last)) -ge $_min ]]; then
		printf '%s\n' "$_pct" > "$_file" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} || true
		return 0
	fi
	return 1
}

# 用法: _speedbackup_progress_step <current> <total> <message> <debug_tag> [notify_tag]
_speedbackup_progress_step() {
	local _cur="$1" _total="$2" _msg="$3" _tag="${4:-progress_step}" _notify="${5:-}" _pct _label
	case $_cur in ''|*[!0-9]*) _cur=0 ;; esac
	case $_total in ''|*[!0-9]*) _total=0 ;; esac
	[[ $_total -le 0 ]] && { _speedbackup_progress_hint "$_msg" "$_tag"; return 0; }
	[[ $_cur -lt 0 ]] && _cur=0
	[[ $_cur -gt $_total ]] && _cur="$_total"
	_pct="$(safe_percent "$_cur" "$_total")"
	_label="$(_speedbackup_progress_label "$_tag" "$_msg")"
	# r458: 保留 r453/r456 原格式與 label，不做 compact；redraw 只寫 /dev/tty，避免進 stderr.log。
	if _speedbackup_progress_term_printf '\r\033[K -%s %d/%d %s' "$_label" "$_cur" "$_total" "$(progress_bar "$_pct")"; then
		if [[ $_cur -ge $_total ]]; then
			_speedbackup_progress_term_printf '\033[K\n' || true
			_SPEEDBACKUP_PROGRESS_LINE_ACTIVE=0
		else
			_SPEEDBACKUP_PROGRESS_LINE_ACTIVE=1
		fi
	else
		_SPEEDBACKUP_PROGRESS_LINE_ACTIVE=0
	fi
	_speed_debug_log "PROGRESS_STEP tag=$_tag current=$_cur total=$_total pct=$_pct msg=$_msg label=$_label mode=singleline-clear-r459 notify=throttle-r286"
	if [[ -n $_notify ]]; then
		if _speedbackup_progress_notify_should_send "$_tag" "$_cur" "$_total" "$_pct"; then
			notification_progress "$_notify" "$_total" "$_cur" "$_label $_cur/$_total ${_pct}%"
			_speed_debug_log "PROGRESS_NOTIFY_SENT tag=$_tag current=$_cur total=$_total pct=$_pct notify=$_notify mode=throttle-r286"
		else
			_speed_debug_log "PROGRESS_NOTIFY_SKIP tag=$_tag current=$_cur total=$_total pct=$_pct notify=$_notify mode=throttle-r286 reason=small-or-pct-throttle"
		fi
	fi
	return 0
}

# 用法: _speedbackup_busy_step <message> <debug_tag> [notify_tag]
_speedbackup_busy_step() {
	local _msg="$1" _tag="${2:-busy_step}" _notify="${3:-}"
	[[ -n $_msg ]] || return 0
	echoRgb "$_msg" "3"
	_speed_debug_log "BUSY_STEP tag=$_tag msg=$_msg"
	[[ -n $_notify ]] && notification_indeterminate "$_notify" "$_msg"
	return 0
}

# r292: 恢復主通知改回「逐 App 計數」固定進度，與備份一致。
# 例如 10 個 App：第 1 個顯示 1/10 10%，第 2 個顯示 2/10 20%。
# 內部安裝/解壓/AppState 階段只記 debug，不推通知，避免恢復看起來像動態細分進度。
_restore_notify_fixed_progress() {
	local _idx="$1" _total="$2" _sub="$3" _msg="$4" _pct _file _last
	case $_total in ''|*[!0-9]*|0) _total=1 ;; esac
	case $_idx in ''|*[!0-9]*) _idx=1 ;; esac
	case $_sub in ''|*[!0-9]*) _sub=0 ;; esac
	[[ $_idx -lt 1 ]] && _idx=1
	[[ $_idx -gt $_total ]] && _idx="$_total"
	_pct="$(safe_percent "$_idx" "$_total")"
	# 只在每個 App 開始時送一次通知；同一 App 內部階段不更新通知。
	if [[ $_sub -eq 0 ]]; then
		_file="${TMPDIR:-/data/local/tmp}/.restore_appcount_notify_idx"
		_last="$(cat "$_file" 2>/dev/null)"
		if [[ $_last != "$_idx/$_total" ]]; then
			printf '%s\n' "$_idx/$_total" > "$_file" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} || true
			notification_progress "105" "$_total" "$_idx" "恢復進度 $_idx/$_total ${_pct}%"
			_speed_debug_log "RESTORE_APPCOUNT_NOTIFY tag=105 idx=$_idx total=$_total sub=$_sub current=$_idx max=$_total pct=$_pct mode=restore-appcount-r292 msg=$_msg"
		else
			_speed_debug_log "RESTORE_APPCOUNT_NOTIFY_SKIP tag=105 idx=$_idx total=$_total sub=$_sub pct=$_pct mode=restore-appcount-r292 reason=duplicate_app msg=$_msg"
		fi
	else
		case ${SPEEDBACKUP_RESTORE_INNER_PROGRESS_VERBOSE:-0}:$_sub in
		1:*) _speed_debug_log "RESTORE_APPCOUNT_NOTIFY_SKIP tag=105 idx=$_idx total=$_total sub=$_sub pct=$_pct mode=restore-appcount-r379 reason=inner_stage_verbose msg=$_msg" ;;
		*:25|*:50|*:90) _speed_debug_log "RESTORE_APPCOUNT_NOTIFY_SKIP tag=105 idx=$_idx total=$_total sub=$_sub pct=$_pct mode=restore-appcount-r379 reason=inner_stage_throttled_keep msg=$_msg" ;;
		*) : ;;
		esac
	fi
	return 0
}

# r247: 不用固定秒數刷新進度；長耗時等待只掛接既有 A/B 進度與通知。
# 原本 r246 的 heartbeat 會每 10 秒重刷同一條百分比，體感像假進度。
# 這裡只在開始/完成各記一次，實際檔名輸出仍交給既有 tar checkpoint，外層 A/B 進度維持原腳本邏輯。
_speedbackup_wait_pid_busy() {
	local _pid="$1" _msg="$2" _tag="${3:-wait_pid_busy}" _notify="${4:-}" _interval="${5:-10}" _rc _pct
	case $_pid in ''|*[!0-9]*) return 2 ;; esac
	if [[ -n $_notify ]]; then
		case ${A:-} in ''|*[!0-9]*) notification_indeterminate "$_notify" "$_msg" ;; *)
			case ${B:-} in ''|*[!0-9]*|0) notification_indeterminate "$_notify" "$_msg" ;; *)
				_pct="$(safe_percent "$((A - 1))" "$B")"
				notification_progress "$_notify" "$B" "$((A - 1))" "$_msg $((A - 1))/$B ${_pct}%"
				;;
			esac
			;;
		esac
	fi
	_speed_debug_log "BUSY_STEP tag=$_tag pid=$_pid mode=existing_progress_no_fixed_refresh msg=$_msg"
	wait "$_pid"
	_rc=$?
	_speed_debug_log "BUSY_STEP_DONE tag=$_tag pid=$_pid rc=$_rc mode=existing_progress_no_fixed_refresh msg=$_msg"
	return "$_rc"
}

_remote_stream_wait_pid_poll_abortable() {
	local _pid="$1" _msg="$2" _tag="${3:-remote_stream_child}" _interval="${4:-1}" _rc _state
	case $_pid in ''|*[!0-9]*) return 2 ;; esac
	case $_interval in ''|*[!0-9]*|0) _interval=1 ;; esac
	_speed_debug_log "BUSY_STEP tag=$_tag pid=$_pid mode=remote_fastfail_poll msg=$_msg"
	while kill -0 "$_pid" 2>/dev/null; do
		_state="$(awk '{print $3; exit}' "/proc/$_pid/stat" 2>/dev/null)"
		[[ $_state = Z ]] && break
		if _remote_stream_fatal_active; then
			_speed_debug_log "REMOTE_STREAM_CHILD_ABORT tag=$_tag pid=$_pid app=${name1:-} fatal=1 mode=r416 policy=fast-fail waitMode=poll"
			_event_terminate_pid "$_pid" "${_tag}_remote_fastfail_abort" >/dev/null 2>&1 || kill -KILL "$_pid" 2>/dev/null || true
			wait "$_pid" 2>/dev/null || true
			_speed_debug_log "BUSY_STEP_DONE tag=$_tag pid=$_pid rc=126 mode=remote_fastfail_poll reason=remote_stream_fatal msg=$_msg"
			return 126
		fi
		sleep "$_interval"
	done
	wait "$_pid"
	_rc=$?
	_speed_debug_log "BUSY_STEP_DONE tag=$_tag pid=$_pid rc=$_rc mode=remote_fastfail_poll msg=$_msg"
	return "$_rc"
}

_remote_stream_child_abort_watchdog() {
	local _pid="$1" _tag="${2:-remote_stream_child}" _interval="${3:-1}" _msg="${4:-}" _state
	case $_pid in ''|*[!0-9]*) return 2 ;; esac
	case $_interval in ''|*[!0-9]*|0) _interval=1 ;; esac
	while kill -0 "$_pid" 2>/dev/null; do
		_state="$(awk '{print $3; exit}' "/proc/$_pid/stat" 2>/dev/null)"
		[[ $_state = Z ]] && return 0
		if _remote_stream_fatal_active; then
			_speed_debug_log "REMOTE_STREAM_CHILD_ABORT tag=$_tag pid=$_pid app=${name1:-} fatal=1 mode=r416 policy=fast-fail waitMode=watchdog"
			_event_terminate_pid "$_pid" "${_tag}_remote_fastfail_abort" >/dev/null 2>&1 || kill -KILL "$_pid" 2>/dev/null || true
			return 126
		fi
		sleep "$_interval"
	done
	return 0
}

_remote_stream_wait_pid_busy_abortable() {
	local _pid="$1" _msg="$2" _tag="${3:-remote_stream_child}" _notify="${4:-}" _interval="${5:-1}" _fifo="${6:-}" _rc _pct _watchdog_pid _watchdog_rc _wait_mode _event_line _event_type _event_rc _event_reason _read_rc
	case $_pid in ''|*[!0-9]*) return 2 ;; esac
	case $_interval in ''|*[!0-9]*|0) _interval=1 ;; esac
	if [[ -n $_notify ]]; then
		case ${A:-} in ''|*[!0-9]*) notification_indeterminate "$_notify" "$_msg" ;; *)
			case ${B:-} in ''|*[!0-9]*|0) notification_indeterminate "$_notify" "$_msg" ;; *)
				_pct="$(safe_percent "$((A - 1))" "$B")"
				notification_progress "$_notify" "$B" "$((A - 1))" "$_msg $((A - 1))/$B ${_pct}%"
				;;
			esac
			;;
		esac
	fi
	_wait_mode="${SPEEDBACKUP_REMOTE_STREAM_WAIT_MODE:-event}"
	case $_wait_mode in poll|legacy|loop)
		_remote_stream_wait_pid_poll_abortable "$_pid" "$_msg" "$_tag" "$_interval"
		return $?
		;;
	esac
	if _remote_stream_fatal_active; then
		_speed_debug_log "REMOTE_STREAM_CHILD_ABORT tag=$_tag pid=$_pid app=${name1:-} fatal=1 mode=r416 policy=fast-fail waitMode=$_wait_mode precheck=1"
		_event_terminate_pid "$_pid" "${_tag}_remote_fastfail_abort" >/dev/null 2>&1 || kill -KILL "$_pid" 2>/dev/null || true
		wait "$_pid" 2>/dev/null || true
		[[ -n $_fifo ]] && rm -f "$_fifo" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
		_speed_debug_log "BUSY_STEP_DONE tag=$_tag pid=$_pid rc=126 mode=remote_fastfail_abort_event reason=remote_stream_fatal_precheck msg=$_msg"
		return 126
	fi
	if [[ $_wait_mode = event && -n $_fifo && -p $_fifo ]]; then
		local _event_retry=0 _event_err_log="${SPEED_DEBUG_ERR_LOG:-/dev/null}" _eventwait_out="" _eventwait_rc=125
		_speed_debug_log "BUSY_STEP tag=$_tag pid=$_pid mode=remote_fastfail_abort_event waitMode=event fifo=$_fifo msg=$_msg"
		if [[ -x ${EVENT_EVENTWAIT_BIN:-} ]]; then
			_speedbackup_tool_verify_once eventwait 0 >/dev/null 2>&1 || true
			_eventwait_out="$TMPDIR/.eventwait_${$}_$RANDOM.out"
			"$EVENT_EVENTWAIT_BIN" "$_fifo" "$_pid" "$(_remote_stream_fatal_file)" "${SPEEDBACKUP_REMOTE_STREAM_EVENTWAIT_TIMEOUT_MS:-0}" "$_tag" > "$_eventwait_out" 2>>"$_event_err_log"
			_eventwait_rc=$?
			_event_line="$(head -n 1 "$_eventwait_out" 2>/dev/null)"
			rm -f "$_eventwait_out" 2>>"$_event_err_log"
			if [[ -n $_event_line ]]; then
				_speed_debug_log "REMOTE_STREAM_EVENTWAIT_RESULT tag=$_tag pid=$_pid rc=$_eventwait_rc event=$(_restore_stream_perf_field "$_event_line") mode=r416"
				_event_type="$(printf '%s\n' "$_event_line" | awk -F '\t' '{print $1}')"
				_event_rc="$(printf '%s\n' "$_event_line" | awk -F '\t' '{print $2}')"
				_event_reason="$(printf '%s\n' "$_event_line" | awk -F '\t' '{print $4}')"
				[[ $_event_type != timeout ]] && rm -f "$_fifo" 2>>"$_event_err_log"
				case $_event_type in
				fatal)
					_speed_debug_log "REMOTE_STREAM_CHILD_ABORT tag=$_tag pid=$_pid app=${name1:-} fatal=1 eventRc=${_event_rc:-126} reason=${_event_reason:-} mode=r416 policy=fast-fail waitMode=eventwait"
					_event_terminate_pid "$_pid" "${_tag}_remote_fastfail_abort" >/dev/null 2>&1 || kill -KILL "$_pid" 2>/dev/null || true
					wait "$_pid" 2>/dev/null || true
					_speed_debug_log "BUSY_STEP_DONE tag=$_tag pid=$_pid rc=126 mode=remote_fastfail_abort_eventwait reason=remote_stream_fatal_event msg=$_msg"
					return 126
					;;
				timeout)
					_speed_debug_log "REMOTE_STREAM_EVENTWAIT_TIMEOUT_FALLBACK tag=$_tag pid=$_pid reason=${_event_reason:-timeout} mode=r416"
					;;
				done)
					wait "$_pid"; _rc=$?
					case $_event_rc in ''|*[!0-9]*) : ;; *) [[ $_event_type = done ]] && _rc="$_event_rc" ;; esac
					if [[ $_rc != 0 ]] && _remote_stream_fatal_active; then
						_speed_debug_log "BUSY_STEP_DONE tag=$_tag pid=$_pid rc=126 childRc=$_rc mode=remote_fastfail_abort_eventwait reason=remote_stream_fatal_after_done msg=$_msg"
						return 126
					fi
					_speed_debug_log "BUSY_STEP_DONE tag=$_tag pid=$_pid rc=$_rc mode=remote_fastfail_abort_eventwait waitMode=eventwait msg=$_msg"
					return "$_rc"
					;;
				esac
			fi
			_speed_debug_log "REMOTE_STREAM_EVENTWAIT_FALLBACK tag=$_tag pid=$_pid rc=$_eventwait_rc reason=no_event_line mode=r416"
		fi
		while :; do
			# mksh may interrupt the FIFO open/read when the worker exits (SIGCHLD/EINTR).
			# Keep this error out of the terminal and retry while the worker is still alive.
			IFS= read -r _event_line 2>>"$_event_err_log" < "$_fifo"; _read_rc=$?
			[[ $_read_rc = 0 ]] && break
			_event_retry=$((_event_retry + 1))
			if ! kill -0 "$_pid" 2>/dev/null || [[ $_event_retry -ge 8 ]]; then
				wait "$_pid"; _rc=$?
				rm -f "$_fifo" 2>>"$_event_err_log"
				_speed_debug_log "BUSY_STEP_DONE tag=$_tag pid=$_pid rc=$_rc mode=remote_fastfail_abort_event waitMode=event reason=fifo_read_failed readRc=$_read_rc retries=$_event_retry msg=$_msg"
				return "$_rc"
			fi
			_speed_debug_log "REMOTE_STREAM_EVENT_READ_RETRY tag=$_tag pid=$_pid readRc=$_read_rc retry=$_event_retry mode=r416 reason=fifo_read_interrupted"
		done
		rm -f "$_fifo" 2>>"$_event_err_log"
		_event_type="$(printf '%s\n' "$_event_line" | awk -F '\t' '{print $1}')"
		_event_rc="$(printf '%s\n' "$_event_line" | awk -F '\t' '{print $2}')"
		_event_reason="$(printf '%s\n' "$_event_line" | awk -F '\t' '{print $4}')"
		case $_event_type in
		fatal)
			_speed_debug_log "REMOTE_STREAM_CHILD_ABORT tag=$_tag pid=$_pid app=${name1:-} fatal=1 eventRc=${_event_rc:-126} reason=${_event_reason:-} mode=r416 policy=fast-fail waitMode=event"
			_event_terminate_pid "$_pid" "${_tag}_remote_fastfail_abort" >/dev/null 2>&1 || kill -KILL "$_pid" 2>/dev/null || true
			wait "$_pid" 2>/dev/null || true
			_speed_debug_log "BUSY_STEP_DONE tag=$_tag pid=$_pid rc=126 mode=remote_fastfail_abort_event reason=remote_stream_fatal_event msg=$_msg"
			return 126
			;;
		done)
			wait "$_pid"; _rc=$?
			case $_event_rc in ''|*[!0-9]*) : ;; *) _rc="$_event_rc" ;; esac
			if [[ $_rc != 0 ]] && _remote_stream_fatal_active; then
				_speed_debug_log "BUSY_STEP_DONE tag=$_tag pid=$_pid rc=126 childRc=$_rc mode=remote_fastfail_abort_event reason=remote_stream_fatal_after_done msg=$_msg"
				return 126
			fi
			_speed_debug_log "BUSY_STEP_DONE tag=$_tag pid=$_pid rc=$_rc mode=remote_fastfail_abort_event waitMode=event msg=$_msg"
			return "$_rc"
			;;
		*)
			wait "$_pid"; _rc=$?
			_speed_debug_log "BUSY_STEP_DONE tag=$_tag pid=$_pid rc=$_rc mode=remote_fastfail_abort_event waitMode=event reason=unknown_event event=$(_restore_stream_perf_field "$_event_line") msg=$_msg"
			return "$_rc"
			;;
		esac
	fi
	# r459: no-fifo path 優先使用 pipeline-watch，監控 root pid + descendants、fatal sidecar 與可用進度檔 idle。
	local _pipe_rc _pipe_line _fatal_file _progress_file _idle_ms
	_fatal_file="$(_remote_stream_fatal_file)"
	_progress_file="$(_speedbackup_stream_pipeline_progress_file 2>/dev/null || echo -)"
	_idle_ms="$(_speedbackup_stream_pipeline_idle_ms "$_progress_file")"
	_speed_debug_log "BUSY_STEP tag=$_tag pid=$_pid mode=remote_pipeline_watch waitMode=eventwait reason=no_event_fifo fatal=$_fatal_file progress=$_progress_file idleMs=$_idle_ms msg=$_msg"
	_eventwait_pipeline_watch_single_pid_ms "$_pid" "$_fatal_file" "$_progress_file" "$_idle_ms" "${SPEEDBACKUP_REMOTE_STREAM_EVENTWAIT_TIMEOUT_MS:-0}" "$_tag" >/dev/null 2>&1
	_pipe_rc=$?
	_pipe_line="${_EVENTWAIT_LAST_LINE:-}"
	case $_pipe_rc in
	0)
		wait "$_pid"; _rc=$?
		if [[ $_rc != 0 ]] && _remote_stream_fatal_active; then
			_speed_debug_log "BUSY_STEP_DONE tag=$_tag pid=$_pid rc=126 childRc=$_rc mode=remote_pipeline_watch reason=remote_stream_fatal_after_done event=$(_restore_stream_perf_field "$_pipe_line") msg=$_msg"
			return 126
		fi
		_speed_debug_log "BUSY_STEP_DONE tag=$_tag pid=$_pid rc=$_rc mode=remote_pipeline_watch waitMode=eventwait event=$(_restore_stream_perf_field "$_pipe_line") msg=$_msg"
		return "$_rc"
		;;
	126)
		_speed_debug_log "REMOTE_STREAM_CHILD_ABORT tag=$_tag pid=$_pid app=${name1:-} fatal=1 mode=r459 policy=fast-fail waitMode=eventwait-pipeline-watch"
		_event_terminate_pid "$_pid" "${_tag}_remote_fastfail_abort" >/dev/null 2>&1 || kill -KILL "$_pid" 2>/dev/null || true
		wait "$_pid" 2>/dev/null || true
		_speed_debug_log "BUSY_STEP_DONE tag=$_tag pid=$_pid rc=126 mode=remote_pipeline_watch reason=remote_stream_fatal_event event=$(_restore_stream_perf_field "$_pipe_line") msg=$_msg"
		return 126
		;;
	125)
		_speed_debug_log "REMOTE_STREAM_CHILD_ABORT tag=$_tag pid=$_pid app=${name1:-} fatal=1 mode=r459 policy=pipeline-idle waitMode=eventwait-pipeline-watch progress=$_progress_file idleMs=$_idle_ms"
		_remote_stream_mark_fatal "${_tag:-remote_stream_pipeline}" 125 0 "stream pipeline progress idle" >/dev/null 2>&1 || true
		_event_terminate_pid "$_pid" "${_tag}_pipeline_idle_abort" >/dev/null 2>&1 || kill -KILL "$_pid" 2>/dev/null || true
		wait "$_pid" 2>/dev/null || true
		_speed_debug_log "BUSY_STEP_DONE tag=$_tag pid=$_pid rc=126 mode=remote_pipeline_watch reason=progress_idle event=$(_restore_stream_perf_field "$_pipe_line") msg=$_msg"
		return 126
		;;
	124)
		_speed_debug_log "REMOTE_STREAM_EVENTWAIT_PIPELINE_TIMEOUT_FALLBACK tag=$_tag pid=$_pid mode=r459 reason=timeout"
		;;
	*)
		_speed_debug_log "REMOTE_STREAM_EVENTWAIT_PIPELINE_FALLBACK tag=$_tag pid=$_pid rc=$_pipe_rc mode=r459 reason=eventwait_unavailable_or_error"
		# r453 fallback: pipeline-watch 不可用時退回 pid-or-file。
		local _pof_rc _pof_line
		_eventwait_pid_or_file_ms "$_pid" "$_fatal_file" "${SPEEDBACKUP_REMOTE_STREAM_EVENTWAIT_TIMEOUT_MS:-0}" "$_tag" >/dev/null 2>&1
		_pof_rc=$?; _pof_line="${_EVENTWAIT_LAST_LINE:-}"
		case $_pof_rc in
		0) wait "$_pid"; _rc=$?; _speed_debug_log "BUSY_STEP_DONE tag=$_tag pid=$_pid rc=$_rc mode=remote_fastfail_pid_or_file waitMode=eventwait event=$(_restore_stream_perf_field "$_pof_line") msg=$_msg"; return "$_rc" ;;
		126) _event_terminate_pid "$_pid" "${_tag}_remote_fastfail_abort" >/dev/null 2>&1 || kill -KILL "$_pid" 2>/dev/null || true; wait "$_pid" 2>/dev/null || true; return 126 ;;
		esac
		;;
	esac
	_remote_stream_child_abort_watchdog "$_pid" "$_tag" "$_interval" "$_msg" &
	_watchdog_pid=$!
	_speed_debug_log "BUSY_STEP tag=$_tag pid=$_pid mode=remote_fastfail_abort_watchdog waitMode=watchdog intervalSec=$_interval reason=eventwait_pid_or_file_fallback msg=$_msg"
	wait "$_pid"
	_rc=$?
	if [[ -n $_watchdog_pid ]]; then
		kill "$_watchdog_pid" 2>/dev/null || true
		wait "$_watchdog_pid" 2>/dev/null; _watchdog_rc=$?
	fi
	if [[ $_rc != 0 ]] && _remote_stream_fatal_active; then
		_speed_debug_log "BUSY_STEP_DONE tag=$_tag pid=$_pid rc=126 childRc=$_rc watchdogRc=${_watchdog_rc:-na} mode=remote_fastfail_abort_watchdog reason=remote_stream_fatal msg=$_msg"
		return 126
	fi
	_speed_debug_log "BUSY_STEP_DONE tag=$_tag pid=$_pid rc=$_rc watchdogRc=${_watchdog_rc:-na} mode=remote_fastfail_abort_watchdog waitMode=watchdog msg=$_msg"
	return "$_rc"
}

# 把過去時間字串 (YYYY.MM.DD HH:MM:SS 或 YYYY-MM-DD HH:MM:SS) 轉成「幾天幾小時幾分前」。
time_ago() {
	local ts="$1" norm past now diff
	[[ -z $ts || $ts = null ]] && { echo "$ts"; return; }
	norm="$(echo "$ts" | sed 's/\./-/g')"
	past="$(date -d "$norm" +%s 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null})"
	now="$(date +%s 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null})"
	[[ -z $past || -z $now ]] && { echo "$ts"; return; }
	diff=$((now - past))
	[[ $diff -lt 0 ]] && { echo "$ts"; return; }
	if [[ $diff -lt 60 ]]; then
		echo "${diff}秒前"
	elif [[ $diff -lt 3600 ]]; then
		echo "$((diff / 60))分鐘前"
	elif [[ $diff -lt 86400 ]]; then
		local h=$((diff / 3600)) m=$(((diff % 3600) / 60))
		[[ $m = 0 ]] && echo "${h}小時前" || echo "${h}小時${m}分前"
	else
		local d=$((diff / 86400)) h=$(((diff % 86400) / 3600)) m=$(((diff % 3600) / 60))
		echo "${d}天${h}小時${m}分前"
	fi
}

_display_power_volume_state_file() {
	printf '%s\n' "${TMPDIR:-/data/local/tmp}/.speedbackup_display_volume_watcher"
}

_display_power_volume_pid_file() {
	printf '%s\n' "${TMPDIR:-/data/local/tmp}/.speedbackup_display_volume_watcher.pid"
}

_display_power_volume_err_file() {
	printf '%s\n' "${TMPDIR:-/data/local/tmp}/.speedbackup_display_volume_watcher.stderr"
}

_display_power_volume_script_file() {
	printf '%s\n' "${TMPDIR:-/data/local/tmp}/.speedbackup_display_volume_watcher_exec.sh"
}

_display_power_volume_output_file() {
	printf '%s\n' "${TMPDIR:-/data/local/tmp}/.speedbackup_display_volume_keycheck.out"
}

_display_power_volume_hint_file() {
	printf '%s\n' "${TMPDIR:-/data/local/tmp}/.speedbackup_display_volume_hint_shown"
}

_display_power_fake_dark_mode() {
	# r192: 備份/恢復期間只用音量鍵控制；watcher stderr 改獨立暫存並只濾除預期 SIGTERM 的 Terminated。
	printf '%s\n' "${SPEEDBACKUP_FAKE_DARK_DISPLAY_MODE:-0}"
}

_display_power_volume_hint_show() {
	[[ ${setDisplayPowerMode:-} = true ]] || return 0
	local _em
	# r196: 提示以每次 display on/off session 為範圍，不再依賴跨執行殘留的固定 marker 檔。
	# 因此備份與恢復每次進入黑屏前各顯示一次；同一 session 內重複 on 仍不重複。
	[[ ${_DISPLAY_POWER_VOLUME_HINT_SHOWN:-0} = 1 ]] && return 0
	_DISPLAY_POWER_VOLUME_HINT_SHOWN=1
	rm -f "$(_display_power_volume_hint_file)" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} || true
	if _keycheck_path >/dev/null 2>&1; then _em=1; else _em=0; fi
	_speed_debug_log "DISPLAY_VOLUME_HINT show=true scope=display-session restoreGuaranteed=1 nativeKeycheck=$_em mode=volume_keys_only volumeUp=setDisplay2 volumeDown=setDisplay0 fakeDarkMode=$(_display_power_fake_dark_mode) keycheckRuntime=legacy_stdout_volume_only"
	echoRgb "即將進入備份/恢復期間螢幕關閉邏輯（mode=0）。" "2"
	echoRgb "喚醒螢幕：短按音量上 = setDisplay 2。" "1"
	echoRgb "再次關閉螢幕：短按音量下 = setDisplay 0。" "2"
	echoRgb "不要按電源鍵：電源鍵會變成真正鎖屏，可能干擾備份/恢復。" "0"
	sleep 3
}

_display_power_volume_watcher_script_write() {
	# r198: 產生完全獨立的 watcher executable。
	# 不 source tools.sh、不繼承主 shell EXIT trap；keycheck 是 watcher 的直接 child，
	# stop 時只終止 keycheck，watcher 取得 rc=143 後因 state 已移除而正常 exit 0。
	local _script="$1"
	[[ -n $_script ]] || return 1
	cat > "$_script" <<'SPEEDBACKUP_VOLUME_WATCHER_EOF'
#!/system/bin/sh
state="$1"
keycheck="$2"
display_mode="$3"
classpath="$4"
app_process="$5"
app_process_base="$6"
main_log="$7"
key_out="$8"

watch_log() {
	[ -n "$main_log" ] && [ "$main_log" != /dev/null ] || return 0
	printf '[%s] %s\n' "$(date '+%H:%M:%S' 2>/dev/null)" "$*" >> "$main_log" 2>/dev/null || true
}

set_display() {
	CLASSPATH="$classpath" "$app_process" "$app_process_base" \
		com.xayah.dex.HiddenApiUtil setDisplayPowerMode "$1" >/dev/null 2>&1
}

normalize_stdout_code() {
	token="$(head -n 1 "$key_out" 2>/dev/null | tr -d '\r' | tr '[:upper:]' '[:lower:]' | sed 's/^[[:space:]]*//; s/[[:space:]]*$//')"
	case "$token" in
	long_vol+|long_volume_up|long-volume-up|long_vol_up|long-vol-up|vol+|volume+|volume_up|volume-up|volumeup|vol_up|vol-up|volup|key_volumeup|key_volume_up|keycode_volume_up|115|24|*volume*up*|*vol*up*) printf '%s\n' 42 ;;
	long_vol-|long_volume_down|long-volume-down|long_vol_down|long-vol-down|vol-|volume-|volume_down|volume-down|volumedown|vol_down|vol-down|voldown|key_volumedown|key_volume_down|keycode_volume_down|114|25|*volume*down*|*vol*down*) printf '%s\n' 41 ;;
	none|timeout|"") printf '%s\n' 0 ;;
	*) printf '%s\n' 0 ;;
	esac
}

trap 'exit 0' TERM INT HUP
watch_log "DISPLAY_VOLUME_WATCH_START setDisplayPowerMode=true keycheckMode=volume_keys_only displayMode=$display_mode volumeUp=setDisplay2 volumeDown=setDisplay0 keycheckRuntime=legacy_stdout_volume_only watcherExecIsolated=1 keycheckDirectChild=1 commandSubstitution=0"

while [ -f "$state" ]; do
	rm -f "$key_out" 2>/dev/null
	if "$keycheck" > "$key_out" 2>/dev/null; then
		key_rc=0
	else
		key_rc=$?
	fi

	# stop 先移除 state 再 TERM keycheck；因此這裡直接正常離開，不把 143 當事件。
	[ -f "$state" ] || break

	if [ -s "$key_out" ]; then
		code="$(normalize_stdout_code)"
	else
		case "$key_rc" in
		42|46|56) code=42 ;;
		41|47|57) code=41 ;;
		*) code=0 ;;
		esac
	fi

	case "$code" in
	42)
		set_display 2 || true
		watch_log "DISPLAY_VOLUME_EVENT action=screen_on input=vol+ rc=42 displayMode=2 reason=volume_up"
		;;
	41)
		set_display "$display_mode" || true
		watch_log "DISPLAY_VOLUME_EVENT action=display_off input=vol- rc=41 displayMode=$display_mode reason=volume_down"
		;;
	esac
done

rm -f "$key_out" 2>/dev/null
watch_log "DISPLAY_VOLUME_WATCH_STOP reason=state_removed exit=0 watcherExecIsolated=1 keycheckDirectChild=1"
exit 0
SPEEDBACKUP_VOLUME_WATCHER_EOF
	chmod 0700 "$_script" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} || return 1
	return 0
}

_display_power_volume_watcher_start() {
	[[ $setDisplayPowerMode = true ]] || return 0
	local _state _pidf _errf _script _outf _old _wpid _key _cp _app _base _mainlog _mode
	_key="$(_keycheck_path 2>/dev/null)" || { _speed_debug_log "DISPLAY_VOLUME_WATCH_SKIP reason=keycheck_native_missing"; return 0; }
	_state="$(_display_power_volume_state_file)"
	_pidf="$(_display_power_volume_pid_file)"
	_errf="$(_display_power_volume_err_file)"
	_script="$(_display_power_volume_script_file)"
	_outf="$(_display_power_volume_output_file)"
	if [[ -s $_pidf ]]; then
		_old="$(cat "$_pidf" 2>/dev/null)"
		case $_old in ''|*[!0-9]*) _old="" ;; esac
		[[ -n $_old ]] && kill -0 "$_old" 2>/dev/null && return 0
	fi
	_cp="$(_dex_classes_path)"
	_app="$(_dex_app_process_abs)"
	_base="${DEX_APP_PROCESS_BASE:-/system/bin}"
	_mainlog="${SPEED_DEBUG_MAIN_LOG:-/dev/null}"
	_mode="$(_display_power_fake_dark_mode)"
	[[ -n $_cp && -f $_cp && -x $_app ]] || {
		_speed_debug_log "DISPLAY_VOLUME_WATCH_SKIP reason=runtime_missing classes=$_cp appProcess=$_app"
		return 0
	}
	_display_power_volume_watcher_script_write "$_script" || {
		_speed_debug_log "DISPLAY_VOLUME_WATCH_SKIP reason=watcher_script_write_failed path=$_script"
		return 0
	}
	: > "$_state" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	rm -f "$_errf" "$_outf" 2>/dev/null || true
	"$_script" "$_state" "$_key" "$_mode" "$_cp" "$_app" "$_base" "$_mainlog" "$_outf" >/dev/null 2>"$_errf" &
	_wpid="$!"
	echo "$_wpid" > "$_pidf" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	_speed_debug_log "DISPLAY_VOLUME_WATCH_SPAWN pid=$_wpid trackedChild=1 watcherExecIsolated=1 keycheckDirectChild=1 commandSubstitution=0 disowned=0"
}

_display_power_volume_descendants() {
	local _root="$1" _psbin="/system/bin/ps"
	case $_root in ''|*[!0-9]*) return 0 ;; esac
	[[ -x $_psbin ]] || _psbin="ps"
	$_psbin -e -o pid=,ppid= 2>/dev/null | awk -v root="$_root" '
		{ ppid[$1]=$2 }
		END {
			mark[root]=1; changed=1
			while (changed) {
				changed=0
				for (p in ppid) if (!(p in mark) && (ppid[p] in mark)) { mark[p]=1; changed=1 }
			}
			for (p in mark) if (p != root) print p
		}'
}

_display_power_volume_pid_active() {
	local _pid="$1" _st=""
	case $_pid in ''|*[!0-9]*) return 1 ;; esac
	kill -0 "$_pid" 2>/dev/null || return 1
	_st="$(awk '/^State:/{print $2; exit}' /proc/"$_pid"/status 2>/dev/null)"
	[[ $_st != Z ]]
}

_display_power_volume_watcher_stop() {
	# r198: watcher 是獨立 exec shell，沒有主 tools.sh 的 EXIT trap。
	# keycheck 是 watcher 直接 child；移除 state 後 TERM keycheck，watcher 必須自行 exit 0，再由主 shell wait/reap。
	local _state _pidf _errf _script _outf _pid _kids _kid _i=0 _forced=0 _phase=term-keycheck-direct-child _wait_rc=0
	_state="$(_display_power_volume_state_file)"
	_pidf="$(_display_power_volume_pid_file)"
	_errf="$(_display_power_volume_err_file)"
	_script="$(_display_power_volume_script_file)"
	_outf="$(_display_power_volume_output_file)"
	rm -f "$_state" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	if [[ -s $_pidf ]]; then
		_pid="$(cat "$_pidf" 2>/dev/null)"
		case $_pid in ''|*[!0-9]*) _pid="" ;; esac
		if [[ -n $_pid ]]; then
			_kids="$(_display_power_volume_descendants "$_pid" 2>/dev/null)"
			_speed_debug_log "DISPLAY_VOLUME_WATCH_STOP_BOUNDED_BEGIN pid=$_pid children=$(echo "$_kids" | tr '\n' ',' | sed 's/,$//') mode=exec-isolated-direct-keycheck"
			for _kid in $_kids; do kill -TERM "$_kid" 2>/dev/null || true; done
			_i=0
			while _display_power_volume_pid_active "$_pid" && [[ $_i -lt 8 ]]; do
				sleep 0.05
				_i=$((_i + 1))
			done
			if _display_power_volume_pid_active "$_pid"; then
				_phase=kill-descendants
				_kids="$(_display_power_volume_descendants "$_pid" 2>/dev/null)"
				for _kid in $_kids; do kill -KILL "$_kid" 2>/dev/null || true; done
				while _display_power_volume_pid_active "$_pid" && [[ $_i -lt 16 ]]; do
					sleep 0.05
					_i=$((_i + 1))
				done
			fi
			if _display_power_volume_pid_active "$_pid"; then
				_forced=1
				_phase=kill-watcher-last-resort
				kill -KILL "$_pid" 2>/dev/null || true
				sleep 0.05
			fi
			# wait 仍放在條件式內避免 errexit；正常 exec watcher 必須回 0。
			if wait "$_pid" 2>/dev/null; then
				_wait_rc=0
			else
				_wait_rc=$?
			fi
			case $_wait_rc in
			0|127) ;;
			137) [[ $_forced = 1 ]] || _speed_debug_log "DISPLAY_VOLUME_WATCH_WAIT_UNEXPECTED pid=$_pid rc=$_wait_rc forced=$_forced" ;;
			*) _speed_debug_log "DISPLAY_VOLUME_WATCH_WAIT_UNEXPECTED pid=$_pid rc=$_wait_rc forced=$_forced" ;;
			esac
			_speed_debug_log "DISPLAY_VOLUME_WATCH_STOP_BOUNDED_DONE pid=$_pid loops=$_i forced=$_forced phase=$_phase watcherTermSignalSent=0 watcherExecIsolated=1 keycheckDirectChild=1 commandSubstitution=0 trackedChild=1 waitRc=$_wait_rc waitGuard=conditional-errexit-safe expectedWaitRc=0"
		fi
		rm -f "$_pidf" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	fi
	_speedbackup_filter_cleanup_stderr_file "$_errf" display_volume_watcher
	rm -f "$_script" "$_outf" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	return 0
}

_DISPLAY_TIMEOUT_REQUESTED_MS="${SPEEDBACKUP_DISPLAY_TIMEOUT_MS:-2147483647}"
# r455: 保留 r454 stale timeout guard；進度條改動已回退。
# 預設回復到 15 秒；若使用者確實長期使用永不息屏，可設 SPEEDBACKUP_DISPLAY_TIMEOUT_SAME_AS_REQUESTED_POLICY=keep。
_DISPLAY_TIMEOUT_FALLBACK_MS="${SPEEDBACKUP_DISPLAY_TIMEOUT_FALLBACK_MS:-15000}"
_DISPLAY_TIMEOUT_SAME_AS_REQUESTED_POLICY="${SPEEDBACKUP_DISPLAY_TIMEOUT_SAME_AS_REQUESTED_POLICY:-fallback}"
_DISPLAY_TIMEOUT_ACTIVE="${_DISPLAY_TIMEOUT_ACTIVE:-0}"
_DISPLAY_RESTORE_DONE="${_DISPLAY_RESTORE_DONE:-0}"

_display_timeout_save_file() {
	printf '%s\n' "${TMPDIR:-/data/local/tmp}/.screen_timeout_orig"
}

_display_timeout_shell_begin() {
	local _scr_save _req_save _applied_save _orig _orig_effective _fallback _policy _readback _rollback_readback _get_rc _put_rc _rb_rc _rollback_put_rc _rollback_get_rc _get_timeout _put_timeout
	_scr_save="$(_display_timeout_save_file)"
	_req_save="${TMPDIR:-/data/local/tmp}/.screen_timeout_requested"
	_applied_save="${TMPDIR:-/data/local/tmp}/.screen_timeout_applied"
	_get_timeout="${SPEEDBACKUP_DISPLAY_SETTINGS_GET_TIMEOUT_MS:-2000}"
	_put_timeout="${SPEEDBACKUP_DISPLAY_SETTINGS_PUT_TIMEOUT_MS:-5000}"
	# r468: begin path uses bounded get/put helpers; Dex direct first, shell fallback.
	# Preserve the old fail-closed semantics: if begin cannot get/put/verify, do not keep the long timeout as active.
	rm -f "${TMPDIR:-/data/local/tmp}/.screen_timeout_requested" "${TMPDIR:-/data/local/tmp}/.screen_timeout_applied" "${TMPDIR:-/data/local/tmp}/.screen_timeout_session_id" "${TMPDIR:-/data/local/tmp}/.screen_timeout_backend" 2>/dev/null
	_orig="$(_speedbackup_settings_get_system_bounded screen_off_timeout "$_get_timeout" display_timeout_begin_original)"
	_get_rc=$?
	[[ $_get_rc = 0 ]] || return 1
	case $_orig in ''|null|*[!0-9]*) return 1 ;; esac
	_orig_effective="$_orig"
	_fallback="${_DISPLAY_TIMEOUT_FALLBACK_MS:-15000}"
	case $_fallback in ''|*[!0-9]*) _fallback=15000 ;; esac
	_policy="${_DISPLAY_TIMEOUT_SAME_AS_REQUESTED_POLICY:-fallback}"
	if [[ $_orig = "$_DISPLAY_TIMEOUT_REQUESTED_MS" ]]; then
		case $_policy in
		keep|KEEP|Keep|0|false|FALSE|no|NO)
			_speed_debug_log "DISPLAY_TIMEOUT_BEGIN_ORIGINAL_EQUALS_REQUESTED policy=keep rawOriginal=$_orig restoreOriginal=$_orig requested=$_DISPLAY_TIMEOUT_REQUESTED_MS mode=r470"
			;;
		*)
			_orig_effective="$_fallback"
			_speed_debug_log "DISPLAY_TIMEOUT_BEGIN_ORIGINAL_EQUALS_REQUESTED policy=fallback rawOriginal=$_orig restoreOriginal=$_orig_effective requested=$_DISPLAY_TIMEOUT_REQUESTED_MS mode=r470"
			;;
		esac
	fi
	printf '%s\n' "$_orig_effective" > "$_scr_save" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} || return 1
	printf '%s\n' "$_DISPLAY_TIMEOUT_REQUESTED_MS" > "$_req_save" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} || return 1
	_speedbackup_settings_put_system_bounded screen_off_timeout "$_DISPLAY_TIMEOUT_REQUESTED_MS" "$_put_timeout" display_timeout_begin_put
	_put_rc=$?
	if [[ $_put_rc != 0 ]]; then
		rm -f "$_req_save" "$_applied_save" "${TMPDIR:-/data/local/tmp}/.screen_timeout_session_id" "${TMPDIR:-/data/local/tmp}/.screen_timeout_backend" 2>/dev/null
		_speed_debug_log "DISPLAY_TIMEOUT_SHELL_BEGIN_FAIL_PUT original=$_orig requested=$_DISPLAY_TIMEOUT_REQUESTED_MS getRc=$_get_rc putRc=$_put_rc backend=bounded-shell mode=r473"
		return 1
	fi
	_readback="$(_speedbackup_settings_get_system_bounded screen_off_timeout "$_get_timeout" display_timeout_begin_readback)"
	_rb_rc=$?
	case $_readback in
	''|null|*[!0-9]*)
		_speedbackup_settings_put_system_bounded screen_off_timeout "$_orig_effective" "$_put_timeout" display_timeout_begin_invalid_rollback_put >/dev/null 2>&1
		_rollback_put_rc=$?
		_rollback_readback="$(_speedbackup_settings_get_system_bounded screen_off_timeout "$_get_timeout" display_timeout_begin_invalid_rollback_readback)"
		_rollback_get_rc=$?
		if [[ $_rollback_get_rc = 0 && $_rollback_readback = "$_orig_effective" ]]; then
			rm -f "$_scr_save" "$_req_save" "$_applied_save" "${TMPDIR:-/data/local/tmp}/.screen_timeout_session_id" "${TMPDIR:-/data/local/tmp}/.screen_timeout_backend" 2>/dev/null
			_DISPLAY_TIMEOUT_ACTIVE=0
		fi
		_speed_debug_log "DISPLAY_TIMEOUT_SHELL_BEGIN_FAIL_INVALID_READBACK original=$_orig requested=$_DISPLAY_TIMEOUT_REQUESTED_MS readback=${_readback:-empty} rollbackReadback=${_rollback_readback:-empty} getRc=$_get_rc putRc=$_put_rc rbRc=$_rb_rc rollbackPutRc=$_rollback_put_rc rollbackGetRc=$_rollback_get_rc backend=bounded-shell mode=r473"
		return 1
		;;
	esac
	printf '%s\n' "$_readback" > "$_applied_save" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} || return 1
	if [[ $_readback != "$_DISPLAY_TIMEOUT_REQUESTED_MS" ]]; then
		_speedbackup_settings_put_system_bounded screen_off_timeout "$_orig_effective" "$_put_timeout" display_timeout_begin_mismatch_rollback_put >/dev/null 2>&1
		_rollback_put_rc=$?
		_rollback_readback="$(_speedbackup_settings_get_system_bounded screen_off_timeout "$_get_timeout" display_timeout_begin_mismatch_rollback_readback)"
		_rollback_get_rc=$?
		if [[ $_rollback_get_rc = 0 && $_rollback_readback = "$_orig_effective" ]]; then
			rm -f "$_scr_save" "$_req_save" "$_applied_save" "${TMPDIR:-/data/local/tmp}/.screen_timeout_session_id" "${TMPDIR:-/data/local/tmp}/.screen_timeout_backend" 2>/dev/null
			_DISPLAY_TIMEOUT_ACTIVE=0
		else
			# Keep marker for EXIT/startup stale restore. End path compares against the actual applied value.
			_DISPLAY_TIMEOUT_ACTIVE=1
		fi
		_speed_debug_log "DISPLAY_TIMEOUT_SHELL_BEGIN_FAIL_MISMATCH original=$_orig requested=$_DISPLAY_TIMEOUT_REQUESTED_MS applied=$_readback rollbackReadback=${_rollback_readback:-empty} getRc=$_get_rc putRc=$_put_rc rbRc=$_rb_rc rollbackPutRc=$_rollback_put_rc rollbackGetRc=$_rollback_get_rc backend=bounded-shell mode=r473"
		return 1
	fi
	Get_dark_screen_seconds="$_orig_effective"
	_DISPLAY_TIMEOUT_ACTIVE=1
	_speed_debug_log "DISPLAY_TIMEOUT_SHELL_BEGIN original=$_orig_effective rawOriginal=$_orig requested=$_DISPLAY_TIMEOUT_REQUESTED_MS applied=$_readback readback=$_readback fallbackPolicy=$_policy getRc=$_get_rc putRc=$_put_rc rbRc=$_rb_rc backend=bounded-shell mode=r473"
	return 0
}

_display_timeout_session_active() {
	local _scr_save _req_save _applied_save _vol_state _vol_pid
	_scr_save="$(_display_timeout_save_file)"
	_req_save="${TMPDIR:-/data/local/tmp}/.screen_timeout_requested"
	_applied_save="${TMPDIR:-/data/local/tmp}/.screen_timeout_applied"
	_vol_state="$(_display_power_volume_state_file 2>/dev/null)"
	_vol_pid="$(_display_power_volume_pid_file 2>/dev/null)"
	[[ ${_DISPLAY_TIMEOUT_ACTIVE:-0} = 1 ]] && return 0
	[[ -s $_scr_save || -s $_req_save || -s $_applied_save ]] && return 0
	[[ -n $_vol_state && -f $_vol_state ]] && return 0
	[[ -n $_vol_pid && -s $_vol_pid ]] && return 0
	return 1
}

_display_timeout_shell_end() {
	local _scr_save _req_save _applied_save _orig _current _readback _requested _applied _get_rc _put_rc _rb_rc
	_scr_save="$(_display_timeout_save_file)"
	_req_save="${TMPDIR:-/data/local/tmp}/.screen_timeout_requested"
	_applied_save="${TMPDIR:-/data/local/tmp}/.screen_timeout_applied"
	_requested="$_DISPLAY_TIMEOUT_REQUESTED_MS"
	if [[ -s $_req_save ]]; then
		_requested="$(cat "$_req_save" 2>/dev/null)"
		case $_requested in ''|*[!0-9]*) _requested="$_DISPLAY_TIMEOUT_REQUESTED_MS" ;; esac
	fi
	_applied="$_requested"
	if [[ -s $_applied_save ]]; then
		_applied="$(cat "$_applied_save" 2>/dev/null)"
		case $_applied in ''|*[!0-9]*) _applied="$_requested" ;; esac
	fi
	[[ -s $_scr_save ]] || {
		rm -f "${TMPDIR:-/data/local/tmp}/.screen_timeout_requested" "${TMPDIR:-/data/local/tmp}/.screen_timeout_applied" "${TMPDIR:-/data/local/tmp}/.screen_timeout_session_id" "${TMPDIR:-/data/local/tmp}/.screen_timeout_backend" 2>/dev/null
		_DISPLAY_TIMEOUT_ACTIVE=0
		Get_dark_screen_seconds=""
		return 0
	}
	_orig="$(cat "$_scr_save" 2>/dev/null)"
	case $_orig in ''|*[!0-9]*) return 1 ;; esac
	_current="$(_speedbackup_settings_get_system_bounded screen_off_timeout "${SPEEDBACKUP_DISPLAY_SETTINGS_GET_TIMEOUT_MS:-2000}" display_timeout_session_current)"
	_get_rc=$?
	# Compare-and-restore: only restore if current still equals the value that this run actually applied.
	# If user/system changed timeout after our begin, do not overwrite that external change.
	if [[ $_get_rc = 0 && $_current != "$_applied" ]]; then
		_speed_debug_log "DISPLAY_TIMEOUT_SHELL_END externalChange=true current=$_current original=$_orig requested=$_requested applied=$_applied restored=false backend=shell-timeout-stale-guard mode=r462"
		rm -f "$_scr_save" "${TMPDIR:-/data/local/tmp}/.screen_timeout_requested" "${TMPDIR:-/data/local/tmp}/.screen_timeout_applied" "${TMPDIR:-/data/local/tmp}/.screen_timeout_session_id" "${TMPDIR:-/data/local/tmp}/.screen_timeout_backend" 2>/dev/null
		_DISPLAY_TIMEOUT_ACTIVE=0
		Get_dark_screen_seconds=""
		return 0
	fi
	_speedbackup_settings_put_system_bounded screen_off_timeout "$_orig" "${SPEEDBACKUP_DISPLAY_SETTINGS_PUT_TIMEOUT_MS:-5000}" display_timeout_session_put
	_put_rc=$?
	[[ $_put_rc = 0 ]] || return 1
	_readback="$(_speedbackup_settings_get_system_bounded screen_off_timeout "${SPEEDBACKUP_DISPLAY_SETTINGS_GET_TIMEOUT_MS:-2000}" display_timeout_session_readback)"
	_rb_rc=$?
	if [[ $_rb_rc = 0 && $_readback != "$_orig" ]]; then
		return 1
	fi
	rm -f "$_scr_save" "${TMPDIR:-/data/local/tmp}/.screen_timeout_requested" "${TMPDIR:-/data/local/tmp}/.screen_timeout_applied" "${TMPDIR:-/data/local/tmp}/.screen_timeout_session_id" "${TMPDIR:-/data/local/tmp}/.screen_timeout_backend" 2>/dev/null
	_DISPLAY_TIMEOUT_ACTIVE=0
	Get_dark_screen_seconds=""
	_speed_debug_log "DISPLAY_TIMEOUT_SHELL_END original=$_orig requested=$_requested applied=$_applied readback=${_readback:-unavailable} restored=true backend=shell-timeout-stale-guard getRc=$_get_rc putRc=$_put_rc rbRc=$_rb_rc mode=r462"
	return 0
}

Set_screen_pause_seconds () {
	if [[ $1 = on ]]; then
		_DISPLAY_RESTORE_DONE=0
		if [[ ${_DISPLAY_TIMEOUT_ACTIVE:-0} != 1 ]]; then
			if _display_timeout_shell_begin; then
				echo_log "由shell設置無操作息屏時間為無限" "" 0
			else
				echoRgb "設置無操作息屏時間失敗。" "0"
				return 1
			fi
		fi
		[[ $setDisplayPowerMode = true ]] && {
			_display_power_volume_hint_show || true
			_display_mode="$(_display_power_fake_dark_mode)"
			if setDisplay "$_display_mode" >/dev/null 2>&1; then
				_speed_debug_log "DISPLAY_POWER_MODE_SET mode=$_display_mode rc=0 terminal=quiet"
			else
				_display_rc=$?
				_speed_debug_log "DISPLAY_POWER_MODE_SET mode=$_display_mode rc=$_display_rc terminal=quiet"
			fi
			echo_log "設置螢幕狀態display-off(mode=$_display_mode, shell-timeout-stale-guard)"
			unset _display_mode _display_rc
			_display_power_volume_watcher_start || true
		}
	elif [[ $1 = off ]]; then
		if _speedbackup_display_restore_should_defer_for_pack; then
			_speedbackup_display_restore_defer_for_debug_pack "set-screen-off-before-final-debug-pack"
			return 0
		fi
		if [[ ${_DISPLAY_RESTORE_DONE:-0} = 1 ]]; then
			_speed_debug_log "DISPLAY_RESTORE_SKIP already_done=1 reason=duplicate-off-call"
			return 0
		fi
		if ! _display_timeout_session_active; then
			_speed_debug_log "DISPLAY_RESTORE_SKIP reason=no-active-display-session active=${_DISPLAY_TIMEOUT_ACTIVE:-0} setDisplayPowerMode=${setDisplayPowerMode:-} mode=r324"
			return 0
		fi
		if [[ $setDisplayPowerMode = true ]]; then
			_speedbackup_display_power_restore_for_final_pack "set-screen-off" || true
		fi
		if _display_timeout_shell_end; then
			echo_log "由shell還原無操作息屏時間" "" 0
			_DISPLAY_RESTORE_DONE=1
		else
			echoRgb "還原無操作息屏時間失敗；shell暫存保留供下次啟動修復。" "0"
			return 1
		fi
	fi
	return 0
}
_appstate_record_from_app_details() {
	local _json="$1" _entry="$2" _pkg="$3" _out="$4"
	[[ -s $_json && -n $_pkg && -n $_out ]] || return 1
	jq -c --arg entry "$_entry" --arg pkg "$_pkg" '
		def mode_num($v):
			if $v == null then 3
			elif ($v|type) == "number" then $v
			else ($v|tostring|ascii_downcase) as $s |
				if ($s|test("^[0-9]+$")) then ($s|tonumber)
				elif ($s=="allow" or $s=="allowed" or $s=="true") then 0
				elif ($s=="ignore" or $s=="ignored" or $s=="false") then 1
				elif ($s=="deny" or $s=="denied" or $s=="error" or $s=="errored") then 2
				elif $s=="foreground" then 4 else 3 end
			end;
		def mode_name($m):
			if $m==0 then "allow" elif $m==1 then "ignored" elif $m==2 then "errored"
			elif $m==3 then "default" elif $m==4 then "foreground" else "mode_\($m)" end;
		def ensure_scoped:
			if type != "object" then . else
				(if has("packageMode") then . else . + {packageMode:null} end) |
				(if has("uidMode") then . else . + {uidMode:null} end) |
				(if has("scope") then . else . + {scope:"default"} end)
			end;
		def normalize_appstate_v2:
			.permissions=[(.permissions // [])[] | if (((.appOp // -1)|tonumber? // -1) >= 0) then ensure_scoped else . end] |
			.specialAccess=((.specialAccess // {}) | with_entries(.value |= ensure_scoped)) |
			.otherAppOps=[(.otherAppOps // [])[] | ensure_scoped] |
			.batterySettings=((.batterySettings // {}) |
				(if has("RUN_IN_BACKGROUND") then .RUN_IN_BACKGROUND |= ensure_scoped else . end) |
				(if has("RUN_ANY_IN_BACKGROUND") then .RUN_ANY_IN_BACKGROUND |= ensure_scoped else . end));
		def pparts($v): ($v|tostring|split(" "));
		def pflag($v): ((pparts($v)|map(select(startswith("pflags=")))|.[0]//"pflags=0")|sub("^pflags=";"")|tonumber? // 0);
		def merged_objects($xs): reduce ($xs[]? | select(type=="object")) as $x ({}; . * $x);
		def first_value($xs): ([$xs[]? | select(. != null)] | .[0] // null);
		def special_meta:
			{SYSTEM_ALERT_WINDOW:{publicName:"android:system_alert_window",permission:"android.permission.SYSTEM_ALERT_WINDOW"},
			 PICTURE_IN_PICTURE:{publicName:"android:picture_in_picture",permission:null},
			 MANAGE_EXTERNAL_STORAGE:{publicName:"android:manage_external_storage",permission:"android.permission.MANAGE_EXTERNAL_STORAGE"},
			 WRITE_SETTINGS:{publicName:"android:write_settings",permission:"android.permission.WRITE_SETTINGS"},
			 REQUEST_INSTALL_PACKAGES:{publicName:"android:request_install_packages",permission:"android.permission.REQUEST_INSTALL_PACKAGES"},
			 GET_USAGE_STATS:{publicName:"android:get_usage_stats",permission:"android.permission.PACKAGE_USAGE_STATS"},
			 USE_FULL_SCREEN_INTENT:{publicName:"android:use_full_screen_intent",permission:"android.permission.USE_FULL_SCREEN_INTENT"},
			 SCHEDULE_EXACT_ALARM:{publicName:"android:schedule_exact_alarm",permission:"android.permission.SCHEDULE_EXACT_ALARM"},
			 ACCESS_NOTIFICATION_POLICY:{publicName:"android:access_notification_policy",permission:"android.permission.ACCESS_NOTIFICATION_POLICY"}};
		def special_key($k;$v):
			(($v.publicName // "")|tostring) as $n |
			(($k // "")|tostring|ascii_upcase) as $u |
			(special_meta) as $m |
			([$m|to_entries[] | select(.value.publicName==$n or .key==$u) | .key] | .[0] // "");
		def special_public($key): (special_meta[$key].publicName // "");
		def special_permission($key): (special_meta[$key].permission // null);
		def canonical_special_state($key;$v):
			($v // {}) as $x |
			mode_num($x.mode // $x.effectiveMode // $x.packageMode // 3) as $m |
			(($x.op // -1)|tonumber? // -1) as $op |
			{publicName:(($x.publicName // special_public($key))|tostring),
			 manifestPermission:($x.manifestPermission // $x.permission // special_permission($key)),
			 requested:($x.requested // true), supported:($x.supported // ($op >= 0)), op:$op,
			 source:"legacy-migrated", packageMode:(if $x.packageMode==null then $m else mode_num($x.packageMode) end),
			 uidMode:(if $x.uidMode==null then null else mode_num($x.uidMode) end),
			 scope:($x.scope // "package"), mode:$m, modeName:mode_name($m), allowed:($m==0 or $m==4)};
		def legacy_permissions($p):
			[$p|to_entries[]? | select(.key|startswith("android.permission.")) |
			 (pparts(.value)) as $v |
			 {name:.key, granted:($v[0]=="true"), flags:pflag(.value), runtime:true, development:false,
			  appOp:(if ($v|length)>=3 then ($v[1]|tonumber? // -1) else -1 end),
			  appOpMode:(if ($v|length)>=3 then mode_num($v[2]) else 3 end),
			  appOpModeName:mode_name(if ($v|length)>=3 then mode_num($v[2]) else 3 end),
			  packageMode:(if ($v|length)>=3 then mode_num($v[2]) else null end), uidMode:null, scope:"package"}];
		def special_from_permissions($p):
			reduce ($p|to_entries[]?) as $e ({};
				(special_key($e.key; {publicName:$e.key})) as $key |
				if $key=="" then . else
					(pparts($e.value)) as $v |
					(($v[1]|tonumber? // -1)) as $op |
					(mode_num($v[2] // 3)) as $m |
					.[$key]=canonical_special_state($key; {publicName:$e.key,op:$op,mode:$m,packageMode:$m,requested:true,supported:($op>=0)})
				end);
		def normalize_special($raw):
			reduce (($raw // {})|to_entries[]?) as $e ({};
				(special_key($e.key; $e.value)) as $key |
				if $key=="" then . else .[$key]=canonical_special_state($key;$e.value) end);
		def legacy_battery($b; $bo):
			($b//{}) as $x |
			def opstate($k): (($x[$k]//"")|tostring|split(" ")) as $v |
				if ($v|length)>=2 then (mode_num($v[1])) as $m |
					{supported:true,op:($v[0]|tonumber? // -1),mode:$m,modeName:mode_name($m),packageMode:$m,uidMode:null,scope:"package"}
				else {supported:false,op:-1,mode:3,modeName:"default",packageMode:null,uidMode:null,scope:"none"} end;
			(mode_num($bo)) as $bom |
			{RUN_IN_BACKGROUND:opstate("BATTERY:RUN_IN_BACKGROUND"),
			 RUN_ANY_IN_BACKGROUND:(if ($x|has("BATTERY:RUN_ANY_IN_BACKGROUND")) then opstate("BATTERY:RUN_ANY_IN_BACKGROUND")
				else {supported:($bo!=null and ($bo|tostring)!=""),op:-1,mode:$bom,modeName:mode_name($bom),packageMode:null,uidMode:null,scope:"legacy"} end),
			 deviceidleWhitelist:(((($x["BATTERY:deviceidle_whitelist"] // $x["BATTERY:idle_whitelist"] // $x["BATTERY:doze_whitelist"] // false)|tostring|ascii_downcase)) == "true")};
		def legacy_ops($p;$special;$battery):
			([$special[]? | .op | select(type=="number" and .>=0)] +
			 [$battery[]? | objects | .op | select(type=="number" and .>=0)]) as $handled |
			[$p|to_entries[]? | select((.key|startswith("android:")) or (.key|startswith("EXTRA_OP_"))) |
			 (pparts(.value)) as $v |
			 {publicName:.key,
			  op:(if (.key|startswith("EXTRA_OP_")) then ($v[0]|tonumber? // -1) else ($v[1]|tonumber? // -1) end),
			  mode:(if (.key|startswith("EXTRA_OP_")) then mode_num($v[1]) else mode_num($v[2]) end)} |
			 . as $item | select($item.op>=0 and (($handled|index($item.op))==null)) | $item |
			 .modeName=mode_name(.mode) | .allowed=(.mode==0 or .mode==4) |
			 .packageMode=.mode | .uidMode=null | .scope="package"] | unique_by(.op);
		(.[$entry].app_state // ([.[]|objects|select(.app_state!=null).app_state]|.[0]) // null) as $state |
		if $state != null then
			$state | normalize_appstate_v2 | .schemaVersion=2 | .recordType="snapshot" | .packageName=$pkg
		else
			[.[]|objects] as $objects |
			($objects|map(select(.PackageName==$pkg))|.[0] // $objects[0] // {}) as $meta |
			merged_objects($objects|map(.permissions)) as $p |
			merged_objects($objects|map(.special_access)) as $raw_special |
			merged_objects($objects|map(.battery_settings)) as $battery_raw |
			first_value($objects|map(.battery_opt)) as $battery_opt |
			first_value($objects|map(.install_diagnostics)) as $install_diag |
			first_value($objects|map(.installer)) as $installer |
			first_value($objects|map(.Ssaid)) as $ssaid |
			((special_from_permissions($p)) * (normalize_special($raw_special))) as $special |
			(legacy_battery($battery_raw;$battery_opt)) as $battery |
			{schemaVersion:2,recordType:"snapshot",packageName:$pkg,userId:0,
			 package:{installer:($installer//$install_diag.installer//$install_diag.installing//null),
			          versionCode:($meta.apk_version//null)},
			 installDiagnostics:($install_diag//{}),
			 permissions:legacy_permissions($p), specialAccess:$special,
			 otherAppOps:legacy_ops($p;$special;$battery), batterySettings:$battery,
			 ssaid:($ssaid//null), sourceFormat:"legacy-app-details-migrated"}
		end |
		select((.permissions|type)=="array" and (.specialAccess|type)=="object" and
		       (.otherAppOps|type)=="array" and (.batterySettings|type)=="object")
	' "$_json" > "$_out" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	[[ -s $_out ]]
}

restore_appstate() {
	echoRgb "加入統一AppState恢復佇列"
	local _restore_appstate_autoflush=0 _record="$TMPDIR/.appstate_record_$$"
	if [[ ${_batch_appstate_mode:-0} != 1 ]]; then
		_restore_appstate_autoflush=1
		_batch_appstate_mode=1
		: > "$TMPDIR/.batch_appstate_ndjson" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	fi
	if ! _appstate_record_from_app_details "$app_details" "$name1" "$name2" "$_record"; then
		echoRgb "$name1 AppState資料缺失或無法轉換，略過狀態恢復" "0"
		_speed_debug_log "RESTORE_APPSTATE_QUEUE_FAIL package=${name2:-} source=$app_details"
		rm -f "$_record" 2>/dev/null
		[[ $_restore_appstate_autoflush = 1 ]] && _batch_appstate_mode=0
		return 1
	fi
	[[ -n ${name2:-} ]] && printf '%s	%s
' "$name2" "${name1:-$name2}" >> "$TMPDIR/.appstate_label_map" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	# 同 package 只保留最後一筆，避免重複恢復。
	if [[ -s $TMPDIR/.batch_appstate_ndjson ]]; then
		_appstate_ndjson_remove_package_file "$TMPDIR/.batch_appstate_ndjson" "$name2" "$TMPDIR/.batch_appstate_ndjson.tmp" || : > "$TMPDIR/.batch_appstate_ndjson.tmp"
		cat "$_record" >> "$TMPDIR/.batch_appstate_ndjson.tmp"
		mv -f "$TMPDIR/.batch_appstate_ndjson.tmp" "$TMPDIR/.batch_appstate_ndjson"
	else
		cat "$_record" > "$TMPDIR/.batch_appstate_ndjson"
	fi
	rm -f "$_record" 2>/dev/null
	if [[ $_restore_appstate_autoflush = 1 ]]; then
		flush_batch_appstate
		local _flush_rc=$?
		_batch_appstate_mode=0
		return $_flush_rc
	fi
	return 0
}

# v24.20.14-3 appstate auto chunk：使用者仍可一次恢復 100+ app；內部只切 dex stdin 批次。
_appstate_chunk_size() {
	local _v="$1" _fallback="$2"
	case $_v in ''|*[!0-9]*) echo "$_fallback" ;; 0) echo "$_fallback" ;; *) echo "$_v" ;; esac
}

_appstate_debug_aggregate() {
	local _op="$1" _kind _idx _in _out _prefix _tag _src _suffix
	[[ -n ${SPEED_DEBUG_RUN_DIR:-} && -d "$SPEED_DEBUG_RUN_DIR" ]] || return 0
	case $_op in
	reset)
		for _prefix in app_state verify_app_state; do
			: > "$SPEED_DEBUG_RUN_DIR/${_prefix}_stdin.log" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
			: > "$SPEED_DEBUG_RUN_DIR/${_prefix}_output.log" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
		done
		;;
	save)
		_kind="$2"; _idx="$3"; _in="$4"; _out="$5"
		case $_kind in restore) _prefix="app_state" ;; verify) _prefix="verify_app_state" ;; *) return 2 ;; esac
		_tag="$(printf '%03d' "$_idx")"
		_src="$_in"; _suffix="stdin"
		while :; do
			[[ -f $_src ]] && {
				{
					echo
					echo "===== ${_kind} chunk ${_tag} ${_suffix} BEGIN ====="
					cat "$_src" 2>/dev/null
					echo "===== ${_kind} chunk ${_tag} ${_suffix} END ====="
				} >> "$SPEED_DEBUG_RUN_DIR/${_prefix}_${_suffix}.log" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
			}
			[[ $_suffix = output ]] && break
			_src="$_out"; _suffix="output"
		done
		;;
	*) return 2 ;;
	esac
}

_appstate_ssaid_report_reset() {
	: > "$TMPDIR/.appstate_ssaid_restored" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	: > "$TMPDIR/.appstate_ssaid_same" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	: > "$TMPDIR/.appstate_ssaid_failed" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	: > "$TMPDIR/.appstate_ssaid_checked" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	: > "$TMPDIR/.appstate_ssaid_report" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
}

_appstate_label_for_pkg() {
	local _pkg="$1" _map="$TMPDIR/.appstate_label_map" _label="" _queue="$TMPDIR/.batch_appstate_ndjson"
	[[ -n $_pkg ]] || return 0
	if [[ -s $_map ]]; then
		_label="$(awk -F '\t' -v p="$_pkg" '$1==p && $2!="" {v=$2} END{print v}' "$_map" 2>/dev/null | tail -n 1)"
	fi
	# r81: 批量恢復流程中 cleanup_tmpdir_contents 可能在 flush 前被多次呼叫；若 label map 不完整，
	# 從仍在場的 canonical AppState queue 回讀 package.label，避免 SSAID 報告退回全包名。
	if [[ -z $_label && -s $_queue ]]; then
		_label="$(jq -r --arg p "$_pkg" 'select(.packageName==$p) | (.package.label // empty)' "$_queue" 2>/dev/null | tail -n 1)"
	fi
	[[ -n $_label ]] && printf '%s\n' "$_label" || printf '%s\n' "$_pkg"
}

_appstate_ssaid_report_line() {
	local _bucket="$1" _pkg="$2" _expected="$3" _actual="$4" _msg="$5" _label _display_line
	[[ -n $_pkg ]] || return 0
	_label="$(_appstate_label_for_pkg "$_pkg")"
	# r254: 終端 SSAID 顯示只保留「應用名 (包名)」，避免 expected/actual 長 SSAID 值刷屏與換行。
	# 完整 expected/actual/message 仍保留在 speed_debug/ssaid_restore_report.tsv。
	_display_line="$_label ($_pkg)"
	printf '%s\n' "$_display_line" >> "$TMPDIR/.appstate_ssaid_${_bucket}" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	printf '%s	%s	%s	%s	%s	%s
' "$_bucket" "$_pkg" "$_label" "$_expected" "$_actual" "$_msg" >> "$TMPDIR/.appstate_ssaid_report" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
}

_appstate_ssaid_collect_restore_output() {
	local _out="$1" _tmp _action _pkg _expected _actual _msg
	[[ -s $_out ]] || return 0
	_tmp="$TMPDIR/.appstate_ssaid_parse_$$"
	jq -r '
		def msg: (.result.message // "");
		def capv($re): try ((msg | capture($re)).v // "") catch "";
		select(.recordType=="restore") as $r |
		($r.items[]? | select(.category=="ssaid")) |
		(msg) as $m |
		(if ((.result.name // "") != "OK") then "failed"
		 elif ($m | test("metadataRestore=\\{attempted=true")) or ($m | test("metadataChangedByWrite=true")) then "restored"
		 elif ($m | test("reason=already-matches")) then "same"
		 else "checked" end) as $action |
		[$action, ($r.packageName // .key // ""), capv("expected=(?<v>[^ ]+)"), capv("actual=(?<v>[^ ]+)"), ($m|gsub("\\t";" "))] | @tsv
	' "$_out" > "$_tmp" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} || { rm -f "$_tmp" 2>/dev/null; return 0; }
	while IFS="$(printf '\t')" read -r _action _pkg _expected _actual _msg; do
		case $_action in
		restored|same|failed|checked) _appstate_ssaid_report_line "$_action" "$_pkg" "$_expected" "$_actual" "$_msg" ;;
		esac
	done < "$_tmp"
	rm -f "$_tmp" 2>/dev/null
	return 0
}

_appstate_ssaid_report_emit() {
	local _restored=0 _same=0 _failed=0 _checked=0 _total=0 _n
	for _n in restored same failed checked; do
		eval "_${_n}=\$(awk 'NF{c++} END{print c+0}' \"\$TMPDIR/.appstate_ssaid_${_n}\" 2>/dev/null)"
	done
	_total=$((_restored + _same + _failed + _checked))
	[[ $_total -eq 0 ]] && return 0
	# checked is the total number of SSAID restore items seen; other is the small
	# fallback bucket for OK items that were neither written nor already-matched.
	_speed_debug_log "SSAID_RESTORE_SUMMARY restored=$_restored same=$_same failed=$_failed checked=$_total other=$_checked"
	[[ -n ${SPEED_DEBUG_RUN_DIR:-} && -d ${SPEED_DEBUG_RUN_DIR:-} && -s $TMPDIR/.appstate_ssaid_report ]] && cp -f "$TMPDIR/.appstate_ssaid_report" "$SPEED_DEBUG_RUN_DIR/ssaid_restore_report.tsv" 2>/dev/null
	if [[ $_restored -gt 0 ]]; then
		echoRgb "本輪SSAID已寫回: $_restored 個" "1"
		sed -n '1,20p' "$TMPDIR/.appstate_ssaid_restored" 2>/dev/null | while IFS= read -r _line; do
			[[ -n $_line ]] && echoRgb "$_line" "2"
		done
		[[ $_restored -gt 20 ]] && echoRgb "其餘 $((_restored-20)) 個見 speed_debug/ssaid_restore_report.tsv" "2"
		echoRgb "SSAID已變更，建議重啟手機後再開啟相關App，避免系統/應用快取仍使用舊值" "3"
	fi
	[[ $_same -gt 0 ]] && echoRgb "SSAID已相同跳過: $_same 個" "2"
	[[ $_checked -gt 0 ]] && echoRgb "SSAID其他狀態已檢查: $_checked 個（詳情見speed_debug）" "2"
	[[ $_failed -gt 0 ]] && echoRgb "SSAID恢復失敗: $_failed 個（詳情見speed_debug）" "0"
}

# 批量沖刷：同一份 canonical AppState NDJSON 依序交給 restore 與 verify；AppOps reset、特殊存取、電池與 SSAID 均由引擎內部處理。
flush_batch_appstate() {
	local _queue="$TMPDIR/.batch_appstate_ndjson" _count _chunk_size _offset=0 _idx=0
	local _restore_ok=0 _restore_partial=0 _restore_failed=0
	local _verify_ok=0 _verify_vendor=0 _verify_mismatch=0 _verify_failed=0
	[[ -s $_queue ]] || return 0
	_appstate_capabilities_check || {
		echoRgb "AppState能力契約不符，已中止狀態恢復" "0"
		return 1
	}
	_count="$(awk 'NF{n++} END{print n+0}' "$_queue" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null})"
	[[ ${_count:-0} -gt 0 ]] || return 0
	_chunk_size="$(_appstate_chunk_size "${APPSTATE_RESTORE_CHUNK_SIZE:-30}" 30)"
	# r253: 不先輸出 appstate_batch_begin 0/N；第一個 chunk 會使用同一條批量預掃式進度列，避免窄螢幕出現兩條 0/N 進度條。
	_speed_debug_log "PROGRESS_STEP_SKIP tag=appstate_batch_begin reason=merged_into_chunk_inline current=0 total=$_count"
	_appstate_debug_aggregate reset
	_appstate_ssaid_report_reset
	: > "$TMPDIR/.appstate_restore_issues" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	: > "$TMPDIR/.appstate_verify_issues" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	while [[ $_offset -lt $_count ]]; do
		_idx=$((_idx+1))
		local _in="$TMPDIR/.appstate_chunk_${_idx}.ndjson"
		local _ro="$TMPDIR/.appstate_restore_${_idx}.ndjson"
		local _vo="$TMPDIR/.appstate_verify_${_idx}.ndjson"
		local _chunk_count
		awk -v off="$_offset" -v size="$_chunk_size" 'NF{n++; if(n>off && n<=off+size) print}' "$_queue" > "$_in" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
		[[ -s $_in ]] || break
		_chunk_count="$(awk 'NF{n++} END{print n+0}' "$_in" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null})"
		case $_chunk_count in ''|*[!0-9]*) _chunk_count=0 ;; esac
		_speedbackup_progress_step "$_offset" "$_count" "正在處理 AppState 批次 $_idx（本批 $_chunk_count 個）" "appstate_batch_chunk" "107"
		if _root_appstate_call restoreAppStateBatch "$_in" "$_ro" \
				&& _appstate_ndjson_has_summary "$_ro" restoreAppStateBatch; then
			_appstate_debug_aggregate save restore "$_idx" "$_in" "$_ro"
			_appstate_ssaid_collect_restore_output "$_ro"
			if _appstate_ndjson_summarize "$_ro" restore "$TMPDIR/.appstate_restore_issues"; then
				_restore_ok=$((_restore_ok + _APPSTATE_NDJSON_OK))
				_restore_partial=$((_restore_partial + _APPSTATE_NDJSON_WARN))
				_restore_failed=$((_restore_failed + _APPSTATE_NDJSON_FAILED))
			else
				_restore_failed=$((_restore_failed + _chunk_count))
				printf 'RESTORE\tchunk_%s\tNDJSON_PARSE_FAIL\tpackages=%s\n' "$_idx" "$_chunk_count" >> "$TMPDIR/.appstate_restore_issues"
			fi
		else
			# r98: batch restore may be rejected by framework/Dex with BAD_REQUEST because one record is not accepted.
			# Do not let one bad AppState item poison the whole chunk; split to per-package calls
			# so good packages can still restore/verify and the bad package is isolated in debug.
			if [[ $_chunk_count -gt 1 ]]; then
				local _split_i=0 _line _single_in _single_ro _single_vo _single_tag _single_pkg
				_speed_debug_log "APPSTATE_RESTORE_CHUNK_FAIL_SPLIT idx=$_idx packages=$_chunk_count code=${_APPSTATE_RESULT_CODE:-unknown} name=${_APPSTATE_RESULT_NAME:-unknown}"
				while IFS= read -r _line; do
					[[ -n $_line ]] || continue
					_split_i=$((_split_i+1))
					_single_tag=$((_idx * 1000 + _split_i))
					_single_in="$TMPDIR/.appstate_chunk_${_idx}_${_split_i}.ndjson"
					_single_ro="$TMPDIR/.appstate_restore_${_idx}_${_split_i}.ndjson"
					_single_vo="$TMPDIR/.appstate_verify_${_idx}_${_split_i}.ndjson"
					printf '%s\n' "$_line" > "$_single_in" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
					_single_pkg="$(printf '%s\n' "$_line" | jq -r '.packageName // "unknown"' 2>/dev/null | awk 'NF{print; exit}')"
					[[ -n $_single_pkg ]] || _single_pkg=unknown
					if _root_appstate_call restoreAppStateBatch "$_single_in" "$_single_ro" \
							&& _appstate_ndjson_has_summary "$_single_ro" restoreAppStateBatch; then
						_appstate_debug_aggregate save restore "$_single_tag" "$_single_in" "$_single_ro"
						_appstate_ssaid_collect_restore_output "$_single_ro"
						if _appstate_ndjson_summarize "$_single_ro" restore "$TMPDIR/.appstate_restore_issues"; then
							_restore_ok=$((_restore_ok + _APPSTATE_NDJSON_OK))
							_restore_partial=$((_restore_partial + _APPSTATE_NDJSON_WARN))
							_restore_failed=$((_restore_failed + _APPSTATE_NDJSON_FAILED))
						else
							_restore_failed=$((_restore_failed + 1))
							printf 'RESTORE\tchunk_%s_single_%s\tNDJSON_PARSE_FAIL\tpackage=%s\n' "$_idx" "$_split_i" "$_single_pkg" >> "$TMPDIR/.appstate_restore_issues"
						fi

						local _single_verify_rc
						_root_appstate_call verifyAppStateBatch "$_single_in" "$_single_vo"
						_single_verify_rc=$?
						if _appstate_verify_batch_accept "$_single_vo" "$_single_verify_rc"; then
							_appstate_debug_aggregate save verify "$_single_tag" "$_single_in" "$_single_vo"
							if _appstate_ndjson_summarize "$_single_vo" verify "$TMPDIR/.appstate_verify_issues"; then
								_verify_ok=$((_verify_ok + _APPSTATE_NDJSON_OK))
								_verify_vendor=$((_verify_vendor + ${_APPSTATE_NDJSON_VENDOR:-0}))
								_verify_mismatch=$((_verify_mismatch + _APPSTATE_NDJSON_WARN))
								_verify_failed=$((_verify_failed + _APPSTATE_NDJSON_FAILED))
							else
								_verify_failed=$((_verify_failed + 1))
								printf 'VERIFY\tchunk_%s_single_%s\tNDJSON_PARSE_FAIL\tpackage=%s\n' "$_idx" "$_split_i" "$_single_pkg" >> "$TMPDIR/.appstate_verify_issues"
							fi
						else
							_verify_failed=$((_verify_failed + 1))
							printf 'VERIFY\tchunk_%s_single_%s\tTRANSPORT_OR_PROTOCOL_FAIL\tcode=%s name=%s package=%s\n' \
								"$_idx" "$_split_i" "${_APPSTATE_RESULT_CODE:-unknown}" "${_APPSTATE_RESULT_NAME:-unknown}" "$_single_pkg" >> "$TMPDIR/.appstate_verify_issues"
							_speed_debug_log "APPSTATE_VERIFY_SINGLE_FAIL idx=$_idx single=$_split_i package=$_single_pkg code=${_APPSTATE_RESULT_CODE:-unknown} name=${_APPSTATE_RESULT_NAME:-unknown}"
						fi
					else
						_restore_failed=$((_restore_failed + 1))
						_verify_failed=$((_verify_failed + 1))
						_appstate_debug_aggregate save restore "$_single_tag" "$_single_in" "$_single_ro"
						printf 'RESTORE\tchunk_%s_single_%s\tTRANSPORT_OR_PROTOCOL_FAIL\tcode=%s name=%s package=%s\n' \
							"$_idx" "$_split_i" "${_APPSTATE_RESULT_CODE:-unknown}" "${_APPSTATE_RESULT_NAME:-unknown}" "$_single_pkg" >> "$TMPDIR/.appstate_restore_issues"
						_speed_debug_log "APPSTATE_RESTORE_SINGLE_FAIL idx=$_idx single=$_split_i package=$_single_pkg code=${_APPSTATE_RESULT_CODE:-unknown} name=${_APPSTATE_RESULT_NAME:-unknown}"
					fi
					rm -f "$_single_in" "$_single_ro" "$_single_vo" 2>/dev/null
				done < "$_in"
				rm -f "$_in" "$_ro" "$_vo" 2>/dev/null
				_offset=$((_offset+_chunk_size))
				_speedbackup_progress_step "$_offset" "$_count" "AppState 批次已完成（拆分重試）" "appstate_batch_split_done" "107"
				continue
			fi
			_restore_failed=$((_restore_failed+_chunk_count))
			_verify_failed=$((_verify_failed+_chunk_count))
			printf 'RESTORE\tchunk_%s\tTRANSPORT_OR_PROTOCOL_FAIL\tcode=%s name=%s packages=%s\n' \
				"$_idx" "${_APPSTATE_RESULT_CODE:-unknown}" "${_APPSTATE_RESULT_NAME:-unknown}" "$_chunk_count" >> "$TMPDIR/.appstate_restore_issues"
			_speed_debug_log "APPSTATE_RESTORE_CHUNK_FAIL idx=$_idx packages=$_chunk_count code=${_APPSTATE_RESULT_CODE:-unknown} name=${_APPSTATE_RESULT_NAME:-unknown}"
			rm -f "$_in" "$_ro" "$_vo" 2>/dev/null
			_offset=$((_offset+_chunk_size))
			_speedbackup_progress_step "$_offset" "$_count" "AppState 批次已完成（含失敗記錄）" "appstate_batch_fail_done" "107"
			continue
		fi
		local _verify_rc
		_root_appstate_call verifyAppStateBatch "$_in" "$_vo"
		_verify_rc=$?
		if _appstate_verify_batch_accept "$_vo" "$_verify_rc"; then
			_appstate_debug_aggregate save verify "$_idx" "$_in" "$_vo"
			if _appstate_ndjson_summarize "$_vo" verify "$TMPDIR/.appstate_verify_issues"; then
				_verify_ok=$((_verify_ok + _APPSTATE_NDJSON_OK))
				_verify_vendor=$((_verify_vendor + ${_APPSTATE_NDJSON_VENDOR:-0}))
				_verify_mismatch=$((_verify_mismatch + _APPSTATE_NDJSON_WARN))
				_verify_failed=$((_verify_failed + _APPSTATE_NDJSON_FAILED))
			else
				_verify_failed=$((_verify_failed + _chunk_count))
				printf 'VERIFY\tchunk_%s\tNDJSON_PARSE_FAIL\tpackages=%s\n' "$_idx" "$_chunk_count" >> "$TMPDIR/.appstate_verify_issues"
			fi
		else
			_verify_failed=$((_verify_failed+_chunk_count))
			printf 'VERIFY\tchunk_%s\tTRANSPORT_OR_PROTOCOL_FAIL\tpackages=%s\n' "$_idx" "$_chunk_count" >> "$TMPDIR/.appstate_verify_issues"
			_speed_debug_log "APPSTATE_VERIFY_CHUNK_FAIL idx=$_idx packages=$_chunk_count code=${_APPSTATE_RESULT_CODE:-unknown} name=${_APPSTATE_RESULT_NAME:-unknown}"
		fi
		rm -f "$_in" "$_ro" "$_vo" 2>/dev/null
		_offset=$((_offset+_chunk_size))
		_speedbackup_progress_step "$_offset" "$_count" "AppState 批次已完成" "appstate_batch_chunk_done" "107"
	done
	# r293: 不再送 AppState 結尾無進度 notification。
	# Android 部分 ROM 會把 restore 尾段的無進度 service notification 套 auto-template，顯示 service_notification_apply_auto_template_* 系統垃圾通知。
	# 最後一個 appstate_batch_chunk_done 已經送出 100% 進度，這裡只記 debug/終端摘要。
	_speed_debug_log "PROGRESS_STEP_SKIP tag=appstate_batch_done reason=chunk_done_already_final current=$_count total=$_count notify=none-no-template-r293"
	echoRgb "AppState恢復摘要: 成功=$_restore_ok 部分=$_restore_partial 失敗=$_restore_failed" "2"
	_speed_debug_log "APPSTATE_VERIFY_SUMMARY ok=$_verify_ok vendor_constrained=$_verify_vendor mismatch=$_verify_mismatch failed=$_verify_failed mode=r322-vendor-dex"
	if [[ $_verify_mismatch -gt 0 || $_verify_failed -gt 0 ]]; then
		echoRgb "AppState驗證摘要: 一致=$_verify_ok 廠商限制=$_verify_vendor 不一致=$_verify_mismatch 失敗=$_verify_failed（詳情見speed_debug）" "0"
	elif [[ $_verify_vendor -gt 0 ]]; then
		echoRgb "AppState驗證摘要: 一致=$_verify_ok 廠商限制=$_verify_vendor（非類原生/MIUI/HyperOS 常見，詳情見speed_debug）" "3"
	else
		echoRgb "AppState驗證摘要: 一致=$_verify_ok" "1"
	fi
	_appstate_ssaid_report_emit
	[[ -n ${SPEED_DEBUG_RUN_DIR:-} && -d ${SPEED_DEBUG_RUN_DIR:-} ]] && {
		[[ -s $TMPDIR/.appstate_restore_issues ]] && cp -f "$TMPDIR/.appstate_restore_issues" "$SPEED_DEBUG_RUN_DIR/appstate_restore_issues.log" 2>/dev/null
		[[ -s $TMPDIR/.appstate_verify_issues ]] && cp -f "$TMPDIR/.appstate_verify_issues" "$SPEED_DEBUG_RUN_DIR/appstate_verify_issues.log" 2>/dev/null
	}
	rm -f "$_queue" "$TMPDIR/.appstate_restore_issues" "$TMPDIR/.appstate_verify_issues" 2>/dev/null
	[[ $_restore_failed -eq 0 && $_verify_failed -eq 0 && $_verify_mismatch -eq 0 ]]
}

# 取得當前正在前台/後台運行的 app 列表
# 配合「後台應用忽略」設定, 跳過正在運行的 app 不備份/恢復。
# r80: 主選單前不再顯示前台/後台自檢；正式備份/恢復仍優先走 Dex/AppState foregroundStateBatch。
Background_application_list() {
	[[ $activity != false ]] || return 0
	[[ $Background_apps_ignore = true ]] || return 0
	if [[ ${_BACKGROUND_STATE_READY:-0} = 1 ]]; then
		return 0
	fi
	unset Backstage
	local _pkg_file="$TMPDIR/.foreground_state_pkgs_$$" _out="$TMPDIR/.foreground_state_out_$$" _run _fg _bg
	appinventory pkgName all 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} | awk 'NF==1 && $1 ~ /^[A-Za-z0-9_.-]+$/ {print $1}' > "$_pkg_file" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	if [[ -s $_pkg_file ]] && _root_appstate_call foregroundStateBatch "$_pkg_file" "$_out"; then
		Backstage="$(_appstate_ndjson_foreground_active_packages "$_out")"
		_run="$(printf '%s\n' "$Backstage" | awk 'NF{n++} END{print n+0}')"
		_fg="$_run"
		_bg=0
		_speed_debug_log "DEX_FOREGROUND_STATE_SIMPLE_DAEMON active_pkgs=$_run result=${_APPSTATE_RESULT_CODE:-unknown}/${_APPSTATE_RESULT_NAME:-unknown}"
		[[ -n ${SPEED_DEBUG_RUN_DIR:-} && -d ${SPEED_DEBUG_RUN_DIR:-} ]] && cp -f "$_out" "$SPEED_DEBUG_RUN_DIR/foreground_state.ndjson" 2>/dev/null
		_BACKGROUND_STATE_READY=1
	fi
	rm -f "$_pkg_file" "$_out" 2>/dev/null
	if [[ $Backstage = "" ]]; then
		# fallback：保留舊 dumpsys/am stack 路線，避免舊 Dex 或 ROM 限制時正式忽略前後台功能直接失效。
		Backstage="$(dumpsys activity activities 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} | awk -v uid="$user" '/ActivityRecord\{/{split($4,a,"/"); user=$3; pkg=a[1]; if(user~/^u[0-9]+$/ && pkg!~/\//){sub(/^u/,"",user); if(uid=="" || user==uid) if(!seen[user","pkg]++) print pkg}}')"
		if [[ $Backstage = "" ]]; then
			Backstage="$(am stack list 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} | awk -v uid="$user" '/taskId/&&!/unknown/{split($2,a,"/"); pkg=a[1]; user="unknown"; for(i=1;i<=NF;i++) if($i~/^userId=/){split($i,b,"="); user=b[2]; break} if(uid==""||user==uid) if(!seen[pkg]++) print pkg}')"
		fi
		[[ $Backstage != "" ]] && _BACKGROUND_STATE_READY=1
	fi
	if [[ $Backstage = "" ]]; then
		echoRgb "獲取當前前台/後台應用失敗" "0"
		unset Backstage
	fi
}

# r80: 主選單前不顯示前台/後台；進入備份/恢復後才用 Dex foregroundListJson 顯示更準確的前台應用名稱。
_action_foreground_dex_display() {
	local _action="$1" _in="$TMPDIR/.action_foreground_in_${$}_$RANDOM" _out="$TMPDIR/.action_foreground_out_${$}_$RANDOM" _line _label _pkg _shown _t0 _t1 _ms _safe_action
	[[ -n $_action ]] || _action="操作"
	_process_observer_top_status "action_foreground_${_action}" >/dev/null 2>&1 || true
	_t0="$(_speed_now_ms)"
	: > "$_in" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} || return 0
	if _root_appstate_call foregroundListJson "$_in" "$_out"; then
		_t1="$(_speed_now_ms)"; _ms=$((_t1-_t0))
		_line="$(jq -r '([.top[]?, .foreground[]?, .active[]?, .foreground_service[]?, .background[]?] | .[0] // empty) | [(.label // ""), (.packageName // "")] | @tsv' "$_out" 2>/dev/null | awk -F '\t' 'NF>=2 && $2!=""{print; exit}')"
		_label="${_line%%	*}"
		_pkg="${_line#*	}"
		[[ $_line = "$_pkg" ]] && _label=""
		_shown="$(jq -r '.counts.shown // 0' "$_out" 2>/dev/null | awk 'NR==1{print}')"
		case $_shown in ''|*[!0-9]*) _shown=0 ;; esac
		_safe_action="$(printf '%s' "$_action" | tr -cd 'A-Za-z0-9_一-龥')"
		[[ -z $_safe_action ]] && _safe_action="action"
		[[ -n ${SPEED_DEBUG_RUN_DIR:-} && -d ${SPEED_DEBUG_RUN_DIR:-} ]] && cp -f "$_out" "$SPEED_DEBUG_RUN_DIR/foreground_list_${_safe_action}.json" 2>/dev/null
		if [[ -n $_pkg ]]; then
			[[ -z $_label ]] && _label="$_pkg"
			echoRgb "前台應用：$_label ($_pkg)" "1"
			_speed_debug_log "ACTION_FOREGROUND_DEX_DISPLAY action=$_action pkg=$_pkg label=$_label shown=$_shown elapsedMs=$_ms result=${_APPSTATE_RESULT_CODE:-unknown}/${_APPSTATE_RESULT_NAME:-unknown}"
		else
			_speed_debug_log "ACTION_FOREGROUND_DEX_DISPLAY_MISS action=$_action shown=$_shown elapsedMs=$_ms result=${_APPSTATE_RESULT_CODE:-unknown}/${_APPSTATE_RESULT_NAME:-unknown}"
		fi
	else
		_t1="$(_speed_now_ms)"; _ms=$((_t1-_t0))
		_speed_debug_log "ACTION_FOREGROUND_DEX_DISPLAY_FAIL action=$_action elapsedMs=$_ms result=${_APPSTATE_RESULT_CODE:-unknown}/${_APPSTATE_RESULT_NAME:-unknown}"
	fi
	rm -f "$_in" "$_out" 2>/dev/null
	return 0
}


# r82: 預設桌面/Launcher 後置。
# 目的：桌面資料若太早恢復，當下尚未安裝的 App 圖標可能無法完整回填；因此輸出清單、備份順序、恢復順序都把預設 HOME package 放到最後。
_DEFAULT_HOME_PKG_CACHE="__unset__"
_DEFAULT_HOME_LABEL_CACHE=""
_DEFAULT_HOME_SOURCE_CACHE=""
_default_home_pkg_valid() {
	local _pkg="$1"
	case $_pkg in
	''|android|com.android.internal.app*|*/*|*[!A-Za-z0-9_.-]*) return 1 ;;
	esac
	case $_pkg in
	*.*) return 0 ;;
	*) return 1 ;;
	esac
}
_default_home_pkg_cmd_fallback() {
	local _u _pkg _line
	_u="${USER_ID:-${user:-0}}"
	command -v cmd >/dev/null 2>&1 || return 1
	_pkg="$(cmd role holders --user "$_u" android.app.role.HOME 2>/dev/null | awk 'NF{print; exit}')"
	if _default_home_pkg_valid "$_pkg"; then
		printf '%s\n' "$_pkg"
		return 0
	fi
	_line="$(cmd package resolve-activity --user "$_u" --brief -a android.intent.action.MAIN -c android.intent.category.HOME 2>/dev/null | awk 'NF{last=$0} END{print last}')"
	_pkg="$_line"
	case $_pkg in
	*/*) _pkg="${_pkg%%/*}" ;;
	esac
	case $_pkg in
	package:*) _pkg="${_pkg#package:}" ;;
	esac
	if _default_home_pkg_valid "$_pkg"; then
		printf '%s\n' "$_pkg"
		return 0
	fi
	return 1
}
_default_home_pkg_ensure() {
	if [[ ${_DEFAULT_HOME_PKG_CACHE:-__unset__} != __unset__ ]]; then
		return 0
	fi
	_DEFAULT_HOME_PKG_CACHE=""
	_DEFAULT_HOME_LABEL_CACHE=""
	_DEFAULT_HOME_SOURCE_CACHE=""
	local _in _out _pkg _label _source _resolver
	_in="$TMPDIR/.default_home_in_${$}_$RANDOM"
	_out="$TMPDIR/.default_home_out_${$}_$RANDOM"
	: > "$_in" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} || return 1
	if _root_appstate_call defaultHome "$_in" "$_out"; then
		_pkg="$(jq -r 'select(.recordType=="defaultHome") | select((.result.name // "") == "OK") | select((.isResolver // true) == false) | (.packageName // empty)' "$_out" 2>/dev/null | awk 'NF{print; exit}')"
		_label="$(jq -r 'select(.recordType=="defaultHome") | (.label // empty)' "$_out" 2>/dev/null | awk 'NF{print; exit}')"
		_source="$(jq -r 'select(.recordType=="defaultHome") | (.source // empty)' "$_out" 2>/dev/null | awk 'NF{print; exit}')"
		_resolver="$(jq -r 'select(.recordType=="defaultHome") | (.isResolver // false)' "$_out" 2>/dev/null | awk 'NF{print; exit}')"
		if ! _default_home_pkg_valid "$_pkg"; then
			_pkg=""
		fi
		[[ -n ${SPEED_DEBUG_RUN_DIR:-} && -d ${SPEED_DEBUG_RUN_DIR:-} ]] && cp -f "$_out" "$SPEED_DEBUG_RUN_DIR/default_home_last.json" 2>/dev/null
		if [[ -z $_pkg ]]; then
			_cmd_pkg="$(_default_home_pkg_cmd_fallback)" || _cmd_pkg=""
			if [[ -n $_cmd_pkg ]]; then
				_pkg="$_cmd_pkg"
				[[ -z $_label ]] && _label="$_pkg"
				_source="${_source:-dex_empty}+cmd_fallback"
			fi
		fi
		_DEFAULT_HOME_PKG_CACHE="$_pkg"
		_DEFAULT_HOME_LABEL_CACHE="$_label"
		_DEFAULT_HOME_SOURCE_CACHE="$_source"
		if [[ -n $_pkg ]]; then
			_speed_debug_log "DEFAULT_HOME_DEX_OK package=$_pkg label=$_label source=$_source"
		else
			_speed_debug_log "DEFAULT_HOME_DEX_EMPTY resolver=$_resolver source=$_source"
		fi
	else
		_speed_debug_log "DEFAULT_HOME_DEX_FAIL result=${_APPSTATE_RESULT_CODE:-unknown}/${_APPSTATE_RESULT_NAME:-unknown}"
	fi
	rm -f "$_in" "$_out" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	return 0
}

# r340: 預設輸入法 / default IME cache。Dex defaultIme 內部用 settings --user USER_ID get secure default_input_method 取值並補 label；tools settings 只作 fallback。
_DEFAULT_IME_PKG_CACHE="__unset__"
_DEFAULT_IME_LABEL_CACHE=""
_DEFAULT_IME_SOURCE_CACHE=""
_default_ime_pkg_valid() {
	local _pkg="$1"
	case $_pkg in
	''|android|com.android.internal.app*|*/*|*[!A-Za-z0-9_.-]*) return 1 ;;
	esac
	case $_pkg in *.*) return 0 ;; *) return 1 ;; esac
}
_default_ime_user_id() {
	local _u="${1:-${USER_ID:-${user:-0}}}"
	case $_u in ''|*[!0-9]*) _u="${USER_ID:-${user:-0}}" ;; esac
	case $_u in ''|*[!0-9]*) _u=0 ;; esac
	printf '%s\n' "$_u"
}
_default_ime_pkg_cmd_fallback() {
	local _u _raw _pkg
	_u="$(_default_ime_user_id "$1")"
	_raw="$(settings --user "$_u" get secure default_input_method 2>/dev/null)" || _raw=""
	case $_raw in ''|null|NULL)
		# 老 ROM 若 settings 不支援 --user，才退回 current-user CLI；不寫死 user 0。
		_raw="$(settings get secure default_input_method 2>/dev/null)" || return 1
		;;
	esac
	case $_raw in ''|null|NULL) return 1 ;; esac
	_pkg="${_raw%%/*}"
	if _default_ime_pkg_valid "$_pkg"; then
		printf '%s\n' "$_pkg"
		return 0
	fi
	return 1
}
_default_ime_pkg_ensure() {
	if [[ ${_DEFAULT_IME_PKG_CACHE:-__unset__} != __unset__ ]]; then
		return 0
	fi
	_DEFAULT_IME_PKG_CACHE=""
	_DEFAULT_IME_LABEL_CACHE=""
	_DEFAULT_IME_SOURCE_CACHE=""
	local _in _out _pkg _label _source _cmd_pkg _u
	_u="$(_default_ime_user_id)"
	# r340: Dex defaultIme primary。Dex 內部 exec settings --user USER_ID，tools settings 僅作 fallback。
	_in="$TMPDIR/.default_ime_in_${$}_$RANDOM"
	_out="$TMPDIR/.default_ime_out_${$}_$RANDOM"
	: > "$_in" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} || return 1
	if _root_appstate_call defaultIme "$_in" "$_out"; then
		_pkg="$(jq -r 'select(.recordType=="defaultIme") | select((.result.name // "") == "OK") | (.packageName // empty)' "$_out" 2>/dev/null | awk 'NF{print; exit}')"
		_label="$(jq -r 'select(.recordType=="defaultIme") | (.label // empty)' "$_out" 2>/dev/null | awk 'NF{print; exit}')"
		_source="$(jq -r 'select(.recordType=="defaultIme") | (.source // empty)' "$_out" 2>/dev/null | awk 'NF{print; exit}')"
		_default_ime_pkg_valid "$_pkg" || _pkg=""
		[[ -n ${SPEED_DEBUG_RUN_DIR:-} && -d ${SPEED_DEBUG_RUN_DIR:-} ]] && cp -f "$_out" "$SPEED_DEBUG_RUN_DIR/default_ime_last.json" 2>/dev/null
		if [[ -n $_pkg ]]; then
			_DEFAULT_IME_PKG_CACHE="$_pkg"
			_DEFAULT_IME_LABEL_CACHE="${_label:-$_pkg}"
			_DEFAULT_IME_SOURCE_CACHE="${_source:-dex_exec_settings}"
			_speed_debug_log "DEFAULT_IME_DEX_EXEC_OK user=$_u package=$_pkg label=${_DEFAULT_IME_LABEL_CACHE:-} source=${_DEFAULT_IME_SOURCE_CACHE:-} mode=r370"
			rm -f "$_in" "$_out" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
			return 0
		fi
		_speed_debug_log "DEFAULT_IME_DEX_EXEC_EMPTY user=$_u source=${_source:-unknown} result=${_APPSTATE_RESULT_CODE:-unknown}/${_APPSTATE_RESULT_NAME:-unknown} mode=r370"
	else
		_speed_debug_log "DEFAULT_IME_DEX_EXEC_FAIL user=$_u result=${_APPSTATE_RESULT_CODE:-unknown}/${_APPSTATE_RESULT_NAME:-unknown} mode=r370"
	fi
	rm -f "$_in" "$_out" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	# fallback：tools 端 settings 也必須吃相同 USER_ID，不寫死 0。
	_cmd_pkg="$(_default_ime_pkg_cmd_fallback "$_u")" || _cmd_pkg=""
	if [[ -n $_cmd_pkg ]]; then
		_DEFAULT_IME_PKG_CACHE="$_cmd_pkg"
		_DEFAULT_IME_LABEL_CACHE="$_cmd_pkg"
		_DEFAULT_IME_SOURCE_CACHE="settings_secure_fallback"
		_speed_debug_log "DEFAULT_IME_SETTINGS_OK user=$_u package=$_cmd_pkg source=settings_secure fallback=1 mode=r370"
	else
		_speed_debug_log "DEFAULT_IME_EMPTY user=$_u both=dex_exec_settings,settings_secure mode=r370"
	fi
	return 0
}
_applist_home_last_filter() {
	local _home="$1"
	awk -v home="$_home" '
	function pkg_of(line,    s,n,a) {
		s=line
		sub(/\r$/, "", s)
		sub(/^[ \t]+/, "", s)
		kind="line"
		if (s == "") return ""
		if (s ~ /^[#＃]/) {
			kind="comment"
			n=split(s, a, /[ \t]+/)
			if (n >= 2 && a[2] ~ /^[A-Za-z][A-Za-z0-9_]*(\.[A-Za-z0-9_]+)+$/) return a[2]
			return ""
		}
		kind="active"
		if (s ~ /^!play[ \t]+/) sub(/^!play[ \t]+/, "", s)
		else if (s ~ /^！play[ \t]+/) sub(/^！play[ \t]+/, "", s)
		else if (s ~ /^[!！]/) { sub(/^[!！]/, "", s); sub(/^[ \t]+/, "", s) }
		n=split(s, a, /[ \t]+/)
		if (n >= 2 && a[2] ~ /^[A-Za-z][A-Za-z0-9_]*(\.[A-Za-z0-9_]+)+$/) return a[2]
		return ""
	}
	{
		line=$0
		sub(/\r$/, "", line)
		if (line == "") next
		kind="line"
		pkg=pkg_of(line)
		if (kind == "active" && pkg != "") key="A:" pkg
		else key="L:" line
		if (seen[key]++) next
		if (home != "" && pkg == home) { hc++; h[hc]=line; next }
		print line
	}
	END { for (i=1; i<=hc; i++) print h[i] }
	'
}

_applist_home_last_file() {
	local _file="$1" _context="${2:-applist}" _home _tmp
	[[ -f $_file ]] || return 0
	_default_home_pkg_ensure
	_home="${_DEFAULT_HOME_PKG_CACHE:-}"
	_tmp="$TMPDIR/.applist_home_last_${$}_$RANDOM"
	_applist_home_last_filter "$_home" < "$_file" > "$_tmp" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} && cat "$_tmp" > "$_file"
	rm -f "$_tmp" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	[[ -n $_home ]] && _speed_debug_log "APPLIST_HOME_LAST context=$_context package=$_home label=${_DEFAULT_HOME_LABEL_CACHE:-} file=$_file"
	return 0
}

_applist_home_last_text() {
	local _context="${2:-applist_text}" _home
	_default_home_pkg_ensure
	_home="${_DEFAULT_HOME_PKG_CACHE:-}"
	printf '%s\n' "$1" | _applist_home_last_filter "$_home"
	[[ -n $_home ]] && _speed_debug_log "APPLIST_HOME_LAST context=$_context package=$_home label=${_DEFAULT_HOME_LABEL_CACHE:-} source=text"
	return 0
}

# ======================================================
# 備份/恢復主入口共用 Dex/AppState 能力契約提示。
_appstate_require_main_capabilities() {
	local _action="$1" _kind _stage _detail _hint
	_appstate_capabilities_check && return 0
	_kind="${_APPSTATE_CAPABILITY_FAIL_KIND:-unknown}"
	_stage="${_APPSTATE_CAPABILITY_FAIL_STAGE:-unknown}"
	_detail="${_APPSTATE_CAPABILITY_FAIL_DETAIL:-}"
	_hint="${_APPSTATE_CAPABILITY_FAIL_HINT:-}"
	case "$_kind" in
	native_binary)
		echoRgb "配套 native 二進制 / AF_UNIX relay 不可用，已中止應用$_action" "0"
		echoRgb "不是單純 Dex capability 缺失；目前判定在 unixsock/filewatch/procwait/netwatch/uidexec 等配套二進制、linker/RELRO、ABI、權限或 SHA 驗證鏈。stage=$_stage" "3"
		;;
	dex_runtime)
		echoRgb "Dex RootDaemon / AppState transport 啟動失敗，已中止應用$_action" "0"
		echoRgb "AF_UNIX relay 基本可用，但 classes.dex、app_process、RootDaemon 啟動或 AppState namespace 沒正常回應。stage=$_stage" "3"
		;;
	dex_appstate)
		echoRgb "Dex AppState 執行錯誤，已中止應用$_action" "0"
		echoRgb "RootDaemon 有回應，但 AppState capabilities 回傳非 OK；偏向 classes.dex 混版、Dex runtime 例外或 AppState command 內部錯誤。stage=$_stage" "3"
		;;
	dex_contract)
		echoRgb "Dex/AppState capability 契約不匹配，已中止應用$_action" "0"
		echoRgb "這是 Dex/classes.dex 與 tools.sh 版本或 capability 不一致，不是 native 二進制 linker 問題。stage=$_stage" "3"
		;;
	*)
		echoRgb "Dex/AppState 能力檢查失敗，已中止應用$_action" "0"
		echoRgb "無法明確歸類為 Dex 或 native 配套二進制；請直接查看 speed_debug 內 APPSTATE_CAPABILITIES_DIAG、root_daemon_stderr.log、appstate_capabilities*.json。stage=$_stage" "3"
		;;
	esac
	[[ -n $_detail ]] && echoRgb "診斷：$_detail" "3"
	[[ -n $_hint ]] && echoRgb "建議：$_hint" "3"
	echoRgb "需要 AppInventory、snapshot/restore/verify、foreground/defaultHome、ProcessObserver/cgroup freezer、display power、WebDAV/SMB 等核心 capability；不再鎖死精確 Dex 版本或 build 字串" "3"
	return 1
}

# backup() 主函數
# ======================================================
# 主備份函數 - 對 appList.txt 內所有 app 執行完整備份
# 流程: 讀清單 → 逐個 app → 備份 apk + data + user_de + obb → 保存 canonical AppState
# 結尾備份 wifi、生成 start.sh、設置 REMOTE_TRIGGER=1 觸發遠端上傳
# ===== 備份主流程、媒體與統計 =====
backup() {
	self_test
	if ! _appstate_require_main_capabilities "備份"; then
		_speed_debug_normal_finish_pack 2
		exit 2
	fi
	_action_foreground_dex_display "備份"
	case $MODDIR in
	/storage/emulated/0/Android/* | /data/media/0/Android/* | /sdcard/Android/*) echoRgb "請勿在$MODDIR內備份" "0" && exit 2 ;;
	esac
	case $Compression_method in
	zstd | Zstd | ZSTD | tar | Tar | TAR) ;;
	*) echoRgb "$Compression_method為不支持的壓縮算法" "0" && exit 2 ;;
	esac
	# 流式上傳路徑快取: 在 Compression_method 還未被 Backup_data() 暫時污染前固定一次
	_BACKUP_DIRNAME_CACHED="$(get_backup_dirname)"
	_prepare_timed prepare_pkg_uid_map
	_prepare_timed prepare_pkg_ver_map
	_prepare_timed prepare_pkg_apk_path_map
	load_kv_map "$TMPDIR/.pkg_uid" _pu
	load_kv_map "$TMPDIR/.pkg_ver" _pv
	: > "$TMPDIR/.backup_done"
	: > "$TMPDIR/.update_apks"
	: > "$TMPDIR/.add_apks"
	: > "$TMPDIR/.changed_apps"
	: > "$TMPDIR/.listver_changed"
	# 初始化備份變更標記
	backup_has_changes=0
	#校驗選填是否正確
	[[ $Backup_Mode != "" ]] && isBoolean "$Backup_Mode" "Backup_Mode" && Backup_Mode="$nsx" || {
	echoRgb "選擇備份模式\n -音量上備份應用+數據，音量下僅應用不包含數據" "2"
	get_version "應用+數據" "僅應用"; Backup_Mode="$branch"
	}
	if [[ $Backup_Mode = true ]]; then
		if [[ -n $(printf "%s\n" "$blacklist" | awk '!/[#＃]/ && NF') ]]; then
			if [[ $blacklist_mode != "" ]]; then
				isBoolean "$blacklist_mode" "blacklist_mode" && blacklist_mode="$nsx"
			else
				echoRgb "選擇黑名單模式\n -音量上不備份，音量下僅備份安裝檔\n -警告! " "2"
				get_version "不備份" "備份安裝檔"; blacklist_mode="$branch"
			fi
		fi
	fi
	if [[ $Backup_Mode = true ]]; then
		[[ $Backup_obb_data != "" ]] && isBoolean "$Backup_obb_data" "Backup_obb_data" && Backup_obb_data="$nsx" || {
		echoRgb "是否備份外部數據 即比如原神的數據包\n -音量上備份，音量下不備份" "2"
		get_version "備份" "不備份"; Backup_obb_data="$branch"
		}
		[[ $Backup_user_data != "" ]] && isBoolean "$Backup_user_data" "Backup_user_data" && Backup_user_data="$nsx" || {
		echoRgb "是否備份使用者數據\n -音量上備份，音量下不備份" "2"
		get_version "備份" "不備份"; Backup_user_data="$branch"
		}
	else
		Backup_user_data="false"
		Backup_obb_data="false"
	fi
	[[ $backup_media != "" ]] && isBoolean "$backup_media" "backup_media" && backup_media="$nsx" || {
	echoRgb "全部應用備份結束後是否備份自定義目錄\n -音量上備份，音量下不備份" "2"
	get_version "備份" "不備份"; backup_media="$branch"
	}
	[[ $setDisplayPowerMode != "" ]] && isBoolean "$setDisplayPowerMode" "setDisplayPowerMode" && setDisplayPowerMode="$nsx" || {
	echoRgb "應用備份開始後關閉螢幕\n -音量上關閉，音量下不關閉" "2"
	get_version "關閉" "不關閉"; setDisplayPowerMode="$branch"
	}
	[[ $Background_apps_ignore != "" ]] && isBoolean "$Background_apps_ignore" "Background_apps_ignore" && Background_apps_ignore="$nsx" || {
	echoRgb "存在進程忽略備份\n -音量上忽略，音量下備份" "2"
	get_version "忽略" "備份"; Background_apps_ignore="$branch"
	}
	i=1
	#數據目錄
	if [[ $list_location != "" ]]; then
		if [[ ${list_location:0:1} = / ]]; then
			txt="$list_location"
		else
			txt="$MODDIR/$list_location"
		fi
	else
		txt="$MODDIR/appList.txt"
	fi
	txt_path="$txt"
	[[ ! -f $txt ]] && echoRgb "請執行start.sh獲取應用列表再來備份" "0" && exit 1
	TXT_NAME="${txt##*/}"
	case ${TXT_NAME##*.} in
	txt) ;;
	*) echoRgb "$txt不是腳本讀取格式" "0" && exit 2 ;;
	esac
	_applist_home_last_file "$txt" "backup_source"
	_applist_sanitize_backup_guide_lines "$txt"
	data="$MODDIR"
	hx="本地"
	echoRgb "腳本受到內核機制影響 息屏後IO性能嚴重影響\n -請勿關閉終端或是息屏備份 如需終止腳本\n -請執行start.sh選擇終止腳本即可停止" "3"
	SPEEDBACKUP_DEFER_REMOTE_SETUP=1
	backup_path
	unset SPEEDBACKUP_DEFER_REMOTE_SETUP
	show_conf backup
	remote_stream_early_hard_precheck
	D="1"
	Apk_info="$(_installed_app_packages "$user")"
	[[ $Apk_info = "" ]] && echoRgb "Apk_info變量為空" "0" && exit
	[[ ! -f ${0%/*}/app_details.json ]] && {
	echoRgb "檢查備份列表中是否存在已經卸載應用" "3"
	while read -r ; do
		if [[ $(echo "$REPLY" | sed -E 's/^[ \t]*//; /^[ \t]*[#＃!]/d') != "" ]]; then
			_list_name="${REPLY%% *}"
			_list_pkg="${REPLY#* }"
			_list_pkg="${_list_pkg%% *}"
			if [[ $_list_name != "" && $_list_pkg != "" && $_list_pkg != "$REPLY" ]]; then
				if [[ $(echo "$Apk_info" | awk -v pkg="$_list_pkg" '$1 == pkg {print $1}') != "" ]]; then
					[[ $Tmplist = "" ]] && Tmplist="$REPLY" || Tmplist="$Tmplist\n$REPLY"
				else
					echoRgb "$REPLY不存在系統，從列表中刪除" "0"
				fi
			fi
		else
			Tmplist="$Tmplist\n$REPLY"
		fi
	done < "$txt"
	}
	[[ $Update_backup = true ]] && {
	echoRgb "檢查備份列表中已經更新應用" "3"
	# 用暫存檔取代 here-string (mksh 不支援 <<<)
	local _upd_tmp="$TMPDIR/.update_check_$$"
	grep -Ev '^[#＃!]' "$txt" | awk '{print $1 ":" $2}' > "$_upd_tmp"
	# 預掃 pkg→version map (若還沒掃過), 取代每 app fork pm
	[[ ! -f $TMPDIR/.pkg_ver ]] && prepare_pkg_ver_map
	while read -r apk; do
		_apk_label="${apk%%:*}"
		_apk_pkg="${apk#*:}"
		_safe_apk_label="$(_backup_path_safe_name "$_apk_label" "$_apk_pkg")"
		Backup_folder="$Backup/$_safe_apk_label"
		app_details="$Backup_folder/app_details.json"
		if [[ -d $Backup_folder ]]; then
			# 讀本地同步副本 (流式模式上傳成功後 cp 到本地, 記錄上次成功備份的版本)
			# 與實機比對才有意義; 遠端快取是給 apk 跳過比對用的, 職責不同
				apk_version="$(_appdetails_get_first_apk_version "$app_details" | tr -d ' \t\r\n')"
			# 從預掃 map 查 versionCode (取代每 app fork pm)
			local _pkg
			_pkg="$_apk_pkg"
			apk_version2="$(get_current_apk_version_code "$_pkg")"
			# debug: 比對版本失敗時印出來。map/fallback 仍命中失敗時，不把空值當版本變化，避免誤觸發整批重備 APK。
			if [[ -z $apk_version2 || $apk_version2 = unknown ]]; then
				echoRgb "${apk%%:*} 當前版本讀取失敗，略過版本變化判斷" "0"
				SpeedDebug_log "WARN: update_backup_version_map_miss package=$_pkg oldVersion=$apk_version"
			elif [[ $apk_version != $apk_version2 ]]; then
				echoRgb "$(echo "$apk" | cut -d':' -f1) 版本變化: $apk_version → $apk_version2" "3"
				_safe_apk_line="$_safe_apk_label $_pkg"
				[[ $Tmplist2 = "" ]] && Tmplist2="$_safe_apk_line" || Tmplist2="$Tmplist2\n$_safe_apk_line"
				# 記錄包名: 本輪強制重備 apk (遠端 json 可能被失敗輪汙染成新版本號而 apk 仍是舊檔)
				echo "$_pkg" >> "$TMPDIR/.listver_changed"
			fi

		fi
	done < "$_upd_tmp"
	rm -f "$_upd_tmp"
	}
	[[ $Tmplist != ""  ]] && { echo "$Tmplist" | sed -e '/^$/d' | sort>"$txt"; _applist_home_last_file "$txt" "backup_installed_filter"; }
	if [[ $Tmplist2 != "" ]]; then
		txt="$(_applist_home_last_text "$(echo "$Tmplist2" | sort)" "backup_update_only")"
	else
		[[ $Update_backup != "" ]] && echoRgb "應用目前無更新" "0" && exit 0
	fi
	if [[ ! -f $txt ]]; then
		[[ $(echo "$txt") != "" ]] && txt="$(_applist_home_last_text "$(echo "$txt" | sed -e '/^$/d')" "backup_effective_text")"
	else
		txt="$(_applist_home_last_text "$(grep -Ev '#|＃' "$txt" | sed -e '/^$/d')" "backup_effective_file")"
	fi
	r="$(echo "$txt" | awk 'NF != 0 { count++ } END { print count }')"
	[[ -f ${0%/*}/app_details.json ]] && r=1
	[[ $r = "" && ! -f ${0%/*}/app_details.json ]] && echoRgb "$MODDIR_NAME/appList.txt是空的或是包名被注釋備份個鬼\n -檢查是否注釋亦或者執行$MODDIR_NAME/start.sh" "0" && exit 1
	if [[ $Backup_Mode = true ]]; then
		[[ $Backup_user_data = false ]] && echoRgb "當前$MODDIR_NAME/backup_settings.conf的\n -Backup_user_data=0將不備份user數據" "0"
		[[ $Backup_obb_data = false ]] && echoRgb "當前$MODDIR_NAME/backup_settings.conf的\n -Backup_obb_data=0將不備份外部數據" "0"
	fi
		[[ $backup_media = false ]] && echoRgb "當前$MODDIR_NAME/backup_settings.conf的\n -backup_media=0將不備份自定義資料夾" "0"
		if stream_enabled; then
			_speed_debug_log "APPDETAILS_BUNDLE_ONLY_NOTICE stage=backup_stream mode=no-fallback-r286 rel=$(_appdetails_bundle_rel)"
			# 真流式不建立本地 Backup_zstd_X；但仍需要一份本輪恢復清單。
			# 因此 appList.txt / start.sh / restore_settings.conf 只放 TMPDIR staging，
			# 結束時由 stream_upload_infra() 上傳到遠端根目錄。
			mkdir -p "$TMPDIR/.stream_stage/.infra" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
			txt2="$TMPDIR/.stream_stage/.infra/appList.txt"
			STREAM_APPLIST_PATH="$txt2"
		else
			# 首次本地備份時 Backup_zstd_X 尚不存在；必須先建立根目錄，
			# 再寫 appList.txt / tools / start.sh / restore_settings.conf，避免首輪 No such file or directory。
			if [[ ! -d $Backup ]]; then
				mkdir -p "$Backup" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} || {
					echoRgb "建立備份目錄失敗: $Backup" "0"
					return 1
				}
			fi
			txt2="$Backup/appList.txt"
			unset STREAM_APPLIST_PATH
		fi
		txt_path2="$txt2"
		[[ ! -f $txt2 ]] && echo "#不需要恢復還原的應用請在開頭使用#注釋 比如：#酷安 com.coolapk.market">"$txt2"
		txt2="$(cat "$txt2")"
		if ! stream_enabled; then
			[[ ! -d $Backup/tools ]] && cp -r "$tools_path" "$Backup"
			[[ ! -f $Backup/start.sh ]] && touch_shell "2" "$Backup/start.sh"
			[[ ! -f $Backup/restore_settings.conf ]] && update_Restore_settings_conf>"$Backup/restore_settings.conf"
			if [[ -d $Backup/tools ]]; then
				find "$Backup/tools" -maxdepth 1 -type f | while read -r; do
					Tools_FILE_NAME="${REPLY##*/}"
					if [[ -f $tools_path/$Tools_FILE_NAME ]]; then
						filesha256="$(sha256sum "$tools_path/$Tools_FILE_NAME" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} | cut -d" " -f1)"
						filesha256_1="$(sha256sum "$REPLY" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} | cut -d" " -f1)"
						if [[ $filesha256 != $filesha256_1 ]]; then
							cp -r "$tools_path/$Tools_FILE_NAME" "$REPLY"
							echoRgb "更新$REPLY"
						fi
					fi
				done
			fi
			filesize="$(calc_dir_size "$Backup")"
		else
			filesize=0
		fi
	Quantity=0
	#開始循環$txt內的資料進行備份
	#記錄開始時間
	en=118
	osn=0; osj=0; osk=0
	#獲取已經開啟的無障礙
	var="$(settings get secure enabled_accessibility_services 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null})"
	#獲取預設鍵盤
	keyboard="$(settings get secure default_input_method 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null})"
	Set_screen_pause_seconds on
	[[ $txt != "" ]] && [[ $(echo "$txt" | cut -d' ' -f2 | grep -w "^${keyboard%/*}$") != ${keyboard%/*} ]] && unset keyboard
	if [[ -f ${0%/*}/app_details.json ]]; then
		# 單獨備份模式: 只預掃這一個 app 的權限
		local _single_pkg
		_single_pkg="$(_appdetails_get_first_pkg "${0%/*}/app_details.json")"
		# 單獨備份也走批量同一套預掃/解析邏輯，避免 inline jq 解析差異導致 permissions 漏寫。
		if _prepare_timed prepare_app_state_prescan_batch "$_single_pkg"; then
			:
		else
			echoRgb "AppState snapshot 預掃失敗，已中止單獨應用備份；不回退舊位置性預掃" "0"
			_speed_debug_normal_finish_pack 2
			exit 2
		fi
		_prepare_timed prepare_dir_size_map "$_single_pkg"
		load_dir_size_map
		_backup_remote_prescan_progress_step 0 "正在預掃遠端"
		_backup_remote_prescan_progress_step 1 "正在預掃遠端備份大小"
		backup_finalize_remote_setup_if_deferred
		_backup_remote_prescan_progress_step 2 "遠端連線 / 容量預掃完成"
		_prepare_timed prepare_remote_filelist
		_backup_remote_prescan_progress_step 3 "遠端檔案列表預掃完成"
		_prepare_timed prepare_remote_json_map
		_backup_remote_prescan_progress_step 4 "遠端 app_details 預掃完成"
		_prepare_timed prepare_remote_fast_skip_map
		_backup_remote_prescan_progress_step 5 "遠端預掃完成"
		_prepare_timed prepare_local_fast_skip_map
		[[ -s $TMPDIR/.pkg_appstate ]] || { echoRgb "AppState snapshot map缺失" "0"; exit 2; }
	else
		if _prepare_timed prepare_app_state_prescan_batch; then
			:
		else
			echoRgb "AppState snapshot 預掃失敗，已中止應用備份；不回退舊位置性預掃" "0"
			_speed_debug_normal_finish_pack 2
			exit 2
		fi
		_prepare_timed prepare_dir_size_map
		load_dir_size_map
		_backup_remote_prescan_progress_step 0 "正在預掃遠端"
		_backup_remote_prescan_progress_step 1 "正在預掃遠端備份大小"
		backup_finalize_remote_setup_if_deferred
		_backup_remote_prescan_progress_step 2 "遠端連線 / 容量預掃完成"
		_prepare_timed prepare_remote_filelist
		_backup_remote_prescan_progress_step 3 "遠端檔案列表預掃完成"
		_prepare_timed prepare_remote_json_map
		_backup_remote_prescan_progress_step 4 "遠端 app_details 預掃完成"
		_prepare_timed prepare_remote_fast_skip_map
		_backup_remote_prescan_progress_step 5 "遠端預掃完成"
		_prepare_timed prepare_local_fast_skip_map
		[[ -s $TMPDIR/.pkg_appstate ]] || { echoRgb "AppState snapshot map缺失" "0"; exit 2; }
	fi
	_backup_prescan_show_summary || true
	starttime1="$(date -u "+%s")"
	TIME="$starttime1"
	notification_progress "101" "$r" 0 "開始備份"
	# 保存本次備份實際使用的清單,供遠端上傳用 (純變數,不寫檔)
	# 子目錄 backup.sh (app_details.json 存在於 0%/*) 只備份單一 app,
	# 上傳時也只該上傳這一個 app 的目錄
	if [[ -n $remote_type ]]; then
		if [[ -f ${0%/*}/app_details.json ]]; then
			# 單獨備份: REMOTE_APPLIST 只設這個 app
			# ${0%/*} 是子目錄路徑, 末段就是 app 名 (例 Chrome)
			_app_dirname="${0%/*}"
			REMOTE_APPLIST="${_app_dirname##*/}"
			unset _app_dirname
		elif [[ -n $txt ]]; then
			REMOTE_APPLIST="$txt"
		fi
	fi
	_stream_fast_skip_collapse_applist
	_local_fast_skip_collapse_applist
	_webdav_stream_prepare_app_dirs_from_txt
	_smb_stream_prepare_app_dirs_from_txt
	_speedbackup_progress_hint "正在啟動備份守護 session（live-safe：只守護當前 App）" "backup_batch_guard_prewarm"
	_cgroup_freezer_batch_daemon_ensure "backup-batch" || true
	_process_observer_guard_hint_once "backup-batch" || true
	_process_observer_batch_start_backup || true
	while [[ $i -le $r ]]; do
		if [[ $remote_stream = 1 && -n $remote_type ]] && _remote_netwatch_mark_stream_fatal "app_loop_top" "netwatch"; then
			echoRgb "遠端 LAN 路由／位址已變更，停止本輪後續應用備份" "0"
			_speed_debug_log "REMOTE_NETWATCH_ABORT_APP_LOOP i=$i total=$r $(_remote_stream_fatal_summary)"
			break
		fi
		if [[ $remote_stream = 1 && -n $remote_type ]] && _remote_stream_fatal_active; then
			echoRgb "遠端流式已中斷，停止本輪後續應用備份" "0"
			_speed_debug_log "REMOTE_STREAM_FATAL_ABORT_APP_LOOP i=$i total=$r $(_remote_stream_fatal_summary)"
			break
		fi
		[[ $en -ge 229 ]] && en=118
		unset name1 name2 apk_path apk_path2
		if [[ ! -f ${0%/*}/app_details.json ]]; then
			# 一次 sed 抓行, 用 parameter expansion 拆欄位 (省 3 fork)
			_line="$(echo "$txt" | sed -n "${i}p")"
			name1="${_line%% *}"
			name2="${_line#* }"
			name2="${name2%% *}"
			unset _line
		else
			ChineseName="$(_appdetails_get_first_entry_name "${0%/*}/app_details.json")"
			PackageName="$(_appdetails_get_first_pkg "${0%/*}/app_details.json")"
			name1="$ChineseName"
			name2="$PackageName"
		fi
		[[ $name2 = "" || $name1 = "" ]] && echoRgb "警告! appList.txt應用包名獲取失敗，可能修改有問題" "0" && exit 1
		apk_path="$(get_current_apk_paths "$name2")"
		apk_path2="${apk_path%%$'\n'*}"
		apk_path2="${apk_path2%/*}"
		if [[ -d $apk_path2 ]]; then
			echoRgb "備份第$i/$r個應用 剩下$((r - i))個" "3"
			echoRgb "備份 $name1" "2"
			notification_progress "101" "$r" "$((i - 1))" "備份第$i/$r個應用 剩下$((r - i))個
備份 $name1"
			unset Backup_folder ChineseName PackageName nobackup No_backupdata result apk_version apk_version2  zsize zmediapath Size data_path Ssaid ssaid
			nobackup="false"
			Background_application_list
			if [[ $Backstage != "" ]] && printf '%s\n' "$Backstage" | awk -v p="$name2" '$0==p{found=1} END{exit !found}'; then
				echoRgb "$name1存在前台/後台，忽略備份" "0"
				nobackup="true"
			fi
			if [[ $Backup_Mode = true ]]; then
				if [[ $name1 = !* || $name1 = ！* ]]; then
					name1="${name1//!/}"
					name1="${name1//！/}"
					echoRgb "跳過備份所有數據" "0"
					No_backupdata=1
				fi
				if [[ $(echo "$blacklist" | grep -w "^$name2$") = $name2 ]]; then
					if [[ $blacklist_mode = true ]]; then
						echoRgb "黑名單應用跳過備份" "0"
						nobackup="true"
					else
						echoRgb "黑名單應用跳過備份所有數據" "0"
					fi
					No_backupdata=1
				fi
			fi
				_backup_path_sanitize_current_name
				Backup_folder="$Backup/$name1"
				app_details="$Backup_folder/app_details.json"
				# 流式模式: 設遠端目標目錄 (鏡像 $name1), 遠端目錄由 _stream_upload 自動建
				# 用 TMPDIR 暫存區取代本機 $Backup (不碰用戶既有本地備份, 結束無需大清理)
				if [[ $remote_stream = 1 && -n $remote_type ]]; then
					_STREAM_DEST="$name1"
					Backup_folder="$TMPDIR/.stream_stage/$name1"
					app_details="$Backup_folder/app_details.json"
				fi
				_app_fast_skipped=0
				if [[ $remote_stream = 1 && -n $remote_type && $nobackup != true ]] && _remote_app_fast_skip_ok "$name1"; then
					starttime2="$(date -u "+%s")"
					result=0
					_backup_mark_done_pkg
					let osj++
					echoRgb "整個應用無變化(遠端備份無變化) 快速跳過" "2"
					_speed_debug_log "STREAM_APP_FAST_SKIP_UNCHANGED app=$name1 package=$name2 source=fast_prescan"
					# r277: single-stage bundle 直接保留未變更 App 的舊 JSON，避免整包覆蓋後遺失 metadata。
					_remote_json_file="$(_appdetails_bundle_remote_json_path "$name1")"
					[[ -s $_remote_json_file ]] && _appdetails_bundle_stage_one "$name1" "$name2" "$_remote_json_file" || true
					endtime 2 "$name1 備份" "3"
					_app_fast_skipped=1
				fi
				if [[ $_app_fast_skipped != 1 ]]; then
    				if [[ $remote_stream = 1 && -n $remote_type ]]; then
    					# 每 app 先清空 staging (防上輪殘留), 再無條件以遠端 json 快取為種:
    					# 1. 權限/SSAID/installer/版本比對有舊值參照, 無變化正確跳過
    					# 2. 本輪只更新部分欄位時, 其餘欄位 (如版本) 不會在上傳時被覆蓋丟失
    					rm -rf "$Backup_folder" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
    					mkdir -p "$Backup_folder" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
    					_remote_json_file="$(_appdetails_bundle_remote_json_path "$name1")"
    					[[ -s $_remote_json_file ]] && \
    					cp "$_remote_json_file" "$app_details" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
    					# 種子可能是舊版/從未經過新增分支寫入的 json, 缺 PackageName 會導致流式恢復失敗;
    					# 在此補上 (不影響其他欄位, 用 jq 確認該 key 存在才寫, 避免空 json 結構錯誤)
    					if [[ -s $app_details ]] && [[ "$(_appdetails_get_entry_string "$app_details" "$name1" PackageName)" = "" ]]; then
    					    _appdetails_ensure_package_name "$app_details" "$name1" "$name2" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
    					fi
    				fi
    			fi
			# 一次讀取 app_details.json 的 APK／包名／時間／大小欄位；App 狀態只讀 app_state
			# 取代後續每個函數內各自 fork jq
			app_details_read "$app_details"
			if [[ -f $app_details ]]; then
				PackageName="$PKG_NAME"
				[[ $PackageName != $name2 ]] && _appdetails_sync_package_name_all "$app_details" "$name2"
				echoRgb "上次備份時間$(time_ago "$BACKUP_TIME")"
			fi
			[[ $hx = USB && $PT = "" ]] && echoRgb "隨身碟意外斷開 請檢查穩定性" "0" && exit 1
			starttime2="$(date -u "+%s")"
			[[ $name2 = com.tencent.mobileqq ]] && echoRgb "QQ可能恢復備份失敗或是丟失聊天記錄，請自行用你信賴的應用備份" "0"
			[[ $name2 = com.tencent.mm ]] && echoRgb "WX可能恢復備份失敗或是丟失聊天記錄，請自行用你信賴的應用備份" "0"
			# 算 apk_path 有幾行 (省 echo|wc -l)
			apk_number=1
			case $apk_path in
			*$'\n'*) apk_number=$(echo "$apk_path" | wc -l) ;;
			esac
			if [[ $nobackup != true ]]; then
				# r266: 使用者明確標記「跳過備份所有數據」的 APK-only App，不需要啟動 quiesce / ProcessObserver / uid-netblock。
				# 這類項目只備份 APK 與 metadata；保留真正 data/user/obb 備份項目的喚醒守護。
				if [[ ${No_backupdata:-} = 1 ]]; then
					_speed_debug_log "APP_SCOPE_GUARD_SKIP_NO_DATA pkg=$name2 label=$name1 stage=backup_app_scope reason=no_backupdata_apk_only"
				# r240: auto/smart 下只有硬編碼高風險 App 先走 cgroup v2；其他 App 預設瞬殺/force-stop fallback。
				# tar-scope freeze 成功時不做入口暫停，避免 launcher 狀態被改動。
				elif [[ $name2 != bin.mt.plus ]]; then
					KILL_APP_UNSAFE_SKIP=0
					_speed_debug_log "PROGRESS_HINT_SUPPRESS_ONCE_ONLY tag=backup_guard_start app=$name1 package=$name2 msg=正在啟動備份守護"
					case "${SPEEDBACKUP_CGROUP_FREEZER:-auto}" in
					all|full|on|enable|enabled|1|true|TRUE) _cgroup_freezer_start_app "$name2" "$name1" "backup_app_scope" || true ;;
					none|off|disable|disabled|0|false|FALSE) _speed_debug_log "CGROUP_FREEZER_FAST_SKIP pkg=$name2 label=$name1 stage=backup_app_scope policy=${SPEEDBACKUP_CGROUP_FREEZER:-auto} reason=policy_off" ;;
					*)
						if { _speedbackup_hard_freeze_pkg "$name2" || _speedbackup_cgroup_fast_settle_pkg "$name2"; } && { ! _pkg_is_quiesce_never_pause "$name2" || _speedbackup_cgroup_fast_settle_default_home_pkg "$name2" || _speedbackup_cgroup_fast_settle_default_ime_pkg "$name2"; }; then
							if _speedbackup_cgroup_fast_settle_default_ime_pkg "$name2"; then _speed_debug_log "BACKUP_POLICY_DEFAULT_IME package=$name2 label=$name1 action=cgroup-first mode=r370"; fi
							_cgroup_freezer_start_app "$name2" "$name1" "backup_app_scope" || true
						else
							_speed_debug_log "CGROUP_FREEZER_FAST_SKIP pkg=$name2 label=$name1 stage=backup_app_scope policy=${SPEEDBACKUP_CGROUP_FREEZER:-auto} reason=non_hardcoded_or_fast_settle_app"
						fi ;;
					esac
					if [[ -n ${CGROUP_FREEZER_APP_TOKEN:-} && ${CGROUP_FREEZER_APP_PKG:-} = "$name2" ]]; then
						_speed_debug_log "CGROUP_GUARD_ACTIVE_SKIP_FALLBACK pkg=$name2 label=$name1 stage=backup_app_scope token=${CGROUP_FREEZER_APP_TOKEN:-} iconGrey=false"
					else
						kill_app
						if [[ $? = 125 || $KILL_APP_UNSAFE_SKIP = 1 ]]; then
							echoRgb "$name1 因存活/系統綁定狀態跳過資料備份，但仍會按既有規則處理 APK/metadata" "0"
							_speed_debug_log "APP_SCOPE_QUIESCE_UNSAFE app=$name1 package=$name2 stage=before_apk"
						else
							_speed_debug_log "QUIESCE_ENTRY_CGROUP_ONLY pkg=$name2 label=$name1 reason=backup_app_scope_fallback iconGrey=false"
						fi
					fi
					case "${SPEEDBACKUP_UID_NETBLOCK_POLICY:-smart}" in
					all|full|on|enable|enabled) _uid_netblock_start_app "$name2" "$name1" "backup_app_scope" || true ;;
					none|off|disable|disabled) _speed_debug_log "UID_NET_BLOCK_FAST_SKIP pkg=$name2 label=$name1 stage=backup_app_scope policy=${SPEEDBACKUP_UID_NETBLOCK_POLICY:-smart} reason=policy_off" ;;
					*)
						if _process_observer_high_risk_pkg "$name2"; then
							_uid_netblock_start_app "$name2" "$name1" "backup_app_scope" || true
						else
							_speed_debug_log "UID_NET_BLOCK_FAST_SKIP pkg=$name2 label=$name1 stage=backup_app_scope policy=${SPEEDBACKUP_UID_NETBLOCK_POLICY:-smart} reason=non_high_risk_app"
						fi ;;
					esac
					_process_observer_start_app "$name2" "$name1" "backup_app_scope" || true
				fi
			if [[ $apk_number = 1 ]]; then
				Backup_apk "非Split Apk" "3"
			else
				Backup_apk "Split Apk支持備份" "3"
			fi
			# metadata 不應綁死 user data 備份；APK-only / 不備份 user data 也要補寫。
			[[ $result = 0 && -f $app_details ]] && Backup_metadata_once
			if [[ $result = 0 && $No_backupdata = "" ]]; then
				if [[ $Backup_Mode = true ]]; then
					if [[ $Backup_obb_data = true ]]; then
						if [[ $name2 != bin.mt.plus ]]; then
							#備份data數據
							[[ $name1 = Nekogram ]] && rm -rf /data/media/0/Android/data/tw.nekomimi.nekogram/files/Telegram/Telegram\ {Video,Stories,Documents,Images}/{*,.*} 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
							if ! _backup_remote_stream_fatal_payloads_active "$name1" "$name2" "before_data"; then Backup_data "data"; fi
							#備份obb數據
							if ! _backup_remote_stream_fatal_payloads_active "$name1" "$name2" "before_obb"; then Backup_data "obb"; fi
							#備份media數據 (部分app如FB Messenger使用 Android/media/<pkg> 存放媒體檔)
							if ! _backup_remote_stream_fatal_payloads_active "$name1" "$name2" "before_media"; then Backup_data "media"; fi
						else
							echoRgb "$name1無法備份" "0"
						fi
					fi
					#備份user數據
					[[ $name2 != bin.mt.plus ]] && {
						[[ $Backup_user_data = true ]] && {
						if ! _backup_remote_stream_fatal_payloads_active "$name1" "$name2" "before_user"; then Backup_data "user"; fi
						if ! _backup_remote_stream_fatal_payloads_active "$name1" "$name2" "before_user_de"; then Backup_data "user_de"; fi
						}
					}
					[[ $name2 = github.tornaco.android.thanos ]] && { if ! _backup_remote_stream_fatal_payloads_active "$name1" "$name2" "before_thanox"; then Backup_data "thanox" "$(find "/data/system" -maxdepth 1 -type d -name "thanos*" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null})"; fi; }
					[[ $name2 = org.frknkrc44.hma_oss ]] && { if ! _backup_remote_stream_fatal_payloads_active "$name1" "$name2" "before_hma"; then Backup_data "hma" "$(find "/data/misc" -maxdepth 1 -type d -name "hide_my_applist_*" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null})"; fi; }
				fi
			fi
			[[ -f $Backup_folder/${name2}.sh ]] && rm -rf "$Backup_folder/${name2}.sh"
			# 入口腳本:
			# 467/r21: 流式備份不再只用遠端 recover.sh 當哨兵值跳過三個 per-app wrapper。
			# 468/r27: 但每個未變更 app 都覆蓋 3 個小 wrapper 會造成 WebDAV/SMB 每 app 約 1~2 秒停頓。
			# 因此策略調整為：本輪有變更或任一 wrapper 缺失才重傳；未變更且三個 wrapper 已存在則跳過。
			if [[ $remote_stream = 1 ]]; then
				# r170: per-app backup/recover/upload wrappers 不再上傳；功能8/9下載後由 touch_shell 本地重建。
				mkdir -p "$Backup_folder" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
				touch_shell "3" "$Backup_folder/recover.sh" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} || true
				touch_shell "1" "$Backup_folder/backup.sh" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} || true
				touch_shell "5" "$Backup_folder/upload.sh" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} || true
			else
				[[ ! -f $Backup_folder/recover.sh ]] && touch_shell "3" "$Backup_folder/recover.sh"
				[[ ! -f $Backup_folder/backup.sh ]] && touch_shell "1" "$Backup_folder/backup.sh"
				[[ ! -f $Backup_folder/upload.sh ]] && touch_shell "5" "$Backup_folder/upload.sh"
			fi
			fi
			# App app_details 最終出口：所有 APK/data/keystore/PackageName jq_inplace 寫入後，再統一收斂一次。
			# 這是 370 判斷錯誤後補上的真正 final writer；不能放在 Backup_AppState 中間，否則後續 Size/path 更新仍會覆寫格式。
			if [[ -f $app_details ]]; then
				_appdetails_normalize_final "$app_details" "APPDETAILS_FINAL"
			fi
			# 備份全部跳過時清理空的 app_details.json 殘留
			_appdetails_remove_if_empty "$app_details"
			endtime 2 "$name1 備份" "3"
			# 流式: 數據 tar 已在壓縮時直接流到遠端, 此處補傳 app_details.json
			# 只在本輪該 app 有變更 (.changed_apps) 時上傳, 全跳過則遠端 json 本就最新
			# 該 app 本輪有任一流式上傳失敗 → 不傳 json (缺 json 下輪必整個重備, 避免壞數據被增量跳過殘留)
			# r355: 移除 r342 後遠端斷線 fast-fail；偵測到 LAN/路由/位址變更就直接中止本輪，避免不完整 payload 被當成成功。
			if [[ $remote_stream = 1 && -n $remote_type ]] && _remote_netwatch_changed_active; then
				_speed_debug_log "REMOTE_NETWATCH_APP_END_CHANGE_DETECTED app=$name1 package=$name2 mode=r370 policy=fast-fail"
				_remote_netwatch_report
				_remote_connectivity_fast_fail "backup_app_end" "$name1" "LAN route/address changed before app finalization" || true
				_remote_stream_mark_fatal "$name1" 126 0 "LAN route/address changed before app finalization; fast-fail without retry"
			fi
			if [[ -s "$TMPDIR/.stream_failed" ]] && awk -v n="$name1" '$0==n{f=1} END{exit !f}' "$TMPDIR/.stream_failed" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}; then
				echoRgb "$name1 本輪有上傳失敗, 不更新遠端 json (下次將重新備份此應用)" "0"
			elif [[ $remote_stream = 1 && -n $remote_type && -f $app_details ]]; then
				# r277: app_details 改為 single-stage bundle-only。每 App 只暫存到 bundle staging，結尾一次上傳 app_details_bundle.tar.zst。
				# 不再逐 App 上傳 $name1/app_details.json，也不下載舊單檔 JSON merge；遠端舊值只來自備份前 bundle 快取。
				_appdetails_normalize_final "$app_details" "APPDETAILS_STREAM_BUNDLE_FINAL" || _speed_debug_log "APPDETAILS_STREAM_BUNDLE_FINAL_PRETTY_FAIL app=$name1 package=$name2 file=$app_details"
				if _appdetails_bundle_stage_one "$name1" "$name2" "$app_details"; then
					echoRgb "app_details.json 已加入 bundle staging" "1"
				else
					echoRgb "app_details.json 加入 bundle staging 失敗" "0"
					_remote_stream_mark_fatal "$name1/app_details.json" 1 0 "appdetails_bundle_stage_failed"
				fi
			fi
			# 邊備份邊上傳：每個應用備份完立即上傳遠端，然後刪除本機檔案節省空間
			# 流式模式不走此路徑 (數據已流式傳走, 無本機 tar 可上傳, json 上面已傳)
			if [[ $remote_stream = 1 ]]; then
				:
			elif [[ $remote_upload_per_app = 1 && -n $remote_type ]]; then
				# 有備份變更 → 上傳
				if awk -v n="$name1" 'BEGIN{f=1} $0==n{f=0} END{exit f}' "$TMPDIR/.changed_apps" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}; then
					per_app_upload_and_cleanup "$name1"
				else
					# 本地無變更，但遠端可能沒有備份 → 檢查遠端 app_details.json
					_remote_has_backup=0
					_remote_check_file="$TMPDIR/.remote_check_$$"
					if remote_download_single_file "${name1}/app_details.json" "$_remote_check_file" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}; then
						[[ -s $_remote_check_file ]] && _remote_has_backup=1
					fi
					rm -f "$_remote_check_file"
					if [[ $_remote_has_backup = 0 ]]; then
						echoRgb "遠端無備份，上傳到遠端" "2"
						per_app_upload_and_cleanup "$name1"
					else
						echoRgb "無備份變更，跳過上傳" "2"
					fi
				fi
			fi
			# r67: 每個 App 所有 APK/data/user/user_de/metadata 處理完成後才解凍。
			_process_observer_stop_app "backup_app_scope_done" || true
			_uid_netblock_stop_app "backup_app_scope_done" || true
			_cgroup_freezer_stop_app "backup_app_scope_done" || true
			_live_app_resume_paused
			lxj="$(echo "$Occupation_status" | awk '{print $3}' | sed 's/%//g')"
			echoRgb "完成$(safe_percent "$i" "$r")% $(progress_bar $(safe_percent "$i" "$r"))$(_progress_local_storage_suffix)" "3"
			notification_progress "101" "$r" "$i" "備份進度 $i/$r $(safe_percent "$i" "$r")%"
			rgb_d="$rgb_a"
			rgb_a=188
			echoRgb "_________________$(endtime 1 "已經")___________________"
			rgb_a="$rgb_d"
		else
			echoRgb "$name1[$name2] 不在安裝列表，備份個寂寞？" "0"
		fi
		if [[ $i = $r ]]; then
			endtime 1 "應用備份" "3"
			#設置無障礙開關
			if [[ $var != "" ]]; then
				if [[ $var != null ]]; then
					settings put secure enabled_accessibility_services "$var" &>/dev/null
					echo_log "設置無障礙"
					settings put secure accessibility_enabled 1 &>/dev/null
					echo_log "打開無障礙開關"
				fi
			fi
			#設置鍵盤
			if [[ $keyboard != "" ]]; then
				ime enable "$keyboard" &>/dev/null
				ime set "$keyboard" &>/dev/null
				settings put secure default_input_method "$keyboard" &>/dev/null
				echo_log "設置鍵盤$(appinfo2 "${keyboard%/*}" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null})"
			fi
			# 某些流程/並發 trap 可能已清掉暫存清單；不存在時視為空，避免 stderr.log 出現 cat: No such file。
			if [[ -f "$TMPDIR/.update_apks" ]]; then update_apk2="$(cat "$TMPDIR/.update_apks" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null})"; else update_apk2=""; fi
			if [[ -f "$TMPDIR/.add_apks" ]]; then add_app2="$(cat "$TMPDIR/.add_apks" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null})"; else add_app2=""; fi
			update_apk2="${update_apk2:=" -暫無更新"}"
			add_app2="${add_app2:=" -暫無更新"}"
			echoRgb "已更新的apk=\"$osn\"\n -已新增的備份=\"$osk\"\n -apk版本號無變化=\"$osj\"\n -下列為版本號已變更的應用\n$update_apk2\n -新增的備份....\n$add_app2" "3"
			notification_progress "101" "$r" "$r" "app備份完成 $(endtime 1 "應用備份" "3")"
			# 把 backup_done 暫存檔的新項目合併進 txt_path2 (保留舊內容, 用 sort -u 去重)
			if [[ -s $TMPDIR/.backup_done ]]; then
				if [[ -f $txt_path2 ]]; then
					cat "$txt_path2" "$TMPDIR/.backup_done" | sort -u | sed '/^$/d' > "$txt_path2.new"
					mv "$txt_path2.new" "$txt_path2"
				else
					sort -u "$TMPDIR/.backup_done" | sed '/^$/d' > "$txt_path2"
				fi
			fi
			# r267: App 備份階段結束後立即釋放 batch watch-set，避免延長到 Media/WiFi 收尾。
			_process_observer_batch_stop "backup_app_phase_done" || true
			# 清掉備份用的暫存檔
			rm -f "$TMPDIR/.backup_done" "$TMPDIR/.update_apks" "$TMPDIR/.add_apks" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
			if [[ $backup_media = true && ! -f ${0%/*}/app_details.json ]]; then
				A=1
				B="$(printf "%s\n" "$Custom_path" | awk '!/[#＃]/ && NF{count++} END{print count}')"
				if [[ $B != "" ]]; then
					echoRgb "備份結束，備份多媒體" "1"
					notification_progress "102" "$B" 0 "Media備份開始"
					starttime1="$(date -u "+%s")"
					Backup_folder="$Backup/Media"
					app_details="$Backup_folder/app_details.json"
					mediatxt="$Backup/mediaList.txt"
					if [[ $remote_stream = 1 && -n $remote_type ]]; then
						_STREAM_DEST="Media"
						Backup_folder="$TMPDIR/.stream_stage/Media"
						app_details="$Backup_folder/app_details.json"
						mediatxt="$TMPDIR/.stream_stage/mediaList.txt"
						mkdir -p "$Backup_folder" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
					fi
					# 延遲建立: 只有實際備份了至少一個資料夾才建立 (避免空殼)
					_media_created=0
					_ensure_media_dirs() {
						[[ $_media_created = 1 ]] && return
						if [[ $remote_stream = 1 && -n $remote_type ]]; then
							[[ ! -d $Backup_folder ]] && mkdir -p "$Backup_folder"
						else
							[[ ! -f $Backup/start.sh ]] && touch_shell "2" "$Backup/start.sh"
							[[ ! -d $Backup_folder ]] && mkdir -p "$Backup_folder"
						fi
						if [[ ! -f $app_details ]]; then
							_media_appdetails_seed_remote_if_stream "$app_details" || printf '{\n}\n' > "$app_details"
						fi
						[[ ! -f $mediatxt ]] && echo "#不需要恢復的資料夾請在開頭使用#注釋 比如：#Download" > "$mediatxt"
						_media_created=1
					}
					echo "$Custom_path" | sed -e '/^#/d; /^$/d; s/\/$//' > "$TMPDIR/.media_custom_paths"
					while read -r; do
						if [[ $remote_stream = 1 && -n $remote_type ]] && _remote_netwatch_mark_stream_fatal "media_loop_top" "netwatch"; then
							echoRgb "遠端 LAN 路由／位址已變更，停止本輪後續 Media 備份" "0"
							_speed_debug_log "REMOTE_NETWATCH_ABORT_MEDIA_LOOP i=$A total=$B item=${REPLY##*/} $(_remote_stream_fatal_summary)"
							break
						fi
						if [[ $remote_stream = 1 && -n $remote_type ]] && _remote_stream_fatal_active; then
							echoRgb "遠端流式已中斷，停止本輪後續 Media 備份" "0"
							_speed_debug_log "REMOTE_STREAM_FATAL_ABORT_MEDIA_LOOP i=$A total=$B item=${REPLY##*/} $(_remote_stream_fatal_summary)"
							break
						fi
						echoRgb "備份第$A/$B個資料夾 剩下$((B - A))個" "3"
						notification_progress "102" "$B" "$((A - 1))" "備份第$A/$B個資料夾 剩下$((B - A))個"
						starttime2="$(date -u "+%s")"
						if [[ ${REPLY##*/} = adb ]]; then
							if [[ $ksu != ksu ]]; then
								echoRgb "Magisk adb"
								_ensure_media_dirs
								Backup_data "${REPLY##*/}" "$REPLY"
							else
								echoRgb "KernelSU adb不支持備份" "0"
								Set_back_0
							fi
						else
							_ensure_media_dirs
							Backup_data "${REPLY##*/}" "$REPLY"
						fi
						endtime 2 "${REPLY##*/}備份" "1"
						echoRgb "完成$(safe_percent "$A" "$B")% $(progress_bar $(safe_percent "$A" "$B"))$(_progress_local_storage_suffix)" "2"
						notification_progress "102" "$B" "$A" "Media備份進度 $A/$B $(safe_percent "$A" "$B")%"
						rgb_d="$rgb_a"
						rgb_a=188
						echoRgb "_________________$(endtime 1 "已經")___________________"
						rgb_a="$rgb_d" && let A++
					done < "$TMPDIR/.media_custom_paths"
					rm -f "$TMPDIR/.media_custom_paths"
					# 收尾: 無實際備份檔則清空殼
					# 流式模式: .tar 壓縮完即上傳, 本機不會留 .tar 檔 (設計如此), 改用 _media_created 旗標判斷
					if [[ $remote_stream = 1 && -n $remote_type ]]; then
						if _remote_stream_fatal_active; then
							echoRgb "Media 遠端流式已中斷，跳過 mediaList/app_details 上傳" "0"
							_speed_debug_log "REMOTE_STREAM_FATAL_MEDIA_METADATA_SKIP $(_remote_stream_fatal_summary)"
							rm -rf "$Backup_folder" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
							[[ -f $mediatxt ]] && rm -f "$mediatxt" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
						elif [[ $_media_created != 1 ]]; then
							echoRgb "Media 無實際備份內容, 清除 mediaList.txt" "0"
							rm -rf "$Backup_folder" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
							[[ -f $mediatxt ]] && [[ ! -s $mediatxt || $(grep -vc "^#" "$mediatxt" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}) = 0 ]] && rm -f "$mediatxt"
						else
							[[ $remote_stream != 1 ]] && echoRgb "目錄↓↓↓\n -$Backup_folder"
							REMOTE_UPLOAD_MEDIA=1
							# 只有 app_details 真的有實際內容(非初始空殼)才上傳, 避免「全部資料夾無變化跳過」
							# 時, 本地空殼覆蓋掉遠端原本正確的版本
							if _appdetails_is_nonempty "$app_details"; then
								_stream_upload "Media/app_details.json" < "$app_details"
								[[ -f $mediatxt ]] && _speed_debug_log "REMOTE_LOCAL_REBUILD_SIDECAR_SUMMARY rel=mediaList.txt reason=local-rebuild-stream-media"
								echoRgb "Media metadata 已上傳遠端，mediaList.txt 保留本地重建" "1"
							else
								echoRgb "Media 本輪全部資料夾無變化, 跳過json上傳(避免覆蓋遠端正確版本)" "2"
							fi
						fi
					elif [[ -d $Backup_folder ]] && ! _speedscan_backup_folder_has_tar_payload "$Backup_folder"; then
						echoRgb "Media 無實際備份內容, 清除空目錄與 mediaList.txt" "0"
						rm -rf "$Backup_folder"
						[[ -f $mediatxt ]] && [[ ! -s $mediatxt || $(grep -vc "^#" "$mediatxt" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}) = 0 ]] && rm -f "$mediatxt"
					else
						echoRgb "目錄↓↓↓\n -$Backup_folder"
						[[ -n $remote_type ]] && REMOTE_UPLOAD_MEDIA=1
					fi
					notification_progress "102" "$B" "$B" "Media備份完成 $(endtime 1 "自定義備份")"
					endtime 1 "自定義備份"
				else
					echoRgb "自定義路徑為空 無法備份" "0"
				fi
			fi
		fi
		unset _restore_force_play_session _restore_force_play_marker
		let i++ en++ nskg++
	done
	_process_observer_batch_stop "backup_loop_exit" || true
	local _backup_stream_fatal_rc=0
	if [[ $remote_stream = 1 && -n $remote_type ]] && _remote_stream_fatal_active; then
		_backup_stream_fatal_rc="$(_remote_stream_fatal_exit_rc)"
		_speed_debug_log "REMOTE_STREAM_FATAL_BACKUP_FASTFAIL_PRESERVE rc=$_backup_stream_fatal_rc $(_remote_stream_fatal_summary)"
	fi
	if [[ $remote_stream = 1 && -n $remote_type ]] && [[ $_backup_stream_fatal_rc = 0 ]]; then
		_appdetails_bundle_upload_stream || true
	fi
	_backup_orphan_cleanup_local
	# r242: 遠端已卸載應用刪除已從備份主流程完全移除，避免完成 100% 後掃整個遠端備份庫。
	# 需要清理時，請從主選單手動執行「刪除遠端已卸載應用」。
	if [[ -n $remote_type ]]; then
		_speed_debug_log "REMOTE_ORPHAN_CLEANUP_SKIP reason=manual_entry_required menu=delete_remote_uninstalled_apps remote_type=$remote_type remote_stream=${remote_stream:-0}"
	fi
	# r355: 遠端 fast-fail 後立即進入收尾，不再繼續 wifi/tools/stat 上傳或遠端後處理，避免使用者看到「部分成功」誤判。
	if [[ $remote_stream = 1 && -n $remote_type && $_backup_stream_fatal_rc != 0 ]]; then
		echoRgb "本輪已因遠端中斷進入快速中止收尾，略過 wifi/tools/遠端統計" "0"
		_speed_debug_log "REMOTE_STREAM_FATAL_SKIP_POST_BACKUP rc=$_backup_stream_fatal_rc $(_remote_stream_fatal_summary)"
	else
		# 流式模式: wifi 也存 TMPDIR 暫存區 (不碰本地 $Backup)
		if [[ $remote_stream = 1 && -n $remote_type ]]; then
			backup_wifi "$TMPDIR/.stream_stage/wifi"
		else
			backup_wifi "$Backup/wifi"
		fi
		[[ -n $remote_type ]] && REMOTE_UPLOAD_WIFI=1
	fi
	Set_screen_pause_seconds off
	[[ $user != 0 ]] && am stop-user "$user" >/dev/null 2>&1
	# 流式模式: 本地無備份檔 (數據在遠端), 跳過本地大小統計; 遠端統計在 remote_cleanup 結尾顯示
	[[ $remote_stream != 1 ]] && Calculate_size "$Backup"
	_stream_failed_report
	if [[ $remote_stream = 1 && -n $remote_type ]] && _remote_stream_fatal_active; then
		echoRgb "批量備份因遠端連線變更／中斷而停止；請確認遠端連線後重新執行" "0"
		_speed_debug_log "REMOTE_STREAM_FATAL_BATCH_END $(_remote_stream_fatal_summary)"
	else
		echoRgb "批量備份完成"
	fi
	echoRgb "備份結束時間$(date +"%Y-%m-%d %H:%M:%S")"
	starttime1="$TIME"
	endtime 1 "批量備份開始到結束"
	notification_progress "105" 100 100 "備份完成 $(endtime 1 "批量備份開始到結束")"
	verify_backup_manifest
	[[ -f $txt_path ]] && chown "$(stat -c '%u:%g' '/data/media/0/Download')" "$txt_path"
	[[ -f $txt_path2 ]] && chown "$(stat -c '%u:%g' '/data/media/0/Download')" "$txt_path2"
	# 備份完成後針對本次有變動的應用做 json 健全度檢查 (結構+欄位一併驗證)
	# 流式模式: json 在遠端 (本地 staging 已刪), 跳過本地驗證 (上傳時已即時驗證)。
	# 遠端非流式且本輪無實際備份變更時，本地 app_details 可能只補到權限/通知等增量欄位；
	# 此時應以上傳後遠端 app_details 驗證為準，避免誤報缺 PackageName/apk_version。
	local _skip_local_json_health=0
	if [[ -n $remote_type && $remote_stream != 1 && ${backup_has_changes:-0} = 0 ]]; then
		_skip_local_json_health=1
		_speed_debug_log "POST_JSON_LOCAL_HEALTH_SKIP reason=remote_nonstream_no_payload_change"
	fi
	if [[ $remote_stream != 1 && $_skip_local_json_health != 1 && -s $TMPDIR/.changed_apps ]]; then
		echoRgb "—————— 備份後 JSON 結構驗證 ——————" "3"
		local _jchk_sorted="$TMPDIR/.post_json_apps"
		sort -u "$TMPDIR/.changed_apps" > "$_jchk_sorted"
		local _jchk_total _jchk_i=1
		_jchk_total="$(wc -l < "$_jchk_sorted")"
		while read -r _japp; do
			local _jf="$Backup/$_japp/app_details.json"
			_speedbackup_progress_step "$_jchk_i" "$_jchk_total" "檢查本地 JSON $_japp" "post_json_health_verify"
			_json_health_check "$_jf" "$_japp"
			let _jchk_i++
		done < "$_jchk_sorted"
		echoRgb "檢查完成 $((_jchk_i-1))/$_jchk_total" "1"
		rm -f "$_jchk_sorted"
	fi
	_json_health_report
	REMOTE_TRIGGER=1
	# subshell 環境下 trap EXIT 在主 shell 不會觸發, 這裡直接呼叫
	remote_cleanup
	if ! cleanup_tmpdir_contents; then
		_speed_debug_pack 1
		exit 1
	fi
	# 正常備份完成點主動建立 final 包並刪除 run_xxx。
	# 仍會先建 snapshot；若 EXIT trap 在單獨入口 / pipeline subshell 未觸發，也不會留下 run 目錄。
	_backup_final_rc="${_backup_stream_fatal_rc:-0}"
	case $_backup_final_rc in ''|*[!0-9]*) _backup_final_rc=0 ;; esac
	if [[ $_backup_final_rc != 0 ]]; then
		_speed_debug_log "REMOTE_STREAM_FATAL_BACKUP_EXIT rc=$_backup_final_rc preserved=1"
	fi
	_speed_debug_normal_finish_pack "$_backup_final_rc"
	exit "$_backup_final_rc"
}
# 增量備份: 只備份版本號有更新的 app
# 對照 app_details.json 內舊版本, 沒變動的跳過
backup_update_apk() {
	Update_backup='true'
	backup
}
# 重新生成應用列表的 app 名稱欄位 (恢復模式選單用)
dumpname() {
	get_name "Apkname"
}
# 轉換 app 資料夾名稱 (舊格式 → 新格式)
convert() {
	get_name "convert"
}
# 對整個備份目錄做壓縮檔完整性檢查 (Check_archive 的批次入口)
check_file() {
	Check_archive "$MODDIR"
}
# 驗證所有 app_details.json 結構完整性 (走 app_details JSON API)
# 主選單「JSON結構檢查」呼叫
Check_json() {
	starttime1="$(date -u "+%s")"
	local error_log="$TMPDIR/json_error_log"
	rm -rf "$error_log"
	local r i=1 _json_list
	_json_list="${TMPDIR:-/data/local/tmp}/.check_json_appdetails_${$}_$RANDOM.lst"
	_appdetails_index_paths "$MODDIR" "$_json_list" 2 0 1 >/dev/null 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} || true
	r="$(grep -vc '^[[:space:]]*$' "$_json_list" 2>/dev/null)"; case $r in ''|*[!0-9]*) r=0 ;; esac
	[[ $r -eq 0 ]] && { echoRgb "找不到任何 app_details.json" "0"; rm -f "$_json_list" 2>/dev/null; return; }
	while read -r REPLY; do
		[[ -n $REPLY ]] || continue
		local dir="${REPLY%/*}"
		_speedbackup_progress_step "$i" "$r" "檢查:${dir##*/}" "json_structure_check"
		if _appdetails_json_parse_ok "$REPLY"; then
			if ! _appdetails_validate_schema "$REPLY"; then
				echoRgb "JSON schema 提示: ${dir##*/} 核心欄位/nullable/app_state 結構不完整（非阻斷）" "2"
			fi
		else
			echoRgb "JSON結構損壞或格式錯誤: ${dir##*/}" "0"
			echo "$REPLY">>"$error_log"
		fi
		let i++
	done < "$_json_list"
	rm -f "$_json_list" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	endtime 1
	if [[ -f $error_log ]]; then
		echoRgb "以下 JSON 檔損壞:\n $(cat "$error_log")" "0"
	else
		echoRgb "恭喜~~全數 JSON 結構正常" "1"
	fi
	rm -rf "$error_log"
}

# app_details.json 重新生成更新：像正常備份 metadata 一樣用目前 Dex AppState 重新產生新 JSON。
# 安全契約：舊 JSON 只作為「目標識別 + 保護欄位來源」，不拿舊 permissions/appops 結構轉換。
# 不重新計算、不覆蓋 Size / Backup time / apk_version / versionCode；不重打包任何 payload。
_appdetails_protected_signature() {
	local _file="$1"
	# 只鎖定「備份判斷用」欄位：root Backup time 與 app entry 直層 Size/版本欄位。
	# 不掃整份 JSON 的所有 versionCode，避免新 Dex AppState 內的 package/installDiagnostics
	# versionCode 被誤判成舊備份 APK 版本遭更新。
	jq -c '
		. as $root |
		def pick_entry($o):
			reduce ["Size","size","apk_size","data_size","obb_size","media_size","origin_size","path","keystore","apk_version","versionCode"][] as $k
			({}; if (($o|type)=="object" and ($o|has($k))) then .[$k]=$o[$k] else . end);
		def is_payload_entry($o):
			(($o|type)=="object") and (
				($o|has("Size")) or ($o|has("size")) or ($o|has("path")) or ($o|has("keystore")) or
				($o|has("apk_size")) or ($o|has("data_size")) or ($o|has("obb_size")) or
				($o|has("media_size")) or ($o|has("origin_size"))
			);
		def backup_entries:
			to_entries[] |
			select(.value|type=="object") |
			select(.key != "Backup time") |
			select(.value.PackageName != null or .value.app_state.packageName != null) |
			{key:.key, packageName:(.value.PackageName // .value.app_state.packageName // ""), protected:(pick_entry(.value) + (if ((.value.app_state.ssaid // .value.Ssaid // null) != null) then {ssaid:(.value.app_state.ssaid // .value.Ssaid)} else {} end))};
		def payload_entries:
			to_entries[] |
			select(.value|type=="object") |
			select(.key != "Backup time") |
			select((.value.PackageName == null) and (.value.app_state.packageName == null)) |
			select(is_payload_entry(.value)) |
			{key:.key, protected:pick_entry(.value)};
		{backup_time:($root["Backup time"] // null), entries:[backup_entries], payloads:[payload_entries]}
	' "$_file" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
}
_appdetails_entry_pkg_line() {
	local _file="$1"
	jq -r 'try (to_entries[] |
		select(.value|type=="object") |
		select(.key != "Backup time") |
		select(.value.PackageName != null or .value.app_state.packageName != null) |
		[.key, (.value.PackageName // .value.app_state.packageName // "")] | @tsv) catch empty' "$_file" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} | head -n 1
}
_appdetails_refresh_scan_root() {
	local _scan_dir
	if [[ $Output_path != "" ]]; then
		local _op="$Output_path"
		[[ ${_op: -1} = / ]] && _op="${_op%?}"
		if [[ ${_op:0:1} != / ]]; then
			_scan_dir="$MODDIR/$_op/$(get_backup_dirname)"
		else
			_scan_dir="$_op/$(get_backup_dirname)"
		fi
	else
		_scan_dir="$MODDIR/$(get_backup_dirname)"
	fi
	[[ ! -d $_scan_dir ]] && _scan_dir="$MODDIR"
	printf '%s\n' "$_scan_dir"
}
_appdetails_refresh_collect_local_pkgs() {
	local _root="$1" _tmp="$2" _line _pkg _json_list
	: > "$_tmp" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	_json_list="${TMPDIR:-/data/local/tmp}/.json_refresh_collect_${$}_$RANDOM.lst"
	_appdetails_index_paths "$_root" "$_json_list" 2 0 0 >/dev/null 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} || true
	while read -r _jf; do
		[[ -n $_jf ]] || continue
		_line="$(_appdetails_entry_pkg_line "$_jf")"
		_pkg="$(printf '%s\n' "$_line" | awk -F'\t' '{print $2}')"
		[[ -n $_pkg ]] && printf '%s\n' "$_pkg"
	done < "$_json_list" | sort -u > "$_tmp" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	rm -f "$_json_list" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
}
_appdetails_refresh_prescan_pkgs() {
	local _pkg_file="$1" _pkgs
	[[ -s $_pkg_file ]] || return 1
	_pkgs="$(paste -sd' ' "$_pkg_file" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null})"
	[[ -n $_pkgs ]] || return 1
	prepare_app_state_prescan_batch $_pkgs >/dev/null 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
}
_appdetails_refresh_regenerate_one_file() {
	local _file="$1" _label="$2" _tmp _state_raw_tmp _state_tmp _out _line _entry _pkg _old_sig _new_sig
	[[ -s $_file ]] || { echoRgb "跳過空 JSON: $_label" "0"; return 1; }
	_appdetails_json_parse_ok "$_file" || { echoRgb "跳過損壞 JSON: $_label" "0"; return 1; }
	_line="$(_appdetails_entry_pkg_line "$_file")"
	_entry="$(printf '%s\n' "$_line" | awk -F'\t' '{print $1}')"
	_pkg="$(printf '%s\n' "$_line" | awk -F'\t' '{print $2}')"
	[[ -n $_entry && -n $_pkg ]] || { echoRgb "跳過無 PackageName 的 JSON: $_label" "0"; return 1; }
	_tmp="$TMPDIR/.json_regen_${$}_$RANDOM"
	_state_raw_tmp="$_tmp.state.raw"
	_state_tmp="$_tmp.state"
	_out="$_tmp.out"
	_old_sig="$(_appdetails_protected_signature "$_file")"
	if ! _kv_file_get_to_file "$TMPDIR/.pkg_appstate" "$_pkg" "$_state_raw_tmp" || \
		! _appstate_snapshot_json_ok "$_state_raw_tmp"; then
		rm -f "$_tmp"* 2>/dev/null
		echoRgb "跳過: $_label ($_pkg) 目前裝置無法產生 Dex AppState 快照" "3"
		_speed_debug_log "JSON_REGENERATE_SKIP_NO_DEX_STATE label=$_label package=$_pkg file=$_file"
		return 2
	fi
	if ! _appstate_persist_compact < "$_state_raw_tmp" > "$_state_tmp" || \
		! _appstate_snapshot_json_ok "$_state_tmp"; then
		rm -f "$_tmp"* 2>/dev/null
		echoRgb "跳過: $_label ($_pkg) AppState持久化裁剪失敗" "0"
		_speed_debug_log "JSON_REGENERATE_SKIP_COMPACT_FAILED label=$_label package=$_pkg file=$_file"
		return 1
	fi
	_appdetails_refresh_build_current_json "$_file" "$_entry" "$_pkg" "$_state_tmp" "$_out" || { rm -f "$_tmp"* 2>/dev/null; echoRgb "重新生成失敗: $_label" "0"; return 1; }
	if ! _app_details_normalize_restore_profile_file "$_out"; then
		rm -f "$_tmp"* 2>/dev/null
		echoRgb "重新生成 canonical profile 失敗: $_label" "0"
		_speed_debug_log "JSON_REGENERATE_CANONICAL_PROFILE_FAIL label=$_label package=$_pkg file=$_file"
		return 1
	fi
	_new_sig="$(_appdetails_protected_signature "$_out")"
	if [[ $_old_sig != "$_new_sig" ]]; then
		rm -f "$_tmp"* 2>/dev/null
		echoRgb "安全中止: $_label 的 Size/apk版本/備份時間被改動，未覆蓋" "0"
		_speed_debug_log "JSON_REGENERATE_PROTECT_GUARD_FAIL label=$_label package=$_pkg file=$_file"
		return 1
	fi
	# 373 起 _json_cat_replace() 內部已在 TMPDIR 建立回復備份；
	# 不再把 app_details.json.pre360.bak 留在備份目錄。
	rm -f "$_file.pre360.bak" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	_json_cat_replace "$_out" "$_file" || { rm -f "$_tmp"* 2>/dev/null; echoRgb "覆蓋失敗: $_label" "0"; return 1; }
	rm -f "$_file.pre360.bak" "$_tmp"* 2>/dev/null
	_speed_debug_log "JSON_REGENERATE_OK label=$_label entry=$_entry package=$_pkg protected_preserved=1 ssaid_preserved=1 source=current_dex_appstate profile=canonical_restore_profile"
	echoRgb "重生JSON: $_label ($_pkg, Size/apk版本/備份時間/SSAID未更新)" "1"
	return 0
}
Json_refresh_local() {
	starttime1="$(date -u "+%s")"
	local _root _pkgs _jsons _total _ok=0 _skip=0 _fail=0 _i=0 _label _rc
	_root="$(_appdetails_refresh_scan_root)"
	_jsons="$TMPDIR/.json_regen_files_$$"
	_pkgs="$TMPDIR/.json_regen_pkgs_$$"
	_appdetails_index_paths "$_root" "$_jsons" 2 0 1 >/dev/null 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} || true
	_total="$(grep -vc '^$' "$_jsons" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null})"
	[[ $_total = 0 ]] && { echoRgb "找不到本地 app_details.json (搜尋: $_root)" "0"; rm -f "$_jsons" "$_pkgs"; return 1; }
	_appdetails_refresh_collect_local_pkgs "$_root" "$_pkgs"
	_appdetails_refresh_prescan_pkgs "$_pkgs" || { echoRgb "Dex AppState預掃不可用，無法重新生成 JSON" "0"; rm -f "$_jsons" "$_pkgs"; return 1; }
	while read -r _jf; do
		[[ -z $_jf ]] && continue
		let _i++
		_label="${_jf%/*}"; _label="${_label##*/}"
		echoRgb "[$_i/$_total] $_label" "3"
		_appdetails_refresh_regenerate_one_file "$_jf" "$_label"
		_rc=$?
		if [[ $_rc -eq 0 ]]; then
			let _ok++
		elif [[ $_rc -eq 2 ]]; then
			let _skip++
		else
			let _fail++
		fi
	done < "$_jsons"
	rm -f "$_jsons" "$_pkgs"
	endtime 1
	echoRgb "本地JSON重生完成: 成功=$_ok 跳過=$_skip 失敗=$_fail，所有 Size/apk版本/備份時間/SSAID未更新" "1"
}
Json_refresh_remote() {
	starttime1="$(date -u "+%s")"
	show_conf remote
	remote_enabled || { _remote_type_missing_msg; return 1; }
	_BACKUP_DIRNAME_CACHED="${_BACKUP_DIRNAME_CACHED:-$(get_backup_dirname)}"
	local _target_dir _stage _jsons _pkgs _total _ok=0 _skip=0 _fail=0 _i=0 _jf _label _line _pkg _rc
	_target_dir="${_BACKUP_DIRNAME_CACHED:-$(get_backup_dirname)}"
	_stage="$(_appdetails_bundle_stage_root)"
	_jsons="$TMPDIR/.json_regen_remote_bundle_jsons_$$"
	_pkgs="$TMPDIR/.json_regen_remote_bundle_pkgs_$$"
	rm -rf "$_stage" "$_jsons" "$_pkgs" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	mkdir -p "$_stage" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} || return 1
	# r457: 遠端已是 app_details_bundle-only；不可再逐 App 下載 app_details.json。
	# 直接下載 bundle -> 原地重生 -> 重新打包上傳 bundle。
	_speed_debug_log "JSON_REFRESH_REMOTE_BUNDLE_BEGIN subdir=$_target_dir mode=r459"
	if ! _appdetails_bundle_download_extract "$_target_dir" "$_stage" "json-refresh-remote-r459"; then
		echoRgb "遠端缺少或無法解析 app_details_bundle.tar.zst；無法重新生成遠端 JSON" "0"
		_speed_debug_log "JSON_REFRESH_REMOTE_BUNDLE_FAIL subdir=$_target_dir reason=download_extract_failed mode=r459"
		rm -rf "$_stage" "$_jsons" "$_pkgs" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
		return 1
	fi
	_appdetails_index_paths "$_stage" "$_jsons" 2 2 1 >/dev/null 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} || true
	_total="$(grep -vc '^[[:space:]]*$' "$_jsons" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null})"
	case $_total in ''|*[!0-9]*) _total=0 ;; esac
	if [[ $_total -le 0 ]]; then
		echoRgb "遠端 app_details bundle 內沒有可更新的 app_details.json" "0"
		_speed_debug_log "JSON_REFRESH_REMOTE_BUNDLE_EMPTY subdir=$_target_dir mode=r459"
		rm -rf "$_stage" "$_jsons" "$_pkgs" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
		return 1
	fi
	: > "$_pkgs" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	while read -r _jf; do
		[[ -n $_jf ]] || continue
		_line="$(_appdetails_entry_pkg_line "$_jf")"
		_pkg="$(printf '%s\n' "$_line" | awk -F'\t' '{print $2}')"
		[[ -n $_pkg ]] && printf '%s\n' "$_pkg" >> "$_pkgs"
	done < "$_jsons"
	sort -u "$_pkgs" -o "$_pkgs" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	_appdetails_refresh_prescan_pkgs "$_pkgs" || { echoRgb "Dex AppState預掃不可用，無法重新生成遠端 JSON" "0"; _speed_debug_log "JSON_REFRESH_REMOTE_PRESCAN_FAIL total=$_total pkgs=$(grep -vc '^[[:space:]]*$' "$_pkgs" 2>/dev/null) mode=r459"; rm -rf "$_stage" "$_jsons" "$_pkgs" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}; return 1; }
	rm -f "$(_appdetails_bundle_dirty_file)" "$(_appdetails_bundle_preupload_ok_file)" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	while read -r _jf; do
		[[ -n $_jf ]] || continue
		let _i++
		_label="${_jf%/app_details.json}"; _label="${_label##*/}"
		echoRgb "[$_i/$_total] 遠端 $_label" "3"
		_appdetails_refresh_regenerate_one_file "$_jf" "$_label(遠端)"
		_rc=$?
		if [[ $_rc -eq 0 ]]; then
			_line="$(_appdetails_entry_pkg_line "$_jf")"
			_pkg="$(printf '%s\n' "$_line" | awk -F'\t' '{print $2}')"
			_appdetails_bundle_mark_dirty "$_label" "$_pkg" "$(stat -c%s "$_jf" 2>/dev/null)"
			let _ok++
		elif [[ $_rc -eq 2 ]]; then
			let _skip++
		else
			let _fail++
		fi
	done < "$_jsons"
	if [[ $_ok -gt 0 ]]; then
		if _appdetails_bundle_upload_stream; then
			_speed_debug_log "JSON_REFRESH_REMOTE_BUNDLE_UPLOAD_OK ok=$_ok skip=$_skip fail=$_fail total=$_total mode=r459"
		else
			_fail=$((_fail + _ok))
			_ok=0
			_speed_debug_log "JSON_REFRESH_REMOTE_BUNDLE_UPLOAD_FAIL total=$_total mode=r459"
		fi
	fi
	rm -rf "$_stage" "$_jsons" "$_pkgs" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	endtime 1
	echoRgb "遠端JSON重生完成: 成功=$_ok 跳過=$_skip 失敗=$_fail，所有 Size/apk版本/備份時間/SSAID未更新" "1"
}

Json_refresh_menu() {
	echoRgb "此功能會像備份流程一樣重新生成 app_details.json 的目前格式/AppState；但不更新 Size、apk版本、備份時間、SSAID，也不重打包資料" "3"
	ask_yn_indep "選擇更新目標" "本地JSON" "遠端JSON"
	if [[ $branch = true ]]; then
		Json_refresh_local
	else
		Json_refresh_remote
	fi
}
# 目前本地備份統計總覽: 應用/媒體數量、檔案數、總大小、含SSAID應用數、json有效率

# roundtrip.sh 已在 v24.20.14-7.48 移除；不得恢復父子 recover→backup 測試入口，避免防重複執行誤判。
Backup_Stats() {
	starttime1="$(date -u "+%s")"
	echoRgb "—————— 目前備份統計 ——————" "3"
	local _jsons _total_json=0 _valid_json=0 _ssaid_cnt=0 _app_cnt=0 _media_cnt=0
	# 唯讀算出備份目錄 (不呼叫 backup_path(), 避免其 mkdir/隨身碟詢問等副作用)
	local _scan_dir
	if [[ $Output_path != "" ]]; then
		local _op="$Output_path"
		[[ ${_op: -1} = / ]] && _op="${_op%?}"
		if [[ ${_op:0:1} != / ]]; then
			_scan_dir="$MODDIR/$_op/$(get_backup_dirname)"
		else
			_scan_dir="$_op/$(get_backup_dirname)"
		fi
	else
		_scan_dir="$MODDIR/$(get_backup_dirname)"
	fi
	[[ ! -d $_scan_dir ]] && _scan_dir="$MODDIR"
	_jsons_file="${TMPDIR:-/data/local/tmp}/.backup_stats_appdetails_${$}_$RANDOM.lst"
	_appdetails_index_paths "$_scan_dir" "$_jsons_file" 2 0 1 >/dev/null 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} || true
	_jsons="$(cat "$_jsons_file" 2>/dev/null)"
	if [[ -z $_jsons ]]; then
		echoRgb "找不到任何備份 (無 app_details.json, 已搜尋: $_scan_dir)" "0"
		rm -f "$_jsons_file" 2>/dev/null
		return
	fi
	_total_json="$(echo "$_jsons" | grep -vc '^$')"
	while read -r _jf; do
		[[ -z $_jf ]] && continue
		local _dirname="${_jf%/*}"
		_dirname="${_dirname##*/}"
		if [[ $_dirname = Media ]]; then
			let _media_cnt++
		else
			let _app_cnt++
		fi
		if _appdetails_json_parse_ok "$_jf"; then
			let _valid_json++
			local _has_ssaid
			_has_ssaid="$(_appdetails_count_any_ssaid "$_jf")"
			[[ ${_has_ssaid:-0} -gt 0 ]] && let _ssaid_cnt++
		fi
	done <<EOF5
$_jsons
EOF5
	# 檔案數與總大小: 用既有 calc_dir_size 邏輯量整個 Backup 目錄, 對應電腦端「大小」算法
	local _filecount _totalsize
	_filecount="$(find "$_scan_dir" -maxdepth 3 -type f 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} | grep -vc '^$')"
	_totalsize="$(calc_dir_size "$_scan_dir" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null})"
	echoRgb "應用數量: $_app_cnt 個" "2"
	[[ $_media_cnt -gt 0 ]] && echoRgb "媒體/自訂資料夾: $_media_cnt 個" "2"
	echoRgb "檔案總數: ${_filecount:-0} 個" "2"
	echoRgb "備份總大小: $(size "${_totalsize:-0}")" "2"
	echoRgb "含SSAID的應用: $_ssaid_cnt 個" "2"
	if [[ $_valid_json -eq $_total_json ]]; then
		echoRgb "JSON有效率: $_valid_json/$_total_json (全數正常)" "1"
	else
		echoRgb "JSON有效率: $_valid_json/$_total_json (有 $((_total_json - _valid_json)) 個損壞)" "0"
	fi
	endtime 1 "統計用時"
}
# 統計分派: conf 有設定遠端就用遠端統計, 沒有就本地統計
Stats_Dispatch() {
	if [[ -n $remote_type ]]; then
		Remote_Backup_Stats
	else
		Backup_Stats
	fi
}
# 遠端備份統計總覽: 應用數量、檔案數、總大小、含SSAID應用數、json有效率 (遠端版)
Remote_Backup_Stats() {
	show_conf remote
	[[ -z $remote_type ]] && { _remote_type_missing_msg; return 1; }
	case $remote_type in
	smb|webdav) ;;
	*) echoRgb "統計功能僅支援 smb / webdav (目前 remote_type=$remote_type)" "0"; return 1 ;;
	esac
	starttime1="$(date -u "+%s")"
	local target_dir="$(get_backup_dirname)"
	echoRgb "目標遠端目錄: $target_dir" "3"
	remote_parse_endpoint
	if ! remote_precheck "$REMOTE_HOST" "$REMOTE_PORT"; then
		echoRgb "遠端連線失敗: $REMOTE_HOST:$REMOTE_PORT" "0"
		_remote_precheck_print_smb_issue
		return 1
	fi
	_remote_stream_fatal_reset "remote_stats_start"
	_remote_netwatch_start
	if _remote_netwatch_mark_remote_fatal "remote_stats_after_precheck" "$target_dir"; then
		echoRgb "遠端統計已因遠端連線逾時中止" "0"
		_remote_netwatch_finish
		return 1
	fi
	[[ $remote_type = smb ]] && remote_parse_smb_url
	echoRgb "連線到 $remote_type://$REMOTE_HOST:$REMOTE_PORT" "1"
	echoRgb "—————— 遠端備份統計 ——————" "3"
	echoRgb "正在掃描遠端檔案列表 (單次連線)..." "3"
	local _filelist="$TMPDIR/.remote_stats_files"
	remote_list_files "$target_dir" > "$_filelist" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	_eventwait_output_file_stable_ms "$_filelist" remote_stats_filelist_ready 80 1500 >/dev/null 2>&1 || true
	if [[ ! -s $_filelist ]]; then
		echoRgb "遠端目錄不存在或無檔案: $target_dir" "0"
		rm -f "$_filelist"
		_remote_netwatch_finish
		return 1
	fi
	local _filecount _totalsize
	_filecount="$(grep -vc '^$' "$_filelist")"
	echoRgb "正在計算遠端總大小..." "3"
	_totalsize="$(remote_dir_size "$target_dir")"

	local _bundle_root="$TMPDIR/.remote_stats_bundle" _bundle_ok=0 _apps="$TMPDIR/.remote_stats_apps"
	rm -rf "$_bundle_root" "$TMPDIR/.remote_stats_dl" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	mkdir -p "$_bundle_root" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	local _stats_bundle_found_rel
	_stats_bundle_found_rel="$(awk -v b="$(_appdetails_bundle_rel)" -v lb="$(_appdetails_bundle_legacy_rel)" '$1==b || $1==lb {print $1; exit}' "$_filelist" 2>/dev/null)"
	if [[ -n $_stats_bundle_found_rel ]]; then
		echoRgb "正在解析遠端 app_details metadata bundle..." "3"
		_speed_debug_log "REMOTE_STATS_BUNDLE_FIRST_BEGIN subdir=$target_dir rel=$target_dir/${_stats_bundle_found_rel:-$(_appdetails_bundle_rel)} canonical=$(_appdetails_bundle_rel) mode=r370"
		if _appdetails_bundle_download_extract "$target_dir" "$_bundle_root" "remote-stats-r342"; then
			_bundle_ok=1
			_appdetails_index_paths "$_bundle_root" "${_apps}.jsons" 2 2 1 >/dev/null 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} || true
			sed 's|/app_details\.json$||; s|.*/||' "${_apps}.jsons" 2>/dev/null | sort -u > "$_apps"
			rm -f "${_apps}.jsons" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
			_speed_debug_log "REMOTE_STATS_BUNDLE_READY count=$(grep -vc '^$' "$_apps" 2>/dev/null) root=$_bundle_root mode=r370"
		else
			_speed_debug_log "REMOTE_STATS_BUNDLE_FAIL subdir=$target_dir action=no_per_app_fallback mode=r370"
		fi
	else
		_speed_debug_log "REMOTE_STATS_BUNDLE_ABSENT subdir=$target_dir mode=r370"
	fi
	if [[ $_bundle_ok != 1 || ! -s $_apps ]]; then
		echoRgb "遠端缺少或無法解析 app_details_bundle.tar.zst；此版本不再逐檔下載 app_details.json 統計" "0"
		echoRgb "檔案總數: ${_filecount:-0} 個" "2"
		echoRgb "備份總大小: $(size "${_totalsize:-0}")" "2"
		rm -rf "$_bundle_root" "$_filelist" "$_apps" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
		_remote_netwatch_finish
		endtime 1 "統計用時"
		return 1
	fi
	local _app_cnt=0 _media_cnt=0 _total_json=0 _valid_json=0 _ssaid_cnt=0 _bad_json_list="$TMPDIR/.remote_stats_json_bad" _ra _jf _has_required _has_ssaid
	: > "$_bad_json_list"
	while read -r _ra; do
		[[ -z $_ra ]] && continue
		if [[ $_ra = Media ]]; then
			_media_cnt=$((_media_cnt + 1))
			continue
		fi
		_app_cnt=$((_app_cnt + 1))
		_total_json=$((_total_json + 1))
		_jf="$_bundle_root/$_ra/app_details.json"
		if [[ ! -s $_jf ]]; then
			echo "$_ra: bundle app_details.json 缺失或為空" >> "$_bad_json_list"
			continue
		fi
		if ! _appdetails_json_parse_ok "$_jf"; then
			echo "$_ra: bundle json 格式損壞或無法解析" >> "$_bad_json_list"
			continue
		fi
		if _appdetails_has_required_meta "$_jf"; then _has_required=1; else _has_required=0; fi
		if [[ ${_has_required:-0} -le 0 ]]; then
			echo "$_ra: 缺 PackageName 或 apk_version" >> "$_bad_json_list"
			continue
		fi
		_valid_json=$((_valid_json + 1))
		_has_ssaid="$(_appdetails_count_any_ssaid "$_jf")"
		[[ ${_has_ssaid:-0} -gt 0 ]] && _ssaid_cnt=$((_ssaid_cnt + 1))
	done < "$_apps"
	_speed_debug_log "REMOTE_STATS_BUNDLE_SUMMARY app=$_app_cnt media=$_media_cnt valid=$_valid_json total=$_total_json ssaid=$_ssaid_cnt files=${_filecount:-0} size=${_totalsize:-0} mode=r370"
	echoRgb "應用數量: $_app_cnt 個" "2"
	[[ $_media_cnt -gt 0 ]] && echoRgb "媒體/自訂資料夾: $_media_cnt 個" "2"
	echoRgb "檔案總數: ${_filecount:-0} 個" "2"
	echoRgb "備份總大小: $(size "${_totalsize:-0}")" "2"
	echoRgb "含SSAID的應用: $_ssaid_cnt 個" "2"
	if [[ $_total_json -le 0 ]]; then
		echoRgb "JSON有效率: 0/0 (沒有應用 JSON，僅媒體/自訂資料夾 metadata)" "2"
	elif [[ $_valid_json -eq $_total_json ]]; then
		echoRgb "JSON有效率: $_valid_json/$_total_json (全數正常)" "1"
	else
		echoRgb "JSON有效率: $_valid_json/$_total_json (有 $((_total_json - _valid_json)) 個損壞或無法解析)" "0"
		if [[ -s $_bad_json_list ]]; then
			echoRgb "遠端 JSON 異常清單:" "0"
			local _bj_i=1 _bj
			while read -r _bj; do
				[[ -n $_bj ]] && echoRgb "$_bj_i. $_bj" "0"
				_bj_i=$((_bj_i + 1))
			done < "$_bad_json_list"
		fi
	fi
	[[ -n ${SPEED_DEBUG_RUN_DIR:-} && -d ${SPEED_DEBUG_RUN_DIR:-} && -s $_bad_json_list ]] && cp "$_bad_json_list" "$SPEED_DEBUG_RUN_DIR/remote_stats_json_bad.log" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	rm -rf "$_bundle_root" "$_filelist" "$_apps" "$_bad_json_list" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	_remote_netwatch_finish
	endtime 1 "統計用時"
}

# ======================================================
# Restore() 主函數
# ======================================================
# 主恢復函數 - 安裝 apk + 恢復 data + 還原 SSAID/權限
# ssaid_mode=true 時只恢復含 SSAID 的 app
# 從遠端流式恢復: 讀 appList_network.txt, 逐 app 流式拉回解壓 (不佔本機)
# 復用 Restore 的全部邏輯 (uid/selinux/權限/ssaid), 只是資料來源改為遠端流式
remote_stream_restore() {
	show_conf remote
	[[ -z $remote_type ]] && { _remote_type_missing_msg; return 1; }
	case $remote_type in
	smb|webdav) ;;
	*) echoRgb "流式恢復僅支援 smb / webdav (目前 remote_type=$remote_type)" "0"; return 1 ;;
	esac
	local list="$MODDIR/appList_network.txt" _list_cache="$TMPDIR/.speedbackup_last_appList_network" _stream_list_file="$TMPDIR/.stream_restore_appList_network.$$"
	if [[ ! -f $list && -f $_list_cache ]]; then
		mkdir -p "${list%/*}" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} || true
		cp -f "$_list_cache" "$list" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} && _speed_debug_log "APP_LIST_NETWORK_RESTORE_FROM_CACHE path=$list cache=$_list_cache mode=r370"
	fi
	if [[ ! -f $list ]]; then
		echoRgb "找不到 $list" "0"
		echoRgb "請先執行 '列出遠端備份' 產生清單, 編輯後再來流式恢復" "3"
		return 1
	fi
	if ! cp -f "$list" "$_stream_list_file" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}; then
		echoRgb "讀取 appList_network.txt 失敗: $list" "0"
		_speed_debug_log "APP_LIST_NETWORK_STREAM_COPY_FAIL path=$list tmp=$_stream_list_file mode=r370"
		return 1
	fi
	_RESTORE_STREAM_LIST_FILE="$_stream_list_file"
	_speed_debug_log "APP_LIST_NETWORK_STREAM_COPY_OK path=$list tmp=$_stream_list_file bytes=$(wc -c < "$_stream_list_file" 2>/dev/null) mode=r370"
	# 連線預檢 + 解析 SMB 路徑 (流式 _stream_download 需要 SMB_SHARE/SMB_REM_PATH)
	remote_parse_endpoint
	[[ $remote_type = smb ]] && remote_parse_smb_url
	if ! remote_precheck "$REMOTE_HOST" "$REMOTE_PORT"; then
		echoRgb "遠端連線失敗: $REMOTE_HOST:$REMOTE_PORT" "0"
			_remote_precheck_print_smb_issue
		return 1
	fi
	_remote_stream_fatal_reset "remote_stream_restore_start"
	_remote_netwatch_start
	if _remote_netwatch_mark_remote_fatal "remote_stream_restore_after_precheck" "restore"; then
		echoRgb "遠端流式恢復已因 LAN 路由／位址變更中止" "0"
		_remote_netwatch_finish
		return 1
	fi
	# TCP port open 不代表共享/帳密/路徑正確；Restore() 前必須做協議層硬預檢。
	_RESTORE_SUBDIR="$(get_backup_dirname)"
	if ! _remote_stream_source_precheck "$_RESTORE_SUBDIR"; then
		_speed_debug_log "REMOTE_STREAM_RESTORE_ABORT source_precheck_failed type=$remote_type host=$REMOTE_HOST port=$REMOTE_PORT subdir=$_RESTORE_SUBDIR"
		_remote_netwatch_finish
		return 1
	fi
	echoRgb "流式恢復來源: $remote_type://$REMOTE_HOST/ ($_RESTORE_SUBDIR)" "3"
	echoRgb "清單: $list" "2"
	# 設流式恢復旗標, 復用 Restore 全流程。先清前一輪中斷殘留 staging。
	_RESTORE_STREAM=1
	# r491: 開頭預掃遠端實檔列表，供 appList_network 刪孤兒/缺 metadata 判斷。
	_prepare_timed prepare_remote_filelist
	rm -rf "$TMPDIR/.restore_stage" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	mkdir -p "$TMPDIR/.restore_stage" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	if ! _restore_stream_appdetails_bundle_prepare; then
		_remote_netwatch_finish
		_RESTORE_STREAM=0
		rm -f "$_stream_list_file" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
		unset _RESTORE_STREAM_LIST_FILE
		return 1
	fi
	_restore_stream_prune_missing_remote_apps "$list" "$_stream_list_file" "$TMPDIR/.restore_stage" || true
	local _stream_app_rows_after_prune
	_stream_app_rows_after_prune="$(awk '
		/^[[:space:]]*[#＃]/ || /^[[:space:]]*$/ { next }
		{
			line=$0
			sub(/^[[:space:]]+/, "", line); sub(/[[:space:]]+$/, "", line)
			if (line == "wifi" || line == "Media") next
			if (line ~ /\.tar(\.zst)?$/) next
			c++
		}
		END { print c+0 }
	' "$_stream_list_file" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null})"
	case $_stream_app_rows_after_prune in ''|*[!0-9]*) _stream_app_rows_after_prune=0 ;; esac
	if [[ $_stream_app_rows_after_prune -eq 0 ]]; then
		echoRgb "appList_network.txt 已無可流式恢復的 App 項目，已結束" "2"
		_speed_debug_log "REMOTE_STREAM_RESTORE_END_EMPTY_AFTER_PRUNE list=$list work=$_stream_list_file mode=r491"
		_remote_netwatch_finish
		_RESTORE_STREAM=0
		rm -rf "$TMPDIR/.restore_stage" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
		rm -f "$_stream_list_file" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
		unset _RESTORE_STREAM_LIST_FILE
		return 0
	fi
	Restore
	local _restore_rc=$?
	# 清理 staging (只有 json, 數據從未落地)
	rm -rf "$TMPDIR/.restore_stage" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	rm -f "$_stream_list_file" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	unset _RESTORE_STREAM_LIST_FILE
	_RESTORE_STREAM=0
	if [[ $_restore_rc != 0 ]]; then
		_speed_debug_log "REMOTE_STREAM_RESTORE_END_NONZERO rc=$_restore_rc"
		_remote_netwatch_finish
		return "$_restore_rc"
	fi
	if _remote_stream_fatal_active; then
		_speed_debug_log "REMOTE_STREAM_RESTORE_END_FATAL $(_remote_stream_fatal_summary)"
		_remote_netwatch_finish
		return "$(_remote_stream_fatal_exit_rc)"
	fi
	_remote_netwatch_finish
}
# 流式恢復時本地不會有 $MODDIR/Media，也不會先下載 mediaList.txt。
# 這裡只下載恢復 Media 必需的 metadata；真正的壓縮包仍由 Release_data() 經 _STREAM_SRC 邊下邊解。
# r215: 流式恢復執行階段與「列出遠端備份」同步：必須同時通過遠端 Media 實檔清單
# 與 Media/app_details.json key guard。payload 副檔名由遠端真實清單決定；遠端不存在就不恢復。
_restore_stream_media_payload_resolve() {
	local _entry="$1" _remote_list="$2" _tar _zst
	case "$_entry" in
	*.tar|*.tar.zst) printf '%s\n' "$_entry"; return 0 ;;
	esac
	_tar="$_entry.tar"
	_zst="$_entry.tar.zst"
	if [[ -s $_remote_list ]]; then
		if awk -v n="$_tar" '$0==n{f=1;exit} END{exit f?0:1}' "$_remote_list" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}; then
			printf '%s\n' "$_tar"
			return 0
		fi
		if awk -v n="$_zst" '$0==n{f=1;exit} END{exit f?0:1}' "$_remote_list" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}; then
			printf '%s\n' "$_zst"
			return 0
		fi
	fi
	printf '%s\n' "$_tar"
}

_restore_stream_media_list_from_appdetails() {
	local _json="$1" _out="$2" _remote_list="$3" _entries _tmp _entry _payload _cnt=0 _drop=0 _exists _key
	[[ -s $_json && -n $_out && -s $_remote_list ]] || return 1
	_entries="$_out.entries.$$"
	_tmp="$_out.tmp.$$"
	jq -r '
		to_entries[]
		| select(.key != "Backup time")
		| select(.key != "PackageName")
		| select(.key != "app_state")
		| select(.value|type == "object")
		| select(((.value.Size // .value.size // .value.path // "")|tostring) != "")
		| .key
	' "$_json" > "$_entries" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} || { rm -f "$_entries" "$_tmp"; return 1; }
	: > "$_tmp" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} || { rm -f "$_entries" "$_tmp"; return 1; }
	while IFS= read -r _entry; do
		_entry="$(printf '%s\n' "$_entry" | sed -e 's/[[:space:]]*$//')"
		case "$_entry" in ''|\#*|＃*) continue ;; esac
		_payload="$(_restore_stream_media_payload_resolve "$_entry" "$_remote_list")"
		_key="$(_app_network_media_payload_stem "$_payload")"
		_exists=0
		if awk -v n="$_payload" '$0==n{f=1;exit} END{exit f?0:1}' "$_remote_list" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}; then
			_exists=1
		fi
		if [[ $_exists != 1 ]]; then
			_drop=$((_drop + 1))
			_speed_debug_log "STREAM_RESTORE_MEDIA_LIST_ENTRY_DROP entry=$_entry payload=$_payload key=$_key source=app_details_json reason=remote_file_missing jsonMatch=1 remoteExists=0"
			continue
		fi
		printf '%s\n' "$_payload" >> "$_tmp" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
		_cnt=$((_cnt + 1))
		_speed_debug_log "STREAM_RESTORE_MEDIA_LIST_ENTRY entry=$_entry payload=$_payload key=$_key source=app_details_json remoteExists=1 jsonMatch=1"
	done < "$_entries"
	grep -Ev '^[[:space:]]*[#＃]|^[[:space:]]*$' "$_tmp" | sort -u > "$_out" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} || true
	rm -f "$_entries" "$_tmp" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	_speed_debug_log "STREAM_RESTORE_MEDIA_LIST_RESOLVE source=app_details_json count=$_cnt dropped=$_drop out=$_out remoteList=${_remote_list:-none} guard=remote-file+json-key"
	[[ -s $_out ]]
}

# 流式恢復時本地不會有 $MODDIR/Media；r172 起遠端不再依賴 mediaList.txt，
# 單獨流式恢復自定義資料夾與功能10共用 appList_network.txt 的 Media 特殊項，
# 壓縮包清單從 Media/app_details.json 推導，避免重新上傳 mediaList.txt。
_restore_stream_prepare_media() {
	_RESTORE_STREAM_MEDIA_READY=0
	unset _RESTORE_STREAM_MEDIA_LIST _RESTORE_STREAM_MEDIA_REMOTE_RAW
	[[ ${_RESTORE_STREAM:-0} = 1 ]] || return 1
	local _list="${_RESTORE_STREAM_LIST_FILE:-$MODDIR/appList_network.txt}"
	[[ -s $_list ]] || { _speed_debug_log "STREAM_RESTORE_MEDIA_LIST_MISSING source=$_list original=$MODDIR/appList_network.txt mode=r370"; return 1; }
	local _mstage="$TMPDIR/.restore_stage/Media" _mlist="$TMPDIR/.restore_stage/mediaList.txt" _mremote="$TMPDIR/.restore_stage/media_remote_files.txt" _mremote_raw="$TMPDIR/.restore_stage/media_remote_files_raw.txt" _mselected="$TMPDIR/.restore_stage/media_selected_from_appList.txt" _mkeys="$TMPDIR/.restore_stage/media_app_details.keys" _mall=0
	mkdir -p "$_mstage" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	: > "$_mselected" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	_app_network_media_payload_list "$_list" "$_mselected" || true
	if _app_network_has_media_all_marker "$_list"; then _mall=1; fi
	if [[ $_mall != 1 && ! -s $_mselected ]]; then
		return 1
	fi
	# r215: 流式恢復執行階段同步「列出遠端備份」行為：只接受遠端 Media 第一層真實 .tar/.tar.zst，排除 json/子路徑/雜項。
	: > "$_mremote_raw" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	: > "$_mremote" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	_RESTORE_STREAM_MEDIA_REMOTE_RAW="$_mremote_raw"
	remote_list_files "$_RESTORE_SUBDIR/Media" > "$_mremote_raw" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} || true
	if _remote_stream_fatal_active; then
		_speed_debug_log "STREAM_RESTORE_MEDIA_ABORT reason=remote_stream_fatal stage=media_remote_list"
		return 1
	fi
	awk '
		function reserved(n) {
			return (n=="app_details_bundle.tar" || n=="app_details_bundle.tar.zst" || n=="app_details.tar" || n=="app_details.tar.zst" ||
				n=="apk.tar" || n=="apk.tar.zst" || n=="data.tar" || n=="data.tar.zst" ||
				n=="user.tar" || n=="user.tar.zst" || n=="user_de.tar" || n=="user_de.tar.zst" ||
				n=="obb.tar" || n=="obb.tar.zst" || n=="hma.tar" || n=="hma.tar.zst" ||
				n=="thanox.tar" || n=="thanox.tar.zst")
		}
		{
			name=$0
			gsub(/\r$/, "", name)
			if (name == "") next
			if (name ~ /\//) next
			if (name ~ /(^|\.)json$/) next
			if (name ~ /\.tar(\.zst)?$/ && !reserved(name)) print name
		}
	' "$_mremote_raw" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} | sort -u > "$_mremote" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	_speed_debug_log "STREAM_RESTORE_MEDIA_REMOTE_LIST rows=$(grep -vc '^$' "$_mremote" 2>/dev/null) rawRows=$(grep -vc '^$' "$_mremote_raw" 2>/dev/null) rel=$_RESTORE_SUBDIR/Media filter=tar-json-excluded"
	if [[ ! -s $_mremote ]]; then
		_speed_debug_log "STREAM_RESTORE_MEDIA_ABORT reason=no_remote_media_payloads rel=$_RESTORE_SUBDIR/Media guard=remote-file+json-key"
		return 1
	fi
	_stream_download "$_RESTORE_SUBDIR/Media/app_details.json" > "$_mstage/app_details.json" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	if _remote_stream_fatal_active; then
		_speed_debug_log "STREAM_RESTORE_MEDIA_ABORT reason=remote_stream_fatal stage=app_details"
		return 1
	fi
	if [[ ! -s "$_mstage/app_details.json" ]] || ! _appdetails_json_parse_ok "$_mstage/app_details.json"; then
		echoRgb "Media/app_details.json 下載失敗或內容損毀，跳過流式 Media 恢復" "0"
		{
			echo "===== BAD_STREAM_MEDIA_APP_DETAILS rel=$_RESTORE_SUBDIR/Media/app_details.json ====="
			echo "size=$(wc -c < "$_mstage/app_details.json" 2>/dev/null)"
			head -c 300 "$_mstage/app_details.json" 2>/dev/null | sed 's/^/  content: /'
			echo
		} >> "${SPEED_DEBUG_RUN_DIR:-/data/speed_debug}/bad_media_restore.log" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
		return 1
	fi
	if ! _app_network_media_json_keys_extract "$_mstage/app_details.json" "$_mkeys"; then
		echoRgb "Media/app_details.json 沒有可恢復的自定義資料夾 key，跳過流式 Media 恢復" "0"
		_speed_debug_log "STREAM_RESTORE_MEDIA_ABORT reason=no_app_details_keys rel=$_RESTORE_SUBDIR/Media/app_details.json"
		return 1
	fi
	if [[ -s $_mselected ]]; then
		: > "$_mlist" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
		local _mp _mex _mcnt=0 _mdrop=0 _mstem
		while IFS= read -r _mp; do
			[[ -z $_mp ]] && continue
			_mstem="$(_app_network_media_payload_stem "$_mp")"
			if ! _app_network_media_json_has_key "$_mkeys" "$_mstem"; then
				_mdrop=$((_mdrop + 1))
				_speed_debug_log "STREAM_RESTORE_MEDIA_LIST_ENTRY_DROP entry=$_mp payload=$_mp key=$_mstem source=appList_network reason=json_key_missing remoteExists=unknown"
				continue
			fi
			_mex=0
			if awk -v n="$_mp" '$0==n{f=1;exit} END{exit f?0:1}' "$_mremote" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}; then
				_mex=1
			fi
			if [[ $_mex != 1 ]]; then
				_mdrop=$((_mdrop + 1))
				_speed_debug_log "STREAM_RESTORE_MEDIA_LIST_ENTRY_DROP entry=$_mp payload=$_mp key=$_mstem source=appList_network reason=remote_file_missing jsonMatch=1 remoteExists=0"
				continue
			fi
			printf '%s\n' "$_mp" >> "$_mlist" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
			_mcnt=$((_mcnt + 1))
			_speed_debug_log "STREAM_RESTORE_MEDIA_LIST_ENTRY entry=$_mp payload=$_mp key=$_mstem source=appList_network remoteExists=1 jsonMatch=1"
		done < "$_mselected"
		sort -u "$_mlist" -o "$_mlist" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
		_speed_debug_log "STREAM_RESTORE_MEDIA_LIST_RESOLVE source=appList_network count=$_mcnt dropped=$_mdrop out=$_mlist remoteList=${_mremote:-none} allMarker=$_mall guard=remote-file+json-key"
		[[ -s $_mlist ]] || return 1
	else
		if ! _restore_stream_media_list_from_appdetails "$_mstage/app_details.json" "$_mlist" "$_mremote"; then
			echoRgb "Media/app_details.json 沒有可恢復的自定義資料夾項目" "0"
			{
				echo "===== BAD_STREAM_MEDIA_LIST_DERIVE rel=$_RESTORE_SUBDIR/Media/app_details.json ====="
				echo "size=$(wc -c < "$_mstage/app_details.json" 2>/dev/null)"
				head -c 300 "$_mstage/app_details.json" 2>/dev/null | sed 's/^/  content: /'
				echo
			} >> "${SPEED_DEBUG_RUN_DIR:-/data/speed_debug}/bad_media_restore.log" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
			return 1
		fi
	fi
	Backup_folder2="$_mstage"
	_RESTORE_STREAM_MEDIA_LIST="$_mlist"
	_RESTORE_STREAM_MEDIA_READY=1
	echoRgb "流式 Media metadata 已下載，將依 appList_network.txt 選項恢復自定義資料夾壓縮包" "1"
	local _msel_rows _msource
	_msel_rows="$(grep -vc '^$' "$_mselected" 2>/dev/null)"
	_msource="app_details_json"
	[[ ${_msel_rows:-0} -gt 0 ]] && _msource="appList_network"
	_speed_debug_log "STREAM_RESTORE_MEDIA_PREPARE_OK source=$_msource list=$_mlist selectedRows=${_msel_rows:-0}"
	return 0
}

remote_stream_restore_media() {
	show_conf remote
	[[ -z $remote_type ]] && { _remote_type_missing_msg; return 1; }
	case $remote_type in
	smb|webdav) ;;
	*) echoRgb "流式恢復自定義資料夾僅支援 smb / webdav (目前 remote_type=$remote_type)" "0"; return 1 ;;
	esac
	local list="$MODDIR/appList_network.txt"
	if [[ ! -f $list ]]; then
		echoRgb "找不到 $list" "0"
		echoRgb "請先執行 '列出遠端備份' 產生清單，保留 Media 後再來流式恢復自定義資料夾" "3"
		return 1
	fi
	local _media_sel="$TMPDIR/.stream_restore_media_select_check.$$" _media_all=0
	: > "$_media_sel" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	_app_network_media_payload_list "$list" "$_media_sel" || true
	if _app_network_has_media_all_marker "$list"; then _media_all=1; fi
	if [[ $_media_all != 1 && ! -s $_media_sel ]]; then
		echoRgb "appList_network.txt 沒有 Media 或自定義資料夾壓縮包項目，沒有可流式恢復的自定義資料夾" "0"
		rm -f "$_media_sel" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
		return 1
	fi
	rm -f "$_media_sel" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	remote_parse_endpoint
	[[ $remote_type = smb ]] && remote_parse_smb_url
	if ! remote_precheck "$REMOTE_HOST" "$REMOTE_PORT"; then
		echoRgb "遠端連線失敗: $REMOTE_HOST:$REMOTE_PORT" "0"
		_remote_precheck_print_smb_issue
		return 1
	fi
	_remote_stream_fatal_reset "remote_stream_restore_media_start"
	_remote_netwatch_start
	_RESTORE_SUBDIR="$(get_backup_dirname)"
	if ! _remote_stream_source_precheck "$_RESTORE_SUBDIR"; then
		_speed_debug_log "REMOTE_STREAM_MEDIA_RESTORE_ABORT source_precheck_failed type=$remote_type host=$REMOTE_HOST port=$REMOTE_PORT subdir=$_RESTORE_SUBDIR"
		_remote_netwatch_finish
		return 1
	fi
	echoRgb "流式恢復自定義資料夾來源: $remote_type://$REMOTE_HOST/ ($_RESTORE_SUBDIR)" "3"
	_RESTORE_STREAM=1
	rm -rf "$TMPDIR/.restore_stage" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	mkdir -p "$TMPDIR/.restore_stage" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	Restore3
	local _rc=$?
	rm -rf "$TMPDIR/.restore_stage" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	_RESTORE_STREAM=0
	if _remote_stream_fatal_active; then
		_speed_debug_log "REMOTE_STREAM_MEDIA_RESTORE_END_FATAL $(_remote_stream_fatal_summary)"
		_remote_netwatch_finish
		return 1
	fi
	_remote_netwatch_finish
	return $_rc
}


# ===== 恢復選單與主流程 =====
Restore() {
	self_test
	if ! _appstate_require_main_capabilities "恢復"; then
		_speed_debug_normal_finish_pack 2
		exit 2
	fi
	_action_foreground_dex_display "恢復"
	disable_verify
	[[ ! -d $path2 ]] && echoRgb "設備不存在user目錄" "0" && exit 1
	# 預掃資料 (取代主迴圈內每 app fork)
	_prepare_timed prepare_pkg_uid_map
	_prepare_timed prepare_pkg_ver_map
	prepare_installed_pkgs_map
	# v24.20.14-7.6：恢復主迴圈期間必須保留 session maps。
	# Release_data() 會在每個 tar 解壓後呼叫 cleanup_tmpdir_contents()；
	# 若此 flag 沒有開啟，第 1 個 app 後 .installed_pkgs/.pkg_ver/.pkg_uid 會被刪除，
	# 第 2 個 app 起就會誤判為未安裝並重跑 APK 安裝。
	_RESTORE_KEEP_SESSION_MAPS=1
	_speed_debug_log "RESTORE_SESSION_MAP_KEEP_BEGIN keep=$_RESTORE_KEEP_SESSION_MAPS installed=$(wc -l < "$TMPDIR/.installed_pkgs" 2>/dev/null) pkg_ver=$(wc -l < "$TMPDIR/.pkg_ver" 2>/dev/null) pkg_uid=$(wc -l < "$TMPDIR/.pkg_uid" 2>/dev/null)"
	if [[ ! -f ${0%/*}/app_details.json ]]; then
		echoRgb "假設反悔了要終止腳本請儘速離開此腳本點擊$MODDIR_NAME/start.sh選擇終止腳本\n -否則腳本將繼續執行直到結束" "0"
		echoRgb "如果大量提示找不到資料夾請執行$MODDIR_NAME/start.sh選擇轉換資料夾名稱"
		txt="$MODDIR/appList.txt"
		# 流式恢復: 改用 appList_network.txt (功能8 產生), 過濾掉註解與特殊項(wifi/Media), 只留 app 行
		if [[ $_RESTORE_STREAM = 1 ]]; then
			local _stream_list_src="${_RESTORE_STREAM_LIST_FILE:-$MODDIR/appList_network.txt}"
			if [[ ! -f $_stream_list_src ]]; then
				echoRgb "appList_network.txt 不存在或被刪除，無法流式恢復" "0"
				_speed_debug_log "STREAM_RESTORE_LIST_MISSING source=$_stream_list_src original=$MODDIR/appList_network.txt mode=r370"
				exit 1
			fi
			if ! awk '
				/^[[:space:]]*[#＃]/ || /^[[:space:]]*$/ { next }
				{
					line=$0
					sub(/^[[:space:]]+/, "", line)
					sub(/[[:space:]]+$/, "", line)
					if (line == "wifi" || line == "Media") next
					if (line ~ /\.tar(\.zst)?$/) next
					print line
				}
			' "$_stream_list_src" > "$TMPDIR/.stream_restore_list" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}; then
				echoRgb "appList_network.txt 解析失敗: $_stream_list_src" "0"
				_speed_debug_log "STREAM_RESTORE_LIST_PARSE_FAIL source=$_stream_list_src mode=r370"
				exit 1
			fi
			txt="$TMPDIR/.stream_restore_list"
			if _restore_list_has_play_markers "$txt"; then
				_speed_debug_log "STREAM_RESTORE_PLAY_MARKER_SUPPORT list=$txt marker=1"
			fi
		fi
		[[ ! -f $txt ]] && echoRgb "請執行start.sh獲取應用列表再來恢復" "0" && exit 2
		_applist_home_last_file "$txt" "restore_source"
		i=1
		r="$(awk '!/[#＃]/ && NF{count++} END{print count}' "$txt" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null})"
		case "$r" in
		""|0) echoRgb "appList.txt包名為空或是被注釋了\n -請執行start.sh獲取應用列表再來恢復" "0"; exit 1 ;;
		esac
		if _restore_list_has_play_markers "$txt"; then
			if _restore_has_play_store; then
				echoRgb "檢測到 !Play 恢復標記，Google Play 商店可用，將走 Play UID hybrid session" "3"
				_speed_debug_log "PLAY_MARKER_LIST_CHECK result=ok stream=${_RESTORE_STREAM:-0} list=$txt"
			else
				echoRgb "檢測到 !Play 恢復標記，但 Google Play 商店不可用，對應 App 會回退原生 pm 安裝" "0"
				_speed_debug_log "PLAY_MARKER_LIST_CHECK result=fail stream=${_RESTORE_STREAM:-0} list=$txt fallback=pm"
			fi
		fi
		Backup_folder2="$MODDIR/Media"
		if [[ $_RESTORE_STREAM = 1 ]]; then
			_restore_stream_prepare_media || true
		fi
		#校驗選填是否正確
		[[ $recovery_mode != "" ]] && isBoolean "$recovery_mode" "recovery_mode" && recovery_mode="$nsx" || {
		echoRgb "選擇應用恢復模式\n -音量上僅恢復未安裝，下全恢復"
		get_version "恢復未安裝" "全恢復"; recovery_mode="$branch"
		}
		[[ $setDisplayPowerMode != "" ]] && isBoolean "$setDisplayPowerMode" "setDisplayPowerMode" && setDisplayPowerMode="$nsx" || {
		echoRgb "應用恢復時關閉螢幕\n -音量上關閉，下不關閉"
		get_version "關閉" "不關閉"; setDisplayPowerMode="$branch"
		}
		if [[ $_RESTORE_STREAM = 1 ]]; then
			Get_user="$(get_backup_dirname | grep -Eo '[0-9]+$')"
		else
			Get_user="$(echo "$MODDIR" | rev | cut -d '/' -f1 | cut -d '_' -f1 | rev | grep -Eo '[0-9]+')"
		fi
		if [[ $Get_user != $user ]]; then
			echoRgb "檢測當前用戶$user與恢復資料夾用戶:$Get_user不同，音量上繼續恢復，下不恢復並離開腳本"
			get_version "恢復安裝" "不恢復安裝"; recovery_mode2="$branch"
		fi
		if [[ -d $Backup_folder2 || $_RESTORE_STREAM_MEDIA_READY = 1 ]]; then
			[[ $media_recovery != "" ]] && isBoolean "$media_recovery" "media_recovery" && media_recovery="$nsx" || {
			echoRgb "是否恢復多媒體數據\n -音量上恢復，音量下不恢復" "2"
			get_version "恢復媒體數據" "跳過恢復媒體數據"; media_recovery="$branch"
			}
		fi
		[[ $Background_apps_ignore != "" ]] && isBoolean "$Background_apps_ignore" "Background_apps_ignore" && Background_apps_ignore="$nsx" || {
		echoRgb "存在進程忽略恢復\n -音量上忽略，音量下恢復" "2"
		get_version "忽略" "恢復"; Background_apps_ignore="$branch"
		}
		[[ $recovery_mode2 = false ]] && exit 2
		if [[ $recovery_mode = true && $ssaid_mode != true && $_RESTORE_STREAM != 1 ]]; then
			echoRgb "獲取未安裝應用中"
			Apk_info="$(_installed_app_packages "$user")"
			[[ $Apk_info = "" ]] && echoRgb "Apk_info變量為空" "0" && exit
			while read -r ; do
				local _reply_line _apk_pkg
				_reply_line="$(echo "$REPLY" | sed 's/^[ \t]*//')"
				if [[ $_reply_line != \#* ]]; then
					case "$_reply_line" in
					!play[[:space:]]*|！play[[:space:]]*)
						_reply_line="${_reply_line#*!play}"
						_reply_line="${_reply_line#*！play}"
						_reply_line="$(printf '%s\n' "$_reply_line" | sed 's/^[ \t]*//')"
						;;
					![[:space:]]*|！[[:space:]]*|!*)
						_reply_line="${_reply_line#!}"
						_reply_line="${_reply_line#！}"
						_reply_line="$(printf '%s\n' "$_reply_line" | sed 's/^[ \t]*//')"
						;;
				esac
					_list_name="${_reply_line%% *}"
					_apk_pkg="${_reply_line#* }"
					_apk_pkg="${_apk_pkg%% *}"
					if [[ $_list_name != "" && $_apk_pkg != "" && $_apk_pkg != "$_reply_line" ]]; then
						[[ $(echo "$Apk_info" | awk -v pkg="$_apk_pkg" '$1 == pkg {print $1}') = "" ]] && Tmplist="$Tmplist\n$REPLY"
					fi
				fi
			done < "$txt"
			if [[ $(echo "$Tmplist" | awk 'NF != 0 { count++ } END { print count }') != "" ]]; then
				echoRgb "獲取完成 預計安裝$(echo "$Tmplist" | awk 'NF != 0 { count++ } END { print count }')個應用"
				txt="$Tmplist"
				echoRgb "未安裝應用列表\n$txt" "1"
				if ! ask_yn "確認恢復?" "恢復安裝" "退出腳本"; then
					exit
				fi
			else
				echoRgb "獲取完成 但備份內應用都已安裝....正在退出腳本" "0" && exit 0
			fi
		fi
		if [[ $ssaid_mode = true ]]; then
			# 改 here-string 為暫存檔 (mksh 不支援 <<<)
			# 用暫存檔取代 ssaid_name 字串拼接 (O(N²) → O(N))
			local _find_tmp="$TMPDIR/.find_ssaid_$$"
			local _ssaid_tmp="$TMPDIR/.ssaid_list_$$"
			_appdetails_index_paths "$MODDIR" "$_find_tmp" 2 0 1 >/dev/null 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} || true
			: > "$_ssaid_tmp"
			while read -r; do
				if [[ $(_appdetails_get_first_ssaid "$REPLY") != "" ]]; then
					ChineseName="$(_appdetails_get_first_entry_name "$REPLY")"
					PackageName="$(_appdetails_get_first_pkg "$REPLY")"
					echo "$ChineseName $PackageName" >> "$_ssaid_tmp"
				fi
			done < "$_find_tmp"
			[[ -s $_ssaid_tmp ]] && ssaid_name="$(cat "$_ssaid_tmp")"
			rm -f "$_find_tmp" "$_ssaid_tmp"
			[[ $ssaid_name != "" ]] && txt="$ssaid_name"
		fi
		if [[ ! -f $txt ]]; then
			[[ -n $txt ]] && txt="$(echo "$txt" | sed -e '/^$/d')"
		else
			txt="$(grep -Ev '#|＃' "$txt" | sed -e '/^$/d')"
		fi
		# r86: 不只來源 appList 檔案要 HOME 後置；recovery_mode/ssaid_mode 生成的文字清單也必須在最終恢復順序前再後置一次。
		[[ -n $txt ]] && txt="$(_applist_home_last_text "$txt" "restore_effective_text")"
		r="$(echo "$txt" | awk 'NF != 0 { count++ } END { print count }')"
		DX="批量恢復"
	else
		i=1
		r=1
		Backup_folder="$MODDIR"
		app_details="$Backup_folder/app_details.json"
		if [[ ! -f $app_details ]]; then
			echoRgb "$app_details遺失，無法獲取包名" "0" && exit 1
		else
			ChineseName="$(_appdetails_get_first_entry_name "$app_details")"
			PackageName="$(_appdetails_get_first_pkg "$app_details")"
			apk_version="$(_appdetails_get_first_apk_version "$app_details")"
		fi
		name1="$ChineseName"
		name1="${name1:="${Backup_folder##*/}"}"
		[[ $name1 = "" ]] && echoRgb "應用名獲取失敗" "0" && exit 2
		name2="$PackageName"
		[[ $name2 = "" ]] && echoRgb "包名獲取失敗" "0" && exit 2
		DX="單獨恢復"
		_speedscan_restore_payload_precheck "$Backup_folder" "$name1" || true
		[[ $Background_apps_ignore != "" ]] && isBoolean "$Background_apps_ignore" "Background_apps_ignore" && Background_apps_ignore="$nsx" || {
		echoRgb "存在進程忽略恢復\n -音量上忽略，音量下恢復" "2"
		get_version "忽略" "恢復"; Background_apps_ignore="$branch"
		}
	fi
	#開始循環$txt內的資料進行恢復
	#記錄開始時間
	starttime1="$(date -u "+%s")"
	TIME="$starttime1"
	Set_screen_pause_seconds on
	_restore_media_space_skip_state_init
	en=118
	_restore_notify_fixed_progress 1 "$r" 0 "開始恢復app"
	# 啟用AppState批量模式: 迴圈內 restore_appstate 只收集到暫存檔, 迴圈結束後 flush 一次沖刷；單 app/外部呼叫會自動臨時 batch+flush
	# 此迴圈同時服務批量恢復(N個app)與單獨恢復(1個app); 單獨恢復時收集1組→flush設1組, 等價立即執行
	_batch_appstate_mode=1
	_RESTORE_PRESERVE_BATCH_QUEUE=1
	RESTORE_LOW_RISK_GUARD_TRIM_COUNT=0
	# 清空本輪批量恢復暫存，installer/電池也一併清，避免同一 shell session 內殘留
: > "$TMPDIR/.batch_appstate_ndjson" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	_restore_install_issue_reset
	_restore_framework_facts_prefetch || _speed_debug_log "RESTORE_FRAMEWORK_FACTS_PREFETCH_SKIP reason=unavailable mode=r416"
	_restore_package_facts_prefetch "$txt" "$r" || _speed_debug_log "RESTORE_PACKAGE_FACTS_PREFETCH_SKIP reason=unavailable mode=r416"
	# APK 安裝維持逐 app 流程：每個 app 解壓成功後立即安裝，再恢復 data/appstate。
	# 預設使用備份 installer 條件式 hybrid_installer_pm；installer 不存在/無 UID 就退回原生 pm，不做無效來源偽裝。
	# 需要 packageSource=STORE 的個別 app 才能在 appList.txt 行首加 !play 走慢速 Play session。
	# r245: hybrid_installer_pm 失敗後不在同一 App 連續重試；本 App 回退原生 pm，下一個符合條件的 App 再探測一次。
	# 只有連續兩個不同 App 的 hybrid 安裝都失敗，才停用本輪後續 hybrid。
	_restore_hybrid_installer_pm_disabled=0
	_restore_hybrid_installer_pm_consecutive_fail=0
	_speedbackup_progress_hint "正在啟動批量恢復守護 session（預設瞬殺，固定高風險 App 才強凍結）" "restore_batch_guard_prewarm"
	_cgroup_freezer_batch_daemon_ensure "restore-batch" || true
	_process_observer_restore_session_start || true
	_process_observer_guard_hint_once "restore-batch" || true
	while [[ $i -le $r ]]; do
		if [[ $remote_stream = 1 && -n $remote_type ]] && _remote_stream_fatal_active; then
			_remote_connectivity_fast_fail "restore_app_loop_top" "app_index_$i" "restore_loop_remote_fatal" >/dev/null 2>&1 || true
			echoRgb "遠端流式已中斷，停止本輪後續應用恢復" "0"
			_speed_debug_log "REMOTE_STREAM_FATAL_ABORT_APP_LOOP i=$i total=$r $(_remote_stream_fatal_summary)"
			break
		fi
		[[ $en -ge 229 ]] && en=118
		if [[ ! -f ${0%/*}/app_details.json ]]; then
			echoRgb "恢復第$i/$r個應用 剩下$((r - i))個" "3"
			_restore_notify_fixed_progress "$i" "$r" 0 "恢復第$i/$r個應用 剩下$((r - i))個"
			# 一次 sed 抓行, 用 parameter expansion 拆欄位
			_line="$(echo "$txt" | sed -n "${i}p")"
			_restore_force_play_session=0
			_restore_force_play_marker=""
			case "$_line" in
			!play[[:space:]]*|！play[[:space:]]*)
				_restore_force_play_session=1
				_restore_force_play_marker="!play"
				_line="${_line#*!play}"
				_line="${_line#*！play}"
				_line="$(printf '%s\n' "$_line" | sed 's/^[ \t]*//')"
				;;
			![[:space:]]*|！[[:space:]]*|!*)
				_restore_force_play_session=1
				_restore_force_play_marker="!"
				_line="${_line#!}"
				_line="${_line#！}"
				_line="$(printf '%s\n' "$_line" | sed 's/^[ \t]*//')"
				;;
			esac
			[[ $_RESTORE_STREAM = 1 && ${_restore_force_play_session:-0} = 1 ]] && _speed_debug_log "STREAM_RESTORE_PLAY_MARKER_APPLY marker=${_restore_force_play_marker:-!} app=${_line%% *}"
			name1="${_line%% *}"
			name2="${_line#* }"
			name2="${name2%% *}"
			unset _line
			unset No_backupdata apk_version
			if [[ $name1 = *! || $name1 = *！ ]]; then
				name1="${name1//!/}"
				name1="${name1//！/}"
				echoRgb "跳過恢復$name1 所有數據" "0"
				No_backupdata=1
			fi
			_backup_path_sanitize_current_name
			Backup_folder="$MODDIR/$name1"
			[[ $_RESTORE_STREAM != 1 ]] && _speedscan_restore_payload_precheck "$Backup_folder" "$name1" || true
			# 流式恢復: 本地無備份, 從遠端拉 app_details.json 到 TMPDIR staging
			if [[ $_RESTORE_STREAM = 1 ]]; then
				Backup_folder="$TMPDIR/.restore_stage/$name1"
				mkdir -p "$Backup_folder" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
				# r277: app_details 已在進入流式恢復前由 app_details_bundle.tar.zst 一次性解壓到 .restore_stage。
				# 不再逐 App 下載 $_RESTORE_SUBDIR/$name1/app_details.json。
				_speed_debug_log "STREAM_RESTORE_APPDETAILS_BUNDLE_USE app=$name1 file=$Backup_folder/app_details.json mode=single-stage-r286"
				# 下載內容可能為空/非合法 json (遠端檔案不存在、傳輸中斷等), 先驗證再解析,
				# 避免 jq parse error 把 name2 弄成空值後整輪 exit 1 砍掉還沒處理的其餘 app。
				if [[ ! -s "$Backup_folder/app_details.json" ]] || ! _appdetails_json_parse_ok "$Backup_folder/app_details.json"; then
					if grep -Eq 'NT_STATUS_OBJECT_NAME_NOT_FOUND|NT_STATUS_OBJECT_PATH_NOT_FOUND|does not exist' "$Backup_folder/app_details.json" 2>/dev/null; then
						echoRgb "$name1 遠端不存在 (清單可能未更新), 跳過此應用" "0"
					else
						echoRgb "$name1 的 app_details.json 下載失敗或內容損毀, 跳過此應用" "0"
					fi
					{
						echo "===== BAD_APP_DETAILS $name1 rel=$_RESTORE_SUBDIR/$name1/app_details.json ====="
						if [[ -f "$Backup_folder/app_details.json" ]]; then
							_bad_size="$(wc -c < "$Backup_folder/app_details.json" 2>/dev/null)"
							case "$_bad_size" in ''|*[!0-9]*) _bad_size=0 ;; esac
							echo "size=$_bad_size"
							head -c 300 "$Backup_folder/app_details.json" 2>/dev/null | sed 's/^/  content: /'
						else
							echo "size=0"
							echo "missing=1"
						fi
						echo
					} >> "${SPEED_DEBUG_RUN_DIR:-/data/speed_debug}/bad_app_details.log" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
					unset _bad_size
					rm -rf "$Backup_folder" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
					unset _restore_force_play_session _restore_force_play_marker
					let i++ en++ nskg++
					continue
				fi
			fi
			if [[ -f "$Backup_folder/app_details.json" ]]; then
				app_details="$Backup_folder/app_details.json"
				apk_version="$(_appdetails_get_first_apk_version "$app_details")"
				# 流式: 列表(appList_network.txt)只有資料夾名, 包名 name2 從 json 的 PackageName 取
				if [[ $_RESTORE_STREAM = 1 ]]; then
					name2="$(_appdetails_get_first_pkg "$app_details")"
				fi
			else
				echoRgb "$Backup_folder/app_details.json不存在" "0"
			fi
			if [[ $name2 = "" ]]; then
				echoRgb "$name1 應用包名獲取失敗, 跳過此應用" "0"
				if [[ $_RESTORE_STREAM = 1 ]]; then
					rm -rf "$Backup_folder" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
					unset _restore_force_play_session _restore_force_play_marker
					let i++ en++ nskg++
					continue
				else
					exit 1
				fi
			fi
		fi
		_speedbackup_restore_label_strict_gate "$name1" "$name2" "restore_loop" || { [[ $_RESTORE_STREAM = 1 ]] && rm -rf "$Backup_folder" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}; unset _restore_force_play_session _restore_force_play_marker; let i++ en++ nskg++; continue; }
		_restore_notify_fixed_progress "$i" "$r" 5 "恢復第$i/$r：讀取metadata $name1"
		# 流式恢復: Backup_folder 是 staging (只有 json), 視為存在以進入恢復流程
		if [[ -d $Backup_folder ]] || [[ $_RESTORE_STREAM = 1 ]]; then
			echoRgb "恢復$name1" "2"
			Background_application_list
			restore="true"
			if [[ $Backstage != "" ]] && printf '%s\n' "$Backstage" | awk -v p="$name2" '$0==p{found=1} END{exit !found}'; then
				echoRgb "$name1存在前台/後台，忽略恢復" "0"
				restore="false"
			fi
			[[ $restore = true ]] && {
			starttime2="$(date -u "+%s")"
			local _restore_app_total_t0 _restore_pkg_status_t0 _restore_data_phase_t0 _restore_appstate_phase_t0 _restore_guard_final_t0 _restore_lowrisk_guard_trimmed
			_restore_app_total_t0="$(_speed_now_ms)"
			# r101: 恢復端 installed/version/uid 預掃只當 cache；處理每個 App 時即時查單包 packageStatus 校正。
			local _is_installed
			_is_installed=""
			RESTORE_PKG_VISIBLE_AFTER_INSTALL_OK=0
			_restore_pkg_status_t0="$(_speed_now_ms)"
			_restore_package_status_refresh "$name2" "restore_pre_app" || _speed_debug_log "RESTORE_PACKAGE_STATUS_WARN package=$name2 reason=pre_app_failed fallback=cache"
			_restore_phase_timing_record "pm_pre_status" "$_restore_pkg_status_t0" "$name1" "$name2" "installed=${RESTORE_PKG_INSTALLED:-unknown} uid=${RESTORE_PKG_UID:-unknown} ver=${RESTORE_PKG_VER:-unknown}" "0"
			case $RESTORE_PKG_INSTALLED in true|1) _is_installed=1 ;; *) _is_installed="" ;; esac
			_restore_notify_fixed_progress "$i" "$r" 15 "恢復第$i/$r：檢查安裝狀態 $name1"
			local _apk_plan _apk_plan_action _apk_plan_reason _apk_verify_start _apk_verify_ms _apk_skip_action
			_apk_plan="$(_restore_package_compare_apk_plan_get "$name2" 2>/dev/null || true)"
			_apk_plan_action="$(printf '%s\n' "$_apk_plan" | awk -F '\t' '{print $1}')"
			_apk_plan_reason="$(printf '%s\n' "$_apk_plan" | awk -F '\t' '{print $2}')"
			[[ -n $_apk_plan_action ]] && _speed_debug_log "RESTORE_APK_PLAN package=$name2 label=$name1 apkAction=$_apk_plan_action apkReason=${_apk_plan_reason:-} mode=r416 source=compare_map"
			# 流式: 設定 apk 遠端來源 (installapk 會用)
			# 流式: 設定 apk 遠端來源 (依壓縮方式決定後綴)
			if [[ $_RESTORE_STREAM = 1 ]]; then
				case $Compression_method in
				tar|Tar|TAR) _STREAM_APK_SRC="$_RESTORE_SUBDIR/$name1/apk.tar" ;;
				*) _STREAM_APK_SRC="$_RESTORE_SUBDIR/$name1/apk.tar.zst" ;;
				esac
			fi
			local _was_installed="${RESTORE_PKG_PREINSTALLED:-$_is_installed}"
			# r481: preRestorePackageStateBatch emits explicit false for missing packages.
			# Do not treat non-empty "false" as preinstalled; recovery_mode must only skip data
			# when the app truly existed before this restore pass.
			if _speedbackup_bool_on "$_was_installed"; then
				_was_installed=1
			else
				_was_installed=""
			fi
			_speed_debug_log "RESTORE_PREINSTALLED_BOOL_NORMALIZE package=$name2 label=$name1 raw=${RESTORE_PKG_PREINSTALLED:-unset} installedBefore=${_was_installed:-0} mode=r481"
			if [[ -z $_is_installed ]]; then
				_restore_notify_fixed_progress "$i" "$r" 25 "恢復第$i/$r：安裝APK $name1"
				RESTORE_APK_ACTION_CONTEXT="install"
				# r435: 非 owner user 先嘗試把已存在於其他 user/owner 的 package 啟用到目前 user。
				# owner user 預設直接 APK install，避免大批量全量恢復時每個 missing App 多一次 pm/cmd install-existing 探測。
				local _install_existing_used=0 _install_existing_ver="" _try_install_existing=0
				_apk_verify_ms=0
				case ${user:-0} in
				0) [[ ${SPEEDBACKUP_RESTORE_INSTALL_EXISTING_FOR_OWNER:-0} = 1 ]] && _try_install_existing=1 ;;
				*) _try_install_existing=1 ;;
				esac
				if [[ $_try_install_existing = 1 ]] && _restore_pm_install_existing_for_user "$name2" "$name1" "$apk_version"; then
					_install_existing_used=1
					_install_existing_ver="${RESTORE_PKG_VER:-}"
					_is_installed=1
					result=0
					RESTORE_APK_TIMING_EXTRACT_MS=0
					RESTORE_APK_TIMING_INSTALL_MS=0
					RESTORE_APK_TIMING_COMMIT_MS=0
					RESTORE_APK_TIMING_TOTAL_MS=0
					RESTORE_APK_TIMING_BYTES=0
					_apk_verify_ms=0
					case $apk_version in
					''|null|NULL|*[!0-9]*) ;;
					*)
						case $_install_existing_ver in
						''|null|NULL|*[!0-9]*) ;;
						*)
							if [[ $apk_version -gt $_install_existing_ver ]]; then
								echoRgb "既有安裝版本$_install_existing_ver 低於備份版本$apk_version，嘗試 APK 更新" "2"
								RESTORE_APK_ACTION_CONTEXT="update_after_install_existing"
								installapk
								local _upgrade_after_existing_result="${result:-1}"
								_apk_verify_start="$(_speed_now_ms)"
								if _pkg_uid_map_refresh_after_install "$name2"; then
									_apk_verify_ms="$(_restore_elapsed_ms "$_apk_verify_start")"
									_is_installed=1
									if [[ $_upgrade_after_existing_result = 0 ]]; then
										echoRgb "APK更新完成" "1"
									else
										echoRgb "APK更新失敗，但既有安裝已啟用，改用現有安裝恢復資料" "0"
										_restore_install_issue_record "$name2" "$name1" "install_existing_then_update_failed_existing_package_used" "current=$_install_existing_ver backup=$apk_version result=$_upgrade_after_existing_result"
									fi
								else
									_apk_verify_ms="$(_restore_elapsed_ms "$_apk_verify_start")"
									_is_installed=0
									echoRgb "既有安裝啟用後狀態消失，跳過資料/AppState恢復" "0"
									_restore_install_issue_record "$name2" "$name1" "install_existing_then_update_package_unavailable" "current=$_install_existing_ver backup=$apk_version result=$_upgrade_after_existing_result"
								fi
							fi
							;;
						esac
						;;
					esac
				fi
				if [[ $_install_existing_used != 1 ]]; then
					installapk
					# r336: commit rc=0 只代表 installer/session 接受；安裝後必須再次查 PackageManager。
					local _install_result="${result:-1}"
					if [[ $_install_result = 0 ]]; then
						_apk_verify_start="$(_speed_now_ms)"
						if _pkg_uid_map_refresh_after_install "$name2"; then
							_apk_verify_ms="$(_restore_elapsed_ms "$_apk_verify_start")"
							_is_installed=1
							case $apk_version in ''|null|NULL|*[!0-9]*) echoRgb "全新安裝完成" "1" ;; *) echoRgb "全新安裝版本>$apk_version" "1" ;; esac
						else
							_apk_verify_ms="$(_restore_elapsed_ms "$_apk_verify_start")"
							_is_installed=0
							result=1
							echoRgb "APK提交成功但系統仍找不到 $name2，跳過資料/AppState恢復" "0"
							_restore_install_issue_record "$name2" "$name1" "install_success_but_package_missing" "phase=new_install apkVersion=${apk_version:-unknown}"
						fi
					else
						_is_installed=0
						_restore_install_issue_record "$name2" "$name1" "install_failed_not_installed" "phase=new_install result=$_install_result apkVersion=${apk_version:-unknown}"
					fi
				else
					_install_result=0
				fi
				RESTORE_APK_TIMING_VERIFY_MS="$_apk_verify_ms"
				if [[ $_install_existing_used = 1 ]]; then
					_restore_apk_timing_record "$name2" "$name1" "${RESTORE_APK_TIMING_BYTES:-0}" "${_install_existing_ver:-}" "${apk_version:-}" "install_existing" "${RESTORE_APK_TIMING_EXTRACT_MS:-0}" "${RESTORE_APK_TIMING_INSTALL_MS:-0}" "${RESTORE_APK_TIMING_COMMIT_MS:-0}" "$_apk_verify_ms" "${RESTORE_APK_TIMING_TOTAL_MS:-0}" "new_install_existing_result_${result:-0}"
				else
					_restore_apk_timing_record "$name2" "$name1" "${RESTORE_APK_TIMING_BYTES:-0}" "" "${apk_version:-}" "install" "${RESTORE_APK_TIMING_EXTRACT_MS:-0}" "${RESTORE_APK_TIMING_INSTALL_MS:-0}" "${RESTORE_APK_TIMING_COMMIT_MS:-0}" "$_apk_verify_ms" "${RESTORE_APK_TIMING_TOTAL_MS:-0}" "new_install_result_${result:-$_install_result}"
				fi
				if [[ $_RESTORE_STREAM = 1 ]] && _remote_stream_fatal_active; then
					_speed_debug_log "STREAM_RESTORE_ABORT_CURRENT_APP reason=remote_stream_fatal app=$name1 stage=apk_install result=${result:-}"
					break
				fi
			else
				# 已裝, 比版本決定要不要 reinstall。
				# v24.20.14-7.4：map 命中失敗不可再當 0，避免已安裝同版 app 被誤判成「全新安裝」。
				local _cur_ver
				_cur_ver="${RESTORE_PKG_VER:-}"
				case $_cur_ver in ''|*[!0-9]*) _cur_ver="$(_kv_file_get "$TMPDIR/.pkg_ver" "$name2" | tr -d ' \t\r\n')" ;; esac
				[[ -z $_cur_ver ]] && _cur_ver="$(get_current_apk_version_code "$name2")"
				case $_apk_plan_action in skip_same_version|skip_newer_local|skip_installed_uncomparable)
					_speed_debug_log "RESTORE_APK_STAGE_EARLY_SKIP package=$name2 label=$name1 apkAction=$_apk_plan_action apkReason=${_apk_plan_reason:-} current=${_cur_ver:-} backup=${apk_version:-} mode=r416 source=compare_map"
					;;
				esac
				case $apk_version in ''|null|NULL|*[!0-9]*)
					# 備份版本不是純數字時不能安全比較；既然已安裝，就跳過 APK 安裝，只恢復 data/appstate。
					echoRgb "已安裝，備份版本不可比對，跳過APK安裝" "2"
					_restore_apk_timing_record "$name2" "$name1" 0 "${_cur_ver:-}" "${apk_version:-}" "skip_installed_uncomparable" 0 0 0 0 0 "installed_backup_version_uncomparable"
					;;
				*)
					case $_cur_ver in ''|null|NULL|*[!0-9]*)
						# 已安裝但目前版本讀不到：安全策略是跳過，而不是把空值當 0 觸發安裝。
						echoRgb "已安裝，當前版本讀取失敗，跳過APK安裝" "0"
						SpeedDebug_log "WARN: installed_version_map_miss package=$name2 backupVersion=$apk_version skip_apk_install=1"
						_restore_apk_timing_record "$name2" "$name1" 0 "${_cur_ver:-}" "${apk_version:-}" "skip_version_read_failed" 0 0 0 0 0 "installed_version_map_miss"
						;;
					*)
						if [[ $apk_version -gt $_cur_ver ]]; then
							_restore_notify_fixed_progress "$i" "$r" 25 "恢復第$i/$r：更新APK $name1"
							RESTORE_APK_ACTION_CONTEXT="update"
							installapk
							local _upgrade_result="${result:-1}"
							_apk_verify_ms=0
							if [[ $_upgrade_result = 0 ]]; then
								_apk_verify_start="$(_speed_now_ms)"
								if _pkg_uid_map_refresh_after_install "$name2"; then
									_apk_verify_ms="$(_restore_elapsed_ms "$_apk_verify_start")"
									_is_installed=1
									echoRgb "版本提升${_cur_ver}>$apk_version" "1"
								else
									_apk_verify_ms="$(_restore_elapsed_ms "$_apk_verify_start")"
									_is_installed=0
									result=1
									echoRgb "APK更新提交成功但系統找不到 $name2，跳過資料/AppState恢復" "0"
									_restore_install_issue_record "$name2" "$name1" "upgrade_success_but_package_missing" "current=$_cur_ver backup=$apk_version"
								fi
							else
								_apk_verify_start="$(_speed_now_ms)"
								if _pkg_uid_map_refresh_after_install "$name2"; then
									_apk_verify_ms="$(_restore_elapsed_ms "$_apk_verify_start")"
									_is_installed=1
									echoRgb "APK更新失敗，但目前已安裝版本仍可用，改用現有安裝恢復資料" "0"
									_restore_install_issue_record "$name2" "$name1" "upgrade_install_failed_existing_package_used" "current=$_cur_ver backup=$apk_version result=$_upgrade_result"
								else
									_apk_verify_ms="$(_restore_elapsed_ms "$_apk_verify_start")"
									_is_installed=0
									echoRgb "APK更新失敗且系統找不到 $name2，跳過資料/AppState恢復" "0"
									_restore_install_issue_record "$name2" "$name1" "upgrade_install_failed_package_unavailable" "current=$_cur_ver backup=$apk_version result=$_upgrade_result"
								fi
							fi
							RESTORE_APK_TIMING_VERIFY_MS="$_apk_verify_ms"
							_restore_apk_timing_record "$name2" "$name1" "${RESTORE_APK_TIMING_BYTES:-0}" "$_cur_ver" "$apk_version" "update" "${RESTORE_APK_TIMING_EXTRACT_MS:-0}" "${RESTORE_APK_TIMING_INSTALL_MS:-0}" "${RESTORE_APK_TIMING_COMMIT_MS:-0}" "$_apk_verify_ms" "${RESTORE_APK_TIMING_TOTAL_MS:-0}" "upgrade_result_${result:-$_upgrade_result}"
						else
							echoRgb "已安裝版本$_cur_ver，跳過APK安裝" "2"
							_speed_debug_log "RESTORE_APK_INSTALL_SKIP package=$name2 label=$name1 reason=installed_version_sufficient current=$_cur_ver backup=$apk_version mode=r416"
							case $apk_version:$_cur_ver in *[!0-9]*:*) _apk_skip_action="skip_installed_uncomparable" ;; *:*) if [[ $_cur_ver -gt $apk_version ]]; then _apk_skip_action="skip_newer_local"; else _apk_skip_action="skip_same_version"; fi ;; esac
							_restore_apk_timing_record "$name2" "$name1" 0 "$_cur_ver" "$apk_version" "${_apk_skip_action:-skip_same_version}" 0 0 0 0 0 "installed_version_sufficient"
						fi
						;;
					esac
					;;
				esac
			fi
			_restore_notify_fixed_progress "$i" "$r" 40 "恢復第$i/$r：APK處理完成 $name1"
			# 流式 + 僅恢復未安裝模式: 僅「恢復前已安裝」才跳過數據恢復；
			# r481 修正 r480 preRestorePackageStateBatch false 被 -n 誤當已安裝。
			if [[ $_RESTORE_STREAM = 1 && $recovery_mode = true ]] && _speedbackup_bool_on "$_was_installed"; then
				echoRgb "$name1 已安裝, 僅恢復未安裝模式下跳過數據恢復" "2"
			elif [[ $_is_installed = 1 ]]; then
				if [[ $No_backupdata = "" ]]; then
				    [[ $name2 != *mt* ]] && {
					_restore_data_phase_t0="$(_speed_now_ms)"
					_restore_lowrisk_guard_trimmed=0
					# r240: 恢復也只讓硬編碼高風險 App 先嘗試 cgroup；一般 App 預設瞬殺。
					_speed_debug_log "PROGRESS_HINT_SUPPRESS_ONCE_ONLY tag=restore_guard_start app=$name1 package=$name2 msg=正在啟動恢復守護"
					if _restore_lowrisk_guard_trim_app "$name2" "$name1" "restore_app_scope" "${_is_installed:-0}" "${_was_installed:-0}"; then
						_restore_lowrisk_guard_trimmed=1
					else
						_cgroup_freezer_start_app "$name2" "$name1" "restore_app_scope" || true
						if [[ -n ${CGROUP_FREEZER_APP_TOKEN:-} && ${CGROUP_FREEZER_APP_PKG:-} = "$name2" ]]; then
							_speed_debug_log "CGROUP_GUARD_ACTIVE_SKIP_FALLBACK pkg=$name2 label=$name1 stage=restore_app_scope token=${CGROUP_FREEZER_APP_TOKEN:-} iconGrey=false"
						else
							kill_app
							_speed_debug_log "QUIESCE_ENTRY_CGROUP_ONLY pkg=$name2 label=$name1 reason=restore_app_scope_fallback iconGrey=false"
						fi
						_uid_netblock_start_app "$name2" "$name1" "restore_app_scope" || true
						if _speedbackup_cgroup_fast_settle_default_ime_pkg "$name2"; then _speed_debug_log "PROCESS_OBSERVER_RESTORE_CGROUP_FREEZE_ACTION package=$name2 label=$name1 reason=default_ime mode=r370"; fi
						_process_observer_start_app "$name2" "$name1" "restore_app_scope" || true
						_restore_live_guard_scope_start "$name2" "$name1" "restore_app_scope" || true
					fi
					if [[ $_RESTORE_STREAM = 1 ]]; then
						_restore_notify_fixed_progress "$i" "$r" 50 "恢復第$i/$r：恢復資料 $name1"
						# 流式: 枚舉資料類型, 設 _STREAM_SRC 遠端路徑, 逐個流式解壓
						local _dt
						# 流式恢復納入 thanox/hma 專屬系統配置。
						for _dt in user data obb user_de thanox hma; do
						if _remote_stream_fatal_active; then
							_speed_debug_log "STREAM_RESTORE_ABORT_DATA_LOOP reason=remote_stream_fatal app=$name1 stage=before_dt dt=$_dt"
							break
						fi
						# 只恢復遠端 json 有記錄的資料 (Size 存在表示有備份)
						local _has
						if [[ -s $app_details ]]; then
							_has="$(_appdetails_get_entry_size "$app_details" "$_dt")"
						else
							_has=""
						fi
						[[ -z $_has || $_has = null ]] && continue
						case $Compression_method in
						tar|Tar|TAR) _STREAM_SRC="$_RESTORE_SUBDIR/$name1/$_dt.tar" ;;
						*) _STREAM_SRC="$_RESTORE_SUBDIR/$name1/$_dt.tar.zst" ;;
						esac
						case $_dt in
						user) _restore_notify_fixed_progress "$i" "$r" 55 "恢復第$i/$r：解壓user $name1" ;;
						data) _restore_notify_fixed_progress "$i" "$r" 63 "恢復第$i/$r：解壓data $name1" ;;
						obb) _restore_notify_fixed_progress "$i" "$r" 71 "恢復第$i/$r：解壓obb $name1" ;;
						user_de) _restore_notify_fixed_progress "$i" "$r" 79 "恢復第$i/$r：解壓user_de $name1" ;;
						thanox) _restore_notify_fixed_progress "$i" "$r" 84 "恢復第$i/$r：解壓thanox $name1" ;;
						hma) _restore_notify_fixed_progress "$i" "$r" 88 "恢復第$i/$r：解壓hma $name1" ;;
						*) _restore_notify_fixed_progress "$i" "$r" 60 "恢復第$i/$r：解壓資料 $name1" ;;
						esac
						if _restore_stream_payload_known_missing "$_STREAM_SRC"; then
							_speed_debug_log "RESTORE_PAYLOAD_REMOTE_MISSING app=$name1 package=$name2 entry=$_dt rel=$_STREAM_SRC action=skip_before_release mode=r377"
							echoRgb "$name1 缺少遠端檔案 $_dt，已略過此 payload 並繼續恢復" "0"
							continue
						fi
						Release_data "$Backup_folder/${_STREAM_SRC##*/}"
						if _remote_stream_fatal_active; then
							_speed_debug_log "STREAM_RESTORE_ABORT_DATA_LOOP reason=remote_stream_fatal app=$name1 stage=after_dt dt=$_dt src=$_STREAM_SRC"
							break
						fi
						done
						unset _STREAM_SRC
    					if _remote_stream_fatal_active; then
    						_speed_debug_log "STREAM_RESTORE_ABORT_CURRENT_APP reason=remote_stream_fatal app=$name1"
    						# r69: 目前 App 在 restore_app_scope 已被 suspend；遠端 fatal 直接跳到下一個 App 前必須先解凍。
    						_process_observer_stop_app "restore_stream_fatal" || true
    						_uid_netblock_stop_app "restore_stream_fatal" || true
    						_cgroup_freezer_stop_app "restore_stream_fatal" || true
    						_live_app_resume_paused
    						continue
    					fi
					else
    					_restore_tar_payloads="$TMPDIR/.restore_tar_payloads_${$}_$RANDOM.lst"
    					_speedscan_tar_payloads "$Backup_folder" "$_restore_tar_payloads" 1 >/dev/null 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
    					while read -r REPLY; do
    						case "${REPLY##*/}" in apk.*|speed_debug_*.tar|speed_debug_*.tar.zst) continue ;; esac
    						Release_data "$REPLY"
    					done < "$_restore_tar_payloads"
    					rm -f "$_restore_tar_payloads" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
					fi
					_restore_phase_timing_record "data_payloads" "$_restore_data_phase_t0" "$name1" "$name2" "stream=${_RESTORE_STREAM:-0}" "0"
					_restore_speedscan_facts_phase "$path2/$user/0/$name2" "$name1" "post_data_user" >/dev/null 2>&1 || true
					_restore_speedscan_facts_phase "$path3/$user/0/$name2" "$name1" "post_data_de" >/dev/null 2>&1 || true
					unset G
					_restore_notify_fixed_progress "$i" "$r" 90 "恢復第$i/$r：暫存AppState $name1"
					_restore_appstate_phase_t0="$(_speed_now_ms)"
					if ! restore_appstate; then
						_speed_debug_log "RESTORE_APPSTATE_SKIPPED package=${name2:-} reason=canonical_record_invalid"
						_restore_phase_timing_record "appstate_queue" "$_restore_appstate_phase_t0" "$name1" "$name2" "result=skipped" "1"
					else
						_restore_phase_timing_record "appstate_queue" "$_restore_appstate_phase_t0" "$name1" "$name2" "result=queued" "0"
					fi
					_restore_guard_final_t0="$(_speed_now_ms)"
					_restore_guard_final_detail="procwait=pkg-gone"
					if [[ ${_restore_lowrisk_guard_trimmed:-0} = 1 ]]; then
						_speed_debug_log "RESTORE_LOW_RISK_GUARD_TRIM_FINAL_KEEP pkg=$name2 label=$name1 reason=restore_app_scope_done release=bulk-post-appstate policy=new-install-batch-session-covers-inactive-lowrisk mode=r481"
						_restore_guard_final_detail="lowrisk-guard-trim-session-keep"
					elif [[ ${PROCESS_OBSERVER_BATCH_SCOPE:-} = restore_session ]] && _process_observer_batch_pkg_active "$name2"; then
						case "${SPEEDBACKUP_RESTORE_SESSION_PER_APP_FINAL_CHECK:-0}" in
						1|true|TRUE|yes|YES|on|ON|enable|ENABLE)
							_restore_live_guard_scope_final_pkg "$name2" "$name1" "restore_app_scope_done" || true
							case "${SPEEDBACKUP_RESTORE_SESSION_PER_APP_PROCWAIT:-0}" in
							1|true|TRUE|yes|YES|on|ON|enable|ENABLE)
								_restore_procwait_pkg_gone "$name2" 700 120 "restore_live_guard_final" "${user:-${USER_ID:-0}}" >/dev/null 2>&1 || true
								_restore_guard_final_detail="session-keep-final-check-procwait=pkg-gone" ;;
							*)
								_speed_debug_log "RESTORE_GUARD_SESSION_APP_PROCWAIT_SKIP pkg=$name2 label=$name1 reason=restore_app_scope_done release=bulk-post-appstate mode=r433"
								_restore_guard_final_detail="session-keep-final-check-skip-procwait" ;;
							esac ;;
						*)
							_speed_debug_log "RESTORE_GUARD_SESSION_APP_FINAL_CHECK_SKIP pkg=$name2 label=$name1 reason=restore_app_scope_done release=bulk-post-appstate policy=batch-session-covers-wake mode=r433"
							_restore_guard_final_detail="session-keep-skip-final-check" ;;
						esac
					else
						_restore_live_guard_scope_final_pkg "$name2" "$name1" "restore_app_scope_done" || true
						_restore_procwait_pkg_gone "$name2" 700 120 "restore_live_guard_final" "${user:-${USER_ID:-0}}" >/dev/null 2>&1 || true
					fi
					_process_observer_stop_app "restore_app_scope_done" || true
					_uid_netblock_stop_app "restore_app_scope_done" || true
					_cgroup_freezer_stop_app "restore_app_scope_done" || true
					_restore_phase_timing_record "guard_final_release" "$_restore_guard_final_t0" "$name1" "$name2" "$_restore_guard_final_detail" "0"
					_live_app_resume_paused
					}
				fi
			else
				[[ $No_backupdata = "" ]]&& echoRgb "$name1沒有安裝無法恢復數據" "0"
			fi
			_restore_phase_timing_record "app_total" "$_restore_app_total_t0" "$name1" "$name2" "index=$i/$r installed=${_is_installed:-0}" "0"
			endtime 2 "$name1恢復" "2" && echoRgb "完成$(safe_percent "$i" "$r")% $(progress_bar $(safe_percent "$i" "$r"))" "3"
			_restore_notify_fixed_progress "$i" "$r" 100 "恢復進度 $i/$r"
			rgb_d="$rgb_a"
			rgb_a=188
			echoRgb "_________________$(endtime 1 "已經")___________________"
			rgb_a="$rgb_d"
			}
		else
			echoRgb "$Backup_folder資料夾遺失，無法恢復" "0"
		fi
		if [[ $i = $r ]]; then
			endtime 1 "應用安裝/資料迴圈" "2"
			# 應用迴圈結束後立刻批量寫入權限/AppOps/電池設定。
			# 不可拖到 Media/自訂資料夾恢復之後；大檔流式 Media 可能被使用者中斷，
			# 若此時尚未 flush，整批應用權限就會停留在暫存佇列，實際沒有套用。
			_speedbackup_progress_hint "開始批量恢復權限/AppOps/電池/SSAID，恢復守護 session 將在批量處理後統一釋放" "restore_post_appstate_begin"
			flush_batch_appstate
			_speed_debug_log "RESTORE_LOW_RISK_GUARD_TRIM_SUMMARY count=${RESTORE_LOW_RISK_GUARD_TRIM_COUNT:-0} mode=r481"
			_restore_post_state_guard_stop_all "restore_post_appstate_done" || true
			_RESTORE_PRESERVE_BATCH_QUEUE=0
			_batch_appstate_mode=0
			_restore_notify_fixed_progress "$r" "$r" 100 "app恢復完成 $(endtime 1 "應用恢復" "2")"
			[[ ! -f ${0%/*}/app_details.json ]] && {
			if [[ $media_recovery = true ]]; then
				starttime1="$(date -u "+%s")"
				app_details="$Backup_folder2/app_details.json"
				if [[ $_RESTORE_STREAM = 1 ]]; then
					txt="${_RESTORE_STREAM_MEDIA_LIST:-$TMPDIR/.restore_stage/mediaList.txt}"
				else
					txt="$MODDIR/mediaList.txt"
				fi
				if [[ -f "$txt" ]]; then
					sort -u "$txt" -o "$txt" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
				else
					echoRgb "mediaList.txt 遺失，無法恢復 Media 壓縮包" "0"
				fi
				A=1
				B="$(awk '!/[#＃]/ && NF{count++} END{print count}' "$txt" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null})"
				[[ $B = "" ]] && echoRgb "mediaList.txt壓縮包名為空或是被注釋了\n -請執行start.sh獲取列表再來恢復" "0" && B=0
				notification_progress "106" "$B" 0 "Media恢復開始"
				while [[ $A -le $B ]]; do
					name1="$(awk -v n=$A '!/[#＃]/ && NF{c++} c==n{print $1; exit}' "$txt" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null})"
					starttime2="$(date -u "+%s")"
					echoRgb "恢復第$A/$B個壓縮包 剩下$((B - A))個" "3"
					if [[ $_RESTORE_STREAM = 1 ]]; then
						_STREAM_SRC="$_RESTORE_SUBDIR/Media/$name1"
					fi
					Release_data "$Backup_folder2/$name1"
					unset _STREAM_SRC
					endtime 2 "$FILE_NAME2恢復" "2" && echoRgb "完成$(safe_percent "$A" "$B")% $(progress_bar $(safe_percent "$A" "$B"))" "3"
					notification_progress "106" "$B" "$A" "Media恢復進度 $A/$B $(safe_percent "$A" "$B")%"
					echoRgb "____________________________________" && let A++
				done
				endtime 1 "自定義恢復" "2"
				_media_done_base="Media恢復完成 $(endtime 1 "Media恢復" "2")"
				_media_done_msg="$(_restore_media_final_notify_msg "$_media_done_base")"
				if [[ "$_media_done_msg" != "$_media_done_base" ]]; then
					echoRgb "$_media_done_msg" "0"
					_speed_debug_log "MEDIA_RESTORE_FINAL_WARN msg=$_media_done_msg mode=r378"
				fi
				notification_progress "106" "$B" "$B" "$_media_done_msg"
			fi
			[[ $_RESTORE_STREAM != 1 ]] && recover_wifi "$MODDIR/wifi"
			}
		fi
		unset _restore_force_play_session _restore_force_play_marker
		let i++ en++ nskg++
	done
	local _restore_stream_fatal_rc=0
	if [[ $_RESTORE_STREAM = 1 && -n ${remote_type:-} ]] && _remote_stream_fatal_active; then
		_restore_stream_fatal_rc="$(_remote_stream_fatal_exit_rc)"
		echoRgb "遠端流式恢復因遠端連線變更／中斷而停止；請確認遠端連線後重新執行" "0"
		_speed_debug_log "REMOTE_STREAM_RESTORE_FASTFAIL_END rc=$_restore_stream_fatal_rc $(_remote_stream_fatal_summary)"
	fi
	# 保底復位：正常情況已在 app 迴圈結束瞬間 flush；這裡只防舊分支或異常路徑漏掉。
	_speedbackup_progress_hint "正在確認恢復後處理與守護狀態" "restore_post_appstate_final"
	flush_batch_appstate
	_restore_post_state_guard_stop_all "restore_post_appstate_final" || true
	# 復位: 確保批量模式不外溢；非迴圈直接呼叫 restore_appstate 時函式內會自動臨時 batch+flush
	_RESTORE_PRESERVE_BATCH_QUEUE=0
	_batch_appstate_mode=0
	_restore_install_issue_emit
	Set_screen_pause_seconds off
	[[ $user != 0 ]] && am stop-user "$user" >/dev/null 2>&1
	starttime1="$TIME"
	if [[ $_restore_stream_fatal_rc != 0 ]]; then
		echoRgb "$DX中止" "0"
		endtime 1 "$DX總流程" >/dev/null 2>&1 || true
		_restore_done_msg="恢復中止：遠端連線變更／中斷 $(endtime 1 "$DX總流程")"
		_speed_debug_log "RESTORE_FINAL_ABORT_NOTIFY mode=remote-fastfail-r355 tag=105 msg=$_restore_done_msg rc=$_restore_stream_fatal_rc"
	else
		_restore_elapsed_msg="$(endtime 1 "$DX總流程")"
		_restore_media_skip_count="$(_restore_media_space_skip_count)"
		case $_restore_media_skip_count in ''|*[!0-9]*) _restore_media_skip_count=0 ;; esac
		if [[ $_restore_media_skip_count -gt 0 ]]; then
			echoRgb "$DX完成，但有 $_restore_media_skip_count 個 Media 項目因空間不足跳過" "0"
			_restore_done_msg="恢復完成但有 $_restore_media_skip_count 個 Media 項目因空間不足跳過 $_restore_elapsed_msg"
			_speed_debug_log "RESTORE_FINAL_NOTIFY mode=progress-100-media-space-warn-r378 tag=105 mediaSpaceSkip=$_restore_media_skip_count msg=$_restore_done_msg"
		else
			echoRgb "$DX完成"
			_restore_done_msg="恢復完成 $_restore_elapsed_msg"
			_speed_debug_log "RESTORE_FINAL_NOTIFY mode=progress-100-no-template-r293 tag=105 msg=$_restore_done_msg"
		fi
		# r293: restore 尾段禁止無進度 notification，避免 Android System 產生 service_notification_apply_auto_template_* 垃圾通知。
		# 用主恢復進度 tag 固定 100/100 更新，不新增/觸發 service auto-template。
		notification_progress "105" 100 100 "$_restore_done_msg"
	fi
	_RESTORE_KEEP_SESSION_MAPS=0
	_speed_debug_log "RESTORE_SESSION_MAP_KEEP_END keep=$_RESTORE_KEEP_SESSION_MAPS"
	_speed_debug_log "RESTORE_FINAL_PACK_NOTIFY mode=no-progress-r293 msg=正在整理暫存與打包 speed_debug"
	_speedbackup_busy_step "正在整理暫存與打包 speed_debug，請稍候" "restore_final_pack"
	cleanup_tmpdir_contents || exit 1
	# 正常恢復完成點主動建立 final 包並刪除 run_xxx。
	# 避免單獨入口 / tee pipeline 的 EXIT trap 提前打包，造成 speed_debug_*.tar 與幕後 run 目錄內容不一致。
	_speed_debug_normal_finish_pack "$_restore_stream_fatal_rc"
	notification_progress "105" 100 100 "$_restore_done_msg；speed_debug 已打包"
	_speed_debug_log "RESTORE_FINAL_PACK_DONE_NOTIFY mode=progress-100-no-template-r293 tag=105 msg=$_restore_done_msg；speed_debug 已打包 rc=$_restore_stream_fatal_rc"
	return "$_restore_stream_fatal_rc"
}
# 恢復自定義資料夾 (Media 等)
Restore3() {
	self_test
	echoRgb "點錯了?這是恢復自定義資料夾腳本 如果你是要恢復應用那你就點錯了" "2"
	echoRgb "假設反悔了要終止腳本請儘速離開此腳本點擊start.sh選擇終止腳本,否則腳本將繼續執行直到結束" "0"
	if ! ask_yn "繼續恢復自定義資料夾?" "恢復自定義資料夾" "離開腳本"; then
		exit 0
	fi
	if [[ ${_RESTORE_STREAM:-0} = 1 ]]; then
		_restore_stream_prepare_media || { echoRgb "流式 Media metadata 準備失敗，無法恢復自定義資料夾" "0"; return 1; }
		mediaDir="$Backup_folder2"
		app_details="$mediaDir/app_details.json"
		txt="${_RESTORE_STREAM_MEDIA_LIST:-$TMPDIR/.restore_stage/mediaList.txt}"
	else
		mediaDir="$MODDIR/Media"
		[[ -f "$mediaDir/app_details.json" ]] && app_details="$mediaDir/app_details.json"
		Backup_folder2="$mediaDir"
		[[ ! -d $mediaDir ]] && echoRgb "媒體資料夾不存在" "0" && exit 2
		txt="$MODDIR/mediaList.txt"
		[[ ! -f $txt ]] && echoRgb "請執行start.sh獲取媒體列表再來恢復" "0" && exit 2
		sort -u "$txt" -o "$txt" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	fi
	#記錄開始時間
	starttime1="$(date -u "+%s")"
	# 注意: 不要在這裡重新定義 echo_log()——shell 函式沒有真正的區域作用域，
	# 這樣寫會直接覆蓋第 3397 行的全域 echo_log()，導致本次呼叫之後
	# (包含這個迴圈內 Release_data() 呼叫的 echo_log，以及往後任何其他流程)
	# 全部改用這裡的簡化版，遺失 _speed_debug_log / Set_back_0 / Set_back_1 / 失敗通知。
	starttime1="$(date -u "+%s")"
	A=1
	B="$(awk '!/[#＃]/ && NF{count++} END{print count}' "$txt" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null})"
	Set_screen_pause_seconds on
	_restore_media_space_skip_state_init
	[[ $B = "" ]] && echoRgb "mediaList.txt壓縮包名為空或是被注釋了\n -請執行start.sh獲取列表再來恢復" "0" && exit 1
	notification_progress "108" "$B" 0 "Media恢復開始"
	while [[ $A -le $B ]]; do
		name1="$(awk -v n=$A '!/[#＃]/ && NF{c++} c==n{print $1; exit}' "$txt" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null})"
		starttime2="$(date -u "+%s")"
		echoRgb "恢復第$A/$B個壓縮包 剩下$((B - A))個" "3"
		if [[ ${_RESTORE_STREAM:-0} = 1 ]]; then
			_STREAM_SRC="$_RESTORE_SUBDIR/Media/$name1"
		fi
		Release_data "$mediaDir/$name1"
		unset _STREAM_SRC
		endtime 2 "$FILE_NAME2恢復" "2" && echoRgb "完成$(safe_percent "$A" "$B")% $(progress_bar $(safe_percent "$A" "$B"))" "3"
		notification_progress "108" "$B" "$A" "Media恢復進度 $A/$B $(safe_percent "$A" "$B")%"
		echoRgb "____________________________________" && let A++
	done
	Set_screen_pause_seconds off
	_restore3_elapsed="$(endtime 1 "恢復結束")"
	_restore3_media_base="Media恢復完成 $(endtime 1 "Media恢復")"
	_restore3_media_msg="$(_restore_media_final_notify_msg "$_restore3_media_base")"
	if [[ "$_restore3_media_msg" != "$_restore3_media_base" ]]; then
		echoRgb "$_restore3_media_msg" "0"
		_speed_debug_log "MEDIA_RESTORE_STANDALONE_FINAL_WARN msg=$_restore3_media_msg elapsed=$_restore3_elapsed mode=r378"
	fi
	notification_progress "108" "$B" "$B" "$_restore3_media_msg"
}
Restore4() {
	[[ $ssaid_mode_1 = true ]] || return 0
	local _list="$TMPDIR/.ssaid_details_list" _record="$TMPDIR/.ssaid_record_$$" _ssaid_only="$TMPDIR/.ssaid_only_$$"
	: > "$TMPDIR/.batch_appstate_ndjson" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	_appdetails_index_paths "$MODDIR" "$_list" 2 0 1 >/dev/null 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} || true
	while read -r app_details; do
		[[ -s $app_details ]] || continue
		name1="$(_appdetails_get_first_entry_name "$app_details")"
		name2="$(_appdetails_get_first_pkg "$app_details")"
		[[ -n $name1 && -n $name2 ]] || continue
		[[ -f "$TMPDIR/.installed_pkgs" ]] || prepare_installed_pkgs_map >/dev/null 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
		awk -v p="$name2" '$0==p{f=1} END{exit !f}' "$TMPDIR/.installed_pkgs" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} || continue
		_appstate_record_from_app_details "$app_details" "$name1" "$name2" "$_record" || continue
		# 只用 SSAID 篩選 App，但送入完整 canonical AppState；禁止為了單寫 SSAID 清空陣列後觸發 AppOps reset。
		_appstate_snapshot_ssaid_only_file "$_record" "$_ssaid_only"
		[[ -s $_ssaid_only ]] && cat "$_ssaid_only" >> "$TMPDIR/.batch_appstate_ndjson"
	done < "$_list"
	rm -f "$_list" "$_record" "$_ssaid_only" 2>/dev/null
	if [[ -s $TMPDIR/.batch_appstate_ndjson ]]; then
		echoRgb "開始恢復含SSAID應用的完整AppState" "2"
		_batch_appstate_mode=1
		flush_batch_appstate
		_batch_appstate_mode=0
	else
		echoRgb "SSAID無備份值，已略過" "2"
	fi
}

# ======================================================
# 生成列表 / 檢查 / backup_media / wifi
# ======================================================
# appList 內建說明行正規化：只移除腳本自己生成的「酷安 com.coolapk.market」範例說明，保留使用者自訂註解。
_applist_backup_guide_header() {
	echo "#不需要備份的應用請在開頭使用#注釋 比如：#酷安 com.coolapk.market（忽略安裝包和資料）"
	echo "#不需要備份資料的應用請在開頭使用!注釋 比如：!酷安 com.coolapk.market（僅忽略資料）"
}

_applist_sanitize_backup_guide_lines() {
	local _file="$1" _tmp
	[[ -f $_file ]] || return 0
	_tmp="$TMPDIR/.applist_guide_sanitize.$$"
	awk '
		function is_builtin_guide(line) {
			return (line ~ /^[[:space:]]*#/ && line ~ /不需要備份/ && line ~ /酷安[[:space:]]+com\.coolapk\.market/)
		}
		is_builtin_guide($0) { next }
		{ print }
	' "$_file" > "$_tmp" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} || { rm -f "$_tmp"; return 1; }
	{ _applist_backup_guide_header; cat "$_tmp"; } > "$_file"
	rm -f "$_tmp"
	_speed_debug_log "APPLIST_GUIDE_SANITIZE file=$_file"
	return 0
}

# 生成應用列表 (掃描所有已安裝 user app, 輸出到 appList.txt)
# 配合 blacklist/whitelist 過濾系統 app
Getlist() {
	case $MODDIR in
	/storage/emulated/0/Android/* | /data/media/0/Android/* | /sdcard/Android/*) echoRgb "請勿在$MODDIR內生成列表" "0" && exit 2 ;;
	esac
	#校驗選填是否正確
	[[ $blacklist_mode != "" ]] && isBoolean "$blacklist_mode" "blacklist_mode" && blacklist_mode="$nsx" || {
	echoRgb "選擇黑名單模式\n -音量上不輸出，音量下輸出應用列表" "2"
	get_version "不輸出" "輸出應用列表"; blacklist_mode="$branch"
	}
	txt="$TMPDIR/appList"
	if [[ -f "$MODDIR/appList.txt" ]]; then
		cat "$MODDIR/appList.txt" >"$txt"
		_applist_sanitize_backup_guide_lines "$txt"
	else
		_applist_backup_guide_header >"$txt"
	fi
	echoRgb "請勿關閉腳本，等待提示結束"
	rgb_a=118
	# r327: legacy-visible timer is reset after inventory metadata is ready; guide text is never counted.
	echoRgb "提示! 腳本默認會屏蔽預裝應用 如需備份請添加預裝應用白名單" "0"
	# r322: appList 生成走 Dex one-call。把 user/xposed inventory、系統白名單、default HOME 解析
	# 合併在同一個 RootDaemon command 內，避免 r319 仍需 appInventory + defaultHome + target packages 三次 round-trip。
	local _target_system_pkgs="$TMPDIR/.getlist_target_system_pkgs" _target_filter _getlist_raw _meta _meta_ime _home_label _home_source _ime_label _ime_source Default_ime_pkg
	: > "$_target_system_pkgs"
	printf '%s\n' "$system" | awk '{for (i=1; i<=NF; i++) if ($i !~ /^[#＃]/) print $i}' >> "$_target_system_pkgs"
	awk 'NF && $0 !~ /[^A-Za-z0-9_.-]/ && $0 !~ /^\./ && $0 !~ /\.\./ {print}' "$_target_system_pkgs" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} | sort -u > "$_target_system_pkgs.tmp"
	mv -f "$_target_system_pkgs.tmp" "$_target_system_pkgs" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	_target_filter="$(paste -sd, "$_target_system_pkgs" 2>/dev/null)"
	# r327: inventory one-call is still logged, but the user-facing "輸出包名" timer
	# matches legacy scope: output + validation only.
	_getlist_raw="$(appinventory_getlist "$_target_filter" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null})"
	if ! printf '%s\n' "$_getlist_raw" | _applist_inventory_has_rows; then
		_speed_debug_log "APP_INVENTORY_GETLIST_EMPTY_FALLBACK reason=no_rows targets=${_target_filter:-empty} mode=r497"
		_getlist_raw="$(_applist_getlist_pm_fallback "$_target_filter" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null})"
	fi
	_meta="$(printf '%s\n' "$_getlist_raw" | awk -F '\t' '$1=="#META" && $2=="defaultHome"{print; exit}')"
	_meta_ime="$(printf '%s\n' "$_getlist_raw" | awk -F '\t' '$1=="#META" && $2=="defaultIme"{print; exit}')"
	Default_home_pkg="$(printf '%s\n' "$_meta" | awk -F '\t' '{print $3}')"
	_home_label="$(printf '%s\n' "$_meta" | awk -F '\t' '{print $4}')"
	_home_source="$(printf '%s\n' "$_meta" | awk -F '\t' '{print $5}')"
	Default_ime_pkg="$(printf '%s\n' "$_meta_ime" | awk -F '\t' '{print $3}')"
	_ime_label="$(printf '%s\n' "$_meta_ime" | awk -F '\t' '{print $4}')"
	_ime_source="$(printf '%s\n' "$_meta_ime" | awk -F '\t' '{print $5}')"
	case "$Default_home_pkg" in ''|*[!A-Za-z0-9_.-]*) Default_home_pkg="" ;; esac
	case "$Default_ime_pkg" in ''|*[!A-Za-z0-9_.-]*) Default_ime_pkg="" ;; esac
	# r323: appInventoryGetlist 已經在同一個 RootDaemon command 解析 default HOME。
	# 直接灌入 _default_home_pkg_ensure() 的 cache，避免結尾 _applist_home_last_file()
	# 再次呼叫 defaultHome，造成 r322 appList 多 1 秒 round-trip。
	_DEFAULT_HOME_PKG_CACHE="$Default_home_pkg"
	_DEFAULT_HOME_LABEL_CACHE="${_home_label:-$Default_home_pkg}"
	_DEFAULT_HOME_SOURCE_CACHE="${_home_source:-appInventoryGetlist}"
	[[ -n $Default_home_pkg ]] && _speed_debug_log "DEFAULT_HOME_CACHE_FROM_GETLIST package=$Default_home_pkg label=${_DEFAULT_HOME_LABEL_CACHE:-} source=${_DEFAULT_HOME_SOURCE_CACHE:-appInventoryGetlist} mode=r370"
	_DEFAULT_IME_PKG_CACHE="$Default_ime_pkg"
	_DEFAULT_IME_LABEL_CACHE="${_ime_label:-$Default_ime_pkg}"
	_DEFAULT_IME_SOURCE_CACHE="${_ime_source:-appInventoryGetlist}"
	[[ -n $Default_ime_pkg ]] && _speed_debug_log "DEFAULT_IME_CACHE_FROM_GETLIST package=$Default_ime_pkg label=${_DEFAULT_IME_LABEL_CACHE:-} source=${_DEFAULT_IME_SOURCE_CACHE:-appInventoryGetlist} mode=r370"
	[[ -n $Default_ime_pkg ]] && _speed_debug_log "DEFAULT_IME_APPLIST_FORCE_INCLUDE package=$Default_ime_pkg label=${_DEFAULT_IME_LABEL_CACHE:-} mode=r370"
	if [[ -n $Default_home_pkg && -n ${SPEED_DEBUG_RUN_DIR:-} && -d ${SPEED_DEBUG_RUN_DIR:-} ]]; then
		printf '{"recordType":"defaultHome","packageName":"%s","label":"%s","source":"%s","result":{"name":"OK"}}\n' \
			"$Default_home_pkg" "${_home_label:-$Default_home_pkg}" "${_home_source:-appInventoryGetlist}" > "$SPEED_DEBUG_RUN_DIR/default_home_last.json" 2>/dev/null
	fi
	if [[ -n $Default_ime_pkg && -n ${SPEED_DEBUG_RUN_DIR:-} && -d ${SPEED_DEBUG_RUN_DIR:-} ]]; then
		printf '{"recordType":"defaultIme","packageName":"%s","label":"%s","source":"%s","result":{"name":"OK"}}\n' \
			"$Default_ime_pkg" "${_ime_label:-$Default_ime_pkg}" "${_ime_source:-appInventoryGetlist}" > "$SPEED_DEBUG_RUN_DIR/default_ime_last.json" 2>/dev/null
	fi
	Apk_info="$(printf '%s\n' "$_getlist_raw" | awk '$1!="#META" && NF>=3{print}' | grep -Ev 'ice.message|com.topjohnwu.magisk' | tr '/\:' '___' | sed 's/\.\./__/g')"
	_user_rows="$(printf '%s\n' "$Apk_info" | awk 'NF>=3 && !index("|" $3 "|", "|system|") {n++} END{print n+0}')"
	_target_rows="$(printf '%s\n' "$Apk_info" | awk 'NF>=3 && index("|" $3 "|", "|system|") {n++} END{print n+0}')"
	xposed_name="$(echo "$Apk_info" | awk 'index("|" $3 "|", "|xposed|") {print $2}')"
	Pre_installed_apps="$(printf '%s\n' "$Apk_info" | awk 'NF>=3 && index("|" $3 "|", "|system|") {print $1, $2}')"
	# r322 預設不建立全系統 allpkg 集合；舊註解行保留，避免為清註解再掃 system。需要完整清理時才開。
	if [[ ${SPEEDBACKUP_APPLIST_FULL_INSTALLED_CLEANUP:-0} = 1 ]]; then
		appinfo "all" "pkgName" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} | sed '/^[[:space:]]*$/d' | sort -u > "$TMPDIR/.getlist_allpkg"
		_speed_debug_log "APP_INVENTORY_GETLIST_FULL_CLEANUP rows=$(wc -l < "$TMPDIR/.getlist_allpkg" 2>/dev/null | tr -d ' ') mode=r323-opt-in"
	else
		: > "$TMPDIR/.getlist_allpkg"
	fi
	Apk_info="$(printf '%s\n' "$Apk_info" | awk 'NF>=3{print $1, $2}' | sed '/^[[:space:]]*$/d' | sort -u)"
	_total_rows="$(printf '%s\n' "$Apk_info" | sed '/^[[:space:]]*$/d' | wc -l | tr -d ' ')"
	_speed_debug_log "APP_INVENTORY_GETLIST_ONECALL userRows=${_user_rows:-0} targetedSystemRows=${_target_rows:-0} totalRows=${_total_rows:-0} defaultHome=${Default_home_pkg:-none} defaultIme=${Default_ime_pkg:-none} fullCleanup=${SPEEDBACKUP_APPLIST_FULL_INSTALLED_CLEANUP:-0} timelineMsg=${SPEEDBACKUP_DEBUG_TIMELINE_MSG:-0} mode=r349-default-ime-applist-mark-output-timer"
	# r327: reset visible duration immediately before the legacy output/validation phase.
	# This avoids counting guide text and the one-call inventory round-trip in "輸出包名" elapsed time.
	starttime1="$(date -u "+%s")"
	_speed_debug_log "APPLIST_TIMER_SCOPE start=output_loop excludes=guide,target_csv,inventory_onecall mode=r327"
	rm -f "$_target_system_pkgs" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	[[ $Apk_info = "" ]] && {
		_speed_debug_log "APP_INVENTORY_GETLIST_EMPTY_OK user=${USER_ID:-${user:-0}} reason=no_user_or_whitelist_packages mode=r497"
		echoRgb "未找到可列出的第三方或白名單系統應用，已生成空列表" "2"
		Apk_info2=""
		Apk_Quantity=0
		endtime1="$(date -u "+%s")"
		echoRgb "輸出包名耗時:$(hms $((endtime1 - starttime1)))" "1"
		cat "$txt" > "$MODDIR/appList.txt" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
		return 0
	} || Apk_info2="$(echo "$Apk_info" | cut -d' ' -f2)"
	Apk_Quantity="$(printf "%s\n" "$Apk_info" | awk 'END{print NR}')"
	echoRgb "列出第三方應用......." "2"
	i=0; rc=0; rd=0; Q=0; Qc=0; rb=0
	# 預先收集所有「待加進 txt」的行, 用暫存檔取代 REPLY2 字串拼接 (O(N²) → O(N))
	local appended="$TMPDIR/.getlist_append"
	: > "$appended"
	# 一次 awk 把所有 app 預分類, 取代主迴圈內的多次 grep/awk fork
	# 輸出格式: <類別>\t<原行>
	# 類別: BLACK / XPOSED / WHITE / PRELOAD / NORMAL
	local classified="$TMPDIR/.getlist_class"
	# 分類 awk: 同時做「已存在判斷」與「同名不同包重命名」, 主迴圈不再 fork grep/add_entry
	# 用 FNR==NR 先吃 $txt (現有清單): 收集已存在包名集合 exist[], 以及 app名→已被佔用 namecnt[]
	# 第二檔 (Apk_info) 才做分類; 輸出格式: <類別>\t<最終label>\t<pkg>
	echo "$Apk_info" | sed 's/[\/:()\[\]\-!]//g' > "$TMPDIR/.getlist_apkinfo"
	awk -v whitelist="$whitelist" \
		-v blacklist="$blacklist" \
		-v xposed="$xposed_name" \
		-v default_home_pkg="$Default_home_pkg" \
		-v default_ime_pkg="$Default_ime_pkg" '
		BEGIN {
			n = split(whitelist, _w, /[ \t\n]+/)
			for (k in _w) if (_w[k] != "") wl[_w[k]] = 1
			n = split(blacklist, _b, /[ \t\n]+/)
			for (k in _b) if (_b[k] != "" && _b[k] !~ /^[#＃]/) bl[_b[k]] = 1
			n = split(xposed, _x, /[ \t\n]+/)
			for (k in _x) if (_x[k] != "") xp[_x[k]] = 1
			preload_re = "(oneplus|miui|xiaomi|oppo|flyme|meizu|coloros)"
			preload_exact["com.android.soundrecorder"] = 1
			preload_exact["com.mfashiongallery.emag"] = 1
			preload_exact["com.mi.health"] = 1
			preload_exact["com.duokan.phone.remotecontroller"] = 1
			preload_exact["com.android.calendar"] = 1
			preload_exact["com.android.deskclock"] = 1
			preload_exact["com.google.android.safetycore"] = 1
			preload_exact["com.google.android.contactkeys"] = 1
			preload_exact["com.google.android.apps.messaging"] = 1
			preload_exact["com.google.android.calendar"] = 1
		}
		# 第一檔: 現有 $txt — 收集已存在 pkg 與 app名已佔用情況
		FNR==NR {
			# 包名永遠是最後一欄 $NF; label 是前面所有欄位 (app 名可能含空格)
			# (註解行如 "#日曆 com.google...calendar" 也要排除該 app 重複輸出)
			if (NF < 2) next
			_cpkg = $NF
			_clabel = $1
			for (_j = 2; _j < NF; _j++) _clabel = _clabel " " $_j
			if ($0 ~ /^[#＃!]/) {
				exist_cmt[_cpkg] = 1       # 被註解(#/!)的已存在包名
			} else {
				exist[_cpkg] = 1           # 正常已存在包名
				namepkg[_clabel] = _cpkg   # 同名衝突判斷只看非註解行
				used[_clabel] = 1
			}
			next
		}
		# 第二檔: Apk_info — 分類
		{
			# 防禦: 跳過空行或缺包名的行 (避免產生空 pkg 分類, 與 Apk_Quantity 計數不一致)
			if (NF < 2) next
			# 包名永遠是最後一欄 $NF; label 是前面所有欄位 (app 名可能含空格)
			pkg = $NF
			label = $1
			for (_j = 2; _j < NF; _j++) label = label " " $_j
			# 已存在(正常) → EXIST; 已存在(被註解) → EXIST_CMT; 兩者主迴圈都只計數跳過
			if (pkg in exist)     { print "EXIST\t"     label "\t" pkg; next }
			# r87: HOME 就算原本在 appList 內被註解，也要補一條有效行；舊註解保留作為使用者歷史內容。
			# r341: default IME 與 default HOME 同級；預設鍵盤即使是系統 App 或既有註解行，也要強制輸出有效行並在終端標註。
			if (default_home_pkg != "" && pkg == default_home_pkg) { force_home = 1 } else { force_home = 0 }
			if (default_ime_pkg != "" && pkg == default_ime_pkg) { force_ime = 1 } else { force_ime = 0 }
			if ((pkg in exist_cmt) && !force_home && !force_ime) { print "EXIST_CMT\t" label "\t" pkg; next }
			# 同名不同包 → 加數字後綴 (與 add_entry 等價)
			final = label
			if ((label in used) && namepkg[label] != pkg) {
				c = 1
				while ((final = label "_" c) in used) c++
			}
			used[final] = 1; namepkg[final] = pkg
			if (force_home && force_ime) { print "HOME_IME\t" final "\t" pkg; next }
			if (force_home) { print "HOME\t" final "\t" pkg; next }
			if (force_ime) { print "IME\t" final "\t" pkg; next }
			if (pkg in bl)        { print "BLACK\t"      final "\t" pkg; next }
			if (pkg ~ preload_re || pkg in preload_exact) {
				if (pkg in xp)    { print "PRELOAD_XP\t" final "\t" pkg; next }
				if (pkg in wl)    { print "PRELOAD_WL\t" final "\t" pkg; next }
				print "PRELOAD\t" final "\t" pkg; next
			}
			if (pkg in xp)        { print "XPOSED\t"     final "\t" pkg; next }
			print "NORMAL\t" final "\t" pkg
		}' "$txt" "$TMPDIR/.getlist_apkinfo" > "$classified"
	rm -f "$TMPDIR/.getlist_apkinfo"
	[[ -n "$(echo "$blacklist" | grep -Ev '#|＃')" ]] && NZK=1
	# 主迴圈: 從分類結果讀, 每行已預先標好類別
	LR=1
	local _seen=0   # 核對1: 迴圈實際處理的 app 數, 應 == Apk_Quantity
	# 分類 awk 已算好最終 label 與已存在判斷, 迴圈內不再 fork (grep/cat/add_entry 全消除)
	while IFS=$'\t' read -r kind app_label app_pkg; do
		[[ -z $app_pkg ]] && continue
		let _seen++
		[[ $rgb_a -ge 229 ]] && rgb_a=118
		app_name="$app_label"
		REPLY="$app_label $app_pkg"
		case $kind in
		EXIST)
			if [[ -n ${Default_home_pkg:-} && $app_pkg = "$Default_home_pkg" && -n ${Default_ime_pkg:-} && $app_pkg = "$Default_ime_pkg" ]]; then
				echoRgb "$app_name 已存在 [預設桌面] [預設鍵盤]" "2"
				_speed_debug_log "APPLIST_DEFAULT_HOME_MARK package=$app_pkg label=$app_name context=getlist_existing mode=r370"
				_speed_debug_log "APPLIST_DEFAULT_IME_MARK package=$app_pkg label=$app_name context=getlist_existing mode=r370"
			elif [[ -n ${Default_home_pkg:-} && $app_pkg = "$Default_home_pkg" ]]; then
				echoRgb "$app_name 已存在 [預設桌面]" "2"
				_speed_debug_log "APPLIST_DEFAULT_HOME_MARK package=$app_pkg label=$app_name context=getlist_existing mode=r370"
			elif [[ -n ${Default_ime_pkg:-} && $app_pkg = "$Default_ime_pkg" ]]; then
				echoRgb "$app_name 已存在 [預設鍵盤]" "2"
				_speed_debug_log "APPLIST_DEFAULT_IME_MARK package=$app_pkg label=$app_name context=getlist_existing mode=r370"
			fi
			let Q++
			let LR++; let rgb_a++
			continue
			;;
		EXIST_CMT)
			let Qc++
			echoRgb "$app_name 已註解 略過輸出" "0"
			let LR++; let rgb_a++
			continue
			;;
		BLACK)
			if [[ $NZK = 1 ]]; then
				if [[ $blacklist_mode = false ]]; then
					echo "$REPLY" >> "$appended"
					tmp=1
					echoRgb "$((i+1)):$app_name $app_pkg($rgb_a)"
					let i++ rb++
				else
					echoRgb "$app_label黑名單應用 不輸出" "0"
					let rb++
				fi
			fi
			let LR++; let rgb_a++
			continue
			;;
		PRELOAD_XP)
			echoRgb "$((i+1)):$app_name為Xposed模塊 進行添加" "0"
			echo "$REPLY" >> "$appended"
			tmp=1
			let i++ rd++
			;;
		PRELOAD_WL)
			echo "$REPLY" >> "$appended"
			tmp=1
			echoRgb "$((i+1)):$app_name $app_pkg($rgb_a)"
			let i++
			;;
		PRELOAD)
			echoRgb "$app_name 預裝應用 忽略輸出" "0"
			echo "#$REPLY" >> "$appended"
			tmp=1
			let rc++
			;;
		XPOSED)
			echo "$REPLY" >> "$appended"
			tmp=1
			echoRgb "$((i+1)):Xposed: $app_name $app_pkg($rgb_a)"
			let i++ rd++
			;;
		HOME_IME)
			echo "$REPLY" >> "$appended"
			tmp=1
			echoRgb "$((i+1)):$app_name $app_pkg($rgb_a) [預設桌面] [預設鍵盤]" "2"
			_speed_debug_log "GETLIST_DEFAULT_HOME_INCLUDE package=$app_pkg label=$app_name mode=r370"
			_speed_debug_log "GETLIST_DEFAULT_IME_INCLUDE package=$app_pkg label=$app_name mode=r370"
			_speed_debug_log "APPLIST_DEFAULT_IME_MARK package=$app_pkg label=$app_name context=getlist mode=r370"
			let i++
			;;
		HOME)
			echo "$REPLY" >> "$appended"
			tmp=1
			echoRgb "$((i+1)):$app_name $app_pkg($rgb_a) [預設桌面]" "2"
			_speed_debug_log "GETLIST_DEFAULT_HOME_INCLUDE package=$app_pkg label=$app_name mode=r370"
			let i++
			;;
		IME)
			echo "$REPLY" >> "$appended"
			tmp=1
			echoRgb "$((i+1)):$app_name $app_pkg($rgb_a) [預設鍵盤]" "2"
			_speed_debug_log "GETLIST_DEFAULT_IME_INCLUDE package=$app_pkg label=$app_name mode=r370"
			_speed_debug_log "APPLIST_DEFAULT_IME_MARK package=$app_pkg label=$app_name context=getlist mode=r370"
			let i++
			;;
		NORMAL|*)
			echo "$REPLY" >> "$appended"
			tmp=1
			echoRgb "$((i+1)):$app_name $app_pkg($rgb_a)"
			let i++
			;;
		esac
		let LR++; let rgb_a++
	done < "$classified"
	# 核對1 用: 先記錄合併前 txt 既有的有效行數 (非註解) — 須在 append 前取
	local _old_eff
	_old_eff=$(awk '/^[[:space:]]*$/{next} /^[[:space:]]*[#＃!]/{next} {c++} END{print c+0}' "$txt" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null})
	local _chk_fail=0
	# ====== 數量核對1: 全員到齊 (無論有無新輸出都檢查) ======
	# 迴圈處理數 _seen 應 == 分類檔行數, 且 == 系統第三方總數 Apk_Quantity
	local _cls_lines
	_cls_lines=$(awk 'END{print NR+0}' "$classified" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null})
	if [[ ${_seen:-0} -ne ${_cls_lines:-0} ]]; then
		echoRgb "⚠️ 數量核對1異常: 迴圈處理=$_seen 但分類檔行數=$_cls_lines (迴圈漏讀)" "0"
		_chk_fail=1
	elif [[ ${_seen:-0} -ne ${Apk_Quantity:-0} ]]; then
		echoRgb "⚠️ 數量核對1異常: 已分類=$_seen 但第三方總數=$Apk_Quantity (分類前後數量不符)" "0"
		_chk_fail=1
	else
		echoRgb "✅ 數量核對1: 全部 $Apk_Quantity 個 app 皆已分類處理" "1"
	fi
	# 把累積的 append 一次寫進 txt
	if [[ -s $appended ]]; then
		# 修復: txt 結尾若缺換行符, 直接 append 會與新內容第一行黏成一行 (已知問題根因)
		[[ -s $txt ]] && [[ -n "$(tail -c1 "$txt")" ]] && echo >> "$txt"
		cat "$appended" >> "$txt"
		echoRgb "已經將預裝應用輸出至appList.txt並注釋# 需要備份則去掉#" "0"
		[[ -n $tmp ]] && echoRgb "第三方apk數量=\"$Apk_Quantity\"\n -已過濾=\"$rc\"\n -xposed=\"$rd\"\n -黑名單應用=\"$rb\"\n -存在列表中=\"$Q\"\n -已註解略過=\"$Qc\"\n -輸出=\"$i\""
		# ====== 數量核對2: 輸出行 (僅在有新輸出時) ======
		# 合併後有效行 應 == 合併前有效行 + 本次輸出 i
		local _eff_lines _expect _new_eff
		_eff_lines=$(awk '/^[[:space:]]*$/{next} /^[[:space:]]*[#＃!]/{next} {c++} END{print c+0}' "$txt")
		# 本次 append 的非註解有效行數 (輸出 i 含註解行, 不可全加)
		_new_eff=$(awk '/^[[:space:]]*$/{next} /^[[:space:]]*[#＃!]/{next} {c++} END{print c+0}' "$appended" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null})
		_expect=$(( ${_old_eff:-0} + ${_new_eff:-0} ))
		if [[ $_eff_lines -ne $_expect ]]; then
			echoRgb "⚠️ 數量核對2異常: 列表有效行=$_eff_lines 但預期(原有$_old_eff+本次新增有效$_new_eff)=$_expect" "0"
			_chk_fail=1
		else
			echoRgb "✅ 數量核對2: 列表有效行=$_eff_lines (原有$_old_eff+本次新增有效$_new_eff)" "1"
		fi
	else
		# 無新輸出 (全部已存在/已註解): 顯示統計, 核對2 不適用
		[[ -n $tmp ]] && echoRgb "第三方apk數量=\"$Apk_Quantity\"\n -已過濾=\"$rc\"\n -xposed=\"$rd\"\n -黑名單應用=\"$rb\"\n -存在列表中=\"$Q\"\n -已註解略過=\"$Qc\"\n -輸出=\"$i\""
		echoRgb "本次無新增應用 (全部已存在或已註解)" "2"
	fi
	# 任一核對失敗 → 中止, 不寫出可能有誤的列表
	if [[ $_chk_fail = 1 ]]; then
		echoRgb "輸出異常 數量核對不通過 請聯繫作者解決" "0"
		rm -rf "$txt"
		rm -f "$appended" "$classified"
		exit
	fi
	rm -f "$appended" "$classified"
	# 結尾過濾: 對 txt 內的每行檢查 pkg 是否還在系統內, 不在的刪掉
	# 用一個 awk 一次處理 (取代原本 per-row fork awk)
	if [[ -f $txt ]]; then
		local pkg_set="$TMPDIR/.getlist_pkgset"
		echo "$Apk_info2" > "$pkg_set"
		# 註解行用「全系統已裝包名」判斷 (Apk_info2 僅第三方+白名單預裝, 會誤刪系統 app)
		# 直接複用開頭 appinfo 已存的全包名集合, 不再跑 pm list packages (省一次全系統查詢)
		local all_pkg_set="$TMPDIR/.getlist_allpkg"
		local _allpkg_n
		_allpkg_n="$(wc -l < "$all_pkg_set" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null} || echo 0)"
		local filtered="$TMPDIR/.getlist_filtered"
		# 三檔: (1)第三方清單 existing[] (2)全系統清單 allpkg[] (3)txt 逐行判斷
		awk -v allpkg_n="$_allpkg_n" '
			# 第一檔: 第三方清單
			FNR==NR { existing[$1]=1; next }
			# 第二檔: 全系統清單
			FILENAME == ALLF { allpkg[$1]=1; next }
			# 第三檔: txt
			/^[[:space:]]*$/ { print; next }
			/^[[:space:]]*[#＃!]/ {
				cpkg = $2
				if (cpkg ~ /^[a-zA-Z][a-zA-Z0-9_]*(\.[a-zA-Z0-9_]+)+$/) {
					# 合法包名的註解行: 全系統清單為空時一律保留(防 pm 失敗誤刪), 否則查全系統存在性
					if (allpkg_n == 0 || cpkg in allpkg) print
					else print "##__MISSING__\t" $0
				} else {
					print   # 說明行 / 無合法包名 → 保留
				}
				next
			}
			{
				pkg = $2
				if (pkg == "" || pkg in existing) print
				else print "##__MISSING__\t" $0
			}' ALLF="$all_pkg_set" "$pkg_set" "$all_pkg_set" "$txt" > "$filtered"
		# 印出被刪除的行 (給用戶看)
		grep '^##__MISSING__' "$filtered" | sed 's/^##__MISSING__\t//' | while read -r missing_line; do
			echoRgb "$missing_line不存在系統，從列表中刪除" "0"
		done
		# 寫回 txt (排序, 去空行)
		grep -v '^##__MISSING__' "$filtered" \
			| sed -e '/^$/d' | sort > "$txt"
			_applist_home_last_file "$txt" "getlist_output"
		rm -f "$pkg_set" "$all_pkg_set" "$filtered"
	fi
	# ====== appList.txt 結構驗證 (類似 JSON 自動檢查) ======
	# 檢查: 非註解行欄位數=2、包名格式合法、包名無重複
	if [[ -f $txt ]]; then
		echoRgb "—————— 應用列表結構驗證 ——————" "3"
		local _lc_err="$TMPDIR/.applist_err"
		: > "$_lc_err"
		awk '
			/^[[:space:]]*$/      { next }
			/^[[:space:]]*[#＃!]/ { next }
			{
				total++
				if (NF != 2) { print "欄位數異常(" NF "欄): " $0; next }
				pkg = $2
				if (pkg !~ /^[a-zA-Z][a-zA-Z0-9_]*(\.[a-zA-Z0-9_]+)+$/) print "包名格式可疑: " $1 " " pkg
				if (pkg in seen) print "包名重複: " pkg " (與 " seen[pkg] " 重複)"
				else seen[pkg] = $1
			}
			END { print "##TOTAL##\t" total > "/dev/stderr" }
		' "$txt" 2> "$TMPDIR/.applist_cnt" >> "$_lc_err"
		local _lc_total
		_lc_total="$(awk -F'\t' '/^##TOTAL##/{print $2}' "$TMPDIR/.applist_cnt" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null})"
		rm -f "$TMPDIR/.applist_cnt"
		if [[ -s $_lc_err ]]; then
			echoRgb "列表驗證發現異常:" "0"
			while read -r _el; do echoRgb "❌ $_el" "0"; done < "$_lc_err"
			echoRgb "請檢查 appList.txt 後再進行備份" "0"
		else
			echoRgb "✅ 列表結構正常 (${_lc_total:-0} 個有效應用)" "1"
		fi
		rm -f "$_lc_err"
	fi
	endtime 1
	cat "$txt">"$MODDIR/appList.txt" && rm "$txt"
	chown "$(stat -c '%u:%g' '/data/media/0/Download')" "$MODDIR/appList.txt"
	echoRgb "輸出包名結束 請查看$MODDIR/appList.txt"
}
# 備份自定義資料夾 (來自 Custom_path 設定)
# 例: Pictures / Download / DCIM / /data/adb 等
# 結尾設 REMOTE_UPLOAD_MEDIA=1 + REMOTE_TRIGGER=1
backup_media() {
	self_test
	backup_path
	show_conf media
	# 清除可能殘留的遠端json快取: backup_media 本身不會建立這個快取(只有批量備份的
	# prepare_remote_json_map 會), 但若先前跑過批量備份或中斷的測試留下舊快取,
	# _get_remote_appdetails 會一直讀到僵死的舊內容, 導致增量比對永遠用錯誤的舊資料
	rm -rf "$TMPDIR/.remote_json" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	# 流式上傳路徑快取: 在 Compression_method 還未被 Backup_data() 暫時污染前固定一次
	_BACKUP_DIRNAME_CACHED="$(get_backup_dirname)"
	# 快照備份前遠端大小 (backup() 主函數才有做這個快照, backup_media 是獨立函數需自己補上,
	# 否則沿用上次殘留的全域變數值, 導致結尾差異統計算出離譜的數字)
	if [[ -n $remote_type ]]; then
		_backup_remote_size_prescan_progress_begin "$_BACKUP_DIRNAME_CACHED"
		_RTOTAL_BEFORE="$(remote_dir_size "$_BACKUP_DIRNAME_CACHED" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null})"
		[[ -z $_RTOTAL_BEFORE ]] && _RTOTAL_BEFORE=0
		_backup_remote_size_prescan_progress_done "$_BACKUP_DIRNAME_CACHED" "$_RTOTAL_BEFORE"
		_speed_debug_log "REMOTE_TOTAL_BEFORE subdir=$_BACKUP_DIRNAME_CACHED bytes=$_RTOTAL_BEFORE mode=r448"
	fi
	echoRgb "假設反悔了要終止腳本請儘速離開此腳本點擊start.sh選擇終止腳本,否則腳本將繼續執行直到結束" "0"
	A=1
	B="$(printf "%s\n" "$Custom_path" | awk '!/[#＃]/ && NF{count++} END{print count}')"
	if [[ $B != "" ]]; then
		starttime1="$(date -u "+%s")"
		Backup_folder="$Backup/Media"
		app_details="$Backup_folder/app_details.json"
		mediatxt="$Backup/mediaList.txt"
		if [[ $remote_stream = 1 && -n $remote_type ]]; then
			_STREAM_DEST="Media"
			Backup_folder="$TMPDIR/.stream_stage/Media"
			app_details="$Backup_folder/app_details.json"
			mediatxt="$TMPDIR/.stream_stage/mediaList.txt"
			mkdir -p "$Backup_folder" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
		fi
		# 延遲建立: 只有實際備份了至少一個資料夾才建立 Media/txt 等 (避免空殼)
		_media_created=0
		_ensure_media_dirs() {
			[[ $_media_created = 1 ]] && return
			if [[ $remote_stream = 1 && -n $remote_type ]]; then
				[[ ! -d $Backup_folder ]] && mkdir -p "$Backup_folder"
			else
				[[ ! -d $Backup_folder ]] && mkdir -p "$Backup_folder"
				[[ ! -f $Backup/start.sh ]] && touch_shell "2" "$Backup/start.sh"
				[[ ! -d $Backup/tools ]] && cp -r "$tools_path" "$Backup"
				[[ ! -f $Backup/restore_settings.conf ]] && update_Restore_settings_conf>"$Backup/restore_settings.conf"
			fi
			if [[ ! -f $app_details ]]; then
				_media_appdetails_seed_remote_if_stream "$app_details" || printf '{\n}\n' > "$app_details"
			fi
			[[ ! -f $mediatxt ]] && echo "#不需要恢復的資料夾請在開頭使用#注釋 比如：#Download" > "$mediatxt"
			filesize="$(calc_dir_size "$Backup_folder")"
			_media_created=1
		}
		Set_screen_pause_seconds on
		notification "109" "Media備份開始"
		echo "$Custom_path" | sed -e '/^#/d; /^$/d; s/\/$//' > "$TMPDIR/.media_custom_paths"
		while read -r; do
			if [[ $remote_stream = 1 && -n $remote_type ]] && _remote_netwatch_mark_stream_fatal "media_only_loop_top" "netwatch"; then
				echoRgb "遠端 LAN 路由／位址已變更，停止本輪後續 Media 備份" "0"
				_speed_debug_log "REMOTE_NETWATCH_ABORT_MEDIA_ONLY_LOOP i=$A total=$B item=${REPLY##*/} $(_remote_stream_fatal_summary)"
				break
			fi
			if [[ $remote_stream = 1 && -n $remote_type ]] && _remote_stream_fatal_active; then
				echoRgb "遠端流式已中斷，停止本輪後續 Media 備份" "0"
				_speed_debug_log "REMOTE_STREAM_FATAL_ABORT_MEDIA_ONLY_LOOP i=$A total=$B item=${REPLY##*/} $(_remote_stream_fatal_summary)"
				break
			fi
			echoRgb "備份第$A/$B個資料夾 剩下$((B - A))個" "3"
			starttime2="$(date -u "+%s")"
			if [[ ${REPLY##*/} = adb ]]; then
				if [[ $ksu != ksu ]]; then
					echoRgb "Magisk adb"
					_ensure_media_dirs
					Backup_data "${REPLY##*/}" "$REPLY"
				else
					echoRgb "KernelSU adb不支持備份" "0"
				fi
			else
				_ensure_media_dirs
				Backup_data "${REPLY##*/}" "$REPLY"
			fi
			endtime 2 "${REPLY##*/}備份" "1"
			echoRgb "完成$(safe_percent "$A" "$B")% $(progress_bar $(safe_percent "$A" "$B"))$(_progress_local_storage_suffix)" "2" && echoRgb "____________________________________" && let A++
		done < "$TMPDIR/.media_custom_paths"
		rm -f "$TMPDIR/.media_custom_paths"
		# 收尾: 若 Media 內無任何備份檔 (全部跳過/不支持), 清掉空殼避免上傳空目錄
		# 流式模式: .tar 壓縮完即上傳, 本機 $Backup_folder 永遠不會留有 .tar 檔 (設計如此),
		# 故改用 _media_created 旗標 (有實際處理過至少一個資料夾才會被設成1) 判斷, 不能沿用本機檔案掃描
		if [[ $remote_stream = 1 && -n $remote_type ]]; then
			if _remote_stream_fatal_active; then
				echoRgb "Media 遠端流式已中斷，跳過 mediaList/app_details 上傳" "0"
				_speed_debug_log "REMOTE_STREAM_FATAL_MEDIA_ONLY_METADATA_SKIP $(_remote_stream_fatal_summary)"
				rm -rf "$Backup_folder" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
				[[ -f $mediatxt ]] && rm -f "$mediatxt" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
			elif [[ $_media_created != 1 ]]; then
				echoRgb "Media 無實際備份內容, 清除 mediaList.txt" "0"
				rm -rf "$Backup_folder" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
				[[ -f $mediatxt ]] && [[ ! -s $mediatxt || $(grep -vc "^#" "$mediatxt" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}) = 0 ]] && rm -f "$mediatxt"
			else
				REMOTE_UPLOAD_MEDIA=1
				# 只有 app_details 真的有實際內容(非初始空殼)才上傳, 避免「全部資料夾無變化跳過」
				# 時, 本地空殼覆蓋掉遠端原本正確的版本
				if _appdetails_is_nonempty "$app_details"; then
					_stream_upload "Media/app_details.json" < "$app_details"
					[[ -f $mediatxt ]] && _speed_debug_log "REMOTE_LOCAL_REBUILD_SIDECAR_SUMMARY rel=mediaList.txt reason=local-rebuild-stream-media"
					echoRgb "Media metadata 已上傳遠端，mediaList.txt 保留本地重建" "1"
				else
					echoRgb "Media 本輪全部資料夾無變化, 跳過json上傳(避免覆蓋遠端正確版本)" "2"
				fi
			fi
		elif [[ -d $Backup_folder ]] && ! _speedscan_backup_folder_has_tar_payload "$Backup_folder"; then
			echoRgb "Media 無實際備份內容, 清除空目錄與 mediaList.txt" "0"
			rm -rf "$Backup_folder"
			[[ -f $mediatxt ]] && [[ ! -s $mediatxt || $(grep -vc "^#" "$mediatxt" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}) = 0 ]] && rm -f "$mediatxt"
		else
			[[ $remote_stream != 1 ]] && Calculate_size "$Backup_folder"
			[[ -n $remote_type ]] && REMOTE_UPLOAD_MEDIA=1
		fi
		Set_screen_pause_seconds off
		endtime 1 "自定義備份"
		notification "109" "Media備份完成 $(endtime 1 "自定義備份")"
	else
		echoRgb "自定義路徑為空 無法備份" "0"
	fi
	REMOTE_TRIGGER=1
	_media_final_rc=0
	if [[ $remote_stream = 1 && -n $remote_type ]] && _remote_stream_fatal_active; then
		_media_final_rc=126
		_speed_debug_log "REMOTE_STREAM_FATAL_MEDIA_ONLY_EXIT rc=$_media_final_rc $(_remote_stream_fatal_summary)"
	fi
	# subshell 環境下 trap EXIT 在主 shell 不會觸發, 這裡直接呼叫
	remote_cleanup
	cleanup_tmpdir_contents || return 1
	return "$_media_final_rc"
}
# HttpUtil 分片下載/解析 Device_List；避免 Android 16 app_process 單一 Dex 行程連續 HTTPS 下載時 native abort。
# 每個品牌由 Dex HttpUtil get 短行程下載，shell 只負責合併既有格式；全部失敗才 fallback 舊 shell 流程。
_device_list_httputil_sharded_download() {
	local _out="$1" _dex_log _tmp_body _ok _fail _i Brand_URL URL model
	[[ -n $_out ]] || return 1
	URL="https://raw.githubusercontent.com/KHwang9883/MobileModels/refs/heads/master/brands"
	_dex_log="$(_speed_debug_log_path device_list_dex.log)"
	_ok=0
	_fail=0
	rm -f "$_out" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	for _i in $(echo "xiaomi\nxiaomi_en\nsamsung\nsamsung_global\nasus\nBlack_Shark\nBlack_Shark_en\ngoogle\nLenovo\nMEIZU\nMEIZU_en\nMotorola\nNokia\nnothing\nnubia\nOnePlus\nOnePlus_en\nSony\nrealme\nrealme_en\nvivo\nvivo_en\noppo\noppo_en"); do
		case $_i in
		xiaomi) Brand_URL="$URL/xiaomi.md" ;;
		xiaomi_en) Brand_URL="$URL/xiaomi_en.md" ;;
		samsung) Brand_URL="$URL/samsung_cn.md" ;;
		samsung_global) Brand_URL="$URL/samsung_global_en.md" ;;
		asus) Brand_URL="$URL/asus_cn.md" ;;
		Black_Shark) Brand_URL="$URL/blackshark.md" ;;
		Black_Shark_en) Brand_URL="$URL/blackshark_en.md" ;;
		google) Brand_URL="$URL/google.md" ;;
		Lenovo) Brand_URL="$URL/lenovo_cn.md" ;;
		MEIZU) Brand_URL="$URL/meizu.md" ;;
		MEIZU_en) Brand_URL="$URL/meizu_en.md" ;;
		Motorola) Brand_URL="$URL/motorola_cn.md" ;;
		Nokia) Brand_URL="$URL/nokia_cn.md" ;;
		nothing) Brand_URL="$URL/nothing.md" ;;
		nubia) Brand_URL="$URL/nubia.md" ;;
		OnePlus) Brand_URL="$URL/oneplus.md" ;;
		OnePlus_en) Brand_URL="$URL/oneplus_en.md" ;;
		Sony) Brand_URL="$URL/sony_cn.md" ;;
		realme) Brand_URL="$URL/realme_cn.md" ;;
		realme_en) Brand_URL="$URL/realme_global_en.md" ;;
		vivo) Brand_URL="$URL/vivo_cn.md" ;;
		vivo_en) Brand_URL="$URL/vivo_global_en.md" ;;
		oppo) Brand_URL="$URL/oppo_cn.md" ;;
		oppo_en) Brand_URL="$URL/oppo_global_en.md" ;;
		*) continue ;;
		esac
		_tmp_body="${TMPDIR:-/data/local/tmp}/.device_list_dex_body_${$}_${RANDOM:-0}"
		rm -f "$_tmp_body" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
		echoRgb "Dex 獲取品牌$_i"
		if _dex_exec_unfiltered com.xayah.dex.HttpUtil get "$Brand_URL" > "$_tmp_body" 2>>"$_dex_log"; then
			if [[ -s $_tmp_body ]]; then
				_ok=$((_ok+1))
				grep -oE '`[^`]+`:[^`]*' "$_tmp_body" 2>>"$_dex_log" | sed -E 's/: /:/g' | sed -E 's/`([^`]+)`:(.*)/"\1" "\2"/' | while read -r REPLY; do
					[[ -n $REPLY ]] || continue
					model="$(echo "$REPLY" | awk -F'"' '{print $2}')"
					[[ -n $model ]] || continue
					if [[ ! -e $_out ]] || [[ $(grep -Ew "$model" "$_out" 2>/dev/null | awk -F'"' '{print $2}' | head -n 1) != "$model" ]]; then
						echo "$REPLY" >> "$_out"
					fi
				done
			else
				_fail=$((_fail+1))
				echo "DEVICE_LIST_BRAND_FAIL name=$_i reason=empty_body url=$Brand_URL" >> "$_dex_log"
			fi
		else
			_fail=$((_fail+1))
			echo "DEVICE_LIST_BRAND_FAIL name=$_i reason=http_get_failed url=$Brand_URL" >> "$_dex_log"
		fi
		rm -f "$_tmp_body" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}
	done
	if [[ -s $_out ]]; then
		echo "DEVICE_LIST_OK mode=dex_httputil_sharded okBrands=$_ok failedBrands=$_fail size=$(stat -c%s "$_out" 2>/dev/null)" >> "$_dex_log"
		return 0
	fi
	echo "DEVICE_LIST_FAIL mode=dex_httputil_sharded okBrands=$_ok failedBrands=$_fail" >> "$_dex_log"
	return 1
}

# 從 tools/Device_List 對照表查詢設備識別資訊 (處理器型號、RAM 規格等)
Device_List() {
	URL="https://raw.githubusercontent.com/KHwang9883/MobileModels/refs/heads/master/brands"
	rm -rf "$tools_path/Device_List"
	echoRgb "使用 Dex HttpUtil 分片下載/解析機型列表" "3"
	if _device_list_httputil_sharded_download "$tools_path/Device_List"; then
		if [[ $(stat -c%s "$tools_path/Device_List" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}) -gt 1 ]]; then
			[[ $shell_language = zh-TW ]] && ts_inplace "$tools_path/Device_List"
			echoRgb "已下載機型列表在$tools_path/Device_List"
			return 0
		fi
	fi
	echoRgb "Dex HttpUtil 機型列表下載失敗，回退 shell 下載流程" "2"
	_device_list_shell_log="$(_speed_debug_log_path device_list_shell.log)"
	rm -rf "$tools_path/Device_List"
	for i in $(echo "xiaomi\nxiaomi_en\nsamsung\nsamsung_global\nasus\nBlack_Shark\nBlack_Shark_en\ngoogle\nLenovo\nMEIZU\nMEIZU_en\nMotorola\nNokia\nnothing\nnubia\nOnePlus\nOnePlus_en\nSony\nrealme\nrealme_en\nvivo\nvivo_en\noppo\noppo_en"); do
		echoRgb "獲取品牌$i"
		case $i in
		xiaomi) Brand_URL="$URL/xiaomi.md" ;;
		xiaomi_en) Brand_URL="$URL/xiaomi_en.md" ;;
		samsung) Brand_URL="$URL/samsung_cn.md" ;;
		samsung_global) Brand_URL="$URL/samsung_global_en.md" ;;
		asus) Brand_URL="$URL/asus_cn.md" ;;
		Black_Shark) Brand_URL="$URL/blackshark.md" ;;
		Black_Shark_en) Brand_URL="$URL/blackshark_en.md" ;;
		google) Brand_URL="$URL/google.md" ;;
		Lenovo) Brand_URL="$URL/lenovo_cn.md" ;;
		MEIZU) Brand_URL="$URL/meizu.md" ;;
		MEIZU_en) Brand_URL="$URL/meizu_en.md" ;;
		Motorola) Brand_URL="$URL/motorola_cn.md" ;;
		Nokia) Brand_URL="$URL/nokia_cn.md" ;;
		nothing) Brand_URL="$URL/nothing.md" ;;
		nubia) Brand_URL="$URL/nubia.md" ;;
		OnePlus) Brand_URL="$URL/oneplus.md" ;;
		OnePlus_en) Brand_URL="$URL/oneplus_en.md" ;;
		Sony) Brand_URL="$URL/sony_cn.md" ;;
		realme) Brand_URL="$URL/realme_cn.md" ;;
		realme_en) Brand_URL="$URL/realme_global_en.md" ;;
		vivo) Brand_URL="$URL/vivo_cn.md" ;;
		vivo_en) Brand_URL="$URL/vivo_global_en.md" ;;
		oppo) Brand_URL="$URL/oppo_cn.md" ;;
		oppo_en) Brand_URL="$URL/oppo_global_en.md" ;;
		esac
		if [[ ! -e $tools_path/Device_List ]]; then
			down "$Brand_URL" 2>>"$_device_list_shell_log" | grep -oE '`[^`]+`:[^`]*' | sed -E 's/: /:/g' | sed -E 's/`([^`]+)`:(.*)/"\1" "\2"/'>"$tools_path/Device_List"
		else
			down "$Brand_URL" 2>>"$_device_list_shell_log" | grep -oE '`[^`]+`:[^`]*' | sed -E 's/: /:/g' | sed -E 's/`([^`]+)`:(.*)/"\1" "\2"/' | while read -r; do
				unset model
				model="$(echo "$REPLY" | awk -F'"' '{print $2}')"
				if [[ $(grep -Ew "$model" "$tools_path/Device_List" | awk -F'"' '{print $2}') != $model ]]; then
					echo "$REPLY">>"$tools_path/Device_List"
				else
					echo "$(grep -Ew "$model" "$tools_path/Device_List" | awk -F'"' '{print $2}') = $model"
				fi
			done
		fi
	done
	if [[ -e $tools_path/Device_List ]]; then
		if [[ $(stat -c%s "$tools_path/Device_List" 2>>${SPEED_DEBUG_ERR_LOG:-/dev/null}) -gt 1 ]]; then
			[[ $shell_language = zh-TW ]] && ts_inplace "$tools_path/Device_List"
			echoRgb "已下載機型列表在$tools_path/Device_List"
		else
			echoRgb "下載機型失敗"
		fi
	else
		echoRgb "下載機型失敗"
	fi
}

# 主選單「備份WiFi」入口
# 建立備份目錄結構 + 複製 tools/ + 生成 start.sh + 備份 wifi.json
wifi() {
	backup_path
	show_conf wifi
	[[ ! -d $Backup/tools ]] && cp -r "$tools_path" "$Backup"
	[[ ! -f $Backup/start.sh ]] && touch_shell "2" "$Backup/start.sh"
	[[ ! -f $Backup/restore_settings.conf ]] && update_Restore_settings_conf>"$Backup/restore_settings.conf"
	backup_wifi "$Backup/wifi"
	[[ -n $remote_type ]] && REMOTE_UPLOAD_WIFI=1
}
# ======================================================
# 主選單入口
# ======================================================
# 446 r2: 入口分流優先使用 wrapper 明確傳入的 SPEEDBACKUP_ENTRY_MODE。
# 不只靠 $0 檔名：./recover.sh、realpath recover.sh、sh recover.sh、部分 manager 包裝
# 都可能讓 $0 形式不同，造成 recover/backup/upload 入口誤判。
case ${SPEEDBACKUP_ENTRY_MODE:-} in
	1)
		start=backup ;;
	3)
		start=Restore ;;
	5)
		# upload.sh 位於 Backup_zstd_X/<app>/upload.sh；MODDIR 已被入口腳本設成 Backup_zstd_X。
		# 優先從 SPEEDBACKUP_ENTRY_SCRIPT 取實際 wrapper 路徑，fallback 才用 $0。
		_upload_entry=${SPEEDBACKUP_ENTRY_SCRIPT:-$0}
		_upload_app="${_upload_entry%/*}"
		_upload_app="${_upload_app##*/}"
		start="single_upload \"$_upload_app\"" ;;
	*)
		# 舊 wrapper / 手動直接執行仍保留檔名 fallback。
		if [[ $0 = *backup.sh ]]; then
			start=backup
		elif [[ $0 = *upload.sh ]]; then
			_upload_app="${0%/*}"
			_upload_app="${_upload_app##*/}"
			start="single_upload \"$_upload_app\""
		else
			[[ $0 = *recover.sh ]] && start=Restore
		fi ;;
esac
if [[ $start != "" ]]; then
	# 單獨入口由入口主線等待工作完成後統一 final 打包。
	# 避免 background_execution=1 或 tee/pipeline 場景下，EXIT trap 早於實際工作完成而刪除 run_xxx。
	_entry_bg="$(grep -o 'background_execution=.*' "$conf_path" | awk -F '=' '{print $2}')"
	case $_entry_bg in
	1)
		( eval "$start" ) &
		_entry_pid=$!
		wait "$_entry_pid"
		_entry_rc=$?
		;;
	*)
		eval "$start"
		_entry_rc=$?
		;;
	esac
	# 函數若已主動 final 打包，這裡會自動跳過；未打包的單獨 upload / media / wifi 等入口則在這裡補齊。
	_speed_debug_normal_finish_pack "${_entry_rc:-0}"
	exit "${_entry_rc:-0}"
else
	# r52: 預熱已在 daemon 函式定義完成後提前觸發；這裡保留冪等呼叫，避免早期預熱被停用/失敗後回到主選單時沒有補觸發。
	_root_daemon_prewarm_bg
	# 主選單循環: 跑完一個動作回到選單繼續
	# 備份類動作 (backup/backup_update_apk/backup_media/wifi) 跑完直接退出整個腳本
	# 其他動作 (Getlist/remote_test/list/download) 跑完回選單
	while true; do
	# 使用逐行資料取代 shell array，避免 mksh/busybox parser 差異。
	steps_data=
	commands_data=
	if [[ -f $MODDIR/backup_settings.conf ]]; then
		steps_data="$(cat <<'SPEEDBACKUP_STEPS_BACKUP'
生成應用列表
備份應用
備份已更新應用
備份自定義資料夾
備份WiFi
測試遠端連線
單獨上傳當前備份
列出遠端備份(產生 appList_network.txt)
刪除遠端已卸載應用
從遠端下載備份
從遠端流式恢復(不佔本機)
從遠端流式恢復自定義資料夾(不佔本機)
目前備份統計
重生現有備份JSON(保留Size/版本/時間/SSAID)
殺死運行中腳本
SPEEDBACKUP_STEPS_BACKUP
)"
		commands_data="$(cat <<'SPEEDBACKUP_COMMANDS_BACKUP'
Getlist
backup; exit
backup_update_apk; exit
backup_media; _rc=$?; _speed_debug_normal_finish_pack $_rc; exit $_rc
wifi; _rc=$?; _speed_debug_normal_finish_pack $_rc; exit $_rc
remote_test_menu
upload_current_backup
remote_list_backups
delete_remote_uninstalled_apps
remote_download_backup
remote_stream_restore; _rc=$?; _speed_debug_normal_finish_pack $_rc; exit $_rc
remote_stream_restore_media; _rc=$?; _speed_debug_normal_finish_pack $_rc; exit $_rc
Stats_Dispatch
Json_refresh_menu
echoRgb '等待腳本停止中，請稍後.....' && echoRgb '腳本終止'; exit
SPEEDBACKUP_COMMANDS_BACKUP
)"
	elif [[ -f $MODDIR/restore_settings.conf ]]; then
		steps_data="$(cat <<'SPEEDBACKUP_STEPS_RESTORE'
重新生成應用列表
恢復備份
僅恢復包含ssaid應用(含數據)
僅恢復包含SSAID應用的App狀態(不含數據)
恢復自定義資料夾
恢復wifi
壓縮檔完整性檢查
JSON結構檢查
重生現有備份JSON(保留Size/版本/時間/SSAID)
轉換文件夾名稱
殺死運行中腳本
SPEEDBACKUP_STEPS_RESTORE
)"
		commands_data="$(cat <<'SPEEDBACKUP_COMMANDS_RESTORE'
dumpname
Restore; exit
ssaid_mode=true && Restore; exit
ssaid_mode_1=true && Restore4; _rc=$?; _speed_debug_normal_finish_pack $_rc; exit $_rc
Restore3; _rc=$?; _speed_debug_normal_finish_pack $_rc; exit $_rc
recover_wifi "$MODDIR/wifi"; _rc=$?; _speed_debug_normal_finish_pack $_rc; exit $_rc
check_file
Check_json
Json_refresh_menu
convert
echoRgb '等待腳本停止中，請稍後.....' && echoRgb '腳本終止'; exit
SPEEDBACKUP_COMMANDS_RESTORE
)"
	fi
	step_count="$(printf '%s\n' "$steps_data" | awk 'NF {n++} END {print n+0}')"
	echoRgb "請選擇要執行的操作："
	i=1
	while [[ $i -le $step_count ]]; do
		_step_label="$(printf '%s\n' "$steps_data" | sed -n "${i}p")"
		printf " -%d) %s\n" "$i" "$_step_label"
		i="$((i + 1))"
	done
	echo " -0) 離開腳本"
	echo -n " -請輸入選項編號: "
	# read 失敗 (stdin 關閉/EOF, 例如後台執行無 tty) 立刻退出,避免無限循環
	if ! read choice; then
		echoRgb "無互動 stdin, 退出" "0"
		exit 0
	fi
	case $choice in
	0)
		echoRgb "已退出腳本" "0"
		_speedbackup_lock_cleanup
		exit 0 ;;
	''|*[!0-9]*)
		echoRgb "輸入錯誤，請重新輸入有效的數字。" "0" ;;
	*)
		if [[ $choice -ge 1 && $choice -le $step_count ]]; then
			_selected_step="$(printf '%s\n' "$steps_data" | sed -n "${choice}p")"
			_selected_command="$(printf '%s\n' "$commands_data" | sed -n "${choice}p")"
			echo " -執行：$_selected_step"
			_root_daemon_prewarm_before_feature
			background="$(grep -o 'background_execution=.*' "$conf_path" | awk -F '=' '{print $2}')"
			if [[ "$background" = "1" ]]; then
				case $_selected_command in
				remote_test_menu*)
					# 功能 6 內部還有 SMB 掃描子選單，需要繼續讀取使用者輸入；
					# 背景 subshell 會讓子選單 read 讀到 EOF，因此這類互動診斷固定前台執行。
					eval "$_selected_command"
					;;
				*)
					# 後台執行: 用 subshell 防 exit 殺主 shell
					(eval "$_selected_command") &
					bg_pid=$!
					wait "$bg_pid"
					case $_selected_command in
					*exit*) exit 0 ;;
					esac
					;;
				esac
			else
				eval "$_selected_command"
			fi
		else
			echoRgb "超出功能選項範圍（1-$step_count）" "0"
		fi
		;;
	esac
	done
fi

# r156 smoke marker: cgroup native scan log normalizes batch-session daemonPersistent=false to daemonSessionPersistent=true.
